-- DEBUG:
-- sebelum load bisa set:
-- getgenv().__NODEHUB_MAIN_DEBUG = true
local DEBUG = (G.__NODEHUB_MAIN_DEBUG == true) or (_G.__NODEHUB_MAIN_DEBUG == true)
local DEBUG_LINES = {}

local function _safeText(v)
    local s = tostring(v)
    s = s:gsub("https?://[%w%p]+", "[URL_HIDDEN]")
    s = s:gsub("%%%[%[%[[^%]]+%]%]%]%%", "[SHORTCODE_HIDDEN]")
    return s
end

local function debuglog(...)
    if not DEBUG then return end

    local parts = {}
    for i = 1, select("#", ...) do
        parts[#parts + 1] = _safeText(select(i, ...))
    end

    local line = "[" .. BOOT_NAME .. "][DEBUG] " .. table.concat(parts, " ")
    DEBUG_LINES[#DEBUG_LINES + 1] = line
    if #DEBUG_LINES > 160 then
        table.remove(DEBUG_LINES, 1)
    end

    G.__NODEHUB_MAIN_DEBUG_LINES = DEBUG_LINES
    _G.__NODEHUB_MAIN_DEBUG_LINES = DEBUG_LINES
    warn(line)
end

local function log(...)
    print("[" .. BOOT_NAME .. "]", ...)
end

local function warnlog(...)
    warn("[" .. BOOT_NAME .. "]", ...)
end

