local function failBoot(msg)
    debuglog("FAIL_BOOT", msg)
    G.__NODEHUB_MAIN_RUNNING = false
    G.__NODEHUB_MAIN_READY = false
    _G.__NODEHUB_MAIN_READY = false
    error("[" .. BOOT_NAME .. "] " .. tostring(msg), 0)
end

