        listAllMutations   = function() return {} end,
        buildMutationDropdownItems = function() return {} end,
        parseMutationSelection = function() return {} end,
        buildPetItems      = function() return {} end,
        buildPetBoostItems = function() return {} end,
    }

 STATE = rawget(_G, "STATE") or STATE or {}
