TAB_AGE_EQUIP_MIN    = G.TAB_AGE_EQUIP_MIN    or TAB_AGE_EQUIP_MIN
TAB_AGE_UNEQUIP_MIN  = G.TAB_AGE_UNEQUIP_MIN  or TAB_AGE_UNEQUIP_MIN
TAB_W_EQUIP_MIN      = G.TAB_W_EQUIP_MIN      or TAB_W_EQUIP_MIN
TAB_W_UNEQUIP_MAX    = G.TAB_W_UNEQUIP_MAX    or TAB_W_UNEQUIP_MAX
TAB_TARGET_EQUIP_MAX = G.TAB_TARGET_EQUIP_MAX or TAB_TARGET_EQUIP_MAX

    ----------------------------------------------------------------
    -- helper autosave: pakai ui:SaveState() dari main.lua
    ----------------------------------------------------------------
local SAVE_TOKEN = 0

local function autoSave()
    SAVE_TOKEN += 1
    local myToken = SAVE_TOKEN

    task.delay(0.25, function()
        if myToken ~= SAVE_TOKEN then
            return
        end

        if ui and type(ui.SaveState) == "function" then
            local ok, err = pcall(function()
                ui:SaveState()
            end)
            if not ok then
                warn("[AutoKG] Gagal ui:SaveState():", err)
            end
        else
            warn("[AutoKG] ui.SaveState() tidak tersedia")
        end
    end)
end

