    -- GLOBALS yang dipakai state.lua
    ----------------------------------------------------------------
G.selected = G.selected or {
    boost = {},
    xp = {},
    noos = {},
    seratusage = {},
    gbxp = {},
}

selected = G.selected

    TAB_AGE_EQUIP_MIN   = TAB_AGE_EQUIP_MIN   or {}
