    G.TAB_AGE_UNEQUIP_MIN  = TAB_AGE_UNEQUIP_MIN
    G.TAB_W_EQUIP_MIN      = TAB_W_EQUIP_MIN
    G.TAB_W_UNEQUIP_MAX    = TAB_W_UNEQUIP_MAX
    G.TAB_TARGET_EQUIP_MAX = TAB_TARGET_EQUIP_MAX
    _G.TAB_AGE_EQUIP_MIN    = TAB_AGE_EQUIP_MIN
    _G.TAB_AGE_UNEQUIP_MIN  = TAB_AGE_UNEQUIP_MIN
    _G.TAB_W_EQUIP_MIN      = TAB_W_EQUIP_MIN
    _G.TAB_W_UNEQUIP_MAX    = TAB_W_UNEQUIP_MAX
    _G.TAB_TARGET_EQUIP_MAX = TAB_TARGET_EQUIP_MAX

    local function setTargetEquipMax(tabKey, v)
        v = math.max(0, math.floor(tonumber(v) or 0))
        local t = G.TAB_TARGET_EQUIP_MAX or TAB_TARGET_EQUIP_MAX or {}
        t[tabKey] = v
        TAB_TARGET_EQUIP_MAX = t
        G.TAB_TARGET_EQUIP_MAX = t
        _G.TAB_TARGET_EQUIP_MAX = t
        return v
    end
    
