local UIREF -- forward decl (diisi setelah ensureTabDefaults)

local function normBoostListMode(mode)
    mode = tostring(mode or "normal"):lower()
    if mode == "machine" or mode == "shark" then
        return mode
    end
    return "normal"
end

local function getBoostListMode()
    return normBoostListMode(STATE.boostListMode or "normal")
end

local function normAgeListMode(mode)
    if tostring(mode or ""):lower() == "baku" then
        return "baku"
    end
    return "normal"
end

local function getAgeListMode()
    return normAgeListMode(STATE and STATE.ageListMode)
end

local refreshPetListsForModeSwitch
local SHARED_PET_TABS = { "xp", "noos", "seratusage", "gbxp" }

local function copyPetSet(src)
    local out = {}
    if type(src) ~= "table" then
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[k] = true
        end
    end
    return out
end

local function replacePetSet(dst, src)
    dst = dst or {}
    for k in pairs(dst) do
        dst[k] = nil
    end
    if type(src) == "table" then
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                dst[k] = true
            end
        end
    end
    return dst
end

local function tabSetEmpty(setTbl)
    if type(setTbl) ~= "table" then
        return true
    end
    for _, v in pairs(setTbl) do
        if v == true or v == 1 or v == "true" then
            return false
        end
    end
    return true
end

local function emptySelPack()
    return {
        boost = {},
    }
end

local function ensureSelectedByListMode()
    STATE.selectedByListMode = STATE.selectedByListMode or {}
    for _, m in ipairs({ "normal", "machine", "shark" }) do
        local pack = STATE.selectedByListMode[m]
        if type(pack) ~= "table" then
            STATE.selectedByListMode[m] = emptySelPack()
        else
            pack.boost = pack.boost or {}
        end
    end
    G.selectedByListMode = STATE.selectedByListMode
    _G.selectedByListMode = STATE.selectedByListMode
end

local function restoreSharedTabsFromPacks()
    ensureSelectedByListMode()
    selected = selected or G.selected or {}
    for _, k in ipairs(SHARED_PET_TABS) do
        selected[k] = selected[k] or {}
        if tabSetEmpty(selected[k]) then
            local src = nil
            for _, m in ipairs({ "normal", "machine", "shark" }) do
                local pack = STATE.selectedByListMode[m]
                if type(pack) == "table" and type(pack[k]) == "table" and next(pack[k]) ~= nil then
                    src = pack[k]
                    if m == "normal" then
                        break
                    end
                end
            end
            if src then
                replacePetSet(selected[k], src)
            end
        end
    end
    local manual = rawget(G, "GBXP_MANUAL_SELECTED") or GBXP_MANUAL_SELECTED
    if tabSetEmpty(manual) then
        for _, m in ipairs({ "normal", "machine", "shark" }) do
            local pack = STATE.selectedByListMode[m]
            if type(pack) == "table" and type(pack.gbxp_manual) == "table" and next(pack.gbxp_manual) ~= nil then
                GBXP_MANUAL_SELECTED = copyPetSet(pack.gbxp_manual)
                G.GBXP_MANUAL_SELECTED = GBXP_MANUAL_SELECTED
                _G.GBXP_MANUAL_SELECTED = GBXP_MANUAL_SELECTED
                break
            end
        end
    end
    G.selected = selected
    _G.selected = selected
end

local function snapshotSelectedToMode(mode)
    mode = normBoostListMode(mode or getBoostListMode())
    ensureSelectedByListMode()
    selected = selected or G.selected or {}
    local pack = STATE.selectedByListMode[mode]
    pack.boost = copyPetSet(selected.boost)
end

local function ensureAgeTeamSelected()
    STATE.ageTeamSelected = type(STATE.ageTeamSelected) == "table" and STATE.ageTeamSelected or {}
    STATE.ageTeamSelected.normal = type(STATE.ageTeamSelected.normal) == "table" and STATE.ageTeamSelected.normal or {}
    STATE.ageTeamSelected.baku = type(STATE.ageTeamSelected.baku) == "table" and STATE.ageTeamSelected.baku or {}
end

local function snapshotAgeTeamToMode(mode)
    mode = normAgeListMode(mode or getAgeListMode())
    ensureAgeTeamSelected()
    selected = selected or G.selected or {}
    STATE.ageTeamSelected[mode] = copyPetSet(selected.seratusage)
end

local function applyAgeTeamFromMode(mode)
    mode = normAgeListMode(mode or getAgeListMode())
    ensureAgeTeamSelected()
    selected = selected or G.selected or {}
    selected.seratusage = selected.seratusage or {}
    replacePetSet(selected.seratusage, STATE.ageTeamSelected[mode])
    G.selected = selected
    _G.selected = selected
end

local function applySelectedFromMode(mode)
    mode = normBoostListMode(mode or getBoostListMode())
    ensureSelectedByListMode()
    local pack = STATE.selectedByListMode[mode] or emptySelPack()
    selected = selected or G.selected or {}
    selected.boost = selected.boost or {}
    replacePetSet(selected.boost, pack.boost)
    restoreSharedTabsFromPacks()
    applyAgeTeamFromMode(getAgeListMode())
    G.selected = selected
    _G.selected = selected
end

local function seedSelectedByListModeIfNeeded()
    ensureSelectedByListMode()
    restoreSharedTabsFromPacks()
    applyAgeTeamFromMode(getAgeListMode())
    local cur = getBoostListMode()
    local pack = STATE.selectedByListMode[cur]
    local has = type(pack.boost) == "table" and next(pack.boost) ~= nil
    if not has then
        snapshotSelectedToMode(cur)
    end
end

