local MACHINE_CLAIM_TEAM_MAX = 8
NMLVL_MACHINE_CLAIM_TEAM_BEFORE = NMLVL_MACHINE_CLAIM_TEAM_BEFORE or {}

local function normMachineClaimUUID(u)
    if not u then return nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    if core == "" then return nil end
    return "{" .. core .. "}"
end

local function normalizeMachineClaimTeamSet(src)
    local out = {}
    if type(src) ~= "table" then return out end
    for k, v in pairs(src) do
        local raw
        if type(k) == "number" then
            if v == true or v == 1 or v == "true" then
                raw = k
            else
                raw = v
            end
        elseif v == true or v == 1 or v == "true" then
            raw = k
        end
        local b = normMachineClaimUUID(raw)
        if b then
            out[b] = true
        end
    end
    return out
end

local function capMachineClaimTeamSet(setTbl)
    setTbl = normalizeMachineClaimTeamSet(setTbl)
    local keys = {}
    for k, on in pairs(setTbl) do
        if on then keys[#keys + 1] = tostring(k) end
    end
    table.sort(keys)
    if #keys <= MACHINE_CLAIM_TEAM_MAX then
        return setTbl
    end
    local out = {}
    for i = 1, MACHINE_CLAIM_TEAM_MAX do
        out[keys[i]] = true
    end
    return out
end

local function publishMachineClaimTeam(setTbl)
    setTbl = capMachineClaimTeamSet(setTbl)
    NMLVL_MACHINE_CLAIM_TEAM_BEFORE = setTbl
    _G.NMLVL_MACHINE_CLAIM_TEAM_BEFORE = setTbl
    G.NMLVL_MACHINE_CLAIM_TEAM_BEFORE = setTbl
    STATE.machineClaimTeamBefore = setTbl
    return setTbl
end

