)

NMLVL_SHARK_RECEIVER_TEAM = NMLVL_SHARK_RECEIVER_TEAM or {}

local function looksLikeUUIDKey(k)
    local core = tostring(k or ""):match("{?([0-9a-fA-F%-]+)}?") or ""
    return (#core >= 30) and (core:find("%-") ~= nil) and (core:match("^[0-9a-fA-F%-]+$") ~= nil)
end

local function normalizeSharkReceiverTypeSet(src)
    local out = {}
    if type(src) ~= "table" then return out end
    for k, v in pairs(src) do
        local name
        if type(k) == "number" then
            name = tostring(v)
        elseif v == true or v == 1 or v == "true" then
            name = tostring(k)
        end
        if name and name ~= "" and not looksLikeUUIDKey(name) then
            out[name] = true
        end
    end
    return out
end

local function publishSharkReceiverTeam(setTbl)
    setTbl = normalizeSharkReceiverTypeSet(setTbl)
