local function copyMutSet(src)
    local out = {}
    if type(src) ~= "table" then return out end
    for k, on in pairs(src) do
        if on == true and k ~= nil then
            out[tostring(k)] = true
        end
    end
    return out
end

local function seedBoostMutBucketIfEmpty(mode)
    ensureBoostMutSelected()
    local bucket = getBoostMutBucket(mode)
    local dest = STATE.boostMutSelected[bucket]
    if type(dest) == "table" and next(dest) ~= nil then
        return dest
    end

    local src = nil
    if bucket ~= "normal" then
        src = STATE.boostMutSelected.normal
    end
    if (type(src) ~= "table" or next(src) == nil) then
        src = rawget(G, "GBXP_MUT_SELECTED") or _G.GBXP_MUT_SELECTED
    end
    dest = copyMutSet(src)
    STATE.boostMutSelected[bucket] = dest
    _G.BOOST_MUT_SELECTED = STATE.boostMutSelected
    G.BOOST_MUT_SELECTED = STATE.boostMutSelected
    return dest
end

