local function refreshMachineStatusLabel()
    local bc = UIREF.boostControls
    if not bc or not bc.machineStatusLabel or not bc.machineStatusLabel.Parent then return end

    local show = (getBoostListMode() == "machine")
    if bc.machineStatusRow and bc.machineStatusRow.Parent then
        bc.machineStatusRow.Visible = show
    end
    if not show then return end

    local text = "Machine: —"
    local api = rawget(_G, "MutationMachineApi")
    if api and type(api.BuildStatusText) == "function" then
        local ok, v = pcall(function() return api.BuildStatusText() end)
        if ok and type(v) == "string" and v ~= "" then
            text = v
        end
    end
    bc.machineStatusLabel.Text = text
end

function refreshShardStatusLabel()
    local bc = UIREF.boostControls
    if not bc or not bc.shardStatusLabel or not bc.shardStatusLabel.Parent then
        return
    end

    local Gg = (getgenv and getgenv()) or _G
    local text = "Shard: —"
    local tog = (STATE.autokgMutationEnabled == true)
        or (AUTOKG_MUTATION_ENABLED == true)
        or (Gg.AUTOKG_MUTATION_ENABLED == true)
    local loop = rawget(_G, "AutoKGLoop") or Gg.AutoKGLoop
    local loopOn = false
    if loop and type(loop.IsRunning) == "function" then
        local ok, v = pcall(function() return loop.IsRunning() end)
        loopOn = ok and v == true
    end
    local stage = tostring(rawget(_G, "CURRENT_STAGE") or rawget(Gg, "CURRENT_STAGE") or "")
    local mode = tostring(getBoostListMode() or "normal")

    if not tog then
        text = "Shard: OFF (toggle disabled)"
    elseif not loopOn then
        text = "Shard: OFF (AutoKG not running)"
    elseif stage ~= "A" then
        local now = stage
        if now == "" or now == "nil" then now = "none" end
        text = "Shard: wait Stage A (now " .. now .. ", mode " .. mode .. ")"
    else
        local w = rawget(_G, "WorldShardCleaner") or Gg.WorldShardCleaner
        if w and type(w.GetStatusText) == "function" then
            local ok, v = pcall(function() return w:GetStatusText() end)
            if ok and type(v) == "string" and v ~= "" then
                text = v
            end
        elseif type(_G.__SHARD_STATUS_TEXT) == "string" and _G.__SHARD_STATUS_TEXT ~= "" then
            text = _G.__SHARD_STATUS_TEXT
        else
            text = "Shard: Stage A — waiting scan (" .. mode .. ")"
        end
    end

    bc.shardStatusLabel.Text = text
end

local function refreshSharkStatusLabel()
