local function refreshBoostModeUi(mode)
    mode = normBoostListMode(mode or getBoostListMode())
    local isMachine = (mode == "machine")
    local isShark = (mode == "shark")
    local showAgeKg = (not isMachine) and (not isShark)

    local bc = UIREF.boostControls
    if bc.equipAgeRow and bc.equipAgeRow.Parent then
        bc.equipAgeRow.Visible = showAgeKg
    end
    if bc.unequipAgeRow and bc.unequipAgeRow.Parent then
        bc.unequipAgeRow.Visible = showAgeKg
    end
    if bc.kgEquipRow and bc.kgEquipRow.Parent then
        bc.kgEquipRow.Visible = showAgeKg
    end
    if bc.kgUnequipRow and bc.kgUnequipRow.Parent then
        bc.kgUnequipRow.Visible = showAgeKg
    end
    if bc.targetMaxRow and bc.targetMaxRow.Parent then
        bc.targetMaxRow.Visible = showAgeKg
    end
    if bc.machineAgeRow and bc.machineAgeRow.Parent then
        bc.machineAgeRow.Visible = isMachine
    end
    if bc.machineStatusRow and bc.machineStatusRow.Parent then
        bc.machineStatusRow.Visible = isMachine
    end
    if bc.machineClaimTeamRow and bc.machineClaimTeamRow.Parent then
        bc.machineClaimTeamRow.Visible = isMachine
    end
    if bc.sharkDonorRow and bc.sharkDonorRow.Parent then
        bc.sharkDonorRow.Visible = isShark
    end
    if bc.sharkUnequipDelayRow and bc.sharkUnequipDelayRow.Parent then
        bc.sharkUnequipDelayRow.Visible = isShark
    end
    if bc.sharkStatusRow and bc.sharkStatusRow.Parent then
        bc.sharkStatusRow.Visible = isShark
    end
    if bc.sharkDonorCountRow and bc.sharkDonorCountRow.Parent then
        bc.sharkDonorCountRow.Visible = isShark
    end
    if bc.sharkWarnRow and bc.sharkWarnRow.Parent then
        bc.sharkWarnRow.Visible = isShark
    end
    if bc.sharkHelpRow and bc.sharkHelpRow.Parent then
        bc.sharkHelpRow.Visible = isShark
    end
    -- Auto Shard Cleaner: semua List Mode (Normal / Machine / Shark), jalan hanya Stage A
    if bc.shardCleanerRow and bc.shardCleanerRow.Parent then
        bc.shardCleanerRow.Visible = true
    end
    if bc.shardStatusRow and bc.shardStatusRow.Parent then
        bc.shardStatusRow.Visible = true
    end
    pcall(refreshShardStatusLabel)
    if bc.venomRow and bc.venomRow.Parent then
        bc.venomRow.Visible = (mode == "normal")
    end
    if bc.mutLabelInst and bc.mutLabelInst.Parent then
        bc.mutLabelInst.Text = getBoostMutationDropdownLabel(mode)
    end

    local ref = UIREF.tabs and UIREF.tabs.boost
    if ref and ref.listTitleLabel and ref.listTitleLabel.Parent then
        ref.listTitleLabel.Text = getBoostPetListLabel(mode)
    end

    if isMachine then
        refreshMachineStatusLabel()
    end
    if isShark then
        refreshSharkStatusLabel()
    end
end

local function pickBoostListMode(a, b, listModeApi)
    if type(b) == "string" then
        local t = tostring(b):lower()
        if t == "shark" or t:find("shark", 1, true) then return "shark" end
        if t == "machine" or t:find("machine", 1, true) then return "machine" end
        if t == "normal" or t:find("normal", 1, true) then return "normal" end
    end
    if type(a) == "string" then
        local t = tostring(a):lower()
        if t == "shark" or t:find("shark", 1, true) then return "shark" end
        if t == "machine" or t:find("machine", 1, true) then return "machine" end
        if t == "normal" or t:find("normal", 1, true) then return "normal" end
    end
    if listModeApi and type(listModeApi.getSelected) == "function" then
        local sel = tostring(listModeApi.getSelected() or ""):lower()
        if sel:find("shark", 1, true) then return "shark" end
        if sel:find("machine", 1, true) then return "machine" end
        if sel:find("normal", 1, true) then return "normal" end
    end
    return getBoostListMode()
end

local function applyBoostListMode(mode)
    mode = normBoostListMode(mode)
    local prev = getBoostListMode()
    if prev ~= mode then
        snapshotSelectedToMode(prev)
        STATE.boostListMode = mode
        applySelectedFromMode(mode)
        if type(refreshPetListsForModeSwitch) == "function" then
            refreshPetListsForModeSwitch()
        end
    else
        STATE.boostListMode = mode
    end

    refreshBoostModeUi(mode)
    seedBoostMutBucketIfEmpty(mode)
    syncMutSelectedGlobals()

    local bc = UIREF.boostControls
    if bc.mutDropdownApi and type(bc.mutDropdownApi.setSelected) == "function" then
        bc.mutDropdownApi.setSelected(getBoostMutSelected(mode))
    end
    if bc.mutDropdownApi and type(bc.mutDropdownApi.refreshLabel) == "function" then
        bc.mutDropdownApi.refreshLabel()
    end

    do
        local loop = rawget(_G, "AutoKGLoop")
        local isRun = false
        if loop then
            if type(loop.IsRunning) == "function" then
                local ok, v = pcall(function() return loop.IsRunning() end)
                isRun = ok and v == true
            else
                isRun = loop.running == true
            end
        end
        if isRun then
            local mml = rawget(_G, "MutationMachineLoop")
            if type(mml) == "table" then
                if mode == "machine" then
                    if type(mml.Start) == "function" then mml.Start("list_mode") end
                    if type(mml.SyncMutSelected) == "function" then mml.SyncMutSelected() end
                else
                    if type(mml.Stop) == "function" then mml.Stop("list_mode") end
                    syncMutSelectedGlobals()
                end
            end
        end
    end

    autoSave()
end

