        ensureTabDefaults(k)
    end

    ----------------------------------------------------------------
    -- UI REGISTRY (biar bisa update walau tab lain aktif)
    ----------------------------------------------------------------
    UIREF = {
        tabs = {},         -- [tabKey] = { listApi=..., selSet=... }
        summaryTitles = {},-- [tabKey] = summaryTitle
        boostControls = {},
    }

    ----------------------------------------------------------------
    -- Helper: hitung total selected & bikin teks summary
    ----------------------------------------------------------------
    local function countSelected(setTbl)
        -- hitung unique UUID core saja (brace + non-brace = 1 pet)
        local seen = {}
        local n = 0
        if type(setTbl) ~= "table" then
            return 0
        end
        for uuid, on in pairs(setTbl) do
            if on then
                local core = tostring(uuid):match("{?([0-9a-fA-F%-]+)}?") or tostring(uuid)
                if core ~= "" and not seen[core] then
                    seen[core] = true
                    n += 1
                end
            end
        end
        return n
    end

    local function buildSummaryText()
        local cNoos  = countSelected(selected.noos)
        local cBoost = countSelected(selected.boost)
        local c100   = countSelected(selected.seratusage)
        local cXP    = countSelected(selected.xp)
        local cGBXP  = countSelected(selected.gbxp)

        return string.format(
            "🐘 Elephant (%d)    🌙 Mutation (%d)    💯 500 Age (%d)    📘 XP (%d)    🧪 GBXP (%d)",
            cNoos, cBoost, c100, cXP, cGBXP
        )
    end

    local function refreshAllSummary()
        local txt = buildSummaryText()
        for _, title in pairs(UIREF.summaryTitles) do
            if title and title.Parent then
                title.Text = txt
            end
        end
    end

    ----------------------------------------------------------------
    -- LIST REFRESH (butuh CreateRowList API setItems & setSelected)
    ----------------------------------------------------------------
    local function _nuUUID(u)
        if u == nil then return nil, nil end
        local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
        if core == "" then return nil, nil end
        return "{" .. core .. "}", core
    end

    local function _getMachineSubmittedRaw()
        local function _fromMachine(machine)
            if type(machine) ~= "table" or type(machine.SubmittedPet) ~= "table" then
                return nil, nil
            end
            local sp = machine.SubmittedPet
            local raw = sp.UUID or sp.uuid or sp.PetUUID or sp.Id
                or (type(sp.PetData) == "table" and (sp.PetData.UUID or sp.PetData.uuid))
            return raw, sp
        end

        local api = rawget(_G, "MutationMachineApi")
            or ((getgenv and getgenv()) or _G).MutationMachineApi
        if api and type(api.GetMachine) == "function" then
            local okM, machine = pcall(function() return api.GetMachine() end)
            if okM then
                local raw, sp = _fromMachine(machine)
                if raw then return raw, sp end
            end
        end

        -- fallback sama seperti pet_list_view (API kadang belum sync)
        local DS = rawget(_G, "DataService")
            or ((getgenv and getgenv()) or _G).DataService
        if DS and type(DS.GetData) == "function" then
            local okP, profile = pcall(function() return DS:GetData() end)
            if okP and type(profile) == "table" then
                local raw, sp = _fromMachine(profile.PetMutationMachine)
                if raw then return raw, sp end
            end
        end

        return nil, nil
    end

    local function _forceKeepGBXPMachineSelected(sel, entries)
        sel = sel or {}
        local raw, sp = _getMachineSubmittedRaw()
        if not raw then return sel, nil end

        local br, core = _nuUUID(raw)
        local entryKey = nil
        if type(entries) == "table" then
            for _, e in ipairs(entries) do
                if e and e.key then
                    local eb, ec = _nuUUID(e.key)
                    if (core and ec == core) or (br and eb == br) or e.key == tostring(raw) then
                        entryKey = e.key
                        break
                    end
                end
            end
            -- fallback: row yang sudah di-label IN MUT MACHINE
            if not entryKey then
                for _, e in ipairs(entries) do
                    if e and e.key and type(e.name) == "string"
                        and e.name:find("IN MUT MACHINE", 1, true)
                    then
                        entryKey = e.key
                        break
                    end
                end
            end
        end
        if not entryKey then
            entryKey = br or tostring(raw)
            if type(entries) == "table" then
                local petType = tostring((sp and (sp.PetType or sp.Type or sp.Name)) or "Pet")
                local name = string.format("⏳ %s | IN MUT MACHINE", petType)
                if PetListView and type(PetListView.formatSubmittedMachineLabel) == "function" then
                    local okN, got = pcall(PetListView.formatSubmittedMachineLabel, sp, "IN MUT MACHINE")
                    if okN and type(got) == "string" and got ~= "" then
                        name = got
                    end
                end
                table.insert(entries, 1, {
                    key = entryKey,
                    name = name,
                    selected = true,
                    on = true,
                })
            end
        end

        -- select SEMUA varian + key yang dipakai UI list
        sel[entryKey] = true
        if br then sel[br] = true end
        if core then sel[core] = true end
        sel[tostring(raw)] = true

        selected.gbxp = selected.gbxp or sel
        selected.gbxp[entryKey] = true
        if br then selected.gbxp[br] = true end
        if core then selected.gbxp[core] = true end

        return sel, entryKey
    end

    ----------------------------------------------------------------
    -- UUID REMAP setelah Mutation Machine claim/submit
    -- Game sering ganti UUID → selected.gbxp harus ikut pindah.
    ----------------------------------------------------------------
    local _lastMutSubmittedCore = nil

    local function _mutBagSnapshot()
        local cores = {}
        local DS = rawget(_G, "DataService")
            or ((getgenv and getgenv()) or _G).DataService
        if not (DS and type(DS.GetData) == "function") then
            return cores, nil
        end
        local ok, profile = pcall(function() return DS:GetData() end)
        if not ok or type(profile) ~= "table" then
            return cores, nil
        end
        local bag = profile.PetsData
            and profile.PetsData.PetInventory
            and profile.PetsData.PetInventory.Data
        if type(bag) ~= "table" then
            return cores, nil
        end
        for rawUUID in pairs(bag) do
            local _, core = _nuUUID(rawUUID)
            if core then cores[core] = true end
        end
        return cores, bag
    end

    local function _mutPetMeta(rec)
        if type(rec) ~= "table" then
            return nil, 0, 0
        end
        local pd = rec.PetData or rec.Data or {}
        local ptype = tostring(
            rec.PetType or rec.Type or rec.Name
            or pd.PetType or pd.Type or pd.Name or ""
        )
        local age = tonumber(rec.Age or rec.age or rec.Level or pd.Age or pd.Level) or 0
        local kg = tonumber(rec.Weight or rec.weight or rec.KG or pd.Weight or pd.CurrentWeight) or 0
        return ptype, age, kg
    end

    local function _saveMutPendingFromSubmitted(raw, sp)
        if not raw or type(sp) ~= "table" then return end
        local br, core = _nuUUID(raw)
        if not core then return end

        local sel = selected.gbxp or {}
        local wasSelected = (sel[raw] or sel[br] or sel[core]) == true
        -- machine pet selalu dianggap selected target GBXP
        if not wasSelected then
            wasSelected = true
        end

        local ptype = tostring(sp.PetType or sp.Type or sp.Name
            or (type(sp.PetData) == "table" and sp.PetData.PetType) or "")
        local age = tonumber(sp.Age or sp.age or sp.Level
            or (type(sp.PetData) == "table" and sp.PetData.Age)) or 0
        local kg = tonumber(sp.Weight or sp.weight or sp.KG
            or (type(sp.PetData) == "table" and sp.PetData.Weight)) or 0

        local cores = select(1, _mutBagSnapshot())
        local prev = STATE._gbxpMutPending
        -- rejoin: kalau pending lama masih UUID yang sama, pertahankan bagCores lama
        -- (snapshot bag saat submit lebih akurat daripada snapshot setelah rejoin)
        if type(prev) == "table" and prev.oldCore == core and type(prev.bagCores) == "table" then
            local n = 0
            for _ in pairs(prev.bagCores) do n = n + 1; break end
            if n > 0 then
                cores = prev.bagCores
            end
        end

        STATE._gbxpMutPending = {
            oldCore = core,
            oldBr = br or ("{" .. core .. "}"),
            petType = ptype,
            oldAge = age,
            oldKg = kg,
            wasSelected = wasSelected,
            bagCores = cores,
            submittedAt = (type(prev) == "table" and prev.oldCore == core and prev.submittedAt) or os.time(),
        }

        -- pastikan selected ikut machine UUID setelah rejoin
        selected.gbxp = selected.gbxp or {}
        selected.gbxp[core] = true
        if br then selected.gbxp[br] = true end
    end

    local function _applyGbxpUuidRemap(oldCore, oldBr, newCore, newBr)
        if not oldCore or not newCore or oldCore == newCore then return false end

        local function remapSet(setTbl)
            if type(setTbl) ~= "table" then return end
            local on = setTbl[oldCore] or setTbl[oldBr] or setTbl["{" .. oldCore .. "}"]
            setTbl[oldCore] = nil
            setTbl[oldBr] = nil
            setTbl["{" .. oldCore .. "}"] = nil
            if on or STATE._gbxpMutPending and STATE._gbxpMutPending.wasSelected then
                setTbl[newCore] = true
                setTbl[newBr or ("{" .. newCore .. "}")] = true
            end
        end

        selected.gbxp = selected.gbxp or {}
        remapSet(selected.gbxp)
        if type(GBXP_MANUAL_SELECTED) == "table" then
            remapSet(GBXP_MANUAL_SELECTED)
        end

        local ref = UIREF.tabs and UIREF.tabs.gbxp
        if ref and type(ref.selSet) == "table" then
            remapSet(ref.selSet)
            ref.selSet = selected.gbxp
        end

        G.selected = selected
        _G.selected = selected
        return true
    end

    local function _resolveMutPendingRemap()
        local pc = STATE._gbxpMutPending
        if type(pc) ~= "table" or not pc.oldCore then return false end

        -- masih di machine → jangan resolve dulu
        local raw = select(1, _getMachineSubmittedRaw())
        if raw then return false end

        local baseline = pc.bagCores or {}
        local coresNow, bag = _mutBagSnapshot()
        if type(bag) ~= "table" then return false end

        -- timeout pending lama
        if (os.time() - (tonumber(pc.submittedAt) or 0)) > 3600 then
            STATE._gbxpMutPending = nil
            return false
        end

        -- UUID tidak berubah (pet balik dengan core yang sama)
        if coresNow[pc.oldCore] then
            -- pastikan tetap selected
            selected.gbxp = selected.gbxp or {}
            selected.gbxp[pc.oldCore] = true
            selected.gbxp[pc.oldBr or ("{" .. pc.oldCore .. "}")] = true
            STATE._gbxpMutPending = nil
            return true
        end

        local wantType = string.lower(tostring(pc.petType or ""))
        local best, bestScore = nil, -1

        for rawUUID, rec in pairs(bag) do
            local br, core = _nuUUID(rawUUID)
            if core and not baseline[core] and core ~= pc.oldCore then
                local ptype, age, kg = _mutPetMeta(rec)
                local score = 0
                if wantType ~= "" and string.lower(tostring(ptype or "")) == wantType then
                    score = score + 100
                elseif wantType ~= "" then
                    score = -1
                end
                if score >= 0 then
                    local dAge = math.abs((age or 0) - (tonumber(pc.oldAge) or 0))
                    local dKg = math.abs((kg or 0) - (tonumber(pc.oldKg) or 0))
                    score = score + math.max(0, 40 - dAge) + math.max(0, 20 - math.min(20, dKg))
                    if score > bestScore then
                        bestScore = score
                        best = { core = core, br = br or ("{" .. core .. "}") }
                    end
                end
            end
        end

        if not best or bestScore < 80 then
            return false
        end

        local ok = _applyGbxpUuidRemap(pc.oldCore, pc.oldBr, best.core, best.br)
        STATE._gbxpMutPending = nil
        return ok
    end

    local function _tickMutUuidRemap()
        local raw, sp = _getMachineSubmittedRaw()
        local _, core = _nuUUID(raw)

        if core then
            if core ~= _lastMutSubmittedCore then
                _saveMutPendingFromSubmitted(raw, sp)
            else
                local pc = STATE._gbxpMutPending
                if not (type(pc) == "table" and pc.oldCore == core) then
                    _saveMutPendingFromSubmitted(raw, sp)
                end
            end
            _lastMutSubmittedCore = core
            return false
        end

        -- SubmittedPet hilang → claim selesai / UUID berubah
        local remapped = false
        if _lastMutSubmittedCore or STATE._gbxpMutPending then
            remapped = _resolveMutPendingRemap() == true
        end
        _lastMutSubmittedCore = nil
        return remapped
    end

    local function entriesFingerprint(entries)
        local buf = {}
        for _, e in ipairs(entries or {}) do
            if type(e) == "table" then
                buf[#buf + 1] = tostring(e.key or "") .. "\1" .. tostring(e.name or "")
            else
                buf[#buf + 1] = tostring(e)
            end
        end
        return table.concat(buf, "\n")
    end

    local function isGbxpSearchFocused()
        local ref = UIREF.tabs and UIREF.tabs.gbxp
        local row = ref and ref.listRow
        if not row then
            return false
        end
        local box = row:FindFirstChild("SearchBox", true)
        return box and box:IsA("TextBox") and box:IsFocused() == true
    end

    local function refreshTabList(tabKey, opts)
        opts = opts or {}
        local ref = UIREF.tabs[tabKey]
        if not ref or not ref.listApi or type(ref.listApi) ~= "function" then
            return
        end

        local entries = {}
        local ok, res = pcall(function()
            return PetListView.buildEntriesForTab(tabKey, ref.selSet)
        end)
        if ok and type(res) == "table" then
            entries = res
        end

        local fp = entriesFingerprint(entries)
        if opts.skipIfUnchanged == true and ref.lastListFp == fp then
            return
        end
        ref.lastListFp = fp

        local machineEntryKey = nil
        if tabKey == "gbxp" then
            -- selalu ikuti selected.gbxp (remap menulis ke sini)
            selected.gbxp = selected.gbxp or ref.selSet or {}
            ref.selSet = selected.gbxp
            local sel, entryKey = _forceKeepGBXPMachineSelected(ref.selSet, entries)
            ref.selSet = sel
            selected.gbxp = sel
            machineEntryKey = entryKey
        end

        pcall(function()
            ref.listApi("setItems", entries)
        end)

        local map = {}
        local function _selHas(uuid)
            local sel = ref.selSet or {}
            if not uuid then return false end
            if sel[uuid] then return true end
            local br, core = _nuUUID(uuid)
            return (br and sel[br] == true) or (core and sel[core] == true) or false
        end
        -- map selected by matching entry keys (hindari mismatch brace/non-brace)
        for _, e in ipairs(entries) do
            if e and e.key and _selHas(e.key) then
                map[e.key] = true
            end
        end
        if machineEntryKey then
            map[machineEntryKey] = true
        end
        -- fallback: raw selSet
        for uuid, on in pairs(ref.selSet or {}) do
            if on then map[uuid] = true end
        end

        pcall(function()
            ref.listApi("setSelected", map)
        end)
        -- UI list sering reset selection setelah setItems → set ulang next frame
        if tabKey == "gbxp" and machineEntryKey then
            task.defer(function()
                pcall(function()
                    ref.listApi("setSelected", map)
                end)
            end)
            task.delay(0.15, function()
                pcall(function()
                    local sel2, key2 = _forceKeepGBXPMachineSelected(ref.selSet, entries)
                    ref.selSet = sel2
                    selected.gbxp = sel2
                    if key2 then map[key2] = true end
                    ref.listApi("setSelected", map)
                end)
            end)
        end
    end

    ----------------------------------------------------------------
    -- AUTO SELECT GBXP (reconcile periodik)
    ----------------------------------------------------------------
    if STATE.gbxpAutoSelect == nil then
        STATE.gbxpAutoSelect = true
    end
    do
        local n = tonumber(STATE.maxPetSelected) or 0
        if n < 0 then n = 0 end
        if n > 500 then n = 500 end
        STATE.maxPetSelected = math.floor(n)
    end

    -- helper normalize uuid biar aman (support "{...}" dan tanpa braces)
local function _normUUID(u)
    if u == nil then return nil end
    local s = tostring(u)
    local core = s:match("{?([0-9a-fA-F%-]+)}?") or s
    if core == "" then return nil end
    return "{" .. core .. "}", core
end

local function _addUUIDVariants(valid, uuid)
    if type(valid) ~= "table" or uuid == nil then return end
    local br, core = _normUUID(uuid)
    valid[tostring(uuid)] = true
    if br then valid[br] = true end
    if core then valid[core] = true end
end

local function _uuidInSet(uuid, set)
    if not uuid or not set then return false end
    if set[uuid] then return true end
    local br, core = _normUUID(uuid)
    return (br and set[br]) or (core and set[core]) or false
end

local function _isGBXPMachinePet(uuid)
    local api = rawget(_G, "MutationMachineApi")
    if api and type(api.IsPetInMachine) == "function" then
        local ok, v = pcall(function() return api.IsPetInMachine(uuid) end)
        return ok and v == true
    end
    return false
end

local function buildValidUUIDSet(tabKey)
    local valid = {}

    local ok, pets = pcall(function()
        return PetListView.listPetsForTab(tabKey)
    end)
    if not ok or type(pets) ~= "table" then
        return valid, pets
    end

    for _, p in ipairs(pets) do
        local uuid = p and p.uuid
        if uuid then
            _addUUIDVariants(valid, uuid)
        end
    end

    -- pet yang sedang di mutation machine tetap dianggap valid di GBXP
    if tabKey == "gbxp" then
        local api = rawget(_G, "MutationMachineApi")
        if api and type(api.GetMachine) == "function" then
            local okM, machine = pcall(function() return api.GetMachine() end)
            if okM and type(machine) == "table" and type(machine.SubmittedPet) == "table" then
                local sp = machine.SubmittedPet
                local raw = sp.UUID or sp.uuid or sp.PetUUID or sp.Id
                if raw then _addUUIDVariants(valid, raw) end
            end
        end
    end

    return valid, pets
end

local function reconcileTabSelected(tabKey, allowAutoAdd)
    selected[tabKey] = selected[tabKey] or {}
    local sel = selected[tabKey]

    local valid, pets = buildValidUUIDSet(tabKey)

    local changed = false

    local function _inRemapGrace(uuid)
        local grace = rawget(_G, "__GBXP_REMAP_GRACE")
            or ((getgenv and getgenv()) or _G).__GBXP_REMAP_GRACE
        if type(grace) ~= "table" or not grace.core then return false end
        if tick() > (tonumber(grace.untilAt) or 0) then return false end
        -- _nuUUID returns (braced, core)
        local _, core = _nuUUID(uuid)
        return core ~= nil and tostring(core) == tostring(grace.core)
    end

    local function _inMutPending(uuid)
        local pc = STATE and STATE._gbxpMutPending
        if type(pc) ~= "table" or not pc.oldCore then return false end
        local _, core = _nuUUID(uuid)
        return core ~= nil and tostring(core) == tostring(pc.oldCore)
    end

    -- (A) prune: hapus yang sudah tidak valid (contoh: XP pet jadi UNFAV)
    -- Manual GBXP: machine / remap grace / pending claim JANGAN di-unselect
    -- Bag belum siap (sering saat pet masuk mutation machine) → jangan wipe selection
    local bagReady = true
    if tabKey == "gbxp" and PetListView and type(PetListView.isPetBagReady) == "function" then
        local okReady, ready = pcall(PetListView.isPetBagReady)
        bagReady = okReady and ready == true
    end

    if bagReady then
        for uuid, on in pairs(sel) do
            if on and not _uuidInSet(uuid, valid) then
                if tabKey == "gbxp" and (_isGBXPMachinePet(uuid) or _inRemapGrace(uuid) or _inMutPending(uuid)) then
                    -- keep selected
                else
                    sel[uuid] = nil
                    changed = true
                end
            end
        end
    end

    -- Manual GBXP: pulihkan centang dari backup kalau prune/list sempat drop
    if tabKey == "gbxp" and STATE.gbxpAutoSelect ~= true and type(GBXP_MANUAL_SELECTED) == "table" then
        for uuid, on in pairs(GBXP_MANUAL_SELECTED) do
            if on and not _uuidInSet(uuid, sel) then
                if (not bagReady)
                    or _uuidInSet(uuid, valid)
                    or _isGBXPMachinePet(uuid)
                    or _inRemapGrace(uuid)
                    or _inMutPending(uuid)
                then
                    sel[uuid] = true
                    changed = true
                end
            end
        end
        selected.gbxp = sel
    end

    -- (A2) GBXP: paksa select pet yang sedang di machine (fix checkbox unselected)
    if tabKey == "gbxp" then
        local raw = select(1, _getMachineSubmittedRaw())
        local already = raw and _uuidInSet(raw, sel)
        local arr = nil
        if type(pets) == "table" then
            arr = {}
            for _, p in ipairs(pets) do
                if p and p.uuid then
                    arr[#arr + 1] = { key = p.uuid, name = p.name }
                end
            end
        end
        local sel2, entryKey = _forceKeepGBXPMachineSelected(sel, arr)
        sel = sel2
        selected.gbxp = sel
        -- hanya mark changed saat machine pet baru masuk selected
        -- (jangan refresh loop tiap 4 detik — bisa ganggu mode Auto)
        if entryKey and not already then
            changed = true
        end
    end

    -- (B) optional auto-add: khusus GBXP auto select ON (mode Auto)
    -- isi SEMUA kandidat (termasuk yang bukan machine); machine sudah di-force di A2
    if allowAutoAdd == true then
        if type(pets) == "table" then
            for _, p in ipairs(pets) do
                if p and p.uuid and not _uuidInSet(p.uuid, sel) then
                    sel[p.uuid] = true
                    changed = true
                end
            end
        else
            for uuid, _ in pairs(valid) do
                if not sel[uuid] then
                    sel[uuid] = true
                    changed = true
                end
            end
        end
    end

    if changed then
        autoSave()
        refreshAllSummary()
        refreshTabList(tabKey)
    end

    return changed
end

local function _uuidKey(u)
    local br = select(1, _normUUID(u))
    return br
end

local function _dedupePetUUIDSet(setTbl)
    if type(setTbl) ~= "table" then return false end
    local cores = {}
    local nonUuid = {}
    for k, on in pairs(setTbl) do
        if on then
            local br, core = _normUUID(k)
            if core and #core >= 30 and core:find("-", 1, true) then
                cores[core] = true
            else
                nonUuid[tostring(k)] = true
            end
        end
    end
    local changed = false
    for k in pairs(setTbl) do
        local br, core = _normUUID(k)
        if core and cores[core] and tostring(k) ~= br then
            setTbl[k] = nil
            changed = true
        end
    end
    for core in pairs(cores) do
        local br = "{" .. core .. "}"
        if setTbl[br] ~= true then
            setTbl[br] = true
            changed = true
        end
    end
    for k in pairs(nonUuid) do
        if setTbl[k] ~= true then
            setTbl[k] = true
            changed = true
        end
    end
    return changed
end

local function isUnlimitedMaxPetSelected()
    local n = tonumber(STATE and STATE.maxPetSelected) or 0
    return n <= 0
end

local function getMaxPetSelectedN()
    local n = tonumber(STATE and STATE.maxPetSelected) or 0
    if n < 0 then n = 0 end
    if n > 500 then n = 500 end
    n = math.floor(n)
    if n == 0 then
        return 100000
    end
    return n
end

-- Auto: hanya pet yang masih punya stage di mode sekarang (AUTO/A/B/C/D/ABCD).
-- age belum kebaca → keep. Pet di mutation machine → keep.
local function _gbxpStillInCurrentStage(uuid)
    if not uuid then
        return false
    end
    if _isGBXPMachinePet(uuid) then
        return true
    end
    local loop = rawget(_G, "AutoKGLoop") or ((getgenv and getgenv()) or _G).AutoKGLoop
    if not (type(loop) == "table" and type(loop.GetStageForGBXP) == "function") then
        return true
    end
    local ok, stage, age = pcall(loop.GetStageForGBXP, uuid)
    if not ok then
        return true
    end
    if age == nil then
        return true
    end
    return stage ~= nil
end

local function _rankUuidKeys(keys, kgMap)
    table.sort(keys, function(a, b)
        local ka = tonumber(kgMap[a]) or 0
        local kb = tonumber(kgMap[b]) or 0
        if ka ~= kb then
            return ka > kb
        end
        return tostring(a) < tostring(b)
    end)
end

local function _trimPickedToMax(picked, pickedSet, kgMap, maxN, protectKey)
    while #picked > maxN do
        local dropIdx = nil
        local dropKg = math.huge
        local dropKey = nil
        for i, k in ipairs(picked) do
            if k ~= protectKey then
                local w = tonumber(kgMap[k]) or 0
                if dropIdx == nil or w < dropKg or (w == dropKg and tostring(k) > tostring(dropKey)) then
                    dropIdx = i
                    dropKg = w
                    dropKey = k
                end
            end
        end
        if not dropIdx then
            break
        end
        pickedSet[picked[dropIdx]] = nil
        table.remove(picked, dropIdx)
    end
end

local function _writeGbxpSelected(keepSet)
    selected.gbxp = selected.gbxp or {}
    local sel = selected.gbxp
    local changed = false
    for uuid, on in pairs(sel) do
        if on then
            local k = _uuidKey(uuid)
            if not k or keepSet[k] ~= true then
                sel[uuid] = nil
                changed = true
            end
        end
    end
    for k in pairs(keepSet) do
        if sel[k] ~= true then
            sel[k] = true
            changed = true
        end
    end
    if _dedupePetUUIDSet(sel) then
        changed = true
    end
    return changed
end

local function reconcileMaxTeamSelected()
    if STATE.gbxpAutoSelect ~= true then
        return false
    end
    local bagReady = true
    if PetListView and type(PetListView.isPetBagReady) == "function" then
        local okReady, ready = pcall(PetListView.isPetBagReady)
        bagReady = okReady and ready == true
    elseif PetListView and type(PetListView.getDatastoreBagIndex) == "function" then
        local okBag, bag = pcall(function()
            return select(1, PetListView.getDatastoreBagIndex())
        end)
        bagReady = okBag and type(bag) == "table"
    end
    if not bagReady then
        return false
    end

    local unlimited = isUnlimitedMaxPetSelected()
    local maxN = getMaxPetSelectedN()
    local valid, pets = buildValidUUIDSet("gbxp")
    if not valid then
        return false
    end

    local eligible = {}
    local kgMap = {}
    if type(pets) == "table" then
        for _, p in ipairs(pets) do
            local k = p and _uuidKey(p.uuid)
            if k and (unlimited or _gbxpStillInCurrentStage(p.uuid)) then
                eligible[k] = true
                local w = tonumber(p.kg) or 0
                if (kgMap[k] or -1) < w then
                    kgMap[k] = w
                end
            end
        end
    else
        for u, on in pairs(valid) do
            if on then
                local k = _uuidKey(u)
                if k and (unlimited or _gbxpStillInCurrentStage(u)) then
                    eligible[k] = true
                    if kgMap[k] == nil then
                        kgMap[k] = 0
                    end
                end
            end
        end
    end

    local machineKey = _uuidKey(_getMachineSubmittedRaw())
    if machineKey then
        eligible[machineKey] = true
        if kgMap[machineKey] == nil then
            kgMap[machineKey] = 0
        end
    end

    local picked = {}
    local pickedSet = {}
    local function addPick(k)
        if not k or pickedSet[k] or not eligible[k] then
            return false
        end
        pickedSet[k] = true
        picked[#picked + 1] = k
        return true
    end

    selected.gbxp = selected.gbxp or {}
    for u, on in pairs(selected.gbxp) do
        if on then
            addPick(_uuidKey(u))
        end
    end
    if machineKey then
        addPick(machineKey)
    end
    _trimPickedToMax(picked, pickedSet, kgMap, maxN, machineKey)

    local all = {}
    for k in pairs(eligible) do
        if not pickedSet[k] then
            all[#all + 1] = k
        end
    end
    _rankUuidKeys(all, kgMap)
    for _, k in ipairs(all) do
        if #picked >= maxN then
            break
        end
        addPick(k)
    end
    if machineKey then
        addPick(machineKey)
    end
    _trimPickedToMax(picked, pickedSet, kgMap, maxN, machineKey)

    local changed = _writeGbxpSelected(pickedSet)
    if changed then
        autoSave()
        refreshAllSummary()
        refreshTabList("gbxp")
    end
    return changed
end

local function reconcileGBXP()
    -- UUID remap setelah claim: pakai MutationMachineRemap (pola agebreak)
    -- fallback tick lama kalau module belum load
    local remap = rawget(_G, "MutationMachineRemap")
        or ((getgenv and getgenv()) or _G).MutationMachineRemap
    local remappedOrDirty = false
    if not (remap and type(remap.Start) == "function") then
        local remapped = false
        pcall(function()
            remapped = _tickMutUuidRemap() == true
        end)
        if remapped then
            remappedOrDirty = true
            pcall(autoSave)
        end
    elseif _G.__AUTOKG_DIRTY or _G.__GBXP_REMAP_DIRTY then
        remappedOrDirty = true
    end

    -- PENTING: reconcile/keep dulu, baru refresh list.
    -- Kalau refresh dulu, pet_list_view prune bisa hapus UUID remapped (manual hilang).
    if STATE.gbxpAutoSelect ~= true then
        reconcileTabSelected("gbxp", false)
    else
        reconcileTabSelected("gbxp", false)
        reconcileMaxTeamSelected()
    end

    if remappedOrDirty then
        _G.__GBXP_REMAP_DIRTY = false
        local Genv = (getgenv and getgenv()) or _G
        Genv.__GBXP_REMAP_DIRTY = false
        pcall(refreshAllSummary)
        pcall(function() refreshTabList("gbxp") end)
    end
end

refreshPetListsForModeSwitch = function()
    local keys = { "boost", "xp", "noos", "seratusage", "gbxp" }
    for _, k in ipairs(keys) do
        local ref = UIREF.tabs and UIREF.tabs[k]
        if ref then
            ref.selSet = selected[k]
            ref.lastListFp = nil
        end
        pcall(function()
            refreshTabList(k)
        end)
    end
    pcall(refreshAllSummary)
end

