    UIREF.ageBakuApply = function(mode)
        mode = normAgeListMode(mode)
        local prev = getAgeListMode()
        if prev ~= mode then
            snapshotAgeTeamToMode(prev)
            STATE.ageListMode = mode
            applyAgeTeamFromMode(mode)
            local ref = UIREF.tabs and UIREF.tabs.seratusage
            if ref then
                ref.selSet = selected.seratusage
                ref.lastListFp = nil
            end
            pcall(function()
                refreshTabList("seratusage")
            end)
            pcall(refreshAllSummary)
        else
            STATE.ageListMode = mode
        end
        G.AGE_LIST_MODE = mode
        _G.AGE_LIST_MODE = mode
        if UIREF.ageBakuRefreshVis then
            UIREF.ageBakuRefreshVis()
        end
        autoSave()
        _G.__AUTOKG_DIRTY = true
        G.__AUTOKG_DIRTY = true
    end

