                { key = "baku",   label = "Baku" },
            }
        end,
        initial     = STATE.ageListMode or "normal",
        onChanged   = function(a, b)
            local t = tostring(b or a or ""):lower()
            if t:find("baku", 1, true) then
                UIREF.ageBakuApply("baku")
            else
                UIREF.ageBakuApply("normal")
            end
        end,
    })
end

