    UIREF.ageBakuRefreshVis = function()
        local bakuOn = getAgeListMode() == "baku"
        local ab = UIREF.ageBaku
        local ref = UIREF.tabs and UIREF.tabs.seratusage
        if ref and ref.listTitleLabel and ref.listTitleLabel.Parent then
            ref.listTitleLabel.Text = getAgePetListLabel()
        end
        if not ab then return end
        if ab.growRow then ab.growRow.Visible = bakuOn end
        if ab.baitRow then ab.baitRow.Visible = bakuOn end
        if ab.spreadRow then ab.spreadRow.Visible = bakuOn end
        if ab.minRow then ab.minRow.Visible = bakuOn end
        if ab.leaveRow then ab.leaveRow.Visible = bakuOn end
        if ab.shovelRow then ab.shovelRow.Visible = bakuOn end
        if ab.stockRow then ab.stockRow.Visible = bakuOn end
        if ab.processRow then ab.processRow.Visible = bakuOn end
        if ab.timeRow then ab.timeRow.Visible = bakuOn end
        if ab.capRow then ab.capRow.Visible = bakuOn end
    end
    UIREF.ageBakuRefreshVis()

    if STATE._bakuStatusPollStarted ~= true then
        STATE._bakuStatusPollStarted = true
        task.spawn(function()
            while true do
                task.wait(1)
                if tostring(STATE.ageListMode or "") ~= "baku" then
                    continue
                end
                local st = rawget(_G, "BAKU_STATUS") or (((getgenv and getgenv()) or _G).BAKU_STATUS)
                local ab = UIREF.ageBaku
                if type(st) == "table" and ab then
                    if ab.stockLabel then
                        ab.stockLabel.Text = string.format(
                            "Ripe fruits: %s  |  Ripe NM: %s / %s  (leave %s)  |  Other mut: %s",
                            tostring(st.fruitTotal or 0),
                            tostring(st.nightmareCount or 0),
                            tostring(st.minNightmare or 1000),
                            tostring(st.leaveNightmare or 100),
                            tostring(st.otherMutCount or 0)
                        )
                    end
                    if ab.processLabel then
                        local ph = tostring(st.phase or "idle")
                        if ph == "xp" then
                            ph = "XP tab (target not 500 Age yet)"
                        elseif ph == "boost" then
                            ph = "Mutation tab (target stage A)"
                        elseif ph == "wait-target" then
                            ph = "waiting (need 500 Age GBXP target)"
                        elseif ph == "NOOS" or ph == "noos" then
                            ph = "Elephant tab (target not 500 Age yet)"
                        end
                        ab.processLabel.Text = "Process: " .. ph
                    end
                    if ab.timeLabel then
                        local comboTag = (st.comboDone == true) and " (done)" or ""
                        ab.timeLabel.Text = string.format(
                            "Grow %s  |  Bait %s  |  Spread %s  |  Until min NM %s%s",
                            tostring(st.timeGrowTxt or "0:00"),
                            tostring(st.timeBaitTxt or "0:00"),
                            tostring(st.timeSpreadTxt or "0:00"),
                            tostring(st.timeComboTxt or "0:00"),
                            comboTag
                        )
                    end
                    if ab.capLabel then
                        if st.capacityOk == true then
                            ab.capLabel.Text = string.format("Capacity OK: %s / %s slots", tostring(st.maxSlots or 0), tostring(st.minNightmare or 1000))
                        else
                            ab.capLabel.Text = string.format(
                                "Not enough plants. Current trees can hold %s fruits. You need at least %s fruit slots to reach this Nightmare goal. Plant more trees.",
                                tostring(st.maxSlots or 0),
                                tostring(st.minNightmare or 1000)
                            )
                        end
                    end
                end
            end
        end)
    end
end
end
