local function clearSetInPlace(t)
    if type(t) ~= "table" then return {} end
    for k in pairs(t) do
        t[k] = nil
    end
    return t
end

local function copySet(src)
    local out = {}
    if type(src) == "table" then
        for k, v in pairs(src) do
            if v == true then
                out[k] = true
            end
        end
    end
    return out
end

local function replaceSetInPlace(dst, src)
    dst = dst or {}
    for k in pairs(dst) do
        dst[k] = nil
    end
    if type(src) == "table" then
        for k, v in pairs(src) do
            if v == true then
                dst[k] = true
            end
        end
    end
    return dst
end

GBXP_MANUAL_SELECTED = GBXP_MANUAL_SELECTED or {}

local function applyGBXPMode(mode)
    mode = tostring(mode or ""):lower()
    selected.gbxp = selected.gbxp or {}

    if mode == "auto" then
        -- simpan manual list dulu sebelum auto overwrite
        if STATE.gbxpAutoSelect == false then
            GBXP_MANUAL_SELECTED = copySet(selected.gbxp)
            G.GBXP_MANUAL_SELECTED = GBXP_MANUAL_SELECTED
            _G.GBXP_MANUAL_SELECTED = GBXP_MANUAL_SELECTED
        end

        STATE.gbxpAutoSelect = true
        clearSetInPlace(selected.gbxp)
        reconcileGBXP()

    elseif mode == "manual" then
        STATE.gbxpAutoSelect = false

        -- restore manual list lama
        GBXP_MANUAL_SELECTED = GBXP_MANUAL_SELECTED
            or G.GBXP_MANUAL_SELECTED
            or _G.GBXP_MANUAL_SELECTED
            or {}
        replaceSetInPlace(selected.gbxp, GBXP_MANUAL_SELECTED)
        G.GBXP_MANUAL_SELECTED = GBXP_MANUAL_SELECTED
        _G.GBXP_MANUAL_SELECTED = GBXP_MANUAL_SELECTED
        reconcileTabSelected("gbxp", false)

    else
        return
    end

    G.gbxpAutoSelect = STATE.gbxpAutoSelect
    _G.gbxpAutoSelect = STATE.gbxpAutoSelect

    refreshTabList("gbxp")
    refreshAllSummary()
    autoSave()
end


-- helper normalize teks
local function _norm(s)
    s = tostring(s or ""):lower()
    s = s:gsub("%s+", " ")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")
    return s
end

-- coba ambil mode dari argumen callback (kalau UI kamu ngasih)
local function _pickModeFromArgs(a, b)
    -- case 1: arg langsung key string
    if type(a) == "string" then
        local t = _norm(a)
        if t:find("auto", 1, true) then return "auto" end
        if t:find("manual", 1, true) then return "manual" end
        if t == "auto" or t == "manual" then return t end
    end

    -- case 2: arg ke-2 table map {key=true}
    if type(b) == "table" then
        for k, on in pairs(b) do
            if on then
                local t = _norm(k)
                if t:find("auto", 1, true) then return "auto" end
                if t:find("manual", 1, true) then return "manual" end
                if t == "auto" or t == "manual" then return t end
            end
        end
    end

    return nil
end



-- ✅ bikin dropdown + ambil "value label" row untuk fallback baca pilihan
local dropdownRow, dropdownValueLabel
dropdownRow, dropdownValueLabel = ui:CreateRowDropdown(body, {
    label       = "GBXP Select Mode",
    placeholder = "Choose mode...",
    mode        = "single",
    getItems    = function() return GBXP_MODE_ITEMS end,
    initial     = (STATE.gbxpAutoSelect == false) and "manual" or "auto",

    onChanged = function(a, b)
        -- 1) coba dari args (kalau UI support)
        local picked = _pickModeFromArgs(a, b)

        -- 2) fallback: baca dari TextLabel value dropdown (kalau UI kamu gak kirim key)
        if not picked and dropdownValueLabel and dropdownValueLabel.Parent then
            local t = _norm(dropdownValueLabel.Text)
            if t:find("auto", 1, true) then picked = "auto" end
            if t:find("manual", 1, true) then picked = "manual" end
        end

        -- 3) fallback terakhir: jangan toggle buta, pakai state (optional)
        if not picked then
            picked = (STATE.gbxpAutoSelect == true) and "manual" or "auto"
            --warn("[GBXP MODE] fallback toggle used, picked =", picked)
        end

        applyGBXPMode(picked)
    end,
})
