local function getGbxpFavItems()
    return {
        { key = "unfav", label = "Unfavorite" },
        { key = "fav",   label = "Favorite" },
        { key = "all",   label = "All" },
    }
end

local function _pickFavFromArgs(a, b)
    local function fromText(s)
        local t = _norm(s)
        if t == "unfav" or t == "unfavorite" then return "unfav" end
        if t == "fav" or t == "favorite" then return "fav" end
        if t == "all" then return "all" end
        if t:find("unfav", 1, true) or t:find("unfavorite", 1, true) then
            return "unfav"
        end
        if t:find("favorite", 1, true) then return "fav" end
        if t:find("all", 1, true) then return "all" end
        return nil
    end
    if type(a) == "string" and a ~= "single" and a ~= "multi" then
        local picked = fromText(a)
        if picked then return picked end
    end
    if type(b) == "string" then
        local picked = fromText(b)
        if picked then return picked end
    elseif type(b) == "table" then
        for k, on in pairs(b) do
            if on then
                local picked = fromText(k)
                if picked then return picked end
            end
        end
    end
    return nil
end

