----------------------------------------------------------------
-- PnP Pet Config (SAVE/LOAD via GLOBAL swap_skill)
-- Mode A = OnClientEvent (default)
-- Mode B = GetPetCooldown:InvokeServer
-- Mode C = Event Cache (Heartbeat)
-- Mode D = CAS skill (PNP debug; delay UI diabaikan)
-- scanInterval: Mode B poll / Mode C anti-spam (boleh 0)
-- ✅ Source of truth: (getgenv() or _G).swap_skill
----------------------------------------------------------------

local function BuildSwapSkillConfig(ui, bodyParent, STATE, PetListView, autoSave)
    local G = (getgenv and getgenv()) or _G

    ----------------------------------------------------------------
    -- SOURCE OF TRUTH (GLOBAL)
    ----------------------------------------------------------------
    local swap_skill = (type(STATE) == "table" and type(STATE.swap_skill) == "table" and STATE.swap_skill)
        or rawget(G, "swap_skill")
        or rawget(_G, "swap_skill")
    if type(swap_skill) ~= "table" then
        swap_skill = {
            enabled      = false,
            selected     = {},
            order        = {},
            delays       = {},
            poll         = 0.05,
            scanInterval = 0.15,
            mode         = "A",
        }
    end
    if type(STATE) == "table" then
        STATE.swap_skill = swap_skill
    end
    G.swap_skill = swap_skill
    _G.swap_skill = swap_skill

    local SS = swap_skill

    -- normalize types (jangan overwrite keras)
    SS.enabled      = (SS.enabled == true)
    SS.selected     = (type(SS.selected) == "table") and SS.selected or {}
    SS.order        = (type(SS.order)    == "table") and SS.order    or {}
    SS.delays       = (type(SS.delays)   == "table") and SS.delays   or {}
    do
        local si = tonumber(SS.scanInterval)
        if si == nil then si = 0.15 end
        if si < 0 then si = 0 end
        SS.scanInterval = si
    end
    SS.poll         = tonumber(SS.poll) or 0.05
    do
        local m = tostring(SS.mode or "A"):upper()
        if m ~= "A" and m ~= "B" and m ~= "C" and m ~= "D" then m = "A" end
        SS.mode = m
    end

    local refreshSwapList
    local pickupHead, equipHead

    ----------------------------------------------------------------
    -- helpers
    ----------------------------------------------------------------
    local function _normUUID(u)
        if u == nil then return nil end
        local s = tostring(u)
        local core = s:match("{?([0-9a-fA-F%-]+)}?") or s
        if core == "" then return nil end
        return "{" .. core .. "}"
    end

    local function toNumFloat(text)
        text = tostring(text or ""):gsub("%s+", "")
        if text == "" then return nil end
        text = text:gsub(",", ".")
        return tonumber(text)
    end

    local function norm(s)
        s = tostring(s or ""):lower()
        s = s:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
        return s
    end

    local function ensureDelay(uuid)
        uuid = _normUUID(uuid)
        if not uuid then return nil end
        local d = SS.delays[uuid]
        if type(d) ~= "table" then
            d = { unequipAfterReady = 0.6, equipNext = 0 }
            SS.delays[uuid] = d
        end
        d.unequipAfterReady = tonumber(d.unequipAfterReady) or 0.6
        d.equipNext         = tonumber(d.equipNext) or 0
        return d
    end

    local function ensureOrderUnique(uuid)
        uuid = _normUUID(uuid)
        if not uuid then return end
        for i = #SS.order, 1, -1 do
            if SS.order[i] == uuid then
                table.remove(SS.order, i)
            end
        end
        table.insert(SS.order, 1, uuid)
    end

    local function getSwapPetEntries()
        -- ambil dari petList main_pet (agar sesuai flow kamu)
        local ok, entries = pcall(function()
            return PetListView.buildEntriesForTab("noos", STATE.main_pet and STATE.main_pet.selected or {})
        end)
        if ok and type(entries) == "table" then return entries end
        return {}
    end

    -- apply helper (Start/Stop module)
    local function applySwapSkillModule(reason)
        local GG = (getgenv and getgenv()) or _G
        local Mod = GG.PnPPet or GG.SwapSkillModule or GG.SwapSkill
            or _G.PnPPet or _G.SwapSkillModule or _G.SwapSkill
        if not Mod then return end

        local function callMaybe(obj, method, ...)
            local f = obj and obj[method]
            if type(f) ~= "function" then return false end
            local args = table.pack(...)
            if pcall(function() f(obj, table.unpack(args, 1, args.n)) end) then return true end
            return pcall(function() f(table.unpack(args, 1, args.n)) end)
        end

        local hasAny = (SS.selected and next(SS.selected) ~= nil)

        if SS.enabled and hasAny then
            callMaybe(Mod, "SetMode", SS.mode or "A")
            callMaybe(Mod, "SyncFromState"); callMaybe(Mod, "syncFromState")
            callMaybe(Mod, "Start");        callMaybe(Mod, "start")
        else
            callMaybe(Mod, "Stop", reason or "ui"); callMaybe(Mod, "stop", reason or "ui")
        end
    end

    -- UI mini helpers
    local function mkCorner(p, r)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, r or 6)
        c.Parent = p
    end
    local function mkStroke(p, col, th, tr)
        local s = Instance.new("UIStroke")
        s.Color = col or Color3.fromRGB(40,40,40)
        s.Thickness = th or 1
        s.Transparency = tr or 0.5
        s.Parent = p
    end
    local function mkPad(p, l, r, t, b)
        local pad = Instance.new("UIPadding")
        pad.PaddingTop    = UDim.new(0, t or 4)
        pad.PaddingBottom = UDim.new(0, b or 4)
        pad.PaddingLeft   = UDim.new(0, l or 4)
        pad.PaddingRight  = UDim.new(0, r or 4)
        pad.Parent = p
    end

    ----------------------------------------------------------------
    -- WRAP
    ----------------------------------------------------------------
    local wrap = Instance.new("Frame")
    wrap.Name = "SwapSkillWrap"
    wrap.Parent = bodyParent
    wrap.BackgroundTransparency = 1
    wrap.Size = UDim2.new(1,0,0,0)
    wrap.AutomaticSize = Enum.AutomaticSize.Y

    local ROW_H = 26
    local GAP   = 6

    ----------------------------------------------------------------
    -- SCAN INTERVAL (row 1)
    ----------------------------------------------------------------
    local intervalWrap = Instance.new("Frame")
    intervalWrap.Name = "IntervalWrap"
    intervalWrap.Parent = wrap
    intervalWrap.BackgroundColor3 = Color3.fromRGB(22,22,22)
    intervalWrap.BorderSizePixel = 0
    intervalWrap.Size = UDim2.new(1, 0, 0, ROW_H)
    intervalWrap.Position = UDim2.new(0, 0, 0, 0)
    mkCorner(intervalWrap, 4); mkStroke(intervalWrap); mkPad(intervalWrap, 6, 6, 0, 0)

    local intervalLbl = Instance.new("TextLabel")
    intervalLbl.Parent = intervalWrap
    intervalLbl.BackgroundTransparency = 1
    intervalLbl.Size = UDim2.new(1, -90, 1, 0)
    intervalLbl.Font = Enum.Font.Gotham
    intervalLbl.TextSize = 12
    intervalLbl.TextXAlignment = Enum.TextXAlignment.Left
    intervalLbl.TextColor3 = Color3.fromRGB(235,235,235)
    intervalLbl.Text = "Scan Interval (B/C)"

    local intervalBox = Instance.new("TextBox")
    intervalBox.Name = "ScanInterval"
    intervalBox.Parent = intervalWrap
    intervalBox.BackgroundColor3 = Color3.fromRGB(10,10,10)
    intervalBox.BorderSizePixel = 0
    intervalBox.Size = UDim2.new(0, 78, 0, 22)
    intervalBox.Position = UDim2.new(1, -78, 0.5, -11)
    intervalBox.Font = Enum.Font.Gotham
    intervalBox.TextSize = 12
    intervalBox.TextColor3 = Color3.fromRGB(235,235,235)
    intervalBox.TextXAlignment = Enum.TextXAlignment.Center
    intervalBox.ClearTextOnFocus = false
    intervalBox.Text = tostring(SS.scanInterval ~= nil and SS.scanInterval or 0.15)
    mkCorner(intervalBox, 4); mkStroke(intervalBox, Color3.fromRGB(40,40,40), 1, 0.6)

    intervalBox.FocusLost:Connect(function()
        local n = toNumFloat(intervalBox.Text)
        -- boleh 0; tolak hanya nil / negatif
        if n == nil or n < 0 then
            intervalBox.Text = tostring(SS.scanInterval ~= nil and SS.scanInterval or 0.15)
            return
        end

        SS.scanInterval = n
        intervalBox.Text = tostring(n)

        -- mirror global + save
        G.swap_skill = SS
        _G.swap_skill = SS
        autoSave()

        pcall(function()
            local GG = (getgenv and getgenv()) or _G
            local Mod = GG.PnPPet or GG.SwapSkillModule or GG.SwapSkill
                or _G.PnPPet or _G.SwapSkillModule or _G.SwapSkill
            if not Mod then return end
            if type(Mod.SetScanInterval) == "function" then
                Mod.SetScanInterval(n)
            elseif type(Mod.setScanInterval) == "function" then
                Mod.setScanInterval(n)
            end
        end)
        applySwapSkillModule("ui_interval")
    end)

    ----------------------------------------------------------------
    -- MODE A/B/C/D (row 2)
    ----------------------------------------------------------------
    local modeWrap = Instance.new("Frame")
    modeWrap.Name = "ModeWrap"
    modeWrap.Parent = wrap
    modeWrap.BackgroundColor3 = Color3.fromRGB(22,22,22)
    modeWrap.BorderSizePixel = 0
