    mkCorner(modeBtn, 4); mkStroke(modeBtn, Color3.fromRGB(40,40,40), 1, 0.6)

    local function renderMode()
        local m = tostring(SS.mode or "A"):upper()
        if m ~= "A" and m ~= "B" and m ~= "C" and m ~= "D" then m = "A" end
        SS.mode = m
        if m == "B" then
            modeBtn.Text = "Mode B"
            modeBtn.TextColor3 = Color3.fromRGB(120, 200, 255)
            modeLbl.Text = "Mode B"
        elseif m == "C" then
            modeBtn.Text = "Mode C"
            modeBtn.TextColor3 = Color3.fromRGB(120, 255, 160)
            modeLbl.Text = "Mode C"
        elseif m == "D" then
            modeBtn.Text = "Mode D"
            modeBtn.TextColor3 = Color3.fromRGB(255, 140, 80)
            modeLbl.Text = "Mode D"
        else
            modeBtn.Text = "Mode A"
            modeBtn.TextColor3 = Color3.fromRGB(255, 217, 0)
            modeLbl.Text = "Mode A"
        end
        if pickupHead then pickupHead.Visible = (m ~= "D") end
        if equipHead then equipHead.Visible = (m ~= "D") end
        if refreshSwapList then refreshSwapList() end
    end
    renderMode()

    modeBtn.MouseButton1Click:Connect(function()
        local cur = tostring(SS.mode or "A"):upper()
        if cur == "A" then
            SS.mode = "B"
        elseif cur == "B" then
            SS.mode = "C"
        elseif cur == "C" then
            SS.mode = "D"
        else
            SS.mode = "A"
        end
        renderMode()

        G.swap_skill = SS
        _G.swap_skill = SS
        autoSave()

        pcall(function()
            local GG = (getgenv and getgenv()) or _G
            local Mod = GG.PnPPet or GG.SwapSkillModule or GG.SwapSkill
                or _G.PnPPet or _G.SwapSkillModule or _G.SwapSkill
            if Mod and type(Mod.SetMode) == "function" then
                Mod.SetMode(SS.mode)
            end
        end)
        applySwapSkillModule("ui_mode")
    end)

