    header.Name = "SwapSkillHeader"
    header.Parent = wrap
    header.BackgroundColor3 = Color3.fromRGB(18,18,18)
    header.BorderSizePixel = 0
    header.Position = UDim2.new(0,0,0, TOP_Y + 26 + GAP)
    header.Size = UDim2.new(1,0,0, headerH)
    mkCorner(header, 6); mkStroke(header); mkPad(header, 6,6,0,0)

    local function mkHead(text, posUDim2, sizeUDim2, align)
        local t = Instance.new("TextLabel")
        t.Parent = header
        t.BackgroundTransparency = 1
        t.Position = posUDim2
        t.Size = sizeUDim2
        t.Font = Enum.Font.GothamBold
        t.TextSize = 11
        t.TextColor3 = Color3.fromRGB(170,170,170)
        t.TextXAlignment = align or Enum.TextXAlignment.Left
        t.Text = text
        return t
    end

    local BOX_W      = 52
    local BOX_GAP    = 9
    local HEAD_SHIFT = 8

    mkHead("Status", UDim2.new(0, 0, 0, 0), UDim2.new(0, 34, 1, 0), Enum.TextXAlignment.Center)

    local PET_RIGHT = (BOX_W + BOX_GAP + BOX_W) + HEAD_SHIFT + 8
    mkHead("PET", UDim2.new(0, 40, 0, 0), UDim2.new(1, -(40 + PET_RIGHT), 1, 0), Enum.TextXAlignment.Center)

    pickupHead = mkHead("Pickup", UDim2.new(1, -(BOX_W + BOX_GAP + BOX_W) - HEAD_SHIFT, 0, 0), UDim2.new(0, BOX_W, 1, 0), Enum.TextXAlignment.Center)
    equipHead = mkHead("Equip",  UDim2.new(1, -(BOX_W) - HEAD_SHIFT,              0, 0), UDim2.new(0, BOX_W, 1, 0), Enum.TextXAlignment.Center)

    ----------------------------------------------------------------
    -- SCROLL LIST (row 5)
    ----------------------------------------------------------------
    local ROW_ITEM_H, ROW_PAD, VISIBLE_ROWS = 28, 6, 6
    local function calcListHeight(count)
        local rows = math.min(count or 0, VISIBLE_ROWS)
        if rows <= 0 then rows = 1 end
        return (rows * ROW_ITEM_H) + ((rows - 1) * ROW_PAD) + 10 + 10
    end

    local sf = Instance.new("ScrollingFrame")
    sf.Name = "SwapSkillList"
    sf.Parent = wrap
    sf.BackgroundColor3 = Color3.fromRGB(15,15,15)
    sf.BorderSizePixel = 0
    sf.Position = UDim2.new(0,0,0, (TOP_Y + 26 + GAP) + headerH + GAP)
    sf.Size = UDim2.new(1,0,0,calcListHeight(0))
    sf.ScrollBarThickness = 0
    sf.ScrollBarImageTransparency = 1
    sf.ScrollingDirection = Enum.ScrollingDirection.Y
    sf.AutomaticCanvasSize = Enum.AutomaticSize.None
    sf.ClipsDescendants = true
    mkCorner(sf, 6); mkStroke(sf); mkPad(sf, 6,6,10,10)

    local layout = Instance.new("UIListLayout")
    layout.Parent = sf
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, ROW_PAD)

    local function clearRows()
        for _, ch in ipairs(sf:GetChildren()) do
            if ch:IsA("Frame") and ch.Name:sub(1,5) == "Item_" then
                ch:Destroy()
            end
            if ch:IsA("TextLabel") and ch.Name == "EmptyHint" then
                ch:Destroy()
            end
        end
    end

    local function buildRow(i, entry)
        local uuid = _normUUID(entry.uuid or entry.key or entry.id or entry.UUID)
        if not uuid then return end

        local name = tostring(entry.name or entry.label or uuid)
        local d = ensureDelay(uuid)

        local item = Instance.new("Frame")
        item.Name = "Item_"..uuid
        item.Parent = sf
        item.BackgroundColor3 = Color3.fromRGB(22,22,22)
        item.Size = UDim2.new(1,0,0,ROW_ITEM_H)
        item.LayoutOrder = i
        mkCorner(item, 4)
        mkPad(item, 6,6,0,0)

        local tog = Instance.new("TextButton")
        tog.Parent = item
        tog.BackgroundColor3 = Color3.fromRGB(10,10,10)
        tog.BorderSizePixel = 0
        tog.Size = UDim2.new(0, 34, 0, 22)
        tog.Position = UDim2.new(0, 0, 0.5, -11)
        tog.Font = Enum.Font.GothamBold
        tog.TextSize = 12
        tog.TextColor3 = Color3.fromRGB(235,235,235)
        mkCorner(tog, 4); mkStroke(tog, Color3.fromRGB(40,40,40), 1, 0.6)

        local nameLbl = Instance.new("TextLabel")
        nameLbl.Parent = item
        nameLbl.BackgroundTransparency = 1
        nameLbl.Position = UDim2.new(0, 40, 0, 0)
        nameLbl.Size = UDim2.new(1, -260, 1, 0)
        nameLbl.Font = Enum.Font.Gotham
        nameLbl.TextSize = 12
        nameLbl.TextXAlignment = Enum.TextXAlignment.Left
        nameLbl.TextColor3 = Color3.fromRGB(235,235,235)
        nameLbl.Text = name

        local hideDelay = (tostring(SS.mode or "A"):upper() == "D")
        nameLbl.Size = hideDelay and UDim2.new(1, -48, 1, 0) or UDim2.new(1, -260, 1, 0)

        local boxUnequip, boxEquip
        if not hideDelay then
        boxUnequip = Instance.new("TextBox")
        boxUnequip.Parent = item
        boxUnequip.BackgroundColor3 = Color3.fromRGB(10,10,10)
        boxUnequip.BorderSizePixel = 0
        boxUnequip.Size = UDim2.new(0, BOX_W, 0, 22)
        boxUnequip.Position = UDim2.new(1, -(BOX_W + BOX_GAP + BOX_W), 0.5, -11)
        boxUnequip.Font = Enum.Font.Gotham
        boxUnequip.TextSize = 12
        boxUnequip.TextColor3 = Color3.fromRGB(235,235,235)
        boxUnequip.TextXAlignment = Enum.TextXAlignment.Center
        boxUnequip.ClearTextOnFocus = false
        boxUnequip.Text = tostring(d.unequipAfterReady)
        mkCorner(boxUnequip, 4); mkStroke(boxUnequip, Color3.fromRGB(40,40,40), 1, 0.6)

        boxEquip = Instance.new("TextBox")
        boxEquip.Parent = item
        boxEquip.BackgroundColor3 = Color3.fromRGB(10,10,10)
        boxEquip.BorderSizePixel = 0
        boxEquip.Size = UDim2.new(0, BOX_W, 0, 22)
        boxEquip.Position = UDim2.new(1, -(BOX_W), 0.5, -11)
        boxEquip.Font = Enum.Font.Gotham
        boxEquip.TextSize = 12
        boxEquip.TextColor3 = Color3.fromRGB(235,235,235)
        boxEquip.TextXAlignment = Enum.TextXAlignment.Center
        boxEquip.ClearTextOnFocus = false
        boxEquip.Text = tostring(d.equipNext)
        mkCorner(boxEquip, 4); mkStroke(boxEquip, Color3.fromRGB(40,40,40), 1, 0.6)
        end

        local function renderToggle()
            local on = (SS.selected[uuid] == true)
            tog.Text = on and "ON" or "OFF"
            tog.TextColor3 = on and Color3.fromRGB(255,217,0) or Color3.fromRGB(235,235,235)
        end
        renderToggle()

        tog.MouseButton1Click:Connect(function()
            local wantOn = not (SS.selected[uuid] == true)

            if wantOn then
                SS.selected[uuid] = true
                ensureOrderUnique(uuid)
                ensureDelay(uuid)
                -- Keep Enable PnP as the only master. Selecting a pet must not turn it back on.
            else
                for k in pairs(SS.selected) do
                    if _normUUID(k) == uuid then
                        SS.selected[k] = nil
                    end
                end
                for i = #SS.order, 1, -1 do
                    if _normUUID(SS.order[i]) == uuid then
                        table.remove(SS.order, i)
                    end
                end
                for k in pairs(SS.delays) do
                    if _normUUID(k) == uuid then
                        SS.delays[k] = nil
                    end
                end
                if next(SS.selected) == nil then
                    SS.enabled = false
                    renderEnable()
                end
            end

            renderToggle()

            -- mirror + save
            G.swap_skill = SS
            _G.swap_skill = SS
            autoSave()

            applySwapSkillModule("ui_select")
        end)

        if boxUnequip then
        boxUnequip.FocusLost:Connect(function()
            local n = toNumFloat(boxUnequip.Text)
            if not n or n < 0 then
                boxUnequip.Text = tostring(d.unequipAfterReady)
                return
            end
            d.unequipAfterReady = n
            ensureOrderUnique(uuid)

            G.swap_skill = SS
            _G.swap_skill = SS
            autoSave()

            applySwapSkillModule("ui_delay")
        end)
        end

        if boxEquip then
        boxEquip.FocusLost:Connect(function()
            local n = toNumFloat(boxEquip.Text)
            if not n or n < 0 then
                boxEquip.Text = tostring(d.equipNext)
                return
            end
            d.equipNext = n
            ensureOrderUnique(uuid)

            G.swap_skill = SS
            _G.swap_skill = SS
            autoSave()

            applySwapSkillModule("ui_delay")
        end)
        end
    end

    refreshSwapList = function()
        local md = tostring(SS.mode or "A"):upper()
        if pickupHead then pickupHead.Visible = (md ~= "D") end
        if equipHead then equipHead.Visible = (md ~= "D") end

        clearRows()

        local q = norm(searchBox.Text)
        local entries = getSwapPetEntries()

        local shown = 0
        for _, e in ipairs(entries) do
            local nm = tostring(e.name or e.label or "")
            if q == "" or norm(nm):find(q,1,true) then
                shown += 1
                buildRow(shown, e)
            end
        end

        if shown == 0 then
            local t = Instance.new("TextLabel")
            t.Name = "EmptyHint"
            t.Parent = sf
            t.BackgroundTransparency = 1
            t.Size = UDim2.new(1,0,0,22)
            t.Font = Enum.Font.Gotham
            t.TextSize = 12
            t.TextXAlignment = Enum.TextXAlignment.Left
            t.TextColor3 = Color3.fromRGB(170,170,170)
            t.Text = (q ~= "") and "No match." or "No pets."
        end

        sf.Size = UDim2.new(1,0,0,calcListHeight(shown))
        if shown > VISIBLE_ROWS then
            sf.ScrollBarThickness = 6
            sf.ScrollBarImageTransparency = 0
        else
            sf.ScrollBarThickness = 0
            sf.ScrollBarImageTransparency = 1
            sf.CanvasPosition = Vector2.new(0,0)
        end

        task.defer(function()
            local h = layout.AbsoluteContentSize.Y
            local pad = sf:FindFirstChildOfClass("UIPadding")
            local top = pad and pad.PaddingTop.Offset or 0
            local bot = pad and pad.PaddingBottom.Offset or 0
            sf.CanvasSize = UDim2.new(0, 0, 0, h + top + bot)
        end)
    end

    searchBox:GetPropertyChangedSignal("Text"):Connect(function()
        task.defer(refreshSwapList)
    end)

    refreshSwapList()
end

