local function isAutoKGRunning()
    local loop = rawget(_G, "AutoKGLoop")
    if not loop then return false end
    if type(loop.IsRunning) == "function" then
        local ok, v = pcall(loop.IsRunning)
        if ok then return v == true end
    end
    return loop.running == true
end


    local function getEffectiveModeId()
        local Genv = (getgenv and getgenv()) or _G
        local m = Genv.GBXP_STAGE_MODE
            or (STATE and (STATE.stage_mode or STATE.GBXP_STAGE_MODE))
            or GBXP_STAGE_MODE
        if not m or m == "" then m = "auto" end
        return m
    end

    local function applyStageModeToEnv(newId)
        newId = tostring(newId or "auto")
        local Genv = (getgenv and getgenv()) or _G
        GBXP_STAGE_MODE = newId
        local setter = Genv.setGBXPStageMode or _G.setGBXPStageMode or setGBXPStageMode
        if type(setter) == "function" then
            setter(newId)
        end
        Genv.GBXP_STAGE_MODE = newId
        _G.GBXP_STAGE_MODE = newId
        if STATE then
            STATE.stage_mode = newId
            STATE.GBXP_STAGE_MODE = newId
        end
    end

    local function getModeOptionsDynamic()
    local A_AGE = tonumber(TAB_AGE_EQUIP_MIN.boost) or 0
    local B_AGE = tonumber(TAB_AGE_UNEQUIP_MIN.xp) or 40

    local C_AGE = tonumber(TAB_AGE_EQUIP_MIN.noos) or 40
