    local D_AGE = tonumber(TAB_AGE_UNEQUIP_MIN.seratusage) or 100
    local D_KG  = math.abs(tonumber(TAB_W_EQUIP_MIN.seratusage) or C_KG)

    return {
        { id = "auto", label = "AUTO  -  A→B→C→D otomatis" },

