local function applyModePreset(mode)
    mode = tostring(mode or "AUTO"):upper()


    local preset = MODE_PRESETS[mode]
    if type(preset) ~= "table" then
        return false
    end

    for tabKey, cfg in pairs(preset) do
        ensureTabDefaults(tabKey)

        if cfg.ageEquip ~= nil then
            TAB_AGE_EQUIP_MIN[tabKey] = tonumber(cfg.ageEquip) or 0
        end

        if cfg.ageUnequip ~= nil then
            TAB_AGE_UNEQUIP_MIN[tabKey] = tonumber(cfg.ageUnequip) or 0
        end

        if cfg.kgEquip ~= nil then
            TAB_W_EQUIP_MIN[tabKey] = tonumber(cfg.kgEquip) or 0
        end

        if cfg.kgUnequip ~= nil then
            TAB_W_UNEQUIP_MAX[tabKey] = tonumber(cfg.kgUnequip) or 999999
        end
    end

    return true
end

-- ==================================================
-- GBXP STRATEGY / PRIORITY MODE
-- GLOBAL = ratakan stage dulu baru lanjut stage berikutnya
-- FOCUS  = fokus isi sampai GBXP_MAX_EQUIP dulu
-- ==================================================
GBXP_PRIORITY_MODE = tostring(
    G.GBXP_PRIORITY_MODE
        or (STATE and (STATE.GBXP_PRIORITY_MODE or STATE.gbxp_priority_mode))
        or GBXP_PRIORITY_MODE
        or "GLOBAL"
):upper()

local function setGBXPPriorityMode(v)
    v = tostring(v or "GLOBAL"):upper()
    if v ~= "GLOBAL" and v ~= "FOCUS" then
        v = "GLOBAL"
    end

    GBXP_PRIORITY_MODE = v

    local Genv = (getgenv and getgenv()) or _G
    if type(Genv.setGBXPPriorityMode) == "function" and Genv.setGBXPPriorityMode ~= setGBXPPriorityMode then
        Genv.setGBXPPriorityMode(v)
    end

    Genv.GBXP_PRIORITY_MODE = v
    _G.GBXP_PRIORITY_MODE = v

    if STATE then
        STATE.GBXP_PRIORITY_MODE = v
        STATE.gbxp_priority_mode = v
    end

    Genv.setGBXPPriorityMode = setGBXPPriorityMode
    _G.setGBXPPriorityMode = setGBXPPriorityMode

    _G.__AUTOKG_DIRTY = true
end

local function getGBXPPriorityMode()
    local Genv = (getgenv and getgenv()) or _G
    local v = tostring(
        (Genv and Genv.GBXP_PRIORITY_MODE)
        or (STATE and (STATE.GBXP_PRIORITY_MODE or STATE.gbxp_priority_mode))
        or GBXP_PRIORITY_MODE
        or "GLOBAL"
    ):upper()
    if v ~= "GLOBAL" and v ~= "FOCUS" then
        v = "GLOBAL"
    end
    return v
end

local function getPriorityButtonText()
    local v = getGBXPPriorityMode()
    if v == "GLOBAL" then
        return "Global"
    else
        return "Focus"
    end
end

