        label = "AUTO - input age / kg mengikuti preset mode",
    },
}

local function getInputMode()
    local mode = tostring(STATE.gbxpInputMode or "manual"):lower()
    if mode ~= "auto" then mode = "manual" end
    return mode
end

local function setInputMode(mode)
    mode = tostring(mode or "manual"):lower()
    if mode ~= "auto" then mode = "manual" end

    STATE.gbxpInputMode = mode

    if mode == "auto" then
        local modeId = getEffectiveModeId()
        applyModePreset(modeId)
        refreshModeInputsUI()
    end

    autoSave()
    _G.__AUTOKG_DIRTY = true
end
