            text    = running and "⚡ RUNNING." or "⚡ START KG",
            kind    = "normal",
            running = running,
            order   = 1,

            onClick = function()
                -- ✅ user klik START = buka manual-stop lock
                _G.__AUTOKG_MANUAL_STOP = false
                -- ✅ kalau sebelumnya ada autostart inflight (PSReconnect/qtp), lepas
                _G.__AUTOKG_AUTOSTART_INFLIGHT = false

                -- ✅ jangan double-start kalau sudah running
                if isAutoKGRunning() then
                    _G.__AUTOKG_DIRTY = true
                    refreshFooter()
                    return
                end

                local modeId = getEffectiveModeId()

                -- simpan mode + reset stage biar konsisten
                applyStageModeToEnv(modeId)

                -- start loop
                local loop = rawget(_G, "AutoKGLoop")
                if loop and type(loop.Start) == "function" then
                    pcall(function()
                        loop.Start(modeId)
                    end)
                end

                autoSave()
                _G.__AUTOKG_DIRTY = true
                refreshFooter()
            end,

            onReady = function(btn)
                -- biar kerasa “electric”
                if isAutoKGRunning() then
                    btn.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
                    btn.TextColor3       = Color3.fromRGB(255, 217, 0)
                else
                    btn.BackgroundColor3 = COLOR_PANEL
                    btn.TextColor3       = COLOR_WHITE
                end
            end,
        },

        -- STOP
        {
            text  = "STOP",
            kind  = "normal",
            order = 2,

            onClick = function()
                -- ✅ user klik STOP = kunci supaya autostart (PSReconnect/qtp/main) gak nyalain lagi
                _G.__AUTOKG_MANUAL_STOP = true

                local loop = rawget(_G, "AutoKGLoop")
                if loop and type(loop.Stop) == "function" then
                    pcall(function()
                        loop.Stop("manual")
                    end)
                end

                autoSave()
                _G.__AUTOKG_DIRTY = true
                refreshFooter()
            end,
        },

    })
end

