    ----------------------------------------------------------------
    -- helper autosave: pakai ui:SaveState() dari main.lua
    ----------------------------------------------------------------
    local function autoSave()
        if ui and type(ui.SaveState) == "function" then
            task.defer(function()
                local ok, err = pcall(function()
                    ui:SaveState()
                end)
                if not ok then
                    warn("[Misc/Gift] Gagal ui:SaveState():", err)
                end
            end)
        else
            warn("[Misc/Gift] ui.SaveState() tidak tersedia, perubahan TIDAK di-persist.")
        end
    end

    local function cleanSelectedMap(selectedMap)
        local out = {}
        if type(selectedMap) ~= "table" then
            return out
        end
        for k, v in pairs(selectedMap) do
            if v == true then
                out[tostring(k)] = true
            elseif type(k) == "number" and (type(v) == "string" or type(v) == "number") then
                local s = tostring(v)
                if s ~= "" then out[s] = true end
            elseif type(k) == "number" and type(v) == "table" then
                local kk = v.key or v.name or v.id
                if kk then out[tostring(kk)] = true end
            elseif type(k) == "string" and type(v) == "table" then
                out[tostring(k)] = true
            end
        end
        return out
    end
    
    
   local Players = game:GetService("Players")
   local LocalPlayer = Players.LocalPlayer

    --------------------------------------------------
    -- DATA SOURCE: TARGET DROPDOWN (PAKAI PLAYERS)
