local function getTargetItems()
    local items = {}

    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer then
            table.insert(items, {
                key      = plr.Name,     -- dipakai dropdown
                name     = plr.Name,     -- tampil di UI
                userId   = plr.UserId,   -- disimpan ke config
            })
        end
    end

    return items
end

    local function normalizeDropdownItems(list)
        local out = {}
        if type(list) ~= "table" then return out end
        for _, it in ipairs(list) do
            if type(it) == "string" then
                out[#out + 1] = { key = it, name = it }
            elseif type(it) == "table" then
                local k = it.key or it.name or it.id
                local n = it.name or it.key or it.id
                if k and n then
                    out[#out + 1] = { key = tostring(k), name = tostring(n) }
                end
            end
        end
        return out
    end

    local function buildTokenRobuxTab(ui, parent, autoSaveFn)
        local function getAutoBuyDev()
            local env = (getgenv and getgenv()) or _G
            return env.AutoBuyDevModule or _G.AutoBuyDevModule
        end

        local AutoBuyDev = getAutoBuyDev()
        local DevItems = {}
        local DevGiftItems = {}

        local PAY_MODE_ITEMS = {
            { key = "token", name = "Token" },
            { key = "robux", name = "Robux" },
        }

        local function refreshDevLists()
            if not AutoBuyDev then return end
            DevItems = normalizeDropdownItems(
                (type(AutoBuyDev.GetAllItems) == "function") and AutoBuyDev.GetAllItems() or {}
            )
            DevGiftItems = normalizeDropdownItems(
                (type(AutoBuyDev.GetGiftItems) == "function") and AutoBuyDev.GetGiftItems() or {}
            )
        end

        if not AutoBuyDev then
            ui:CreateRowLabel(parent, "AutoBuyDev module not loaded. Reload script.")
            return
        end

        local function normalizeDevSelectedKey(sel)
            if type(sel) == "string" and sel ~= "" then return sel end
            if type(sel) == "table" then
                for k, v in pairs(sel) do
                    if v == true then return tostring(k) end
                end
                for _, k in ipairs(sel) do
                    if k and tostring(k) ~= "" then return tostring(k) end
                end
            end
            return ""
        end

        do
            local key = normalizeDevSelectedKey(AUTO_BUY_DEV_SELECTED)
            if key == "" then
                local merged = {}
                for k, v in pairs(cleanSelectedMap(AUTO_BUY_DEV_TOKEN_SELECTED or {})) do merged[k] = v end
                for k, v in pairs(cleanSelectedMap(AUTO_BUY_DEV_ROBUX_SELECTED or {})) do merged[k] = v end
                key = normalizeDevSelectedKey(merged)
            end
            AUTO_BUY_DEV_SELECTED = key
        end
        do
            AUTO_BUY_DEV_GIFT_SELECTED = normalizeDevSelectedKey(AUTO_BUY_DEV_GIFT_SELECTED)
        end
        if AUTO_BUY_DEV_PAY_MODE ~= "token" and AUTO_BUY_DEV_PAY_MODE ~= "robux" then
            AUTO_BUY_DEV_PAY_MODE = "token"
        end
        AUTO_BUY_DEV_PURCHASE_MODE = tostring(AUTO_BUY_DEV_PURCHASE_MODE or "self"):lower()
        if AUTO_BUY_DEV_PURCHASE_MODE ~= "gift" then
            AUTO_BUY_DEV_PURCHASE_MODE = "self"
        end

        local PURCHASE_MODE_ITEMS = {
            { key = "self", name = "Buy for Self" },
            { key = "gift", name = "Gift" },
        }

        local function syncAutoBuyDev()
            if AutoBuyDev and type(AutoBuyDev.SyncFromGlobals) == "function" then
                pcall(AutoBuyDev.SyncFromGlobals)
            end
        end

        local rowPay, apiPay
        local rowItem, apiItem
        local rowGiftItem, apiGiftItem
        local rowGiftTarget, apiGiftTarget

        local function getSelfDevItems()
            if AutoBuyDev and type(AutoBuyDev.GetSelfItems) == "function" then
                return normalizeDropdownItems(AutoBuyDev.GetSelfItems())
            end
            local out = {}
            for _, it in ipairs(DevItems) do
                local nm = tostring(it.name or "")
                if nm:upper():find("%[GIFT%]", 1, true) == nil then
                    out[#out + 1] = it
                end
            end
        return out
    end

        local function getOnlineGiftTargetItems()
            local items = {}
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr ~= LocalPlayer then
                    items[#items + 1] = {
                        key = tostring(plr.UserId),
                        name = string.format("@%s (%s)", plr.Name, tostring(plr.UserId)),
                    }
                end
            end
            table.sort(items, function(a, b)
                return tostring(a.name):lower() < tostring(b.name):lower()
            end)
            return items
        end

        local function applyPurchaseModeUI(mode)
            local isGift = (tostring(mode or ""):lower() == "gift")
            if rowPay then rowPay.Visible = not isGift end
            if rowItem then rowItem.Visible = not isGift end
            if rowGiftItem then rowGiftItem.Visible = isGift end
            if rowGiftTarget then rowGiftTarget.Visible = isGift end
            if apiPay and apiPay.refreshLabel then pcall(apiPay.refreshLabel) end
            if apiItem and apiItem.refreshLabel then pcall(apiItem.refreshLabel) end
            if apiGiftItem and apiGiftItem.refreshLabel then pcall(apiGiftItem.refreshLabel) end
            if apiGiftTarget and apiGiftTarget.refreshLabel then pcall(apiGiftTarget.refreshLabel) end
        end

        ui:CreateRowDropdown(parent, {
            label       = "Purchase Mode",
            placeholder = "Self or Gift...",
            mode        = "single",
            getItems    = function() return PURCHASE_MODE_ITEMS end,
            initial     = AUTO_BUY_DEV_PURCHASE_MODE,
            onChanged   = function(_, selectedKey)
                AUTO_BUY_DEV_PURCHASE_MODE = (selectedKey == "gift") and "gift" or "self"
                if AutoBuyDev and type(AutoBuyDev.SetPurchaseMode) == "function" then
                    AutoBuyDev.SetPurchaseMode(AUTO_BUY_DEV_PURCHASE_MODE)
                end
                applyPurchaseModeUI(AUTO_BUY_DEV_PURCHASE_MODE)
                syncAutoBuyDev()
                autoSaveFn()
            end,
        })

        rowPay, apiPay = ui:CreateRowDropdown(parent, {
            label       = "Pay With",
            placeholder = "Token or Robux...",
            mode        = "single",
            getItems    = function() return PAY_MODE_ITEMS end,
            initial     = AUTO_BUY_DEV_PAY_MODE,
            onChanged   = function(_, selectedKey)
                AUTO_BUY_DEV_PAY_MODE = (selectedKey == "robux") and "robux" or "token"
                syncAutoBuyDev()
                autoSaveFn()
            end,
        })

        rowItem, apiItem = ui:CreateRowDropdown(parent, {
            label       = "Select Item",
            placeholder = "Select item (self)...",
            mode        = "single",
            getItems    = function()
                if #DevItems == 0 then refreshDevLists() end
                return getSelfDevItems()
            end,
            initial     = (AUTO_BUY_DEV_SELECTED ~= "") and AUTO_BUY_DEV_SELECTED or nil,
            onChanged   = function(_, selectedKey)
                AUTO_BUY_DEV_SELECTED = tostring(selectedKey or "")
                syncAutoBuyDev()
                autoSaveFn()
            end,
        })

        rowGiftItem, apiGiftItem = ui:CreateRowDropdown(parent, {
            label       = "Select Gift Item",
            placeholder = "Select gift item...",
            mode        = "single",
            getItems    = function()
                if #DevGiftItems == 0 then refreshDevLists() end
                return DevGiftItems
            end,
            initial     = (AUTO_BUY_DEV_GIFT_SELECTED ~= "") and AUTO_BUY_DEV_GIFT_SELECTED or nil,
            onChanged   = function(_, selectedKey)
                AUTO_BUY_DEV_GIFT_SELECTED = tostring(selectedKey or "")
                syncAutoBuyDev()
                autoSaveFn()
            end,
        })

        rowGiftTarget, apiGiftTarget = ui:CreateRowDropdown(parent, {
            label       = "Gift Target (online)",
            placeholder = "Pick one player in server...",
            mode        = "single",
            getItems    = function()
                return getOnlineGiftTargetItems()
            end,
            initial     = nil,
            onChanged   = function(_, selectedKey)
                local uid = tonumber(selectedKey)
                if uid and uid > 0 and AutoBuyDev and type(AutoBuyDev.SetGiftTargetUserId) == "function" then
                    AutoBuyDev.SetGiftTargetUserId(math.floor(uid))
                elseif AutoBuyDev and type(AutoBuyDev.SetGiftTargetUserId) == "function" then
                    AutoBuyDev.SetGiftTargetUserId(nil)
                end
                syncAutoBuyDev()
            end,
        })

        applyPurchaseModeUI(AUTO_BUY_DEV_PURCHASE_MODE)

        ui:CreateRowToggle(parent, "Scan (Marketplace)", false, function(isOn)
            if isOn ~= true then return end
            if type(AutoBuyDev.IsLoading) == "function" and AutoBuyDev.IsLoading() then
                return
            end
            task.spawn(function()
                pcall(function()
                    if type(AutoBuyDev.Rescan) == "function" then
                        AutoBuyDev.Rescan()
                    else
                        AutoBuyDev.RefreshListsFromCache()
                    end
                    refreshDevLists()
                end)
            end)
        end, nil, nil, 1)

        local BUY_STATUS_COLORS = {
            ok   = Color3.fromRGB(130, 255, 175),
            err  = Color3.fromRGB(255, 110, 110),
            warn = Color3.fromRGB(255, 200, 90),
            info = Color3.fromRGB(145, 150, 160),
        }

        local _, buyStatusLbl = ui:CreateRowLabel(parent, "Status: Ready", nil, nil, "info")

        local function setBuyStatus(text, tone)
            if not buyStatusLbl or not buyStatusLbl:IsA("TextLabel") then return end
            buyStatusLbl.Text = tostring(text or "")
            buyStatusLbl.TextColor3 = BUY_STATUS_COLORS[tone] or BUY_STATUS_COLORS.info
        end

        ui:CreateRowToggle(parent, "Buy Now", false, function(isOn)
            if isOn ~= true then return end
            syncAutoBuyDev()
            setBuyStatus("Processing purchase...", "info")
            task.spawn(function()
                local ok, msg, tone = false, "Buy module not loaded", "err"
                if type(AutoBuyDev.BuyOnce) == "function" then
                    local pOk, a, b, c = pcall(AutoBuyDev.BuyOnce)
                    if pOk then
                        ok, msg, tone = a, b, c
                    else
                        ok, msg, tone = false, "Error: " .. tostring(a), "err"
                    end
                end
                setBuyStatus(msg or (ok and "Success" or "Failed"), tone or (ok and "ok" or "err"))
            end)
        end, nil, nil, 1)

        syncAutoBuyDev()
        task.spawn(function()
            pcall(function()
                if type(AutoBuyDev.RefreshListsFromCache) == "function" then
                    AutoBuyDev.RefreshListsFromCache()
                elseif type(AutoBuyDev.RefreshAllLists) == "function" then
                    AutoBuyDev.RefreshAllLists()
                end
                refreshDevLists()
            end)
        end)
    end

    local function buildPurchaseHistorySection(ui, parent)
        local function getAutoBuyDev()
        local env = (getgenv and getgenv()) or _G
            return env.AutoBuyDevModule or _G.AutoBuyDevModule
        end

        local AutoBuyDev = getAutoBuyDev()
        if not AutoBuyDev then
            ui:CreateRowLabel(parent, "AutoBuyDev module not loaded. Reload script.")
            return
        end

        local summaryRow, summaryLbl = ui:CreateRowLabel(
            parent,
            "Loading transaction history...",
            "DataService.Transactions Â· newest first",
            nil,
            "info"
        )
        local summarySub = nil
        if summaryRow then
            for _, ch in ipairs(summaryRow:GetChildren()) do
                if ch:IsA("TextLabel") and ch ~= summaryLbl then
                    summarySub = ch
                    break
                end
            end
        end

        local scroll = Instance.new("ScrollingFrame")
        scroll.Name = "PurchaseHistoryScroll"
        scroll.BackgroundTransparency = 1
        scroll.BorderSizePixel = 0
        scroll.ScrollBarThickness = 4
        scroll.Size = UDim2.new(1, 0, 0, 200)
        scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
        scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
        scroll.LayoutOrder = (#parent:GetChildren() + 1)
        scroll.Parent = parent

        local listLayout = Instance.new("UIListLayout")
        listLayout.SortOrder = Enum.SortOrder.LayoutOrder
        listLayout.Padding = UDim.new(0, 4)
        listLayout.Parent = scroll

        local function clearHistoryRows()
            for _, ch in ipairs(scroll:GetChildren()) do
                if ch:IsA("GuiObject") and not ch:IsA("UIListLayout") then
                    ch:Destroy()
                end
            end
        end

        local function addHistoryRow(text, order, styleKey)
            local row = Instance.new("TextLabel")
            row.Name = "HistRow"
            row.BackgroundColor3 = Color3.fromRGB(22, 22, 26)
            row.BackgroundTransparency = 0.25
            row.Size = UDim2.new(1, -6, 0, 56)
            row.Font = Enum.Font.Gotham
            row.TextSize = 11
            row.TextWrapped = true
            row.TextXAlignment = Enum.TextXAlignment.Left
            row.TextYAlignment = Enum.TextYAlignment.Top
            row.Text = text
            row.LayoutOrder = order
            row.Parent = scroll

            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(0, 6)
            corner.Parent = row

            local pad = Instance.new("UIPadding")
            pad.PaddingLeft = UDim.new(0, 6)
            pad.PaddingRight = UDim.new(0, 6)
            pad.PaddingTop = UDim.new(0, 4)
            pad.PaddingBottom = UDim.new(0, 4)
            pad.Parent = row

            if ui.ApplyRowLabelStyle then
                ui:ApplyRowLabelStyle(row, styleKey or "default")
            end
        end

        local function refreshHistory()
            clearHistoryRows()
            if type(AutoBuyDev.GetPurchaseHistory) ~= "function" then
                if summaryLbl then
                    summaryLbl.Text = "Purchase history API not available."
                end
                addHistoryRow("Reload script with the latest AutoBuyDev module.", 1, "warn")
                return
            end
            local rows, total, spendStats = {}, 0, nil
            local okHist, a, b, c = pcall(AutoBuyDev.GetPurchaseHistory, 30)
            if okHist then
                rows = type(a) == "table" and a or {}
                total = tonumber(b) or 0
                spendStats = type(c) == "table" and c or nil
            else
                if summaryLbl then
                    summaryLbl.Text = "History error: " .. tostring(a)
                end
                addHistoryRow("History load failed: " .. tostring(a), 1, "err")
                return
            end
            if summaryLbl then
                summaryLbl.Text = string.format(
                    "Transactions: %d total Â· showing %d",
                    total,
                    #rows
                )
                local spendLine = ""
                if type(AutoBuyDev.FormatDoneSpendSummary) == "function" and spendStats then
                    spendLine = AutoBuyDev.FormatDoneSpendSummary(spendStats)
                elseif spendStats then
                    spendLine = string.format(
                        "Done spend: %s tokens Â· R$ %s robux",
                        tostring(spendStats.doneToken or 0),
                        tostring(spendStats.doneRobux or 0)
                    )
                end
                if summarySub then
                    summarySub.Text = (spendLine ~= "") and spendLine
                        or "Done spend: 0 tokens Â· R$ 0 robux (finished purchases)"
                end
                if summaryRow and summaryRow:IsA("GuiObject") then
                    summaryRow.Size = UDim2.new(1, 0, 0, spendLine ~= "" and 48 or 34)
                end
            end
            if #rows == 0 then
                addHistoryRow("No entries in DataService.Transactions yet.", 1, "info")
                return
            end
            for i, ent in ipairs(rows) do
                local tx = ent.raw or {}
                local pid = ent.productId or tonumber(tx.ProductId)
                local pay = ent.payMethod or "?"
                local robux = tonumber(ent.robuxSpent) or tonumber(tx.RobuxSpent) or 0
                local receipt = tostring(ent.receiptId or tx.ReceiptId or "")
                if #receipt > 12 then
                    receipt = receipt:sub(1, 8) .. "â€¦"
                end
                if receipt == "" then receipt = "â€”" end
                local txt = string.format(
                    "#%s Â· %s\nid %s Â· %s (R$ %s) Â· %s\n%s Â· receipt %s",
                    tostring(ent.index or i),
                    tostring(ent.productName or "?"),
                    tostring(pid or "?"),
                    pay,
                    tostring(robux),
                    tostring(ent.status or "?"),
                    tostring(ent.timeStr or "?"),
                    receipt
                )
                local tone = (ent.status == "Done") and "ok" or "warn"
                addHistoryRow(txt, i, tone)
            end
        end

        ui:CreateRowToggle(parent, "Refresh History", false, function(isOn)
            if isOn ~= true then return end
            task.spawn(function()
                pcall(refreshHistory)
            end)
        end, nil, nil, 1)

        task.defer(function()
            pcall(refreshHistory)
        end)
    end


