ui:RegisterSubTab("config", "config", "Config", function()
    ui:ClearSubContent()

    local bodyCfg, setCfgExpanded = ui:CreateSection("Config", true)
    local statusRow, statusTitle, statusDetail = ui:CreateRowLabel(bodyCfg, "Status", "Idle", 1)

    local function setCfgStatus(text, detail)
        if statusTitle then statusTitle.Text = tostring(text or "Idle") end
        if statusDetail then statusDetail.Text = tostring(detail or "") end
    end

    local function getStateMod()
        local G0 = (getgenv and getgenv()) or _G
        local st = rawget(_G, "State") or rawget(G0, "State")
        if type(st) == "table" and type(st.ExportJson) == "function" then
            return st
        end
        local m = rawget(_G, "MAIN") or rawget(G0, "MAIN")
        if type(m) == "table" and type(m.ExportJson) == "function" then
            return m
        end
        local Loaded = rawget(_G, "Loaded") or rawget(G0, "Loaded")
        if type(Loaded) == "table" and type(Loaded.state) == "table" then
            return Loaded.state
        end
        return st or m
    end

    local function copyText(text)
        if type(setclipboard) == "function" then
            local ok = pcall(setclipboard, text)
            if ok then return true end
        end
        if type(toclipboard) == "function" then
            local ok = pcall(toclipboard, text)
            if ok then return true end
        end
        if type(set_clipboard) == "function" then
            local ok = pcall(set_clipboard, text)
            if ok then return true end
        end
        return false
    end

    local function readClipboard()
        if type(getclipboard) == "function" then
            local ok, v = pcall(getclipboard)
            if ok and type(v) == "string" and v ~= "" then
                return v
            end
        end
        if type(get_clipboard) == "function" then
            local ok, v = pcall(get_clipboard)
            if ok and type(v) == "string" and v ~= "" then
                return v
            end
        end
        return nil
    end

    local function makeActionBtn(parent, text, order, onClick)
        local row = Instance.new("Frame")
        row.Name = "RowBtn_" .. tostring(text)
        row.BackgroundTransparency = 1
        row.Size = UDim2.new(1, 0, 0, 28)
        row.LayoutOrder = order or (#parent:GetChildren() + 1)
        row.Parent = parent

        local btn = Instance.new("TextButton")
        btn.Name = "Btn"
        btn.AutoButtonColor = false
        btn.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
        btn.Size = UDim2.new(1, 0, 1, 0)
        btn.Font = Enum.Font.GothamBold
        btn.TextSize = 12
        btn.TextColor3 = Color3.fromRGB(240, 240, 240)
        btn.Text = tostring(text)
        btn.BorderSizePixel = 0
        btn.Parent = row
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, 8)
        c.Parent = btn
        local s = Instance.new("UIStroke")
        s.Color = Color3.fromRGB(80, 80, 80)
        s.Thickness = 1
        s.Transparency = 0.35
        s.Parent = btn
        btn.MouseButton1Click:Connect(function()
            if type(onClick) == "function" then
                pcall(onClick)
            end
        end)
        return row, btn
    end

    makeActionBtn(bodyCfg, "Copy", 2, function()
        local SM = getStateMod()
        if type(SM) ~= "table" or type(SM.ExportJson) ~= "function" then
            setCfgStatus("Failed", "state module")
            return
        end
        local json, err, meta = SM.ExportJson()
        if type(json) ~= "string" or json == "" then
            setCfgStatus("Failed", tostring(err or "encode"))
            return
        end
        local clip = copyText(json)
        local chars = (type(meta) == "table" and tonumber(meta.chars)) or #json
        if clip then
            setCfgStatus("Copied", "chars=" .. tostring(chars))
        else
            setCfgStatus("Failed", "clipboard")
        end
    end)

    local pasteWrap = Instance.new("Frame")
    pasteWrap.Name = "ConfigPaste"
    pasteWrap.BackgroundTransparency = 1
    pasteWrap.Size = UDim2.new(1, 0, 0, 78)
    pasteWrap.LayoutOrder = 3
    pasteWrap.Parent = bodyCfg

    local pasteBox = Instance.new("TextBox")
    pasteBox.Name = "Input"
    pasteBox.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
    pasteBox.Size = UDim2.new(1, 0, 1, 0)
    pasteBox.Font = Enum.Font.Gotham
    pasteBox.TextSize = 11
    pasteBox.TextColor3 = Color3.fromRGB(220, 220, 220)
    pasteBox.PlaceholderColor3 = Color3.fromRGB(110, 110, 110)
    pasteBox.PlaceholderText = "Paste save config"
    pasteBox.Text = ""
    pasteBox.ClearTextOnFocus = false
    pasteBox.MultiLine = true
    pasteBox.TextWrapped = true
    pasteBox.TextXAlignment = Enum.TextXAlignment.Left
    pasteBox.TextYAlignment = Enum.TextYAlignment.Top
    pasteBox.ClipsDescendants = true
    pasteBox.Parent = pasteWrap
    pcall(function()
        pasteBox.TextTruncate = Enum.TextTruncate.None
    end)
    local boxPad = Instance.new("UIPadding")
    boxPad.PaddingLeft = UDim.new(0, 8)
    boxPad.PaddingRight = UDim.new(0, 8)
    boxPad.PaddingTop = UDim.new(0, 6)
    boxPad.PaddingBottom = UDim.new(0, 6)
    boxPad.Parent = pasteBox
    local boxCorner = Instance.new("UICorner")
    boxCorner.CornerRadius = UDim.new(0, 8)
    boxCorner.Parent = pasteBox
    local boxStroke = Instance.new("UIStroke")
    boxStroke.Color = Color3.fromRGB(70, 70, 70)
    boxStroke.Thickness = 1
    boxStroke.Transparency = 0.35
    boxStroke.Parent = pasteBox

    makeActionBtn(bodyCfg, "Apply", 4, function()
        local SM = getStateMod()
        if type(SM) ~= "table" or type(SM.ImportJson) ~= "function" then
            setCfgStatus("Failed", "state module")
            return
        end
        local raw = tostring(pasteBox.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if raw == "" then
            raw = tostring(readClipboard() or ""):gsub("^%s+", ""):gsub("%s+$", "")
        end
        if raw == "" then
            setCfgStatus("Failed", "paste kosong")
            return
        end
        setCfgStatus("Checking", "chars=" .. tostring(#raw))
        local ok, reason = SM.ImportJson(raw)
        if ok then
            pasteBox.Text = ""
            setCfgStatus("Applied", "chars=" .. tostring(#raw) .. " · " .. tostring(reason))
            pcall(function()
                if ui and type(ui.SaveState) == "function" then
                    ui:SaveState()
                end
            end)
            _G.__auto_hatch_DIRTY = true
            _G.__AUTOKG_DIRTY = true
            pcall(function()
                if ui and type(ui.RefreshActiveSubTab) == "function" then
                    ui:RefreshActiveSubTab()
                end
            end)
        else
            local msg = tostring(reason or "import")
            if reason == "refused_empty_overwrite" then
                msg = "ditolak: config paste kosong / hapus list. Cek Copy chars dulu."
            end
            setCfgStatus("Failed", msg .. " · chars=" .. tostring(#raw))
        end
    end)

    if type(ui.CreateRowLabel) == "function" then
        ui:CreateRowLabel(bodyCfg, "Copy → paste di akun lain → Apply. Cek chars Copy = chars Apply.", nil, 5)
    end

    if setCfgExpanded then setCfgExpanded(true) end
end, 1)


