local function syncAutoBuy()
    local env = (type(G) == "table" and G) or (getgenv and getgenv()) or _G

    env.AUTO_BUY_SEED_ENABLED = (AUTO_BUY_SEED_ENABLED == true)
    env.AUTO_BUY_EGG_ENABLED = (AUTO_BUY_EGG_ENABLED == true)
    env.AUTO_BUY_GEAR_ENABLED = (AUTO_BUY_GEAR_ENABLED == true)
    env.AUTO_BUY_EVENT_ENABLED = (AUTO_BUY_EVENT_ENABLED == true)
    env.AUTO_BUY_TRAVELING_MERCHANT_ENABLED = (AUTO_BUY_TRAVELING_MERCHANT_ENABLED == true)
    env.AUTO_BUY_GARDEN_COIN_ENABLED = (AUTO_BUY_GARDEN_COIN_ENABLED == true)
    env.AUTO_BUY_SEASON_PASS_ENABLED = (AUTO_BUY_SEASON_PASS_ENABLED == true)
    env.AUTO_CLAIM_SEASON_PASS_ENABLED = (AUTO_CLAIM_SEASON_PASS_ENABLED == true)
    env.AUTO_BUY_COSMETIC_ENABLED = (AUTO_BUY_COSMETIC_ENABLED == true)

    env.SEED_SELECTED = SEED_SELECTED or {}
    env.EGG_SELECTED = EGG_SELECTED or {}
    env.GEAR_SELECTED = GEAR_SELECTED or {}
    env.EVENT_SELECTED = EVENT_SELECTED or {}
    env.EVENT_SHOPS_SELECTED = EVENT_SHOPS_SELECTED or {}
    env.TRAVELING_MERCHANT_SELECTED = TRAVELING_MERCHANT_SELECTED or {}
    env.GARDEN_COIN_SELECTED = GARDEN_COIN_SELECTED or {}
    env.GARDEN_COIN_BUY_QTY = math.max(1, math.min(20, math.floor(tonumber(GARDEN_COIN_BUY_QTY) or 1)))
    env.SEASON_PASS_SELECTED = SEASON_PASS_SELECTED or {}
    env.COSMETIC_SELECTED = COSMETIC_SELECTED or {}

    _G.AUTO_BUY_GARDEN_COIN_ENABLED = env.AUTO_BUY_GARDEN_COIN_ENABLED
    _G.GARDEN_COIN_SELECTED = env.GARDEN_COIN_SELECTED
    _G.GARDEN_COIN_BUY_QTY = env.GARDEN_COIN_BUY_QTY

    if AutoBuy and type(AutoBuy.SyncFromGlobals) == "function" then
        pcall(AutoBuy.SyncFromGlobals)
    end

