local function eventShopColorFromBuy(buy, shopName)
    if buy and type(buy.GetEventShopColor) == "function" then
        local ok, col = pcall(buy.GetEventShopColor, shopName)
        if ok and typeof(col) == "Color3" then
            return col
        end
    end
    return Color3.fromRGB(255, 196, 70)
end

local function inferEventShopsFromItems(buy)
    local shops = EVENT_SHOPS_SELECTED or {}
    for _, on in pairs(shops) do
        if on then return shops end
    end
    shops = {}
    if not buy or type(buy.GetEventShopDropdownItems) ~= "function" then
        return shops
    end
    local okShops, shopItems = pcall(buy.GetEventShopDropdownItems)
    if not okShops or type(shopItems) ~= "table" then
        return shops
    end
    local selected = EVENT_SELECTED or {}
    for _, rec in ipairs(shopItems) do
        local shopName = tostring((type(rec) == "table" and (rec.key or rec.name)) or rec)
        if shopName ~= "" and type(buy.GetEventItemKeysForShop) == "function" then
            local okKeys, keys = pcall(buy.GetEventItemKeysForShop, shopName)
            if okKeys and type(keys) == "table" then
                for _, itemKey in ipairs(keys) do
                    if selected[itemKey] == true then
                        shops[shopName] = true
                        break
                    end
                end
            end
        end
    end
    EVENT_SHOPS_SELECTED = shops
    return shops
end

