local function pruneEventSelectedToShops(buy)
    local keep = {}
    for shopName, on in pairs(EVENT_SHOPS_SELECTED or {}) do
        if on == true and buy and type(buy.GetEventItemKeysForShop) == "function" then
            local okKeys, keys = pcall(buy.GetEventItemKeysForShop, shopName)
            if okKeys and type(keys) == "table" then
                for _, itemKey in ipairs(keys) do
                    keep[tostring(itemKey)] = true
                end
            end
        end
    end
    local nextSel = {}
    for k, on in pairs(EVENT_SELECTED or {}) do
        if on == true and keep[tostring(k)] then
            nextSel[tostring(k)] = true
        end
    end
    EVENT_SELECTED = nextSel
end

local function rebuildEventItemDropdowns()
    for _, ch in ipairs(eventItemHolder:GetChildren()) do
        if not ch:IsA("UIListLayout") then
            ch:Destroy()
        end
    end
    local buy = getAutoBuy()
    inferEventShopsFromItems(buy)
    local shops = {}
    for shopName, on in pairs(EVENT_SHOPS_SELECTED or {}) do
        if on == true then
            shops[#shops + 1] = tostring(shopName)
        end
    end
    table.sort(shops, function(a, b)
        return string.lower(a) < string.lower(b)
    end)
    if #shops == 0 then
        ui:CreateRowLabel(eventItemHolder, "Pilih event shop dulu", nil, 1, "info")
        return
    end
    for i, shopName in ipairs(shops) do
        local col = eventShopColorFromBuy(buy, shopName)
        local row = ui:CreateRowDropdown(eventItemHolder, {
            label       = shopName,
            placeholder = "Select items...",
    mode        = "multi",
            labelStyle  = { color = col, font = Enum.Font.GothamMedium, size = 12 },
            getItems    = function()
                local mod = getAutoBuy()
                if mod and type(mod.GetEventDropdownItemsForShop) == "function" then
                    local ok, items = pcall(mod.GetEventDropdownItemsForShop, shopName)
                    if ok and type(items) == "table" then
                        return normalizeDropdownItems(items)
                    end
                end
                return {}
            end,
    initial     = EVENT_SELECTED,
    onChanged   = function(_, selectedMap)
                local shopSel = cleanSelectedMap(selectedMap)
                local nextSel = {}
                for k, on in pairs(EVENT_SELECTED or {}) do
                    if on == true then
                        nextSel[k] = true
                    end
                end
                local shopKeys = {}
                local mod = getAutoBuy()
                if mod and type(mod.GetEventItemKeysForShop) == "function" then
                    local okKeys, keys = pcall(mod.GetEventItemKeysForShop, shopName)
                    if okKeys and type(keys) == "table" then
                        for _, itemKey in ipairs(keys) do
                            shopKeys[tostring(itemKey)] = true
                        end
                    end
                end
                for k in pairs(shopKeys) do
                    nextSel[k] = nil
                end
                for k, on in pairs(shopSel) do
                    if on == true then
                        nextSel[k] = true
                    end
                end
                EVENT_SELECTED = nextSel
        syncAutoBuy()
        autoSave()
    end,
})
        if row then
            row.LayoutOrder = i
        end
    end
end

