--------------------------------------------------
-- Helper: bangun satu section Gift (row 1 / 2 / 3)
-- FIX:
-- 1) Target dropdown pakai KEY stabil:
--    - uid key  : "12345"
--    - name key : "name:PlayerName" (fallback kalau uid tidak diketahui / offline)
-- 2) Selected target TETAP tampil walau offline (placeholder).
-- 3) Legacy migrate:
--    - targets["Name"]=true -> jadi uid kalau online, kalau offline -> name:Name
--    - targets[uid]={userId=uid,name=...} tetap
-- 4) Auto-migrasi name:Name -> uid saat Name online.
--------------------------------------------------
local function buildGiftSection(body, suffix, title, PetItems)
    suffix = suffix or ""  -- "", "B", "C"

    local keyEnabled     = "enabled"     .. suffix
    local keyTargets     = "targets"     .. suffix
    local keyMinKG       = "minKG"       .. suffix
    local keyMinAge      = "minAge"      .. suffix
    local keyPetType     = "petType"     .. suffix
    local keyAutoUnfav   = "autoUnfav"   .. suffix
    local keyMut         = "mut"         .. suffix
    local keyPrioTicket  = "prioTicket"  .. suffix

    -- default
    giftCfg[keyEnabled]     = giftCfg[keyEnabled]     or false
    giftCfg[keyTargets]     = giftCfg[keyTargets]     or {}
    giftCfg[keyMinKG]       = giftCfg[keyMinKG]       or 0
    giftCfg[keyMinAge]      = giftCfg[keyMinAge]      or 0
    giftCfg[keyPetType]     = giftCfg[keyPetType]     or {}
    giftCfg[keyAutoUnfav]   = giftCfg[keyAutoUnfav]   or false
    giftCfg[keyMut]         = giftCfg[keyMut]         or {}
    giftCfg[keyPrioTicket]  = giftCfg[keyPrioTicket]  or false

    ------------------------------------------------------
    -- helpers target-key
    ------------------------------------------------------
    local function _nameKey(name)
        return "name:" .. tostring(name or "")
    end

    local function _isNameKey(k)
        k = tostring(k or "")
        return k:sub(1, 5) == "name:"
    end

    local function _nameFromKey(k)
        k = tostring(k or "")
        if k:sub(1, 5) == "name:" then
            return k:sub(6)
        end
        return k
    end

    ------------------------------------------------------
    -- âœ… MIGRASI TARGET LEGACY (name-based) -> uid-based
    -- + keep fallback name-key kalau offline / uid unknown
    -- + auto convert name:Bob -> uid saat Bob online
    ------------------------------------------------------
    local function _migrateTargetsToStableKeys()
        local src = giftCfg[keyTargets]
        if type(src) ~= "table" then
            giftCfg[keyTargets] = {}
            return
        end

        local dst = {}
        local changed = false

        for k, v in pairs(src) do
            local kStr = tostring(k)

            -- CASE 1: schema table
            if type(v) == "table" then
                local uid = tonumber(v.userId) or tonumber(kStr)
                local nm  = tostring(v.name or "")

                if uid then
                    dst[tostring(uid)] = {
                        userId = uid,
                        name   = (nm ~= "" and nm) or ("UserId " .. tostring(uid)),
                    }
                else
                    -- tidak ada uid -> simpan by name
                    local name = (nm ~= "" and nm) or (_isNameKey(kStr) and _nameFromKey(kStr) or kStr)
                    local plr = Players:FindFirstChild(name)
                    if plr then
                        dst[tostring(plr.UserId)] = { userId = plr.UserId, name = plr.Name }
                        changed = true
                    else
                        dst[_nameKey(name)] = { userId = nil, name = name }
                        changed = true
                    end
                end

            -- CASE 2: legacy bool map (targets["Name"]=true)
            elseif v == true then
                local name = _isNameKey(kStr) and _nameFromKey(kStr) or kStr
                local plr = Players:FindFirstChild(name)
                if plr then
                    dst[tostring(plr.UserId)] = { userId = plr.UserId, name = plr.Name }
                    changed = true
                else
                    dst[_nameKey(name)] = { userId = nil, name = name }
                    changed = true
                end

            -- CASE 3: unknown junk -> ignore
            end
        end

        giftCfg[keyTargets] = dst
        if changed then
            autoSave()
        end
    end

    _migrateTargetsToStableKeys()

    ------------------------------------------------------
    -- âœ… ITEMS: online + offline(selected) placeholder
    -- KEY dropdown = uidStr OR name:Name
    ------------------------------------------------------
    local function _getTargetItems()
        local items = {}
        local seenUid = {}   -- [uidStr]=true
        local seenName = {}  -- [lowerName]=true

        -- A) online players
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= Players.LocalPlayer then
                local uidStr = tostring(plr.UserId)
                seenUid[uidStr] = true
                seenName[string.lower(plr.Name)] = true
                items[#items+1] = { key = uidStr, name = plr.Name }
            end
        end

        -- B) saved targets: add placeholders
        local src = giftCfg[keyTargets]
        if type(src) == "table" then
            for k, info in pairs(src) do
                local keyStr = tostring(k)

                -- uid key
                local uid = tonumber(keyStr)
                if uid then
                    if not seenUid[keyStr] then
                        local nm = (type(info) == "table" and info.name) or ("UserId " .. keyStr)
                        items[#items+1] = {
                            key  = keyStr,
                            name = tostring(nm) .. " (offline)",
                        }
                    end

                -- name key
                elseif _isNameKey(keyStr) then
                    local nm = (type(info) == "table" and info.name) or _nameFromKey(keyStr)
                    local low = string.lower(nm or "")
                    -- kalau nama tsb sudah online, online-entry sudah ada, jadi skip
                    if low ~= "" and not seenName[low] then
                        items[#items+1] = {
                            key  = keyStr,
                            name = tostring(nm) .. " (offline)",
                        }
                    end
                end
            end
        end

        table.sort(items, function(a, b)
            return tostring(a.name):lower() < tostring(b.name):lower()
        end)

        return items
    end

    ------------------------------------------------------
    -- âœ… TARGET DROPDOWN (fixed)
    ------------------------------------------------------
    ui:CreateRowDropdown(body, {
        label       = "Target",
        placeholder = "Pilih target gift...",
        mode        = "multi",

        getItems = function()
            -- optional: refresh migrate name->uid setiap buka dropdown
            -- (biar kalau target join mendadak, langsung convert)
            _migrateTargetsToStableKeys()
            return _getTargetItems()
        end,

        -- initial pakai key yg tersimpan (uidStr atau name:Name)
        initial = (function()
            local map = {}
            local src = giftCfg[keyTargets]
            if type(src) == "table" then
                for k, _ in pairs(src) do
                    map[tostring(k)] = true
                end
            end
            return map
        end)(),

        onChanged = function(_, selectedMap)
            selectedMap = selectedMap or {}
            local dst = {}

            for keyStr, on in pairs(selectedMap) do
                if on then
                    keyStr = tostring(keyStr)

                    local uid = tonumber(keyStr)
                    if uid then
                        -- uid key
                        local plr  = Players:GetPlayerByUserId(uid)
                        local name = plr and plr.Name or nil

                        -- fallback: pakai nama lama kalau ada
                        local old = giftCfg[keyTargets] and giftCfg[keyTargets][keyStr]
                        if not name and type(old) == "table" and old.name then
                            name = old.name
                        end
                        if not name then
                            name = "UserId " .. keyStr
                        end

                        dst[keyStr] = { userId = uid, name = name }

                    elseif _isNameKey(keyStr) then
                        -- name key
                        local name = _nameFromKey(keyStr)
                        local plr = Players:FindFirstChild(name)

                        -- kalau sekarang online, auto-convert ke uid
                        if plr then
                            local uidStr = tostring(plr.UserId)
                            dst[uidStr] = { userId = plr.UserId, name = plr.Name }
                        else
