-- SECTION: Auto Update Server
----------------------------------------------------------------
local function ensureState()
    G.STATE = (type(G.STATE) == "table") and G.STATE or {}
    G.STATE.rejoin = (type(G.STATE.rejoin) == "table") and G.STATE.rejoin or {}
    return G.STATE.rejoin
end

local function clampMinute(n)
    n = tonumber(n) or 60
    n = math.floor(n)
    if n < 1 then n = 1 end
    if n > 300 then n = 300 end
    return n
end

local function syncUpdateNewServerModule()
    local UNS = G.UpdateNewServer or _G.UpdateNewServer
    if not UNS then return end
    pcall(function()
        if type(UNS.Apply) == "function" then
            UNS:Apply(UPDATE_NEW_SERVER_ENABLED == true, clampMinute(UPDATE_NEW_SERVER_MINUTE))
        else
            if type(UNS.SetEnabled) == "function" then
                UNS:SetEnabled(UPDATE_NEW_SERVER_ENABLED == true)
            end
            if type(UNS.SetMinute) == "function" then
                UNS:SetMinute(clampMinute(UPDATE_NEW_SERVER_MINUTE))
            end
        end
    end)
end

-- source awal: GLOBAL (sudah di-restore state.lua)
UPDATE_NEW_SERVER_ENABLED = (UPDATE_NEW_SERVER_ENABLED == true)
UPDATE_NEW_SERVER_MINUTE  = clampMinute(UPDATE_NEW_SERVER_MINUTE)

do
    local rs = ensureState()
    rs.update_new_server = UPDATE_NEW_SERVER_ENABLED
    rs.update_new_server_minute = UPDATE_NEW_SERVER_MINUTE
end

local body2 = createSection("Auto Update Server", false)

local _, jobIdLbl = ui:CreateRowLabel(body2, "Job ID: " .. tostring(game.JobId or "-"), nil, nil, "info")
local _, timerLbl = ui:CreateRowLabel(body2, "Next update: --:--", nil, nil, "accent")

local function getServerNow()
    local ok, v = pcall(function()
        return workspace:GetServerTimeNow()
    end)
    if ok and type(v) == "number" then
        return v
    end
    return os.time()
end

local _, serverClockLbl = ui:CreateRowLabel(
    body2,
    "Server Time Now: " .. os.date("!%H:%M:%S", math.floor(getServerNow())),
    nil,
    nil,
    "info"
)

task.spawn(function()
    while body2 and body2.Parent do
        pcall(function()
            if jobIdLbl and jobIdLbl.Parent then
                jobIdLbl.Text = "Job ID: " .. tostring(game.JobId or "-")
            end

            if serverClockLbl and serverClockLbl.Parent then
                serverClockLbl.Text = "Server Time Now: " .. os.date("!%H:%M:%S", math.floor(getServerNow()))
            end

            local remainText = "Next update: --:--"
            local UNS = G.UpdateNewServer or _G.UpdateNewServer
            if UNS and type(UNS.GetInfo) == "function" then
                local ok, info = pcall(function()
                    return UNS:GetInfo()
                end)
                if ok and type(info) == "table" then
                    if info.enabled ~= true then
                        remainText = "Next update: (off)"
                    elseif type(info.remainFmt) == "string" then
                        remainText = "Next update: " .. info.remainFmt
                    else
                        local r = math.max(0, math.floor(tonumber(info.remainSec) or 0))
                        remainText = string.format(
                            "Next update: %02d:%02d",
                            math.floor(r / 60),
                            r % 60
                        )
                    end
                end
            end

            if timerLbl and timerLbl.Parent then
                timerLbl.Text = remainText
            end
        end)
        task.wait(1)
    end
end)

