ui:CreateRowInput(body2, "Max Check Interval ( Sec )", tostring(AUTO_BOOST_DELAY or 20), function(text)
    text = tostring(text or ""):gsub("%s+", "")
    if text == "" then
        return -- biarin, jangan spam warn saat user hapus lalu ketik lagi
    end

    local v = tonumber(text)
    if not v or v <= 0 then
        warn("[AutoBoost] Delay Boost tidak valid: " .. tostring(text))
        return
    end

    -- optional: bulatkan biar delay rapi & konsisten
    v = math.floor(v + 0.5)

    AUTO_BOOST_DELAY = v
    local G = (getgenv and getgenv()) or _G
    G.AUTO_BOOST_DELAY = v

    -- âœ… prioritas: setDelay (update tanpa restart)
    local BoostModule = getBoostModule()
    if BoostModule then
        pcall(function()
            if type(BoostModule.setDelay) == "function" then
                BoostModule.setDelay(v)         -- kalau fungsi biasa (.)
            elseif type(BoostModule.SetDelay) == "function" then
                BoostModule.SetDelay(v)
            elseif type(BoostModule.setDelay) == "function" then
                BoostModule:setDelay(v)         -- kalau method (:)
            elseif type(BoostModule.SetDelay) == "function" then
                BoostModule:SetDelay(v)
            else
                -- fallback property
                BoostModule.delay = v
                BoostModule.DELAY = v
            end
        end)
    end

    -- âœ… autosave agak ditunda biar gak spam writefile pas ngetik
    if ui and type(ui._boostDelaySaveDebounce) ~= "thread" then
        -- nothing
    end
    task.defer(function()
        -- debounce sederhana: tunggu sebentar, kalau nilainya masih sama baru save
        local cur = v
        task.wait(0.35)
        if AUTO_BOOST_DELAY == cur then
            autoSave()
        end
    end)
end)



        local function getBoostModule()
            local G = (getgenv and getgenv()) or _G
            return G.AutoBoost or _G.AutoBoost
                or G.AutoKGBoost or _G.AutoKGBoost
                or G.auto_hatchBoost or _G.auto_hatchBoost
        end

        local function setAutoBoostEnabled(on)
            on = (on == true)
            AUTO_BOOST_ENABLED = on
            STATE.autoBoostEnabled = on
            local G = (getgenv and getgenv()) or _G
            G.AUTO_BOOST_ENABLED = on
            _G.AUTO_BOOST_ENABLED = on

            local bm = getBoostModule()
            if type(bm) ~= "table" then
                return
            end
            if type(bm.SetEnabled) == "function" then
                pcall(bm.SetEnabled, bm, on)
            elseif on and type(bm.start) == "function" then
                pcall(bm.start, bm)
            elseif (not on) and type(bm.stop) == "function" then
                pcall(bm.stop, bm)
            end
        end

