-- Auto Feed (body3) â€” fresh
-- Source of truth: getgenv().AUTO_FEED
-- ============================================================
do
    local G = (getgenv and getgenv()) or _G
    if type(G.AUTO_FEED) ~= "table" then
        G.AUTO_FEED = { enabled = false, hunger_under = 200000, pets = {}, fruits = {} }
    end
    local cfg = G.AUTO_FEED
    cfg.pets   = type(cfg.pets) == "table" and cfg.pets or {}
    cfg.fruits = type(cfg.fruits) == "table" and cfg.fruits or {}
    cfg.hunger_under = tonumber(cfg.hunger_under) or 200000
    cfg.enabled = (cfg.enabled == true)

    local function getFeed()
        return G.AutoFeed or _G.AutoFeed
    end

    local function uuidOnly(map)
        local out = {}
        for k, v in pairs(map or {}) do
            if v == true or v == 1 or v == "true" then
                local s = tostring(k)
                local core = s:match("{?([0-9a-fA-F%-]+)}?")
                if core and #core >= 30 and core:find("%-") then
                    out["{" .. core .. "}"] = true
                end
            end
        end
        return out
    end

    local function boolMap(map)
        local out = {}
        for k, v in pairs(map or {}) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            end
        end
        return out
    end

    local function pushFeed()
        local Feed = getFeed()
        if Feed and type(Feed.ApplyConfig) == "function" then
            pcall(Feed.ApplyConfig, Feed)
        end
    end

    local function saveFeed()
        autoSave()
    end

    local function getFeedPetItems()
        if PetListView and type(PetListView.buildEntriesForTab) == "function" then
            local ok, list = pcall(function()
                return PetListView.buildEntriesForTab("", {}) or {}
            end)
            if ok and type(list) == "table" then
                return list
            end
        end
        if PetListView and type(PetListView.buildPetItems) == "function" then
            local ok, list = pcall(function()
                return PetListView.buildPetItems() or {}
            end)
            if ok and type(list) == "table" then
                return list
            end
        end
        return {}
    end

    -- feed.lua filter buah pakai nama ItemName (bukan UUID tool)
    local function getFeedFruitItems()
        local items = {}
        local seen = {}
        local fruitList = {}

        pcall(function()
            if PetListView and type(PetListView.listFruitItems) == "function" then
                fruitList = PetListView.listFruitItems() or {}
            end
        end)

        for _, it in ipairs(fruitList) do
            if type(it) == "table" then
                local fname = tostring(it.fruit or it.key or "")
                if fname ~= "" and not seen[fname] then
                    seen[fname] = true
                    table.insert(items, {
                        key  = fname,
                        name = tostring(it.name or fname),
                    })
                end
            end
        end

        table.sort(items, function(a, b)
            return tostring(a.name) < tostring(b.name)
        end)

        return items
    end

ui:CreateRowDropdown(body3, {
    label       = "Select Pet To Feed",
    placeholder = "Select Pet...",
    mode        = "multi",
        getItems    = getFeedPetItems,
        initial     = cfg.pets,
    onChanged   = function(_, selectedMap)
            cfg.pets = uuidOnly(selectedMap)
            pushFeed()
            saveFeed()
    end,
})

ui:CreateRowDropdown(body3, {
    label       = "Select Fruit",
        placeholder = "All fruit",
    mode        = "multi",
        getItems    = getFeedFruitItems,
        initial     = cfg.fruits,
    onChanged   = function(_, selectedMap)
            cfg.fruits = boolMap(selectedMap)
            pushFeed()
            saveFeed()
    end,
})

    ui:CreateRowInput(body3, "If Hunger Under", tostring(cfg.hunger_under), function(text)
    text = tostring(text or ""):gsub("%s+", "")
    if text == "" then return end
    local v = tonumber(text)
        if not v then return end
    v = math.floor(v + 0.5)
        if v < 1 then v = 1 elseif v > 200000 then v = 200000 end
        cfg.hunger_under = v
        local Feed = getFeed()
        if Feed and Feed.setHungerUnder then pcall(Feed.setHungerUnder, Feed, v) end
    task.defer(function()
        task.wait(0.35)
            if cfg.hunger_under == v then saveFeed() end
    end)
end)

    local _, setFeedToggle = ui:CreateRowToggle(body3, "Enable Auto Feed", cfg.enabled == true, function(isOn)
        cfg.enabled = (isOn == true)
        pushFeed()
        saveFeed()
    end)

    task.defer(function()
        pcall(function()
            if setFeedToggle then setFeedToggle(cfg.enabled == true, true) end
            pushFeed()
        end)
    end)
end
