-- Auto Collect Fruit (SOURCE OF TRUTH: MAIN.misc.auto_collect)
-- rules     = ARRAY of KEEP/COLLECT rows (type / variant / mutation / kg)
-- ruleMode  = "keep" | "take"
-- fruits/variants/mutations/blacklist/kg = save lama; dimigrate ke rules kalau rules kosong
------------------------------------------------------------

local G = (getgenv and getgenv()) or _G

local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)
if type(MAIN) ~= "table" then
    MAIN = {}
    _G.MAIN = MAIN
    if G then G.MAIN = MAIN end
end

MAIN.misc = MAIN.misc or {}
MAIN.misc.auto_collect = MAIN.misc.auto_collect or {}

local AC_STATE = MAIN.misc.auto_collect

AC_STATE.enabled   = (AC_STATE.enabled == true)
AC_STATE.delay = tonumber(AC_STATE.delay) or 0.2
AC_STATE.fruits    = type(AC_STATE.fruits) == "table" and AC_STATE.fruits or {}
AC_STATE.variants  = type(AC_STATE.variants) == "table" and AC_STATE.variants or {}
AC_STATE.mutations = type(AC_STATE.mutations) == "table" and AC_STATE.mutations or {}
AC_STATE.mutations_blacklist = type(AC_STATE.mutations_blacklist) == "table" and AC_STATE.mutations_blacklist or {}
AC_STATE.kg        = tonumber(AC_STATE.kg) or 0
AC_STATE.kgMode    = tostring(AC_STATE.kgMode or "above")
AC_STATE.rules     = type(AC_STATE.rules) == "table" and AC_STATE.rules or {}
AC_STATE.ruleMode  = tostring(AC_STATE.ruleMode or "keep")

local function mapToArray(map)
    local arr = {}

    if type(map) == "table" then
        for k, v in pairs(map) do
            if v == true then
                arr[#arr + 1] = tostring(k)
            end
        end
    end

    table.sort(arr)
    return arr
end

local function arrayToMap(arr)
    local m = {}

    if type(arr) == "table" then
        for _, v in ipairs(arr) do
            if v ~= nil and tostring(v) ~= "" then
                m[tostring(v)] = true
            end
        end
    end

    return m
end

local function parseKgRule(txt)
    txt = tostring(txt or ""):gsub("%s+", "")

    if txt == "" then
        return 0, "above"
    end

    local n = tonumber(txt)
    if not n then
        return 0, "above"
    end

    if n < 0 then
        return math.abs(n), "below"
    end

    return n, "above"
end

local function kgInputText()
    local kg = tonumber(AC_STATE.kg) or 0
    local mode = tostring(AC_STATE.kgMode or "above")

    if kg <= 0 then
        return "0"
    end

    if mode == "below" then
        return "-" .. tostring(kg)
    end

    return tostring(kg)
end

local function __call(obj, fn, ...)
    if obj and type(obj[fn]) == "function" then
        local ok, err = pcall(obj[fn], obj, ...)
        if _G.AUTO_COLLECT_DEBUG == true and not ok then
            warn("[AC UI] call fail:", fn, err)
        end
        return ok
    end
    return false
end

local function syncAutoCollectModule()
    local GG = (getgenv and getgenv()) or _G
    local ac = GG.AutoCollectFruit or GG.CollectFruitModule
        or rawget(_G, "AutoCollectFruit") or rawget(_G, "CollectFruitModule")

    GG.AUTO_COLLECT_FRUIT_ENABLED = (AC_STATE.enabled == true)

    GG.AUTO_COLLECT_FRUITS_SELECTED =
        AUTO_COLLECT_FRUITS_SELECTED or {}

    GG.AUTO_COLLECT_VARIANTS_SELECTED =
        AUTO_COLLECT_VARIANTS_SELECTED or {}

    GG.AUTO_COLLECT_MUTATIONS_SELECTED =
        AUTO_COLLECT_MUTATIONS_SELECTED or {}

    GG.AUTO_COLLECT_MUTATIONS_BLACKLIST =
        AUTO_COLLECT_MUTATIONS_BLACKLIST or {}

    GG.AUTO_COLLECT_KG = tonumber(AC_STATE.kg) or 0
    GG.AUTO_COLLECT_KG_MODE = tostring(AC_STATE.kgMode or "above")
    GG.AUTO_COLLECT_DELAY =
    tonumber(AC_STATE.delay) or 0
    GG.AUTO_COLLECT_RULES = AC_STATE.rules or {}
    GG.AUTO_COLLECT_RULE_MODE = tostring(AC_STATE.ruleMode or "keep")


    if not ac then
        if _G.AUTO_COLLECT_DEBUG == true then
            warn("[AC UI] module not found: AutoCollectFruit/CollectFruitModule")
        end
        return
    end

    __call(ac, "SetSelected", GG.AUTO_COLLECT_FRUITS_SELECTED)
    __call(ac, "SetFruits", GG.AUTO_COLLECT_FRUITS_SELECTED)
    __call(ac, "setFruits", GG.AUTO_COLLECT_FRUITS_SELECTED)

    __call(ac, "SetVariants", GG.AUTO_COLLECT_VARIANTS_SELECTED)
    __call(ac, "setVariants", GG.AUTO_COLLECT_VARIANTS_SELECTED)

    __call(ac, "SetMutations", GG.AUTO_COLLECT_MUTATIONS_SELECTED)
    __call(ac, "setMutations", GG.AUTO_COLLECT_MUTATIONS_SELECTED)

    __call(ac, "SetMutationBlacklist", GG.AUTO_COLLECT_MUTATIONS_BLACKLIST)
    __call(ac, "setMutationBlacklist", GG.AUTO_COLLECT_MUTATIONS_BLACKLIST)

    __call(ac, "SetKgFilter", GG.AUTO_COLLECT_KG, GG.AUTO_COLLECT_KG_MODE)
    __call(ac, "setKgFilter", GG.AUTO_COLLECT_KG, GG.AUTO_COLLECT_KG_MODE)
    __call(ac, "SetRules", GG.AUTO_COLLECT_RULES)
    __call(ac, "setRules", GG.AUTO_COLLECT_RULES)
    __call(ac, "SetRuleMode", GG.AUTO_COLLECT_RULE_MODE)
    __call(ac, "setRuleMode", GG.AUTO_COLLECT_RULE_MODE)

    __call(ac, "SetEnabled", (AC_STATE.enabled == true))
    __call(ac, "setEnabled", (AC_STATE.enabled == true))
    
__call(ac, "SetDelay", GG.AUTO_COLLECT_DELAY)
__call(ac, "setDelay", GG.AUTO_COLLECT_DELAY)

    if AC_STATE.enabled == true then
        __call(ac, "Start")
        __call(ac, "start")
    else
        __call(ac, "Stop")
        __call(ac, "stop")
    end
end

