local function acMutationItems()
    local items = {
        { key = "__NO_MUTATION__", name = "[NO MUTATION]" },
    }
    local seen = { ["__NO_MUTATION__"] = true, ["No Mutation"] = true }

    local function addItem(it)
        if type(it) ~= "table" then
            return
        end
        local key = tostring(it.key or it.name or "")
        if key == "" or seen[key] then
            return
        end
        seen[key] = true
        items[#items + 1] = it
    end

    if PetListView and type(PetListView.listFruitMutations) == "function" then
        local list = PetListView.listFruitMutations() or {}
        for _, it in ipairs(list) do
            addItem(it)
        end
    end

    return items
end

-- Save lama (fruit/variant/whitelist/blacklist/kg) → rule rows kalau rules masih kosong.
do
    local function arrHas(arr)
        if type(arr) ~= "table" then
            return false
        end
        for _, v in ipairs(arr) do
            if v ~= nil and tostring(v) ~= "" then
                return true
            end
        end
        return false
    end
    do
        local CR0 = rawget(G, "CollectRules") or rawget(_G, "CollectRules")
        if type(CR0) == "table" and type(CR0.AsArray) == "function" then
            AC_STATE.rules = CR0.AsArray(AC_STATE.rules)
        end
        if (type(AC_STATE.rules) ~= "table" or #AC_STATE.rules == 0)
            and type(G.AUTO_COLLECT_RULES) == "table" then
            AC_STATE.rules = G.AUTO_COLLECT_RULES
            if type(CR0) == "table" and type(CR0.AsArray) == "function" then
                AC_STATE.rules = CR0.AsArray(AC_STATE.rules)
            end
        end
    end
    if type(AC_STATE.rules) ~= "table" or #AC_STATE.rules == 0 then
        local migrated = {}
        local function oneMutRule(action, mutName)
            migrated[#migrated + 1] = {
                action = action,
                fruits = {},
                variants = {},
                mutations = { tostring(mutName) },
                mutMode = "all",
                kg = 0,
                kgMode = "above",
            }
        end
        if arrHas(AC_STATE.mutations_blacklist) then
            for _, mutName in ipairs(AC_STATE.mutations_blacklist) do
                if mutName ~= nil and tostring(mutName) ~= "" then
                    oneMutRule("keep", mutName)
                end
            end
        end
        if arrHas(AC_STATE.mutations) then
            for _, mutName in ipairs(AC_STATE.mutations) do
                if mutName ~= nil and tostring(mutName) ~= "" then
                    migrated[#migrated + 1] = {
                        action = "take",
                        fruits = arrHas(AC_STATE.fruits) and AC_STATE.fruits or {},
                        variants = arrHas(AC_STATE.variants) and AC_STATE.variants or {},
                        mutations = { tostring(mutName) },
                        mutMode = "all",
                        kg = tonumber(AC_STATE.kg) or 0,
                        kgMode = tostring(AC_STATE.kgMode or "above"),
                    }
                end
            end
        elseif arrHas(AC_STATE.fruits) or arrHas(AC_STATE.variants) or (tonumber(AC_STATE.kg) or 0) > 0 then
            migrated[#migrated + 1] = {
                action = "take",
                fruits = AC_STATE.fruits or {},
                variants = AC_STATE.variants or {},
                mutations = {},
                mutMode = "exact",
                kg = tonumber(AC_STATE.kg) or 0,
                kgMode = tostring(AC_STATE.kgMode or "above"),
            }
        end
        if #migrated > 0 then
            AC_STATE.rules = migrated
        end
    end
end

