local function asfKgText()
    local kg = tonumber(ASF_STATE.kg) or 0
    local mode = tostring(ASF_STATE.kgMode or "above")
    if kg <= 0 then
        return "0"
    end
    if mode == "below" then
        return "-" .. tostring(kg)
    end
    return tostring(kg)
end

local function syncAutoSellFruitModule()
    local ASF = _G.AutoSellFruit or G.AutoSellFruit
    if type(ASF) ~= "table" then
        return
    end
    if type(ASF.SetFruits) == "function" then
        pcall(ASF.SetFruits, AUTO_SELL_FRUIT_FRUITS_SELECTED)
    end
    if type(ASF.SetMutations) == "function" then
        pcall(ASF.SetMutations, AUTO_SELL_FRUIT_MUTATIONS_SELECTED)
    end
    if type(ASF.SetKgFilter) == "function" then
        pcall(ASF.SetKgFilter, AUTO_SELL_FRUIT_KG, AUTO_SELL_FRUIT_KG_MODE)
    end
    if type(ASF.SetDelay) == "function" then
        pcall(ASF.SetDelay, AUTO_SELL_FRUIT_DELAY)
    end
    if type(ASF.SetBackpackTotal) == "function" then
        pcall(ASF.SetBackpackTotal, AUTO_SELL_FRUIT_BACKPACK_TOTAL)
    end
    if type(ASF.SetEnabled) == "function" then
        pcall(ASF.SetEnabled, AUTO_SELL_FRUIT_MAX_ENABLED == true)
    elseif type(ASF.SyncFromState) == "function" then
        pcall(ASF.SyncFromState)
    end
end

