-- HELPERS
-------------------------------------------------------------
local Players = game:GetService("Players")
local LP = Players.LocalPlayer


local function getHRP()
    local char = LP.Character
    return char and char:FindFirstChild("HumanoidRootPart")
end

local function round1(n)
    return math.floor((tonumber(n) or 0) * 10 + 0.5) / 10
end

local function makePosKey(pos)
    return string.format("%.1f,%.1f,%.1f", round1(pos.X), round1(pos.Y), round1(pos.Z))
end

local function makePosLabel(pos)
    return string.format(
        "X %.1f | Y %.1f | Z %.1f",
        round1(pos.X),
        round1(pos.Y),
        round1(pos.Z)
    )
end

local function getFarmCF(farm)
    if not farm then return nil end

    -- kalau ternyata Model
    if farm:IsA("Model") then
        return farm:GetPivot()
    end

    -- cari part yang stabil di dalam farm
    local preferredNames = {
        "Center_Point",
        "CenterPoint",
        "Spawn_Point",
        "SpawnPoint",
        "FarmSpawn",
        "Base",
        "Baseplate",
        "Ground",
    }

    for _, name in ipairs(preferredNames) do
        local obj = farm:FindFirstChild(name, true)
        if obj and obj:IsA("BasePart") then
            return obj.CFrame
        end
    end

    -- fallback: ambil rata-rata semua BasePart
    local sum = Vector3.zero
    local count = 0

    for _, obj in ipairs(farm:GetDescendants()) do
        if obj:IsA("BasePart") then
            sum += obj.Position
            count += 1
        end
    end

    if count > 0 then
        return CFrame.new(sum / count)
    end

    return nil
end

local function getMyFarm()
    local farmRoot = workspace:FindFirstChild("Farm")
    if not farmRoot then return nil end

    for _, farm in ipairs(farmRoot:GetChildren()) do
        local important = farm:FindFirstChild("Important")
        local data = important and important:FindFirstChild("Data")
        local owner = data and data:FindFirstChild("Owner")

        if owner then
            local v = tostring(owner.Value or "")
            if v == LP.Name or v == tostring(LP.UserId) then
                return farm
            end
        end
    end

    return nil
end

local function cfToTable(cf)
    return { cf:GetComponents() }
end

local function cleanPositionList()
    local seen = {}
    local out = {}

    for _, p in ipairs(AUTO_SPRINKLER_POSITIONS) do
        if type(p) == "table" then
            local key = tostring(p.key or "")

            if key ~= "" and not seen[key] then
                seen[key] = true
                table.insert(out, p)
            end
        end
    end

    AUTO_SPRINKLER_POSITIONS = out
    G.AUTO_SPRINKLER_POSITIONS = AUTO_SPRINKLER_POSITIONS
end

local MAX_SPRINKLER_POSITIONS = 5

local function prunePositionSelected()
    local exists = {}

    for _, p in ipairs(AUTO_SPRINKLER_POSITIONS) do
        if type(p) == "table" and p.key then
            exists[tostring(p.key)] = true
        end
    end

    for key in pairs(AUTO_SPRINKLER_POSITION_SELECTED) do
        if not exists[tostring(key)] then
            AUTO_SPRINKLER_POSITION_SELECTED[key] = nil
        end
    end

    G.AUTO_SPRINKLER_POSITION_SELECTED = AUTO_SPRINKLER_POSITION_SELECTED
end


local function buildPositionItems()
    cleanPositionList()
    prunePositionSelected()

    local items = {}

    for i, p in ipairs(AUTO_SPRINKLER_POSITIONS) do
        local label

        if p.rx and p.ry and p.rz then
            label = string.format(
                "%d. Farm Offset | X %.1f | Y %.1f | Z %.1f",
                i,
                round1(p.rx),
                round1(p.ry),
                round1(p.rz)
            )
        else
            local pos = Vector3.new(p.x or 0, p.y or 0, p.z or 0)
            label = tostring(i) .. ". OLD | " .. makePosLabel(pos)
        end

        table.insert(items, {
            key = tostring(p.key or ""),
            name = label,
        })
    end

    return items
end



local function saveCurrentCharacterPosition()
    local hrp = getHRP()
    if not hrp then
        warn("[AutoSprinklerUI] HRP tidak ditemukan")
        return false
    end

    local farm = getMyFarm()
    if not farm then
        warn("[AutoSprinklerUI] Farm sendiri tidak ditemukan")
        return false
    end

    local farmCF = getFarmCF(farm)
if not farmCF then
    warn("[AutoSprinklerUI] Farm CF tidak ditemukan")
    return false
end

local relCF = farmCF:ToObjectSpace(hrp.CFrame)
    local relPos = relCF.Position
    local key = makePosKey(relPos)

for _, p in ipairs(AUTO_SPRINKLER_POSITIONS) do
    if p.key == key then
        return true
    end
end

    while #AUTO_SPRINKLER_POSITIONS >= MAX_SPRINKLER_POSITIONS do
        local old = table.remove(AUTO_SPRINKLER_POSITIONS, 1)
        if old and old.key then
            AUTO_SPRINKLER_POSITION_SELECTED[old.key] = nil
        end
    end

    table.insert(AUTO_SPRINKLER_POSITIONS, {
        key = key,

        -- relative position dari farm sendiri
        rx = round1(relPos.X),
        ry = round1(relPos.Y),
        rz = round1(relPos.Z),

        -- full relative CFrame biar arah/rotasi aman
        rel = cfToTable(relCF),
    })



    G.AUTO_SPRINKLER_POSITIONS = AUTO_SPRINKLER_POSITIONS
    G.AUTO_SPRINKLER_POSITION_SELECTED = AUTO_SPRINKLER_POSITION_SELECTED

    return true
end

