local function buildOtherPlayerItems()
    local items = {}
    local seen = {}

    -- 1) player online
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP then

            local key = tostring(plr.UserId)

            seen[key] = true

            table.insert(items, {
                key = key,
                name = plr.Name,
            })
        end
    end

    -- 2) player dari saved target / positions
    local function addOffline(uid)
        uid = tostring(uid or "")

        if uid == "" or seen[uid] then
            return
        end

        seen[uid] = true

        local display = "User "..uid.." (Offline)"

        pcall(function()
            local ok, name =
                pcall(function()
                    return Players:GetNameFromUserIdAsync(
                        tonumber(uid)
                    )
                end)

            if ok and name then
                display = tostring(name) .. " (Offline)"
            end
        end)

        table.insert(items, {
            key = uid,
            name = display,
        })
    end

    -- dari target selected
    for uid in pairs(AUTO_SPRINKLER_OTHER_TARGET or {}) do
        addOffline(uid)
    end

    -- dari saved positions
    for _, p in ipairs(AUTO_SPRINKLER_OTHER_POSITIONS or {}) do
        if p and p.targetUserId then
            addOffline(p.targetUserId)
        end
    end

    table.sort(items, function(a, b)
        return tostring(a.name):lower()
            < tostring(b.name):lower()
    end)

    return items
end

local function cleanOtherPositionList()
    local seen = {}
    local out = {}

    for _, p in ipairs(AUTO_SPRINKLER_OTHER_POSITIONS) do
        if type(p) == "table" then
            local key = tostring(p.key or "")

            if key ~= "" and not seen[key] then
                seen[key] = true
                table.insert(out, p)
            end
        end
    end

    AUTO_SPRINKLER_OTHER_POSITIONS = out
    G.AUTO_SPRINKLER_OTHER_POSITIONS =
        AUTO_SPRINKLER_OTHER_POSITIONS
end

local function pruneOtherPositionSelected()
    local exists = {}

    for _, p in ipairs(AUTO_SPRINKLER_OTHER_POSITIONS) do
        if type(p) == "table" and p.key then
            exists[tostring(p.key)] = true
        end
    end

    for key in pairs(AUTO_SPRINKLER_OTHER_POSITION_SELECTED) do
        if not exists[tostring(key)] then
            AUTO_SPRINKLER_OTHER_POSITION_SELECTED[key] = nil
        end
    end

    G.AUTO_SPRINKLER_OTHER_POSITION_SELECTED =
        AUTO_SPRINKLER_OTHER_POSITION_SELECTED
end

local function buildOtherPositionItems()
    cleanOtherPositionList()
    pruneOtherPositionSelected()

    local items = {}

    for i, p in ipairs(AUTO_SPRINKLER_OTHER_POSITIONS) do
        local label

        if p.rx and p.ry and p.rz then
            label = string.format(
                "%d. Farm Offset | X %.1f | Y %.1f | Z %.1f",
                i,
                round1(p.rx),
                round1(p.ry),
                round1(p.rz)
            )
        else
            local pos = Vector3.new(
                p.x or 0,
                p.y or 0,
                p.z or 0
            )

            label =
                tostring(i)
                .. ".  World Pos | "
                .. makePosLabel(pos)
        end

        table.insert(items, {
            key = tostring(p.key or ""),
            name = label,
        })
    end

    return items
end

