local function getFarmOwnerFromPosition(pos)
    local farmRoot = workspace:FindFirstChild("Farm")
    if not farmRoot or not pos then return nil end

    local bestOwner = nil
    local bestDist = math.huge

    for _, farm in ipairs(farmRoot:GetChildren()) do
        local important = farm:FindFirstChild("Important")
        local data = important and important:FindFirstChild("Data")
        local owner = data and data:FindFirstChild("Owner")
        local objects = important and important:FindFirstChild("Objects_Physical")

        if owner and objects then
            local cf = getFarmCF(farm)
            if cf then
                local dx = cf.Position.X - pos.X
                local dz = cf.Position.Z - pos.Z
                local dist = math.sqrt(dx * dx + dz * dz)

                if dist < bestDist then
                    bestDist = dist
                    bestOwner = tostring(owner.Value or "")
                end
            end
        end
    end

    return bestOwner, bestDist
end

