MAIN.misc.auto_reclaimer = MAIN.misc.auto_reclaimer or {
    enabled = false,
    skip_fav = true,
    delaySec = 1,
    total = 1,
    plants = {},
}
local AR_STATE = MAIN.misc.auto_reclaimer
AR_STATE.enabled = (AR_STATE.enabled == true)
AR_STATE.skip_fav = (AR_STATE.skip_fav ~= false)
AR_STATE.delaySec = math.max(0.05, math.min(300, tonumber(AR_STATE.delaySec) or 1))
AR_STATE.total = math.max(0, math.floor(tonumber(AR_STATE.total) or 1))
AR_STATE.plants = type(AR_STATE.plants) == "table" and AR_STATE.plants or {}

local function arrayToMapAR(arr)
    local out = {}
    if type(arr) ~= "table" then return out end
    if #arr > 0 then
        for _, k in ipairs(arr) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(arr) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function mapToArrayAR(map)
    local out = {}
    if type(map) ~= "table" then return out end
    for k, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            out[#out + 1] = tostring(k)
        end
    end
    table.sort(out)
    return out
end

AUTO_RECLAIMER_ENABLED = (AUTO_RECLAIMER_ENABLED == true) or AR_STATE.enabled
if AUTO_RECLAIMER_SKIP_FAV == nil then
    AUTO_RECLAIMER_SKIP_FAV = (AR_STATE.skip_fav ~= false)
else
    AUTO_RECLAIMER_SKIP_FAV = (AUTO_RECLAIMER_SKIP_FAV ~= false)
end
AUTO_RECLAIMER_DELAY_SEC = math.max(
    0.05,
    math.min(300, tonumber(AUTO_RECLAIMER_DELAY_SEC) or AR_STATE.delaySec or 1)
)
AUTO_RECLAIMER_TOTAL = math.max(
    0,
    math.floor(tonumber(AUTO_RECLAIMER_TOTAL) or AR_STATE.total or 1)
)
AUTO_RECLAIMER_PLANTS_SELECTED = cleanSelectedMap(
    AUTO_RECLAIMER_PLANTS_SELECTED or arrayToMapAR(AR_STATE.plants)
)

G.AUTO_RECLAIMER_ENABLED = AUTO_RECLAIMER_ENABLED
G.AUTO_RECLAIMER_SKIP_FAV = AUTO_RECLAIMER_SKIP_FAV
G.AUTO_RECLAIMER_DELAY_SEC = AUTO_RECLAIMER_DELAY_SEC
G.AUTO_RECLAIMER_TOTAL = AUTO_RECLAIMER_TOTAL
G.AUTO_RECLAIMER_PLANTS_SELECTED = AUTO_RECLAIMER_PLANTS_SELECTED
_G.AUTO_RECLAIMER_ENABLED = AUTO_RECLAIMER_ENABLED
_G.AUTO_RECLAIMER_SKIP_FAV = AUTO_RECLAIMER_SKIP_FAV
_G.AUTO_RECLAIMER_DELAY_SEC = AUTO_RECLAIMER_DELAY_SEC
_G.AUTO_RECLAIMER_TOTAL = AUTO_RECLAIMER_TOTAL
_G.AUTO_RECLAIMER_PLANTS_SELECTED = AUTO_RECLAIMER_PLANTS_SELECTED

local function syncAutoReclaimerModule()
    local mod = rawget(_G, "AutoReclaimer") or rawget(G, "AutoReclaimer")
    if type(mod) ~= "table" then return end
    if type(mod.SetPlants) == "function" then
        pcall(mod.SetPlants, AUTO_RECLAIMER_PLANTS_SELECTED)
    end
    if type(mod.SetTotal) == "function" then
        pcall(mod.SetTotal, AUTO_RECLAIMER_TOTAL)
    end
    if type(mod.SetDelay) == "function" then
        pcall(mod.SetDelay, AUTO_RECLAIMER_DELAY_SEC)
    end
    if type(mod.SetSkipFav) == "function" then
        pcall(mod.SetSkipFav, AUTO_RECLAIMER_SKIP_FAV)
    end
    if type(mod.SyncFromState) == "function" then
        pcall(mod.SyncFromState)
    elseif type(mod.SetEnabled) == "function" then
        pcall(function()
            mod.SetEnabled(AUTO_RECLAIMER_ENABLED == true)
        end)
    end
end

local function persistArState()
    AR_STATE.enabled = (AUTO_RECLAIMER_ENABLED == true)
    AR_STATE.skip_fav = (AUTO_RECLAIMER_SKIP_FAV ~= false)
    AR_STATE.delaySec = math.max(0.05, math.min(300, tonumber(AUTO_RECLAIMER_DELAY_SEC) or 1))
    AR_STATE.total = math.max(0, math.floor(tonumber(AUTO_RECLAIMER_TOTAL) or 1))
    AR_STATE.plants = mapToArrayAR(AUTO_RECLAIMER_PLANTS_SELECTED)
    MAIN.misc.auto_reclaimer = {
        enabled = AR_STATE.enabled,
        skip_fav = AR_STATE.skip_fav,
        delaySec = AR_STATE.delaySec,
        total = AR_STATE.total,
        plants = AR_STATE.plants,
    }
end

