}
local AP_STATE = MAIN.misc.auto_plant
AP_STATE.enabled = (AP_STATE.enabled == true)
AP_STATE.delaySec = math.max(0.05, math.min(300, tonumber(AP_STATE.delaySec) or 1))
AP_STATE.total = math.max(0, math.floor(tonumber(AP_STATE.total) or 0))
do
    local m = tostring(AP_STATE.mode or "near"):lower()
    if m == "posisi" or m == "pos" or m == "manual" then m = "position" end
    if m ~= "near" and m ~= "position" and m ~= "random" then m = "near" end
    AP_STATE.mode = m
end
AP_STATE.seeds = type(AP_STATE.seeds) == "table" and AP_STATE.seeds or {}
AP_STATE.garden_plants = type(AP_STATE.garden_plants) == "table" and AP_STATE.garden_plants or {}
AP_STATE.positions = type(AP_STATE.positions) == "table" and AP_STATE.positions or {}
AP_STATE.position_selected = type(AP_STATE.position_selected) == "table" and AP_STATE.position_selected or {}

local function arrayToMapAP(arr)
    local out = {}
    if type(arr) ~= "table" then return out end
    if #arr > 0 then
        for _, k in ipairs(arr) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(arr) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function mapToArrayAP(map)
    local out = {}
    if type(map) ~= "table" then return out end
    for k, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            out[#out + 1] = tostring(k)
        end
    end
    table.sort(out)
    return out
end

AUTO_PLANT_ENABLED = (AUTO_PLANT_ENABLED == true) or AP_STATE.enabled
AUTO_PLANT_DELAY_SEC = math.max(
    0.05,
    math.min(300, tonumber(AUTO_PLANT_DELAY_SEC) or AP_STATE.delaySec or 1)
)
AUTO_PLANT_TOTAL = math.max(
    0,
    math.floor(tonumber(AUTO_PLANT_TOTAL) or AP_STATE.total or 0)
)
AUTO_PLANT_MODE = tostring(AUTO_PLANT_MODE or AP_STATE.mode or "near"):lower()
if AUTO_PLANT_MODE == "posisi" or AUTO_PLANT_MODE == "pos" or AUTO_PLANT_MODE == "manual" then
    AUTO_PLANT_MODE = "position"
end
if AUTO_PLANT_MODE ~= "near" and AUTO_PLANT_MODE ~= "position" and AUTO_PLANT_MODE ~= "random" then
    AUTO_PLANT_MODE = "near"
end
AUTO_PLANT_SEEDS_SELECTED = cleanSelectedMap(
