local function persistApState()
    AP_STATE.enabled = (AUTO_PLANT_ENABLED == true)
    AP_STATE.delaySec = math.max(0.05, math.min(300, tonumber(AUTO_PLANT_DELAY_SEC) or 1))
    AP_STATE.total = math.max(0, math.floor(tonumber(AUTO_PLANT_TOTAL) or 0))
    AP_STATE.mode = AUTO_PLANT_MODE
    AP_STATE.seeds = mapToArrayAP(AUTO_PLANT_SEEDS_SELECTED)
    AP_STATE.garden_plants = mapToArrayAP(AUTO_PLANT_GARDEN_SELECTED)
    AP_STATE.positions = AUTO_PLANT_POSITIONS
    AP_STATE.position_selected = mapToArrayAP(AUTO_PLANT_POSITION_SELECTED)
    MAIN.misc.auto_plant = {
        enabled = AP_STATE.enabled,
        delaySec = AP_STATE.delaySec,
        total = AP_STATE.total,
        mode = AP_STATE.mode,
        seeds = AP_STATE.seeds,
        garden_plants = AP_STATE.garden_plants,
        positions = AP_STATE.positions,
        position_selected = AP_STATE.position_selected,
    }
end

local function syncAutoPlantModule()
    local mod = rawget(_G, "AutoPlant") or rawget(G, "AutoPlant")
    if type(mod) ~= "table" then return end
    if type(mod.SetSeeds) == "function" then
        pcall(mod.SetSeeds, AUTO_PLANT_SEEDS_SELECTED)
    end
    if type(mod.SetGardenPlants) == "function" then
        pcall(mod.SetGardenPlants, AUTO_PLANT_GARDEN_SELECTED)
    end
    if type(mod.SetMode) == "function" then
        pcall(mod.SetMode, AUTO_PLANT_MODE)
    end
    if type(mod.SetDelay) == "function" then
        pcall(mod.SetDelay, AUTO_PLANT_DELAY_SEC)
    end
    if type(mod.SetTotal) == "function" then
        pcall(mod.SetTotal, AUTO_PLANT_TOTAL)
    end
    if type(mod.SetPositions) == "function" then
        pcall(mod.SetPositions, AUTO_PLANT_POSITIONS)
    end
    if type(mod.SetPositionSelected) == "function" then
        pcall(mod.SetPositionSelected, AUTO_PLANT_POSITION_SELECTED)
    end
    if type(mod.SyncFromState) == "function" then
        pcall(mod.SyncFromState)
    elseif type(mod.SetEnabled) == "function" then
        pcall(function()
            mod.SetEnabled(AUTO_PLANT_ENABLED == true)
        end)
    end
end

