local function applyAutoPlantModeUI(mode)
    mode = tostring(mode or AUTO_PLANT_MODE or "near"):lower()
    if mode == "posisi" or mode == "pos" or mode == "manual" then
        mode = "position"
    end
    local showNear = (mode == "near")
    local showPos = (mode == "position")
    if apGardenRow then apGardenRow.Visible = showNear end
    if apPosRow then apPosRow.Visible = showPos end
    if rowSaveApPos then rowSaveApPos.Visible = showPos end
end

ui:CreateRowDropdown(body9c, {
    label       = "Mode",
    placeholder = "Near / Position / Random...",
    mode        = "single",
    getItems    = function() return PLANT_MODE_ITEMS end,
    initial     = AUTO_PLANT_MODE,
    onChanged   = function(_, selectedKey)
        local m = tostring(selectedKey or "near"):lower()
        if m == "posisi" or m == "pos" or m == "manual" then
            m = "position"
        end
        if m ~= "near" and m ~= "position" and m ~= "random" then
            m = "near"
        end
        AUTO_PLANT_MODE = m
        G.AUTO_PLANT_MODE = AUTO_PLANT_MODE
        _G.AUTO_PLANT_MODE = AUTO_PLANT_MODE
        applyAutoPlantModeUI(AUTO_PLANT_MODE)
