-- Position only: Location List (multi + red X) + Save Current Position
local function buildApPositionItems()
    local mod = rawget(_G, "AutoPlant") or rawget(G, "AutoPlant")
    if type(mod) == "table" and type(mod.BuildPositionItems) == "function" then
        local ok, items = pcall(mod.BuildPositionItems)
        if ok and type(items) == "table" then
            return items
        end
    end
    local items = {}
    for i, p in ipairs(AUTO_PLANT_POSITIONS) do
        if type(p) == "table" then
            items[#items + 1] = {
                key = tostring(p.key or i),
                name = string.format("#%d  X %.1f | Y %.1f | Z %.1f", i, tonumber(p.rx) or 0, tonumber(p.ry) or 0, tonumber(p.rz) or 0),
            }
        end
    end
    return items
end

local function refreshApPosListUI()
    if not apPosListApi then return end
    pcall(function()
        if type(apPosListApi.setSelected) == "function" then
            apPosListApi.setSelected(AUTO_PLANT_POSITION_SELECTED)
        end
        if type(apPosListApi.refreshLabel) == "function" then
            apPosListApi.refreshLabel()
        end
    end)
end

apPosRow, apPosListApi = ui:CreateRowDropdown(body9c, {
    label       = "Location List",
    placeholder = "Multi-select positions...",
    mode        = "multi",
    getItems    = buildApPositionItems,
    initial     = AUTO_PLANT_POSITION_SELECTED,
    onDeleteItem = function(key)
        key = tostring(key or "")
        if key == "" then return end
        local mod = rawget(_G, "AutoPlant") or rawget(G, "AutoPlant")
        if type(mod) == "table" and type(mod.DeletePosition) == "function" then
            pcall(mod.DeletePosition, key)
        else
            for i = #AUTO_PLANT_POSITIONS, 1, -1 do
                local p = AUTO_PLANT_POSITIONS[i]
                if p and tostring(p.key) == key then
                    table.remove(AUTO_PLANT_POSITIONS, i)
                end
            end
            AUTO_PLANT_POSITION_SELECTED[key] = nil
        end
        AUTO_PLANT_POSITIONS = G.AUTO_PLANT_POSITIONS or AUTO_PLANT_POSITIONS
        AUTO_PLANT_POSITION_SELECTED = cleanSelectedMap(
            G.AUTO_PLANT_POSITION_SELECTED or AUTO_PLANT_POSITION_SELECTED
        )
        G.AUTO_PLANT_POSITIONS = AUTO_PLANT_POSITIONS
        G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED
        _G.AUTO_PLANT_POSITIONS = AUTO_PLANT_POSITIONS
        _G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED
        persistApState()
        autoSave()
        refreshApPosListUI()
    end,
    onChanged = function(_, selectedMap)
        AUTO_PLANT_POSITION_SELECTED = cleanSelectedMap(selectedMap)
        G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED
        _G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED
