MAIN.misc.auto_shovel = MAIN.misc.auto_shovel or {
    enabled = false,
    delaySec = 1,
    total = 0,
    plants = {},
}
local AS_STATE = MAIN.misc.auto_shovel
AS_STATE.enabled = (AS_STATE.enabled == true)
AS_STATE.delaySec = math.max(0.05, math.min(300, tonumber(AS_STATE.delaySec) or 1))
AS_STATE.total = math.max(0, math.floor(tonumber(AS_STATE.total) or 0))
AS_STATE.plants = type(AS_STATE.plants) == "table" and AS_STATE.plants or {}

local function arrayToMapAS(arr)
    local out = {}
    if type(arr) ~= "table" then return out end
    if #arr > 0 then
        for _, k in ipairs(arr) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(arr) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function mapToArrayAS(map)
    local out = {}
    if type(map) ~= "table" then return out end
    for k, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            out[#out + 1] = tostring(k)
        end
    end
    table.sort(out)
    return out
end

AUTO_SHOVEL_ENABLED = (AUTO_SHOVEL_ENABLED == true) or AS_STATE.enabled
AUTO_SHOVEL_DELAY_SEC = math.max(
    0.05,
    math.min(300, tonumber(AUTO_SHOVEL_DELAY_SEC) or AS_STATE.delaySec or 1)
)
AUTO_SHOVEL_TOTAL = math.max(
    0,
    math.floor(tonumber(AUTO_SHOVEL_TOTAL) or AS_STATE.total or 0)
)
AUTO_SHOVEL_PLANTS_SELECTED = cleanSelectedMap(
    AUTO_SHOVEL_PLANTS_SELECTED or arrayToMapAS(AS_STATE.plants)
)

