    ASF_SHOVEL_STATE.enabled = (AUTO_SHOVEL_FRUIT_ENABLED == true)
    ASF_SHOVEL_STATE.delaySec = math.max(0, math.min(300, tonumber(AUTO_SHOVEL_FRUIT_DELAY_SEC) or 0.03))
