    ASF_SHOVEL_STATE.mutations = mapToArrayAS(AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED)
    ASF_SHOVEL_STATE.kg = tonumber(AUTO_SHOVEL_FRUIT_KG) or 0
