    ASF_SHOVEL_STATE.ruleMode = tostring(ASF_SHOVEL_STATE.ruleMode or "keep")
    MAIN.misc.auto_shovel_fruit = ASF_SHOVEL_STATE
    G.AUTO_SHOVEL_FRUIT_RULES = ASF_SHOVEL_STATE.rules
    G.AUTO_SHOVEL_FRUIT_RULE_MODE = ASF_SHOVEL_STATE.ruleMode
    _G.AUTO_SHOVEL_FRUIT_RULES = ASF_SHOVEL_STATE.rules
    _G.AUTO_SHOVEL_FRUIT_RULE_MODE = ASF_SHOVEL_STATE.ruleMode
end

local function syncAutoShovelFruitModule()
    local mod = rawget(_G, "AutoShovelFruit") or rawget(G, "AutoShovelFruit")
    if type(mod) ~= "table" then return end
    if type(mod.SetFruits) == "function" then
        pcall(mod.SetFruits, AUTO_SHOVEL_FRUIT_SELECTED)
    end
    if type(mod.SetVariants) == "function" then
        pcall(mod.SetVariants, AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED)
    end
    if type(mod.SetMutations) == "function" then
        pcall(mod.SetMutations, AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED)
    end
    if type(mod.SetKgFilter) == "function" then
        pcall(mod.SetKgFilter, AUTO_SHOVEL_FRUIT_KG, AUTO_SHOVEL_FRUIT_KG_MODE)
    end
    if type(mod.SetRules) == "function" then
        pcall(mod.SetRules, ASF_SHOVEL_STATE.rules)
    end
    if type(mod.SetRuleMode) == "function" then
        pcall(mod.SetRuleMode, ASF_SHOVEL_STATE.ruleMode)
    end
    if type(mod.SetDelay) == "function" then
        pcall(mod.SetDelay, AUTO_SHOVEL_FRUIT_DELAY_SEC)
    end
    if type(mod.SyncFromState) == "function" then
        pcall(mod.SyncFromState)
    elseif type(mod.SetEnabled) == "function" then
        pcall(function()
            mod.SetEnabled(AUTO_SHOVEL_FRUIT_ENABLED == true)
        end)
    end
end

