MAIN.misc.auto_trowel = MAIN.misc.auto_trowel or {
    enabled = false,
    delaySec = 1,
    total = 0,
    plants = {},
    position = nil,
}
local ATW_STATE = MAIN.misc.auto_trowel
ATW_STATE.enabled = (ATW_STATE.enabled == true) or (ATW_STATE.always == true)
ATW_STATE.delaySec = math.max(0, math.min(300, tonumber(ATW_STATE.delaySec) or 1))
ATW_STATE.total = math.max(0, math.floor(tonumber(ATW_STATE.total) or 0))
ATW_STATE.plants = type(ATW_STATE.plants) == "table" and ATW_STATE.plants or {}
ATW_STATE.position = type(ATW_STATE.position) == "table" and ATW_STATE.position or nil

local function arrayToMapATW(arr)
    local out = {}
    if type(arr) ~= "table" then return out end
    if #arr > 0 then
        for _, k in ipairs(arr) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(arr) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function mapToArrayATW(map)
    local out = {}
    if type(map) ~= "table" then return out end
    for k, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            out[#out + 1] = tostring(k)
        end
    end
    table.sort(out)
    return out
end

AUTO_TROWEL_ENABLED = (AUTO_TROWEL_ENABLED == true)
    or (G.AUTO_TROWEL_ENABLED == true)
    or (ATW_STATE.enabled == true)
AUTO_TROWEL_DELAY_SEC = math.max(
    0,
    math.min(300, tonumber(AUTO_TROWEL_DELAY_SEC) or ATW_STATE.delaySec or 1)
)
AUTO_TROWEL_TOTAL = math.max(
    0,
    math.floor(tonumber(AUTO_TROWEL_TOTAL) or ATW_STATE.total or 0)
)
AUTO_TROWEL_PLANTS_SELECTED = cleanSelectedMap(
    AUTO_TROWEL_PLANTS_SELECTED or arrayToMapATW(ATW_STATE.plants)
)
AUTO_TROWEL_POSITION = type(AUTO_TROWEL_POSITION) == "table" and AUTO_TROWEL_POSITION
    or (type(ATW_STATE.position) == "table" and ATW_STATE.position)
    or nil

G.AUTO_TROWEL_ENABLED = AUTO_TROWEL_ENABLED
G.AUTO_TROWEL_DELAY_SEC = AUTO_TROWEL_DELAY_SEC
G.AUTO_TROWEL_TOTAL = AUTO_TROWEL_TOTAL
G.AUTO_TROWEL_PLANTS_SELECTED = AUTO_TROWEL_PLANTS_SELECTED
G.AUTO_TROWEL_POSITION = AUTO_TROWEL_POSITION
_G.AUTO_TROWEL_ENABLED = AUTO_TROWEL_ENABLED
_G.AUTO_TROWEL_DELAY_SEC = AUTO_TROWEL_DELAY_SEC
_G.AUTO_TROWEL_TOTAL = AUTO_TROWEL_TOTAL
_G.AUTO_TROWEL_PLANTS_SELECTED = AUTO_TROWEL_PLANTS_SELECTED
_G.AUTO_TROWEL_POSITION = AUTO_TROWEL_POSITION

local function persistAtwState()
    ATW_STATE.enabled = (AUTO_TROWEL_ENABLED == true)
    ATW_STATE.always = nil
    ATW_STATE.delaySec = math.max(0, math.min(300, tonumber(AUTO_TROWEL_DELAY_SEC) or 1))
    ATW_STATE.total = math.max(0, math.floor(tonumber(AUTO_TROWEL_TOTAL) or 0))
    ATW_STATE.plants = mapToArrayATW(AUTO_TROWEL_PLANTS_SELECTED)
    local pos = G.AUTO_TROWEL_POSITION or AUTO_TROWEL_POSITION
    if type(pos) == "table" and (pos.rx ~= nil or pos.x ~= nil or type(pos.rel) == "table") then
        ATW_STATE.position = pos
        AUTO_TROWEL_POSITION = pos
    elseif type(ATW_STATE.position) == "table" then
        AUTO_TROWEL_POSITION = ATW_STATE.position
        G.AUTO_TROWEL_POSITION = ATW_STATE.position
    end
    MAIN.misc.auto_trowel = ATW_STATE
end

local function syncAutoTrowelModule()
    local mod = rawget(_G, "AutoTrowel") or rawget(G, "AutoTrowel")
    if type(mod) ~= "table" then return end
    if type(mod.SetPlants) == "function" then
        pcall(mod.SetPlants, AUTO_TROWEL_PLANTS_SELECTED)
    end
    if type(mod.SetTotal) == "function" then
        pcall(mod.SetTotal, AUTO_TROWEL_TOTAL)
    end
    if type(mod.SetDelay) == "function" then
        pcall(mod.SetDelay, AUTO_TROWEL_DELAY_SEC)
    end
    if type(mod.SetEnabled) == "function" then
        pcall(function()
            mod.SetEnabled(AUTO_TROWEL_ENABLED == true)
        end)
    elseif type(mod.SyncFromState) == "function" then
        pcall(mod.SyncFromState)
    end
end

