local function persistAwtState()
    AWT_STATE.enabled = (AUTO_WATERING_ENABLED == true)
    AWT_STATE.delaySec = math.max(0, math.min(300, tonumber(AUTO_WATERING_DELAY_SEC) or 8))
    AWT_STATE.plants = mapToArrayAWT(AUTO_WATERING_PLANTS_SELECTED)
