        plants = AWT_STATE.plants,
        cans = AWT_STATE.cans,
    }
end

local function syncAutoWateringModule()
    local mod = rawget(_G, "AutoWatering") or rawget(G, "AutoWatering")
    if type(mod) ~= "table" then return end
    if type(mod.SetPlants) == "function" then
        pcall(mod.SetPlants, AUTO_WATERING_PLANTS_SELECTED)
    end
    if type(mod.SetCans) == "function" then
        pcall(mod.SetCans, AUTO_WATERING_CANS_SELECTED)
    end
    if type(mod.SetDelay) == "function" then
        pcall(mod.SetDelay, AUTO_WATERING_DELAY_SEC)
    end
    if type(mod.SetEnabled) == "function" then
        pcall(function()
            mod.SetEnabled(AUTO_WATERING_ENABLED == true)
        end)
    elseif type(mod.SyncFromState) == "function" then
        pcall(mod.SyncFromState)
    end
end

