-- AUTO SHOVEL SPRINKLER (session: place max/type → shovel all → stop)
-------------------------------------------------------------
MAIN.misc.auto_shovel_sprinkler = MAIN.misc.auto_shovel_sprinkler or {
    enabled = false,
    maxPerType = 1,
    types = {},
    plants = {},
}
local ASS_STATE = MAIN.misc.auto_shovel_sprinkler
ASS_STATE.enabled = (ASS_STATE.enabled == true)
ASS_STATE.maxPerType = math.max(0, math.floor(tonumber(ASS_STATE.maxPerType) or 1))
ASS_STATE.types = type(ASS_STATE.types) == "table" and ASS_STATE.types or {}
ASS_STATE.plants = type(ASS_STATE.plants) == "table" and ASS_STATE.plants or {}

local function arrayToMapASS(arr)
    local out = {}
    if type(arr) ~= "table" then return out end
    if #arr > 0 then
        for _, k in ipairs(arr) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(arr) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function mapToArrayASS(map)
    local out = {}
    if type(map) ~= "table" then return out end
    for k, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            out[#out + 1] = tostring(k)
        end
    end
    table.sort(out)
    return out
end

AUTO_SHOVEL_SPRINKLER_ENABLED = (AUTO_SHOVEL_SPRINKLER_ENABLED == true)
    or (G.AUTO_SHOVEL_SPRINKLER_ENABLED == true)
