MAIN.misc.auto_ascend = MAIN.misc.auto_ascend or {
    total = 0, -- 0 = infinite while toggle ON
    delaySec = 2,
    enabled = false,
}
local AA_STATE = MAIN.misc.auto_ascend
AA_STATE.total = math.max(0, math.floor(tonumber(AA_STATE.total) or 0))
AA_STATE.delaySec = tonumber(AA_STATE.delaySec) or 2
if AA_STATE.delaySec < 0.5 then AA_STATE.delaySec = 0.5 end
if AA_STATE.delaySec > 300 then AA_STATE.delaySec = 300 end
AA_STATE.enabled = (AA_STATE.enabled == true)

AUTO_ASCEND_TOTAL = math.max(0, math.floor(tonumber(AUTO_ASCEND_TOTAL) or AA_STATE.total or 0))
AUTO_ASCEND_DELAY_SEC = tonumber(AUTO_ASCEND_DELAY_SEC) or AA_STATE.delaySec
AUTO_ASCEND_ENABLED = (AUTO_ASCEND_ENABLED == true) or AA_STATE.enabled

AA_STATE.total = AUTO_ASCEND_TOTAL
AA_STATE.delaySec = AUTO_ASCEND_DELAY_SEC
AA_STATE.enabled = AUTO_ASCEND_ENABLED

G.AUTO_ASCEND_TOTAL = AUTO_ASCEND_TOTAL
G.AUTO_ASCEND_DELAY_SEC = AUTO_ASCEND_DELAY_SEC
G.AUTO_ASCEND_ENABLED = AUTO_ASCEND_ENABLED
_G.AUTO_ASCEND_TOTAL = AUTO_ASCEND_TOTAL
_G.AUTO_ASCEND_DELAY_SEC = AUTO_ASCEND_DELAY_SEC
_G.AUTO_ASCEND_ENABLED = AUTO_ASCEND_ENABLED

local function persistAscendState()
    AA_STATE.total = math.max(0, math.floor(tonumber(AUTO_ASCEND_TOTAL) or 0))
    AA_STATE.delaySec = tonumber(AUTO_ASCEND_DELAY_SEC) or 2
    AA_STATE.enabled = (AUTO_ASCEND_ENABLED == true)
    MAIN.misc.auto_ascend = {
        total = AA_STATE.total,
        delaySec = AA_STATE.delaySec,
        enabled = AA_STATE.enabled,
    }
end

