local function syncAutoFavoritePetModule()
    local mod = rawget(_G, "AutoFavoritePet") or rawget(G, "AutoFavoritePet")
    if type(mod) ~= "table" then return end
    if type(mod.SyncFromState) == "function" then
        pcall(mod.SyncFromState)
    elseif type(mod.SetEnabled) == "function" then
        pcall(function()
            mod.SetEnabled(
                (AUTO_FAVORITE_PET_FAV_ENABLED == true)
