end)

local function aspSetEqual(a, b)
    a = type(a) == "table" and a or {}
    b = type(b) == "table" and b or {}
    local n = 0
    for k, v in pairs(a) do
        if v then
            if not b[k] then
                return false
            end
            n += 1
        end
    end
    local m = 0
    for _, v in pairs(b) do
        if v then
            m += 1
        end
    end
    return n == m
end

local function stopAspOnFilterChange()
    if aspFilterArmed ~= true then
        return
    end
    if AUTO_SELL_PET_ENABLED ~= true and AUTO_SELL_PET_NOW ~= true then
        return
    end
    AUTO_SELL_PET_ENABLED = false
    AUTO_SELL_PET_NOW = false
    G.AUTO_SELL_PET_ENABLED = false
    G.AUTO_SELL_PET_NOW = false
    _G.AUTO_SELL_PET_ENABLED = false
    _G.AUTO_SELL_PET_NOW = false
    persistAspState()
    autoSave()
    local mod = rawget(_G, "AutoSellPet") or rawget(G, "AutoSellPet")
    if type(mod) == "table" then
        if type(mod.SetAutoEnabled) == "function" then
            pcall(mod.SetAutoEnabled, false)
        end
        if type(mod.SetEnabled) == "function" then
            pcall(mod.SetEnabled, false)
        elseif type(mod.stop) == "function" then
            pcall(mod.stop)
        end
    end
    local setAuto = G.__AUTO_SELL_PET_SET_AUTO_TOGGLE or _G.__AUTO_SELL_PET_SET_AUTO_TOGGLE
    if type(setAuto) == "function" then
        pcall(setAuto, false, true)
    end
    local setNow = G.__AUTO_SELL_PET_SET_TOGGLE or _G.__AUTO_SELL_PET_SET_TOGGLE
    if type(setNow) == "function" then
        pcall(setNow, false, true)
    end
    pcall(paintAspStatus)
end

