G.AUTO_CRAFT_ENABLED = AUTO_CRAFT_ENABLED

local function normCraftTeamUUID(u)
    if u == nil then return nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    if core == "" or #core < 30 or not core:find("%-") then
        return nil
    end
    return "{" .. core .. "}"
end

local function normalizeCraftTeamSet(src)
    local out = {}
    if type(src) ~= "table" then return out end
    for k, v in pairs(src) do
        local raw
        if type(k) == "number" then
            if v == true or v == 1 or v == "true" then
                raw = k
            else
                raw = v
            end
        elseif v == true or v == 1 or v == "true" then
            raw = k
        end
        local b = normCraftTeamUUID(raw)
        if b then
            out[b] = true
        end
    end
    return out
end

local function craftTeamSetToArray(setTbl)
    local arr = {}
    for uuid, on in pairs(setTbl or {}) do
        if on then
            arr[#arr + 1] = tostring(uuid)
        end
    end
    table.sort(arr)
    return arr
end

local function publishCraftTeamGlobal(globalKey, setTbl)
    setTbl = normalizeCraftTeamSet(setTbl)
    G[globalKey] = setTbl
    _G[globalKey] = setTbl
    return setTbl
end

local function restoreCraftTeamFromState(globalKey, stateKey)
    local cur = rawget(G, globalKey) or rawget(_G, globalKey)
    if type(cur) == "table" and next(cur) ~= nil then
        return publishCraftTeamGlobal(globalKey, cur)
    end

    local src = AC_STATE[stateKey]
    if (not src or next(src) == nil) and type(MAIN.misc.auto_craft) == "table" then
        src = MAIN.misc.auto_craft[stateKey]
    end

    return publishCraftTeamGlobal(globalKey, normalizeCraftTeamSet(src))
end

local function persistCraftTeamsToMain()
    AC_STATE.team_before_claim = craftTeamSetToArray(AUTO_CRAFT_TEAM_BEFORE_CLAIM)
    AC_STATE.team_reduce       = craftTeamSetToArray(AUTO_CRAFT_TEAM_REDUCE)
    AC_STATE.team_submit       = craftTeamSetToArray(AUTO_CRAFT_TEAM_SUBMIT)
    MAIN.misc.auto_craft = MAIN.misc.auto_craft or {}
    MAIN.misc.auto_craft.team_before_claim = AC_STATE.team_before_claim
    MAIN.misc.auto_craft.team_reduce       = AC_STATE.team_reduce
    MAIN.misc.auto_craft.team_submit       = AC_STATE.team_submit
end

local function saveCraftTeamsImmediate()
    persistCraftTeamsToMain()
    if ui and type(ui.SaveState) == "function" then
        pcall(function()
            ui:SaveState()
        end)
    end
end

AUTO_CRAFT_TEAM_BEFORE_CLAIM = restoreCraftTeamFromState("AUTO_CRAFT_TEAM_BEFORE_CLAIM", "team_before_claim")
AUTO_CRAFT_TEAM_REDUCE       = restoreCraftTeamFromState("AUTO_CRAFT_TEAM_REDUCE", "team_reduce")
AUTO_CRAFT_TEAM_SUBMIT       = restoreCraftTeamFromState("AUTO_CRAFT_TEAM_SUBMIT", "team_submit")
persistCraftTeamsToMain()

local function getAutoCraftPetItems()
    if PetListView and type(PetListView.buildEntriesForTab) == "function" then
        return PetListView.buildEntriesForTab("", {}) or {}
    end
    warn("[AutoCraft UI] PetListView.buildEntriesForTab tidak ada")
    return {}
end

local function syncCraftTeamGlobal(globalKey, stateKey, selectedMap)
    local out = publishCraftTeamGlobal(globalKey, selectedMap)
    if globalKey == "AUTO_CRAFT_TEAM_BEFORE_CLAIM" then
        AUTO_CRAFT_TEAM_BEFORE_CLAIM = out
    elseif globalKey == "AUTO_CRAFT_TEAM_REDUCE" then
        AUTO_CRAFT_TEAM_REDUCE = out
    elseif globalKey == "AUTO_CRAFT_TEAM_SUBMIT" then
        AUTO_CRAFT_TEAM_SUBMIT = out
    end
    AC_STATE[stateKey] = craftTeamSetToArray(out)
    persistCraftTeamsToMain()
end

local craftTeamDropdownApis = {}

local function refreshCraftTeamDropdowns()
    local mapping = {
        { api = craftTeamDropdownApis.before_claim, set = AUTO_CRAFT_TEAM_BEFORE_CLAIM },
        { api = craftTeamDropdownApis.reduce,       set = AUTO_CRAFT_TEAM_REDUCE },
        { api = craftTeamDropdownApis.submit,       set = AUTO_CRAFT_TEAM_SUBMIT },
    }
    for _, row in ipairs(mapping) do
        local api = row.api
        local setTbl = normalizeCraftTeamSet(row.set)
        if api and type(api.setSelected) == "function" then
            pcall(function()
                api.setSelected(setTbl)
                if type(api.refreshLabel) == "function" then
                    api.refreshLabel()
                end
            end)
        end
    end
end

