                    seen[key] = true
                end
            end
        end

        return items
    end,
    initial     = AUTO_CRAFT_RECIPES_SELECTED,
    onChanged   = function(_, selectedMap)
        AUTO_CRAFT_RECIPES_SELECTED = {}
        for recipeId, enabled in pairs(selectedMap or {}) do
