local function resolveAutoCraftModule()
    local env = (getgenv and getgenv()) or _G
    return env.AutoCraftLoop or _G.AutoCraftLoop
end

local function syncAutoCraftModule()
    local AC = resolveAutoCraftModule()
    if not AC then return end
    if type(AC.SyncFromGlobals) == "function" then
        pcall(AC.SyncFromGlobals)
    elseif type(AC.SetEnabled) == "function" then
        pcall(function() AC.SetEnabled(AUTO_CRAFT_ENABLED == true) end)
    end
end

local function buildLocalAutoCraftStatus()
    if AUTO_CRAFT_ENABLED ~= true then
        return "", { "Auto crafting off" }
    end

    local hasRecipe = false
    for _, on in pairs(AUTO_CRAFT_RECIPES_SELECTED or {}) do
        if on then
            hasRecipe = true
            break
        end
    end

    if not hasRecipe then
        return "", { "No recipes selected" }
    end

    return "", { "Starting upâ€¦" }
end

