local function layoutAutoCraftStatusPanel(title, detailLines)
    detailLines = detailLines or {}
    local visibleCount = 0
    local totalH = 0
    local showTitle = title and tostring(title) ~= ""

    if acStatusTitle then
        acStatusTitle.Visible = showTitle
        acStatusTitle.Text = showTitle and tostring(title) or ""
    end

    local yOffset = showTitle and 18 or 0

    for i, lbl in ipairs(acDetailLabels) do
        local text = detailLines[i]
        if text and tostring(text) ~= "" then
            lbl.Text = tostring(text)
            lbl.Visible = true
            lbl.Position = UDim2.new(0, 0, 0, yOffset + visibleCount * 14)
            local lineH = math.max(14, math.ceil(lbl.TextBounds.Y))
            lbl.Size = UDim2.new(1, 0, 0, lineH)
            visibleCount += 1
            totalH += lineH
        else
            lbl.Text = ""
            lbl.Visible = false
        end
    end

    acStatusRow.Size = UDim2.new(1, 0, 0, math.max(showTitle and 18 or 14, yOffset + totalH))
end

local function splitStatusLines(text)
    local lines = {}
    for line in tostring(text or ""):gmatch("[^\r\n]+") do
        if line ~= "" then
            lines[#lines + 1] = line
        end
    end
    return lines
end

local function refreshAutoCraftStatus()
    local AC = resolveAutoCraftModule()
    local title, details

    if AC and type(AC.getStatusPanel) == "function" then
        local ok, panel = pcall(AC.getStatusPanel)
        if ok and type(panel) == "table" then
            title = panel.title
            details = panel.details
        end
    elseif AC and type(AC.getStatusText) == "function" then
        local ok, _, sub = pcall(AC.getStatusText)
        if ok then
            title = ""
            details = splitStatusLines(sub)
        end
    end

    if not details then
        title, details = buildLocalAutoCraftStatus()
    end

    layoutAutoCraftStatusPanel(title or "", details or {})
end

