local function __acookArrayToSet(arr)
    local out = {}
    if type(arr) ~= "table" then return out end
    if #arr > 0 then
        for _, k in ipairs(arr) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(arr) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function __acookSetToArray(map)
    local out = {}
    if type(map) ~= "table" then return out end
    for k, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            table.insert(out, tostring(k))
        end
    end
    table.sort(out)
    return out
end

