    ACOOK_STATE.cook_enabled = (AUTO_COOK_COOK_ENABLED ~= false)
    ACOOK_STATE.empty_mismatch = (AUTO_COOK_EMPTY_MISMATCH == true)
    ACOOK_STATE.recipes_selected = __acookSetToArray(AUTO_COOK_RECIPES_SELECTED)
    MAIN.misc.auto_cook = {
        enabled = ACOOK_STATE.enabled,
        claim_enabled = ACOOK_STATE.claim_enabled,
        submit_enabled = ACOOK_STATE.submit_enabled,
        cook_enabled = ACOOK_STATE.cook_enabled,
        empty_mismatch = ACOOK_STATE.empty_mismatch,
        recipes_selected = ACOOK_STATE.recipes_selected,
    }
end

