local function aoCleanSet(src)
    local out = {}
    if type(src) ~= "table" then return out end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        elseif type(k) == "number" and v ~= nil and tostring(v) ~= "" then
            out[tostring(v)] = true
        end
    end
    return out
end

local function aoSetToArray(map)
    local arr = {}
    for k, v in pairs(map or {}) do
        if v == true then
            arr[#arr + 1] = tostring(k)
        end
    end
    table.sort(arr)
    return arr
end

