MAIN.misc.auto_moon_crafting = MAIN.misc.auto_moon_crafting or {
    enabled = false,
    delaySec = 1,
    recipes = {},
}
local AMC_STATE = MAIN.misc.auto_moon_crafting
AMC_STATE.enabled = (AMC_STATE.enabled == true)
AMC_STATE.delaySec = math.max(0.3, math.min(300, tonumber(AMC_STATE.delaySec) or 1))
AMC_STATE.recipes = type(AMC_STATE.recipes) == "table" and AMC_STATE.recipes or {}

local function arrayToMapAmc(arr)
    local out = {}
    if type(arr) ~= "table" then return out end
    if #arr > 0 then
        for _, k in ipairs(arr) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(arr) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function mapToArrayAmc(map)
    local out = {}
    if type(map) ~= "table" then return out end
    for k, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            out[#out + 1] = tostring(k)
        end
    end
    table.sort(out)
    return out
end

AUTO_MOON_CRAFTING_ENABLED = (AUTO_MOON_CRAFTING_ENABLED == true) or AMC_STATE.enabled
AUTO_MOON_CRAFTING_DELAY_SEC = math.max(
    0.3,
    math.min(300, tonumber(AUTO_MOON_CRAFTING_DELAY_SEC) or AMC_STATE.delaySec or 1)
)
AUTO_MOON_CRAFTING_RECIPES = AUTO_MOON_CRAFTING_RECIPES or arrayToMapAmc(AMC_STATE.recipes)

G.AUTO_MOON_CRAFTING_ENABLED = AUTO_MOON_CRAFTING_ENABLED
G.AUTO_MOON_CRAFTING_DELAY_SEC = AUTO_MOON_CRAFTING_DELAY_SEC
G.AUTO_MOON_CRAFTING_RECIPES = AUTO_MOON_CRAFTING_RECIPES
_G.AUTO_MOON_CRAFTING_ENABLED = AUTO_MOON_CRAFTING_ENABLED
_G.AUTO_MOON_CRAFTING_DELAY_SEC = AUTO_MOON_CRAFTING_DELAY_SEC
_G.AUTO_MOON_CRAFTING_RECIPES = AUTO_MOON_CRAFTING_RECIPES

local function syncAutoMoonCraftingModule()
    local mod = rawget(_G, "AutoMoonCrafting") or rawget(G, "AutoMoonCrafting")
    if type(mod) ~= "table" then return end
    if type(mod.SetRecipes) == "function" then
        pcall(mod.SetRecipes, AUTO_MOON_CRAFTING_RECIPES)
    end
    if type(mod.SyncFromState) == "function" then
        pcall(mod.SyncFromState)
    elseif type(mod.SetEnabled) == "function" then
        pcall(function()
            mod.SetEnabled(AUTO_MOON_CRAFTING_ENABLED == true)
        end)
    end
end

local function persistAmcState()
    AMC_STATE.enabled = (AUTO_MOON_CRAFTING_ENABLED == true)
    AMC_STATE.delaySec = math.max(0.3, math.min(300, tonumber(AUTO_MOON_CRAFTING_DELAY_SEC) or 1))
    AMC_STATE.recipes = mapToArrayAmc(AUTO_MOON_CRAFTING_RECIPES)
    MAIN.misc.auto_moon_crafting = {
        enabled = AMC_STATE.enabled,
        delaySec = AMC_STATE.delaySec,
        recipes = AMC_STATE.recipes,
    }
end

