local function syncAutoFallMarketModule()
    local mod = rawget(_G, "AutoFallMarket") or rawget(G, "AutoFallMarket")
    if type(mod) ~= "table" then return end
    if type(mod.SetDelay) == "function" then
        pcall(mod.SetDelay, AUTO_FALL_DELAY_SEC)
    end
    if type(mod.SetPlantTotal) == "function" then
        pcall(mod.SetPlantTotal, AUTO_FALL_PLANT_TOTAL)
    end
    if type(mod.SetPlantSort) == "function" then
        pcall(mod.SetPlantSort, AUTO_FALL_PLANT_SORT)
    end
    if type(mod.SyncFromState) == "function" then
        pcall(mod.SyncFromState)
    elseif type(mod.SetEnabled) == "function" then
        pcall(function()
            mod.SetEnabled(
                (AUTO_FALL_SUBMIT_ENABLED == true)
                or (AUTO_FALL_CLAIM_ENERGY == true)
                or (AUTO_FALL_PLANT_ENABLED == true)
                or (AUTO_FALL_RECLAIM_ENABLED == true)
                or (AUTO_FALL_COLLECT_ENABLED == true)
            )
        end)
    end
end

local function persistAfmState()
    AFM_STATE.submit_enabled = (AUTO_FALL_SUBMIT_ENABLED == true)
    AFM_STATE.delaySec = math.max(0.3, math.min(300, tonumber(AUTO_FALL_DELAY_SEC) or 1))
    AFM_STATE.claim_energy = (AUTO_FALL_CLAIM_ENERGY == true)
    AFM_STATE.plant_enabled = (AUTO_FALL_PLANT_ENABLED == true)
    AFM_STATE.reclaim_enabled = (AUTO_FALL_RECLAIM_ENABLED == true)
    AFM_STATE.collect_enabled = (AUTO_FALL_COLLECT_ENABLED == true)
    AFM_STATE.plant_total = math.max(0, math.floor(tonumber(AUTO_FALL_PLANT_TOTAL) or 10))
    AFM_STATE.plant_sort = (AUTO_FALL_PLANT_SORT == "good") and "good" or "bad"
    MAIN.misc.auto_fall_market = {
        submit_enabled = AFM_STATE.submit_enabled,
        delaySec = AFM_STATE.delaySec,
        claim_energy = AFM_STATE.claim_energy,
        plant_enabled = AFM_STATE.plant_enabled,
        reclaim_enabled = AFM_STATE.reclaim_enabled,
        collect_enabled = AFM_STATE.collect_enabled,
        plant_total = AFM_STATE.plant_total,
        plant_sort = AFM_STATE.plant_sort,
    }
end

