task.spawn(function()
    while bodyFall and bodyFall.Parent do
        pcall(function()
            if not afmStatusLbl or not afmStatusLbl.Parent then return end
            local mod = rawget(_G, "AutoFallMarket") or rawget(G, "AutoFallMarket")
            local txt = "Fall: 0/500 · need — · garden 0/10 · blooms 0\nPlant OFF · Collect OFF · Reclaimer OFF · idle"
            if type(mod) == "table" and type(mod.GetStatusText) == "function" then
                local ok, got = pcall(mod.GetStatusText)
                if ok and type(got) == "string" and got ~= "" then
                    txt = got
                end
            end
            afmStatusLbl.Text = txt
        end)
        task.wait(1)
    end
end)

task.defer(function()
    pcall(syncAutoFallMarketModule)
end)

