MAIN.misc.auto_fairy_event = MAIN.misc.auto_fairy_event or {
    catch_enabled = false,
    jar_enabled = false,
    fountain_enabled = false,
    claim_enabled = false,
    restart_enabled = false,
    upgrade_enabled = false,
    plant_enabled = false,
    plant_total = 1,
    delaySec = 1,
    wish_rewards = {},
    upgrades = {},
}
local AFE_STATE = MAIN.misc.auto_fairy_event
AFE_STATE.catch_enabled = (AFE_STATE.catch_enabled == true)
AFE_STATE.jar_enabled = (AFE_STATE.jar_enabled == true)
AFE_STATE.fountain_enabled = (AFE_STATE.fountain_enabled == true)
AFE_STATE.claim_enabled = (AFE_STATE.claim_enabled == true)
AFE_STATE.restart_enabled = (AFE_STATE.restart_enabled == true)
AFE_STATE.upgrade_enabled = (AFE_STATE.upgrade_enabled == true)
AFE_STATE.plant_enabled = (AFE_STATE.plant_enabled == true)
AFE_STATE.plant_total = math.max(0, math.floor(tonumber(AFE_STATE.plant_total) or 1))
AFE_STATE.delaySec = math.max(0.3, math.min(300, tonumber(AFE_STATE.delaySec) or 1))
do
    local src = AFE_STATE.wish_rewards
    local map = {}
    if type(src) == "table" then
        if src[1] ~= nil then
            for _, k in ipairs(src) do
                if k ~= nil and k ~= "" then
                    map[tostring(k)] = true
                end
            end
        else
            for k, v in pairs(src) do
                if v == true or v == 1 then
                    map[tostring(k)] = true
                end
            end
        end
    end
    AFE_STATE.wish_rewards = map
end
do
    local src = AFE_STATE.upgrades
    local map = {}
    if type(src) == "table" then
        if src[1] ~= nil then
            for _, k in ipairs(src) do
                if k ~= nil and k ~= "" then
                    map[tostring(k)] = true
                end
            end
        else
            for k, v in pairs(src) do
                if v == true or v == 1 then
                    map[tostring(k)] = true
                end
            end
        end
    end
    AFE_STATE.upgrades = map
end

