local function syncAutoFairyEventModule()
    local mod = rawget(_G, "AutoFairyEvent") or rawget(G, "AutoFairyEvent")
    if type(mod) ~= "table" then return end
    if type(mod.SetDelay) == "function" then
        pcall(mod.SetDelay, AUTO_FAIRY_DELAY_SEC)
    end
    if type(mod.SetCatchEnabled) == "function" then
        pcall(mod.SetCatchEnabled, AUTO_FAIRY_CATCH_ENABLED)
    end
    if type(mod.SetJarEnabled) == "function" then
        pcall(mod.SetJarEnabled, AUTO_FAIRY_JAR_ENABLED)
    end
    if type(mod.SetFountainEnabled) == "function" then
        pcall(mod.SetFountainEnabled, AUTO_FAIRY_FOUNTAIN_ENABLED)
    end
    if type(mod.SetWishRewards) == "function" then
        pcall(mod.SetWishRewards, AUTO_FAIRY_WISH_REWARDS)
    end
    if type(mod.SetClaimEnabled) == "function" then
        pcall(mod.SetClaimEnabled, AUTO_FAIRY_CLAIM_ENABLED)
    end
    if type(mod.SetRestartEnabled) == "function" then
        pcall(mod.SetRestartEnabled, AUTO_FAIRY_RESTART_ENABLED)
    end
    if type(mod.SetUpgrades) == "function" then
        pcall(mod.SetUpgrades, AUTO_FAIRY_UPGRADES)
    end
    if type(mod.SetUpgradeEnabled) == "function" then
        pcall(mod.SetUpgradeEnabled, AUTO_FAIRY_UPGRADE_ENABLED)
    end
    if type(mod.SetPlantEnabled) == "function" then
        pcall(mod.SetPlantEnabled, AUTO_FAIRY_PLANT_ENABLED)
    end
    if type(mod.SetPlantTotal) == "function" then
        pcall(mod.SetPlantTotal, AUTO_FAIRY_PLANT_TOTAL)
    elseif type(mod.SyncFromState) == "function" then
        pcall(mod.SyncFromState)
    end
end

