do
    local function toSet(src, fallback)
        local map = {}
        if type(src) == "table" then
            if src[1] ~= nil then
                for _, k in ipairs(src) do
                    if k ~= nil and k ~= "" then
                        map[tostring(k)] = true
                    end
                end
            else
                for k, v in pairs(src) do
                    if v == true or v == 1 then
                        map[tostring(k)] = true
                    end
                end
            end
        end
        if next(map) == nil and type(fallback) == "table" then
            return fallback
        end
        return map
    end
    AHW_STATE.seeds = toSet(AHW_STATE.seeds, AHW_STATE.seeds)
    AHW_STATE.shop = toSet(AHW_STATE.shop, {
        ["Halloween Candy Corn Carrot"] = true,
        ["Halloween Spider Shrub"] = true,
        ["Haunted Sprinkler"] = true,
