local function syncAutoHalloweenModule()
    local mod = rawget(_G, "AutoHalloweenEvent") or rawget(G, "AutoHalloweenEvent")
    if type(mod) ~= "table" then return end
    if type(mod.SetDelay) == "function" then pcall(mod.SetDelay, AUTO_HALLOWEEN_DELAY_SEC) end
    if type(mod.SetPlantEnabled) == "function" then pcall(mod.SetPlantEnabled, AUTO_HALLOWEEN_PLANT_ENABLED) end
