--------------------------------------------------
-- PERFORMANCE LOGIC: Remove Spider Web FX
-- Put this OUTSIDE RegisterSubTab
--------------------------------------------------
do
    if not _G.__REMOVE_SPIDER_WEB_STARTED then
        _G.__REMOVE_SPIDER_WEB_STARTED = true

        local Workspace = game:GetService("Workspace")

        local function isSpiderRemoveEnabled()
            return REMOVE_SPIDER_WEB_ENABLED == true
                or (
                    MAIN
                    and MAIN.misc
                    and MAIN.misc.optimizer
                    and MAIN.misc.optimizer.remove_spider_web == true
                )
        end

        local function removeSpider(obj)
            if not isSpiderRemoveEnabled() then return end

            if obj and obj.Name == "SpiderWebFX" then
                pcall(function()
                    obj:Destroy()
                end)
            end
        end

        task.spawn(function()
            task.wait(1)
            if not isSpiderRemoveEnabled() then
                return
            end
            local farm = Workspace:FindFirstChild("Farm")
            local root = farm or Workspace
            for _, v in ipairs(root:GetDescendants()) do
                removeSpider(v)
            end
        end)

        Workspace.DescendantAdded:Connect(function(obj)
            removeSpider(obj)
        end)
    end
end
    --------------------------------------------------
    -- Subtab Misc lain bisa kamu tambahkan di bawah sini
    --------------------------------------------------
end

