            or (Genv.AUTO_ASCEND_ENABLED == true)
            or (_G.AUTO_ASCEND_ENABLED == true)
        Genv.AUTO_ASCEND_ENABLED = false
        _G.AUTO_ASCEND_ENABLED = false
        pcall(_G.__autoAscendSync)
        Genv.AUTO_ASCEND_ENABLED = keepOn
        _G.AUTO_ASCEND_ENABLED = keepOn
        AUTO_ASCEND_ENABLED = keepOn
    end
        _G.__AUTO_ASCEND_STARTED = true
    Genv.__AUTO_ASCEND_GEN = (tonumber(Genv.__AUTO_ASCEND_GEN) or 0) + 1
    local ASCEND_GEN = Genv.__AUTO_ASCEND_GEN

        local Players = game:GetService("Players")
        local ReplicatedStorage = game:GetService("ReplicatedStorage")
        local LP = Players.LocalPlayer

        local BuyRebirth = nil
        local DataService = nil
        local RebirthShared = nil
        local RebirthConfigData = nil

        local LOOP_TOKEN = 0
        local ASCENDED = 0
        local LAST_STATUS = "Idle · Ascended 0"

        local function publish(msg)
            LAST_STATUS = tostring(msg or "")
            Genv.__AUTO_ASCEND_STATUS = LAST_STATUS
            _G.__AUTO_ASCEND_STATUS = LAST_STATUS
        end

        -- Compact like game UI: 688.9T / 2Qa / 1Qi
        local function fmtCompact(n)
            n = tonumber(n)
            if not n then return "?" end
            local abs = math.abs(n)
            local sign = (n < 0) and "-" or ""
            if abs < 1000 then
                if abs == math.floor(abs) then
                    return sign .. tostring(math.floor(abs))
                end
                return sign .. string.format("%.1f", abs):gsub("%.0$", "")
            end
            local units = {
                { 1e33, "Dc" },
                { 1e30, "No" },
                { 1e27, "Oc" },
                { 1e24, "Sp" },
                { 1e21, "Sx" },
                { 1e18, "Qi" },
                { 1e15, "Qa" },
                { 1e12, "T" },
                { 1e9,  "B" },
                { 1e6,  "M" },
                { 1e3,  "K" },
            }
            for _, u in ipairs(units) do
                if abs >= u[1] then
                    local v = abs / u[1]
                    local s
                    if v >= 100 then
                        s = string.format("%.0f", v)
                    elseif v >= 10 then
                        s = string.format("%.1f", v):gsub("%.0$", "")
                    else
                        s = string.format("%.2f", v):gsub("%.?0+$", "")
                    end
                    return sign .. s .. u[2]
                end
            end
            return sign .. tostring(math.floor(abs))
        end

        local function lazy()
            if not BuyRebirth then
                pcall(function()
                    local ge = ReplicatedStorage:FindFirstChild("GameEvents")
                        or ReplicatedStorage:WaitForChild("GameEvents", 8)
                    BuyRebirth = ge and (ge:FindFirstChild("BuyRebirth") or ge:WaitForChild("BuyRebirth", 5))
                end)
            end
            if not DataService then
                pcall(function()
                    DataService = require(ReplicatedStorage.Modules.DataService)
                end)
            end
            if not RebirthShared then
                pcall(function()
                    RebirthShared = require(ReplicatedStorage.Modules.RebirthShared)
                end)
            end
            if not RebirthConfigData then
                pcall(function()
                    RebirthConfigData = require(ReplicatedStorage.Data.RebirthConfigData)
                end)
            end
        end

        local function isEnabled()
            return AUTO_ASCEND_ENABLED == true
                or Genv.AUTO_ASCEND_ENABLED == true
                or _G.AUTO_ASCEND_ENABLED == true
        end

        local function getDelay()
            local n = tonumber(AUTO_ASCEND_DELAY_SEC)
                or tonumber(Genv.AUTO_ASCEND_DELAY_SEC)
                or 2
            if n < 0.5 then n = 0.5 end
            if n > 300 then n = 300 end
            return n
        end

        local function getMax()
            local t = tonumber(AUTO_ASCEND_TOTAL)
                or tonumber(Genv.AUTO_ASCEND_TOTAL)
                or 0
            return math.max(0, math.floor(t))
        end

        local function cooldownLeft(data)
            if not data or not data.RebirthData or not RebirthConfigData then
                return 0
            end
            local last = tonumber(data.RebirthData.LastRebirthTime) or 0
            local reset = tonumber(RebirthConfigData.RESET_TIME) or 0
            local left = last + reset - math.floor(workspace:GetServerTimeNow())
            return math.max(0, left)
        end

        local function canAscend()
            lazy()
            if not BuyRebirth or not DataService or not RebirthShared then
                return false, "services missing"
            end
            local okData, data = pcall(function()
                return DataService:GetData()
            end)
            if not okData or type(data) ~= "table" then
                return false, "no data"
            end

            local avail = false
            pcall(function()
                avail = RebirthShared:IsRebirthAvailable(LP) == true
            end)
            if not avail then
                local left = cooldownLeft(data)
                if left > 0 then
                    return false, string.format("cooldown %ds", math.ceil(left))
                end
                return false, "not available"
            end

            local price = 0
            pcall(function()
                local rd = data.RebirthData or {}
                price = tonumber(RebirthShared:CalculatePrice(rd.TotalRebirths, LP)) or 0
            end)
            local sheckles = 0
            do
                local s = tonumber(data.Sheckles)
                if s then sheckles = s end
                if sheckles <= 0 and type(data.CurrencyData) == "table" then
                    s = tonumber(data.CurrencyData.Sheckles)
                    if s then sheckles = s end
                end
                if sheckles <= 0 and type(data.Stats) == "table" then
                    s = tonumber(data.Stats.Sheckles)
                    if s then sheckles = s end
                end
                if sheckles <= 0 and type(data.SpecialCurrency) == "table" then
                    s = tonumber(data.SpecialCurrency.Sheckles)
                    if s then sheckles = s end
                end
            end
            if sheckles < price then
                return false, string.format("%s / %s", fmtCompact(sheckles), fmtCompact(price))
            end
            return true, string.format("ready %s", fmtCompact(price)), price
        end

        local function disableAndSave(reason)
            AUTO_ASCEND_ENABLED = false
            Genv.AUTO_ASCEND_ENABLED = false
            _G.AUTO_ASCEND_ENABLED = false
            if MAIN and MAIN.misc then
                MAIN.misc.auto_ascend = MAIN.misc.auto_ascend or {}
                MAIN.misc.auto_ascend.enabled = false
            end
            publish(string.format("%s · Ascended %d", reason or "Stopped", ASCENDED))
            if type(_G.__autoAscendOnStop) == "function" then
                pcall(_G.__autoAscendOnStop, reason)
            end
        end

        local function worker(token)
            publish(string.format("Running · Ascended %d", ASCENDED))
            while token == LOOP_TOKEN do
                if Genv.__AUTO_ASCEND_GEN ~= ASCEND_GEN then
                    break
                end
                if not isEnabled() then
                    publish(string.format("Idle · Ascended %d", ASCENDED))
                    break
                end

                local ok, why = canAscend()
                if ok then
                    local firedOk, err = pcall(function()
                        BuyRebirth:FireServer()
                    end)
                    if firedOk then
                        ASCENDED += 1
                        publish(string.format("Fired · Ascended %d", ASCENDED))
                        local maxN = getMax()
                        if maxN > 0 and ASCENDED >= maxN then
                            disableAndSave("Max reached")
                            break
                        end
                    else
                        publish(string.format("Fire fail · %s", tostring(err)))
                    end
                    task.wait(getDelay())
                else
                    publish(string.format("%s · Ascended %d", tostring(why), ASCENDED))
                    task.wait(getDelay())
                end
            end
        end

        function _G.__autoAscendSync()
            if isEnabled() then
                LOOP_TOKEN += 1
                local token = LOOP_TOKEN
                task.spawn(worker, token)
            else
                LOOP_TOKEN += 1
                publish(string.format("Idle · Ascended %d", ASCENDED))
            end
        end
        -- legacy name
        _G.__autoAscendFire = _G.__autoAscendSync

        -- boot if toggle already on from save
        task.defer(function()
            if isEnabled() then
                _G.__autoAscendSync()
            end
        end)
end

return M






































































        end,
        required = true,
