    DataService = DataService or safeRequire({ "Modules", "DataService" })
    PetRegistry = PetRegistry or safeRequire({ "Data", "PetRegistry" })
    mutationModule = mutationModule or safeRequire({ "Data", "PetRegistry", "PetMutationRegistry" })
    PetList = PetList or safeRequire({ "Data", "PetRegistry", "PetList" })
    SeedData = SeedData or safeRequire({ "Data", "SeedData" })
    VariantEnums = VariantEnums or safeRequire({ "Data", "EnumRegistry", "VariantsEnums" })
    MutationHandler = MutationHandler or safeRequire({ "Modules", "MutationHandler" })
    return DataService
end

