-------------------------------------------------------------
local function __getStoreBag()
    resolveGameModules()
    if not ActivePetsService or not ActivePetsService.GetPlayerDatastorePetData then
        warn("[PetListView] ActivePetsService:GetPlayerDatastorePetData not available")
        return nil
    end

    local ok, store = pcall(function()
        return ActivePetsService:GetPlayerDatastorePetData(LocalPlayer.Name)
    end)
    if not ok then
        warn("[PetListView] GetPlayerDatastorePetData error:", store)
        return nil
    end
    if not store or not store.PetInventory or not store.PetInventory.Data then
        warn("[PetListView] Store/PetInventory/Data empty")
        return nil
    end

    return store.PetInventory.Data
end

------------------------------------------------------------
-- GBXP HELPERS (mirip logic syncGBXPFromStoreOnce lama)
------------------------------------------------------------
local function _getSelectedGlobal()
    local G = (getgenv and getgenv()) or _G
    return rawget(G, "selected") or rawget(getfenv(0), "selected") or {}
end

local function _normUUIDCore(u)
    if not u then return nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    return core
end

-- cek apakah uuid sudah dipakai di tab lain (noos/boost/xp/seratusage)
local function _in_other_tabs(uuid)
    local core = _normUUIDCore(uuid)
    if not core then return false end

    local sel = _getSelectedGlobal()
    local function has(tbl)
        if type(tbl) ~= "table" then return false end
        if tbl[uuid] or tbl["{"..core.."}"] or tbl[core] then
            return true
        end
        for k,_ in pairs(tbl) do
            local kc = _normUUIDCore(k)
            if kc == core then return true end
        end
        return false
    end

    return has(sel.noos) or has(sel.boost) or has(sel.xp) or has(sel.seratusage)
end

-- whitelist type (pakai _G.GBXP_TYPE_WHITELIST kalau ada)
local function _get_gbxp_whitelist()
    local G = (getgenv and getgenv()) or _G
    local w = rawget(G, "GBXP_TYPE_WHITELIST")
           or rawget(getfenv(0), "GBXP_TYPE_WHITELIST")
    if type(w) == "table" then
        return w
    end
    return nil
end

local function _gbxp_whitelist_match(petTypeNorm)
    petTypeNorm = tostring(petTypeNorm or ""):lower()
    if petTypeNorm == "" then return false end

    local w = _get_gbxp_whitelist()
    -- kalau whitelist nil atau kosong → semua lolos
    if not w or (next(w) == nil) then
        return true
    end

    for key,_ in pairs(w) do
        local pat = tostring(key or ""):lower()
        if pat ~= "" and petTypeNorm:find(pat, 1, true) then
            return true
        end
    end
    return false
end

-- hitung W100 pakai helper yang SUDAH ada di file ini
local function _weight_at_100_for_rec(rec, uuid)
    local SCALE = SCALE_PER_LVL or 0
    local age   = __age_from_record(rec)
    local base  = __base_from_record(rec)
    local cur   = __current_from_record(rec)

    -- A) pakai base dari record
    if base then
        return base * (1 + SCALE * 100)
    end

    -- B) proyeksi dari current + age
    if cur and age then
        local delta = math.max(0, 100 - age)
        return cur * (1 + SCALE * delta)
    end

    return nil
end

-- keputusan final: boleh jadi kandidat GBXP atau tidak
local function _norm_gbxp_fav_filter()
    local G = (getgenv and getgenv()) or _G
    local v = rawget(G, "GBXP_FAV_FILTER")
    if v == nil and type(G.STATE) == "table" then
        v = G.STATE.gbxpFavFilter
    end
    v = tostring(v or "unfav"):lower()
    if v == "fav" or v == "favorite" then return "fav" end
    if v == "all" then return "all" end
    return "unfav"
end

local function _is_gbxp_candidate(rec, uuid, petTypeNorm, fav)
    -- ambil config global kalau ada, kalau tidak pakai default
    local G = (getgenv and getgenv()) or _G
    local AGE_CUTOFF          = rawget(G, "AGE_CUTOFF")          or 1000
    local WEIGHT100_THRESHOLD = rawget(G, "WEIGHT100_THRESHOLD") or 250
    local favFilter = _norm_gbxp_fav_filter()

    if favFilter == "unfav" then
        if fav then return false end
    elseif favFilter == "fav" then
        if not fav then return false end
    end

    -- type whitelist
    if not _gbxp_whitelist_match(petTypeNorm) then
        return false
    end

    -- age check (<= AGE_CUTOFF, termasuk age 1000)
    local age = __age_from_record(rec)
    if not age or age > AGE_CUTOFF then
        return false
    end

    -- W100 check
    local w100 = _weight_at_100_for_rec(rec, uuid)
    if not w100 or w100 >= WEIGHT100_THRESHOLD then
        return false
    end

    -- tidak dipakai tab lain
    if _in_other_tabs(uuid) then
        return false
    end

    return true
end

-------------------------------------------------------------
-- Pet di Mutation Machine (UUID hilang dari bag → tetap tampil di GBXP)
-------------------------------------------------------------
local function __kg_from_machine_submitted(sp)
    if type(sp) ~= "table" then return nil end

    local kgNow = __current_from_record(sp)
    if kgNow then return kgNow end

    local age = __age_from_record(sp) or 0
    local base = __base_from_record(sp)
    if base then
        local scale = SCALE_PER_LVL or 0
        return base * (1 + scale * age)
    end

    return nil
end

-------------------------------------------------------------
-- Label 1 baris (SEMUA tab via listPetsForTab):
--   ⏳ ★ [Mut] PetName | Base1 X.XX KG | Age N | Y.YY KG | suffix
-------------------------------------------------------------
local function __format_pet_list_label(opts)
    opts = opts or {}
    local favTag = opts.fav and "★ " or ""
    local waitTag = opts.inMachine and "⏳ " or ""
    local mutPrefix = tostring(opts.mutPrefix or "")
    local petType = tostring(opts.petType or "Pet")
    local age = tonumber(opts.age) or 0
    local kgAtAge1 = tonumber(opts.kgAtAge1) or 0
    local kgNow = opts.kgNow

    local ageText = age > 0 and string.format("Age %d", age) or "Age ?"
    local base1Text = (kgAtAge1 > 0)
        and string.format("Base1 %.2f KG", kgAtAge1)
        or "Base1 ? KG"
    local kgText = kgNow and string.format("%.2f KG", kgNow) or "? KG"

    local label = string.format(
        "%s%s%s%s | %s | %s | %s",
        waitTag,
        favTag,
        mutPrefix,
        petType,
        base1Text,
        ageText,
        kgText
    )

    if opts.suffix and tostring(opts.suffix) ~= "" then
        label = label .. " | " .. tostring(opts.suffix)
    end
    return label
end

local function __mut_prefix_from_names(mutNames, rec)
    if type(mutNames) == "table" and #mutNames > 0 then
        return "[" .. table.concat(mutNames, ", ") .. "] "
    end
    if type(rec) == "table" then
        local mut = tostring(rec.MutationType or "")
        if mut ~= "" and mut ~= "None" and mut ~= "nil" then
            local mapped = MUT_CODE_TO_NAME[mut] or mut
            return "[" .. mapped .. "] "
        end
    end
    return ""
end

local function __format_submitted_machine_label(sp, suffix)
    sp = (type(sp) == "table") and sp or {}
    local petType = tostring(sp.PetType or sp.Type or sp.Name
        or (type(sp.PetData) == "table" and sp.PetData.PetType) or "Pet")
    local mutNames = __mutation_names_from_record(sp)
    return __format_pet_list_label({
        inMachine = true,
        mutPrefix = __mut_prefix_from_names(mutNames, sp),
        petType = petType,
        kgAtAge1 = __kg_at_age_from_record(sp, 1) or 0,
        age = tonumber(__age_from_record(sp)) or 0,
        kgNow = __kg_from_machine_submitted(sp),
        suffix = suffix or "IN MUT MACHINE",
    })
end

local function __getMutationMachineSubmittedPet()
    -- 1) API dulu (lebih konsisten setelah module load)
    local api = rawget(_G, "MutationMachineApi")
        or ((getgenv and getgenv()) or _G).MutationMachineApi
    if api and type(api.GetMachine) == "function" then
        local ok, machine = pcall(function() return api.GetMachine() end)
        if ok and type(machine) == "table" and type(machine.SubmittedPet) == "table" then
            return machine.SubmittedPet, machine
        end
    end

    -- 2) fallback DataService
    if DataService and type(DataService.GetData) == "function" then
        local ok, profile = pcall(function() return DataService:GetData() end)
        if ok and type(profile) == "table" and type(profile.PetMutationMachine) == "table" then
            local machine = profile.PetMutationMachine
            if type(machine.SubmittedPet) == "table" then
                return machine.SubmittedPet, machine
            end
        end
    end

    return nil, nil
end

local function __appendMutationMachinePets(pets)
    pets = pets or {}
    local seen = {}

    for _, p in ipairs(pets) do
        if p and p.uuid then
            local core = select(1, __normUUID(p.uuid))
            seen[tostring(p.uuid)] = true
            if core then seen[core] = true end
        end
    end

    local sp = __getMutationMachineSubmittedPet()
    if type(sp) ~= "table" then
        return pets
    end

    local rawUUID = sp.UUID or sp.uuid or sp.PetUUID or sp.Id
        or (type(sp.PetData) == "table" and (sp.PetData.UUID or sp.PetData.uuid))
    if not rawUUID then
        return pets
    end

    local core, br = __normUUID(rawUUID)
    local uuid = br or tostring(rawUUID)

    local petType = tostring(sp.PetType or sp.Type or sp.Name
        or (type(sp.PetData) == "table" and sp.PetData.PetType) or "Pet")
    local PD = (type(sp.PetData) == "table" and sp.PetData)
        or (type(sp.Data) == "table" and sp.Data)
        or {}
    local age = tonumber(__age_from_record(sp)) or tonumber(PD.Level) or tonumber(sp.Age) or tonumber(sp.age) or 0
    local kgNow = __kg_from_machine_submitted(sp)
    local kgAtAge1 = __kg_at_age_from_record(sp, 1) or 0
    if kgAtAge1 == 0 then
        kgAtAge1 = tonumber(PD.BaseWeight) or tonumber(sp.BaseWeight) or 0
    end
    if (not kgNow or kgNow == 0) and kgAtAge1 > 0 and age >= 0 then
        local scale = SCALE_PER_LVL or 0
        kgNow = kgAtAge1 * (1 + scale * age)
    end

    -- mutasi: utamakan EnumId dari PetData (mis. "d" = Shiny), jangan pecah nama
    local mutNames = {}
    local mutRaw = PD.MutationType or sp.MutationType
    if mutRaw ~= nil and tostring(mutRaw) ~= "" then
        local code = tostring(mutRaw):gsub("%s+", "")
        local mapped = (MUT_CODE_TO_NAME and MUT_CODE_TO_NAME[code]) or nil
        if mapped then
            mutNames[1] = mapped
        elseif #code == 1 then
            -- single enum miss
        else
            mutNames[1] = code
        end
    end
    if #mutNames == 0 then
        pcall(function()
            mutNames = __mutation_names_from_record(sp) or {}
        end)
    end
    local mutPrefix = ""
    if #mutNames > 0 then
        mutPrefix = "[" .. table.concat(mutNames, ", ") .. "] "
    end

    local label = __format_pet_list_label({
        inMachine = true,
        mutPrefix = mutPrefix,
        petType = petType,
        kgAtAge1 = kgAtAge1,
        age = age,
        kgNow = kgNow,
        suffix = "IN MUT MACHINE",
    })

    if seen[tostring(uuid)] or (core and seen[core]) or seen[tostring(rawUUID)] then
        -- sudah ada di list bag → update label/info machine
        for _, p in ipairs(pets) do
            if p and p.uuid then
                local pc = select(1, __normUUID(p.uuid))
                if (core and pc == core) or tostring(p.uuid) == tostring(uuid) then
                    p.name = label
                    p.inMachine = true
                    p.inMutationMachine = true
                    p.age = age
                    p.kg = kgNow or p.kg or 0
                    p.kgAtAge1 = kgAtAge1
                    p.muts = mutNames
                end
            end
        end
        return pets
    end

    table.insert(pets, {
        uuid = uuid,
        name = label,
        age  = age,
        kg   = kgNow or 0,
        kgAtAge1 = kgAtAge1,
        ptype = string.lower(petType),
        ptypeLabel = petType,
        fav  = false,
        muts = mutNames,
        inMachine = true,
        inMutationMachine = true,
    })

    return pets
end

-------------------------------------------------------------
-- 5) List pet per tab
-------------------------------------------------------------
local function listPetsForTab(tabKey)
    resolveGameModules()
    local pets = {}

    local bag = __getStoreBag()
    if not bag then
        -- bag belum ready: untuk GBXP tetap coba tampilkan pet di machine
        if tabKey == "gbxp" then
            return __appendMutationMachinePets(pets)
        end
        return pets
    end

    for rawUUID, rec in pairs(bag) do
        if type(rec) == "table" then
            local core, br = __normUUID(rawUUID)
            local uuid = br or core

            local fav = __is_favorite(rec) and true or false
            local PD  = rec.PetData or rec.Data or {}
            local mutNames = __mutation_names_from_record(rec)

            -- Ambil PetType
            local petTypeRaw =
                rec.Type or rec.PetType or
                PD.Type  or PD.PetType  or
                rec.Name or PD.Name     or
                "Pet"

            local petTypeLabel = tostring(petTypeRaw)
            local petTypeNorm  = petTypeLabel:lower()

            --------------------------------------------------------
            -- RULE FILTER PER TAB
            --------------------------------------------------------
            local allowed
            if tabKey == "gbxp" then
                -- whitelist type, fav filter (unfav/fav/all), age/W100, tidak di tab lain
                allowed = _is_gbxp_candidate(rec, uuid, petTypeNorm, fav)
            elseif tabKey == "agebreak" then
                -- Age Break: unfav saja (fav tidak bisa submit mesin)
                allowed = (fav ~= true)
            elseif tabKey == "main_pet" or tabKey == "bronto"
                or tabKey == "hatch_egg" or tabKey == "sell_pet" or tabKey == "boost"
                or tabKey == "xp" or tabKey == "seratusage" or tabKey == "noos" then
                -- Tab lain: hanya favorite
                allowed = (fav == true)
            elseif tabKey == "swap_skill" then
                allowed = (fav == true)
            else
                allowed = true
            end

            if allowed then
                -- Age / level sekarang
                local age = __age_from_record(rec) or 0

                -- BaseWeight dari datastore
                local base = __base_from_record(rec)

                -- KG sekarang
                local kgNow
                if base then
                    local lvl   = age or 0
                    local scale = SCALE_PER_LVL or 0
                    kgNow = base * (1 + scale * lvl)
                else
                    kgNow = __current_from_record(rec)
                end

                local mutNames  = __mutation_names_from_record(rec)
                local mutPrefix = __mut_prefix_from_names(mutNames, rec)
                local kgAtAge1 = __kg_at_age_from_record(rec, 1) or 0
                local label = __format_pet_list_label({
                    fav = fav,
                    mutPrefix = mutPrefix,
                    petType = petTypeLabel,
                    kgAtAge1 = kgAtAge1,
                    age = age,
                    kgNow = kgNow,
                })

                table.insert(pets, {
                    uuid   = uuid,
                    name   = label,
                    age    = age or 0,
                    kg     = kgNow or 0,
                    kgAtAge1 = kgAtAge1,
                    ptype  = petTypeNorm,
                    ptypeLabel = petTypeLabel,
                    fav    = fav,
                    muts = mutNames,
                })
            end
        end
    end

    if tabKey == "gbxp" then
        local okAppend, appended = pcall(__appendMutationMachinePets, pets)
        if okAppend and type(appended) == "table" then
            pets = appended
        end
    end

    table.sort(pets, function(a, b)
        local am = (a and (a.inMutationMachine or a.inMachine)) and 1 or 0
        local bm = (b and (b.inMutationMachine or b.inMachine)) and 1 or 0
        if am ~= bm then
            return am > bm -- pet di machine paling atas
        end
        if a.ptype == b.ptype then
            if a.age == b.age then
                return (a.kg or 0) < (b.kg or 0)
            end
            return (a.age or 0) < (b.age or 0)
        end
        return tostring(a.ptype or "") < tostring(b.ptype or "")
    end)

    return pets
end

local function buildPetItems()
    local list = {}

    for petName, cfg in pairs(PetList) do
        table.insert(list, {
            key   = petName,        -- dipakai sebagai key di selectedMap
            name  = petName,        -- teks di list
            right = cfg.Rarity,     -- optional: tampilkan rarity di kanan (kalau CreateRowDropdown support)
            icon  = cfg.Icon,       -- optional: kalau mau dipakai icon
                     -- simpan config full kalau perlu
        })
    end

    table.sort(list, function(a, b)
        return a.name < b.name
    end)

    return list
end



local function __getInventoryDataTable()
    if not DataService or type(DataService.GetData) ~= "function" then
        warn("[PetListView] DataService atau GetData tidak tersedia")
        return nil
    end

    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if not ok or type(profile) ~= "table" then
        warn("[PetListView] DataService:GetData() gagal / profile bukan table:", profile)
        return nil
    end

    local inv = profile.InventoryData
    if type(inv) ~= "table" then
        warn("[PetListView] profile.InventoryData kosong / bukan table")
        return nil
    end

    return inv
end


