-- return: eggs, stats, equippedPets
local function __getDataPlayerEggs()
    if not DataService or type(DataService.GetData) ~= "function" then
        return {}, { MaxEggsInFarm = 0, MaxEquippedPets = 0, MaxPetsInInventory = 0 }, nil
    end

    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if not ok or type(profile) ~= "table" then
        return {}, { MaxEggsInFarm = 0, MaxEquippedPets = 0, MaxPetsInInventory = 0 }, nil
    end

    local inv = profile.InventoryData

    ------------------------------------------------
    -- Kumpulkan egg di inventory
    ------------------------------------------------
    local eggs = {}
    if type(inv) == "table" then
        for guid, item in pairs(inv) do
            if type(item) == "table" and item.ItemType == "PetEgg" and type(item.ItemData) == "table" then
                local d = item.ItemData
                table.insert(eggs, {
                    uuid = guid,
                    name = d.EggName or "Egg",
                    uses = d.Uses or 0,
                })
            end
        end
    end

    ------------------------------------------------
    -- Ambil MutableStats dari PetsData (if any)
    ------------------------------------------------
    local stats = {
        MaxEggsInFarm       = 0,
        MaxEquippedPets     = 0,
        MaxPetsInInventory  = 0,
    }

    local petsData  = profile.PetsData
    local mutable   = petsData and petsData.MutableStats
    local petequip  = petsData and petsData.EquippedPets

    if type(mutable) == "table" then
        stats.MaxEggsInFarm      = mutable.MaxEggsInFarm      or 0
        stats.MaxEquippedPets    = mutable.MaxEquippedPets    or 0
        stats.MaxPetsInInventory = mutable.MaxPetsInInventory or 0
    end

    return eggs, stats, petequip
end

local function __getPetInventorySummary()
    if not DataService or type(DataService.GetData) ~= "function" then
        return 0, 0
    end

    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if not ok or type(profile) ~= "table" then
        return 0, 0
    end

    local petsData = profile.PetsData
    if type(petsData) ~= "table" then
        return 0, 0
    end

    local petInv = petsData.PetInventory
    local data   = petInv and petInv.Data

    local totalPets = 0
    if type(data) == "table" then
        for _ in pairs(data) do
            totalPets += 1
        end
    end

    local mutable = petsData.MutableStats
    local maxPets = 0
    if type(mutable) == "table" then
        maxPets = mutable.MaxPetsInInventory or 0
    end

    return totalPets, maxPets
end

local function __listEggPriorityItems()
