-------------------------------------------------------------
-- 8) FRUIT ITEMS (Backpack Tool): butuh Attribute c + f
-- - uuid  = tool:GetAttribute("c"/"C")
-- - fruit = tool:GetAttribute("f"/"F")   (nama buah)
-- - kg    = tool.Weight (NumberValue/IntValue) atau fallback
-------------------------------------------------------------
local function __get_tool_weight_kg(tool)
    if not tool then return nil end

    local function readValueBase(obj)
        if obj and obj:IsA("ValueBase") then
            local v = obj.Value
            if type(v) == "number" then return v end
            local n = tonumber(tostring(v))
            if n then return n end
        end
        return nil
    end

    -- A) Paling umum: Tool.Weight (NumberValue)
    local wObj = tool:FindFirstChild("Weight")
    local n = readValueBase(wObj)
    if n then return n end

    -- B) Kadang Weight ada di dalam Handle / folder lain
    local found = tool:FindFirstChild("Weight", true) -- recursive
    n = readValueBase(found)
    if n then return n end

    -- C) Optional fallback attribute (kalau suatu saat dev ubah)
    local aw = tool:GetAttribute("Weight") or tool:GetAttribute("weight") or tool:GetAttribute("KG") or tool:GetAttribute("kg")
    if aw ~= nil then
        local nn = __toNumberKG(aw)
        if nn then return nn end
    end

    return nil
end


-- format angka KG:
-- 0.2    -> 0.20
-- 12.34  -> 12.34
-- 999.9  -> 999.90
-- 1000   -> 1K
-- 80000  -> 80K
-- 1250000-> 1.25M
local function __fmtCompact(n)
    n = tonumber(n)
    if not n then return "?" end

    local abs = math.abs(n)
    local sign = (n < 0) and "-" or ""

    -- ✅ angka kecil JANGAN dibulatkan ke 0
    if abs < 1000 then
        -- selalu tampilkan 2 desimal
        local s = string.format("%.2f", abs)
        s = s:gsub("%.?0+$", "")       -- opsional: 12.00 -> 12
        return sign .. s
    end

    local value, suf
    if abs >= 1e12 then
        value, suf = abs / 1e12, "T"
    elseif abs >= 1e9 then
        value, suf = abs / 1e9, "B"
    elseif abs >= 1e6 then
        value, suf = abs / 1e6, "M"
    else
        value, suf = abs / 1e3, "K"
    end

    local s = string.format("%.2f", value)
    s = s:gsub("%.?0+$", "") -- trim 80.00 -> 80
    return sign .. s .. suf
end


local function __listFruitItemsFromBackpack()
    local out = {}

    for _, tool in ipairs(Backpack:GetChildren()) do
        if tool:IsA("Tool") then
            local cAttr = tool:GetAttribute("c") or tool:GetAttribute("C")
            local fAttr = tool:GetAttribute("f") or tool:GetAttribute("F")
            local wmAttr = tool:GetAttribute("WeightMulti")
                or tool:GetAttribute("weightMulti")
                or tool:GetAttribute("WeightMultiplier")
                or tool:GetAttribute("weightMultiplier")

            -- ✅ wajib ada c + f + weightmulti
            if cAttr and fAttr ~= nil and tostring(fAttr) ~= "" and wmAttr ~= nil then
                local core, br = __normUUID(cAttr)
                local uuid = br or core

                if uuid then
                    local fruitName = tostring(fAttr)
                    local kg = __get_tool_weight_kg(tool)

                    local kgText = kg and (__fmtCompact(kg) .. " KG") or "? KG"

                    table.insert(out, {
                        key   = uuid,                              -- ✅ save/load UUID (attr c)
                        fruit = fruitName,                         -- ✅ nama dari f
                        kg    = kg,                                -- ✅ tetap dari __get_tool_weight_kg
                        name  = string.format("%s | %s", fruitName, kgText),
                        tool  = tool,
                    })
                end
            end
        end
    end

    table.sort(out, function(a, b)
        if a.fruit == b.fruit then
            return (a.kg or 0) < (b.kg or 0)
        end
        return tostring(a.fruit) < tostring(b.fruit)
    end)

    return out
end

local function buildSeedItems()
    local list = {}

    if type(SeedData) ~= "table" then
        warn("[PetListView] SeedData bukan table:", typeof(SeedData))
        return list
    end

    for plantName, info in pairs(SeedData) do
        if type(info) == "table" then
            local seedNameRaw = info.SeedName or plantName
            local display = __stripSeedWord(seedNameRaw)

            table.insert(list, {
                key    = plantName,              -- ✅ key stabil (plant name)
                name   = display,                -- ✅ tampil tanpa "Seed"
                right  = info.SeedRarity,        -- opsional (rarity di kanan)
                icon   = info.FruitIcon or info.Asset, -- opsional icon
                raw    = info,                   -- simpan full info kalau perlu
            })
        end
    end

    -- Golden Egg: di-lay Golden Goose, sering tidak ada di SeedData
    do
        local function fruitKeyCanon(s)
            s = tostring(s or ""):lower()
            s = s:gsub("[^%w]+", "")
            return s
        end
        local hasGoldenEgg = false
        for _, it in ipairs(list) do
            if fruitKeyCanon(it.key) == "goldenegg" or fruitKeyCanon(it.name) == "goldenegg" then
                hasGoldenEgg = true
                break
            end
        end
        if not hasGoldenEgg then
            table.insert(list, {
                key   = "Golden Egg",
                name  = "Golden Egg",
                right = "Divine",
            })
        end
    end

    table.sort(list, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)

    return list
end


local M = {}

local function _isGBXPAutoSelect()
    local st = rawget(_G, "STATE")
    if type(st) == "table" and st.gbxpAutoSelect == false then
        return false
    end
    return true -- default AUTO kalau nil
end

local function _isUnlimitedMaxPetSelected()
    local st = rawget(_G, "STATE")
    local n = tonumber(type(st) == "table" and st.maxPetSelected) or 0
    return n <= 0
end

local function _countSet(t)
    local n = 0
    if type(t) == "table" then
        for _, on in pairs(t) do
            if on then n += 1 end
        end
    end
    return n
end

local function _agebreakPetTypeMatch(ptype, petTypes)
    if type(petTypes) ~= "table" then return true end
    local any = false
    for k, on in pairs(petTypes) do
        if on then
            any = true
            local pk = tostring(k):lower()
            local pt = tostring(ptype or ""):lower()
            if pk == pt then
                return true
            end
        end
    end
    return not any
end

local function _targetFinishSelesai(age, kg, maxAge, maxKg)
    age = tonumber(age) or 0
    kg  = tonumber(kg) or 0
    maxAge = tonumber(maxAge) or 0
    maxKg  = tonumber(maxKg) or 0
    if maxAge <= 0 then maxAge = 125 end
    if maxAge > 125 then maxAge = 125 end

    if age >= maxAge then return true end
    if maxKg > 0 and kg >= maxKg then return true end
    return false
end

local function _targetBelowFinishMax(age, kg, maxAge, maxKg)
    return not _targetFinishSelesai(age, kg, maxAge, maxKg)
end

function M.isAgeBreakFinishSelesai(age, kg, opts)
    opts = opts or {}
    local maxAge = tonumber(opts.maxAge) or 0
    local maxKg  = tonumber(opts.maxKg) or 0
    if maxAge <= 0 then maxAge = 125 end
    if maxAge > 125 then maxAge = 125 end
    return _targetFinishSelesai(age, kg, maxAge, maxKg)
end

local function _petMatchesAgeBreakFilter(p, opts)
    opts = opts or {}
    local minAge = tonumber(opts.minAge) or 100
    local maxAge = tonumber(opts.maxAge) or 0
    if maxAge <= 0 then maxAge = 125 end
    if minAge < 100 then minAge = 100 end
    if maxAge > 125 then maxAge = 125 end
    if minAge > maxAge then minAge = maxAge end
    local minKg  = tonumber(opts.minKg)  or 0
    local maxKg  = tonumber(opts.maxKg)  or 0
    local age = tonumber(p and p.age) or 0
    local kg  = tonumber(p and p.kg)  or 0
    local ageOk = age >= minAge and age >= 100 and age <= 125
    local kgOk  = kg >= minKg
    local belowMax = _targetBelowFinishMax(age, kg, maxAge, maxKg)
    return ageOk
        and kgOk
        and belowMax
        and _agebreakPetTypeMatch(p.ptype or p.ptypeLabel, opts.petTypes or {})
end

local function _isAgeBreakSelectedUUID(uuid, selectedSet)
    if type(selectedSet) ~= "table" or not uuid then return false end
    if selectedSet[uuid] then return true end
    local core = _normUUIDCore(uuid)
    if not core then return false end
    if selectedSet[core] then return true end
    if selectedSet["{" .. core .. "}"] then return true end
    return false
end

-- Pet yang sedang di mesin Age Break (UUID hilang dari PetInventory)
local function __kg_from_agebreak_submitted(sp)
    if type(sp) ~= "table" then return nil end

    local kgNow = __current_from_record(sp)
    if kgNow then return kgNow end

    local age = __age_from_record(sp) or 0
    local base = __base_from_record(sp)
    if base then
        local scale = SCALE_PER_LVL or 0
        return base * (1 + scale * age)
    end

    return nil
end

local function __appendAgeBreakMachinePets(pets)
    pets = pets or {}
    local seen = {}

    for _, p in ipairs(pets) do
        if p and p.uuid then
            local core = _normUUIDCore(p.uuid)
            seen[tostring(p.uuid)] = true
            if core then seen[core] = true end
        end
    end

    if not DataService or type(DataService.GetData) ~= "function" then
        return pets
    end

    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if not ok or type(profile) ~= "table" then
        return pets
    end

    local machine = profile.PetAgeBreakMachine
    if type(machine) ~= "table" or type(machine.SubmittedPet) ~= "table" then
        return pets
    end

    local sp = machine.SubmittedPet
    local rawUUID = sp.UUID or sp.uuid or sp.PetUUID
    if not rawUUID then
        return pets
    end

    local core = _normUUIDCore(rawUUID)
    local uuid = rawUUID
    if type(rawUUID) == "string" and not rawUUID:find("{") and core then
        uuid = "{" .. core .. "}"
    end

    if seen[tostring(uuid)] or (core and seen[core]) then
        return pets
    end

    local petType = tostring(sp.PetType or sp.Type or sp.Name or "Pet")
    local age = tonumber(__age_from_record(sp)) or 0
    local kgNow = __kg_from_agebreak_submitted(sp)

    local mutNames = __mutation_names_from_record(sp)
    local mutPrefix = __mut_prefix_from_names(mutNames, sp)
    local kgAtAge1 = __kg_at_age_from_record(sp, 1) or 0

    table.insert(pets, {
        uuid = uuid,
        name = __format_pet_list_label({
            inMachine = true,
            mutPrefix = mutPrefix,
            petType = petType,
            kgAtAge1 = kgAtAge1,
            age = age,
            kgNow = kgNow,
            suffix = "IN MACHINE",
        }),
        age  = age,
        kg   = kgNow or 0,
        kgAtAge1 = kgAtAge1,
        ptype = petType:lower(),
        ptypeLabel = petType,
        fav  = false,
        inMachine = true,
    })

    return pets
end

-- Filter kriteria target (loop auto / list UI)
function M.getAgeBreakAllPets()
    local pets = listPetsForTab("agebreak")
    return __appendAgeBreakMachinePets(pets)
end

function M.getAgeBreakFilterMatches(opts)
    return M.filterAgeBreakPets(M.getAgeBreakAllPets(), opts)
end

function M.filterAgeBreakPets(pets, opts)
    opts = opts or {}
    local out = {}
    for _, p in ipairs(pets or {}) do
        if _petMatchesAgeBreakFilter(p, opts) then
            out[#out + 1] = p
        end
    end
    return out
end

local function _parseSignedFilter(text)
    text = tostring(text or ""):gsub("%s+", "")
    if text == "" or text == "0" then
        return { mode = "off" }
    end
    local sign, numStr = text:match("^([+-]?)([%d%.]+)$")
    local num = numStr and tonumber(numStr) or tonumber(text)
    if num == nil then
        return { mode = "off" }
    end
    if sign == "-" then
        return { mode = "max", value = num }
    end
    return { mode = "min", value = num }
end

local function _valueMatchesSignedFilter(value, filterText)
    local f = _parseSignedFilter(filterText)
    if f.mode == "off" then return true end
    local v = tonumber(value) or 0
    if f.mode == "min" then return v >= f.value end
    if f.mode == "max" then return v <= f.value end
    return true
end

function M.parseSignedFilter(text)
    return _parseSignedFilter(text)
end

local function _petMatchesDupeFilter(p, opts)
    opts = opts or {}
    local age = tonumber(p and p.age) or 0
    local kgAt1 = tonumber(p and p.kgAtAge1) or tonumber(p and p.kg) or 0
    return _valueMatchesSignedFilter(age, opts.ageFilter)
        and _valueMatchesSignedFilter(kgAt1, opts.kgFilter)
        and _agebreakPetTypeMatch(p.ptype or p.ptypeLabel, opts.petTypes or {})
end

function M.getDupeFilterMatches(opts)
    local pets = M.getAgeBreakAllPets()
    local out = {}
    for _, p in ipairs(pets or {}) do
        if p.inMachine ~= true and p.fav ~= true and _petMatchesDupeFilter(p, opts) then
            out[#out + 1] = p
        end
    end
    return out
end

function M.buildEntriesForDupe(selectedSet, opts)
    selectedSet = selectedSet or {}
    opts = opts or {}

    local pets = M.getAgeBreakAllPets()
    local result = {}
    local seen = {}

    for _, p in ipairs(pets) do
        if p and p.uuid and p.inMachine ~= true and p.fav ~= true then
            local show =
                _petMatchesDupeFilter(p, opts)
                or _isAgeBreakSelectedUUID(p.uuid, selectedSet)

            if show and not seen[p.uuid] then
                seen[p.uuid] = true
                result[#result + 1] = {
                    key  = p.uuid,
                    name = p.name,
                }
            end
        end
    end

    return result
end

function M.buildEntriesForAgeBreak(selectedSet, opts)
    selectedSet = selectedSet or {}
    opts = opts or {}

    local pets = listPetsForTab("agebreak")
    pets = __appendAgeBreakMachinePets(pets)

    local result = {}
    local seen = {}

    for _, p in ipairs(pets) do
        if p and p.uuid and p.fav ~= true then
            local show =
                _petMatchesAgeBreakFilter(p, opts)
                or p.inMachine == true
                or _isAgeBreakSelectedUUID(p.uuid, selectedSet)

            if show and not seen[p.uuid] then
                seen[p.uuid] = true
                result[#result + 1] = {
                    key  = p.uuid,
                    name = p.name,
                }
            end
        end
    end

    return result
end

function M.buildEntriesForTab(tabKey, selectedSet)
    resolveGameModules()
    selectedSet = selectedSet or {}

    if tabKey == "agebreak" then
        local G = (getgenv and getgenv()) or _G
        local MAIN = rawget(G, "MAIN") or _G.MAIN
        local st = MAIN and MAIN.agebreak and MAIN.agebreak.state
        return M.buildEntriesForAgeBreak(selectedSet, {
            minAge   = tonumber(G.AGEBREAK_MIN_AGE or (st and st.minAge)) or 0,
            minKg    = tonumber(G.AGEBREAK_MIN_KG  or (st and st.minKg))  or 0,
            maxAge   = tonumber(G.AGEBREAK_MAX_AGE or (st and st.maxAge)) or 0,
            maxKg    = tonumber(G.AGEBREAK_MAX_KG  or (st and st.maxKg))  or 0,
            petTypes = G.AGEBREAK_PET_TYPES or (st and st.petTypes) or {},
        })
    end

    -- listPetsForTab(tabKey) milikmu: untuk "gbxp" biasanya sudah return kandidat (non-fav)
    local pets = listPetsForTab(tabKey)

    ----------------------------------------------------------------
    -- KHUSUS GBXP: AUTO/MANUAL + PRUNE
    ----------------------------------------------------------------
    if tabKey == "gbxp" then
        -- Build set kandidat valid dari pets yang ditampilkan
        local valid = {}
        for _, p in ipairs(pets) do
            if p and p.uuid then
                local core, br = __normUUID(p.uuid)
                valid[tostring(p.uuid)] = true
                if br then valid[br] = true end
                if core then valid[core] = true end
            end
        end

        local function _inValid(uuid)
            if not uuid then return false end
            if valid[uuid] then return true end
            local core, br = __normUUID(uuid)
            return (br and valid[br]) or (core and valid[core]) or false
        end

        local function _isInMutMachine(uuid)
            local api = rawget(_G, "MutationMachineApi") or ((getgenv and getgenv()) or _G).MutationMachineApi
            if api and type(api.IsPetInMachine) == "function" then
                local ok, v = pcall(function() return api.IsPetInMachine(uuid) end)
                return ok and v == true
            end
            return false
        end

        -- Keep during claim remap window (manual mode tidak auto-add lagi)
        local function _keepGbxpSelected(uuid)
            if _isInMutMachine(uuid) then return true end
            local core = select(1, __normUUID(uuid))
            if not core then return false end

            local Genv = (getgenv and getgenv()) or _G
            local grace = rawget(_G, "__GBXP_REMAP_GRACE") or rawget(Genv, "__GBXP_REMAP_GRACE")
            if type(grace) == "table" and grace.core and tostring(grace.core) == tostring(core) then
                if tick() <= (tonumber(grace.untilAt) or 0) then
                    return true
                end
            end

            local st = rawget(_G, "STATE") or rawget(Genv, "STATE")
            local pc = st and st._gbxpMutPending
            if type(pc) == "table" and pc.oldCore and tostring(pc.oldCore) == tostring(core) then
                return true
            end
            return false
        end

        -- (A) PRUNE: hapus selected invalid, kecuali machine / remap grace / pending claim
        -- Bag belum ready: jangan wipe manual selection (UUID pet di machine hilang dari inventory)
        local bag = __getStoreBag()
        local bagReady = type(bag) == "table" and next(bag) ~= nil
        if bagReady then
            for uuid, on in pairs(selectedSet) do
                if on and not _inValid(uuid) then
                    if not _keepGbxpSelected(uuid) then
                        selectedSet[uuid] = nil
                    end
                end
            end
        end

        -- (B) AUTO-ADD: Max Pet Selected 0 = select semua kandidat (tanpa cek stage)
        if isAuto and _isUnlimitedMaxPetSelected() then
            for _, p in ipairs(pets) do
                if p and p.uuid then
                    local core = select(1, __normUUID(p.uuid))
                    local already = selectedSet[p.uuid]
                        or (core and (selectedSet[core] or selectedSet["{" .. core .. "}"]))
                    if not already then
                        selectedSet[p.uuid] = true
                    end
                end
            end
        end

        -- (C) MANUAL mode: tidak auto isi apapun (biarkan user pilih)
    end

    ----------------------------------------------------------------
    -- BUILD RESULT UNTUK UI LIST
    ----------------------------------------------------------------
    local result = {}
    local resultSeen = {}
    for _, p in ipairs(pets) do
        if p and p.uuid then
            local core = select(1, __normUUID(p.uuid))
            resultSeen[tostring(p.uuid)] = true
            if core then resultSeen[core] = true end

            local isMachine = (p.inMutationMachine or p.inMachine) == true
            -- pet di machine harus tetap selected di GBXP (manual/auto)
            if tabKey == "gbxp" and isMachine and type(selectedSet) == "table" then
                selectedSet[p.uuid] = true
                if core then
                    selectedSet[core] = true
                    selectedSet["{" .. core .. "}"] = true
                end
            end

            table.insert(result, {
                key  = p.uuid,
                name = p.name,
                selected = (tabKey == "gbxp" and isMachine) or nil,
                on = (tabKey == "gbxp" and isMachine) or nil,
                inMachine = isMachine or nil,
                inMutationMachine = isMachine or nil,
            })
        end
    end

    -- Safety: selected GBXP yang sedang di machine harus tetap ada di list UI
    if tabKey == "gbxp" and type(selectedSet) == "table" then
        local sp = __getMutationMachineSubmittedPet()
        if type(sp) == "table" then
            local rawUUID = sp.UUID or sp.uuid or sp.PetUUID or sp.Id
                or (type(sp.PetData) == "table" and (sp.PetData.UUID or sp.PetData.uuid))
            local core, br = __normUUID(rawUUID)
            local uuid = br or (rawUUID and tostring(rawUUID)) or nil
            if uuid then
                -- selalu force-select machine UUID (walau sudah ada di result)
                selectedSet[uuid] = true
                if core then
                    selectedSet[core] = true
                    selectedSet["{" .. core .. "}"] = true
                end
                if not resultSeen[uuid] and not (core and resultSeen[core]) then
                    local petType = tostring(sp.PetType or sp.Type or sp.Name or "Pet")
                    local age = tonumber(__age_from_record(sp)) or 0
                    local kgNow = __kg_from_machine_submitted(sp)
                    local mutNames = __mutation_names_from_record(sp)
                    local kgAtAge1 = __kg_at_age_from_record(sp, 1) or 0
                    table.insert(result, 1, {
                        key = uuid,
                        name = __format_pet_list_label({
                            inMachine = true,
                            mutPrefix = __mut_prefix_from_names(mutNames, sp),
                            petType = petType,
                            kgAtAge1 = kgAtAge1,
                            age = age,
                            kgNow = kgNow,
                            suffix = "IN MUT MACHINE",
                        }),
                        selected = true,
                        on = true,
                        inMachine = true,
                        inMutationMachine = true,
                    })
                else
                    -- entry sudah ada: tandai selected biar CreateRowList tidak miss
                    for _, e in ipairs(result) do
                        if e and e.key then
                            local ec = select(1, __normUUID(e.key))
                            if (core and ec == core) or tostring(e.key) == tostring(uuid) then
                                e.selected = true
                                e.on = true
                                e.inMachine = true
                                e.inMutationMachine = true
                            end
                        end
                    end
                end
            end
        end
    end

    return result
end

