local function __findToolByInventoryUUID(coreUUID)
    if not coreUUID then return nil end

    local containers = {
        LocalPlayer:FindFirstChild("Backpack"),
        LocalPlayer.Character,
    }

    for _, container in ipairs(containers) do
        if container then
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") then

                    local attr =
                        tool:GetAttribute("c")
                        or tool:GetAttribute("C")
                        or tool:GetAttribute("UUID")
                        or tool:GetAttribute("uuid")

                    local attrCore = __normUUID(attr)

                    if attrCore == coreUUID then
                        return tool
                    end
                end
            end
        end
    end

    return nil
end

-------------------------------------------------------------
-- RESOLVE LABEL BERDASARKAN ITEM TYPE
-------------------------------------------------------------
local function __resolveInventoryItem(rec, toolName)

    local itemType = tostring(rec.ItemType or "Item")
    local data = rec.ItemData or {}

    local out = {
        itemType = itemType,
        itemName = toolName or itemType,
        amountText = nil,
    }

    ---------------------------------------------------------
    -- SPRINKLER
    ---------------------------------------------------------
    if itemType == "Sprinkler" then

        out.itemName =
            data.ItemName
            or toolName
            or "Sprinkler"

        out.amountText =
            "Uses " .. tostring(data.Uses or 0)

    ---------------------------------------------------------
    -- SEED
    ---------------------------------------------------------
    elseif itemType == "Seed" then

        out.itemName =
            data.ItemName
            or toolName
            or "Seed"

        out.amountText =
            "Qty " .. tostring(data.Quantity or 0)

    ---------------------------------------------------------
    -- PET EGG
    ---------------------------------------------------------
    elseif itemType == "PetEgg" then

        out.itemName =
            data.EggName
            or toolName
            or "Pet Egg"

        out.amountText =
            "Uses " .. tostring(data.Uses or 0)

    ---------------------------------------------------------
    -- PET SHARD
    ---------------------------------------------------------
    elseif itemType == "PetShard" then

        out.itemName =
            data.ShardType
            or toolName
            or "Pet Shard"

        out.amountText =
            "Uses " .. tostring(data.Uses or 0)

    ---------------------------------------------------------
    -- COSMETIC CRATE
    ---------------------------------------------------------
    elseif itemType == "CosmeticCrate" then

        out.itemName =
            data.CrateType
            or toolName
            or "Crate"

        out.amountText =
            "Uses " .. tostring(data.Uses or 0)

    ---------------------------------------------------------
    -- DEFAULT
    ---------------------------------------------------------
    else

        out.itemName =
            data.ItemName
            or toolName
            or itemType

        if data.Quantity then
            out.amountText = "Qty " .. tostring(data.Quantity)

        elseif data.Uses then
            out.amountText = "Uses " .. tostring(data.Uses)
        end
    end

    return out
end

