-- MAIN INVENTORY ITEM LIST
-------------------------------------------------------------
function buildInventoryItemsByType(itemType, opts)

    opts = opts or {}

    local result = {}

    local inv = __getInventoryDataTable()
    if type(inv) ~= "table" then
        return result
    end

    local wanted = tostring(itemType or ""):lower()

    for rawUUID, rec in pairs(inv) do

        if type(rec) == "table" then

            local recType =
                tostring(rec.ItemType or ""):lower()

            if wanted == "" or recType == wanted then

                local core, br = __normUUID(rawUUID)

                local tool =
                    __findToolByInventoryUUID(core)

                if not opts.onlyBackpack or tool then

                    local resolved =
                        __resolveInventoryItem(
                            rec,
                            tool and tool.Name
                        )

                    local label

                    if resolved.amountText then
                        label = string.format(
                            "%s | %s | %s",
                            tostring(resolved.itemName),
                            tostring(resolved.amountText),
                            tostring(resolved.itemType)
                        )
                    else
                        label = string.format(
                            "%s | %s",
                            tostring(resolved.itemName),
                            tostring(resolved.itemType)
                        )
                    end

                    table.insert(result, {
                        key       = br or core,
                        uuid      = br or core,
                        coreUUID  = core,

                        name      = label,

                        itemName  = resolved.itemName,
                        itemType  = resolved.itemType,
                        amount    = resolved.amountText,

                        tool      = tool,
                        raw       = rec,
                    })
                end
            end
        end
    end

    table.sort(result, function(a, b)
        return tostring(a.itemName) < tostring(b.itemName)
    end)

    return result
end


local function __listFruitMutations()
    local out = {}
    local seen = {}

    local function addMutation(m)
        if type(m) ~= "table" then return end

        local name = m.Name or m.name
        if type(name) ~= "string" or name == "" then return end

        if seen[name] then return end
        seen[name] = true

        table.insert(out, {
            key   = name,
            name  = name,
            multi = m.ValueMulti or m.valueMulti or m.Multiplier,
            id    = m.Id or m.ID or m.EnumId,
        })
    end

    if MutationHandler and type(MutationHandler.GetMutations) == "function" then
        local ok, muts = pcall(function()
            return MutationHandler:GetMutations()
        end)

        if ok and type(muts) == "table" then
            -- support array
            for _, m in ipairs(muts) do
                addMutation(m)
            end

            -- support dictionary/map
            for mutName, m in pairs(muts) do
                if type(m) == "table" then
                    if not m.Name then
                        m.Name = tostring(mutName)
                    end
                    addMutation(m)
                end
            end
        end
    end

    table.sort(out, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)

    return out
end

