local function __listFruitVariants()
    local out = {}

    if type(VariantEnums) ~= "table" then
        return out
    end

    for variantName, order in pairs(VariantEnums) do
        table.insert(out, {
            key = variantName,
            name = variantName,
            order = tonumber(order) or 999,
        })
    end

    table.sort(out, function(a, b)
        if a.order == b.order then
            return tostring(a.name) < tostring(b.name)
        end
        return a.order < b.order
    end)

    return out
end

