-- Helper dropdown crafting (registry game), terpisah dari PetListView.
-- List resep hanya untuk mesin yang punya instance di map.

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace         = game:GetService("Workspace")

local M = {}

local LocalPlayer = Players.LocalPlayer

-- Nama model di map ≠ key registry
local MODEL_NAME_TO_OBJECT_TYPE = {
    DinoCraftingTable          = "DinoEventWorkbench",
    EventCraftingWorkBench     = "GearEventWorkbench",
    SeedEventCraftingWorkBench = "SeedEventWorkbench",
    GiantCraftingWorkBench     = "GiantBeanstalkEventWorkbench",
}

