    instances = 45,
    stock     = 10,
    recipes   = 20,
}

local _cache = {
    instances = { at = 0, list = {}, typeSet = {} },
    stock     = { at = 0, data = {} },
    recipes   = { at = 0, list = {} },
}

local function _cacheFresh(entry, ttl)
    return entry and (os.clock() - (entry.at or 0)) < ttl
end

function M.invalidateCache()
    _cache.instances.at = 0
    _cache.stock.at = 0
    _cache.recipes.at = 0
end

local function _scanRootsForAttributes(add, roots)
    for _, root in ipairs(roots) do
        if not root then continue end
        for _, inst in ipairs(root:GetDescendants()) do
            local otype = inst:GetAttribute("CraftingObjectType")
            if otype then
                add(inst, otype, inst:GetAttribute("CraftingObjectId"), "attribute")
            end
        end
    end
end

local function _compareIndex(a, b)
    local na, nb = tonumber(a), tonumber(b)
    if na and nb then return na < nb end
    return tostring(a) < tostring(b)
end

local function _safeRequire(path)
    local ok, mod = pcall(function()
        return require(path)
    end)
    if ok then return mod end
    return nil
end

