local function _looksLikeRecipe(tbl)
    if type(tbl) ~= "table" then return false end
    for _, key in ipairs({ "SlotInputs", "InputSlots", "Inputs", "Ingredients", "Output", "Result" }) do
        if tbl[key] ~= nil then return true end
    end
    return false
end

local function _flattenItemRecipes(source)
    local flat = {}
    if type(source) ~= "table" then return flat end

    for key, val in pairs(source) do
        if _looksLikeRecipe(val) then
            flat[tostring(key)] = val
        elseif type(val) == "table" then
            for subKey, subVal in pairs(val) do
                if _looksLikeRecipe(subVal) then
                    flat[tostring(subKey)] = subVal
                elseif type(subVal) == "table" then
                    for deepKey, deepVal in pairs(subVal) do
                        if _looksLikeRecipe(deepVal) then
                            flat[tostring(deepKey)] = deepVal
                        end
                    end
                end
            end
        end
    end

    if next(flat) == nil then
        for key, val in pairs(source) do
            if type(val) == "table" then
                flat[tostring(key)] = val
            end
        end
    end

    return flat
end

local function _categoryMatchesMachine(categoryKey, objectType)
    categoryKey = tostring(categoryKey or ""):lower()
    objectType = tostring(objectType or ""):lower()
    if categoryKey == "" or objectType == "" then return false end
    if categoryKey == objectType then return true end

    local stem = _objectTypeStem(objectType)
    if stem ~= "" and (categoryKey:find(stem, 1, true) or stem:find(categoryKey, 1, true)) then
        return true
    end
    return false
end

local function _collectNestedCategoryRecipes(recipeReg, availableTypes)
    local out = {} -- recipeId -> objectType
    if type(recipeReg) ~= "table" then return out end

    local source = recipeReg.ItemRecipes
    if type(source) ~= "table" then return out end

    for categoryKey, categoryVal in pairs(source) do
        if type(categoryVal) == "table" and not _looksLikeRecipe(categoryVal) then
            for objectType in pairs(availableTypes) do
                if _categoryMatchesMachine(categoryKey, objectType) then
                    for recipeId, recipe in pairs(categoryVal) do
                        if _looksLikeRecipe(recipe) or type(recipe) == "table" then
                            out[tostring(recipeId)] = objectType
                        end
                    end
                end
            end
        end
    end

    return out
end

local function _recipeDisplayName(recipeId, recipe)
    if type(recipe) == "table" then
        local dn = recipe.DisplayName or recipe.Name
        if dn and tostring(dn) ~= "" then
            return tostring(dn)
        end
    end
    return tostring(recipeId)
end

local function _firstListedMachineType(recipe)
    if type(recipe) ~= "table" then return nil end
    for _, field in ipairs({ "MachineTypes", "CraftingObjectTypes", "ObjectTypes" }) do
        local arr = recipe[field]
        if type(arr) == "table" then
            if arr[1] ~= nil and tostring(arr[1]) ~= "" then
                return tostring(arr[1])
            end
            for _, v in pairs(arr) do
                if v ~= nil and tostring(v) ~= "" then
                    return tostring(v)
                end
            end
        end
    end
    return nil
end

local function _directRecipeMachineType(recipe)
    if type(recipe) ~= "table" then return nil end
    local mt = recipe.MachineType or recipe.CraftingObjectType or recipe.ObjectType
    if mt and tostring(mt) ~= "" then
        return tostring(mt)
    end
    return _firstListedMachineType(recipe)
end

local function _resolveRecipeMachineType(recipe, typeReg)
    local direct = _directRecipeMachineType(recipe)
    if direct then return direct end
    if type(recipe) ~= "table" or type(typeReg) ~= "table" then return nil end

    local ct = recipe.CraftingType or recipe.Type
    if not ct then return nil end

    local td = typeReg[ct] or typeReg[tostring(ct)]
    if type(td) ~= "table" then return nil end

    local ot = td.CraftingObjectType or td.ObjectType or td.MachineType
    if ot and tostring(ot) ~= "" then
        return tostring(ot)
    end
    return nil
end

local function _collectRecipeIdsFromBlock(block, out)
    if type(block) ~= "table" then return end
    for k, v in pairs(block) do
        if type(v) == "string" or type(v) == "number" then
            out[tostring(v)] = true
            if type(k) == "string" or type(k) == "number" then
                out[tostring(k)] = true
            end
        elseif type(v) == "table" then
            local rid = v.RecipeId or v.Name or v.Id or v.id or k
            if rid then out[tostring(rid)] = true end
        elseif type(k) == "string" or type(k) == "number" then
            out[tostring(k)] = true
        end
    end
end

local function _objectTypeStem(objectType)
    objectType = tostring(objectType or "")
    return objectType:gsub("Workbench$", ""):gsub("Table$", ""):lower()
end

local function _recipeReferencesMachine(recipe, recipeId, objectType, objectReg, typeReg)
    objectType = tostring(objectType or "")
    if objectType == "" then return false end

    if type(recipe) == "table" then
        for _, field in ipairs({
            "MachineType", "CraftingObjectType", "ObjectType",
            "Workbench", "WorkbenchType",
        }) do
            if tostring(recipe[field] or "") == objectType then
                return true
            end
        end

        for _, field in ipairs({ "CraftingObjectTypes", "ObjectTypes", "MachineTypes" }) do
            local arr = recipe[field]
            if type(arr) == "table" then
                for _, v in pairs(arr) do
                    if tostring(v) == objectType then return true end
                end
            end
        end

        local rct = recipe.CraftingType or recipe.Type
        if rct then
            rct = tostring(rct)
            if type(objectReg) == "table" then
                local mdef = objectReg[objectType]
                local mct = type(mdef) == "table" and (mdef.CraftingType or mdef.Type)
                if mct and tostring(mct) == rct then return true end
            end
            if type(typeReg) == "table" then
                local td = typeReg[rct] or typeReg[tostring(rct)]
                if type(td) == "table" then
                    local ot = td.CraftingObjectType or td.ObjectType or td.MachineType
                    if tostring(ot) == objectType then return true end
                end
            end
            local stem = _objectTypeStem(objectType)
            local rctLower = rct:lower()
            if stem ~= "" and (stem:find(rctLower, 1, true) or rctLower:find(stem, 1, true)) then
                return true
            end
        end
    end

    local rid = tostring(recipeId or ""):lower()
    local stem = _objectTypeStem(objectType)
    if stem ~= "" and rid:find(stem, 1, true) then
        return true
    end

    return false
end

local function _getMachineCraftTypes(objectType, objectReg, typeReg)
    local types = {}
    objectType = tostring(objectType or "")
    if objectType == "" then return types end

    types[objectType:lower()] = true
    local stem = _objectTypeStem(objectType)
    if stem ~= "" then types[stem] = true end

    local mdef = objectReg and objectReg[objectType]
    if type(mdef) == "table" then
        for _, key in ipairs({ "CraftingType", "Type", "EventType", "Category" }) do
            local v = mdef[key]
            if v then types[tostring(v):lower()] = true end
        end
    end

    if type(typeReg) == "table" then
        for typeKey, typeDef in pairs(typeReg) do
            if type(typeDef) == "table" then
                local ot = typeDef.CraftingObjectType or typeDef.ObjectType or typeDef.MachineType or typeKey
                if tostring(ot) == objectType then
                    types[tostring(typeKey):lower()] = true
                    for _, key in ipairs({ "CraftingType", "Type", "EventType", "Category" }) do
                        local v = typeDef[key]
                        if v then types[tostring(v):lower()] = true end
                    end
                end
            end
        end
    end

    return types
end

local function _harvestTypeRegistryRecipes(objectType, typeReg, recipes)
    local out = {}
    if type(typeReg) ~= "table" or type(recipes) ~= "table" then return out end

    local function recipeExists(id)
        id = tostring(id or "")
        return id ~= "" and (recipes[id] ~= nil or recipes[id:gsub("^%s+", "")] ~= nil)
    end

    local function scanNode(node, depth)
        if depth > 6 or type(node) ~= "table" then return end
        for k, v in pairs(node) do
            if recipeExists(k) then
                out[tostring(k)] = true
            end
            if type(v) == "string" and recipeExists(v) then
                out[tostring(v)] = true
            end
            if type(v) == "table" then
                local rid = v.RecipeId or v.Name or v.Id
                if rid and recipeExists(rid) then
                    out[tostring(rid)] = true
                end
                scanNode(v, depth + 1)
            end
        end
    end

    for typeKey, typeDef in pairs(typeReg) do
        if type(typeDef) == "table" then
            local ot = typeDef.CraftingObjectType or typeDef.ObjectType or typeDef.MachineType or typeKey
            if tostring(ot) == objectType then
                scanNode(typeDef, 0)
            end
        end
    end

    local direct = typeReg[objectType]
    if type(direct) == "table" then
        scanNode(direct, 0)
    end

    return out
end

local function _recipeMatchesMachineTypes(recipe, craftTypes)
    if type(recipe) ~= "table" or type(craftTypes) ~= "table" then return false end
    for _, key in ipairs({ "CraftingType", "Type", "EventType", "Category" }) do
        local v = recipe[key]
        if v and craftTypes[tostring(v):lower()] then
            return true
        end
    end
    return false
end

local function _collectRegistryRecipesForMachine(objectType, recipeReg, objectReg)
    local out = {}
    objectType = tostring(objectType or "")
    if objectType == "" then return out end

    if type(recipeReg) == "table" then
        local section = recipeReg[objectType]
        if type(section) == "table" then
            for recipeId in pairs(section) do
                out[tostring(recipeId)] = true
            end
        end

        local sorted = recipeReg.RecipiesSortedByMachineType or recipeReg.RecipesSortedByMachineType
        if type(sorted) == "table" then
            local bucket = sorted[objectType] or sorted[tostring(objectType)]
            if type(bucket) == "table" then
                for recipeId in pairs(bucket) do
                    out[tostring(recipeId)] = true
                end
            end
        end
    end

    if type(objectReg) == "table" then
        local def = objectReg[objectType]
        if type(def) == "table" then
            for _, key in ipairs({
                "Recipes", "ItemRecipes", "AllowedRecipes",
                "CraftableRecipes", "RecipeList", "AllowedItemRecipes",
            }) do
                _collectRecipeIdsFromBlock(def[key], out)
            end
        end
    end

    return out
end

local function _buildRecipesByMachine(allRecipes, objectReg, typeReg)
    local map = {} -- objectType -> { [recipeId]=true }

    local function ensure(ot)
        ot = tostring(ot or "")
        if ot == "" then return nil end
        map[ot] = map[ot] or {}
        return map[ot]
    end

    if type(allRecipes) == "table" then
        for recipeId, recipe in pairs(allRecipes) do
            local rid = tostring(recipeId)
            local ot = _resolveRecipeMachineType(recipe, typeReg)
            if ot then
                ensure(ot)[rid] = true
            end
        end
    end

    if type(typeReg) == "table" then
        for typeKey, typeDef in pairs(typeReg) do
            if type(typeDef) == "table" then
                local ot = typeDef.CraftingObjectType or typeDef.ObjectType or typeDef.MachineType
                    or typeKey
                if ot then
                    local bucket = ensure(ot)
                    for _, key in ipairs({ "Recipes", "ItemRecipes", "AllowedRecipes", "CraftableRecipes" }) do
                        _collectRecipeIdsFromBlock(typeDef[key], bucket)
                    end
                end
            end
        end
    end

    if type(objectReg) == "table" then
        for objectType, def in pairs(objectReg) do
            if type(def) == "table" then
                local bucket = ensure(objectType)
                for _, key in ipairs({ "Recipes", "ItemRecipes", "AllowedRecipes", "CraftableRecipes" }) do
                    _collectRecipeIdsFromBlock(def[key], bucket)
                end

                local ctype = def.CraftingType or def.Type
                if ctype and type(typeReg) == "table" then
                    local td = typeReg[ctype] or typeReg[tostring(ctype)]
                    if type(td) == "table" then
                        for _, key in ipairs({ "Recipes", "ItemRecipes", "AllowedRecipes", "CraftableRecipes" }) do
                            _collectRecipeIdsFromBlock(td[key], bucket)
                        end
                    end
                end
            end
        end
    end

    return map
end

local function _registryNameHints(objectType, def)
    local hints = { tostring(objectType) }
    if type(def) == "table" then
        for _, key in ipairs({
            "ModelName", "InstanceName", "PrefabName",
            "DisplayName", "Name", "TemplateName",
        }) do
            local v = def[key]
            if v and tostring(v) ~= "" then
                table.insert(hints, tostring(v))
            end
        end
    end
    return hints
end

local function _resolveObjectTypeFromModelName(modelName, objectReg)
    modelName = tostring(modelName or "")
    if modelName == "" then return nil end

    local alias = MODEL_NAME_TO_OBJECT_TYPE[modelName]
    if alias then return alias end

    if type(objectReg) == "table" then
        for objectType, def in pairs(objectReg) do
            for _, hint in ipairs(_registryNameHints(objectType, def)) do
                if hint == modelName then
                    return tostring(objectType)
                end
            end
        end
    end

    return nil
end

local function _scanCraftingInstances(force)
    if not force and _cacheFresh(_cache.instances, CACHE_TTL.instances) then
        return _cache.instances.list, _cache.instances.typeSet
    end

    local list = {}
    local seenPath = {}
    local typeSet = {}

    local function add(inst, objectType, objectId, source)
        if not inst then return end
        objectType = tostring(objectType or "")
        if objectType == "" then return end

        local path = inst:GetFullName()
        if seenPath[path] then return end
        seenPath[path] = true
        typeSet[objectType] = true

        table.insert(list, {
            instance   = inst,
            path       = path,
            objectId   = tostring(objectId or inst:GetAttribute("CraftingObjectId") or objectType),
            objectType = objectType,
            source     = source or "scan",
        })
    end

    -- 1) Scan terarah — bukan seluruh Workspace/ReplicatedStorage
    local scanRoots = {}
    local craftingTables = Workspace:FindFirstChild("CraftingTables")
    if craftingTables then
        table.insert(scanRoots, craftingTables)
    end

    local npcs = Workspace:FindFirstChild("NPCS")
    local npcTables = npcs and npcs:FindFirstChild("CraftingTables")
    if npcTables then
        table.insert(scanRoots, npcTables)
    end

    local interaction = Workspace:FindFirstChild("Interaction")
    if interaction then
        table.insert(scanRoots, interaction:FindFirstChild("CraftingTable") or interaction)
    end

    if #scanRoots == 0 then
        table.insert(scanRoots, Workspace)
    end

    local modules = ReplicatedStorage:FindFirstChild("Modules")
    local updateSvc = modules and modules:FindFirstChild("UpdateService")
    if updateSvc then
        for _, folderName in ipairs({ "DinoEvent", "SeedEvent", "GearEvent" }) do
            local folder = updateSvc:FindFirstChild(folderName)
            if folder then
                table.insert(scanRoots, folder)
            end
        end
    end

    _scanRootsForAttributes(add, scanRoots)

    -- 2) Fallback: model dari registry / UpdateService (FindFirstChild, bukan GetDescendants)
    local objectReg = _getObjectRegistry()
    if type(objectReg) == "table" then
        for objectType, def in pairs(objectReg) do
            if not typeSet[tostring(objectType)] then
                local hints = _registryNameHints(objectType, def)
                for _, hint in ipairs(hints) do
                    local found = (craftingTables and craftingTables:FindFirstChild(hint, true))
                        or (updateSvc and updateSvc:FindFirstChild(hint, true))
                        or Workspace:FindFirstChild(hint, true)
                    if found then
                        add(found, objectType, nil, "registry_model")
                        break
                    end
                end
            end
        end
    end

    if updateSvc and type(objectReg) == "table" then
        for modelName, objectType in pairs(MODEL_NAME_TO_OBJECT_TYPE) do
            if not typeSet[objectType] then
                local found = updateSvc:FindFirstChild(modelName, true)
                if found then
                    add(found, objectType, nil, "update_service")
                end
            end
        end
    end

    -- 3) Fallback: hasil scan executor sebelumnya
    local scan = _G.CRAFT_SCAN_RESULT
    if type(scan) == "table" and type(scan.instances) == "table" then
        for _, instInfo in ipairs(scan.instances) do
            if type(instInfo) == "table" and instInfo.instance and instInfo.objectType then
                add(instInfo.instance, instInfo.objectType, instInfo.objectId, "craft_scan_result")
            end
        end
    end

    -- Prioritas: instance aktif di Workspace.CraftingTables (bukan cutscene template)
    local activeList, activeSet = {}, {}
    for _, inst in ipairs(list) do
        if inst.path:find("Workspace%.CraftingTables", 1, true)
            or inst.path:find("^Workspace%.", 1, true) and not inst.path:find("Cutscene", 1, true)
        then
            table.insert(activeList, inst)
            activeSet[inst.objectType] = true
        end
    end
    if #activeList > 0 then
        list = activeList
        typeSet = activeSet
    end

    table.sort(list, function(a, b)
        return a.path < b.path
    end)

    _cache.instances.at = os.clock()
    _cache.instances.list = list
    _cache.instances.typeSet = typeSet
    return list, typeSet
end

local function _getInstanceData(force)
    return _scanCraftingInstances(force)
end

function M.listCraftingInstances()
    local instances = _getInstanceData()
    return instances
end

function M.getAvailableMachineTypes()
    local _, typeSet = _getInstanceData()
    local out = {}
    for objectType in pairs(typeSet) do
        table.insert(out, objectType)
    end
    table.sort(out, function(a, b) return tostring(a) < tostring(b) end)
    return out
end

function M.hasMachineInstance(objectType)
    if objectType == nil or objectType == "" then return false end
    local _, typeSet = _getInstanceData()
    return typeSet[tostring(objectType)] == true
end

function M.getRecipe(recipeId)
    if recipeId == nil or recipeId == "" then return nil end
    local reg = _getRecipeRegistry()
    local raw = reg and reg.ItemRecipes
    if type(raw) ~= "table" then return nil end
    local recipes = _flattenItemRecipes(raw)
    return recipes[recipeId] or recipes[tostring(recipeId)]
end

function M.getRecipeDisplayName(recipeId)
    return _recipeDisplayName(recipeId, M.getRecipe(recipeId))
end

function M.getRecipeMachineType(recipeId)
    return _resolveRecipeMachineType(M.getRecipe(recipeId), _getTypeRegistry())
        or _directRecipeMachineType(M.getRecipe(recipeId))
end

----------------------------------------------------------------
-- BACKPACK / INVENTORY: hitung bahan lengkap per resep
-- Format game: recipe.Inputs = { {ItemType, ItemData={ItemName}}, ... }
----------------------------------------------------------------
local DataService = nil
local PetBoostRegistry = nil
pcall(function()
    DataService = require(ReplicatedStorage.Modules.DataService)
end)
pcall(function()
    PetBoostRegistry = require(ReplicatedStorage.Data.PetRegistry.PetBoostRegistry)
end)

local function _normKeyPart(v)
    return tostring(v or ""):lower():gsub("%s+", "")
end

-- Tool/inventory display names → GearData / recipe ItemName
local ITEM_NAME_ALIASES = {
    smallpettoy = "smalltoy",
    smallpassiveboost = "smalltoy",
    smallxpboost = "smalltreat",
    smallpettreat = "smalltreat",
    mediumpettoy = "mediumtoy",
    mediumpassiveboost = "mediumtoy",
    mediumxpboost = "mediumtreat",
    mediumpettreat = "mediumtreat",
    largepettoy = "largetoy",
    largepassiveboost = "largetoy",
    largexpboost = "smithtreat",
    largepettreat = "smithtreat",
}

local function _normItemName(itemName)
    local k = _normKeyPart(itemName)
    return ITEM_NAME_ALIASES[k] or k
end

-- Samakan tipe inventory vs recipe (Pet Egg / Food / Holdable, dll)
local function _normItemType(itemType)
    local t = _normKeyPart(itemType)
    if t == "petegg" or t == "egg" then return "petegg" end
    if t == "food" or t == "holdable" or t == "fruit" then return "food" end
    if t == "petboost" or t == "treat" or t == "toy" then return "petboost" end
    if t == "currency" or t == "money" or t == "sheckles" then return "currency" end
    return t
end

local function _composePetBoostName(d)
    if type(d) ~= "table" then return "" end
    local size = d.PetBoostSize
    local btype = d.PetBoostType
    if size and btype and type(PetBoostRegistry) == "table" then
        local map = PetBoostRegistry.BoostTypeToPetModelName
        local model = type(map) == "table" and map[btype]
        if model then
            return tostring(size) .. " " .. tostring(model)
        end
    end
    return ""
end

local function _itemDataName(d, itemType)
    if type(d) ~= "table" then return "" end
    local t = _normItemType(itemType)
    if t == "petboost" then
        local composed = _composePetBoostName(d)
        if composed ~= "" then return composed end
    end
    if t == "petegg" then
        local egg = d.EggName or d.ItemName or d.Name
        if egg and tostring(egg) ~= "" then return tostring(egg) end
    end
    local n = d.ItemName or d.Value or d.EggName or d.HoldableName or d.FoodName or d.Name
        or d.PetName or d.DisplayName or d.ShardType or d.CrateType or d.Type
    return (n and tostring(n) ~= "") and tostring(n) or ""
end

local function _stockKey(itemType, itemName)
    itemType = _normItemType(itemType)
    itemName = _normItemName(itemName)
    if itemType == "" then return nil end
    if itemName == "" then return itemType .. "\0" end
    return itemType .. "\0" .. itemName
end

local function _slotFilterName(slotDef)
    if type(slotDef) ~= "table" then return nil end
    local d = slotDef.ItemData
    if type(d) == "table" then
        local n = d.ItemName or d.EggName or d.HoldableName or d.FoodName or d.Name
            or d.PetName or d.DisplayName or d.ShardType or d.CrateType or d.Type
        if n and tostring(n) ~= "" then
            return tostring(n)
        end
    end
    return slotDef.Filter or slotDef.RequiredName or slotDef.Name
        or slotDef.EggName or slotDef.HoldableName or slotDef.DisplayName
end

local function _slotItemType(slotDef)
    if type(slotDef) ~= "table" then return nil end
    return slotDef.ItemType or slotDef.Type or slotDef.itemType
end

local function _slotAcceptAllTypes(slotDef)
    if type(slotDef) ~= "table" then return false end
    local d = slotDef.ItemData
    return type(d) == "table" and d.AcceptAllTypes == true
end

local function _slotRequiredAmount(slotDef)
    if type(slotDef) ~= "table" then return 1 end
    local d = slotDef.ItemData
    local n = slotDef.Amount or slotDef.Count or slotDef.Quantity or slotDef.Sheckles
    if n == nil and type(d) == "table" then
        n = d.Amount or d.Count or d.Quantity or d.Sheckles or d.Cost
    end
    n = tonumber(n) or 1
    return math.max(1, math.floor(n))
end

local function _recordQuantity(rec)
    if type(rec) ~= "table" then return 1 end
    local d = rec.ItemData
    if type(d) == "table" then
        -- Game: Quantity or (Uses or 1)
        local q = tonumber(d.Quantity or d.quantity)
        if q and q > 0 then return math.floor(q) end
        local uses = tonumber(d.Uses or d.uses)
        if uses and uses > 0 then return math.floor(uses) end
    end
    return 1
end

local function _isShecklesSlot(slotDef)
    if type(slotDef) ~= "table" then return false end
    local t = _normKeyPart(_slotItemType(slotDef))
    local n = _normKeyPart(_slotFilterName(slotDef))
    if t == "sheckles" or t == "currency" or t == "money" or n == "sheckles" then
        return true
    end
    local d = slotDef.ItemData
    if type(d) == "table" then
        local dn = _normKeyPart(d.ItemName or d.Currency or d.CurrencyType)
        if dn == "sheckles" then return true end
    end
    if (t == "" or t == "item") and n == "" then
        local cost = tonumber(slotDef.Amount or slotDef.Sheckles or slotDef.Cost)
        if cost and cost >= 1000 then return true end
    end
    return false
end

local function _getSheckles(profile)
    if type(profile) ~= "table" then return 0 end
    local s = tonumber(profile.Sheckles)
    if s and s > 0 then return s end
    if type(profile.CurrencyData) == "table" then
        s = tonumber(profile.CurrencyData.Sheckles)
        if s and s > 0 then return s end
    end
    if type(profile.Stats) == "table" then
        s = tonumber(profile.Stats.Sheckles)
        if s and s > 0 then return s end
    end
    return 0
end

local function _getProfile()
    if not DataService or type(DataService.GetData) ~= "function" then
        return nil
    end
    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if ok and type(profile) == "table" then return profile end
    return nil
end

local function _addStock(stock, itemType, itemName, qty)
    local key = _stockKey(itemType, itemName)
    if not key then return end
    qty = tonumber(qty) or 0
    if qty <= 0 then return end
    stock[key] = (stock[key] or 0) + qty
end

local function _stockLookup(stock, slotDef)
    if _isShecklesSlot(slotDef) then
        return tonumber(stock["__sheckles__"]) or 0
    end

    local needType = _slotItemType(slotDef)
    local needName = _slotFilterName(slotDef)

    local key = _stockKey(needType, needName)
    local have = tonumber(key and stock[key]) or 0
    if have > 0 then return have end

    -- Inventory kadang simpan ItemType = nama item (Harvest Tool), bukan kategori (Gear)
    if needName and tostring(needName) ~= "" then
        have = tonumber(stock[_stockKey(needName, needName)]) or 0
        if have > 0 then return have end
        have = tonumber(stock[_stockKey(needName, "")]) or 0
        if have > 0 then return have end

        -- Fallback: cocokkan nama item saja lintas tipe
        local want = _normItemName(needName)
        local total = 0
        for k, qty in pairs(stock) do
            if type(k) == "string" then
                local sep = k:find("\0", 1, true)
                local namePart = sep and k:sub(sep + 1) or ""
                if namePart == want then
                    total += tonumber(qty) or 0
                end
            end
        end
        if total > 0 then return total end
    end

    return 0
end

local function _buildInventoryStock(inv)
    local stock = {}
    if type(inv) ~= "table" then return stock end

    for _, rec in pairs(inv) do
        if type(rec) == "table" then
            local itemType = rec.ItemType or rec.Type
            local itemName = _itemDataName(rec.ItemData, itemType)
            local qty = _recordQuantity(rec)
            _addStock(stock, itemType, itemName, qty)

            -- ItemData tanpa nama: ItemType sendiri adalah nama item (Harvest Tool, dll)
            if itemName == "" and itemType then
                _addStock(stock, itemType, itemType, qty)
            end
        end
    end

    return stock
end

local function _getSlotRequirements(recipe, machineDef)
    if type(recipe) == "table" then
        for _, key in ipairs({ "Inputs", "SlotInputs", "InputSlots", "Ingredients" }) do
            local block = recipe[key]
            if type(block) == "table" and next(block) then
                return block
            end
        end
    end
    if type(machineDef) == "table" and type(machineDef.Slots) == "table" then
        return machineDef.Slots
    end
    return nil
end

local function _slotListFromRequirements(slotReqs)
    local list = {}
    if type(slotReqs) ~= "table" then return list end

    local n = #slotReqs
    if n > 0 then
        for i = 1, n do
            if type(slotReqs[i]) == "table" then
                list[#list + 1] = slotReqs[i]
            end
        end
    end
    if #list == 0 then
        for _, def in pairs(slotReqs) do
            if type(def) == "table" then
                list[#list + 1] = def
            end
        end
    end
    return list
end

local function _currencyStockKey(currencyType)
    local t = _normKeyPart(currencyType)
    if t == "" or t == "currency" or t == "money" then
        t = "sheckles"
    end
    return "__currency__" .. t
end

local function _recipeCurrencyNeed(recipe)
    if type(recipe) ~= "table" then return 0, "Sheckles" end
    local cost = recipe.Cost
    if type(cost) ~= "table" then return 0, "Sheckles" end
    local amount = math.max(0, math.floor(tonumber(cost.Amount or cost.Quantity or cost.Sheckles) or 0))
    local raw = cost.CurrencyType or cost.ItemName or cost.Type or "Sheckles"
    raw = tostring(raw)
    if raw == "" then raw = "Sheckles" end
    return amount, raw
end

local function _recipeCurrencyCost(recipe)
    local amount = _recipeCurrencyNeed(recipe)
    return amount
end

local function _lookupCurrencyInTable(tbl, currencyType)
    if type(tbl) ~= "table" then return nil end
    local want = tostring(currencyType or "")
    if want == "" then return nil end
    local n = tonumber(tbl[want])
    if n then return n end
    local wantNorm = _normKeyPart(want)
    for k, v in pairs(tbl) do
        if _normKeyPart(k) == wantNorm then
            n = tonumber(v)
            if n then return n end
        end
    end
    return nil
end

local function _getCurrencyAmount(profile, currencyType)
    if type(profile) ~= "table" then return 0 end
    local raw = tostring(currencyType or "Sheckles")
    local t = _normKeyPart(raw)
    if t == "" or t == "currency" or t == "money" then
        raw = "Sheckles"
        t = "sheckles"
    end

    if t == "sheckles" then
        return _getSheckles(profile)
    end

    local n = _lookupCurrencyInTable(profile.SpecialCurrency, raw)
    if n ~= nil then return n end
    n = _lookupCurrencyInTable(profile.CurrencyData, raw)
    if n ~= nil then return n end
    n = _lookupCurrencyInTable(profile.Currencies, raw)
    if n ~= nil then return n end
    n = tonumber(profile[raw])
    if n ~= nil then return n end
    n = _lookupCurrencyInTable(profile.Stats, raw)
    if n ~= nil then return n end
    return 0
end

local function _ingestCurrencies(stock, profile)
    if type(stock) ~= "table" or type(profile) ~= "table" then return end

    local sheckles = _getSheckles(profile)
    stock["__sheckles__"] = sheckles
    stock[_currencyStockKey("Sheckles")] = sheckles
    _addStock(stock, "Sheckles", "Sheckles", sheckles)
    _addStock(stock, "Currency", "Sheckles", sheckles)

    local function addAll(tbl)
        if type(tbl) ~= "table" then return end
        for k, v in pairs(tbl) do
            local n = tonumber(v)
            if n and n > 0 and type(k) == "string" then
                local key = _currencyStockKey(k)
                stock[key] = math.max(tonumber(stock[key]) or 0, n)
                _addStock(stock, "Currency", k, n)
            end
        end
    end

    addAll(profile.SpecialCurrency)
    addAll(profile.CurrencyData)
    addAll(profile.Currencies)
end

local function _countCraftableTimes(recipe, objectType, objectReg, stock)
    if type(recipe) ~= "table" then return 0 end
    objectType = tostring(objectType or "")
    if objectType == "" then return 0 end

    local machineDef = objectReg and objectReg[objectType]
    local slotReqs = _getSlotRequirements(recipe, machineDef)
    local slotList = _slotListFromRequirements(slotReqs)
    if #slotList == 0 and _recipeCurrencyCost(recipe) <= 0 then return 0 end

    stock = stock or {}
    local minCrafts = math.huge
    local grouped = {}

    for _, slotDef in ipairs(slotList) do
        local need = _slotRequiredAmount(slotDef)
        local have
        local groupKey

        if _slotAcceptAllTypes(slotDef) then
            local itemType = _normItemType(_slotItemType(slotDef))
            local total = 0
            local prefix = itemType .. "\0"
            for k, qty in pairs(stock) do
                if type(k) == "string" and k:sub(1, #prefix) == prefix then
                    total += qty
                end
            end
            have = total
            groupKey = "__type__" .. itemType
        elseif _isShecklesSlot(slotDef) then
            have = tonumber(stock["__sheckles__"]) or 0
            groupKey = "__sheckles__"
        else
            have = _stockLookup(stock, slotDef)
            groupKey = _normItemName(_slotFilterName(slotDef))
            if groupKey == "" then
                groupKey = _normItemType(_slotItemType(slotDef))
            end
        end

        local g = grouped[groupKey]
        if not g then
            g = { need = 0, have = have }
            grouped[groupKey] = g
        end
        g.need += need
        if have < g.have then
            g.have = have
        end
    end

    for _, g in pairs(grouped) do
        if g.have < g.need then return 0 end
        local crafts = math.floor(g.have / g.need)
        if crafts < minCrafts then minCrafts = crafts end
    end

    local cashNeed, cashType = _recipeCurrencyNeed(recipe)
    if cashNeed > 0 then
        local cashHave = tonumber(stock[_currencyStockKey(cashType)]) or 0
        if cashHave <= 0 and _normKeyPart(cashType) == "sheckles" then
            cashHave = tonumber(stock["__sheckles__"]) or 0
        end
        if cashHave < cashNeed then return 0 end
        local cashCrafts = math.floor(cashHave / cashNeed)
        if cashCrafts < minCrafts then minCrafts = cashCrafts end
    end

    if minCrafts == math.huge then return 0 end
    return minCrafts
end

local function _buildMaterialStock(force)
    if not force and _cacheFresh(_cache.stock, CACHE_TTL.stock) then
        return _cache.stock.data
    end

    local profile = _getProfile()
    local inv = profile and profile.InventoryData
    local stock = _buildInventoryStock(inv)
    _ingestCurrencies(stock, profile)

    if next(stock) ~= nil then
        _cache.stock.at = os.clock()
        _cache.stock.data = stock
    else
        _cache.stock.at = 0
        _cache.stock.data = {}
    end
    return stock
end

function M.getMaterialStock(force)
    return _buildMaterialStock(force == true)
end

local function _buildIncludedRecipeMap(recipes, availableTypes, reg, objectReg, typeReg)
    local included = _collectNestedCategoryRecipes(reg, availableTypes)
    local byMachine = _buildRecipesByMachine(recipes, objectReg, typeReg)

    for objectType in pairs(availableTypes) do
        local bucket = byMachine[objectType]
        if type(bucket) == "table" then
            for recipeId in pairs(bucket) do
                included[recipeId] = objectType
            end
        end

        local regBucket = _collectRegistryRecipesForMachine(objectType, reg, objectReg)
        for recipeId in pairs(regBucket) do
            if recipes[recipeId] or recipes[tostring(recipeId)] then
                included[recipeId] = objectType
            end
        end

        local typeBucket = _harvestTypeRegistryRecipes(objectType, typeReg, recipes)
        for recipeId in pairs(typeBucket) do
            included[recipeId] = objectType
        end

        local craftTypes = _getMachineCraftTypes(objectType, objectReg, typeReg)
        for recipeId, recipe in pairs(recipes) do
            if _recipeMatchesMachineTypes(recipe, craftTypes) then
                included[tostring(recipeId)] = objectType
            end
        end

        local scan = _G.CRAFT_SCAN_RESULT
        if type(scan) == "table" and type(scan.recipesByMachine) == "table" then
            local bucket = scan.recipesByMachine[objectType]
            if type(bucket) == "table" then
                for recipeId in pairs(bucket) do
                    included[tostring(recipeId)] = objectType
                end
            end
        end
    end

    for recipeId, recipe in pairs(recipes) do
        local rid = tostring(recipeId)
        if not included[rid] then
            for objectType in pairs(availableTypes) do
                if _recipeReferencesMachine(recipe, rid, objectType, objectReg, typeReg) then
                    included[rid] = objectType
                    break
                end
            end
        end
    end

    for recipeId, recipe in pairs(recipes) do
        local rid = tostring(recipeId)
        if not included[rid] then
            local ot = _resolveRecipeMachineType(recipe, typeReg)
            if ot and availableTypes[ot] then
                included[rid] = ot
            end
        end
    end

    if next(included) == nil then
        for recipeId, recipe in pairs(recipes) do
            local rid = tostring(recipeId)
            for objectType in pairs(availableTypes) do
                local stem = _objectTypeStem(objectType)
                if stem ~= "" and rid:lower():find(stem, 1, true) then
                    included[rid] = objectType
                    break
                end
            end
        end
    end

    return included
end

function M.resolveRecipeMachineType(recipeId)
    if recipeId == nil or recipeId == "" then return nil end
    local rid = tostring(recipeId)

    local _, availableTypes = _getInstanceData()
    if next(availableTypes) ~= nil then
        local reg = _getRecipeRegistry()
        local rawRecipes = reg and reg.ItemRecipes
        if type(rawRecipes) == "table" then
            local recipes = _flattenItemRecipes(rawRecipes)
            local included = _buildIncludedRecipeMap(
                recipes, availableTypes, reg, _getObjectRegistry(), _getTypeRegistry()
            )
            if included[rid] then
                return included[rid]
            end
        end
    end

    return M.getRecipeMachineType(recipeId)
end

local function _resolveMaterialStock(stock, force)
    if type(stock) == "table" and next(stock) ~= nil then
        return stock
    end
    return _buildMaterialStock(force == true)
end

function M.countCraftableTimes(recipeId, objectType, stock)
    local recipe = M.getRecipe(recipeId)
    if not recipe then return 0 end
    objectType = objectType or M.resolveRecipeMachineType(recipeId)
    return _countCraftableTimes(
        recipe,
        objectType,
        _getObjectRegistry(),
        _resolveMaterialStock(stock, false)
    )
end

function M.listCraftingRecipes(force)
    if not force and _cacheFresh(_cache.recipes, CACHE_TTL.recipes) then
        return _cache.recipes.list
    end

    local out = {}
    local _, availableTypes = _getInstanceData()

    if next(availableTypes) == nil then
        return out
    end

    local reg = _getRecipeRegistry()
    local rawRecipes = reg and reg.ItemRecipes
    if type(rawRecipes) ~= "table" then
        warn("[CraftListView] CraftingRecipeRegistry.ItemRecipes tidak ditemukan")
        return out
    end
    local recipes = _flattenItemRecipes(rawRecipes)

    local objectReg = _getObjectRegistry()
    local typeReg   = _getTypeRegistry()
    local included = _buildIncludedRecipeMap(recipes, availableTypes, reg, objectReg, typeReg)

    local ids = {}
    for recipeId in pairs(included) do
        table.insert(ids, recipeId)
    end
    table.sort(ids, _compareIndex)

    local stock = _buildMaterialStock()

    for _, recipeId in ipairs(ids) do
        local recipe = recipes[recipeId] or recipes[tostring(recipeId)]
        local machineType = included[recipeId] or _resolveRecipeMachineType(recipe, typeReg)
        local display = _recipeDisplayName(recipeId, recipe)
        local craftable = _countCraftableTimes(recipe, machineType, objectReg, stock)
        local label = string.format("%s (%d)", display, craftable)

        table.insert(out, {
            key            = tostring(recipeId),
            name           = label,
            displayName    = display,
            craftableCount = craftable,
            machineType    = machineType,
            recipe         = recipe,
        })
    end

    _cache.recipes.at = os.clock()
    _cache.recipes.list = out
    return out
end

function M.listCraftingMachines()
    local out = {}
    local instances, availableTypes = _getInstanceData()

    if next(availableTypes) == nil then
        return out
    end

    local reg = _getObjectRegistry()
    if type(reg) ~= "table" then
        warn("[CraftListView] CraftingObjectRegistry tidak ditemukan")
        return out
    end

    local keys = {}
    for objectType in pairs(availableTypes) do
        table.insert(keys, objectType)
    end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)

    for _, objectType in ipairs(keys) do
        local def = reg[objectType]
        local display = objectType
        if type(def) == "table" then
            display = def.DisplayName or def.Name or objectType
        end

        local instList = {}
        for _, inst in ipairs(instances) do
            if inst.objectType == objectType then
                table.insert(instList, inst)
            end
        end

        table.insert(out, {
            key         = tostring(objectType),
            name        = tostring(display),
            displayName = tostring(display),
            slots       = type(def) == "table" and type(def.Slots) == "table" and def.Slots or {},
            instances   = instList,
        })
    end

    return out
end

function M.clearCache()
    -- scan selalu fresh
end

function M.debugMaterialStock()
    local stock = _buildMaterialStock()
    local lines = {}
    for k, v in pairs(stock) do
        if k ~= "__sheckles__" and (tonumber(v) or 0) > 0 then
            table.insert(lines, k:gsub("\0", "|") .. "=" .. tostring(v))
        end
    end
    table.sort(lines)
    return stock, lines
end

function M.debugRecipe(recipeId)
    local recipe = M.getRecipe(recipeId)
    if not recipe then return nil, "recipe_not_found" end

    local machineType = M.resolveRecipeMachineType(recipeId)
    local objectReg = _getObjectRegistry()
    local machineDef = objectReg and objectReg[machineType]
    local slotReqs = _getSlotRequirements(recipe, machineDef)
    local slotList = _slotListFromRequirements(slotReqs)
    local stock = _buildMaterialStock()
    local cashNeed, cashType = _recipeCurrencyNeed(recipe)
    local report = {
        recipeId = tostring(recipeId),
        machineType = machineType,
        slotSource = recipe.Inputs and "Inputs" or "other",
        slots = {},
        currencyType = cashType,
        currencyNeed = cashNeed,
        currencyHave = tonumber(stock[_currencyStockKey(cashType)]) or 0,
        craftable = M.countCraftableTimes(recipeId, machineType),
    }

    for i, slotDef in ipairs(slotList) do
        local needType = _slotItemType(slotDef)
        local needName = _slotFilterName(slotDef)
        table.insert(report.slots, {
            index = i,
            itemType = needType,
            itemName = needName,
            need = _slotRequiredAmount(slotDef),
            have = _stockLookup(stock, slotDef),
            isSheckles = _isShecklesSlot(slotDef),
            stockKey = _stockKey(needType, needName),
        })
    end

    return report
end

