-- Map mutasi yang DIJAGA (TIDAK di-cleanse) → dari Select Mutation tab boost (mode aktif)
local function getBoostListMode()
    local st = rawget(GG, "STATE")
    if st and st.boostListMode then
        local m = tostring(st.boostListMode):lower()
        if m == "machine" or m == "shark" then return m end
    end

    local main = rawget(GG, "MAIN")
    if main and type(main.nmlvl) == "table" and type(main.nmlvl.state) == "table" then
        local m = tostring(main.nmlvl.state.boostListMode or ""):lower()
        if m == "machine" or m == "shark" then return m end
    end

    if type(_G.__getBoostListMode) == "function" then
        local ok, v = pcall(_G.__getBoostListMode)
        if ok then
            local m = tostring(v):lower()
            if m == "machine" or m == "shark" then
                return m
            end
        end
    end

    return "normal"
end

local function getBoostMutBucket()
    local m = getBoostListMode()
    if m == "machine" or m == "shark" then
        return m
    end
    return "normal"
end

local function getBoostMutSelectedMap()
    local bucket = getBoostMutBucket()

    local function pickFromBoostMutSelected(bms)
        if type(bms) ~= "table" then return nil end
        local sel = bms[bucket]
        if type(sel) == "table" and next(sel) ~= nil then
            return sel
        end
        return nil
    end

    local st = rawget(GG, "STATE")
    local src = pickFromBoostMutSelected(st and st.boostMutSelected)
    if src then return src end

    local main = rawget(GG, "MAIN")
    if main and type(main.nmlvl) == "table" and type(main.nmlvl.state) == "table" then
        src = pickFromBoostMutSelected(main.nmlvl.state.boostMutSelected)
        if src then return src end
    end

    src = pickFromBoostMutSelected(rawget(GG, "BOOST_MUT_SELECTED") or rawget(_G, "BOOST_MUT_SELECTED"))
    if src then return src end

    return nil
end

local function getKeepMutationMap()
    local src = getBoostMutSelectedMap()
    if type(src) ~= "table" then
        return nil
    end

    local out = {}
    for mutName, on in pairs(src) do
        if on then
            local key = tostring(mutName):lower()
            out[key] = true
        end
    end

    if next(out) == nil then
        return nil
    end

    return out
end

