------------------------------ Helpers ---------------------------------
local function normalizeUUID(u)
    if not u then return nil, nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    return core, "{" .. core .. "}"
end

local function ownedByTargetFromMover(mover)
    local inst = mover
    for _ = 1, 4 do
        if not inst or inst == WS then
            break
        end
        local ownerName = inst:GetAttribute("OWNER")
            or inst:GetAttribute("Owner")
            or inst:GetAttribute("OwnerName")
            or inst:GetAttribute("Player")
        if TRACE_OWNER then
            dprint("OWNER", sf("inst=%s ownerAttr=%s", inst:GetFullName(), tostring(ownerName)))
        end
        if ownerName == TARGET_PLAYER_NAME then
            return true, inst
        end
        inst = inst.Parent
    end
    return false, mover
end

local function uuidFromInst(inst)
    if not inst then return nil end
    return inst:GetAttribute("UUID")
        or inst:GetAttribute("Guid")
        or inst:GetAttribute("GUID")
        or inst:GetAttribute("Id")
end

-- Ambil record pet dari datastore berdasarkan UUID
local _bagCache, _bagAt = nil, 0

local function getBagData()
    local now = os.clock()
    if type(_bagCache) == "table" and (now - _bagAt) <= 0.35 then
        return _bagCache
    end

    local okStore, store = pcall(function()
        return ActivePetsService:GetPlayerDatastorePetData(Players.LocalPlayer.Name)
    end)
    local bag = okStore and store and store.PetInventory and store.PetInventory.Data
    _bagCache = type(bag) == "table" and bag or nil
    _bagAt = now
    return _bagCache
end

local function getPetRecordForUUID(uuid, bag)
    if not uuid or uuid == "" then return nil end
    local core, braced = normalizeUUID(uuid)
    bag = bag or getBagData()
    if type(bag) ~= "table" then return nil end
    local rec = bag[core] or bag[braced] or bag[uuid]
    if type(rec) == "table" then
        return rec
    end
    for k, v in pairs(bag) do
        if type(v) == "table" and select(1, normalizeUUID(k)) == core then
            return v
        end
    end
    return nil
end

local function recordIsFavorite(rec)
    if type(rec) ~= "table" then
        return false
    end
    local PD = rec.PetData or rec.Data or {}
    if type(PD.IsFavorite) == "boolean" then return PD.IsFavorite == true end
    if type(PD.IsFavourite) == "boolean" then return PD.IsFavourite == true end
    if type(PD.IsFavorited) == "boolean" then return PD.IsFavorited == true end
    if type(rec.IsFavorite) == "boolean" then return rec.IsFavorite == true end
    if type(rec.IsFavourite) == "boolean" then return rec.IsFavourite == true end
    if type(rec.IsFavorited) == "boolean" then return rec.IsFavorited == true end
    return PD.Favorite == true or rec.Favorite == true
end

-- Favorite tidak di-shard. Record tidak ketemu → skip (jangan sampai fav ke-strip).
local function isFavoriteUUID(uuid, rec)
    rec = rec or getPetRecordForUUID(uuid)
    if not rec then
        return true
    end
    return recordIsFavorite(rec)
end

-- Ambil mutationType dari datastore pemain (bisa huruf 1 char atau nama penuh)
local function getRawMutationFromUUID(uuid, rec)
    rec = rec or getPetRecordForUUID(uuid)
    if rec then
        local mt = rec.MutationType or (rec.PetData and rec.PetData.MutationType)
        if type(mt) == "string" and mt ~= "" then
            return mt
        end
    end

    return ""
end



-- Normalisasi: huruf tunggal (termasuk "A") → nama penuh via registry; kalau sudah nama, jadikan lowercase
local function normalizeMutationNameLower(raw)
    if not raw or raw == "" then return "" end

    local s = tostring(raw):gsub("%s+", "")
    if s == "" then return "" end

    -- 1) PRIORITAS: exact match (case-sensitive)
    if EnumToPetMutation then
        local full = EnumToPetMutation[s]
        if type(full) == "string" and full ~= "" then
            return full:lower()
        end
    end

    -- 2) fallback: split kalau misalnya "E+V" atau tidak dikenal
    if #s > 1 then
        for c in s:gmatch("%a") do
            local full = EnumToPetMutation and EnumToPetMutation[c]
            if type(full) == "string" and full ~= "" then
                return full:lower()
            end
        end
    end

    -- 3) fallback terakhir
    return s:lower()
end

local ONLY_UUID_CORES = nil -- nil = semua pet world; table = hanya UUID ini (mode Shark GBXP)

local function uuidInOnlyScope(uuid)
    if type(ONLY_UUID_CORES) ~= "table" then
        return true
    end
    local core = select(1, normalizeUUID(uuid))
    if not core or core == "" then
        return false
    end
    return ONLY_UUID_CORES[core] == true
end

local function isBadMutation(raw, keepMap)
    local nm = normalizeMutationNameLower(raw)

    -- tidak ada mutasi → jangan di-cleanse
    if nm == "" then
        return false
    end

    keepMap = keepMap or getKeepMutationMap()

    -- kalau state belum siap / kosong → AMAN, jangan cleanse apapun
    if not keepMap then
        return false
    end

    -- bad = semua mutasi yang TIDAK ada di daftar "keep" dari state
    return not keepMap[nm]
end


