_G.WorldShardCleaner = _G.WorldShardCleaner or {}

function _G.WorldShardCleaner:setOnlyUUIDs(map)
    -- nil = semua pet world; table (boleh kosong) = hanya UUID itu
    if map == nil or type(map) ~= "table" then
        ONLY_UUID_CORES = nil
        return
    end
    local out = {}
    for k, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            local core = select(1, normalizeUUID(k))
            if core and core ~= "" then
                out[core] = true
            end
        elseif type(k) == "number" and type(v) == "string" then
            local core = select(1, normalizeUUID(v))
            if core and core ~= "" then
                out[core] = true
            end
        end
    end
    ONLY_UUID_CORES = out
end

