    local st = rawget(GG, "STATE")
    if type(st) == "table" then
        st.boostMutSelected = st.boostMutSelected or { normal = {}, machine = {}, shark = {} }
        st.boostMutSelected.normal = st.boostMutSelected.normal or {}
        st.boostMutSelected.machine = st.boostMutSelected.machine or {}
        st.boostMutSelected.shark = st.boostMutSelected.shark or {}
        st.boostMutSelected[bucket] = new
    end

    local main = rawget(GG, "MAIN")
    if main and type(main) == "table" then
        main.nmlvl = main.nmlvl or {}
        main.nmlvl.state = main.nmlvl.state or {}
        main.nmlvl.state.boostMutSelected = main.nmlvl.state.boostMutSelected or { normal = {}, machine = {}, shark = {} }
        main.nmlvl.state.boostMutSelected.normal = main.nmlvl.state.boostMutSelected.normal or {}
