        main.nmlvl.state.boostMutSelected.shark = main.nmlvl.state.boostMutSelected.shark or {}
        main.nmlvl.state.boostMutSelected[bucket] = new
    end

    GG.BOOST_MUT_SELECTED = (st and st.boostMutSelected) or (main and main.nmlvl and main.nmlvl.state and main.nmlvl.state.boostMutSelected)
end

