------------------------- World Model Collector -------------------------
local function hasTagSafe(inst, tag)
    -- Beberapa game monkey-patch :HasTag; tetap utamakan CollectionService
    local okCs = pcall(function()
        return CS:HasTag(inst, tag)
    end)
    if okCs then
        return CS:HasTag(inst, tag)
    end

    if typeof(inst.HasTag) == "function" then
        local ok, res = pcall(inst.HasTag, inst, tag)
        if ok then return res end
    end

    return false
end

local function collectPetModelsForOwner()
    local out, seen = {}, {}
    local folder = WS:FindFirstChild("PetsPhysical")
    if not folder then
        return out
    end

    local function push(host, model)
        if not host or not model then
            return
        end
        local okOwn, ownerInst = ownedByTargetFromMover(host)
        if not okOwn then
            return
        end
        local uuid = uuidFromInst(ownerInst) or uuidFromInst(host) or uuidFromInst(model)
        local core = uuid and select(1, normalizeUUID(uuid))
        if not core or core == "" or seen[core] then
            return
        end
        seen[core] = true
        out[#out + 1] = { uuid = core, model = model, mover = host }
    end

    -- 1) anak langsung PetsPhysical (mover aktif garden)
    for _, mover in ipairs(folder:GetChildren()) do
        local own, ownerInst = ownedByTargetFromMover(mover)
        if own then
            local model = nil
            for _, ch in ipairs(mover:GetChildren()) do
                if ch:IsA("Model") and hasTagSafe(ch, "PetModel") then
                    model = ch
                    break
                end
            end
            if not model then
                model = mover:FindFirstChildWhichIsA("Model", true)
            end
            push(ownerInst or mover, model)
        end
    end

    -- 2) fallback: PetModel di dalam PetsPhysical (struktur nested)
    if #out == 0 then
        for _, inst in ipairs(folder:GetDescendants()) do
            if inst:IsA("Model") and hasTagSafe(inst, "PetModel") then
                push(inst.Parent, inst)
            end
        end
    end

    if TRACE_WORLD_SCAN then
        dprint("SCAN", sf("Kumpul %d pet model milik %s", #out, TARGET_PLAYER_NAME))
    end

    return out
end

------------------------- Auto Equip / Unequip --------------------------
local InvEnums = nil
pcall(function()
    InvEnums = require(RS.Data.EnumRegistry.InventoryServiceEnums)
end)
local ATTR_SHARD_TYPE = (InvEnums and InvEnums.ShardType) or "u"
local ATTR_USES = (InvEnums and InvEnums.Uses) or "e"

local function isCleansingShard(tool)
    if not tool or not tool:IsA("Tool") then
        return false
    end
    local st = tostring(tool:GetAttribute(ATTR_SHARD_TYPE) or "")
    if st == "Cleansing Pet Shard" then
        return true
    end
    local n = tostring(tool.Name or ""):lower()
    return n:find("cleansing pet shard", 1, true) ~= nil
end

local function getHeldTool(char)
    char = char or (LP and LP.Character)
    if not char then
        return nil
    end
    return char:FindFirstChildOfClass("Tool")
end

local function handText()
    local held = getHeldTool()
    if held then
        return tostring(held.Name)
    end
    return "empty"
end

local function isHoldingCleansingShard()
    local held = getHeldTool()
    if isCleansingShard(held) then
        return true, held
    end
    return false, held
end

local function getBackpack()
    return (LP and LP:FindFirstChild("Backpack")) or (LP and LP.Backpack)
end

local function getShardTool()
    local function scan(container)
        if not container then
            return nil
        end
        for _, tool in ipairs(container:GetChildren()) do
            if isCleansingShard(tool) then
                local uses = tonumber(tool:GetAttribute(ATTR_USES))
                if uses == nil or uses > 0 then
                    return tool
                end
            end
        end
        return nil
    end
    return scan(LP and LP.Character) or scan(getBackpack())
end

local function waitUntil(pred, timeout)
    local t0 = os.clock()
    timeout = tonumber(timeout) or EQUIP_TIMEOUT
    while (os.clock() - t0) < timeout do
        local ok, extra = pred()
        if ok then
            return true, extra
        end
        task.wait(EQUIP_POLL)
    end
    return pred()
end

local function unequipAllToolsFromCharacter()
    local char = LP and LP.Character
    local backpack = getBackpack()
    if not char or not backpack then
        return
    end

    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end

    for _, inst in ipairs(char:GetChildren()) do
        if inst:IsA("Tool") then
            inst.Parent = backpack
        end
    end
end

local function handsEmpty()
    return getHeldTool() == nil
end

-- Wajib: tangan kosong dulu, lalu Cleansing Pet Shard HARUS jadi Tool yang dipegang.
local function ensureEquipped()
    local char = LP and LP.Character
    if not char then
        dx("EQUIP", "Character belum siap, skip equip shard")
        setStatus("Shard: ERROR — character not ready")
        return false
    end

    local holding, held = isHoldingCleansingShard()
    if holding and held and held.Parent == char then
        return true, held
    end

    -- Lepas tool lain (seed/shovel/dll) sampai tangan kosong
    for _ = 1, 4 do
        if handsEmpty() then
            break
        end
        unequipAllToolsFromCharacter()
        waitUntil(handsEmpty, 0.45)
    end

    local leftover = getHeldTool()
    if leftover and not isCleansingShard(leftover) then
        setStatus("Shard: ERROR — cannot unequip other tool (" .. tostring(leftover.Name) .. ")")
        return false
    end

    holding, held = isHoldingCleansingShard()
    if holding and held and held.Parent == char then
        return true, held
    end

    local backpack = getBackpack()
    local shard = getShardTool()
    if not shard then
        setStatus("Shard: ERROR — Cleansing Pet Shard not in Backpack")
        dx("EQUIP", "Shard tidak ditemukan di Backpack/Character!")
        return false
    end

    -- EquipTool hanya andal kalau tool ada di Backpack dulu
    if backpack and shard.Parent ~= backpack then
        shard.Parent = backpack
        task.wait(0.08)
        shard = getShardTool() or shard
    end

    setStatus("Shard: equipping " .. tostring(shard.Name))
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:EquipTool(shard)
        end)
    end

    local ok2, tool2 = waitUntil(function()
        local e, t = isHoldingCleansingShard()
        return (e and t and t.Parent == char) == true, t
    end, EQUIP_TIMEOUT)

    if not (ok2 and tool2) then
        -- fallback: parent ke character, lalu EquipTool lagi
        if shard and shard.Parent ~= char then
            shard.Parent = char
        end
        if hum and shard then
            pcall(function()
                hum:EquipTool(shard)
            end)
        end
        ok2, tool2 = waitUntil(function()
            local e, t = isHoldingCleansingShard()
            return (e and t and t.Parent == char) == true, t
        end, 0.8)
    end

    if ok2 and tool2 then
        setStatus("Shard: holding " .. tostring(tool2.Name))
        return true, tool2
    end

    setStatus("Shard: ERROR — Cleansing Pet Shard not in hand (hand=" .. handText() .. ")")
    dx("EQUIP", "Gagal equip Cleansing Shard (tangan=" .. handText() .. ")")
    return false
end

-- Hanya lepas Cleansing Pet Shard. Sprinkler/shovel/dll jangan disentuh.
local weEquippedShard = false

local function unequipCleansingShardOnly()
    local held = getHeldTool()
    if not isCleansingShard(held) then
        weEquippedShard = false
        return
    end
    dprint("EQUIP", "Put away Cleansing Pet Shard only")
    local backpack = getBackpack()
    local char = LP and LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end
    if held and backpack and held.Parent ~= backpack then
        held.Parent = backpack
    end
    waitUntil(function()
        return not isCleansingShard(getHeldTool())
    end, 0.4)
    weEquippedShard = false
end

----------------------------- Cleanse call ------------------------------
local _lastSendAt = 0

local function fireCleanseModel(model, idx, total, rawMut)
    if not ShardRE then
        dx("SHARD", "Remote PetShardService_RE tidak ditemukan.")
        setStatus("Shard: ERROR — PetShardService_RE missing")
        return false
    end

    if not ensureEquipped() then
        return false
    end

    local now = workspace:GetServerTimeNow()
    local since = now - _lastSendAt
    if since < APPLY_GAP then
        task.wait(APPLY_GAP - since)
        if not ensureEquipped() then
            return false
        end
    end

    local holding, held = isHoldingCleansingShard()
    if not (holding and held) then
        setStatus("Shard: ERROR — Cleansing Pet Shard not in hand (hand=" .. handText() .. ")")
        return false
    end

    local nm = normalizeMutationNameLower(rawMut)
    if nm == "" then
        nm = tostring(rawMut or "?")
    end
    setStatus(string.format(
        "Shard: holding %s, apply %d/%d (%s)",
        tostring(held.Name),
        tonumber(idx) or 1,
        tonumber(total) or 1,
        nm
    ))

    _lastSendAt = workspace:GetServerTimeNow()
    local ok, err = pcall(function()
        ShardRE:FireServer("ApplyShard", model)
    end)

    -- Server cek tool masih di character; jangan unequip dulu
    task.wait(HOLD_AFTER_FIRE)

    holding, held = isHoldingCleansingShard()
    if not (holding and held) then
        setStatus("Shard: ERROR — shard left hand after fire (hand=" .. handText() .. ")")
        return false
    end

    if ok then
        dprint("SHARD", "ApplyShard OK →", model:GetFullName())
        return true
    end
    setStatus("Shard: ERROR apply failed: " .. tostring(err))
    dx("SHARD", "ApplyShard error:", tostring(err))
    return false
end

------------------------------- Main ------------------------------------
local RUN = false
_G.__WSC_GEN = (_G.__WSC_GEN or 0) + 1
local myGen = _G.__WSC_GEN

task.spawn(function()
    while _G.__WSC_GEN == myGen do
        if RUN then
            local mode = getBoostListMode()
            local keepMap = getKeepMutationMap()
            local keepN = 0
            if type(keepMap) == "table" then
                for _ in pairs(keepMap) do keepN += 1 end
            end

            if not keepMap then
                setStatus("Shard: idle — Select Mutation empty (" .. mode .. "), won't clean")
                if weEquippedShard then
                    unequipCleansingShardOnly()
                end
            else
                setStatus("Shard: scanning garden (" .. mode .. ", keep " .. tostring(keepN) .. ")")
                local pets = collectPetModelsForOwner()
                local badTargets = {}
                local bag = getBagData()
                local favSkip, emptyMut, scopedSkip = 0, 0, 0

                for _, it in ipairs(pets) do
                    if not uuidInOnlyScope(it.uuid) then
                        scopedSkip += 1
                    else
                        local rec = getPetRecordForUUID(it.uuid, bag)
                        if isFavoriteUUID(it.uuid, rec) then
                            favSkip += 1
                        else
                            local raw = getRawMutationFromUUID(it.uuid, rec)
                            if tostring(raw) == "" then
                                emptyMut += 1
                            elseif isBadMutation(raw, keepMap) then
                                it.rawMut = raw
                                badTargets[#badTargets + 1] = it
                            end
                        end
                    end
                end

                setStatus(string.format(
                    "Shard: garden %d | dirty %d | favSkip %d | emptyMut %d | skipScope %d | %s keep %d",
                    #pets, #badTargets, favSkip, emptyMut, scopedSkip, mode, keepN
                ))

                if #badTargets > 0 then
                    setStatus("Shard: unequip other tools, equip Cleansing Pet Shard...")
                    local okHold, shardTool = ensureEquipped()
                    if okHold and shardTool then
                        weEquippedShard = true
                        for i, it in ipairs(badTargets) do
                            if not fireCleanseModel(it.model, i, #badTargets, it.rawMut) then
                                break
                            end
                        end
                        -- Keep shard in hand while still dirty; next scan may apply more
                    else
                        setStatus("Shard: ERROR — Cleansing Pet Shard not in hand (hand=" .. handText() .. ")")
                    end
                else
                    -- Tidak ada target: jangan spam unequip sprinkler/tool lain
                    if weEquippedShard then
                        unequipCleansingShardOnly()
                    end
                end
            end
        else
            setStatus("Shard: idle (run flag OFF — need toggle + AutoKG Stage A)")
            if weEquippedShard then
                unequipCleansingShardOnly()
            end
        end

        task.wait(SCAN_EVERY)
    end
end)

