-- UUID helpers
----------------------------------------------------------------
local function normalizeUUID(u)
    if not u then return nil, nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    return core, "{" .. core .. "}"
end

local function trackKey(petCore, meta)
    return tostring(petCore)
        .. "\0" .. tostring(meta and meta.boostType or "")
        .. "\0" .. tostring(meta and meta.amount or 0)
end

local function amountsMatch(a, b)
    a = tonumber(a)
    b = tonumber(b)
    if not a or not b then return false end
    return math.abs(a - b) < 0.011
end

----------------------------------------------------------------
-- Profile / PetData
----------------------------------------------------------------
local function getProfile()
    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if ok and type(profile) == "table" and next(profile) ~= nil then
        return profile
    end
    return nil
end

local function getPetDataFromProfile(profile, petCore, petBraced)
    local inv = profile and profile.PetsData and profile.PetsData.PetInventory
    local data = inv and inv.Data
    if type(data) ~= "table" then return nil end

    local rec = data[petBraced] or data[petCore]
    if type(rec) ~= "table" then return nil end
    return rec.PetData
end

----------------------------------------------------------------
-- Parse boost tool name → boostType, amount, duration
----------------------------------------------------------------
local function parseBoostToolMeta(tool)
    if not tool then return nil end

    local reg = getRegistry()
    local name = tostring(tool.Name or "")
    if name == "" then return nil end

    local modelMap = reg.PetModelNameToBoostType or FALLBACK_REGISTRY.PetModelNameToBoostType
    local statData = reg.BoostTypeStatData or FALLBACK_REGISTRY.BoostTypeStatData

    for modelName, boostType in pairs(modelMap) do
        if name:find(modelName, 1, true) then
            local stats = statData[boostType]
            local amounts = stats and stats.Amount
            local times = stats and stats.Time
            if type(amounts) == "table" and type(times) == "table" then
                for sizeKey, amount in pairs(amounts) do
                    if name:find(sizeKey, 1, true) then
                        local duration = tonumber(times[sizeKey]) or 0
                        return {
                            boostType = boostType,
                            size = sizeKey,
                            amount = tonumber(amount) or 0,
                            duration = duration,
                            toolName = name,
                        }
                    end
                end
            end
        end
    end

    return nil
end

----------------------------------------------------------------
-- Baca PetData.Boosts (array game):
--   [1] = { BoostType, BoostAmount, Time }  -- Time = sisa detik
----------------------------------------------------------------
local function getBoostsBucket(petData)
    if type(petData) ~= "table" then return nil end
    local boosts = petData.Boosts
    if type(boosts) == "table" then
        return boosts
    end
    return nil
end

local function entryBoostType(entry)
    if type(entry) ~= "table" then return nil end
    return entry.BoostType or entry.Type or entry.boostType
end

local function readNumber(entry, keys)
    if type(entry) ~= "table" then return nil end
    for _, key in ipairs(keys) do
        local v = entry[key]
        if type(v) == "number" then
            return v
        end
    end
    return nil
end

local function getBoostAmount(entry)
    return readNumber(entry, {
        "BoostAmount", "Amount", "Value", "BoostValue", "StatValue",
    })
end

local function findBoostEntryForMeta(petData, meta)
    if type(meta) ~= "table" or not meta.boostType then
        return nil
    end

    local bucket = getBoostsBucket(petData)
    if not bucket then
        return nil
    end

    local boostType = meta.boostType
    local targetAmount = meta.amount

    for _, entry in pairs(bucket) do
        if type(entry) == "table" and entryBoostType(entry) == boostType then
            if targetAmount and targetAmount > 0 then
                if amountsMatch(getBoostAmount(entry), targetAmount) then
                    return entry
                end
            else
                return entry
            end
        end
    end

    return nil
end

local function getBoostExpiryAt(entry, now)
    if type(entry) ~= "table" then
        return nil
    end

    now = now or serverNow()

    -- game: Time = sisa detik (contoh: 56, 86393.5)
    local remaining = readNumber(entry, {
        "Time", "TimeRemaining", "Remaining", "RemainingTime", "TimeLeft",
        "DurationLeft", "SecondsLeft",
    })
    if remaining and remaining > 0 then
        return now + remaining
    end

    local endTime = readNumber(entry, {
        "EndTime", "ExpiresAt", "Expiration", "ExpireTime",
        "EndTimestamp", "Expiry", "Expires",
    })
    if endTime and endTime > 1e8 then
        return endTime
    end
    if endTime and endTime > 0 and endTime <= 604800 then
        return now + endTime
    end

    local started = readNumber(entry, { "StartTime", "StartedAt", "AppliedAt" })
    local duration = readNumber(entry, { "Duration", "TotalTime" })
    if started and duration then
        return started + duration
    end

    return nil
end

local function trackedExpiry(petCore, meta)
    return APPLY_TRACK[trackKey(petCore, meta)]
end

local function setTrackedExpiry(petCore, meta, expireAt)
    APPLY_TRACK[trackKey(petCore, meta)] = expireAt
end

local function boostNeedsReapply(petCore, petData, meta, now)
    now = now or serverNow()

    local entry = findBoostEntryForMeta(petData, meta)
    if not entry then
        bprint(
            "Perlu apply (belum aktif):", meta.toolName or meta.size,
            meta.boostType, "amount", meta.amount
        )
        return true
    end

    local expiryAt = getBoostExpiryAt(entry, now)
    if expiryAt and expiryAt > now + 1.5 then
        bprint(
            "Masih aktif:", meta.toolName or meta.size,
            meta.boostType, "amount", meta.amount,
            "sisa", math.floor(expiryAt - now), "s"
        )
        setTrackedExpiry(petCore, meta, expiryAt)
        return false
    end

    local tracked = trackedExpiry(petCore, meta)
    if tracked and tracked > now + 1.5 then
        bprint(
            "Track masih aktif:", meta.toolName or meta.size,
            "sisa", math.floor(tracked - now), "s"
        )
        return false
    end

    bprint(
        "Perlu apply (habis):", meta.toolName or meta.size,
        meta.boostType, "amount", meta.amount
    )
    return true
end

----------------------------------------------------------------
-- Unequip semua tools di character
----------------------------------------------------------------
local function unequipAllTools()
    local char     = LP.Character
    local backpack = LP:FindFirstChild("Backpack") or LP.Backpack
    if not char or not backpack then return end

    for _, inst in ipairs(char:GetChildren()) do
        if inst:IsA("Tool") then
            inst.Parent = backpack
        end
    end
end

----------------------------------------------------------------
-- Cari boost tool di Backpack berdasarkan UUID (attr c)
----------------------------------------------------------------
local function findBoostToolByUUID(boostUUID)
    if not boostUUID then return nil end

    local boostCore = select(1, normalizeUUID(boostUUID))
    if not boostCore then return nil end

    local backpack = LP:FindFirstChild("Backpack") or LP.Backpack
    if not backpack then return nil end

    for _, tool in ipairs(backpack:GetChildren()) do
        if tool:IsA("Tool") then
            local attr = tool:GetAttribute("c") or tool:GetAttribute("C")
            if attr then
                local attrCore = select(1, normalizeUUID(attr))
                if attrCore == boostCore then
                    return tool
                end
            end
        end
    end

    return nil
end

local function equipTool(tool)
    local char = LP.Character
    if not char or not tool then return false end

    unequipAllTools()
    tool.Parent = char
    task.wait(0.4)
    return true
end

----------------------------------------------------------------
-- Selected PET filter (UUID map)
----------------------------------------------------------------
local function buildSelectedPetUUIDSet()
    local src = (_G.SELECTED_PET_TYPES ~= nil and _G.SELECTED_PET_TYPES)
            or (SELECTED_PET_TYPES ~= nil and SELECTED_PET_TYPES)
            or {}

    if type(src) ~= "table" then
        return nil
    end

    local hasAny = false
    for _, enabled in pairs(src) do
        if enabled then
            hasAny = true
            break
        end
    end

    if not hasAny then
        return nil -- ALL
    end

    local out = {}
    for k, enabled in pairs(src) do
        if enabled then
            local core, br = normalizeUUID(k)
            if core then out[core] = true end
            if br then out[br] = true end
            out[tostring(k)] = true
        end
    end

    return out
end

----------------------------------------------------------------
-- Ambil active pets sesuai UUID filter
----------------------------------------------------------------
local function getActivePetsFiltered(profile)
    local out = {}

    local cps = ActivePetsService.ClientPetState
    if type(cps) ~= "table" then return out end

    local perPlayer = cps[LP] or cps[LP.UserId] or cps[LP.Name]
    if type(perPlayer) ~= "table" then return out end

    local selectedUUIDSet = buildSelectedPetUUIDSet()

    for uuidKey, handlers in pairs(perPlayer) do
        if type(handlers) == "table" then
            local rec = handlers.PetModelHandler
                    or handlers.PetVFXHandler
                    or handlers.PetSoundHandler

            if type(rec) == "table" then
                local core, braced = normalizeUUID(rec.UUID or uuidKey)
                if core and braced then
                    local allowed = (selectedUUIDSet == nil)
                        or selectedUUIDSet[core]
                        or selectedUUIDSet[braced]
                        or selectedUUIDSet[tostring(rec.UUID or uuidKey)]

                    if allowed then
                        local pd = rec.PetData or rec.Data or {}
                        local pt = pd.PetType or rec.PetType or rec.Name
                        local petTypeName = pt and tostring(pt) or "?"

                        local profilePd = getPetDataFromProfile(profile, core, braced)
                        if type(profilePd) == "table" then
                            pd = profilePd
                        end

                        table.insert(out, {
                            uuidCore   = core,
                            uuidBraced = braced,
                            petType    = petTypeName,
                            petData    = pd,
                        })
                    end
                end
            end
        end
    end

    return out
end

----------------------------------------------------------------
-- Ambil boost UUID terpilih
----------------------------------------------------------------
local function getSelectedBoostUUIDs()
    local list = {}
    local src = _G.PETBOOST_SELECTED or PETBOOST_SELECTED

    if type(src) ~= "table" then
        return list
    end

    for uuid, enabled in pairs(src) do
        if enabled then
            table.insert(list, uuid)
        end
    end

    return list
end

-- Semua item terpilih dicek satu per satu (Small/Medium/Large = entry terpisah by amount).
local function buildSelectedBoostPlans(boostUUIDs)
    local list = {}

    for _, boostUUID in ipairs(boostUUIDs) do
        local tool = findBoostToolByUUID(boostUUID)
        local meta = parseBoostToolMeta(tool)
        if tool and meta then
            list[#list + 1] = {
                uuid = boostUUID,
                tool = tool,
                meta = meta,
            }
        end
    end

    table.sort(list, function(a, b)
        if a.meta.boostType ~= b.meta.boostType then
            return tostring(a.meta.boostType) < tostring(b.meta.boostType)
        end
        return (a.meta.amount or 0) < (b.meta.amount or 0)
    end)

    return list
end

----------------------------------------------------------------
-- Hitung waktu tidur loop berikutnya
----------------------------------------------------------------
local function computeNextSleepSec(profile, pets, boostUUIDs, now)
    local maxPoll = tonumber(_G.AUTO_BOOST_DELAY or AUTO_BOOST_DELAY) or DEFAULT_DELAY
    maxPoll = math.max(maxPoll, MIN_POLL_SEC)

    local nextWake = now + maxPoll

    for _, info in ipairs(pets) do
        local petData = info.petData
        if type(petData) ~= "table" then
            petData = getPetDataFromProfile(profile, info.uuidCore, info.uuidBraced) or petData
        end

        local plans = buildSelectedBoostPlans(boostUUIDs)
        for _, plan in ipairs(plans) do
            local meta = plan.meta
            local entry = findBoostEntryForMeta(petData, meta)
            local expiryAt = getBoostExpiryAt(entry, now)
                or trackedExpiry(info.uuidCore, meta)

            if expiryAt and expiryAt > now then
                local wakeAt = expiryAt + 0.75
                if wakeAt < nextWake then
                    nextWake = wakeAt
                end
            end
        end
    end

    local sleepSec = nextWake - now
    if sleepSec < MIN_POLL_SEC then
        sleepSec = MIN_POLL_SEC
    end
    if sleepSec > maxPoll and nextWake == now + maxPoll then
        sleepSec = maxPoll
    end

    return sleepSec
end

----------------------------------------------------------------
-- APPLY BOOST (hanya kalau perlu)
----------------------------------------------------------------
local function applyAutoBoostOnce(myToken)
    if not PetBoostRE then
        bwarn("PetBoostRE tidak ditemukan (GameEvents.PetBoostService)")
        return false, MIN_POLL_SEC
    end
    if (not AUTO_BOOST_RUNNING) or (myToken ~= STOP_TOKEN) then return false, MIN_POLL_SEC end

    local boostUUIDs = getSelectedBoostUUIDs()
    if #boostUUIDs == 0 then
        bwarn("PETBOOST_SELECTED kosong — pilih item boost di UI")
        return false, MIN_POLL_SEC
    end

    local profile = getProfile()
    local pets = getActivePetsFiltered(profile)
    if #pets == 0 then
        bwarn("Tidak ada pet aktif (cek filter Select Pet To Boost)")
        return false, MIN_POLL_SEC
    end

    local now = serverNow()
    local usedAny = false
    local plans = buildSelectedBoostPlans(boostUUIDs)
    if #plans == 0 then
        bwarn("Item boost terpilih tidak ketemu/ter-parse di backpack:", #boostUUIDs)
        return false, MIN_POLL_SEC
    end

    bprint("tick pets=", #pets, "items=", #plans, "selectedUUIDs=", #boostUUIDs)

    for _, info in ipairs(pets) do
        if (not AUTO_BOOST_RUNNING) or (myToken ~= STOP_TOKEN) then break end

        local uuidBraced = info.uuidBraced
        local petType    = info.petType or "?"
        local petData    = info.petData

        for _, plan in ipairs(plans) do
            if (not AUTO_BOOST_RUNNING) or (myToken ~= STOP_TOKEN) then break end

            local tool = plan.tool
            local meta = plan.meta
            if not tool or not meta then
                bwarn("Boost tool/meta missing:", plan.uuid)
            elseif boostNeedsReapply(info.uuidCore, petData, meta, now) then
                bprint(
                    "Apply boost:", petType, uuidBraced,
                    meta.toolName or tool.Name,
                    "type", meta.boostType,
                    "amount", meta.amount,
                    "duration", meta.duration
                )

                if equipTool(tool) then
                    if (not AUTO_BOOST_RUNNING) or (myToken ~= STOP_TOKEN) then
                        unequipAllTools()
                        break
                    end

                    task.wait(0.2)

                    local ok = pcall(function()
                        PetBoostRE:FireServer("ApplyBoost", uuidBraced)
                    end)

                    if ok then
                        usedAny = true
                        local duration = tonumber(meta.duration) or 0
                        if duration > 0 then
                            setTrackedExpiry(info.uuidCore, meta, now + duration)
                        end
                        bprint("ApplyBoost OK:", uuidBraced, tool.Name, "duration", duration)
                    else
                        bwarn("ApplyBoost FAIL:", uuidBraced, tool.Name)
                    end

                    task.wait(0.2)
                    unequipAllTools()
                end
            else
                bprint(
                    "Skip boost:", petType, meta.boostType,
                    "keep", meta.toolName or tool.Name,
                    "amount", meta.amount
                )
            end
        end
    end

    local sleepSec = computeNextSleepSec(profile, pets, boostUUIDs, serverNow())
    return usedAny, sleepSec
end

----------------------------------------------------------------
-- PUBLIC MODULE
----------------------------------------------------------------
local M = {}

function M.isRunning()
    return AUTO_BOOST_RUNNING
end

function M.setDelay(a, b)
    local v = (type(a) == "table") and b or a
    local n = tonumber(v)
    if not n or n <= 0 then return end
    n = math.floor(n + 0.5)
    AUTO_BOOST_DELAY = n
    _G.AUTO_BOOST_DELAY = n
    local G = (getgenv and getgenv()) or _G
    G.AUTO_BOOST_DELAY = n
end

function M.start()
    if AUTO_BOOST_RUNNING then
        bprint("start() ignored — sudah running")
        return
    end
    if not isEnabled() then
        bprint("start() ignored — AUTO_BOOST_ENABLED=false")
        return
    end

    AUTO_BOOST_RUNNING = true
    bprint("worker START")

    local myToken = STOP_TOKEN

    AUTO_BOOST_THREAD = task.spawn(function()
        while AUTO_BOOST_RUNNING and (myToken == STOP_TOKEN) do
            if not isEnabled() then
                bprint("worker STOP — toggle OFF")
                M.stop()
                break
            end

            local ok, errMsg, sleepSec = pcall(function()
                return applyAutoBoostOnce(myToken)
            end)
            if not ok then
                warn("[AutoKGBoost] loop error:", tostring(errMsg))
                sleepSec = DEFAULT_DELAY
            end
            sleepSec = tonumber(sleepSec) or DEFAULT_DELAY
            sleepSec = math.max(sleepSec, MIN_POLL_SEC)
            bprint("sleep", sleepSec, "s")

            local t = sleepSec
            while t > 0 and AUTO_BOOST_RUNNING and (myToken == STOP_TOKEN) do
                if not isEnabled() then
                    bprint("worker STOP — toggle OFF (sleep)")
                    M.stop()
                    break
                end
                task.wait(1)
                t -= 1
            end
        end
        bprint("worker EXIT")
    end)
end

function M.stop()
    if AUTO_BOOST_RUNNING then
        bprint("worker STOP requested")
    end
    AUTO_BOOST_RUNNING = false
    STOP_TOKEN += 1
    AUTO_BOOST_THREAD  = nil
    pcall(unequipAllTools)
end

function M.syncFromState(_state)
    local G = (getgenv and getgenv()) or _G
    if G.AUTO_BOOST_ENABLED ~= nil then
        AUTO_BOOST_ENABLED = (G.AUTO_BOOST_ENABLED == true)
    end
    _G.AUTO_BOOST_ENABLED = (AUTO_BOOST_ENABLED == true)
    G.AUTO_BOOST_ENABLED = _G.AUTO_BOOST_ENABLED

    local d = tonumber(G.AUTO_BOOST_DELAY or _G.AUTO_BOOST_DELAY or AUTO_BOOST_DELAY) or DEFAULT_DELAY
    M.setDelay(d)

    if isEnabled() then
        M.start()
    else
        M.stop()
    end
end

function M.SetEnabled(a, b)
    local on = a
    if type(a) == "table" then
        on = b
    end
    local v = (on == true)
    local G = (getgenv and getgenv()) or _G
    G.AUTO_BOOST_ENABLED = v
    _G.AUTO_BOOST_ENABLED = v
    AUTO_BOOST_ENABLED = v
    if v then M.start() else M.stop() end
end

function M.ApplyConfig()
    M.syncFromState()
end

M.Stop       = M.stop
M.Start      = M.start
M.SetDelay   = M.setDelay
M.SyncFromState = M.syncFromState

_G.AutoBoost      = M
_G.AutoKGBoost    = M
_G.auto_hatchBoost = M

if DEBUG_BOOST then
    print("[AutoKGBoost] module loaded, PetBoostRE=", PetBoostRE ~= nil)
end

return M

