local NO_MUTATION_KEY   = "__NO_MUTATION__"
local NO_MUTATION_LABEL = "[TANPA MUTASI]" -- cuma buat UI, di sini nggak dipakai

GIFT_CFG = GIFT_CFG or {}

----------------------------------------------------------------
-- DEBUG UTIL
----------------------------------------------------------------
local function dbg(...)
    if AUTO_GIFT_DEBUG then
        print("[AutoGift]", ...)
    end
end

local function _debugSkip(tag, reason, ...)
    if not AUTO_GIFT_DEBUG then return end
    print("[AutoGift][SKIP]", "["..tostring(tag).."]", reason, ...)
end



local function _useTradeMode()
    if not GIFT_CFG then return false end

    return GIFT_CFG.prioTicket  == true
        or GIFT_CFG.prioTicketB == true
        or GIFT_CFG.prioTicketC == true
end

local function _clearGiftBusy()
    _giftBusy = false
    _giftHoldUntil = 0
end

----------------------------------------------------------------
-- FAVORITE HELPERS (Tool only)
----------------------------------------------------------------
local function isToolFavorited(tool)
    if not tool or not tool:IsA("Tool") then return false end
    return tool:GetAttribute("d") == true
        or tool:GetAttribute("Favorite") == true
        or tool:GetAttribute("IsFavorite") == true
        or tool:GetAttribute("Fav") == true
        or tool:GetAttribute("fav") == true
end

local function setToolFavorite(tool, wantFav)
    if not tool or not FavoriteItemRE then
        return false
    end

    local cur = (isToolFavorited(tool) == true)
    wantFav = (wantFav == true)

    if cur == wantFav then
        -- status sudah sesuai, tidak usah kirim RE lagi
        return false
    end

    local ok, err = pcall(function()
        FavoriteItemRE:FireServer(tool)
    end)

    if not ok then
        _debugSkip(tool.Name or "?", "fav_toggle_fail", err)
        return false
    end

    dbg(string.format("[FAV] Toggle %s → wantFav=%s", tool:GetFullName(), tostring(wantFav)))
    return true
end

local function _getToolUUID(tool)
    if not (tool and tool.Parent) then return nil end
    return tool:GetAttribute("PET_UUID")
        or tool:GetAttribute("UUID")
        or tool:GetAttribute("PetUUID")
end


