-- TRADE CORE (NO GUI, NO TradeBridge) - ReplicationReciever
----------------------------------------------------------------
local RunService = game:GetService("RunService")

local function safeRequire(obj)
    local ok, mod = pcall(function() return require(obj) end)
    return ok and mod or nil
end

local ReplicationReciever = safeRequire(
    ReplicatedStorage:FindFirstChild("Modules") and ReplicatedStorage.Modules:FindFirstChild("ReplicationReciever")
)

local TradeData = safeRequire(
    ReplicatedStorage:FindFirstChild("Data") and ReplicatedStorage.Data:FindFirstChild("TradeData")
) or { ButtonCooldown = 0 }

-- remotes (sesuaikan nama seperti di referensi kamu)
local UpdateState   = TradeEvents and (TradeEvents:FindFirstChild("UpdateTradeState") or TradeEvents:FindFirstChild("UpdatedTradeState"))
local DeclineEv     = TradeEvents and (TradeEvents:FindFirstChild("Decline") or TradeEvents:FindFirstChild("DeclineTrade"))

-- anti spam + session
local _trade = {
    inFlight = false,
    targetUserId = nil,

    tradeId = nil,
    replicator = nil,

    cooldownUntil = 0,
    perTargetCooldown = {}, -- [userId] = time
}

local TIMEOUT_READY  = TRADE_TIMEOUT_OPEN or 6
local TIMEOUT_ACTION = TRADE_TIMEOUT_STEP or 6

local TRADE_FAIL_COOLDOWN      = 3
local TRADE_DECLINE_COOLDOWN   = 5
local TRADE_BUSY_COOLDOWN      = 8

local function _now() return os.clock() end

local function _waitUntil(pred, timeout)
    local t0 = os.clock()
    while os.clock() - t0 < (timeout or 10) do
        local ok, why = pred()
        if ok then return true, why end
        RunService.Heartbeat:Wait()
    end
    return false, "timeout"
end

local function _destroyRep()
    if _trade.replicator then
        pcall(function() _trade.replicator:Destroy() end)
    end
    _trade.replicator = nil
end

local function _resetTradeSession()
    _trade.inFlight = false
    _trade.targetUserId = nil
    _trade.tradeId = nil
    _destroyRep()
end

local function _setTargetCD(userId, secs)
    if not userId then return end
    _trade.perTargetCooldown[userId] = _now() + (secs or 0)
end

-- hook UpdateTradeState => tradeId (atau kadang string/message)
local _tradeHooked = false
