    if _tradeHooked then return end
    _tradeHooked = true

    if UpdateState and UpdateState:IsA("RemoteEvent") and ReplicationReciever then
        UpdateState.OnClientEvent:Connect(function(arg)
            -- Ada game yg kirim tradeId string, ada yg kirim message.
            -- Kita handle dua-duanya:
            if typeof(arg) == "string" then
                -- kalau ini looks like tradeId => buat replicator
                -- kalau ini message declined => kasih cooldown
                local low = string.lower(arg)
if string.find(low, "declined", 1, true) then
    if _trade.targetUserId then
        _setTargetCD(_trade.targetUserId, 1.5) -- manual decline jangan lama
    end

    _resetTradeSession()
    _clearGiftBusy()
    _resumeAutoHatchIfNeeded()
    return
end

if string.find(low, "busy", 1, true) then
    if _trade.targetUserId then
        _setTargetCD(_trade.targetUserId, 5)
    end

    _resetTradeSession()
    _clearGiftBusy()
    _resumeAutoHatchIfNeeded()
    return
end

                -- treat sebagai tradeId
                _trade.tradeId = arg
            elseif arg == nil then
                _trade.tradeId = nil
            else
                -- kalau tradeId bukan string, biarin (rare)
                _trade.tradeId = arg
            end

            _destroyRep()
            if _trade.tradeId then
                local ok, rep = pcall(function()
                    return ReplicationReciever.new(_trade.tradeId)
                end)
                if ok and rep then
                    _trade.replicator = rep
                end
            end
        end)
    end
end
_hookTradeOnce()

-- cooldown satisfied (TradeData.ButtonCooldown + lastChange)
local function _cooldownSatisfied()
    if not _trade.replicator then return false, "no_rep" end
    local d = _trade.replicator:GetData()
    if not d then return false, "no_data" end

    local cd = tonumber(TradeData.ButtonCooldown) or 0
    local lastChange = tonumber(d.lastChange) or 0
    local delta = workspace:GetServerTimeNow() - lastChange
    return (delta >= cd), ("delta="..tostring(delta).." cd="..tostring(cd))
end

local _waitTradeClosed  -- forward declare (WAJIB)


local function _forceDecline(reason)
    local uid = _trade.targetUserId  -- simpan dulu

    if DeclineEv and DeclineEv:IsA("RemoteEvent") then
        pcall(function()
            DeclineEv:FireServer()
        end)
    end

    if _waitTradeClosed then
        _waitTradeClosed(2.5)
    end

    _resetTradeSession()
    _clearGiftBusy()

if uid then
    if reason == "target_decline" then
        _setTargetCD(uid, 10)
    elseif reason == "busy" then
        _setTargetCD(uid, TRADE_BUSY_COOLDOWN)
    else
        _setTargetCD(uid, 3)
    end
end
end



local function _getMyOffer()
    if not _trade.replicator then return nil end
    local data = _trade.replicator:GetData()
    if not data then return nil end

    local myIdx
    for i,p in ipairs(data.players or {}) do
        if p == LocalPlayer then myIdx = i break end
    end
    if not myIdx then return nil end

    local bucket = (data.offers and data.offers[myIdx]) or {}
    return {
        items = bucket.items or {},
        sheckles = bucket.sheckles or 0,
        states = data.states or {},
        players = data.players or {}
    }
end

local function _myOfferCount()
    local o = _getMyOffer()
    if not o then return nil end
    local c = 0
    for _ in pairs(o.items) do c += 1 end
    return c
end

local function _hasItemInMyOffer(typeName, uuid)
    local o = _getMyOffer()
    if not o then return false end
    for _, it in pairs(o.items) do
        if it and it.type == typeName and it.id == uuid then
            return true
        end
    end
    return false
end

local function _bothAccepted()
    local o = _getMyOffer()
    if not o then return false, "no_offer" end

    local players, states = o.players, o.states
    local myIdx
    for i,p in ipairs(players) do
        if p == LocalPlayer then myIdx = i break end
    end
    if not myIdx then return false, "no_myidx" end

    local otherIdx = (myIdx == 1) and 2 or 1
    return (states[myIdx] == "Accepted" and states[otherIdx] == "Accepted"), "both_accepted"
end

local function _canRequest(target)
    if not target then return false, "no_target" end
    local t = _now()

    if t < (_trade.cooldownUntil or 0) then
        return false, "global_cd"
    end
    local tcd = _trade.perTargetCooldown[target.UserId]
    if tcd and t < tcd then
        return false, "target_cd"
    end
    if _trade.inFlight then
        return false, "inflight"
    end
    return true, "ok"
end

local function _sendRequest(target)
    local ok, why = _canRequest(target)
    if not ok then
        return false, why
    end

    _trade.inFlight = true
    _trade.targetUserId = target.UserId
    _trade.tradeId = nil
    _destroyRep()

    pcall(function()
        SendRequestRE:FireServer(target)
    end)

    return true, "sent"
end

local function _waitReplicatorReady(timeout)
    local ok = _waitUntil(function()
        if _trade.replicator then
            local o = _getMyOffer()
            if o then return true, "rep_ready" end
        end
        return false, "wait_rep"
    end, timeout or TIMEOUT_READY)

    if not ok then
        -- gagal open -> cooldown supaya gak spam
        if _trade.targetUserId then
            _setTargetCD(_trade.targetUserId, TRADE_FAIL_COOLDOWN)
        end
        _trade.cooldownUntil = _now() + TRADE_FAIL_COOLDOWN
        _resetTradeSession()
        return false
    end

    _trade.inFlight = false
    return true
end

-- forward declare (sudah ada di atas):
-- local _waitTradeClosed

_waitTradeClosed = function(timeout)
    return _waitUntil(function()
        -- kalau replicator hilang / tradeId nil => dianggap closed
        if not _trade.tradeId then return true, "closed_nil" end
        if not _trade.replicator then return true, "closed_norep" end
        local d = _trade.replicator:GetData()
        if not d then return true, "closed_nodata" end
        -- beberapa game set players kosong saat close
        if not d.players or #d.players == 0 then return true, "closed_players0" end
        return false, "still_open"
    end, timeout or TIMEOUT_ACTION)
end



local function _getBackpack()
    return LocalPlayer:FindFirstChildOfClass("Backpack")
        or LocalPlayer:FindFirstChild("Backpack")
end

local function _isPetTool(t)
    if not (t and t:IsA("Tool")) then return false end
    local it = t:GetAttribute("ItemType") or t:GetAttribute("Itemtype")
    return it and string.lower(tostring(it)) == "pet"
end


local function _isTradeAddableTool(tool)
    if not (tool and tool.Parent and tool:IsA("Tool")) then
        return false
    end

    if not _isPetTool(tool) then
        return false
    end

    if isToolFavorited(tool) then
        return false
    end

    local uuid = _getToolUUID(tool)
    if not uuid then
        return false
    end

    return true
end


local function _countTargetBackpack(plr)
    if not (plr and plr:IsA("Player")) then
        return math.huge
    end
    local bp = plr:FindFirstChild("Backpack")
    if not bp then
        return math.huge
    end
    local cnt = 0
    for _, child in ipairs(bp:GetChildren()) do
        if _isPetTool(child) then
            cnt += 1
        end
    end
    return cnt
end

local function _pickLeastBackpackTarget(targets)
    if type(targets) ~= "table" or #targets == 0 then
        return nil
    end
    if #targets == 1 then
        return targets[1]
    end

    local best, bestCnt
    for _, p in ipairs(targets) do
        local c = _countTargetBackpack(p)
        if not best or c < bestCnt then
            best = p
            bestCnt = c
        end
    end
    return best or targets[1]
end

local function _unequipAllTools()
    local char = LocalPlayer.Character
    if not char then return end

    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end

    local bp = _getBackpack()
    if not bp then return end

    -- Pindahkan SEMUA tool dari character ke backpack
    for _, obj in ipairs(char:GetChildren()) do
        if obj:IsA("Tool") then
            obj.Parent = bp
        end
    end

    task.wait(0.05)
end

local function _ensureHoldingTradingTicket()

    local char = LocalPlayer.Character
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if not (char and hum) then return false end

    -- already holding
    for _, t in ipairs(char:GetChildren()) do
        if t:IsA("Tool") and string.find(string.lower(t.Name), string.lower(TICKET_NAME), 1, true) then
            return true
        end
    end

    local bp = _getBackpack()
    if not bp then return false end

    for _, t in ipairs(bp:GetChildren()) do
        if t:IsA("Tool") and string.find(string.lower(t.Name), string.lower(TICKET_NAME), 1, true) then
            hum:UnequipTools()
            hum:EquipTool(t)
            return true
        end
    end

    return false
end

local function _takeTradeBatch(queue)
    local batch = {}

    -- ambil lebih banyak dari 12 sebagai cadangan
    local count = math.min(#queue, TRADE_MAX_ITEMS_PER_SESSION + 15)

    for i = 1, count do
        batch[#batch+1] = queue[i]
    end

    return batch
end

----------------------------------------------------------------
-- TARGET: GIFT_CFG.targets / targetsB / targetsC
----------------------------------------------------------------
local function _getGiftTargets(which)
    which = which or "targets"
    local result = {}

    if GIFT_CFG and GIFT_CFG[which] and next(GIFT_CFG[which]) ~= nil then
        for key, info in pairs(GIFT_CFG[which]) do
            local userId = info.userId or tonumber(key)
            local name   = info.name

            local plr
            if userId then
                plr = Players:GetPlayerByUserId(userId)
            end

            if (not plr) and name and name ~= "" then
                local want = string.lower(name)
                for _, p in ipairs(Players:GetPlayers()) do
                    if string.lower(p.Name) == want then
                        plr = p
                        break
                    end
                end
            end

            if plr then
                table.insert(result, plr)
            end
        end

        return result
    end

    -- fallback lama (kalau config lama masih ada)
    if which == "targets" then
        local target
        if GIFT_CFG and GIFT_CFG.targetUserId then
            target = Players:GetPlayerByUserId(GIFT_CFG.targetUserId)
        end
        if (not target) and GIFT_CFG and GIFT_CFG.targetName and GIFT_CFG.targetName ~= "" then
            local want = string.lower(GIFT_CFG.targetName)
            for _, p in ipairs(Players:GetPlayers()) do
                if string.lower(p.Name) == want then
                    target = p
                    break
                end
            end
        end
        if target then
            table.insert(result, target)
        end
    end

    return result
end

----------------------------------------------------------------
-- PET TYPE FILTER (petType / petTypeB / petTypeC)
----------------------------------------------------------------
local function _passesPetType(petTypeNorm, cfgMap)
    if not cfgMap or type(cfgMap) ~= "table" then
        -- tidak ada map → filter off
        return true
    end

    local hasAny = false
    for _, v in pairs(cfgMap) do
        if v then
            hasAny = true
            break
        end
    end

    if not hasAny then
        -- tidak ada yang dipilih → filter off (semua boleh)
        return true
    end

    if not petTypeNorm or petTypeNorm == "" then
        return false
    end

    for key, enabled in pairs(cfgMap) do
        if enabled then
            if petTypeNorm == tostring(key):lower() then
                return true
            end
        end
    end

    return false
end

----------------------------------------------------------------
-- W100 / AGE FILTER
--   kgRaw:
--      >0  → W100 >= kgRaw
--      <0  → W100 <= |kgRaw|
--   ageRaw:
--      0   → age <= 1
--      >0  → age >= ageRaw
--      <0  → age <= |ageRaw|
----------------------------------------------------------------
local function _passesGiftGroup(weightArg, age, kgRaw, ageRaw)
    kgRaw  = tonumber(kgRaw)  or 0
    ageRaw = tonumber(ageRaw) or 0

    local kgLimit   = math.abs(kgRaw)
    local useMaxKG  = (kgRaw < 0)

    -- AGE:
    --  >0  → age >= value
    --  <0  → age <= |value|
    --   0  → TIDAK filter umur (bebas)
    local ageLimit  = math.abs(ageRaw)
    local useMaxAge = (ageRaw < 0)

    if kgLimit > 0 then
        if (not useMaxKG) and weightArg < kgLimit then
            return false
        elseif useMaxKG and weightArg > kgLimit then
            return false
        end
    end

    if ageLimit > 0 then
        if (not useMaxAge) and age < ageLimit then
            return false
        elseif useMaxAge and age > ageLimit then
            return false
        end
    end

    return true
end


----------------------------------------------------------------
-- MUTASI FILTER per Gift group
--   mutMap (map name → true)
--   Semantik BARU:
--   • mutMap NIL / kosong  → TIDAK filter mutasi (semua lolos)
--   • mutMap punya NO_MUTATION_KEY = true  → boleh pilih pet tanpa mutasi
--   • mutMap punya nama mutasi lain       → pet harus punya salah satu mutasi tsb
--   Kombinasi:
--      - Hanya [TANPA MUTASI]      → hanya pet tanpa mutasi
--      - Hanya ["Giant","Mini"]   → hanya pet dengan Giant/Mini
--      - [TANPA MUTASI]+["Giant"] → pet tanpa mutasi ATAU punya Giant
----------------------------------------------------------------
local function _matchGiftMutation(rec, helpers, mutMap)
    -- fallback: kalau mutMap nil, coba pakai global lama (kompat)
    if mutMap == nil and type(GIFT_CFG) == "table" and type(GIFT_CFG.mut) == "table" then
        mutMap = GIFT_CFG.mut
    end

    mutMap = (type(mutMap) == "table") and mutMap or {}

    -- mutasi dari record
    local muts   = helpers.mutation_names_from_record(rec) or {}
    local hasMut = (#muts > 0)

    -- cek apakah config punya pilihan (ada yang true)
    local hasSelected = false
    for _, v in pairs(mutMap) do
        if v then
            hasSelected = true
            break
        end
    end

    -- ❌ TIDAK ADA PILIHAN → tidak filter mutasi sama sekali
    if not hasSelected then
        -- dbg("mut_cfg_empty → no filter (ALL OK)")
        return true
    end

    -- 🔍 Pisah "no mutation" vs nama mutasi biasa
    local wantNoMutation = false
    local selNames       = {}

    for name, on in pairs(mutMap) do
        if on then
            if name == NO_MUTATION_KEY then
                wantNoMutation = true
            else
                selNames[string.lower(tostring(name))] = true
            end
        end
    end

    -- ✅ Kalau pet PUNYA mutasi
    if hasMut then
        -- Cek apakah salah satu mutasinya ada di selNames
        for _, m in ipairs(muts) do
            if selNames[string.lower(m)] then
                dbg("mut_match", table.concat(muts, "+"))
                return true
            end
        end

        -- Pet punya mutasi, tapi:
        --  • selNames nggak cocok
        --  • kalau cuma "no mutation" yang dipilih → harusnya SKIP
        dbg("mut_has_mut_but_no_match", table.concat(muts, "+"))
        return false
    end

    -- ❗ Pet TIDAK punya mutasi (hasMut == false)
    if wantNoMutation then
        dbg("mut_no_mutation_match (pet_no_mut)")
        return true
    end

    -- Tidak punya mutasi, tapi user cuma pilih mutasi tertentu (tanpa NO_MUTATION)
    dbg("mut_pet_no_mut_but_cfg_need_mut")
    return false
end



