-- CORE GIVE
----------------------------------------------------------------
----------------------------------------------------------------
-- CORE GIVE (VERSI BARU)
-- • Tidak lagi melakukan unfav per pet di sini
-- • Unfav massal dilakukan di _autoGiftPass() sebelum gift stage
----------------------------------------------------------------
local function _give(uuidFmt, target, tool, allowUnfav)
    -- allowUnfav sekarang diabaikan (dipertahankan biar signature tidak berubah)
    -- karena unfav sudah dilakukan massal sebelum gift.
    if not PetGiftingService then
        _debugSkip(uuidFmt, "PetGiftingService_nil")
        return false
    end

    local useTool = tool

    -- Cari Tool jika belum diberikan
    if not useTool then
        local bp = _getBackpack()
        if bp then
            for _, t in ipairs(bp:GetChildren()) do
                if t:IsA("Tool") then
                    local id = t:GetAttribute("PET_UUID")
                        or t:GetAttribute("UUID")
                        or t:GetAttribute("PetUUID")
                    if id then
                        local coreAttr = tostring(id):match("{?([0-9a-fA-F%-]+)}?") or tostring(id)
                        local fmtAttr = "{" .. coreAttr .. "}"
                        if fmtAttr == uuidFmt or coreAttr == uuidFmt then
                            useTool = t
                            break
                        end
                    end
                end
            end
        end
    end

    if not useTool then
        _debugSkip(uuidFmt, "tool_not_found")
        return false
    end

    -- Safety: jika masih favorit, jangan gift (karena stage unfav harusnya sudah handle)
    if isToolFavorited(useTool) then
        _debugSkip(uuidFmt, "still_favorited_pre_gift_skip")
        return false
    end

    -- Equip tool
    local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then
        _debugSkip(uuidFmt, "no_humanoid")
        return false
    end

    _unequipAllTools()
    task.wait(0.25)

    useTool.Parent = char
    task.wait(0.05)

    pcall(function()
        hum:EquipTool(useTool)
    end)
    task.wait(0.30)

    -- Gift
    local ok, res = pcall(function()
        return PetGiftingService:GivePet(target)
    end)

    if not ok then
        _debugSkip(uuidFmt, "GivePet_err", res)
    end

    -- Unequip
    task.wait(0.20)
    _unequipAllTools()
    task.wait(AUTO_GIFT_GIFT_DELAY)

    return ok and res ~= false
end

----------------------------------------------------------------
-- TRADE BATCH (UPDATED)
-- - Busy hold cuma kalau trade benar2 dimulai (request sukses)
-- - Kalau gagal sebelum request / sebelum rep ready -> gak nge-hold lama
----------------------------------------------------------------
local function _runTradeBatch(target, queueBatch)
    if not target or not queueBatch or #queueBatch == 0 then
        return false
    end
    if not (SendRequestRE and AddItemRE and AcceptTradeRE and ConfirmTradeRE and UpdateState and ReplicationReciever) then
        return false
    end

    -- wajib pegang ticket
    if not _ensureHoldingTradingTicket() then
        return false
    end

    -- request trade (kalau ini gagal, JANGAN mark busy panjang)
    local okSend, why = _sendRequest(target)
    if not okSend then
        return false
    end

    -- ✅ trade benar2 dimulai -> tahan busy cukup lama untuk 1 sesi
    -- (biar _autoGiftPass tidak mulai pass baru di tengah sesi)
    _markGiftBusy(6)

    -- tunggu replicator siap
    if not _waitReplicatorReady(TIMEOUT_READY) then
        -- _waitReplicatorReady udah set cooldown & reset session
        return false
    end

task.wait(2)
    -- add items
    -- add items
local added = 0

for _, item in ipairs(queueBatch) do
    if added >= TRADE_MAX_ITEMS_PER_SESSION then
        break
    end

    local tool = item.tool
    if tool and tool.Parent and (not isToolFavorited(tool)) then
        local uuid = tool:GetAttribute("PET_UUID")
            or tool:GetAttribute("UUID")
            or tool:GetAttribute("PetUUID")

        if uuid then
            local beforeCount = _myOfferCount() or 0

            pcall(function()
                AddItemRE:FireServer("Pet", uuid)
            end)

            local okAdd = _waitUntil(function()
                if _hasItemInMyOffer("Pet", uuid) then
                    return true, "match"
                end

                local c = _myOfferCount()
                if c and c > beforeCount then
                    return true, "count"
                end

                return false, "wait_add"
            end, 4)

            if okAdd then
                added += 1
                task.wait(TRADE_DELAY_ADD)
            end
        end
    end
end

if added == 0 then
    _forceDecline("added_0")

    -- jangan langsung scan ulang dan spam send trade
    _markGiftBusy(5)
    return false
end

-- tunggu offer count stabil setelah add terakhir
_waitUntil(function()
    local c = _myOfferCount()
    return c and c >= added
end, 3)

-- tunggu cooldown server, tapi jangan stuck terlalu lama
_waitUntil(_cooldownSatisfied, 6)
task.wait(0.35)

-- accept retry
local accepted = false
for i = 1, 3 do
    pcall(function()
        AcceptTradeRE:FireServer()
    end)

    local okAcc = _waitUntil(function()
        local ok = _bothAccepted()
        if ok then
            return true, "both_accepted"
        end

        local o = _getMyOffer()
        if o then
            for _, st in pairs(o.states or {}) do
                if st == "Accepted" then
                    return true, "some_accepted"
                end
            end
        end

        return false, "wait_accept"
    end, 3)

    if okAcc then
        accepted = true
        break
    end

    task.wait(0.5)
end

if not accepted then
    _forceDecline("accept_timeout")
    return false
end

-- confirm retry
local confirmed = false

for i = 1, 4 do
    _waitUntil(_cooldownSatisfied, 3)
    task.wait(0.35)

    pcall(function()
        ConfirmTradeRE:FireServer()
    end)

    local okClose = _waitTradeClosed(3)
    if okClose then
        confirmed = true
        break
    end

    task.wait(0.5)
end

if not confirmed then
    _forceDecline("confirm_timeout")
    return false
end

_resetTradeSession()
_clearGiftBusy()
task.wait(TRADE_DELAY_AFTER)
return true
end



----------------------------------------------------------------
-- 1 PASS: SCAN BACKPACK & FILTER BY GIFT_CFG (UPDATED)
-- - guard _giftBusy: kalau masih hold, return
-- - BULK UNFAV -> lalu per-group: trade OR give
-- - PENTING: TIDAK ada _markGiftBusy(6.0) sebelum _runTradeBatch
----------------------------------------------------------------
local function _autoGiftPass()
    _markGiftIdleIfDue()

    -- ✅ guard: kalau masih dalam window gift/trade, jangan mulai pass baru
    if _giftBusy then
        return
    end

    local PLV = _resolvePetListView()
    if not PLV or type(PLV.getDatastoreBagIndex) ~= "function" then
        _debugSkip("PASS", "PetListView/getDatastoreBagIndex belum siap")
        return
    end

    local bp = _getBackpack()
    if not bp then
        _debugSkip("PASS", "backpack_nil")
        return
    end

    local bag, index, helpers = PLV.getDatastoreBagIndex()
    if not bag or not index or not helpers then
        _debugSkip("PASS", "datastore_bag_nil")
        return
    end

    local cfg = GIFT_CFG or {}

    -- Build target list per row
    local targets1 = _getGiftTargets("targets")
    local targets2 = _getGiftTargets("targetsB")
    local targets3 = _getGiftTargets("targetsC")

    local groups = {}

    local function addGroup(id, enabledKey, targets, kgKey, ageKey, petTypeKey, autoUnfavKey, mutKey)
        if not (cfg[enabledKey] == true) then
            return
        end
        if not (targets and #targets > 0) then
            return
        end

        table.insert(groups, {
            id         = id,
            targets    = targets,
            kgRaw      = tonumber(cfg[kgKey])      or 0,
            ageRaw     = tonumber(cfg[ageKey])     or 0,
            petTypeMap = cfg[petTypeKey]          or {},
            autoUnfav  = (cfg[autoUnfavKey] == true),
            mutMap     = cfg[mutKey]              or {},
        })
    end

    -- Prioritas Gift 1 -> Gift 2 -> Gift 3
    addGroup("1", "enabled",  targets1, "minKG",  "minAge",  "petType",  "autoUnfav",  "mut")
    addGroup("2", "enabledB", targets2, "minKGB", "minAgeB", "petTypeB", "autoUnfavB", "mutB")
    addGroup("3", "enabledC", targets3, "minKGC", "minAgeC", "petTypeC", "autoUnfavC", "mutC")

    if #groups == 0 then
        _giftBusy = false
        _giftHoldUntil = 0
        _resumeAutoHatchIfNeeded()
        return
    end

    ------------------------------------------------------------
    -- STAGE A: SCAN & BUILD QUEUE
    ------------------------------------------------------------
    local queue = {}
    local queued = 0

    for _, tool in ipairs(bp:GetChildren()) do
        if _isTradeAddableTool(tool) then
            local idAttr = tool:GetAttribute("PET_UUID")
                or tool:GetAttribute("UUID")
                or tool:GetAttribute("PetUUID")

            if idAttr then
                local core, br = helpers.normUUID(idAttr)
                local rec = index[core] or index[br]
                local uuidFmt = br or ("{"..tostring(core or idAttr).."}")

                if rec then
                    local age  = helpers.age_from_record(rec)
                    local w100 = helpers.weight_at_100_for_rec(rec)

                    if age and w100 then
                        local PD = rec.PetData or rec.Data or {}
                        local petTypeRaw =
                            rec.Type or rec.PetType or
                            PD.Type  or PD.PetType  or
                            rec.Name or PD.Name     or
                            "Pet"

                        local petTypeLabel = tostring(petTypeRaw)
                        local petTypeNorm  = petTypeLabel:lower()

                        local chosenGroup
                        for _, grp in ipairs(groups) do
                            if _passesGiftGroup(w100, age, grp.kgRaw, grp.ageRaw)
                                and _passesPetType(petTypeNorm, grp.petTypeMap)
                                and _matchGiftMutation(rec, helpers, grp.mutMap)
                            then
                                chosenGroup = grp
                                break
                            end
                        end

                        if chosenGroup then
                            queued += 1
                            queue[#queue+1] = {
                                tool        = tool,
                                uuidFmt      = uuidFmt,
                                group        = chosenGroup,
                                age          = age,
                                w100         = w100,
                                petTypeLabel = petTypeLabel,
                            }
                        end
                    end
                end
            end
        end
    end

    if queued == 0 then
        _giftBusy = false
        _giftHoldUntil = 0
        _resumeAutoHatchIfNeeded()
        return
    end

    ------------------------------------------------------------
    -- STAGE B: BULK UNFAV (hanya yg group.autoUnfav == true)
    ------------------------------------------------------------
    local didUnfav = 0
    for _, item in ipairs(queue) do
        local grp = item.group
        local t = item.tool
        if grp and grp.autoUnfav and t and t.Parent and isToolFavorited(t) then
            setToolFavorite(t, false)
            didUnfav += 1
            if (didUnfav % 4) == 0 then
                task.wait(0.08)
            end
        end
    end
    if didUnfav > 0 then
        task.wait(0.35)
    end

    ------------------------------------------------------------
    -- STAGE C: per-group (trade OR give)
    ------------------------------------------------------------
    local sent = 0

    local grouped = {}
    local order = { "1", "2", "3" }
    for _, item in ipairs(queue) do
        local gid = item.group and item.group.id
        if gid then
            grouped[gid] = grouped[gid] or {}
            table.insert(grouped[gid], item)
        end
    end

    local function _tradeOnForGroupId(gid)
        if gid == "1" then return (GIFT_CFG and GIFT_CFG.prioTicket  == true) end
        if gid == "2" then return (GIFT_CFG and GIFT_CFG.prioTicketB == true) end
        if gid == "3" then return (GIFT_CFG and GIFT_CFG.prioTicketC == true) end
        return false
    end

    for _, gid in ipairs(order) do
        if sent >= AUTO_GIFT_MAX_SEND_PER_PASS then
            break
        end

        local gqueue = grouped[gid]
        if gqueue and #gqueue > 0 then
            local grp = gqueue[1].group
            local tradeOn = _tradeOnForGroupId(gid)

            if tradeOn then
                -- TRADE (ticket) per group
                local target = _pickLeastBackpackTarget(grp.targets)
                if target then
                    local batch = _takeTradeBatch(gqueue)
                    if batch and #batch > 0 then
                        -- buat trade: tahan busy pendek dulu biar gak double-pass start,
                        -- nanti _runTradeBatch akan set busy panjang setelah request sukses
                        _markGiftBusy(1.0)

                        _ensureAutoHatchStoppedForGift()

                        local ok = _runTradeBatch(target, batch)
                        if ok then
                            sent += TRADE_MAX_ITEMS_PER_SESSION
                        end
                    end
                end
            else
                -- GIVE 1 per 1
                for _, item in ipairs(gqueue) do
                    if sent >= AUTO_GIFT_MAX_SEND_PER_PASS then
                        break
                    end

                    local t = item.tool
                    if t and t.Parent then
                        if not isToolFavorited(t) then
                            local target = _pickLeastBackpackTarget(item.group.targets)
                            if target then
                                _markGiftBusy(1.6)
                                _ensureAutoHatchStoppedForGift()

                                local okGive = _give(item.uuidFmt, target, t, false)
                                if okGive then
                                    sent += 1
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    _markGiftIdleIfDue()
    if not _giftBusy then
        _resumeAutoHatchIfNeeded()
    end
end



