local M = {}
local _loopStarted = false

local function _startLoop()
    if _loopStarted then return end
    _loopStarted = true

    task.spawn(function()
        dbg("AutoGift loop START (gift.lua pakai PetListView)")
        while true do
            local ok, err = pcall(_autoGiftPass)
            if not ok then
                warn("[AutoGift] ERROR dalam _autoGiftPass:", err)
            end
            task.wait(AUTO_GIFT_SCAN_INTERVAL)
        end
    end)
end

-- Auto start loop saat module di-require
_startLoop()

-- Optional API: manual single pass
function M.RunOnePass()
    local ok, err = pcall(_autoGiftPass)
    if not ok then
        warn("[AutoGift] RunOnePass error:", err)
    end
end

-- Flag auto accept (listener-nya dibuat di module lain)
function M.IsAutoAcceptGiftEnabled()
    return GIFT_CFG and GIFT_CFG.autoAcceptGift == true
end

function M.IsAutoAcceptTradeEnabled()
    return GIFT_CFG and GIFT_CFG.autoAcceptTrade == true
end

return M
        end,
        required = false,
    },
    {
        key = "AutoAccept",
        name = "Auto Accept Gift/Trade",
        factory = function()
            -- autoaccept.lua
-- Auto Accept Gift + Trade untuk NodeHub
-- Receiver mode untuk gift/trade ticket 1 arah
-- Anti false-decline + anti coroutine lama decline trade baru

--------------------------------------------------
-- Services & Globals
--------------------------------------------------
local Players           = game:GetService("Players")
local RunService        = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace         = game:GetService("Workspace")

local RS = ReplicatedStorage
local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G

--------------------------------------------------
-- Config
--------------------------------------------------
local DEBUG = false

local CLEAR_WINDOW_SEC   = 3
local CLEAR_INTERVAL_SEC = 0.25

-- Receiver tidak cek item.
-- Timeout ini untuk close UI kalau sender AFK.
local TIMEOUT_ACCEPT  = 60
local TIMEOUT_CONFIRM = 15
local TIMEOUT_END     = 30
local START_DELAY     = 2

local tradeToken = 0

--------------------------------------------------
-- Debug
--------------------------------------------------
local function dbg(...)
    if DEBUG then
        print("[TradeRecvDBG]", ...)
    end
end

local function warnx(...)
    warn("[TradeRecvDBG]", ...)
end

--------------------------------------------------
-- GIFT_CFG
--------------------------------------------------
local function getGiftCfg()
    local cfg = rawget(G, "GIFT_CFG")
        or G.GIFT_CFG
        or rawget(_G, "GIFT_CFG")
        or _G.GIFT_CFG
        or rawget(_G, "giftCfg")
        or _G.giftCfg
        or _G.GIFT_CONFIG
        or GIFT_CFG

    if typeof(cfg) ~= "table" then
        return nil
    end

    return cfg
end

local function isAutoGiftOn()
    local cfg = getGiftCfg()
    return cfg and cfg.autoAcceptGift == true
end

local function isAutoTradeOn()
    local cfg = getGiftCfg()
    return cfg and cfg.autoAcceptTrade == true
end

--------------------------------------------------
-- Safe Require
--------------------------------------------------
local function safeRequire(obj)
    if not obj then return nil end

    local ok, mod = pcall(function()
        return require(obj)
    end)

    if not ok then
        dbg("require fail:", tostring(obj), mod)
        return nil
    end

    return mod
end

--------------------------------------------------
-- Auto Accept Gift
--------------------------------------------------
local okGift, giftErr = pcall(function()
        local GameEvents = RS:WaitForChild("GameEvents", 8)
        local GiftPet    = GameEvents and GameEvents:WaitForChild("GiftPet", 8)
        local AcceptGift = GameEvents and GameEvents:WaitForChild("AcceptPetGift", 8)
        if not (GiftPet and AcceptGift) then
            error("Gift remotes belum siap")
        end

    GiftPet.OnClientEvent:Connect(function(uuid, petName, fromPlayer)
        if not isAutoGiftOn() then
            return
        end

        pcall(function()
            AcceptGift:FireServer(true, uuid)
        end)

        task.spawn(function()
            local playerGui = LP:FindFirstChild("PlayerGui") or LP:WaitForChild("PlayerGui", 5)
            if not playerGui then
                return
            end
            local deadline  = tick() + CLEAR_WINDOW_SEC

            while tick() < deadline do
                local root = playerGui:FindFirstChild("Gift_Notification")
                if root then
                    local frame = root:FindFirstChild("Frame")
                    if frame then
                        local inner = frame:FindFirstChild("Gift_Notification")
                        if inner then
                            inner:Destroy()
                        end
                    end
                end

                task.wait(CLEAR_INTERVAL_SEC)
            end
        end)
    end)
end)

if not okGift then
    warn("[AutoAccept] Gagal init Auto Accept Gift:", giftErr)
end

--------------------------------------------------
-- Trade Remotes / Modules
--------------------------------------------------
local TradeEvents
local SendRequestEv
local RespondRequestEv
local AcceptEv
local ConfirmEv
local DeclineEv
local UpdateState
local ReplicationReciever
local TradeData

local TRADE_SYSTEM_OK = false

do
    local okTrade, err = pcall(function()
        local GE = RS:WaitForChild("GameEvents", 8)
        TradeEvents = GE and GE:WaitForChild("TradeEvents", 8)
        if not TradeEvents then
            error("TradeEvents belum siap")
        end

        SendRequestEv    = TradeEvents:WaitForChild("SendRequest", 5)
        RespondRequestEv = TradeEvents:WaitForChild("RespondRequest", 5)
        AcceptEv         = TradeEvents:WaitForChild("Accept", 5)
        ConfirmEv        = TradeEvents:WaitForChild("Confirm", 5)
        DeclineEv        = TradeEvents:WaitForChild("Decline", 5)
        UpdateState      = TradeEvents:WaitForChild("UpdateTradeState", 5)

        local modules = RS:WaitForChild("Modules", 8)
        ReplicationReciever = safeRequire(modules and modules:WaitForChild("ReplicationReciever", 8))

        local dataFolder = RS:WaitForChild("Data", 8)
        TradeData = safeRequire(dataFolder and dataFolder:WaitForChild("TradeData", 8)) or { ButtonCooldown = 0 }

        if not ReplicationReciever then
            error("ReplicationReciever module tidak ditemukan")
        end
    end)

    if okTrade then
        TRADE_SYSTEM_OK = true
    else
        warnx("Init TradeEvents gagal, auto trade off:", err)
    end
end

--------------------------------------------------
-- Trade State
--------------------------------------------------
local currentTradeId = nil
local replicator     = nil

local function destroyReplicator()
    if replicator then
        pcall(function()
            replicator:Destroy()
        end)
    end
    replicator = nil
end

local function waitUntil(pred, timeout, token)
    local t0 = os.clock()
    local limit = timeout or 10

    while os.clock() - t0 < limit do
        if token and token ~= tradeToken then
            return false, "old-token"
        end

        local ok, why = pred()
        if ok then
            return true, why
        end

        RunService.Heartbeat:Wait()
    end

    return false, "timeout"
end

local function getTradeData()
    if not replicator then
        return nil
    end

    local ok, data = pcall(function()
        return replicator:GetData()
    end)

    if not ok or not data then
        return nil
    end

    return data
end

local function getStateIndices()
    local data = getTradeData()
    if not data then return nil end

    local players = data.players or {}
    local states  = data.states or {}
    local myIdx

    for i, p in ipairs(players) do
        if p == LP then
            myIdx = i
            break
        end
    end

    if not myIdx then
        return nil
    end

    local otherIdx = (myIdx == 1) and 2 or 1
    return states, myIdx, otherIdx
end

local function otherAccepted()
    local states, myIdx, otherIdx = getStateIndices()
    if not states or not myIdx or not otherIdx then
        return false, "no-state"
    end

    local myState    = states[myIdx]
    local otherState = states[otherIdx]

    if otherState == "Accepted" then
        return true, ("other=%s my=%s"):format(tostring(otherState), tostring(myState))
    end

    return false, ("other=%s my=%s"):format(tostring(otherState), tostring(myState))
end

local function bothAccepted()
    local states, myIdx, otherIdx = getStateIndices()
    if not states or not myIdx or not otherIdx then
        return false, "no-state"
    end

    local myState    = states[myIdx]
    local otherState = states[otherIdx]

    if myState == "Accepted" and otherState == "Accepted" then
        return true, "both-accepted"
    end

    return false, ("other=%s my=%s"):format(tostring(otherState), tostring(myState))
end

local function otherConfirmed()
    local states, myIdx, otherIdx = getStateIndices()
    if not states or not myIdx or not otherIdx then
        return false, "no-state"
    end

    local myState    = states[myIdx]
    local otherState = states[otherIdx]

    if otherState == "Confirmed" then
        return true, ("other=%s my=%s"):format(tostring(otherState), tostring(myState))
    end

    return false, ("other=%s my=%s"):format(tostring(otherState), tostring(myState))
end

local function cooldownSatisfied()
    local data = getTradeData()
    if not data then
        return false, "no-data"
    end

    local cd = tonumber(TradeData and TradeData.ButtonCooldown) or 0
    local lastChange = tonumber(data.lastChange) or 0
    local delta = Workspace:GetServerTimeNow() - lastChange

    if delta >= cd then
        return true, ("delta=%.3f cd=%.3f"):format(delta, cd)
    end

    return false, ("delta=%.3f cd=%.3f"):format(delta, cd)
end

local function waitTradeStarted(token, timeout)
    return waitUntil(function()
        if not currentTradeId or not replicator then
            return false, "no-trade"
        end

        local data = getTradeData()
        if data and data.players and #data.players >= 2 then
            return true, "trade-started"
        end

        return false, "wait-data"
    end, timeout or 20, token)
end

local function waitTradeEnded(token, timeout)
    return waitUntil(function()
        if not currentTradeId then
            return true, "closed-id-nil"
        end

        if not replicator then
            return true, "closed-no-rep"
        end

        local data = getTradeData()
        if not data then
            return true, "closed-no-data"
        end

        if not data.players or #data.players == 0 then
            return true, "closed-players0"
        end

        return false, "still-open"
    end, timeout or TIMEOUT_END, token)
end

local function safeDecline(reason, token)
    if token and token ~= tradeToken then
        warnx("SKIP DECLINE old token:", reason)
        return false
    end

    warnx("DECLINE:", tostring(reason or "unknown"))

    pcall(function()
        DeclineEv:FireServer()
    end)

    task.wait(0.3)
    return true
end

--------------------------------------------------
-- Main Auto Trade Receiver Flow
--------------------------------------------------
local function runAutoAcceptOnce(myToken)
    if myToken ~= tradeToken then
        dbg("Abort old run start token=", myToken, "current=", tradeToken)
        return false
    end

    if not isAutoTradeOn() then
        dbg("autoAcceptTrade false, batal.")
        return false
    end

    dbg("runAutoAcceptOnce: menunggu trade aktif token=", myToken)

    local okStart, whyStart = waitTradeStarted(myToken, 20)
    if not okStart then
        dbg("trade tidak aktif / old:", whyStart)
        return false
    end

    if myToken ~= tradeToken then return false end

    --------------------------------------------------
    -- Gift mode: jangan cek item
    --------------------------------------------------
    dbg("Gift mode: skip cek item, receiver tunggu sender Accept")

    --------------------------------------------------
    -- 1) Tunggu sender Accept
    --------------------------------------------------
    local okOtherAcc, whyOtherAcc = waitUntil(otherAccepted, TIMEOUT_ACCEPT, myToken)
    if myToken ~= tradeToken then return false end

    if not okOtherAcc then
        safeDecline("Lawan tidak Accept dalam " .. tostring(TIMEOUT_ACCEPT) .. " detik: " .. tostring(whyOtherAcc), myToken)
        return false
    end

    dbg("Lawan sudah Accepted:", whyOtherAcc)

    --------------------------------------------------
    -- 2) Receiver Accept
    --------------------------------------------------
    local okCdAccept = waitUntil(cooldownSatisfied, 15, myToken)
    if myToken ~= tradeToken then return false end

    if not okCdAccept then
        safeDecline("Cooldown Accept timeout", myToken)
        return false
    end

    task.wait(0.5)
    if myToken ~= tradeToken then return false end

    dbg("AcceptEv:FireServer()")
    pcall(function()
        AcceptEv:FireServer()
    end)

    --------------------------------------------------
    -- 3) Pastikan both accepted
    --------------------------------------------------
    local okBoth, whyBoth = waitUntil(bothAccepted, 20, myToken)
    if myToken ~= tradeToken then return false end

    if not okBoth then
        safeDecline("BothAccepted timeout: " .. tostring(whyBoth), myToken)
        return false
    end

    dbg("Kedua pemain Accepted")

    --------------------------------------------------
    -- 4) Tunggu sender Confirm
    --------------------------------------------------
    local okOtherConf, whyOtherConf = waitUntil(otherConfirmed, TIMEOUT_CONFIRM, myToken)
    if myToken ~= tradeToken then return false end

    if not okOtherConf then
        safeDecline("Lawan tidak Confirm dalam " .. tostring(TIMEOUT_CONFIRM) .. " detik: " .. tostring(whyOtherConf), myToken)
        return false
    end

    dbg("Lawan sudah Confirm:", whyOtherConf)

    --------------------------------------------------
    -- 5) Receiver Confirm
    --------------------------------------------------
    local okCdConfirm = waitUntil(cooldownSatisfied, 15, myToken)
    if myToken ~= tradeToken then return false end

    if not okCdConfirm then
        safeDecline("Cooldown Confirm timeout", myToken)
        return false
    end

    task.wait(0.5)
    if myToken ~= tradeToken then return false end

    dbg("ConfirmEv:FireServer()")
    pcall(function()
        ConfirmEv:FireServer()
    end)

    --------------------------------------------------
    -- 6) Tunggu trade close
    --------------------------------------------------
    local okEnd, whyEnd = waitTradeEnded(myToken, TIMEOUT_END)
    if myToken ~= tradeToken then return false end

    if not okEnd then
        safeDecline("Trade belum selesai / timeout: " .. tostring(whyEnd), myToken)
        return false
    end

    dbg("Trade selesai token=", myToken)
    return true
end

--------------------------------------------------
-- Bind Events
--------------------------------------------------
if TRADE_SYSTEM_OK then
    SendRequestEv.OnClientEvent:Connect(function(tradeId, fromPlayer, expireAt)
        local remaining = (expireAt or 0) - Workspace:GetServerTimeNow()

        dbg(("Incoming trade request dari %s | tradeId=%s | sisa=%.2fs")
            :format(fromPlayer and fromPlayer.Name or "?", tostring(tradeId), remaining))

        if not isAutoTradeOn() then
            dbg("autoAcceptTrade=false, tidak RespondRequest")
            return
        end

        if not tradeId then
            warnx("tradeId nil, tidak bisa RespondRequest")
            return
        end

        task.wait(3)

        pcall(function()
            RespondRequestEv:FireServer(tradeId, true)
        end)

        dbg("RespondRequestEv:FireServer(tradeId, true)")
    end)

    UpdateState.OnClientEvent:Connect(function(tradeId)
        tradeToken += 1
        local myToken = tradeToken

        dbg("UpdateTradeState:", tradeId, "token=", myToken)

        destroyReplicator()
        currentTradeId = tradeId

        if tradeId then
            local ok, rep = pcall(function()
                return ReplicationReciever.new(tradeId)
            end)

            if ok and rep then
                replicator = rep
                dbg("Replicator ready token=", myToken)

                if isAutoTradeOn() then
                    task.defer(function()
                        task.wait(START_DELAY)

                        if myToken ~= tradeToken then
                            dbg("Skip old deferred token=", myToken)
                            return
                        end

                        runAutoAcceptOnce(myToken)
                    end)
                end
            else
                warnx("ReplicationReciever.new gagal:", rep)
            end
        else
            dbg("TradeState nil / trade selesai token=", myToken)
        end
    end)

    dbg("Auto-accept trade siap. Toggle GIFT_CFG.autoAcceptTrade")
end

--------------------------------------------------
-- Module API
--------------------------------------------------
local M = {}

function M.IsAutoGiftOn()
    return isAutoGiftOn()
end

function M.IsAutoTradeOn()
    return isAutoTradeOn()
end

return M
        end,
        required = false,
    },
    {
        key = "baku_combo",
        name = "baku_combo",
        factory = function()
            -- baku_combo.lua — 500 Age List Mode "baku" fruit/Nightmare stock (packed BK)
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")

local LP = Players.LocalPlayer
local G = (getgenv and getgenv()) or _G
local M = {}
M.__MODULE_VERSION = 17

local BK = {
    phase = "idle",
    phaseAt = 0,
    shovelPassDone = false,
    busy = false,
    lastCountAt = 0,
    lastSlotsAt = 0,
    fruitTotal = 0,
    nightmareCount = 0,
    otherMutCount = 0,
    maxSlots = 0,
    noShovel = false,
    levelingHold = false,
    durGrow = 0,
    durBait = 0,
    durSpread = 0,
    durShovel = 0,
    durCombo = 0,
    comboAt = nil,
    comboFrozen = false,
    _slotByPlant = {},
    _slotDirty = true,
    _slotWatch = nil,
    _slotCons = {},
}

local DWELL = 2
local COUNT_SEC = 2.5
local SLOT_SEC = 20

local function env()
    return (getgenv and getgenv()) or _G
end

function BK.normMode(mode)
    mode = tostring(mode or "normal"):lower()
    if mode == "baku" then
        return "baku"
    end
    return "normal"
end

function BK.getMode()
    local E = env()
    local st = rawget(_G, "STATE") or rawget(E, "STATE")
    if type(st) == "table" then
        return BK.normMode(st.ageListMode)
    end
    return BK.normMode(rawget(E, "AGE_LIST_MODE"))
end

function BK.getMin()
    local st = rawget(_G, "STATE")
    local n = tonumber(st and st.bakuMinNightmare) or 1000
    if n < 1 then
        n = 1
    end
    return n
end

function BK.getLeave()
    local st = rawget(_G, "STATE")
    local n = tonumber(st and st.bakuLeaveNightmare)
    if n == nil then
        n = 100
    end
    n = math.floor(n)
    if n < 0 then
        n = 0
    end
    local minN = BK.getMin()
    if n >= minN then
        n = minN - 1
    end
    if n < 0 then
        n = 0
    end
    return n
end

function BK.shovelOn()
    local st = rawget(_G, "STATE")
    if st and st.bakuShovelOtherMut == false then
        return false
    end
    return true
end

function BK.uuidArr(map)
    local out, seen = {}, {}
    if type(map) ~= "table" then
        return out
    end
    for k, v in pairs(map) do
        if v == true or v == 1 then
            local s = tostring(k)
            local core = s:match("{?([0-9a-fA-F%-]+)}?") or s
            if core ~= "" and not seen[core] then
                seen[core] = true
                out[#out + 1] = s
            end
        end
    end
    return out
end

function BK.team(key)
    local st = rawget(_G, "STATE")
    if type(st) ~= "table" then
        return {}
    end
    return BK.uuidArr(st[key])
end

function BK.fmtSec(sec)
    sec = math.max(0, math.floor((tonumber(sec) or 0) + 0.5))
    local h = math.floor(sec / 3600)
    local m = math.floor((sec % 3600) / 60)
    local s = sec % 60
    if h > 0 then
        return string.format("%d:%02d:%02d", h, m, s)
    end
    return string.format("%d:%02d", m, s)
end

function BK.liveDur(name)
    local base = 0
    if name == "grow" then
        base = tonumber(BK.durGrow) or 0
    elseif name == "bait" then
        base = tonumber(BK.durBait) or 0
    elseif name == "spread" then
        base = tonumber(BK.durSpread) or 0
    elseif name == "shovel" then
        base = tonumber(BK.durShovel) or 0
    end
    if BK.phase == name and (tonumber(BK.phaseAt) or 0) > 0 then
        base += os.clock() - BK.phaseAt
    end
    return base
end

function BK.comboDur()
    if BK.comboFrozen == true then
        return tonumber(BK.durCombo) or 0
    end
    if BK.comboAt then
        return os.clock() - BK.comboAt
    end
    return 0
end

function BK.resetComboTimes()
    BK.durGrow = 0
    BK.durBait = 0
    BK.durSpread = 0
    BK.durShovel = 0
    BK.durCombo = 0
    BK.comboAt = os.clock()
    BK.comboFrozen = false
end

function BK.stampPhaseDur(prev, elapsed)
    elapsed = tonumber(elapsed) or 0
    if elapsed < 0 then
        elapsed = 0
    end
    if prev == "grow" then
        BK.durGrow = (tonumber(BK.durGrow) or 0) + elapsed
    elseif prev == "bait" then
        BK.durBait = (tonumber(BK.durBait) or 0) + elapsed
    elseif prev == "spread" then
        BK.durSpread = (tonumber(BK.durSpread) or 0) + elapsed
    elseif prev == "shovel" then
        BK.durShovel = (tonumber(BK.durShovel) or 0) + elapsed
    end
end

function BK.publish()
    local st = {
        phase = BK.phase,
        fruitTotal = BK.fruitTotal,
        nightmareCount = BK.nightmareCount,
        otherMutCount = BK.otherMutCount,
        minNightmare = BK.getMin(),
        leaveNightmare = BK.getLeave(),
        maxSlots = BK.maxSlots,
        capacityOk = BK.maxSlots >= BK.getMin(),
        noShovel = BK.noShovel == true,
        hasAgeTarget = BK.hasAgeTarget == true,
        timeGrow = BK.liveDur("grow"),
        timeBait = BK.liveDur("bait"),
        timeSpread = BK.liveDur("spread"),
        timeCombo = BK.comboDur(),
        comboDone = BK.comboFrozen == true,
        timeGrowTxt = BK.fmtSec(BK.liveDur("grow")),
        timeBaitTxt = BK.fmtSec(BK.liveDur("bait")),
        timeSpreadTxt = BK.fmtSec(BK.liveDur("spread")),
        timeComboTxt = BK.fmtSec(BK.comboDur()),
    }
    G.BAKU_STATUS = st
    _G.BAKU_STATUS = st
    return st
end

function BK.snapLastCombo()
    local snap = {
        phase = tostring(BK.phase or "leveling"),
        comboDone = BK.comboFrozen == true,
        timeGrow = BK.liveDur("grow"),
        timeBait = BK.liveDur("bait"),
        timeSpread = BK.liveDur("spread"),
        timeShovel = BK.liveDur("shovel"),
        timeCombo = BK.comboDur(),
        timeGrowTxt = BK.fmtSec(BK.liveDur("grow")),
        timeBaitTxt = BK.fmtSec(BK.liveDur("bait")),
        timeSpreadTxt = BK.fmtSec(BK.liveDur("spread")),
        timeShovelTxt = BK.fmtSec(BK.liveDur("shovel")),
        timeComboTxt = BK.fmtSec(BK.comboDur()),
        fruitTotal = BK.fruitTotal,
        nightmareCount = BK.nightmareCount,
        minNightmare = BK.getMin(),
        leaveNightmare = BK.getLeave(),
        tsUnix = os.time(),
    }
    G.BAKU_LAST_COMBO = snap
    _G.BAKU_LAST_COMBO = snap
    return snap
end

function BK.isOwnFarm(farm)
    if not farm then
        return false
    end
    local ok, owner = pcall(function()
        return farm.Important.Data.Owner.Value
    end)
    return ok and owner == LP.Name
end

function BK.getFarm()
    if BK._farm and BK._farm.Parent and BK.isOwnFarm(BK._farm) then
        return BK._farm
    end
    BK._farm = nil
    if not BK._getFarmFn then
        pcall(function()
            BK._getFarmFn = require(ReplicatedStorage.Modules.GetFarm)
        end)
    end
    if type(BK._getFarmFn) == "function" then
        local ok, farm = pcall(BK._getFarmFn, LP)
        if ok and farm and BK.isOwnFarm(farm) then
            BK._farm = farm
            return farm
        end
    end
    local farms = workspace:FindFirstChild("Farm")
    if farms then
        for _, farm in ipairs(farms:GetChildren()) do
            if BK.isOwnFarm(farm) then
                BK._farm = farm
                return farm
            end
        end
    end
    return nil
end

function BK.mutSet()
    if BK._mutSet then
        return BK._mutSet
    end
    local set = { Wet = true, Drenched = true, Chilled = true, Frozen = true, Shocked = true }
    pcall(function()
        local MH = require(ReplicatedStorage.Modules.MutationHandler)
        local muts = MH and MH.GetMutations and MH:GetMutations()
        if type(muts) == "table" then
            for k, m in pairs(muts) do
                local name = type(m) == "table" and (m.Name or m.name or k) or k
                if type(name) == "string" and name ~= "" and name ~= "Nightmare" then
                    set[name] = true
                end
            end
        end
    end)
    BK._mutSet = set
    return set
end

function BK.isRipe(f)
    if not f then
        return false
    end
    local tagged = false
    pcall(function()
        tagged = CollectionService:HasTag(f, "Harvestable") == true
    end)
    if not tagged and typeof(f.HasTag) == "function" then
        pcall(function()
            tagged = f:HasTag("Harvestable") == true
        end)
    end
    if tagged then
        return true
    end
    local prompt = f:FindFirstChild("ProximityPrompt")
    if not prompt then
        local okp, p2 = pcall(function()
            return f:FindFirstChildWhichIsA("ProximityPrompt")
        end)
        prompt = okp and p2 or nil
    end
    if prompt and prompt.Enabled == true then
        return true
    end
    local maxAge = tonumber(f:GetAttribute("MaxAge"))
    local grow = f:FindFirstChild("Grow")
    local ageVal = grow and grow:FindFirstChild("Age")
    if maxAge ~= nil and ageVal and (ageVal:IsA("NumberValue") or ageVal:IsA("IntValue")) then
        return (tonumber(ageVal.Value) or 0) >= maxAge
    end
    local done = tonumber(f:GetAttribute("DoneGrowTime"))
    if done and done > 0 then
        local now = os.time()
        pcall(function()
            now = workspace:GetServerTimeNow()
        end)
        return now >= done
    end
    return false
end

function BK.fruitFlags(f)
    local hasNm = f:GetAttribute("Nightmare") == true
    local extra = false
    local set = BK.mutSet()
    local attrs = f:GetAttributes()
    if type(attrs) == "table" then
        for k, v in pairs(attrs) do
            if v == true and set[k] == true then
                extra = true
                break
            end
        end
    end
    return hasNm, extra
end

function BK.clearSlotWatch()
    local cons = BK._slotCons
    if type(cons) == "table" then
        for i = 1, #cons do
            pcall(function()
                cons[i]:Disconnect()
            end)
        end
    end
    BK._slotCons = {}
    BK._slotWatch = nil
end

function BK.watchPlants(plants)
    if BK._slotWatch == plants then
        return
    end
    BK.clearSlotWatch()
    if not plants then
        return
    end
    BK._slotWatch = plants
    local cons = {}
    cons[#cons + 1] = plants.ChildAdded:Connect(function()
        BK._slotDirty = true
    end)
    cons[#cons + 1] = plants.ChildRemoved:Connect(function()
        BK._slotDirty = true
    end)
    BK._slotCons = cons
end

function BK.refreshSlots(force)
    local farm = BK.getFarm()
    local plants = farm and farm:FindFirstChild("Important")
    plants = plants and plants:FindFirstChild("Plants_Physical")
    BK.watchPlants(plants)
    local now = os.clock()
    if not force
        and BK.maxSlots > 0
        and BK._slotDirty ~= true
        and (now - BK.lastSlotsAt) < SLOT_SEC
    then
        return BK.maxSlots
    end
    BK.lastSlotsAt = now
    BK._slotDirty = false
    local n = 0
    local cache = BK._slotByPlant
    if plants then
        for _, plant in ipairs(plants:GetChildren()) do
            if plant:IsA("Model") then
                local spawnN = 0
                local sp = plant:FindFirstChild("Fruit_Spawn")
                if sp then
                    spawnN = #sp:GetChildren()
                end
                local fruitN = 0
                local folder = plant:FindFirstChild("Fruits")
                if folder then
                    fruitN = #folder:GetChildren()
                end
                local slots = math.max(spawnN, fruitN)
                if slots > 0 then
                    cache[plant] = slots
                else
                    slots = tonumber(cache[plant]) or 1
                end
                n += slots
            end
        end
    end
    BK.maxSlots = n
    return n
end

function BK.refreshCounts(force)
    local now = os.clock()
    if not force and (now - BK.lastCountAt) < COUNT_SEC then
        return
    end
    BK.lastCountAt = now
    local farm = BK.getFarm()
    local tot, nm, other = 0, 0, 0
    local plants = farm and farm:FindFirstChild("Important")
    plants = plants and plants:FindFirstChild("Plants_Physical")
    if plants then
        for _, plant in ipairs(plants:GetChildren()) do
            if plant:IsA("Model") then
                local folder = plant:FindFirstChild("Fruits")
                local list = (folder and #folder:GetChildren() > 0) and folder:GetChildren() or { plant }
                for _, f in ipairs(list) do
                    if f:IsA("Model") and f:GetAttribute("Favorited") ~= true then
                        if BK.isRipe(f) then
                            tot += 1
                            local hasNm, extra = BK.fruitFlags(f)
                            if hasNm then
                                nm += 1
                            end
                            if extra then
                                other += 1
                            end
                        end
                    end
                end
            end
        end
    end
    BK.fruitTotal = tot
    BK.nightmareCount = nm
    BK.otherMutCount = other
end

local function isComboPhase(p)
    return p == "grow" or p == "bait" or p == "spread" or p == "shovel"
end

function BK.setPhase(p)
    if BK.phase == p then
        return
    end
    local prev = BK.phase
    local elapsed = os.clock() - (tonumber(BK.phaseAt) or os.clock())
    BK.stampPhaseDur(prev, elapsed)

    -- Combo baru: dari leveling / idle / XP / Mutation, atau sisa combo lama yang sudah (done).
    -- Jangan reset di waiting/blocked/shovel di tengah grow→spread.
    local enteringCombo = isComboPhase(p)
    local midGap = prev == "waiting" or prev == "blocked" or prev == "shovel"
    if enteringCombo then
        local fromOutside = (not isComboPhase(prev)) and (not midGap)
        if fromOutside or BK.comboFrozen == true or (BK.comboAt == nil and not midGap) then
            BK.resetComboTimes()
        end
    end

    if p == "leveling" and BK.comboFrozen ~= true and BK.comboAt ~= nil then
        BK.durCombo = os.clock() - BK.comboAt
        BK.comboFrozen = true
        BK.comboAt = nil
        BK._comboJustDone = true
        BK.snapLastCombo()
    elseif p == "idle" or p == "xp" or p == "boost" or p == "noos" then
        if BK.comboFrozen ~= true and BK.comboAt ~= nil then
            BK.durCombo = os.clock() - BK.comboAt
        end
        BK.comboAt = nil
        if p == "idle" then
            BK.comboFrozen = false
            BK.durGrow = 0
            BK.durBait = 0
            BK.durSpread = 0
            BK.durShovel = 0
            BK.durCombo = 0
        end
    end

    BK.phase = p
    BK.phaseAt = os.clock()
    if p ~= "shovel" and p ~= "spread" then
        BK.shovelPassDone = false
    end
end

function BK.dwellOk()
    return (os.clock() - (BK.phaseAt or 0)) >= DWELL
end

function BK.core(u)
    return tostring(u or ""):match("{?([0-9a-fA-F%-]+)}?") or tostring(u or "")
end

function BK.unique(arr)
    local out, seen = {}, {}
    if type(arr) ~= "table" then
        return out
    end
    for i = 1, #arr do
        local u = arr[i]
        local c = BK.core(u)
        if c ~= "" and not seen[c] then
            seen[c] = true
            out[#out + 1] = u
        end
    end
    return out
end

function BK.append(dst, src)
    if type(src) ~= "table" then
        return
    end
    for i = 1, #src do
        dst[#dst + 1] = src[i]
    end
end

function BK.ageTeam()
    local st = rawget(_G, "STATE")
    local mode = "normal"
    if type(st) == "table" then
        mode = (tostring(st.ageListMode or "normal"):lower() == "baku") and "baku" or "normal"
        if type(st.ageTeamSelected) == "table" then
            local a = BK.uuidArr(st.ageTeamSelected[mode] or st.ageTeamSelected.normal)
            if #a > 0 then
                return a
            end
        end
    end
    local sel = rawget(_G, "selected")
    if type(sel) == "table" then
        return BK.uuidArr(sel.seratusage)
    end
    return {}
end

function BK.wantSig(arr)
    local keys = {}
    for i = 1, #(arr or {}) do
        keys[i] = BK.core(arr[i])
    end
    table.sort(keys)
    return table.concat(keys, ",")
end

function BK.loop()
    return rawget(_G, "AutoKGLoop") or rawget(G, "AutoKGLoop")
end

function BK.resetSync()
    BK._wantSig = nil
    BK._equipTryAt = {}
    BK.busy = false
    BK.durGrow = 0
    BK.durBait = 0
    BK.durSpread = 0
    BK.durShovel = 0
    BK.durCombo = 0
    BK.comboAt = nil
    BK.comboFrozen = false
    BK.phase = "idle"
    BK.phaseAt = 0
end

local readEquipped
function BK.equippedCores()
    if readEquipped == nil then
        local ok, DS = pcall(function()
            return require(game:GetService("ReplicatedStorage").Modules.DataService)
        end)
        if ok and type(DS) == "table" and type(DS.GetData) == "function" then
            readEquipped = function()
                local profile = DS:GetData()
                local pets = type(profile) == "table" and profile.PetsData or nil
                return type(pets) == "table" and pets.EquippedPets or nil
            end
        else
            readEquipped = false
        end
    end

    local set = {}
    local eq = nil
    if readEquipped then
        local ok, data = pcall(readEquipped)
        if ok then
            eq = data
        end
    end
    if type(eq) == "table" then
        for k, v in pairs(eq) do
            local id = nil
            if type(v) == "string" then
                id = v
            elseif type(v) == "table" then
                id = v.UUID or v.uuid or v.PetUUID or k
            elseif type(k) == "string" and v == true then
                id = k
            end
            local c = BK.core(id)
            if c ~= "" then
                set[c] = true
            end
        end
        return set
    end

    local folder = workspace:FindFirstChild("PetsPhysical")
    if folder then
        for _, p in ipairs(folder:GetChildren()) do
            if not p:IsA("Weld") and p.Name ~= "PetMover" then
                local c = BK.core(p:GetAttribute("UUID") or p:GetAttribute("uuid"))
                if c ~= "" then
                    set[c] = true
                end
            end
        end
    end
    return set
end

function BK.missingList(want)
    local out = {}
    if type(want) ~= "table" or #want == 0 then
        return out
    end
    local eq = BK.equippedCores()
    local tried = BK._equipTryAt or {}
    local now = os.clock()
    for i = 1, #want do
        local c = BK.core(want[i])
        if c ~= "" and eq[c] == true then
            tried[c] = nil
        elseif c ~= "" and (now - (tonumber(tried[c]) or 0)) >= 1 then
            out[#out + 1] = want[i]
        end
    end
    BK._equipTryAt = tried
    return out
end

function BK.wantMissing(want)
    return #BK.missingList(want) > 0
end

function BK.equipWanted(arr, why)
    local loop = BK.loop()
    if type(loop) == "table" and type(loop.EquipUUIDs) == "function" then
        pcall(loop.EquipUUIDs, loop, arr, why or "baku")
        return
    end
    if type(loop) == "table" and type(loop.equipMany) == "function" then
        pcall(loop.equipMany, arr)
    end
end

function BK.unequipWanted(arr, why)
    if type(arr) ~= "table" or #arr == 0 then
        return
    end
    local loop = BK.loop()
    if type(loop) == "table" and type(loop.UnequipUUIDs) == "function" then
        pcall(loop.UnequipUUIDs, loop, arr, why or "baku")
    end
end

function BK.phaseWant(phase, grow, bait, spread, age)
    if phase == "leveling" then
        return BK.unique(age)
    end
    if phase == "bait" then
        return BK.unique(bait)
    end
    if phase == "spread" then
        return BK.unique(spread)
    end
    if phase == "shovel" then
        return BK.unique(spread)
    end
    if phase == "wait-target" then
        return {}
    end
    if phase == "grow" or phase == "blocked" or phase == "waiting" then
        return BK.unique(grow)
    end
    return {}
end

function BK.poolAll(grow, bait, spread, age)
    local w = {}
    BK.append(w, grow)
    BK.append(w, bait)
    BK.append(w, spread)
    BK.append(w, age)
    return BK.unique(w)
end

function BK.notIn(pool, keep)
    local keepSet = {}
    for i = 1, #(keep or {}) do
        keepSet[BK.core(keep[i])] = true
    end
    local drop = {}
    for i = 1, #(pool or {}) do
        local u = pool[i]
        if keepSet[BK.core(u)] ~= true then
            drop[#drop + 1] = u
        end
    end
    return drop
end

function BK.findOtherMutFruit()
    local farm = BK.getFarm()
    local plants = farm and farm:FindFirstChild("Important")
    plants = plants and plants:FindFirstChild("Plants_Physical")
    if not plants then
        return nil
    end
    for _, plant in ipairs(plants:GetChildren()) do
        if plant:GetAttribute("Favorited") ~= true then
            local folder = plant:FindFirstChild("Fruits")
            if folder then
                for _, f in ipairs(folder:GetChildren()) do
                    if f:IsA("Model") and f:GetAttribute("Favorited") ~= true and BK.isRipe(f) then
                        local _, extra = BK.fruitFlags(f)
                        if extra then
                            return f
                        end
                    end
                end
            end
        end
    end
    return nil
end

function BK.shovelOne()
    local ASF = rawget(_G, "AutoShovelFruit") or rawget(G, "AutoShovelFruit")
    local fruit = BK.findOtherMutFruit()
    if not fruit then
        BK.shovelPassDone = true
        BK.noShovel = false
        return "none"
    end
    if type(ASF) ~= "table" or type(ASF.ShovelFruit) ~= "function" then
        BK.noShovel = true
        return "no api"
    end
    local ok, msg = pcall(function()
        return ASF.ShovelFruit(fruit)
    end)
    if not ok then
        return "err"
    end
    if msg == "no shovel" or msg == "equip failed" then
        BK.noShovel = true
        return msg
    end
    BK.noShovel = false
    return msg or "ok"
end

function BK.Tick()
    if BK.getMode() ~= "baku" then
        BK.setPhase("idle")
        BK.publish()
        return { holdLeveling = false }
    end

    BK.refreshSlots(false)
    BK.refreshCounts(false)

    local minN = BK.getMin()
    local leaveN = BK.getLeave()
    local capOk = BK.maxSlots >= minN
    local nm = BK.nightmareCount
    local other = BK.otherMutCount
    local grow = BK.team("bakuGrowTeam")
    local bait = BK.team("bakuBaitTeam")
    local spread = BK.team("bakuSpreadTeam")
    local shovelOn = BK.shovelOn()

    local fruits = BK.fruitTotal
    local gbxpOwner = nil
    do
        local loop = BK.loop()
        if type(loop) == "table" and type(loop.PeekGbxpOwner) == "function" then
            local okO, vO = pcall(loop.PeekGbxpOwner)
            if okO then
                gbxpOwner = vO
            end
        end
    end
    BK.hasAgeTarget = (gbxpOwner == "AGE")

    if gbxpOwner ~= "AGE" then
        local skipPhase = "idle"
        if gbxpOwner == "XP" then
            skipPhase = "xp"
        elseif gbxpOwner == "BOOST" then
            skipPhase = "boost"
        elseif gbxpOwner == "NOOS" then
            skipPhase = "noos"
        end
        if BK.phase ~= skipPhase then
            local dropCombo = BK.poolAll(grow, bait, spread, {})
            if #dropCombo > 0 then
                BK.unequipWanted(dropCombo, "baku skip " .. tostring(skipPhase))
            end
        end
        BK.levelingHold = false
        BK.setPhase(skipPhase)
        BK.publish()
        return { holdLeveling = false }
    end

    -- Min = mulai leveling. Leave = tetap leveling sampai ripe NM turun ke angka ini.
    if nm >= minN then
        BK.levelingHold = true
    elseif nm <= leaveN then
        BK.levelingHold = false
    end

    local want = "waiting"
    if BK.levelingHold and nm > leaveN then
        want = "leveling"
    elseif not capOk then
        want = "blocked"
    elseif fruits < minN then
        if #grow > 0 then
            want = "grow"
        else
            want = "waiting"
        end
    elseif nm <= 0 then
        if #bait > 0 then
            want = "bait"
        elseif #grow > 0 then
            want = "grow"
        else
            want = "waiting"
        end
    elseif #spread > 0 then
        want = "spread"
    elseif shovelOn and other > 0 then
        want = "shovel"
    else
        want = "waiting"
    end

    if BK.phase ~= want and not BK.dwellOk() and BK.phase ~= "idle" then
        want = BK.phase
    end
    BK._comboJustDone = false
    BK.setPhase(want)

    local age = BK.ageTeam()
    local wantEquip = BK.phaseWant(want, grow, bait, spread, age)
    local levelingNow = want == "leveling"
    local comboNow = want == "grow" or want == "bait" or want == "spread"
        or want == "shovel" or want == "blocked"
    -- Combo tahan loop. Leveling tidak: GBXP + 500 Age dipasang loop, pet combo dilepas di sini.
    local holdLeveling = comboNow and #wantEquip > 0
    local dropEquip = {}
    if levelingNow or holdLeveling then
        dropEquip = BK.notIn(BK.poolAll(grow, bait, spread, age), wantEquip)
    end

    if not BK.busy then
        BK.busy = true
        local phaseNow = want
        local sig = phaseNow .. "|" .. BK.wantSig(wantEquip)
        task.spawn(function()
            local ok, err = pcall(function()
                local doShovel = shovelOn and other > 0
                    and (phaseNow == "shovel" or phaseNow == "spread")
                if doShovel then
                    for _ = 1, 8 do
                        local msg = BK.shovelOne()
                        if msg == "none" or msg == "no shovel" or msg == "equip failed" or msg == "no api" then
                            break
                        end
                    end
                    BK.lastCountAt = 0
                    BK.refreshCounts(true)
                end
                local missing = BK.missingList(wantEquip)
                if sig ~= BK._wantSig or #missing > 0 then
                    BK._wantSig = sig
                    if #dropEquip > 0 then
                        BK.unequipWanted(dropEquip, "baku drop " .. tostring(phaseNow))
                    end
                    if phaseNow ~= "leveling" and #missing > 0 then
                        local nowTry = os.clock()
                        BK._equipTryAt = BK._equipTryAt or {}
                        for i = 1, #missing do
                            BK._equipTryAt[BK.core(missing[i])] = nowTry
                        end
                        BK.equipWanted(missing, "baku " .. tostring(phaseNow))
                    end
                end
            end)
            if not ok then
                warn("[BakuCombo]", err)
            end
            BK.busy = false
        end)
    end

    local st = BK.publish()
    return {
        holdLeveling = holdLeveling,
        protect = wantEquip,
        comboJustDone = BK._comboJustDone == true,
        comboSnap = (BK._comboJustDone == true) and (G.BAKU_LAST_COMBO or st) or nil,
    }
end

function M.Tick()
    return BK.Tick()
end

function M.GetStatus()
    return G.BAKU_STATUS or BK.publish()
end

function M.IsBakuMode()
    return BK.getMode() == "baku"
end

function M.ResetSync()
    BK.resetSync()
end

G.BakuCombo = M
_G.BakuCombo = M
return M

