        key = "autokg_loop",
        name = "autokg_loop",
        factory = function()
            -- autokg_loop.lua
-- Loop utama AutoKG / GBXP (Stage A/B/C/D + NOOS/XP/BOOST/AGE support)
-- Dibungkus module dengan Start/Stop, diexpose ke _G.AutoKGLoop
-- === SINGLETON GUARD (WAJIB) ===
-- Kalau loop masih running, jangan dobel-thread.
-- Kalau sudah stop, izinkan re-exec supaya helper Global/Focus/CAD ter-update.
if rawget(_G, "AutoKGLoop") and type(_G.AutoKGLoop) == "table" then
    local old = _G.AutoKGLoop
    local stillRunning = false
    if type(old.IsRunning) == "function" then
        local ok, v = pcall(old.IsRunning)
        stillRunning = ok and v == true
    elseif old.running == true then
        stillRunning = true
    end
    if stillRunning
        and type(old.Start) == "function"
        and type(old.Stop) == "function"
        and type(old.IsRunning) == "function"
    then
        warn("[AutoKG] Gautokg_loop masih running — Stop dulu baru re-exec")
        return old
    end
    _G.AutoKGLoop = nil
end

