local function _getStageMode()
    local m = rawget(G, "GBXP_STAGE_MODE")
        or (G.STATE and (G.STATE.stage_mode or G.STATE.GBXP_STAGE_MODE))
        or GBXP_STAGE_MODE
        or "AUTO"
    m = tostring(m or "AUTO"):gsub("%s+", ""):upper()
    if m == "" or m == "NIL" then m = "AUTO" end
    return m
end

-- Mode B / BC / CD / ... tidak punya Stage A (mutasi).
-- AUTO dan A/AD/CAD/CDA/ACBD/DA punya Stage A.
local function _stageModeHasA(mode)
    mode = tostring(mode or _getStageMode() or ""):gsub("%s+", ""):upper()
    if mode == "" or mode == "AUTO" then
        return true
    end
    return string.find(mode, "A", 1, true) ~= nil
end

local function _getPriorityMode()
    local v = tostring(
        rawget(G, "GBXP_PRIORITY_MODE")
        or (G.STATE and (G.STATE.GBXP_PRIORITY_MODE or G.STATE.gbxp_priority_mode))
        or GBXP_PRIORITY_MODE
        or "GLOBAL"
    ):gsub("%s+", ""):upper()
    if v ~= "FOCUS" then v = "GLOBAL" end
    GBXP_PRIORITY_MODE = v
    G.GBXP_PRIORITY_MODE = v
    if G.STATE then
        G.STATE.GBXP_PRIORITY_MODE = v
        G.STATE.gbxp_priority_mode = v
    end
    return v
end

