local GetPetCooldownRF  = GetPetCooldownRF or waitChild(GameEventsFolder, "GetPetCooldown", 2)
local mutationModule    = safeRequire(waitChild(PetRegistryInst, "PetMutationRegistry", 2))
local PetsServiceModule = PetsServiceModule or safeRequire(waitChild(PetServices, "PetsService", 2))
local PetsServiceRE     = waitChild(GameEventsFolder, "PetsService", 2)

local function resolveGameModules()
    if not Modules then
        Modules = waitChild(ReplicatedStorage, "Modules", 2)
    end
    if not PetServices then
        PetServices = waitChild(Modules, "PetServices", 2)
    end
    if not GameEventsFolder then
        GameEventsFolder = waitChild(ReplicatedStorage, "GameEvents", 2)
        GameEvents = GameEventsFolder
    end
    if not DataFolder then
        DataFolder = waitChild(ReplicatedStorage, "Data", 2)
    end
    if not PetRegistryInst then
        PetRegistryInst = waitChild(DataFolder, "PetRegistry", 2)
    end
    if not ActivePetsService then
        ActivePetsService = safeRequire(waitChild(PetServices, "ActivePetsService", 2))
    end
    if not PetUtilities then
        PetUtilities = safeRequire(waitChild(PetServices, "PetUtilities", 2))
    end
    if not PetRegistry then
        PetRegistry = safeRequire(PetRegistryInst)
    end
    if not GetPetCooldownRF then
        GetPetCooldownRF = waitChild(GameEventsFolder, "GetPetCooldown", 2)
    end
    if not mutationModule then
        mutationModule = safeRequire(waitChild(PetRegistryInst, "PetMutationRegistry", 2))
    end
    if not PetsServiceModule then
        PetsServiceModule = safeRequire(waitChild(PetServices, "PetsService", 2))
    end
    if not PetsServiceRE then
        PetsServiceRE = waitChild(GameEventsFolder, "PetsService", 2)
    end
    return ActivePetsService
end


local function _bakuWebhookPack(src)
    src = (type(src) == "table") and src or rawget(G, "BAKU_LAST_COMBO") or rawget(_G, "BAKU_LAST_COMBO")
    if type(src) ~= "table" then
        src = rawget(G, "BAKU_STATUS") or rawget(_G, "BAKU_STATUS")
    end
    if type(src) ~= "table" then
        return nil
    end
    local grow = tonumber(src.timeGrow) or 0
    local bait = tonumber(src.timeBait) or 0
    local spread = tonumber(src.timeSpread) or 0
    local combo = tonumber(src.timeCombo) or 0
    if grow <= 0 and bait <= 0 and spread <= 0 and combo <= 0 then
        return nil
    end
    return {
        timeGrow = grow,
        timeBait = bait,
        timeSpread = spread,
        timeShovel = tonumber(src.timeShovel) or 0,
        timeCombo = combo,
        timeGrowTxt = tostring(src.timeGrowTxt or ""),
        timeBaitTxt = tostring(src.timeBaitTxt or ""),
        timeSpreadTxt = tostring(src.timeSpreadTxt or ""),
        timeShovelTxt = tostring(src.timeShovelTxt or ""),
        timeComboTxt = tostring(src.timeComboTxt or ""),
        comboDone = src.comboDone == true,
        fruitTotal = tonumber(src.fruitTotal) or 0,
        nightmareCount = tonumber(src.nightmareCount) or 0,
        minNightmare = tonumber(src.minNightmare) or 0,
        leaveNightmare = tonumber(src.leaveNightmare) or 0,
        tsUnix = tonumber(src.tsUnix) or os.time(),
    }
end

local function _sendWebhook(eventName, data)
    local W = rawget(G, "AutoKGWebhook") or rawget(_G, "AutoKGWebhook")
        or rawget(G, "Webhook") or rawget(_G, "Webhook")
    if not W or type(W.Send) ~= "function" then
        return
    end

    task.spawn(function()
        pcall(function()
            W.Send(eventName, data or {})
        end)
    end)
end

local function _shortUUID(u)
    u = tostring(u or "")
    return u:sub(1, 8)
end
