local M = {}

-- flag utama loop
local running       = false
local __prevRunning = false

-- bisa kamu atur dari luar kalau mau
local GBXP_DEBUG    = GBXP_DEBUG or false
local DEBUG_LEVEL   = DEBUG_LEVEL or 2

-- Auto Shard Cleaner: hanya Stage A (tab mutasi) + toggle ON + loop running.
-- Keep-list = mutasi yang dipilih di List Mode aktif (normal / machine / shark).
local _shardCleanerStage = nil

local function _mutCleanEnabled()
    local st = rawget(G, "STATE") or _G.STATE
    return (st and st.autokgMutationEnabled == true)
        or (rawget(G, "AUTOKG_MUTATION_ENABLED") == true)
        or (rawget(_G, "AUTOKG_MUTATION_ENABLED") == true)
        or (rawget(G, "NMLVL_MUTCLEAN_ENABLED") == true)
        or (rawget(_G, "NMLVL_MUTCLEAN_ENABLED") == true)
        or (NMLVL_MUTCLEAN_ENABLED == true)
end

local function _syncShardCleanerRun(activeStage)
    _shardCleanerStage = activeStage
    G.CURRENT_STAGE = activeStage
    _G.CURRENT_STAGE = activeStage

    local w = rawget(G, "WorldShardCleaner") or rawget(_G, "WorldShardCleaner")
    if type(w) ~= "table" then
        return
    end

    local shouldRun = (running == true)
        and _mutCleanEnabled()
        and (tostring(activeStage or "") == "A")

    if type(w.setOnlyUUIDs) == "function" then
        local listMode = nil
        do
            local st = rawget(G, "STATE") or _G.STATE
            if type(st) == "table" then
                listMode = tostring(st.boostListMode or ""):lower()
            end
        end
        if listMode == "shark" then
            pcall(function()
                w:setOnlyUUIDs((type(selected) == "table" and selected.gbxp) or {})
            end)
        else
            pcall(function()
                w:setOnlyUUIDs(nil)
            end)
        end
    end

    if type(w.setRun) == "function" then
        pcall(function() w:setRun(shouldRun) end)
    elseif type(w.setEnabled) == "function" then
        pcall(function() w:setEnabled(shouldRun) end)
    end
end

local function _setShardCleanerRunning(on)
    local w = rawget(G, "WorldShardCleaner") or rawget(_G, "WorldShardCleaner")
    if type(w) ~= "table" then
        return
    end
    if type(w.setRun) == "function" then
        pcall(function() w:setRun(on == true) end)
    elseif type(w.setEnabled) == "function" then
        pcall(function() w:setEnabled(on == true) end)
    end
end

_G.__SYNC_SHARD_CLEANER = function()
    _syncShardCleanerRun(_shardCleanerStage)
end
G.__SYNC_SHARD_CLEANER = _G.__SYNC_SHARD_CLEANER

