local function setToArray(setTbl)
    local arr = {}
    if type(setTbl) ~= "table" then
        return arr
    end
    -- dedupe brace/non-brace biar 1 pet tidak kehitung 2x
    local seen = {}
    for uuid, on in pairs(setTbl) do
        if on then
            local core = tostring(uuid):match("{?([0-9a-fA-F%-]+)}?") or tostring(uuid)
            if core ~= "" and not seen[core] then
                seen[core] = true
                local br = "{" .. core .. "}"
                arr[#arr + 1] = (setTbl[br] and br) or uuid
            end
        end
    end
    return arr
end



