-- Mutation Machine helpers (opsional: butuh MutationMachineApi/Loop di global)
------------------------------------------------------------
local function _clearTbl(t)
    if type(t) ~= "table" then return end
    for k in pairs(t) do t[k] = nil end
end

local function _getBoostListModeFromState()
    local st = rawget(G, "STATE") or _G.STATE
    local m = st and st.boostListMode
    if type(_G.__getBoostListMode) == "function" then
        local ok, v = pcall(_G.__getBoostListMode)
        if ok and v then m = v end
    end
    m = tostring(m or "normal"):lower()
    if m == "machine" or m == "shark" then
        return m
    end
    return "normal"
end

local function _getMutSelectedFromBoostBucket()
    local bucket = _getBoostListModeFromState()
    local st = rawget(G, "STATE") or _G.STATE
    local bms = st and st.boostMutSelected
    if type(bms) == "table" and type(bms[bucket]) == "table" and next(bms[bucket]) ~= nil then
        return bms[bucket]
    end
    return nil
end

local function SyncMutSelectedFromBoostBucket()
    local src = _getMutSelectedFromBoostBucket()
    if type(src) ~= "table" then
        return
    end

    _clearTbl(GBXP_MUT_SELECTED)
    _clearTbl(GBXP_MUT_SELECTED_LC)

    for name, on in pairs(src) do
        if on == true and name ~= nil then
            local s = tostring(name)
            GBXP_MUT_SELECTED[s] = true
            GBXP_MUT_SELECTED_LC[s:lower()] = true
        end
    end

    G.GBXP_MUT_SELECTED = GBXP_MUT_SELECTED
    G.GBXP_MUT_SELECTED_LC = GBXP_MUT_SELECTED_LC
    _G.GBXP_MUT_SELECTED = GBXP_MUT_SELECTED
    _G.GBXP_MUT_SELECTED_LC = GBXP_MUT_SELECTED_LC
end

local function _isNormalListMode()
    return _getBoostListModeFromState() == "normal"
end

local function _isSharkListMode()
    return _getBoostListModeFromState() == "shark"
end

local function _isMachineListMode()
    return _getBoostListModeFromState() == "machine"
end

local function _isPetInMutationMachine(uuid)
    if not uuid then return false end
    local mApi = rawget(G, "MutationMachineApi") or _G.MutationMachineApi
    if not mApi or type(mApi.IsPetInMachine) ~= "function" then return false end
    local ok, v = pcall(function() return mApi.IsPetInMachine(uuid) end)
    return ok and v == true
end

local function _getBoostHandoffAge()
    if _isSharkListMode() then
        -- Age 100 = syarat DONOR, bukan target bite / Stage A.
        local ageEq = rawget(G, "TAB_AGE_EQUIP_MIN") or TAB_AGE_EQUIP_MIN
        return tonumber((ageEq and ageEq.boost) or 0) or 0
    end
    local mml = rawget(G, "MutationMachineLoop") or _G.MutationMachineLoop
    if mml and type(mml.IsMachineListMode) == "function" and mml.IsMachineListMode() then
        local api = rawget(G, "MutationMachineApi") or _G.MutationMachineApi
        if api and type(api.GetMachineAgeReq) == "function" then
            local ok, v = pcall(function() return api.GetMachineAgeReq() end)
            if ok and tonumber(v) then
                return tonumber(v)
            end
        end
        local st = rawget(G, "STATE") or _G.STATE
        local req = tonumber(st and st.boostMachineAgeReq)
            or tonumber(_G.BOOST_MACHINE_AGE_REQ)
            or 1
        if req < 1 then req = 1 end
        return req
    end
    local ageEq = rawget(G, "TAB_AGE_EQUIP_MIN") or TAB_AGE_EQUIP_MIN
    return tonumber((ageEq and ageEq.boost) or 0) or 0
end

local function _machineWaitBoostActive()
    -- List Mode normal: jangan tahan GBXP / paksa boost team
    if _isNormalListMode() then
        return false
    end
    local mml = rawget(G, "MutationMachineLoop") or _G.MutationMachineLoop
    if not mml or type(mml.WantBoostOn) ~= "function" then return false end
    return mml.WantBoostOn() == true
end

local function _syncMutationMachineOnStart(reason)
    local mml = rawget(G, "MutationMachineLoop") or _G.MutationMachineLoop
    if type(mml) ~= "table" then return end
    if type(mml.SetNmlvlActive) == "function" then
        pcall(function() mml.SetNmlvlActive(true) end)
    end
    if type(mml.IsMachineListMode) == "function" and mml.IsMachineListMode() then
        if type(mml.Start) == "function" then pcall(function() mml.Start(reason) end) end
        if type(mml.SyncMutSelected) == "function" then pcall(function() mml.SyncMutSelected() end) end
    else
        if type(mml.Stop) == "function" then pcall(function() mml.Stop(reason) end) end
        SyncMutSelectedFromBoostBucket()
    end
end

local function _syncMutationMachineOnStop(reason)
    local mml = rawget(G, "MutationMachineLoop") or _G.MutationMachineLoop
    if type(mml) ~= "table" then return end
    if type(mml.SetNmlvlActive) == "function" then
        pcall(function() mml.SetNmlvlActive(false) end)
    end
    if type(mml.Stop) == "function" then
        pcall(function() mml.Stop(reason) end)
    end
end

