G.__getBoostListMode = _getBoostListModeFromState
_G.__getBoostListMode = _getBoostListModeFromState
G.__AUTOKG_SYNC_MUT_SELECTED = SyncMutSelectedFromBoostBucket
_G.__AUTOKG_SYNC_MUT_SELECTED = SyncMutSelectedFromBoostBucket

----------------------------------------------------------------
-- UUID & Number helpers
----------------------------------------------------------------
local function __normUUID(u)
    if not u or u == "" then return nil, nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    return core, "{"..core.."}"
end

local function __toNumberKG(v)
    if v == nil then return nil end
    if type(v) == "number" then return v end
    if type(v) == "string" then
        local s = v:lower():gsub("%s+",""):gsub("kg",""):gsub(",", ".")
        local num = tonumber(s:match("[-+]?%d+%.?%d*"))
        return num
    end
    return nil
end
----------------------------------------------------------------
-- SCALE (auto-normalize: 2 => 0.02)
----------------------------------------------------------------
local SCALE_PER_LVL = PetRegistry.PetConfig.WEIGHT_CONFIG.SCALE_PERCENTAGE_OF_BASE_WEIGHT_PER_LEVEL
local SCALE = SCALE_PER_LVL



local function __number_from_candidates(tbl, keys, srcOut)
    for _,k in ipairs(keys) do
        local v = tbl[k]
        if type(v) == "number" then if srcOut then srcOut[1]=k end; return v end
        if type(v) == "string" then
            local n = tonumber((v:gsub(",", ".")))
            if n then if srcOut then srcOut[1]=k end; return n end
        end
    end
    return nil
end


----------------------------------------------------------------
-- getBaseKg (diisi ulang setelah bag-cache helper siap — lihat bawah)
----------------------------------------------------------------
local getBaseKg


----------------------------------------------------------------
-- Bag fetch + per-tick cache (anti O(n*m) saat 200+ GBXP)
----------------------------------------------------------------
-- Cache berlaku hanya dalam 1 iterasi mainLoop (lihat _tickCacheBegin).
-- Di luar loop / sebelum begin: perilaku tetap fetch fresh.
local _TICK = {
    active = false,
    bag = false,       -- false=belum fetch, nil=empty/missing, table=bag
    index = nil,       -- [core|braced] -> rec
    store = false,     -- full datastore snapshot (optional reuse)
    -- Fix2: nilai pet di-cache per tick (false = sudah dicek tapi nil)
    age = nil,
    base = nil,
    w100 = nil,
    mut = nil,
    equipped = false,  -- Fix3: false=belum, table=set
}

local function _tickCacheBegin()
    _TICK.active = true
    _TICK.bag = false
    _TICK.index = nil
    _TICK.store = false
    _TICK.age = {}
    _TICK.base = {}
    _TICK.w100 = {}
    _TICK.mut = {}
    _TICK.equipped = false
end

local function _tickCacheEnd()
    _TICK.active = false
    _TICK.bag = false
    _TICK.index = nil
    _TICK.store = false
    _TICK.age = nil
    _TICK.base = nil
    _TICK.w100 = nil
    _TICK.mut = nil
    _TICK.equipped = false
end

local function _tickCacheKey(uuid)
    if uuid == nil then return nil end
    local core = tostring(uuid):match("{?([0-9a-fA-F%-]+)}?") or tostring(uuid)
    return core
end

local function _buildBagIndex(bag)
    local idx = {}
    if type(bag) ~= "table" then
        return idx
    end
    for rawUUID, rec in pairs(bag) do
        if type(rec) == "table" then
            local core, br = __normUUID(rawUUID)
            if core then
                idx[core] = rec
                idx[br or ("{" .. core .. "}")] = rec
            end
            -- juga simpan key mentah (kalau format aneh)
            idx[tostring(rawUUID)] = rec
        end
    end
    return idx
end

local function __getStoreSnapshot()
    if _TICK.active and _TICK.store ~= false then
        return _TICK.store
    end
    if not ActivePetsService or not ActivePetsService.GetPlayerDatastorePetData then
        if _TICK.active then _TICK.store = nil end
        return nil
    end
    local ok, store = pcall(function()
        return ActivePetsService:GetPlayerDatastorePetData(LocalPlayer.Name)
    end)
    if not ok or type(store) ~= "table" then
        if _TICK.active then _TICK.store = nil end
        return nil
    end
    if _TICK.active then
        _TICK.store = store
    end
    return store
end

local function __getStoreBag()
    if _TICK.active and _TICK.bag ~= false then
        return _TICK.bag
    end

    local store = __getStoreSnapshot()
    if not store or not store.PetInventory or not store.PetInventory.Data then
        if _TICK.active then
            _TICK.bag = nil
            _TICK.index = {}
        end
        return nil
    end

    local bag = store.PetInventory.Data
    if _TICK.active then
        _TICK.bag = bag
        _TICK.index = _buildBagIndex(bag)
    end
    return bag
end

local function __getBagIndex()
    if _TICK.active then
        if _TICK.index == nil then
            local bag = __getStoreBag()
            if not bag then
                _TICK.index = {}
            elseif _TICK.index == nil then
                _TICK.index = _buildBagIndex(bag)
            end
        end
        return _TICK.index
    end
    -- di luar tick: bangun index sementara dari bag fresh (jarang dipanggil)
    local bag = __getStoreBag()
    return _buildBagIndex(bag)
end

----------------------------------------------------------------
-- getBaseKg via bag/index (+ per-tick cache)
----------------------------------------------------------------
getBaseKg = function(uuid)
    if not uuid or uuid == "" then return nil end
    local key = _tickCacheKey(uuid)

    if _TICK.active and key and _TICK.base then
        local cached = _TICK.base[key]
        if cached ~= nil then
            return (cached ~= false) and cached or nil
        end
    end

    local n = nil
    local core, braced = __normUUID(uuid)
    local idx = __getBagIndex()
    local rec = idx and (
        idx[tostring(uuid)]
        or (braced and idx[braced])
        or (core and idx[core])
    ) or nil

    if type(rec) ~= "table" then
        -- fallback: snapshot langsung (jarang, kalau index gagal)
        local store = __getStoreSnapshot()
        if store and store.PetInventory and store.PetInventory.Data then
            rec = store.PetInventory.Data[core] or store.PetInventory.Data[braced]
        end
    end

    if type(rec) == "table" then
        local PD = rec.PetData or rec.Data or {}
        local raw = rec.BaseWeight or rec.BaseWeightKG or rec.WeightBase
            or PD.BaseWeight or PD.BaseWeightKG or PD.WeightBase
        n = __toNumberKG(raw)
    end

    if _TICK.active and key and _TICK.base then
        _TICK.base[key] = n or false
    end
    return n
end


local function __mutation_names_from_record(rec)
    if type(rec) ~= "table" then return {} end

    local PD = rec.PetData or rec.Data or {}

    local raw =
        PD.MutationType or
        rec.MutationType or
        PD.Mutations or PD.Mutation or PD.MutationCodes or
        rec.Mutations or rec.Mutation or rec.MutationCodes

    if not raw then
        return {}
    end

    local codes = {}

    local function addCodeString(s)
        if type(s) ~= "string" or s == "" then return end

        -- cek kode utuh dulu, contoh: "EV"
        if MUT_CODE_TO_NAME[s] then
            table.insert(codes, s)
            return
        end

        -- fallback pecah per huruf, contoh: "BSR" => B,S,R
        for c in s:gmatch("%a") do
            if MUT_CODE_TO_NAME[c] then
                table.insert(codes, c)
            end
        end
    end

    if type(raw) == "string" then
        addCodeString(raw)

    elseif type(raw) == "table" then
        for _, v in pairs(raw) do
            if type(v) == "string" then
                addCodeString(v)

            elseif type(v) == "table" then
                addCodeString(v.MutationType)
                addCodeString(v.EnumId)
                addCodeString(v.Code)
                addCodeString(v.code)
                addCodeString(v.Mutation)
            end
        end
    end

    local names, seen = {}, {}

    for _, code in ipairs(codes) do
        local name = MUT_CODE_TO_NAME[code]
        if name and not seen[name] then
            seen[name] = true
            table.insert(names, name)
        end
    end

    return names
end



local function _getPetRecord(uuid)
    if not uuid then return nil end
    uuid = tostring(uuid)

    --------------------------------------------------------
    -- 1) PAKAI DATASTORE BAG (O(1) via index saat tick cache aktif)
    --------------------------------------------------------
    do
        local core, br = __normUUID(uuid)
        local idx = __getBagIndex()
        if idx then
            local rec = idx[uuid]
                or (br and idx[br])
                or (core and idx[core])
            if type(rec) == "table" then
                return rec
            end
        end
    end

    --------------------------------------------------------
    -- 2) Fallback ke PetUtilities (kalau ada & bentuknya table)
    --------------------------------------------------------
    if PetUtilities and PetUtilities.GetPetByUUID then
        local ok, rec = pcall(function()
            return PetUtilities:GetPetByUUID(LocalPlayer, uuid)
        end)
        if ok and rec and type(rec) == "table" then
            return rec
        end
    end

    --------------------------------------------------------
    -- 3) Fallback terakhir: PetsService
    --------------------------------------------------------
    if PetsService then
        local ok, rec = pcall(function()
            if PetsService.GetPetByUUID then
                return PetsService:GetPetByUUID(LocalPlayer, uuid)
            elseif PetsService.GetPet then
                return PetsService:GetPet(uuid)
            end
        end)
        if ok and rec then
            return rec
        end
    end

    return nil
end



-- HAPUS atau abaikan: local MUT_NAME_CACHE = MUT_NAME_CACHE or {}

local function _getMutationNamesForUUID(uuid)
    if not uuid then return {} end
    uuid = tostring(uuid)
    local key = _tickCacheKey(uuid)

    if _TICK.active and key and _TICK.mut then
        local cached = _TICK.mut[key]
        if cached ~= nil then
            return cached
        end
    end

    local rec = _getPetRecord and _getPetRecord(uuid) or nil
    if not rec then
        if _TICK.active and key and _TICK.mut then
            _TICK.mut[key] = {}
        end
        return {}
    end

    local names = __mutation_names_from_record(rec) or {}

    if _TICK.active and key and _TICK.mut then
        _TICK.mut[key] = names
    end

    return names
end


