-- kumpulkan semua uuid yang dipakai AutoKG (boost / noos / seratusage / xp / gbxp)
local function unequipAllAutoKG()
    local all = {}

    local function addFrom(setTbl)
        if type(setTbl) ~= "table" then return end
        for uuid, on in pairs(setTbl) do
            if on then
                all[uuid] = true
            end
        end
    end

    addFrom(selected.boost)
    addFrom(selected.noos)
    addFrom(selected.seratusage)
    addFrom(selected.xp)
    addFrom(selected.gbxp)

    for uuid, _ in pairs(all) do
        safeUnequip(uuid)
    end
end

------------------------------------------------------------
-- 🔍 Ambil level pet (AGE) dengan debug lengkap
------------------------------------------------------------
local function _norm(u)
    -- buang/ambil kurung kurawal bila ada
    if not u or u == "" then return nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    return core, "{"..core.."}"
end

local function _pickLevel(t)
    if type(t) ~= "table" then return nil end
    return tonumber(t.Level)
        or tonumber(t.PetData and t.PetData.Level)
        or tonumber(t.Data    and t.Data.Level)
end

if not getPetAge then
    function getPetAge(uuid)
        if not uuid or uuid == "" then return nil end
        local key = _tickCacheKey(uuid)
        if _TICK.active and key and _TICK.age then
            local cached = _TICK.age[key]
            if cached ~= nil then
                return (cached ~= false) and cached or nil
            end
        end

        local uNorm, uBraced = _norm(uuid)
        local lvl = nil

        -- 1) Saat tick aktif: baca dari bag index dulu (hindari 200x PetUtilities)
        if _TICK.active then
            local rec = _getPetRecord(uuid)
            if type(rec) == "table" then
                lvl = _pickLevel(rec)
            end
        end

        -- 2) PetUtilities (uNorm → uBraced)
        if not lvl then
            for _, u in ipairs({ uNorm, uBraced }) do
                local ok, data = pcall(function()
                    return PetUtilities:GetPetByUUID(LocalPlayer, u)
                end)
                if ok and type(data) == "table" then
                    lvl = _pickLevel(data)
                    if lvl then break end
                end
            end
        end

        -- 3) Fallback datastore (reuse snapshot kalau tick aktif)
        if not lvl then
            local store = __getStoreSnapshot()
            if not store then
                -- biarkan nil; jangan spam warn tiap pet di list 200
            else
                local bag = store.PetInventory and store.PetInventory.Data
                local pet = bag and (bag[uNorm] or bag[uBraced]) or nil
                if pet then
                    lvl = _pickLevel(pet)
                end
            end
        end

        if _TICK.active and key and _TICK.age then
            _TICK.age[key] = lvl or false
        end
        return lvl
    end
end



------------------------------------------------------------
-- WEIGHT@LEVEL100 (tanpa base)
------------------------------------------------------------
local SCALE = PetRegistry.PetConfig.WEIGHT_CONFIG.SCALE_PERCENTAGE_OF_BASE_WEIGHT_PER_LEVEL

-- Pastikan global getBaseKg menunjuk ke implementasi lokal (kalau belum di-set loader)
if not rawget(_G, "getBaseKg") then
    _G.getBaseKg = getBaseKg
end

if not getWeightAtLevel100 then
    function getWeightAtLevel100(uuid)
        if not uuid or uuid == "" then return nil end
        local key = _tickCacheKey(uuid)
        if _TICK.active and key and _TICK.w100 then
            local cached = _TICK.w100[key]
            if cached ~= nil then
                return (cached ~= false) and cached or nil
            end
        end

        local base = getBaseKg and getBaseKg(uuid) or nil
        local w = base and (base * (1 + SCALE * 100)) or nil

        if _TICK.active and key and _TICK.w100 then
            _TICK.w100[key] = w or false
        end
        return w
    end
end

------------------------------------------------------------
-- WEBHOOK STAGE SESSION TRACKER
------------------------------------------------------------
local STAGE_SESS = STAGE_SESS or {}

local function _round2(n)
    n = tonumber(n)
    if not n then return nil end
    return math.floor(n * 100 + 0.5) / 100
end

local function _nowSec()
    local ok, v = pcall(function()
        return workspace:GetServerTimeNow()
    end)
    if ok and type(v) == "number" then
        return v
    end
    return os.time()
end

local function _fmtDuration(sec)
    sec = math.floor(tonumber(sec) or 0)
    local h = math.floor(sec / 3600)
    local m = math.floor((sec % 3600) / 60)
    local s = sec % 60
    return string.format("%02d:%02d:%02d", h, m, s)
end

local function _stageKey(uuid, stage)
    local core = tostring(uuid or ""):match("{?([0-9a-fA-F%-]+)}?") or tostring(uuid or "")
    if core == "" then
        core = tostring(uuid or "")
    end
    return "{" .. core .. "}|" .. tostring(stage or "-")
end

local function _stageRole(stage)
    stage = tostring(stage or "")
    if stage == "A" then return "boost" end
    if stage == "B" then return "xp" end
    if stage == "C" then return "noos" end
    if stage == "D" then return "seratusage" end
    return "unknown"
end

local function _getPetTypeFromRecord(rec)
    if type(rec) ~= "table" then return nil end
    local PD = rec.PetData or rec.Data or {}

    return rec.PetType
        or rec.Type
        or rec.Name
        or rec.ItemName
        or PD.PetType
        or PD.Type
        or PD.Name
        or PD.ItemName
end

local function _getPetInfo(uuid)
    local rec = _getPetRecord and _getPetRecord(uuid) or nil

    local age = nil
    pcall(function()
        age = getPetAge and getPetAge(uuid)
    end)

    local w100 = nil
    pcall(function()
        w100 = getWeightAtLevel100 and getWeightAtLevel100(uuid)
    end)
    
    local kg = nil
    pcall(function()
       local age = getPetAge and getPetAge(uuid)
        local base = getBaseKg and getBaseKg(uuid)

        if base and age then
        kg = base * (1 + SCALE * age)
         end
    end)

    local muts = {}
    pcall(function()
        muts = _getMutationNamesForUUID and _getMutationNamesForUUID(uuid) or {}
    end)

    return {
        uuid      = tostring(uuid or ""),
        short     = _shortUUID(uuid),
        petType   = _getPetTypeFromRecord(rec) or "Unknown",
        age       = age and math.floor(age + 0.0001) or nil,
        kg        = _round2(kg),      -- KG sekarang
        w100      = _round2(w100),
        mutations = muts,
        mutText   = (#muts > 0 and table.concat(muts, ", ")) or "-",
    }
end

local function _teamToArray(teamMap)
    local out = {}

    for role, pets in pairs(teamMap or {}) do
        local arr = {}

        for _, info in pairs(pets or {}) do
            local pet = info.pet or {}

            table.insert(arr, {
                petType = pet.petType or "Unknown",
                kg = pet.w100 or pet.kg,
            })
        end

        table.sort(arr, function(a, b)
            return tostring(a.petType or "") < tostring(b.petType or "")
        end)

        out[role] = arr
    end

    return out
end

local function _fillTeamSnapshot(sess, role, arr)
    if not sess or not role or type(arr) ~= "table" then return end
    sess.team = sess.team or {}
    sess.team[role] = sess.team[role] or {}

    for _, uuid in ipairs(arr) do
        if uuid then
            local k = tostring(uuid)
            sess.team[role][k] = sess.team[role][k] or {
                role = role,
                pet = _getPetInfo(uuid),
                reasons = { snapshot = true },
            }
        end
    end
end

local function _addSupportToStageSessions(role, uuid, reason)
    role = tostring(role or "")
    if role ~= "boost" and role ~= "xp" and role ~= "noos" and role ~= "seratusage" then
        return
    end

    for _, sess in pairs(STAGE_SESS) do
        if sess.role == role then
            sess.team[role] = sess.team[role] or {}

            local k = tostring(uuid)
            sess.team[role][k] = sess.team[role][k] or {
                role = role,
                pet = _getPetInfo(uuid),
                reasons = {},
            }

            local r = tostring(reason or "")
            if r ~= "" then
                sess.team[role][k].reasons[r] = true
            end
        end
    end
end

local function _makeStageEndPetInfo(rec, fallbackUuid)
    if rec and rec.uuid then
        local info = _getPetInfo(rec.uuid)
        info.age = rec.age
        info.w100 = _round2(rec.w100)
        return info
    end

    return _getPetInfo(fallbackUuid)
end

