-- GBXP MAIN LOOP CONFIG
------------------------------------------------------------
local EPS                     = EPS or 1e-6
local ACTION_DELAY_SEC        = ACTION_DELAY_SEC or 0.12
local TRACE_EVERY_N           = TRACE_EVERY_N or 20
DEBUG_LEVEL                   = DEBUG_LEVEL or 2

local DEFAULT_W100_MAX        = DEFAULT_W100_MAX or 60.45
local AGE_MAX_UNEQUIP_B       = AGE_MAX_UNEQUIP_B or 100
local REEQUIP_RETRY_SEC       = REEQUIP_RETRY_SEC or 1
local REEQUIP_RETRY_SEC_TAB       = REEQUIP_RETRY_SEC_TAB or 1
local B_AFTER_ACTION_WAIT_SEC = B_AFTER_ACTION_WAIT_SEC or 600

local __loopCounter = 0

-- Fix5: throttle adaptif biar 200 pet tidak makan CPU tiap 0.1s
-- (<80 → 0.10s | 80–149 → 0.18s | ≥150 → 0.25s)
local function _loopWaitForCount(n)
    n = tonumber(n) or 0
    if n >= 150 then
        return 0.25
    elseif n >= 80 then
        return 0.18
    end
    return 0.10
end

local function _getW100MaxEquip()
    local kgEq = rawget(G, "TAB_W_EQUIP_MIN") or TAB_W_EQUIP_MIN
    local v = kgEq and kgEq.noos

    if type(v) == "number" and v ~= 0 then
        return math.abs(v)
    end

    return DEFAULT_W100_MAX
end


local function _ts()
    local s = os and os.date and os.date("%H:%M:%S") or tostring(tick()):sub(1,6)
    return "["..s.."]"
end

local function d(lvl, ...)
    if not GBXP_DEBUG then return end
    if (lvl or 2) > DEBUG_LEVEL then return end
    local parts = { _ts(), "[GBXP]" }
    for i = 1, select("#", ...) do
        parts[#parts+1] = tostring(select(i, ...))
    end
    print(table.concat(parts, " "))
end

local function dx(...)
    d(3, ...)
end


