local function _invalidateEquippedCache()
    if _TICK.active then
        _TICK.equipped = false
    end
end

local function _getEquippedSetFromWorld(force)
    if _TICK.active and not force and type(_TICK.equipped) == "table" then
        return _TICK.equipped
    end

    local set = {}

    -- 1) runtime active pets
    local ok1, active = pcall(function()
        return ActivePetsService and ActivePetsService:GetActivePetsForPlayer(LocalPlayer)
    end)
    if ok1 and type(active) == "table" then
        for _, u in ipairs(active) do
            set[tostring(u)] = true
        end
    end

    -- 2) datastore snapshot (reuse __getStoreSnapshot saat tick aktif)
    local pdata = __getStoreSnapshot()
    if type(pdata) == "table" then
        local PD = pdata.PetsData or pdata.Data or pdata
        local eq = PD and (PD.EquippedPets or PD.equipped or PD.Equipped) or nil
        if type(eq) == "table" then
            for _, u in ipairs(eq) do
                set[tostring(u)] = true
            end
        end
    end

    if _TICK.active then
        _TICK.equipped = set
    end
    return set
end

local function _isEquippedNow(uuid, worldSet)
    if not uuid then return false end
    return worldSet[tostring(uuid)] == true
end

local function _isInStore(uuid)
    if hasPetInStore then
        local ok, res = pcall(hasPetInStore, uuid)
        if ok then return res end
    end
    return true
end

------------------------------------------------------------
-- Safe wrappers untuk equip/unequip
------------------------------------------------------------
local function _safeEquip(u, why, where)
    if not u then return end
    d(2, "equip", u, where and ("@"..where) or "", why and ("| "..why) or "")

    local ok, err = pcall(function()
        safeEquip(u)
    end)

    if ok then
        _addSupportToStageSessions(tostring(where or ""), u, why)
        _invalidateEquippedCache()
    else
        d(1, "equip-fail", u, tostring(err))
    end

    task.wait(ACTION_DELAY_SEC)
end

local function _safeUnequip(u, why, where)
    if not u then return end
    d(2, "unequip", u, where and ("@"..where) or "", why and ("| "..why) or "")

    local ok, err = pcall(function()
        safeUnequip(u)
    end)

    if ok then
        _addSupportToStageSessions(tostring(where or ""), u, why)
        _invalidateEquippedCache()
    else
        d(1, "unequip-fail", u, tostring(err))
    end

    task.wait(ACTION_DELAY_SEC)
end

local function _equipMany(arr, why, where)
    if type(arr) ~= "table" or #arr == 0 then return end
    d(2, "equipMany #"..tostring(#arr), where and ("@"..where) or "", why or "")
    local ok, err = pcall(function() equipMany(arr) end)
    if not ok then d(1, "equipMany-fail", tostring(err)) end
    _invalidateEquippedCache()
    task.wait(ACTION_DELAY_SEC)
end

local function _unequipMany(arr, why, where)
    if type(arr) ~= "table" or #arr == 0 then return end
    d(2, "unequipMany #"..tostring(#arr), where and ("@"..where) or "", why or "")
    local ok, err = pcall(function() unequipMany(arr) end)
    if not ok then d(1, "unequipMany-fail", tostring(err)) end
    _invalidateEquippedCache()
    task.wait(ACTION_DELAY_SEC)
end

local function _countSet(t)
    local n = 0
    for _, v in pairs(t or {}) do
        if v == true then n += 1 end
    end
    return n
end

-- Unequip SEMUA pet yang masih equipped di garden
local function unequipAllPetsInGarden(maxWaitSec, why)
    maxWaitSec = tonumber(maxWaitSec) or 10
    why = tostring(why or "garden_clear")
    local t0 = tick()
    local lastCount = nil

    while (tick() - t0) < maxWaitSec do
        local ws = _getEquippedSetFromWorld()
        local c = _countSet(ws)
        if c <= 0 then
            d(1, "unequipAllPetsInGarden: empty OK", why)
            return true
        end

        if lastCount == nil or c ~= lastCount then
            d(1, ("unequipAllPetsInGarden: %d pet(s), unequipping"):format(c), why)
            lastCount = c
        end

        for uuid, _ in pairs(ws) do
            safeUnequip(uuid)
        end
        _invalidateEquippedCache()
        task.wait(0.35)
    end

    local remain = _countSet(_getEquippedSetFromWorld(true))
    if remain > 0 then
        d(1, "unequipAllPetsInGarden: still not empty", "count=" .. tostring(remain), why)
        return false
    end
    return true
end

------------------------------------------------------------
-- GBXP stage & rule helpers
------------------------------------------------------------
local function _isMutationSelected(uuid)
    if not _getMutationNamesForUUID then return false end

    local selectedLC = {}
    for k, v in pairs(GBXP_MUT_SELECTED or {}) do
        if v then
            selectedLC[tostring(k):lower()] = true
        end
    end

    local muts = _getMutationNamesForUUID(uuid) or {}
    for _, name in ipairs(muts) do
        local s = tostring(name)
        if GBXP_MUT_SELECTED[s] or selectedLC[s:lower()] then
            return true
        end
    end

    return false
end

local function _recordIsFavorite(rec)
    if type(rec) ~= "table" then
        return false
    end
    local PD = rec.PetData or rec.Data or {}
    if type(PD.IsFavorite) == "boolean" then return PD.IsFavorite == true end
    if type(PD.IsFavourite) == "boolean" then return PD.IsFavourite == true end
    if type(PD.IsFavorited) == "boolean" then return PD.IsFavorited == true end
    if type(rec.IsFavorite) == "boolean" then return rec.IsFavorite == true end
    if type(rec.IsFavourite) == "boolean" then return rec.IsFavourite == true end
    if type(rec.IsFavorited) == "boolean" then return rec.IsFavorited == true end
    return PD.Favorite == true or rec.Favorite == true
end

-- Sama seperti donor shark: favorite di-skip. Record hilang → anggap fav.
local function _gbxpIsFavorite(uuid)
    local rec = _getPetRecord and _getPetRecord(uuid) or nil
    if type(rec) ~= "table" then
        local bag = __getStoreBag and __getStoreBag() or nil
        if type(bag) == "table" then
            local core, br = __normUUID(uuid)
            rec = bag[uuid] or (br and bag[br]) or (core and bag[core])
        end
    end
    if type(rec) ~= "table" then
        return true
    end
    return _recordIsFavorite(rec)
end

-- GBXP yang punya mutasi tapi bukan Select Mutation to donor → perlu shard.
-- Mutasi kosong tidak bisa di-cleanse.
local function _gbxpNeedsShardClean(uuid)
    if not uuid then
        return false
    end
    if _gbxpIsFavorite(uuid) then
        return false
    end
    if _isPetInMutationMachine(uuid) then
        return false
    end
    if _isMutationSelected(uuid) then
        return false
    end
    local muts = _getMutationNamesForUUID(uuid) or {}
    return type(muts) == "table" and #muts > 0
end

------------------------------------------------------------
-- SHARK LIST MODE (packed table: avoid Lua 200-local chunk limit)
------------------------------------------------------------
local Shark = {}
Shark.DONOR_AGE = 100
Shark.BITE_TEAM_MAX = 8
Shark.RECEIVER_MAX = 1
Shark.MIMIC_MAX = 1

function Shark.uuidKeys(uuid)
    local out, seen = {}, {}
    local function add(v)
        v = tostring(v or "")
        if v == "" or seen[v] then return end
        seen[v] = true
        out[#out + 1] = v
    end
    add(uuid)
    local core, braced = __normUUID(uuid)
    add(core)
    add(braced)
    return out
end

function Shark.hasUUID(setTbl, uuid)
    if type(setTbl) ~= "table" or uuid == nil then return false end
    for _, key in ipairs(Shark.uuidKeys(uuid)) do
        local v = setTbl[key]
        if v == true or v == 1 or v == "true" then
            return true
        end
    end
    return false
end

function Shark.markUUID(setTbl, uuid)
    if type(setTbl) ~= "table" or uuid == nil then return end
    for _, key in ipairs(Shark.uuidKeys(uuid)) do
        setTbl[key] = true
    end
end

function Shark.filterOut(arr, protectSet)
    local out = {}
    for _, u in ipairs(arr or {}) do
        if not Shark.hasUUID(protectSet, u) then
            out[#out + 1] = u
        end
    end
    return out
end

Shark.MIMIC_BITE_WINDOW = 12
Shark.SB = {}

function Shark.getMaxEquip()
    return Shark.tabTargetMax("boost")
end

function Shark.tabTargetMax(tabKey)
    local t = rawget(G, "TAB_TARGET_EQUIP_MAX") or rawget(_G, "TAB_TARGET_EQUIP_MAX") or TAB_TARGET_EQUIP_MAX
    local v = type(t) == "table" and tonumber(t[tabKey])
    if type(v) ~= "number" or v < 1 then
        v = 1
    end
    if v > 8 then
        v = 8
    end
    return math.floor(v)
end

function Shark.ownerTabMax(owner)
    if tostring(owner) == "AGE" then
        return Shark.tabTargetMax("seratusage")
    end
    return Shark.tabTargetMax("xp")
end

function Shark.readTypeSet(src)
    local out = {}
    if type(src) ~= "table" then return out end
    for k, on in pairs(src) do
        if on == true or on == 1 or on == "true" then
            local name = tostring(k)
            if name ~= "" then
                local core = name:match("{?([0-9a-fA-F%-]+)}?") or ""
                local looksUUID = (#core >= 30) and (core:find("%-") ~= nil) and (core:match("^[0-9a-fA-F%-]+$") ~= nil)
                if not looksUUID then
                    out[name] = true
                    local low = name:lower():gsub("^%s+", ""):gsub("%s+$", "")
                    if low ~= "" then
                        out[low] = true
                    end
                end
            end
        end
    end
    return out
end

function Shark.isTypePicked(pt, typeSet)
    if type(typeSet) ~= "table" or pt == nil then return false end
    local raw = tostring(pt)
    if typeSet[raw] == true then return true end
    local low = raw:lower():gsub("^%s+", ""):gsub("%s+$", "")
    return low ~= "" and typeSet[low] == true
end

function Shark.petTypeOf(uuid)
    local rec = nil
    if type(_getPetRecord) == "function" then
        local ok, r = pcall(_getPetRecord, uuid)
        if ok then rec = r end
    end
    return rec and rec.PetType or nil
end

function Shark.typeIsShark(pt)
    return tostring(pt or ""):lower():gsub("^%s+", ""):gsub("%s+$", "") == "shark"
end

function Shark.typeIsMimic(pt)
    local low = tostring(pt or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
    if low == "mimic" or low == "mimic octopus" then
        return true
    end
    return low:find("mimic octopus", 1, true) ~= nil
end

function Shark.unequipAllSharks()
    local ws = _getEquippedSetFromWorld()
    for u, on in pairs(ws) do
        if on == true or on == 1 then
            if Shark.typeIsShark(Shark.petTypeOf(u)) then
                _safeUnequip(u, "shark off (farm XP/GBXP)", "shark-guard")
            end
        end
    end
end

-- Pet yang hanya untuk Shark Stage A (donor type / shark / mimic).
-- Jangan nempel setelah ganti mode CB/CD/B/... 
function Shark.keepForStage(activeStage, targetList, boostArr, xpArr, noosArr, ageArr)
    local keep = {}
    local function addArr(arr)
        for _, u in ipairs(arr or {}) do
            Shark.markUUID(keep, u)
        end
    end
    for _, rec in ipairs(targetList or {}) do
        if rec and rec.uuid then
            Shark.markUUID(keep, rec.uuid)
        end
    end
    local s = tostring(activeStage or "")
    if s == "A" then
        addArr(boostArr)
    elseif s == "B" then
        addArr(xpArr)
    elseif s == "C" then
        addArr(noosArr)
    elseif s == "D" then
        addArr(ageArr)
    end
    return keep
end

function Shark.markExclusive(arr)
    Shark._exclusiveEquipped = Shark._exclusiveEquipped or {}
    for _, u in ipairs(arr or {}) do
        Shark.markUUID(Shark._exclusiveEquipped, u)
    end
end

function Shark.stopExclusive(keepSet)
    keepSet = keepSet or {}
    local donorTypeSet = Shark.readTypeSet(G.NMLVL_SHARK_DONOR_TEAM or _G.NMLVL_SHARK_DONOR_TEAM or {})
    local ws = _getEquippedSetFromWorld()
    local strip = {}
    for u, _ in pairs(Shark._exclusiveEquipped or {}) do
        Shark.markUUID(strip, u)
    end
    for u, on in pairs(ws) do
        if on == true or on == 1 or on == "true" then
            local pt = Shark.petTypeOf(u)
            if Shark.typeIsShark(pt) or Shark.typeIsMimic(pt) or Shark.isTypePicked(pt, donorTypeSet) then
                Shark.markUUID(strip, u)
            end
        end
    end
    for u, _ in pairs(strip) do
        if not Shark.hasUUID(keepSet, u) and not _isPetInMutationMachine(u) then
            if _isEquippedNow(u, ws) then
                _safeUnequip(u, "shark exclusive off (no Stage A bite/level)", "shark-stop")
                ws = _getEquippedSetFromWorld()
            end
        end
    end
    Shark._exclusiveEquipped = {}
end

function Shark.stripGardenIfSharkOut(keepSet)
    keepSet = keepSet or {}
    local ws = _getEquippedSetFromWorld()
    local sharkOut = false
    for u, on in pairs(ws) do
        if (on == true or on == 1) and Shark.typeIsShark(Shark.petTypeOf(u)) then
            sharkOut = true
            break
        end
    end
    if not sharkOut then
        return
    end
    ws = _getEquippedSetFromWorld()
    for u, on in pairs(ws) do
        if (on == true or on == 1) and not Shark.hasUUID(keepSet, u) then
            if not _isPetInMutationMachine(u) then
                _safeUnequip(u, "shark garden only mimic+donor+target", "shark-guard")
            end
        end
    end
end

function Shark.SB.uuidCore(u)
    return tostring(u or ""):match("{?([0-9a-fA-F%-]+)}?") or tostring(u or "")
end

function Shark.SB.rt()
    local rt = rawget(G, "__SHARK_MIMIC_RT")
    if type(rt) ~= "table" then
        rt = rawget(_G, "__SHARK_MIMIC_RT")
    end
    if type(rt) ~= "table" then
        rt = {}
    end
    if type(rt.cdByCore) ~= "table" then
        rt.cdByCore = {}
    end
    if rt.mode ~= "wait" and rt.mode ~= "food" then
        rt.mode = "wait"
    end
    rt.biteUntil = tonumber(rt.biteUntil) or 0
    rt.ignoreMimicUntil = tonumber(rt.ignoreMimicUntil) or 0
    rt.mimicCore = tostring(rt.mimicCore or "")
    rt.connVer = tonumber(rt.connVer) or 0
    G.__SHARK_MIMIC_RT = rt
    _G.__SHARK_MIMIC_RT = rt
    return rt
end

function Shark.SB.parseCd(data)
    local mimicry = nil
    local copied = false
    local copiedName = nil
    if type(data) ~= "table" then
        return { mimicry = nil, copied = false, copiedName = nil, at = os.clock() }
    end
    for _, item in pairs(data) do
        if type(item) == "table" then
            local name = tostring(item.Passive or item.passive or item.Skill or item.skill or item.Name or "")
            local low = name:lower()
            local t = tonumber(item.Time or item.time or item.Remaining or item.Remain or item.Cooldown)
            if low:find("mimicry", 1, true) then
                if t ~= nil and t == t and t > -1e9 and t < 1e9 then
                    mimicry = math.max(0, t)
                end
            elseif t ~= nil and t == t and t > 1 then
                copied = true
                copiedName = name
            end
        end
    end
    return { mimicry = mimicry, copied = copied, copiedName = copiedName, at = os.clock() }
end

function Shark.SB.ensureCdConn()
    local rt = Shark.SB.rt()
    if rt.connVer == 71 and rt.conn then
        return
    end
    if rt.conn then
        pcall(function()
            rt.conn:Disconnect()
        end)
        rt.conn = nil
    end
    local ev = (GameEvents and GameEvents:FindFirstChild("PetCooldownsUpdated"))
        or PetCooldownsUpdated
    if not ev then
        return
    end
    rt.connVer = 71
    rt.conn = ev.OnClientEvent:Connect(function(uuid, cds)
        local core = Shark.SB.uuidCore(uuid)
        if core == "" then
            return
        end
        local pack = Shark.SB.parseCd(cds)
        local prev = rt.cdByCore[core]
        if pack.mimicry == nil and type(prev) == "table" and prev.mimicry ~= nil then
            local elapsed = os.clock() - (tonumber(prev.at) or os.clock())
            pack.mimicry = math.max(0, (tonumber(prev.mimicry) or 0) - elapsed)
        end
        rt.cdByCore[core] = pack
        if core == tostring(rt.mimicCore or "") then
            rt.evTime = pack and pack.mimicry
        end
    end)
end

function Shark.SB.refreshCd(uuid)
    Shark.SB.ensureCdConn()
    local rt = Shark.SB.rt()
    local core = Shark.SB.uuidCore(uuid)
    return rt.cdByCore[core] or { mimicry = nil, at = os.clock() }
end

function Shark.SB.mimicryRemain(uuid)
    local pack = Shark.SB.refreshCd(uuid)
    local base = pack and tonumber(pack.mimicry)
    if base == nil then
        return nil
    end
    local elapsed = os.clock() - (tonumber(pack.at) or os.clock())
    return math.max(0, base - elapsed)
end

function Shark.SB.fmtCd(sec)
    if type(sec) ~= "number" then
        return "--"
    end
    local s = math.max(0, math.floor(sec + 0.5))
    return string.format("%d:%02d", math.floor(s / 60), s % 60)
end

function Shark.SB.getUnequipSharkDelay()
    local st = rawget(G, "STATE") or _G.STATE
    local v = tonumber(rawget(G, "NMLVL_SHARK_UNEQUIP_DELAY"))
        or tonumber(rawget(_G, "NMLVL_SHARK_UNEQUIP_DELAY"))
        or tonumber(st and st.sharkUnequipDelay)
        or 1
    if v < 0 then v = 0 end
    if v > 30 then v = 30 end
    return v
end

function Shark.SB.loopOn()
    return running == true
end

function Shark.SB.stopHooks()
    if Shark.SB._hb then
        pcall(function()
            Shark.SB._hb:Disconnect()
        end)
        Shark.SB._hb = nil
        Shark.SB._hbVer = nil
    end
    local R
    pcall(function()
        R = Shark.SB.rt()
    end)
    if type(R) == "table" then
        if R.animConn then
            pcall(function()
                R.animConn:Disconnect()
            end)
            R.animConn = nil
        end
        R.boundCore = nil
        R.mode = "wait"
        R.biteUntil = 0
        R.mimicCore = ""
        R.readySince = nil
        R.cdArmed = false
        R.foodSawReady = false
        R.ignoreMimicUntil = os.clock() + 1e12
    end
end

function Shark.syncGarden(desiredArr, why)
    desiredArr = desiredArr or {}
    local keep = {}
    for _, u in ipairs(desiredArr) do
        Shark.markUUID(keep, u)
    end
    local ws = _getEquippedSetFromWorld()
    for u, on in pairs(ws) do
        if (on == true or on == 1 or on == "true")
            and type(u) == "string"
            and not Shark.hasUUID(keep, u)
        then
            if not _isPetInMutationMachine(u) then
                pcall(function()
                    safeUnequip(u)
                end)
            end
        end
    end
    pcall(function()
        equipMany(desiredArr)
    end)
    _invalidateEquippedCache()
    return true
end

function Shark.SB.foodNow()
    if not Shark.SB.loopOn() then
        return
    end
    local R = Shark.SB.rt()
    if tostring(R.mode) == "food" then
        return
    end
    R.mode = "food"
    R.biteUntil = 0
    R.cdArmed = false
    R.readySince = nil
    R.foodSawReady = true
    local team = {}
    if R.mimic then team[#team + 1] = R.mimic end
    if R.donor then team[#team + 1] = R.donor end
    if R.recv then team[#team + 1] = R.recv end
    Shark.syncGarden(team, "SHARK food now")
end

function Shark.SB.isSkillAnim(name)
    local n = tostring(name or ""):lower()
    if n == "" or n == "idle" or n == "walk" or n == "run" then
        return false
    end
    return n == "mimicry"
end

function Shark.SB.hasBang(mdl)
    if not mdl then
        return false
    end
    local hit = false
    pcall(function()
        for _, d in ipairs(mdl:GetDescendants()) do
            if d:IsA("TextLabel") or d:IsA("TextButton") then
                local t = tostring(d.Text or "")
                if (t == "!" or t:find("!", 1, true)) and d.Visible ~= false then
                    hit = true
                    break
                end
            elseif d:IsA("ImageLabel") or d:IsA("BillboardGui") then
                local n = tostring(d.Name):lower()
                local on = true
                if d:IsA("BillboardGui") then
                    on = d.Enabled ~= false
                else
                    on = d.Visible ~= false
                end
                if on and (n:find("exclam") or n:find("alert") or n == "!" or n:find("warn")) then
                    hit = true
                    break
                end
            end
        end
    end)
    return hit
end

function Shark.SB.findOwnMimicModel(core)
    core = Shark.SB.uuidCore(core)
    if core == "" then
        return nil
    end
    local found = nil
    pcall(function()
        local folder = workspace:FindFirstChild("PetsPhysical")
        if not folder then
            return
        end
        for _, mover in ipairs(folder:GetChildren()) do
            if tostring(mover:GetAttribute("OWNER")) == LocalPlayer.Name
                and Shark.SB.uuidCore(mover:GetAttribute("UUID")) == core
            then
                found = mover:FindFirstChildWhichIsA("Model") or mover
                break
            end
        end
    end)
    return found
end

function Shark.SB.lookMimicry()
    if not Shark.SB.loopOn() then
        return
    end
    local R = Shark.SB.rt()
    if tostring(R.mode) ~= "wait" then
        return
    end
    if os.clock() < (tonumber(R.ignoreMimicUntil) or 0) then
        return
    end
    if tostring(R.mimic or "") == "" then
        return
    end
    local remain = Shark.SB.mimicryRemain(R.mimic)
    if remain == nil then
        R.readySince = nil
        return
    end
    if remain > 0.05 then
        R.cdArmed = true
        R.readySince = nil
        return
    end
    if R.cdArmed == false then
        return
    end
    if R.readySince == nil then
        R.readySince = os.clock()
    end
    local delay = Shark.SB.getUnequipSharkDelay()
    if (os.clock() - R.readySince) >= delay then
        Shark.SB.foodNow()
    end
end

function Shark.SB.endFood()
    if not Shark.SB.loopOn() then
        return
    end
    local R = Shark.SB.rt()
    if tostring(R.mode) ~= "food" then
        return
    end
    R.mode = "wait"
    R.biteUntil = 0
    R.readySince = nil
    R.foodSawReady = false
    R.cdArmed = false
    local team = {}
    if R.shark then team[#team + 1] = R.shark end
    if R.mimic then team[#team + 1] = R.mimic end
    Shark.syncGarden(team, "SHARK food done")
end

function Shark.SB.lookFoodDone()
    if not Shark.SB.loopOn() then
        return
    end
    local R = Shark.SB.rt()
    if tostring(R.mode) ~= "food" then
        return
    end
    if tostring(R.mimic or "") == "" then
        return
    end
    local pack = Shark.SB.refreshCd(R.mimic)
    local remain = Shark.SB.mimicryRemain(R.mimic)
    if remain == nil then
        remain = pack and tonumber(pack.mimicry)
    end
    -- Hanya Mimicry. CD skill copy (delay skill ke-2) diabaikan.
    if remain ~= nil and remain <= 0.05 then
        R.foodSawReady = true
        return
    end
    if R.foodSawReady == true and remain ~= nil and remain >= 1 then
        Shark.SB.endFood()
    end
end

function Shark.SB.bindBiteAnim()
    -- hatch v71: bite tidak lagi dari anim/VFX
end

function Shark.SB.ensureHb()
    if not Shark.SB.loopOn() then
        return
    end
    if Shark.SB._hb and Shark.SB._hbVer == 71 then
        return
    end
    if Shark.SB._hb then
        pcall(function()
            Shark.SB._hb:Disconnect()
        end)
        Shark.SB._hb = nil
    end
    pcall(function()
        Shark.SB._hbVer = 71
        Shark.SB._hb = game:GetService("RunService").Heartbeat:Connect(function()
            if not Shark.SB.loopOn() then
                return
            end
            local R = Shark.SB.rt()
            if tostring(R.mode) == "food" then
                Shark.SB.lookFoodDone()
            elseif tostring(R.mode) == "wait" and tostring(R.mimicCore or "") ~= "" then
                Shark.SB.lookMimicry()
            end
            local VR = rawget(G, "__VENOM_MIMIC_RT") or rawget(_G, "__VENOM_MIMIC_RT")
            if type(VR) == "table" and type(VR.lookMimicry) == "function" then
                VR.lookMimicry()
            end
        end)
    end)
end

function Shark.SB.hookVfx()
    -- Shark bite = Mimicry CD. VFX wrap tetap untuk Venom CAST.
    pcall(function()
        local PetVFXMod = require(ReplicatedStorage.Modules.PetServices.PetVFXHandler)
        if not PetVFXMod.__autokgSharkMimicOrig then
            PetVFXMod.__autokgSharkMimicOrig = PetVFXMod.playVFX
        end
        PetVFXMod.__autokgSharkMimicWatch = 71
        function PetVFXMod:playVFX(anim)
            local orig = PetVFXMod.__autokgSharkMimicOrig
            local animLow = tostring(anim or ""):lower()
            if animLow == "mimicry" then
                local VR = rawget(G, "__VENOM_MIMIC_RT") or rawget(_G, "__VENOM_MIMIC_RT")
                if type(VR) == "table" and type(VR.onCast) == "function" then
                    VR.onCast(self and self.UUID)
                end
            end
            if orig then
                return orig(self, anim)
            end
        end
    end)
end

function Shark.SB.thresh()
    local emin, emax
    pcall(function()
        local MAIN = rawget(G, "MAIN") or _G.MAIN
        local th = MAIN and MAIN.nmlvl and MAIN.nmlvl.state and MAIN.nmlvl.state.thresholds
        if type(th) == "table" then
            emin = th.age_equip_min
            emax = th.age_unequip_min
        end
    end)
    if type(emin) ~= "table" then
        emin = (type(TAB_AGE_EQUIP_MIN) == "table") and TAB_AGE_EQUIP_MIN or {}
    end
    if type(emax) ~= "table" then
        emax = (type(TAB_AGE_UNEQUIP_MIN) == "table") and TAB_AGE_UNEQUIP_MIN or {}
    end
    return emin, emax
end

function Shark.SB.donorOwner(snap)
    snap = snap or {}
    local pickAge = nil
    local farm = snap.farmArr or {}
    local function readAge(u)
        local a = nil
        if type(getPetAge) == "function" then
            local ok, v = pcall(getPetAge, u)
            if ok then a = tonumber(v) end
        end
        if a == nil then
            for _, rec in ipairs(snap.youngArr or {}) do
                if rec and rec.uuid and Shark.SB.uuidCore(rec.uuid) == Shark.SB.uuidCore(u) then
                    a = tonumber(rec.age)
                    break
                end
            end
        end
        return a
    end
    -- farmArr di-sort umur terbesar dulu: owner ikut donor yang di-level
    if farm[1] then
        pickAge = readAge(farm[1])
    end
    if pickAge == nil then
        for _, rec in ipairs(snap.youngArr or {}) do
            local a = tonumber(rec and rec.age)
            if a ~= nil and (pickAge == nil or a > pickAge) then
                pickAge = a
            end
        end
    end
    if pickAge == nil then
        return "XP"
    end
    local emin, emax = Shark.SB.thresh()
    local agMin = tonumber(emin and emin.seratusage)
    if agMin == nil then
        agMin = 50
    end
    local xpMin = tonumber(emin and emin.xp) or 0
    local xpMax = tonumber(emax and emax.xp)
    if xpMax == nil then
        xpMax = 50
    end
    local agMax = tonumber(emax and emax.seratusage) or 0
    if pickAge >= xpMin and (xpMax == 0 or pickAge < xpMax) then
        return "XP"
    end
    if (pickAge + (EPS or 0)) >= agMin and (agMax == 0 or pickAge < agMax) then
        return "AGE"
    end
    return "XP"
end

function Shark.applyBiteNow(snap, gbxpArr, boostArr, xpArr, ageArr, noosArr)
    snap = snap or {}
    Shark.SB.lookMimicry()
    Shark.SB.lookFoodDone()
    local rt = Shark.SB.rt()
    if tostring(rt.mode) == "food" then
        Shark.syncGarden(snap.biteArr or {}, "SHARK food")
        Shark.markExclusive(snap.biteArr)
        return
    end
    Shark.syncGarden(snap.biteArr or {}, "SHARK wait")
    Shark.markExclusive(snap.biteArr)
end

function Shark.applyLevelDonorNow(snap, gbxpArr, boostArr, xpArr, ageArr, noosArr)
    snap = snap or {}
    local GARDEN_MAX = 8
    local owner = Shark.SB.donorOwner(snap)
    local donorCap = Shark.ownerTabMax(owner)
    local src = snap.farmArr or snap.donorArr or {}
    local supportSrc = (owner == "AGE") and (ageArr or {}) or (xpArr or {})

    local farmArr, farmSet, seen = {}, {}, {}
    for _, u in ipairs(src) do
        if #farmArr >= donorCap then break end
        if u ~= nil then
            local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
            if core ~= "" and not seen[core] then
                seen[core] = true
                farmArr[#farmArr + 1] = u
                Shark.markUUID(farmSet, u)
            end
        end
    end
    snap.farmArr = farmArr
    snap.farmSet = farmSet

    local leftover = math.max(0, GARDEN_MAX - #farmArr)
    local supportArr, supportSet = {}, {}
    for _, u in ipairs(supportSrc) do
        if #supportArr >= leftover then break end
        if u and not Shark.hasUUID(farmSet, u) and not Shark.hasUUID(supportSet, u) then
            supportArr[#supportArr + 1] = u
            Shark.markUUID(supportSet, u)
        end
    end

    local protect = {}
    for _, u in ipairs(supportArr) do Shark.markUUID(protect, u) end
    for _, u in ipairs(farmArr) do Shark.markUUID(protect, u) end

    _unequipMany(Shark.filterOut(boostArr or {}, protect), "BOOST OFF (level donor)", "shark-level-boost")
    _unequipMany(Shark.filterOut(noosArr or {}, protect), "NOOS OFF (level donor)", "shark-level-noos")
    _unequipMany(Shark.filterOut(gbxpArr or {}, farmSet), "GBXP OFF (level donor)", "shark-level-gbxp")

    local desired = {}
    for _, u in ipairs(supportArr) do
        desired[#desired + 1] = u
    end
    for _, u in ipairs(farmArr) do
        desired[#desired + 1] = u
    end
    Shark.syncGarden(desired, "LEVEL DONOR " .. tostring(owner))
    Shark.markExclusive(desired)
end

function Shark.syncPnP(reason, holdOff)
    local S = rawget(G, "STATE") or rawget(_G, "STATE")
    if type(S) ~= "table" then return end

    local cfg = S.swap_skill
    local gs = rawget(G, "swap_skill") or rawget(_G, "swap_skill")
    -- Split STATE vs G.swap_skill: Enable OFF on either copy must stop PnP.
    local cfgOn = (type(cfg) == "table" and cfg.enabled == true)
    if type(gs) == "table" and gs.enabled ~= true then
        cfgOn = false
    end
    if type(cfg) == "table" and cfg.enabled ~= true then
        cfgOn = false
    end
    local wantPnP = true
    if holdOff == true then
        wantPnP = false
    else
        wantPnP = cfgOn
    end
    if wantPnP then
        local hasAny = (type(cfg) == "table" and type(cfg.selected) == "table" and next(cfg.selected) ~= nil)
        if not hasAny then
            wantPnP = false
        end
    end

    local now = os.clock()
    if Shark._pnpWant == wantPnP and (now - (tonumber(Shark._pnpAt) or 0)) < 0.75 then
        return
    end
    Shark._pnpWant = wantPnP
    Shark._pnpAt = now
    Shark._pnpHeld = holdOff == true

    local GG = (getgenv and getgenv()) or _G
    local mod = GG.PnPPet or GG.SwapSkillModule or GG.SwapSkill
        or _G.PnPPet or _G.SwapSkillModule or _G.SwapSkill
    if type(mod) ~= "table" then return end

    pcall(function()
        if wantPnP then
            if type(mod.SyncFromState) == "function" then
                mod.SyncFromState()
            end
            if type(mod.SetMode) == "function" and type(cfg) == "table" then
                mod.SetMode(cfg.mode or "A")
            end
            if type(mod.Start) == "function" then
                mod.Start(reason or "shark_pnp_on")
            end
        else
            if type(mod.Stop) == "function" then
                mod.Stop(reason or "shark_pnp_off")
            end
        end
    end)
end

function Shark.eval()
    local out = {
        phase = "idle",
        text = "Shark: —",
        donorCountText = "Donor: —",
        sharkUUID = nil,
        mimicUUID = nil,
        donorUUID = nil,
        biteArr = {},
        biteSet = {},
        youngArr = {},
        donorSet = {},
        donorArr = {},
        farmSet = {},
        farmArr = {},
        donorReadyN = 0,
        donorYoungN = 0,
    }

    local function finish(phase, text)
        out.phase = phase
        out.text = text
        return out
    end

    if not _isSharkListMode() then
        return finish("idle", "Shark: —")
    end
    if not _stageModeHasA() then
        return finish(
            "idle",
            "Shark: no Stage A (loop mode " .. tostring(_getStageMode()) .. ")"
        )
    end
    Shark.SB.hookVfx()

    local mutSel = rawget(G, "GBXP_MUT_SELECTED") or GBXP_MUT_SELECTED
    if type(mutSel) ~= "table" or next(mutSel) == nil then
        return finish("no mut", "Shark: pick mutation")
    end

    local bag = __getStoreBag and __getStoreBag() or nil
    if type(bag) ~= "table" then
        return finish("idle", "Shark: —")
    end

    local function isFav(rec)
        if type(rec) ~= "table" then return false end
        local PD = rec.PetData or rec.Data or {}
        if type(PD.IsFavorite) == "boolean" then return PD.IsFavorite == true end
        if type(rec.IsFavorite) == "boolean" then return rec.IsFavorite == true end
        return false
    end
    local function hasMuts(muts)
        return type(muts) == "table" and #muts > 0
    end
    local function mutPicked(mutName)
        if type(mutSel) ~= "table" or not mutName then return false end
        local n = tostring(mutName)
        if n == "" then return false end
        if mutSel[n] == true then return true end
        local low = n:lower()
        for k, v in pairs(mutSel) do
            if v == true and tostring(k):lower() == low then
                return true
            end
        end
        return false
    end
    local function mutMatch(mutList)
        if type(mutList) ~= "table" then return false end
        for _, m in ipairs(mutList) do
            if mutPicked(m) then return true end
        end
        return false
    end

    local donorTypeSet = Shark.readTypeSet(G.NMLVL_SHARK_DONOR_TEAM or _G.NMLVL_SHARK_DONOR_TEAM or {})
    local gbxpSet = (type(selected) == "table" and type(selected.gbxp) == "table") and selected.gbxp or {}
    local boostSet = (type(selected) == "table" and type(selected.boost) == "table") and selected.boost or {}
    local eps = EPS or 1e-6
    local donorAge = Shark.DONOR_AGE

    local hasDonorPick = false
    for _, on in pairs(donorTypeSet) do
        if on == true then
            hasDonorPick = true
            break
        end
    end
    local hasGbxpPick = false
    for _, on in pairs(gbxpSet) do
        if on == true or on == 1 or on == "true" then
            hasGbxpPick = true
            break
        end
    end

    if not hasDonorPick then
        out.donorCountText = "Donor: pilih type"
        return finish("pick donor", "Shark: pick donor type")
    end

    local sharkBest, sharkScore = nil, -1
    local mimicBest, mimicScore = nil, -1
    local readyDonors = {}
    local youngArr = {}
    local favDonors = 0
    local typeHits = 0
    local receiverCands = {}

    for rawUUID, rec in pairs(bag) do
        if type(rec) == "table" then
            local core, br = __normUUID(rawUUID)
            local uuid = br or core or tostring(rawUUID)
            local pt = rec.PetType
            local age = tonumber(_pickLevel(rec)) or tonumber(getPetAge and getPetAge(uuid)) or 0
            local fav = isFav(rec)
            local muts = __mutation_names_from_record(rec) or {}
            local match = mutMatch(muts)
            local isShark = Shark.typeIsShark(pt)
            local isMimic = Shark.typeIsMimic(pt)
            local isDonorType = Shark.isTypePicked(pt, donorTypeSet)
            local edible = (not isShark) and (age + eps) >= donorAge and hasMuts(muts)

            if isShark then
                local score = age
                if fav then score = score + 1000 end
                if Shark.hasUUID(boostSet, uuid) then score = score + 500 end
                if score > sharkScore then
                    sharkScore = score
                    sharkBest = uuid
                end
            elseif isMimic then
                if Shark.hasUUID(boostSet, uuid) then
                    local score = age
                    if fav then score = score + 1000 end
                    score = score + 500
                    if score > mimicScore then
                        mimicScore = score
                        mimicBest = uuid
                    end
                end
            end

            if Shark.hasUUID(gbxpSet, uuid) and (not isShark) and (not isMimic) and (not match) then
                receiverCands[#receiverCands + 1] = { uuid = uuid, age = age, fav = fav }
            end

            if isDonorType and (not isShark) then
                typeHits += 1
                if match then
                    if fav then
                        favDonors += 1
                    elseif (age + eps) >= donorAge then
                        readyDonors[#readyDonors + 1] = { uuid = uuid, age = age, pt = pt }
                    else
                        youngArr[#youngArr + 1] = { uuid = uuid, age = age, pt = pt }
                    end
                end
            end
        end
    end

    out.donorReadyN = #readyDonors
    out.donorYoungN = #youngArr
    out.donorCountText = ("Donor: ready %d · leveling %d · fav skip %d"):format(
        #readyDonors,
        #youngArr,
        favDonors
    )
    out.youngArr = youngArr

    local donorSet, donorArr, farmSet, farmArr = {}, {}, {}, {}
    table.sort(youngArr, function(a, b)
        return (tonumber(a.age) or 0) > (tonumber(b.age) or 0)
    end)
    local ownerGuess = Shark.SB.donorOwner({
        youngArr = youngArr,
        farmArr = (youngArr[1] and { youngArr[1].uuid }) or {},
    })
    local farmMax = Shark.ownerTabMax(ownerGuess)
    for i = 1, math.min(farmMax, #youngArr) do
        local u = youngArr[i].uuid
        farmArr[#farmArr + 1] = u
        Shark.markUUID(farmSet, u)
    end
    if youngArr[1] then
        local u = youngArr[1].uuid
        donorArr[1] = u
        Shark.markUUID(donorSet, u)
        out.donorUUID = u
    end
    out.donorSet = donorSet
    out.donorArr = donorArr
    out.farmSet = farmSet
    out.farmArr = farmArr

    if not sharkBest then
        return finish("no shark", "Shark: no Shark pet")
    end

    if #readyDonors == 0 then
        if #youngArr > 0 then
            return finish("leveling donor", ("Shark: leveling donor (%d <100)"):format(#youngArr))
        end
        if favDonors > 0 then
            return finish("donor fav", ("Shark: donor fav, unfav dulu (%d)"):format(favDonors))
        end
        if typeHits <= 0 then
            return finish("no donor", "Shark: no donor type in bag")
        end
        return finish("no donor", "Shark: no donor unfav + mut")
    end

    if not hasGbxpPick then
        if #youngArr > 0 then
            return finish("leveling donor", ("Shark: leveling donor (%d <100)"):format(#youngArr))
        end
        return finish("pick receiver", "Shark: pick GBXP target")
    end

    if #receiverCands == 0 then
        if #youngArr > 0 then
            return finish("leveling donor", ("Shark: leveling donor (%d <100)"):format(#youngArr))
        end
        return finish("no receiver", "Shark: no GBXP target without selected mut")
    end

    if not mimicBest then
        return finish("no mimic", "Shark: no Mimic (Mutation team)")
    end

    table.sort(readyDonors, function(a, b)
        return (tonumber(a.age) or 0) > (tonumber(b.age) or 0)
    end)
    local donorUUID = readyDonors[1].uuid
    out.donorUUID = donorUUID
    out.sharkUUID = sharkBest
    out.mimicUUID = mimicBest

    table.sort(receiverCands, function(a, b)
        if (a.fav == true) ~= (b.fav == true) then
            return a.fav == true
        end
        return (tonumber(a.age) or 0) > (tonumber(b.age) or 0)
    end)
    local recvUUID = nil
    local donorCore = Shark.SB.uuidCore(donorUUID)
    for _, rec in ipairs(receiverCands) do
        if rec and rec.uuid and Shark.SB.uuidCore(rec.uuid) ~= donorCore then
            recvUUID = rec.uuid
            break
        end
    end
    if not recvUUID then
        if #youngArr > 0 then
            return finish("leveling donor", ("Shark: leveling donor (%d <100)"):format(#youngArr))
        end
        return finish("no receiver", "Shark: no GBXP target without selected mut")
    end

    local biteArr, biteSet = {}, {}
    local function pushBite(u)
        if not u then return end
        if Shark.hasUUID(biteSet, u) then return end
        if #biteArr >= Shark.BITE_TEAM_MAX then return end
        local core, br = __normUUID(u)
        local keyed = br or core or tostring(u)
        biteArr[#biteArr + 1] = keyed
        Shark.markUUID(biteSet, keyed)
    end

    local remain = Shark.SB.mimicryRemain(mimicBest)
    local nowClock = os.clock()
    local rt = Shark.SB.rt()
    Shark.SB.ensureCdConn()
    rt.mimicCore = Shark.SB.uuidCore(mimicBest)
    rt.mimic = mimicBest
    rt.shark = sharkBest
    rt.donor = donorUUID
    rt.recv = recvUUID
    Shark.SB.hookVfx()
    if running then
        Shark.SB.ensureHb()
        Shark.SB.lookMimicry()
        Shark.SB.lookFoodDone()
    end
    local mode = tostring(rt.mode or "wait")
    if mode ~= "food" then
        mode = "wait"
    end
    rt.mode = mode

    out.sharkUUID = sharkBest
    out.mimicUUID = mimicBest
    out.donorUUID = donorUUID
    out.recvUUID = recvUUID
    out.phase = "waiting bite"
    out.subPhase = mode

    if mode == "food" then
        pushBite(mimicBest)
        pushBite(donorUUID)
        pushBite(recvUUID)
        out.text = "Shark: hold target until Mimicry CD"
    else
        pushBite(sharkBest)
        pushBite(mimicBest)
        if remain == nil then
            out.text = "Shark: wait Mimicry (Shark + Mimic)"
        elseif remain > 0.05 then
            out.text = ("Shark: wait Mimicry %s | Shark + Mimic"):format(Shark.SB.fmtCd(remain))
        else
            local delay = Shark.SB.getUnequipSharkDelay()
            local since = tonumber(rt.readySince)
            local left = delay
            if since then
                left = math.max(0, delay - (nowClock - since))
            end
            out.text = ("Shark: wait Mimicry ready · unequip shark %.1fs"):format(left)
        end
    end
    out.biteArr = biteArr
    out.biteSet = biteSet
    return out
end

function Shark.publishStatus(snap)
    snap = (type(snap) == "table") and snap or Shark.eval()
    local text = tostring(snap.text or "Shark: —")
    G.__SHARK_STATUS_TEXT = text
    _G.__SHARK_STATUS_TEXT = text

    local countText = snap.donorCountText
    if type(countText) ~= "string" or countText == "" then
        countText = "Donor: —"
        if _isSharkListMode() then
            local ready = tonumber(snap.donorReadyN) or 0
            local young = tonumber(snap.donorYoungN) or 0
            if ready <= 0 and young <= 0 then
                countText = "Donor: 0"
            else
                countText = string.format("Donor: %d ready / %d leveling", ready, young)
            end
        end
    end
    G.__SHARK_DONOR_COUNT_TEXT = countText
    _G.__SHARK_DONOR_COUNT_TEXT = countText
    return snap
end

function M.GetSharkStatusText()
    local snap = Shark.publishStatus()
    return snap.text
end

function M.GetSharkDonorCountText()
    Shark.publishStatus()
    return _G.__SHARK_DONOR_COUNT_TEXT or "Donor: —"
end

local MUT_CHECK_CACHE = {} -- [uuid] = {ts=0, matched=false}
-- matched=true boleh cache lama (stabil); matched=false harus cepat refresh
-- supaya mutasi baru tidak tertahan ~10s (bug: boost off dulu, target finish belakangan)
local MUT_CACHE_TTL_HIT  = 10
local MUT_CACHE_TTL_MISS = 0.25

local function _setMutationSelectedCache(uuid, matched)
    if not uuid then return end
    MUT_CHECK_CACHE[uuid] = {
        ts = tick(),
        matched = matched == true,
    }
end

local function _isMutationSelectedCached(uuid, ttlHit, ttlMiss)
    ttlHit  = ttlHit  or MUT_CACHE_TTL_HIT
    ttlMiss = ttlMiss or MUT_CACHE_TTL_MISS
    local now = tick()
    local c = MUT_CHECK_CACHE[uuid]

    if c then
        local ttl = c.matched and ttlHit or ttlMiss
        if (now - c.ts) < ttl then
            return c.matched
        end
    end

    local matched = _isMutationSelected(uuid)
    _setMutationSelectedCache(uuid, matched)
    return matched
end

----------------------------------------------------------------
-- VENOM ONLY: Mimic + Scorpion support
----------------------------------------------------------------
local VENOM_ONLY_MUT_NAME = "Venom"

local function _isVenomOnlyEnabled()
    if not _isNormalListMode() then
        return false
    end
    local GG = (getgenv and getgenv()) or _G

    return rawget(GG, "boostVenomOnlyMimicScorpion") == true
        or rawget(_G, "boostVenomOnlyMimicScorpion") == true
        or (type(STATE) == "table" and STATE.boostVenomOnlyMimicScorpion == true)
end

local function _hasMutationName(uuid, wantedName)
    wantedName = tostring(wantedName or ""):lower()
    if wantedName == "" then return false end

    local muts = {}
    pcall(function()
        muts = _getMutationNamesForUUID(uuid) or {}
    end)

    for _, name in ipairs(muts) do
        if tostring(name):lower() == wantedName then
            return true
        end
    end

    return false
end

local function _hasVenom(uuid)
    return _hasMutationName(uuid, VENOM_ONLY_MUT_NAME)
end

local function _allTargetsMutMatch(targetList)
    if type(targetList) ~= "table" or #targetList == 0 then
        return false
    end

    for _, rec in ipairs(targetList) do
        local u = rec and rec.uuid
        if not u then return false end

        -- live check + sync cache biar rule-sweep / stage A konsisten di tick yang sama
        local matched = _isMutationSelected(u)
        _setMutationSelectedCache(u, matched)

        if not matched then
            return false
        end
    end
    return true
end


local function _getCutoffAge(tabKey)
    tabKey = tostring(tabKey or "gbxp")
    local v = TAB_AGE_UNEQUIP_MIN and TAB_AGE_UNEQUIP_MIN[tabKey]
    if type(v) == "number" and v > 0 then
        return v
    end
    return AGE_MAX_UNEQUIP_B
end

local function _getNoosAgeThreshold()
    local v = TAB_AGE_EQUIP_MIN and TAB_AGE_EQUIP_MIN.noos
    if type(v) == "number" then
        v = math.abs(v)
        if v > 0 then return v end
    end
    return 40
end

local function _getBAgeThreshold()
    local v = TAB_AGE_UNEQUIP_MIN and TAB_AGE_UNEQUIP_MIN.xp
    if type(v) == "number" and v > 0 then
        return v
    end
    return 40
end



local function _modeNeedsMutToFinish(mode)
    mode = tostring(mode or "auto"):upper()
    -- mode yang wajib mutasi cocok supaya FINISH
    return (mode == "AUTO" or mode == "A" or mode == "AD" or mode == "DA" or mode == "CDA" or mode == "CAD" or mode == "ACBD")
end

local function _passOneValue(v, rawMin, rawMax)
    if v == nil then
        return true
    end

    local min = tonumber(rawMin or 0) or 0
    local max = tonumber(rawMax or 0) or 0
    local ok  = true

    -- MIN
    if min ~= 0 then
        local limit = math.abs(min)
        if min > 0 then
            if v < (limit - EPS) then
                ok = false
            end
        else
            if v > (limit + EPS) then
                ok = false
            end
        end
    end

    -- MAX
    if ok and max ~= 0 then
        local limit = math.abs(max)
        if max > 0 then
            if v >= (limit - EPS) then
                ok = false
            end
        else
            if v <= (limit + EPS) then
                ok = false
            end
        end
    end

    return ok
end

local function _passTabRule(tabKey, age, w100)
    local ageEq = rawget(G, "TAB_AGE_EQUIP_MIN") or TAB_AGE_EQUIP_MIN
    local ageUn = rawget(G, "TAB_AGE_UNEQUIP_MIN") or TAB_AGE_UNEQUIP_MIN
    local kgEq  = rawget(G, "TAB_W_EQUIP_MIN") or TAB_W_EQUIP_MIN
    local kgUn  = rawget(G, "TAB_W_UNEQUIP_MAX") or TAB_W_UNEQUIP_MAX

    local aMin = ageEq and ageEq[tabKey]
    local aMax = ageUn and ageUn[tabKey]
    local wMin = kgEq and kgEq[tabKey]
    local wMax = kgUn and kgUn[tabKey]
    if tabKey == "boost" then
        -- machine/shark: Stage A hanya Age Req (field KG/Unequip Age di UI disembunyikan)
        aMin = _getBoostHandoffAge()
        if not _isNormalListMode() then
            aMax = 0
            wMin = 0
            wMax = 0
        end
    end

    if not _passOneValue(age,  aMin, aMax) then return false end
    if not _passOneValue(w100, wMin, wMax) then return false end

    return true
end

local function _getStagePriorityList(mode)
    mode = tostring(mode or "AUTO"):upper()

    if mode == "AUTO" then
        return { "A", "B", "C", "D" }

    elseif mode == "A" or mode == "B" or mode == "C"  or mode == "D"then
        return { mode }
    elseif mode == "BD" then
        return { "B", "D" }     
        
    elseif mode == "AD" then
        return { "B", "A", "D" }
        
    elseif mode == "DA" then
        return { "B", "D", "A" }

    elseif mode == "BC" then
        return { "B", "C" }

    elseif mode == "CB" then
        return { "C", "B" }
        
    elseif mode == "CBD" then
        return { "C", "B", "D" }

    elseif mode == "CD" or mode == "DC" then
        -- style kamu: D dulu, lalu C, lalu B
        return { "D", "C", "B" }

    elseif mode == "CDA" then
        return { "C", "B", "D" ,"A" }
    elseif mode == "CAD" then
        return { "C", "B", "A", "D" }
    elseif mode == "ACBD" then
        return { "A", "C", "B", "D" }
    end

    -- fallback
    return { "A", "B", "C", "D" }
end


local STAGE_TO_TAB = {
    A = "boost",
    B = "xp",
    C = "noos",
    D = "seratusage",
}

local DEFAULT_TAB_TARGET_MAX = 1

local function _getTargetEquipMaxTable()
    local t = rawget(G, "TAB_TARGET_EQUIP_MAX")
        or rawget(_G, "TAB_TARGET_EQUIP_MAX")
        or TAB_TARGET_EQUIP_MAX
    if type(t) == "table" then
        TAB_TARGET_EQUIP_MAX = t
        return t
    end
    return nil
end

local function _getGBXPMaxEquipForStage(stage)
    stage = tostring(stage or "")
    local tabKey = STAGE_TO_TAB[stage]
    local t = _getTargetEquipMaxTable()

    local v = tabKey and t and tonumber(t[tabKey])
    if v and v > 0 then
        return math.floor(v)
    end

    -- fallback aman kalau input tab kosong / belum kebaca
    return DEFAULT_TAB_TARGET_MAX
end

function M.CloseInactiveStageSessions(activeStageKeys, groups)
    activeStageKeys = type(activeStageKeys) == "table" and activeStageKeys or {}
    groups = type(groups) == "table" and groups or { A = {}, B = {}, C = {}, D = {} }

    local function coreOf(u)
        return tostring(u or ""):match("{?([0-9a-fA-F%-]+)}?") or tostring(u or "")
    end

    for key, sess in pairs(STAGE_SESS) do
        if type(sess) == "table" and not activeStageKeys[key] then
            local endRec = nil
            local sameStageRec = nil
            local sessCore = coreOf(sess.uuid)
            local sessStage = tostring(sess.stage or "")
            for _, s in ipairs({ "A", "B", "C", "D" }) do
                for _, rec in ipairs(groups[s] or {}) do
                    if rec and coreOf(rec.uuid) == sessCore then
                        endRec = rec
                        if tostring(rec.stage or s) == sessStage or s == sessStage then
                            sameStageRec = rec
                        end
                        break
                    end
                end
                if endRec then
                    break
                end
            end

            -- Masih antri di stage yang sama (cuma bukan slot equip sekarang).
            -- Jangan kirim finish, itu yang bikin webhook spam.
            if sameStageRec then
                continue
            end

            local now = _nowSec()
            local durLive = now - (sess.startedAt or now)
            if durLive < 3 and not endRec then
                STAGE_SESS[key] = nil
                continue
            end
            local dur = now - (sess.startedAt or now)
            local payload = {
                mode = sess.mode,
                priority = sess.priority,
                stage = sess.stage,
                role = sess.role,
                gbxpMaxEquip = _getGBXPMaxEquipForStage(sess.stage),

                startedAt = sess.startedAt,
                startedAtText = sess.startedAtText,
                endedAt = now,
                endedAtText = os.date("!%Y-%m-%d %H:%M:%S", math.floor(now)),
                durationSec = math.floor(dur),
                durationText = _fmtDuration(dur),

                reasonEnd = endRec
                    and ("stage_changed_to_" .. tostring(endRec.stage))
                    or "stage_finished_or_removed",

                targetStart = sess.targetStart,
                targetEnd = _makeStageEndPetInfo(endRec, sess.uuid),

                team = _teamToArray(sess.team),
            }
            if tostring(sess.stage) == "D" then
                local bakuPack = _bakuWebhookPack(sess.baku or nil)
                if bakuPack then
                    payload.baku = bakuPack
                end
            end
            _sendWebhook("AUTOKG_STAGE_FINISH", payload)

            STAGE_SESS[key] = nil
        end
    end
end

local function _getGBXPMaxEquipForMode(mode)
    local maxV = DEFAULT_TAB_TARGET_MAX

    for _, stage in ipairs(_getStagePriorityList(mode)) do
        maxV = math.max(maxV, _getGBXPMaxEquipForStage(stage))
    end

    return maxV
end
local function _getStageForGBXP(uuid)
    local mode = _getStageMode()

    -- Fix4: age/w100 dihitung 1x; return stage, age, w100 (caller boleh abaikan extra)
    local age = getPetAge(uuid)
    if not age then return nil end
    age = math.floor(age + EPS)

    local w100 = getWeightAtLevel100(uuid)

    -- mut hanya relevan jika mode menyentuh stage A
    local needsMut = (mode == "A")
        or (mode == "AUTO")
        or (mode == "AD") or (mode == "DA")
        or (mode == "CAD") or (mode == "CDA") or (mode == "ACBD")
        or (string.find(mode, "A", 1, true) ~= nil)

    local mutMatch = false
    if needsMut then
        -- Stage A selesai = mutasi sudah ada di Select Mutation.
        -- Toggle Venom hanya ganti cara apply (Mimic+Scorpion), bukan syarat finish.
        mutMatch = _isMutationSelectedCached(uuid, 10)
    end

    ------------------------------------------------------------
    -- MODE A ONLY
    ------------------------------------------------------------
    if mode == "A" then
        if mutMatch then
            return nil, age, w100
        end
        if _passTabRule("boost", age, w100) then
            return "A", age, w100
        end
        return nil, age, w100
    end

    ------------------------------------------------------------
    -- MODE B ONLY (XP)
    ------------------------------------------------------------
    if mode == "B" then
        if _passTabRule("xp", age, w100) then
            return "B", age, w100
        end
        return nil, age, w100
    end

    ------------------------------------------------------------
    -- MODE C ONLY (NOOS)
    ------------------------------------------------------------
    if mode == "C" then
        if _passTabRule("noos", age, w100) then
            return "C", age, w100
        end
        return nil, age, w100
    end

    if mode == "D" then
        if _passTabRule("seratusage", age, w100) then
            return "D", age, w100
        end
        return nil, age, w100
    end

    if mode == "BD" then
        if _passTabRule("xp", age, w100) then
            return "B", age, w100
        end
        if _passTabRule("seratusage", age, w100) then
            return "D", age, w100
        end
        return nil, age, w100
    end

    -- AD/DA: kejar mutasi dulu. CAD/CDA JANGAN di sini —
    -- kalau ikut, pet yang seharusnya C/Elephant ketarik ke A.
    if mode == "AD" or mode == "DA" then
        local boostAge = _getBoostHandoffAge()

        if (not mutMatch)
            and age >= boostAge
            and _passTabRule("boost", age, w100)
        then
            return "A", age, w100
        end

        if mutMatch and _passTabRule("xp", age, w100) then
            return "B", age, w100
        end
    end

    ------------------------------------------------------------
    -- MULTI MODE (pakai priority) — termasuk AUTO
    ------------------------------------------------------------
    local priority = _getStagePriorityList(mode)

    for _, stage in ipairs(priority) do
        if stage == "A" and (not mutMatch) and _passTabRule("boost", age, w100) then
            return "A", age, w100
        end
        if stage == "B" and _passTabRule("xp", age, w100) then
            return "B", age, w100
        end
        if stage == "C" and _passTabRule("noos", age, w100) then
            return "C", age, w100
        end
        if stage == "D" and _passTabRule("seratusage", age, w100) then
            return "D", age, w100
        end
    end

    return nil, age, w100
end

function M.GetStageForGBXP(uuid)
    return _getStageForGBXP(uuid)
end

function M.IsGbxpAutoSelect()
    local st = rawget(G, "STATE") or rawget(_G, "STATE")
    if type(st) == "table" and st.gbxpAutoSelect == false then
        return false
    end
    if rawget(G, "gbxpAutoSelect") == false or rawget(_G, "gbxpAutoSelect") == false then
        return false
    end
    return true
end

function M.IsUnlimitedMaxPetSelected()
    local st = rawget(G, "STATE") or rawget(_G, "STATE")
    local n = tonumber(st and st.maxPetSelected) or 0
    return n <= 0
end

function M.GetMaxPetSelectedN()
    local st = rawget(G, "STATE") or rawget(_G, "STATE")
    local n = tonumber(st and st.maxPetSelected) or 0
    if n < 0 then n = 0 end
    if n > 500 then n = 500 end
    n = math.floor(n)
    if n == 0 then
        return 100000
    end
    return n
end

function M.ListGbxpPets()
    local plv = rawget(G, "PetListView") or rawget(_G, "PetListView")
    if type(plv) ~= "table" or type(plv.listPetsForTab) ~= "function" then
        return {}
    end
    local ok, res = pcall(function()
        return plv.listPetsForTab("gbxp")
    end)
    if (not ok or type(res) ~= "table") then
        ok, res = pcall(function()
            return plv:listPetsForTab("gbxp")
        end)
    end
    if ok and type(res) == "table" then
        return res
    end
    return {}
end

-- Pickup GBXP (ada di list, tidak selected) yang masih di garden → unequip.
-- Jangan sentuh: target GBXP, tim Mutation/XP/Elephant/500 Age, Shark bite, team before claim.
function M.UnequipUnselectedGbxpFromGarden(targetList)
    if G.__MACHINE_CLAIM_BUSY == true then
        return false
    end
    local mml = rawget(G, "MutationMachineLoop") or _G.MutationMachineLoop
    if mml and type(mml.IsClaimBusy) == "function" then
        local okBusy, busy = pcall(mml.IsClaimBusy)
        if okBusy and busy == true then
            return false
        end
    end

    local worldSet = _getEquippedSetFromWorld()
    if type(worldSet) ~= "table" or next(worldSet) == nil then
        return false
    end

    local keep = {}
    local function keepUuid(u)
        local c = tostring(u or ""):match("{?([0-9a-fA-F%-]+)}?") or tostring(u or "")
        if c and c ~= "" then
            keep[c] = true
        end
    end
    local function keepSet(t)
        if type(t) ~= "table" then
            return
        end
        for k, v in pairs(t) do
            if v == true or v == 1 or v == "true" then
                keepUuid(k)
            elseif type(k) == "number" then
                keepUuid(v)
            end
        end
    end
    local function keepArr(arr)
        if type(arr) ~= "table" then
            return
        end
        for _, u in ipairs(arr) do
            keepUuid(u)
        end
    end

    for _, rec in ipairs(targetList or {}) do
        if rec and rec.uuid then
            keepUuid(rec.uuid)
        end
    end
    -- Mutation / XP / Elephant / 500 Age + selected GBXP
    for _, key in ipairs({ "boost", "xp", "noos", "seratusage", "gbxp" }) do
        keepSet(selected and selected[key])
    end

    -- Shark bite/level HANYA Stage A. Jangan keep donor saat mode CB/CD.
    if _isSharkListMode()
        and _stageModeHasA()
        and tostring(CURRENT_STAGE or "") == "A"
    then
        local okS, snap = pcall(Shark.eval)
        if okS and type(snap) == "table" then
            keepUuid(snap.sharkUUID)
            keepUuid(snap.donorUUID)
            keepUuid(snap.mimicUUID)
            keepArr(snap.biteArr)
            keepArr(snap.farmArr)
            keepArr(snap.donorArr)
            keepSet(snap.biteSet)
            keepSet(snap.farmSet)
            keepSet(snap.donorSet)
        end
    end

    -- Pet team before mutation claim
    keepSet(rawget(G, "NMLVL_MACHINE_CLAIM_TEAM_BEFORE") or _G.NMLVL_MACHINE_CLAIM_TEAM_BEFORE)
    do
        local st = rawget(G, "STATE") or _G.STATE
        keepSet(st and st.machineClaimTeamBefore)
    end
    if mml and type(mml.GetClaimTeamBefore) == "function" then
        local okC, claimTeam = pcall(mml.GetClaimTeamBefore)
        if okC then
            keepSet(claimTeam)
        end
    end

    local function isEquippedCore(core)
        if not core or core == "" then
            return false
        end
        return worldSet[core] == true or worldSet["{" .. core .. "}"] == true
    end

    local n = 0
    for _, p in ipairs(M.ListGbxpPets()) do
        local uuid = p and p.uuid
        local core = tostring(uuid or ""):match("{?([0-9a-fA-F%-]+)}?") or tostring(uuid or "")
        if core ~= "" and not keep[core] then
            if not _isPetInMutationMachine(uuid) and not _isPetInMutationMachine("{" .. core .. "}") then
                if isEquippedCore(core) then
                    _safeUnequip("{" .. core .. "}", "gbxp pickup not selected", "gbxp-pickup")
                    n += 1
                    worldSet = _getEquippedSetFromWorld()
                    if n >= 6 then
                        break
                    end
                end
            end
        end
    end
    return n > 0
end

function M.FillGbxpSelectedFromList()
    selected = selected or {}
    selected.gbxp = selected.gbxp or {}
    local sel = selected.gbxp
    local maxN = M.GetMaxPetSelectedN()
    local skipStage = M.IsUnlimitedMaxPetSelected()
    local pets = M.ListGbxpPets()
    local cand = {}
    local machineUuid = nil
    for _, p in ipairs(pets) do
        local uuid = p and p.uuid
        if uuid then
            if _isPetInMutationMachine(uuid) then
                machineUuid = uuid
            end
            local stage = skipStage and true or _getStageForGBXP(uuid)
            if stage then
                cand[#cand + 1] = {
                    uuid = uuid,
                    kg = tonumber(p.kg) or 0,
                }
            end
        end
    end
    table.sort(cand, function(a, b)
        if a.kg ~= b.kg then
            return a.kg > b.kg
        end
        return tostring(a.uuid) < tostring(b.uuid)
    end)

    local picked = {}
    local seen = {}
    local function addUuid(uuid)
        if not uuid then return end
        local core = tostring(uuid):match("{?([0-9a-fA-F%-]+)}?") or tostring(uuid)
        if core == "" or seen[core] then return end
        if #picked >= maxN then return end
        seen[core] = true
        picked[#picked + 1] = "{" .. core .. "}"
    end
    if _isMachineListMode() and _stageModeHasA() then
        addUuid(machineUuid)
    end
    for _, c in ipairs(cand) do
        addUuid(c.uuid)
    end

    local keep = {}
    for _, u in ipairs(picked) do
        keep[u] = true
    end
    local changed = false
    for uuid, on in pairs(sel) do
        if on then
            local core = tostring(uuid):match("{?([0-9a-fA-F%-]+)}?") or tostring(uuid)
            local br = "{" .. core .. "}"
            if keep[br] ~= true then
                sel[uuid] = nil
                changed = true
            end
        end
    end
    for _, u in ipairs(picked) do
        if sel[u] ~= true then
            sel[u] = true
            changed = true
        end
    end
    return changed
end

-- Auto: ganti pet yang sudah selesai stage dengan pet berikutnya (atomic, jangan kosongin dulu).
function M.RefreshGbxpAutoSelected()
    if not M.IsGbxpAutoSelect() then
        return false
    end
    local fn = rawget(_G, "__AUTOKG_RECONCILE_GBXP") or rawget(G, "__AUTOKG_RECONCILE_GBXP")
    if type(fn) == "function" then
        local ok = pcall(fn)
        return ok == true
    end
    return M.FillGbxpSelectedFromList()
end

function M.GbxpSelectedNeedsRefresh()
    if not M.IsGbxpAutoSelect() then
        return false
    end
    local sel = selected and selected.gbxp
    if type(sel) ~= "table" then
        return true
    end
    local n = 0
    local hasFinished = false
    for uuid, on in pairs(sel) do
        if on then
            n += 1
            if not _isPetInMutationMachine(uuid) then
                local stage, age = _getStageForGBXP(uuid)
                local hadSession = false
                if age ~= nil and stage == nil then
                    local core = tostring(uuid):match("{?([0-9a-fA-F%-]+)}?") or tostring(uuid)
                    for _, sess in pairs(STAGE_SESS) do
                        if type(sess) == "table" then
                            local sc = tostring(sess.uuid or ""):match("{?([0-9a-fA-F%-]+)}?") or tostring(sess.uuid or "")
                            if sc == core then
                                hadSession = true
                                break
                            end
                        end
                    end
                end
                if hadSession then
                    hasFinished = true
                end
            end
        end
    end
    -- 0 = select semua tanpa cek stage, jangan drop pet selesai.
    if M.IsUnlimitedMaxPetSelected() then
        return n == 0
    end
    -- Jangan isi slot kosong tiap tick (n < maxN) — itu yang spam webhook finish.
    -- Refresh hanya kalau pet selected sudah selesai, atau tim GBXP kosong.
    return hasFinished or n == 0
end


local function _resolveFinishTabKey(uuid, mode)
    mode = tostring(mode or ""):upper()
    local stage = _getStageForGBXP(uuid)
    if stage and STAGE_TO_TAB[stage] then
        return STAGE_TO_TAB[stage], stage
    end
    if STAGE_TO_TAB[mode] then
        return STAGE_TO_TAB[mode], nil
    end
    return "gbxp", nil
end


local function _shouldUnequipGBXP(uuid)
    local mode = _getStageMode()
    local mutMatch = _isMutationSelectedCached(uuid, 10)

    -- MODE A: finish hanya kalau mutasi cocok
    if mode == "A" then
        return mutMatch
    end

    local age = getPetAge(uuid)
    if not age then return false end
    age = math.floor(age + EPS)

    local tabKey, stage = _resolveFinishTabKey(uuid, mode)
    local cutoffAge = _getCutoffAge(tabKey)

    -- Stage A (BOOST): finish = mutasi cocok
    if stage == "A" then
        return mutMatch
    end

    -- Tab XP / 500 Age: finish age-only (single & multi mode)
    if tabKey == "xp" or tabKey == "seratusage" then
        return age >= (cutoffAge - EPS)
    end

    -- Tab NOOS / GBXP fallback: age + w100 (+ mut untuk AUTO-style)
    local w100 = getWeightAtLevel100(uuid)
    if not w100 then return false end

    local requireMutToFinish = _modeNeedsMutToFinish(mode)
    local finishMutOK = (not requireMutToFinish) or mutMatch

    if (mode == "AD" or mode == "DA") and tabKey == "gbxp" then
        return age >= (cutoffAge - EPS) and mutMatch
    end

    return age >= (cutoffAge - EPS)
       and w100 >= (_getW100MaxEquip() - EPS)
       and finishMutOK
end


local function _findRecInGroups(groups, uuid)
    for _, s in ipairs({"A","B","C","D"}) do
        for _, rec in ipairs(groups[s] or {}) do
            if rec.uuid == uuid then
                return rec, s
            end
        end
    end
    return nil, nil
end

local FOCUS_DEBUG = false
local FOCUS_TRACE_EVERY_N = 10

local function df(...)
    if not FOCUS_DEBUG then return end
    local parts = { _ts(), "[GBXP/FOCUS]" }
    for i = 1, select("#", ...) do
        parts[#parts+1] = tostring(select(i, ...))
    end
    print(table.concat(parts, " "))
end

local FOCUS_MISSING_GRACE_SEC = 3

local function _stageInMode(stage, mode)
    for _, s in ipairs(_getStagePriorityList(mode)) do
        if s == stage then
            return true
        end
    end
    return false
end

local function _focusPetInfo(uuid, groups, mode)
    local rec, stage = _findRecInGroups(groups, uuid)
    local age  = getPetAge(uuid)
    local w100 = getWeightAtLevel100(uuid)

    return {
        uuid  = _shortUUID(uuid),
        stage = stage or "-",
        age   = age and math.floor(age + EPS) or "-",
        w100  = w100 and string.format("%.2f", w100) or "-",
        inMode = stage and _stageInMode(stage, mode) or false,
        rec = rec ~= nil,
    }
end

local function _sortGroupBestFirst(groups)
    local ws = _getEquippedSetFromWorld()

    for _, stage in ipairs({"A", "B", "C", "D"}) do
        table.sort(groups[stage], function(a, b)
            -- Semua stage:
            -- yang sudah equipped jangan kegeser oleh W100 lebih besar
            local ae = _isEquippedNow(a.uuid, ws)
            local be = _isEquippedNow(b.uuid, ws)

            if ae ~= be then
                return ae == true
            end

            -- kalau sama-sama equipped / sama-sama belum equipped,
            -- tetap pilih W100/KG terbesar
            local aw = tonumber(a.w100) or 0
            local bw = tonumber(b.w100) or 0

            if aw ~= bw then
                return aw > bw
            end

            return tostring(a.uuid) < tostring(b.uuid)
        end)
    end
end

local function _pickFocusTargets(groups, mode, sched)
    sched = sched or GBXP_FOCUS_SCHED
    mode = tostring(mode or "AUTO"):upper()

if sched.mode ~= mode then
    df("RESET mode changed", tostring(sched.mode), "=>", mode)
    sched.mode = mode
    sched.targets = {}
    sched.missingSince = {}
    sched.stage = nil
end

    sched.missingSince = sched.missingSince or {}

    local now = tick()
    local maxEquip = _getGBXPMaxEquipForMode(mode)

    local alive = {}
    local used = {}

    df("---- PICK START",
        "mode=", mode,
        "max=", maxEquip,
        "oldLock=", table.concat(sched.targets or {}, ",")
    )

    --------------------------------------------------
    -- 1) KEEP target lama
    --------------------------------------------------
    for _, uuid in ipairs(sched.targets or {}) do
        if #alive >= maxEquip then break end

        local rec, stage = _findRecInGroups(groups, uuid)
        local info = _focusPetInfo(uuid, groups, mode)

        if rec and _stageInMode(stage, mode) then
            sched.missingSince[uuid] = nil
            alive[#alive+1] = uuid
            used[uuid] = true

            df("KEEP",
                info.uuid,
                "stage=", info.stage,
                "age=", info.age,
                "w100=", info.w100,
                "reason=still_in_mode"
            )
        else
            sched.missingSince[uuid] = sched.missingSince[uuid] or now
            local missingFor = now - sched.missingSince[uuid]

            if missingFor < FOCUS_MISSING_GRACE_SEC then
                alive[#alive+1] = uuid
                used[uuid] = true

                df("KEEP-GRACE",
                    info.uuid,
                    "stage=", info.stage,
                    "age=", info.age,
                    "w100=", info.w100,
                    "missing=", string.format("%.1f", missingFor),
                    "reason=wait_transition"
                )
            else
                sched.missingSince[uuid] = nil

                df("DROP",
                    info.uuid,
                    "stage=", info.stage,
                    "age=", info.age,
                    "w100=", info.w100,
                    "missing=", string.format("%.1f", missingFor),
                    "reason=out_of_mode"
                )
            end
        end
    end

    --------------------------------------------------
    -- 2) Hitung barrier stage dari lock yang masih hidup
    --------------------------------------------------
    local stagePriority = _getStagePriorityList(mode)

    local stageIndexMap = {}
    for i, s in ipairs(stagePriority) do
        stageIndexMap[s] = i
    end

    local minIndex = math.huge

    for _, uuid in ipairs(alive) do
        local _, st = _findRecInGroups(groups, uuid)
        if st and stageIndexMap[st] then
            minIndex = math.min(minIndex, stageIndexMap[st])
        end
    end

    if minIndex == math.huge then
        minIndex = 1
    end

    df("BARRIER",
        "minIndex=", tostring(minIndex),
        "priority=", table.concat(stagePriority, ">")
    )

    --------------------------------------------------
    -- 3) Isi slot kosong dengan stage >= barrier
    --------------------------------------------------
    for _, s in ipairs(stagePriority) do
        if #alive >= maxEquip then break end

        local idx = stageIndexMap[s]

        if idx and idx >= minIndex then
            for _, rec in ipairs(groups[s] or {}) do
                if #alive >= maxEquip then break end

                local u = rec.uuid

                if u and not used[u] then
                    alive[#alive+1] = u
                    used[u] = true
                    sched.missingSince[u] = nil

                    df("ADD",
                        _shortUUID(u),
                        "stage=", tostring(s),
                        "age=", tostring(rec.age),
                        "w100=", string.format("%.2f", rec.w100 or 0),
                        "reason=fill_filtered_by_stage"
                    )
                end
            end
        else
            df("SKIP-STAGE",
                tostring(s),
                "idx=", tostring(idx),
                "minIndex=", tostring(minIndex),
                "reason=below_barrier"
            )
        end
    end

    --------------------------------------------------
    -- 4) Safety trim
    --------------------------------------------------
    if #alive > maxEquip then
        df("TRIM", "before=", #alive, "max=", maxEquip)

        while #alive > maxEquip do
            local removed = table.remove(alive)
            df("TRIM-REMOVE", _shortUUID(removed))
        end
    end

    sched.targets = alive

    df("FINAL LOCK", table.concat(alive, ","))

    return alive
end
