local PetCooldownsUpdated = waitChild(GameEventsFolder or ReplicatedStorage:FindFirstChild("GameEvents"), "PetCooldownsUpdated", 3)

local VENOM_STATE = {
    lastAction = 0,

    mimicReadyAfter = 0,
    mimicKey = "",

    firedUntil = 0,
    firedUUID = nil,
    busyUntil = 0,
    watchUUIDs = {},
    watchCores = {},
    animConns = {},
    boundKey = "",
}
G.__VENOM_MIMIC_RT = VENOM_STATE
_G.__VENOM_MIMIC_RT = VENOM_STATE

local VENOM_CFG = {
    checkDelay = 0,
    delayUnequipScorpion = 1,
    delayEquipTarget = 0,
    delayUnequipTarget = 13,
    delayEquipScorpion = 3,
}

local VENOM_READY_SOON_SEC = 0
local VENOM_ACTION_GAP = 0

local VENOM_CD_CACHE = VENOM_CD_CACHE or {}
local VENOM_CD_CONN = VENOM_CD_CONN or nil

function VENOM_STATE.clearWatch()
    VENOM_STATE.watchUUIDs = {}
    VENOM_STATE.watchCores = {}
    VENOM_STATE.firedUntil = 0
    VENOM_STATE.firedUUID = nil
    VENOM_STATE.boundKey = ""
    if type(VENOM_STATE.animConns) == "table" then
        for _, c in pairs(VENOM_STATE.animConns) do
            pcall(function()
                if c then
                    c:Disconnect()
                end
            end)
        end
    end
    VENOM_STATE.animConns = {}
end

function VENOM_STATE.setWatch(arr)
    VENOM_STATE.watchUUIDs = {}
    VENOM_STATE.watchCores = {}
    for _, u in ipairs(arr or {}) do
        local core = Shark.SB.uuidCore(u)
        if core ~= "" then
            VENOM_STATE.watchUUIDs[#VENOM_STATE.watchUUIDs + 1] = u
            VENOM_STATE.watchCores[core] = u
        end
    end
end

function VENOM_STATE.onCast(uuid)
    if not _isVenomOnlyEnabled() then
        return
    end
    if os.clock() < (tonumber(VENOM_STATE.busyUntil) or 0) then
        return
    end
    local core = Shark.SB.uuidCore(uuid)
    if core == "" or not VENOM_STATE.watchCores[core] then
        return
    end
    VENOM_STATE.firedUntil = os.clock() + 12
    VENOM_STATE.firedUUID = VENOM_STATE.watchCores[core] or uuid
    d(1, "[VENOM] Mimicry cast", tostring(core))
end

function VENOM_STATE.lookMimicry()
    if not _isVenomOnlyEnabled() then
        return
    end
    if os.clock() < (tonumber(VENOM_STATE.busyUntil) or 0) then
        return
    end
    if type(VENOM_STATE.watchUUIDs) ~= "table" or #VENOM_STATE.watchUUIDs == 0 then
        return
    end
    for _, uuid in ipairs(VENOM_STATE.watchUUIDs) do
        local cas = ""
        pcall(function()
            if ActivePetsService and type(ActivePetsService.GetServerState) == "function" then
                local st = ActivePetsService:GetServerState(LocalPlayer.Name, uuid)
                if type(st) == "table" then
                    cas = tostring(st.CustomAnimationState or "")
                end
            end
        end)
        if cas == "" then
            pcall(function()
                local pl = ActivePetsService and ActivePetsService.ClientPetState and ActivePetsService.ClientPetState[LocalPlayer.Name]
                local pet = pl and (pl[uuid] or pl["{" .. Shark.SB.uuidCore(uuid) .. "}"])
                if type(pet) == "table" then
                    cas = tostring(pet.LastAnimationState or "")
                    if cas == "" and pet.PetVFXHandler then
                        cas = tostring(pet.PetVFXHandler.CurrentAnimation or "")
                    end
                end
            end)
        end
        if tostring(cas):lower() == "mimicry" then
            VENOM_STATE.onCast(uuid)
            return
        end
    end
end

function VENOM_STATE.bindAnim()
    local key = table.concat(VENOM_STATE.watchUUIDs or {}, "|")
    if VENOM_STATE.boundKey == key and type(VENOM_STATE.animConns) == "table" then
        local alive = false
        for _, c in pairs(VENOM_STATE.animConns) do
            if c and c.Connected then
                alive = true
                break
            end
        end
        if alive then
            VENOM_STATE.lookMimicry()
            return
        end
    end
    if type(VENOM_STATE.animConns) == "table" then
        for _, c in pairs(VENOM_STATE.animConns) do
            pcall(function()
                if c then
                    c:Disconnect()
                end
            end)
        end
    end
    VENOM_STATE.animConns = {}
    VENOM_STATE.boundKey = key
    for _, uuid in ipairs(VENOM_STATE.watchUUIDs or {}) do
        local core = Shark.SB.uuidCore(uuid)
        local mdl = Shark.SB.findOwnMimicModel(core)
        local animator = mdl and mdl:FindFirstChildWhichIsA("Animator", true)
        if animator then
            VENOM_STATE.animConns[core] = animator.AnimationPlayed:Connect(function(track)
                local n = track and track.Name
                local an = track and track.Animation and track.Animation.Name
                if Shark.SB.isSkillAnim(n) or Shark.SB.isSkillAnim(an) then
                    VENOM_STATE.onCast(uuid)
                end
            end)
        end
    end
    VENOM_STATE.lookMimicry()
end

local function _venomNormUUID(u)
    if u == nil then return nil end
    local s = tostring(u)
    local core = s:match("{?([0-9a-fA-F%-]+)}?") or s
    if core == "" then return nil end
    return "{" .. core .. "}"
end

local function _venomShortUUID(u)
    u = _venomNormUUID(u)
    if not u then return "-" end
    return u:sub(1, 9)
end

local function _venomParseCooldownSeconds(v)
    if type(v) == "number" then
        return v
    end

    if type(v) ~= "string" then
        return 0
    end

    local s = v:lower()
        :gsub(",", ".")
        :gsub("%s+", " ")
        :gsub("^%s*(.-)%s*$", "%1")

    if s:find("ready", 1, true) then
        return 0
    end

    local m, sec = s:match("^(%d+)%s*:%s*(%d+)$")
    if m and sec then
        return (tonumber(m) or 0) * 60 + (tonumber(sec) or 0)
    end

    local mm = s:match("(%d+)%s*m")
    local ss = s:match("(%d+)%s*s")
    if mm or ss then
        return (tonumber(mm) or 0) * 60 + (tonumber(ss) or 0)
    end

    return tonumber(s:match("[-+]?%d+%.?%d*")) or 0
end

local function _venomCopyCooldownList(cds)
    local out = {}

    for _, cd in ipairs(cds or {}) do
        if type(cd) == "table" then
            local item = {}
            for k, v in pairs(cd) do
                item[k] = v
            end
            out[#out + 1] = item
        end
    end

    return out
end

local function _venomCacheCooldown(uuid, cds)
    uuid = _venomNormUUID(uuid)
    if not uuid then return end

    if type(cds) ~= "table" then
        VENOM_CD_CACHE[uuid] = nil
        return
    end

    VENOM_CD_CACHE[uuid] = {
        receivedAt = os.clock(),
        list = _venomCopyCooldownList(cds),
    }

    d(1, "[VENOM/CD EVENT]", _venomShortUUID(uuid), "entries=", tostring(#cds))
end

local function _venomStartCooldownCache()
    pcall(function()
        Shark.SB.ensureCdConn()
    end)
    if VENOM_CD_CONN then
        return
    end

    if not PetCooldownsUpdated then
        resolveGameModules()
        PetCooldownsUpdated = waitChild(GameEventsFolder or ReplicatedStorage:FindFirstChild("GameEvents"), "PetCooldownsUpdated", 2)
    end
    if not PetCooldownsUpdated then
        return
    end

    VENOM_CD_CONN = PetCooldownsUpdated.OnClientEvent:Connect(function(uuid, cds)
        _venomCacheCooldown(uuid, cds)
    end)

    d(1, "[VENOM/CD] cache listener started")
end

local function _venomStopCooldownCache()
    if VENOM_CD_CONN then
        VENOM_CD_CONN:Disconnect()
        VENOM_CD_CONN = nil
    end

    table.clear(VENOM_CD_CACHE)
    VENOM_STATE.clearWatch()
    d(1, "[VENOM/CD] cache listener stopped")
end

local function _venomFindMimicryEntry(cds)
    if type(cds) ~= "table" then
        return nil
    end

    for _, cd in ipairs(cds) do
        if type(cd) == "table" then
            local name = tostring(cd.Passive or cd.passive or cd.Skill or cd.skill or cd.Name or ""):lower()
            if name:find("mimicry", 1, true) then
                return cd
            end
        end
    end

    return nil
end

local function _getMimicCooldownLeft(uuid)
    uuid = _venomNormUUID(uuid)
    if not uuid then return nil end

    local remain
    pcall(function()
        remain = Shark.SB.mimicryRemain(uuid)
    end)
    if remain ~= nil then
        return remain
    end

    local pack = VENOM_CD_CACHE[uuid]
    if type(pack) ~= "table" or type(pack.list) ~= "table" then
        d(1, "[VENOM/CD] no cache", _venomShortUUID(uuid))
        return nil
    end

    local cdObj = _venomFindMimicryEntry(pack.list)
    if not cdObj then
        d(1, "[VENOM/CD] no Mimicry entry", _venomShortUUID(uuid))
        return nil
    end

    local t = tonumber(cdObj.Time or cdObj.time or cdObj.Remaining or cdObj.Remain or cdObj.Cooldown)
    if t == nil or t ~= t or t <= -1e9 or t >= 1e9 then
        d(1, "[VENOM/CD] no Mimicry time", _venomShortUUID(uuid))
        return nil
    end

    local elapsed = os.clock() - (pack.receivedAt or os.clock())
    return math.max(0, t - elapsed)
end

local function _isReadyCooldown(v)
    if v == nil then return false end
    v = _venomParseCooldownSeconds(v)
    return v <= VENOM_READY_SOON_SEC
end

local function _anyMimicReadyOrSoon(mimics)
    VENOM_STATE.lookMimicry()

    if os.clock() < (tonumber(VENOM_STATE.firedUntil) or 0) then
        local u = VENOM_STATE.firedUUID
        local cd = u and _getMimicCooldownLeft(u) or nil
        d(1, "[VENOM] Mimicry CAST", tostring(u), "cd=", tostring(cd))
        return true, u, cd
    end

    for _, uuid in ipairs(mimics or {}) do
        local cd = _getMimicCooldownLeft(uuid)
        d(1, "[VENOM] Mimicry CD", tostring(uuid), "=", tostring(cd))
    end

    return false, nil, nil
end

local function _petTypeOf(uuid)
    local info = _getPetInfo and _getPetInfo(uuid)
    return tostring(info and info.petType or ""):lower()
end

local function _isMimic(uuid)
    return _petTypeOf(uuid):find("mimic", 1, true) ~= nil
end

local function _isScorpion(uuid)
    return _petTypeOf(uuid):find("scorpion", 1, true) ~= nil
end

local function _findVenomBoostPets(boostArr)
    local mimics = {}
    local scorpion = nil

    for _, uuid in ipairs(boostArr or {}) do
        if _isMimic(uuid) then
            table.insert(mimics, uuid)
        elseif not scorpion and _isScorpion(uuid) then
            scorpion = uuid
        end
    end

    return mimics, scorpion
end

local function _venomEquipManyFast(arr, reason)
    if type(arr) ~= "table" or #arr == 0 then return end

    d(1, "[VENOM/INSTANT EQUIP]", reason or "", "#", tostring(#arr))

    for _, uuid in ipairs(arr) do
        if uuid then
            task.spawn(safeEquip, uuid)
        end
    end
    _invalidateEquippedCache()
end

local function _venomUnequipManyFast(arr, reason)
    for _, uuid in ipairs(arr or {}) do
        if uuid then
            task.spawn(function()
                pcall(function()
                    safeUnequip(uuid)
                end)
            end)
        end
    end
    if type(arr) == "table" and #arr > 0 then
        _invalidateEquippedCache()
    end
    d(1, "[VENOM/FAST UNEQUIP]", reason or "", "#", tostring(#(arr or {})))
end

local function _handleVenomStageA(activeStage, targetList, boostArr)
    if not _isVenomOnlyEnabled() then
        _venomStopCooldownCache()
        return false
    end

    if tostring(activeStage or "") ~= "A" then
        _venomStopCooldownCache()
        return false
    end

    if type(targetList) ~= "table" or #targetList == 0 then
        _venomStopCooldownCache()
        return false
    end

    _venomStartCooldownCache()

    local now = tick()
    if (now - (VENOM_STATE.lastAction or 0)) < VENOM_ACTION_GAP then
        return true
    end
    VENOM_STATE.lastAction = now

    local mimicArr, scorpionUUID = _findVenomBoostPets(boostArr)

    if #mimicArr == 0 or not scorpionUUID then
        VENOM_STATE.clearWatch()
        d(1, "[VENOM] Mimic / Scorpion belum dipilih di tab boost",
            "mimic#", tostring(#mimicArr),
            "scorpion=", tostring(scorpionUUID)
        )
        return false
    end

    ------------------------------------------------------------
    -- TARGETS SESUAI BOOST TARGET EQUIP MAX / STAGE A
    ------------------------------------------------------------
    local maxTarget = _getGBXPMaxEquipForStage("A")

    if type(maxTarget) ~= "number" or maxTarget <= 0 then
        maxTarget = 1
    end

    local targets = {}

    for _, rec in ipairs(targetList or {}) do
        local uuid = rec and rec.uuid

        if uuid and not _isMutationSelected(uuid) then
            targets[#targets + 1] = uuid

            if #targets >= maxTarget then
                break
            end
        end
    end

    ------------------------------------------------------------
    -- Kalau semua target sudah cocok Select Mutation
    ------------------------------------------------------------
    if #targets == 0 then
        VENOM_STATE.clearWatch()
        d(1, "[VENOM] no valid target, all already match selected mutation")

        LAST_TARGET_UUID = nil
        LAST_STAGE = nil
        __RESUME_REAPPLY = true

        return true
    end

    VENOM_STATE.setWatch(mimicArr)
    Shark.SB.ensureCdConn()
    Shark.SB.hookVfx()
    Shark.SB.ensureHb()
    VENOM_STATE.bindAnim()

    local ws = _getEquippedSetFromWorld()

    ------------------------------------------------------------
    -- Remove boost pet selain Mimic + Scorpion
    ------------------------------------------------------------
    local allowed = {}

    for _, u in ipairs(mimicArr) do
        allowed[u] = true
    end

    allowed[scorpionUUID] = true

    local removeOtherBoost = {}

    for _, u in ipairs(boostArr or {}) do
        if not allowed[u] and _isEquippedNow(u, ws) then
            removeOtherBoost[#removeOtherBoost + 1] = u
        end
    end

    if #removeOtherBoost > 0 then
        _venomUnequipManyFast(
            removeOtherBoost,
            "remove non Mimic/Scorpion boost pet"
        )
    end

    ------------------------------------------------------------
    -- Equip semua Mimic barengan
    ------------------------------------------------------------
    ws = _getEquippedSetFromWorld()

    local needEquipMimic = {}

    for _, mimicUUID in ipairs(mimicArr) do
        if not _isEquippedNow(mimicUUID, ws) then
            needEquipMimic[#needEquipMimic + 1] = mimicUUID
        end
    end

    local equippedNewMimic = (#needEquipMimic > 0)

    if equippedNewMimic then
        _venomEquipManyFast(
            needEquipMimic,
            "equip all Mimic same time"
        )
    end

    ------------------------------------------------------------
    -- Keep Scorpion ON saat tunggu Mimicry ready
    ------------------------------------------------------------
    ws = _getEquippedSetFromWorld()

    if not _isEquippedNow(scorpionUUID, ws) then
        _venomEquipManyFast(
            { scorpionUUID },
            "keep Scorpion while waiting Mimicry"
        )
    end

    ------------------------------------------------------------
    -- Tunggu cooldown event baru setelah mimic batch berubah
    ------------------------------------------------------------
    local mimicKey = table.concat(mimicArr, "|")

    if equippedNewMimic or VENOM_STATE.mimicKey ~= mimicKey then
        VENOM_STATE.mimicKey = mimicKey
        VENOM_STATE.mimicReadyAfter = tick() + 0.2

        d(1, "[VENOM] wait cooldown event after equip Mimic batch")
        task.wait(VENOM_CFG.checkDelay)
        return true
    end

    if tick() < (VENOM_STATE.mimicReadyAfter or 0) then
        d(1, "[VENOM] cooldown event not ready yet")
        task.wait(VENOM_CFG.checkDelay)
        return true
    end

    ------------------------------------------------------------
    -- Cek Mimic cooldown
    ------------------------------------------------------------
    ws = _getEquippedSetFromWorld()

    local mimicReady, readyMimic, cdLeft = _anyMimicReadyOrSoon(mimicArr)

    d(1, "[VENOM]",
        "ready=", tostring(mimicReady),
        "readyMimic=", tostring(readyMimic),
        "cdLeft=", tostring(cdLeft),
        "targets#", tostring(#targets),
        "maxTarget=", tostring(maxTarget),
        "scorpion=", tostring(scorpionUUID)
    )

    ------------------------------------------------------------
    -- Kalau Mimic ready: lepas Scorpion, pasang targets
    ------------------------------------------------------------
    if mimicReady then
        VENOM_STATE.busyUntil = os.clock() + 20
        VENOM_STATE.firedUntil = 0
        VENOM_STATE.firedUUID = nil
        d(1, "[VENOM] Mimic ready:", tostring(readyMimic), "cd=", tostring(cdLeft))

        task.wait(VENOM_CFG.delayUnequipScorpion)

        ws = _getEquippedSetFromWorld()

        if _isEquippedNow(scorpionUUID, ws) then
            _venomUnequipManyFast(
                { scorpionUUID },
                "Mimicry ready, remove Scorpion"
            )
        end

        task.wait(VENOM_CFG.delayEquipTarget)

        ------------------------------------------------------------
        -- Equip semua target sesuai maxTarget
        ------------------------------------------------------------
        ws = _getEquippedSetFromWorld()

        local needEquipTargets = {}

        for _, targetUUID in ipairs(targets) do
            if not _isEquippedNow(targetUUID, ws) then
                needEquipTargets[#needEquipTargets + 1] = targetUUID
            end
        end

        if #needEquipTargets > 0 then
            _venomEquipManyFast(
                needEquipTargets,
                "equip venom targets"
            )
        end

        ------------------------------------------------------------
        -- Window venom target
        ------------------------------------------------------------
        task.wait(VENOM_CFG.delayUnequipTarget)

        ------------------------------------------------------------
        -- Unequip semua target setelah window
        ------------------------------------------------------------
        ws = _getEquippedSetFromWorld()

        local needUnequipTarget = {}

        for _, targetUUID in ipairs(targets) do
            if _isEquippedNow(targetUUID, ws) then
                needUnequipTarget[#needUnequipTarget + 1] = targetUUID
            end
        end

        if #needUnequipTarget > 0 then
            _venomUnequipManyFast(
                needUnequipTarget,
                "remove venom targets after window"
            )
        end

        ------------------------------------------------------------
        -- Unequip semua Mimic barengan supaya CD reset/sync
        ------------------------------------------------------------
        task.wait(0.05)

        ws = _getEquippedSetFromWorld()

        local needUnequipMimic = {}

        for _, mimicUUID in ipairs(mimicArr) do
            if _isEquippedNow(mimicUUID, ws) then
                needUnequipMimic[#needUnequipMimic + 1] = mimicUUID
            end
        end

        if #needUnequipMimic > 0 then
            _venomUnequipManyFast(
                needUnequipMimic,
                "reset all Mimic cooldown same time"
            )
        end

        VENOM_STATE.mimicKey = ""
        VENOM_STATE.mimicReadyAfter = 0

        ------------------------------------------------------------
        -- Pasang Scorpion lagi setelah reset mimic
        ------------------------------------------------------------
        task.wait(VENOM_CFG.delayEquipScorpion)

        ws = _getEquippedSetFromWorld()

        if not _isEquippedNow(scorpionUUID, ws) then
            _venomEquipManyFast(
                { scorpionUUID },
                "equip Scorpion again after Mimic reset"
            )
        end
    else
        ------------------------------------------------------------
        -- Mimic belum ready: pastikan semua target OFF, Scorpion ON
        ------------------------------------------------------------
        ws = _getEquippedSetFromWorld()

        local needOffTarget = {}

        for _, targetUUID in ipairs(targets) do
            if _isEquippedNow(targetUUID, ws) then
                needOffTarget[#needOffTarget + 1] = targetUUID
            end
        end

        if #needOffTarget > 0 then
            _venomUnequipManyFast(
                needOffTarget,
                "targets off while waiting Mimicry"
            )
        end

        ws = _getEquippedSetFromWorld()

        if not _isEquippedNow(scorpionUUID, ws) then
            _venomEquipManyFast(
                { scorpionUUID },
                "keep Scorpion while waiting Mimicry"
            )
        end

        task.wait(VENOM_CFG.checkDelay)
    end

    return true
end

local function mainLoop(token)
    LAST_STAGE = LAST_STAGE or nil
    __NO_TARGET_HANDLED = __NO_TARGET_HANDLED or false

    while true do
        resolveGameModules()
        if G[LOOP_TOKEN_ATTR] ~= token then
            return
        end

        local loopWait = 0.10

        ------------------------------------------------------------
        -- START / STOP EDGE
        ------------------------------------------------------------
        if running and (not __prevRunning) then
            __onStart()
            LAST_STAGE = nil
        elseif (not running) and __prevRunning then
            __onStop()
            LAST_STAGE = nil
        end
        __prevRunning = running

        if running then
            __loopCounter += 1
            -- Fix1: 1x fetch bag + index UUID untuk seluruh tick (200+ pet aman)
            _tickCacheBegin()

            do
                local mml = rawget(G, "MutationMachineLoop") or _G.MutationMachineLoop
                if mml and type(mml.IsMachineListMode) == "function" and mml.IsMachineListMode() then
                    if type(mml.SyncMutSelected) == "function" then
                        pcall(function() mml.SyncMutSelected() end)
                    end
                elseif _isSharkListMode() then
                    SyncMutSelectedFromBoostBucket()
                end
            end

            GBXP_LOCAL.equipModeByUUID = GBXP_LOCAL.equipModeByUUID or {}

            -- selected live dari UI (getgenv), jangan pakai salinan lama
            do
                local liveSel = rawget(G, "selected") or rawget(_G, "selected")
                if type(liveSel) == "table" then
                    selected = liveSel
                end
            end
            selected = selected or {}
            selected.boost      = selected.boost      or {}
            selected.xp         = selected.xp         or {}
            selected.noos       = selected.noos       or {}
            selected.gbxp       = selected.gbxp       or {}
            selected.seratusage = selected.seratusage or {}
            G.selected = selected
            _G.selected = selected

            local boostArr = setToArray(selected.boost)
            local xpArr    = setToArray(selected.xp)
            local noosArr  = setToArray(selected.noos)
            local gbxpArr  = setToArray(selected.gbxp)
            local ageArr   = setToArray(selected.seratusage)
            loopWait = _loopWaitForCount(#gbxpArr)

            -- unselect di UI → unequip tick ini (tanpa Stop/Start)
            do
                local function coreOf(u)
                    return tostring(u or ""):match("{?([0-9a-fA-F%-]+)}?") or tostring(u or "")
                end
                local function toCoreSet(arr)
                    local s = {}
                    for _, u in ipairs(arr or {}) do
                        local c = coreOf(u)
                        if c ~= "" then s[c] = true end
                    end
                    return s
                end
                local cur = {
                    boost = toCoreSet(boostArr),
                    xp = toCoreSet(xpArr),
                    noos = toCoreSet(noosArr),
                    gbxp = toCoreSet(gbxpArr),
                    seratusage = toCoreSet(ageArr),
                }
                local prev = _SEL_PREV
                local changed = false
                local wsLive = nil
                for _, key in ipairs({ "boost", "xp", "noos", "gbxp", "seratusage" }) do
                    local nows = cur[key]
                    local old = prev[key] or {}
                    for c, _ in pairs(old) do
                        if nows[c] ~= true then
                            changed = true
                            if wsLive == nil then
                                wsLive = _getEquippedSetFromWorld()
                            end
                            local br = "{" .. c .. "}"
                            if not _isPetInMutationMachine(br) and not _isPetInMutationMachine(c) then
                                if _isEquippedNow(br, wsLive) or _isEquippedNow(c, wsLive) then
                                    _safeUnequip(br, "unselected " .. key, "sel-live")
                                    wsLive = _getEquippedSetFromWorld()
                                end
                            end
                            if GBXP_LOCAL.equipModeByUUID then
                                GBXP_LOCAL.equipModeByUUID[br] = nil
                                GBXP_LOCAL.equipModeByUUID[c] = nil
                            end
                        end
                    end
                    for c, _ in pairs(nows) do
                        if old[c] ~= true then
                            changed = true
                        end
                    end
                end
                if changed then
                    __RESUME_REAPPLY = true
                    LAST_TARGET_UUID = nil
                    LAST_MODE = nil
                end
                _SEL_PREV = cur
            end

            if __loopCounter % TRACE_EVERY_N == 1 then
                d(1, "tick", __loopCounter,
                    "| gbxp#", #gbxpArr,
                    "| boost#", #boostArr,
                    "xp#", #xpArr,
                    "noos#", #noosArr,
                    "age#", #ageArr
                )
            end

            --------------------------------------------------------
            -- 0) RULE SWEEP: FINISH / MISSING
            --------------------------------------------------------
            do
                local mode = _getStageMode()
                local worldSet = _getEquippedSetFromWorld()
                local didUnequip = false
                local needsMutMode = (mode == "A")
                    or (mode == "AUTO")
                    or (mode == "AD") or (mode == "DA")
                    or (mode == "CAD") or (mode == "CDA") or (mode == "ACBD")
                    or (string.find(mode, "A", 1, true) ~= nil)

                for _, uuid in ipairs(gbxpArr) do
                    if _isEquippedNow(uuid, worldSet) then
                        -- Sync mut LIVE dulu untuk pet yang equipped.
                        -- Tanpa ini, cache miss lama membuat boost-off (live)
                        -- lebih dulu dari target FINISH (cached) → delay perpindahan.
                        if needsMutMode then
                            _setMutationSelectedCache(uuid, _isMutationSelected(uuid))
                        end

                        local exists = true

                        if _getPetRecord then
                            local ok, rec = pcall(_getPetRecord, uuid)
                            exists = ok and rec ~= nil
                        elseif hasPetInStore then
                            local ok, res = pcall(hasPetInStore, uuid)
                            if ok then exists = res == true end
                        end

                        if not exists then
                            _safeUnequip(uuid, "pet missing from store", "rule0-missing")
                            didUnequip = true

                        elseif _shouldUnequipGBXP(uuid) then
                            local reason
                            if mode == "A" then
                                reason = "rule-sweep FINISH mutation matched"
                            else
                                local petTab, petStage = _resolveFinishTabKey(uuid, mode)
                                local petCutoff = _getCutoffAge(petTab)
                                reason = string.format(
                                    "rule-sweep FINISH stage=%s tab=%s age>=%s",
                                    tostring(petStage or "-"),
                                    tostring(petTab or "gbxp"),
                                    tostring(petCutoff)
                                )
                            end

                            _safeUnequip(uuid, reason, "rule0")
                            didUnequip = true
                        end
                    end
                end

                if didUnequip then
                    LAST_TARGET_UUID = nil
                    LAST_MODE = nil
                    LAST_STAGE = nil
                    __RESUME_REAPPLY = true
                end
            end

            --------------------------------------------------------
            -- 1) BUILD GROUPS A/B/C/D
            --------------------------------------------------------
            local groups = { A = {}, B = {}, C = {}, D = {} }
            local skipped = 0
            local mode = _getStageMode()
            local worldSetSkip = nil -- lazy: hanya kalau normal+machine guard
            local anyGbxpInMachine = false

            for _, uuid in ipairs(gbxpArr) do
                local exists = true

                if _getPetRecord then
                    local ok, rec = pcall(_getPetRecord, uuid)
                    exists = ok and rec ~= nil
                elseif hasPetInStore then
                    local ok, res = pcall(hasPetInStore, uuid)
                    if ok then exists = res == true end
                end

                local inMachineNow = _isPetInMutationMachine(uuid)
                if inMachineNow then
                    anyGbxpInMachine = true
                end

                if not exists then
                    skipped += 1
                else
                    local alreadyDoneA = false

                    if mode == "A" then
                        alreadyDoneA = _isMutationSelectedCached(uuid, 10)
                    end

                    if not alreadyDoneA then
                        -- Fix4: stage+age+w100 dari 1 call
                        local stage, age, w100 = _getStageForGBXP(uuid)

                        if stage then
                            -- Pet di mesin hanya dikeluarkan dari target Stage A.
                            -- Stage B/C/D tetap masuk group supaya mode lain tidak stop.
                            local holdForMachine = inMachineNow
                                and stage == "A"
                                and _isMachineListMode()
                            if holdForMachine then
                                skipped += 1
                                if worldSetSkip == nil then
                                    worldSetSkip = _getEquippedSetFromWorld()
                                end
                                if _isEquippedNow(uuid, worldSetSkip) then
                                    _safeUnequip(uuid, "gbxp-guard (in mutation machine)", "gbxp-machine")
                                    worldSetSkip = _getEquippedSetFromWorld()
                                end
                            elseif age and w100 then
                                groups[stage][#groups[stage] + 1] = {
                                    uuid = uuid,
                                    age = age,
                                    w100 = w100,
                                    stage = stage,
                                }
                            else
                                skipped += 1
                            end
                        end
                    end
                end
            end

            _sortGroupBestFirst(groups)

            d(1, "GROUPS",
                "A=", #groups.A,
                "B=", #groups.B,
                "C=", #groups.C,
                "D=", #groups.D,
                "skipped=", skipped
            )

            --------------------------------------------------------
            -- 2) PICK ACTIVE STAGE + TARGET LIST
            --------------------------------------------------------
            local activeStage = nil
            local targetList = {}

            do
                local forced = _getStageMode()
                local prioMode = _getPriorityMode()

                if prioMode == "FOCUS" then
                    local focusUUIDs = _pickFocusTargets(groups, forced, GBXP_FOCUS_SCHED)
                    local focusSet = {}

                    for _, u in ipairs(focusUUIDs) do
                        focusSet[u] = true
                    end

                    if GBXP_FOCUS_SCHED.stage then
                        for _, rec in ipairs(groups[GBXP_FOCUS_SCHED.stage] or {}) do
                            if focusSet[rec.uuid] then
                                activeStage = GBXP_FOCUS_SCHED.stage
                                break
                            end
                        end
                    end

                    if not activeStage then
                        GBXP_FOCUS_SCHED.stage = nil

                        for _, s in ipairs(_getStagePriorityList(forced)) do
                            for _, rec in ipairs(groups[s] or {}) do
                                if focusSet[rec.uuid] then
                                    activeStage = s
                                    GBXP_FOCUS_SCHED.stage = s
                                    break
                                end
                            end
                            if activeStage then break end
                        end
                    end

                    if activeStage then
                        local maxEquip = _getGBXPMaxEquipForStage(activeStage)

                        for _, rec in ipairs(groups[activeStage] or {}) do
                            if focusSet[rec.uuid] then
                                targetList[#targetList + 1] = rec
                                if #targetList >= maxEquip then
                                    break
                                end
                            end
                        end
                    end

                    GBXP_STAGE_SCHED.stage = nil
                    GBXP_STAGE_SCHED.mode = nil
                else
                    if GBXP_STAGE_SCHED.mode ~= forced then
                        GBXP_STAGE_SCHED.mode = forced
                        GBXP_STAGE_SCHED.stage = nil
                    end

                    -- Global: kunci stage sampai group itu kosong.
                    -- Pet yang sudah lulus (B→C) nunggu, jangan nyerobot
                    -- selama masih ada pet di stage yang sedang diratakan.
                    if GBXP_STAGE_SCHED.stage and #(groups[GBXP_STAGE_SCHED.stage] or {}) > 0 then
                        activeStage = GBXP_STAGE_SCHED.stage
                    else
                        GBXP_STAGE_SCHED.stage = nil

                        for _, s in ipairs(_getStagePriorityList(forced)) do
                            if #(groups[s] or {}) > 0 then
                                activeStage = s
                                GBXP_STAGE_SCHED.stage = s
                                break
                            end
                        end
                    end

                    if activeStage then
                        local maxEquip = _getGBXPMaxEquipForStage(activeStage)

                        for _, rec in ipairs(groups[activeStage] or {}) do
                            targetList[#targetList + 1] = rec
                            if #targetList >= maxEquip then
                                break
                            end
                        end
                    end

                    -- Pet A terakhir ada di mesin: group A kosong, Global lompat B/D.
                    -- Selesaikan mesin dulu (tim mutasi Stage A), baru stage berikutnya.
                    if _isMachineListMode()
                        and _stageModeHasA()
                        and anyGbxpInMachine
                        and #(groups.A or {}) == 0
                    then
                        activeStage = "A"
                        GBXP_STAGE_SCHED.stage = "A"
                        targetList = {}
                    end

                    GBXP_FOCUS_SCHED.targets = {}
                    GBXP_FOCUS_SCHED.mode = nil
                    GBXP_FOCUS_SCHED.stage = nil
                end

                CURRENT_STAGE = activeStage
            end

            _syncShardCleanerRun(activeStage)

            --------------------------------------------------------
            -- BAKU (500 Age list mode): combo dulu, leveling hanya Stage D
            --------------------------------------------------------
            local bakuHoldLeveling = false
            local bakuProtect = {}
            do
                local stB = rawget(_G, "STATE") or rawget(G, "STATE")
                if type(stB) == "table" and tostring(stB.ageListMode or "") == "baku" then
                    local baku = rawget(G, "BakuCombo") or _G.BakuCombo
                    if type(baku) == "table" and type(baku.Tick) == "function" then
                        local okB, resB = pcall(baku.Tick)
                        if okB and type(resB) == "table" then
                            bakuHoldLeveling = resB.holdLeveling == true
                            if type(resB.protect) == "table" then
                                bakuProtect = resB.protect
                            end
                            if resB.comboJustDone == true or type(resB.comboSnap) == "table" then
                                local snap = resB.comboSnap or rawget(G, "BAKU_LAST_COMBO")
                                for _, sess in pairs(STAGE_SESS) do
                                    if sess and tostring(sess.stage) == "D" then
                                        sess.baku = snap
                                    end
                                end
                            end
                        end
                    end
                end
            end
            G.BAKU_HOLD_LEVELING = bakuHoldLeveling == true
            _G.BAKU_HOLD_LEVELING = G.BAKU_HOLD_LEVELING
            G.BAKU_PROTECT = bakuProtect
            _G.BAKU_PROTECT = bakuProtect

            if bakuHoldLeveling then
                local function bakuCore(u)
                    return tostring(u or ""):match("{?([0-9a-fA-F%-]+)}?") or tostring(u or "")
                end
                local keep = {}
                for _, u in ipairs(bakuProtect or {}) do
                    local c = bakuCore(u)
                    if c ~= "" then
                        keep[c] = true
                    end
                end
                local function dropNotKept(arr)
                    local drop = {}
                    for _, u in ipairs(arr or {}) do
                        local c = bakuCore(u)
                        if c ~= "" and keep[c] ~= true then
                            drop[#drop + 1] = u
                        end
                    end
                    return drop
                end
                local wsHold = _getEquippedSetFromWorld()
                for _, u in ipairs(gbxpArr or {}) do
                    if keep[bakuCore(u)] ~= true and _isEquippedNow(u, wsHold) then
                        _safeUnequip(u, "gbxp-off (baku combo)", "baku-combo-gbxp")
                        wsHold = _getEquippedSetFromWorld()
                    end
                end
                _unequipMany(dropNotKept(xpArr), "XP OFF (baku combo)", "baku-xp")
                _unequipMany(dropNotKept(boostArr), "BOOST OFF (baku combo)", "baku-boost")
                _unequipMany(dropNotKept(noosArr), "NOOS OFF (baku combo)", "baku-noos")

                -- Combo masuk durasi Stage D: sesi webhook tetap jalan, finish hanya saat GBXP Age selesai.
                if activeStage == "D" then
                    local activeStageKeys = {}
                    for _, rec in ipairs(targetList or {}) do
                        if rec and rec.uuid and tostring(rec.stage) == "D" then
                            local key = _stageKey(rec.uuid, rec.stage)
                            activeStageKeys[key] = rec
                            if not STAGE_SESS[key] then
                                local now = _nowSec()
                                STAGE_SESS[key] = {
                                    uuid = tostring(rec.uuid),
                                    stage = "D",
                                    role = "seratusage",
                                    startedAt = now,
                                    startedAtText = os.date("!%Y-%m-%d %H:%M:%S", math.floor(now)),
                                    mode = _getStageMode(),
                                    priority = _getPriorityMode(),
                                    targetStart = _getPetInfo(rec.uuid),
                                    ageStart = rec.age,
                                    w100Start = _round2(rec.w100),
                                    team = {},
                                }
                            end
                        end
                    end
                    for _, sess in pairs(STAGE_SESS) do
                        if sess.role == "seratusage" then
                            _fillTeamSnapshot(sess, "seratusage", ageArr)
                        end
                    end
                    if next(activeStageKeys) then
                        M.CloseInactiveStageSessions(activeStageKeys, groups)
                    end
                end

                _tickCacheEnd()
                task.wait(loopWait)
                continue
            end
            
            --------------------------------------------------------
-- VENOM STAGE A HANDLER
--------------------------------------------------------
local venomHandled =
    _handleVenomStageA(
        activeStage,
        targetList,
        boostArr
    )

if venomHandled then
    _tickCacheEnd()
    task.wait(loopWait)
    continue
end

            --------------------------------------------------------
            -- MACHINE WAIT / CLAIM GATE
            --------------------------------------------------------
            local fullTargetList = targetList
            local onStageA = tostring(activeStage or "") == "A"
            -- Pet GBXP cuma yang di mesin: tidak masuk group, stage kosong.
            -- B/C/D yang masih punya target tidak ikut kondisi ini.
            local soloMachineHold = (not onStageA)
                and anyGbxpInMachine
                and _isMachineListMode()
                and _stageModeHasA()
                and (activeStage == nil or #targetList == 0)
                and #(groups.B or {}) == 0
                and #(groups.C or {}) == 0
                and #(groups.D or {}) == 0
            -- Tahan boost hanya saat Stage A + list machine. B/C/D tidak ikut stop.
            local machineWaitBoost = onStageA
                and _isMachineListMode()
                and _machineWaitBoostActive()
            if soloMachineHold then
                machineWaitBoost = true
            end
            local machineClaimBusy = false
            local machineClaimPhase = false
            do
                local mml0 = rawget(G, "MutationMachineLoop") or _G.MutationMachineLoop
                if mml0 and type(mml0.IsClaimBusy) == "function" then
                    machineClaimBusy = mml0.IsClaimBusy() == true
                end
                if (not machineClaimBusy) and G.__MACHINE_CLAIM_BUSY == true then
                    machineClaimBusy = true
                end
                local mApi0 = rawget(G, "MutationMachineApi") or _G.MutationMachineApi
                if mApi0 and type(mApi0.GetPhase) == "function" then
                    local okP, phase = pcall(function() return mApi0.GetPhase() end)
                    machineClaimPhase = okP and phase == "claim"
                end
            end
            if machineClaimBusy or machineClaimPhase then
                machineWaitBoost = false
            end

            local mmlGate = rawget(G, "MutationMachineLoop") or _G.MutationMachineLoop
            local inMachineListMode = mmlGate
                and type(mmlGate.IsMachineListMode) == "function"
                and mmlGate.IsMachineListMode()
            local blockForMachineClaim = (onStageA or soloMachineHold)
                and inMachineListMode
                and (machineClaimBusy or machineClaimPhase)

            if machineWaitBoost then
                -- machine running: fokus boost team, GBXP target ditahan
                local worldSet = _getEquippedSetFromWorld()
                for _, u in ipairs(gbxpArr) do
                    if _isEquippedNow(u, worldSet) then
                        _safeUnequip(u, "gbxp-off (machine wait boost)", "machine-wait-gbxp")
                    end
                end

                local boostOwned = boostArr
                local globalOwnedSet = {}
                for _, u in ipairs(boostOwned or {}) do
                    if u then globalOwnedSet[u] = true end
                end

                enforceTab(boostArr, boostOwned, globalOwnedSet, "boost", "BOOST ON (machine wait)", "BOOST OFF (machine wait)")
                enforceTab(xpArr, {}, globalOwnedSet, "xp", "", "XP OFF (machine wait)")
                enforceTab(noosArr, {}, globalOwnedSet, "noos", "", "NOOS OFF (machine wait)")
                enforceTab(ageArr, {}, globalOwnedSet, "seratusage", "", "AGE OFF (machine wait)")

                do
                    local mml = rawget(G, "MutationMachineLoop") or _G.MutationMachineLoop
                    if mml and type(mml.Tick) == "function" then
                        pcall(function()
                            mml.Tick({
                                targetList = fullTargetList,
                                groups = groups,
                                machineWaitBoost = true,
                            })
                        end)
                    end
                end

                _tickCacheEnd()
                task.wait(loopWait)
                continue
            end

            --------------------------------------------------------
            -- SHARK (Mimicry wait / solo / food + leveling donor)
            --------------------------------------------------------
            local sharkSnap = nil
            local sharkWaitBite = false
            local sharkLevelDonor = false
            local sharkMutOn = _isSharkListMode()
                and _stageModeHasA()
                and tostring(activeStage or "") == "A"
            if _isSharkListMode() then
                sharkSnap = Shark.publishStatus(Shark.eval())
                sharkWaitBite = sharkMutOn
                    and (sharkSnap.phase == "waiting bite")
                sharkLevelDonor = sharkMutOn
                    and (sharkSnap.phase == "leveling donor")
                Shark.syncPnP("tick", sharkWaitBite)
            elseif Shark._pnpHeld then
                Shark.syncPnP("tick", false)
            end

            -- Shark wait/level tidak equip GBXP. Cleaner hanya scan pet di garden,
            -- jadi GBXP salah mutasi harus di-equip dulu (scope = selected.gbxp).
            if _isSharkListMode()
                and _mutCleanEnabled()
                and _stageModeHasA()
                and tostring(activeStage or "") == "A"
            then
                local dirty = {}
                local maxE = _getGBXPMaxEquipForStage("A")
                if not maxE or maxE <= 0 then
                    maxE = 8
                end
                if maxE > 8 then
                    maxE = 8
                end
                for _, u in ipairs(gbxpArr) do
                    if _gbxpNeedsShardClean(u) then
                        dirty[#dirty + 1] = u
                        if #dirty >= maxE then
                            break
                        end
                    end
                end
                if #dirty > 0 then
                    sharkWaitBite = false
                    sharkLevelDonor = false
                    Shark.syncPnP("tick", false)
                    local dirtySet = {}
                    for _, u in ipairs(dirty) do
                        dirtySet[u] = true
                    end
                    pcall(function()
                        local w = rawget(G, "WorldShardCleaner") or rawget(_G, "WorldShardCleaner")
                        if w and type(w.setOnlyUUIDs) == "function" then
                            w:setOnlyUUIDs(dirtySet)
                        end
                    end)
                    Shark.syncGarden(dirty, "SHARD CLEAN GBXP")
                    Shark.markExclusive(dirty)
                    d(1, "SHARD CLEAN GBXP", #dirty)
                    _tickCacheEnd()
                    task.wait(loopWait)
                    continue
                end
            end

            if sharkWaitBite or sharkLevelDonor then
                _setShardCleanerRunning(false)
            end

            if sharkWaitBite then
                Shark.applyBiteNow(sharkSnap, gbxpArr, boostArr, xpArr, ageArr, noosArr)
                Shark.stripGardenIfSharkOut(sharkSnap and sharkSnap.biteSet)
                _tickCacheEnd()
                task.wait(loopWait)
                continue
            end

            if sharkLevelDonor then
                Shark.applyLevelDonorNow(sharkSnap, gbxpArr, boostArr, xpArr, ageArr, noosArr)
                _tickCacheEnd()
                task.wait(loopWait)
                continue
            end

            -- Mode CB/CD/B/... atau Stage A tapi bukan bite/level: donor/mimic/shark jangan nempel.
            Shark.stopExclusive(
                Shark.keepForStage(activeStage, targetList, boostArr, xpArr, noosArr, ageArr)
            )

            --------------------------------------------------------
            -- 3) NO TARGET CLEANUP
            --------------------------------------------------------
            local noTargetState = (activeStage == nil or #targetList == 0)

            if noTargetState then
                if not __NO_TARGET_HANDLED then
                    __NO_TARGET_HANDLED = true

                    local worldSet = _getEquippedSetFromWorld()
                    local modeNow = _getStageMode()

                    for _, u in ipairs(gbxpArr) do
                        if _isEquippedNow(u, worldSet) then
                            _safeUnequip(
                                u,
                                "no GBXP target left for mode " .. modeNow,
                                "gbxp-no-target"
                            )
                        end
                    end

                    local emptySet = {}

                    enforceTab(boostArr, {}, emptySet, "boost", "", "BOOST OFF no target")
                    enforceTab(xpArr, {}, emptySet, "xp", "", "XP OFF no target")
                    enforceTab(noosArr, {}, emptySet, "noos", "", "NOOS OFF no target")
                    enforceTab(ageArr, {}, emptySet, "seratusage", "", "AGE OFF no target")

                    LAST_TARGET_UUID = nil
                    LAST_MODE = nil
                    LAST_STAGE = nil
                    GBXP_LOCAL.equippedUUID = nil
                    GBXP_LOCAL.equipModeByUUID = {}
                end
                -- Pet selesai / tidak ada target: tetap kirim webhook finish, baru ganti selected.
                M.CloseInactiveStageSessions({}, groups)
                if M.GbxpSelectedNeedsRefresh() then
                    M.RefreshGbxpAutoSelected()
                end
                M.UnequipUnselectedGbxpFromGarden({})
            else
                __NO_TARGET_HANDLED = false

                ----------------------------------------------------
                -- 4) STAGE SESSION START
                ----------------------------------------------------
                local activeStageKeys = {}

                for _, rec in ipairs(targetList) do
                    if rec and rec.uuid and rec.stage then
                        local key = _stageKey(rec.uuid, rec.stage)
                        activeStageKeys[key] = rec

                        if not STAGE_SESS[key] then
                            local now = _nowSec()

                            STAGE_SESS[key] = {
                                uuid = tostring(rec.uuid),
                                stage = tostring(rec.stage),
                                role = _stageRole(rec.stage),

                                startedAt = now,
                                startedAtText = os.date("!%Y-%m-%d %H:%M:%S", math.floor(now)),

                                mode = _getStageMode(),
                                priority = _getPriorityMode(),

                                targetStart = _getPetInfo(rec.uuid),
                                ageStart = rec.age,
                                w100Start = _round2(rec.w100),

                                team = {},
                            }
                        end
                    end
                end

                for _, sess in pairs(STAGE_SESS) do
                    if sess.role == "boost" then
                        _fillTeamSnapshot(sess, "boost", boostArr)
                    elseif sess.role == "xp" then
                        _fillTeamSnapshot(sess, "xp", xpArr)
                    elseif sess.role == "noos" then
                        _fillTeamSnapshot(sess, "noos", noosArr)
                    elseif sess.role == "seratusage" then
                        _fillTeamSnapshot(sess, "seratusage", ageArr)
                    end
                end

                ----------------------------------------------------
                -- 5) STAGE SESSION FINISH
                ----------------------------------------------------
                M.CloseInactiveStageSessions(activeStageKeys, groups)
                if M.GbxpSelectedNeedsRefresh() then
                    M.RefreshGbxpAutoSelected()
                end

                ----------------------------------------------------
                -- 6) TARGET INFO
                ----------------------------------------------------
                local hasB = false
                local minAge = nil
                local targetSet = {}

                for _, rec in ipairs(targetList) do
                    targetSet[rec.uuid] = true

                    if (not minAge) or rec.age < minAge then
                        minAge = rec.age
                    end

                    if rec.w100 >= (_getW100MaxEquip() - EPS) then
                        hasB = true
                    end
                end

                local targetKey = _makeTargetKey(targetList)
                local weightMode = hasB and "B" or "A"

                local targetChanged = (targetKey ~= LAST_TARGET_UUID)
                local modeChanged = (weightMode ~= LAST_MODE)
                local stageChanged = (activeStage ~= LAST_STAGE)

                local forceApply =
                    targetChanged
                    or modeChanged
                    or stageChanged
                    or __RESUME_REAPPLY

                d(1,
                    "picked STAGE=", tostring(activeStage or "-"),
                    targetKey or "nil",
                    "count=", #targetList,
                    "minAge=", tostring(minAge or "-"),
                    "MODE=", _getStageMode(),
                    "force=", tostring(forceApply),
                    "stageChanged=", tostring(stageChanged)
                )


                ----------------------------------------------------
                -- 7) ENFORCE GBXP TARGET
                ----------------------------------------------------
                if not blockForMachineClaim then
                do
                    local worldSet = _getEquippedSetFromWorld()
                    local now = tick()

                    for _, u in ipairs(gbxpArr) do
                        if _isPetInMutationMachine(u) then
                            if _isEquippedNow(u, worldSet) then
                                _safeUnequip(u, "gbxp-guard (in mutation machine)", "gbxp-machine")
                                worldSet = _getEquippedSetFromWorld()
                            end
                        elseif _isEquippedNow(u, worldSet) and (not targetSet[u]) then
                            _safeUnequip(
                                u,
                                "not in active targetList stage=" .. tostring(activeStage),
                                "gbxp-guard"
                            )
                        end
                    end

                    worldSet = _getEquippedSetFromWorld()

                    for _, rec in ipairs(targetList) do
                        local u = rec.uuid
                        if _isPetInMutationMachine(u) then
                            -- jangan re-equip pet yang sedang di mutation machine
                        else
                        local last = _LAST_TRY_EQUIP[u] or 0

                        if u
                            and _isInStore(u)
                            and (not _isEquippedNow(u, worldSet))
                            and (forceApply or ((now - last) >= REEQUIP_RETRY_SEC))
                        then
                            _LAST_TRY_EQUIP[u] = now

                            _safeEquip(
                                u,
                                "GBXP STAGE=" .. tostring(rec.stage)
                                    .. " age=" .. tostring(rec.age)
                                    .. " w100=" .. tostring(rec.w100),
                                forceApply and "main-equip" or "ensure"
                            )

                            GBXP_LOCAL.equipModeByUUID[u] = weightMode
                        end
                        end
                    end
                end

                M.UnequipUnselectedGbxpFromGarden(targetList)

                ----------------------------------------------------
                -- 8) SUPPORT TAB GATE
                ----------------------------------------------------
                do
                    local wantNoosOn = false
                    local noosAgeThr = _getNoosAgeThreshold()

                    for _, rec in ipairs(targetList) do
                        if rec.age > (noosAgeThr - EPS)
                            and rec.w100 < (_getW100MaxEquip() - EPS)
                        then
                            wantNoosOn = true
                            break
                        end
                    end

                    local allMutMatch = (activeStage == "A") and _allTargetsMutMatch(targetList)

                    local ownerByUUID, boostOwned, xpOwned, noosOwned, ageOwned =
                        _computeSupportOwners(
                            boostArr,
                            xpArr,
                            noosArr,
                            ageArr,
                            targetList,
                            minAge,
                            wantNoosOn
                        )

                    if allMutMatch then
                        -- Jangan lepas boost kalau masih ada kandidat Stage A lain
                        -- (maxEquip 1: current slot sudah mut, next masih nunggu).
                        local hasNextA = false
                        for _, rec in ipairs(groups.A or {}) do
                            local u = rec and rec.uuid
                            if u and not _isMutationSelected(u) then
                                hasNextA = true
                                break
                            end
                        end

                        if hasNextA then
                            d(1, "BOOST keep ON: stage A slot done, next A candidate exists")
                        else
                            d(1, "BOOST forced OFF: stage A all targets mutation matched")
                            boostOwned = {}
                        end
                    end

                    local stageNow = tostring(activeStage or "")

                    if stageNow ~= "A" then boostOwned = {} end
                    if stageNow ~= "B" then xpOwned = {} end
                    if stageNow ~= "C" then noosOwned = {} end
                    if stageNow ~= "D" then ageOwned = {} end

                    local globalOwnedSet = {}

                    for _, u in ipairs(boostOwned or {}) do
                        if u then globalOwnedSet[u] = true end
                    end
                    for _, u in ipairs(xpOwned or {}) do
                        if u then globalOwnedSet[u] = true end
                    end
                    for _, u in ipairs(noosOwned or {}) do
                        if u then globalOwnedSet[u] = true end
                    end
                    for _, u in ipairs(ageOwned or {}) do
                        if u then globalOwnedSet[u] = true end
                    end

                    enforceTab(
                        boostArr,
                        boostOwned,
                        globalOwnedSet,
                        "boost",
                        "BOOST owner ON stage A",
                        "BOOST owner OFF not stage A"
                    )

                    enforceTab(
                        xpArr,
                        xpOwned,
                        globalOwnedSet,
                        "xp",
                        "XP owner ON stage B",
                        "XP owner OFF not stage B"
                    )

                    enforceTab(
                        noosArr,
                        noosOwned,
                        globalOwnedSet,
                        "noos",
                        "NOOS owner ON stage C",
                        "NOOS owner OFF not stage C"
                    )

                    enforceTab(
                        ageArr,
                        ageOwned,
                        globalOwnedSet,
                        "seratusage",
                        "AGE owner ON stage D",
                        "AGE owner OFF not stage D"
                    )
                end
                end -- not blockForMachineClaim
                 

                LAST_TARGET_UUID = targetKey
                LAST_MODE = weightMode
                LAST_STAGE = activeStage
                __RESUME_REAPPLY = false
            end

            do
                local mml = rawget(G, "MutationMachineLoop") or _G.MutationMachineLoop
                if mml and type(mml.Tick) == "function" then
                    pcall(function()
                        mml.Tick({
                            targetList = fullTargetList or targetList,
                            groups = groups,
                            machineWaitBoost = machineWaitBoost == true,
                        })
                    end)
                end
            end

            _tickCacheEnd()
        else
            _syncShardCleanerRun(nil)
        end

        task.wait(loopWait)
    end
end

------------------------------------------------------------
-- PUBLIC API
------------------------------------------------------------
function M.PeekGbxpOwner()
    local s = tostring(CURRENT_STAGE or G.CURRENT_STAGE or _G.CURRENT_STAGE or "")
    if s == "D" then
        return "AGE"
    end
    if s == "B" then
        return "XP"
    end
    if s == "A" then
        return "BOOST"
    end
    if s == "C" then
        return "NOOS"
    end
    return nil
end

function M.EquipUUIDs(self, arr, why)
    local list = arr
    if type(self) == "table" and self[1] ~= nil and type(arr) ~= "table" then
        list = self
        why = arr
    end
    _equipMany(list, tostring(why or "api"), "api-equip")
end

function M.UnequipUUIDs(self, arr, why)
    local list = arr
    if type(self) == "table" and self[1] ~= nil and type(arr) ~= "table" then
        list = self
        why = arr
    end
    _unequipMany(list, tostring(why or "api"), "api-unequip")
end

function M.Start(modeId)
        if running then
        return
    end

    resolveGameModules()

    pcall(function()
        unequipAllPetsInGarden(10, "Start " .. tostring(modeId or ""))
    end)
    pcall(function()
        local baku = rawget(G, "BakuCombo") or _G.BakuCombo
        if type(baku) == "table" and type(baku.ResetSync) == "function" then
            baku.ResetSync()
        end
    end)

    running = true

    if modeId then
        if type(setGBXPStageMode) == "function" then
            setGBXPStageMode(modeId)
        else
            GBXP_STAGE_MODE = modeId
            G.GBXP_STAGE_MODE = modeId
            _G.GBXP_STAGE_MODE = modeId
            if G.STATE then
                G.STATE.stage_mode = modeId
                G.STATE.GBXP_STAGE_MODE = modeId
            end
        end
    end

    _syncMutationMachineOnStart(tostring(modeId or "autokg_start"))
    
    -- di AutoKG Start
pcall(function()
    local W = rawget(_G, "AutoKGWebhook") or rawget(G, "AutoKGWebhook") or _G.Webhook
    if W and W.StartResultLoop then
        W.StartResultLoop()
    end
end)

    ------------------------------------------------
    -- START NIL COOLDOWN FIXER
    ------------------------------------------------
task.spawn(function()
    local NCF = rawget(_G, "NilCooldownFixer")

    if NCF
    and type(NCF.Start) == "function"
    and (
        type(NCF.IsRunning) ~= "function"
        or not NCF.IsRunning()
    )
    then
        NCF.Start(20)
    end
end)

    pcall(function()
        local SS = _G.SwapSkill or (getgenv and getgenv().SwapSkill)
        local st = rawget(G, "STATE") or rawget(_G, "STATE")
        local cfg = type(st) == "table" and st.swap_skill
        local pnpOn = type(cfg) == "table" and cfg.enabled == true
        if SS and type(SS.SyncFromState) == "function" then SS.SyncFromState() end
        if pnpOn then
            if SS and type(SS.Start) == "function" then SS.Start() end
        else
            if SS and type(SS.Stop) == "function" then SS.Stop("autokg_start") end
        end
        if _isSharkListMode() then
            Shark.syncPnP("autokg_start", false)
            pcall(function()
                local R = Shark.SB.rt()
                R.ignoreMimicUntil = 0
                Shark.SB.hookVfx()
                Shark.SB.ensureHb()
            end)
        end
    end)

    _syncShardCleanerRun(nil)

    d(1, "AutoKGLoop.Start mode=", tostring(modeId or _getStageMode()))
end

function M.Stop(reason)
    if not running then
        return
    end

    running = false
    _syncShardCleanerRun(nil)
    _syncMutationMachineOnStop(tostring(reason or "autokg_stop"))
    pcall(function()
        Shark.SB.stopHooks()
    end)
    d(1, "AutoKGLoop.Stop()", tostring(reason or ""))

    -- reset runtime state
    __RESUME_REAPPLY = false
    LAST_TARGET_UUID = nil
    LAST_MODE        = nil
    CURRENT_STAGE    = nil

    GBXP_LOCAL.equippedUUID = nil
    GBXP_LOCAL.equipModeByUUID = {}

    -- 🔥 RESET GLOBAL STAGE LOCK
    if GBXP_STAGE_SCHED then
        GBXP_STAGE_SCHED.stage = nil
        GBXP_STAGE_SCHED.mode  = nil
    end

    -- 🔥 RESET FOCUS LOCK (WAJIB)
    if GBXP_FOCUS_SCHED then
        GBXP_FOCUS_SCHED.targets      = {}
        GBXP_FOCUS_SCHED.mode         = nil
        GBXP_FOCUS_SCHED.missingSince = {}
        GBXP_FOCUS_SCHED.stage        = nil -- penting untuk stage lock
    end

    -- stop async delay
    M.__stopEpoch = (M.__stopEpoch or 0) + 1

pcall(function()
    local SS = _G.SwapSkill or (getgenv and getgenv().SwapSkill)
    if SS and type(SS.Stop) == "function" then
        SS.Stop()
    end
end)

pcall(function()
    local NCF = rawget(_G, "NilCooldownFixer")

    if NCF
    and type(NCF.Stop) == "function"
    and (
        type(NCF.IsRunning) ~= "function"
        or NCF.IsRunning()
    )
    then
        NCF.Stop()
    end
end)
    -- unequip semua pet di garden
    pcall(function()
        unequipAllPetsInGarden(10, "Stop " .. tostring(reason or ""))
    end)
    
    -- di AutoKG Stop
pcall(function()
    local W = rawget(_G, "AutoKGWebhook") or rawget(G, "AutoKGWebhook") or _G.Webhook
    if W and W.StopResultLoop then
        W.StopResultLoop()
    end
end)
end


function M.IsRunning()
    return running
end

function M.SetDebug(on, level)
    GBXP_DEBUG  = (on == true)
    DEBUG_LEVEL = level or DEBUG_LEVEL
end

-- simpan ke global dulu
_G.AutoKGLoop = M


M.__token = token
G[LOOP_TOKEN_ATTR] = token

task.spawn(function()
    mainLoop(token)
end)

local function _bucket01(n)
    n = tonumber(n)
    if not n then return "?" end
    return string.format("%.1f", math.floor(n * 10) / 10)
end

local function _incNested(t, a, b, n)
    a = tostring(a or "?")
    b = tostring(b or "?")
    n = tonumber(n) or 1

    t[a] = t[a] or {}
    t[a][b] = (tonumber(t[a][b]) or 0) + n
end

local function _inc(t, k, n)
    k = tostring(k or "?")
    n = tonumber(n) or 1
    t[k] = (tonumber(t[k]) or 0) + n
end

local SNAPSHOT_BUCKET_AGE = 1

function M.GetResultSnapshot()
    local mode = _getStageMode()
    local out = {
        mode = mode,
        gbxpTotal = 0,
        needProcess = {},
        notProcess = {},
        stageNeed = {
            A = 0,
            B = 0,
            C = 0,
            D = 0,
        },
    }

    local function petTypeOf(uuid, p)
        if type(p) == "table" then
            local label = p.ptypeLabel or p.ptype
            if label and tostring(label) ~= "" then
                return tostring(label)
            end
        end
        local rec = nil
        pcall(function()
            rec = _getPetRecord(uuid)
        end)
        return _getPetTypeFromRecord(rec) or "Unknown"
    end

    local function stageOf(uuid)
        local ok, stage = pcall(_getStageForGBXP, uuid)
        if ok then
            return stage
        end
        return nil
    end

    local function addNotProcess(uuid, p)
        local petType = petTypeOf(uuid, p)
        local ageNow = type(p) == "table" and tonumber(p.age) or nil
        local kgAge1 = type(p) == "table" and tonumber(p.kgAtAge1) or nil
        pcall(function()
            if not ageNow then
                ageNow = getPetAge and getPetAge(uuid)
            end
            if not kgAge1 then
                local base = getBaseKg and getBaseKg(uuid)
                if base then
                    kgAge1 = base * (1 + SCALE * SNAPSHOT_BUCKET_AGE)
                end
            end
        end)
        local kgKey = _bucket01(kgAge1)
        if not tonumber(kgKey) then
            kgKey = "0.0"
        end
        local ageKey = tostring(math.floor(tonumber(ageNow) or 0))
        out.notProcess[petType] = out.notProcess[petType] or {}
        out.notProcess[petType][kgKey] = out.notProcess[petType][kgKey] or {}
        out.notProcess[petType][kgKey][ageKey] =
            (tonumber(out.notProcess[petType][kgKey][ageKey]) or 0) + 1
    end

    -- Details 2 (Need Process): hanya tim GBXP yang sedang selected.
    local selectedSeen = {}
    for _, uuid in ipairs(setToArray(selected and selected.gbxp or {})) do
        local core = tostring(uuid):match("{?([0-9a-fA-F%-]+)}?") or tostring(uuid)
        if core ~= "" and not selectedSeen[core] then
            selectedSeen[core] = true
            out.gbxpTotal += 1
            local stage = stageOf(uuid)
            if stage then
                _inc(out.needProcess, petTypeOf(uuid), 1)
                out.stageNeed[stage] = (tonumber(out.stageNeed[stage]) or 0) + 1
            else
                addNotProcess(uuid)
            end
        end
    end

    -- Details 3 (Not Process / Pickup): kandidat list yang sudah tidak punya stage.
    -- Jangan masukin pet yang masih selected ke sini 2x.
    local listSeen = {}
    for _, p in ipairs(M.ListGbxpPets()) do
        local uuid = p and p.uuid
        if uuid then
            local core = tostring(uuid):match("{?([0-9a-fA-F%-]+)}?") or tostring(uuid)
            if core ~= "" and not listSeen[core] and not selectedSeen[core] then
                listSeen[core] = true
                if not stageOf(uuid) then
                    addNotProcess(uuid, p)
                end
            end
        end
    end

    return out
end

return M

        end,
        required = false,
    },
    {
        key = "mutation_machine_api",
        name = "mutation_machine_api",
        factory = function()
            -- mutation_machine_api.lua
-- Pet Mutation Machine: read state + SubmitHeldPet / StartMachine / ClaimMutatedPet
-- Hardened for intermittent stuck (no proximity / teleport required):
--   - StartMachine costs MUTATE_PRICE sheckles
--   - submit → wait SubmittedPet → start with verify/retry

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LocalPlayer = Players.LocalPlayer
local G = (getgenv and getgenv()) or _G

local function waitChild(parent, name, timeout)
    if not parent then return nil end
    local existing = parent:FindFirstChild(name)
    if existing then return existing end
    local ok, inst = pcall(function()
        return parent:WaitForChild(name, timeout or 3)
    end)
    if ok then return inst end
    return nil
end

local function safeRequire(inst)
    if not inst then return nil end
    local ok, mod = pcall(require, inst)
    if ok then return mod end
    return nil
end

local DataService = safeRequire(waitChild(waitChild(ReplicatedStorage, "Modules", 5), "DataService", 5))
local PetsService = safeRequire(
    waitChild(waitChild(waitChild(ReplicatedStorage, "Modules", 5), "PetServices", 5), "PetsService", 5)
)

local GameEvents = waitChild(ReplicatedStorage, "GameEvents", 5)
local RE_Machine = GameEvents and (GameEvents:FindFirstChild("PetMutationMachineService_RE") or waitChild(GameEvents, "PetMutationMachineService_RE", 3))

local InvEnums = nil
pcall(function()
    InvEnums = require(ReplicatedStorage.Data.EnumRegistry.InventoryServiceEnums)
end)
local ItemTypeEnums = nil
pcall(function()
    ItemTypeEnums = require(ReplicatedStorage.Data.EnumRegistry.ItemTypeEnums)
end)

local PetMutationMachineData = nil
pcall(function()
    PetMutationMachineData = require(ReplicatedStorage.Data.PetMutationMachineData)
end)

local M = {}

local ACTION_COOLDOWN      = 0.6
local DEFAULT_MUTATE_PRICE = 500000000

local _lastActionAt   = 0
local _lastFailReason = nil
local _lastFailAt     = 0
local _lastFireAction = nil
local _lastFireOk     = nil
local _lastFireAt     = 0
local _lastTargetName = nil
local _lastTargetUuid = nil

local function normUUID(u)
    if not u or u == "" then return nil, nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    if core == "" then return nil, nil end
    return core, "{" .. core .. "}"
end

local function setFail(reason)
    _lastFailReason = reason and tostring(reason) or nil
    _lastFailAt = tick()
end

local function setLastTarget(uuid, name)
    local core = select(1, normUUID(uuid))
    _lastTargetUuid = core
    if name and tostring(name) ~= "" then
        _lastTargetName = tostring(name)
    end
end

function M.GetLastFailReason()
    if not _lastFailReason then return nil end
    if (tick() - _lastFailAt) > 12 then
        return nil
    end
    return _lastFailReason
end

function M.GetLastFailAge()
    if not _lastFailReason then return nil end
    return math.max(0, tick() - _lastFailAt)
end

function M.GetProfile()
    if type(DataService) ~= "table" then
        DataService = safeRequire(waitChild(waitChild(ReplicatedStorage, "Modules", 2), "DataService", 2))
    end
    if type(DataService) ~= "table" or type(DataService.GetData) ~= "function" then
        return nil
    end
    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if ok and type(profile) == "table" then
        return profile
    end
    return nil
end

function M.GetMachine()
    local profile = M.GetProfile()
    return profile and profile.PetMutationMachine
end

function M.GetPhase(machine)
    machine = machine or M.GetMachine()
    if type(machine) ~= "table" then return "unknown" end
    if machine.PetReady == true then return "claim" end
    if machine.IsRunning == true or (tonumber(machine.TimeLeft) or 0) > 0 then
        return "running"
    end
    if type(machine.SubmittedPet) == "table" then return "submitted" end
    return "idle"
end

function M.IsProcessing(machine)
    machine = machine or M.GetMachine()
    if type(machine) ~= "table" then return false end
    if machine.PetReady == true then return true end
    if machine.IsRunning == true then return true end
    if (tonumber(machine.TimeLeft) or 0) > 0 then return true end
    if type(machine.SubmittedPet) == "table" then return true end
    return false
end

function M.SubmittedCore(machine)
    machine = machine or M.GetMachine()
    local sp = machine and machine.SubmittedPet
    if type(sp) ~= "table" then return nil end
    return select(1, normUUID(sp.UUID or sp.uuid or sp.PetUUID or sp.Id))
end

local MUT_CODE_TO_NAME = {}
pcall(function()
    local mod = require(ReplicatedStorage.Data.PetRegistry.PetMutationRegistry)
    local reg = (type(mod) == "table" and (mod.PetMutationRegistry or mod)) or nil
    if type(reg) ~= "table" then return end
    for mutName, def in pairs(reg) do
        if type(def) == "table" and type(def.EnumId) == "string" and def.EnumId ~= "" then
            MUT_CODE_TO_NAME[def.EnumId] = tostring(mutName)
        end
    end
end)

local Snap = {}
function Snap.mutNames(rec)
    if type(rec) ~= "table" then return {} end
    local PD = rec.PetData or rec.Data or {}
    local raw = PD.MutationType or rec.MutationType
        or PD.Mutations or PD.Mutation or PD.MutationCodes
        or rec.Mutations or rec.Mutation or rec.MutationCodes
    if not raw then return {} end
    local names, seen = {}, {}
    local function addCode(code)
        code = tostring(code or ""):gsub("%s+", "")
        if code == "" or code == "None" or code == "nil" then return end
        local name = MUT_CODE_TO_NAME[code]
        if name then
            if not seen[name] then
                seen[name] = true
                names[#names + 1] = name
            end
            return
        end
        if #code > 1 and not seen[code] then
            seen[code] = true
            names[#names + 1] = code
            return
        end
        for c in code:gmatch("%a") do
            local n = MUT_CODE_TO_NAME[c]
            if n and not seen[n] then
                seen[n] = true
                names[#names + 1] = n
            end
        end
    end
    if type(raw) == "string" then
        addCode(raw)
    elseif type(raw) == "table" then
        for k, v in pairs(raw) do
            if type(v) == "string" then
                addCode(v)
            elseif type(v) == "table" then
                addCode(v.MutationType or v.EnumId or v.Code or v.code or v.Mutation or v.Name)
            elseif v == true then
                addCode(k)
            end
        end
    end
    return names
end

function Snap.num(rec, keys)
    if type(rec) ~= "table" then return nil end
    for _, k in ipairs(keys) do
        local v = rec[k]
        local n = tonumber(v)
        if not n and type(v) == "string" then
            n = tonumber((v:gsub(",", ".")))
        end
        if n then return n end
    end
    return nil
end

function Snap.fromRecord(rec, uuidHint)
    if type(rec) ~= "table" then return nil end
    local PD = rec.PetData or rec.Data or {}
    local uuid = select(1, normUUID(
        uuidHint or rec.UUID or rec.uuid or rec.PetUUID or rec.Id or PD.UUID or PD.uuid
    ))
    local name = tostring(rec.PetType or rec.Type or rec.Name or PD.PetType or PD.Type or PD.Name or "Pet")
    local ageKeys = { "Age", "age", "Level", "level" }
    local wKeys = { "Weight", "weight", "KG", "kg", "W", "w" }
    local age = Snap.num(rec, ageKeys) or Snap.num(PD, ageKeys)
    local kg = Snap.num(rec, wKeys) or Snap.num(PD, wKeys)
    return {
        uuid = uuid,
        petType = name,
        age = age,
        kg = kg,
        mutations = Snap.mutNames(rec),
    }
end

function Snap.lookup(uuid)
    local core, br = normUUID(uuid)
    if not core then return nil end
    local function fromBag(bag)
        if type(bag) ~= "table" then return nil end
        local rec = bag[core] or bag[br] or bag[uuid] or bag[tostring(uuid)]
        if type(rec) == "table" then return rec end
        for k, v in pairs(bag) do
            if type(v) == "table" and select(1, normUUID(k)) == core then
                return v
            end
        end
        return nil
    end
    local profile = M.GetProfile()
    if type(profile) ~= "table" then return nil end
    local rec = fromBag(profile.InventoryData)
    if rec then return rec end
    local pd = profile.PetsData
    if type(pd) == "table" then
        rec = fromBag(pd.Pets or pd.Inventory or pd.PetInventory)
        if rec then return rec end
        if type(pd.PetInventory) == "table" then
            rec = fromBag(pd.PetInventory.Data or pd.PetInventory)
            if rec then return rec end
        end
    end
    return nil
end

function M.GetSubmittedSnapshot(machine)
    machine = machine or M.GetMachine()
    local sp = machine and machine.SubmittedPet
    if type(sp) ~= "table" then return nil end
    return Snap.fromRecord(sp)
end

function M.GetInventorySnapshot(uuid)
    local rec = Snap.lookup(uuid)
    if not rec then return nil end
    return Snap.fromRecord(rec, uuid)
end

function M.IsPetInMachine(uuid)
    local core = select(1, normUUID(uuid))
    if not core then return false end
    local sub = M.SubmittedCore()
    return sub ~= nil and sub == core
end

local function _submittedPetLabel(machine)
    machine = machine or M.GetMachine()
    local sp = machine and machine.SubmittedPet
    if type(sp) ~= "table" then return nil end
    return tostring(sp.PetType or sp.Type or sp.Name or "Pet")
end

local function _formatTimeLeft(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    local mins = math.floor(sec / 60)
    local secs = sec % 60
    return string.format("%02d:%02d", mins, secs)
end

local function _fmtNum(n)
    n = tonumber(n) or 0
    local abs = math.abs(n)
    if abs >= 1e12 then
        return string.format("%.2fT", n / 1e12)
    elseif abs >= 1e9 then
        return string.format("%.2fB", n / 1e9)
    elseif abs >= 1e6 then
        return string.format("%.2fM", n / 1e6)
    elseif abs >= 1e3 then
        return string.format("%.1fK", n / 1e3)
    end
    return tostring(math.floor(n))
end

local function _submittedPetDetails(machine)
    machine = machine or M.GetMachine()
    local sp = machine and machine.SubmittedPet
    if type(sp) ~= "table" then return nil end

    local pd = type(sp.PetData) == "table" and sp.PetData or nil
    local name = tostring(sp.PetType or sp.Type or sp.Name or (pd and pd.PetType) or "Pet")
    local uuid = select(1, normUUID(sp.UUID or sp.uuid or sp.PetUUID or sp.Id or (pd and pd.UUID)))

    return {
        name = name,
        uuid = uuid,
    }
end

local function _failLabel(fail)
    if not fail then return nil end
    local map = {
        no_money = "kurang sheckles",
        hold_failed = "gagal hold pet",
        submit_timeout = "submit timeout",
        submit_fire_fail = "submit fire gagal",
        start_timeout = "start timeout / stuck",
        not_submitted = "belum submitted",
        no_remote = "remote hilang",
        cooldown = "cooldown",
    }
    return map[fail] or tostring(fail)
end

function M.GetMutatePrice()
    local p = PetMutationMachineData and tonumber(PetMutationMachineData.MUTATE_PRICE)
    if p and p > 0 then return p end
    return DEFAULT_MUTATE_PRICE
end

function M.GetSheckles()
    local profile = M.GetProfile()
    if type(profile) ~= "table" then return 0 end
    local s = tonumber(profile.Sheckles)
    if s then return s end
    if type(profile.CurrencyData) == "table" then
        s = tonumber(profile.CurrencyData.Sheckles)
        if s then return s end
    end
    if type(profile.Stats) == "table" then
        s = tonumber(profile.Stats.Sheckles)
        if s then return s end
    end
    return 0
end

function M.CanAffordStart()
    return M.GetSheckles() >= M.GetMutatePrice()
end

function M.WaitPhase(wantPhase, timeoutSec)
    timeoutSec = tonumber(timeoutSec) or 4
    local t0 = tick()
    while (tick() - t0) < timeoutSec do
        if M.GetPhase() == wantPhase then
            return true
        end
        task.wait(0.15)
    end
    return M.GetPhase() == wantPhase
end

function M.BuildStatusText()
    local fail = M.GetLastFailReason()
    local machine = M.GetMachine()
    if type(machine) ~= "table" then
        return "Machine: data belum tersedia"
    end

    local phase = M.GetPhase(machine)
    local petName = _submittedPetLabel(machine)
    local tl = tonumber(machine.TimeLeft) or 0

    local headline
    if phase == "claim" then
        headline = string.format(
            "Machine: READY — claim%s",
            petName and (" " .. petName) or ""
        )
    elseif phase == "running" then
        headline = string.format(
            "Machine: RUNNING — %s (%s)",
            petName or "pet",
            _formatTimeLeft(tl)
        )
    elseif phase == "submitted" then
        headline = string.format(
            "Machine: SUBMITTED — start%s",
            petName and (" " .. petName) or ""
        )
    elseif phase == "idle" then
        headline = "Machine: IDLE — siap submit pet"
    else
        headline = "Machine: " .. tostring(phase)
    end

    -- Override headline for clear stuck / money / hold errors
    if fail == "no_money" then
        headline = string.format(
            "Machine: BUTUH SHECKLES — start %s / punya %s",
            _fmtNum(M.GetMutatePrice()),
            _fmtNum(M.GetSheckles())
        )
    elseif fail == "start_timeout" and phase == "submitted" then
        headline = string.format(
            "Machine: STUCK SUBMIT — retry start%s",
            petName and (" " .. petName) or ""
        )
    elseif fail == "hold_failed" then
        headline = "Machine: ERROR — gagal hold pet tool"
    elseif fail == "submit_timeout" then
        headline = string.format(
            "Machine: SUBMIT FAIL — timeout%s",
            (_lastTargetName and (" " .. _lastTargetName)) or ""
        )
    elseif fail == "submit_fire_fail" or fail == "no_remote" then
        headline = "Machine: ERROR — " .. _failLabel(fail)
    end

    if fail then
        local ago = math.floor(M.GetLastFailAge() or 0)
        return headline .. "\nFail: " .. _failLabel(fail) .. " (" .. tostring(ago) .. "s)"
    end

    return headline
end

local function getBackpack()
    return LocalPlayer:FindFirstChildOfClass("Backpack") or LocalPlayer:FindFirstChild("Backpack")
end

local function isPetTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    if ItemTypeEnums and InvEnums then
        local it = tool:GetAttribute(InvEnums.ITEM_TYPE)
        if it ~= nil then
            return tostring(it) == tostring(ItemTypeEnums.Pet)
        end
    end
    local id = tool:GetAttribute("PET_UUID") or tool:GetAttribute("UUID") or tool:GetAttribute("PetUUID")
    return id ~= nil and id ~= ""
end

function M.FindPetTool(uuid)
    local core = select(1, normUUID(uuid))
    if not core then return nil end

    local function scan(container)
        if not container then return nil end
        for _, t in ipairs(container:GetChildren()) do
            if t:IsA("Tool") and isPetTool(t) then
                local id = t:GetAttribute("PET_UUID") or t:GetAttribute("UUID") or t:GetAttribute("PetUUID")
                if id then
                    local c = tostring(id):match("{?([0-9a-fA-F%-]+)}?") or tostring(id)
                    if c == core then return t end
                end
            end
        end
        return nil
    end

    local char = LocalPlayer.Character
    return scan(char) or scan(getBackpack())
end

local function unequipAllTools()
    local char = LocalPlayer.Character
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum:UnequipTools() end)
    end
    local bp = getBackpack()
    if bp then
        for _, obj in ipairs(char:GetChildren()) do
            if obj:IsA("Tool") then
                obj.Parent = bp
            end
        end
    end
end

local function toolUUIDCore(tool)
    if not tool then return nil end
    local id = tool:GetAttribute("PET_UUID") or tool:GetAttribute("UUID") or tool:GetAttribute("PetUUID")
    if not id then return nil end
    return tostring(id):match("{?([0-9a-fA-F%-]+)}?") or tostring(id)
end

-- Garden/active pet equip (bukan tool di tangan). Setelah claim sering nempel di character.
function M.GetEquippedGardenPets()
    local list = {}
    local profile = M.GetProfile and M.GetProfile() or nil
    local petequip = profile and profile.PetsData and profile.PetsData.EquippedPets
    if type(petequip) ~= "table" then return list end
    for _, value in pairs(petequip) do
        local uuid
        if type(value) == "string" then
            uuid = value
        elseif type(value) == "table" then
            uuid = value.UUID or value.Uuid or value.PetUUID or value.uuid
        end
        if uuid then
            list[#list + 1] = uuid
        end
    end
    return list
end

function M.UnequipGardenPet(uuid)
    local core, br = normUUID(uuid)
    if not core then return end
    if type(safeUnequip) == "function" then
        pcall(function() safeUnequip(br or core) end)
        pcall(function() safeUnequip(core) end)
        return
    end
    if not PetsService then
        PetsService = safeRequire(
            waitChild(waitChild(waitChild(ReplicatedStorage, "Modules", 2), "PetServices", 2), "PetsService", 2)
        )
    end
    if PetsService then
        pcall(function() PetsService:UnequipPet(br or ("{" .. core .. "}")) end)
        pcall(function() PetsService:UnequipPet(core) end)
    end
end

function M.UnequipAllGardenPets(maxSec)
    maxSec = tonumber(maxSec) or 4
    local t0 = os.clock()
    while (os.clock() - t0) < maxSec do
        local list = M.GetEquippedGardenPets()
        if #list == 0 then
            return true
        end
        for _, u in ipairs(list) do
            M.UnequipGardenPet(u)
        end
        task.wait(0.3)
    end
    return #M.GetEquippedGardenPets() == 0
end

function M.WaitPetTool(uuid, timeoutSec)
    timeoutSec = tonumber(timeoutSec) or 6
    local t0 = os.clock()
    while (os.clock() - t0) < timeoutSec do
        local tool = M.FindPetTool(uuid)
        if tool then
            return tool
        end
        task.wait(0.2)
    end
    return nil
end

function M.HoldPetTool(uuid)
    local want = select(1, normUUID(uuid))
    if not want then return false end

    -- setelah claim, tool bisa delay muncul di backpack
    local tool = M.WaitPetTool(uuid, 6) or M.FindPetTool(uuid)
    if not tool then return false end

    local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return false end

    unequipAllTools()
    task.wait(0.12)

    tool = M.FindPetTool(uuid) or tool
    if not tool then return false end

    tool.Parent = char
    pcall(function() hum:EquipTool(tool) end)
    task.wait(0.25)

    local held = char:FindFirstChildWhichIsA("Tool")
    if not (held and isPetTool(held)) then
        return false
    end
    -- wajib UUID yang dipegang = target (jangan submit pet claim yang masih di tangan)
    local heldCore = toolUUIDCore(held)
    return heldCore ~= nil and heldCore == want
end

local function canFire(force)
    if force then
        _lastActionAt = tick()
        return true
    end
    local now = tick()
    if (now - _lastActionAt) < ACTION_COOLDOWN then
        return false
    end
    _lastActionAt = now
    return true
end

function M.Fire(action, force)
    if not RE_Machine then
        _lastFireAction = action
        _lastFireOk = false
        _lastFireAt = tick()
        return false, "no_remote"
    end
    if not canFire(force == true) then
        return false, "cooldown"
    end
    local ok, err = pcall(function()
        RE_Machine:FireServer(action)
    end)
    _lastFireAction = action
    _lastFireOk = ok == true
    _lastFireAt = tick()
    return ok, err
end

function M.SubmitHeldPet(uuid)
    setLastTarget(uuid, nil)

    -- Claim sering auto-equip pet ke garden/character → clear dulu sebelum hold tool
    pcall(function()
        M.UnequipAllGardenPets(4)
    end)
    unequipAllTools()
    task.wait(0.15)

    local tool = M.WaitPetTool(uuid, 6) or M.FindPetTool(uuid)
    if tool then
        setLastTarget(uuid, tool.Name)
    end

    if not M.HoldPetTool(uuid) then
        setFail("hold_failed")
        return false, "hold_failed"
    end

    -- double-check: tool di tangan masih UUID target
    do
        local char = LocalPlayer.Character
        local held = char and char:FindFirstChildWhichIsA("Tool")
        local want = select(1, normUUID(uuid))
        local got = toolUUIDCore(held)
        if not want or not got or got ~= want then
            setFail("hold_failed")
            return false, "hold_mismatch"
        end
    end

    local ok, err = M.Fire("SubmitHeldPet", true)
    if not ok then
        setFail(err or "submit_fire_fail")
        return false, err
    end

    if M.WaitPhase("submitted", 5) or M.IsPetInMachine(uuid) then
        setFail(nil)
        local pet = _submittedPetDetails()
        if pet and pet.name then
            setLastTarget(uuid, pet.name)
        end
        return true
    end

    setFail("submit_timeout")
    return false, "submit_timeout"
end

function M.StartMachine()
    return M.Fire("StartMachine")
end

-- Reliable start: afford check + retries until running/claim
function M.StartMachineReliable(opts)
    opts = opts or {}
    local retries = tonumber(opts.retries) or 4
    local waitSec = tonumber(opts.waitSec) or 3.5

    if M.GetPhase() == "running" or M.GetPhase() == "claim" then
        setFail(nil)
        return true
    end
    if M.GetPhase() ~= "submitted" then
        return false, "not_submitted"
    end

    if not M.CanAffordStart() then
        setFail("no_money")
        return false, "no_money"
    end

    for _ = 1, retries do
        if M.GetPhase() == "running" or M.GetPhase() == "claim" then
            setFail(nil)
            return true
        end
        if not M.CanAffordStart() then
            setFail("no_money")
            return false, "no_money"
        end

        M.Fire("StartMachine", true)

        local t0 = tick()
        while (tick() - t0) < waitSec do
            local ph = M.GetPhase()
            if ph == "running" or ph == "claim" then
                setFail(nil)
                return true
            end
            task.wait(0.2)
        end

        task.wait(0.35)
    end

    if M.GetPhase() == "running" or M.GetPhase() == "claim" then
        setFail(nil)
        return true
    end

    setFail("start_timeout")
    return false, "start_timeout"
end

-- Atomic: submit then immediately start until running
function M.SubmitAndStart(uuid, opts)
    opts = opts or {}

    local phase = M.GetPhase()
    if phase == "running" or phase == "claim" then
        return true, "already_processing"
    end

    -- jangan submit pet yang sudah HIT list mutasi
    do
        local mml = rawget(G, "MutationMachineLoop") or _G.MutationMachineLoop
        if mml and type(mml.IsMutDone) == "function" then
            local ok, done = pcall(mml.IsMutDone, uuid)
            if ok and done then
                return false, "mut_done"
            end
        end
        local doneTbl = rawget(G, "__MACHINE_MUT_DONE") or rawget(_G, "__MACHINE_MUT_DONE")
        if type(doneTbl) == "table" then
            local core = tostring(uuid or ""):match("{?([0-9a-fA-F%-]+)}?")
            if core and (doneTbl[core] == true or doneTbl["{" .. core .. "}"] == true) then
                return false, "mut_done"
            end
        end
    end

    if phase == "submitted" then
        local ok, err = M.StartMachineReliable(opts)
        return ok, err
    end

    local okSub, errSub = M.SubmitHeldPet(uuid)
    if not okSub then
        -- maybe already submitted by race
        if M.GetPhase() == "submitted" then
            return M.StartMachineReliable(opts)
        end
        return false, errSub
    end

    task.wait(0.55) -- match client prompt debounce after submit
    return M.StartMachineReliable(opts)
end

