    {
        key = "mutation_machine_loop",
        name = "mutation_machine_loop",
        factory = function()
            -- mutation_machine_loop.lua
-- Machine mutation hunt hooks for Auto NM+LVL (boostListMode = "machine").
-- Leveling/equip logic stays in autonmlvl_loop; this module handles machine submit/start/claim.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local G = (getgenv and getgenv()) or _G

-- Hot-reload: replace old singleton (skip/done logic must update)
local MODULE_VERSION = 7
local prev = rawget(G, "MutationMachineLoop")
if type(prev) == "table" and prev.__MODULE_VERSION == MODULE_VERSION then
    return prev
end

local M = (type(prev) == "table") and prev or {}
M.__MODULE_VERSION = MODULE_VERSION

local enabled     = (M.IsEnabled and M.IsEnabled() == true) or false
local nmlvlActive = (M.IsNmlvlActive and M.IsNmlvlActive() == true) or false

local EPS = 0.01

local CLAIM_PRE_DELAY  = 2
local CLAIM_POST_DELAY = 3
local MAX_CLAIM_TEAM   = 8

local _claimBusy         = false
local _claimSessionToken = nil

-- UUID yang sudah HIT list mutasi (Mega dll) → jangan submit lagi (persist + memori)
G.__MACHINE_MUT_DONE = G.__MACHINE_MUT_DONE or {}
local _doneMut = G.__MACHINE_MUT_DONE
if type(G.__MACHINE_MUT_DONE) == "table" then
    _doneMut = G.__MACHINE_MUT_DONE
end
_G.__MACHINE_MUT_DONE = _doneMut
G.__MACHINE_MUT_DONE = _doneMut

local DataService = nil
local PetsService = nil
pcall(function()
    DataService = require(ReplicatedStorage.Modules.DataService)
    PetsService = require(ReplicatedStorage.Modules.PetServices.PetsService)
end)

local function _clear(t)
    if type(t) ~= "table" then return end
    for k in pairs(t) do t[k] = nil end
end

local function _normToken(s)
    s = string.lower(tostring(s or ""))
    s = s:gsub("%b[]", ""):gsub("[^%w%s]", " "):gsub("%s+", " ")
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

local function _normUUID(u)
    if not u then return nil, nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    if core == "" then return nil, nil end
    return core, "{" .. core .. "}"
end

local function _bracedUUID(u)
    local _, br = _normUUID(u)
    return br
end

function M.GetListMode()
    local STATE = rawget(G, "STATE") or _G.STATE
    local mode = tostring((STATE and STATE.boostListMode) or "normal"):lower()
    if mode ~= "machine" then mode = "normal" end
    return mode
end

function M.IsMachineListMode()
    return M.GetListMode() == "machine"
end

function M.SetEnabled(on)
    enabled = (on == true)
end

function M.IsEnabled()
    return enabled == true
end

function M.SetNmlvlActive(on)
    nmlvlActive = (on == true)
end

function M.IsNmlvlActive()
    return nmlvlActive == true
end

local function _modeHasStageA()
    local mode = tostring(
        rawget(G, "GBXP_STAGE_MODE")
        or (G.STATE and (G.STATE.stage_mode or G.STATE.GBXP_STAGE_MODE))
        or "AUTO"
    ):gsub("%s+", ""):upper()
    if mode == "" or mode == "NIL" or mode == "AUTO" then
        return true
    end
    return string.find(mode, "A", 1, true) ~= nil
end

local function _machineHoldingPet()
    local api = rawget(G, "MutationMachineApi") or rawget(_G, "MutationMachineApi")
    if not api or type(api.GetPhase) ~= "function" then return false end
    local ok, phase = pcall(function()
        return tostring(api.GetPhase() or "")
    end)
    if not ok then return false end
    return phase == "submitted" or phase == "running" or phase == "claim"
end

function M.ShouldRunMachine()
    if not enabled or not nmlvlActive then return false end
    if not M.IsMachineListMode() then return false end
    -- Mesin hanya urusan Stage A. B/C/D dan mode tanpa A tidak boleh ikut berhenti.
    local stageNow = tostring(rawget(G, "CURRENT_STAGE") or rawget(_G, "CURRENT_STAGE") or "")
    if stageNow == "A" then return true end
    if stageNow ~= "" then return false end
    -- Satu-satunya pet GBXP ada di mesin: umurnya tidak kebaca, stage jadi kosong.
    -- Claim/start tetap jalan. Mode tanpa A (D, B, BD, ...) tetap diam.
    if not _modeHasStageA() then return false end
    return _machineHoldingPet()
end

function M.IsClaimBusy()
    return _claimBusy == true or G.__MACHINE_CLAIM_BUSY == true
end

function M.GetClaimTeamBefore()
    return G.NMLVL_MACHINE_CLAIM_TEAM_BEFORE or _G.NMLVL_MACHINE_CLAIM_TEAM_BEFORE or {}
end

function M.SyncMutSelected()
    if not M.IsMachineListMode() then return end

    local STATE = rawget(G, "STATE") or _G.STATE
    local bms = STATE and STATE.boostMutSelected
    local src = bms and bms.machine
    -- bucket machine kosong: jangan wipe GBXP_MUT_SELECTED (pilihan user hilang)
    if type(src) ~= "table" or next(src) == nil then
        src = bms and bms.normal
    end
    if type(src) ~= "table" or next(src) == nil then
        return
    end

    G.GBXP_MUT_SELECTED    = G.GBXP_MUT_SELECTED    or {}
    G.GBXP_MUT_SELECTED_LC = G.GBXP_MUT_SELECTED_LC or {}

    _clear(G.GBXP_MUT_SELECTED)
    _clear(G.GBXP_MUT_SELECTED_LC)

    for name, on in pairs(src) do
        if on == true and name ~= nil then
            local s = tostring(name)
            G.GBXP_MUT_SELECTED[s] = true
            G.GBXP_MUT_SELECTED_LC[s:lower()] = true
            local nor = _normToken(s)
            if nor ~= "" then
                G.GBXP_MUT_SELECTED[nor] = true
            end
        end
    end
end

function M.GetApi()
    return G.MutationMachineApi or _G.MutationMachineApi
end

function M.WantBoostOn()
    if not M.ShouldRunMachine() then return false end
    if M.IsClaimBusy() then return false end
    local api = M.GetApi()
    if not api or type(api.IsProcessing) ~= "function" then return false end
    if type(api.GetPhase) == "function" and api.GetPhase() == "claim" then
        return false
    end
    return api.IsProcessing() == true
end

local function _markMutDone(uuid)
    local core, br = _normUUID(uuid)
    if not core then return end
    _doneMut[core] = true
    _doneMut["{" .. core .. "}"] = true
    if br then _doneMut[br] = true end
    if type(uuid) == "string" and uuid ~= "" then
        _doneMut[uuid] = true
    end
    G.__MACHINE_MUT_DONE = _doneMut
    _G.__MACHINE_MUT_DONE = _doneMut
end

local function _isMutDone(uuid)
    local core, br = _normUUID(uuid)
    if not core then return false end
    if _doneMut[core] == true or _doneMut["{" .. core .. "}"] == true then
        return true
    end
    if br and _doneMut[br] == true then
        return true
    end
    if type(uuid) == "string" and _doneMut[uuid] == true then
        return true
    end
    return false
end

function M.MarkMutDone(uuid)
    _markMutDone(uuid)
end

function M.IsMutDone(uuid)
    return _isMutDone(uuid)
end

local function _nameMatchesSelected(n, sel, selLc)
    n = tostring(n or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if n == "" then return false end
    if sel[n] == true or selLc[n:lower()] == true or sel[n:lower()] == true then
        return true
    end
    local nor = _normToken(n)
    if nor ~= "" and (sel[nor] == true or selLc[nor] == true) then
        return true
    end
    return false
end

local function _labelHasSelectedMut(label, sel, selLc)
    label = tostring(label or "")
    if label == "" then return false end
    local low = label:lower()
    for name, on in pairs(sel) do
        if on == true then
            local mut = tostring(name)
            if mut ~= "" and low:find(mut:lower(), 1, true) then
                return true
            end
        end
    end
    for name, on in pairs(selLc) do
        if on == true then
            local mut = tostring(name)
            if mut ~= "" and low:find(mut, 1, true) then
                return true
            end
        end
    end
    return false
end

local function _toolNameHasSelectedMut(uuid, sel, selLc)
    local api = G.MutationMachineApi or _G.MutationMachineApi
    if api and type(api.FindPetTool) == "function" then
        local ok, tool = pcall(api.FindPetTool, uuid)
        if ok and tool then
            local label = tostring(tool.Name or tool.DisplayName or "")
            if _labelHasSelectedMut(label, sel, selLc) then
                return true
            end
        end
    end

    -- fallback scan backpack/character (attribute mismatch / FindPetTool miss)
    local Players = game:GetService("Players")
    local LP = Players.LocalPlayer
    local core = select(1, _normUUID(uuid))
    if not core then return false end
    local function scan(container)
        if not container then return false end
        for _, t in ipairs(container:GetChildren()) do
            if t:IsA("Tool") then
                local id = t:GetAttribute("PET_UUID") or t:GetAttribute("UUID") or t:GetAttribute("PetUUID")
                local c = id and (tostring(id):match("{?([0-9a-fA-F%-]+)}?") or tostring(id))
                if c == core then
                    if _labelHasSelectedMut(t.Name or t.DisplayName, sel, selLc) then
                        return true
                    end
                end
            end
        end
        return false
    end
    local char = LP and LP.Character
    local bp = LP and LP:FindFirstChildOfClass("Backpack")
    return scan(char) or scan(bp)
end

local function _mutationsFromPetListView(uuid)
    local PLV = rawget(G, "PetListView") or _G.PetListView
    if type(PLV) ~= "table" or type(PLV.getDatastoreBagIndex) ~= "function" then
        return nil
    end
    local ok, bag, index, helpers = pcall(function()
        return PLV.getDatastoreBagIndex()
    end)
    if not ok then return nil end
    local core, br = _normUUID(uuid)
    local rec = nil
    if type(index) == "table" then
        rec = index[tostring(uuid)] or (core and index[core]) or (br and index[br])
    end
    if not rec and type(bag) == "table" then
        rec = bag[tostring(uuid)] or (core and bag[core]) or (br and bag[br])
    end
    if type(rec) ~= "table" then return nil end
    if type(helpers) == "table" and type(helpers.mutation_names_from_record) == "function" then
        local ok2, names = pcall(helpers.mutation_names_from_record, rec)
        if ok2 and type(names) == "table" then return names end
    end
    return nil
end

local function _uuidHasSelectedMut(uuid, api)
    if not uuid then return false end
    if _isMutDone(uuid) then return true end

    local sel = G.GBXP_MUT_SELECTED or _G.GBXP_MUT_SELECTED or {}
    local selLc = G.GBXP_MUT_SELECTED_LC or _G.GBXP_MUT_SELECTED_LC or {}
    if next(sel) == nil and next(selLc) == nil then
        return false
    end

    if type(api) == "table" and type(api.GetInventorySnapshot) == "function" then
        local ok, snap = pcall(api.GetInventorySnapshot, uuid)
        if ok and type(snap) == "table" and type(snap.mutations) == "table" then
            for _, n0 in ipairs(snap.mutations) do
                if _nameMatchesSelected(n0, sel, selLc) then
                    _markMutDone(uuid)
                    if snap.uuid then _markMutDone(snap.uuid) end
                    return true
                end
            end
        end
    end

    local plvMuts = _mutationsFromPetListView(uuid)
    if type(plvMuts) == "table" then
        for _, n0 in ipairs(plvMuts) do
            if _nameMatchesSelected(n0, sel, selLc) then
                _markMutDone(uuid)
                return true
            end
        end
    end

    if _toolNameHasSelectedMut(uuid, sel, selLc) then
        _markMutDone(uuid)
        return true
    end

    return false
end

local function _pickStageATarget(targetList, api)
    if type(targetList) ~= "table" then return nil end
    local req = api.GetMachineAgeReq()
    local submitted = api.SubmittedCore()

    -- already submitted: only continue if belum HIT (jangan Start ulang pet Mega)
    for _, rec in ipairs(targetList) do
        if rec and rec.uuid and rec.stage == "A" then
            local core = select(1, _normUUID(rec.uuid))
            if submitted and core == submitted then
                if _uuidHasSelectedMut(rec.uuid, api) then
                    return nil
                end
                return rec
            end
        end
    end

    for _, rec in ipairs(targetList) do
        if rec and rec.uuid and rec.stage == "A" then
            local age = tonumber(rec.age or 0) or 0
            if (age + EPS) >= req and not _uuidHasSelectedMut(rec.uuid, api) then
                return rec
            end
        end
    end

    return nil
end

local function _getPlayerData()
    if not DataService then return nil end
    local ok, data = pcall(function()
        return DataService:GetData()
    end)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end

local function _getEquippedPetList()
    local list = {}
    local data = _getPlayerData()
    local petequip = data and data.PetsData and data.PetsData.EquippedPets
    if type(petequip) ~= "table" then return list end

    for _, value in pairs(petequip) do
        local uuid
        if type(value) == "string" then
            uuid = value
        elseif type(value) == "table" then
            uuid = value.UUID or value.Uuid or value.PetUUID or value.uuid
        end
        if uuid then
            list[#list + 1] = uuid
        end
    end
    return list
end

local function _getMaxEquippedPets()
    local data = _getPlayerData()
    local m = data and data.PetsData and data.PetsData.MutableStats
    return math.max(1, tonumber(m and m.MaxEquippedPets) or 3)
end

local function _unequipPetUUID(uuid)
    if not uuid then return end
    local core, br = _normUUID(uuid)
    if type(safeUnequip) == "function" then
        pcall(function() safeUnequip(br or core or uuid) end)
        if core and br and br ~= core then
            pcall(function() safeUnequip(core) end)
        end
        return
    end
    if not PetsService then return end
    pcall(function() PetsService:UnequipPet(br or core or uuid) end)
    if core and br and br ~= core then
        pcall(function() PetsService:UnequipPet(core) end)
    end
end

local function _equipPetUUID(uuid)
    if not uuid then return end
    local core, br = _normUUID(uuid)
    if type(safeEquip) == "function" then
        pcall(function() safeEquip(br or core or uuid) end)
        return
    end
    if not PetsService then return end
    pcall(function() PetsService:EquipPet(br or core or uuid) end)
end

local function _forceUnequipAll(maxSec)
    maxSec = tonumber(maxSec) or 5
    local t0 = os.clock()
    while (os.clock() - t0) < maxSec do
        local list = _getEquippedPetList()
        if #list == 0 then
            return true
        end
        for _, uuid in ipairs(list) do
            _unequipPetUUID(uuid)
        end
        task.wait(0.35)
    end
    return #_getEquippedPetList() == 0
end

local function _teamHasPets(teamSet)
    for _, on in pairs(teamSet or {}) do
        if on then return true end
    end
    return false
end

local function _listTeamUUIDs(teamSet)
    local out, seen = {}, {}
    for k, on in pairs(teamSet or {}) do
        if on then
            local b = _bracedUUID(k)
            if b and not seen[b] then
                seen[b] = true
                out[#out + 1] = b
            end
        end
    end
    table.sort(out)
    return out
end

local Wh = {}
function Wh.mutList(v)
    local out = {}
    if type(v) ~= "table" then return out end
    if #v > 0 then
        for _, n in ipairs(v) do
            local s = tostring(n or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if s ~= "" then out[#out + 1] = s end
        end
        return out
    end
    for k, on in pairs(v) do
        if on == true then
            local s = tostring(k or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if s ~= "" then out[#out + 1] = s end
        end
    end
    return out
end

function Wh.mutSet(list)
    local s = {}
    for _, n in ipairs(Wh.mutList(list)) do
        s[n:lower()] = n
    end
    return s
end

function Wh.mutAdded(before, after)
    local b = Wh.mutSet(before)
    local added = {}
    for _, n in ipairs(Wh.mutList(after)) do
        if not b[n:lower()] then
            added[#added + 1] = n
        end
    end
    return added
end

function Wh.matchSelected(muts)
    local sel = G.GBXP_MUT_SELECTED or _G.GBXP_MUT_SELECTED or {}
    local selLc = G.GBXP_MUT_SELECTED_LC or _G.GBXP_MUT_SELECTED_LC or {}
    for _, n in ipairs(Wh.mutList(muts)) do
        if sel[n] == true or selLc[n:lower()] == true or sel[n:lower()] == true then
            return true
        end
        local nor = _normToken(n)
        if nor ~= "" and (sel[nor] == true or selLc[nor] == true) then
            return true
        end
    end
    return false
end

function Wh.cfg()
    local STATE = rawget(G, "STATE") or _G.STATE
    local w = (STATE and STATE.webhook)
        or (G.STATE and G.STATE.webhook)
        or _G.STATE and _G.STATE.webhook
    if type(w) ~= "table" then return nil end
    if w.enabled ~= true and G.WEBHOOK_ENABLED ~= true and _G.WEBHOOK_ENABLED ~= true then
        return nil
    end
    local url = tostring(w.targetUrl or w.url or w.webhookUrl or G.WEBHOOK_URL or _G.WEBHOOK_URL or "")
    url = url:gsub("^%s+", ""):gsub("%s+$", "")
    if url == "" then return nil end
    w.targetUrl = url
    w.enabled = true
    w.mode = tostring(w.mode or G.WEBHOOK_MODE or "FULL")
    return w
end

function Wh.send(before, after)
    local src = (type(after) == "table" and after) or (type(before) == "table" and before) or {}
    local beforeMut = Wh.mutList(before and before.mutations)
    local afterMut = Wh.mutList(after and after.mutations)
    local added = Wh.mutAdded(beforeMut, afterMut)
    local matchBefore = Wh.matchSelected(beforeMut)
    local matchAfter = Wh.matchSelected(afterMut)
    local match = matchAfter or matchBefore

    -- HIT list → blacklist UUID SEBELUM webhook (wajib, walau webhook off)
    if match then
        _markMutDone(src.uuid)
        _markMutDone(after and after.uuid)
        _markMutDone(before and before.uuid)
    end

    local cfg = Wh.cfg()
    if not cfg then return end
    local Webhook = rawget(G, "AutoKGWebhook") or rawget(_G, "AutoKGWebhook")
        or rawget(G, "Webhook") or _G.Webhook
    if type(Webhook) ~= "table" then return end
    local matchHit = matchAfter
    local payload = {
        tsUnix = os.time(),
        uuid = src.uuid or (before and before.uuid) or (after and after.uuid) or "",
        petType = src.petType or (before and before.petType) or "Pet",
        age = src.age or (before and before.age),
        kg = src.kg or (before and before.kg),
        beforeMutations = beforeMut,
        afterMutations = afterMut,
        addedMutations = added,
        matchSelectedMut = matchHit,
    }
    pcall(function()
        if type(Webhook.SendWith) == "function" then
            Webhook.SendWith(cfg, "MACHINE_MUTATE_CLAIM", payload, {
                mode = tostring(cfg.mode or "FULL"),
                pingEveryone = (matchHit == true),
                dedupeKey = "MACHINE_MUTATE_CLAIM|" .. tostring(
                    src.uuid or (before and before.uuid) or (after and after.uuid) or ""
                ) .. "|" .. tostring(os.time()),
            })
        elseif type(Webhook.Send) == "function" then
            Webhook.Send("MACHINE_MUTATE_CLAIM", payload, {
                pingEveryone = (matchHit == true),
            })
        end
    end)
end

function Wh.waitAfter(api, uuid, timeoutSec, beforeMut)
    timeoutSec = tonumber(timeoutSec) or 8
    local t0 = os.clock()
    while (os.clock() - t0) < timeoutSec do
        if type(api.GetPhase) == "function" and api.GetPhase() == "idle" then
            break
        end
        task.wait(0.2)
    end
    local after = nil
    if uuid and type(api.GetInventorySnapshot) == "function" then
        local beforeSet = Wh.mutSet(beforeMut)
        for _ = 1, 12 do
            after = api.GetInventorySnapshot(uuid)
            if type(after) == "table" then
                local added = Wh.mutAdded(beforeMut, after.mutations)
                if #added > 0 then
                    break
                end
                if next(beforeSet) == nil and type(after.mutations) == "table" and #after.mutations > 0 then
                    break
                end
            end
            task.wait(0.35)
        end
    end
    return after
end

function Wh.claimAndNotify(api)
    if not api or type(api.ClaimMutatedPet) ~= "function" then return end
    local before = nil
    if type(api.GetSubmittedSnapshot) == "function" then
        pcall(function()
            before = api.GetSubmittedSnapshot()
        end)
    end

    -- kalau pet yang di-claim SUDAH match selected (seharusnya tidak masuk), blacklist sekarang
    if before and Wh.matchSelected(before.mutations) then
        _markMutDone(before.uuid)
    end

    api.ClaimMutatedPet()
    local uuid = before and before.uuid
    local after = Wh.waitAfter(api, uuid, 8, before and before.mutations)

    -- setelah claim pet sering auto-equip di character → lepas dulu
    pcall(function()
        if uuid then
            _unequipPetUUID(uuid)
        end
        _forceUnequipAll(4)
    end)
    pcall(function()
        if type(api.UnequipAllGardenPets) == "function" then
            api.UnequipAllGardenPets(3)
        end
    end)

    -- mark HIT segera setelah snapshot (jangan tunggu webhook cfg)
    if after and Wh.matchSelected(after.mutations) then
        _markMutDone(after.uuid or uuid)
        _markMutDone(uuid)
    elseif before and Wh.matchSelected(before.mutations) then
        _markMutDone(uuid)
    end

    Wh.send(before, after)
end

local function _setClaimBusy(on)
    _claimBusy = (on == true)
    G.__MACHINE_CLAIM_BUSY = _claimBusy or nil
    _G.__MACHINE_CLAIM_BUSY = G.__MACHINE_CLAIM_BUSY
end

local function _runClaimWithTeam(api, teamSet)
    local token = tostring(os.clock()) .. "_" .. tostring(math.random(1, 1e9))
    _claimSessionToken = token
    _setClaimBusy(true)

    task.spawn(function()
        local targets = _listTeamUUIDs(teamSet)
        local maxEq = math.min(_getMaxEquippedPets(), MAX_CLAIM_TEAM, #targets)

        _forceUnequipAll(5)

        for i = 1, maxEq do
            _equipPetUUID(targets[i])
        end

        task.wait(CLAIM_PRE_DELAY)

        if _claimSessionToken == token then
            Wh.claimAndNotify(api)
        end

        task.wait(CLAIM_POST_DELAY)

        -- trigger UUID remap (pola agebreak_remap) setelah claim
        local remap = rawget(G, "MutationMachineRemap") or rawget(_G, "MutationMachineRemap")
        if remap and type(remap.NotifyClaim) == "function" then
            pcall(function() remap.NotifyClaim() end)
        end

        for i = 1, maxEq do
            _unequipPetUUID(targets[i])
        end

        if _claimSessionToken == token then
            _claimSessionToken = nil
            _setClaimBusy(false)
        end
    end)
end

function M.Tick(ctx)
    if not M.ShouldRunMachine() then return end

    M.SyncMutSelected()

    local api = M.GetApi()
    if not api then return end

    ctx = ctx or {}
    local targetList = ctx.targetList

    local machine = api.GetMachine()
    local phase = api.GetPhase(machine)

    if phase == "claim" then
        if M.IsClaimBusy() or _claimSessionToken then
            return
        end

        local teamSet = M.GetClaimTeamBefore()
        if not _teamHasPets(teamSet) then
            Wh.claimAndNotify(api)
            task.delay(0.8, function()
                local remap = rawget(G, "MutationMachineRemap") or rawget(_G, "MutationMachineRemap")
                if remap and type(remap.NotifyClaim) == "function" then
                    pcall(function() remap.NotifyClaim() end)
                end
            end)
            return
        end

        _runClaimWithTeam(api, teamSet)
        return
    end

    if _claimSessionToken == nil and not _claimBusy then
        _setClaimBusy(false)
    end

    if phase == "running" then
        return
    end

    -- Stuck / leftover submitted pet: keep retrying Start + afford check
    -- TAPI: kalau pet submitted sudah punya mutasi selected → CANCEL, jangan Start (biar tidak ke-roll lagi)
    if phase == "submitted" then
        local subUuid = api.SubmittedCore and api.SubmittedCore()
        local snap = nil
        if type(api.GetSubmittedSnapshot) == "function" then
            pcall(function() snap = api.GetSubmittedSnapshot() end)
        end
        local alreadyHit = false
        if snap and Wh.matchSelected(snap.mutations) then
            alreadyHit = true
            _markMutDone(snap.uuid or subUuid)
        elseif subUuid and _uuidHasSelectedMut(subUuid, api) then
            alreadyHit = true
        end
        if alreadyHit then
            if type(api.CancelMachine) == "function" then
                pcall(function() api.CancelMachine() end)
            else
                pcall(function() api.Fire("CancelMachine", true) end)
            end
            return
        end
        if type(api.StartMachineReliable) == "function" then
            api.StartMachineReliable({ retries = 3, waitSec = 2.5 })
        else
            api.StartMachine()
        end
        return
    end

    -- idle: submit stage-A then immediately start (atomic)
    local target = _pickStageATarget(targetList, api)
    if not target or not target.uuid then return end

    local req = api.GetMachineAgeReq()
    local age = tonumber(target.age or 0) or 0
    if (age + EPS) < req then return end

    local uuid = tostring(target.uuid)
    -- hard gate: pet sudah HIT / punya mutasi selected → jangan submit
    if _uuidHasSelectedMut(uuid, api) then
        return
    end

    -- sebelum submit: pastikan tidak ada pet garden yang masih equip (bekas claim)
    _forceUnequipAll(4)
    if type(api.UnequipAllGardenPets) == "function" then
        pcall(function() api.UnequipAllGardenPets(3) end)
    end
    if type(safeUnequip) == "function" then
        pcall(function() safeUnequip(uuid) end)
    else
        _unequipPetUUID(uuid)
    end
    task.wait(0.2)

    -- tunggu tool target ada di backpack/character sebelum SubmitAndStart
    if type(api.WaitPetTool) == "function" then
        local tool = api.WaitPetTool(uuid, 6)
        if not tool then
            return
        end
    end

    if type(api.SubmitAndStart) == "function" then
        api.SubmitAndStart(uuid, { retries = 4, waitSec = 3 })
    else
        api.SubmitHeldPet(uuid)
    end
end

function M.Start(reason)
    M.SetEnabled(true)
    M.SyncMutSelected()
end

function M.Stop(reason)
    M.SetEnabled(false)
    _claimSessionToken = nil
    _setClaimBusy(false)
end

function M.IsRunning()
    return M.IsEnabled() and M.IsNmlvlActive()
end

G.MutationMachineLoop = M
_G.MutationMachineLoop = M

return M

        end,
        required = true,
    },
    {
        key = "mutation_machine_remap",
        name = "mutation_machine_remap",
        factory = function()
            -- mutation_machine_remap.lua
-- Pola sama seperti agebreak_remap.lua (auto_hatch):
-- Setelah submit + claim Mutation Machine, UUID sering berubah.
-- Remap selected.gbxp[oldUuid] -> selected.gbxp[newUuid] via inventory diff.

local M = {}

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local DataService
pcall(function()
    DataService = require(ReplicatedStorage.Modules.DataService)
end)

local POLL_SEC = 1.0
local CLAIM_RETRY_SEC = 15
local CLAIM_RETRY_INTERVAL = 0.4
local PENDING_MAX_AGE_SEC = 3600
local REMATCH_MIN_SCORE = 50

local G = (getgenv and getgenv()) or _G

local running = false
local lastSubmittedCore = nil
local lastPetReady = false
local resolveToken = 0

--------------------------------------------------
-- UTIL
--------------------------------------------------
local function normUUID(u)
    if u == nil then return nil, nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    if core == "" then return nil, nil end
    return core, "{" .. core .. "}"
end

local function lower(s)
    return string.lower(tostring(s or ""))
end

local function getProfile()
    if type(DataService) ~= "table" then
        pcall(function()
            DataService = require(ReplicatedStorage.Modules.DataService)
        end)
    end
    if type(DataService) ~= "table" or type(DataService.GetData) ~= "function" then
        return nil
    end
    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if ok and type(profile) == "table" then
        return profile
    end
    return nil
end

local function getBag(profile)
    profile = profile or getProfile()
    local bag = profile
        and profile.PetsData
        and profile.PetsData.PetInventory
        and profile.PetsData.PetInventory.Data
    if type(bag) == "table" then
        return bag
    end
    return nil
end

local function getMachine(profile)
    profile = profile or getProfile()
    if type(profile) == "table" and type(profile.PetMutationMachine) == "table" then
        return profile.PetMutationMachine
    end
    local api = rawget(G, "MutationMachineApi") or rawget(_G, "MutationMachineApi")
    if api and type(api.GetMachine) == "function" then
        local ok, machine = pcall(function() return api.GetMachine() end)
        if ok and type(machine) == "table" then
            return machine
        end
    end
    return nil
end

local function snapshotBagCores(bag)
    local out = {}
    if type(bag) ~= "table" then return out end
    for rawUUID in pairs(bag) do
        local core = normUUID(rawUUID)
        if core then
            out[core] = true
        end
    end
    return out
end

local function coresToList(cores)
    local list = {}
    if type(cores) ~= "table" then return list end
    for core in pairs(cores) do
        list[#list + 1] = tostring(core)
    end
    return list
end

local function listToCores(list)
    local out = {}
    if type(list) ~= "table" then return out end
    for k, v in pairs(list) do
        if v == true or v == 1 then
            out[tostring(k)] = true
        elseif type(v) == "string" and v ~= "" then
            out[v] = true
        elseif type(k) == "number" and type(v) == "string" then
            out[v] = true
        end
    end
    return out
end

local function petTypeFromRec(rec)
    if type(rec) ~= "table" then return nil end
    local pd = rec.PetData or rec.Data or {}
    return rec.Type or rec.PetType or rec.Name
        or pd.Type or pd.PetType or pd.Name
end

local function ageFromRec(rec)
    if type(rec) ~= "table" then return nil end
    local pd = rec.PetData or rec.Data or {}
    for _, src in ipairs({ rec, pd }) do
        for _, k in ipairs({ "Age", "age", "Level", "level" }) do
            local v = src[k]
            if type(v) == "number" then return v end
            if type(v) == "string" then
                local n = tonumber(v:gsub(",", "."))
                if n then return n end
            end
        end
    end
    return nil
end

local function kgFromRec(rec)
    if type(rec) ~= "table" then return nil end
    local pd = rec.PetData or rec.Data or {}
    for _, src in ipairs({ rec, pd }) do
        for _, k in ipairs({ "Weight", "weight", "KG", "kg", "W", "w", "WeightNow", "currentWeight" }) do
            local v = src[k]
            if type(v) == "number" then return v end
        end
    end
    return nil
end

local function fingerprintFromSubmitted(sp)
    if type(sp) ~= "table" then return nil end
    local core, br = normUUID(sp.UUID or sp.uuid or sp.PetUUID or sp.Id
        or (type(sp.PetData) == "table" and (sp.PetData.UUID or sp.PetData.uuid)))
    if not core then return nil end

    return {
        oldCore = core,
        oldUuid = br or ("{" .. core .. "}"),
        petType = tostring(sp.PetType or sp.Type or sp.Name
            or (type(sp.PetData) == "table" and sp.PetData.PetType) or ""),
        oldAge = tonumber(ageFromRec(sp)) or 0,
        oldKg = tonumber(kgFromRec(sp)) or 0,
    }
end

local function getSelectedGbxp()
    local selected = rawget(G, "selected") or rawget(_G, "selected")
    if type(selected) ~= "table" then
        selected = {}
        G.selected = selected
        _G.selected = selected
    end
    selected.gbxp = selected.gbxp or {}
    return selected.gbxp, selected
end

local function isSelectedUUID(uuidCore, uuidBr)
    local function inSet(setTbl)
        if type(setTbl) ~= "table" then return false end
        if uuidBr and setTbl[uuidBr] then return true end
        if uuidCore and setTbl[uuidCore] then return true end
        if uuidCore and setTbl["{" .. uuidCore .. "}"] then return true end
        return false
    end

    local gbxp = getSelectedGbxp()
    if inSet(gbxp) then return true end

    local manual = rawget(G, "GBXP_MANUAL_SELECTED") or rawget(_G, "GBXP_MANUAL_SELECTED")
    if inSet(manual) then return true end

    return false
end

local function removeUuidFromSet(setTbl, oldCore, oldBr)
    if type(setTbl) ~= "table" or not oldCore then return end
    local kill = {}
    for k in pairs(setTbl) do
        local core = select(1, normUUID(k))
        if core == oldCore or k == oldBr or k == oldCore then
            kill[#kill + 1] = k
        end
    end
    for _, k in ipairs(kill) do
        setTbl[k] = nil
    end
end

local function addUuidToSet(setTbl, newUuid, newCore)
    if type(setTbl) ~= "table" then return end
    local br = newUuid or (newCore and ("{" .. newCore .. "}"))
    if br then setTbl[br] = true end
    if newCore then setTbl[newCore] = true end
end

local function keepGbxpSelectedUuid(uuid, core)
    local gbxp = getSelectedGbxp()
    addUuidToSet(gbxp, uuid, core)
    local manual = rawget(G, "GBXP_MANUAL_SELECTED") or rawget(_G, "GBXP_MANUAL_SELECTED")
    if type(manual) ~= "table" then
        manual = {}
        G.GBXP_MANUAL_SELECTED = manual
        _G.GBXP_MANUAL_SELECTED = manual
    end
    addUuidToSet(manual, uuid, core)
end

local function getPending()
    local STATE = rawget(G, "STATE") or rawget(_G, "STATE")
    if type(STATE) ~= "table" then return nil end
    local pc = STATE._gbxpMutPending
    if type(pc) ~= "table" or not pc.oldCore then return nil end
    return pc, STATE
end

local function savePending(pc)
    local STATE = rawget(G, "STATE") or rawget(_G, "STATE")
    if type(STATE) ~= "table" then return end
    STATE._gbxpMutPending = pc
    local StateMod = rawget(G, "State") or rawget(_G, "State")
    if StateMod and type(StateMod.save) == "function" then
        pcall(function() StateMod.save() end)
    elseif type(rawget(G, "autoSave")) == "function" then
        pcall(function() G.autoSave() end)
    end
end

local function clearPending()
    local _, STATE = getPending()
    if type(STATE) == "table" then
        STATE._gbxpMutPending = nil
    end
    local StateMod = rawget(G, "State") or rawget(_G, "State")
    if StateMod and type(StateMod.save) == "function" then
        pcall(function() StateMod.save() end)
    end
end

--------------------------------------------------
-- MATCH + REMAP
--------------------------------------------------
local function scoreCandidate(rec, pc)
    local ptype = petTypeFromRec(rec)
    local want = tostring(pc.petType or "")
    if want ~= "" and lower(ptype) ~= lower(want) then
        return -1
    end

    -- Mutation machine: age sering reset → jangan syarat age naik
    local score = 100
    local age = tonumber(ageFromRec(rec)) or 0
    local oldAge = tonumber(pc.oldAge) or 0
    local kg = tonumber(kgFromRec(rec))
    local oldKg = tonumber(pc.oldKg) or 0

    -- bonus: age rendah (baru keluar machine) atau dekat oldAge
    score = score + math.max(0, 30 - age)
    if oldAge > 0 then
        score = score + math.max(0, 20 - math.min(20, math.abs(age - oldAge) * 0.2))
    end
    if oldKg > 0 and kg and kg > 0 then
        score = score + math.max(0, 25 - math.min(25, math.abs(kg - oldKg) * 0.1))
    end

    return score
end

local function findNewUuidCandidates(bag, baselineCores, pc)
    if type(bag) ~= "table" or type(baselineCores) ~= "table" then
        return {}
    end

    local candidates = {}
    for rawUUID, rec in pairs(bag) do
        if type(rec) == "table" then
            local core, br = normUUID(rawUUID)
            if core and not baselineCores[core] and core ~= pc.oldCore then
                local score = scoreCandidate(rec, pc)
                if score >= REMATCH_MIN_SCORE then
                    candidates[#candidates + 1] = {
                        core = core,
                        uuid = br or ("{" .. core .. "}"),
                        score = score,
                        age = ageFromRec(rec),
                        ptype = petTypeFromRec(rec),
                    }
                end
            end
        end
    end

    table.sort(candidates, function(a, b)
        if a.score ~= b.score then return a.score > b.score end
        return (a.age or 0) < (b.age or 0)
    end)

    return candidates
end

local function applyRemap(pc, newUuid, newCore)
    local gbxp, selected = getSelectedGbxp()
    local oldCore = pc.oldCore or select(1, normUUID(pc.oldUuid or pc.oldBr))
    local oldBr = pc.oldUuid or pc.oldBr or (oldCore and ("{" .. oldCore .. "}"))

    local sets = { gbxp }
    local manual = rawget(G, "GBXP_MANUAL_SELECTED") or rawget(_G, "GBXP_MANUAL_SELECTED")
    if type(manual) == "table" then
        sets[#sets + 1] = manual
    end

    for _, setTbl in ipairs(sets) do
        removeUuidFromSet(setTbl, oldCore, oldBr)
        addUuidToSet(setTbl, newUuid, newCore)
    end

    -- kalau old UUID sudah HIT list mutasi, ikut-kan ke UUID baru
    do
        local done = rawget(G, "__MACHINE_MUT_DONE") or rawget(_G, "__MACHINE_MUT_DONE")
        if type(done) ~= "table" then
            done = {}
            G.__MACHINE_MUT_DONE = done
            _G.__MACHINE_MUT_DONE = done
        end
        local oldHit = (oldCore and done[oldCore] == true)
            or (oldBr and done[oldBr] == true)
        if oldHit and newCore then
            done[newCore] = true
            done["{" .. newCore .. "}"] = true
            if type(newUuid) == "string" and newUuid ~= "" then
                done[newUuid] = true
            end
        end
    end

    selected.gbxp = gbxp
    G.selected = selected
    _G.selected = selected
    G.GBXP_MANUAL_SELECTED = manual
    _G.GBXP_MANUAL_SELECTED = manual

    clearPending()

    -- grace: jangan di-prune reconcile sebelum listPets sync
    G.__GBXP_REMAP_GRACE = {
        core = newCore,
        br = newUuid or (newCore and ("{" .. newCore .. "}")),
        untilAt = tick() + 20,
    }
    _G.__GBXP_REMAP_GRACE = G.__GBXP_REMAP_GRACE

    _G.__AUTOKG_DIRTY = true
    G.__AUTOKG_DIRTY = true
    -- dedicated flag: footer watcher jangan "makan" dirty sebelum GBXP refresh aman
    _G.__GBXP_REMAP_DIRTY = true
    G.__GBXP_REMAP_DIRTY = true

    local StateMod = rawget(G, "State") or rawget(_G, "State")
    if StateMod and type(StateMod.save) == "function" then
        pcall(function() StateMod.save() end)
    end

    print(("[MutMachineRemap] OK %s -> %s (%s)"):format(
        tostring(oldBr),
        tostring(newUuid),
        tostring(pc.petType)
    ))

    return true
end

local function tryResolveClaim(pc)
    if pc.wasSelected ~= true then
        clearPending()
        return true
    end

    local baseline = listToCores(pc.preClaimSnapshot)
    if next(baseline) == nil then
        baseline = listToCores(pc.bagCores or pc.bagSnapshot)
    end
    if next(baseline) == nil then
        -- fallback: snapshot sekarang minus pet yang baru muncul sulit;
        -- ambil bag sekarang tapi exclude oldCore saja → match tipe di pet "baru"
        -- lebih aman: tunggu sampai bag snapshot sempat tersimpan
        return false
    end

    local bag = getBag()
    if not bag then return false end

    -- UUID tidak berubah
    local coresNow = snapshotBagCores(bag)
    if coresNow[pc.oldCore] then
        local gbxp = getSelectedGbxp()
        addUuidToSet(gbxp, pc.oldUuid or pc.oldBr, pc.oldCore)
        local manual = rawget(G, "GBXP_MANUAL_SELECTED") or rawget(_G, "GBXP_MANUAL_SELECTED")
        if type(manual) == "table" then
            addUuidToSet(manual, pc.oldUuid or pc.oldBr, pc.oldCore)
            G.GBXP_MANUAL_SELECTED = manual
            _G.GBXP_MANUAL_SELECTED = manual
        end
        G.__GBXP_REMAP_GRACE = {
            core = pc.oldCore,
            br = pc.oldUuid or pc.oldBr or ("{" .. tostring(pc.oldCore) .. "}"),
            untilAt = tick() + 20,
        }
        _G.__GBXP_REMAP_GRACE = G.__GBXP_REMAP_GRACE
        clearPending()
        _G.__AUTOKG_DIRTY = true
        G.__AUTOKG_DIRTY = true
        _G.__GBXP_REMAP_DIRTY = true
        G.__GBXP_REMAP_DIRTY = true
        return true
    end

    local candidates = findNewUuidCandidates(bag, baseline, pc)
    if #candidates == 0 then
        return false
    end

    local best = candidates[1]
    local second = candidates[2]
    -- longgar sedikit dari agebreak (8) karena mut machine lebih noisy
    if second and (best.score - second.score) < 5 then
        return false
    end

    return applyRemap(pc, best.uuid, best.core)
end

local function beginClaimResolve(pc)
    if type(pc) ~= "table" then return end
    pc.claimStartedAt = tick()
    savePending(pc)

    resolveToken += 1
    local token = resolveToken

    task.spawn(function()
        local deadline = tick() + CLAIM_RETRY_SEC
        while tick() < deadline do
            if token ~= resolveToken then
                return
            end
            local cur = getPending()
            if type(cur) ~= "table" then
                return
            end
            if tryResolveClaim(cur) then
                return
            end
            task.wait(CLAIM_RETRY_INTERVAL)
        end
        warn("[MutMachineRemap] timeout — pending dibersihkan (pet mungkin unselected)")
        clearPending()
    end)
end

--------------------------------------------------
-- MACHINE WATCH
--------------------------------------------------
local function upsertPendingFromSubmitted(sp, bag)
    local fp = fingerprintFromSubmitted(sp)
    if not fp then return end

    -- GBXP: machine pet selalu dianggap target selected (manual/auto)
    local wasSelected = true

    local pc = getPending()
    if type(pc) == "table" and pc.oldCore == fp.oldCore and pc.claimStartedAt == nil then
        pc.petType = fp.petType
        pc.oldAge = fp.oldAge
        pc.oldKg = fp.oldKg
        pc.wasSelected = true
        if type(bag) == "table" then
            local snap = coresToList(snapshotBagCores(bag))
            if #snap > 0 then
                pc.bagCores = snap
                pc.bagSnapshot = snap
            end
        end
        -- pastikan selected ikut
        keepGbxpSelectedUuid(fp.oldUuid, fp.oldCore)
        savePending(pc)
        return
    end

    if type(pc) == "table" and pc.claimStartedAt ~= nil then
        return
    end

    local snap = type(bag) == "table" and coresToList(snapshotBagCores(bag)) or {}

    savePending({
        oldCore = fp.oldCore,
        oldBr = fp.oldUuid,
        oldUuid = fp.oldUuid,
        petType = fp.petType,
        oldAge = fp.oldAge,
        oldKg = fp.oldKg,
        wasSelected = wasSelected,
        bagCores = snap,
        bagSnapshot = snap,
        preClaimSnapshot = nil,
        submittedAt = os.time(),
        claimStartedAt = nil,
    })

    keepGbxpSelectedUuid(fp.oldUuid, fp.oldCore)
end

local function onMachineTick(machine, bag)
    machine = type(machine) == "table" and machine or {}
    local sp = machine.SubmittedPet
    local submittedCore = nil
    if type(sp) == "table" then
        local fp = fingerprintFromSubmitted(sp)
        submittedCore = fp and fp.oldCore or nil
    end

    local petReady = machine.PetReady == true

    if submittedCore and type(sp) == "table" then
        upsertPendingFromSubmitted(sp, bag)

        -- seperti agebreak: snapshot tepat sebelum claim
        if petReady and not lastPetReady then
            local pc = getPending()
            if type(pc) == "table" and pc.oldCore == submittedCore and pc.claimStartedAt == nil then
                pc.preClaimSnapshot = coresToList(snapshotBagCores(bag))
                savePending(pc)
            end
        end
    end

    -- SubmittedPet hilang → mulai resolve (retry loop)
    if lastSubmittedCore and not submittedCore then
        local pc = getPending()
        if type(pc) == "table" and tostring(pc.oldCore) == tostring(lastSubmittedCore) then
            if pc.claimStartedAt == nil then
                beginClaimResolve(pc)
            end
        end
    end

    lastSubmittedCore = submittedCore
    lastPetReady = petReady

    local pc = getPending()
    if type(pc) == "table" and pc.submittedAt then
        if (os.time() - tonumber(pc.submittedAt)) > PENDING_MAX_AGE_SEC then
            clearPending()
        end
    end
end

local function tick()
    local profile = getProfile()
    if not profile then return end
    local bag = getBag(profile)
    onMachineTick(getMachine(profile), bag)
end

function M.GetPending()
    return getPending()
end

function M.NotifyClaim()
    local pc = getPending()
    if type(pc) == "table" and pc.claimStartedAt == nil then
        -- JANGAN overwrite baseline dengan bag post-claim (UUID baru sudah masuk → remap gagal).
        -- Isi snapshot hanya jika masih kosong DAN oldCore masih ada di bag (benar-benar pre-claim).
        local hasPre = pc.preClaimSnapshot and next(listToCores(pc.preClaimSnapshot)) ~= nil
        local hasBag = pc.bagCores and next(listToCores(pc.bagCores)) ~= nil
        if not hasPre and not hasBag then
            local bag = getBag()
            local cores = snapshotBagCores(bag)
            if pc.oldCore and cores[pc.oldCore] then
                pc.preClaimSnapshot = coresToList(cores)
                savePending(pc)
            end
        end
        beginClaimResolve(pc)
    end
end

function M.Start()
    if running then return M end
    running = true

    task.spawn(function()
        while running do
            pcall(tick)
            task.wait(POLL_SEC)
        end
    end)

    pcall(function()
        if type(DataService.GetPathSignal) == "function" then
            local sig = DataService:GetPathSignal("PetMutationMachine/SubmittedPet")
            if sig and type(sig.Connect) == "function" then
                sig:Connect(function()
                    task.defer(tick)
                end)
            end
        end
    end)

    -- rejoin: pending ada, machine kosong → resolve
    task.defer(function()
        task.wait(2.5)
        local pc = getPending()
        if type(pc) ~= "table" or pc.wasSelected ~= true then return end
        local machine = getMachine()
        local hasSubmitted = type(machine) == "table" and type(machine.SubmittedPet) == "table"
        if not hasSubmitted and pc.claimStartedAt == nil then
            beginClaimResolve(pc)
        elseif hasSubmitted then
            -- masih di machine: pastikan selected + backup manual
            keepGbxpSelectedUuid(pc.oldUuid or pc.oldBr, pc.oldCore)
            _G.__AUTOKG_DIRTY = true
        end
    end)

    return M
end

function M.Stop()
    running = false
end

G.MutationMachineRemap = M
_G.MutationMachineRemap = M

return M

