local function buildEventList()
	table.clear(EVENT_INFO)

	local tmp = {}
	for shopName, shopTbl in pairs(EventShopData) do
		if type(shopTbl) == "table" then
			for itemName, info in pairs(shopTbl) do
				if type(info) == "table" and info.DisplayInShop ~= false then
					local name  = info.SeedName or itemName
					local order = info.LayoutOrder or 0
					local price = info.Price or info.FallbackPrice or 0
					local currency = info.SpecialCurrencyType or "Sheckles"
					local prev = EVENT_INFO[name]
					if type(prev) == "table" then
						prev.byShop = prev.byShop or {}
						prev.byShop[shopName] = { price = price, currency = currency }
					else
						EVENT_INFO[name] = {
							price       = price,
							currency    = currency,
							layoutOrder = order,
							shopName    = shopName,
							purchaseId  = info.PurchaseID,
							itemType    = info.ItemType,
							byShop      = {
								[shopName] = { price = price, currency = currency },
							},
						}
					end

					tmp[#tmp+1] = { name = name, order = order }
				end
			end
		end
	end

	table.sort(tmp, function(a, b)
		if a.order == b.order then return tostring(a.name) < tostring(b.name) end
		return a.order < b.order
	end)

	local names = {}
	local seen = {}
	for _, rec in ipairs(tmp) do
		local name = rec.name
		if not seen[name] then
			seen[name] = true
			names[#names + 1] = name
		end
	end

	dprint("buildEventList:", #names, "sample:", names[1])
	return names
end

