local function eventShopColor(shopName)
	local s = tostring(shopName or "")
	local h = 0
	for i = 1, #s do
		h = (h * 33 + string.byte(s, i)) % 2147483647
	end
	return EVENT_SHOP_PALETTE[(h % #EVENT_SHOP_PALETTE) + 1]
end

local function buildTravelingMerchantList()
	table.clear(TM_INFO)

	local tmp = {}
	for merchantName, merchantInfo in pairs(TravelingMerchantData) do
		if type(merchantInfo) == "table" and type(merchantInfo.ShopData) == "table" then
			local merchantTitle = tostring(merchantInfo.Title or merchantName)
			for itemName, info in pairs(merchantInfo.ShopData) do
				if type(info) == "table" and info.DisplayInShop ~= false then
					local name = tostring(itemName)
					if name ~= "" then
						local order = info.LayoutOrder or 0
						local prev = TM_INFO[name]
						if not prev then
							TM_INFO[name] = {
								price       = info.Price or info.FallbackPrice or 0,
								currency    = info.SpecialCurrencyType or "Sheckles",
								layoutOrder = order,
								merchant    = merchantTitle,
								itemType    = info.ItemType,
								rarity      = info.SeedRarity or info.Rarity,
							}
							tmp[#tmp + 1] = { name = name, order = order }
						elseif (tonumber(order) or 0) < (tonumber(prev.layoutOrder) or 0) then
							prev.layoutOrder = order
						end
					end
				end
			end
		end
	end

	table.sort(tmp, function(a, b)
		if a.order == b.order then return tostring(a.name) < tostring(b.name) end
		return a.order < b.order
	end)

	local names = {}
	for i, rec in ipairs(tmp) do
		names[i] = rec.name
	end

	dprint("buildTravelingMerchantList:", #names, "sample:", names[1])
	return names
end

local function clampGardenCoinQty(v)
	local n = math.floor(tonumber(v) or 1)
	if n < 1 then n = 1 end
	if n > 20 then n = 20 end
	return n
end

local function gcStripTier(s)
	s = tostring(s or "")
	s = s:gsub("%s+[Dd]eluxe%s*$", "")
	s = s:gsub("%s+%+%+%s*$", "")
	s = s:gsub("%s+%+%s*$", "")
	return s
end

local function gcTierRank(key)
	key = tostring(key or "")
	if key:find("[Dd]eluxe%s*$") then return 4 end
	if key:find("%+%+") then return 3 end
	if key:find("%+") then return 2 end
	return 1
end

local function buildGardenCoinList()
	table.clear(GC_INFO)
	table.clear(GC_FAMILY)

	local qty = clampGardenCoinQty(GARDEN_COIN_BUY_QTY)
	GARDEN_COIN_BUY_QTY = qty

	for itemKey, info in pairs(GardenCoinShopData) do
		if type(info) == "table" and info.DisplayInShop ~= false then
			local key = tostring(itemKey)
			if key ~= "" then
				local order = info.LayoutOrder or 0
				local displayName = tostring(info.SeedName or key)
				local familyKey = gcStripTier(key)
				if familyKey == "" then familyKey = key end
				local rec = {
					price = info.Price or info.FallbackPrice or 0,
					currency = info.SpecialCurrencyType or "GardenCoins",
					layoutOrder = order,
					lifetimeLimit = info.LifetimeLimit,
					lifetimeLimitDependancy = info.LifetimeLimitDependancy,
					displayName = displayName,
					itemType = info.ItemType,
					rarity = info.SeedRarity or info.Rarity,
					itemKey = key,
					familyKey = familyKey,
					tier = gcTierRank(key),
				}
				GC_INFO[key] = rec
				if displayName ~= "" and displayName ~= key then
					GC_INFO[displayName] = rec
				end

				local fam = GC_FAMILY[familyKey]
				if not fam then
					fam = {
						keys = {},
						name = gcStripTier(displayName),
						order = order,
					}
					if fam.name == "" then fam.name = displayName end
					GC_FAMILY[familyKey] = fam
				end
				fam.keys[#fam.keys + 1] = key
				if order < fam.order then fam.order = order end
				if rec.tier == 1 then
					fam.name = gcStripTier(displayName)
				end
			end
		end
	end

	local tmp = {}
	for familyKey, fam in pairs(GC_FAMILY) do
		table.sort(fam.keys, function(a, b)
			local ia = GC_INFO[a]
			local ib = GC_INFO[b]
			local ta = (ia and ia.tier) or 1
			local tb = (ib and ib.tier) or 1
			if ta == tb then
				return ((ia and ia.layoutOrder) or 0) < ((ib and ib.layoutOrder) or 0)
			end
			return ta < tb
		end)
		tmp[#tmp + 1] = {
			key = familyKey,
			name = tostring(fam.name or familyKey),
			order = fam.order or 0,
		}
	end

	table.sort(tmp, function(a, b)
		if a.order == b.order then return tostring(a.name) < tostring(b.name) end
		return a.order < b.order
	end)

	dprint("buildGardenCoinList families:", #tmp, "sample:", tmp[1] and tmp[1].key)
	return tmp
end

local function buildSeasonPassList()
	table.clear(SP_INFO)

	local shopItems = SeasonPassData and SeasonPassData.ShopItems
	if type(shopItems) ~= "table" then
		SeasonPassListSeason = SeasonPassData and SeasonPassData.CurrentSeason
		dprint("buildSeasonPassList: ShopItems missing, season=", tostring(SeasonPassListSeason))
		return {}
	end

	local tmp = {}
	for itemKey, info in pairs(shopItems) do
		if type(info) == "table" and info.LayoutOrder ~= -1 and info.RobuxOnly ~= true then
			local key = tostring(itemKey)
			if key ~= "" then
				local order = info.LayoutOrder or 0
				local displayName = tostring(info.DisplayName or key)
				SP_INFO[key] = {
					price = info.Price or 0,
					currency = "PassPoints",
					layoutOrder = order,
					displayName = displayName,
					itemType = info.Type,
					rarity = info.Rarity,
					robuxOnly = info.RobuxOnly == true,
				}
				tmp[#tmp + 1] = {
					key = key,
					name = displayName,
					order = order,
				}
			end
		end
	end

	table.sort(tmp, function(a, b)
		if a.order == b.order then return tostring(a.name) < tostring(b.name) end
		return a.order < b.order
	end)

	SeasonPassListSeason = SeasonPassData and SeasonPassData.CurrentSeason
	dprint("buildSeasonPassList:", #tmp, "season=", tostring(SeasonPassListSeason), "sample:", tmp[1] and tmp[1].key)
	return tmp
end

local function buildCosmeticList()
	table.clear(COS_INFO)
	local tmp = {}

	local function addEntry(itemKey, info, kind, category)
		if type(info) ~= "table" or info.LayoutOrder == -1 then return end
		local key = tostring(itemKey)
		if key == "" or COS_INFO[key] then return end

		local order = info.LayoutOrder or 0
		local displayName = tostring(
			info.CosmeticName or info.CrateName or info.DisplayName or info.FenceName or key
		)
		COS_INFO[key] = {
			price = info.Price or 0,
			currency = "Sheckles",
			layoutOrder = order,
			displayName = displayName,
			kind = kind, -- item | crate | fence
			category = category, -- Cosmetics | Fences
			fenceName = info.FenceName,
			lifetimeLimit = info.LifetimeLimit,
		}
		tmp[#tmp + 1] = {
			key = key,
			name = displayName,
			order = order,
		}
	end

	local tabs = CosmeticShopTabData and CosmeticShopTabData.Tabs
	if type(tabs) == "table" then
		for category, tab in pairs(tabs) do
			if type(tab) == "table" then
				if type(tab.Items) == "table" then
					for itemKey, info in pairs(tab.Items) do
						addEntry(itemKey, info, "item", tostring(category))
					end
				end
				if type(tab.Crates) == "table" then
					for itemKey, info in pairs(tab.Crates) do
						addEntry(itemKey, info, "crate", tostring(category))
					end
				end
				if type(tab.Fences) == "table" then
					for itemKey, info in pairs(tab.Fences) do
						addEntry(itemKey, info, "fence", tostring(category))
					end
				end
			end
		end
	end

	-- Fallback: flat CosmeticItemShopData
	if #tmp == 0 and type(CosmeticItemShopData) == "table" then
		for itemKey, info in pairs(CosmeticItemShopData) do
			addEntry(itemKey, info, "item", "Cosmetics")
		end
	end

	table.sort(tmp, function(a, b)
		if a.order == b.order then return tostring(a.name) < tostring(b.name) end
		return a.order < b.order
	end)

	dprint("buildCosmeticList:", #tmp, "sample:", tmp[1] and tmp[1].key)
	return tmp
end

local function ensureListsBuilt()
	if not SeedItems then
		local ok, res = pcall(buildSeedList)
		SeedItems = (ok and type(res) == "table") and res or {}
		if not ok then dwarn("buildSeedList error:", res) end
	end
	if not EggItems then
		local ok, res = pcall(buildEggList)
		EggItems = (ok and type(res) == "table") and res or {}
		if not ok then dwarn("buildEggList error:", res) end
	end
	if not GearItems then
		local ok, res = pcall(buildGearList)
		GearItems = (ok and type(res) == "table") and res or {}
		if not ok then dwarn("buildGearList error:", res) end
	end
	if not EventItems then
		local ok, res = pcall(buildEventList)
		EventItems = (ok and type(res) == "table") and res or {}
		if not ok then dwarn("buildEventList error:", res) end
	end
	if not MerchantItems then
		local ok, res = pcall(buildTravelingMerchantList)
		MerchantItems = (ok and type(res) == "table") and res or {}
		if not ok then dwarn("buildTravelingMerchantList error:", res) end
	end
	if not GardenCoinItems then
		local ok, res = pcall(buildGardenCoinList)
		GardenCoinItems = (ok and type(res) == "table") and res or {}
		if not ok then dwarn("buildGardenCoinList error:", res) end
	end

	local currentSeason = SeasonPassData and SeasonPassData.CurrentSeason
	if (not SeasonPassItems) or SeasonPassListSeason ~= currentSeason then
		local ok, res = pcall(buildSeasonPassList)
		SeasonPassItems = (ok and type(res) == "table") and res or {}
		if not ok then dwarn("buildSeasonPassList error:", res) end
	end
	if not CosmeticItems then
		local ok, res = pcall(buildCosmeticList)
		CosmeticItems = (ok and type(res) == "table") and res or {}
		if not ok then dwarn("buildCosmeticList error:", res) end
	end

	dprint("ensureListsBuilt -> seed", #SeedItems, "egg", #EggItems, "gear", #GearItems, "event", #EventItems, "tm", #MerchantItems, "gc", #GardenCoinItems, "sp", #SeasonPassItems, "cos", #CosmeticItems)
end

function M.GetLists()
	ensureListsBuilt()
	return SeedItems, EggItems, GearItems, EventItems, MerchantItems, GardenCoinItems, SeasonPassItems, CosmeticItems
end

function M.SetGardenCoinBuyQty(v)
	GARDEN_COIN_BUY_QTY = clampGardenCoinQty(v)
	local env = (type(G) == "table" and G) or (getgenv and getgenv()) or _G
	if type(env) == "table" then env.GARDEN_COIN_BUY_QTY = GARDEN_COIN_BUY_QTY end
	_G.GARDEN_COIN_BUY_QTY = GARDEN_COIN_BUY_QTY
	GardenCoinItems = nil
	ensureListsBuilt()
	return GARDEN_COIN_BUY_QTY
end

