--------------------------------------------------
-- FILE HELPERS
--------------------------------------------------
local CAN_FS = (type(readfile) == "function" and type(isfile) == "function")

local function safeName(s)
    s = tostring(s or "player")
    s = s:gsub("[^%w%-_.]", "_")
    s = s:gsub("_+", "_")
    return s:sub(1, 48)
end

local function getSaveFile()
    return ("%s/%s.json"):format(SAVE_DIR, safeName(LP.Name))
end

local _fileCache = { t = 0, data = nil }

local function readDecodedFile()
    if not CAN_FS then
        return nil, "fs_missing"
    end

    local f = getSaveFile()
    if not isfile(f) then
        return nil, "not_found"
    end

    local now = os.clock()
    if _fileCache.data and (now - _fileCache.t) < 1 then
        return _fileCache.data, "cache"
    end

    local ok, txt = pcall(readfile, f)
    if not ok or type(txt) ~= "string" or txt == "" then
        return nil, "read_fail"
    end

    local ok2, data = pcall(HttpService.JSONDecode, HttpService, txt)
    if not ok2 or type(data) ~= "table" then
        return nil, "json_fail"
    end

    _fileCache.t = now
    _fileCache.data = data

    return data, "ok"
end

local function extractRejoinTable(data)
    if type(data) ~= "table" then return {} end

    if type(data.rejoin) == "table" then
        return data.rejoin
    end

    if type(data.state) == "table" and type(data.state.rejoin) == "table" then
        return data.state.rejoin
    end

    if type(data.main) == "table"
        and type(data.main.misc) == "table"
        and type(data.main.misc.rejoin) == "table" then
        return data.main.misc.rejoin
    end

    return {}
end

local function readRejoinDelaySec()
    local g = rawget(_G, "REJOIN_DELAY_SEC")
    if g ~= nil then
        return clampDelaySec(g, REJOIN_DELAY_SEC)
    end

    local S = rawget(_G, "STATE")
    if type(S) == "table" and type(S.rejoin) == "table" then
        local d = tonumber(S.rejoin.rejoin_delay_sec)
        if d then
            return clampDelaySec(d, REJOIN_DELAY_SEC)
        end
    end

    local data = select(1, readDecodedFile())
    if type(data) == "table" then
        local r = extractRejoinTable(data)
        local d = tonumber(r.rejoin_delay_sec)
        if d then
            return clampDelaySec(d, REJOIN_DELAY_SEC)
        end
    end

    return REJOIN_DELAY_SEC
end

local function applyRejoinDelayFromSources()
    REJOIN_DELAY_SEC = readRejoinDelaySec()
    G.REJOIN_DELAY_SEC = REJOIN_DELAY_SEC
    _G.REJOIN_DELAY_SEC = REJOIN_DELAY_SEC
    log("REJOIN_DELAY_SEC =", REJOIN_DELAY_SEC)
end

local function readFlagsFromFile()
    local DEFAULT_RECONNECT = true
    local DEFAULT_EXEC = false

    local data = select(1, readDecodedFile())
    if type(data) ~= "table" then
        local S = rawget(_G, "STATE")
        if type(S) == "table" and type(S.rejoin) == "table" then
            return (S.rejoin.auto_reconnect == true), (S.rejoin.auto_exec == true)
        end

        return DEFAULT_RECONNECT, DEFAULT_EXEC
    end

    local r = extractRejoinTable(data)

    return (r.auto_reconnect == true), (r.auto_exec == true)
end

