            if not isfolder(SAVE_DIR) then
                makefolder(SAVE_DIR)
            end
        end
    end)

    local lockFile = SAVE_DIR .. "/_qtp_exec_lock.txt"

    if type(isfile) == "function" and type(readfile) == "function" and isfile(lockFile) then
        local old = ""
        pcall(function()
            old = tostring(readfile(lockFile) or "")
        end)

        if old:find(tostring(game.JobId), 1, true) then
            return
        end
    end

    pcall(function()
        if type(writefile) == "function" then
            writefile(
                lockFile,
                "jobId=" .. tostring(game.JobId) ..
                "\nplaceId=" .. tostring(game.PlaceId) ..
                "\ntime=" .. tostring(os.time())
            )
        end
    end)

    pcall(function()
        if type(writefile) == "function" then
            writefile(
                SAVE_DIR .. "/_qtp_ran.txt",
                "ran@" .. os.time() ..
                "\njobId=" .. tostring(game.JobId) ..
                "\nplaceId=" .. tostring(game.PlaceId) ..
                "\nurl=" .. tostring(url)
            )
        end
    end)

    G.__PSRECONNECT_LOADED = nil
    G.__NODEHUB_LOADED = nil
    G.__NODEHUB_LOADED_SESSION = nil
    G.__NODEHUB_AUTOEXECED = nil
    G.__MAINUI_LOADED = nil
    G.__UI_LOADED = nil

    local src

    for i = 1, 10 do
        local ok, res = pcall(function()
            return game:HttpGet(url)
        end)

        if ok and type(res) == "string" and #res > 0 then
            src = res
            break
        end

        task.wait(1.2)
