TeleportService.TeleportInitFailed:Connect(function(player, result, errMsg)
    if player ~= LP then return end

    local m = string.lower(tostring(errMsg or ""))

    if result == Enum.TeleportResult.Unauthorized
        or m:find("restricted")
        or m:find("private")
        or m:find("not authorized") then
        TELEPORT_BLOCKED = true
        log("Teleport blocked:", result, errMsg)
    else
        log("Teleport failed:", result, errMsg)
    end
end)

--------------------------------------------------
-- TELEPORT CORE
--------------------------------------------------
local function doTeleport()
    if TELEPORT_BLOCKED then
        return false, "teleport_blocked"
    end

    local ok, err = pcall(function()
        TeleportService:Teleport(game.PlaceId, LP)
    end)

    if not ok then
        return false, tostring(err)
    end

    return true, "teleport_called"
end

local function canTriggerRejoin()
    local now = os.clock()

    if _rejoinInFlight then
        return false
    end

    if (now - _lastRejoinT) < MIN_REJOIN_INTERVAL then
        return false
    end

    _lastRejoinT = now
    return true
end

local function tryRejoin(delaySec)
    if not canTriggerRejoin() then
        return false, "rejoin_busy"
    end

    _rejoinInFlight = true

    applyRejoinDelayFromSources()

    local fileAutoReconnect = select(1, readFlagsFromFile())
    AUTO_RECONNECT_ENABLED = (fileAutoReconnect == true)

    if AUTO_RECONNECT_ENABLED ~= true then
        _rejoinInFlight = false
        return false, "auto_reconnect_off"
    end

    if TELEPORT_BLOCKED then
        _rejoinInFlight = false
        return false, "teleport_blocked"
    end

    local waitSec = clampDelaySec(delaySec, REJOIN_DELAY_SEC)
    task.delay(waitSec, function()
        local okQ, reasonQ = QueueAutoExecIfEnabled()
        local _, autoExec = readFlagsFromFile()

        if autoExec == true and not okQ then
            log("HARD GATE: cancel teleport, QTP failed:", reasonQ)
            _rejoinInFlight = false
            return
        end

        if okQ then
            task.wait(0.8)
        end

        doTeleport()

        task.delay(3, function()
            _rejoinInFlight = false
        end)
    end)

    return true, "scheduled"
end

--------------------------------------------------
-- TEXT DETECT
--------------------------------------------------
local function normText(s)
    s = tostring(s or "")
    s = s:gsub("%s+", " ")
    s = s:gsub("^%s+", "")
    s = s:gsub("%s+$", "")
    return s
end

local function isShutdownText(t)
    t = string.lower(normText(t))

    return t:find("server telah dimatikan", 1, true)
        or t:find("kode error: 288", 1, true)
        or t:find("server has shut down", 1, true)
        or t:find("error code: 288", 1, true)
end

local function isGenericDisconnectText(t)
    t = string.lower(normText(t))

    return t:find("error", 1, true)
        or t:find("disconnected", 1, true)
        or t:find("lost connection", 1, true)
        or t:find("kicked", 1, true)
        or t:find("reconnect", 1, true)
        or t:find("koneksi terputus", 1, true)
        or t:find("hubungkan kembali", 1, true)
        or t:find("akun yang sama", 1, true)
        or t:find("perangkat yang berbeda", 1, true)
        or t:find("kode error", 1, true)
end

--------------------------------------------------
-- DISCONNECT PROMPT HOOK
--------------------------------------------------
local _lastPromptDetectedT = 0
local MIN_PROMPT_DETECT_INTERVAL = 2

local _discLatched = false
local _lastDiscKey = nil
local DISC_COOLDOWN_SEC = 90
local _lastDiscSentAt = 0

local function readAnyText(obj)
    if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
        return tostring(obj.Text or "")
    end
    return ""
end

local function collectDialogText(overlay)
    local all = {}

    for _, d in ipairs(overlay:GetDescendants()) do
        local t = readAnyText(d)
        t = normText(t)

        if t ~= "" then
            all[#all + 1] = t
        end
    end

    return table.concat(all, "\n")
end

local function hookPrompt()
    task.spawn(function()
        local gui = CoreGui:WaitForChild("RobloxPromptGui", 30)
        if not gui then
            log("RobloxPromptGui not found")
            return
        end

        local overlay = gui:WaitForChild("promptOverlay", 30)
        if not overlay then
            log("promptOverlay not found")
            return
        end

        log("promptOverlay hooked")

        local function scan()
            local now = os.clock()
            if (now - _lastPromptDetectedT) < MIN_PROMPT_DETECT_INTERVAL then
                return
            end

            for _, v in ipairs(overlay:GetDescendants()) do
                local txt = readAnyText(v)

                if txt ~= "" and (isShutdownText(txt) or isGenericDisconnectText(txt)) then
                    _lastPromptDetectedT = now

                    local reasonAll = collectDialogText(overlay)
                    local key = normText(reasonAll):sub(1, 400)

                    local now2 = os.clock()

                    if _discLatched and _lastDiscKey == key then
                        return
                    end

                    if (now2 - _lastDiscSentAt) < DISC_COOLDOWN_SEC then
                        return
                    end

                    _discLatched = true
                    _lastDiscKey = key
                    _lastDiscSentAt = now2

                    log("disconnect detected:", reasonAll)

                    if isShutdownText(reasonAll) then
                        tryRejoin(REJOIN_DELAY_SEC)
                    else
                        tryRejoin(REJOIN_DELAY_SEC)
                    end

                    return
                end
            end
        end

        overlay.DescendantRemoving:Connect(function()
            task.defer(function()
                local still = false

                for _, d in ipairs(overlay:GetDescendants()) do
                    local t = readAnyText(d)
                    if t ~= "" and (isShutdownText(t) or isGenericDisconnectText(t)) then
                        still = true
                        break
                    end
                end

                if not still then
                    _discLatched = false
                    _lastDiscKey = nil
                end
            end)
        end)

        scan()

        while true do
            task.wait(0.6)
            scan()
        end
    end)
end

hookPrompt()

