-- 2) PetInformationUserInterface
-- APS:677 Anchored (PnP) diabaikan.
--------------------------------------------------
local APS_REJOIN_DELAY = 5
local _apsFailToken = 0

local function isApsFailText(txt)
    local low = tostring(txt or ""):lower()
    if low:find("anchored", 1, true) then
        return false
    end
    if low:find("requested module experienced an error while loading", 1, true) then
        return true
    end
    if low:find("petinformationuserinterface", 1, true) then
        return true
    end
    return false
end

local function probePetModules()
    local RS = game:GetService("ReplicatedStorage")
    local petServices = RS:FindFirstChild("Modules") and RS.Modules:FindFirstChild("PetServices")
    if not petServices then
        return true
    end
    local names = {
        "ActivePetsService",
        "PetInformationUserInterfaceService",
    }
    for i = 1, #names do
        local mod = petServices:FindFirstChild(names[i])
        if mod then
            local ok, err = pcall(require, mod)
            if not ok and isApsFailText(err) then
                return false, err
            end
        end
    end
    return true
end

local function scheduleApsRejoin(reason)
    if not isApsFailText(reason) then
        return
    end
    if _apsFailToken ~= 0 then
        return
    end
    _apsFailToken = os.clock()
    local token = _apsFailToken
    warn("[PSReconnect] PetServices loading gagal, rejoin " .. tostring(APS_REJOIN_DELAY) .. "s:", tostring(reason))
    task.delay(APS_REJOIN_DELAY, function()
        if _apsFailToken ~= token then
            return
        end
        _apsFailToken = 0
        pcall(function()
            tryRejoin(0)
        end)
    end)
end

local function isLogErrorType(typ)
    if typ == Enum.MessageType.MessageError or typ == Enum.MessageType.MessageWarning then
        return true
    end
    local s = tostring(typ or ""):lower()
    return s:find("error", 1, true) == true or s:find("warning", 1, true) == true
end

-- Error sering muncul SEBELUM stitcher jalan → scan history console dulu.
local function scanLogHistory()
    local ok, hist = pcall(function()
        return game:GetService("LogService"):GetLogHistory()
    end)
    if not ok or type(hist) ~= "table" then
        return
    end
    for i = 1, #hist do
        local row = hist[i]
        if type(row) == "table" then
            local typ = row.messageType or row.MessageType or row.Type
            if isLogErrorType(typ) then
                local msg = row.message or row.Message or row.messageText
                if isApsFailText(msg) then
                    scheduleApsRejoin(msg)
                    return
                end
            end
        elseif type(row) == "string" and isApsFailText(row) then
            scheduleApsRejoin(row)
            return
        end
    end
end

pcall(scanLogHistory)

pcall(function()
    game:GetService("LogService").MessageOut:Connect(function(msg, typ)
        if not isLogErrorType(typ) then
            return
        end
        if isApsFailText(msg) then
            scheduleApsRejoin(msg)
        end
    end)
end)

pcall(function()
    game:GetService("ScriptContext").Error:Connect(function(message, stack)
        local blob = tostring(message) .. "\n" .. tostring(stack)
        if isApsFailText(blob) then
            scheduleApsRejoin(message)
        end
    end)
end)

-- Module require: kalau APS/PetInformation sudah gagal load sebelum script, require()
-- tetap lempar "experienced an error while loading".
task.spawn(function()
    task.wait(1)
    local ok, err = probePetModules()
    if not ok then
        scheduleApsRejoin(err)
    end
    while true do
        task.wait(8)
        ok, err = probePetModules()
        if not ok then
            scheduleApsRejoin(err)
        end
    end
end)

