local LOOP_SEC       = 0.25
local EQUIP_WAIT     = 0.12
local FIRE_WAIT      = 0.06
local GAP_SEC        = 0.08
local PET_COOLDOWN   = 0.25

local RUNNING    = false
local STOP_TOKEN = 0
local THREAD     = nil
local LAST_FEED  = {} -- [petCore] = clock
local function normalizeUUID(u)
    if u == nil then return nil, nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    if #core < 8 then return nil, nil end
    return core, "{" .. core .. "}"
end

local function uuidCoreMatch(a, b)
    local ca = select(1, normalizeUUID(a))
    local cb = select(1, normalizeUUID(b))
    return ca and cb and ca == cb
end

local function ensureCfg()
    if type(G.AUTO_FEED) ~= "table" then
        G.AUTO_FEED = {
            enabled      = false,
            hunger_under = 200000,
            pets         = {},
            fruits       = {},
        }
    end
    local c = G.AUTO_FEED
    c.pets   = type(c.pets) == "table" and c.pets or {}
    c.fruits = type(c.fruits) == "table" and c.fruits or {}
    c.hunger_under = tonumber(c.hunger_under) or 200000
    c.enabled = (c.enabled == true)
    return c
end

local function warnOnce(_msg) end

local function getActivePetRE()
    if not GameEvents then return nil end
    return GameEvents:FindFirstChild("ActivePetService")
        or GameEvents:FindFirstChild("ActivePetsService")
end

local function getProfile()
    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if ok and type(profile) == "table" and next(profile) ~= nil then
        return profile
    end
    return nil
end

local function buildPetFilter(cfg)
    local out, any = {}, false
    for uuid, on in pairs(cfg.pets or {}) do
        if on then
            local core, br = normalizeUUID(uuid)
            if core then out[core] = true; any = true end
            if br   then out[br]   = true end
        end
    end
    if not any then return nil end
    return out
end

local function getActivePets(cfg)
    local list = {}
    local cps = ActivePetsService.ClientPetState
    if type(cps) ~= "table" then return list end

    local perPlayer = cps[LP] or cps[LP.UserId] or cps[LP.Name]
    if type(perPlayer) ~= "table" then return list end

    local filter = buildPetFilter(cfg)

    for uuidKey, handlers in pairs(perPlayer) do
        if type(handlers) == "table" then
            local rec = handlers.PetModelHandler
                or handlers.PetVFXHandler
                or handlers.PetSoundHandler
            if type(rec) == "table" then
                local core, braced = normalizeUUID(rec.UUID or uuidKey)
                if core and braced then
                    local ok = (filter == nil)
                        or filter[core] == true
                        or filter[braced] == true
                    if ok then
                        local pd = rec.PetData or rec.Data or {}
                        list[#list + 1] = {
                            core   = core,
                            braced = braced,
                            type   = tostring(pd.PetType or rec.PetType or ""),
                        }
                    end
                end
            end
        end
    end
    return list
end

local function getPetHunger(profile, petBraced)
    local petsData = profile and profile.PetsData
    local inv = petsData and petsData.PetInventory
    local data = inv and inv.Data
    if type(data) ~= "table" then return nil end

    local core, braced = normalizeUUID(petBraced)
    local rec = data[braced] or data[core]
    if type(rec) ~= "table" then return nil end
    local pd = rec.PetData
    if type(pd) ~= "table" then return nil end
    local h = pd.Hunger
    return type(h) == "number" and h or nil
end

local function fruitWanted(cfg, nameLower)
    local fruits = cfg.fruits or {}
    local hasAny = false
    for _, on in pairs(fruits) do
        if on then hasAny = true; break end
    end
    if not hasAny then return true end
    if nameLower == "" then return false end

    nameLower = nameLower:gsub("%s+seed$", ""):gsub("%s+fruit$", "")
    for key, on in pairs(fruits) do
        if on then
            local k = tostring(key):lower()
            if k == nameLower then return true end
            if nameLower:find(k, 1, true) or k:find(nameLower, 1, true) then return true end
        end
    end
    return false
end

-- Index tool backpack/character by attr c (inventory UUID)
local function buildToolMapByAttrC()
    local map = {} -- [core] = Tool

    local function scan(container)
        if not container then return end
        for _, inst in ipairs(container:GetDescendants()) do
            if inst:IsA("Tool") then
                local attr = inst:GetAttribute("c") or inst:GetAttribute("C")
                local core = select(1, normalizeUUID(attr))
                if core then
                    map[core] = inst
                end
            end
        end
    end

    scan(BACKPACK)
    scan(LP.Character)
    return map
end

local function isHoldableRecord(itemRec)
    if type(itemRec) ~= "table" then return false end
    return tostring(itemRec.ItemType or "") == "Holdable"
end

local function getHoldableItemName(itemRec)
    local id = itemRec.ItemData
    if type(id) == "table" and id.ItemName then
        return tostring(id.ItemName):lower()
    end
    return ""
end

local function isHoldableFavorite(itemRec)
    local id = itemRec.ItemData
    if type(id) == "table" and id.IsFavorite == true then return true end
    return itemRec.IsFavorite == true
end

-- InventoryData Holdable → tool di backpack (match attr c == UUID)
local function collectFeedTools(cfg, profile)
    local inv = profile and profile.InventoryData
    if type(inv) ~= "table" then return 0, 0, {} end

    local toolMap = buildToolMapByAttrC()
    local out, seen = {}, {}
    local holdableCount = 0
    local missingTool = 0

    for itemKey, itemRec in pairs(inv) do
        if isHoldableRecord(itemRec) and not isHoldableFavorite(itemRec) then
            holdableCount += 1

            local nm = getHoldableItemName(itemRec)
            if fruitWanted(cfg, nm) then
                local core = select(1, normalizeUUID(itemKey))
                if not core and type(itemRec.ItemData) == "table" then
                    core = select(1, normalizeUUID(itemRec.ItemData.UUID or itemRec.ItemData.ItemUUID))
                end

                if core and not seen[core] then
                    local tool = toolMap[core]
                    if not tool then
                        for tCore, t in pairs(toolMap) do
                            if uuidCoreMatch(tCore, core) then
                                tool = t
                                core = tCore
                                break
                            end
                        end
                    end

                    if tool then
                        seen[core] = true
                        local braced = select(2, normalizeUUID(itemKey)) or ("{" .. core .. "}")
                        out[#out + 1] = { tool = tool, uuid = braced, name = nm }
                    else
                        missingTool += 1
                    end
                end
            end
        end
    end

    return holdableCount, missingTool, out
end

local function unequipTools()
    local char = LP.Character
    if not char then return end
    for _, inst in ipairs(char:GetChildren()) do
        if inst:IsA("Tool") then
            inst.Parent = BACKPACK
        end
    end
end

local function equipTool(tool)
    local char = LP.Character
    if not char or not tool then return false end

    if tool.Parent ~= BACKPACK and tool.Parent ~= char then
        return false
    end

    unequipTools()
    tool.Parent = char
    task.wait(EQUIP_WAIT)
    return tool.Parent == char
end

local function feedPet(re, petBraced, tool)
    if not equipTool(tool) then return false end
    task.wait(FIRE_WAIT)
    local ok = pcall(function()
        re:FireServer("Feed", petBraced)
    end)
    task.wait(FIRE_WAIT)
    unequipTools()
    return ok == true
end

local function worker(token)
    local re = getActivePetRE()
    if not re then
        warnOnce("ActivePetService remote tidak ditemukan.")
        return
    end

    while RUNNING and token == STOP_TOKEN do
        local cfg = ensureCfg()
        if not cfg.enabled then break end

        local profile = getProfile()
        if not profile then
            warnOnce("Profile belum loaded.")
            task.wait(1)
        else
            local pets = getActivePets(cfg)
            local holdableCount, missingTool, tools = collectFeedTools(cfg, profile)
            local under = cfg.hunger_under

            if holdableCount == 0 then
                warnOnce("Tidak ada ItemType Holdable di InventoryData.")
            elseif #tools == 0 then
                if missingTool > 0 then
                    warnOnce(("Ada %d Holdable di data tapi tool belum di backpack (attr c harus match UUID)."):format(missingTool))
                else
                    warnOnce("Holdable tidak match filter buah yang dipilih.")
                end
            end

            if #pets > 0 and #tools > 0 then
                for _, pet in ipairs(pets) do
                    if not RUNNING or token ~= STOP_TOKEN then break end

                    local last = LAST_FEED[pet.core]
                    if not last or (os.clock() - last) >= PET_COOLDOWN then
                        local hunger = getPetHunger(profile, pet.braced)
                        if type(hunger) == "number" and hunger < under then
                            for _, item in ipairs(tools) do
                                if not RUNNING or token ~= STOP_TOKEN then break end
                                if feedPet(re, pet.braced, item.tool) then
                                    LAST_FEED[pet.core] = os.clock()
                                    task.wait(GAP_SEC)
                                    break
                                end
                            end
                        end
                    end
                end
            end

            task.wait(LOOP_SEC)
        end
    end
end
