local M = {}

function M.getConfig()
    return ensureCfg()
end

function M.ApplyConfig()
    local cfg = ensureCfg()
    if cfg.enabled then
        M.start()
    else
        M.stop()
    end
    return cfg
end

function M.syncFromState()
    return M.ApplyConfig()
end

function M.SetEnabled(on)
    local cfg = ensureCfg()
    if on ~= nil then
        cfg.enabled = (on == true)
    end
    return M.ApplyConfig()
end

function M.setHungerUnder(v)
    local cfg = ensureCfg()
    local n = tonumber(v)
    if n then cfg.hunger_under = math.clamp(math.floor(n + 0.5), 1, 200000) end
end
M.SetHungerUnder = M.setHungerUnder

function M.setPets(map)
    ensureCfg().pets = type(map) == "table" and map or {}
end
M.SetPetsSelected = M.setPets
M.SetPets = M.setPets

function M.setFruits(map)
    ensureCfg().fruits = type(map) == "table" and map or {}
end
M.SetFruitsSelected = M.setFruits
M.SetFruits = M.setFruits

function M.isRunning()
    return RUNNING
end

function M.stop()
    RUNNING = false
    STOP_TOKEN += 1
    THREAD = nil
    pcall(unequipTools)
end

function M.start()
    if RUNNING then return end
    local cfg = ensureCfg()
    if not cfg.enabled then return end

    RUNNING = true
    local token = STOP_TOKEN
    THREAD = task.spawn(function()
        pcall(worker, token)
    end)
end

G.AutoFeed   = M
G.AutoKGFeed = M
_G.AutoFeed  = M

