local function canIO()
    return type(readfile) == "function" and type(isfile) == "function"
        and type(writefile) == "function" and type(isfolder) == "function"
        and type(makefolder) == "function"
end

local function ensureScanDir()
    if not canIO() then return end
    pcall(function()
        if not isfolder("nodehub") then makefolder("nodehub") end
        if not isfolder(SCAN_DIR) then makefolder(SCAN_DIR) end
    end)
end

local _buyRemotesCache = nil
local _gameMarketMod = nil
local INFO_TYPE_PRODUCT = Enum.InfoType.Product

local function getTradeRemotes()
    local ge = RS:FindFirstChild("GameEvents")
    local te = ge and ge:FindFirstChild("TradeEvents")
    local tt = te and te:FindFirstChild("TradeTokens")
    if not tt then return nil, nil, nil end
    return tt:FindFirstChild("CanPurchase"), tt:FindFirstChild("Purchase"), tt:FindFirstChild("BuyDeveloperPurchase")
end

local function scoreRemoteName(name)
    local n = tostring(name):lower()
    local s = 0
    if n:find("developer", 1, true) then s += 40 end
    if n:find("prompt", 1, true) then s += 35 end
    if n:find("robux", 1, true) then s += 30 end
    if n:find("buy", 1, true) then s += 20 end
    if n:find("purchase", 1, true) then s += 20 end
    if n:find("product", 1, true) then s += 15 end
    if n:find("token", 1, true) then s -= 40 end
    if n:find("sell", 1, true) or n:find("gift", 1, true) then s -= 50 end
    return s
end

local function shouldTryRobuxRemote(inst)
    if not inst or not (inst:IsA("RemoteEvent") or inst:IsA("RemoteFunction")) then
        return false
    end
    return scoreRemoteName(inst.Name) >= 25
end

local function collectRobuxBuyRemotes()
    if _buyRemotesCache then return _buyRemotesCache end

    local list = {}
    local seen = {}

    local function add(inst)
        if inst and not seen[inst] and shouldTryRobuxRemote(inst) then
            seen[inst] = true
            list[#list + 1] = inst
        end
    end

    local ge = RS:FindFirstChild("GameEvents")
    if ge then
        for _, d in ipairs(ge:GetDescendants()) do
            add(d)
        end
    end

    table.sort(list, function(a, b)
        return scoreRemoteName(a.Name) > scoreRemoteName(b.Name)
    end)

    _buyRemotesCache = list
    return list
end

-- Alur game (decompile): Market.PromptPurchase OnClientEvent -> PromptPurchase / PromptPurchaseRobux
-- ID = ProductId dari CanPurchase (bukan DeveloperProductId)
local function findGameMarketModule()
    if _gameMarketMod then return _gameMarketMod end

    local mods = RS:WaitForChild("Modules", 8)
    if not mods then return nil end

    local tryNames = {
        "RobuxController", "MarketplaceController", "MarketController",
        "PurchaseController", "ProductPurchase", "RobuxMarketplace",
    }
    for _, name in ipairs(tryNames) do
        local ch = mods:FindFirstChild(name)
        if ch and ch:IsA("ModuleScript") then
            local ok, mod = pcall(require, ch)
            if ok and type(mod) == "table"
                and type(mod.PromptPurchase) == "function"
                and type(mod.PromptPurchaseRobux) == "function" then
                _gameMarketMod = mod
                dbgPrint("[AutoBuyDev] Market module:", ch.Name)
                return mod
            end
        end
    end

    for _, ch in ipairs(mods:GetChildren()) do
        if ch:IsA("ModuleScript") then
            local ok, mod = pcall(require, ch)
            if ok and type(mod) == "table"
                and type(mod.PromptPurchase) == "function"
                and type(mod.PromptPurchaseRobux) == "function"
                and type(mod.CanPurchaseWithTokens) == "function" then
                _gameMarketMod = mod
                dbgPrint("[AutoBuyDev] Market module (scan):", ch.Name)
                return mod
            end
        end
    end
    return nil
end

local function getMarketPromptPurchaseRE()
    local ge = RS:FindFirstChild("GameEvents")
    local market = ge and ge:FindFirstChild("Market")
    local re = market and market:FindFirstChild("PromptPurchase")
    if re and re:IsA("RemoteEvent") then return re end
    return nil
end

local function fireMarketPromptClientEvent(productId, robuxOnly)
    productId = tonumber(productId)
    if not productId then return false end

    local re = getMarketPromptPurchaseRE()
    if not re then return false end

    local payload = { type = 1, id = productId }

    if typeof(getconnections) == "function" then
        for _, conn in ipairs(getconnections(re.OnClientEvent)) do
            if conn.Function then
                local ok = pcall(conn.Function, payload, robuxOnly == true)
                if ok then
                    dbgPrint(string.format(
                        "[AutoBuyDev] OnClientEvent id=%s robuxOnly=%s",
                        tostring(productId), tostring(robuxOnly)
                    ))
                    return true
                end
            end
        end
    end
    return false
end

local function tryFireServerMarketPrompt(productId, robuxOnly)
    productId = tonumber(productId)
    local re = getMarketPromptPurchaseRE()
    if not re or not productId then return false end

    local tries = {
        { { type = 1, id = productId }, robuxOnly == true },
        { { type = 1, id = productId } },
        { productId },
        { productId, robuxOnly == true },
    }

    for i, args in ipairs(tries) do
        local ok = pcall(function()
            re:FireServer(table.unpack(args))
        end)
        if ok then
            dbgPrint(string.format("[AutoBuyDev] FireServer PromptPurchase try%d id=%s", i, productId))
            task.wait(0.3)
            return true
        end
    end
    return false
end

local function callGameMarketPrompt(productId, robuxOnly)
    productId = tonumber(productId)
    if not productId then return false, "bad_id" end

    local mod = findGameMarketModule()
    if mod then
        local ok, err = pcall(function()
            if robuxOnly then
                mod:PromptPurchaseRobux(productId, INFO_TYPE_PRODUCT)
            else
                mod:PromptPurchase(productId, INFO_TYPE_PRODUCT)
            end
        end)
        if ok then
            local tag = robuxOnly and "PromptPurchaseRobux" or "PromptPurchase"
            dbgPrint(string.format("[AutoBuyDev] %s(%s) OK", tag, productId))
            return true, tag
        end
        dbgWarn("[AutoBuyDev] Market module error:", tostring(err))
    else
        dbgWarn("[AutoBuyDev] Market module TIDAK DITEMUKAN — coba FireServer / Notifis")
    end

    if fireMarketPromptClientEvent(productId, robuxOnly) then
        return true, "OnClientEvent"
    end

    if tryFireServerMarketPrompt(productId, robuxOnly) then
        return true, "FireServer"
    end

    return false, "no_ui_path"
end

local function tryNotifisShopUI(productId, data)
    productId = tonumber(productId)
    if not productId or type(data) ~= "table" then return false end

    local mods = RS:FindFirstChild("Modules")
    local scr = mods and mods:FindFirstChild("NotifisController")
    if not scr then return false end

    local ok, nc = pcall(require, scr)
    if not ok or type(nc.PromptPurchase) ~= "function" then return false end

    local name = tostring(data.Name or "Item")
    local price = tonumber(data.PriceInRobux) or tonumber(data.UserBasePriceInRobux) or 0

    local ok2 = pcall(function()
        nc:PromptPurchase(name, price, function(choice)
            dbgPrint("[AutoBuyDev] Notifis pilih:", tostring(choice))
            if choice == "Robux" then
                callGameMarketPrompt(productId, true)
            elseif choice == "Tokens" then
                invokeTokenPurchase(productId)
            end
        end)
    end)

    if ok2 then
        dbgPrint("[AutoBuyDev] NotifisController UI:", name, price)
        return true
    end
    return false
end

