local function tryInvokeRemote(remote, productId)
    local id = tonumber(productId)
    if not id or not remote then return false end

    local argSets = {
        { id },
        { id, LP },
        { LP, id },
        { LP and LP.UserId, id },
        { tostring(id) },
    }

    for _, args in ipairs(argSets) do
        local ok, res = pcall(function()
            if remote:IsA("RemoteEvent") then
                remote:FireServer(table.unpack(args))
                return true
            end
            return remote:InvokeServer(table.unpack(args))
        end)
        if ok and res ~= false then
            return true, remote:GetFullName()
        end
    end
    return false
end

local function tryGameRobuxRemotes(productId)
    for _, remote in ipairs(collectRobuxBuyRemotes()) do
        local ok, path = tryInvokeRemote(remote, productId)
        if ok then return true, path end
    end
    return false
end

local function tryTradeTokensClientModule(productId)
    local mods = RS:FindFirstChild("Modules")
    if not mods then return false end

    for _, modScript in ipairs(mods:GetChildren()) do
        if modScript:IsA("ModuleScript") and modScript.Name:lower():find("trade", 1, true) then
            local ok, mod = pcall(require, modScript)
            if ok and type(mod) == "table" then
                for _, fnName in ipairs({
                    "PromptProductPurchase", "BuyDeveloperProduct", "BuyDeveloperPurchase",
                    "PurchaseRobux", "BuyProduct", "Purchase",
                }) do
                    local fn = mod[fnName]
                    if type(fn) == "function" then
                        local ok2 = pcall(fn, mod, productId)
                        if ok2 then return true, modScript.Name .. "." .. fnName end
                        ok2 = pcall(fn, mod, LP, productId)
                        if ok2 then return true, modScript.Name .. "." .. fnName .. "(LP)" end
                    end
                end
            end
        end
    end
    return false
end

local function formatItemLabel(nm, rbx)
    if rbx and rbx > 0 then
        return string.format("%s | %s R$", nm, tostring(rbx))
    end
    return string.format("%s | ? R$", nm)
end

local function normalizeProductName(name)
    name = tostring(name or ""):lower()
    name = name:gsub("%[gift%]", "")
    name = name:gsub("|.*$", "")
    name = name:gsub("%s+", " ")
    return (name:match("^%s*(.-)%s*$") or name)
end

local function lookupScanProductById(productId)
    productId = tonumber(productId)
    if not productId then return nil end
    for _, p in ipairs(_productsRaw) do
        if tonumber(p.ProductId) == productId then
            return p
        end
    end
    return nil
end

local function lookupGiftScanMeta(normalId, giftId, giftKey)
    local meta = lookupScanProductById(normalId) or lookupScanProductById(giftId)
    if meta then return meta end
    local normKey = normalizeProductName(giftKey)
    if normKey == "" then return nil end
    for _, p in ipairs(_productsRaw) do
        if normalizeProductName(p.Name) == normKey then
            return p
        end
    end
    return nil
end

local function isGiftScanName(name)
    return tostring(name or ""):upper():find("%[GIFT%]", 1, true) ~= nil
end

local function loadGiftDataRaw()
    local dataFolder = RS:FindFirstChild("Data")
    local giftMod = dataFolder and dataFolder:FindFirstChild("GiftData")
    if not giftMod or not giftMod:IsA("ModuleScript") then
        return nil
    end
    local ok, data = pcall(require, giftMod)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end

local function rebuildGiftIdSet(giftData)
    _giftIdSet = {}
    if type(giftData) ~= "table" then return end
    for _, entry in pairs(giftData) do
        if type(entry) == "table" then
            local gid = tonumber(entry.GiftId)
            local nid = tonumber(entry.NormalId)
            if gid and gid > 0 then _giftIdSet[gid] = true end
            if nid and nid > 0 then _giftIdSet[nid] = true end
        end
    end
end

-- GiftData sering NormalId/GiftId = 0 (seed dll) → ambil ProductId dari hasil scan
local function resolveGiftSendId(giftKey, entry)
    entry = type(entry) == "table" and entry or {}
    local normalId = tonumber(entry.NormalId)
    local giftId = tonumber(entry.GiftId)
    if normalId and normalId > 0 then return normalId end
    if giftId and giftId > 0 then return giftId end

    local scanMeta = lookupGiftScanMeta(normalId, giftId, giftKey)
    if scanMeta then
        local pid = tonumber(scanMeta.ProductId)
        if pid and pid > 0 then return pid end
    end

    local keyStr = tostring(giftKey or "")
    if keyStr ~= "" then
        for _, p in ipairs(_productsRaw) do
            local nm = tostring(p.Name or "")
            if nm:find(keyStr, 1, true) then
                local pid = tonumber(p.ProductId)
                if pid and pid > 0 then return pid end
            end
        end
    end
    return nil
end

local function giftSendIdFromMeta(gmeta, fallback)
    if not gmeta then return fallback end
    local nid = tonumber(gmeta.normalId)
    local gid = tonumber(gmeta.giftId)
    local pid = tonumber(gmeta.productId)
    if nid and nid > 0 then return nid end
    if gid and gid > 0 then return gid end
    if pid and pid > 0 then return pid end
    return fallback
end

local function buildGiftDropdownItems(giftData)
    local out = {}
    local seen = {}

    local function addGiftRow(sendId, giftKey, entry, scanMeta)
        sendId = tonumber(sendId)
        if not sendId or sendId <= 0 or seen[sendId] then return end
        seen[sendId] = true

        entry = type(entry) == "table" and entry or {}
        local normalId = tonumber(entry.NormalId)
        local giftId = tonumber(entry.GiftId)

        local nm = scanMeta and tostring(scanMeta.Name or "") or ""
        if nm == "" then
            nm = tostring(giftKey or "Gift")
        end
        local rbx = scanMeta and tonumber(scanMeta.PriceInRobux)

        out[#out + 1] = {
            key = tostring(sendId),
            name = formatItemLabel(nm, rbx),
            giftKey = tostring(giftKey or nm),
            productId = sendId,
            normalId = (normalId and normalId > 0) and normalId or nil,
            giftId = (giftId and giftId > 0) and giftId or nil,
            robuxPrice = rbx,
            displayName = nm,
            isGiftData = true,
        }
    end

    if type(giftData) == "table" then
        for giftKey, entry in pairs(giftData) do
            if type(entry) == "table" then
                local sendId = resolveGiftSendId(giftKey, entry)
                if sendId then
                    local scanMeta = lookupGiftScanMeta(
                        tonumber(entry.NormalId),
                        tonumber(entry.GiftId),
                        giftKey
                    )
                    addGiftRow(sendId, giftKey, entry, scanMeta)
                end
            end
        end
    end

    for _, p in ipairs(_productsRaw) do
        if isGiftScanName(p.Name) then
            local pid = tonumber(p.ProductId)
            if pid and pid > 0 then
                addGiftRow(pid, p.Name, {}, p)
            end
        end
    end

    table.sort(out, function(a, b) return a.name < b.name end)
    return out
end

-- Beli biasa: tampilkan semua item scan (termasuk nama [GIFT])
local function buildDropdownItems(products)
    local out = {}
    for _, p in ipairs(products) do
        local pid = tonumber(p.ProductId)
        if pid and pid > 0 then
            local nm = tostring(p.Name or "Item")
            local rbx = tonumber(p.PriceInRobux)
            out[#out + 1] = {
                key = tostring(pid),
                name = formatItemLabel(nm, rbx),
                productId = pid,
                robuxPrice = rbx,
                displayName = nm,
            }
        end
    end
    table.sort(out, function(a, b) return a.name < b.name end)
    return out
end

local function clearProductIdCache()
    _gameProductIdCache = {}
end

local function loadRobuxCachePayload()
    if not canIO() or not isfile(ROBUX_JSON) then return nil end
    local ok, data = pcall(function()
        return HttpService:JSONDecode(readfile(ROBUX_JSON))
    end)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end

local function loadRobuxProductsFromFile()
    local payload = loadRobuxCachePayload()
    if payload and type(payload.products) == "table" then
        return payload.products
    end
    return {}
end

local function loadGiftCachePayload()
    if not canIO() or not isfile(GIFT_JSON) then return nil end
    local ok, data = pcall(function()
        return HttpService:JSONDecode(readfile(GIFT_JSON))
    end)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end

local function giftDataFromCachePayload(payload)
    if type(payload) ~= "table" then return nil end
    if type(payload.giftData) == "table" then
        return payload.giftData
    end
    if type(payload.gifts) == "table" then
        local out = {}
        for _, row in ipairs(payload.gifts) do
            if type(row) == "table" and row.giftKey then
                out[row.giftKey] = {
                    GiftId = row.giftId or row.GiftId,
                    NormalId = row.normalId or row.NormalId,
                }
            end
        end
        return out
    end
    return nil
end

local function saveGiftDataToFile(giftData, giftItems)
    if not canIO() or type(giftData) ~= "table" then return false end
    ensureScanDir()

    local rows = {}
    if type(giftItems) == "table" then
        for _, it in ipairs(giftItems) do
            rows[#rows + 1] = {
                giftKey = it.giftKey,
                giftId = it.giftId,
                normalId = it.normalId,
                productId = it.productId,
            }
        end
    end

    local payload = {
        updatedAt = os.time(),
        username = USERNAME,
        placeId = game.PlaceId,
        source = _lastGiftSource,
        count = #rows,
        giftData = giftData,
        gifts = rows,
    }
    local ok = pcall(function()
        writefile(GIFT_JSON, HttpService:JSONEncode(payload))
    end)
    return ok
end

local function saveRobuxProductsToFile(products)
    if not canIO() then return false end
    ensureScanDir()
    local payload = {
        scannedAt = os.time(),
        username = USERNAME,
        placeId = game.PlaceId,
        count = #products,
        products = products,
    }
    local ok = pcall(function()
        writefile(ROBUX_JSON, HttpService:JSONEncode(payload))
    end)
    return ok
end

-- Sama seperti scan_purchases.lua RunRobuxOnly (MarketplaceService, semua halaman)
local function fetchAllDeveloperProducts(onProgress)
    local list = {}
    local ok, products = pcall(function()
        return MarketplaceService:GetDeveloperProductsAsync(game.PlaceId)
    end)
    if not ok or not products then
        return false, tostring(products), list
    end

    local pageNum = 0
    while true do
        pageNum += 1
        local pageOk, pageErr = pcall(function()
            for _, item in ipairs(products:GetCurrentPage()) do
                list[#list + 1] = {
                    ProductId = item.ProductId,
                    Name = tostring(item.Name or ""),
                    Description = tostring(item.Description or ""),
                    PriceInRobux = item.PriceInRobux,
                    IconImageAssetId = item.IconImageAssetId,
                }
            end
        end)
        if not pageOk then
            return false, tostring(pageErr), list
        end
        if type(onProgress) == "function" then
            onProgress(#list, pageNum, products.IsFinished)
        end
        if products.IsFinished then
            break
        end
        local advOk, advErr = pcall(function()
            products:AdvanceToNextPageAsync()
        end)
        if not advOk then
            return false, tostring(advErr), list
        end
        task.wait()
    end

    table.sort(list, function(a, b)
        local pa = tonumber(a.PriceInRobux) or 0
        local pb = tonumber(b.PriceInRobux) or 0
        if pa ~= pb then return pa < pb end
        return tostring(a.Name) < tostring(b.Name)
    end)

    return true, nil, list
end

function AutoBuyDev.IsLoading()
    return _loading == true
end

local function clearLists()
    _allItems = {}
    _giftItems = {}
    _productsRaw = {}
end

local function deleteCacheFile()
    if not canIO() then return end
    if isfile(ROBUX_JSON) then
        pcall(function()
            if type(delfile) == "function" then
                delfile(ROBUX_JSON)
            end
        end)
    end
end

local function applyProducts(products)
    _productsRaw = products or {}
    _lastBuySource = (#_productsRaw > 0) and "json" or "none"
    _allItems = buildDropdownItems(_productsRaw)
    AutoBuyDev.RefreshGiftLists()
    return #_allItems
end

local function needsBuyCacheRescan()
    if not canIO() or not isfile(ROBUX_JSON) then
        return true, "no_file"
    end
    local payload = loadRobuxCachePayload()
    if not payload or type(payload.products) ~= "table" or #payload.products == 0 then
        return true, "empty"
    end
    local cachedPlace = tonumber(payload.placeId)
    if cachedPlace and cachedPlace ~= game.PlaceId then
        return true, "place_mismatch"
    end
    return false, "ok"
end

-- Scan beli biasa: MarketplaceService → robux_products_*.json (tanpa [GIFT])
-- Gift: selalu refresh dari Data.GiftData live (+ simpan cadangan gift_data_*.json)
function AutoBuyDev.Rescan()
    if _loading then
        dbgWarn("[AutoBuyDev] Scan sedang berjalan...")
        return false, "busy"
    end

    clearLists()
    clearProductIdCache()
    deleteCacheFile()

    _loading = true
    dbgPrint("[AutoBuyDev] Scan beli biasa (Marketplace) — gift ikut refresh dari GiftData...")
    local ok, err, fetched = fetchAllDeveloperProducts(function(total, page, done)
        if (page % 3) == 0 or done then
            dbgPrint(string.format("[AutoBuyDev] ... halaman %d | total %d%s", page, total, done and " (selesai)" or ""))
        end
    end)
    _loading = false

    if ok and #fetched > 0 then
        saveRobuxProductsToFile(fetched)
        _lastBuySource = "live_scan"
        local n = applyProducts(fetched)
        dbgPrint(string.format(
            "[AutoBuyDev] Scan selesai | beli=%d (→ %s) | gift=%d (%s, → %s)",
            n, ROBUX_JSON, #_giftItems, _lastGiftSource, GIFT_JSON
        ))
        return true, n, #_giftItems
    end

    if #fetched > 0 then
        saveRobuxProductsToFile(fetched)
        _lastBuySource = "live_scan_partial"
        local n = applyProducts(fetched)
        dbgWarn(string.format(
            "[AutoBuyDev] Scan partial: %s | beli=%d | gift=%d",
            tostring(err), n, #_giftItems
        ))
        return false, n, #_giftItems
    end

    pcall(AutoBuyDev.RefreshGiftLists)
    dbgWarn("[AutoBuyDev] Scan beli gagal:", tostring(err), "| gift=", #_giftItems)
    return false, tostring(err), #_giftItems
end

-- Muat list beli dari cache JSON (tidak fetch Marketplace)
function AutoBuyDev.RefreshItemLists()
    if _loading then return #_allItems end
    local products = loadRobuxProductsFromFile()
    local payload = loadRobuxCachePayload()
    if payload then
        _lastBuySource = "json"
        local cachedPlace = tonumber(payload.placeId)
        if cachedPlace and cachedPlace ~= game.PlaceId then
            dbgWarn(string.format(
                "[AutoBuyDev] Cache beli placeId beda (cache=%s, game=%s) — tekan Scan",
                tostring(cachedPlace), tostring(game.PlaceId)
            ))
        end
    else
        _lastBuySource = "none"
    end
    return applyProducts(products)
end

-- Gift: prioritas live GiftData; cadangan file jika modul belum load
function AutoBuyDev.RefreshGiftLists()
    clearProductIdCache()

    local giftData = loadGiftDataRaw()
    if giftData then
        _lastGiftSource = "live"
    else
        local cached = giftDataFromCachePayload(loadGiftCachePayload())
        if cached then
            giftData = cached
            _lastGiftSource = "json_fallback"
            dbgWarn("[AutoBuyDev] GiftData belum ada — pakai cadangan JSON (tekan Scan / tunggu Data load)")
        else
            giftData = {}
            _lastGiftSource = "none"
        end
    end

    rebuildGiftIdSet(giftData)
    _giftItems = buildGiftDropdownItems(giftData)
    if giftData and _lastGiftSource == "live" then
        saveGiftDataToFile(giftData, _giftItems)
    end

    dbgPrint(string.format("[AutoBuyDev] Gift list: %d item (sumber=%s)", #_giftItems, _lastGiftSource))
    return #_giftItems
end

-- Refresh keduanya: beli dari JSON + gift dari GiftData live
function AutoBuyDev.RefreshAllLists()
    local buyN = AutoBuyDev.RefreshItemLists()
    local giftN = AutoBuyDev.RefreshGiftLists()
    return buyN, giftN
end

function AutoBuyDev.GetListStatus()
    local buyPayload = loadRobuxCachePayload()
    local giftPayload = loadGiftCachePayload()
    return {
        buyCount = #_allItems,
        giftCount = #_giftItems,
        buySource = _lastBuySource,
        giftSource = _lastGiftSource,
        buyScannedAt = buyPayload and buyPayload.scannedAt,
        buyPlaceId = buyPayload and buyPayload.placeId,
        giftUpdatedAt = giftPayload and giftPayload.updatedAt,
        buyCacheFile = ROBUX_JSON,
        giftCacheFile = GIFT_JSON,
    }
end

function AutoBuyDev.FormatListStatus()
    local s = AutoBuyDev.GetListStatus()
    local age = ""
    if s.buyScannedAt then
        age = string.format(" | cache %dh ago", math.floor((os.time() - tonumber(s.buyScannedAt)) / 3600))
    end
    return string.format(
        "Buy: %d (%s) | Gift: %d (%s)%s",
        s.buyCount or 0,
        tostring(s.buySource or "?"),
        s.giftCount or 0,
        tostring(s.giftSource or "?"),
        age
    )
end

-- UI tab: muat dari cache/JSON saja (tanpa Marketplace scan)
function AutoBuyDev.RefreshListsFromCache()
    if _loading then return #_allItems, #_giftItems end
    local buyN = AutoBuyDev.RefreshItemLists()
    local giftN = AutoBuyDev.RefreshGiftLists()
    return buyN, giftN
end

-- Saat load script: gift refresh; beli auto-scan hanya jika cache kosong/salah place
function AutoBuyDev.EnsureListsOnLoad()
    local need, why = needsBuyCacheRescan()
    if need then
        dbgPrint("[AutoBuyDev] Auto scan beli:", why)
        return AutoBuyDev.Rescan()
    end
    local buyN = AutoBuyDev.RefreshItemLists()
    AutoBuyDev.RefreshGiftLists()
    return true, buyN, #_giftItems
end

function AutoBuyDev.GetAllItems()
    return _allItems
end

function AutoBuyDev.GetSelfItems()
    local out = {}
    for _, it in ipairs(_allItems) do
        local nm = it.displayName or it.name or ""
        if not isGiftScanName(nm) then
            out[#out + 1] = it
        end
    end
    return out
end

function AutoBuyDev.GetPurchaseMode()
    local m = tostring(AUTO_BUY_DEV_PURCHASE_MODE or "self"):lower()
    return (m == "gift") and "gift" or "self"
end

function AutoBuyDev.SetPurchaseMode(mode)
    AUTO_BUY_DEV_PURCHASE_MODE = (tostring(mode or ""):lower() == "gift") and "gift" or "self"
end

function AutoBuyDev.GetGiftTargetUserId()
    return tonumber(_G.AUTO_BUY_DEV_GIFT_TARGET_USER_ID)
end

function AutoBuyDev.SetGiftTargetUserId(userId)
    local uid = tonumber(userId)
    if uid and uid > 0 then
        _G.AUTO_BUY_DEV_GIFT_TARGET_USER_ID = math.floor(uid)
    else
        _G.AUTO_BUY_DEV_GIFT_TARGET_USER_ID = nil
    end
end

function AutoBuyDev.GetGiftItems()
    if #_giftItems == 0 then
        pcall(AutoBuyDev.RefreshGiftLists)
    end
    return _giftItems
end

function AutoBuyDev.SyncFromGlobals()
    AUTO_BUY_DEV_PAY_MODE = tostring(AUTO_BUY_DEV_PAY_MODE or "token"):lower()
    if AUTO_BUY_DEV_PAY_MODE ~= "robux" then AUTO_BUY_DEV_PAY_MODE = "token" end
    AutoBuyDev.SetPurchaseMode(AUTO_BUY_DEV_PURCHASE_MODE)
    AUTO_BUY_DEV_GIFT_SELECTED = tostring(AUTO_BUY_DEV_GIFT_SELECTED or "")
    AUTO_BUY_DEV_SELECTED = tostring(AUTO_BUY_DEV_SELECTED or "")
end

local function findScanIdsBySimilarName(displayName)
    local norm = normalizeProductName(displayName)
    if norm == "" then return {} end
    local out = {}
    local seen = {}
    for _, p in ipairs(_productsRaw) do
        if normalizeProductName(p.Name) == norm then
            local pid = tonumber(p.ProductId)
            if pid and not seen[pid] then
                seen[pid] = true
                out[#out + 1] = pid
            end
        end
    end
    return out
end

local function getGiftMetaByProductId(productId)
    productId = tonumber(productId)
    if not productId then return nil end
    for _, it in ipairs(_giftItems) do
        if tonumber(it.key) == productId
            or tonumber(it.normalId) == productId
            or tonumber(it.giftId) == productId
            or tonumber(it.productId) == productId then
            return it
        end
    end
    return nil
end

local function getItemMetaById(productId)
    productId = tostring(productId or "")
    for _, it in ipairs(_allItems) do
        if tostring(it.key) == productId then
            return it
        end
    end
    for _, it in ipairs(_giftItems) do
        if tostring(it.key) == productId then
            return it
        end
    end
    return nil
end

-- ID list scan ≠ ID game; gift pakai GiftData.NormalId (SendGiftTo)
function AutoBuyDev.ResolveProductId(scanId)
    scanId = tonumber(scanId)
    if not scanId then return nil, "bad_id" end

    local gmeta = getGiftMetaByProductId(scanId)
    if gmeta then
        local sendId = giftSendIdFromMeta(gmeta, scanId)
        _gameProductIdCache[scanId] = sendId
        return sendId, "gift_data"
    end

    if _gameProductIdCache[scanId] then
        return _gameProductIdCache[scanId], "cache"
    end

    local ENV = (getgenv and getgenv()) or _G
    local captured = tonumber(ENV.__AB_LAST_GIFT_PRODUCT_ID)
    if captured and captured > 0 then
        _gameProductIdCache[scanId] = captured
        dbgPrint(string.format("[AutoBuyDev] Pakai ID dari gift manual terakhir: %s", captured))
        return captured, "capture"
    end

    local canRF = select(1, getTradeRemotes())
    if canRF then
        local ok, can, data = pcall(function()
            return canRF:InvokeServer(scanId)
        end)
        if ok and can == true and type(data) == "table" then
            local gid = tonumber(data.ProductId) or tonumber(data.TargetId) or scanId
            if gid ~= scanId then
                dbgPrint(string.format("[AutoBuyDev] ID list scan=%s → ID game=%s (CanPurchase)", scanId, gid))
            end
            _gameProductIdCache[scanId] = gid
            return gid, "canpurchase"
        end
    end

    local meta = getItemMetaById(scanId)
    if meta and canRF then
        for _, altScanId in ipairs(findScanIdsBySimilarName(meta.displayName or meta.name)) do
            if altScanId ~= scanId then
                local ok, can, data = pcall(function()
                    return canRF:InvokeServer(altScanId)
                end)
                if ok and can == true and type(data) == "table" then
                    local gid = tonumber(data.ProductId) or altScanId
                    dbgPrint(string.format(
                        "[AutoBuyDev] ID benar via nama sama: scan=%s → game=%s",
                        scanId, gid
                    ))
                    _gameProductIdCache[scanId] = gid
                    return gid, "canpurchase_alt"
                end
            end
        end
    end

    if LP then
        local ti = LP:FindFirstChild("Target_Item")
        local tid = ti and tonumber(ti.Value)
        if tid and tid > 0 then
            dbgPrint(string.format("[AutoBuyDev] Pakai Target_Item=%s (buka item di Shop dulu)", tid))
            _gameProductIdCache[scanId] = tid
            return tid, "target_item"
        end
    end

    dbgWarn(string.format(
        "[AutoBuyDev] Tidak bisa resolve ID game untuk scan=%s — tekan Scan atau pilih dari list Gift",
        scanId
    ))
    return scanId, "fallback_scan"
end

function AutoBuyDev.InstallGiftCapture()
    local ENV = (getgenv and getgenv()) or _G
    if ENV.__AB_GIFT_CAPTURE then return end

    local remote = findGiftSendRemote()
    if not remote or type(hookfunction) ~= "function" then return end

    ENV.__AB_GIFT_CAPTURE = true
    local oldFire = hookfunction(remote.FireServer, function(self, ...)
        if self == remote then
            local a1 = select(1, ...)
            local pid = nil
            if type(a1) == "table" then
                pid = tonumber(a1.productId)
            else
                pid = tonumber(select(2, ...))
            end
            if pid and pid > 0 then
                ENV.__AB_LAST_GIFT_PRODUCT_ID = pid
                dbgPrint("[AutoBuyDev] CAPTURE gift manual productId=", pid)
            end
        end
        return oldFire(self, ...)
    end)
    dbgPrint("[AutoBuyDev] Gift capture ON — gift manual 1x akan simpan productId benar")
end

function AutoBuyDev.IsGiftItem(productId)
    return getGiftMetaByProductId(productId) ~= nil
end

local _giftSendRemote = nil

local function findGiftSendRemote()
    if _giftSendRemote and _giftSendRemote.Parent then
        return _giftSendRemote
    end

    local ge = RS:FindFirstChild("GameEvents")
    if not ge then return nil end

    local giftFolder = ge:FindFirstChild("Gift")
    if giftFolder then
        local r = giftFolder:FindFirstChild("SendGiftTo")
        if r and r:IsA("RemoteEvent") then
            _giftSendRemote = r
            return r
        end
    end

    local exact = {
        "GiftSendGiftTo", "SendGiftTo", "GiftUSendGiftTo", "SendGift",
    }
    for _, name in ipairs(exact) do
        local r = ge:FindFirstChild(name, true)
        if r and r:IsA("RemoteEvent") then
            _giftSendRemote = r
            return r
        end
    end

    for _, d in ipairs(ge:GetDescendants()) do
        if d:IsA("RemoteEvent") then
            local n = d.Name:lower()
            if n:find("sendgift", 1, true) or (n:find("gift", 1, true) and n:find("send", 1, true)) then
                _giftSendRemote = d
                return d
            end
        end
    end
    return nil
end

local function collectGiftProductIds(scanId, canData)
    local ids = {}
    local seen = {}
    local function add(v, tag)
        v = tonumber(v)
        if v and v > 0 and not seen[v] then
            seen[v] = true
            ids[#ids + 1] = { id = v, tag = tag or "id" }
        end
    end

    local gmeta = getGiftMetaByProductId(scanId)
    if gmeta then
        add(gmeta.normalId, "GiftData.NormalId")
        add(gmeta.giftId, "GiftData.GiftId")
        add(gmeta.productId, "GiftData.sendId")
    end

    local gameId = AutoBuyDev.ResolveProductId(scanId)
    add(gameId, "resolved_game_id")
    if not gmeta then
        add(scanId, "scan_list")
    end

    if type(canData) == "table" then
        for _, key in ipairs({
            "ProductId", "TargetId", "DeveloperProductId",
            "GiftProductId", "Id", "ItemId", "ShopProductId",
        }) do
            add(canData[key], "CanPurchase." .. key)
        end
    end

    if LP then
        local ti = LP:FindFirstChild("Target_Item")
        if ti then
            add(tonumber(ti.Value) or ti.Value, "Target_Item")
        end
    end

    return ids
end

local function fireGiftOnce(remote, targetUserId, productId)
    local tries = {
        {
            function()
                remote:FireServer({
                    targetUserId = targetUserId,
                    productId = productId,
                })
            end,
            "table",
        },
        {
            function()
                remote:FireServer(targetUserId, productId)
            end,
            "two_args",
        },
    }
    for _, entry in ipairs(tries) do
        local ok = pcall(entry[1])
        if ok then return true, entry[2] end
    end
    return false
end

local function callTradeCanPurchase(productId)
    productId = tonumber(productId)
    if not productId then return false, nil end

    local canRF = select(1, getTradeRemotes())
    if not canRF then return false, nil end

    if canRF:IsA("RemoteFunction") then
        local ok, can, data = pcall(function()
            return canRF:InvokeServer(productId)
        end)
        if not ok then return false, nil end
        return can == true, data
    end

    dbgWarn("[AutoBuyDev] CanPurchase is not a RemoteFunction:", canRF:GetFullName(), canRF.ClassName)
    return false, nil
end

local function resolveCanPurchase(productId)
    productId = tonumber(productId)
    if not productId then return false, nil end

    local can, data = callTradeCanPurchase(productId)
    if not can then
        dbgWarn("[AutoBuyDev] CanPurchase=false id=", productId)
    else
        dbgPrint(string.format(
            "[AutoBuyDev] CanPurchase id=%s ok ProductId=%s DevId=%s",
            tostring(productId),
            tostring(data and data.ProductId),
            tostring(data and data.DeveloperProductId)
        ))
    end
    return can, data
end

local function checkTokensForProduct(productId)
    productId = tonumber(productId)
    if not productId then
        return false, "bad_id"
    end
    local can = select(1, resolveCanPurchase(productId))
    if can then
        return true, "ok"
    end
    if not select(1, getTradeRemotes()) then
        return false, "no_canpurchase_remote"
    end
    return false, "canpurchase_false"
end

function AutoBuyDev.CheckTokensForProduct(productId)
    return checkTokensForProduct(productId)
end

local function checkTokensForGift(scanId)
    scanId = tonumber(scanId)
    if not scanId then
        return false, "bad_id", nil
    end

    local tried = {}
    local function tryId(id)
        id = tonumber(id)
        if not id or id <= 0 or tried[id] then return false end
        tried[id] = true
        local ok = select(1, checkTokensForProduct(id))
        if ok then return true, id end
        return false
    end

    if tryId(scanId) then return true, "ok", scanId end

    local gmeta = getGiftMetaByProductId(scanId)
    if gmeta then
        local fromMeta = giftSendIdFromMeta(gmeta, scanId)
        if tryId(fromMeta) then return true, "ok", fromMeta end
        if tryId(gmeta.normalId) then return true, "ok", tonumber(gmeta.normalId) end
        if tryId(gmeta.giftId) then return true, "ok", tonumber(gmeta.giftId) end
        if tryId(gmeta.productId) then return true, "ok", tonumber(gmeta.productId) end
    end

    local resolved = select(1, AutoBuyDev.ResolveProductId(scanId))
    if resolved and tryId(resolved) then
        return true, "ok", resolved
    end

    return false, "canpurchase_false", nil
end

function AutoBuyDev.TrySendGift(scanId, targetUserId, canData)
    scanId = tonumber(scanId)
    targetUserId = tonumber(targetUserId) or AutoBuyDev.GetGiftTargetUserId()
    if not scanId or not targetUserId or targetUserId <= 0 then
        dbgWarn("[AutoBuyDev] Gift: productId / targetUserId invalid (pilih pemain online)")
        return false, "bad_args"
    end

    local remote = findGiftSendRemote()
    if not remote then
        dbgWarn("[AutoBuyDev] Gift remote tidak ditemukan (cari SendGift di GameEvents)")
        return false, "no_remote"
    end

    local gameId = AutoBuyDev.ResolveProductId(scanId)

    local canOk, canHow = checkTokensForProduct(gameId)
    if not canOk then
        return false, canHow
    end

    if canData == nil then
        local _can, data = resolveCanPurchase(gameId)
        canData = data
    end

    local idList = collectGiftProductIds(scanId, canData)
    dbgPrint(string.format(
        "[AutoBuyDev] Gift coba %d ProductId → targetUserId=%s",
        #idList, tostring(targetUserId)
    ))

    for _, entry in ipairs(idList) do
        local gid, tag = entry.id, entry.tag
        local ok, fmt = fireGiftOnce(remote, targetUserId, gid)
        if ok then
            dbgPrint(string.format(
                "[AutoBuyDev] Gift OK %s | productId=%s (%s) → %s",
                remote.Name, tostring(gid), tag, tostring(targetUserId)
            ))
            return true, string.format("%s:%s:%s", remote.Name, tag, tostring(gid))
        end
    end

    dbgWarn("[AutoBuyDev] Gift gagal semua ID — 'Product not found' = ID salah. Buka item di Shop game, lalu Buy Now lagi (ambil Target_Item).")
    return false, "product_not_found"
end

local function invokeTokenPurchase(productId)
    local _, purchase = getTradeRemotes()
    if not purchase then
        dbgWarn("[AutoBuyDev] TradeTokens.Purchase TIDAK ADA")
        return false, "no_purchase_remote"
    end

    local ok, success, errMsg = pcall(function()
        return purchase:InvokeServer(productId)
    end)
    if not ok then
        dbgWarn("[AutoBuyDev] Purchase error:", tostring(success))
        return false, "purchase_error", tostring(success)
    end

    dbgPrint(string.format(
        "[AutoBuyDev] Purchase(%s) success=%s msg=%s",
        tostring(productId), tostring(success), tostring(errMsg)
    ))

    if success == true then
        return true, "Purchase", nil
    end
    if errMsg then
        dbgWarn("[AutoBuyDev] Purchase ditolak:", tostring(errMsg))
    end
    return false, "purchase_false", errMsg
end

-- Self purchase: open in-game Token / Robux choice UI (no direct TradeTokens.Purchase).
local function purchaseWithPrompt(scanId)
    scanId = tonumber(scanId)
    if not scanId then return false, "bad_id" end

    local gameId = AutoBuyDev.ResolveProductId(scanId)

    local canOk, canHow = checkTokensForProduct(gameId)
    if not canOk then
        return false, canHow
    end

    local _can, data = resolveCanPurchase(gameId)

    local ok, how = callGameMarketPrompt(gameId, false)
    if ok then return true, how end

    if data and tryNotifisShopUI(gameId, data) then
        return true, "Notifis"
    end

    dbgWarn("[AutoBuyDev] Purchase prompt did not open — open Shop in game and buy manually.")
    return false, "prompt_ui_failed"
end

function AutoBuyDev.BuyProductId(scanId, _payMode)
    return purchaseWithPrompt(scanId)
end

local function _msgTokenOrReject(errMsg, how)
    local s = tostring(errMsg or how or ""):lower()
    if s:find("token") and (s:find("kurang") or s:find("not enough") or s:find("insufficient") or s:find("lack")) then
        return "Not enough tokens"
    end
    if s:find("insufficient") or s:find("not enough") or s:find("kurang") then
        return "Insufficient balance or requirements"
    end
    if s:find("robux") then
        return "Not enough Robux"
    end
    if errMsg and tostring(errMsg) ~= "" then
        return tostring(errMsg)
    end
    return nil
end

-- message, tone ("ok"|"err"|"warn"|"info") for UI
function AutoBuyDev.DescribeBuyResult(ok, how, errMsg, opts)
    opts = opts or {}
    how = tostring(how or "")
    local mode = tostring(opts.purchaseMode or ""):lower()
    local pay = tostring(opts.payMode or ""):lower()

    if ok == true then
        if mode == "gift" then
            return "Gift sent successfully", "ok"
        end
        if how == "Notifis" then
            return "Shop UI opened — choose Token or Robux", "ok"
        end
        if how == "PromptPurchase" or how == "OnClientEvent" or how == "FireServer" then
            return "Purchase prompt opened — choose Token or Robux", "ok"
        end
        return "Purchase prompt opened — choose Token or Robux in game", "ok"
    end

    local tokenMsg = _msgTokenOrReject(errMsg, how)
    if how == "purchase_false" and tokenMsg then
        return tokenMsg, "err"
    end
    if how == "canpurchase_false" then
        return "Not enough tokens for this item (check balance)", "err"
    end
    if how == "no_canpurchase_remote" then
        return "CanPurchase check unavailable — rejoin and retry", "err"
    end
    if how == "no_purchase_remote" then
        return "TradeTokens.Purchase remote not found", "err"
    end
    if how == "purchase_error" then
        return "Server error while purchasing: " .. tostring(errMsg or how), "err"
    end
    if how == "prompt_ui_failed" or how == "robux_ui_failed" then
        return "Purchase prompt failed — open Shop in game", "err"
    end
    if how == "bad_id" then
        return "Invalid item ID", "err"
    end
    if how == "bad_args" then
        return "Select a gift item and one online player", "warn"
    end
    if how == "no_remote" then
        return "Gift remote not found", "err"
    end
    if how == "product_not_found" then
        return "Gift product not found — Scan or re-select item", "err"
    end
    if tokenMsg then
        return tokenMsg, "err"
    end
    if errMsg and tostring(errMsg) ~= "" then
        return tostring(errMsg), "err"
    end
    return "Purchase failed (" .. (how ~= "" and how or "unknown") .. ")", "err"
end

-- Buy once → ok (bool), message (string), tone (string)
function AutoBuyDev.BuyOnce()
    AutoBuyDev.SyncFromGlobals()

    if AutoBuyDev.GetPurchaseMode() == "gift" then
        local giftPid = tonumber(AUTO_BUY_DEV_GIFT_SELECTED)
        if (not giftPid or giftPid <= 0) and type(AUTO_BUY_DEV_GIFT_SELECTED) == "string" then
            giftPid = tonumber(tostring(AUTO_BUY_DEV_GIFT_SELECTED):match("(%d+)"))
        end
        local targetUid = AutoBuyDev.GetGiftTargetUserId()
        if not giftPid or giftPid <= 0 then
            return false, "Select an item from the Gift list", "warn"
        end
        if not targetUid or targetUid <= 0 then
            return false, "Select one online player (Gift Target)", "warn"
        end
        local canOk, canHow, useId = checkTokensForGift(giftPid)
        if not canOk then
            local msg, tone = AutoBuyDev.DescribeBuyResult(false, canHow, nil, { purchaseMode = "gift" })
            return false, msg, tone
        end
        local sendId = useId or giftPid
        local ok, how = AutoBuyDev.TrySendGift(sendId, targetUid, nil)
        local msg, tone = AutoBuyDev.DescribeBuyResult(ok, how, nil, { purchaseMode = "gift" })
        return ok == true, msg, tone
    end

    local payMode = AUTO_BUY_DEV_PAY_MODE
    local pid = tonumber(AUTO_BUY_DEV_SELECTED)

    if not pid then
        return false, "Select an item from the purchase list", "warn"
    end

    local _gameId, resolveHow = AutoBuyDev.ResolveProductId(pid)
    local ok, how, errMsg = AutoBuyDev.BuyProductId(pid, payMode)
    local msg, tone = AutoBuyDev.DescribeBuyResult(ok, how, errMsg, {
        purchaseMode = "self",
        payMode = payMode,
        resolveHow = resolveHow,
    })
    return ok == true, msg, tone
end

function AutoBuyDev.OpenShopUI(scanId)
    scanId = tonumber(scanId) or tonumber(AUTO_BUY_DEV_SELECTED)
    if not scanId then return false end
    local gameId = AutoBuyDev.ResolveProductId(scanId)
    local canOk = select(1, AutoBuyDev.CheckTokensForProduct(gameId))
    if canOk ~= true then return false end
    local ok = callGameMarketPrompt(gameId, false)
    return ok
end

local function formatTransactionTime(ts)
    ts = tonumber(ts)
    if not ts or ts <= 0 then return "unknown time" end
    return os.date("%Y-%m-%d %H:%M", ts)
end

local function collectTransactionsArray(txs)
    local out = {}
    if type(txs) ~= "table" then return out end
    for _, tx in ipairs(txs) do
        if type(tx) == "table" then
            out[#out + 1] = tx
        end
    end
    if #out == 0 then
        for _, tx in pairs(txs) do
            if type(tx) == "table" then
                out[#out + 1] = tx
            end
        end
    end
    return out
end

local function readDataServiceTransactions()
    local txs = nil
    pcall(function()
        local modules = RS:FindFirstChild("Modules")
        local dsMod = modules and modules:FindFirstChild("DataService")
        if not dsMod or not dsMod:IsA("ModuleScript") then return end
        local DS = require(dsMod)
        txs = DS.Transactions
        if type(txs) ~= "table" or #txs == 0 then
            if type(DS.GetData) == "function" then
                local data = DS:GetData()
                if type(data) == "table" and type(data.Transactions) == "table" then
                    txs = data.Transactions
                end
            end
        end
    end)
    return collectTransactionsArray(txs)
end

function AutoBuyDev.GetProductNameForId(productId)
    productId = tonumber(productId)
    if not productId then return nil end
    local p = lookupScanProductById(productId)
    if p and p.Name and p.Name ~= "" then
        return tostring(p.Name)
    end
    local meta = getItemMetaById(productId)
    if meta then
        local nm = meta.displayName or meta.name
        if nm and tostring(nm) ~= "" then
            return tostring(nm)
        end
    end
    local g = getGiftMetaByProductId(productId)
    if g then
        local nm = g.name or g.displayName
        if nm and tostring(nm) ~= "" then
            return tostring(nm)
        end
    end
    return nil
end

function AutoBuyDev.GetPurchaseHistory(limit)
    limit = math.max(1, math.min(tonumber(limit) or 25, 50))
    local txs = readDataServiceTransactions()
    local indexed = {}
    for i, tx in ipairs(txs) do
        indexed[#indexed + 1] = { index = i, tx = tx }
    end
    table.sort(indexed, function(a, b)
        return (tonumber(a.tx.Time) or 0) > (tonumber(b.tx.Time) or 0)
    end)
    local out = {}
    for n = 1, math.min(limit, #indexed) do
        local entry = indexed[n]
        local tx = entry.tx
        local pid = tonumber(tx.ProductId)
        local name = AutoBuyDev.GetProductNameForId(pid)
        if not name or name == "" then
            name = pid and ("Product " .. tostring(pid)) or "Unknown product"
        end
        local robux = tonumber(tx.RobuxSpent) or 0
        local pay = robux > 0 and "Robux" or "Token"
        local fin = (tx.Finished == true) and "Done" or "Pending"
        out[#out + 1] = {
            index = entry.index,
            productId = pid,
            productName = name,
            payMethod = pay,
            robuxSpent = robux,
            status = fin,
            timeStr = formatTransactionTime(tx.Time),
            receiptId = tostring(tx.ReceiptId or ""),
            placeId = tonumber(tx.PlaceId),
            raw = tx,
        }
    end
    return out, #txs
end

function AutoBuyDev.Init()
    pcall(AutoBuyDev.RefreshAllLists)
    task.spawn(function()
        RS:WaitForChild("Data", 30)
        RS:WaitForChild("GameEvents", 30)
        RS:WaitForChild("Modules", 8)
        task.wait(2)
        pcall(AutoBuyDev.EnsureListsOnLoad)
        pcall(findGameMarketModule)
        pcall(AutoBuyDev.InstallGiftCapture)
        pcall(AutoBuyDev.LogBuyRemotes)
        dbgPrint("[AutoBuyDev] Load selesai |", AutoBuyDev.FormatListStatus())
    end)
end

