local function asSet(src)
    local out = {}
    if type(src) ~= "table" then
        return out
    end
    for k, v in pairs(src) do
        if v == true then
            out[tostring(k)] = true
        elseif type(k) == "number" and v ~= nil and tostring(v) ~= "" then
            out[tostring(v)] = true
        end
    end
    return out
end

local function hasAnySelected(map)
    if type(map) ~= "table" then
        return false
    end
    for _, v in pairs(map) do
        if v == true then
            return true
        end
    end
    return false
end

local function canonKey(s)
    s = tostring(s or "")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")
    s = s:gsub("^[Ff]ruit[_%s%-]+", "")
    s = s:gsub("^[Ss]eed[_%s%-]+", "")
    s = s:gsub("^[Pp]lant[_%s%-]+", "")
    s = s:gsub("[_%s%-]+[Ss]eed$", "")
    s = s:gsub("%s+[Ss]eed$", "")
    s = s:lower()
    s = s:gsub("[^%w]+", "")
    return s
end

local function persistState(patch)
    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)
    if type(MAIN) ~= "table" then
        return
    end
    MAIN.misc = MAIN.misc or {}
    MAIN.misc.auto_sell_fruit = MAIN.misc.auto_sell_fruit or {}
    local st = MAIN.misc.auto_sell_fruit
    if type(patch) == "table" then
        for k, v in pairs(patch) do
            st[k] = v
        end
    end
    if type(st.fruits) == "table" then
        local arr = {}
        for k in pairs(asSet(st.fruits)) do
            arr[#arr + 1] = k
        end
        table.sort(arr)
        st.fruits = arr
    end
    if type(st.mutations) == "table" then
        local arr = {}
        for k in pairs(asSet(st.mutations)) do
            arr[#arr + 1] = k
        end
        table.sort(arr)
        st.mutations = arr
    end
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)
    local st = MAIN and MAIN.misc and MAIN.misc.auto_sell_fruit
    if type(st) ~= "table" then
        st = {}
    end

    local kgMode = tostring(
        G.AUTO_SELL_FRUIT_KG_MODE
        or _G.AUTO_SELL_FRUIT_KG_MODE
        or st.kgMode
        or "above"
    )
    if kgMode ~= "below" then
        kgMode = "above"
    end

    return {
        enabled =
            (G.AUTO_SELL_FRUIT_MAX_ENABLED == true)
            or (_G.AUTO_SELL_FRUIT_MAX_ENABLED == true)
            or (st.enabled == true),
        fruits = asSet(
            G.AUTO_SELL_FRUIT_FRUITS_SELECTED
            or _G.AUTO_SELL_FRUIT_FRUITS_SELECTED
            or st.fruits
        ),
        mutations = asSet(
            G.AUTO_SELL_FRUIT_MUTATIONS_SELECTED
            or _G.AUTO_SELL_FRUIT_MUTATIONS_SELECTED
            or st.mutations
        ),
        kg = tonumber(G.AUTO_SELL_FRUIT_KG or _G.AUTO_SELL_FRUIT_KG or st.kg) or 0,
        kgMode = kgMode,
        delay = math.max(0, tonumber(G.AUTO_SELL_FRUIT_DELAY or _G.AUTO_SELL_FRUIT_DELAY or st.delay) or 0.4),
        backpackTotal = math.max(0, math.floor(tonumber(
            G.AUTO_SELL_FRUIT_BACKPACK_TOTAL
            or _G.AUTO_SELL_FRUIT_BACKPACK_TOTAL
            or st.backpackTotal
        ) or 0)),
    }
end

local function syncGlobalsFromState()
    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)
    local st = MAIN and MAIN.misc and MAIN.misc.auto_sell_fruit

    if type(st) == "table" then
        AUTO_SELL_FRUIT_MAX_ENABLED = (st.enabled == true)
        AUTO_SELL_FRUIT_FRUITS_SELECTED = asSet(st.fruits)
        AUTO_SELL_FRUIT_MUTATIONS_SELECTED = asSet(st.mutations)
        AUTO_SELL_FRUIT_KG = tonumber(st.kg) or 0
        AUTO_SELL_FRUIT_KG_MODE = tostring(st.kgMode or "above")
        if AUTO_SELL_FRUIT_KG_MODE ~= "below" then
            AUTO_SELL_FRUIT_KG_MODE = "above"
        end
        AUTO_SELL_FRUIT_DELAY = math.max(0, tonumber(st.delay) or 0.4)
        AUTO_SELL_FRUIT_BACKPACK_TOTAL = math.max(0, math.floor(tonumber(st.backpackTotal) or 0))

        _G.AUTO_SELL_FRUIT_MAX_ENABLED = AUTO_SELL_FRUIT_MAX_ENABLED
        G.AUTO_SELL_FRUIT_MAX_ENABLED = AUTO_SELL_FRUIT_MAX_ENABLED
        _G.AUTO_SELL_FRUIT_FRUITS_SELECTED = AUTO_SELL_FRUIT_FRUITS_SELECTED
        G.AUTO_SELL_FRUIT_FRUITS_SELECTED = AUTO_SELL_FRUIT_FRUITS_SELECTED
        _G.AUTO_SELL_FRUIT_MUTATIONS_SELECTED = AUTO_SELL_FRUIT_MUTATIONS_SELECTED
        G.AUTO_SELL_FRUIT_MUTATIONS_SELECTED = AUTO_SELL_FRUIT_MUTATIONS_SELECTED
        _G.AUTO_SELL_FRUIT_KG = AUTO_SELL_FRUIT_KG
        G.AUTO_SELL_FRUIT_KG = AUTO_SELL_FRUIT_KG
        _G.AUTO_SELL_FRUIT_KG_MODE = AUTO_SELL_FRUIT_KG_MODE
        G.AUTO_SELL_FRUIT_KG_MODE = AUTO_SELL_FRUIT_KG_MODE
        _G.AUTO_SELL_FRUIT_DELAY = AUTO_SELL_FRUIT_DELAY
        G.AUTO_SELL_FRUIT_DELAY = AUTO_SELL_FRUIT_DELAY
        _G.AUTO_SELL_FRUIT_BACKPACK_TOTAL = AUTO_SELL_FRUIT_BACKPACK_TOTAL
        G.AUTO_SELL_FRUIT_BACKPACK_TOTAL = AUTO_SELL_FRUIT_BACKPACK_TOTAL
    end
end

local function usesFilter(st)
    st = st or getState()
    return hasAnySelected(st.fruits)
        or hasAnySelected(st.mutations)
        or ((tonumber(st.kg) or 0) > 0)
end

-- true if every holdable fruit matches the filter (or filter is empty) → jual sekaligus
local function canSellWholeInventory(st)
    st = st or getState()
    if not usesFilter(st) then
        return true
    end
    local function scan(container)
        if not container then
            return true
        end
        for _, inst in ipairs(container:GetChildren()) do
            if isHoldableFruitTool(inst) and not toolMatchesFilter(inst, st) then
                return false
            end
        end
        return true
    end
    return scan(LP:FindFirstChild("Backpack")) and scan(LP.Character)
end

--------------------------------------------------
-- HOLDABLE COUNT / CAPACITY (match Backpack UpdateInventorySizeIndicator)
--------------------------------------------------
local function getBonusBackpackSize()
    return tonumber(LP:GetAttribute("BonusBackpackSize")) or 0
end

function M.GetMaxHoldableCapacity()
    return math.ceil(BASE_HOLDABLE_CAPACITY + getBonusBackpackSize())
end
M.getMaxHoldableCapacity = M.GetMaxHoldableCapacity

local function countFromInventoryService()
    if type(InventoryService) ~= "table" or type(InventoryService.Find) ~= "function" then
        return nil
    end

    local ok, result = pcall(function()
        return InventoryService:Find("Holdable")
    end)

    if not ok or type(result) ~= "table" then
        return nil
    end

    local n = 0
    for _ in pairs(result) do
        n += 1
    end

    return n
end

local function countHoldablesFromProfile(profile)
    if type(profile) ~= "table" then return nil end

    local inv = profile.InventoryData
    if type(inv) ~= "table" then return nil end

    local n = 0
    local seenAny = false

    for _, item in pairs(inv) do
        if type(item) == "table" then
            seenAny = true

            local itemType = tostring(
                item.ItemType
                or item.Type
                or item.Category
                or ""
            ):lower()

            if itemType == "holdable" or itemType:find("hold") then
                n += 1
            end
        end
    end

    if seenAny then return n end
    return nil
end

local function countHoldablesByTools()
    local n = 0

    local function scan(container)
        if not container then return end

        for _, inst in ipairs(container:GetChildren()) do
            if inst:IsA("Tool") then
                local itemType = tostring(inst:GetAttribute("ItemType") or ""):lower()

                if itemType == "holdable"
                    or itemType:find("hold")
                    or inst:GetAttribute("Weight") ~= nil
                    or inst:GetAttribute("ItemName") ~= nil
                then
                    n += 1
                end
            end
        end
    end

    scan(LP:FindFirstChild("Backpack"))
    scan(LP.Character)

    return n
end

local function getHoldableCount()
    local fromInv = countFromInventoryService()
    if type(fromInv) == "number" then
        return fromInv
    end

    if DataService and type(DataService.GetData) == "function" then
        local ok, profile = pcall(function()
            return DataService:GetData()
        end)

        if ok and type(profile) == "table" then
            local c = countHoldablesFromProfile(profile)
            if type(c) == "number" then
                return c
            end
        end
    end

    return countHoldablesByTools()
end

function M.GetCapacityInfo()
    local maxCap = M.GetMaxHoldableCapacity()
    local count = getHoldableCount()
    return {
        count = count,
        max = maxCap,
        bonus = getBonusBackpackSize(),
        full = count >= maxCap,
    }
end
M.getCapacityInfo = M.GetCapacityInfo

--------------------------------------------------
-- NPC PROXIMITY (server rejects Sell_Inventory if too far)
--------------------------------------------------
local function getCharacter()
    return LP.Character or LP.CharacterAdded:Wait()
end

local function halloweenEventOn()
    if type(EventRotationController) ~= "table" or type(EventRotationController.IsInEvent) ~= "function" then
        return false
    end
    local ok, on = pcall(function()
        return EventRotationController:IsInEvent("Halloween2026Event")
    end)
    return ok and on == true
end

local function bindHwSellRemotes()
    if HW_SELL_INV and HW_SELL_HELD then
        return
    end
    pcall(function()
        local ge = ReplicatedStorage:FindFirstChild("GameEvents")
        local events = ge and ge:FindFirstChild("Events")
        local he = events and events:FindFirstChild("Halloween2026Event")
        if he then
            HW_SELL_INV = HW_SELL_INV or he:FindFirstChild("HalloweenSellInventoryRE")
            HW_SELL_HELD = HW_SELL_HELD or he:FindFirstChild("HalloweenSellHeldRE")
        end
    end)
end

local function getSellNpcPart(halloween)
    if halloween == true then
        local model
        pcall(function()
            model = workspace:FindFirstChild("SinisterSteven", true)
        end)
        if not model then
            local interaction = workspace:FindFirstChild("Interaction")
            local market = interaction and interaction:FindFirstChild("Halloween2026MarketModel")
            local inner = market and market:FindFirstChild("MarketModel")
            model = inner and inner:FindFirstChild("SinisterSteven")
        end
        if model then
            return model:FindFirstChild("HumanoidRootPart")
                or model.PrimaryPart
                or model:FindFirstChildWhichIsA("BasePart", true)
        end
        return nil
    end

    local npcFolder = workspace:FindFirstChild("NPCS") or workspace:FindFirstChild("NPCs")
    if npcFolder then
        local steven = npcFolder:FindFirstChild("Steven")
        if steven then
            return steven:FindFirstChild("HumanoidRootPart")
                or steven.PrimaryPart
                or steven:FindFirstChildWhichIsA("BasePart", true)
        end
    end

    local tutorialPoints = workspace:FindFirstChild("Tutorial_Points")
    if tutorialPoints then
        return tutorialPoints:FindFirstChild("Tutorial_Point_2")
    end

    return nil
end

local function prepareCharacterForPivot(char)
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return false end

    if workspace:GetAttribute("Stoplight")
        or char:GetAttribute("EasterEggHunt_CARRYING")
    then
        return false
    end

    if hum.Sit then
        hum.Sit = false
        hum:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
        task.wait(0.1)
        hum:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
    end

    return true
end

local function pivotNearSellNpc(halloween)
    local char = getCharacter()
    if not prepareCharacterForPivot(char) then
        return nil
    end

    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end

    local npcPart = getSellNpcPart(halloween)
    if not npcPart then return nil end

    local savedCf = hrp.CFrame
    char:PivotTo(npcPart.CFrame * CFrame.new(0, 0, 6))
    task.wait(0.15)

    return savedCf
end

local function stayNearSellNpc(halloween)
    local char = getCharacter()
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local npcPart = getSellNpcPart(halloween)
    if not (hrp and npcPart) then
        return false
    end
    if (hrp.Position - npcPart.Position).Magnitude > 18 then
        if not prepareCharacterForPivot(char) then
            return false
        end
        char:PivotTo(npcPart.CFrame * CFrame.new(0, 0, 6))
        task.wait(0.1)
    end
    return true
end

local function restoreCharacterCFrame(cf)
    if typeof(cf) ~= "CFrame" then return end

    local char = LP.Character
    if not char then return end

    pcall(function()
        char:PivotTo(cf)
    end)
end

--------------------------------------------------
-- FILTER (type / mutation / kg)
-- Game SellNPC: Sell_Inventory = all, Sell_Item = held tool only
--------------------------------------------------
local function childValue(tool, name)
    local inst = tool:FindFirstChild(name)
    if inst and inst:IsA("ValueBase") then
        return inst.Value
    end
    return nil
end

local function getToolName(tool)
    return childValue(tool, "Item_String")
        or tool:GetAttribute("f")
        or tool:GetAttribute("ItemName")
        or tool:GetAttribute("FruitName")
end

local function getToolWeight(tool)
    return tonumber(childValue(tool, "Weight") or tool:GetAttribute("Weight") or 0) or 0
end

local function isFavoriteTool(tool)
    local fav = tool:GetAttribute(FAVORITE_ATTR)
    if fav == nil then
        fav = tool:GetAttribute("Favorite")
    end
    return fav == true
end

local function isHalloweenEventPlant(tool)
    if not tool or not tool:IsA("Tool") then
        return false
    end
    if not halloweenEventOn() then
        return false
    end
    local name = getToolName(tool)
    if not name or name == "" then
        return false
    end
    local ok, has = pcall(function()
        return PlantTraitsData and PlantTraitsData.HasTrait(name, "HalloweenSlot")
    end)
    return ok and has == true
end

local function isHoldableFruitTool(tool)
    if not tool or not tool:IsA("Tool") then
        return false
    end
    if isFavoriteTool(tool) then
        return false
    end
    return tool:FindFirstChild("Item_String") ~= nil
        or tool:GetAttribute("FruitVersion") ~= nil
        or tool:GetAttribute("s") ~= nil
end

local function matchSet(selectedMap, value)
    if not hasAnySelected(selectedMap) then
        return true
    end
    local needle = canonKey(value)
    for k, v in pairs(selectedMap) do
        if v == true and canonKey(k) == needle then
            return true
        end
    end
    return false
end

local function matchMutation(selectedMap, tool)
    if not hasAnySelected(selectedMap) then
        return true
    end
    for selectedName, on in pairs(selectedMap) do
        if on == true and tool:GetAttribute(selectedName) == true then
            return true
        end
    end
    return false
end

local function matchKg(weight, kg, mode)
    kg = tonumber(kg) or 0
    weight = tonumber(weight) or 0
    if kg <= 0 then
        return true
    end
    if tostring(mode) == "below" then
        return weight <= kg
    end
    return weight >= kg
end

local function toolMatchesFilter(tool, st)
    if not isHoldableFruitTool(tool) then
        return false
    end
    local name = getToolName(tool)
    if not matchSet(st.fruits, name) then
        return false
    end
    if not matchMutation(st.mutations, tool) then
        return false
    end
    if not matchKg(getToolWeight(tool), st.kg, st.kgMode) then
        return false
    end
    return true
end

local function findOneMatching(st, halloween)
    local wantHw = (halloween == true)
    local function scan(container)
        if not container then
            return nil
        end
        for _, inst in ipairs(container:GetChildren()) do
            if toolMatchesFilter(inst, st) and (isHalloweenEventPlant(inst) == wantHw) then
                return inst
            end
        end
        return nil
    end
    return scan(LP:FindFirstChild("Backpack")) or scan(LP.Character)
end

local function countMatching(st)
    local n = 0
    local function scan(container)
        if not container then
            return
        end
        for _, inst in ipairs(container:GetChildren()) do
            if toolMatchesFilter(inst, st) then
                n += 1
            end
        end
    end
    scan(LP:FindFirstChild("Backpack"))
    scan(LP.Character)
    return n
end

local function hasSellableFruit(st)
    st = st or getState()
    return findOneMatching(st, false) ~= nil or findOneMatching(st, true) ~= nil
end

local function hasSellableGroup(st, halloween)
    st = st or getState()
    return findOneMatching(st, halloween) ~= nil
end

local function equipTool(tool)
    local char = getCharacter()
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum or not tool or not tool.Parent then
        return false
    end
    if tool.Parent == char then
        return true
    end
    local ok = pcall(function()
        hum:EquipTool(tool)
    end)
    if not ok then
        return false
    end
    return tool.Parent == char or tool.Parent == LP.Character
end

local function sellHeldItem(halloween)
    local ev = SELL_ITEM_EVENT
    if halloween == true then
        bindHwSellRemotes()
        ev = HW_SELL_HELD
    end
    if not ev then
        return false
    end
    local ok, err = pcall(function()
        ev:FireServer()
    end)
    if not ok then
        warn("[ASF] sell held error:", err)
        return false
    end
    return true
end

local function sellFilteredNow(st, halloween)
    dlog("SELL FILTERED START", "hw=", halloween == true)
    local countBefore = getHoldableCount()
    local sold = 0
    local guard = 0

    while getState().enabled and guard < 800 do
        guard += 1
        local tool = findOneMatching(st, halloween)
        if not tool then
            break
        end
        if not stayNearSellNpc(halloween) then
            dlog("NPC too far during filtered sell")
            break
        end
        if not equipTool(tool) then
            dlog("EQUIP FAIL", tool and tool.Name)
            task.wait(0.05)
        else
            if not sellHeldItem(halloween) then
                task.wait(0.05)
            else
                sold += 1
                local t0 = os.clock()
                while tool.Parent and (os.clock() - t0) < 0.12 and getState().enabled do
                    task.wait()
                end
            end
        end
    end

    pcall(function()
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum:UnequipTools()
        end
    end)

    local countAfter = getHoldableCount()
    dlog("SELL FILTERED END", "sold=", sold, "before=", countBefore, "after=", countAfter)
    return countAfter < countBefore or sold > 0
end

local function sellAllInventoryNow(halloween)
    local ev = SELL_EVENT
    if halloween == true then
        bindHwSellRemotes()
        ev = HW_SELL_INV
    end
    if not ev then
        return false
    end
    local ok, err = pcall(function()
        ev:FireServer()
    end)
    if not ok then
        warn("[ASF] Sell inventory error:", err)
        return false
    end
    return true
end

local function sellGroupNow(st, halloween)
    if not hasSellableGroup(st, halloween) then
        return false
    end

    local savedCf = pivotNearSellNpc(halloween)
    if not savedCf then
        dlog("SELL SKIP: cannot reach sell NPC", "hw=", halloween == true)
        return false
    end

    task.wait(0.35)

    local soldAny = false
    local stall = 0
    while getState().enabled and hasSellableGroup(st, halloween) and stall < 4 do
        st = getState()
        if not stayNearSellNpc(halloween) then
            dlog("SELL STOP: cannot stay at NPC", "hw=", halloween == true)
            break
        end

        local before = countMatching(st)
        local bulk = canSellWholeInventory(st)
        if bulk then
            local bulkOk = false
            for _ = 1, 6 do
                if not stayNearSellNpc(halloween) then
                    break
                end
                if sellAllInventoryNow(halloween) then
                    bulkOk = true
                end
                task.wait(0.25)
                if not hasSellableGroup(getState(), halloween) then
                    soldAny = true
                    bulkOk = true
                    break
                end
            end
            soldAny = bulkOk or soldAny
        else
            soldAny = sellFilteredNow(st, halloween) or soldAny
        end

        local after = countMatching(getState())
        if after >= before then
            stall += 1
            dlog("SELL stall", stall, "left=", after, "hw=", halloween == true)
            task.wait(0.4)
        else
            stall = 0
            soldAny = true
        end
    end

    restoreCharacterCFrame(savedCf)
    task.wait(0.15)
    return soldAny == true
end

local function sellFruitNow()
    if busySelling then return false end
    busySelling = true

    local st = getState()
    dlog("SELL START", "filter=", usesFilter(st), "match=", countMatching(st))

    if not hasSellableFruit(st) then
        dlog("SELL SKIP: no matching fruit")
        busySelling = false
        return false
    end

    local soldAny = false
    if hasSellableGroup(st, true) then
        soldAny = sellGroupNow(st, true) or soldAny
        st = getState()
    end
    if getState().enabled and hasSellableGroup(st, false) then
        soldAny = sellGroupNow(st, false) or soldAny
    end

    lastSellAttemptAt = os.clock()
    busySelling = false
    dlog("SELL END", "soldAny=", soldAny, "left=", countMatching(getState()))
    return soldAny == true
end

--------------------------------------------------
-- LOOP
--------------------------------------------------
local running = false
local loopId = 0

local function mainLoop(myId)
    dlog("LOOP START", myId)

    while running and loopId == myId do
        local st = getState()

        if st.enabled then
            local hasSellable = hasSellableFruit(st)

            local interval = math.max(0, tonumber(st.delay) or 0)
            local needN = math.max(0, math.floor(tonumber(st.backpackTotal) or 0))
            local holdN = getHoldableCount()
            local cap = M.GetMaxHoldableCapacity()
            if needN > cap then
                needN = cap
            end
            local backpackOk = (needN <= 0) or (holdN >= needN)

            dlog("holdable =", holdN, "/", cap, "need=", needN, "sellable=", hasSellable)

            if hasSellable and backpackOk and not busySelling and os.clock() - lastSellAttemptAt >= interval then
                dlog("SELL trip NPC interval=", interval, "backpack", holdN, ">=", needN)
                sellFruitNow()
            end
        end

        task.wait(CHECK_DELAY)
    end

    dlog("LOOP END", myId)
end

--------------------------------------------------
-- API
--------------------------------------------------
local function coerceOn(a, b)
    if type(a) == "table" then
        return b == true
    end
    return a == true
end

function M.SetEnabled(a, b)
    local on = coerceOn(a, b)

    AUTO_SELL_FRUIT_MAX_ENABLED = on
    _G.AUTO_SELL_FRUIT_MAX_ENABLED = on
    G.AUTO_SELL_FRUIT_MAX_ENABLED = on
    persistState({ enabled = on })

    if on then
        if not running then
            running = true
            loopId += 1
            local myId = loopId
            task.spawn(function()
                mainLoop(myId)
            end)
        end
    else
        running = false
    end

    dlog("SetEnabled", on)
end

local function setMapArg(a, b)
    if type(a) == "table" and type(b) == "table" then
        return asSet(b)
    end
    return asSet(a)
end

function M.SetFruits(a, b)
    local map = setMapArg(a, b)
    AUTO_SELL_FRUIT_FRUITS_SELECTED = map
    G.AUTO_SELL_FRUIT_FRUITS_SELECTED = map
    _G.AUTO_SELL_FRUIT_FRUITS_SELECTED = map
    persistState({ fruits = map })
end
M.setFruits = M.SetFruits

function M.SetMutations(a, b)
    local map = setMapArg(a, b)
    AUTO_SELL_FRUIT_MUTATIONS_SELECTED = map
    G.AUTO_SELL_FRUIT_MUTATIONS_SELECTED = map
    _G.AUTO_SELL_FRUIT_MUTATIONS_SELECTED = map
    persistState({ mutations = map })
end
M.setMutations = M.SetMutations

function M.SetKgFilter(a, b, c)
    local kg, mode
    if type(a) == "table" then
        kg, mode = b, c
    else
        kg, mode = a, b
    end
    kg = tonumber(kg) or 0
    mode = tostring(mode or "above")
    if mode ~= "below" then
        mode = "above"
    end
    AUTO_SELL_FRUIT_KG = kg
    AUTO_SELL_FRUIT_KG_MODE = mode
    G.AUTO_SELL_FRUIT_KG = kg
    G.AUTO_SELL_FRUIT_KG_MODE = mode
    _G.AUTO_SELL_FRUIT_KG = kg
    _G.AUTO_SELL_FRUIT_KG_MODE = mode
    persistState({ kg = kg, kgMode = mode })
end
M.setKgFilter = M.SetKgFilter

function M.SetDelay(a, b)
    local n = tonumber(type(a) == "table" and b or a) or 0.4
    n = math.max(0, n)
    AUTO_SELL_FRUIT_DELAY = n
    G.AUTO_SELL_FRUIT_DELAY = n
    _G.AUTO_SELL_FRUIT_DELAY = n
    persistState({ delay = n })
end
M.setDelay = M.SetDelay

function M.SetBackpackTotal(a, b)
    local n = tonumber(type(a) == "table" and b or a) or 0
    n = math.max(0, math.floor(n))
    AUTO_SELL_FRUIT_BACKPACK_TOTAL = n
    G.AUTO_SELL_FRUIT_BACKPACK_TOTAL = n
    _G.AUTO_SELL_FRUIT_BACKPACK_TOTAL = n
    persistState({ backpackTotal = n })
end
M.setBackpackTotal = M.SetBackpackTotal

function M.setEnabled(a, b)
    return M.SetEnabled(a, b)
end

function M.Start()
    return M.SetEnabled(true)
end

function M.start()
    return M.Start()
end

function M.Stop()
    return M.SetEnabled(false)
end

function M.stop()
    return M.Stop()
end

function M.IsRunning()
    return running == true
end

function M.isRunning()
    return M.IsRunning()
end

function M.SyncFromState()
    syncGlobalsFromState()

    local st = getState()
    M.SetEnabled(st.enabled)
end

function M.syncFromState()
    return M.SyncFromState()
end

function M.DebugOnce()
    local info = M.GetCapacityInfo()
    print(
        "[ASF] holdable =",
        info.count,
        "/",
        info.max,
        "bonus=",
        info.bonus
    )

    if info.full then
        return sellFruitNow()
    end

    return false
end

