            -- auto_favorite_pet.lua
-- Auto Favorite / Unfavorite pet tools via GameEvents.Favorite_Item (toggle).
-- Shared filters: type, mutation, age, kg (W100), rarity. Skip equipped + already-desired.

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local DEFAULT_DELAY_SEC = 1
local MAX_PER_TICK      = 2
local FAV_FIRE_COOLDOWN = 2.5
local NO_MUTATION_KEY   = "__NO_MUTATION__"

local RUNNING      = false
local STOP_TOKEN   = 0
local THREAD       = nil
local LAST_STATUS  = "idle"
local LAST_ACTION  = ""
local FAV_COUNT    = 0
local UNFAV_COUNT  = 0
local PENDING_COUNT = 0
local __FAV_LAST_FIRE = {} -- [uuidCore] = { t, want }

local FavoriteItemRE = nil
local DataService    = nil
local PetsService    = nil
local PetList        = nil
local SCALE_PER_LVL  = nil

local function dbgOn()
    return G.AUTO_FAVORITE_PET_DEBUG == true or _G.AUTO_FAVORITE_PET_DEBUG == true
end

local function dlog(...)
    if not dbgOn() then return end
    print("[AutoFavoritePet]", ...)
end

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_FAVORITE_PET_STATUS = LAST_STATUS
    _G.__AUTO_FAVORITE_PET_STATUS = LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_favorite_pet
    return type(st) == "table" and st or {}
end

local function favEnabled()
    if G.AUTO_FAVORITE_PET_FAV_ENABLED == true or _G.AUTO_FAVORITE_PET_FAV_ENABLED == true then
        return true
    end
    return getState().fav_enabled == true
end

local function unfavEnabled()
    if G.AUTO_FAVORITE_PET_UNFAV_ENABLED == true or _G.AUTO_FAVORITE_PET_UNFAV_ENABLED == true then
        return true
    end
    return getState().unfav_enabled == true
end

local function skipEquippedEnabled()
    if G.AUTO_FAVORITE_PET_SKIP_EQUIPPED == false or _G.AUTO_FAVORITE_PET_SKIP_EQUIPPED == false then
        return false
    end
    if G.AUTO_FAVORITE_PET_SKIP_EQUIPPED == true or _G.AUTO_FAVORITE_PET_SKIP_EQUIPPED == true then
        return true
    end
    local st = getState()
    if st.skip_equipped == false then
        return false
    end
    return true -- default ON
end

local function anyEnabled()
    return favEnabled() or unfavEnabled()
end

local function delaySec()
    local n = tonumber(G.AUTO_FAVORITE_PET_DELAY_SEC)
        or tonumber(_G.AUTO_FAVORITE_PET_DELAY_SEC)
        or tonumber(getState().delaySec)
        or DEFAULT_DELAY_SEC
    n = tonumber(n) or DEFAULT_DELAY_SEC
    if n < 0 then n = 0 end
    if n > 300 then n = 300 end
    return n
end

local function signedFromState(keyGlobal, keyState, def)
    local n = tonumber(G[keyGlobal])
    if n == nil then n = tonumber(_G[keyGlobal]) end
    if n == nil then n = tonumber(getState()[keyState]) end
    if n == nil then n = def end
    return n
end

local function ageRaw()
    return signedFromState("AUTO_FAVORITE_PET_AGE", "age", 0)
end

local function kgRaw()
    return signedFromState("AUTO_FAVORITE_PET_KG", "kg", 0)
end

local function mapFromGlobalOrState(globalKey, stateKey)
    local src = G[globalKey] or _G[globalKey] or getState()[stateKey]
    local out = {}
    if type(src) ~= "table" then
        return out
    end
    if #src > 0 then
        for _, k in ipairs(src) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function selectedPetTypes()
    return mapFromGlobalOrState("AUTO_FAVORITE_PET_TYPES", "pet_types")
end

local function selectedMutations()
    return mapFromGlobalOrState("AUTO_FAVORITE_PET_MUTATIONS", "mutations")
end

local function selectedRarities()
    return mapFromGlobalOrState("AUTO_FAVORITE_PET_RARITIES", "rarities")
end

local function lazyServices()
    if FavoriteItemRE == nil then
        local ge = ReplicatedStorage:FindFirstChild("GameEvents")
        FavoriteItemRE = ge and ge:FindFirstChild("Favorite_Item")
    end
    if DataService == nil then
        pcall(function()
            DataService = require(ReplicatedStorage.Modules.DataService)
        end)
    end
    if PetsService == nil then
        pcall(function()
            PetsService = require(ReplicatedStorage.Modules.PetServices.PetsService)
        end)
    end
    if PetList == nil then
        pcall(function()
            PetList = require(ReplicatedStorage.Data.PetRegistry.PetList)
        end)
    end
    if SCALE_PER_LVL == nil then
        pcall(function()
            local PetRegistry = require(ReplicatedStorage.Data.PetRegistry)
            SCALE_PER_LVL = PetRegistry.PetConfig.WEIGHT_CONFIG.SCALE_PERCENTAGE_OF_BASE_WEIGHT_PER_LEVEL
        end)
        if SCALE_PER_LVL == nil then
            SCALE_PER_LVL = 0
        end
    end
end

local function getPLV()
    return rawget(_G, "PetListView") or rawget(G, "PetListView")
end

local function getBagHelpers()
    local PLV = getPLV()
    if PLV and type(PLV.getDatastoreBagIndex) == "function" then
        local ok, bag, index, helpers = pcall(PLV.getDatastoreBagIndex)
        if ok and type(helpers) == "table" then
            return bag, index, helpers
        end
    end
    return nil, nil, nil
end

local function normUUID(u)
    if not u or u == "" then return nil, nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    if core == "" then return nil, nil end
    return core, "{" .. core .. "}"
end

local function toolUUID(tool)
    if not tool then return nil end
    return tool:GetAttribute("PET_UUID")
        or tool:GetAttribute("UUID")
        or tool:GetAttribute("PetUUID")
end

local function isPetTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    local id = toolUUID(tool)
    return id ~= nil and id ~= ""
end

local function isToolFavorited(tool)
    if not tool or not tool:IsA("Tool") then return false end
    return tool:GetAttribute("d") == true
        or tool:GetAttribute("Favorite") == true
        or tool:GetAttribute("IsFavorite") == true
        or tool:GetAttribute("Fav") == true
        or tool:GetAttribute("fav") == true
end

local function isFavoriteRec(rec)
    if type(rec) ~= "table" then return false end
    local PD = rec.PetData or rec.Data or {}
    if typeof(PD.IsFavorite) == "boolean" then return PD.IsFavorite end
    if typeof(PD.IsFavourite) == "boolean" then return PD.IsFavourite end
    if typeof(rec.IsFavorite) == "boolean" then return rec.IsFavorite end
    if typeof(rec.IsFavourite) == "boolean" then return rec.IsFavourite end
    if typeof(rec.Favorite) == "boolean" then return rec.Favorite end
    return false
end

local function isPetFavorited(tool, rec)
    if isToolFavorited(tool) then return true end
    if type(rec) == "table" and isFavoriteRec(rec) then return true end
    return false
end

local function petTypeFromRec(rec)
    if type(rec) ~= "table" then return nil end
    local PD = rec.PetData or rec.Data or {}
    return rec.PetType or rec.Type or PD.PetType or PD.Type or rec.Name or PD.Name
end

local function rarityOfType(petType)
    lazyServices()
    if type(PetList) ~= "table" or not petType then return nil end
    local cfg = PetList[tostring(petType)]
    if type(cfg) ~= "table" then
        -- case-insensitive fallback
        local want = tostring(petType):lower()
        for name, c in pairs(PetList) do
            if type(c) == "table" and tostring(name):lower() == want then
                cfg = c
                break
            end
        end
    end
    if type(cfg) ~= "table" then return nil end
    return cfg.Rarity and tostring(cfg.Rarity) or nil
end

local function getPetRec(uuid, index)
    lazyServices()
    local core, br = normUUID(uuid)
    if not core then return nil end

    if type(index) == "table" then
        local rec = index[br] or index[core] or index[uuid]
        if type(rec) == "table" then
            return rec
        end
    end

    if PetsService and type(PetsService.GetPlayerPetData) == "function" then
        local ok, rec = pcall(function()
            return PetsService:GetPlayerPetData(br or core)
        end)
        if ok and type(rec) == "table" then
            return rec
        end
        ok, rec = pcall(function()
            return PetsService:GetPlayerPetData(core)
        end)
        if ok and type(rec) == "table" then
            return rec
        end
    end

    return nil
end

local function ageFromRec(rec, helpers)
    if helpers and type(helpers.age_from_record) == "function" then
        return tonumber(helpers.age_from_record(rec)) or 0
    end
    if type(rec) ~= "table" then return 0 end
    local PD = rec.PetData or rec.Data or {}
    return tonumber(rec.Age or rec.Level or PD.Age or PD.Level) or 0
end

local function w100FromRec(rec, helpers)
    if helpers and type(helpers.weight_at_100_for_rec) == "function" then
        return tonumber(helpers.weight_at_100_for_rec(rec))
    end
    if type(rec) ~= "table" then return nil end
    local PD = rec.PetData or rec.Data or {}
    local base = tonumber(rec.BaseWeight or PD.BaseWeight or rec.BaseWeightKG or PD.BaseWeightKG)
    if base then
        lazyServices()
        local scale = tonumber(SCALE_PER_LVL) or 0
        return base * (1 + scale * 100)
    end
    return tonumber(rec.Weight or PD.Weight or rec.KG or PD.KG)
end

local function mutationNamesFromRec(rec, helpers)
    if helpers and type(helpers.mutation_names_from_record) == "function" then
        local names = helpers.mutation_names_from_record(rec)
        if type(names) == "table" then
            return names
        end
    end
    if type(rec) ~= "table" then return {} end
    local PD = rec.PetData or rec.Data or {}
    local raw = PD.MutationType or rec.MutationType or PD.Mutations or PD.Mutation
        or rec.Mutations or rec.Mutation
    if type(raw) == "string" and raw ~= "" then
        return { raw }
    end
    if type(raw) == "table" then
        local out = {}
        for _, v in pairs(raw) do
            if type(v) == "string" and v ~= "" then
                table.insert(out, v)
            elseif type(v) == "table" then
                local n = v.MutationType or v.Name or v.EnumId
                if n then table.insert(out, tostring(n)) end
            end
        end
        return out
    end
    return {}
end

local function mapHasAny(map)
    if type(map) ~= "table" then return false end
    for _, v in pairs(map) do
        if v then return true end
    end
    return false
end

local function passesPetType(petType, cfgMap)
    if not mapHasAny(cfgMap) then
        return true
    end
    if not petType or petType == "" then
        return false
    end
    local norm = tostring(petType):lower()
    for key, enabled in pairs(cfgMap) do
        if enabled and norm == tostring(key):lower() then
            return true
        end
    end
    return false
end

local function passesAgeKg(age, w100, aRaw, kRaw)
    aRaw = tonumber(aRaw) or 0
    kRaw = tonumber(kRaw) or 0
    age = tonumber(age) or 0
    w100 = tonumber(w100)

    local kgLimit = math.abs(kRaw)
    local useMaxKG = (kRaw < 0)
    local ageLimit = math.abs(aRaw)
    local useMaxAge = (aRaw < 0)

    if kgLimit > 0 then
        if w100 == nil then
            return false
        end
        if (not useMaxKG) and w100 < kgLimit then
            return false
        elseif useMaxKG and w100 > kgLimit then
            return false
        end
    end

    if ageLimit > 0 then
        if (not useMaxAge) and age < ageLimit then
            return false
        elseif useMaxAge and age > ageLimit then
            return false
        end
    end

    return true
end

local function passesMutation(rec, helpers, mutMap)
    mutMap = (type(mutMap) == "table") and mutMap or {}
    if not mapHasAny(mutMap) then
        return true
    end

    local muts = mutationNamesFromRec(rec, helpers) or {}
    local hasMut = (#muts > 0)

    local wantNoMutation = false
    local selNames = {}
    for name, on in pairs(mutMap) do
        if on then
            if name == NO_MUTATION_KEY then
                wantNoMutation = true
            else
                selNames[string.lower(tostring(name))] = true
            end
        end
    end

    if hasMut then
        for _, m in ipairs(muts) do
            if selNames[string.lower(m)] then
                return true
            end
        end
        return false
    end

    return wantNoMutation == true
end

local function passesRarity(petType, rarityMap)
    if not mapHasAny(rarityMap) then
        return true
    end
    local rarity = rarityOfType(petType)
    if not rarity or rarity == "" then
        return false
    end
    local norm = rarity:lower()
    for key, enabled in pairs(rarityMap) do
        if enabled and norm == tostring(key):lower() then
            return true
        end
    end
    return false
end

local function buildEquippedSet()
    lazyServices()
    local set = {}
    if not DataService or type(DataService.GetData) ~= "function" then
        return set
    end
    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if not ok or type(profile) ~= "table" then
        return set
    end
    local petsData = profile.PetsData or profile.Pets or profile
    local petequip = petsData and petsData.EquippedPets
    if type(petequip) ~= "table" then
        return set
    end
    for _, value in pairs(petequip) do
        local uuid
        if type(value) == "string" then
            uuid = value
        elseif type(value) == "table" then
            uuid = value.UUID or value.Uuid or value.PetUUID or value.Guid or value.uuid
        end
        if uuid then
            local core, br = normUUID(uuid)
            if core then
                set[core] = true
                if br then set[br] = true end
            end
            set[tostring(uuid)] = true
        end
    end
    return set
end

local function scanBackpackPetTools()
    local out = {}
    local function scan(container)
        if not container then return end
        for _, t in ipairs(container:GetChildren()) do
            if t:IsA("Tool") and isPetTool(t) then
                local uuid = toolUUID(t)
                if uuid and uuid ~= "" then
                    table.insert(out, { tool = t, uuid = tostring(uuid) })
                end
            end
        end
    end
    scan(LP:FindFirstChild("Backpack"))
    local char = LP.Character
    if char then
        scan(char)
    end
    return out
end

local function unequipHeldTools()
    local char = LP.Character
    if not char then return end
    local bp = LP:FindFirstChild("Backpack")
    for _, t in ipairs(char:GetChildren()) do
        if t:IsA("Tool") then
            pcall(function()
                if bp then
                    t.Parent = bp
                end
            end)
        end
    end
end

local function setToolFavorite(tool, wantFav)
    lazyServices()
    if not tool or not FavoriteItemRE then
        return false
    end

    wantFav = (wantFav == true)
    local uuidCore = select(1, normUUID(toolUUID(tool)))
    local now = os.clock()
    local last = uuidCore and __FAV_LAST_FIRE[uuidCore]

    -- soft cooldown: avoid toggle spam while lagging
    if last and last.want == wantFav and (now - last.t) < FAV_FIRE_COOLDOWN then
        return true
    end

    unequipHeldTools()

    local ok, err = pcall(function()
        FavoriteItemRE:FireServer(tool)
    end)
    if not ok then
        dlog("Favorite_Item fail", err)
        return false
    end

    if uuidCore then
        __FAV_LAST_FIRE[uuidCore] = { t = os.clock(), want = wantFav }
    end

    local deadline = os.clock() + 1.2
    while os.clock() < deadline do
        if isToolFavorited(tool) == wantFav then
            return true
        end
        task.wait(0.05)
    end

    -- lag soft-ok
    return true
end

local function collectCandidates()
    lazyServices()
    local _, index, helpers = getBagHelpers()
    local equipped = skipEquippedEnabled() and buildEquippedSet() or {}
    local typeMap = selectedPetTypes()
    local mutMap = selectedMutations()
    local rarityMap = selectedRarities()
    local aRaw = ageRaw()
    local kRaw = kgRaw()
    local doFav = favEnabled()
    local doUnfav = unfavEnabled()

    local favList, unfavList = {}, {}
    local pending = 0

    for _, entry in ipairs(scanBackpackPetTools()) do
        local core = select(1, normUUID(entry.uuid))
        if skipEquippedEnabled() and core and (equipped[core] or equipped[entry.uuid]) then
            -- skip equipped
        else
            local rec = getPetRec(entry.uuid, index)
            if type(rec) == "table" then
                local ptype = tostring(petTypeFromRec(rec) or "")
                local age = ageFromRec(rec, helpers)
                local w100 = w100FromRec(rec, helpers)

                if ptype ~= ""
                    and passesPetType(ptype, typeMap)
                    and passesMutation(rec, helpers, mutMap)
                    and passesAgeKg(age, w100, aRaw, kRaw)
                    and passesRarity(ptype, rarityMap)
                then
                    local isFav = isPetFavorited(entry.tool, rec)
                    local item = {
                        tool = entry.tool,
                        uuid = entry.uuid,
                        petType = ptype,
                        isFav = isFav,
                    }

                    -- Both ON → prefer fav end-state only
                    if doFav and doUnfav then
                        if not isFav then
                            table.insert(favList, item)
                            pending += 1
                        end
                    else
                        if doFav and not isFav then
                            table.insert(favList, item)
                            pending += 1
                        elseif doUnfav and isFav then
                            table.insert(unfavList, item)
                            pending += 1
                        end
                    end
                end
            end
        end
    end

    return favList, unfavList, pending
end

function M.ListPetTypeItems()
    local PLV = getPLV()
    if PLV and type(PLV.buildPetItems) == "function" then
        local ok, items = pcall(PLV.buildPetItems)
        if ok and type(items) == "table" then
            return items
        end
    end
    lazyServices()
    local list = {}
    if type(PetList) == "table" then
        for petName, cfg in pairs(PetList) do
            table.insert(list, {
                key = petName,
                name = petName,
                right = type(cfg) == "table" and cfg.Rarity or nil,
            })
        end
        table.sort(list, function(a, b) return a.name < b.name end)
    end
    return list
end

function M.ListMutationItems()
    local items = {
        { key = NO_MUTATION_KEY, name = "[TANPA MUTASI]" },
    }
    local PLV = getPLV()
    if PLV and type(PLV.listAllMutations) == "function" then
        local ok, muts = pcall(PLV.listAllMutations)
        if ok and type(muts) == "table" then
            for _, mutName in ipairs(muts) do
                items[#items + 1] = { key = mutName, name = mutName }
            end
            return items
        end
    end
    return items
end

function M.ListRarityItems()
    lazyServices()
    local seen, order = {}, {}
    if type(PetList) == "table" then
        for _, cfg in pairs(PetList) do
            if type(cfg) == "table" and cfg.Rarity then
                local r = tostring(cfg.Rarity)
                if r ~= "" and not seen[r] then
                    seen[r] = true
                    table.insert(order, r)
                end
            end
        end
    end
    table.sort(order)
    local items = {}
    for _, r in ipairs(order) do
        items[#items + 1] = { key = r, name = r }
    end
    return items
end

function M.GetStatusText()
    local action = LAST_ACTION ~= "" and LAST_ACTION or LAST_STATUS
    return string.format(
        "Fav %d · Unfav %d · Pending %d\n%s",
        FAV_COUNT,
        UNFAV_COUNT,
        PENDING_COUNT,
        action
    )
end

function M.GetCounts()
    return {
        fav = FAV_COUNT,
        unfav = UNFAV_COUNT,
        pending = PENDING_COUNT,
        status = LAST_STATUS,
        favEnabled = favEnabled(),
        unfavEnabled = unfavEnabled(),
    }
end

local function processOne(item, wantFav)
    if not item or not item.tool or not item.tool.Parent then
        return false
    end
    local label = item.petType or "?"
    LAST_ACTION = wantFav and ("fav " .. label) or ("unfav " .. label)
    publishStatus(LAST_ACTION)

    local already = isPetFavorited(item.tool, nil)
    if already == wantFav then
        return true
    end

    local ok = setToolFavorite(item.tool, wantFav)
    if ok then
        if wantFav then
            FAV_COUNT += 1
        else
            UNFAV_COUNT += 1
        end
    end
    return ok
end

local function worker(token)
    while RUNNING and STOP_TOKEN == token and anyEnabled() do
        local waitSec = math.max(delaySec(), 0.25)
        local favList, unfavList, pending = collectCandidates()
        PENDING_COUNT = pending

        local acted = 0
        local budget = MAX_PER_TICK

        -- Prefer fav when both enabled (collectCandidates already empties unfav in that case)
        for _, item in ipairs(favList) do
            if acted >= budget then break end
            if not anyEnabled() or STOP_TOKEN ~= token then break end
            if processOne(item, true) then
                acted += 1
                task.wait(waitSec)
            end
        end

        for _, item in ipairs(unfavList) do
            if acted >= budget then break end
            if not anyEnabled() or STOP_TOKEN ~= token then break end
            if processOne(item, false) then
                acted += 1
                task.wait(waitSec)
            end
        end

        if acted == 0 then
            if pending == 0 then
                publishStatus("idle")
                LAST_ACTION = "idle"
            else
                publishStatus("pending")
                LAST_ACTION = "pending"
            end
            task.wait(waitSec)
        end
    end

    if STOP_TOKEN == token then
        RUNNING = false
        if not anyEnabled() then
            publishStatus("stopped")
            LAST_ACTION = "stopped"
        end
    end
end

function M.SyncFromState()
    return M.SetEnabled(anyEnabled())
end
M.syncFromState = M.SyncFromState

function M.SetEnabled(_on)
    if anyEnabled() then
        M.start()
    else
        M.stop()
    end
    return anyEnabled()
end
M.setEnabled = M.SetEnabled

function M.isRunning()
    return RUNNING
end
M.IsRunning = M.isRunning

function M.stop()
    RUNNING = false
    STOP_TOKEN += 1
    THREAD = nil
    publishStatus("stopped")
    LAST_ACTION = "stopped"
end
M.Stop = M.stop

function M.start()
    if not anyEnabled() then
        M.stop()
        return
    end
    if RUNNING then return end

    RUNNING = true
    local token = STOP_TOKEN
    publishStatus("running")
    LAST_ACTION = "running"
    THREAD = task.spawn(function()
        pcall(worker, token)
    end)
end
M.Start = M.start

function M.RunOnce()
    if not anyEnabled() then
        return false, "disabled"
    end
    local favList, unfavList = collectCandidates()
    if #favList > 0 then
        return processOne(favList[1], true)
    end
    if #unfavList > 0 then
        return processOne(unfavList[1], false)
    end
    publishStatus("no match")
    LAST_ACTION = "no match"
    return false, "no_match"
end

G.AutoFavoritePet = M
_G.AutoFavoritePet = M

return M

        end,
        required = false,
    },
    {
        key = "AutoSellPet",
        name = "Auto Sell Pet",
        factory = function()
            -- Gauto_sell_pet.lua
-- Own filters (type / mutation / rarity / age / kg).
-- Auto Sell: saved + auto-load loop. Sell Now: session-only, never persisted.
-- Delay > 0: one-by-one SellPetShopSelected. Delay 0: all matches at once.
-- Never SellAllPets_RE (that sells every unfavorited pet).

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local DEFAULT_DELAY_SEC = 1
local SELL_WAIT_SEC     = 2
local NO_MUTATION_KEY   = "__NO_MUTATION__"

local RUNNING     = false
local STOP_TOKEN  = 0
local THREAD      = nil
local LAST_STATUS = "idle"
local LAST_ACTION = ""
local SOLD_COUNT  = 0
local MATCH_COUNT = 0

local SellPetShopSelected = nil
local PetsService = nil
local PetList     = nil
local SCALE_PER_LVL = nil

local function dbgOn()
    return G.AUTO_SELL_PET_DEBUG == true or _G.AUTO_SELL_PET_DEBUG == true
end

local function dlog(...)
    if not dbgOn() then return end
    print("[AutoSellPet]", ...)
end

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_SELL_PET_STATUS = LAST_STATUS
    _G.__AUTO_SELL_PET_STATUS = LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_sell_pet
    return type(st) == "table" and st or {}
end

local function sellNowEnabled()
    return G.AUTO_SELL_PET_NOW == true or _G.AUTO_SELL_PET_NOW == true
end

local function autoEnabled()
    return G.AUTO_SELL_PET_ENABLED == true or _G.AUTO_SELL_PET_ENABLED == true
end

local function wantRun()
    return autoEnabled() or sellNowEnabled()
end

local function minPets()
    local n = tonumber(G.AUTO_SELL_PET_MIN_PETS)
    if n == nil then n = tonumber(_G.AUTO_SELL_PET_MIN_PETS) end
    if n == nil then n = tonumber(getState().minPets) end
    n = math.floor(tonumber(n) or 0)
    if n < 0 then n = 0 end
    if n > 500 then n = 500 end
    return n
end

local function delaySec()
    local n = tonumber(G.AUTO_SELL_PET_DELAY_SEC)
        or tonumber(_G.AUTO_SELL_PET_DELAY_SEC)
        or tonumber(getState().delaySec)
        or DEFAULT_DELAY_SEC
    n = tonumber(n) or DEFAULT_DELAY_SEC
    if n < 0 then n = 0 end
    if n > 30 then n = 30 end
    return n
end

local function signedFromState(keyGlobal, keyState, def)
    local n = tonumber(G[keyGlobal])
    if n == nil then n = tonumber(_G[keyGlobal]) end
    if n == nil then n = tonumber(getState()[keyState]) end
    if n == nil then n = def end
    return n
end

local function mapFromGlobalOrState(globalKey, stateKey)
    local src = G[globalKey] or _G[globalKey] or getState()[stateKey]
    local out = {}
    if type(src) ~= "table" then
        return out
    end
    if #src > 0 then
        for _, k in ipairs(src) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function mapHasAny(map)
    if type(map) ~= "table" then return false end
    for _, v in pairs(map) do
        if v then return true end
    end
    return false
end

local function selectedPetTypes()
    return mapFromGlobalOrState("AUTO_SELL_PET_TYPES", "pet_types")
end

local function selectedMutations()
    return mapFromGlobalOrState("AUTO_SELL_PET_MUTATIONS", "mutations")
end

local function selectedRarities()
    return mapFromGlobalOrState("AUTO_SELL_PET_RARITIES", "rarities")
end

local function hasRestrictiveFilter()
    return mapHasAny(selectedPetTypes())
        or mapHasAny(selectedRarities())
        or mapHasAny(selectedMutations())
end

local function lazyServices()
    if PetsService == nil then
        pcall(function()
            PetsService = require(ReplicatedStorage.Modules.PetServices.PetsService)
        end)
    end
    if PetList == nil then
        pcall(function()
            PetList = require(ReplicatedStorage.Data.PetRegistry.PetList)
        end)
    end
    if SCALE_PER_LVL == nil then
        pcall(function()
            local PetRegistry = require(ReplicatedStorage.Data.PetRegistry)
            SCALE_PER_LVL = PetRegistry.PetConfig.WEIGHT_CONFIG.SCALE_PERCENTAGE_OF_BASE_WEIGHT_PER_LEVEL
        end)
        if SCALE_PER_LVL == nil then
            SCALE_PER_LVL = 0
        end
    end
end

local function lazySellRE()
    if SellPetShopSelected and SellPetShopSelected.Parent then
        return true
    end
    local ge = ReplicatedStorage:FindFirstChild("GameEvents")
    SellPetShopSelected = ge and ge:FindFirstChild("SellPetShopSelected")
    return SellPetShopSelected ~= nil
end

local function getPLV()
    return rawget(_G, "PetListView") or rawget(G, "PetListView")
end

local function getBagHelpers()
    local PLV = getPLV()
    if PLV and type(PLV.getDatastoreBagIndex) == "function" then
        local ok, bag, index, helpers = pcall(PLV.getDatastoreBagIndex)
        if ok and type(helpers) == "table" then
            return bag, index, helpers
        end
    end
    return nil, nil, nil
end

local function normUUID(u)
    if not u or u == "" then return nil, nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    if core == "" then return nil, nil end
    return core, "{" .. core .. "}"
end

local function toolUUID(tool)
    if not tool then return nil end
    return tool:GetAttribute("PET_UUID")
        or tool:GetAttribute("UUID")
        or tool:GetAttribute("PetUUID")
end

local function isPetTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    local id = toolUUID(tool)
    return id ~= nil and id ~= ""
end

local function isToolFavorited(tool)
    if not tool or not tool:IsA("Tool") then return false end
    return tool:GetAttribute("d") == true
        or tool:GetAttribute("Favorite") == true
        or tool:GetAttribute("IsFavorite") == true
        or tool:GetAttribute("Fav") == true
        or tool:GetAttribute("fav") == true
end

local function isFavoriteRec(rec)
    if type(rec) ~= "table" then return false end
    local PD = rec.PetData or rec.Data or {}
    if typeof(PD.IsFavorite) == "boolean" then return PD.IsFavorite end
    if typeof(PD.IsFavourite) == "boolean" then return PD.IsFavourite end
    if typeof(rec.IsFavorite) == "boolean" then return rec.IsFavorite end
    if typeof(rec.IsFavourite) == "boolean" then return rec.IsFavourite end
    if typeof(rec.Favorite) == "boolean" then return rec.Favorite end
    return false
end

local function isPetFavorited(tool, rec)
    if isToolFavorited(tool) then return true end
    if type(rec) == "table" and isFavoriteRec(rec) then return true end
    return false
end

local function petTypeFromRec(rec)
    if type(rec) ~= "table" then return nil end
    local PD = rec.PetData or rec.Data or {}
    return rec.PetType or rec.Type or PD.PetType or PD.Type or rec.Name or PD.Name
end

local function rarityOfType(petType)
    lazyServices()
    if type(PetList) ~= "table" or not petType then return nil end
    local cfg = PetList[tostring(petType)]
    if type(cfg) ~= "table" then
        local want = tostring(petType):lower()
        for name, c in pairs(PetList) do
            if type(c) == "table" and tostring(name):lower() == want then
                cfg = c
                break
            end
        end
    end
    if type(cfg) ~= "table" then return nil end
    return cfg.Rarity and tostring(cfg.Rarity) or nil
end

local function getPetRec(uuid, index)
    lazyServices()
    local core, br = normUUID(uuid)
    if not core then return nil end
    if type(index) == "table" then
        local rec = index[br] or index[core] or index[uuid]
        if type(rec) == "table" then
            return rec
        end
    end
    if PetsService and type(PetsService.GetPlayerPetData) == "function" then
        local ok, rec = pcall(function()
            return PetsService:GetPlayerPetData(br or core)
        end)
        if ok and type(rec) == "table" then
            return rec
        end
        ok, rec = pcall(function()
            return PetsService:GetPlayerPetData(core)
        end)
        if ok and type(rec) == "table" then
            return rec
        end
    end
    return nil
end

local function ageFromRec(rec, helpers)
    if helpers and type(helpers.age_from_record) == "function" then
        return tonumber(helpers.age_from_record(rec)) or 0
    end
    if type(rec) ~= "table" then return 0 end
    local PD = rec.PetData or rec.Data or {}
    return tonumber(rec.Age or rec.Level or PD.Age or PD.Level) or 0
end

local function w100FromRec(rec, helpers)
    if helpers and type(helpers.weight_at_100_for_rec) == "function" then
        return tonumber(helpers.weight_at_100_for_rec(rec))
    end
    if type(rec) ~= "table" then return nil end
    local PD = rec.PetData or rec.Data or {}
    local base = tonumber(rec.BaseWeight or PD.BaseWeight or rec.BaseWeightKG or PD.BaseWeightKG)
    if base then
        lazyServices()
        local scale = tonumber(SCALE_PER_LVL) or 0
        return base * (1 + scale * 100)
    end
    return tonumber(rec.Weight or PD.Weight or rec.KG or PD.KG)
end

local function mutationNamesFromRec(rec, helpers)
    if helpers and type(helpers.mutation_names_from_record) == "function" then
        local names = helpers.mutation_names_from_record(rec)
        if type(names) == "table" then
            return names
        end
    end
    if type(rec) ~= "table" then return {} end
    local PD = rec.PetData or rec.Data or {}
    local raw = PD.MutationType or rec.MutationType or PD.Mutations or PD.Mutation
        or rec.Mutations or rec.Mutation
    if type(raw) == "string" and raw ~= "" then
        return { raw }
    end
    if type(raw) == "table" then
        local out = {}
        for _, v in pairs(raw) do
            if type(v) == "string" and v ~= "" then
                table.insert(out, v)
            elseif type(v) == "table" then
                local n = v.MutationType or v.Name or v.EnumId
                if n then table.insert(out, tostring(n)) end
            end
        end
        return out
    end
    return {}
end

local function passesPetType(petType, cfgMap)
    if not mapHasAny(cfgMap) then
        return true
    end
    if not petType or petType == "" then
        return false
    end
    local norm = tostring(petType):lower()
    for key, enabled in pairs(cfgMap) do
        if enabled and norm == tostring(key):lower() then
            return true
        end
    end
    return false
end

local function passesAgeKg(age, w100, aRaw, kRaw)
    aRaw = tonumber(aRaw) or 0
    kRaw = tonumber(kRaw) or 0
    age = tonumber(age) or 0
    w100 = tonumber(w100)
    local kgLimit = math.abs(kRaw)
    local useMaxKG = (kRaw < 0)
    local ageLimit = math.abs(aRaw)
    local useMaxAge = (aRaw < 0)
    if kgLimit > 0 then
        if w100 == nil then
            return false
        end
        if (not useMaxKG) and w100 < kgLimit then
            return false
        elseif useMaxKG and w100 > kgLimit then
            return false
        end
    end
    if ageLimit > 0 then
        if (not useMaxAge) and age < ageLimit then
            return false
        elseif useMaxAge and age > ageLimit then
            return false
        end
    end
    return true
end

local function passesMutation(rec, helpers, mutMap)
    mutMap = (type(mutMap) == "table") and mutMap or {}
    if not mapHasAny(mutMap) then
        return true
    end
    local muts = mutationNamesFromRec(rec, helpers) or {}
    local hasMut = (#muts > 0)
    local wantNoMutation = false
    local selNames = {}
    for name, on in pairs(mutMap) do
        if on then
            if name == NO_MUTATION_KEY then
                wantNoMutation = true
            else
                selNames[string.lower(tostring(name))] = true
            end
        end
    end
    if hasMut then
        for _, m in ipairs(muts) do
            if selNames[string.lower(m)] then
                return true
            end
        end
        return false
    end
    return wantNoMutation == true
end

local function passesRarity(petType, rarityMap)
    if not mapHasAny(rarityMap) then
        return true
    end
    local rarity = rarityOfType(petType)
    if not rarity or rarity == "" then
        return false
    end
    local norm = rarity:lower()
    for key, enabled in pairs(rarityMap) do
        if enabled and norm == tostring(key):lower() then
            return true
        end
    end
    return false
end

local function scanBackpackPetTools()
    local out = {}
    local function scan(container)
        if not container then return end
        for _, t in ipairs(container:GetChildren()) do
            if t:IsA("Tool") and isPetTool(t) then
                local uuid = toolUUID(t)
                if uuid and uuid ~= "" then
                    table.insert(out, { tool = t, uuid = tostring(uuid) })
                end
            end
        end
    end
    scan(LP:FindFirstChild("Backpack"))
    local char = LP.Character
    if char then
        scan(char)
    end
    return out
end

local function collectSellTools()
    lazyServices()
    local out = {}
    if not hasRestrictiveFilter() then
        return out
    end
    local _, index, helpers = getBagHelpers()
    local typeMap = selectedPetTypes()
    local mutMap = selectedMutations()
    local rarityMap = selectedRarities()
    local aRaw = signedFromState("AUTO_SELL_PET_AGE", "age", 0)
    local kRaw = signedFromState("AUTO_SELL_PET_KG", "kg", 0)

    for _, entry in ipairs(scanBackpackPetTools()) do
        local rec = getPetRec(entry.uuid, index)
        if type(rec) == "table" then
            local ptype = tostring(petTypeFromRec(rec) or "")
            local age = ageFromRec(rec, helpers)
            local w100 = w100FromRec(rec, helpers)
            if ptype ~= ""
                and passesPetType(ptype, typeMap)
                and passesMutation(rec, helpers, mutMap)
                and passesAgeKg(age, w100, aRaw, kRaw)
                and passesRarity(ptype, rarityMap)
                and not isPetFavorited(entry.tool, rec)
            then
                table.insert(out, {
                    tool = entry.tool,
                    uuid = entry.uuid,
                    petType = ptype,
                })
            end
        end
    end
    return out
end

local function typeCountLine(list)
    local counts = {}
    for _, item in ipairs(list) do
        local name = tostring(item.petType or "?")
        counts[name] = (counts[name] or 0) + 1
    end
    local rows = {}
    for name, n in pairs(counts) do
        table.insert(rows, { name = name, n = n })
    end
    table.sort(rows, function(a, b)
        if a.n ~= b.n then
            return a.n > b.n
        end
        return a.name < b.name
    end)
    local parts = {}
    for i, row in ipairs(rows) do
        parts[i] = row.name .. " x" .. tostring(row.n)
    end
    if #parts == 0 then
        return "(none)"
    end
    return table.concat(parts, " · ")
end

local function unequipHeldTools()
    local char = LP.Character
    if not char then return end
    local bp = LP:FindFirstChild("Backpack")
    for _, t in ipairs(char:GetChildren()) do
        if t:IsA("Tool") then
            pcall(function()
                if bp then
                    t.Parent = bp
                end
            end)
        end
    end
end

local function sellOneTool(tool)
    if not tool or not tool.Parent then
        return false
    end
    if isToolFavorited(tool) then
        dlog("skip favored", tool.Name)
        return false
    end
    if not lazySellRE() then
        publishStatus("SellPetShopSelected missing")
        return false
    end
    unequipHeldTools()
    local ok, err = pcall(function()
        SellPetShopSelected:FireServer(tool)
    end)
    if not ok then
        dlog("SellPetShopSelected fail", err)
        return false
    end
    local deadline = os.clock() + SELL_WAIT_SEC
    while os.clock() < deadline do
        if not tool.Parent then
            return true
        end
        task.wait(0.05)
    end
    return (tool.Parent == nil)
end

local function sellBatchTools(list)
    if type(list) ~= "table" or #list == 0 then
        return 0
    end
    if not lazySellRE() then
        publishStatus("SellPetShopSelected missing")
        return 0
    end
    unequipHeldTools()
    local pending = {}
    for _, item in ipairs(list) do
        local tool = item and item.tool
        if tool and tool.Parent and not isToolFavorited(tool) then
            local ok = pcall(function()
                SellPetShopSelected:FireServer(tool)
            end)
            if ok then
                pending[#pending + 1] = tool
            end
        end
    end
    if #pending == 0 then
        return 0
    end
    local deadline = os.clock() + SELL_WAIT_SEC
    while os.clock() < deadline do
        local anyLeft = false
        for _, tool in ipairs(pending) do
            if tool.Parent then
                anyLeft = true
                break
            end
        end
        if not anyLeft then
            break
        end
        task.wait(0.05)
    end
    local sold = 0
    for _, tool in ipairs(pending) do
        if tool.Parent == nil then
            sold += 1
        end
    end
    return sold
end

local function clearSellNowUi()
    G.AUTO_SELL_PET_NOW = false
    _G.AUTO_SELL_PET_NOW = false
    local setUi = G.__AUTO_SELL_PET_SET_TOGGLE or _G.__AUTO_SELL_PET_SET_TOGGLE
    if type(setUi) == "function" then
        pcall(setUi, false, true)
    end
end

local function finishSellNow(reason)
    LAST_ACTION = tostring(reason or "done")
    clearSellNowUi()
    if autoEnabled() then
        publishStatus(LAST_ACTION)
        return
    end
    publishStatus(LAST_ACTION)
    RUNNING = false
    STOP_TOKEN += 1
    THREAD = nil
end

local function tickOnce()
    if not hasRestrictiveFilter() then
        MATCH_COUNT = 0
        if sellNowEnabled() then
            finishSellNow("set pet type / rarity / mutation")
        else
            publishStatus("set pet type / rarity / mutation")
        end
        return
    end
    local ok, list = pcall(collectSellTools)
    if not ok or type(list) ~= "table" then
        MATCH_COUNT = 0
        publishStatus("scan fail")
        return
    end
    MATCH_COUNT = #list
    if #list == 0 then
        if sellNowEnabled() then
            finishSellNow("done")
        else
            publishStatus("auto idle · match 0")
        end
        return
    end
    local need = minPets()
    if autoEnabled() and not sellNowEnabled() and need > 0 and #list < need then
        publishStatus(("wait pets %d/%d"):format(#list, need))
        return
    end
    if delaySec() <= 0 then
        LAST_ACTION = "sell batch " .. tostring(#list)
        publishStatus(LAST_ACTION)
        local n = sellBatchTools(list)
        SOLD_COUNT += n
        local okRest, rest = pcall(collectSellTools)
        MATCH_COUNT = (okRest and type(rest) == "table") and #rest or 0
        LAST_ACTION = ("sold batch %d · left %d"):format(n, MATCH_COUNT)
        publishStatus(LAST_ACTION)
        if MATCH_COUNT == 0 and sellNowEnabled() then
            finishSellNow("done")
        end
        return
    end
    local item = list[1]
    local ptype = item and item.petType or "?"
    LAST_ACTION = "sell " .. tostring(ptype)
    publishStatus(LAST_ACTION)
    if sellOneTool(item.tool) then
        SOLD_COUNT += 1
        LAST_ACTION = "sold " .. tostring(ptype)
        publishStatus(LAST_ACTION)
        local okRest, rest = pcall(collectSellTools)
        MATCH_COUNT = (okRest and type(rest) == "table") and #rest or 0
        if MATCH_COUNT == 0 and sellNowEnabled() then
            finishSellNow("done")
        end
    else
        LAST_ACTION = "sell fail " .. tostring(ptype)
        publishStatus(LAST_ACTION)
    end
end

function M.GetStatusText()
    local autoOn = autoEnabled()
    local nowOn = sellNowEnabled()
    if not hasRestrictiveFilter() then
        MATCH_COUNT = 0
        return string.format(
            "Auto %s · Sell Now %s · sold %d · match 0\nset pet type / rarity / mutation",
            autoOn and "ON" or "OFF",
            nowOn and "ON" or "OFF",
            SOLD_COUNT
        )
    end
    local ok, list = pcall(collectSellTools)
    if not ok or type(list) ~= "table" then
        return string.format(
            "Auto %s · Sell Now %s · sold %d · match %d\nscan fail",
            autoOn and "ON" or "OFF",
            nowOn and "ON" or "OFF",
            SOLD_COUNT,
            MATCH_COUNT
        )
    end
    MATCH_COUNT = #list
    local need = minPets()
    local line2 = typeCountLine(list)
    if autoOn and not nowOn and need > 0 and MATCH_COUNT < need then
        line2 = ("wait pets %d/%d"):format(MATCH_COUNT, need)
    elseif LAST_STATUS ~= "" and LAST_STATUS ~= "idle" then
        line2 = LAST_STATUS .. " · " .. line2
    end
    return string.format(
        "Auto %s · Sell Now %s · sold %d · match %d\n%s",
        autoOn and "ON" or "OFF",
        nowOn and "ON" or "OFF",
        SOLD_COUNT,
        MATCH_COUNT,
        line2
    )
end

function M.isRunning()
    return RUNNING
end
M.IsRunning = M.isRunning

function M.stop()
    RUNNING = false
    STOP_TOKEN += 1
    THREAD = nil
    if LAST_ACTION ~= "done" then
        LAST_ACTION = "stopped"
        publishStatus("stopped")
    end
end
M.Stop = M.stop

function M.start()
    if not wantRun() then
        if RUNNING then
            M.stop()
        end
        return
    end
    if RUNNING then return end
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    publishStatus("running")
    LAST_ACTION = "running"
    THREAD = task.spawn(function()
        while RUNNING and token == STOP_TOKEN and wantRun() do
            pcall(tickOnce)
            local w = delaySec()
            if w <= 0 then
                if type(LAST_STATUS) == "string" and (string.find(LAST_STATUS, "wait", 1, true) or string.find(LAST_STATUS, "idle", 1, true)) then
                    w = 1
                else
                    w = 0.2
                end
            end
            task.wait(w)
        end
        if token == STOP_TOKEN then
            RUNNING = false
            THREAD = nil
            if LAST_ACTION ~= "done" and not wantRun() then
                publishStatus("stopped")
                LAST_ACTION = "stopped"
            end
        end
    end)
end
M.Start = M.start

function M.SetEnabled(on)
    G.AUTO_SELL_PET_NOW = (on == true)
    _G.AUTO_SELL_PET_NOW = (on == true)
    if on == true then
        M.start()
    elseif not autoEnabled() then
        M.stop()
    end
    return sellNowEnabled()
end
M.setEnabled = M.SetEnabled

function M.SetAutoEnabled(on)
    G.AUTO_SELL_PET_ENABLED = (on == true)
    _G.AUTO_SELL_PET_ENABLED = (on == true)
    if on == true then
        M.start()
    elseif not sellNowEnabled() then
        M.stop()
    end
    return autoEnabled()
end
M.setAutoEnabled = M.SetAutoEnabled

function M.SyncFromState()
    G.AUTO_SELL_PET_NOW = false
    _G.AUTO_SELL_PET_NOW = false
    if autoEnabled() then
        M.start()
    elseif not sellNowEnabled() then
        M.stop()
    end
    return autoEnabled()
end
M.syncFromState = M.SyncFromState

publishStatus("idle")
return M

