-- model di UpdateService → registry type
local MODEL_TO_TYPE = {
    DinoCraftingTable          = "DinoEventWorkbench",
    EventCraftingWorkBench     = "GearEventWorkbench",
    SeedEventCraftingWorkBench = "SeedEventWorkbench",
    GiantCraftingWorkBench     = "GiantBeanstalkEventWorkbench",
}

local UPDATE_SERVICE_PATHS = {
    DinoEventWorkbench = { folder = "DinoEvent",  model = "DinoCraftingTable" },
    SeedEventWorkbench = { folder = "SeedEvent",  model = "SeedEventCraftingWorkBench" },
    GearEventWorkbench = { folder = "GearEvent",  model = "EventCraftingWorkBench" },
}

local MACHINE_CACHE = {}

local RUNNING    = false
local STOP_TOKEN = 0
local THREAD     = nil

local STATUS = {
    state     = "idle",
    recipe    = "",
    machine   = "",
    step      = "",
    message   = "",
    queue     = 0,
    crafted   = 0,
    updatedAt = 0,
}

local function touchStatus()
    STATUS.updatedAt = os.clock()
end

local function setStatus(patch)
    for k, v in pairs(patch or {}) do
        STATUS[k] = v
    end
    touchStatus()
end

local function log(...)
    if CONFIG.DEBUG then
    print("[AutoCraft]", ...)
  end
end

local function dlog(...)
    if CONFIG.DEBUG then
        print("[AutoCraft DBG]", ...)
    end
end

local function warnlog(...)
    warn("[AutoCraft]", ...)
end

local function waitStep(sec)
    task.wait(tonumber(sec) or CONFIG.STEP_DELAY or 2)
end

local function normUUID(u)
    if not u then return nil end
    return tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
end

local function inventoryItemName(rec)
    if type(rec) ~= "table" then return "" end
    local d = rec.ItemData or {}
    local itype = tostring(rec.ItemType or rec.Type or ""):lower():gsub("%s+", "")
    if itype == "petboost" then
        local size = d.PetBoostSize
        local btype = d.PetBoostType
        if size and btype and type(PetBoostRegistry) == "table" then
            local map = PetBoostRegistry.BoostTypeToPetModelName
            local model = type(map) == "table" and map[btype]
            if model then
                return tostring(size) .. " " .. tostring(model)
            end
        end
    end
    return tostring(
        d.ItemName or d.Value or d.EggName or d.HoldableName or d.FoodName or d.Name
        or d.PetName or d.DisplayName or d.ShardType or d.Type or ""
    )
end

local ITEM_NAME_ALIASES = {
    smallpettoy = "smalltoy",
    smallpassiveboost = "smalltoy",
    smallxpboost = "smalltreat",
    smallpettreat = "smalltreat",
    mediumpettoy = "mediumtoy",
    mediumpassiveboost = "mediumtoy",
    mediumxpboost = "mediumtreat",
    mediumpettreat = "mediumtreat",
    largepettoy = "largetoy",
    largepassiveboost = "largetoy",
    largexpboost = "smithtreat",
    largepettreat = "smithtreat",
}

local function canonItemName(s)
    local k = tostring(s or ""):lower():gsub("%s+", "")
    return ITEM_NAME_ALIASES[k] or k
end

local function namesMatchCanon(a, b)
    local ca, cb = canonItemName(a), canonItemName(b)
    return ca ~= "" and ca == cb
end

local function normalizeItemType(itemType)
    local t = tostring(itemType or ""):lower():gsub("%s+", "")
    if t == "petegg" or t == "egg" then return "petegg" end
    -- Resep Food (Corndog) sering tersimpan sebagai Holdable di inventory
    if t == "food" or t == "holdable" or t == "fruit" then return "food" end
    if t == "petboost" or t == "treat" or t == "toy" then return "petboost" end
    return t
end

local function recordTypesCompatible(needType, gotType, needName)
    needType = normalizeItemType(needType)
    gotType = normalizeItemType(gotType)
    if needType == "" or gotType == "" then return true end
    if needType == gotType then return true end

    -- Gear / Harvest Tool: inventory kadang pakai nama item sebagai ItemType
    if needName and tostring(needName) ~= "" then
        local want = tostring(needName):lower():gsub("%s+", "")
        if gotType == want or needType == want then return true end
    end

    return false
end

local function recordItemType(rec)
    if type(rec) ~= "table" then return "" end
    return normalizeItemType(rec.ItemType or rec.Type)
end

local function itemNameMatches(needName, rec)
    if not needName or needName == "" or type(rec) ~= "table" then return false end
    if namesMatchCanon(needName, inventoryItemName(rec)) then return true end
    if namesMatchCanon(needName, rec.ItemType) then return true end
    return false
end

local function slotFilterName(slotDef)
    if type(slotDef) ~= "table" then return nil end
    local d = slotDef.ItemData
    if type(d) == "table" then
        local n = d.ItemName or d.EggName or d.HoldableName or d.FoodName or d.Name
            or d.PetName or d.DisplayName or d.ShardType or d.CrateType or d.Type
        if n and tostring(n) ~= "" then
            return tostring(n)
        end
    end
    return slotDef.Filter or slotDef.RequiredName or slotDef.Name
        or slotDef.EggName or slotDef.HoldableName or slotDef.DisplayName
end

local function slotItemType(slotDef)
    if type(slotDef) ~= "table" then return nil end
    return slotDef.ItemType or slotDef.Type or slotDef.itemType
end

local function getToolUUID(tool)
    if not tool then return nil end
    return tool:GetAttribute("c")
        or tool:GetAttribute("C")
        or tool:GetAttribute("PET_UUID")
        or tool:GetAttribute("UUID")
end

local function recordNameMatchesSlot(slotDef, rec)
    if type(slotDef) ~= "table" or type(rec) ~= "table" then return false end

    local needType = normalizeItemType(slotItemType(slotDef))
    local needName = slotFilterName(slotDef)
    if not needName or tostring(needName) == "" then return true end

    local want = tostring(needName):lower()
    local d = rec.ItemData or {}

    if needType == "petboost" then
        return namesMatchCanon(needName, inventoryItemName(rec))
    end

    if needType == "holdable" or needType == "food" then
        return namesMatchCanon(needName, inventoryItemName(rec))
    end

    if needType == "seed" then
        local n = d.ItemName or d.SeedName or d.Name
        return n and tostring(n):lower() == want
    end

    if needType == "petegg" then
        local n = d.EggName or d.ItemName or d.Name
        return n and tostring(n):lower() == want
    end

    if needType == "pet" then
        local n = d.PetName or d.ItemName or d.Name or d.DisplayName
        return n and tostring(n):lower() == want
    end

    return itemNameMatches(needName, rec)
end

local function recordMatchesSlot(slotDef, rec)
    if type(slotDef) ~= "table" or type(rec) ~= "table" then return false end

    local needType = slotItemType(slotDef)
    local gotType = rec.ItemType or rec.Type
    local needName = slotFilterName(slotDef)

    if not recordTypesCompatible(needType, gotType, needName) then
        return false
    end

    return recordNameMatchesSlot(slotDef, rec)
end

local function uuidCoreMatch(a, b)
    local ca, cb = normUUID(a), normUUID(b)
    return ca and cb and ca == cb
end

local function lookupInventory(inv, uuid)
    if type(inv) ~= "table" then return nil, nil end
    local core = normUUID(uuid)
    if not core then return nil, nil end
    for key, rec in pairs(inv) do
        if normUUID(key) == core then
            return rec, key
        end
    end
    return nil, nil
end

local function buildToolMapByAttrC()
    local map = {}

    local function scan(container)
        if not container then return end
        for _, inst in ipairs(container:GetDescendants()) do
            if inst:IsA("Tool") then
                local core = normUUID(getToolUUID(inst))
                if core and not map[core] then
                    map[core] = inst
                end
            end
        end
    end

    scan(backpack)
    scan(player.Character)
    return map
end

local function findToolInMap(toolMap, core)
    if not core or type(toolMap) ~= "table" then return nil end
    if toolMap[core] then return toolMap[core] end
    for key, tool in pairs(toolMap) do
        if uuidCoreMatch(key, core) then
            return tool
        end
    end
    return nil
end

local function isUUIDUsed(usedUUIDs, core, rawKey)
    if type(usedUUIDs) ~= "table" then return false end
    if core and usedUUIDs[core] then return true end
    if rawKey and usedUUIDs[rawKey] then return true end
    if rawKey and core and usedUUIDs[normUUID(rawKey)] then return true end
    return false
end

local function unequipHands()
    local ch = player.Character
    if not ch then return end
    for _, t in ipairs(ch:GetChildren()) do
        if t:IsA("Tool") then
            t.Parent = backpack
        end
    end
end

local CURRENT_TEAM_MODE = nil
local SWAP_SKILL_STOPPED_BY_CRAFT = false

local function getSwapSkillModule()
    return rawget(_G, "SwapSkill") or rawget(G, "SwapSkill")
        or rawget(_G, "SwapSkillModule") or rawget(G, "SwapSkillModule")
end

local function stopSwapSkillForCraft()
    local SS = getSwapSkillModule()
    if not SS or type(SS.Stop) ~= "function" then
        return false
    end
    local wasRunning = false
    if type(SS.IsRunning) == "function" then
        local ok, v = pcall(function() return SS:IsRunning() end)
        wasRunning = ok and v == true
    elseif _G.__SWAP_SKILL_RUNNING == true then
        wasRunning = true
    end
    if wasRunning then
        SWAP_SKILL_STOPPED_BY_CRAFT = true
    end
    pcall(SS.Stop)
    dlog("swap skill stopped for craft claim team")
    return true
end

local function startSwapSkillForCraft()
    local SS = getSwapSkillModule()
    if not SS or type(SS.Start) ~= "function" then
        return false
    end
    pcall(function() SS.Start() end)
    SWAP_SKILL_STOPPED_BY_CRAFT = false
    dlog("swap skill started for craft reduce team")
    return true
end

local function restoreSwapSkillAfterCraft()
    if not SWAP_SKILL_STOPPED_BY_CRAFT then
        return
    end
    local STATE = rawget(_G, "STATE")
    local enabled = type(STATE) == "table"
        and type(STATE.swap_skill) == "table"
        and STATE.swap_skill.enabled == true
    if not enabled then
        SWAP_SKILL_STOPPED_BY_CRAFT = false
        return
    end
    startSwapSkillForCraft()
end

local function bracedUUID(u)
    local core = normUUID(u)
    if not core then return nil end
    return "{" .. core .. "}"
end

local function getTeamSet(mode)
    if mode == "claim" then
        return G.AUTO_CRAFT_TEAM_BEFORE_CLAIM or _G.AUTO_CRAFT_TEAM_BEFORE_CLAIM or {}
    end
    if mode == "submit" then
        return G.AUTO_CRAFT_TEAM_SUBMIT or _G.AUTO_CRAFT_TEAM_SUBMIT or {}
    end
    if mode == "reduce" then
        return G.AUTO_CRAFT_TEAM_REDUCE or _G.AUTO_CRAFT_TEAM_REDUCE or {}
    end
    return {}
end

local function teamSetHasPets(teamSet)
    for _, on in pairs(teamSet or {}) do
        if on then return true end
    end
    return false
end

local function listTeamUUIDs(teamSet)
    local out, seen = {}, {}
    for k, on in pairs(teamSet or {}) do
        if on then
            local b = bracedUUID(k)
            if b and not seen[b] then
                seen[b] = true
                out[#out + 1] = b
            end
        end
    end
    table.sort(out)
    return out
end

local function getEquippedPetList()
    local list = {}
    local data = getPlayerData()
    local petequip = data and data.PetsData and data.PetsData.EquippedPets
    if type(petequip) ~= "table" then return list end

    for _, value in pairs(petequip) do
        local uuid
        if type(value) == "string" then
            uuid = value
        elseif type(value) == "table" then
            uuid = value.UUID or value.Uuid or value.PetUUID or value.uuid
        end
        if uuid then
            list[#list + 1] = uuid
        end
    end
    return list
end

local function getEquippedPetSet()
    local set = {}
    for _, uuid in ipairs(getEquippedPetList()) do
        local b = bracedUUID(uuid)
        if b then set[b] = true end
    end
    return set
end

local function unequipPetUUID(uuid)
    if not uuid then return end
    local raw = normUUID(uuid) or tostring(uuid)
    local br = bracedUUID(uuid)
    pcall(function() PetsService:UnequipPet(raw) end)
    if br and br ~= raw then
        pcall(function() PetsService:UnequipPet(br) end)
    end
end

local function equipPetUUID(uuid)
    if not uuid then return end
    local raw = normUUID(uuid) or tostring(uuid)
    local br = bracedUUID(uuid)
    pcall(function() PetsService:EquipPet(br or raw) end)
    if br and br ~= raw then
        pcall(function() PetsService:EquipPet(raw) end)
    end
end

local function forceUnequipAllVerified(maxSec)
    maxSec = tonumber(maxSec) or CONFIG.TEAM_UNEQUIP_VERIFY_SEC or 5
    if maxSec < 0.5 then maxSec = 0.5 end

    local t0 = os.clock()
    while (os.clock() - t0) < maxSec do
        local list = getEquippedPetList()
        if #list == 0 then
            return true
        end

        for _, uuid in ipairs(list) do
            unequipPetUUID(uuid)
        end

        task.wait(CONFIG.TEAM_UNEQUIP_POLL or 0.35)
    end

    return #getEquippedPetList() == 0
end

local function getMaxEquippedPets()
    local data = getPlayerData()
    local m = data and data.PetsData and data.PetsData.MutableStats
    return math.max(1, tonumber(m and m.MaxEquippedPets) or 3)
end

local function teamMatchesEquipped(teamSet)
    local targets = listTeamUUIDs(teamSet)
    if #targets == 0 then return true end
    local equipped = getEquippedPetSet()
    local eqCount = 0
    for _ in pairs(equipped) do eqCount += 1 end
    if eqCount ~= #targets then return false end
    for _, uuid in ipairs(targets) do
        if not equipped[uuid] then return false end
    end
    return true
end

local function applyPetTeam(mode)
    mode = tostring(mode or "none")
    local teamSet = getTeamSet(mode)

    if not teamSetHasPets(teamSet) then
        CURRENT_TEAM_MODE = mode
        return false
    end

    -- Skip hanya kalau mode sama DAN sudah pas (reduce idle poll).
    -- Ganti mode (claim/submit/reduce) selalu full cycle meski pet overlap.
    if CURRENT_TEAM_MODE == mode and teamMatchesEquipped(teamSet) then
        return false
    end

    if rawget(_G, "__EQUIP_LOCK") and tonumber(_G.__EQUIP_LOCK) and _G.__EQUIP_LOCK > os.clock() then
        dlog("equip lock active, skip team", mode)
        return false
    end

    local targetList = listTeamUUIDs(teamSet)
    local maxEq = getMaxEquippedPets()

    if mode == "claim" then
        stopSwapSkillForCraft()
    end

    -- Ganti team: unequip SEMUA dulu (verified), baru equip SEMUA team baru.
    local cleared = forceUnequipAllVerified(CONFIG.TEAM_UNEQUIP_VERIFY_SEC)
    if not cleared then
        dlog("warning: masih ada pet equipped setelah force unequip, mode=", mode)
    end

    local toEquip = {}
    for i = 1, math.min(#targetList, maxEq) do
        toEquip[#toEquip + 1] = targetList[i]
    end

    for _, uuid in ipairs(toEquip) do
        equipPetUUID(uuid)
    end

    CURRENT_TEAM_MODE = mode
    dlog("pet team applied:", mode, #targetList, "pets")

    if mode == "claim" or mode == "submit" then
        waitStep(CONFIG.TEAM_EQUIP_DELAY_CLAIM_SUBMIT)
    end

    if mode == "reduce" then
        startSwapSkillForCraft()
    end

    return true
end

local function getRecipes()
    return (RecipeRegistry and RecipeRegistry.ItemRecipes) or {}
end

local function flattenRecipe(recipeId)
    local raw = getRecipes()
    if raw[recipeId] and type(raw[recipeId]) == "table" then
        return raw[recipeId]
    end
    for _, val in pairs(raw) do
        if type(val) == "table" and type(val[recipeId]) == "table" then
            return val[recipeId]
        end
    end
    return nil
end

local function getRecipe(name)
    local r = getRecipes()
    return r[name] or r[tostring(name)] or flattenRecipe(name)
end

local function getMachineDef(objectType)
    return ObjectRegistry and ObjectRegistry[objectType]
end

local function getSlotRequirements(recipe, machineDef)
    if type(recipe) == "table" then
        for _, key in ipairs({ "Inputs", "SlotInputs", "InputSlots", "Ingredients" }) do
            local block = recipe[key]
            if type(block) == "table" and next(block) then
                return block, key
            end
        end
    end
    if type(machineDef) == "table" and type(machineDef.Slots) == "table" then
        return machineDef.Slots, "MachineSlots"
    end
    return nil, nil
end

local function isCurrencySlot(slotDef)
    if type(slotDef) ~= "table" then return false end
    local t = tostring(slotItemType(slotDef) or ""):lower()
    local n = tostring(slotFilterName(slotDef) or ""):lower()
    if t == "sheckles" or t == "currency" or t == "money" or n == "sheckles" then
        return true
    end
    local d = slotDef.ItemData
    if type(d) == "table" then
        local dn = tostring(d.ItemName or d.Currency or d.CurrencyType or ""):lower()
        if dn == "sheckles" then return true end
    end
    if (t == "" or t == "item") and n == "" then
        local cost = tonumber(slotDef.Amount or slotDef.Sheckles or slotDef.Cost)
        if cost and cost >= 1000 then return true end
    end
    return false
end

local function findUpdateServiceMachine(objectType)
    objectType = tostring(objectType or "")
    local modules = ReplicatedStorage:FindFirstChild("Modules")
    local updateSvc = modules and modules:FindFirstChild("UpdateService")
    if not updateSvc then return nil end

    local path = UPDATE_SERVICE_PATHS[objectType]
    if path then
        local folder = updateSvc:FindFirstChild(path.folder)
        if folder then
            local model = folder:FindFirstChild(path.model)
            if model then return model end
        end
    end

    for modelName, otype in pairs(MODEL_TO_TYPE) do
        if otype == objectType then
            local found = updateSvc:FindFirstChild(modelName, true)
            if found then return found end
        end
    end

    return nil
end

local function craftingScanRoots()
    local roots, seen = {}, {}
    local function add(inst)
        if not inst or seen[inst] then return end
        seen[inst] = true
        table.insert(roots, inst)
    end

    add(workspace:FindFirstChild("CraftingTables"))

    local npcs = workspace:FindFirstChild("NPCS")
    add(npcs and npcs:FindFirstChild("CraftingTables"))

    local interaction = workspace:FindFirstChild("Interaction")
    if interaction then
        add(interaction:FindFirstChild("CraftingTable"))
        add(interaction:FindFirstChild("CraftingTables"))
    end

    if #roots == 0 then
        add(workspace)
    end
    return roots
end

local function scanCraftingTablesFor(matchFn)
    for _, root in ipairs(craftingScanRoots()) do
        if matchFn(root) then
            return root
        end
        for _, inst in ipairs(root:GetDescendants()) do
            local hit = matchFn(inst)
            if hit then return hit end
        end
    end
    return nil
end

local function findMachineInstance(objectType)
    objectType = tostring(objectType or "")

    local cacheKey = "type:" .. objectType
    local cached = MACHINE_CACHE[cacheKey]
    if cached and (os.clock() - cached.at) < CONFIG.MACHINE_CACHE_TTL then
        if cached.machine and cached.machine.Parent then
            return cached.machine
        end
    end

    local updateMachine = findUpdateServiceMachine(objectType)
    if updateMachine then
        MACHINE_CACHE[cacheKey] = { machine = updateMachine, at = os.clock() }
        dlog("machine UpdateService", objectType, updateMachine:GetFullName())
        return updateMachine
    end

    local found = scanCraftingTablesFor(function(inst)
        local otype = inst:GetAttribute("CraftingObjectType")
        if otype and tostring(otype) == objectType then
            return inst
        end
        return nil
    end)

    if found then
        MACHINE_CACHE[cacheKey] = { machine = found, at = os.clock() }
    end
    return found
end

local function getGcoTable()
    local data = getPlayerData()
    return data and data.CraftingData and data.CraftingData.GlobalCraftingObjectData
end

local function getCraftDataByGcoKey(gcoKey)
    local gco = getGcoTable()
    if not gco or not gcoKey then return nil end
    return gco[tostring(gcoKey)]
end

-- MachineData key bisa beda dari GCO key (Workbench-1 → GearEventWorkbench)
local function resolveMachineDataKey(craftData, gcoKey)
    gcoKey = tostring(gcoKey or "")
    if type(craftData) ~= "table" then return gcoKey end
    local md = craftData.MachineData
    if type(md) ~= "table" then return gcoKey end

    if type(md[gcoKey]) == "table" and type(md[gcoKey].CraftingItems) == "table" then
        return gcoKey
    end
    if getMachineDef(gcoKey) and type(md[gcoKey]) == "table" then
        return gcoKey
    end

    for key, block in pairs(md) do
        if type(block) == "table" and type(block.CraftingItems) == "table" then
            return tostring(key)
        end
    end

    for key, block in pairs(md) do
        if type(block) == "table" then
            return tostring(key)
        end
    end

    return gcoKey
end

local function getObjectCraftingData(machine, objectType, gcoKey)
    local gco = getGcoTable()
    if not gco then return nil end

    if gcoKey and gco[tostring(gcoKey)] then
        return gco[tostring(gcoKey)]
    end

    local objectId = machine and machine:GetAttribute("CraftingObjectId")
    if objectId and gco[objectId] then
        return gco[objectId]
    end

    local otype = machine and machine:GetAttribute("CraftingObjectType")
    if otype and gco[otype] then
        return gco[otype]
    end
    if objectType and gco[objectType] then
        return gco[objectType]
    end
    return nil
end

-- gco[gcoKey].MachineData[machineDataKey].CraftingItems[slot]
local function getCraftingSlot(craftData, machineDataKey, slot)
    if type(craftData) ~= "table" then return nil end
    slot = slot or CONFIG.CRAFT_SLOT or 1
    machineDataKey = tostring(machineDataKey or "")

    local md = craftData.MachineData
    if type(md) ~= "table" then return nil end

    local nested = md[machineDataKey]
    if type(nested) == "table" then
        local ci = nested.CraftingItems or nested.Slots
        if type(ci) == "table" then
            local sd = ci[slot] or ci[tostring(slot)]
            if type(sd) == "table" then return sd end
        end
    end

    for _, block in pairs(md) do
        if type(block) == "table" and type(block.CraftingItems) == "table" then
            local sd = block.CraftingItems[slot] or block.CraftingItems[tostring(slot)]
            if type(sd) == "table" then return sd end
        end
    end

    return md[slot] or md[tostring(slot)]
end

local function buildGcoContext(gcoKey)
    gcoKey = tostring(gcoKey or "")
    local craftData = getCraftDataByGcoKey(gcoKey)
    if not craftData then return nil end

    local machineDataKey = resolveMachineDataKey(craftData, gcoKey)
    return {
        gcoKey         = gcoKey,
        machineDataKey = machineDataKey,
        remoteType     = machineDataKey,
        craftData      = craftData,
    }
end

local function listGcoWorkstations()
    local gco = getGcoTable()
    local out = {}
    if type(gco) ~= "table" then return out end

    for gcoKey, craftData in pairs(gco) do
        if type(craftData) == "table" then
            local ctx = buildGcoContext(gcoKey)
            if ctx then
                table.insert(out, ctx)
            end
        end
    end

    table.sort(out, function(a, b) return a.gcoKey < b.gcoKey end)
    return out
end

local function makeWorkstationCtx(gcoKey, machineDataKey)
    gcoKey = tostring(gcoKey or "")
    machineDataKey = tostring(machineDataKey or gcoKey)
    if gcoKey == "" then return nil end

    local ctx = buildGcoContext(gcoKey)
    if ctx then
        if machineDataKey ~= "" then
            ctx.machineDataKey = machineDataKey
            ctx.remoteType = machineDataKey
        end
        return ctx
    end

    if machineDataKey ~= "" and machineDataKey ~= gcoKey then
        ctx = buildGcoContext(machineDataKey)
        if ctx then return ctx end
    end

    return {
        gcoKey         = gcoKey,
        machineDataKey = machineDataKey ~= "" and machineDataKey or gcoKey,
        remoteType     = machineDataKey ~= "" and machineDataKey or gcoKey,
        craftData      = getCraftDataByGcoKey(gcoKey) or getCraftDataByGcoKey(machineDataKey),
    }
end

-- GCO only lists benches the server already registered. Event benches
-- (Giant Beanstalk, etc.) can exist in the world before that entry exists.
local function listTargetWorkstations(byMachine)
    local out = {}
    local seen = {}

    local function addCtx(ctx)
        if type(ctx) ~= "table" then return end
        local key = tostring(ctx.gcoKey) .. "\0" .. tostring(ctx.machineDataKey)
        if seen[key] then return end
        seen[key] = true
        table.insert(out, ctx)
    end

    for _, ctx in ipairs(listGcoWorkstations()) do
        addCtx(ctx)
    end

    if type(byMachine) == "table" then
        for objectType in pairs(byMachine) do
            objectType = tostring(objectType or "")
            if objectType ~= "" then
                local have = false
                for _, ctx in ipairs(out) do
                    if ctx.machineDataKey == objectType or ctx.gcoKey == objectType then
                        have = true
                        break
                    end
                end
                if not have then
                    addCtx(makeWorkstationCtx(objectType, objectType))
                end
            end
        end
    end

    return out
end

local function findMachineForGco(gcoKey, machineDataKey)
    gcoKey = tostring(gcoKey or "")
    machineDataKey = tostring(machineDataKey or "")

    local cacheKey = gcoKey .. "\0" .. machineDataKey
    local cached = MACHINE_CACHE[cacheKey]
    if cached and (os.clock() - cached.at) < CONFIG.MACHINE_CACHE_TTL then
        if cached.machine and cached.machine.Parent then
            return cached.machine
        end
    end

    local function remember(m)
        if m then
            MACHINE_CACHE[cacheKey] = { machine = m, at = os.clock() }
        end
        return m
    end

    local byId = scanCraftingTablesFor(function(inst)
        local oid = inst:GetAttribute("CraftingObjectId")
        if oid and tostring(oid) == gcoKey then
            return inst
        end
        return nil
    end)
    if byId then
        dlog("machine by CraftingObjectId", gcoKey, byId:GetFullName())
        return remember(byId)
    end

    local byType = scanCraftingTablesFor(function(inst)
        local otype = inst:GetAttribute("CraftingObjectType")
        if otype and tostring(otype) == machineDataKey then
            return inst
        end
        return nil
    end)
    if byType then return remember(byType) end

    local m = findUpdateServiceMachine(machineDataKey)
    if m then return remember(m) end

    return remember(findMachineInstance(machineDataKey))
end

local function evaluateSlot(slotData)
    if type(slotData) ~= "table" then
        return "empty", nil, 0
    end

    local tLeft = tonumber(slotData.TimeRemaining or slotData.TimeLeft) or 0
    local isDone = slotData.IsDone == true
    local recipeId = slotData.RecipeId

    dlog("slot eval", "RecipeId=", recipeId, "tLeft=", tLeft, "IsDone=", isDone)

    if isDone or (tLeft <= 0 and recipeId ~= nil and tostring(recipeId) ~= "") then
        return "claim", slotData, tLeft
    end
    if tLeft > 0 or slotData.IsCrafting == true or slotData.Crafting == true then
        return "crafting", slotData, tLeft
    end
    if recipeId ~= nil and tostring(recipeId) ~= "" then
        return "busy", slotData, tLeft
    end
    return "empty", slotData, tLeft
end

local function getGcoSlotState(ctx, slot)
    if type(ctx) ~= "table" then return "empty", nil, 0 end
    local slotData = getCraftingSlot(ctx.craftData, ctx.machineDataKey, slot)
    return evaluateSlot(slotData)
end

-- DataService.InventoryData[uuid] → cari Tool attr "c" == uuid
local function findToolForSlot(slotDef, usedUUIDs, toolMap)
    usedUUIDs = usedUUIDs or {}
    toolMap = toolMap or buildToolMapByAttrC()

    local inv = getInventoryData()
    if type(inv) ~= "table" then return nil, nil, nil, nil end

    for invKey, rec in pairs(inv) do
        if type(rec) == "table" and recordMatchesSlot(slotDef, rec) then
            local core = normUUID(invKey) or normUUID(rec.ItemData and rec.ItemData.UUID)
            if core and not isUUIDUsed(usedUUIDs, core, invKey) then
                local tool = findToolInMap(toolMap, core)
                if tool then
                    return tool, getToolUUID(tool), rec, invKey
                end
            end
        end
    end

    return nil, nil, nil, nil
end

local function buildCraftPlan(recipeName, objectType)
    local recipe = getRecipe(recipeName)
    if not recipe then return nil, "recipe_not_found" end

    local machineDef = getMachineDef(objectType)
    if not machineDef then return nil, "machine_not_found" end

    local slotReqs = getSlotRequirements(recipe, machineDef)
    if type(slotReqs) ~= "table" or not next(slotReqs) then
        return nil, "no_slot_requirements"
    end

    local plan = {
        recipeName = recipeName,
        objectType = objectType,
        craftSlot  = CONFIG.CRAFT_SLOT or 1,
        inputs     = {},
    }

    local used = {}
    local toolMap = buildToolMapByAttrC()
    local slots = {}
    for idx, def in pairs(slotReqs) do
        table.insert(slots, { index = idx, def = def })
    end
    table.sort(slots, function(a, b)
        local na, nb = tonumber(a.index), tonumber(b.index)
        if na and nb then return na < nb end
        return tostring(a.index) < tostring(b.index)
    end)

    for _, s in ipairs(slots) do
        if isCurrencySlot(s.def) then
            plan.inputs[s.index] = { currency = true, slotDef = s.def }
        else
            local tool, uuid, invRec, invKey = findToolForSlot(s.def, used, toolMap)
            if not tool then
                return nil, ("missing_" .. tostring(slotFilterName(s.def) or slotItemType(s.def)))
            end
            local core = normUUID(uuid) or normUUID(invKey)
            if core then used[core] = true end
            if uuid then used[uuid] = true end
            local itype = (invRec and (invRec.ItemType or invRec.Type)) or slotItemType(s.def) or "PetEgg"
            if itype == "Pet Egg" then itype = "PetEgg" end
            plan.inputs[s.index] = {
                tool      = tool,
                uuid      = uuid,
                invRecord = invRec,
                invKey    = invKey,
                itemType  = itype,
                slotDef   = s.def,
            }
        end
    end

    return plan, "ok"
end

local function fireSetRecipe(machine, objectType, recipeName)
    CraftingRE:FireServer("SetRecipe", machine, objectType, recipeName)
end

local function fireSubmitAll(machine)
    if not machine then
        return false
    end
    local handler = CraftingStationHandler
    if type(handler) ~= "table" then
        return false
    end
    local fn = handler.SubmitAllRequiredItems or handler.SubmitAllRequiredItems
    if type(fn) ~= "function" then
        return false
    end
    return pcall(fn, handler, machine)
end

local function buildInputPayload(invRecord, invKey, uuid, fallbackType)
    local itemType = (invRecord and (invRecord.ItemType or invRecord.Type)) or fallbackType
    if itemType == "Pet Egg" then itemType = "PetEgg" end

    local itemData = {}
    if type(invRecord) == "table" and type(invRecord.ItemData) == "table" then
        for k, v in pairs(invRecord.ItemData) do
            itemData[k] = v
        end
    end

    -- referensi game: UUID mentah dari attribute tool
    itemData.UUID = itemData.UUID or uuid or invKey

    return { ItemType = itemType, ItemData = itemData }
end

local function fireInputItem(machine, objectType, slot, payload)
    dlog("InputItem", slot, payload and payload.ItemType, payload and payload.ItemData and payload.ItemData.UUID)
    CraftingRE:FireServer("InputItem", machine, objectType, slot, payload)
end

local function fireCraft(machine, objectType, slot)
    CraftingRE:FireServer("Craft", machine, objectType, slot)
end

local function fireClaim(machine, objectType, slot)
    dlog("Claim", objectType, "slot", slot, machine and machine:GetFullName())
    CraftingRE:FireServer("Claim", machine, objectType, slot)
end

local function getCraftListView()
    return G.CraftListView or _G.CraftListView
end

local function getSelectedRecipes()
    local map = G.AUTO_CRAFT_RECIPES_SELECTED or _G.AUTO_CRAFT_RECIPES_SELECTED or {}
    if next(map) == nil then
        local main = G.MAIN or _G.MAIN
        local ac = main and main.misc and main.misc.auto_craft
        if type(ac) == "table" and type(ac.recipes) == "table" then
            for _, rid in ipairs(ac.recipes) do
                map[tostring(rid)] = true
            end
        end
    end
    local list = {}
    for id, on in pairs(map) do
        if on then list[#list + 1] = tostring(id) end
    end
    table.sort(list)
    return list
end

local function resolveMachineType(recipeId)
    local clv = getCraftListView()
    if clv and type(clv.resolveRecipeMachineType) == "function" then
        local ok, mt = pcall(clv.resolveRecipeMachineType, recipeId)
        if ok and mt and tostring(mt) ~= "" then return mt end
    end
    if clv and type(clv.getRecipeMachineType) == "function" then
        local ok, mt = pcall(clv.getRecipeMachineType, recipeId)
        if ok and mt and tostring(mt) ~= "" then return mt end
    end
    local recipe = getRecipe(recipeId)
    if type(recipe) == "table" then
        local mt = recipe.CraftingObjectType or recipe.MachineType or recipe.ObjectType
        if mt and tostring(mt) ~= "" then
            return mt
        end
        local listed = recipe.MachineTypes or recipe.CraftingObjectTypes
        if type(listed) == "table" then
            return listed[1] or listed[2]
        end
    end
    return nil
end

local function stockHasEntries(stock)
    return type(stock) == "table" and next(stock) ~= nil
end

local function countCraftable(recipeId, objectType, stock)
    local clv = getCraftListView()
    if clv and type(clv.countCraftableTimes) == "function" then
        local ok, n = pcall(clv.countCraftableTimes, recipeId, objectType, stock)
        if ok then
            return tonumber(n) or 0
        end
    end
    return 0
end

local function groupRecipesByMachine(recipeIds)
    local byType = {}
    for _, recipeId in ipairs(recipeIds) do
        local objectType = resolveMachineType(recipeId)
        if objectType then
            byType[objectType] = byType[objectType] or {}
            table.insert(byType[objectType], recipeId)
        end
    end
    return byType
end

local function getSharedMaterialStock(force)
    local clv = getCraftListView()
    if clv and type(clv.getMaterialStock) == "function" then
        local ok, stock = pcall(clv.getMaterialStock, force == true)
        if ok and stockHasEntries(stock) then
            return stock
        end
    end
    return nil
end

local function recipeReadyToSubmit(recipeId, objectType, stock)
    local n = countCraftable(recipeId, objectType, stock)
    if n <= 0 then
        return false, "no_materials"
    end
    local ok, plan, why = pcall(buildCraftPlan, recipeId, objectType)
    if ok and plan then
        return true, "ok"
    end
    return false, (ok and why) or "missing_tool"
end

local function describeWaitReason(selected, craftSlot, stock)
    local ok, msg = pcall(function()
        local byMachine = groupRecipesByMachine(selected)
        local sawInventory = false
        local sawMissingTool = false

        for _, ctx in ipairs(listTargetWorkstations(byMachine)) do
            local recipeList = byMachine[ctx.machineDataKey]
            if recipeList and #recipeList > 0 then
                local phase = select(1, getGcoSlotState(ctx, craftSlot))
                if phase == "empty" then
                    for _, recipeId in ipairs(recipeList) do
                        local n = countCraftable(recipeId, ctx.machineDataKey, stock)
                        if n > 0 then
                            sawInventory = true
                            local pok, plan = pcall(buildCraftPlan, recipeId, ctx.machineDataKey)
                            if not (pok and plan) then
                                sawMissingTool = true
                            end
                        end
                    end
                end
            end
        end

        if sawMissingTool then
            return "Waiting for tools in backpack"
        end
        if sawInventory then
            return "Waiting for craft slot"
        end
        return "Waiting for materials"
    end)
    if ok and type(msg) == "string" then
        return msg
    end
    return "Waiting for materials"
end

local function recipeDisplayName(recipeId)
    if recipeId == nil or tostring(recipeId) == "" then return "" end
    local clv = getCraftListView()
    if clv and type(clv.getRecipeDisplayName) == "function" then
        local ok, name = pcall(clv.getRecipeDisplayName, recipeId)
        if ok and name and tostring(name) ~= "" then
            return tostring(name)
        end
    end
    local recipe = getRecipe(recipeId)
    if type(recipe) == "table" then
        local dn = recipe.DisplayName or recipe.Name
        if dn and tostring(dn) ~= "" then return tostring(dn) end
    end
    return tostring(recipeId)
end

-- Gate: claim / wait / empty — sama referensi handleAutoCrafting
local function handleSlotGate(ctx, craftSlot)
    if type(ctx) ~= "table" then return false, "no_context" end
    craftSlot = craftSlot or CONFIG.CRAFT_SLOT or 1

    local machine = ctx.machine or findMachineForGco(ctx.gcoKey, ctx.machineDataKey)
    if not machine then
        setStatus({
            state   = "error",
            machine = ctx.gcoKey,
            step    = "Machine not found",
            message = ctx.machineDataKey,
        })
        return false, "no_machine_instance"
    end
    ctx.machine = machine

    local phase, slotData, tLeft = getGcoSlotState(ctx, craftSlot)
    local label = ctx.gcoKey .. " / " .. ctx.machineDataKey

    if phase == "claim" then
        setStatus({
            state   = "claiming",
            machine = label,
            recipe  = slotData and slotData.RecipeId or "",
            step    = "Claiming " .. recipeDisplayName(slotData and slotData.RecipeId or ""),
        })
        unequipHands()
        fireClaim(machine, ctx.remoteType, craftSlot)
        waitStep(1.5)
        ctx.craftData = getCraftDataByGcoKey(ctx.gcoKey) or ctx.craftData
        local after = getCraftingSlot(ctx.craftData, ctx.machineDataKey, craftSlot)
        if after then
            warnlog("Slot belum kosong setelah claim:", label)
            return false, "slot_not_empty_after_claim"
        end
        local clv = getCraftListView()
        if clv and type(clv.invalidateCache) == "function" then
            pcall(clv.invalidateCache)
        end
        return true, "claimed"
    end

    if phase == "crafting" then
        setStatus({
            state   = "waiting",
            machine = label,
            recipe  = slotData and slotData.RecipeId or "",
            step    = string.format(
                "Crafting %s (%ds left)",
                recipeDisplayName(slotData and slotData.RecipeId or ""),
                math.max(0, math.floor(tLeft))
            ),
            message = "still_crafting",
        })
        return false, "still_crafting"
    end

    if phase == "busy" then
        setStatus({
            state   = "waiting",
            machine = label,
            recipe  = slotData and slotData.RecipeId or "",
            step    = "Slot busy: " .. recipeDisplayName(slotData and slotData.RecipeId or ""),
            message = "machine_busy",
        })
        return false, "machine_busy"
    end

    return true, "empty"
end

function M.craftOnce(opts)
    opts = opts or {}
    local recipeName = opts.recipeName
    local objectType = opts.objectType or opts.machineDataKey
    if not recipeName or not objectType then
        return false, "no_config"
    end

    local ctx = opts.ctx
    if not ctx then
        local gcoKey = opts.gcoKey or objectType
        ctx = buildGcoContext(gcoKey)
        if ctx then
            ctx.machineDataKey = opts.machineDataKey or ctx.machineDataKey
            ctx.remoteType = opts.remoteType or ctx.machineDataKey
        end
    end
    if not ctx then
        ctx = {
            gcoKey         = opts.gcoKey or objectType,
            machineDataKey = objectType,
            remoteType     = opts.remoteType or objectType,
            craftData      = getCraftDataByGcoKey(opts.gcoKey or objectType),
        }
    end

    local machine = opts.machine or ctx.machine or findMachineForGco(ctx.gcoKey, ctx.machineDataKey)
    if not machine then
        setStatus({ state = "error", message = "no_machine_instance", step = "Machine not found" })
        return false, "no_machine_instance"
    end
    ctx.machine = machine

    local craftSlot = CONFIG.CRAFT_SLOT or 1
    local gateOk, gateResult = handleSlotGate(ctx, craftSlot)
    if not gateOk then
        return false, gateResult
    end

    setStatus({
        state   = "prepare",
        recipe  = tostring(recipeName),
        machine = ctx.gcoKey .. " / " .. ctx.remoteType,
        step    = "Starting " .. recipeDisplayName(recipeName),
    })

    local plan, why = buildCraftPlan(recipeName, ctx.machineDataKey)
    if not plan then
        setStatus({ state = "error", message = why, step = "Failed to prepare materials" })
        return false, why
    end

    unequipHands()
    waitStep()
    setStatus({ state = "crafting", step = "Setting recipe" })
    fireSetRecipe(machine, ctx.remoteType, recipeName)
    waitStep()

    local slotIndexes = {}
    for idx in pairs(plan.inputs) do
        table.insert(slotIndexes, idx)
    end
    table.sort(slotIndexes, function(a, b)
        local na, nb = tonumber(a), tonumber(b)
        if na and nb then return na < nb end
        return tostring(a) < tostring(b)
    end)

    setStatus({ state = "crafting", step = "Submit All" })
    local usedSubmitAll = fireSubmitAll(machine)
    if usedSubmitAll then
        task.wait(math.max(0.45, 0.12 * math.max(1, #slotIndexes)))
    end

    -- Fallback InputItem for leftover slots (Submit All can succeed without filling).
    for si, slotIdx in ipairs(slotIndexes) do
        local inp = plan.inputs[slotIdx]
        if not inp.currency then
            setStatus({
                state = "crafting",
                step  = string.format("Input materials %d/%d", si, #slotIndexes),
            })
            unequipHands()
            pcall(function() inp.tool.Parent = player.Character or character end)
            task.wait(0.25)
            local payload = buildInputPayload(inp.invRecord, inp.invKey, inp.uuid, inp.itemType)
            fireInputItem(machine, ctx.remoteType, slotIdx, payload)
            waitStep()
            pcall(function()
                if inp.tool.Parent == player.Character then
                    inp.tool.Parent = backpack
                end
            end)
        end
    end

    unequipHands()
    waitStep()
    setStatus({ state = "crafting", step = "Starting craft" })
    fireCraft(machine, ctx.remoteType, craftSlot)

    STATUS.crafted = (STATUS.crafted or 0) + 1
    setStatus({ state = "done", message = "", step = "Craft started" })
    log("Craft started:", recipeName, "on", ctx.gcoKey, "/", ctx.remoteType)
    return true, "started", plan
end

local function collectWorkstationPlan(selected, craftSlot, sharedStock)
    local byMachine = groupRecipesByMachine(selected)
    local claims, submits, crafting = {}, {}, {}

    for _, ctx in ipairs(listTargetWorkstations(byMachine)) do
        local recipeList = byMachine[ctx.machineDataKey]
        if recipeList and #recipeList > 0 then
            ctx.machine = findMachineForGco(ctx.gcoKey, ctx.machineDataKey)
            ctx.craftData = getCraftDataByGcoKey(ctx.gcoKey)
                or getCraftDataByGcoKey(ctx.machineDataKey)
                or ctx.craftData

            local phase, slotData, tLeft = getGcoSlotState(ctx, craftSlot)

            if phase == "claim" then
                claims[#claims + 1] = { ctx = ctx, slotData = slotData, tLeft = tLeft }
            elseif phase == "crafting" or phase == "busy" then
                crafting[#crafting + 1] = {
                    ctx = ctx,
                    slotData = slotData,
                    tLeft = tLeft,
                    phase = phase,
                }
            elseif phase == "empty" then
                for _, recipeId in ipairs(recipeList) do
                    local okReady, ready = pcall(recipeReadyToSubmit, recipeId, ctx.machineDataKey, sharedStock)
                    if okReady and ready then
                        submits[#submits + 1] = { ctx = ctx, recipeId = recipeId }
                        break
                    end
                end
            end
        end
    end

    return claims, submits, crafting
end

local function refreshCraftingStatus(crafting, craftSlot)
    for _, item in ipairs(crafting or {}) do
        handleSlotGate(item.ctx, craftSlot)
    end
end

local function worker(token)
    while RUNNING and token == STOP_TOKEN do
        if G.AUTO_CRAFT_ENABLED ~= true and _G.AUTO_CRAFT_ENABLED ~= true then
            setStatus({ state = "disabled", step = "", message = "", recipe = "", machine = "" })
            M.stop()
            break
        end

        local selected = getSelectedRecipes()
        STATUS.queue = #selected

        if #selected == 0 then
            setStatus({ state = "idle", step = "No recipes selected", message = "", recipe = "", machine = "" })
            task.wait(CONFIG.IDLE_DELAY)
        else
            local anyWaiting = false
            local anyWorked = false
            local craftSlot = CONFIG.CRAFT_SLOT or 1
            local sharedStock = getSharedMaterialStock(true)

            local claims, submits, crafting = collectWorkstationPlan(selected, craftSlot, sharedStock)

            dlog("plan", "claims", #claims, "submits", #submits, "crafting", #crafting)

            -- Priority: claim > submit > reduce
            if #claims > 0 then
                applyPetTeam("claim")
                for _, item in ipairs(claims) do
                    if not RUNNING or token ~= STOP_TOKEN then break end
                    local ok, res = handleSlotGate(item.ctx, craftSlot)
                    if res == "claimed" then
                        anyWorked = true
                    elseif res == "still_crafting" or res == "machine_busy"
                        or res == "slot_not_empty_after_claim"
                    then
                        anyWaiting = true
                    end
                    if ok then
                        anyWorked = true
                    end
                end

                if #crafting > 0 then
                    applyPetTeam("reduce")
                    refreshCraftingStatus(crafting, craftSlot)
                    anyWaiting = true
                end
            elseif #submits > 0 then
                applyPetTeam("submit")
                local item = submits[1]
                local ctx = item.ctx
                local ok, result = M.craftOnce({
                    recipeName     = item.recipeId,
                    objectType     = ctx.machineDataKey,
                    gcoKey         = ctx.gcoKey,
                    machineDataKey = ctx.machineDataKey,
                    remoteType     = ctx.remoteType,
                    machine        = ctx.machine,
                    ctx            = ctx,
                })
                if ok then
                    anyWorked = true
                    applyPetTeam("reduce")
                    local _, _, craftingNow = collectWorkstationPlan(selected, craftSlot, sharedStock)
                    refreshCraftingStatus(craftingNow, craftSlot)
                    anyWaiting = true
                elseif result == "still_crafting" or result == "machine_busy"
                    or result == "claimed" or result == "slot_not_empty_after_claim"
                then
                    anyWaiting = true
                    if #crafting > 0 then
                        applyPetTeam("reduce")
                        refreshCraftingStatus(crafting, craftSlot)
                    end
                end
            elseif #crafting > 0 then
                applyPetTeam("reduce")
                refreshCraftingStatus(crafting, craftSlot)
                anyWaiting = true
            else
                CURRENT_TEAM_MODE = nil
                if not stockHasEntries(sharedStock) then
                    local clv = getCraftListView()
                    if clv and type(clv.invalidateCache) == "function" then
                        pcall(clv.invalidateCache)
                    end
                end
                setStatus({
                    state   = "idle",
                    machine = "",
                    recipe  = "",
                    step    = describeWaitReason(selected, craftSlot, sharedStock),
                    message = "",
                })
            end

            if anyWaiting then
                task.wait(CONFIG.WAIT_POLL)
            elseif anyWorked then
                task.wait(CONFIG.LOOP_DELAY)
            else
                task.wait(CONFIG.IDLE_DELAY)
            end
        end
    end
end

function M.getStatus()
    return STATUS
end

local function formatMachineLabel(machine)
    machine = tostring(machine or "")
    local gcoKey, mdKey = machine:match("^([^/]+)%s*/%s*(.+)$")
    if gcoKey and mdKey then
        gcoKey = gcoKey:gsub("^%s+", ""):gsub("%s+$", "")
        mdKey = mdKey:gsub("^%s+", ""):gsub("%s+$", "")
        if gcoKey == mdKey then return gcoKey end
        return gcoKey .. " (" .. mdKey:gsub("Workbench$", "") .. ")"
    end
    return machine
end

local function formatWorkbenchAction(ctx, phase, slotData, tLeft)
    local machine = formatMachineLabel(ctx.gcoKey)
    local recipe = recipeDisplayName(slotData and slotData.RecipeId or "")

    if phase == "claim" then
        return machine .. ": Claiming " .. recipe
    elseif phase == "crafting" then
        return string.format(
            "%s: Crafting %s (%ds left)",
            machine,
            recipe,
            math.max(0, math.floor(tLeft))
        )
    elseif phase == "busy" then
        return machine .. ": Slot busy · " .. recipe
    end
    return nil
end

local function parseGcoKeyFromMachine(machine)
    machine = tostring(machine or "")
    local gco = machine:match("^([^/]+)")
    if gco then
        return gco:gsub("^%s+", ""):gsub("%s+$", "")
    end
    gco = machine:match("^([^(]+)")
    if gco then
        return gco:gsub("^%s+", ""):gsub("%s+$", "")
    end
    return machine
end

local function collectActiveActionLines(selected)
    local lines = {}
    if #selected == 0 then return lines end

    local byMachine = groupRecipesByMachine(selected)
    local craftSlot = CONFIG.CRAFT_SLOT or 1
    local seenGco = {}

    for _, ctx in ipairs(listTargetWorkstations(byMachine)) do
        local recipeList = byMachine[ctx.machineDataKey]
        if recipeList and #recipeList > 0 then
            local phase, slotData, tLeft = getGcoSlotState(ctx, craftSlot)
            if phase == "claim" or phase == "crafting" or phase == "busy" then
                local line = formatWorkbenchAction(ctx, phase, slotData, tLeft)
                if line then
                    seenGco[ctx.gcoKey] = true
                    lines[#lines + 1] = line
                end
            end
        end
    end

    -- Only show live loop step when GCO has not reported this bench yet (e.g. input phase).
    local s = STATUS
    local stateKey = tostring(s.state or ""):lower()
    if (stateKey == "prepare" or stateKey == "crafting") and s.step and tostring(s.step) ~= "" then
        local gcoKey = parseGcoKeyFromMachine(s.machine or "")
        if gcoKey ~= "" and not seenGco[gcoKey] then
            local machine = formatMachineLabel(s.machine or "") or gcoKey
            lines[#lines + 1] = machine .. ": " .. tostring(s.step)
        end
    end

    return lines
end

local function friendlyErrorMessage(msg)
    msg = tostring(msg or "")
    local map = {
        no_machine_instance  = "Machine not found on map",
        recipe_not_found     = "Recipe not found",
        machine_not_found    = "Workbench not recognized",
        no_slot_requirements = "Invalid recipe slots",
    }
    if map[msg] then return map[msg] end
    if msg:find("^missing_") then
        return "Missing: " .. msg:gsub("^missing_", ""):gsub("_", " ")
    end
    return msg
end

function M.getStatusPanel()
    local s = STATUS
    local enabled = G.AUTO_CRAFT_ENABLED == true or _G.AUTO_CRAFT_ENABLED == true
    local selected = getSelectedRecipes()
    local stateKey = tostring(s.state or "idle"):lower()
    local details = {}

    if not enabled then
        return { title = "", details = { "Auto crafting off" } }
    end

    if #selected == 0 then
        return { title = "", details = { "No recipes selected" } }
    end

    details = collectActiveActionLines(selected)

    if #details == 0 then
        if stateKey == "error" then
            details[1] = friendlyErrorMessage(s.message) or "Error"
        elseif s.step and tostring(s.step) ~= "" then
            details[1] = tostring(s.step)
        else
            details[1] = "Idle"
        end
    end

    while #details > 6 do
        table.remove(details)
    end

    return { title = "", details = details }
end

function M.getStatusText()
    local panel = M.getStatusPanel()
    local lines = panel.details or {}
    return "", table.concat(lines, "\n")
end

function M.debugDump()
    print("\n========== AutoCraft DEBUG ==========")
    print("recipes:", table.concat(getSelectedRecipes(), ", "))
    print("team mode:", tostring(CURRENT_TEAM_MODE))
    print("team before claim:", #listTeamUUIDs(getTeamSet("claim")))
    print("team reduce:", #listTeamUUIDs(getTeamSet("reduce")))
    print("team submit:", #listTeamUUIDs(getTeamSet("submit")))
    for _, ctx in ipairs(listGcoWorkstations()) do
        local machine = findMachineForGco(ctx.gcoKey, ctx.machineDataKey)
        local slotData = getCraftingSlot(ctx.craftData, ctx.machineDataKey, CONFIG.CRAFT_SLOT)
        local phase = evaluateSlot(slotData)
        print(string.format(
            "GCO=%s mdKey=%s remote=%s phase=%s machine=%s",
            ctx.gcoKey,
            ctx.machineDataKey,
            ctx.remoteType,
            phase,
            machine and machine:GetFullName() or "nil"
        ))
        if slotData then
            print("  RecipeId=", slotData.RecipeId,
                "TimeRemaining=", slotData.TimeRemaining,
                "IsDone=", slotData.IsDone)
        end
    end
    print("=====================================\n")
end

function M.isRunning()
    return RUNNING
end

function M.stop()
    RUNNING = false
    STOP_TOKEN = STOP_TOKEN + 1
    THREAD = nil
    CURRENT_TEAM_MODE = nil
    restoreSwapSkillAfterCraft()
    setStatus({ state = "disabled", step = "Stopped", message = "" })
end

function M.start()
    if RUNNING then return end
    if G.AUTO_CRAFT_ENABLED ~= true and _G.AUTO_CRAFT_ENABLED ~= true then return end

    local clv = getCraftListView()
    if clv and type(clv.invalidateCache) == "function" then
        pcall(clv.invalidateCache)
    end

    RUNNING = true
    local token = STOP_TOKEN
    setStatus({ state = "idle", step = "Loop started", message = "", recipe = "", machine = "" })
    if CONFIG.DEBUG then
        task.defer(function() pcall(M.debugDump) end)
    end
    THREAD = task.spawn(function()
        local ok, err = pcall(worker, token)
        if not ok then
            local detail = tostring(err)
            if debug and type(debug.traceback) == "function" then
                detail = debug.traceback(detail, 2)
            end
            warnlog("Worker error:", detail)
            RUNNING = false
            setStatus({ state = "error", step = "Worker crashed", message = tostring(err) })
        end
    end)
end

function M.SetEnabled(on)
    local enabled = (on == true)
    G.AUTO_CRAFT_ENABLED = enabled
    _G.AUTO_CRAFT_ENABLED = enabled
    if enabled then M.start() else M.stop() end
    return enabled
end

function M.SyncFromGlobals()
    return M.SetEnabled(G.AUTO_CRAFT_ENABLED == true or _G.AUTO_CRAFT_ENABLED == true)
end

G.AutoCraftLoop = M
_G.AutoCraftLoop = M
_G.PrintAutoCraftDebug = function() M.debugDump() end

return M

        end,
        required = false,
    },
    {
        key = "swap_skill_module",
        name = "swap_skill_module",
        factory = function()
            -- swap_skill_module.lua
-- PnP Pet — Mode A (default) + Mode B + Mode C + Mode D
--
-- Mode A: PetCooldownsUpdated.OnClientEvent
-- Mode B: GetPetCooldown:InvokeServer (poll)
-- Mode C: EVENT CACHE + Heartbeat (alur/delay persis event-cache version)
--
-- Mode A/B:
--   parallel per pet
--   target = equipped ∩ selected
--   ready → wait unequipAfterReady → unequip → wait equipNext(min 0.1) → equip
--   ready saat busy → pending
--
-- Mode C:
--   ✅ Tidak spam GetPetCooldown:InvokeServer
--   ✅ Pakai PetCooldownsUpdated.OnClientEvent cache
--   ✅ Cooldown cache dihitung mundur sendiri sampai 0
--   ✅ Prioritas Skill asli / primary
--   ✅ Fallback Passive hanya kalau tidak ada Skill valid
--   ✅ ready edge → du → unequip → de → equip (default du=0.6, de=0)
--   ✅ scanInterval boleh 0
--
-- STATE.swap_skill:
--   enabled / selected / order / delays / scanInterval / mode ("A"|"B"|"C")
--
-- API: Start/Stop/IsRunning/SyncFromState/SetScanInterval/SetMode/SetDebug/SetAutoRejoinSwapBug

local M = {}

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TeleportService = game:GetService("TeleportService")
local RunService = game:GetService("RunService")

local LP = Players.LocalPlayer
local GameEvents = ReplicatedStorage:WaitForChild("GameEvents", 20)
local PetsServiceRE = GameEvents and GameEvents:WaitForChild("PetsService", 15)
local PetCooldownsUpdated = GameEvents and GameEvents:WaitForChild("PetCooldownsUpdated", 15)
local GetCDRF = GameEvents and (GameEvents:FindFirstChild("GetPetCooldown")
    or GameEvents:WaitForChild("GetPetCooldown", 5))
local ReplicationClass
pcall(function()
    ReplicationClass = require(ReplicatedStorage.Modules.ReplicationClass)
end)

if type(table.clear) ~= "function" then
    function table.clear(t)
        for k in pairs(t) do t[k] = nil end
    end
end

----------------------------------------------------------
-- STATE
----------------------------------------------------------
local DEFAULT_DELAYS = {
    unequipAfterReady = 0.6,
    equipNext = 0.1,
}

-- Mode C delays (persis event-cache version)
local DEFAULT_DELAYS_C = {
    unequipAfterReady = 0.6,
    equipNext = 0,
}

local function GetSTATE()
    local GG = (getgenv and getgenv()) or _G
    local s = rawget(GG, "STATE")
    if type(s) == "table" then return s end
    local s2 = rawget(_G, "STATE")
    if type(s2) == "table" then
        GG.STATE = s2
        return s2
    end
    local created = {}
    GG.STATE = created
    return created
end

-- One table only. UI writes G.swap_skill; module used to read STATE.swap_skill.
-- Split tables made Enable OFF in UI while Auto KG / listeners still swapped.
local function ensureSwapSkillState()
    local GG = (getgenv and getgenv()) or _G
    local STATE = GetSTATE()
    local fromState = (type(STATE.swap_skill) == "table") and STATE.swap_skill or nil
    local fromG = rawget(GG, "swap_skill")
    if type(fromG) ~= "table" then
        fromG = rawget(_G, "swap_skill")
    end
    -- UI table wins so Enable OFF in PnP Config is what the module/KG loop see.
    local ss = fromG or fromState or {}
    ss.enabled = (ss.enabled == true)
    STATE.swap_skill = ss
    GG.swap_skill = ss
    _G.swap_skill = ss
    ss.selected = ss.selected or {}
    ss.order = ss.order or {}
    ss.delays = ss.delays or {}
    ss.skillCache = ss.skillCache or {}

    if ss.scanInterval == nil then
        ss.scanInterval = 0.15
    end
    local si = tonumber(ss.scanInterval)
    if si == nil then si = 0.15 end
    if si < 0 then si = 0 end
    ss.scanInterval = si

    ss.poll = tonumber(ss.poll) or 0.05
    if ss.poll < 0.02 then
        ss.poll = 0.02
    end

    -- Mode A = OnClient, Mode B = InvokeServer, Mode C = Event Cache, D = CAS (PNP debug)
    local m = tostring(ss.mode or "A"):upper()
    if m ~= "A" and m ~= "B" and m ~= "C" and m ~= "D" then m = "A" end
    ss.mode = m
    return ss
end

local function getMode()
    return ensureSwapSkillState().mode
end

local function _normUUID(u)
    if u == nil then return nil end
    local s = tostring(u)
    local core = s:match("{?([0-9a-fA-F%-]+)}?") or s
    if core == "" then return nil end
    return "{" .. core .. "}"
end

local function _shortUUID(u)
    u = _normUUID(u)
    if not u then return "-" end
    return string.sub(u, 1, 9)
end

local function toNum(v)
    return tonumber(v)
end

local function ensureDelay(uuid)
    local ss = ensureSwapSkillState()
    uuid = _normUUID(uuid)
    if not uuid then return nil end

    local d = ss.delays[uuid]
    if type(d) ~= "table" then
        local bare = tostring(uuid):gsub("[{}]", "")
        d = ss.delays["{" .. bare .. "}"] or ss.delays[bare]
    end
    if type(d) ~= "table" then
        local def = (getMode() == "C") and DEFAULT_DELAYS_C or DEFAULT_DELAYS
        d = {
            unequipAfterReady = def.unequipAfterReady,
            equipNext = def.equipNext,
        }
        ss.delays[uuid] = d
    end
    return d
end

local function getSwapDelays(uuid)
    local d = ensureDelay(uuid)
    local du = tonumber(d and d.unequipAfterReady)
    if du == nil or du < 0 then
        du = DEFAULT_DELAYS.unequipAfterReady
    end
    local de = tonumber(d and d.equipNext)
    if de == nil or de < 0.1 then
        de = DEFAULT_DELAYS.equipNext
    end
    if de > 1 then
        de = DEFAULT_DELAYS.equipNext
    end
    return du, de
end

-- Mode C delay: boleh 0 (persis code event-cache)
local function ensureDelayC(uuid)
    local ss = ensureSwapSkillState()
    uuid = _normUUID(uuid)
    if not uuid then return nil end

    local d = ss.delays[uuid]
    if type(d) ~= "table" then
        d = {
            unequipAfterReady = DEFAULT_DELAYS_C.unequipAfterReady,
            equipNext = DEFAULT_DELAYS_C.equipNext,
        }
        ss.delays[uuid] = d
    end

    d.unequipAfterReady = tonumber(d.unequipAfterReady)
    if d.unequipAfterReady == nil or d.unequipAfterReady < 0 then
        d.unequipAfterReady = DEFAULT_DELAYS_C.unequipAfterReady
    end

    d.equipNext = tonumber(d.equipNext)
    if d.equipNext == nil or d.equipNext < 0 then
        d.equipNext = DEFAULT_DELAYS_C.equipNext
    end

    return d
end

local function buildSelectedOrdered()
    local ss = ensureSwapSkillState()
    local selected = ss.selected or {}
    local order = ss.order or {}
    local out, used = {}, {}

    for _, u in ipairs(order) do
        u = _normUUID(u)
        if u and selected[u] == true and not used[u] then
            used[u] = true
            out[#out + 1] = u
        end
    end
    for u, on in pairs(selected) do
        if on == true then
            local n = _normUUID(u)
            if n and tostring(u) == n and not used[n] then
                used[n] = true
                out[#out + 1] = n
            end
        end
    end
    return out
end

local function isSelected(uuid)
    uuid = _normUUID(uuid)
    if not uuid then return false end
    local ss = ensureSwapSkillState()
    if ss.enabled ~= true then
        return false
    end
    return ss.selected[uuid] == true
end

