-- Equipped
----------------------------------------------------------
local activeRep = nil
local equippedCache = {}
local equippedAt = 0

local function refreshEquipped(force)
    local now = os.clock()
    if (not force) and (now - equippedAt) < 0.2 then
        return equippedCache
    end
    local out = {}
    pcall(function()
        if not activeRep then
            activeRep = ReplicationClass.new("ActivePetsService_Replicator")
            activeRep.DontStager = true
        end
        local data = activeRep:YieldUntilData().Table
        local states = (data and data.ActivePetStates) or {}
        local mine = states[LP.Name]
            or states[tostring(LP.Name)]
            or states[LP.UserId]
            or states[tostring(LP.UserId)]
            or {}
        for u in pairs(mine) do
            local n = _normUUID(u)
            if n then out[n] = true end
        end
    end)
    equippedCache = out
    equippedAt = now
    return equippedCache
end

local function isEquipped(uuid)
    uuid = _normUUID(uuid)
    if not uuid then return false end
    return refreshEquipped(false)[uuid] == true
end

-- target scan: equipped ∩ selected (Mode A/B)
local function getScanTargets()
    local eq = refreshEquipped(true)
    local out = {}
    for u in pairs(eq) do
        if isSelected(u) then
            out[#out + 1] = u
        end
    end
    table.sort(out)
    return out
end

