local function log(...)
    if DEBUG then
        print("[PnPPet]", ...)
    end
end

local function dlog(key, interval, ...)
    if not DEBUG then return end
    key = tostring(key or "default")
    interval = tonumber(interval) or 1
    local now = os.clock()
    local last = lastDebugAt[key] or 0
    if now - last >= interval then
        lastDebugAt[key] = now
        print("[PnPPet]", ...)
    end
end

----------------------------------------------------------
-- CD parse (Mode A/B)
----------------------------------------------------------
local function _isFiniteNumber(n)
    return type(n) == "number" and n == n and n > -math.huge and n < math.huge
end

local function _parseCooldownSeconds(v)
    if type(v) == "number" then
        if not _isFiniteNumber(v) then return 0 end
        if v < 0 then return 0 end
        return v
    end
    if type(v) ~= "string" then return nil end
    local s = v:lower():gsub(",", "."):gsub("%s+", " "):gsub("^%s*(.-)%s*$", "%1")
    if s == "inf" or s == "infinity" or s == "+inf" or s == "-inf" or s == "nan" then
        return 0
    end
    if s == "" or s == "-" or s == "--" or s == "ready" or s:find("ready", 1, true) then
        return 0
    end
    local m, sec = s:match("^(%d+)%s*:%s*(%d+)$")
    if m and sec then
        return (tonumber(m) or 0) * 60 + (tonumber(sec) or 0)
    end
    local n = tonumber(s:match("[-+]?%d+%.?%d*"))
    if n == nil then return nil end
    if not _isFiniteNumber(n) or n < 0 then return 0 end
    return n
end

local function pickEntry(cds)
    if type(cds) ~= "table" then return nil end
    local function scan(key)
        for _, cd in ipairs(cds) do
            if type(cd) == "table" and cd[key] then
                local t = _parseCooldownSeconds(cd.Time)
                if t ~= nil then return t, key, tostring(cd[key]) end
            end
        end
        for _, cd in pairs(cds) do
            if type(cd) == "table" and cd[key] then
                local t = _parseCooldownSeconds(cd.Time)
                if t ~= nil then return t, key, tostring(cd[key]) end
            end
        end
        return nil
    end
    local t, k, n = scan("Skill")
    if t ~= nil then return t, k, n end
    return scan("Passive")
end

