-- Mode C — Event Cache runtime
----------------------------------------------------------
local UB_TOKENS = {} -- kosong = AUTO
local READY_TOL = 0.05

local EXCLUDE_TOKENS = {
    "mutation",
    "mutasi",
    "tethered",
    "shiny",
    "sparkling",
    "boost",
    "movement variation",
    "block wandering",
}

local CD_CACHE = {}
local modeC_hbConn = nil
local modeC_lastReady = {}
local modeC_busy = {}
local modeC_lastTrig = {}
local modeC_acc = 0

local function resetModeCTrackers()
    table.clear(modeC_lastReady)
    table.clear(modeC_busy)
    table.clear(modeC_lastTrig)
    table.clear(lastDebugAt)
    modeC_acc = 0
end

local function stopModeC()
    if modeC_hbConn then
        pcall(function() modeC_hbConn:Disconnect() end)
        modeC_hbConn = nil
    end
    table.clear(CD_CACHE)
