end

local function _normSkillLabel(s)
    s = string.lower(tostring(s or ""))
    s = s:gsub("%b[]", "")
         :gsub("[^%w%s]", " ")
         :gsub("%s+", " ")
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

local function _labelHasAny(labelNorm, tokens)
    labelNorm = tostring(labelNorm or "")
    for _, tok in ipairs(tokens or {}) do
        tok = tostring(tok or "")
        if tok ~= "" and string.find(labelNorm, tok, 1, true) then
            return true
        end
    end
    return false
end

local function _parseCooldownSecondsC(v)
    if type(v) == "number" then
        return v
    end

    if type(v) ~= "string" then
        return 0
    end

    local s = v:lower()
        :gsub(",", ".")
        :gsub("%s+", " ")
        :gsub("^%s*(.-)%s*$", "%1")

    local m, sec = s:match("^(%d+)%s*:%s*(%d+)$")
    if m and sec then
        return (tonumber(m) or 0) * 60 + (tonumber(sec) or 0)
    end

    local mm = s:match("(%d+)%s*m")
    local ss = s:match("(%d+)%s*s")
    if mm or ss then
        return (tonumber(mm) or 0) * 60 + (tonumber(ss) or 0)
    end

    return tonumber(s:match("[-+]?%d+%.?%d*")) or 0
end

local function _copyCooldownList(cds)
    local out = {}
    for _, cd in ipairs(cds or {}) do
        if type(cd) == "table" then
            local item = {}
            for k, v in pairs(cd) do
                item[k] = v
            end
            out[#out + 1] = item
        end
    end
    return out
end

local function _cacheCooldown(uuid, cds)
    uuid = _normUUID(uuid)
    if not uuid then return end

    if type(cds) ~= "table" then
        CD_CACHE[uuid] = nil
        log("CD EVENT invalid", _shortUUID(uuid), typeof(cds))
        return
    end

    CD_CACHE[uuid] = {
        receivedAt = os.clock(),
        list = _copyCooldownList(cds),
    }

    if DEBUG then
        local names = {}
        for _, cd in ipairs(cds) do
            if type(cd) == "table" then
                names[#names + 1] = tostring(cd.Skill or cd.Passive or "?") .. "=" .. tostring(cd.Time)
            end
        end
        dlog("cd_event_" .. uuid, 1, "CD EVENT", _shortUUID(uuid), table.concat(names, " | "))
    end
end

local function _getCachedCooldowns(uuid)
    uuid = _normUUID(uuid)
    local pack = CD_CACHE[uuid]

    if type(pack) ~= "table" or type(pack.list) ~= "table" then
        return nil
    end

    local elapsed = os.clock() - (pack.receivedAt or os.clock())
    return pack.list, elapsed
end

local function _entryLabel(cd, preferKind)
    if type(cd) ~= "table" then return nil, nil end

    if preferKind == "Skill" then
        if cd.Skill then return "Skill", cd.Skill end
        return nil, nil
    elseif preferKind == "Passive" then
        if cd.Passive then return "Passive", cd.Passive end
        return nil, nil
    end

    if cd.Skill then return "Skill", cd.Skill end
    if cd.Passive then return "Passive", cd.Passive end
    return nil, nil
end

local function _validLabel(rawLabel)
    local ln = _normSkillLabel(rawLabel)
    if ln == "" then return nil end

    if _labelHasAny(ln, EXCLUDE_TOKENS) then
        return nil
    end

    local autoMode = (type(UB_TOKENS) ~= "table") or (#UB_TOKENS == 0)
    if (not autoMode) and (not _labelHasAny(ln, UB_TOKENS)) then
        return nil
    end

    return ln
end

local function _findByCache(cds, cache)
    if type(cds) ~= "table" or type(cache) ~= "table" then return nil end

    local wantNorm = cache.labelNorm
    local wantKind = cache.kind

    if type(wantNorm) ~= "string" or wantNorm == "" then
        return nil
    end

    for _, cd in ipairs(cds) do
        local kind, raw = _entryLabel(cd, wantKind)
        local ln = _validLabel(raw)
        if ln and ln == wantNorm then
            return cd, kind, ln
        end
    end

    for _, cd in ipairs(cds) do
        local kind, raw = _entryLabel(cd)
        local ln = _validLabel(raw)
        if ln and ln == wantNorm then
            return cd, kind, ln
        end
    end

    return nil
end

local function _detectEntry(cds)
    if type(cds) ~= "table" then return nil end

    -- PRIMARY: Skill asli dulu
    for _, cd in ipairs(cds) do
        if type(cd) == "table" and cd.Skill then
            local ln = _validLabel(cd.Skill)
            if ln then
                return cd, "Skill", ln
            end
        end
    end

    -- Fallback Passive
    for _, cd in ipairs(cds) do
        if type(cd) == "table" and cd.Passive then
            local ln = _validLabel(cd.Passive)
            if ln then
                return cd, "Passive", ln
            end
        end
    end

    return nil
end

local function getCooldownC(uuid)
    uuid = _normUUID(uuid)
    if not uuid then return nil end

    local ss = ensureSwapSkillState()
    local cds, elapsed = _getCachedCooldowns(uuid)

    if type(cds) ~= "table" then
        dlog("no_cache_" .. uuid, 2, "NO CACHE", _shortUUID(uuid), "waiting PetCooldownsUpdated")
        return nil
    end

    local cached = ss.skillCache[uuid]
    local cdObj, kind, labelNorm

    if type(cached) == "table" then
        cdObj, kind, labelNorm = _findByCache(cds, cached)
    end

    if not cdObj then
        cdObj, kind, labelNorm = _detectEntry(cds)

        if cdObj then
            ss.skillCache[uuid] = {
                kind = kind,
                labelNorm = labelNorm,
            }
            log("DETECT SKILL", _shortUUID(uuid), tostring(kind), tostring(labelNorm))
        else
            ss.skillCache[uuid] = nil
            dlog("no_skill_" .. uuid, 2, "NO VALID SKILL", _shortUUID(uuid))
            return nil
        end
    end

    local base = _parseCooldownSecondsC(cdObj.Time)
    local remain = math.max(0, base - (elapsed or 0))

    if TRACE_CD then
        dlog("trace_cd_" .. uuid, 0.5,
            "CD",
            _shortUUID(uuid),
            tostring(kind or (cached and cached.kind) or "?"),
            tostring(labelNorm or (cached and cached.labelNorm) or "?"),
            "base=", string.format("%.2f", base),
            "elapsed=", string.format("%.2f", elapsed or 0),
            "remain=", string.format("%.2f", remain)
        )
    end

    return remain
end

local function equipC(uuid)
    uuid = _normUUID(uuid)
    if not uuid then return false end

    local ok, err = pcall(function()
        PetsServiceRE:FireServer("EquipPet", uuid)
    end)

    if not ok then
        log("EQUIP FAIL", _shortUUID(uuid), tostring(err))
        return false
    end

    log("EQUIP OK", _shortUUID(uuid))
    return true
end

local function unequipC(uuid)
    uuid = _normUUID(uuid)
    if not uuid then return false end

    local ok, err = pcall(function()
        PetsServiceRE:FireServer("UnequipPet", uuid)
    end)

    if not ok then
        log("UNEQUIP FAIL", _shortUUID(uuid), tostring(err))
        return false
    end

    log("UNEQUIP OK", _shortUUID(uuid))
    return true
end

local function tickModeC(dt)
    if not running or getMode() ~= "C" then return end

    local ss = ensureSwapSkillState()

    local poll = tonumber(ss.poll) or 0.05
    if poll < 0.02 then poll = 0.02 end

    modeC_acc += dt
    if modeC_acc < poll then return end
    modeC_acc = 0

    local list = buildSelectedOrdered()
    if #list <= 0 then
        dlog("empty_list", 3, "NO SELECTED PET")
        return
    end

    local now = os.clock()

    -- scanInterval boleh 0 (hanya fallback kalau nil / negatif)
    local minInterval = toNum(ss.scanInterval)
    if minInterval == nil or minInterval < 0 then
        minInterval = 0.25
    end

    dlog("status", 3,
        "RUNNING mode=C",
        "selected=", #list,
        "cache=", tostring((function()
            local n = 0
            for _ in pairs(CD_CACHE) do n += 1 end
            return n
        end)()),
        "poll=", poll,
        "scanInterval=", minInterval
    )

    for _, uuid in ipairs(list) do
        if not modeC_busy[uuid] then
            local cd
            local ok, err = pcall(function()
                cd = getCooldownC(uuid)
            end)

            if not ok then
                cd = nil
                log("getCooldown ERROR", _shortUUID(uuid), tostring(err))
            end

            if cd ~= nil then
                local ready = (cd <= READY_TOL)
                local wasReady = (modeC_lastReady[uuid] == true)

                if ready ~= wasReady then
                    log("READY STATE", _shortUUID(uuid), "was=", wasReady, "now=", ready, "cd=", string.format("%.2f", cd))
                end

                if (not wasReady) and ready then
                    local lt = modeC_lastTrig[uuid] or 0

                    if (now - lt) >= minInterval then
                        modeC_lastTrig[uuid] = now
                        modeC_busy[uuid] = true

                        local d = ensureDelayC(uuid)
                        local du = tonumber(d and d.unequipAfterReady) or DEFAULT_DELAYS_C.unequipAfterReady
                        local de = tonumber(d and d.equipNext) or DEFAULT_DELAYS_C.equipNext

                        log("TRIGGER READY", _shortUUID(uuid), "du=", du, "de=", de)

                        task.delay(du, function()
                            if not running or getMode() ~= "C" or not isSelected(uuid) then
                                modeC_busy[uuid] = false
                                return
                            end

                            unequipC(uuid)
                            modeC_lastReady[uuid] = false

                            task.delay(de, function()
                                if not running or getMode() ~= "C" or not isSelected(uuid) then
                                    modeC_busy[uuid] = false
                                    return
                                end

                                equipC(uuid)
                                modeC_busy[uuid] = false
                            end)
                        end)
                    else
                        dlog("interval_" .. uuid, 1,
                            "SKIP INTERVAL",
                            _shortUUID(uuid),
                            "wait=", string.format("%.2f", minInterval - (now - lt))
                        )
                    end
                end

                modeC_lastReady[uuid] = ready
            else
                modeC_lastReady[uuid] = false
            end
        end
    end
end

local function startModeC()
    stopModeC()
    resetModeCTrackers()

    cdConn = PetCooldownsUpdated.OnClientEvent:Connect(function(uuid, cds)
        if getMode() ~= "C" then return end
        _cacheCooldown(uuid, cds)
    end)

    modeC_hbConn = RunService.Heartbeat:Connect(tickModeC)
    log("LISTEN mode=C EventCache scanInterval=", ensureSwapSkillState().scanInterval)
end

----------------------------------------------------------
-- Swap core Mode A/B (parallel, delays dari UI)
----------------------------------------------------------
-- Mode D — CAS skill (persis debug_pnp_try.lua)
----------------------------------------------------------
local MODE_D_AFTER_UNEQUIP = 0.03
local MODE_D_MIN_RETRIG = 0.45
local MODE_D_ANIM_DELAY = {
    Frill = 0.22,
    Fan = 0.1,
    Play = 0.06,
    Soar = 0.08,
}
local MODE_D_ANIM_RETRIG = {
    Frill = 2.2,
    Fan = 0.5,
    Play = 0.5,
    Soar = 0.7,
}
local MODE_D_IDLE = {
    Idle = true,
    Walk = true,
    idle = true,
    walk = true,
}

local modeD_hbConn = nil
local modeD_pathConn = nil
local modeD_busy = {}
local modeD_pending = {}
local modeD_inSkill = {}
local modeD_lastTrig = {}
local modeD_swapLock = false
local modeD_ncfPaused = false
local DataServiceMod
pcall(function()
    DataServiceMod = require(ReplicatedStorage.Modules.DataService)
end)
local PetVFXMod
pcall(function()
    PetVFXMod = require(ReplicatedStorage.Modules.PetServices.PetVFXHandler)
end)

local function resetModeDTrackers()
    table.clear(modeD_busy)
    table.clear(modeD_pending)
    table.clear(modeD_inSkill)
    table.clear(modeD_lastTrig)
    modeD_swapLock = false
end

local function stopModeD()
    if modeD_hbConn then
        pcall(function() modeD_hbConn:Disconnect() end)
        modeD_hbConn = nil
    end
    if modeD_pathConn then
        pcall(function() modeD_pathConn:Disconnect() end)
        modeD_pathConn = nil
    end
    resetModeDTrackers()
    if modeD_ncfPaused then
        modeD_ncfPaused = false
        pcall(function()
            local NCF = _G.NilCooldownFixer or ((getgenv and getgenv()) and getgenv().NilCooldownFixer)
            -- jangan auto Start lagi; loop NM yang nyalakan kalau perlu
        end)
    end
end

local function dIsSkillAnim(anim)
    if type(anim) ~= "string" then return false end
    if anim == "" then return false end
    if MODE_D_IDLE[anim] then return false end
    return true
end

local function dPetName(uuid)
    uuid = _normUUID(uuid)
    if not uuid or not DataServiceMod then return "?" end
    local name = "?"
    pcall(function()
        local data = DataServiceMod:GetData()
        local inv = data and data.PetsData and data.PetsData.PetInventory and data.PetsData.PetInventory.Data
        if type(inv) ~= "table" then return end
        local rec = inv[uuid] or inv[tostring(uuid):gsub("[{}]", "")]
        if type(rec) ~= "table" then
            local bare = tostring(uuid):gsub("[{}]", "")
            rec = inv["{" .. bare .. "}"]
        end
        if type(rec) == "table" then
            name = tostring(rec.PetType or rec.Name or "?")
        end
    end)
    return name
end

local function dRequiredAnim(uuid)
    local n = string.lower(dPetName(uuid))
    if n:find("dilophosaurus", 1, true) then return "Frill" end
    if n:find("peacock", 1, true) then return "Fan" end
    if n:find("phoenix", 1, true) then return "Soar" end
    if n:find("ferret", 1, true) or n:find("french fry", 1, true) then return "Play" end
    return nil
end

local function dLiveCas(uuid)
    uuid = _normUUID(uuid)
    if not uuid then return nil end
    pcall(function()
        if not activeRep then
            activeRep = ReplicationClass.new("ActivePetsService_Replicator")
            activeRep.DontStager = true
        end
    end)
    if not activeRep then return nil end
    local cas
    pcall(function()
        local data = activeRep:YieldUntilData().Table
        local states = (data and data.ActivePetStates) or {}
        local mine = states[LP.Name] or states[tostring(LP.Name)]
            or states[LP.UserId] or states[tostring(LP.UserId)] or {}
        for raw, st in pairs(mine) do
            if _normUUID(raw) == uuid and type(st) == "table" then
                local c = st.CustomAnimationState
                if type(c) == "string" and c ~= "" then
                    cas = c
                end
                break
            end
        end
    end)
    return cas
end

local doSwapD

local function dQueueSkill(uuid, anim, tag)
    uuid = _normUUID(uuid)
    if not uuid or not isSelected(uuid) then return end
    if not dIsSkillAnim(anim) then return end
    local need = dRequiredAnim(uuid)
    if need and anim ~= need then return end
    if modeD_pending[uuid] and modeD_pending[uuid].anim == anim then return end
    local retrig = MODE_D_ANIM_RETRIG[anim] or MODE_D_MIN_RETRIG
    if modeD_inSkill[uuid] == anim and (os.clock() - (modeD_lastTrig[uuid] or 0)) < retrig then
        return
    end
    modeD_inSkill[uuid] = anim
    local delay = MODE_D_ANIM_DELAY[anim] or 0.04
    modeD_pending[uuid] = {
        why = (tag or "ANIM") .. " " .. tostring(anim),
        at = os.clock(),
        anim = anim,
        notBefore = os.clock() + delay,
    }
end

local function dScanAndSwap()
    if not running or getMode() ~= "D" then return end
    pcall(function()
        if not activeRep then
            activeRep = ReplicationClass.new("ActivePetsService_Replicator")
            activeRep.DontStager = true
        end
    end)
    if not activeRep then return end
    local now = os.clock()
    local seen = {}
    pcall(function()
        local data = activeRep:YieldUntilData().Table
        local states = (data and data.ActivePetStates) or {}
        local mine = states[LP.Name] or states[tostring(LP.Name)]
            or states[LP.UserId] or states[tostring(LP.UserId)] or {}
        for raw, st in pairs(mine) do
            local uuid = _normUUID(raw)
            if uuid then seen[uuid] = st end
        end
    end)
    for uuid, st in pairs(seen) do
        if isSelected(uuid) then
            local anim = (type(st) == "table") and st.CustomAnimationState or nil
            local need = dRequiredAnim(uuid)
            if need and anim and anim ~= need then
                anim = nil
            end
            if dIsSkillAnim(anim) then
                dQueueSkill(uuid, anim, "ANIM")
            elseif not modeD_pending[uuid] then
                modeD_inSkill[uuid] = nil
            end
        end
    end
    for uuid, pack in pairs(modeD_pending) do
        if type(pack) ~= "table" then
            modeD_pending[uuid] = nil
        elseif (now - (pack.at or 0)) > 1.6 then
            modeD_pending[uuid] = nil
        else
            local cas = dLiveCas(uuid)
            if cas == pack.anim then
                pack.lostAt = nil
            else
                pack.lostAt = pack.lostAt or now
                if (now - pack.lostAt) > 0.12 then
                    modeD_pending[uuid] = nil
                end
            end
        end
    end
    local oldest, pick
    for uuid, pack in pairs(modeD_pending) do
        if type(pack) == "table" and not modeD_busy[uuid] and now >= (pack.notBefore or 0) then
            if dLiveCas(uuid) == pack.anim then
                if not oldest or pack.at < oldest then
                    oldest = pack.at
                    pick = uuid
                end
            end
        end
    end
    if pick then
        doSwapD(pick, modeD_pending[pick].why, modeD_pending[pick].anim)
    end
end

doSwapD = function(uuid, why, anim)
    uuid = _normUUID(uuid)
    if not uuid or not running or not isSelected(uuid) then return false end
    if modeD_busy[uuid] then return false end
    if modeD_swapLock then return false end
    local now = os.clock()
    local retrig = (anim and MODE_D_ANIM_RETRIG[anim]) or MODE_D_MIN_RETRIG
    if (now - (modeD_lastTrig[uuid] or 0)) < retrig then return false end
    local need = dRequiredAnim(uuid)
    local cas = dLiveCas(uuid)
    if need then
        if cas ~= need then return false end
        if anim and anim ~= need then return false end
    elseif not dIsSkillAnim(cas) then
        return false
    end
    modeD_busy[uuid] = true
    modeD_swapLock = true
    modeD_lastTrig[uuid] = now
    modeD_pending[uuid] = nil
    log("MODE_D", why or "SWAP", dPetName(uuid), anim or cas)
    lastRemoveAt = os.clock()
    task.spawn(function()
        pcall(function()
            if isSelected(uuid) then
                PetsServiceRE:FireServer("UnequipPet", uuid)
            end
        end)
        equippedAt = 0
        task.wait(MODE_D_AFTER_UNEQUIP)
        pcall(function()
            if running and getMode() == "D" and isSelected(uuid) then
                PetsServiceRE:FireServer("EquipPet", uuid)
            end
        end)
        equippedAt = 0
        modeD_busy[uuid] = false
        modeD_swapLock = false
        for _ = 1, 3 do
            if not running or getMode() ~= "D" or not isSelected(uuid) then break end
            task.wait(0.05)
            if refreshEquipped(true)[uuid] then break end
            pcall(function() PetsServiceRE:FireServer("EquipPet", uuid) end)
            equippedAt = 0
        end
    end)
    return true
end

M._onAnimModeD = function(rawUuid, anim)
    if not running or getMode() ~= "D" then return end
    local uuid = _normUUID(rawUuid)
    if not uuid then return end
    local need = dRequiredAnim(uuid)
    if need and tostring(anim) ~= need then return end
    dQueueSkill(rawUuid, anim, "VFX")
end

pcall(function()
    if PetVFXMod and not PetVFXMod.__nodeModeDOrig then
        PetVFXMod.__nodeModeDOrig = PetVFXMod.playVFX
        function PetVFXMod:playVFX(anim)
            local orig = PetVFXMod.__nodeModeDOrig
            local SS = rawget(_G, "SwapSkill") or rawget(_G, "PnPPet")
            if SS and type(SS._onAnimModeD) == "function" then
                pcall(SS._onAnimModeD, self.UUID, anim)
            end
            if orig then
                return orig(self, anim)
            end
        end
    end
end)

local function startModeD()
    stopModeD()
    resetModeDTrackers()
    pcall(function()
        local dbg = rawget(_G, "PnpDebug")
        if type(dbg) == "table" and type(dbg.Stop) == "function" then
            dbg.Stop()
        end
    end)
    modeD_hbConn = RunService.Heartbeat:Connect(function()
        pcall(dScanAndSwap)
    end)
    pcall(function()
        if not activeRep then
            activeRep = ReplicationClass.new("ActivePetsService_Replicator")
            activeRep.DontStager = true
        end
        if activeRep and activeRep.GetPathSignal then
            local sig = activeRep:GetPathSignal("ActivePetStates/@")
            if sig then
                modeD_pathConn = sig:Connect(function()
                    pcall(dScanAndSwap)
                end)
            end
        end
    end)
    log("LISTEN mode=D CAS-gate (PNP debug)")
end

----------------------------------------------------------
local doSwap

local function finishSwap(uuid)
    busy[uuid] = false
    equippedAt = 0
    local p = pending[uuid]
    if not p then return end
    pending[uuid] = nil
    log("PENDING_RUN", _shortUUID(uuid))
    doSwap(uuid, p.cd, p.kind, p.name)
end

doSwap = function(uuid, cd, kind, name)
    uuid = _normUUID(uuid)
    if not uuid or not running or not isSelected(uuid) then return end

    if busy[uuid] then
        pending[uuid] = { cd = cd, kind = kind, name = name }
        log("PENDING", _shortUUID(uuid), "ready saat busy")
        return
    end

    busy[uuid] = true
    pending[uuid] = nil

    local du, de = getSwapDelays(uuid)
    log("SWAP", _shortUUID(uuid), string.format(
        "%s:%s cd=%.2f mode=%s | afterReady=%.2f beforeEquip=%.2f",
        tostring(kind), tostring(name), cd, getMode(), du, de
    ))

    task.spawn(function()
        if du > 0 then task.wait(du) end
        if not running or not isSelected(uuid) then
            busy[uuid] = false
            return
        end

        local okU, errU = pcall(function()
            PetsServiceRE:FireServer("UnequipPet", uuid)
        end)
        equippedAt = 0
        if not okU then
            log("UNEQUIP FAIL", _shortUUID(uuid), tostring(errU))
            finishSwap(uuid)
            return
        end
        log("UNEQUIP OK", _shortUUID(uuid))

        task.wait(de)
        if not running or not isSelected(uuid) then
            busy[uuid] = false
            return
        end

        local okE, errE = pcall(function()
            PetsServiceRE:FireServer("EquipPet", uuid)
        end)
        equippedAt = 0
        if okE then
            log("EQUIP OK", _shortUUID(uuid))
        else
            log("EQUIP FAIL", _shortUUID(uuid), tostring(errE))
        end

        log("SWAP_DONE", _shortUUID(uuid))
        finishSwap(uuid)
    end)
end

local function handleReadyCd(uuid, cd, kind, name)
    uuid = _normUUID(uuid)
    if not uuid or not running then return end
    if not isSelected(uuid) then return end

    -- target: equipped ∩ selected; busy boleh pending
    if not busy[uuid] and not isEquipped(uuid) then
        return
    end

    if type(cd) ~= "number" then return end
    if cd > 0 then
        if pending[uuid] then
            pending[uuid] = nil
            log("PENDING_CLR", _shortUUID(uuid), "cd=", string.format("%.2f", cd))
        end
        return
    end

    doSwap(uuid, cd, kind, name)
end

----------------------------------------------------------
-- Mode A — OnClientEvent
----------------------------------------------------------
local function onEvent(uuid, cds)
    if getMode() ~= "A" then return end
    uuid = _normUUID(uuid)
    if not uuid or not running or type(cds) ~= "table" then return end
    if not isSelected(uuid) then return end

    local cd, kind, name = pickEntry(cds)
    if cd == nil then return end
    handleReadyCd(uuid, cd, kind, name)
end

----------------------------------------------------------
-- Mode B — InvokeServer poll (parallel swap)
----------------------------------------------------------
local function invokeCD(uuid)
    if not GetCDRF then return nil end
    local ok, cds = pcall(function()
        return GetCDRF:InvokeServer(uuid)
    end)
    if not ok or type(cds) ~= "table" then return nil end
    return cds
end

local function pollOnceModeB()
    if not running or getMode() ~= "B" then return end
    local targets = getScanTargets()
    if #targets == 0 then return end

    for _, uuid in ipairs(targets) do
        if not running or getMode() ~= "B" then return end
        task.spawn(function()
            local cds = invokeCD(uuid)
            if not cds then return end
            local cd, kind, name = pickEntry(cds)
            if cd == nil then return end
            handleReadyCd(uuid, cd, kind, name)
        end)
    end
end

local function startModeBLoop()
    pollToken += 1
    local my = pollToken
    task.spawn(function()
        while running and pollToken == my and getMode() == "B" do
            local ss = ensureSwapSkillState()
            local poll = tonumber(ss.scanInterval) or 0.15
            -- Mode B tetap floor 0.05 biar tidak busy-loop
            if poll < 0.05 then poll = 0.05 end

            local ok, err = pcall(pollOnceModeB)
            if not ok then
                log("MODE_B ERR", tostring(err))
            end
            task.wait(poll)
        end
    end)
end

local function stopListeners()
    pollToken += 1
    if cdConn then
        pcall(function() cdConn:Disconnect() end)
        cdConn = nil
    end
    stopModeC()
    stopModeD()
end

local function startListeners()
    stopListeners()
    local mode = getMode()
    if mode == "B" then
        startModeBLoop()
        log("LISTEN mode=B InvokeServer poll=", ensureSwapSkillState().scanInterval)
    elseif mode == "C" then
        startModeC()
    elseif mode == "D" then
        startModeD()
    else
        cdConn = PetCooldownsUpdated.OnClientEvent:Connect(onEvent)
        log("LISTEN mode=A OnClientEvent")
    end
end

----------------------------------------------------------
-- ActivePetStates removed watcher (auto rejoin)
----------------------------------------------------------
local function stopBeforeRejoin()
    pcall(function()
        local H = rawget(_G, "auto_hatchLoop") or rawget(_G, "AutoHatchLoop")
        if H then
            if type(H.Stop) == "function" then H.Stop("swap_bug")
            elseif type(H.stop) == "function" then H.stop("swap_bug") end
        end
    end)
    pcall(function()
        local N = rawget(_G, "AutoKGLoop") or rawget(_G, "NMLVLLoop") or rawget(_G, "AutoNMLVLLoop")
        if N then
            if type(N.Stop) == "function" then N.Stop("swap_bug")
            elseif type(N.stop) == "function" then N.stop("swap_bug") end
        end
    end)
    pcall(function()
        local SS = rawget(_G, "SwapSkill") or (getgenv and getgenv().SwapSkill)
        if SS and type(SS.Stop) == "function" then SS.Stop() end
    end)
end

local function _rejoinNowBySwapTimeout()
    local done = false
    pcall(function()
        if _G.PSReconnect then
            if type(_G.PSReconnect.RejoinNow) == "function" then
                _G.PSReconnect:RejoinNow(); done = true
            elseif type(_G.PSReconnect.rejoinNow) == "function" then
                _G.PSReconnect:rejoinNow(); done = true
            end
        end
    end)
    if not done then
        pcall(function()
            TeleportService:Teleport(game.PlaceId, LP)
        end)
    end
end

local function _getMyActiveStates(rep)
    local data = rep:YieldUntilData().Table
    local states = data.ActivePetStates or {}
    return states[LP.Name]
        or states[tostring(LP.Name)]
        or states[LP.UserId]
        or states[tostring(LP.UserId)]
        or {}
end

local function _scanRemovedFromRep(rep, reason)
    if not running then return end
    local nowStates = _getMyActiveStates(rep)
    local nowMap = {}
    for uuid in pairs(nowStates) do
        uuid = _normUUID(uuid)
        if uuid then nowMap[uuid] = true end
    end
    for uuid in pairs(lastActivePets) do
        if not nowMap[uuid] then
            lastRemoveAt = os.clock()
            log("ACTIVE PET REMOVED", _shortUUID(uuid), reason)
        end
    end
    lastActivePets = nowMap
end

local function _startRemoveWatcher()
    if removeWatchStarted then return end
    removeWatchStarted = true

    task.spawn(function()
        local Rep = ReplicationClass.new("ActivePetsService_Replicator")
        Rep.DontStager = true
        Rep:YieldUntilData()

        lastRemoveAt = os.clock()
        lastActivePets = {}
        _scanRemovedFromRep(Rep, "initial")

        if repPetConn then
            repPetConn:Disconnect()
            repPetConn = nil
        end
        repPetConn = Rep:GetPathSignal("ActivePetStates/@"):Connect(function()
            _scanRemovedFromRep(Rep, "replicator_signal")
        end)

        while true do
            task.wait(5)
            if running then
                _scanRemovedFromRep(Rep, "backup_5s")
                local diff = os.clock() - (lastRemoveAt or os.clock())
                AUTO_REJOIN_SWAP_BUG_ENABLED = (_G.AUTO_REJOIN_SWAP_BUG_ENABLED == true)
                local selectedCount = #buildSelectedOrdered()
                local modeNow = getMode()
                local timeout = REMOVE_TIMEOUT
                if modeNow == "C" then
                    timeout = REMOVE_TIMEOUT_C
                elseif modeNow == "D" then
                    timeout = REMOVE_TIMEOUT_D
                end
                if AUTO_REJOIN_SWAP_BUG_ENABLED and selectedCount > 0 and diff >= timeout then
                    log("NO ACTIVE PET REMOVED >= timeout, REJOIN")
                    if modeNow == "C" or modeNow == "D" then
                        -- Mode C/D: jangan hard-stop loop, cuma rejoin
                        task.wait(2)
                        _rejoinNowBySwapTimeout()
                    else
                        stopBeforeRejoin()
                        task.wait(1.5)
                        _rejoinNowBySwapTimeout()
                    end
                    task.wait(999999)
                end
            else
                lastRemoveAt = os.clock()
                lastActivePets = {}
            end
        end
    end)
end

----------------------------------------------------------
-- Public API
----------------------------------------------------------
function M.SetDebug(on)
    DEBUG = (on == true)
    return DEBUG
end

function M.SetTraceCooldown(on)
    TRACE_CD = (on == true)
    return TRACE_CD
end

function M.SetAutoRejoinSwapBug(on)
    AUTO_REJOIN_SWAP_BUG_ENABLED = (on == true)
    _G.AUTO_REJOIN_SWAP_BUG_ENABLED = AUTO_REJOIN_SWAP_BUG_ENABLED
    return AUTO_REJOIN_SWAP_BUG_ENABLED
end

function M.SetMode(mode, maybeMode)
    -- support SS:SetMode("B") dan SS.SetMode("B")
    if type(mode) == "table" then
        mode = maybeMode
    end
    local ss = ensureSwapSkillState()
    local m = tostring(mode or "A"):upper()
    if m ~= "A" and m ~= "B" and m ~= "C" and m ~= "D" then m = "A" end
    local prev = ss.mode
    ss.mode = m
    log("SetMode", prev, "→", m)
    if running and prev ~= m then
        resetTrackers()
        startListeners()
    end
    return ss.mode
end

function M.GetMode()
    return getMode()
end

function M.SyncFromState()
    local ss = ensureSwapSkillState()
    if ss.enabled ~= true then
        if running then
            M.Stop()
        end
        log("SyncFromState disabled")
        return true
    end
    local list = buildSelectedOrdered()
    for _, uuid in ipairs(list) do
        if ss.mode == "C" then
            ensureDelayC(uuid)
            local c = ss.skillCache[uuid]
            if type(c) == "table" then
                local k = c.kind
                local ln = c.labelNorm
                if (k ~= "Skill" and k ~= "Passive") or type(ln) ~= "string" or ln == "" then
                    ss.skillCache[uuid] = nil
                end
            end
        elseif ss.mode ~= "D" then
            ensureDelay(uuid)
        end
    end
    log("SyncFromState selected=", #list, "mode=", ss.mode)
    if running then
        startListeners()
    end
    return true
end

function M.Start(force)
    local ss = ensureSwapSkillState()
    -- callMethod / colon pass self as first arg; Shark.syncPnP passes a reason string.
    -- Neither may bypass Enable OFF.
    if force ~= true then
        force = false
    end

    if ss.enabled ~= true then
        if running then
            M.Stop()
        end
        log("Start blocked: disabled by state")
        return false, "disabled by state"
    end

    if running then
        startListeners()
        return true
    end

    running = true
    resetTrackers()
    lastRemoveAt = os.clock()
    lastActivePets = {}
    _startRemoveWatcher()
    startListeners()

    _G.__SWAP_SKILL_RUNNING = true
    log("START OK selected=", #buildSelectedOrdered(), "mode=", getMode())
    return true
end

function M.Stop()
    if not running then
        return true, "already stopped"
    end

    running = false
    _G.__SWAP_SKILL_RUNNING = false
    stopListeners()
    resetTrackers()
    lastRemoveAt = os.clock()
    table.clear(lastActivePets)

    log("STOP OK")
    return true
end

function M.SetScanInterval(v)
    local ss = ensureSwapSkillState()
    local n = tonumber(v)
    if n == nil then
        return ss.scanInterval
    end
    -- boleh 0 (Mode C); Mode B tetap di-floor saat loop
    if n < 0 then n = 0 end
    ss.scanInterval = n
    return ss.scanInterval
end

function M.IsRunning()
    return running == true
end

function M.GetDebugSnapshot()
    local list = buildSelectedOrdered()
    local busyN, pendN = 0, 0
    for _, v in pairs(busy) do
        if v then busyN += 1 end
    end
    for _ in pairs(pending) do
        pendN += 1
    end

    local cacheCount = 0
    for _ in pairs(CD_CACHE) do
        cacheCount += 1
    end

    local mode = getMode()
    local modeName = "OnClientEvent"
    if mode == "B" then
        modeName = "InvokeServer"
    elseif mode == "C" then
        modeName = "EventCache"
    elseif mode == "D" then
        modeName = "CAS-PNPDebug"
    end

    return {
        running = running,
        selectedCount = #list,
        busyCount = busyN,
        pendingCount = pendN,
        cacheCount = cacheCount,
        debug = DEBUG,
        traceCooldown = TRACE_CD,
        mode = mode,
        modeName = modeName,
        scanInterval = ensureSwapSkillState().scanInterval,
        version = "pnp-pet-v3-moded",
    }
end

----------------------------------------------------------
-- Publish global
----------------------------------------------------------
do
    local GG = (getgenv and getgenv()) or _G
    GG.SwapSkill = M
    GG.PnPPet = M
    _G.SwapSkill = M
    _G.PnPPet = M
end

return M

        end,
        required = false,
    },
    {
        key = "collect_rules",
        name = "collect_rules",
        factory = function()
            -- collect_rules.lua — modular Auto Collect rules (type / variant / mutation / kg)
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local G = (getgenv and getgenv()) or _G
local M = {}
M.__MODULE_VERSION = 7

local NO_MUT = "__NO_MUTATION__"

local function canon(s)
    s = tostring(s or "")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")
    s = s:gsub("^[Ff]ruit[_%s%-]+", "")
    s = s:gsub("^[Ss]eed[_%s%-]+", "")
    s = s:gsub("^[Pp]lant[_%s%-]+", "")
    s = s:gsub("[_%s%-]+[Ss]eed$", "")
    s = s:gsub("%s+[Ss]eed$", "")
    s = s:lower()
    s = s:gsub("[^%w]+", "")
    return s
end

local function isNoMut(k)
    local s = tostring(k or "")
    if s == NO_MUT or s == "[TANPA MUTASI]" or s == "[NO MUTATION]" or s == "[No Mutation]" or s == "No Mutation" then
        return true
    end
    local c = canon(s)
    return c == "nomutation" or c == "tanpamutasi"
end

local function toSet(src)
    local out = {}
    if type(src) ~= "table" then
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 then
            local key = tostring(k)
            if key ~= "" then
                out[key] = true
            end
        elseif type(v) == "string" and v ~= "" then
            out[v] = true
        end
    end
    for _, v in ipairs(src) do
        if v ~= nil and tostring(v) ~= "" then
            out[tostring(v)] = true
        end
    end
    return out
end

local function setToArr(map)
    local arr = {}
    for k, v in pairs(map or {}) do
        if v == true then
            arr[#arr + 1] = tostring(k)
        end
    end
    table.sort(arr)
    return arr
end

local function hasAny(map)
    if type(map) ~= "table" then
        return false
    end
    for _, v in pairs(map) do
        if v == true then
            return true
        end
    end
    return false
end

local function matchNameSet(selected, value)
    if not hasAny(selected) then
        return true
    end
    local needle = canon(value)
    for k, on in pairs(selected) do
        if on == true and canon(k) == needle then
            return true
        end
    end
    return false
end

function M.AsArray(rules)
    if type(rules) ~= "table" then
        return {}
    end
    local out = {}
    if rules[1] ~= nil then
        for i = 1, #rules do
            if type(rules[i]) == "table" then
                out[#out + 1] = rules[i]
            end
        end
        if #out > 0 then
            return out
        end
    end
    local keyed, maxn = {}, 0
    for k, v in pairs(rules) do
        if type(v) == "table" then
            local i = tonumber(k)
            if i and i >= 1 then
                keyed[i] = v
                if i > maxn then
                    maxn = i
                end
            else
                out[#out + 1] = v
            end
        end
    end
    if maxn > 0 then
        local arr = {}
        for i = 1, maxn do
            if type(keyed[i]) == "table" then
                arr[#arr + 1] = keyed[i]
            end
        end
        if #arr > 0 then
            return arr
        end
    end
    return out
end

function M.Has(rules)
    return #M.AsArray(rules) > 0
end

function M.NormAction(s)
    s = tostring(s or "keep"):lower()
    if s == "take" or s == "collect" or s == "only" then
        return "take"
    end
    return "keep"
end

local function ruleAction(rule, fallback)
    if type(rule) == "table" and rule.action ~= nil and tostring(rule.action) ~= "" then
        return M.NormAction(rule.action)
    end
    return M.NormAction(fallback)
end

function M.HasKeepTake(rules, fallback)
    local hasKeep, hasTake = false, false
    rules = M.AsArray(rules)
    if type(rules) ~= "table" then
        return false, false
    end
    for i = 1, #rules do
        local act = ruleAction(rules[i], fallback)
        if act == "take" then
            hasTake = true
        else
            hasKeep = true
        end
    end
    return hasKeep, hasTake
end

function M.Allow(action, rules, name, variant, weight, fruitMuts)
    rules = M.AsArray(rules)
    if not M.Has(rules) then
        return nil
    end
    local fallback = M.NormAction(action)
    local keepHit, takeHit = false, false
    for i = 1, #rules do
        if M.MatchRule(rules[i], name, variant, weight, fruitMuts) then
            if ruleAction(rules[i], fallback) == "take" then
                takeHit = true
            else
                keepHit = true
            end
        end
    end
    if keepHit then
        return false
    end
    if takeHit then
        return true
    end
    local hasKeep, hasTake = M.HasKeepTake(rules, fallback)
    if hasTake and not hasKeep then
        return false
    end
    return true
end

function M.Pack(rules, defaultAction)
    local out = {}
    rules = M.AsArray(rules)
    if type(rules) ~= "table" then
        return out
    end
    local def = M.NormAction(defaultAction or "keep")
    for i = 1, #rules do
        local r = rules[i]
        if type(r) == "table" then
            local mode = tostring(r.mutMode or "exact"):lower()
            if mode ~= "all" and mode ~= "any" then
                mode = "exact"
            end
            local kgMode = tostring(r.kgMode or "above"):lower()
            if kgMode ~= "below" then
                kgMode = "above"
            end
            out[#out + 1] = {
                action = ruleAction(r, def),
                fruits = setToArr(toSet(r.fruits)),
                variants = setToArr(toSet(r.variants)),
                mutations = setToArr(toSet(r.mutations)),
                mutMode = mode,
                kg = tonumber(r.kg) or 0,
                kgMode = kgMode,
            }
        end
    end
    return out
end

function M.PackInPlace(rules, defaultAction)
    local packed = M.Pack(rules, defaultAction)
    if type(rules) ~= "table" then
        return packed
    end
    for i = 1, #packed do
        local dst = rules[i]
        local src = packed[i]
        if type(dst) ~= "table" then
            rules[i] = src
        else
            dst.action = src.action
            dst.fruits = src.fruits
            dst.variants = src.variants
            dst.mutations = src.mutations
            dst.mutMode = src.mutMode
            dst.kg = src.kg
            dst.kgMode = src.kgMode
        end
    end
    while #rules > #packed do
        table.remove(rules)
    end
    return rules
end

function M.New()
    return {
        action = "keep",
        fruits = {},
        variants = {},
        mutations = {},
        mutMode = "exact",
        kg = 0,
        kgMode = "above",
    }
end

local function matchMuts(ruleMuts, fruitMuts, mutMode)
    local wantNo = false
    local need = {}
    for k, on in pairs(ruleMuts or {}) do
        if on == true then
            if isNoMut(k) then
                wantNo = true
            else
                need[k] = true
            end
        end
    end
    local nNeed = 0
    for _ in pairs(need) do
        nNeed += 1
    end
    local noMutHit = wantNo and not hasAny(fruitMuts)
    if nNeed == 0 then
        if wantNo then
            return noMutHit
        end
        return true
    end
    local namedHit = false
    if mutMode == "any" then
        for name in pairs(need) do
            if fruitMuts[name] == true then
                namedHit = true
                break
            end
        end
    else
        namedHit = true
        for name in pairs(need) do
            if fruitMuts[name] ~= true then
                namedHit = false
                break
            end
        end
        if namedHit and mutMode ~= "all" then
            local nFruit = 0
            for _ in pairs(fruitMuts or {}) do
                nFruit += 1
            end
            namedHit = nFruit == nNeed
        end
    end
    if wantNo then
        return noMutHit or namedHit
    end
    return namedHit
end

local function matchKg(weight, kg, mode)
    kg = tonumber(kg) or 0
    weight = tonumber(weight) or 0
    if kg <= 0 then
        return true
    end
    if tostring(mode) == "below" then
        return weight <= kg
    end
    return weight >= kg
end

function M.MatchRule(rule, name, variant, weight, fruitMuts)
    if type(rule) ~= "table" then
        return false
    end
    if not matchNameSet(toSet(rule.fruits), name) then
        return false
    end
    if not matchNameSet(toSet(rule.variants), variant) then
        return false
    end
    local mode = tostring(rule.mutMode or "exact"):lower()
    if mode ~= "all" and mode ~= "any" then
        mode = "exact"
    end
    if not matchMuts(toSet(rule.mutations), fruitMuts, mode) then
        return false
    end
    return matchKg(weight, rule.kg, rule.kgMode)
end

function M.MatchAny(rules, name, variant, weight, fruitMuts)
    if not M.Has(rules) then
        return false
    end
    for i = 1, #rules do
        if M.MatchRule(rules[i], name, variant, weight, fruitMuts) then
            return true
        end
    end
    return false
end

function M.Explain(action, rules, takeWord)
    takeWord = tostring(takeWord or "COLLECT")
    local past = (takeWord == "SHOVEL") and "shoveled" or "collected"
    local lines = {}
    lines[#lines + 1] = "Each row has its own KEEP or " .. takeWord .. ". KEEP wins if both match. Empty Type/Variant/Mutation/KG = any."
    lines[#lines + 1] = "Any = has at least one selected mutation (example: Haunted OR Spooky)."
    lines[#lines + 1] = "Exact = mutations must match the selected set exactly (no extra, no missing)."
    lines[#lines + 1] = "All = must include every selected mutation (extra mutations OK)."
    lines[#lines + 1] = "[NO MUTATION] + Nightmare in one row = no mutation OR Nightmare."
    if not M.Has(rules) then
        lines[#lines + 1] = "No rules: every fruit is " .. past .. "."
        return table.concat(lines, "\n")
    end
    local hasKeep, hasTake = M.HasKeepTake(rules, action)
    if hasKeep and not hasTake then
        lines[#lines + 1] = "Unmatched fruits are " .. past .. "."
    elseif hasTake and not hasKeep then
        lines[#lines + 1] = "Unmatched fruits stay on the tree."
    else
        lines[#lines + 1] = "Unmatched fruits are " .. past .. "."
    end
    for i, r in ipairs(rules) do
        local muts = setToArr(toSet(r.mutations))
        local mutTxt = #muts == 0 and "any mutation" or table.concat(muts, "+")
        mutTxt = mutTxt:gsub(NO_MUT, "[NO MUTATION]")
        local fr = setToArr(toSet(r.fruits))
        local va = setToArr(toSet(r.variants))
        local typeTxt = #fr == 0 and "any type" or table.concat(fr, ",")
        local varTxt = #va == 0 and "any variant" or table.concat(va, ",")
        local kg = tonumber(r.kg) or 0
        local kgTxt = "any kg"
        if kg > 0 then
            kgTxt = (tostring(r.kgMode) == "below" and ("<" .. tostring(kg) .. " kg") or (">=" .. tostring(kg) .. " kg"))
        end
        local verb = ruleAction(r, action) == "take" and takeWord or "KEEP"
        lines[#lines + 1] = string.format(
            "Rule %d: %s if %s | %s | %s (%s) | %s.",
            i,
            verb,
            typeTxt,
            varTxt,
            mutTxt,
            tostring(r.mutMode or "exact"),
            kgTxt
        )
    end
    return table.concat(lines, "\n")
end

local function mutKnown()
    if M._mutKnown then
        return M._mutKnown
    end
    local set = {}
    pcall(function()
        local MH = require(ReplicatedStorage.Modules.MutationHandler)
        local muts = MH and MH.GetMutations and MH:GetMutations()
        if type(muts) ~= "table" then
            return
        end
        for k, m in pairs(muts) do
            local n = type(m) == "table" and (m.Name or m.name or k) or k
            if type(n) == "string" and n ~= "" then
                set[n] = true
            end
        end
    end)
    M._mutKnown = set
    return set
end

function M.FruitMuts(fruit)
    local fruitMuts = {}
    if not fruit then
        return fruitMuts
    end
    local known = mutKnown()
    local attrs
    pcall(function()
        attrs = fruit:GetAttributes()
    end)
    if type(attrs) == "table" then
        for k, v in pairs(attrs) do
            if v == true and known[k] == true then
                fruitMuts[k] = true
            end
        end
    end
    return fruitMuts
end

local function fruitNameOf(f)
    local s = f:FindFirstChild("Item_String")
    if s and s.Value then
        return tostring(s.Value)
    end
    return tostring(f:GetAttribute("ItemName") or f:GetAttribute("FruitName") or f.Name)
end

local function isRipeFruit(f)
    if not f then
        return false
    end
    local tagged = false
    pcall(function()
        tagged = CollectionService:HasTag(f, "Harvestable") == true
    end)
    if tagged then
        return true
    end
    local prompt = f:FindFirstChildWhichIsA("ProximityPrompt", true)
    if prompt and prompt.Enabled == true then
        return true
    end
    local maxAge = tonumber(f:GetAttribute("MaxAge"))
    local grow = f:FindFirstChild("Grow")
    local ageVal = grow and grow:FindFirstChild("Age")
    if maxAge ~= nil and ageVal and (ageVal:IsA("NumberValue") or ageVal:IsA("IntValue")) then
        return (tonumber(ageVal.Value) or 0) >= maxAge
    end
    local done = tonumber(f:GetAttribute("DoneGrowTime"))
    if done and done > 0 then
        local now = os.time()
        pcall(function()
            now = workspace:GetServerTimeNow()
        end)
        return now >= done
    end
    return false
end

function M.CountGarden(action, rules)
    local keepN, takeN, tot = 0, 0, 0
    local LP = Players.LocalPlayer
    local farm
    pcall(function()
        farm = require(ReplicatedStorage.Modules.GetFarm)(LP)
    end)
    if farm then
        local okOwn, owner = pcall(function()
            return farm.Important.Data.Owner.Value
        end)
        if okOwn and owner ~= LP.Name then
            farm = nil
        end
    end
    local plants = farm and farm:FindFirstChild("Important")
    plants = plants and plants:FindFirstChild("Plants_Physical")
    local known = mutKnown()
    if plants then
        for _, plant in ipairs(plants:GetChildren()) do
            local folder = plant:FindFirstChild("Fruits")
            local list = folder and folder:GetChildren() or {}
            for _, f in ipairs(list) do
                if f:IsA("Model") and isRipeFruit(f) then
                    tot += 1
                    local fruitMuts = {}
                    local attrs = f:GetAttributes()
                    if type(attrs) == "table" then
                        for k, v in pairs(attrs) do
                            if v == true and known[k] == true then
                                fruitMuts[k] = true
                            end
                        end
                    end
                    local name = fruitNameOf(f)
                    local variant = tostring((attrs and attrs.Variant) or "Normal")
                    local weight = tonumber(attrs and attrs.Weight) or 0
                    local allow = M.Allow(action, rules, name, variant, weight, fruitMuts)
                    if allow == false then
                        keepN += 1
                    else
                        takeN += 1
                    end
                end
            end
        end
    end
    return keepN, takeN, tot
end

local function parseKg(txt)
    txt = tostring(txt or ""):gsub("%s+", "")
    if txt == "" then
        return 0, "above"
    end
    local n = tonumber(txt)
    if not n then
        return 0, "above"
    end
    if n < 0 then
        return math.abs(n), "below"
    end
    return n, "above"
end

local function kgText(kg, mode)
    kg = tonumber(kg) or 0
    if kg <= 0 then
        return "0"
    end
    if tostring(mode) == "below" then
        return "-" .. tostring(kg)
    end
    return tostring(kg)
end

function M.MountUI(ui, body, opts)
    opts = opts or {}
    if type(ui) ~= "table" or not body then
        return
    end
    local ac = opts.acState
    if type(ac) ~= "table" then
        return
    end
    if type(ac.ruleMode) ~= "string" or ac.ruleMode == "" then
        ac.ruleMode = "keep"
    end
    ac.ruleMode = M.NormAction(ac.ruleMode)
    ac.rules = M.PackInPlace(ac.rules, ac.ruleMode)

    local takeWord = tostring(opts.takeLabel or "COLLECT")
    local saveRulesKey = tostring(opts.saveRulesKey or "AUTO_COLLECT_RULES")
    local saveModeKey = tostring(opts.saveModeKey or "AUTO_COLLECT_RULE_MODE")

    local function save()
        -- Jangan ganti ac.rules dengan array baru. Tombol KEEP/Exact masih pegang table rule yang lama,
        -- jadi edit setelah Pack tidak ikut tersimpan (No Mutation kelihatan tetap, yang lain hilang saat pindah tab).
        ac.rules = type(ac.rules) == "table" and ac.rules or {}
        for i = 1, #ac.rules do
            local r = ac.rules[i]
            if type(r) == "table" then
                r.action = ruleAction(r, ac.ruleMode)
                r.fruits = setToArr(toSet(r.fruits))
                r.variants = setToArr(toSet(r.variants))
                r.mutations = setToArr(toSet(r.mutations))
                do
                    local mm = tostring(r.mutMode or "exact"):lower()
                    if mm ~= "all" and mm ~= "any" then
                        mm = "exact"
                    end
                    r.mutMode = mm
                end
                r.kg = tonumber(r.kg) or 0
