                            if k ~= nil and tostring(k) ~= "" then
                                known[tostring(k)] = true
                            end
                        end
                    end
                end
                for k, on in pairs(prev) do
                    if on and incoming[k] ~= true and known[k] ~= true then
                        incoming[k] = true
                    end
                end
                return setToArr(incoming)
