------------------------------------------------------------
-- DEBUG
------------------------------------------------------------
local function _dbgOn()
    return (_G.AUTO_COLLECT_DEBUG == true)
        or (G and G.AUTO_COLLECT_DEBUG == true)
end

local function _detailDbgOn()
    return (_G.AUTO_COLLECT_DEBUG_DETAIL == true)
        or (G and G.AUTO_COLLECT_DEBUG_DETAIL == true)
end

local function _ts()
    local ok, s = pcall(function()
        return os.date("%H:%M:%S")
    end)
    return ok and s or "??:??:??"
end

local function DEBUG(...)
    if not _dbgOn() then return end

    local parts = { "[AC@" .. _ts() .. "]" }

    for i = 1, select("#", ...) do
        parts[#parts + 1] = tostring(select(i, ...))
    end

    print(table.concat(parts, " "))
end

local function WARN(...)
    local parts = { "[AC@" .. _ts() .. "][WARN]" }

    for i = 1, select("#", ...) do
        parts[#parts + 1] = tostring(select(i, ...))
    end

    warn(table.concat(parts, " "))
end

------------------------------------------------------------
-- HELPERS
------------------------------------------------------------
local function _canonKey(s)
    s = tostring(s or "")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")
    s = s:gsub("^[Ff]ruit[_%s%-]+", "")
    s = s:gsub("^[Ss]eed[_%s%-]+", "")
    s = s:gsub("^[Pp]lant[_%s%-]+", "")
    s = s:gsub("[_%s%-]+[Ss]eed$", "")
    s = s:gsub("%s+[Ss]eed$", "")
    s = s:lower()
    s = s:gsub("[^%w]+", "")
    return s
end

local function _hasTag(inst, tag)
    if not inst then
        return false
    end
    local okCs, hasCs = pcall(function()
        return CollectionService:HasTag(inst, tag)
    end)
    if okCs and hasCs then
        return true
    end
    if typeof(inst.HasTag) == "function" then
        local ok, res = pcall(inst.HasTag, inst, tag)
        if ok and res then
            return true
        end
    end
    return false
end

local function isGoldenEggName(name)
    local k = _canonKey(name)
    return k == "goldenegg" or k:find("goldenegg", 1, true) ~= nil
end

local NO_MUTATION_KEY = "__NO_MUTATION__"

local function _isNoMutKey(k)
    local s = tostring(k or "")
    if s == "" then
        return false
    end
    if s == NO_MUTATION_KEY or s == "[TANPA MUTASI]" or s == "[NO MUTATION]" or s == "[No Mutation]" or s == "No Mutation" then
        return true
    end
    local c = _canonKey(s)
    return c == "nomutation" or c == "tanpamutasi"
end

local _mutNameList = nil
local _mutNameSet = nil
local _mhMod = nil

local function _mutationHandler()
    if type(_mhMod) == "table" then
        return _mhMod
    end
    local ok, MH = pcall(function()
        return require(ReplicatedStorage.Modules.MutationHandler)
    end)
    if ok and type(MH) == "table" then
        _mhMod = MH
        return MH
    end
    return nil
end

local function _fruitMutationNames()
    if type(_mutNameList) == "table" and #_mutNameList > 0 then
        return _mutNameList
    end
    local list = {}
    local seen = {}
    local function add(name)
        name = tostring(name or "")
        if name == "" or _isNoMutKey(name) or seen[name] then
            return
        end
        seen[name] = true
        list[#list + 1] = name
    end
    pcall(function()
        local MH = _mutationHandler()
        if type(MH) ~= "table" or type(MH.GetMutations) ~= "function" then
            return
        end
        local muts = MH:GetMutations()
        if type(muts) ~= "table" then
            return
        end
        -- GetMutations() is a dict (Sandy, Nightmare, ...), not an array.
        for k, m in pairs(muts) do
            if type(m) == "table" then
                add(m.Name or m.name or k)
            elseif type(m) == "string" then
                add(m)
            elseif type(k) == "string" then
                add(k)
            end
        end
    end)
    if #list > 0 then
        _mutNameList = list
        local set = {}
        for i = 1, #list do
            set[list[i]] = true
        end
        _mutNameSet = set
    end
    return list
end

local function fruitHasKnownMutation(fruit)
    if not fruit then
        return false
    end
    _fruitMutationNames()
    local set = _mutNameSet
    local attrs = fruit:GetAttributes()
    if type(attrs) == "table" and type(set) == "table" then
        for k, v in pairs(attrs) do
            if v == true and set[k] == true then
                return true
            end
        end
        return false
    end
    for _, name in ipairs(_fruitMutationNames()) do
        if fruit:GetAttribute(name) == true then
            return true
        end
    end
    return false
end

local function _hasAnySelected(map)
    if type(map) ~= "table" then
        return false
    end

    for _, v in pairs(map) do
        if v == true then
            return true
        end
    end

    return false
end

local function _mapKeysTrue(map)
    local out = {}

    if type(map) == "table" then
        for k, v in pairs(map) do
            if v == true then
                out[#out + 1] = tostring(k)
            end
        end
    end

    table.sort(out)
    return out
end

local function _arrayToSet(arr)
    local out = {}

    if type(arr) == "table" then
        for _, v in ipairs(arr) do
            if v ~= nil and tostring(v) ~= "" then
                out[tostring(v)] = true
            end
        end
    end

    return out
end

local function _setToArray(map)
    local out = {}

    if type(map) == "table" then
        for k, v in pairs(map) do
            if v == true then
                out[#out + 1] = tostring(k)
            end
        end
    end

    table.sort(out)
    return out
end

local function _normalizeSet(src)
    if type(src) ~= "table" then
        return {}
    end

    local out = {}
    local hasArray = false

    for i = 1, #src do
        local v = src[i]

        if v ~= nil and tostring(v) ~= "" then
            out[tostring(v)] = true
            hasArray = true
        end
    end

    if hasArray then
        return out
    end

    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end

    return out
end

local function getValue(inst, name)
    local v = inst and inst:FindFirstChild(name)

    if v and (
        v:IsA("StringValue")
        or v:IsA("NumberValue")
        or v:IsA("IntValue")
        or v:IsA("BoolValue")
    ) then
        return v.Value
    end

    return nil
end

