-- STATE READ
------------------------------------------------------------
local function getACState()
    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)
    local ac = MAIN and MAIN.misc and MAIN.misc.auto_collect
    ac = type(ac) == "table" and ac or {}

    local fruits =
        type(G.AUTO_COLLECT_FRUITS_SELECTED) == "table"
        and G.AUTO_COLLECT_FRUITS_SELECTED
        or type(AUTO_COLLECT_FRUITS_SELECTED) == "table"
        and AUTO_COLLECT_FRUITS_SELECTED
        or _arrayToSet(ac.fruits)

    local variants =
        type(G.AUTO_COLLECT_VARIANTS_SELECTED) == "table"
        and G.AUTO_COLLECT_VARIANTS_SELECTED
        or type(AUTO_COLLECT_VARIANTS_SELECTED) == "table"
        and AUTO_COLLECT_VARIANTS_SELECTED
        or _arrayToSet(ac.variants)

    local mutations =
        type(G.AUTO_COLLECT_MUTATIONS_SELECTED) == "table"
        and G.AUTO_COLLECT_MUTATIONS_SELECTED
        or type(AUTO_COLLECT_MUTATIONS_SELECTED) == "table"
        and AUTO_COLLECT_MUTATIONS_SELECTED
        or _arrayToSet(ac.mutations)

    local mutationsBlacklist =
        type(G.AUTO_COLLECT_MUTATIONS_BLACKLIST) == "table"
        and G.AUTO_COLLECT_MUTATIONS_BLACKLIST
        or type(AUTO_COLLECT_MUTATIONS_BLACKLIST) == "table"
        and AUTO_COLLECT_MUTATIONS_BLACKLIST
        or _arrayToSet(ac.mutations_blacklist)

    local kg = tonumber(G.AUTO_COLLECT_KG or AUTO_COLLECT_KG or ac.kg) or 0
    local kgMode = tostring(G.AUTO_COLLECT_KG_MODE or AUTO_COLLECT_KG_MODE or ac.kgMode or "above")

    if kgMode ~= "below" and kgMode ~= "above" then
        kgMode = "above"
    end
    
    local delay = tonumber(G.AUTO_COLLECT_DELAY or AUTO_COLLECT_DELAY or ac.delay) or 0.2
    if delay < 0 then delay = 0 end

    return {
        enabled   = (G.AUTO_COLLECT_FRUIT_ENABLED == true)
            or (AUTO_COLLECT_FRUIT_ENABLED == true)
            or (ac.enabled == true),

        fruits    = _normalizeSet(fruits),
        variants  = _normalizeSet(variants),
        mutations = _normalizeSet(mutations),
        mutationsBlacklist = _normalizeSet(mutationsBlacklist),
        kg        = kg,
        delay     = delay,
        kgMode    = kgMode,
        rules     = (type(ac.rules) == "table" and ac.rules)
            or (type(G.AUTO_COLLECT_RULES) == "table" and G.AUTO_COLLECT_RULES)
            or {},
        ruleMode  = tostring(G.AUTO_COLLECT_RULE_MODE or ac.ruleMode or "keep"),
    }
end

local function syncGlobalsFromState()
    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)
    local ac = MAIN and MAIN.misc and MAIN.misc.auto_collect

    if type(ac) == "table" then
        AUTO_COLLECT_FRUIT_ENABLED = (ac.enabled == true)
        G.AUTO_COLLECT_FRUIT_ENABLED = AUTO_COLLECT_FRUIT_ENABLED

        AUTO_COLLECT_FRUITS_SELECTED = _arrayToSet(ac.fruits)
        G.AUTO_COLLECT_FRUITS_SELECTED = AUTO_COLLECT_FRUITS_SELECTED

        AUTO_COLLECT_VARIANTS_SELECTED = _arrayToSet(ac.variants)
        G.AUTO_COLLECT_VARIANTS_SELECTED = AUTO_COLLECT_VARIANTS_SELECTED

        AUTO_COLLECT_MUTATIONS_SELECTED = _arrayToSet(ac.mutations)
        G.AUTO_COLLECT_MUTATIONS_SELECTED = AUTO_COLLECT_MUTATIONS_SELECTED

        AUTO_COLLECT_MUTATIONS_BLACKLIST = _arrayToSet(ac.mutations_blacklist)
        G.AUTO_COLLECT_MUTATIONS_BLACKLIST = AUTO_COLLECT_MUTATIONS_BLACKLIST

        AUTO_COLLECT_KG = tonumber(ac.kg) or 0
        G.AUTO_COLLECT_KG = AUTO_COLLECT_KG

        AUTO_COLLECT_KG_MODE = tostring(ac.kgMode or "above")

        if AUTO_COLLECT_KG_MODE ~= "below" and AUTO_COLLECT_KG_MODE ~= "above" then
            AUTO_COLLECT_KG_MODE = "above"
        end

        G.AUTO_COLLECT_KG_MODE = AUTO_COLLECT_KG_MODE

        G.AUTO_COLLECT_RULES = type(ac.rules) == "table" and ac.rules or {}
        G.AUTO_COLLECT_RULE_MODE = tostring(ac.ruleMode or "keep")
    end
end

syncGlobalsFromState()

