local function _getUpvalue(fn, idx)
    if type(getupvalue) == "function" then
        local ok, v = pcall(getupvalue, fn, idx)

        if ok then
            return v
        end
    end

    return nil
end

local function _getFenv(fn)
    if type(getfenv) == "function" then
        local ok, env = pcall(getfenv, fn)

        if ok then
            return env
        end
    end

    return nil
end

local tblPromptQueue = nil

do
    local env = _getFenv(CollectController.Collect)

    if type(env) == "table" and type(env.tbl_2_upvr) == "table" then
        tblPromptQueue = env.tbl_2_upvr
        DEBUG("QueueRef FOUND via fenv.tbl_2_upvr")
    else
        local uv = _getUpvalue(CollectController.Collect, 2)

        if type(uv) == "table" then
            tblPromptQueue = uv
            DEBUG("QueueRef FOUND via upvalue#2")
        else
            WARN("QueueRef NOT FOUND. Collect mungkin gagal queue.")
        end
    end
end

------------------------------------------------------------
-- FARM CACHE
------------------------------------------------------------
local cachedFarm = nil
local cachedFarmAt = 0

local function getOwnFarm()
    local now = os.clock()

    if cachedFarm
        and cachedFarm.Parent
        and (now - cachedFarmAt) <= FARM_CACHE_SEC
    then
        return cachedFarm
    end

    cachedFarm = nil
    cachedFarmAt = now

    local farms = workspace:FindFirstChild("Farm")

    if not farms then
        DEBUG("Farm workspace.Farm not found")
        return nil
    end

    for _, farm in ipairs(farms:GetChildren()) do
        local ok, owner = pcall(function()
            return farm.Important.Data.Owner.Value
        end)

        if ok and owner == username then
            cachedFarm = farm
            return farm
        end
    end

    DEBUG("Farm sendiri tidak ketemu:", username)
    return nil
end

------------------------------------------------------------
-- FRUIT INFO
------------------------------------------------------------
local function getFruitName(fruit)
    return getValue(fruit, "Item_String")
        or fruit:GetAttribute("ItemName")
        or fruit:GetAttribute("FruitName")
        or fruit:GetAttribute("SeedName")
        or fruit.Name
end

local function getFruitVariant(fruit)
    return tostring(
        getValue(fruit, "Variant")
        or fruit:GetAttribute("Variant")
        or "Normal"
    )
end

local function getFruitWeight(fruit)
    return tonumber(
        getValue(fruit, "Weight")
        or fruit:GetAttribute("Weight")
        or 0
    ) or 0
end

local function getMutationMap(fruit, selectedMap)
    local out = {}

    if _hasAnySelected(selectedMap) then
        for mutName, on in pairs(selectedMap) do
            if on == true and fruit:GetAttribute(mutName) == true then
                out[tostring(mutName)] = true
            end
        end
    end

    return out
end

------------------------------------------------------------
-- FILTER
------------------------------------------------------------
local function matchSet(selectedMap, value)
    if not _hasAnySelected(selectedMap) then
        return true
    end

    local needle = _canonKey(value)

    for k, v in pairs(selectedMap) do
        if v == true and _canonKey(k) == needle then
            return true
        end
    end

    return false
end

local function matchMutation(selectedMap, fruit)
    if not _hasAnySelected(selectedMap) then
        return true
    end

    local wantNo = false
    for selectedName, on in pairs(selectedMap) do
        if on == true then
            if _isNoMutKey(selectedName) then
                wantNo = true
            elseif fruit:GetAttribute(selectedName) == true then
                return true
            end
        end
    end

    -- [TANPA MUTASI] = no mutation on the fruit (variant Gold/Rainbow does not count as a mutation).
    if wantNo and not fruitHasKnownMutation(fruit) then
        return true
    end

    return false
end

local function matchKg(weight, kg, mode)
    kg = tonumber(kg) or 0
    weight = tonumber(weight) or 0

    if kg <= 0 then
        return true
    end

    if tostring(mode) == "below" then
        return weight <= kg
    end

    return weight >= kg
end

local function isFruitModel(fruit)
    if not fruit or not fruit:IsA("Model") then return false end
    if fruit:GetAttribute("FruitVersion") ~= nil then return true end
    if fruit:FindFirstChildWhichIsA("ProximityPrompt", true) then return true end
    if fruit:GetAttribute("ItemName") or fruit:GetAttribute("FruitName") or fruit:GetAttribute("Weight") then return true end
    if fruit:FindFirstChild("Item_String") or fruit:FindFirstChild("Weight") then return true end
    if _hasTag(fruit, "Harvestable") then
        return true
    end
    if isGoldenEggName(fruit.Name)
        or isGoldenEggName(fruit:GetAttribute("ItemName"))
        or isGoldenEggName(fruit:GetAttribute("FruitName"))
    then
        return true
    end
    return false
end

local function fruitFromPrompt(prompt)
    if not prompt or not prompt.Parent then
        return nil
    end
    local inst = prompt.Parent
    while inst and inst ~= workspace do
        if inst:IsA("Model") then
            if isFruitModel(inst) then
                return inst
            end
            local par = inst.Parent
            if par and par.Name == "Plants_Physical" then
                return inst
            end
            if par and par.Name == "Fruits" then
                return inst
            end
        end
        inst = inst.Parent
    end
    return nil
end

local function isRipeFruit(f)
    if not f then
        return false
    end
    if _hasTag(f, "Harvestable") then
        return true
    end
    local prompt = f:FindFirstChildWhichIsA("ProximityPrompt", true)
    if prompt and prompt.Enabled == true then
        return true
    end
    local maxAge = tonumber(f:GetAttribute("MaxAge"))
    local grow = f:FindFirstChild("Grow")
    local ageVal = grow and grow:FindFirstChild("Age")
    if maxAge ~= nil and ageVal and (ageVal:IsA("NumberValue") or ageVal:IsA("IntValue")) then
        return (tonumber(ageVal.Value) or 0) >= maxAge
    end
    local done = tonumber(f:GetAttribute("DoneGrowTime"))
    if done and done > 0 then
        local now = os.time()
        pcall(function()
            now = workspace:GetServerTimeNow()
        end)
        return now >= done
    end
    return false
end

local function isFruitAllowed(fruit, ac)
    if not fruit or not fruit:IsA("Model") then
        return false, "not_model"
    end

if not isFruitModel(fruit) then
    return false, "not_fruit_model"
end

    if not isRipeFruit(fruit) then
        return false, "not_ripe"
    end

    local name = getFruitName(fruit)
    local variant = getFruitVariant(fruit)
    local weight = getFruitWeight(fruit)
    local muts = getMutationMap(fruit, ac.mutations)

    local CR = rawget(G, "CollectRules") or rawget(_G, "CollectRules")
    if type(CR) == "table" and type(CR.Allow) == "function" and type(CR.Has) == "function" and CR.Has(ac.rules) then
        _fruitMutationNames()
        local fruitMuts = {}
        local set = _mutNameSet
        local attrs = fruit:GetAttributes()
        if type(attrs) == "table" and type(set) == "table" then
            for k, v in pairs(attrs) do
                if v == true and set[k] == true then
                    fruitMuts[k] = true
                end
            end
        end
        local okRule = CR.Allow(ac.ruleMode, ac.rules, name, variant, weight, fruitMuts)
        if okRule == true then
            return true, "ok", name, variant, weight, muts
        end
        return false, "collect_rule", name, variant, weight, muts
    end

    return true, "ok", name, variant, weight, muts
end

------------------------------------------------------------
-- HOLDABLE COUNT / CAPACITY (match Backpack UpdateInventorySizeIndicator)
------------------------------------------------------------
local holdableCache = 0
local holdableCacheAt = 0

local function getBonusBackpackSize()
    return tonumber(LP:GetAttribute("BonusBackpackSize")) or 0
end

local function getMaxHoldableCapacity()
    return math.ceil(BASE_HOLDABLE_CAPACITY + getBonusBackpackSize())
end

local function _countFromInventoryService()
    if type(InventoryService) ~= "table" or type(InventoryService.Find) ~= "function" then
        return nil
    end

    local ok, result = pcall(function()
        return InventoryService:Find("Holdable")
    end)

    if not ok or type(result) ~= "table" then
        return nil
    end

    local n = 0
    for _ in pairs(result) do
        n += 1
    end

    return n
end

local function _countHoldablesFromProfile(profile)
    if type(profile) ~= "table" then
        return nil
    end

    local inv = profile.InventoryData

    if type(inv) ~= "table" then
        return nil
    end

    local n = 0
    local seenAny = false

    for _, item in pairs(inv) do
        if type(item) == "table" then
            seenAny = true

            local it = tostring(item.ItemType or item.Type or item.Category or ""):lower()

            if it:find("hold") or it == "holdable" then
                n += 1
            end
        end
    end

    if seenAny then
        return n
    end

    return nil
end

local function _countHoldablesByTools()
    local n = 0

    local function scan(container)
        if not container then
            return
        end

        for _, inst in ipairs(container:GetChildren()) do
            if inst:IsA("Tool") then
                n += 1
            end
        end
    end

    scan(LP:FindFirstChild("Backpack"))
    scan(LP.Character)

    return n
end

local function getHoldableCount()
    local now = os.clock()

    if (now - holdableCacheAt) <= HOLDABLE_CACHE_SEC then
        return holdableCache
    end

    holdableCacheAt = now

    local fromInv = _countFromInventoryService()
    if type(fromInv) == "number" then
        holdableCache = fromInv
        return fromInv
    end

    if DataService and type(DataService.GetData) == "function" then
        local ok, profile = pcall(function()
            return DataService:GetData()
        end)

        if ok and type(profile) == "table" then
            local c = _countHoldablesFromProfile(profile)

            if type(c) == "number" then
                holdableCache = c
                return c
            end
        end
    end

    holdableCache = _countHoldablesByTools()
    return holdableCache
end

function M.GetMaxHoldableCapacity()
    return getMaxHoldableCapacity()
end
M.getMaxHoldableCapacity = M.GetMaxHoldableCapacity

function M.GetCapacityInfo()
    return {
        count = getHoldableCount(),
        max = getMaxHoldableCapacity(),
        bonus = getBonusBackpackSize(),
        full = getHoldableCount() >= getMaxHoldableCapacity(),
    }
end
M.getCapacityInfo = M.GetCapacityInfo

------------------------------------------------------------
-- PROMPT CACHE + COOLDOWN
------------------------------------------------------------
local PROMPT_CACHE = setmetatable({}, { __mode = "k" })
local PROMPT_COOLDOWN = setmetatable({}, { __mode = "k" })

local function getPromptCached(fruit)
    local cached = PROMPT_CACHE[fruit]

    if cached and cached.Parent then
        return cached
    end

    local prompt = fruit:FindFirstChildWhichIsA("ProximityPrompt", true)

    if prompt then
        PROMPT_CACHE[fruit] = prompt
    end

    return prompt
end

local function prunePromptQueue(ac)
    if type(tblPromptQueue) ~= "table" then
        return 0
    end
    ac = ac or getACState()
    local keepN = 0
    for prompt, on in pairs(tblPromptQueue) do
        if on ~= true or not prompt or not prompt.Parent then
            tblPromptQueue[prompt] = nil
        else
            local fruit = fruitFromPrompt(prompt)
            local farm = getOwnFarm()
            local onOwn = farm and prompt:IsDescendantOf(farm)
            local allowed = onOwn and fruit and select(1, isFruitAllowed(fruit, ac)) == true
            if allowed then
                keepN += 1
            else
                tblPromptQueue[prompt] = nil
            end
        end
    end
    return keepN
end

local function cleanupPromptCooldown()
    local now = tick()

    for prompt, expire in pairs(PROMPT_COOLDOWN) do
        if now >= expire then
            PROMPT_COOLDOWN[prompt] = nil

            if prompt and prompt.Parent then
                prompt:SetAttribute("Collected", nil)
            end
        end
    end
end

------------------------------------------------------------
-- QUEUE - CHUNK SCAN
------------------------------------------------------------
local stats = {
    loops = 0,
    queued = 0,
    scannedPlants = 0,
    scannedFruits = 0,
    skipped = 0,
    collectCalls = 0,
    lastSummary = os.clock(),
}

local STATUS = { text = "Collect: idle" }
local tickSkip = {}

local REASON_SHORT = {
    fruit_filter = "fruit",
    variant_filter = "variant",
    mutation_filter = "whitelist",
    mutation_blacklist = "blacklist",
    kg_filter = "kg",
    collect_rule = "rule",
    not_ripe = "not ripe",
    not_fruit_model = "not fruit",
    not_model = "not fruit",
    prompt = "prompt",
}

local function setCollectStatus(text)
    text = tostring(text or "Collect: —")
    STATUS.text = text
    G.__AC_STATUS_TEXT = text
    _G.__AC_STATUS_TEXT = text
end
setCollectStatus("Collect: idle")

local function bumpSkip(reason)
    reason = tostring(reason or "skip")
    tickSkip[reason] = (tickSkip[reason] or 0) + 1
    stats.skipped += 1
end

local function topSkipLabel()
    local best, n = nil, 0
    for k, v in pairs(tickSkip) do
        if v > n then
            best, n = k, v
        end
    end
    if not best then
        return nil, 0
    end
    return (REASON_SHORT[best] or best), n
end

local function queueFruitPrompts()
    tickSkip = {}
    if type(tblPromptQueue) ~= "table" then
        DEBUG("Queue skip: tblPromptQueue invalid")
        setCollectStatus("Collect: ERROR — CollectController queue missing")
        return 0
    end

    local farm = getOwnFarm()

    if not farm then
        setCollectStatus("Collect: no farm")
        return 0
    end

    local important = farm:FindFirstChild("Important")
    local plants = important and important:FindFirstChild("Plants_Physical")

    prunePromptQueue(getACState())

    if not plants then
        DEBUG("Plants_Physical tidak ketemu")
        setCollectStatus("Collect: no Plants_Physical")
        return 0
    end

    local ac = getACState()
    local countQueued = 0

    local allPlants = plants:GetChildren()
    local totalPlants = #allPlants

    if totalPlants <= 0 then
        return 0
    end

    for _ = 1, SCAN_PER_LOOP do
        if scanIndex > totalPlants then
            scanIndex = 1
        end

        local plant = allPlants[scanIndex]
        scanIndex += 1

        stats.scannedPlants += 1

        if plant then
            local fruitsFolder = plant:FindFirstChild("Fruits")
            local fruits = {}

            if fruitsFolder then
                fruits = fruitsFolder:GetChildren()
            end

            -- Folder Fruits kosong / tidak ada: 1x harvest (Carrot, Golden Egg, dll)
            if #fruits == 0 then
                local harvestable = _hasTag(plant, "Harvestable")
                local prompt = plant:FindFirstChildWhichIsA("ProximityPrompt", true)
                local collectPrompt = prompt and (
                    _hasTag(prompt, "CollectPrompt")
                    or prompt.Enabled == true
                )
                local named = isGoldenEggName(plant.Name)
                    or isGoldenEggName(getFruitName(plant))
                if harvestable or collectPrompt or named then
                    fruits = { plant }
                end
            end

            for _, fruit in ipairs(fruits) do
                    stats.scannedFruits += 1

                    if countQueued >= MAX_COLLECT_PER_LOOP then
                        return countQueued
                    end

                    local allowed, reason, name, variant, weight = isFruitAllowed(fruit, ac)

                    if allowed then
                        local prompt = getPromptCached(fruit)

                        if prompt
                            and prompt.Enabled
                            and not prompt:GetAttribute("Collected")
                            and not PROMPT_COOLDOWN[prompt]
                        then
                            tblPromptQueue[prompt] = true
                            prompt:SetAttribute("Collected", true)
                            PROMPT_COOLDOWN[prompt] = tick() + PROMPT_MARK_SEC

                            countQueued += 1

                            if _detailDbgOn() then
                                DEBUG(
                                    "QUEUE",
                                    tostring(name),
                                    "variant=" .. tostring(variant),
                                    "kg=" .. tostring(weight)
                                )
                            end
                        else
                            bumpSkip("prompt")
                        end
                    else
                        bumpSkip(reason)

                        if _detailDbgOn() then
                            DEBUG(
                                "SKIP",
                                tostring(reason),
                                tostring(name or fruit.Name),
                                tostring(variant or "-"),
                                tostring(weight or "-")
                            )
                        end
                    end
            end
        end
    end

    stats.queued += countQueued
    return prunePromptQueue(ac)
end

------------------------------------------------------------
-- DEBUG SUMMARY
------------------------------------------------------------
local function debugSummary(runningState)
    if not _dbgOn() then
        return
    end

    local now = os.clock()

    if (now - stats.lastSummary) < DEBUG_SUMMARY_SEC then
        return
    end

    stats.lastSummary = now

    DEBUG(
        "SUMMARY",
        "running=" .. tostring(runningState),
        "loops=" .. tostring(stats.loops),
        "queued=" .. tostring(stats.queued),
        "collectCalls=" .. tostring(stats.collectCalls),
        "plants=" .. tostring(stats.scannedPlants),
        "fruits=" .. tostring(stats.scannedFruits),
        "skipped=" .. tostring(stats.skipped),
        "hold=" .. tostring(holdableCache)
    )

    stats.loops = 0
    stats.queued = 0
    stats.collectCalls = 0
    stats.scannedPlants = 0
    stats.scannedFruits = 0
    stats.skipped = 0
end

------------------------------------------------------------
-- LOOP
------------------------------------------------------------
local running = false
local loopId = 0

local function collectLoop(myId)
    DEBUG("Loop START", "id=" .. tostring(myId))

    while running and myId == loopId do
        stats.loops += 1

        cleanupPromptCooldown()

        local ac = getACState()

        if ac.enabled == true then
            local holdCount = getHoldableCount()
            local maxHold = getMaxHoldableCapacity()

            if holdCount < maxHold then
                local queued = queueFruitPrompts()
                local skipN = 0
                for _, v in pairs(tickSkip) do
                    skipN += v
                end
                local top = select(1, topSkipLabel())

                if queued > 0 then
                    setCollectStatus(string.format("Collect: take %d", queued))
                    DEBUG("Collect queued=" .. tostring(queued))

                    local delayNow = tonumber(ac.delay)
                        or tonumber(G.AUTO_COLLECT_DELAY)
                        or tonumber(AUTO_COLLECT_DELAY)
                        or 0
                    if delayNow < 0 then delayNow = 0 end
                    local burstGap = (delayNow <= 0) and 0 or COLLECT_BURST_GAP
                    for i = 1, COLLECT_CALLS_PER_BURST do
                        if i == 1 or (i % 4) == 0 then
                            if prunePromptQueue(ac) <= 0 then
                                break
                            end
                        end
                        local ok, err = pcall(function()
                            CollectController:Collect()
                        end)

                        if not ok then
                            WARN("Collect ERROR", err)
                            setCollectStatus("Collect: ERROR " .. tostring(err))
                            break
                        end

                        stats.collectCalls += 1
                        if burstGap > 0 then
                            task.wait(burstGap)
                        end
                    end
                    prunePromptQueue(ac)
                elseif top then
                    setCollectStatus(string.format("Collect: 0 ripe · skip %d (%s)", skipN, top))
                else
                    setCollectStatus("Collect: scanning · 0 ripe")
                end
            else
                setCollectStatus(string.format("Collect: bag full %d/%d", holdCount, maxHold))
                DEBUG("Collect skip holdable full", holdCount, "/", maxHold)
                task.wait(0.25)
            end
        else
            setCollectStatus("Collect: OFF")
        end

        debugSummary(true)

local waitDelay =
    tonumber(ac.delay)
    or tonumber(G.AUTO_COLLECT_DELAY)
    or tonumber(AUTO_COLLECT_DELAY)
    or LOOP_TICK_SEC

if waitDelay < 0 then
    waitDelay = 0
end
-- Delay 0 = secepat CollectController. Jangan paksa 0.02.
if waitDelay > 0 then
    task.wait(waitDelay)
else
    task.wait()
end
    end

    DEBUG("Loop END", "id=" .. tostring(myId))
    if not running then
        setCollectStatus("Collect: OFF")
    end
end

------------------------------------------------------------
-- PUBLIC API
------------------------------------------------------------
local function _coerceOn(a, b)
    if type(a) == "table" then
        return b == true
    end

    return a == true
end

function M.SetEnabled(a, b)
    local on = _coerceOn(a, b)

    DEBUG("API SetEnabled", tostring(on))

    G.AUTO_COLLECT_FRUIT_ENABLED = on
    AUTO_COLLECT_FRUIT_ENABLED = on

    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)

    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.auto_collect = MAIN.misc.auto_collect or {}
        MAIN.misc.auto_collect.enabled = on
    end

    if on then
        if not running then
            running = true
            loopId += 1

            local myId = loopId

            task.spawn(function()
                collectLoop(myId)
            end)
        end
    else
        running = false
        setCollectStatus("Collect: OFF")
    end
end

function M.setEnabled(a, b)
    return M.SetEnabled(a, b)
end

function M.Start()
    return M.SetEnabled(true)
end

function M.start()
    return M.Start()
end

function M.Stop()
    return M.SetEnabled(false)
end

function M.stop()
    return M.Stop()
end

function M.IsRunning()
    return running == true
end

function M.isRunning()
    return M.IsRunning()
end

function M.SetFruits(a, b)
    local map = a

    if type(a) == "table" and b ~= nil then
        map = b
    end

    map = _normalizeSet(map)

    G.AUTO_COLLECT_FRUITS_SELECTED = map
    AUTO_COLLECT_FRUITS_SELECTED = map

    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)

    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.auto_collect = MAIN.misc.auto_collect or {}
        MAIN.misc.auto_collect.fruits = _setToArray(map)
    end

    DEBUG("API SetFruits", table.concat(_mapKeysTrue(map), ","))
end

M.SetSelected = M.SetFruits
M.setSelected = M.SetFruits
M.setFruits = M.SetFruits

function M.SetVariants(a, b)
    local map = a

    if type(a) == "table" and b ~= nil then
        map = b
    end

    map = _normalizeSet(map)

    G.AUTO_COLLECT_VARIANTS_SELECTED = map
    AUTO_COLLECT_VARIANTS_SELECTED = map

    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)

    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.auto_collect = MAIN.misc.auto_collect or {}
        MAIN.misc.auto_collect.variants = _setToArray(map)
    end

    DEBUG("API SetVariants", table.concat(_mapKeysTrue(map), ","))
end

M.setVariants = M.SetVariants

function M.SetMutations(a, b)
    local map = a

    if type(a) == "table" and b ~= nil then
        map = b
    end

    map = _normalizeSet(map)

    G.AUTO_COLLECT_MUTATIONS_SELECTED = map
    AUTO_COLLECT_MUTATIONS_SELECTED = map

    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)

    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.auto_collect = MAIN.misc.auto_collect or {}
        MAIN.misc.auto_collect.mutations = _setToArray(map)
    end

    DEBUG("API SetMutations", table.concat(_mapKeysTrue(map), ","))
end

