function M.SetMutationBlacklist(a, b)
    local map = a

    if type(a) == "table" and b ~= nil then
        map = b
    end

    map = _normalizeSet(map)

    G.AUTO_COLLECT_MUTATIONS_BLACKLIST = map
    AUTO_COLLECT_MUTATIONS_BLACKLIST = map

