function M.SetKgFilter(a, b, c)
    local kg, mode

    if type(a) == "table" then
        kg = b
        mode = c
    else
        kg = a
        mode = b
    end

    kg = tonumber(kg) or 0
    mode = tostring(mode or "above")

    if mode ~= "below" and mode ~= "above" then
        mode = "above"
    end

    G.AUTO_COLLECT_KG = kg
    G.AUTO_COLLECT_KG_MODE = mode

    AUTO_COLLECT_KG = kg
    AUTO_COLLECT_KG_MODE = mode

    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)

    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.auto_collect = MAIN.misc.auto_collect or {}
        MAIN.misc.auto_collect.kg = kg
        MAIN.misc.auto_collect.kgMode = mode
    end

    DEBUG("API SetKgFilter", "kg=" .. tostring(kg), "mode=" .. tostring(mode))
end

M.setKgFilter = M.SetKgFilter

function M.SetRules(a, b)
    local rules = a
    if type(a) == "table" and b ~= nil then
        rules = b
    end
    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)
    local ac = type(MAIN) == "table" and MAIN.misc and MAIN.misc.auto_collect
    -- Table yang sama dengan UI. Jangan Pack (itu bikin table baru dan klik KEEP/Exact/mutasi tidak nyangkut).
    if type(ac) == "table" and ac.rules == rules then
        G.AUTO_COLLECT_RULES = ac.rules
        _G.AUTO_COLLECT_RULES = ac.rules
        return
    end
    local CR = rawget(G, "CollectRules") or rawget(_G, "CollectRules")
    if type(CR) == "table" and type(CR.Pack) == "function" then
        rules = CR.Pack(rules)
    elseif type(rules) ~= "table" then
        rules = {}
    end
    G.AUTO_COLLECT_RULES = rules
    _G.AUTO_COLLECT_RULES = rules
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.auto_collect = MAIN.misc.auto_collect or {}
        MAIN.misc.auto_collect.rules = rules
    end
end

M.setRules = M.SetRules

function M.SetRuleMode(a, b)
    local mode = a
    if type(a) == "table" and b ~= nil then
        mode = b
    end
    local CR = rawget(G, "CollectRules") or rawget(_G, "CollectRules")
    if type(CR) == "table" and type(CR.NormAction) == "function" then
        mode = CR.NormAction(mode)
    else
        mode = tostring(mode or "keep")
    end
    G.AUTO_COLLECT_RULE_MODE = mode
    local MAIN = rawget(_G, "MAIN") or (G and G.MAIN)
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.auto_collect = MAIN.misc.auto_collect or {}
        MAIN.misc.auto_collect.ruleMode = mode
    end
end

M.setRuleMode = M.SetRuleMode

