            -- webhook.lua
-- Direct Discord webhook (no PHP). Stage / Result / Mutation Machine embeds built in Lua.
local M = {}

local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local LP = Players.LocalPlayer

local G = (getgenv and getgenv()) or _G

local LAST_SEND = 0
local MIN_DELAY = 1.5
local LOOP_RUNNING = false
local RESULT_VERSION = 3

local CAN_FS = (
    typeof(writefile) == "function"
    and typeof(readfile) == "function"
    and typeof(isfile) == "function"
    and typeof(makefolder) == "function"
)

local SAVE_DIR = "autosk"

local function safeName(s)
    s = tostring(s or "player")
    s = s:gsub("[^%w%-_.]", "_")
    s = s:gsub("_+", "_")
    return s:sub(1, 48)
end

local USERNAME = safeName(LP and LP.Name or "player")
local RESULT_FILE = ("%s/%s_webhook_result.json"):format(SAVE_DIR, USERNAME)

local function ensureFolder()
    if not CAN_FS then return false end
    if not isfolder(SAVE_DIR) then
        pcall(makefolder, SAVE_DIR)
    end
    return isfolder(SAVE_DIR)
end

local function clampNumber(v, minV, maxV, def)
    v = tonumber(v)
    if not v then return def end
    v = math.floor(v)
    if v < minV then v = minV end
    if v > maxV then v = maxV end
    return v
end

local function formatTime(ts)
    ts = tonumber(ts) or os.time()
    return os.date("%Y-%m-%d %H:%M:%S", ts)
end

local function detectDurationSec(data)
    if type(data) ~= "table" then return 0 end

    return tonumber(
        data.durationSec
        or data.duration
        or data.elapsedSec
        or 0
    ) or 0
end

local function _isPetTool(t)
    if not (t and t:IsA("Tool")) then return false end
    local it = t:GetAttribute("ItemType") or t:GetAttribute("Itemtype")
    return it and string.lower(tostring(it)) == "pet"
end

local function _countTargetBackpack(plr)
    if not (plr and plr:IsA("Player")) then return nil end

    local bp = plr:FindFirstChild("Backpack")
    if not bp then return nil end

    local cnt = 0
    for _, child in ipairs(bp:GetChildren()) do
        if _isPetTool(child) then
            cnt += 1
        end
    end

    return cnt
end

local function getCurrentPlayersInfo(cfg)
    local arr = {}
    local lowBackpackPlayers = {}
    local totalKnownBackpackPets = 0
    local knownBackpackPlayers = 0

    local backpackLimit = tonumber(cfg and cfg.pingBackpackBelow) or 20

    for _, plr in ipairs(Players:GetPlayers()) do
        local petCount = _countTargetBackpack(plr)

        local info = {
            displayName = tostring(plr.DisplayName or ""),
            backpackPetCount = petCount,
        }

        arr[#arr + 1] = info

        if petCount ~= nil then
            knownBackpackPlayers += 1
            totalKnownBackpackPets += petCount

            if cfg
                and cfg.pingBackpackEnabled == true
                and petCount < backpackLimit
            then
                lowBackpackPlayers[#lowBackpackPlayers + 1] = info
            end
        end
    end

    return {
        count = #arr,
        players = arr,
        knownBackpackPlayers = knownBackpackPlayers,
        totalKnownBackpackPets = totalKnownBackpackPets,
        lowBackpackPlayers = lowBackpackPlayers,
    }
end

local RESULT = {
    version = RESULT_VERSION,

    startedAt = os.time(),
    startedAtText = formatTime(os.time()),
    lastReset = os.time(),
    lastResetText = formatTime(os.time()),
    lastSend = 0,
    lastSendText = "",
    updatedAt = os.time(),
    updatedAtText = formatTime(os.time()),
    stageSec = {},
    
    total = 0,
    stageRun = {},

    teamByStage = {},
    jobFinish = {},
    mutationFinish = {},
}

local function saveResult()
    if not CAN_FS or not ensureFolder() then return false end

    local ok, json = pcall(function()
        return HttpService:JSONEncode(RESULT)
    end)

    if ok and type(json) == "string" then
        pcall(writefile, RESULT_FILE, json)
        return true
    end

    return false
end

local function loadResult()
    if not CAN_FS or not isfile(RESULT_FILE) then return false end

    local ok, txt = pcall(readfile, RESULT_FILE)
    if not ok or type(txt) ~= "string" or txt == "" then return false end

    local ok2, data = pcall(function()
        return HttpService:JSONDecode(txt)
    end)

    if ok2 and type(data) == "table" then
        local fileVersion = tonumber(data.version) or 0

        if fileVersion ~= RESULT_VERSION then
            warn("[Webhook] Result version mismatch → auto reset")
            return false
        end

        RESULT = data

        RESULT.startedAt = tonumber(RESULT.startedAt) or os.time()
        RESULT.startedAtText = tostring(RESULT.startedAtText or formatTime(RESULT.startedAt))
        RESULT.lastReset = tonumber(RESULT.lastReset) or RESULT.startedAt
        RESULT.lastResetText = tostring(RESULT.lastResetText or formatTime(RESULT.lastReset))
        RESULT.lastSend = tonumber(RESULT.lastSend) or 0
        RESULT.lastSendText = tostring(RESULT.lastSendText or "")

        RESULT.updatedAt = tonumber(RESULT.updatedAt) or os.time()
        RESULT.updatedAtText = tostring(RESULT.updatedAtText or formatTime(RESULT.updatedAt))
RESULT.stageSec = type(RESULT.stageSec) == "table" and RESULT.stageSec or {}
RESULT.total = tonumber(RESULT.total) or 0

RESULT.stageRun = type(RESULT.stageRun) == "table" and RESULT.stageRun or {}


RESULT.modeFinished = type(RESULT.modeFinished) == "table" and RESULT.modeFinished or {}
RESULT.teamByStage = type(RESULT.teamByStage) == "table" and RESULT.teamByStage or {}
RESULT.jobFinish = type(RESULT.jobFinish) == "table" and RESULT.jobFinish or {}
RESULT.mutationFinish = type(RESULT.mutationFinish) == "table" and RESULT.mutationFinish or {}


        return true
    end

    return false
end

local loaded = loadResult()
if not loaded then
    RESULT.version = RESULT_VERSION
    saveResult()
end

local function getWebhookState()
    G.STATE = type(G.STATE) == "table" and G.STATE or {}
    G.STATE.webhook = type(G.STATE.webhook) == "table" and G.STATE.webhook or {}

    local WH = G.STATE.webhook

    local enabled = (WH.enabled == true) or (G.WEBHOOK_ENABLED == true)
    local resultEnabled = (WH.resultEnabled == true) or (G.WEBHOOK_RESULT_ENABLED == true)

    local resetHours = clampNumber(
        WH.resultResetHours or G.WEBHOOK_RESULT_RESET_HOURS,
        1,
        72,
        24
    )

    local sendHours = clampNumber(
        WH.resultSendHours or G.WEBHOOK_RESULT_SEND_HOURS,
        1,
        600,
        1
    )

    -- sync balik tapi jangan matikan paksa
    WH.resultEnabled = resultEnabled
    WH.resultResetHours = resetHours
    WH.resultSendHours = sendHours

return {
    enabled = enabled,
    mode = tostring(WH.mode or G.WEBHOOK_MODE or "FULL"),

    url = tostring(WH.targetUrl or G.WEBHOOK_URL or ""),
    targetWebhook = tostring(WH.targetUrl or G.WEBHOOK_URL or ""),

    resultEnabled = resultEnabled,
    resultResetHours = resetHours,
    resultSendHours = sendHours,

    pingPlayerEnabled = (WH.pingPlayerEnabled == true) or (G.WEBHOOK_PING_PLAYER_ENABLED == true),
    pingPlayerBelow = clampNumber(
        WH.pingPlayerBelow or G.WEBHOOK_PING_PLAYER_BELOW,
        1,
        50,
        2
    ),

    pingBackpackEnabled = (WH.pingBackpackEnabled == true) or (G.WEBHOOK_PING_BACKPACK_ENABLED == true),
    pingBackpackBelow = clampNumber(
        WH.pingBackpackBelow or G.WEBHOOK_PING_BACKPACK_BELOW,
        1,
        500,
        20
    ),
}
end

local function httpPost(url, body)
    local req =
        (syn and syn.request)
        or (http and http.request)
        or http_request
        or request

    if type(req) ~= "function" then
        return false, "no_http_request"
    end

    local ok, res = pcall(req, {
        Url = url,
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json",
        },
        Body = body,
    })

    if not ok then
        return false, tostring(res)
    end

    local code = tonumber(res and (res.StatusCode or res.status_code or res.Status))
    if code and (code < 200 or code >= 300) then
        return false, "http_" .. tostring(code)
    end

    return true, res
end

local function basePayload(eventName, data)
    return {
        event = tostring(eventName or "UNKNOWN"),
        mode = "FULL",
        ts = os.time(),
        tsText = formatTime(os.time()),
        jobId = tostring(game.JobId or ""),
        placeId = game.PlaceId,
        player = {
            name = LP and LP.Name or "",
            userId = LP and LP.UserId or 0,
        },
        data = data or {},
    }
end

local function incMap(map, key)
    key = tostring(key or "")
    if key == "" then return end

    map[key] = tonumber(map[key]) or 0
    map[key] += 1
end

local function detectStage(data)
    if type(data) ~= "table" then return "" end

    return tostring(
        data.stage
        or data.currentStage
        or data.activeStage
        or data.CURRENT_STAGE
        or data.role
        or ""
    )
end

local function detectReason(data)
    if type(data) ~= "table" then return "" end

    return tostring(
        data.reason
        or data.reasonEnd
        or data.endReason
        or ""
    )
end

local function detectPetType(data)
    if type(data) ~= "table" then return "" end

    if type(data.targetStart) == "table" and data.targetStart.petType then
        return tostring(data.targetStart.petType)
    end

    if type(data.targetEnd) == "table" and data.targetEnd.petType then
        return tostring(data.targetEnd.petType)
    end

    return tostring(data.petType or "")
end



local function simplifyTeam(team)
    local out = {}

    if type(team) ~= "table" then
        return out
    end

    for role, arr in pairs(team) do
        out[tostring(role)] = {}

        if type(arr) == "table" then
            for _, p in ipairs(arr) do
                if type(p) == "table" then
                    table.insert(out[tostring(role)], {
                        petType = tostring(p.petType or "?"),
                        kg = tonumber(p.kg) or 0,
                    })
                end
            end
        end
    end

    return out
end

local STAGE_TO_TAB = {
    A = "boost",
    B = "xp",
    C = "noos",
    D = "seratusage",
}

local ROLE_TO_STAGE = {
    boost = "A",
    xp = "B",
    noos = "C",
    seratusage = "D",
}

local function getStageTargetEquip()
    local GG = (getgenv and getgenv()) or _G
    local T = rawget(GG, "TAB_TARGET_EQUIP_MAX")
        or rawget(_G, "TAB_TARGET_EQUIP_MAX")
        or {}

    local out = {}

    for stage, tab in pairs(STAGE_TO_TAB) do
        out[stage] = tonumber(T[tab]) or 0
    end

    return out
end

local function normStage(stage, role)
    stage = tostring(stage or ""):upper()

    if stage == "A" or stage == "B" or stage == "C" or stage == "D" then
        return stage
    end

    local r = tostring(role or ""):lower()
    return ROLE_TO_STAGE[r] or stage
end

local function getEndInfo(data)
    if type(data) ~= "table" then return {} end
    if type(data.targetEnd) == "table" then return data.targetEnd end
    if type(data.targetStart) == "table" then return data.targetStart end
    return data
end

local function hasMutation(info)
    if type(info) ~= "table" then return false end

    local selected = rawget(G, "GBXP_MUT_SELECTED") or rawget(_G, "GBXP_MUT_SELECTED") or {}
    local hasSelected = false
    local selectedLC = {}

    if type(selected) == "table" then
        for name, on in pairs(selected) do
            if on then
                hasSelected = true
                selectedLC[tostring(name):lower()] = true
            end
        end
    end

    local foundAny = false

    local function checkName(name)
        name = tostring(name or "")
        if name == "" or name == "-" then return false end

        foundAny = true

        if not hasSelected then
            return true -- semua valid kalau tidak ada filter
        end

        return selectedLC[name:lower()] == true
    end

    -- cek array mutation
    if type(info.mutations) == "table" then
        for _, name in ipairs(info.mutations) do
            if checkName(name) then
                return true
            end
        end
    end

    -- cek text fallback
    local m = tostring(info.mutText or info.mutation or "")
    if m ~= "" and m ~= "-" then
        for part in m:gmatch("[^,%+]+") do
            part = part:gsub("^%s+", ""):gsub("%s+$", "")
            if checkName(part) then
                return true
            end
        end
    end

    -- ❌ tidak punya mutation sama sekali
    if not foundAny then
        return false
    end

    return false
end

local function getRuleTables()
    local GG = (getgenv and getgenv()) or _G

    return
        TAB_AGE_EQUIP_MIN   or rawget(GG, "TAB_AGE_EQUIP_MIN")   or _G.TAB_AGE_EQUIP_MIN   or {},
        TAB_AGE_UNEQUIP_MIN or rawget(GG, "TAB_AGE_UNEQUIP_MIN") or _G.TAB_AGE_UNEQUIP_MIN or {},
        TAB_W_EQUIP_MIN     or rawget(GG, "TAB_W_EQUIP_MIN")     or _G.TAB_W_EQUIP_MIN     or {},
        TAB_W_UNEQUIP_MAX   or rawget(GG, "TAB_W_UNEQUIP_MAX")   or _G.TAB_W_UNEQUIP_MAX   or {}
end

local function passOneValue(v, rawMin, rawMax)
    if v == nil then return true end

    local EPS = 1e-6
    local min = tonumber(rawMin or 0) or 0
    local max = tonumber(rawMax or 0) or 0

    if min ~= 0 then
        local limit = math.abs(min)
        if min > 0 then
            if v < limit - EPS then return false end
        else
            if v > limit + EPS then return false end
        end
    end

    if max ~= 0 then
        local limit = math.abs(max)
        if max > 0 then
            if v >= limit - EPS then return false end
        else
            if v <= limit + EPS then return false end
        end
    end

    return true
end

local function passTabRule(tabKey, age, w100)
    local AGE_EQUIP, AGE_UNEQUIP, W_EQUIP, W_UNEQUIP = getRuleTables()

    return passOneValue(age,  AGE_EQUIP[tabKey], AGE_UNEQUIP[tabKey])
       and passOneValue(w100, W_EQUIP[tabKey],   W_UNEQUIP[tabKey])
end

local function getMatchedMutations(info)
    local out, seen = {}, {}
    if type(info) ~= "table" then return out end

    local selected = rawget(G, "GBXP_MUT_SELECTED") or rawget(_G, "GBXP_MUT_SELECTED") or {}
    local selectedLC, hasSelected = {}, false

    if type(selected) == "table" then
        for name, on in pairs(selected) do
            if on then
                hasSelected = true
                selectedLC[tostring(name):lower()] = true
            end
        end
    end

    local function add(name)
        name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if name == "" or name == "-" then return end
        if hasSelected and not selectedLC[name:lower()] then return end

        if not seen[name] then
            seen[name] = true
            table.insert(out, name)
        end
    end

    if type(info.mutations) == "table" then
        for _, name in ipairs(info.mutations) do
            add(name)
        end
    end

    local m = tostring(info.mutText or info.mutation or "")
    if m ~= "" and m ~= "-" then
        for part in m:gmatch("[^,%+]+") do
            add(part)
        end
    end

    return out
end


local function getFinalLimits(mode)
    mode = tostring(mode or ""):upper()

    local AGE_EQUIP, AGE_UNEQUIP, W_EQUIP, W_UNEQUIP = getRuleTables()

    local ageLimit = 0
    local kgLimit = 0

    local function takeAge(tab)
        local v = tonumber(AGE_UNEQUIP[tab])
        if v and v > ageLimit then
            ageLimit = v
        end
    end

    local function takeKG(tab)
        local v = tonumber(W_EQUIP[tab]) or tonumber(W_UNEQUIP[tab])
        if v then
            v = math.abs(v)
            if v > kgLimit then
                kgLimit = v
            end
        end
    end

    -- 🔥 ambil berdasarkan MODE
    if mode:find("A") then takeAge("boost") end
    if mode:find("B") then takeAge("xp") end
    if mode:find("C") then takeKG("noos") end
    if mode:find("D") then takeAge("seratusage") end

    -- fallback aman
    if ageLimit <= 0 then ageLimit = 100 end
    if kgLimit <= 0 then kgLimit = 60.45 end

    return ageLimit, kgLimit
end

local function makeFinalLabel(mode)
    mode = tostring(mode or ""):upper()

    local ageLimit, kgLimit = getFinalLimits(mode)
    local parts = {}

    if mode == "A" then
        table.insert(parts, "Mutation Match")

    elseif mode == "B" then
        table.insert(parts, "Age ≥ " .. tostring(ageLimit))

    elseif mode == "C" then
        table.insert(parts, "KG ≥ " .. tostring(kgLimit))

    elseif mode == "D" then
        table.insert(parts, "Age ≥ " .. tostring(ageLimit))

    elseif mode == "BC" or mode == "CB" then
        table.insert(parts, "Age ≥ " .. tostring(ageLimit))
        table.insert(parts, "KG ≥ " .. tostring(kgLimit))

    elseif mode == "AD" or mode == "DA" then
        table.insert(parts, "Age ≥ " .. tostring(ageLimit))
        table.insert(parts, "Mutation Match")

    elseif mode == "CD" or mode == "DC" or mode == "CBD" then
        table.insert(parts, "Age ≥ " .. tostring(ageLimit))
        table.insert(parts, "KG ≥ " .. tostring(kgLimit))

    elseif mode == "CAD" or mode == "CDA" or mode == "ACBD" or mode == "AUTO" then
        table.insert(parts, "Age ≥ " .. tostring(ageLimit))
        table.insert(parts, "KG ≥ " .. tostring(kgLimit))
        table.insert(parts, "Mutation Match")
    end

    return table.concat(parts, " + ")
end

local function isModeFinalFinishValid(mode, data)
    mode = tostring(mode or ""):upper()

    local info = getEndInfo(data)
    local age = tonumber(info.age) or 0
    local w100 = tonumber(info.w100) or 0
    local muts = getMatchedMutations(info)
    local mutOK = #muts > 0

    local ageLimit, kgLimit = getFinalLimits(mode)

    local ageOK = ageLimit <= 0 or age >= ageLimit
    local kgOK = kgLimit <= 0 or w100 >= kgLimit

    if mode == "A" then
        return mutOK, makeFinalLabel(mode), muts

    elseif mode == "B" or mode == "D" then
        return ageOK, makeFinalLabel(mode), muts

    elseif mode == "C" then
        return kgOK, makeFinalLabel(mode), muts

    elseif mode == "BC" or mode == "CB" then
        return ageOK and kgOK, makeFinalLabel(mode), muts

    elseif mode == "AD" or mode == "DA" then
        return ageOK and mutOK, makeFinalLabel(mode), muts

    elseif mode == "CD" or mode == "DC" or mode == "CBD" then
        return ageOK and kgOK, makeFinalLabel(mode), muts

    elseif mode == "CAD" or mode == "CDA" or mode == "ACBD" or mode == "AUTO" then
        return ageOK and kgOK and mutOK, makeFinalLabel(mode), muts
    end

    return false, "", muts
end

local function addJobFinish(label, muts)
    label = tostring(label or "")
    if label == "" then return end

    RESULT.jobFinish = RESULT.jobFinish or {}
    RESULT.mutationFinish = RESULT.mutationFinish or {}

    local addCount = math.max(1, #(muts or {}))
    RESULT.jobFinish[label] = (tonumber(RESULT.jobFinish[label]) or 0) + addCount

    for _, mutName in ipairs(muts or {}) do
        RESULT.mutationFinish[mutName] = (tonumber(RESULT.mutationFinish[mutName]) or 0) + 1
    end
end




local function addResult(eventName, data)
    eventName = tostring(eventName or "UNKNOWN")
    data = type(data) == "table" and data or {}

    local stage = detectStage(data)
    local reason = detectReason(data)
    local mode = tostring(data.mode or ""):upper()
    local role = tostring(data.role or "")
    local durSec = detectDurationSec(data)
    stage = normStage(stage, role)

    local isStageEnd =
        reason == "stage_finished_or_removed"
        or tostring(reason):find("stage_changed", 1, true) ~= nil

    RESULT.total = tonumber(RESULT.total) or 0
    RESULT.total += 1

    RESULT.stageRun = RESULT.stageRun or {}
    RESULT.stageSec = RESULT.stageSec or {}
    RESULT.modeFinished = RESULT.modeFinished or {}
    RESULT.teamByStage = RESULT.teamByStage or {}

    -- hitung avg detik stage kalau event ini menutup / mengganti stage
    if stage ~= "" and isStageEnd then
        incMap(RESULT.stageRun, stage)

        if durSec > 0 then
            RESULT.stageSec[stage] = (tonumber(RESULT.stageSec[stage]) or 0) + durSec
        end
    end

    -- progress tetap hanya kalau benar-benar finish/remove
if reason == "stage_finished_or_removed" then
    local okFinish, label, muts = isModeFinalFinishValid(mode, data)

    if okFinish then
        addJobFinish(label, muts)
        incMap(RESULT.modeFinished, mode)
    else
        incMap(RESULT.modeFinished, mode .. "_NOT_FINAL_FINISH")
    end
end

    -- simpan team 1x saja per stage + role
    if stage ~= "" and role ~= "" then
        RESULT.teamByStage[stage] = RESULT.teamByStage[stage] or {}

        local simple = simplifyTeam(data.team)
        RESULT.teamByStage[stage][role] = simple[role] or {}
    end

    RESULT.updatedAt = os.time()
    RESULT.updatedAtText = formatTime(RESULT.updatedAt)


    saveResult()
end

local Dc = {}
Dc.AVATAR = "https://golaspay.net/assets/sc_logo.jpg"

function Dc.v(x, d)
    d = d or "-"
    if x == nil or x == "" then return d end
    if type(x) == "boolean" then return x and "ON" or "OFF" end
    return tostring(x)
end

function Dc.n(x, d)
    d = d or "-"
    if x == nil or x == "" then return d end
    local num = tonumber(x)
    if not num then return Dc.v(x, d) end
    local s = string.format("%.2f", num)
    s = s:gsub("0+$", ""):gsub("%.$", "")
    return s
end

function Dc.clip(s, limit)
    s = tostring(s or "")
    limit = tonumber(limit) or 3900
    if #s <= limit then return s end
    return s:sub(1, math.max(0, limit - 3)) .. "..."
end

function Dc.wrap(title, desc, color, fields, content, pingEveryone)
    local payload = {
        username = "Node Hub",
        avatar_url = Dc.AVATAR,
        embeds = {{
            title = tostring(title or "NodeHub"),
            description = desc,
            color = tonumber(color) or 0xF1C40F,
            footer = {
                text = "NodeHub AutoEle • " .. os.date("%d %b %Y | %H:%M"),
                icon_url = Dc.AVATAR,
            },
        }},
    }
    if type(fields) == "table" and #fields > 0 then
        payload.embeds[1].fields = fields
    end
    if pingEveryone == true then
        payload.content = "@everyone"
        payload.allowed_mentions = { parse = { "everyone" } }
    elseif content and content ~= "" then
        payload.content = content
    end
    return payload
end

function Dc.stageFinish(p)
    local d = type(p.data) == "table" and p.data or {}
    local player = Dc.v(p.player and p.player.name)
    local mode = string.upper(Dc.v(d.mode))
    local stage = string.upper(Dc.v(d.stage))
    local prio = string.upper(Dc.v(d.priority))
    local maxEq = Dc.v(d.gbxpMaxEquip)
    local reason = Dc.v(d.reasonEnd)
    local dur = Dc.v(d.durationText)
    local s = type(d.targetStart) == "table" and d.targetStart or {}
    local e = type(d.targetEnd) == "table" and d.targetEnd or {}
    local petName = Dc.v(s.petType or e.petType, "Unknown")
    local mut = Dc.v(e.mutText or s.mutText)
    local theme = ({
        A = { color = 0xF1C40F, icon = "🧬", label = "Mutation" },
        B = { color = 0xF1C40F, icon = "🌱", label = "Leveling" },
        C = { color = 0xF1C40F, icon = "⚖️", label = "Weight" },
        D = { color = 0xF1C40F, icon = "🏁", label = "Age 100" },
    })[stage] or { color = 0xF1C40F, icon = "⚡", label = "-" }

    local lines, i = {}, 1
    if type(d.team) == "table" then
        for _, pets in pairs(d.team) do
            if type(pets) == "table" then
                for _, pet in ipairs(pets) do
                    if type(pet) == "table" then
                        lines[#lines + 1] = "│ " .. tostring(i) .. ". "
                            .. Dc.v(pet.petType, "?")
                            .. " `" .. Dc.n(pet.kg) .. "kg`"
                        i += 1
                    end
                end
            end
        end
    end
    local teamText = (#lines > 0) and table.concat(lines, "\n") or "-"
    if #teamText > 1000 then
        teamText = teamText:sub(1, 990) .. "\n│ ..."
    end

    local endedTxt = Dc.v(d.endedAtText or p.tsText)
    if tonumber(d.endedAt) then
        endedTxt = os.date("%Y-%m-%d %H:%M:%S", math.floor(tonumber(d.endedAt)))
    end

    local fields = {
        {
            name = "Profile",
            value = "│ Username : **" .. player .. "**\n│ Priority : **" .. prio .. "**\n│ Target Max Equip : **" .. maxEq .. "**",
            inline = true,
        },
        {
            name = "Finish",
            value = "│ Duration : **" .. dur .. "**\n│ Reason : **" .. reason .. "**\n│ Time : **" .. endedTxt .. "**",
            inline = true,
        },
    }
    do
        local baku = type(d.baku) == "table" and d.baku or nil
        local has = baku and (baku.timeComboTxt or baku.timeGrowTxt or tonumber(baku.timeCombo))
        if has then
            fields[#fields + 1] = {
                name = "Baku Combo",
                value = "│ Grow : **" .. Dc.v(baku.timeGrowTxt, "-") .. "**\n"
                    .. "│ Bait : **" .. Dc.v(baku.timeBaitTxt, "-") .. "**\n"
                    .. "│ Spread : **" .. Dc.v(baku.timeSpreadTxt, "-") .. "**\n"
                    .. "│ Until min NM : **" .. Dc.v(baku.timeComboTxt, "-") .. "**\n"
                    .. "│ Ripe NM : **" .. Dc.v(baku.nightmareCount, "-") .. "** / **" .. Dc.v(baku.minNightmare, "-") .. "**",
                inline = false,
            }
        end
    end
    fields[#fields + 1] = {
        name = "Progress",
        value = "│ Start : Age **" .. Dc.n(s.age) .. "** | KG **" .. Dc.n(s.kg) .. "** | W100 **" .. Dc.n(s.w100) .. "**\n"
            .. "│ End : Age **" .. Dc.n(e.age) .. "** | KG **" .. Dc.n(e.kg) .. "** | W100 **" .. Dc.n(e.w100) .. "**",
        inline = false,
    }
    fields[#fields + 1] = {
        name = "Team",
        value = teamText,
        inline = false,
    }

    return Dc.wrap(
        theme.icon .. " NodeHub — Progress Finish",
        "**" .. petName .. "** • `" .. mut .. "`\n`" .. mode .. "` • Current Stage `" .. stage .. "` / " .. theme.label,
        theme.color,
        fields
    )
end

function Dc.serverInfo(si)
    if type(si) ~= "table" then return "-" end
    local playerCount = tonumber(si.playerCount) or 0
    local players = type(si.players) == "table" and si.players or {}
    local reasons = type(si.reasons) == "table" and si.reasons or {}
    local lines = { "Player Count: **" .. tostring(playerCount) .. "**" }
    if #reasons > 0 then
        local rs = {}
        for _, r in ipairs(reasons) do
            rs[#rs + 1] = tostring(r)
        end
        lines[#lines + 1] = "Reason: `" .. table.concat(rs, "`, `") .. "`"
    end
    if #players > 0 then
        lines[#lines + 1] = ""
        lines[#lines + 1] = "**Players**"
        for _, pl in ipairs(players) do
            if type(pl) == "table" then
                lines[#lines + 1] = "└ **" .. Dc.v(pl.displayName) .. "** • Pet **" .. Dc.v(pl.backpackPetCount, "?") .. "**"
            end
        end
    end
    return Dc.clip(table.concat(lines, "\n"), 1000)
end

function Dc.resultInfo(p)
    local d = type(p.data) == "table" and p.data or {}
    local s = type(d.autokgSnapshot) == "table" and d.autokgSnapshot or {}
    local player = Dc.v(p.player and p.player.name)
    local mode = string.upper(Dc.v(s.mode or p.mode))
    local dur = math.floor(tonumber(d.durationSec) or 0)
    local runtime = string.format("%02dh %02dm", math.floor(dur / 3600), math.floor((dur % 3600) / 60))
    local totalFinish = 0
    for _, count in pairs(type(d.jobFinish) == "table" and d.jobFinish or {}) do
        totalFinish += math.floor(tonumber(count) or 0)
    end
    local avgPetSec = (totalFinish > 0) and math.floor(dur / totalFinish) or 0
    local avgPetText = (avgPetSec > 0)
        and string.format("%02dm %02ds", math.floor(avgPetSec / 60), avgPetSec % 60)
        or "-"

    local stageLines = {}
    for _, st in ipairs({ "A", "B", "C", "D" }) do
        local run = math.floor(tonumber(d.stageRun and d.stageRun[st]) or 0)
        local avg = math.floor(tonumber(d.avgStageSeconds and d.avgStageSeconds[st]) or 0)
        local need = math.floor(tonumber(s.stageNeed and s.stageNeed[st]) or 0)
        if run > 0 or need > 0 then
            local targetEquip = math.floor(tonumber(d.stageTargetEquip and d.stageTargetEquip[st]) or 0)
            local targetText = (targetEquip > 0) and ("(Target " .. tostring(targetEquip) .. ")") or "Target Equip -"
            stageLines[#stageLines + 1] = "**Stage " .. st .. "** `" .. targetText .. "`\n└ Run **"
                .. tostring(run) .. "** • Avg **" .. tostring(avg) .. "s** • Queue **" .. tostring(need) .. "**"
        end
    end

    local teamLines = {}
    local team = type(d.teamByStage) == "table" and d.teamByStage or {}
    for stage, roles in pairs(team) do
        teamLines[#teamLines + 1] = "**Stage " .. tostring(stage) .. " Active**"
        local i = 1
        if type(roles) == "table" then
            for _, pets in pairs(roles) do
                if type(pets) == "table" then
                    for _, pet in ipairs(pets) do
                        if type(pet) == "table" then
                            teamLines[#teamLines + 1] = "└ " .. tostring(i) .. ". "
                                .. Dc.v(pet.petType, "?")
                                .. " • `" .. Dc.n(pet.kg) .. "kg`"
                            i += 1
                            if i > 10 then break end
                        end
                    end
                end
                if i > 10 then break end
            end
        end
    end

    local jobLines = {}
    local jobFinish = type(d.jobFinish) == "table" and d.jobFinish or {}
    local jobKeys = {}
    for k, count in pairs(jobFinish) do
        if (tonumber(count) or 0) > 0 then
            jobKeys[#jobKeys + 1] = { k = tostring(k), c = tonumber(count) or 0 }
        end
    end
    table.sort(jobKeys, function(a, b) return a.c > b.c end)
    for _, row in ipairs(jobKeys) do
        local label = row.k
        label = label:gsub("Age%s+([0-9.]+)", "Age ≥ %1")
        label = label:gsub("KG%s+([0-9.]+)", "KG ≥ %1")
        label = label:gsub(">=", "≥")
        jobLines[#jobLines + 1] = label .. ": **" .. tostring(row.c) .. "**"
    end

    local mutLines = {}
    local mutationFinish = type(d.mutationFinish) == "table" and d.mutationFinish or {}
    local mutKeys = {}
    for k, count in pairs(mutationFinish) do
        if (tonumber(count) or 0) > 0 then
            mutKeys[#mutKeys + 1] = { k = tostring(k), c = tonumber(count) or 0 }
        end
    end
    table.sort(mutKeys, function(a, b) return a.c > b.c end)
    for _, row in ipairs(mutKeys) do
        mutLines[#mutLines + 1] = Dc.v(row.k) .. ": **" .. tostring(row.c) .. "**"
    end

    local finishText = "\n\n✅ **Job Finish:**\n" .. ((#jobLines > 0) and table.concat(jobLines, "\n") or "0")
    if mode:find("A", 1, true) or mode == "AUTO" then
        finishText = finishText .. "\n\n🧬 **Mutation Finish:**\n"
            .. ((#mutLines > 0) and table.concat(mutLines, "\n") or "0")
    end

    local description =
        "👤 **" .. player .. "**\n⚙️ Mode: **" .. mode .. "**\n\n"
        .. "🕰️ Runtime: **" .. runtime .. "**\n"
        .. "⏱️ Avg/Pet: **" .. avgPetText .. "**\n"
        .. "📦 Total Pet: **" .. Dc.v(s.gbxpTotal, "0") .. "**"
        .. finishText .. "\n\n"
        .. "🧭 **Stage Performance**\n"
        .. ((#stageLines > 0) and table.concat(stageLines, "\n") or "-") .. "\n\n"
        .. "🐾 **Active Team**\n"
        .. Dc.clip((#teamLines > 0) and table.concat(teamLines, "\n") or "-", 3000) .. "\n\n"
        .. "🖥️ **Server Info**\n"
        .. Dc.serverInfo(d.serverInfo)

    local pingEveryone = (type(d.serverInfo) == "table" and d.serverInfo.ping == true)
    return Dc.wrap("Node Hub - 📊 AutoEle Result", Dc.clip(description, 3900), 0xF1C40F, nil, nil, pingEveryone)
end

function Dc.resultNeed(p)
    local d = type(p.data) == "table" and p.data or {}
    local s = type(d.autokgSnapshot) == "table" and d.autokgSnapshot or {}
    local need = type(s.needProcess) == "table" and s.needProcess or {}
    local rows, totalAll = {}, 0
    for pet, count in pairs(need) do
        local c = math.floor(tonumber(count) or 0)
        if c > 0 then
            rows[#rows + 1] = { pet = tostring(pet), c = c }
            totalAll += c
        end
    end
    table.sort(rows, function(a, b) return a.c > b.c end)
    local lines = { "📦 **Total Need Process:** " .. tostring(totalAll), "" }
    for i = 1, math.min(10, #rows) do
        lines[#lines + 1] = tostring(i) .. ". **" .. Dc.v(rows[i].pet) .. "** — Total **" .. tostring(rows[i].c) .. "**"
    end
    return Dc.wrap("📋 AutoEle • Need Process", (#lines > 2) and table.concat(lines, "\n") or "-", 0x3498DB)
end

function Dc.resultNot(p)
    local d = type(p.data) == "table" and p.data or {}
    local s = type(d.autokgSnapshot) == "table" and d.autokgSnapshot or {}
    local np = type(s.notProcess) == "table" and s.notProcess or {}
    if np.finished or np.noStage then
        local merged = {}
        for _, groupName in ipairs({ "finished", "noStage" }) do
            local group = np[groupName]
            if type(group) == "table" then
                for pet, kgMap in pairs(group) do
                    merged[pet] = merged[pet] or {}
                    if type(kgMap) == "table" then
                        for kg, ageMap in pairs(kgMap) do
                            merged[pet][kg] = merged[pet][kg] or {}
                            if type(ageMap) == "table" then
                                for age, count in pairs(ageMap) do
                                    merged[pet][kg][age] = (tonumber(merged[pet][kg][age]) or 0) + (tonumber(count) or 0)
                                end
                            end
                        end
                    end
                end
            end
        end
        np = merged
    end

    local bucketSize = 0.1
    local petRows, totalAll = {}, 0
    for pet, kgMap in pairs(np) do
        if type(kgMap) == "table" then
            local minKgPet = nil
            for kg, ageMap in pairs(kgMap) do
                if type(ageMap) == "table" then
                    for _, count in pairs(ageMap) do
                        if (tonumber(count) or 0) > 0 then
                            local kgNum = tonumber(kg)
                            if kgNum and (minKgPet == nil or kgNum < minKgPet) then
                                minKgPet = kgNum
                            end
                        end
                    end
                end
            end
            if minKgPet then
                for kg, ageMap in pairs(kgMap) do
                    if type(ageMap) == "table" then
                        local kgNum = tonumber(kg) or 0
                        local bucketIndex = math.floor(((kgNum - minKgPet) / bucketSize) + 0.000001)
                        if bucketIndex < 0 then bucketIndex = 0 end
                        local low = math.floor((minKgPet + bucketIndex * bucketSize) * 100 + 0.5) / 100
                        local high = math.floor((low + bucketSize) * 100 + 0.5) / 100
                        local key = string.format("%.2f|%.2f", low, high)
                        for age, count in pairs(ageMap) do
                            local c = math.floor(tonumber(count) or 0)
                            if c > 0 then
                                local ageNum = math.floor(tonumber(age) or 0)
                                totalAll += c
                                petRows[pet] = petRows[pet] or { pet = Dc.v(pet), total = 0, buckets = {} }
                                petRows[pet].total += c
                                local b = petRows[pet].buckets[key]
                                if not b then
                                    b = { low = low, high = high, total = 0, minAge = nil, maxAge = nil }
                                    petRows[pet].buckets[key] = b
                                end
                                b.total += c
                                if b.minAge == nil or ageNum < b.minAge then b.minAge = ageNum end
                                if b.maxAge == nil or ageNum > b.maxAge then b.maxAge = ageNum end
                            end
                        end
                    end
                end
            end
        end
    end

    local rows = {}
    for _, row in pairs(petRows) do
        rows[#rows + 1] = row
    end
    table.sort(rows, function(a, b)
        if a.total == b.total then return tostring(a.pet) < tostring(b.pet) end
        return a.total > b.total
    end)

    local lines = { "📦 **Total :** **" .. tostring(totalAll) .. "**", "" }
    for i = 1, math.min(20, #rows) do
        local row = rows[i]
        lines[#lines + 1] = "**" .. Dc.v(row.pet) .. "** — Total **" .. tostring(row.total) .. "**"
        local buckets = {}
        for _, b in pairs(row.buckets or {}) do
            buckets[#buckets + 1] = b
        end
        table.sort(buckets, function(a, b) return a.low < b.low end)
        for _, b in ipairs(buckets) do
            local kgText = Dc.n(b.low) .. "–" .. Dc.n(b.high) .. "kg"
            local ageText = "-"
            if b.minAge ~= nil and b.maxAge ~= nil then
                ageText = (b.minAge == b.maxAge) and tostring(b.minAge) or (tostring(b.minAge) .. "–" .. tostring(b.maxAge))
            end
            lines[#lines + 1] = "└ `KG " .. kgText .. " • Age " .. ageText .. "` (" .. tostring(b.total) .. ")"
        end
        lines[#lines + 1] = ""
    end
    if #rows == 0 then
        lines[#lines + 1] = "-"
    end
    return Dc.wrap("📌 AutoEle • Not Process / Finish", Dc.clip(table.concat(lines, "\n"), 3900), 0x2ECC71)
end

function Dc.machineClaim(p)
    local d = type(p.data) == "table" and p.data or {}
    local player = Dc.v(p.player and p.player.name, "Unknown")
    local mode = string.upper(tostring(p.mode or d.mode or "FULL"))
    local match = (d.matchSelectedMut == true)
    local added = d.addedMutations or d.added or {}
    local color = 0x64748B
    if match then
        color = 0xA855F7
    elseif type(added) == "table" and #added > 0 then
        color = 0x22C55E
    end
    local function muts(list)
        if type(list) ~= "table" then return "-" end
        local clean = {}
        if #list > 0 then
            for _, m in ipairs(list) do
                local s = tostring(m or ""):gsub("^%s+", ""):gsub("%s+$", "")
                if s ~= "" then
                    clean[#clean + 1] = s
                    if #clean >= 12 then break end
                end
            end
        else
            for k, on in pairs(list) do
                if on == true then
                    local s = tostring(k or ""):gsub("^%s+", ""):gsub("%s+$", "")
                    if s ~= "" then
                        clean[#clean + 1] = s
                        if #clean >= 12 then break end
                    end
                end
            end
        end
        return (#clean > 0) and table.concat(clean, ", ") or "-"
    end
    local kgTxt = (tonumber(d.kg) ~= nil) and string.format("%.2f KG", tonumber(d.kg)) or "-"
    local ageTxt = tonumber(d.age) and tostring(math.floor(tonumber(d.age))) or "-"
    local tsUnix = tonumber(d.tsUnix) or os.time()
    local desc = "🧾 **Profile**\n│ Username : " .. player
        .. "\n│ Time : " .. os.date("%d %b %Y | %H:%M:%S", tsUnix) .. "\n\n"
        .. "🔮 **Pet** " .. Dc.v(d.petType, "Pet")
        .. "\n│ Age : " .. ageTxt
        .. "\n│ KG : " .. kgTxt
        .. "\n│ Before : " .. muts(d.beforeMutations or d.before)
        .. "\n│ After : " .. muts(d.afterMutations or d.after)
        .. "\n│ Added : " .. muts(added)
        .. "\n│ Match Selected : " .. (match and "YES" or "NO")
    if mode == "FULL" and tostring(d.uuid or "") ~= "" then
        desc = desc .. "\n│ UUID : `" .. tostring(d.uuid) .. "`"
    end
    local title = match and "NodeHub — Mutation Machine (HIT)" or "NodeHub — Mutation Machine Claim"
    local payload = {
        username = player:sub(1, 80),
        avatar_url = Dc.AVATAR,
        embeds = {{
            title = title,
            description = desc,
            color = color,
            timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ", tsUnix),
            footer = { text = "Node Hub Auto KG", icon_url = Dc.AVATAR },
        }},
    }
    if match then
        payload.content = "@everyone"
        payload.allowed_mentions = { parse = { "everyone" } }
    end
    return payload
end

function Dc.generic(p)
    local raw = ""
    pcall(function()
        raw = HttpService:JSONEncode(p.data or {})
    end)
    if #raw > 1500 then raw = raw:sub(1, 1500) .. "…" end
    return Dc.wrap(
        "📩 " .. tostring(p.event or "UNKNOWN"),
        "```json\n" .. raw .. "\n```",
        0x95A5A6
    )
end

function Dc.build(eventName, p)
    eventName = string.upper(tostring(eventName or "UNKNOWN"))
    p = type(p) == "table" and p or {}
    p.event = eventName
    if eventName == "AUTOKG_STAGE_FINISH" then
        return { Dc.stageFinish(p) }
    elseif eventName == "WEBHOOK_RESULT" then
        return { Dc.resultInfo(p), Dc.resultNeed(p), Dc.resultNot(p) }
    elseif eventName == "MACHINE_MUTATE_CLAIM" then
        return { Dc.machineClaim(p) }
    elseif eventName == "TEST" then
        return { Dc.wrap("Webhook test", Dc.v(p.data and p.data.message, "Webhook test from NodeHub"), 0x3498DB) }
    end
    return { Dc.generic(p) }
end

local function sendRaw(eventName, data)
    local cfg = getWebhookState()
    eventName = tostring(eventName or "UNKNOWN")

    if eventName == "WEBHOOK_RESULT" then
        if cfg.resultEnabled ~= true then
            return false, "result_disabled"
        end
    else
        if cfg.enabled ~= true then
            return false, "disabled"
        end
    end

    local target = tostring(cfg.targetWebhook or cfg.url or "")
    target = target:gsub("^%s+", ""):gsub("%s+$", "")
    if target == "" then
        return false, "empty_discord_webhook"
    end

    local nowClock = os.clock()
    if nowClock - LAST_SEND < MIN_DELAY then
        task.wait(MIN_DELAY - (nowClock - LAST_SEND))
    end

    local envelope = basePayload(eventName, data)
    envelope.webhook = {
        target = target,
        source = "autokg",
    }

    local payloads = Dc.build(eventName, envelope)
    if type(payloads) ~= "table" or #payloads == 0 then
        return false, "empty_payload"
    end

    local okAll, lastRes = true, nil
    for i, payload in ipairs(payloads) do
        if i > 1 then
            task.wait(0.7)
        end
        LAST_SEND = os.clock()
        local okJson, json = pcall(function()
            return HttpService:JSONEncode(payload)
        end)
        if not okJson then
            return false, "json_encode_failed"
        end
        local ok, res = httpPost(target, json)
        lastRes = res
        if not ok then
            okAll = false
        end
    end
    return okAll, lastRes
end

local HATCH_EVENTS = {
    CYCLE_FINISH = true,
    AUTO_START = true,
    DISCONNECT = true,
    NMLVL_GBXP_START = true,
    NMLVL_GBXP_CYCLE = true,
}

local function isHatchWebhook(wh)
    if type(wh) ~= "table" or wh == M then
        return false
    end
    if wh.__source == "autokg" or wh.__source == "webhook-dispatch" then
        return false
    end
    return type(wh.HookDisconnectWatcher) == "function"
        or type(wh.StartDefault) == "function"
        or type(wh.Init) == "function"
end

local function adoptHatchWebhook(wh)
    if not isHatchWebhook(wh) then
        if type(wh) == "table" and wh.__source == "webhook-dispatch" then
            adoptHatchWebhook(wh._foreignWebhook)
        end
        return
    end
    M._foreignWebhook = wh
    _G.AutoHatchWebhook = wh
    G.AutoHatchWebhook = wh
end

local function getHatchWebhook()
    local h = M._foreignWebhook
        or rawget(_G, "AutoHatchWebhook")
        or rawget(G, "AutoHatchWebhook")
    if isHatchWebhook(h) then
        return h
    end
    return nil
end

local function isHatchEvent(eventName)
    return HATCH_EVENTS[string.upper(tostring(eventName or ""))] == true
end

local function forwardHatch(eventName, data, opts, wbConfig)
    local h = getHatchWebhook()
    if not h then
        return false, "hatch_webhook_missing"
    end
    if wbConfig ~= nil and type(h.SendWith) == "function" then
        return h.SendWith(wbConfig, eventName, data, opts)
    end
    if type(h.Send) == "function" then
        return h.Send(eventName, data, opts)
    end
    return false, "hatch_webhook_missing"
end

function M.Send(eventName, data, opts)
    if isHatchEvent(eventName) then
        return forwardHatch(eventName, data, opts, nil)
    end
    addResult(eventName, data)
    return sendRaw(eventName, data)
end

function M.SendWith(wbConfig, eventName, data, opts)
    if isHatchEvent(eventName) then
        return forwardHatch(eventName, data, opts, wbConfig)
    end
    local wb = type(wbConfig) == "table" and wbConfig or {}
    if wb.enabled == false then
        return false, "disabled"
    end
    return M.Send(eventName, data, opts)
end

function M.SendResult(reason)
    local cfg = getWebhookState()

    if cfg.resultEnabled ~= true then
        return false, "result_disabled"
    end

    local now = os.time()

local autokgSnapshot = nil
pcall(function()
    local L = rawget(G, "AutoKGLoop") or rawget(_G, "AutoKGLoop")
    if L and type(L.GetResultSnapshot) == "function" then
        autokgSnapshot = L.GetResultSnapshot()
    end
end)

local avgStageSeconds = {}

for stage, runCount in pairs(RESULT.stageRun or {}) do
    local totalSec = tonumber((RESULT.stageSec or {})[stage]) or 0
    local count = tonumber(runCount) or 0

    if count > 0 then
        avgStageSeconds[stage] = math.floor(totalSec / count)
    else
        avgStageSeconds[stage] = 0
    end
end

local playersInfo = getCurrentPlayersInfo(cfg)

local ping = {
    playerLow = false,
    backpackLow = false,
    shouldPing = false,
    reasons = {},
}

if cfg.pingPlayerEnabled == true and playersInfo.count < cfg.pingPlayerBelow then
    ping.playerLow = true
    ping.shouldPing = true
    table.insert(ping.reasons, "PLAYER_BELOW")
end

if cfg.pingBackpackEnabled == true and #playersInfo.lowBackpackPlayers > 0 then
    ping.backpackLow = true
    ping.shouldPing = true
    table.insert(ping.reasons, "BACKPACK_PLAYER_BELOW")
end

    local resultPayload = {
    reason = tostring(reason or "manual"),

    startedAt = RESULT.startedAt,
    startedAtText = RESULT.startedAtText,

    lastReset = RESULT.lastReset,
    lastResetText = RESULT.lastResetText,

    sentAt = now,
    sentAtText = formatTime(now),
    stageTargetEquip = getStageTargetEquip(),

    durationSec = now - (tonumber(RESULT.lastReset) or tonumber(RESULT.startedAt) or now),
    total = tonumber(RESULT.total) or 0,

    stageRun = RESULT.stageRun or {},
    stageSec = RESULT.stageSec or {},
    avgStageSeconds = avgStageSeconds,

    teamByStage = RESULT.teamByStage or {},
    
    autokgSnapshot = autokgSnapshot,
    jobFinish = RESULT.jobFinish or {},
    mutationFinish = RESULT.mutationFinish or {},

    avgPerMinute = math.floor((tonumber(RESULT.total) or 0) / math.max(1, (now - (tonumber(RESULT.lastReset) or now)) / 60)),

    config = {
        resultEnabled = cfg.resultEnabled,
        resetHours = cfg.resultResetHours,
        sendHours = cfg.resultSendHours,
    },

serverInfo = {
    ping = ping.shouldPing,
    backpackLow = ping.backpackLow,
    reasons = ping.reasons,

    playerCount = playersInfo.count,
    players = playersInfo.players,
},

    
}

    local ok, res = sendRaw("WEBHOOK_RESULT", resultPayload)

    if ok then
        RESULT.lastSend = now
        RESULT.lastSendText = formatTime(now)
        saveResult()
    end

    return ok, res
end

function M.ResetResult(reason)
    local now = os.time()

RESULT = {
