    startedAt = now,
    startedAtText = formatTime(now),

    lastReset = now,
    lastResetText = formatTime(now),

    lastSend = RESULT.lastSend or 0,
    lastSendText = RESULT.lastSendText or "",

    resetReason = tostring(reason or "manual"),

    updatedAt = now,
    updatedAtText = formatTime(now),
