function M.GetResultFile()
    return RESULT_FILE
end

function M.StartResultLoop()
    if LOOP_RUNNING then
        return false, "already_running"
    end

    LOOP_RUNNING = true

    task.spawn(function()
        while LOOP_RUNNING do
            local cfg = getWebhookState()
            local now = os.time()

            if cfg.resultEnabled == true then
                local sendEverySec = clampNumber(cfg.resultSendHours, 1, 600, 1) * 60
                local resetEverySec = clampNumber(cfg.resultResetHours, 1, 72, 24) * 3600

                if tonumber(RESULT.lastSend or 0) <= 0 then
                    RESULT.lastSend = now
                    RESULT.lastSendText = formatTime(now)
                    saveResult()
                end

                if now - (tonumber(RESULT.lastSend) or now) >= sendEverySec then
                    pcall(function()
                        M.SendResult("interval")
                    end)
                end

                if now - (tonumber(RESULT.lastReset) or now) >= resetEverySec then
                    pcall(function()
                        M.SendResult("before_reset")
                    end)

                    M.ResetResult("interval_reset")
                end
            end

            task.wait(30)
        end
    end)

    return true
end

function M.DebugState()
    local cfg = getWebhookState()
    return {
        webhookEnabled = cfg.enabled,
        url = cfg.url,
        resultEnabled = cfg.resultEnabled,
        resultResetHours = cfg.resultResetHours,
        resultSendHours = cfg.resultSendHours,
        loopRunning = LOOP_RUNNING,
        resultFile = RESULT_FILE,
        total = RESULT.total,
    }
end

function M.IsResultLoopRunning()
    return LOOP_RUNNING == true
end

function M.StopResultLoop()
    LOOP_RUNNING = false
    return true
end

