end

local function fmtPos(v)
    if not v then return "nil" end
    return string.format("%.2f, %.2f, %.2f", v.X, v.Y, v.Z)
end

local function getAttrsText(obj)
    local names = {
        "Lifetime",
        "TimeLeft",
        "Duration",
        "EndTime",
        "ExpiresAt",
        "Active",
        "IsActive",
        "Enabled",
        "ItemName",
        "OBJECT_TYPE",
        "ItemType",
        "Type",
    }

    local out = {}

    for _, name in ipairs(names) do
        local v = obj:GetAttribute(name)
        if v ~= nil then
            table.insert(out, name .. "=" .. tostring(v))
        end
    end

    return table.concat(out, ", ")
end

local function normMode(mode)
    mode = tostring(mode or "self"):lower()
    if mode ~= "other" then
        mode = "self"
    end
    return mode
end

local function getProfile(mode)
    mode = normMode(mode)
    return PROFILES[mode], mode
end

local function normUUID(u)
    if not u or u == "" then return nil end
    return tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
end

