-- FARM
----------------------------------------------------------------

local function farmOwnerMatch(farm, targetUserId, targetName)
    if not farm then return false end

    targetUserId = targetUserId and tostring(targetUserId) or nil
    targetName = targetName and tostring(targetName) or nil

    local important = farm:FindFirstChild("Important")
    local data = important and important:FindFirstChild("Data")
    local owner = data and data:FindFirstChild("Owner")

    if owner then
        local v = tostring(owner.Value or "")

        if targetUserId and v == targetUserId then
            return true
        end

        if targetName and v == targetName then
            return true
        end

        local plr = Players:FindFirstChild(v)
        if plr and targetUserId and tostring(plr.UserId) == targetUserId then
            return true
        end
    end

    local attrOwner =
        farm:GetAttribute("Owner")
        or farm:GetAttribute("OwnerName")
        or farm:GetAttribute("UserId")
        or farm:GetAttribute("OwnerId")

    if attrOwner then
        local v = tostring(attrOwner)

        if targetUserId and v == targetUserId then
            return true
        end

        if targetName and v == targetName then
            return true
        end

        local plr = Players:FindFirstChild(v)
        if plr and targetUserId and tostring(plr.UserId) == targetUserId then
            return true
        end
    end

    return false
end

local function getFarmByOwner(targetUserId, targetName)
    local farmRoot = workspace:FindFirstChild("Farm")
    if not farmRoot then return nil end

    targetUserId = targetUserId and tostring(targetUserId) or nil
    targetName = targetName and tostring(targetName) or nil

    for i, farm in ipairs(farmRoot:GetChildren()) do
        local important = farm:FindFirstChild("Important")
        local data = important and important:FindFirstChild("Data")
        local owner = data and data:FindFirstChild("Owner")
        local ownerValue = owner and tostring(owner.Value or "") or ""

        d("scan farm:", i, farm:GetFullName(), "owner:", ownerValue)

        if ownerValue ~= "" then
            if ownerValue == targetName or ownerValue == targetUserId then
                return farm
            end

            local plr = Players:FindFirstChild(ownerValue)
            if plr and targetUserId and tostring(plr.UserId) == targetUserId then
                return farm
            end
        end

        if farmOwnerMatch(farm, targetUserId, targetName) then
            return farm
        end
    end

    return nil
end

local function getMyFarm()
    return getFarmByOwner(LP.UserId, LP.Name)
end

local function getFirstSelectedTarget()
    local targetMap = G.AUTO_SPRINKLER_OTHER_TARGET or {}

    for key, on in pairs(targetMap) do
        if on == true then
            local uid = tonumber(key)
            local name = nil

            local plr = uid and Players:GetPlayerByUserId(uid)
            if plr then
                name = plr.Name
            else
                name = tostring(key)
            end

            return tostring(key), name
        end
    end

    return nil, nil
end

local function getOtherFarm()
    local targetUserId, targetName = getFirstSelectedTarget()

    if not targetUserId and not targetName then
        return nil
    end

    return getFarmByOwner(targetUserId, targetName)
end

local function getFarmForMode(mode)
    mode = normMode(mode)

    if mode == "other" then
        return getOtherFarm()
    end

    return getMyFarm()
end

local function getFarmCF(farm)
    if not farm then return nil end

    if farm:IsA("Model") then
        return farm:GetPivot()
    end

    local preferredNames = {
        "Center_Point",
        "CenterPoint",
        "Spawn_Point",
        "SpawnPoint",
        "FarmSpawn",
        "Base",
        "Baseplate",
        "Ground",
    }

    for _, name in ipairs(preferredNames) do
        local obj = farm:FindFirstChild(name, true)
        if obj and obj:IsA("BasePart") then
            return obj.CFrame
        end
    end

    local sum = Vector3.zero
    local count = 0

    for _, obj in ipairs(farm:GetDescendants()) do
        if obj:IsA("BasePart") then
            sum += obj.Position
            count += 1
        end
    end

    if count > 0 then
        return CFrame.new(sum / count)
    end

    return nil
end

local function getObjectsPhysical(mode)
    local farm = getFarmForMode(mode)
    if not farm then
        return nil
    end

    local important = farm:FindFirstChild("Important")
    return important and important:FindFirstChild("Objects_Physical")
end

----------------------------------------------------------------
-- SPRINKLER OBJECT CHECK
----------------------------------------------------------------

local function isSprinklerObject(obj)
    if not obj then return false end

    local name = tostring(obj.Name or ""):lower()
    local objectType = tostring(obj:GetAttribute("OBJECT_TYPE") or ""):lower()
    local itemType = tostring(obj:GetAttribute("ItemType") or ""):lower()
    local typeAttr = tostring(obj:GetAttribute("Type") or ""):lower()

    return name:find("sprinkler", 1, true)
        or objectType:find("sprinkler", 1, true)
        or itemType:find("sprinkler", 1, true)
        or typeAttr:find("sprinkler", 1, true)
end

local function isActiveSprinklerObject(obj)
    if not isSprinklerObject(obj) then
        return false
    end

    local lifetime =
        tonumber(obj:GetAttribute("Lifetime"))
        or tonumber(obj:GetAttribute("TimeLeft"))
        or tonumber(obj:GetAttribute("Duration"))
        or tonumber(obj:GetAttribute("EndTime"))
        or tonumber(obj:GetAttribute("ExpiresAt"))

    if lifetime then
        if lifetime <= 0 then
            return false
        end

        local now = workspace:GetServerTimeNow()

        if lifetime > 100000 and lifetime <= now then
            return false
        end

        return true
    end

    local active =
        obj:GetAttribute("Active")
        or obj:GetAttribute("IsActive")
        or obj:GetAttribute("Enabled")

    if active ~= nil then
        return active == true
    end

    return true
end

local function getObjPos(obj)
    if not obj then return nil end

    local anchor =
        obj:FindFirstChild("SprinklerAnchor", true)

    if anchor and anchor:IsA("BasePart") then
        return anchor.Position
    end

    if obj:IsA("Model") then
        local ok, cf = pcall(function()
            return obj:GetPivot()
        end)

        if ok and cf then
            return cf.Position
        end
    end

    if obj:IsA("BasePart") then
        return obj.Position
    end

    local part =
        obj:FindFirstChildWhichIsA("BasePart", true)

    return part and part.Position or nil
end

local function cleanSprinklerName(s)
    s = tostring(s or ""):lower()
    s = s:gsub("%b[]", "")
    s = s:gsub("%b()", "")
    s = s:gsub("%s+", " ")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")
    return s
end

local function getSprinklerKindFromName(name)
    name = cleanSprinklerName(name)
    local kind = name:match("^(.-%s+sprinkler)")
    return kind or name
end

local function getObjSprinklerKind(obj)
    if not obj then return "" end

    return getSprinklerKindFromName(
        obj:GetAttribute("ItemName")
        or obj:GetAttribute("Name")
        or obj.Name
    )
end

local function getToolSprinklerKind(tool)
    if not tool then return "" end

    return getSprinklerKindFromName(
        tool:GetAttribute("ItemName")
        or tool.Name
    )
end

function M.HasActiveSprinkler(mode)
    syncGlobals()
    mode = normMode(mode)

    local objects = getObjectsPhysical(mode)
    if not objects then
        d("Objects_Physical not found:", mode)
        return false
    end

    for _, obj in ipairs(objects:GetChildren()) do
        if isActiveSprinklerObject(obj) then
            d("active sprinkler found:", mode, obj:GetFullName())
            return true, obj
        end
    end

    return false
end

local function getObjectsPhysicalForLoc(mode, loc)
    mode = normMode(mode)

    if mode == "other" then
        if not loc or not loc.targetUserId or loc.targetUserId == "" then
            return nil
        end

        local farm = getFarmByOwner(loc.targetUserId, nil)
        local important = farm and farm:FindFirstChild("Important")
        return important and important:FindFirstChild("Objects_Physical")
    end

    return getObjectsPhysical(mode)
end

local function distXZ(a, b)
    local dx = a.X - b.X
    local dz = a.Z - b.Z
    return math.sqrt(dx * dx + dz * dz)
end

local function hasActiveSprinklerKindInObjects(objects, pos, wantedKind)
    if not objects or not pos then
        d("ACTIVE SCAN FAIL: objects/pos nil", tostring(objects), tostring(pos))
        return false
    end

    wantedKind = cleanSprinklerName(wantedKind)

    if M.DEBUG_ACTIVE_SCAN then
        print("========== SPRINKLER ACTIVE SCAN ==========")
        print("objects:", objects:GetFullName())
        print("wantedKind:", wantedKind)
        print("targetPos:", fmtPos(pos))
        print("radius:", M.SPRINKLER_DETECT_RADIUS)
        print("children:", #objects:GetChildren())
    end

    local foundSprinkler = 0

    for _, obj in ipairs(objects:GetChildren()) do
        if isSprinklerObject(obj) then
            foundSprinkler += 1

            local active = isActiveSprinklerObject(obj)
            local objKind = getObjSprinklerKind(obj)
            local objPos = getObjPos(obj)
            local dXZ = objPos and distXZ(objPos, pos) or 999999

            if M.DEBUG_ACTIVE_SCAN then
                print("[SCAN OBJ]", foundSprinkler)
                print(" name:", obj.Name)
                print(" path:", obj:GetFullName())
                print(" objKind:", objKind)
                print(" active:", active)
                print(" objPos:", fmtPos(objPos))
                print(" distXZ:", math.floor(dXZ * 100) / 100)
                print(" attrs:", getAttrsText(obj))
                print(" kindMatch:", objKind == wantedKind)
                print(" radiusMatch:", dXZ <= M.SPRINKLER_DETECT_RADIUS)
            end

            if active and objPos and objKind == wantedKind and dXZ <= M.SPRINKLER_DETECT_RADIUS then
                --print("[AutoSprinkler] FOUND ACTIVE:", objKind, "distXZ:", dXZ)
                return true, obj
            end
        end
    end

    if M.DEBUG_ACTIVE_SCAN then
        print("NO ACTIVE MATCH. sprinklerFound:", foundSprinkler)
        print("==========================================")
    end

    return false
end

function M.HasActiveSprinklerKindAt(mode, pos, wantedKind)
    syncGlobals()
    mode = normMode(mode)

    local objects = getObjectsPhysical(mode)
    if not objects or not pos then
        return false
    end

    wantedKind = cleanSprinklerName(wantedKind)

    for _, obj in ipairs(objects:GetChildren()) do
        if isActiveSprinklerObject(obj) then
            local objKind = getObjSprinklerKind(obj)
            local objPos = getObjPos(obj)

            if objPos
                and objKind == wantedKind
                and (objPos - pos).Magnitude <= M.SPRINKLER_DETECT_RADIUS
            then
                d("skip active:", mode, objKind, "dist:", math.floor((objPos - pos).Magnitude))
                return true, obj
            end
        end
    end

    return false
end

function M.HasActiveSprinklerAt(mode, pos)
    syncGlobals()
    mode = normMode(mode)

    local objects = getObjectsPhysical(mode)
    if not objects or not pos then
        return false
    end

    for _, obj in ipairs(objects:GetChildren()) do
        if isActiveSprinklerObject(obj) then
            local objPos = getObjPos(obj)

            if objPos and (objPos - pos).Magnitude <= M.SPRINKLER_DETECT_RADIUS then
                return true, obj
            end
        end
    end

    return false
end

