local function tableToCF(t)
    if type(t) ~= "table" then return nil end
    if #t < 12 then return nil end

    local nums = {}

    for i = 1, 12 do
        nums[i] = tonumber(t[i])
        if nums[i] == nil then
            return nil
        end
    end

    return CFrame.new(table.unpack(nums))
end

