    local selected = getProfileValue(profile, "positionSelectedKey") or {}

    local out = {}

    for _, p in ipairs(positions) do
        if type(p) == "table" then
            local key = tostring(p.key or "")

            if key ~= "" and selected[key] == true then
                local cf

                -- OTHER: pakai world position langsung seperti kode test
                if mode == "other" and p.x and p.y and p.z then
                    cf = CFrame.new(
                        tonumber(p.x),
                        tonumber(p.y),
                        tonumber(p.z)
                    )
                end

                -- SELF / fallback relative
                if not cf and farmCF and type(p.rel) == "table" then
                    local relCF = tableToCF(p.rel)
                    if relCF then
                        cf = farmCF:ToWorldSpace(relCF)
                    end
                end

                if not cf and farmCF and p.rx and p.ry and p.rz then
                    cf = farmCF:ToWorldSpace(CFrame.new(
                        tonumber(p.rx),
                        tonumber(p.ry),
                        tonumber(p.rz)
                    ))
                end

                if not cf and p.x and p.y and p.z then
                    cf = CFrame.new(
                        tonumber(p.x),
                        tonumber(p.y),
                        tonumber(p.z)
                    )
                end

                if cf then
local targetUserId = nil

if mode == "other" then
    if type(p.key) == "string" then
        targetUserId = p.key:match("^(%d+)|")
    end

    if not targetUserId or targetUserId == "" then
        targetUserId = p.targetUserId
    end

    if not targetUserId or targetUserId == "" then
        w("other position missing targetUserId, skip:", key)
        continue
    end
else
    targetUserId = p.targetUserId
end

    d(mode, "use pos:", key, "target:", tostring(targetUserId), cf.Position)

    table.insert(out, {
        key = key,
        targetUserId = targetUserId,
        pos = cf.Position,
        cf = cf,
    })
end
            end
        end
    end

    return out
end

