local function getToolUUID(tool)
    if not tool then return nil end

    return tool:GetAttribute("c")
        or tool:GetAttribute("C")
        or tool:GetAttribute("UUID")
        or tool:GetAttribute("uuid")
        or tool:GetAttribute("ITEM_UUID")
        or tool:GetAttribute("ItemUUID")
        or tool:GetAttribute("Item_UUID")
end

local function isSprinklerTool(tool)
    if not tool or not tool:IsA("Tool") then return false end

    local name = tostring(tool.Name or ""):lower()
    local itemType = tostring(tool:GetAttribute("ItemType") or ""):lower()
    local typeAttr = tostring(tool:GetAttribute("Type") or ""):lower()
    local objectType = tostring(tool:GetAttribute("OBJECT_TYPE") or ""):lower()
    local itemName = tostring(tool:GetAttribute("ItemName") or ""):lower()

    return name:find("sprinkler", 1, true)
        or itemName:find("sprinkler", 1, true)
        or itemType:find("sprinkler", 1, true)
        or typeAttr:find("sprinkler", 1, true)
        or objectType:find("sprinkler", 1, true)
end

local function getSelectedSprinklers(mode)
    syncGlobals()

    local profile = getProfile(mode)
    local selected = getProfileValue(profile, "selectedKey") or {}

local out = {}
local seenKind = {}

    local containers = {
        LP:FindFirstChild("Backpack"),
        LP.Character,
    }

    for _, container in ipairs(containers) do
        if container then
            for _, tool in ipairs(container:GetChildren()) do
                if isSprinklerTool(tool) then
                    local uuid = getToolUUID(tool)
                    local core = normUUID(uuid)

                    local okSelected =
                        (core and isSelected(selected, core))
                        or isSelected(selected, tool.Name)

                    if okSelected then
    local kind = getToolSprinklerKind(tool)

    if kind ~= "" and not seenKind[kind] then
        seenKind[kind] = true

        table.insert(out, {
            uuid = core or tool.Name,
            tool = tool,
            itemName = tool.Name,
            kind = kind,
        })
    end
end
                end
            end
        end
    end

    return out
end

local function equipTool(tool)
    if not tool then return false end

    local char = getChar()
    local hum = char and char:FindFirstChildOfClass("Humanoid")

    if tool.Parent == char then
        return true
    end

    if hum then
        pcall(function()
            hum:EquipTool(tool)
        end)

        task.wait(0.15)
    end

    if tool.Parent ~= char then
        pcall(function()
            tool.Parent = char
        end)

        task.wait(0.15)
    end

    return tool.Parent == char
end

local function unequipTool(tool)
    if not tool then return end

    local char = getChar()
    if not char then return end

    if tool.Parent == char then
        local backpack = LP:FindFirstChild("Backpack")

        pcall(function()
            tool.Parent = backpack
        end)

        task.wait(0.1)
    end
end

local function moveNear(pos)
    if M.TELEPORT_NEAR_POSITION ~= true then
        return
    end

    local hrp = getHRP()
    if not hrp then return end

    if (hrp.Position - pos).Magnitude > M.MAX_DISTANCE then
        hrp.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0))
        task.wait(0.2)
    end
end

