----------------------------------------------------------------
-- START / STOP
----------------------------------------------------------------

function M.Start(mode)
    syncGlobals()

    local profile
    profile, mode = getProfile(mode)

    if running[mode] then
        return
    end

    if G[profile.enabledKey] ~= true then
        d("Start ignored, enabled false:", mode)
        return
    end

    running[mode] = true
    loopToken[mode] += 1

    local myToken = loopToken[mode]

    d("started:", mode)

    task.spawn(function()
        while running[mode] and loopToken[mode] == myToken do
            syncGlobals()

            if G[profile.enabledKey] ~= true then
                running[mode] = false
                break
            end

            local ok, a, b = pcall(function()
                return M.PlaceOnce(mode)
            end)

            if not ok then
                w("PlaceOnce error:", mode, a)
            else
                d("PlaceOnce result:", mode, a, b)
            end

            task.wait(M.CYCLE_DELAY)
        end

        if loopToken[mode] == myToken then
            running[mode] = false
        end

        d("loop ended:", mode)
    end)
end

function M.Stop(reason, mode)
    mode = normMode(mode)

    loopToken[mode] += 1
    running[mode] = false

    --d("stopped:", mode, tostring(reason or "manual"))
end

function M.SetEnabled(on, mode)
    syncGlobals()

    local profile
    profile, mode = getProfile(mode)

    setProfileEnabled(profile, on == true)

    if G[profile.enabledKey] == true then
        M.Start(mode)
    else
        M.Stop("disabled", mode)
    end
end

function M.IsRunning(mode)
    mode = normMode(mode)
    return running[mode] == true
end

function M.SyncFromState()
    syncGlobals()

    if G.AUTO_SPRINKLER_ENABLED == true then
        M.Start("self")
    else
        M.Stop("sync_state", "self")
    end

    if G.AUTO_SPRINKLER_OTHER_ENABLED == true then
        M.Start("other")
    else
        M.Stop("sync_state", "other")
    end
end

function M.DebugScan(mode)
    syncGlobals()

    mode = normMode(mode)

    print("========== AutoSprinkler DebugScan ==========")
    print("Mode:", mode)

    local profile = getProfile(mode)

    print("Enabled:", G[profile.enabledKey])
    print("Selected positions:", #getSelectedPositions(mode))
    print("Selected sprinklers:", #getSelectedSprinklers(mode))

    if mode == "other" then
        local uid, name = getFirstSelectedTarget()
        print("Target:", tostring(uid), tostring(name))
    end

    local farm = getFarmForMode(mode)
    print("Farm:", farm and farm:GetFullName() or "nil")

    local objects = getObjectsPhysical(mode)
    print("Objects_Physical:", objects and objects:GetFullName() or "nil")

    local has, obj = M.HasActiveSprinkler(mode)
    print("HasActiveSprinkler:", has, obj and obj:GetFullName() or "nil")

    local backpack = LP:FindFirstChild("Backpack")
    if backpack then
        for _, tool in ipairs(backpack:GetChildren()) do
            if tool:IsA("Tool") and isSprinklerTool(tool) then
                print("SprinklerTool:", tool.Name, "uuid:", tostring(getToolUUID(tool)))
            end
        end
    end

    print("=============================================")
end

function M.Init(opts)
    opts = opts or {}

    if opts.debug ~= nil then
        M.DEBUG = opts.debug == true
    end

    if opts.placeDelay then
        M.PLACE_DELAY = tonumber(opts.placeDelay) or M.PLACE_DELAY
    end

    if opts.cycleDelay then
        M.CYCLE_DELAY = tonumber(opts.cycleDelay) or M.CYCLE_DELAY
    end

    syncGlobals()
    M.SyncFromState()

    return M
end

G.AutoSprinkler = M
_G.AutoSprinkler = M

task.defer(function()
    syncGlobals()
    M.SyncFromState()
end)

return M
        end,
        required = false,
    },

    {
        key = "AutoCook",
        name = "Auto Cook",
        factory = function()
            -- auto_cook.lua
-- Auto cook via CookingPotService_RE + FoodRecipeData
-- Actions: SubmitHeldPlant / CookBest / GetFoodFromPot / EmptyPot
-- Fill every Ingredients type (Corndog = Stick + Meat + Batter), then cook.
-- Requires.Count is ignored when it is smaller than the number of types.
-- Count > #types still means extra plants of the same types (Waffle).
-- The game only exposes CookBest — there is no Cook("Corndog") API.

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local LOOP_SEC   = 1.5
local EQUIP_WAIT = 0.2
local FIRE_WAIT  = 0.25
local ACTION_GAP = 0.35
local WAIT_MISSING_SEC = 8

local RUNNING    = false
local STOP_TOKEN = 0
local LAST_STATUS = "idle"
local LOCAL_POT = {}
local WAIT_MISSING = {} -- [uuid] = os.clock()
local HOOKED_POT_EVENTS = false
local BANNED_COMBOS = {} -- [recipe] = { ["corn|pepper|cacao"] = true }
local AVOID_FRUIT = {}   -- [recipe] = { pepper = 2, corn = 1 }

local function copyNames(src)
    local out = {}
    if type(src) ~= "table" then return out end
    for i, n in ipairs(src) do
        out[i] = n
    end
    return out
end

local function rememberSubmit(uuid, plantName, fromSubmit)
    uuid = tostring(uuid or "")
    plantName = tostring(plantName or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if uuid == "" or plantName == "" then return end
    local rec = LOCAL_POT[uuid]
    if not rec then
        rec = { names = {} }
        LOCAL_POT[uuid] = rec
    end
    rec.names[#rec.names + 1] = plantName
    rec.fromSubmit = fromSubmit == true
end

local function setLocalNames(uuid, names)
    uuid = tostring(uuid or "")
    if uuid == "" then return end
    LOCAL_POT[uuid] = { names = copyNames(names) }
end

local function localNamesOf(uuid)
    local rec = LOCAL_POT[tostring(uuid or "")]
    if rec and type(rec.names) == "table" then
        return rec.names
    end
    return {}
end

local function clearLocalPot(uuid)
    if uuid then
        LOCAL_POT[tostring(uuid)] = nil
        WAIT_MISSING[tostring(uuid)] = nil
        return
    end
    for k in pairs(LOCAL_POT) do
        LOCAL_POT[k] = nil
    end
    for k in pairs(WAIT_MISSING) do
        WAIT_MISSING[k] = nil
    end
end

local DataService = nil
local CookingPotClientUtils = nil
local FoodRecipeData = nil
local PlantTraitsData = nil
local CookingPotService_RE = nil
local GetFarm = nil

local function tryRequire(path)
    local ok, mod = pcall(function()
        local cur = ReplicatedStorage
        for part in string.gmatch(path, "[^%.]+") do
            cur = cur:FindFirstChild(part)
            if not cur then return nil end
        end
        if cur and cur:IsA("ModuleScript") then
            return require(cur)
        end
        return nil
    end)
    if ok then return mod end
    return nil
end

local function ensureModules()
    if not DataService then
        DataService = tryRequire("Modules.DataService")
    end
    if not CookingPotClientUtils then
        CookingPotClientUtils = tryRequire("Modules.Events.CookingEvent.CookingPotClientUtils")
            or tryRequire("Modules.CookingPotClientUtils")
    end
    if not FoodRecipeData then
        FoodRecipeData = tryRequire("Data.FoodRecipeData")
    end
    if not PlantTraitsData then
        PlantTraitsData = tryRequire("Modules.PlantTraitsData")
    end
    if not GetFarm then
        GetFarm = tryRequire("Modules.GetFarm")
    end
    if not CookingPotService_RE then
        local ge = ReplicatedStorage:FindFirstChild("GameEvents")
        CookingPotService_RE = ge and ge:FindFirstChild("CookingPotService_RE")
    end
    if CookingPotService_RE and not HOOKED_POT_EVENTS then
        HOOKED_POT_EVENTS = true
        CookingPotService_RE.OnClientEvent:Connect(function(action, a, b, c)
            if action == "CookingStarted" then
                clearLocalPot(a or b or c)
            elseif action == "PlantAdded" then
                local uuid = tostring(c or b or "")
                local rec = LOCAL_POT[uuid]
                local plantName = tostring(a or "")
                -- Only record server adds that we have not already counted
                -- after our own SubmitHeldPlant.
                if rec then
                    local last = rec.names[#rec.names]
                    if last == plantName and rec.fromSubmit then
                        rec.fromSubmit = false
                        return
                    end
                end
                rememberSubmit(uuid, plantName)
            end
        end)
    end
end

pcall(ensureModules)

----------------------------------------------------------------
-- Globals / state
----------------------------------------------------------------
AUTO_COOK_ENABLED = (AUTO_COOK_ENABLED == true)
AUTO_COOK_CLAIM_ENABLED = (AUTO_COOK_CLAIM_ENABLED ~= false) -- default on
AUTO_COOK_SUBMIT_ENABLED = (AUTO_COOK_SUBMIT_ENABLED ~= false)
AUTO_COOK_COOK_ENABLED = (AUTO_COOK_COOK_ENABLED ~= false)
AUTO_COOK_EMPTY_MISMATCH = (AUTO_COOK_EMPTY_MISMATCH == true)
AUTO_COOK_RECIPES_SELECTED = AUTO_COOK_RECIPES_SELECTED or {}

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_COOK_STATUS = LAST_STATUS
    _G.__AUTO_COOK_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_cook
    return type(st) == "table" and st or {}
end

local function restoreSet(src)
    local out = {}
    if type(src) ~= "table" then return out end
    if #src > 0 then
        for _, k in ipairs(src) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function syncGlobalsFromState()
    local st = getState()

    if G.AUTO_COOK_ENABLED == true or _G.AUTO_COOK_ENABLED == true or AUTO_COOK_ENABLED == true or st.enabled == true then
        AUTO_COOK_ENABLED = true
    else
        AUTO_COOK_ENABLED = false
    end

    local claim = G.AUTO_COOK_CLAIM_ENABLED
    if claim == nil then claim = _G.AUTO_COOK_CLAIM_ENABLED end
    if claim == nil then claim = AUTO_COOK_CLAIM_ENABLED end
    if claim == nil then claim = st.claim_enabled end
    AUTO_COOK_CLAIM_ENABLED = (claim ~= false)

    local submit = G.AUTO_COOK_SUBMIT_ENABLED
    if submit == nil then submit = _G.AUTO_COOK_SUBMIT_ENABLED end
    if submit == nil then submit = AUTO_COOK_SUBMIT_ENABLED end
    if submit == nil then submit = st.submit_enabled end
    AUTO_COOK_SUBMIT_ENABLED = (submit ~= false)

    local cook = G.AUTO_COOK_COOK_ENABLED
    if cook == nil then cook = _G.AUTO_COOK_COOK_ENABLED end
    if cook == nil then cook = AUTO_COOK_COOK_ENABLED end
    if cook == nil then cook = st.cook_enabled end
    AUTO_COOK_COOK_ENABLED = (cook ~= false)

    if G.AUTO_COOK_EMPTY_MISMATCH == true or _G.AUTO_COOK_EMPTY_MISMATCH == true or AUTO_COOK_EMPTY_MISMATCH == true or st.empty_mismatch == true then
        AUTO_COOK_EMPTY_MISMATCH = true
    else
        AUTO_COOK_EMPTY_MISMATCH = false
    end

    local sel = G.AUTO_COOK_RECIPES_SELECTED or _G.AUTO_COOK_RECIPES_SELECTED or AUTO_COOK_RECIPES_SELECTED
    if type(sel) ~= "table" or next(sel) == nil then
        sel = st.recipes_selected
    end
    AUTO_COOK_RECIPES_SELECTED = restoreSet(sel)
end

local function anyEnabled()
    syncGlobalsFromState()
    return AUTO_COOK_ENABLED == true
end

local function normName(s)
    return string.lower(tostring(s or ""))
end

local function comboKey(names)
    local t = {}
    for i, n in ipairs(names or {}) do
        t[i] = normName(n)
    end
    table.sort(t)
    return table.concat(t, "|")
end

local function isBannedCombo(recipe, names)
    recipe = tostring(recipe or "")
    local t = BANNED_COMBOS[recipe]
    if not t then return false end
    local key = comboKey(names)
    return key ~= "" and t[key] == true
end

local function avoidScore(recipe, plantName)
    local t = AVOID_FRUIT[tostring(recipe or "")]
    if not t then return 0 end
    return t[normName(plantName)] or 0
end

local function avoidFruits(recipe, names)
    recipe = tostring(recipe or "")
    if recipe == "" then return end
    local t = AVOID_FRUIT[recipe]
    if not t then
        t = {}
        AVOID_FRUIT[recipe] = t
    end
    for _, n in ipairs(names or {}) do
        local k = normName(n)
        if k ~= "" then
            t[k] = (t[k] or 0) + 1
        end
    end
end

local function banCombo(recipe, names)
    recipe = tostring(recipe or "")
    if recipe == "" then return end
    local key = comboKey(names)
    if key == "" then return end
    BANNED_COMBOS[recipe] = BANNED_COMBOS[recipe] or {}
    BANNED_COMBOS[recipe][key] = true
    avoidFruits(recipe, names)
end

local function sortToolsForRetry(recipe, tools)
    local copy = {}
    for i, e in ipairs(tools or {}) do
        copy[i] = e
    end
    table.sort(copy, function(a, b)
        local sa = avoidScore(recipe, a.name)
        local sb = avoidScore(recipe, b.name)
        if sa == sb then
            return tostring(a.name) < tostring(b.name)
        end
        return sa < sb
    end)
    return copy
end

----------------------------------------------------------------
-- Recipe helpers (slot-based, from FoodRecipeData.Requires.Ingredients)
----------------------------------------------------------------
local function flattenNamePool(value, out, seen)
    out = out or {}
    seen = seen or {}
    if value == nil then return out end

    if type(value) == "string" then
        local key = value:lower()
        if key ~= "" and not seen[key] then
            seen[key] = true
            out[#out + 1] = value
        end
        return out
    end

    if type(value) ~= "table" then return out end

    local n = #value
    if n > 0 then
        for i = 1, n do
            flattenNamePool(value[i], out, seen)
        end
        return out
    end

    for k, v in pairs(value) do
        if type(k) == "string" and (v == true or type(v) == "number") then
            flattenNamePool(k, out, seen)
        elseif type(v) == "string" or type(v) == "table" then
            flattenNamePool(v, out, seen)
        end
    end
    return out
end

local function recipeCount(def)
    return tonumber(def and def.Requires and def.Requires.Count) or 1
end

local function getRecipeSlots(def)
    local slots = {}
    local ingredients = def and def.Requires and def.Requires.Ingredients
    if type(ingredients) ~= "table" then return slots end

    for slotName, slotVal in pairs(ingredients) do
        local plants = flattenNamePool(slotVal, {}, {})
        local set = {}
        for _, p in ipairs(plants) do
            set[normName(p)] = true
        end
        local trait = nil
        if PlantTraitsData and type(PlantTraitsData.Traits) == "table" then
            for tname, tval in pairs(PlantTraitsData.Traits) do
                if tval == slotVal then
                    trait = tostring(tname)
                    break
                end
            end
        end
        slots[#slots + 1] = {
            name = tostring(slotName),
            plants = plants,
            set = set,
            trait = trait,
        }
    end

    table.sort(slots, function(a, b)
        if #a.plants == #b.plants then return a.name < b.name end
        return #a.plants < #b.plants
    end)
    return slots
end

-- Ignore Requires.Count when it is smaller than the ingredient types
-- (Corndog: Stick + Meat + Batter = 3, Count 2 is not accurate).
-- Soup has no Ingredients: use Count. Waffle/Smoothie: Count > #types means extras.
local function recipeNeed(def)
    local slots = getRecipeSlots(def)
    if #slots == 0 then
        return recipeCount(def)
    end
    local count = recipeCount(def)
    if count > #slots then
        return count
    end
    return #slots
end

local function slotAccepts(slot, plantName)
    if not slot then return false end
    local raw = tostring(plantName or "")
    local key = normName(raw)
    if key == "" then return false end
    if slot.set[key] == true then return true end
    for name in pairs(slot.set or {}) do
        if key == name then return true end
        if #key > #name and key:sub(-#name) == name then
            local left = key:sub(1, #key - #name)
            if left == "" or left:find("[^%w]$") then
                return true
            end
        end
    end
    if slot.trait and PlantTraitsData and type(PlantTraitsData.HasTrait) == "function" then
        local ok, has = pcall(PlantTraitsData.HasTrait, raw, slot.trait)
        if ok and has then return true end
    end
    return false
end

local function plantSlotCount(plantName, slots)
    local n = 0
    for _, s in ipairs(slots) do
        if slotAccepts(s, plantName) then n += 1 end
    end
    return n
end

-- Assign submitted plants to unique slots first (specific plants / small slots first).
-- Leftovers become extras on any matching slot (Count > #slots, e.g. Smoothie/Waffle).
local function assignSubmitted(slots, submittedNames)
    local filled = {}
    local extras = {}
    local unmatched = {}
    local slotFilled = {}

    if #slots == 0 then
        return {
            filled = filled,
            extras = extras,
            unmatched = unmatched,
            filledCount = 0,
            extraCount = #submittedNames,
        }
    end

    local plants = {}
    for i, name in ipairs(submittedNames) do
        plants[i] = { name = tostring(name), idx = i, choices = plantSlotCount(name, slots) }
    end
    table.sort(plants, function(a, b)
        if a.choices == b.choices then return a.idx < b.idx end
        return a.choices < b.choices
    end)

    local used = {}
    for _, s in ipairs(slots) do
        for _, p in ipairs(plants) do
            if not used[p.idx] and slotAccepts(s, p.name) then
                used[p.idx] = true
                slotFilled[s.name] = p.name
                filled[#filled + 1] = { slot = s.name, plant = p.name }
                break
            end
        end
    end

    for _, p in ipairs(plants) do
        if not used[p.idx] then
            local ok = false
            for _, s in ipairs(slots) do
                if slotAccepts(s, p.name) then
                    used[p.idx] = true
                    extras[#extras + 1] = { slot = s.name, plant = p.name }
                    ok = true
                    break
                end
            end
            if not ok then
                unmatched[#unmatched + 1] = p.name
            end
        end
    end

    local filledCount = 0
    for _ in pairs(slotFilled) do filledCount += 1 end

    return {
        filled = filled,
        extras = extras,
        unmatched = unmatched,
        filledCount = filledCount,
        extraCount = #extras,
        slotFilled = slotFilled,
    }
end

local function isSoupRecipe(def)
    local slots = getRecipeSlots(def)
    return #slots == 0
end

local function recipeOnTrack(def, submittedNames)
    local need = recipeNeed(def)
    local have = #submittedNames
    if have > need then return false, "overfill" end

    local slots = getRecipeSlots(def)
    if #slots == 0 then
        return true, "soup"
    end

    local asg = assignSubmitted(slots, submittedNames)
    if #asg.unmatched > 0 then
        return false, "unmatched"
    end

    local minSlots = math.min(#slots, need)
    if have == need then
        if asg.filledCount < minSlots then
            return false, "slots"
        end
        return true, "ready"
    end

    -- still filling: extras are only OK after all required slots are covered
    if asg.extraCount > 0 and asg.filledCount < minSlots then
        return false, "wrong-slot"
    end
    return true, "filling"
end

local function recipeReady(def, submittedNames)
    if #submittedNames ~= recipeNeed(def) then return false end
    local ok, why = recipeOnTrack(def, submittedNames)
    return ok and (why == "ready" or why == "soup")
end

function M.GetRecipeList()
    ensureModules()
    local out = {}
    local recipes = FoodRecipeData and FoodRecipeData.Recipes
    if type(recipes) ~= "table" then return out end

    local tmp = {}
    for name, def in pairs(recipes) do
        if type(def) == "table" then
            tmp[#tmp + 1] = {
                key = tostring(name),
                name = tostring(name),
                priority = tonumber(def.Priority) or 0,
            }
        end
    end
    table.sort(tmp, function(a, b)
        if a.priority == b.priority then return a.name < b.name end
        return a.priority > b.priority
    end)
    for i, rec in ipairs(tmp) do
        out[i] = { key = rec.key, name = rec.name }
    end
    return out
end

local function getSelectedRecipes()
    ensureModules()
    local selected = AUTO_COOK_RECIPES_SELECTED or {}
    local list = {}
    local recipes = FoodRecipeData and FoodRecipeData.Recipes
    if type(recipes) ~= "table" then return list end

    for name, on in pairs(selected) do
        if on == true and type(recipes[name]) == "table" then
            list[#list + 1] = {
                name = tostring(name),
                def = recipes[name],
                priority = tonumber(recipes[name].Priority) or 0,
            }
        end
    end
    table.sort(list, function(a, b)
        if a.priority == b.priority then return a.name < b.name end
        return a.priority > b.priority
    end)
    return list
end

local function selectedHas(name)
    if not name then return false end
    return (AUTO_COOK_RECIPES_SELECTED or {})[tostring(name)] == true
end

----------------------------------------------------------------
-- Pot / tools
----------------------------------------------------------------
local function getBackpack()
    return LP:FindFirstChild("Backpack")
end

local function unequipTools()
    local char = LP.Character
    local bag = getBackpack()
    if not char or not bag then return end
    for _, inst in ipairs(char:GetChildren()) do
        if inst:IsA("Tool") then
            inst.Parent = bag
        end
    end
end

local function equipTool(tool)
    local char = LP.Character
    local bag = getBackpack()
    if not char or not tool then return false end
    if tool.Parent ~= bag and tool.Parent ~= char then return false end

    unequipTools()
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum:EquipTool(tool) end)
    else
        tool.Parent = char
    end
    task.wait(EQUIP_WAIT)
    return tool.Parent == char
end

local function toolChildValue(tool, childName)
    if not tool then return nil end
    local ch = tool:FindFirstChild(childName)
    if ch and ch:IsA("ValueBase") then
        local v = tostring(ch.Value or "")
        if v ~= "" then return v end
    end
    return nil
end

local function cleanPlantName(raw)
    raw = tostring(raw or "")
    raw = raw:gsub("%b[]", " ")
    raw = raw:gsub("%s*%(%d+%.?%d*%s*kg%)$", "")
    raw = raw:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    return raw
end

local function firstPlantName(...)
    for i = 1, select("#", ...) do
        local v = select(i, ...)
        if type(v) == "string" then
            local cleaned = cleanPlantName(v)
            if cleaned ~= "" and cleaned:find("%a") then
                return cleaned
            end
        end
    end
    return ""
end

local function toolPlantName(tool)
    if not tool then return "" end
    local n = firstPlantName(
        toolChildValue(tool, "Item_String"),
        tool:GetAttribute("f"),
        tool:GetAttribute("Seed"),
        tool:GetAttribute("ItemName"),
        tool:GetAttribute("FruitName"),
        tool:GetAttribute("PlantName"),
        tool:GetAttribute("HoldableName")
    )
    if n ~= "" then return n end
    return firstPlantName(tool.Name)
end

local function toolHasTag(tool, tag)
    if not tool then return false end
    local ok, res = pcall(function()
        return CollectionService:HasTag(tool, tag) or tool:HasTag(tag)
    end)
    return ok and res == true
end

local function isFruitTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    if toolHasTag(tool, "FoodTool") or toolHasTag(tool, "FoodGenerated") then return false end
    if tool:GetAttribute("PET_UUID") ~= nil then return false end
    if toolHasTag(tool, "FruitTool") then return true end
    local typeCode = tostring(tool:GetAttribute("b") or "")
    if typeCode == "u" or typeCode == "l" or typeCode == "n" then return false end
    if typeCode == "j" then return true end
    local t = tostring(tool:GetAttribute("ITEMTYPE") or tool:GetAttribute("ItemType") or "")
    return t == "Holdable" or t == "Fruit"
end

local function collectAllFruitTools()
    local out, seen = {}, {}
    local bag = getBackpack()
    local char = LP.Character
    local function tryAdd(tool)
        if not tool or seen[tool] or not isFruitTool(tool) then return end
        local parent = tool.Parent
        if parent ~= bag and parent ~= char then return end
        local pname = toolPlantName(tool)
        if pname == "" then return end
        seen[tool] = true
        out[#out + 1] = { tool = tool, name = pname }
    end
    local function scan(container)
        if not container then return end
        for _, child in ipairs(container:GetChildren()) do
            tryAdd(child)
        end
    end
    scan(bag)
    scan(char)
    pcall(function()
        for _, inst in ipairs(CollectionService:GetTagged("FruitTool")) do
            tryAdd(inst)
        end
    end)
    return out
end

local TOOLS_CACHE = { at = 0, list = {} }
local function collectAllFruitToolsCached()
    local now = os.clock()
    if (now - (TOOLS_CACHE.at or 0)) < 0.8 and type(TOOLS_CACHE.list) == "table" then
        return TOOLS_CACHE.list
    end
    local list = collectAllFruitTools()
    TOOLS_CACHE.at = now
    TOOLS_CACHE.list = list
    return list
end

-- Dump CookingPotUIController: FireServer(action) with no extra args.
-- Extra UUID in the same pcall can abort the dump call.
local function fireCook(action, uuid)
    ensureModules()
    if not CookingPotService_RE then return false end
    action = tostring(action or "")
    uuid = tostring(uuid or "")
    local okDump = pcall(function()
        CookingPotService_RE:FireServer(action)
    end)
    local okUuid = false
    if uuid ~= "" then
        okUuid = pcall(function()
            CookingPotService_RE:FireServer(action, uuid)
        end)
    end
    return okDump or okUuid
end

local function getKitModel(uuid)
    local model = nil
    pcall(function()
        if CookingPotClientUtils and type(CookingPotClientUtils.GetCookingPotModel) == "function" then
            model = CookingPotClientUtils:GetCookingPotModel(LP, uuid)
        end
    end)
    return model
end

-- Dump path: IngredientsBoard.CookingIngredientGui.Background.ExtraUI.EmptyPotFrame.EmptyButton
local function findEmptyButton(uuid)
    local roots = {}
    local model = getKitModel(uuid)
    if model then
        roots[#roots + 1] = model
        if model.Parent then roots[#roots + 1] = model.Parent end
    end
    pcall(function()
        local tagged = game:GetService("CollectionService"):GetTagged("CookingEventModel")
        if tagged and tagged[1] then
            roots[#roots + 1] = tagged[1]
        end
    end)
    for _, root in ipairs(roots) do
        local named = root:FindFirstChild("EmptyButton", true)
        if named then return named end
        local frame = root:FindFirstChild("EmptyPotFrame", true)
        if frame then
            local btn = frame:FindFirstChild("EmptyButton")
                or frame:FindFirstChildWhichIsA("GuiButton", true)
                or frame:FindFirstChildWhichIsA("TextButton", true)
            if btn then return btn end
        end
    end
    return nil
end

-- Dump: EmptyButton.Activated fires EmptyPot with no extra args.
local function clickEmptyButton(uuid)
    local btn = findEmptyButton(uuid)
    if not btn then return false end
    if type(getconnections) == "function" then
        local fired = false
        pcall(function()
            for _, c in ipairs(getconnections(btn.Activated)) do
                if type(c.Fire) == "function" then
                    c:Fire()
                    fired = true
                elseif type(c.Function) == "function" then
                    c.Function()
                    fired = true
                end
            end
        end)
        if fired then return true end
    end
    if type(firesignal) == "function" then
        local ok = pcall(function()
            firesignal(btn.Activated)
        end)
        if ok then return true end
    end
    if btn:IsA("GuiButton") then
        pcall(function()
            btn:Activate()
        end)
        return true
    end
    return false
end

local function emptyPot(uuid, why)
    publishStatus("empty " .. tostring(why or "mismatch"))
    clickEmptyButton(uuid)
    -- Dump: FireServer EmptyPot, no extra args.
    pcall(function()
        if CookingPotService_RE then
            CookingPotService_RE:FireServer("EmptyPot")
        end
    end)
    task.wait(ACTION_GAP)
    clearLocalPot(uuid)
end

local function addUuid(out, seen, uuid)
    uuid = tostring(uuid or "")
    if uuid == "" or seen[uuid] then return end
    seen[uuid] = true
    out[#out + 1] = uuid
end

local function listPotUUIDs()
    ensureModules()
    local out, seen = {}, {}

    local function ingestModels(models)
        if type(models) ~= "table" then return end
        for _, model in ipairs(models) do
            local parent = model and model.Parent
            local uuid = parent and parent:GetAttribute("CosmeticUUID")
            if uuid and tostring(uuid) ~= "" then
                addUuid(out, seen, uuid)
            end
        end
    end

    if CookingPotClientUtils then
        if type(CookingPotClientUtils.GetAllCookingPotUUIDs) == "function" then
            local ok, models = pcall(function()
                return CookingPotClientUtils:GetAllCookingPotUUIDs(LP)
            end)
            if ok then ingestModels(models) end
        end
        if #out == 0 and type(CookingPotClientUtils.GetAllCookingPotModels) == "function" then
            local ok, models = pcall(function()
                return CookingPotClientUtils:GetAllCookingPotModels(LP)
            end)
            if ok then ingestModels(models) end
        end
    end

    if #out == 0 and type(GetFarm) == "function" then
        pcall(function()
            local farm = GetFarm(LP)
            local important = farm and farm:FindFirstChild("Important")
            local phys = important and important:FindFirstChild("Cosmetic_Physical")
            if not phys then return end
            for _, child in ipairs(phys:GetChildren()) do
                if child:FindFirstChild("Cooking Kit") then
                    addUuid(out, seen, child:GetAttribute("CosmeticUUID"))
                end
            end
        end)
    end

    if DataService and type(DataService.GetData) == "function" then
        pcall(function()
            local data = playerData()
            local kitRoot = data and data.CookingKit
            if type(kitRoot) == "table" then
                for _, kit in pairs(kitRoot) do
                    if type(kit) == "table" then
                        for kitUuid, _ in pairs(kit) do
                            if type(kitUuid) == "string" then
                                addUuid(out, seen, kitUuid)
                            end
                        end
                    end
                end
            end
        end)
    end

    return out
end

local function playerData()
    if not DataService or type(DataService.GetData) ~= "function" then
        return nil
    end
    local ok, data = pcall(function()
        return DataService:GetData(LP)
    end)
    if ok and type(data) == "table" then return data end
    ok, data = pcall(function()
        return DataService:GetData()
    end)
    if ok and type(data) == "table" then return data end
    return nil
end

local function findKitPot(pd, uuid)
    if type(pd) ~= "table" then return nil end
    uuid = tostring(uuid or "")
    if uuid == "" then return nil end
    if uuid == "OLD_KITCHEN_COOKING_EVENT" then
        return pd.CookingPot
    end
    local kitRoot = pd.CookingKit
    if type(kitRoot) ~= "table" then return nil end
    local slot = pd.SaveSlots and pd.SaveSlots.SelectedSlot
    if slot and type(kitRoot[slot]) == "table" and type(kitRoot[slot][uuid]) == "table" then
        return kitRoot[slot][uuid]
    end
    for _, kit in pairs(kitRoot) do
        if type(kit) == "table" and type(kit[uuid]) == "table" then
            return kit[uuid]
        end
    end
    return nil
end

local function getPotData(uuid)
    ensureModules()
    if CookingPotClientUtils and type(CookingPotClientUtils.GetCookingPotData) == "function" then
        local ok, data = pcall(function()
            return CookingPotClientUtils:GetCookingPotData(LP, uuid)
        end)
        if ok and type(data) == "table" then return data end
    end
    return findKitPot(playerData(), uuid)
end

local function submittedPlantNames(data)
    local names = {}
    local function push(name)
        name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if name ~= "" then
            names[#names + 1] = name
        end
    end

    local function walk(v, depth)
        if v == nil or depth > 6 then return end
        if type(v) == "string" then
            push(v)
            return
        end
        if type(v) ~= "table" then return end

        local item = v.ItemData
        if type(item) == "table" then
            push(item.ItemName or item.Name or item.HoldableName)
            return
        end
        if type(v.ItemName) == "string" or type(v.Name) == "string" then
            push(v.ItemName or v.Name or v.HoldableName)
            return
        end

        if #v > 0 then
            for i = 1, #v do
                walk(v[i], depth + 1)
            end
            return
        end
        for _, child in pairs(v) do
            walk(child, depth + 1)
        end
    end

    walk(data and data.SubmittedIngredients, 0)
    return names
end

local BOARD_SKIP = {
    uilistlayout = true,
    uipadding = true,
    uistroke = true,
    uicorner = true,
    ingredients = true,
    ingredient = true,
    empty = true,
    cook = true,
    cooking = true,
    time = true,
}

local function worldBoardNames(uuid)
    local names = {}
    if not CookingPotClientUtils or type(CookingPotClientUtils.GetCookingPotModel) ~= "function" then
        return names
    end
    pcall(function()
        local model = CookingPotClientUtils:GetCookingPotModel(LP, uuid)
        if not model then return end

        local function takeName(raw)
            raw = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if raw == "" then return end
            if BOARD_SKIP[string.lower(raw)] then return end
            if raw:find("INGREDIENT") or raw:find(":") then return end
            names[#names + 1] = raw
        end

        local function collectFrom(root)
            if not root then return end
            for _, child in ipairs(root:GetChildren()) do
                if child:IsA("Frame") then
                    local label = child:FindFirstChild("ItemNameLabel")
                    if label and label:IsA("TextLabel") then
                        local t = tostring(label.Text or ""):gsub("%s+$", "")
                        if t ~= "" then
                            takeName(t)
                        else
                            takeName(child.Name)
                        end
                    elseif child.Name ~= "UIListLayout" and child.Name ~= "UIPadding" then
                        takeName(child.Name)
                    end
                elseif child:IsA("TextLabel") then
                    takeName(child.Text)
                end
            end
        end

        local inside = model:FindFirstChild("InsidePotFrame", true)
        collectFrom(inside)
        if #names == 0 then
            local gui = model:FindFirstChild("CookingIngredientGui", true)
            collectFrom(gui and gui:FindFirstChild("InsidePotFrame", true))
            collectFrom(gui and gui:FindFirstChild("Background") and gui.Background:FindFirstChild("InsidePotFrame"))
        end
    end)
    return names
end

local function potPlantNames(data, uuid)
    local dataNames = submittedPlantNames(data)
    local board = worldBoardNames(uuid)
    local remembered = localNamesOf(uuid)

    local best = dataNames
    if #board > #best then best = board end
    if #remembered > #best then best = remembered end

    if #best > #remembered then
        setLocalNames(uuid, best)
    end
    return copyNames(best)
end

local function submittedCount(data)
    return #submittedPlantNames(data)
end

local function potReadyToClaim(data)
    if not data then return false end
    if data.IsCooking then return false end
    return data.FinishedFoodRawData ~= nil and data.CookingEndTime == nil
end

local function formatMMSS(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    local m = math.floor(sec / 60)
    local s = sec % 60
    return string.format("%02d:%02d", m, s)
end

local function describePotLine(index, uuid)
    local data = getPotData(uuid)
    if not data then
        return ("Pot %d: no data"):format(index)
    end

    local recipe = data.BestRecipe and tostring(data.BestRecipe) or nil
    local endTime = data.CookingEndTime
    local now = workspace:GetServerTimeNow()

    if potReadyToClaim(data) then
        return ("Pot %d: ready · %s"):format(index, recipe or "food")
    end

    if data.IsCooking or endTime ~= nil then
        local left = 0
        if type(endTime) == "number" then
            left = math.max(0, endTime - now)
        end
        local name = recipe or "cooking"
        if left > 0 then
            return ("Pot %d: cooking %s · %s"):format(index, formatMMSS(left), name)
        end
        return ("Pot %d: finishing · %s"):format(index, name)
    end

    local names = potPlantNames(data, uuid)
    local count = #names
    if count > 0 then
        local need = "?"
        if recipe and FoodRecipeData and FoodRecipeData.Recipes and FoodRecipeData.Recipes[recipe] then
            need = tostring(recipeNeed(FoodRecipeData.Recipes[recipe]))
        end
        local plants = table.concat(names, ", ")
        if #plants > 28 then plants = plants:sub(1, 25) .. "..." end
        return ("Pot %d: filling %d/%s%s · %s"):format(
            index,
            count,
            need,
            recipe and (" · " .. recipe) or "",
            plants
        )
    end

    return ("Pot %d: idle"):format(index)
end

local function previewNames(list, maxN)
    maxN = maxN or 3
    if type(list) ~= "table" or #list == 0 then return "—" end
    local parts = {}
    for i = 1, math.min(maxN, #list) do
        parts[i] = tostring(list[i])
    end
    local extra = #list - #parts
    local s = table.concat(parts, ", ")
    if extra > 0 then
        s = s .. " +" .. tostring(extra)
    end
    return s
end

local function bagNamesForSlot(slot, tools)
    local seen, names = {}, {}
    for _, entry in ipairs(tools) do
        local key = normName(entry.name)
        if key ~= "" and not seen[key] and slotAccepts(slot, entry.name) then
            seen[key] = true
            names[#names + 1] = entry.name
        end
    end
    return names
end

local function describeRecipeNeed(rec, submittedNames, tools)
    local lines = {}
    local need = recipeNeed(rec.def)
    local slots = getRecipeSlots(rec.def)
    local have = #submittedNames
    if #slots == 0 then
        lines[#lines + 1] = ("need %s %d/%d fruit"):format(rec.name, have, need)
        return lines
    end

    lines[#lines + 1] = ("need %s %d/%d fruit"):format(rec.name, have, need)

    local asg = assignSubmitted(slots, submittedNames)
    local parts = {}
    for _, slot in ipairs(slots) do
        local filled = asg.slotFilled and asg.slotFilled[slot.name]
        if filled then
            parts[#parts + 1] = slot.name .. "=" .. filled
        else
            local bag = bagNamesForSlot(slot, tools)
            parts[#parts + 1] = slot.name .. ":" .. previewNames(bag, 2)
        end
    end
    if #parts > 0 then
        lines[#lines + 1] = "  " .. table.concat(parts, " · ")
    end
    return lines
end

function M.GetStatusText()
    syncGlobalsFromState()
    ensureModules()
    local on = (AUTO_COOK_ENABLED == true) and "ON" or "OFF"
    local selected = getSelectedRecipes()
    local n = #selected

    local pots = listPotUUIDs()
    local lines = {
        ("Auto Cook %s · recipes %d · pots %d"):format(on, n, #pots),
    }

    if #pots == 0 then
        lines[#lines + 1] = "no Cooking Kit"
    else
        for i, uuid in ipairs(pots) do
            local ok, line = pcall(describePotLine, i, uuid)
            lines[#lines + 1] = (ok and line) or ("Pot %d: err"):format(i)
        end
    end

    local submitted, tools = {}, {}
    local potData = nil
    local cooking = false
    local bestName = nil
    if #pots > 0 then
        potData = getPotData(pots[1])
        submitted = potPlantNames(potData, pots[1])
        cooking = potData and (potData.IsCooking == true or potData.CookingEndTime ~= nil) or false
        bestName = potData and potData.BestRecipe and tostring(potData.BestRecipe) or nil
    end
    pcall(function()
        tools = collectAllFruitToolsCached()
    end)

    local function recipeNames()
        local names = {}
        for _, rec in ipairs(selected) do
            names[#names + 1] = rec.name
        end
        return table.concat(names, ", ")
    end

    if n == 0 then
        lines[#lines + 1] = "need: select a recipe"
    elseif cooking then
        lines[#lines + 1] = "selected: " .. recipeNames()
    else
        local focus = selected[1]
        if bestName then
            for _, rec in ipairs(selected) do
                if rec.name == bestName then
                    focus = rec
                    break
                end
            end
        end
        local ok, needLines = pcall(describeRecipeNeed, focus, submitted, tools)
        if ok and type(needLines) == "table" then
            for _, line in ipairs(needLines) do
                lines[#lines + 1] = line
            end
        else
            lines[#lines + 1] = "need " .. tostring(focus and focus.name or "?")
        end
        if n > 1 then
            local others = {}
            for _, rec in ipairs(selected) do
                if not focus or rec.name ~= focus.name then
                    others[#others + 1] = rec.name
                end
            end
            if #others > 0 then
                lines[#lines + 1] = "also: " .. table.concat(others, ", ")
            end
        end
    end

    if LAST_STATUS and LAST_STATUS ~= "" then
        lines[#lines + 1] = "action: " .. LAST_STATUS
    end

    return table.concat(lines, "\n")
end

----------------------------------------------------------------
-- Inventory vs recipe
----------------------------------------------------------------
local function takeToolForSlot(slot, tools, used, allSlots)
    local best, bestChoices
    for i, entry in ipairs(tools) do
        if not used[i] and slotAccepts(slot, entry.name) then
            local choices = plantSlotCount(entry.name, allSlots or { slot })
            if not best or choices < bestChoices then
                best = i
                bestChoices = choices
            end
        end
    end
    return best
end

local function takeToolForSlots(slots, tools, used, preferUnfilled)
    local bestIdx, bestScore
    for i, entry in ipairs(tools) do
        if not used[i] then
            local matchesUnfilled = false
            local matchesAny = false
            local choices = 0
            for _, s in ipairs(slots) do
                if slotAccepts(s, entry.name) then
                    matchesAny = true
                    choices += 1
                    if preferUnfilled and preferUnfilled[s.name] then
                        matchesUnfilled = true
                    end
                end
            end
            if matchesAny then
                local score = choices
                if preferUnfilled and not matchesUnfilled then
                    score += 1000
                end
                if not bestIdx or score < bestScore then
                    bestIdx = i
                    bestScore = score
                end
            end
        end
    end
    return bestIdx
end

-- Selected recipe is filled when every Ingredients slot has a plant.
local function recipeCouldWin(def, names)
    local slots = getRecipeSlots(def)
    local need = recipeNeed(def)
    if #slots == 0 then
        return #names == need
    end
    local asg = assignSubmitted(slots, names)
    if #asg.unmatched > 0 then return false end
    return #names == need and asg.filledCount >= math.min(#slots, need)
end

local function predictBestRecipe(names)
    ensureModules()
    if type(names) ~= "table" or #names == 0 then return nil end
    local recipes = FoodRecipeData and FoodRecipeData.Recipes
    if type(recipes) ~= "table" then return nil end
    local bestName, bestPri = nil, -1e9
    for name, def in pairs(recipes) do
        if type(def) == "table" and recipeCouldWin(def, names) then
            local pri = tonumber(def.Priority) or 0
            if pri > bestPri then
                bestPri = pri
                bestName = tostring(name)
            end
        end
    end
    return bestName
end

local function namesPlus(list, name)
    local out = {}
    for i, v in ipairs(list) do
        out[i] = v
    end
    out[#out + 1] = name
    return out
end

local function toolsForRecipe(def, tools)
    local slots = getRecipeSlots(def)
    if #slots == 0 then return tools end

    local scored = {}
    for _, entry in ipairs(tools) do
        local choices = plantSlotCount(entry.name, slots)
        if choices > 0 then
            scored[#scored + 1] = { entry = entry, choices = choices }
        end
    end
    table.sort(scored, function(a, b)
        if a.choices == b.choices then
            return tostring(a.entry.name) < tostring(b.entry.name)
        end
        return a.choices < b.choices
    end)

    local out, seenName = {}, {}
    for _, s in ipairs(scored) do
        local key = normName(s.entry.name)
        if not seenName[key] then
            seenName[key] = true
            out[#out + 1] = s.entry
        end
        if #out >= 48 then break end
    end
    return out
end

local function canCompleteRecipe(def, submittedNames, tools, targetName, requirePredict)
    local need = recipeNeed(def)
    local have = #submittedNames
    if have > need then return false end
    if not select(1, recipeOnTrack(def, submittedNames)) then return false end
    if have == need then
        if targetName and isBannedCombo(targetName, submittedNames) then
            return false
        end
        if requirePredict and targetName then
            return predictBestRecipe(submittedNames) == targetName
        end
        return recipeCouldWin(def, submittedNames)
    end

    local cand = toolsForRecipe(def, tools)
    if #cand == 0 then
        return isSoupRecipe(def) and #tools > 0
    end

    local function dfs(cur, used, depth)
        if #cur == need then
            if targetName and isBannedCombo(targetName, cur) then
                return false
            end
            if requirePredict and targetName then
                return predictBestRecipe(cur) == targetName
            end
            return recipeCouldWin(def, cur)
        end
        if depth > 6 then return false end
        for i, entry in ipairs(cand) do
            if not used[i] then
                local nxt = namesPlus(cur, entry.name)
                if select(1, recipeOnTrack(def, nxt)) then
                    used[i] = true
                    if dfs(nxt, used, depth + 1) then
                        return true
                    end
                    used[i] = false
                end
            end
        end
        return false
    end

    return dfs(submittedNames, {}, 0)
end

local function slotNameForPlant(def, submittedNames, plantName)
    local slots = getRecipeSlots(def)
    local asg = assignSubmitted(slots, submittedNames)
    for _, s in ipairs(slots) do
        if not (asg.slotFilled and asg.slotFilled[s.name]) and slotAccepts(s, plantName) then
            return s.name
        end
    end
    return "extra"
end

local function pickNextSubmit(def, submittedNames, tools, targetName)
    local need = recipeNeed(def)
    if #submittedNames >= need then return nil end

    local slots = getRecipeSlots(def)
    local ordered = sortToolsForRetry(targetName, tools)
    if #slots == 0 then
        if #ordered > 0 then return ordered[1], "any" end
        return nil
    end

    local asg = assignSubmitted(slots, submittedNames)
    for _, slot in ipairs(slots) do
        if not (asg.slotFilled and asg.slotFilled[slot.name]) then
            for _, entry in ipairs(ordered) do
                if slotAccepts(slot, entry.name) then
                    local nxt = namesPlus(submittedNames, entry.name)
                    if select(1, recipeOnTrack(def, nxt)) then
                        if not (#nxt == need and targetName and isBannedCombo(targetName, nxt)) then
                            return entry, slot.name
                        end
                    end
                end
            end
        end
    end
    return nil
end

local function pickTargetRecipe(selectedRecipes, submittedNames, tools)
    if #selectedRecipes == 0 then return nil, "no recipe selected" end

    if #submittedNames > 0 then
        for _, rec in ipairs(selectedRecipes) do
            if select(1, recipeOnTrack(rec.def, submittedNames)) then
                return rec, "continue"
            end
        end
        return nil, "mismatch"
    end

    return selectedRecipes[1], "start"
end

----------------------------------------------------------------
-- Tick actions
----------------------------------------------------------------
local function processPot(uuid, selectedRecipes)
    local data = getPotData(uuid)
    if not data then
        publishStatus("no pot data")
        return
    end

    if AUTO_COOK_CLAIM_ENABLED ~= false and potReadyToClaim(data) then
        publishStatus("claim " .. tostring(data.BestRecipe or "food"))
        fireCook("GetFoodFromPot", uuid)
        clearLocalPot(uuid)
        task.wait(ACTION_GAP)
        return
    end

    if data.IsCooking or data.CookingEndTime ~= nil then
        clearLocalPot(uuid)
        local cooking = data.BestRecipe and tostring(data.BestRecipe) or "food"
        if next(AUTO_COOK_RECIPES_SELECTED or {}) and not selectedHas(cooking) then
            publishStatus("cannot empty while cooking " .. cooking .. " · wait claim")
        else
            publishStatus("cooking...")
        end
        return
    end

    if #selectedRecipes == 0 then
        publishStatus("no recipe selected")
        return
    end

    local submitted = potPlantNames(data, uuid)
    local count = #submitted
    local tools = collectAllFruitToolsCached()
    local target, reason = pickTargetRecipe(selectedRecipes, submitted, tools)
    local best = data.BestRecipe and tostring(data.BestRecipe) or nil

    local function doEmpty(why)
        emptyPot(uuid, why)
    end

    -- Partial fill often shows a lower recipe (Soup) as BestRecipe.
    -- Do not empty until the selected recipe has all required plants,
    -- unless the plants already in the pot cannot complete it.
    local needGuess = target and recipeNeed(target.def) or nil
    if not needGuess then
        needGuess = recipeNeed(selectedRecipes[1] and selectedRecipes[1].def)
    end
    local filling = count < (needGuess or 1)

    if reason == "mismatch" and count > 0 then
        if AUTO_COOK_EMPTY_MISMATCH ~= false then
            doEmpty(best and ("mismatch " .. best) or "mismatch")
        else
            publishStatus("pot mismatch" .. (best and (" · " .. best) or "") .. " (enable Empty)")
        end
        return
    end

    if not target then
        publishStatus(reason or "no recipe")
        return
    end

    local need = recipeNeed(target.def)
    local slots = getRecipeSlots(target.def)
    local asg = assignSubmitted(slots, submitted)
    filling = count < need

    -- Full pot only: BestRecipe is not the selected one.
    if (not filling) and best and not selectedHas(best) then
        if AUTO_COOK_EMPTY_MISMATCH ~= false then
            doEmpty("mismatch " .. best)
        else
            publishStatus("pot mismatch · " .. best .. " (enable Empty)")
        end
        return
    end

    if count > need or (asg.extraCount > 0 and asg.filledCount < #slots) then
        doEmpty("overfill " .. count .. "/" .. need)
        return
    end

    if count >= need then
        local predicted = predictBestRecipe(submitted)
        local result = best or predicted
        if not result then
            task.wait(0.15)
            data = getPotData(uuid)
            submitted = potPlantNames(data, uuid)
            best = data and data.BestRecipe and tostring(data.BestRecipe) or nil
            predicted = predictBestRecipe(submitted)
            result = best or predicted
        end

        if result == target.name then
            publishStatus("cook " .. target.name)
            fireCook("CookBest", uuid)
            task.wait(0.45)
            data = getPotData(uuid)
            if data and data.IsCooking ~= true and data.CookingEndTime == nil then
                -- CookBest did not take; dump EmptyButton is the working client path
                doEmpty("cook did not start")
            else
                clearLocalPot(uuid)
            end
            task.wait(ACTION_GAP)
            return
        end

        banCombo(target.name, submitted)
        doEmpty("retry " .. target.name .. " · was " .. tostring(result or "unknown"))
        return
    end

    if AUTO_COOK_SUBMIT_ENABLED ~= false then
        local missing = nil
        for _, slot in ipairs(slots) do
            if not (asg.slotFilled and asg.slotFilled[slot.name]) then
                missing = slot.name
                break
            end
        end

        -- Empty pot: do not start Batter/Meat unless Stick (and the rest) are in the bag.
        if count == 0 and not canCompleteRecipe(target.def, submitted, tools, target.name) then
            WAIT_MISSING[uuid] = nil
            publishStatus("need " .. tostring(missing or "other") .. " fruit for " .. target.name)
            return
        end

        local entry, slotName = pickNextSubmit(target.def, submitted, tools, target.name)
        if not entry then
            if count > 0 then
                local waited = 0
                if missing then
                    WAIT_MISSING[uuid] = WAIT_MISSING[uuid] or os.clock()
                    waited = os.clock() - WAIT_MISSING[uuid]
                    if waited < WAIT_MISSING_SEC then
                        publishStatus(
                            ("need %s fruit for %s · wait %ds"):format(
                                missing,
                                target.name,
                                math.max(1, math.ceil(WAIT_MISSING_SEC - waited))
                            )
                        )
                        return
                    end
                end
                WAIT_MISSING[uuid] = nil
                avoidFruits(target.name, submitted)
                doEmpty(missing and ("no " .. missing .. " fruit") or ("retry other fruit for " .. target.name))
                return
            end
            WAIT_MISSING[uuid] = nil
            if isSoupRecipe(target.def) then
                publishStatus("no fruit tools")
            else
                publishStatus("need other fruit for " .. target.name)
            end
            return
        end

        WAIT_MISSING[uuid] = nil
        publishStatus("submit " .. entry.name .. " → " .. target.name .. (slotName and (" [" .. slotName .. "]") or ""))
        if equipTool(entry.tool) then
            task.wait(FIRE_WAIT)
            fireCook("SubmitHeldPlant", uuid)
            rememberSubmit(uuid, entry.name, true)
            task.wait(ACTION_GAP)
            unequipTools()
        end
        return
    end

    publishStatus("idle " .. target.name)
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        if not anyEnabled() then break end
        ensureModules()

        local selected = getSelectedRecipes()
        local pots = listPotUUIDs()
        if #pots == 0 then
            publishStatus("no Cooking Kit placed")
            task.wait(LOOP_SEC)
        else
            for _, uuid in ipairs(pots) do
                if not RUNNING or token ~= STOP_TOKEN or not anyEnabled() then break end
                local ok, err = pcall(processPot, uuid, selected)
                if not ok then
                    publishStatus("err: " .. tostring(err))
                end
                task.wait(ACTION_GAP)
            end
            task.wait(LOOP_SEC)
        end
    end
    unequipTools()
    publishStatus("stopped")
end

----------------------------------------------------------------
-- API
----------------------------------------------------------------
function M.SyncFromGlobals()
    syncGlobalsFromState()
    G.AUTO_COOK_ENABLED = (AUTO_COOK_ENABLED == true)
    G.AUTO_COOK_CLAIM_ENABLED = (AUTO_COOK_CLAIM_ENABLED ~= false)
    G.AUTO_COOK_SUBMIT_ENABLED = (AUTO_COOK_SUBMIT_ENABLED ~= false)
    G.AUTO_COOK_COOK_ENABLED = (AUTO_COOK_COOK_ENABLED ~= false)
    G.AUTO_COOK_EMPTY_MISMATCH = (AUTO_COOK_EMPTY_MISMATCH == true)
    G.AUTO_COOK_RECIPES_SELECTED = AUTO_COOK_RECIPES_SELECTED or {}
    _G.AUTO_COOK_ENABLED = G.AUTO_COOK_ENABLED
    _G.AUTO_COOK_CLAIM_ENABLED = G.AUTO_COOK_CLAIM_ENABLED
    _G.AUTO_COOK_SUBMIT_ENABLED = G.AUTO_COOK_SUBMIT_ENABLED
    _G.AUTO_COOK_COOK_ENABLED = G.AUTO_COOK_COOK_ENABLED
    _G.AUTO_COOK_EMPTY_MISMATCH = G.AUTO_COOK_EMPTY_MISMATCH
    _G.AUTO_COOK_RECIPES_SELECTED = G.AUTO_COOK_RECIPES_SELECTED
end

function M.Start()
    M.SyncFromGlobals()
    if RUNNING then return end
    if not anyEnabled() then return end
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    publishStatus("stopped")
end

function M.SetEnabled(on)
    AUTO_COOK_ENABLED = (on == true)
    G.AUTO_COOK_ENABLED = AUTO_COOK_ENABLED
    _G.AUTO_COOK_ENABLED = AUTO_COOK_ENABLED
    if AUTO_COOK_ENABLED then
        M.Start()
    else
        M.Stop()
    end
end

function M.SyncFromState()
    M.SyncFromGlobals()
    if anyEnabled() then
        M.Start()
    else
        M.Stop()
    end
end

function M.IsRunning()
    return RUNNING
end

return M

