    {
        key = "AutoOpen",
        name = "Auto Open",
        factory = function()
            -- Gauto_open.lua
-- Auto open selected seed packs, crate/chest, and optional Pet Pouch.
-- Packs/chests: GameEvents.SeedPack.Open + SpinFinished
-- Cosmetic crates: CosmeticCrateService CreateCrate / OpenCrate
-- Pouch: GameEvents.PetPouchUse

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local MIN_DELAY     = 0.15
local MAX_DELAY     = 300
local DEFAULT_DELAY = 0.4
local RESULT_WAIT   = 8
local FAST_RESULT_WAIT = 1.0
local MAX_PENDING_CRATES = 8

local RUNNING    = false
local STOP_TOKEN = 0
local LAST_STATUS = "idle"
local OPENED_PACKS = 0
local OPENED_CRATES = 0
local USED_POUCH = 0

local DataService = nil
local SeedPackData = nil
local CosmeticCrates = nil
local GetFarm = nil
local OpenRemote = nil
local SpinFinishedRemote = nil
local PetPouchUseRemote = nil
local ResultRemote = nil
local CosmeticCrateService = nil

pcall(function()
    ReplicatedStorage:WaitForChild("Modules", 15)
end)
pcall(function()
    DataService = require(ReplicatedStorage.Modules.DataService)
end)
pcall(function()
    SeedPackData = require(ReplicatedStorage.Data.SeedPackData)
end)
pcall(function()
    local reg = require(ReplicatedStorage.Data.CosmeticCrateRegistry)
    CosmeticCrates = (type(reg) == "table" and (reg.CosmeticCrates or reg)) or nil
end)
pcall(function()
    if type(CosmeticCrates) ~= "table" then
        CosmeticCrates = require(ReplicatedStorage.Data.CosmeticCrateRegistry.CosmeticCrates)
    end
end)
pcall(function()
    GetFarm = require(ReplicatedStorage.Modules.GetFarm)
end)

local function bindRemotes()
    local ge = ReplicatedStorage:FindFirstChild("GameEvents")
        or ReplicatedStorage:WaitForChild("GameEvents", 15)
    if not ge then return end

    local folder = ge:FindFirstChild("SeedPack")
    if folder then
        OpenRemote = folder:FindFirstChild("Open")
        SpinFinishedRemote = folder:FindFirstChild("SpinFinished")
        ResultRemote = folder:FindFirstChild("Result")
    end
    PetPouchUseRemote = ge:FindFirstChild("PetPouchUse")
    CosmeticCrateService = ge:FindFirstChild("CosmeticCrateService")
end

pcall(bindRemotes)

AUTO_OPEN_PACK_ENABLED = (AUTO_OPEN_PACK_ENABLED == true)
AUTO_OPEN_CRATE_ENABLED = (AUTO_OPEN_CRATE_ENABLED == true)
AUTO_OPEN_POUCH_ENABLED = (AUTO_OPEN_POUCH_ENABLED == true)
AUTO_OPEN_SKIP_ANIM = (AUTO_OPEN_SKIP_ANIM ~= false)
AUTO_OPEN_DELAY_SEC = tonumber(AUTO_OPEN_DELAY_SEC) or DEFAULT_DELAY

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_OPEN_STATUS = LAST_STATUS
    _G.__AUTO_OPEN_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

function M.GetStatusText()
    local st = LAST_STATUS
    if st == "" then st = "idle" end
    return string.format(
        "Auto Open · packs %d · crates %d · pouch %d\n%s",
        OPENED_PACKS,
        OPENED_CRATES,
        USED_POUCH,
        st
    )
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_open
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function asSelectedMap(raw)
    local out = {}
    if type(raw) ~= "table" then return out end
    for k, v in pairs(raw) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        elseif type(k) == "number" and v ~= nil and tostring(v) ~= "" then
            out[tostring(v)] = true
        end
    end
    return out
end

local function selectedPacks()
    local raw = G.AUTO_OPEN_PACKS_SELECTED or _G.AUTO_OPEN_PACKS_SELECTED
    if type(raw) ~= "table" or next(raw) == nil then
        raw = getState().packs
    end
    return asSelectedMap(raw)
end

local function selectedCrates()
    local raw = G.AUTO_OPEN_CRATES_SELECTED or _G.AUTO_OPEN_CRATES_SELECTED
    if type(raw) ~= "table" or next(raw) == nil then
        raw = getState().crates
    end
    return asSelectedMap(raw)
end

local function anyEnabled()
    return AUTO_OPEN_PACK_ENABLED == true
        or AUTO_OPEN_CRATE_ENABLED == true
        or AUTO_OPEN_POUCH_ENABLED == true
end

local function syncGlobalsFromState()
    local st = getState()

    AUTO_OPEN_PACK_ENABLED = (
        G.AUTO_OPEN_PACK_ENABLED == true
        or _G.AUTO_OPEN_PACK_ENABLED == true
        or AUTO_OPEN_PACK_ENABLED == true
        or st.pack_enabled == true
    )
    AUTO_OPEN_CRATE_ENABLED = (
        G.AUTO_OPEN_CRATE_ENABLED == true
        or _G.AUTO_OPEN_CRATE_ENABLED == true
        or AUTO_OPEN_CRATE_ENABLED == true
        or st.crate_enabled == true
    )
    AUTO_OPEN_POUCH_ENABLED = (
        G.AUTO_OPEN_POUCH_ENABLED == true
        or _G.AUTO_OPEN_POUCH_ENABLED == true
        or AUTO_OPEN_POUCH_ENABLED == true
        or st.pouch_enabled == true
    )
    if G.AUTO_OPEN_SKIP_ANIM == false
        or _G.AUTO_OPEN_SKIP_ANIM == false
        or AUTO_OPEN_SKIP_ANIM == false
        or st.skip_anim == false then
        AUTO_OPEN_SKIP_ANIM = false
    else
        AUTO_OPEN_SKIP_ANIM = true
    end
    AUTO_OPEN_DELAY_SEC = clampDelay(
        G.AUTO_OPEN_DELAY_SEC or _G.AUTO_OPEN_DELAY_SEC or st.delaySec or AUTO_OPEN_DELAY_SEC
    )

    G.AUTO_OPEN_PACK_ENABLED = AUTO_OPEN_PACK_ENABLED
    G.AUTO_OPEN_CRATE_ENABLED = AUTO_OPEN_CRATE_ENABLED
    G.AUTO_OPEN_POUCH_ENABLED = AUTO_OPEN_POUCH_ENABLED
    G.AUTO_OPEN_SKIP_ANIM = AUTO_OPEN_SKIP_ANIM
    G.AUTO_OPEN_DELAY_SEC = AUTO_OPEN_DELAY_SEC
    _G.AUTO_OPEN_PACK_ENABLED = AUTO_OPEN_PACK_ENABLED
    _G.AUTO_OPEN_CRATE_ENABLED = AUTO_OPEN_CRATE_ENABLED
    _G.AUTO_OPEN_POUCH_ENABLED = AUTO_OPEN_POUCH_ENABLED
    _G.AUTO_OPEN_SKIP_ANIM = AUTO_OPEN_SKIP_ANIM
    _G.AUTO_OPEN_DELAY_SEC = AUTO_OPEN_DELAY_SEC
end

local function packsRegistry()
    return (SeedPackData and SeedPackData.Packs) or {}
end

local function cratesRegistry()
    return (type(CosmeticCrates) == "table" and CosmeticCrates) or {}
end

local function nameKind(key)
    local low = string.lower(tostring(key or ""))
    if low:find("chest", 1, true) then return "chest" end
    if low:find("crate", 1, true) then return "crate" end
    if low:find("pouch", 1, true) then return "other" end
    if low:find("seed pack", 1, true) or low:find("sack", 1, true) then return "pack" end
    if low:find("pack", 1, true) then return "pack" end
    return "other"
end

local function isChestOrCrateKey(key)
    local kind = nameKind(key)
    return kind == "chest" or kind == "crate"
end

local function isPackKey(key)
    key = tostring(key or "")
    if key == "" or not packsRegistry()[key] then return false end
    return not isChestOrCrateKey(key)
end

local function isPlantSeedTool(tool)
    if not tool then return false end
    if tool:GetAttribute("Seed") ~= nil then return true end
    local itemType = tostring(tool:GetAttribute("b") or "")
    local nm = string.lower(tool.Name)
    if itemType == "n" and nm:find("seed", 1, true) and not nm:find("pack", 1, true) then
        return true
    end
    return false
end

local function stripQtySuffix(name)
    return tostring(name or "")
        :gsub("%s*%[.-%]%s*$", "")
        :gsub("%s*x%d+%s*$", "")
        :gsub("%s+$", "")
end

local function resolvePackKey(tool)
    if not tool then return nil end
    local packs = packsRegistry()
    local n = tool:GetAttribute("n")
    if type(n) == "string" and n ~= "" then
        if packs[n] then return n end
        if packs[n .. " Seed Pack"] then return n .. " Seed Pack" end
    end

    local name = stripQtySuffix(tool.Name)
    if packs[name] then return name end
    if n and packs[tostring(n)] then return tostring(n) end

    for key, def in pairs(packs) do
        local dn = type(def) == "table" and def.DisplayName
        if dn and (dn == name or dn == n) then
            return key
        end
    end
    return nil
end

local function resolveCrateKey(tool)
    if not tool then return nil end
    local crateType = tool:GetAttribute("i")
    if type(crateType) == "string" and crateType ~= "" then
        return crateType
    end
    local name = stripQtySuffix(tool.Name)
    local crates = cratesRegistry()
    if crates[name] then return name end
    local packs = packsRegistry()
    if packs[name] and isChestOrCrateKey(name) then
        return name
    end
    local n = tool:GetAttribute("n")
    if type(n) == "string" and n ~= "" then
        if crates[n] or (packs[n] and isChestOrCrateKey(n)) then
            return n
        end
    end
    if isChestOrCrateKey(name) then
        return name
    end
    return nil
end

local function toolQty(tool)
    local e = tonumber(tool and tool:GetAttribute("e"))
    if e and e > 0 then return math.floor(e) end
    local uses = tonumber(tool and tool:GetAttribute("Uses"))
    if uses and uses > 0 then return math.floor(uses) end
    return 1
end

local function iterTools(fn)
    local function scan(container)
        if not container then return end
        for _, inst in ipairs(container:GetChildren()) do
            if inst:IsA("Tool") then
                fn(inst)
            end
        end
    end
    scan(LP and LP.Backpack)
    scan(LP and LP.Character)
end

local function isPetPouch(tool)
    if not tool then return false end
    local nm = string.lower(tool.Name)
    if nm:find("pet pouch", 1, true) then return true end
    return tool:FindFirstChild("PetPouchHandler") ~= nil
        or tool:FindFirstChild("PetPouch") ~= nil
end

local function isCosmeticCrateTool(tool)
    if not tool or isPetPouch(tool) then return false end
    if tool:FindFirstChild("CosmeticCrateToolLocal") then return true end
    local crateType = tool:GetAttribute("i")
    if type(crateType) == "string" and crateType ~= "" then return true end
    return nameKind(tool.Name) == "crate"
end

local function findPouchTool()
    local found
    iterTools(function(tool)
        if not found and isPetPouch(tool) then
            found = tool
        end
    end)
    return found
end

local function findPackTool(wanted)
    local found
    iterTools(function(tool)
        if found or isPetPouch(tool) or isCosmeticCrateTool(tool) or isPlantSeedTool(tool) then return end
        local key = resolvePackKey(tool)
        if key and isPackKey(key) and wanted[key] then
            found = tool
            return
        end
        local n = tool:GetAttribute("n")
        if n and wanted[tostring(n)] and isPackKey(n) then
            found = tool
        end
    end)
    return found
end

local function findSeedpackChestTool(wanted)
    local found
    iterTools(function(tool)
        if found or isPetPouch(tool) or isCosmeticCrateTool(tool) then return end
        local key = resolvePackKey(tool)
        if key and nameKind(key) == "chest" and wanted[key] then
            found = tool
            return
        end
        local n = tool:GetAttribute("n")
        if n and wanted[tostring(n)] and nameKind(n) == "chest" then
            found = tool
        end
    end)
    return found
end

local function findCosmeticCrateTool(wanted)
    local found
    iterTools(function(tool)
        if found or not isCosmeticCrateTool(tool) then return end
        local key = resolveCrateKey(tool)
        if key and wanted[key] then
            found = tool
        end
    end)
    return found
end

local function unequipHands()
    local ch = LP and LP.Character
    if not ch then return end
    for _, t in ipairs(ch:GetChildren()) do
        if t:IsA("Tool") then
            t.Parent = LP.Backpack
        end
    end
end

local function equipTool(tool)
    if not tool or not tool.Parent then return false end
    local ch = LP and LP.Character
    if not ch then return false end
    if tool.Parent == ch then return true end
    unequipHands()
    local ok = pcall(function()
        tool.Parent = ch
    end)
    return ok and tool.Parent == ch
end

local function waitDelay()
    local left = clampDelay(AUTO_OPEN_DELAY_SEC)
    while left > 0 and RUNNING do
        local step = math.min(0.25, left)
        task.wait(step)
        left -= step
    end
end

local function hideRollCrateUI()
    local pg = LP and LP:FindFirstChild("PlayerGui")
    local ui = pg and pg:FindFirstChild("RollCrate_UI")
    if not ui then return end
    pcall(function()
        ui.Enabled = false
        local frame = ui:FindFirstChild("Frame")
        if frame then
            frame.Visible = false
        end
    end)
end

local origSeedPackSpin = nil
local seedPackSpinHooked = false
local skipNativeSpin = false
local finishSpin

local function clickSkipButton()
    local pg = LP and LP:FindFirstChild("PlayerGui")
    local ui = pg and pg:FindFirstChild("RollCrate_UI")
    if not ui then
        return
    end
    local function fireClick(obj)
        if not obj then
            return
        end
        pcall(function()
            if obj.Activated then
                obj.Activated:Fire()
            end
        end)
        pcall(function()
            if obj.MouseButton1Click then
                obj.MouseButton1Click:Fire()
            end
        end)
    end
    local frame = ui:FindFirstChild("Frame")
    fireClick(frame and frame:FindFirstChild("Skip"))
    fireClick(ui:FindFirstChild("Skip", true))
end

local function clearPackVisuals()
    local vis = workspace:FindFirstChild("Visuals")
    if not vis then
        return
    end
    for _, ch in ipairs(vis:GetChildren()) do
        local n = tostring(ch.Name):lower()
        if n:find("seed pack", 1, true)
            or n:find("seedpack", 1, true)
            or n:find("rollcrate", 1, true)
            or n:find("crate_ui", 1, true) then
            pcall(function()
                ch:Destroy()
            end)
        end
    end
end

local function skipUiNow()
    hideRollCrateUI()
    clickSkipButton()
    clearPackVisuals()
    hideRollCrateUI()
end

local function skipAnimNow()
    skipUiNow()
    finishSpin()
    skipUiNow()
end

local function hookSeedPackSpin()
    if seedPackSpinHooked then
        return
    end
    local ctrl
    pcall(function()
        ctrl = require(ReplicatedStorage.Modules.SeedPackController)
    end)
    if type(ctrl) ~= "table" or type(ctrl.Spin) ~= "function" then
        return
    end
    origSeedPackSpin = ctrl.Spin
    ctrl.Spin = function(self, ...)
        if skipNativeSpin == true and AUTO_OPEN_SKIP_ANIM == true then
            skipAnimNow()
            return
        end
        return origSeedPackSpin(self, ...)
    end
    seedPackSpinHooked = true
end

local function waitPackResult(timeout)
    timeout = tonumber(timeout) or RESULT_WAIT
    if not ResultRemote then
        task.wait(AUTO_OPEN_SKIP_ANIM and 0.08 or 0.35)
        return false
    end
    local got = false
    local conn
    conn = ResultRemote.OnClientEvent:Connect(function()
        got = true
    end)
    local t0 = os.clock()
    while RUNNING and not got and (os.clock() - t0) < timeout do
        task.wait(0.03)
        if AUTO_OPEN_SKIP_ANIM then
            skipUiNow()
        end
    end
    if conn then
        pcall(function() conn:Disconnect() end)
    end
    return got
end

local function fireOpen(packKey)
    if not OpenRemote then
        bindRemotes()
    end
    if not OpenRemote then
        return false
    end
    return pcall(function()
        OpenRemote:FireServer(packKey)
    end)
end

function finishSpin()
    if not SpinFinishedRemote then
        bindRemotes()
    end
    if not SpinFinishedRemote then return end
    pcall(function()
        SpinFinishedRemote:FireServer()
    end)
end

local function openSeedpackItem(tool, key, ignoreRunning)
    if not tool or not key then return false end
    hookSeedPackSpin()
    skipNativeSpin = AUTO_OPEN_SKIP_ANIM == true
    publishStatus("Opening " .. key)
    if AUTO_OPEN_SKIP_ANIM then
        skipUiNow()
    end
    equipTool(tool)
    task.wait(AUTO_OPEN_SKIP_ANIM and 0.05 or 0.2)
    pcall(function()
        tool:Activate()
    end)

    local got = false
    local conn
    if ResultRemote then
        conn = ResultRemote.OnClientEvent:Connect(function()
            got = true
        end)
    end

    if not fireOpen(key) then
        if conn then
            pcall(function() conn:Disconnect() end)
        end
        skipNativeSpin = false
        publishStatus("Open failed: " .. key)
        return false
    end

    local timeout = AUTO_OPEN_SKIP_ANIM and FAST_RESULT_WAIT or RESULT_WAIT
    local t0 = os.clock()
    while (ignoreRunning or RUNNING) and not got and (os.clock() - t0) < timeout do
        task.wait(0.03)
        if AUTO_OPEN_SKIP_ANIM then
            skipUiNow()
        end
    end
    if conn then
        pcall(function() conn:Disconnect() end)
    end

    finishSpin()
    if AUTO_OPEN_SKIP_ANIM then
        for _ = 1, 8 do
            skipAnimNow()
            task.wait(0.05)
        end
    end
    skipNativeSpin = false
    return true
end

local function openOnePack(wanted)
    local tool = findPackTool(wanted)
    if not tool then
        return false, "no_pack"
    end
    local key = resolvePackKey(tool)
    if not key then
        return false, "unknown_pack"
    end
    if openSeedpackItem(tool, key) then
        OPENED_PACKS += 1
        publishStatus("Opened " .. key)
        return true, "opened"
    end
    return false, "open_failed"
end

local function openOneSeedpackChest(wanted)
    local tool = findSeedpackChestTool(wanted)
    if not tool then
        return false, "no_chest"
    end
    local key = resolvePackKey(tool)
    if not key then
        return false, "unknown_chest"
    end
    if openSeedpackItem(tool, key) then
        OPENED_CRATES += 1
        publishStatus("Opened " .. key)
        return true, "opened"
    end
    return false, "open_failed"
end

local function listedCrateInstances()
    local ok, tagged = pcall(function()
        return CollectionService:GetTagged("CosmeticCrateServer")
    end)
    if ok and type(tagged) == "table" then
        return tagged
    end
    return {}
end

local function countOwnedCrates(wanted)
    local ready, pending = 0, 0
    local owner = LP and LP.Name
    for _, inst in ipairs(listedCrateInstances()) do
        if inst and inst.Parent and inst:GetAttribute("OWNER") == owner then
            local ctype = inst:GetAttribute("CrateType")
            if ctype and wanted[tostring(ctype)] then
                local t = tonumber(inst:GetAttribute("TimeToOpen")) or 0
                if t <= 0 then
                    ready += 1
                else
                    pending += 1
                end
            end
        end
    end
    return ready, pending
end

local function openReadyCosmeticCrate(wanted)
    if not CosmeticCrateService then
        bindRemotes()
    end
    if not CosmeticCrateService then
        return false, "no_crate_remote"
    end

    local owner = LP and LP.Name
    for _, inst in ipairs(listedCrateInstances()) do
        if inst and inst.Parent and inst:GetAttribute("OWNER") == owner then
            local ctype = inst:GetAttribute("CrateType")
            if ctype and wanted[tostring(ctype)] then
                local t = tonumber(inst:GetAttribute("TimeToOpen")) or 0
                if t <= 0 then
                    publishStatus("Opening crate " .. tostring(ctype))
                    local ok = pcall(function()
                        CosmeticCrateService:FireServer("OpenCrate", inst)
                    end)
                    if ok then
                        OPENED_CRATES += 1
                        publishStatus("Opened crate " .. tostring(ctype))
                        return true, "opened"
                    end
                end
            end
        end
    end
    return false, "none_ready"
end

local function farmPlacePosition()
    if type(GetFarm) ~= "function" then return nil end
    local farm = nil
    pcall(function()
        farm = GetFarm(LP)
    end)
    if not farm then return nil end

    local plots = farm:FindFirstChild("Plant_Locations", true)
    if not plots then return nil end

    local parts = {}
    if plots:IsA("BasePart") then
        table.insert(parts, plots)
    end
    for _, inst in ipairs(plots:GetDescendants()) do
        if inst:IsA("BasePart") then
            table.insert(parts, inst)
        end
    end
    if #parts == 0 then return nil end

    local part = parts[1 + math.floor(os.clock() * 7) % #parts]
    local size = part.Size
    local ox = (math.random() - 0.5) * math.min(8, size.X * 0.6)
    local oz = (math.random() - 0.5) * math.min(8, size.Z * 0.6)
    return part.Position + Vector3.new(ox, size.Y * 0.5, oz)
end

local function placeCosmeticCrate(wanted)
    if not CosmeticCrateService then
        bindRemotes()
    end
    if not CosmeticCrateService then
        return false, "no_crate_remote"
    end

    local _, pending = countOwnedCrates(wanted)
    if pending >= MAX_PENDING_CRATES then
        return false, "pending_full"
    end

    local tool = findCosmeticCrateTool(wanted)
    if not tool then
        return false, "no_crate_tool"
    end
    local key = resolveCrateKey(tool)
    local pos = farmPlacePosition()
    if not pos then
        return false, "no_farm"
    end

    publishStatus("Placing crate " .. tostring(key or "?"))
    equipTool(tool)
    task.wait(0.2)
    local ok = pcall(function()
        CosmeticCrateService:FireServer("CreateCrate", pos)
    end)
    if not ok then
        publishStatus("Place crate failed")
        return false, "place_failed"
    end
    publishStatus("Placed crate " .. tostring(key or "?"))
    return true, "placed"
end

local function openOneCrateOrChest(wanted)
    local ok = openReadyCosmeticCrate(wanted)
    if ok then return true, "opened" end

    ok = openOneSeedpackChest(wanted)
    if ok then return true, "opened" end

    ok = placeCosmeticCrate(wanted)
    if ok then return true, "placed" end

    return false, "waiting"
end

local function pouchUsesLeft()
    if type(DataService) == "table" and type(DataService.GetData) == "function" then
        local ok, data = pcall(function()
            return DataService:GetData()
        end)
        if ok and type(data) == "table" then
            local n = tonumber(data.PetPouchUses)
            if n then return n end
        end
    end
    local tool = findPouchTool()
    if tool then
        return toolQty(tool)
    end
    return 0
end

local function usePouch()
    if not PetPouchUseRemote then
        bindRemotes()
    end
    if not PetPouchUseRemote then
        return false, "no_pouch_remote"
    end

    local tool = findPouchTool()
    if not tool and pouchUsesLeft() <= 0 then
        return false, "no_pouch"
    end

    publishStatus("Using Pet Pouch")
    if tool then
        equipTool(tool)
        task.wait(0.2)
        pcall(function()
            tool:Activate()
        end)
    end

    local ok = pcall(function()
        PetPouchUseRemote:FireServer()
    end)
    if not ok then
        publishStatus("Pet Pouch failed")
        return false, "pouch_failed"
    end
    USED_POUCH += 1
    publishStatus("Pet Pouch used")
    return true, "pouch"
end

local function buildOwnedList(kindFilter)
    local owned = {}
    iterTools(function(tool)
        if isPetPouch(tool) or isPlantSeedTool(tool) then return end
        local key
        if isCosmeticCrateTool(tool) then
            key = resolveCrateKey(tool)
        else
            key = resolvePackKey(tool)
        end
        if not key or not kindFilter(key) then return end
        owned[key] = (owned[key] or 0) + toolQty(tool)
    end)
    return owned
end

local function buildDropdown(owned, registry, kindFilter)
    local items, seen = {}, {}
    local keys = {}
    for key in pairs(owned) do
        table.insert(keys, key)
    end
    table.sort(keys)
    for _, key in ipairs(keys) do
        local def = registry[key]
        local display = (type(def) == "table" and def.DisplayName) or key
        table.insert(items, {
            key = key,
            name = string.format("%s (%d)", display, owned[key]),
        })
        seen[key] = true
    end

    local rest = {}
    for key, def in pairs(registry) do
        if not seen[key] and kindFilter(key) then
            table.insert(rest, {
                key = key,
                name = (type(def) == "table" and def.DisplayName) or key,
            })
        end
    end
    table.sort(rest, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)
    for _, it in ipairs(rest) do
        table.insert(items, it)
    end
    return items
end

function M.ListPackItems()
    return buildDropdown(
        buildOwnedList(isPackKey),
        packsRegistry(),
        isPackKey
    )
end

function M.ListCrateItems()
    local owned = buildOwnedList(isChestOrCrateKey)
    local merged = {}
    for key, def in pairs(packsRegistry()) do
        if isChestOrCrateKey(key) then
            merged[key] = def
        end
    end
    for key, def in pairs(cratesRegistry()) do
        merged[key] = def
    end
    return buildDropdown(owned, merged, isChestOrCrateKey)
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()

        if not anyEnabled() then
            publishStatus("idle")
            M.Stop()
            break
        end

        local did = false
        if AUTO_OPEN_PACK_ENABLED == true then
            local wanted = selectedPacks()
            if next(wanted) == nil then
                publishStatus("No seed pack selected")
            else
                local ok = openOnePack(wanted)
                did = ok == true
                if not ok then
                    publishStatus("Waiting for selected seed pack")
                end
            end
        end

        if AUTO_OPEN_CRATE_ENABLED == true then
            local wanted = selectedCrates()
            if next(wanted) == nil then
                publishStatus("No crate / chest selected")
            else
                local ok = openOneCrateOrChest(wanted)
                if ok then
                    did = true
                elseif not did then
                    publishStatus("Waiting for crate / chest")
                end
            end
        end

        if AUTO_OPEN_POUCH_ENABLED == true then
            local ok = usePouch()
            if ok then
                did = true
            elseif not did then
                publishStatus("No Pet Pouch")
            end
        end

        if not did then
            task.wait(math.max(1, clampDelay(AUTO_OPEN_DELAY_SEC)))
        else
            waitDelay()
        end
    end
end

function M.OpenPackByKeys(wanted)
    if type(wanted) ~= "table" or next(wanted) == nil then
        return false, "no_keys"
    end
    bindRemotes()
    hookSeedPackSpin()
    local prevSkip = AUTO_OPEN_SKIP_ANIM
    AUTO_OPEN_SKIP_ANIM = true
    local tool = findPackTool(wanted)
    local key = tool and resolvePackKey(tool)
    if not tool then
        tool = findSeedpackChestTool(wanted)
        key = tool and resolvePackKey(tool)
    end
    local ok = false
    local why = "no_pack"
    if tool then
        if key then
            ok = openSeedpackItem(tool, key, true)
            why = ok and "opened" or "open_failed"
            if ok then
                OPENED_PACKS += 1
                publishStatus("Opened " .. key)
            end
        else
            why = "unknown_pack"
        end
    end
    AUTO_OPEN_SKIP_ANIM = prevSkip
    skipNativeSpin = false
    return ok, why
end

function M.Start()
    syncGlobalsFromState()
    hookSeedPackSpin()
    if RUNNING then return end
    if not anyEnabled() then
        return
    end
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    if LAST_STATUS == "running" then
        publishStatus("idle")
    end
end

function M.SetEnabled(on)
    on = (on == true)
    if on then
        M.Start()
    else
        AUTO_OPEN_PACK_ENABLED = false
        AUTO_OPEN_CRATE_ENABLED = false
        AUTO_OPEN_POUCH_ENABLED = false
        G.AUTO_OPEN_PACK_ENABLED = false
        G.AUTO_OPEN_CRATE_ENABLED = false
        G.AUTO_OPEN_POUCH_ENABLED = false
        _G.AUTO_OPEN_PACK_ENABLED = false
        _G.AUTO_OPEN_CRATE_ENABLED = false
        _G.AUTO_OPEN_POUCH_ENABLED = false
        M.Stop()
    end
end

function M.SetDelay(sec)
    AUTO_OPEN_DELAY_SEC = clampDelay(sec)
    G.AUTO_OPEN_DELAY_SEC = AUTO_OPEN_DELAY_SEC
    _G.AUTO_OPEN_DELAY_SEC = AUTO_OPEN_DELAY_SEC
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
end

function M.SyncFromState()
    M.SyncFromGlobals()
    if anyEnabled() then
        M.Start()
    else
        M.Stop()
    end
end

G.AutoOpen = M
_G.AutoOpen = M

task.defer(function()
    pcall(hookSeedPackSpin)
end)

return M

