            -- auto_beanstalk.lua
-- Auto Event Beanstalk — Submit craving plants to Jack + claim / portal / fence
-- Separate from Harvest Moon. Remotes: ReplicatedStorage.GameEvents.Events.BeanstalkEvent

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local FIRE_WAIT  = 0.3
local MIN_DELAY  = 0.3
local MAX_DELAY  = 300
local DEFAULT_DELAY = 1
local PORTAL_MIN = 7
local FENCE_MIN = 12
local FENCE_SKIN = "SKYCASTLE"
local MAX_CLAIMS = 5
local MAX_PROGRESS = 900
local TRAIT_INTERVAL = 3600
local TRAITS = { "Berry", "Flower", "Fruit", "Leafy", "Vegetable", "Woody", "Prickly", "Stalky", "Tropical" }

local RUNNING    = false
local STOP_TOKEN = 0
local LAST_STATUS = "idle"
local LAST_FIRE_AT = 0

local PROGRESS_CUR = 0
