end)
pcall(function()
    BeanstalkCfg = require(ReplicatedStorage.Data.Events.BeanstalkEvent.BeanstalkEventConfig)
end)

if type(BeanstalkCfg) == "table" then
    MAX_PROGRESS = tonumber(BeanstalkCfg.MaxBeanstalkProgress) or MAX_PROGRESS
    MAX_CLAIMS = tonumber(BeanstalkCfg.MaxClaimedRewards) or MAX_CLAIMS
