----------------------------------------------------------------
AUTO_BEANSTALK_SUBMIT_ENABLED = (AUTO_BEANSTALK_SUBMIT_ENABLED == true)
AUTO_BEANSTALK_DELAY_SEC = tonumber(AUTO_BEANSTALK_DELAY_SEC) or DEFAULT_DELAY
AUTO_BEANSTALK_CLAIM_REWARD = (AUTO_BEANSTALK_CLAIM_REWARD == true)
AUTO_BEANSTALK_AUTO_PORTAL = (AUTO_BEANSTALK_AUTO_PORTAL == true)
AUTO_BEANSTALK_CLAIM_FENCE = (AUTO_BEANSTALK_CLAIM_FENCE == true)

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_BEANSTALK_STATUS = LAST_STATUS
    _G.__AUTO_BEANSTALK_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_beanstalk
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function syncGlobalsFromState()
    local st = getState()

    if G.AUTO_BEANSTALK_SUBMIT_ENABLED == true
        or _G.AUTO_BEANSTALK_SUBMIT_ENABLED == true
        or AUTO_BEANSTALK_SUBMIT_ENABLED == true
        or st.submit_enabled == true then
        AUTO_BEANSTALK_SUBMIT_ENABLED = true
    else
        AUTO_BEANSTALK_SUBMIT_ENABLED = false
    end

    local delaySrc = G.AUTO_BEANSTALK_DELAY_SEC
    if delaySrc == nil then delaySrc = _G.AUTO_BEANSTALK_DELAY_SEC end
    if delaySrc == nil then delaySrc = AUTO_BEANSTALK_DELAY_SEC end
    if delaySrc == nil then delaySrc = st.delaySec end
    AUTO_BEANSTALK_DELAY_SEC = clampDelay(delaySrc)

    if G.AUTO_BEANSTALK_CLAIM_REWARD == true
        or _G.AUTO_BEANSTALK_CLAIM_REWARD == true
        or AUTO_BEANSTALK_CLAIM_REWARD == true
        or st.claim_reward == true then
        AUTO_BEANSTALK_CLAIM_REWARD = true
    else
        AUTO_BEANSTALK_CLAIM_REWARD = false
    end

    if G.AUTO_BEANSTALK_AUTO_PORTAL == true
        or _G.AUTO_BEANSTALK_AUTO_PORTAL == true
        or AUTO_BEANSTALK_AUTO_PORTAL == true
        or st.auto_portal == true then
        AUTO_BEANSTALK_AUTO_PORTAL = true
    else
        AUTO_BEANSTALK_AUTO_PORTAL = false
    end

    if G.AUTO_BEANSTALK_CLAIM_FENCE == true
        or _G.AUTO_BEANSTALK_CLAIM_FENCE == true
        or AUTO_BEANSTALK_CLAIM_FENCE == true
        or st.claim_fence == true then
        AUTO_BEANSTALK_CLAIM_FENCE = true
    else
        AUTO_BEANSTALK_CLAIM_FENCE = false
    end

    G.AUTO_BEANSTALK_SUBMIT_ENABLED = AUTO_BEANSTALK_SUBMIT_ENABLED
    G.AUTO_BEANSTALK_DELAY_SEC = AUTO_BEANSTALK_DELAY_SEC
    G.AUTO_BEANSTALK_CLAIM_REWARD = AUTO_BEANSTALK_CLAIM_REWARD
    G.AUTO_BEANSTALK_AUTO_PORTAL = AUTO_BEANSTALK_AUTO_PORTAL
    G.AUTO_BEANSTALK_CLAIM_FENCE = AUTO_BEANSTALK_CLAIM_FENCE
    _G.AUTO_BEANSTALK_SUBMIT_ENABLED = AUTO_BEANSTALK_SUBMIT_ENABLED
    _G.AUTO_BEANSTALK_DELAY_SEC = AUTO_BEANSTALK_DELAY_SEC
    _G.AUTO_BEANSTALK_CLAIM_REWARD = AUTO_BEANSTALK_CLAIM_REWARD
    _G.AUTO_BEANSTALK_AUTO_PORTAL = AUTO_BEANSTALK_AUTO_PORTAL
    _G.AUTO_BEANSTALK_CLAIM_FENCE = AUTO_BEANSTALK_CLAIM_FENCE
end

local function anyEnabled()
    return AUTO_BEANSTALK_SUBMIT_ENABLED == true
        or AUTO_BEANSTALK_CLAIM_REWARD == true
        or AUTO_BEANSTALK_AUTO_PORTAL == true
        or AUTO_BEANSTALK_CLAIM_FENCE == true
end

----------------------------------------------------------------
-- Remotes / data
----------------------------------------------------------------
local function findIn(folder, name)
    if not folder or not name or name == "" then return nil end
    local inst = folder:FindFirstChild(name)
    if inst then return inst end
    for _, child in ipairs(folder:GetDescendants()) do
        if child.Name == name then
            return child
        end
    end
    return nil
end

local function resolveRemotes()
    if not FolderRemote then
        pcall(function()
            local ge = ReplicatedStorage:FindFirstChild("GameEvents")
            local events = ge and ge:FindFirstChild("Events")
            FolderRemote = events and events:FindFirstChild("BeanstalkEvent")
        end)
    end
    if not FolderRemote then return end

    SubmitAllRemote = SubmitAllRemote or findIn(FolderRemote, "BeanstalkRESubmitAllPlant")
    ClaimRewardRemote = ClaimRewardRemote or findIn(FolderRemote, "BeanstalkREClaimReward")
    ClaimFenceRemote = ClaimFenceRemote or findIn(FolderRemote, "BeanstalkREClaimFence")
    TeleportRemote = TeleportRemote or findIn(FolderRemote, "RE_BeanstalkTeleportRequest")
    ProgressRemote = ProgressRemote or findIn(FolderRemote, "RE_ClientBeanStalkProgress")
    PopulateRemote = PopulateRemote or findIn(FolderRemote, "BeanstalkREPopulate")
end

local function getPlayerData()
    if not DataService then return nil end
    local ok, data = pcall(function()
        return DataService:GetData()
    end)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end

local function getBeanstalkData()
    local data = getPlayerData()
    local ev = data and data.BeanstalkEvent
    return type(ev) == "table" and ev or nil
end

local function getContributions()
    local ev = getBeanstalkData()
    return tonumber(ev and ev.EventsContributed) or 0
end

local function getClaimedRewards()
    local ev = getBeanstalkData()
    return tonumber(ev and ev.ClaimedRewards) or 0
end

local function ownsFenceSkin()
    local data = getPlayerData()
    local owned = data and data.FenceSkinData and data.FenceSkinData.OwnedFences
    if type(owned) ~= "table" then return false end
    if owned[FENCE_SKIN] == true then return true end
    for k, v in pairs(owned) do
        if tostring(k):upper() == FENCE_SKIN and (v == true or type(v) == "table") then
            return true
        end
        if type(v) == "string" and tostring(v):upper() == FENCE_SKIN then
            return true
        end
    end
    return false
end

local function isGrown()
    return workspace:GetAttribute("ActivateBeanstalk") == true
end

local function taggedFirst(tag)
    local ok, list = pcall(function()
        return CollectionService:GetTagged(tag)
    end)
    if ok and type(list) == "table" and list[1] then
        return list[1]
    end
    return nil
end

local function getEventModel()
    return taggedFirst("BeanstalkEventModel")
end

----------------------------------------------------------------
-- Craving / progress
----------------------------------------------------------------
local function traitFromText(s)
    s = tostring(s or "")
    if s == "" then return "" end
    for _, t in ipairs(TRAITS) do
        if s:find(t, 1, true) then
            return t
        end
    end
    return ""
end

local function cravingFromBillboard()
    local model = getEventModel()
    if not model then return "" end
    local found = ""
    pcall(function()
        local bubble = model:FindFirstChild("BeanstalkBubblePart", true)
        local board = bubble and bubble:FindFirstChild("TraitRefreshBillboard")
        if not board then
            board = model:FindFirstChild("TraitRefreshBillboard", true)
        end
        if not board then return end
        for _, d in ipairs(board:GetDescendants()) do
            if d:IsA("TextLabel") or d:IsA("TextButton") then
                local hit = traitFromText(d.Text)
                if hit ~= "" then
                    found = hit
                    return
                end
            end
        end
    end)
    return found
end

local function cravingFromUtils()
    if not CravingUtils then return "" end
    local cfg = {
        Interval = TRAIT_INTERVAL,
        Options = TRAITS,
    }
    local ok, res = pcall(function()
        if type(CravingUtils.GetCurrentCraving) == "function" then
            return CravingUtils:GetCurrentCraving(cfg)
        end
        return nil
    end)
    if ok and type(res) == "string" and res ~= "" then
        return res
    end
    ok, res = pcall(function()
        return CravingUtils.GetCurrentCraving(CravingUtils, cfg)
    end)
    if ok and type(res) == "string" and res ~= "" then
        return res
    end
    return ""
end

local function getCravingTrait()
    local fromUi = cravingFromBillboard()
    if fromUi ~= "" then return fromUi end
    local fromUtils = cravingFromUtils()
    if fromUtils ~= "" then return fromUtils end
    local attr = workspace:GetAttribute("BeanstalkCraving")
        or workspace:GetAttribute("BeanstalkTrait")
        or workspace:GetAttribute("Beanstalk_Trait")
    attr = tostring(attr or "")
    if attr ~= "" and attr ~= "nil" then
        return attr
    end
    return ""
end

local function progressFromLabel()
    local sprout = taggedFirst("BeanstalkSprout")
    if not sprout then return nil, nil end
    local cur, maxN
    pcall(function()
        local gui = sprout:FindFirstChild("BeanStalkTimer", true)
        local bar = gui and (gui:FindFirstChild("UpgradeBar", true) or gui:FindFirstChildOfClass("BillboardGui"))
        local label = nil
        if bar then
            label = bar:FindFirstChild("ProgressionLabel", true)
        end
        if not label then
            label = sprout:FindFirstChild("ProgressionLabel", true)
        end
        if label and type(label.Text) == "string" then
            local a, b = label.Text:match("(%d+)%s*/%s*(%d+)")
            cur = tonumber(a)
            maxN = tonumber(b)
        end
    end)
    return cur, maxN
end

local function getProgress()
    local cur = tonumber(PROGRESS_CUR) or 0
    local maxN = tonumber(PROGRESS_MAX) or MAX_PROGRESS
    if maxN <= 0 then maxN = MAX_PROGRESS end
    if cur <= 0 then
        local a, b = progressFromLabel()
        if a then cur = a end
        if b and b > 0 then maxN = b end
    end
    if isGrown() and cur < maxN then
        cur = maxN
    end
    return cur, maxN
end

----------------------------------------------------------------
-- Tools / trait match
----------------------------------------------------------------
local function getBackpack()
    return LP:FindFirstChild("Backpack")
end

local function isFavoriteTool(tool)
    if not tool then return false end
    if tool:GetAttribute("d") == true then return true end
    if tool:GetAttribute("Favorited") == true then return true end
    if tool:GetAttribute("Favorite") == true then return true end
    if tool:GetAttribute("IsFavorite") == true then return true end
    if tool:GetAttribute("Fav") == true then return true end
    if tool:GetAttribute("fav") == true then return true end
    return false
end

local function isFruitTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    if CollectionService:HasTag(tool, "FruitTool") then return true end
    local t = tool:GetAttribute("ITEMTYPE") or tool:GetAttribute("ItemType")
    return t == "Holdable"
end

local function toolPlantName(tool)
    if not tool then return "" end
    local n = tool:GetAttribute("ItemName")
        or tool:GetAttribute("FruitName")
        or tool:GetAttribute("PlantName")
        or tool:GetAttribute("HoldableName")
    if n and tostring(n) ~= "" then return tostring(n) end
    local raw = tostring(tool.Name or "")
    return raw:gsub("%s*%[.-%]$", ""):gsub("%s*%(%d+%)$", "")
end

local function hasTraitName(plantName, trait)
    plantName = tostring(plantName or "")
    trait = tostring(trait or "")
    if plantName == "" or trait == "" then return false end
    if PlantTraitsData and type(PlantTraitsData.HasTrait) == "function" then
        local ok, res = pcall(function()
            return PlantTraitsData.HasTrait(plantName, trait)
        end)
        if ok and res == true then return true end
        ok, res = pcall(function()
            return PlantTraitsData:HasTrait(plantName, trait)
        end)
        if ok and res == true then return true end
    end
    if PlantTraitsData and type(PlantTraitsData[trait]) == "table" then
        if PlantTraitsData[trait][plantName] == true then return true end
        local want = plantName:lower()
        for k, v in pairs(PlantTraitsData[trait]) do
            if v == true and tostring(k):lower() == want then
                return true
            end
        end
    end
    return false
end

local function toolHasTrait(tool, trait)
    return hasTraitName(toolPlantName(tool), trait)
end

local function unequipTools()
    local char = LP.Character
    local bag = getBackpack()
    if not char or not bag then return end
    for _, inst in ipairs(char:GetChildren()) do
        if inst:IsA("Tool") then
            inst.Parent = bag
        end
    end
end

local function countMatchingTools(trait)
    local n = 0
    local function scan(container)
        if not container then return end
        for _, tool in ipairs(container:GetChildren()) do
            if isFruitTool(tool) and not isFavoriteTool(tool) then
                if toolHasTrait(tool, trait) then
                    n = n + 1
                end
            end
        end
    end
    scan(getBackpack())
    scan(LP.Character)
    return n
end

local function debounceOk()
    return (os.clock() - LAST_FIRE_AT) >= 0.25
end

local function markFired()
    LAST_FIRE_AT = os.clock()
end

----------------------------------------------------------------
-- Actions
----------------------------------------------------------------
local function fireSubmitAll()
    resolveRemotes()
    if not SubmitAllRemote then return false, "no SubmitAll remote" end
    local ok = pcall(function()
        SubmitAllRemote:FireServer()
    end)
    if ok then
        markFired()
        task.wait(FIRE_WAIT)
    end
    return ok, ok and "submitted all" or "submitAll fire failed"
end

local function trySubmit()
    if isGrown() then
        return false, "grown"
    end
    if not debounceOk() then
        return false, "debounce"
    end

    local trait = getCravingTrait()
    if trait == "" then
        return false, "no craving trait yet"
    end

    local n = countMatchingTools(trait)
    if n <= 0 then
        return false, ("need %s plant"):format(trait)
    end
    publishStatus(("submit all x%d [%s]"):format(n, trait))
    return fireSubmitAll()
end

local function nextClaimIndex()
    if type(CLAIM_INDICES) == "table" and #CLAIM_INDICES > 0 then
        for _, i in ipairs(CLAIM_INDICES) do
            if CLAIMED_THIS_GROW[i] ~= true then
                return i
            end
        end
        return nil
    end
    local claimed = getClaimedRewards()
    local startAt = math.max(1, claimed + 1)
    for i = startAt, MAX_CLAIMS do
        if CLAIMED_THIS_GROW[i] ~= true then
            return i
        end
    end
    return nil
end

local function tryClaimReward()
    if not isGrown() then
        return false, "waiting grow"
    end
    if getClaimedRewards() >= MAX_CLAIMS then
        return false, "claim done"
    end
    local idx = nextClaimIndex()
    if idx == nil then
        return false, "claim done"
    end
    resolveRemotes()
    if not ClaimRewardRemote then
        return false, "no ClaimReward remote"
    end
    local ok = pcall(function()
        ClaimRewardRemote:FireServer(idx)
    end)
    if ok then
        CLAIMED_THIS_GROW[idx] = true
        markFired()
        task.wait(FIRE_WAIT)
        return true, ("claimed #%d"):format(idx)
    end
    return false, "claim fire failed"
end

local function tryPortal()
    if TELEPORTED_THIS_GROW then
        return false, "portal done"
    end
    if not isGrown() then
        return false, "waiting grow"
    end
    local contrib = getContributions()
    if contrib < PORTAL_MIN then
        return false, ("portal need %d grow"):format(PORTAL_MIN)
    end
    resolveRemotes()
    if not TeleportRemote then
        return false, "no Portal remote"
    end
    local portal = taggedFirst("BeanstalkPortalModel")
    if not portal then
        return false, "no portal model"
    end
    local ok = pcall(function()
        TeleportRemote:FireServer(portal)
    end)
    if ok then
        TELEPORTED_THIS_GROW = true
        markFired()
        task.wait(FIRE_WAIT)
        return true, "teleported castle"
    end
    return false, "portal fire failed"
end

local function tryClaimFence()
    if FENCE_FIRED_THIS_GROW then
        return false, "fence done"
    end
    if ownsFenceSkin() then
        FENCE_FIRED_THIS_GROW = true
        return false, "fence owned"
    end
    if not isGrown() then
        return false, "waiting grow"
    end
    local contrib = getContributions()
    if contrib < FENCE_MIN then
        return false, ("fence need %d grow"):format(FENCE_MIN)
    end
    resolveRemotes()
    if not ClaimFenceRemote then
        return false, "no ClaimFence remote"
    end
    local ok = pcall(function()
        ClaimFenceRemote:FireServer()
    end)
    if ok then
        FENCE_FIRED_THIS_GROW = true
        markFired()
        task.wait(FIRE_WAIT)
        return true, ("claimed %s"):format(FENCE_SKIN)
    end
    return false, "fence fire failed"
end

local function resetGrowFlagsIfNeeded()
    local grown = isGrown()
    if LAST_GROWN and not grown then
        CLAIMED_THIS_GROW = {}
        TELEPORTED_THIS_GROW = false
        FENCE_FIRED_THIS_GROW = false
        CLAIM_INDICES = {}
        PROGRESS_CUR = 0
    end
    LAST_GROWN = grown
end

----------------------------------------------------------------
-- Status
----------------------------------------------------------------
function M.GetStatusText()
    syncGlobalsFromState()
    local cur, maxN = getProgress()
    local trait = getCravingTrait()
    local grown = isGrown()
    local phase = "idle"

    if grown then
        phase = "grown"
        if AUTO_BEANSTALK_CLAIM_REWARD == true and getClaimedRewards() < MAX_CLAIMS then
            if LAST_STATUS ~= "" and LAST_STATUS ~= "idle" and LAST_STATUS ~= "running" then
                phase = "grown · " .. LAST_STATUS
            else
                phase = "grown · claim"
            end
        elseif LAST_STATUS ~= "" and LAST_STATUS ~= "idle" and LAST_STATUS ~= "running" then
            phase = "grown · " .. LAST_STATUS
        end
    elseif AUTO_BEANSTALK_SUBMIT_ENABLED == true then
        if LAST_STATUS ~= "" and LAST_STATUS ~= "idle" and LAST_STATUS ~= "running" then
            phase = LAST_STATUS
        else
            phase = "waiting grow"
        end
    elseif LAST_STATUS ~= "" then
        phase = LAST_STATUS
    end

    local crave = (trait ~= "" and trait) or "—"
    return ("Beanstalk: %d/%d · craving %s · %s"):format(cur, maxN, crave, phase)
end

----------------------------------------------------------------
-- Hooks
----------------------------------------------------------------
local function hookRemotes()
    resolveRemotes()
    if ProgressRemote and not HOOKED_PROGRESS then
        local ok = pcall(function()
            ProgressRemote.OnClientEvent:Connect(function(cur, maxN)
                PROGRESS_CUR = tonumber(cur) or PROGRESS_CUR
                local n = tonumber(maxN)
                if n and n > 0 then
                    PROGRESS_MAX = n
                end
            end)
        end)
        if ok then
            HOOKED_PROGRESS = true
        end
    end
    if PopulateRemote and not HOOKED_POPULATE then
        local ok = pcall(function()
            PopulateRemote.OnClientEvent:Connect(function(list)
                CLAIM_INDICES = {}
                if type(list) == "table" then
                    for i in pairs(list) do
                        local n = tonumber(i)
                        if n then
                            CLAIM_INDICES[#CLAIM_INDICES + 1] = n
                        end
                    end
                    table.sort(CLAIM_INDICES)
                end
            end)
        end)
        if ok then
            HOOKED_POPULATE = true
        end
    end
end

----------------------------------------------------------------
-- Loop
----------------------------------------------------------------
local function worker(token)
    publishStatus("running")
    hookRemotes()
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if not anyEnabled() then
            break
        end

        resolveRemotes()
        resetGrowFlagsIfNeeded()
        local didWork = false
        local grown = isGrown()

        if AUTO_BEANSTALK_SUBMIT_ENABLED == true and not grown then
            local ok, msg = trySubmit()
            if msg then publishStatus(msg) end
            if ok then didWork = true end
        end

        if not didWork and AUTO_BEANSTALK_CLAIM_REWARD == true and grown then
            local ok, msg = tryClaimReward()
            if msg then publishStatus(msg) end
            if ok then didWork = true end
        end

        if not didWork and AUTO_BEANSTALK_AUTO_PORTAL == true and grown then
            local ok, msg = tryPortal()
            if msg then publishStatus(msg) end
            if ok then didWork = true end
        end

        if not didWork and AUTO_BEANSTALK_CLAIM_FENCE == true and grown then
            local ok, msg = tryClaimFence()
            if msg then publishStatus(msg) end
            if ok then didWork = true end
        end

        if not didWork then
            if grown then
                if LAST_STATUS == "running" or LAST_STATUS == "" then
                    publishStatus("grown")
                end
            elseif AUTO_BEANSTALK_SUBMIT_ENABLED == true then
                if LAST_STATUS == "running" or LAST_STATUS == "" then
                    publishStatus("waiting grow")
                end
            end
        end

        task.wait(clampDelay(AUTO_BEANSTALK_DELAY_SEC))
    end

    unequipTools()
    RUNNING = false
    if LAST_STATUS == "running" then
        publishStatus("stopped")
    end
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
    G.AUTO_BEANSTALK_SUBMIT_ENABLED = (AUTO_BEANSTALK_SUBMIT_ENABLED == true)
    G.AUTO_BEANSTALK_DELAY_SEC = clampDelay(AUTO_BEANSTALK_DELAY_SEC)
    G.AUTO_BEANSTALK_CLAIM_REWARD = (AUTO_BEANSTALK_CLAIM_REWARD == true)
    G.AUTO_BEANSTALK_AUTO_PORTAL = (AUTO_BEANSTALK_AUTO_PORTAL == true)
    G.AUTO_BEANSTALK_CLAIM_FENCE = (AUTO_BEANSTALK_CLAIM_FENCE == true)
    _G.AUTO_BEANSTALK_SUBMIT_ENABLED = G.AUTO_BEANSTALK_SUBMIT_ENABLED
    _G.AUTO_BEANSTALK_DELAY_SEC = G.AUTO_BEANSTALK_DELAY_SEC
    _G.AUTO_BEANSTALK_CLAIM_REWARD = G.AUTO_BEANSTALK_CLAIM_REWARD
    _G.AUTO_BEANSTALK_AUTO_PORTAL = G.AUTO_BEANSTALK_AUTO_PORTAL
    _G.AUTO_BEANSTALK_CLAIM_FENCE = G.AUTO_BEANSTALK_CLAIM_FENCE
end

function M.Start()
    M.SyncFromGlobals()
    hookRemotes()
    if RUNNING then return end
    if not anyEnabled() then return end
    RUNNING = true
    STOP_TOKEN = STOP_TOKEN + 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN = STOP_TOKEN + 1
    publishStatus("stopped")
end

function M.SetEnabled(on)
    if on == true then
        if not anyEnabled() then
            AUTO_BEANSTALK_SUBMIT_ENABLED = true
        end
    else
        AUTO_BEANSTALK_SUBMIT_ENABLED = false
        AUTO_BEANSTALK_CLAIM_REWARD = false
        AUTO_BEANSTALK_AUTO_PORTAL = false
        AUTO_BEANSTALK_CLAIM_FENCE = false
    end
    G.AUTO_BEANSTALK_SUBMIT_ENABLED = AUTO_BEANSTALK_SUBMIT_ENABLED
    G.AUTO_BEANSTALK_CLAIM_REWARD = AUTO_BEANSTALK_CLAIM_REWARD
    G.AUTO_BEANSTALK_AUTO_PORTAL = AUTO_BEANSTALK_AUTO_PORTAL
    G.AUTO_BEANSTALK_CLAIM_FENCE = AUTO_BEANSTALK_CLAIM_FENCE
    _G.AUTO_BEANSTALK_SUBMIT_ENABLED = AUTO_BEANSTALK_SUBMIT_ENABLED
    _G.AUTO_BEANSTALK_CLAIM_REWARD = AUTO_BEANSTALK_CLAIM_REWARD
    _G.AUTO_BEANSTALK_AUTO_PORTAL = AUTO_BEANSTALK_AUTO_PORTAL
    _G.AUTO_BEANSTALK_CLAIM_FENCE = AUTO_BEANSTALK_CLAIM_FENCE
    if anyEnabled() then M.Start() else M.Stop() end
end

function M.SetSubmitEnabled(on)
    AUTO_BEANSTALK_SUBMIT_ENABLED = (on == true)
    G.AUTO_BEANSTALK_SUBMIT_ENABLED = AUTO_BEANSTALK_SUBMIT_ENABLED
    _G.AUTO_BEANSTALK_SUBMIT_ENABLED = AUTO_BEANSTALK_SUBMIT_ENABLED
    if anyEnabled() then M.Start() else M.Stop() end
end

function M.SetDelay(sec)
    AUTO_BEANSTALK_DELAY_SEC = clampDelay(sec)
    G.AUTO_BEANSTALK_DELAY_SEC = AUTO_BEANSTALK_DELAY_SEC
    _G.AUTO_BEANSTALK_DELAY_SEC = AUTO_BEANSTALK_DELAY_SEC
end

function M.SetClaimReward(on)
    AUTO_BEANSTALK_CLAIM_REWARD = (on == true)
    G.AUTO_BEANSTALK_CLAIM_REWARD = AUTO_BEANSTALK_CLAIM_REWARD
    _G.AUTO_BEANSTALK_CLAIM_REWARD = AUTO_BEANSTALK_CLAIM_REWARD
    if anyEnabled() then M.Start() else M.Stop() end
end

function M.SetAutoPortal(on)
    AUTO_BEANSTALK_AUTO_PORTAL = (on == true)
    G.AUTO_BEANSTALK_AUTO_PORTAL = AUTO_BEANSTALK_AUTO_PORTAL
    _G.AUTO_BEANSTALK_AUTO_PORTAL = AUTO_BEANSTALK_AUTO_PORTAL
    if anyEnabled() then M.Start() else M.Stop() end
end

function M.SetClaimFence(on)
    AUTO_BEANSTALK_CLAIM_FENCE = (on == true)
    G.AUTO_BEANSTALK_CLAIM_FENCE = AUTO_BEANSTALK_CLAIM_FENCE
    _G.AUTO_BEANSTALK_CLAIM_FENCE = AUTO_BEANSTALK_CLAIM_FENCE
    if anyEnabled() then M.Start() else M.Stop() end
end

function M.SyncFromState()
    M.SyncFromGlobals()
    if anyEnabled() then
        M.Start()
    else
        M.Stop()
    end
end

task.defer(function()
    hookRemotes()
end)

G.AutoBeanstalk = M
_G.AutoBeanstalk = M

return M

        end,
        required = false,
