    {
        key = "AutoFallMarket",
        name = "Auto Event Fall Market",
        factory = function()
            -- auto_fall_market.lua
-- Auto Event Fall Market — SubmitAllPlants to Harvest Spirit + ClaimFallEnergyRewards
-- Remotes: ReplicatedStorage.GameEvents.Events.FallMarketEvent

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

