local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_FALL_STATUS = LAST_STATUS
    _G.__AUTO_FALL_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_fall_market
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function syncGlobalsFromState()
    local st = getState()

    if G.AUTO_FALL_SUBMIT_ENABLED == true
        or _G.AUTO_FALL_SUBMIT_ENABLED == true
        or AUTO_FALL_SUBMIT_ENABLED == true
        or st.submit_enabled == true then
        AUTO_FALL_SUBMIT_ENABLED = true
    else
        AUTO_FALL_SUBMIT_ENABLED = false
    end

    local delaySrc = G.AUTO_FALL_DELAY_SEC
    if delaySrc == nil then delaySrc = _G.AUTO_FALL_DELAY_SEC end
    if delaySrc == nil then delaySrc = AUTO_FALL_DELAY_SEC end
    if delaySrc == nil then delaySrc = st.delaySec end
    AUTO_FALL_DELAY_SEC = clampDelay(delaySrc)

    if G.AUTO_FALL_CLAIM_ENERGY == true
        or _G.AUTO_FALL_CLAIM_ENERGY == true
        or AUTO_FALL_CLAIM_ENERGY == true
        or st.claim_energy == true then
        AUTO_FALL_CLAIM_ENERGY = true
    else
        AUTO_FALL_CLAIM_ENERGY = false
    end

    if G.AUTO_FALL_PLANT_ENABLED == true
        or _G.AUTO_FALL_PLANT_ENABLED == true
        or AUTO_FALL_PLANT_ENABLED == true
        or st.plant_enabled == true then
        AUTO_FALL_PLANT_ENABLED = true
    else
        AUTO_FALL_PLANT_ENABLED = false
    end

    if G.AUTO_FALL_RECLAIM_ENABLED == true
        or _G.AUTO_FALL_RECLAIM_ENABLED == true
        or AUTO_FALL_RECLAIM_ENABLED == true
        or st.reclaim_enabled == true then
        AUTO_FALL_RECLAIM_ENABLED = true
    else
        AUTO_FALL_RECLAIM_ENABLED = false
    end

    if G.AUTO_FALL_COLLECT_ENABLED == true
        or _G.AUTO_FALL_COLLECT_ENABLED == true
        or AUTO_FALL_COLLECT_ENABLED == true
        or st.collect_enabled == true then
        AUTO_FALL_COLLECT_ENABLED = true
    else
        AUTO_FALL_COLLECT_ENABLED = false
    end

    local totalSrc = G.AUTO_FALL_PLANT_TOTAL
    if totalSrc == nil then totalSrc = _G.AUTO_FALL_PLANT_TOTAL end
    if totalSrc == nil then totalSrc = AUTO_FALL_PLANT_TOTAL end
    if totalSrc == nil then totalSrc = st.plant_total end
    AUTO_FALL_PLANT_TOTAL = math.max(0, math.floor(tonumber(totalSrc) or 10))

    local sortSrc = G.AUTO_FALL_PLANT_SORT
    if sortSrc == nil then sortSrc = _G.AUTO_FALL_PLANT_SORT end
    if sortSrc == nil then sortSrc = AUTO_FALL_PLANT_SORT end
    if sortSrc == nil then sortSrc = st.plant_sort end
    AUTO_FALL_PLANT_SORT = (tostring(sortSrc or ""):lower() == "good") and "good" or "bad"

    G.AUTO_FALL_SUBMIT_ENABLED = AUTO_FALL_SUBMIT_ENABLED
    G.AUTO_FALL_DELAY_SEC = AUTO_FALL_DELAY_SEC
    G.AUTO_FALL_CLAIM_ENERGY = AUTO_FALL_CLAIM_ENERGY
    G.AUTO_FALL_PLANT_ENABLED = AUTO_FALL_PLANT_ENABLED
    G.AUTO_FALL_RECLAIM_ENABLED = AUTO_FALL_RECLAIM_ENABLED
    G.AUTO_FALL_COLLECT_ENABLED = AUTO_FALL_COLLECT_ENABLED
    G.AUTO_FALL_PLANT_TOTAL = AUTO_FALL_PLANT_TOTAL
    G.AUTO_FALL_PLANT_SORT = AUTO_FALL_PLANT_SORT
    _G.AUTO_FALL_SUBMIT_ENABLED = AUTO_FALL_SUBMIT_ENABLED
    _G.AUTO_FALL_DELAY_SEC = AUTO_FALL_DELAY_SEC
    _G.AUTO_FALL_CLAIM_ENERGY = AUTO_FALL_CLAIM_ENERGY
    _G.AUTO_FALL_PLANT_ENABLED = AUTO_FALL_PLANT_ENABLED
    _G.AUTO_FALL_RECLAIM_ENABLED = AUTO_FALL_RECLAIM_ENABLED
    _G.AUTO_FALL_COLLECT_ENABLED = AUTO_FALL_COLLECT_ENABLED
    _G.AUTO_FALL_PLANT_TOTAL = AUTO_FALL_PLANT_TOTAL
    _G.AUTO_FALL_PLANT_SORT = AUTO_FALL_PLANT_SORT
end

local function anyEnabled()
    return AUTO_FALL_SUBMIT_ENABLED == true
        or AUTO_FALL_CLAIM_ENERGY == true
        or AUTO_FALL_PLANT_ENABLED == true
        or AUTO_FALL_RECLAIM_ENABLED == true
        or AUTO_FALL_COLLECT_ENABLED == true
end

----------------------------------------------------------------
-- Remotes
----------------------------------------------------------------
local function findIn(folder, name)
    if not folder or not name or name == "" then return nil end
    local inst = folder:FindFirstChild(name)
    if inst then return inst end
    for _, child in ipairs(folder:GetDescendants()) do
        if child.Name == name then
            return child
        end
    end
    return nil
end

local function resolveRemotes()
    if not FolderRemote then
        pcall(function()
            local ge = ReplicatedStorage:FindFirstChild("GameEvents")
            local events = ge and ge:FindFirstChild("Events")
            FolderRemote = events and events:FindFirstChild("FallMarketEvent")
        end)
    end
    if not FolderRemote then return end

    SubmitAllRemote = SubmitAllRemote or findIn(FolderRemote, "SubmitAllPlants")
    ClaimRewardRemote = ClaimRewardRemote or findIn(FolderRemote, "ClaimFallEnergyRewards")
    ProgressRemote = ProgressRemote or findIn(FolderRemote, "FallBloomProgressed")
end

