local function getFallMarketModel()
    local ok, model = pcall(function()
        local interaction = workspace:FindFirstChild("Interaction")
        return interaction and interaction:FindFirstChild("FallMarketModel")
    end)
    if ok then return model end
    return nil
end

local function stripRichText(s)
    s = tostring(s or "")
    s = s:gsub("<[^>]+>", "")
    s = s:gsub("&nbsp;", " ")
    s = s:gsub("&amp;", "&")
    s = s:gsub("&lt;", "<")
    s = s:gsub("&gt;", ">")
    return s
end

local function cravingFromBubble()
    local model = getFallMarketModel()
    if not model then return "" end
    local label = nil
    pcall(function()
        label = model
            :FindFirstChild("MrOakaly")
            and model.MrOakaly:FindFirstChild("BubblePart")
            and model.MrOakaly.BubblePart:FindFirstChild("BubbleBillboard")
            and model.MrOakaly.BubblePart.BubbleBillboard:FindFirstChild("BG")
            and model.MrOakaly.BubblePart.BubbleBillboard.BG:FindFirstChild("TextLabel")
    end)
    if not label then
        pcall(function()
            local oak = model:FindFirstChild("MrOakaly", true)
            if not oak then return end
            for _, d in ipairs(oak:GetDescendants()) do
                if d:IsA("TextLabel") or d:IsA("TextButton") then
                    local t = string.lower(stripRichText(d.Text))
                    if t:find("heartseed") or t:find("needs") then
                        label = d
                        break
                    end
                end
            end
        end)
    end
    if not label then return "" end

    local raw = stripRichText(label.Text)
    -- "The Heartseed needs Vegetable plants!"
    local trait = raw:match("[Nn]eeds%s+([%w%s%-]+)%s+plants")
        or raw:match("[Nn]eeds%s+([%w%s%-]+)")
    if not trait then return "" end
    trait = trait:gsub("^%s+", ""):gsub("%s+$", "")
    trait = trait:gsub("%s+", " ")
    return trait
end

local function getProgressionLabel()
    local model = getFallMarketModel()
    if not model then return nil end
    local label = nil
    pcall(function()
        label = model
            .MrOakaly
            .ProgressPart
            .ProgressBillboard
            .UpgradeBar
            .ProgressionLabel
    end)
    if label then return label end
    pcall(function()
        local oak = model:FindFirstChild("MrOakaly", true)
        if not oak then return end
        for _, d in ipairs(oak:GetDescendants()) do
            if d:IsA("TextLabel") or d:IsA("TextButton") then
                local t = stripRichText(d.Text)
                if t:match("%d+%s*/%s*%d+") or t:lower():find("cooldown") then
                    label = d
                    break
                end
            end
        end
    end)
    return label
end

local function parseCooldownSeconds(text)
    text = stripRichText(text)
    local m, s = text:match("[Cc]ooldown:%s*(%d+):(%d+)")
    if m then
        return (tonumber(m) or 0) * 60 + (tonumber(s) or 0), true
    end
    m, s = text:lower():match("cd%s*:?%s*(%d+):(%d+)")
    if m then
        return (tonumber(m) or 0) * 60 + (tonumber(s) or 0), true
    end
    return 0, false
end

local function progressFromBillboard()
    local label = getProgressionLabel()
    if not label then return nil, nil end
    local text = stripRichText(label.Text)
    local remain, isCd = parseCooldownSeconds(text)
    if isCd then
        CD_REMAIN = remain
        ON_EVENT_CD = true
        return 0, PROGRESS_MAX
    end
    local a, b = text:match("(%d+)%s*/%s*(%d+)")
    local cur, maxN = tonumber(a), tonumber(b)
    if maxN and maxN > 0 and cur and cur >= maxN then
        CD_REMAIN = remain
        ON_EVENT_CD = true
        return 0, maxN
    end
    if cur then
        CD_REMAIN = 0
        ON_EVENT_CD = false
    end
    return cur, maxN
end

local function fmtCountdown(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    local m = math.floor(sec / 60)
    local s = sec % 60
    return string.format("%d:%02d", m, s)
end

local function bloomsFromSign()
    local model = getFallMarketModel()
    if not model then return nil end
    local qty = nil
    pcall(function()
        qty = model
            .FallBloomsContributedSign
            .Part
            .SurfaceGui
            .Root
            .Quantity
    end)
    if qty and (qty:IsA("TextLabel") or qty:IsA("TextButton")) then
        return tonumber(tostring(qty.Text):match("%d+"))
    end
    return nil
end

local function getFallMarketData()
    if not DataService then return nil end
    local data = nil
    pcall(function()
        if type(DataService.GetData) == "function" then
            data = DataService:GetData()
        elseif type(DataService.Get) == "function" then
            data = DataService:Get()
        end
    end)
    if type(data) ~= "table" then return nil end
    local fm = data.FallMarket
    return type(fm) == "table" and fm or nil
end

local function refreshObservers()
    local cur, maxN = progressFromBillboard()
    if cur then PROGRESS_CUR = cur end
    if maxN and maxN > 0 then PROGRESS_MAX = maxN end

    local blooms = bloomsFromSign()
    if blooms ~= nil then
        BLOOMS_COUNT = blooms
    else
        local fm = getFallMarketData()
        if fm and tonumber(fm.EventsContributed) then
            BLOOMS_COUNT = tonumber(fm.EventsContributed) or BLOOMS_COUNT
        end
    end

    local craving = cravingFromBubble()
    if craving ~= "" then
        CRAVING = craving
    end
end

local function isEventCd()
    if ON_EVENT_CD then return true end
    local maxN = tonumber(PROGRESS_MAX) or 0
    local cur = tonumber(PROGRESS_CUR) or 0
    return maxN > 0 and cur >= maxN
end

local function eventCdRemain()
    if not isEventCd() then return 0 end
    local remain = tonumber(CD_REMAIN) or 0
    if remain > 0 then return remain end
    local duration = 0
    if type(FallCfg) == "table" then
        duration = tonumber(FallCfg.FallBloomDuration)
            or tonumber(FallCfg.BloomCooldown)
            or tonumber(FallCfg.FallBloomCooldown)
            or tonumber(FallCfg.CooldownDuration)
            or tonumber(FallCfg.ActivityCycleDuration)
            or 0
    end
    if duration <= 0 then return 0 end
    local fm = getFallMarketData()
    local last = fm and tonumber(fm.LastActivityCycleCompleted) or 0
    if last <= 0 then return 0 end
    local now = 0
    pcall(function()
        now = workspace:GetServerTimeNow()
    end)
    if now <= 0 then now = os.time() end
    return math.max(0, (last + duration) - now)
end

local function isEnergyClaimable()
    local fm = getFallMarketData()
    if not fm then return true end -- fire anyway; server rejects if not ready
    if fm.FallEnergyRewardClaimable == true then
        return true
    end
    return false
end

----------------------------------------------------------------
-- Actions
----------------------------------------------------------------
local function canFire()
    return (os.clock() - LAST_FIRE_AT) >= FIRE_WAIT
end

local function fireSubmitAll()
    resolveRemotes()
    if not SubmitAllRemote then
        return false, "no SubmitAll remote"
    end
    if not canFire() then
        return false, "cooldown"
    end
    local ok = pcall(function()
        SubmitAllRemote:FireServer()
    end)
    LAST_FIRE_AT = os.clock()
    if not ok then
        return false, "submit fail"
    end
    return true, "submitted"
end

local function trySubmit()
    if AUTO_FALL_SUBMIT_ENABLED ~= true then
        return false, nil
    end
    refreshObservers()
    if isEventCd() then
        return false, "event cd"
    end
    return fireSubmitAll()
end

local function tryClaimEnergy()
    if AUTO_FALL_CLAIM_ENERGY ~= true then
        return false, nil
    end
    if (os.clock() - LAST_CLAIM_AT) < CLAIM_COOLDOWN then
        return false, "claim cooldown"
    end
    if not isEnergyClaimable() then
        return false, "energy not claimable"
    end
    resolveRemotes()
    if not ClaimRewardRemote then
        return false, "no Claim remote"
    end
    local ok = pcall(function()
        ClaimRewardRemote:FireServer()
    end)
    LAST_CLAIM_AT = os.clock()
    if not ok then
        return false, "claim fail"
    end
    return true, "claimed energy"
end

----------------------------------------------------------------
-- Garden helpers / trait match
----------------------------------------------------------------
local function plantTraitsFor(name)
    name = tostring(name or "")
    if name == "" or not PlantTraitsData then return nil end
    local ok, traits = pcall(function()
        if type(PlantTraitsData.GetTraits) == "function" then
            return PlantTraitsData:GetTraits(name) or PlantTraitsData.GetTraits(name)
        end
        if type(PlantTraitsData.Get) == "function" then
            return PlantTraitsData:Get(name) or PlantTraitsData.Get(name)
        end
        if type(PlantTraitsData[name]) == "table" then
            return PlantTraitsData[name]
        end
        return nil
    end)
    if ok then return traits end
    return nil
end

local function hasTraitName(plantName, trait)
    plantName = tostring(plantName or "")
    trait = tostring(trait or "")
    if plantName == "" or trait == "" then return false end
    if plantName:lower() == trait:lower() then return true end
    if PlantTraitsData and type(PlantTraitsData.HasTrait) == "function" then
        local ok, res = pcall(function()
            return PlantTraitsData.HasTrait(plantName, trait)
        end)
        if ok and res == true then return true end
        ok, res = pcall(function()
            return PlantTraitsData:HasTrait(plantName, trait)
        end)
        if ok and res == true then return true end
    end
    if PlantTraitsData and type(PlantTraitsData[trait]) == "table" then
        if PlantTraitsData[trait][plantName] == true then return true end
        local want = plantName:lower()
        for k, v in pairs(PlantTraitsData[trait]) do
            if v == true and tostring(k):lower() == want then
                return true
            end
        end
    end
    local traits = plantTraitsFor(plantName)
    if type(traits) == "table" then
        for _, t in ipairs(traits) do
            if tostring(t):lower() == trait:lower() then
                return true
            end
        end
        for k, v in pairs(traits) do
            if type(k) == "string" and k:lower() == trait:lower() and v then
                return true
            end
            if type(v) == "string" and v:lower() == trait:lower() then
                return true
            end
        end
    end
    return false
end

local function getBackpack()
    return LP and LP:FindFirstChild("Backpack")
end

local function unequipTools()
    local char = LP.Character
    local bag = getBackpack()
    if char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            pcall(function() hum:UnequipTools() end)
        end
    end
    if not char or not bag then return end
    for _, inst in ipairs(char:GetChildren()) do
        if inst:IsA("Tool") then
            pcall(function()
                inst.Parent = bag
            end)
        end
    end
end

local function equipTool(tool)
    local char = LP.Character
    local bag = getBackpack()
    if not char or not tool then return false end
    if tool.Parent ~= bag and tool.Parent ~= char then return false end
    unequipTools()
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum:EquipTool(tool) end)
    else
        tool.Parent = char
    end
    task.wait(EQUIP_WAIT)
    return tool.Parent == char
end

local function cleanSeedName(s)
    local n = tostring(s or "")
    n = n:gsub("%s*%[.-%]$", "")
    n = n:gsub("%s*%(%d+%)$", "")
    n = n:gsub("%s+[Ss]eed%s*$", "")
    n = n:gsub("^%s+", ""):gsub("%s+$", "")
    return n
end

local function isSeedTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    local it = tostring(tool:GetAttribute("ItemType") or tool:GetAttribute("ITEM_TYPE") or ""):lower()
    if it == "seed" then return true end
    local nm = tostring(tool.Name or ""):lower()
    return nm:find("seed", 1, true) ~= nil and not nm:find("seed pack", 1, true)
end

local function seedNameOf(tool)
    if not tool then return "" end
    return cleanSeedName(tool:GetAttribute("ItemName") or tool.Name)
end

local RARITY_RANK = {
    Common = 1,
    Uncommon = 2,
    Rare = 3,
    Legendary = 4,
    Mythical = 5,
    Divine = 6,
    Prismatic = 7,
    Transcendent = 8,
}

local seedRankIndex = nil
local function buildSeedRankIndex()
    if seedRankIndex then return seedRankIndex end
    seedRankIndex = {}
    if type(SeedData) ~= "table" then return seedRankIndex end
    for key, rec in pairs(SeedData) do
        if type(rec) == "table" then
            local rank = RARITY_RANK[tostring(rec.SeedRarity or rec.Rarity or "")] or 0
            local names = {
                tostring(key),
                rec.SeedName,
                rec.ItemName,
                rec.PlantName,
            }
            for _, nm in ipairs(names) do
                local cleaned = cleanSeedName(nm)
                if cleaned ~= "" then
                    seedRankIndex[cleaned:lower()] = rank
                end
            end
        end
    end
    return seedRankIndex
end

local function seedRarityRank(seedName)
    local idx = buildSeedRankIndex()
    local cleaned = cleanSeedName(seedName)
    if cleaned == "" then return 0 end
    return tonumber(idx[cleaned:lower()]) or 0
end

local function collectTraitSeedTools(trait)
    trait = tostring(trait or "")
    local hits = {}
    if trait == "" then return hits end
    local function scan(container)
        if not container then return end
        for _, tool in ipairs(container:GetChildren()) do
            if isSeedTool(tool) then
                local sn = seedNameOf(tool)
                if sn ~= "" and hasTraitName(sn, trait) then
                    hits[#hits + 1] = { tool = tool, name = sn, rank = seedRarityRank(sn) }
                end
            end
        end
    end
    scan(LP.Character)
    scan(getBackpack())
    return hits
end

local function findTraitSeedTool(trait)
    local hits = collectTraitSeedTools(trait)
    if #hits == 0 then return nil, nil end
    local goodFirst = AUTO_FALL_PLANT_SORT == "good"
    table.sort(hits, function(a, b)
        if a.rank ~= b.rank then
            if goodFirst then
                return a.rank > b.rank
            end
            return a.rank < b.rank
        end
        return tostring(a.name):lower() < tostring(b.name):lower()
    end)
    return hits[1].tool, hits[1].name
end

local function getOwnFarm()
    local now = os.clock()
    if cachedFarm and cachedFarm.Parent and (now - cachedFarmAt) <= FARM_CACHE_SEC then
        return cachedFarm
    end
    cachedFarm = nil
    cachedFarmAt = now
    if type(GetFarmAsync) == "function" then
        local ok, farm = pcall(GetFarmAsync, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end
    local farms = workspace:FindFirstChild("Farm") or workspace:FindFirstChild("Farms")
    if farms then
        for _, farm in ipairs(farms:GetChildren()) do
            local important = farm:FindFirstChild("Important")
            local data = important and important:FindFirstChild("Data")
            local ownerVal = data and data:FindFirstChild("Owner")
            if ownerVal and (ownerVal.Value == LP.Name or tostring(ownerVal.Value) == tostring(LP.UserId)) then
                cachedFarm = farm
                return farm
            end
        end
    end
    return nil
end

local function getPlantsFolder(farm)
    farm = farm or getOwnFarm()
    if not farm then return nil end
    local important = farm:FindFirstChild("Important")
    local plants = important and important:FindFirstChild("Plants_Physical")
    if plants then return plants end
    return farm:FindFirstChild("Plants_Physical", true)
end

local function getCanPlantParts(farm)
    farm = farm or getOwnFarm()
    if not farm then return {} end
    local out = {}
    local important = farm:FindFirstChild("Important")
    local root = important or farm
    for _, desc in ipairs(root:GetDescendants()) do
        if desc:IsA("BasePart") and desc.Name == "Can_Plant" then
            out[#out + 1] = desc
        end
    end
    return out
end

local function plantGroundXZ(plant)
    if not plant then return nil end
    if plant:IsA("BasePart") then
        return plant.Position.X, plant.Position.Z
    end
    if plant:IsA("Model") then
        local ok, pivot = pcall(function() return plant:GetPivot().Position end)
        if ok and pivot then return pivot.X, pivot.Z end
        if plant.PrimaryPart then
            return plant.PrimaryPart.Position.X, plant.PrimaryPart.Position.Z
        end
    end
    local part = plant:FindFirstChildWhichIsA("BasePart", true)
    if part then return part.Position.X, part.Position.Z end
    return nil
end

local function isBlockedSpot(pos, plantsFolder, minDist)
    if not pos then return true end
    minDist = tonumber(minDist) or RANDOM_MIN_DIST
    if not plantsFolder then return false end
    local min2 = minDist * minDist
    local px, pz = pos.X, pos.Z
    for _, plant in ipairs(plantsFolder:GetChildren()) do
        local gx, gz = plantGroundXZ(plant)
        if gx and gz then
            local dx = gx - px
            local dz = gz - pz
            if (dx * dx + dz * dz) < min2 then
                return true
            end
        end
    end
    return false
end

local function randomPointOnPart(part)
    if not part then return nil end
    local size = part.Size
    local rx = (math.random() - 0.5) * size.X * RANDOM_PART_MARGIN
    local rz = (math.random() - 0.5) * size.Z * RANDOM_PART_MARGIN
    return (part.CFrame * CFrame.new(rx, size.Y * 0.5 + 0.05, rz)).Position
end

local function canPlantSignature(parts)
    local bits = {}
    for _, part in ipairs(parts) do
        local p = part.Position
        local s = part.Size
        local o = part.Orientation
        bits[#bits + 1] = string.format(
            "%s:%.1f:%.1f:%.1f:%.1f:%.1f:%.1f:%.1f",
            part:GetFullName(),
            p.X, p.Y, p.Z,
            s.X, s.Y, s.Z,
            o.Y
        )
    end
    table.sort(bits)
    return table.concat(bits, "|") .. ("#%d"):format(#parts)
end

local function nearestOtherPad(part, parts)
    local best, bestD = nil, math.huge
    for _, other in ipairs(parts) do
        if other ~= part then
            local d = (other.Position - part.Position).Magnitude
            if d < bestD then
                bestD = d
                best = other
            end
        end
    end
    return best
end

local function innerEdgeOriginLocal(part, other)
    local hx = part.Size.X * 0.5
    local hz = part.Size.Z * 0.5
    local ox, oz = 0, 0
    if other then
        local to = other.Position - part.Position
        local localTo = part.CFrame:VectorToObjectSpace(Vector3.new(to.X, 0, to.Z))
        if math.abs(localTo.X) >= math.abs(localTo.Z) then
            ox = (localTo.X >= 0 and 1 or -1) * math.max(0.2, hx - INNER_INSET)
            oz = 0
        else
            ox = 0
            oz = (localTo.Z >= 0 and 1 or -1) * math.max(0.2, hz - INNER_INSET)
        end
    else
        ox = math.max(0.2, hx - INNER_INSET)
        oz = 0
    end
    return ox, oz
end

local function innerEdgeClusterSlotsOnPad(part, other)
    local out = {}
    if not part then return out end
    local cf = part.CFrame
    local size = part.Size
    local yOff = size.Y * 0.5 + 0.05
    local limitX = math.max(0.2, size.X * 0.5 - 0.2)
    local limitZ = math.max(0.2, size.Z * 0.5 - 0.2)
    local ox, oz = innerEdgeOriginLocal(part, other)
    local stepX = math.max(1, math.ceil((limitX + math.abs(ox)) / SLOT_SPACING) + 1)
    local stepZ = math.max(1, math.ceil((limitZ + math.abs(oz)) / SLOT_SPACING) + 1)
    local scored = {}
    for dx = -stepX, stepX do
        for dz = -stepZ, stepZ do
            local lx = ox + dx * SLOT_SPACING
            local lz = oz + dz * SLOT_SPACING
            if math.abs(lx) <= limitX and math.abs(lz) <= limitZ then
                local ddx, ddz = lx - ox, lz - oz
                scored[#scored + 1] = {
                    lx = lx,
                    lz = lz,
                    d2 = ddx * ddx + ddz * ddz,
                }
            end
        end
    end
    table.sort(scored, function(a, b)
        if a.d2 ~= b.d2 then
            return a.d2 < b.d2
        end
        if a.lz ~= b.lz then
            return a.lz < b.lz
        end
        return a.lx < b.lx
    end)
    for _, s in ipairs(scored) do
        out[#out + 1] = (cf * CFrame.new(s.lx, yOff, s.lz)).Position
    end
    return out
end

local function buildInnerEdgeSlots(farm)
    local parts = getCanPlantParts(farm)
    local lists = {}
    for _, part in ipairs(parts) do
        lists[#lists + 1] = innerEdgeClusterSlotsOnPad(part, nearestOtherPad(part, parts))
    end
    local slots = {}
    local maxN = 0
    for _, list in ipairs(lists) do
        if #list > maxN then maxN = #list end
    end
    for i = 1, maxN do
        for _, list in ipairs(lists) do
            if list[i] then
                slots[#slots + 1] = list[i]
            end
        end
    end
    return slots, canPlantSignature(parts)
end

local function pickInnerEdgePlantPos(farm, plantsFolder)
    local parts = getCanPlantParts(farm)
    if #parts == 0 then
        return nil, "no Can_Plant"
    end
    local sig = canPlantSignature(parts)
    if innerSlots == nil or innerSlotSig ~= sig then
        innerSlots, innerSlotSig = buildInnerEdgeSlots(farm)
        innerSlotCursor = 1
    end
    if not innerSlots or #innerSlots == 0 then
        return nil, "no inner slot"
    end
    local n = #innerSlots
    local start = innerSlotCursor
    for i = 0, n - 1 do
        local idx = ((start - 1 + i) % n) + 1
        local pos = innerSlots[idx]
        if not isBlockedSpot(pos, plantsFolder, SLOT_SPACING) then
            innerSlotCursor = (idx % n) + 1
            return pos, nil
        end
    end
    return nil, "inner cluster full"
end

local function pickRandomPlantPos(farm, plantsFolder)
    return pickInnerEdgePlantPos(farm, plantsFolder)
end

local function cleanGardenPlantName(plant)
    if not plant then return "" end
    local n = plant:GetAttribute("ItemName")
        or plant:GetAttribute("PlantName")
        or plant:GetAttribute("SeedName")
        or plant.Name
    n = tostring(n or "")
    n = n:gsub("%s*%[.-%]$", ""):gsub("%s*%(%d+%)$", "")
    return n:gsub("^%s+", ""):gsub("%s+$", "")
end

local function countGardenTraitPlants(trait)
    trait = tostring(trait or "")
    if trait == "" then return 0 end
    local folder = getPlantsFolder()
    if not folder then return 0 end
    local n = 0
    for _, plant in ipairs(folder:GetChildren()) do
        local pname = cleanGardenPlantName(plant)
        if pname ~= "" and hasTraitName(pname, trait) then
            n += 1
        end
    end
    return n
end

local function resolvePlantRemote()
    if PlantRE and PlantRE.Parent then return true end
    local ok, rem = pcall(function()
        return ReplicatedStorage.GameEvents:FindFirstChild("Plant_RE")
    end)
    if ok and rem then
        PlantRE = rem
        return true
    end
    return false
end

local function isCollectableInst(inst)
    if not inst or not inst.Parent then return false end
    if inst:GetAttribute("Collected") == true then return false end
    if inst:GetAttribute("Favorited") == true then return false end
    if CollectionService:HasTag(inst, "Harvestable") or inst:HasTag("Harvestable") then
        return true
    end
    local prompt = inst:FindFirstChildWhichIsA("ProximityPrompt", true)
    if not prompt or prompt.Enabled ~= true then return false end
    if prompt:GetAttribute("Collected") == true then return false end
    return prompt:HasTag("CollectPrompt")
        or CollectionService:HasTag(prompt, "CollectPrompt")
end

local function collectModelFrom(inst)
    local prompt = inst:FindFirstChildWhichIsA("ProximityPrompt", true)
    if prompt and prompt.Parent and prompt.Parent.Parent then
        return prompt.Parent.Parent
    end
    return inst
end

local function resolveCollectRemote()
    if CollectCropsRE and CollectCropsRE.Parent then return true end
    local ge = ReplicatedStorage:FindFirstChild("GameEvents")
    local crops = ge and ge:FindFirstChild("Crops")
    CollectCropsRE = crops and crops:FindFirstChild("Collect")
    if CollectCropsRE then return true end
    CollectCropsRE = ge and ge:FindFirstChild("Collect", true)
    return CollectCropsRE ~= nil
end

local function getMaxHoldableCapacity()
    return math.ceil(BASE_HOLDABLE + (tonumber(LP:GetAttribute("BonusBackpackSize")) or 0))
end

local function getHoldableCount()
    local now = os.clock()
    if (now - holdableCacheAt) <= HOLDABLE_CACHE_SEC then
        return holdableCache
    end
    holdableCacheAt = now
    local n = nil
    if type(InventoryService) == "table" and type(InventoryService.Find) == "function" then
        local ok, result = pcall(function()
            return InventoryService:Find("Holdable")
        end)
        if ok and type(result) == "table" then
            local c = 0
            for _ in pairs(result) do
                c += 1
            end
            n = c
        end
    end
    if type(n) ~= "number" then
        n = 0
        local function scan(container)
            if not container then return end
            for _, inst in ipairs(container:GetChildren()) do
                if inst:IsA("Tool") then
                    n += 1
                end
            end
        end
        scan(LP:FindFirstChild("Backpack"))
        scan(LP.Character)
    end
    holdableCache = n
    return n
end

local function tryCollectEvent()
    if AUTO_FALL_COLLECT_ENABLED ~= true then
        return 0, nil
    end
    local trait = CRAVING
    if trait == "" then
        trait = cravingFromBubble()
        CRAVING = trait
    end
    if trait == "" then
        return 0, "no craving trait yet"
    end
    local plantsFolder = getPlantsFolder()
    if not plantsFolder then
        return 0, "no own farm"
    end
    if not resolveCollectRemote() then
        return 0, "no Collect remote"
    end

    local cap = getMaxHoldableCapacity()
    local used = getHoldableCount()
    local stopAt = math.max(1, math.floor(cap * COLLECT_BAG_STOP))
    if used >= stopAt then
        return 0, ("backpack %d/%d (80%%)"):format(used, cap)
    end
    local room = stopAt - used
    local maxBatch = math.min(COLLECT_BATCH, room)

    local batch = {}
    local seen = {}
    local plants = plantsFolder:GetChildren()
    for i = 1, #plants do
        if #batch >= maxBatch then break end
        local plant = plants[i]
        local pname = cleanGardenPlantName(plant)
        if pname ~= "" and hasTraitName(pname, trait) then
            local fruitsFolder = plant:FindFirstChild("Fruits")
            if fruitsFolder then
                local fruits = fruitsFolder:GetChildren()
                for j = 1, #fruits do
                    if #batch >= maxBatch then break end
                    local fruit = fruits[j]
                    if isCollectableInst(fruit) then
                        local model = collectModelFrom(fruit)
                        if model and not seen[model] then
                            seen[model] = true
                            batch[#batch + 1] = model
                        end
                    end
                end
            elseif isCollectableInst(plant) then
                local model = collectModelFrom(plant)
                if model and not seen[model] then
                    seen[model] = true
                    batch[#batch + 1] = model
                end
            end
        end
    end

    if #batch == 0 then
        return 0, nil
    end
    local ok = pcall(function()
        CollectCropsRE:FireServer(batch)
    end)
    if not ok then
        return 0, "collect fire failed"
    end
    LAST_COLLECT_STATUS = ("collected %d [%s]"):format(#batch, trait)
    holdableCache = used + #batch
    holdableCacheAt = os.clock()
    return #batch, LAST_COLLECT_STATUS
end

local function tryPlantOne()
    if AUTO_FALL_PLANT_ENABLED ~= true then
        return false, nil
    end
    local trait = CRAVING
    if trait == "" then
        trait = cravingFromBubble()
        CRAVING = trait
    end
    if trait == "" then
        return false, "no craving trait yet"
    end

    local total = AUTO_FALL_PLANT_TOTAL
    local gardenN = countGardenTraitPlants(trait)
    if total > 0 and gardenN >= total then
        pcall(unequipTools)
        return false, ("garden full %d/%d [%s]"):format(gardenN, total, trait)
    end

    -- pilih seed dulu (sort rarity), baru cari slot / equip / plant
    local tool, seedName = findTraitSeedTool(trait)
    if not tool or not seedName then
        return false, ("no %s seed"):format(trait)
    end

    local farm = getOwnFarm()
    if not farm then
        return false, "no own farm"
    end
    local plantsFolder = getPlantsFolder(farm)
    local pos, posErr = pickRandomPlantPos(farm, plantsFolder)
    if not pos then
        return false, posErr or "no empty slot"
    end
    if not equipTool(tool) then
        pcall(unequipTools)
        return false, "equip seed failed"
    end
    if not resolvePlantRemote() then
        pcall(unequipTools)
        return false, "no Plant_RE"
    end
    local ok = pcall(function()
        PlantRE:FireServer(pos, seedName)
    end)
    task.wait(0.15)
    pcall(unequipTools)
    if not ok then
        return false, "plant fire failed"
    end
    local gardenAfter = countGardenTraitPlants(trait)
    LAST_PLANT_STATUS = ("planted %s · garden %d/%s [%s]"):format(
        seedName,
        gardenAfter,
        total > 0 and tostring(total) or "∞",
        trait
    )
    if total > 0 and gardenAfter >= total then
        pcall(unequipTools)
    end
    return true, LAST_PLANT_STATUS
end

local function usesAttrKey()
    if type(InventoryServiceEnums) == "table" and InventoryServiceEnums.Uses ~= nil then
        return InventoryServiceEnums.Uses
    end
    return "Uses"
end

local function findReclaimerTool()
    local function scan(container)
        if not container then return nil end
        for _, tool in ipairs(container:GetChildren()) do
            if tool:IsA("Tool") then
                local n = tostring(tool.Name or ""):lower()
                if n:find("reclaimer", 1, true) then
                    return tool
                end
            end
        end
        return nil
    end
    return scan(LP.Character) or scan(getBackpack())
end

local function getReclaimerUses()
    local tool = findReclaimerTool()
    if not tool then return 0, nil end
    local uses = tonumber(tool:GetAttribute(usesAttrKey())) or 1
    return uses, tool
end

local function ensureReclaimerEquipped()
    local tool = findReclaimerTool()
    if not tool then return false end
    return equipTool(tool)
end

local function hasFavoritedFruit(plant)
    local fruits = plant:FindFirstChild("Fruits")
    if not fruits then return false end
    for _, child in ipairs(fruits:GetChildren()) do
        if child:GetAttribute("Favorited") == true then
            return true
        end
    end
    return false
end

local function isFullyGrown(plant)
    local maxAge = plant:GetAttribute("MaxAge")
    local grow = plant:FindFirstChild("Grow")
    local age = grow and grow:FindFirstChild("Age")
    if maxAge == nil or not age or not age:IsA("NumberValue") then
        return false
    end
    return age.Value >= maxAge
end

local function isReclaimEligible(plant, plantsFolder, trait)
    if not plant or not plant.Parent then return false end
    local name = cleanGardenPlantName(plant)
    if name == "" or BLOCKLIST[name] or BLOCKLIST[plant.Name] then
        return false
    end
    if CollectionService:HasTag(plant, "Harvestable") or plant:HasTag("Harvestable") then
        return false
    end
    if plantsFolder and not plant:IsDescendantOf(plantsFolder) then
        return false
    end
    if not plant:FindFirstChild("Grow") then
        return false
    end
    if plant:GetAttribute("Favorited") == true or hasFavoritedFruit(plant) then
        return false
    end
    if not isFullyGrown(plant) then
        return false
    end
    if trait ~= "" and hasTraitName(name, trait) then
        return false
    end
    return true, name
end

local function resolveReclaimerRemote()
    if ReclaimerRE and ReclaimerRE.Parent then return true end
    local ge = ReplicatedStorage:FindFirstChild("GameEvents")
    if not ge then return false end
    ReclaimerRE = ge:FindFirstChild("ReclaimerService_RE")
    return ReclaimerRE ~= nil
end

local function tryReclaimOne()
    if AUTO_FALL_RECLAIM_ENABLED ~= true then
        return false, nil
    end
    local trait = CRAVING
    if trait == "" then
        trait = cravingFromBubble()
        CRAVING = trait
    end
    if trait == "" then
        return false, "no craving trait yet"
    end

    local uses, tool = getReclaimerUses()
    if not tool then
        return false, "no Reclaimer tool"
    end
    if uses <= 0 then
        return false, "Reclaimer uses 0"
    end

    local plantsFolder = getPlantsFolder()
    if not plantsFolder then
        return false, "no own farm"
    end
    local target, targetName = nil, nil
    for _, plant in ipairs(plantsFolder:GetChildren()) do
        local ok, name = isReclaimEligible(plant, plantsFolder, trait)
        if ok then
            target = plant
            targetName = name
            break
        end
    end
    if not target then
        return false, "no leftover plant"
    end
    if not ensureReclaimerEquipped() then
        return false, "equip reclaimer failed"
    end
    if not resolveReclaimerRemote() then
        return false, "no Reclaimer remote"
    end
    local ok = pcall(function()
        ReclaimerRE:FireServer("TryReclaim", target)
    end)
    if not ok then
        return false, "reclaim fire failed"
    end
    LAST_RECLAIM_STATUS = ("reclaimed %s"):format(tostring(targetName or "?"))
    return true, LAST_RECLAIM_STATUS
end

----------------------------------------------------------------
-- Status
----------------------------------------------------------------
function M.GetStatusText()
    refreshObservers()
    local cur = tonumber(PROGRESS_CUR) or 0
    local maxN = tonumber(PROGRESS_MAX) or MAX_PROGRESS
    local blooms = tonumber(BLOOMS_COUNT) or 0
    local need = (CRAVING ~= "" and CRAVING) or "—"
    local gardenN = 0
    if CRAVING ~= "" then
        pcall(function()
            gardenN = countGardenTraitPlants(CRAVING)
        end)
    end
    local total = AUTO_FALL_PLANT_TOTAL
    local plantOn = AUTO_FALL_PLANT_ENABLED == true and "ON" or "OFF"
    local reclaimOn = AUTO_FALL_RECLAIM_ENABLED == true and "ON" or "OFF"
    local collectOn = AUTO_FALL_COLLECT_ENABLED == true and "ON" or "OFF"
    local phase = "idle"
    local onCd = isEventCd()

    if onCd then
        cur = 0
        local remain = eventCdRemain()
        if remain > 0 then
            phase = "event cd " .. fmtCountdown(remain)
        else
            phase = "event cd"
        end
        return ("Fall: %d/%d · %s · need %s · garden %d/%s · blooms %d\nPlant %s · Collect %s · Reclaimer %s"):format(
            cur,
            maxN,
            phase,
            need,
            gardenN,
            total > 0 and tostring(total) or "∞",
            blooms,
            plantOn,
            collectOn,
            reclaimOn
        )
    elseif RUNNING then
        if LAST_STATUS ~= "" and LAST_STATUS ~= "idle" and LAST_STATUS ~= "running" then
            phase = LAST_STATUS
        elseif AUTO_FALL_COLLECT_ENABLED == true then
            phase = "collect"
        elseif AUTO_FALL_PLANT_ENABLED == true then
            phase = "plant"
        elseif AUTO_FALL_RECLAIM_ENABLED == true then
            phase = "reclaim"
        elseif AUTO_FALL_SUBMIT_ENABLED == true then
            phase = "submitting"
        elseif AUTO_FALL_CLAIM_ENERGY == true then
            phase = "claim"
        else
            phase = "running"
        end
    elseif LAST_STATUS ~= "" and LAST_STATUS ~= "idle" then
        phase = LAST_STATUS
    end

    return ("Fall: %d/%d · need %s · garden %d/%s · blooms %d\nPlant %s · Collect %s · Reclaimer %s · %s"):format(
        cur,
        maxN,
        need,
        gardenN,
        total > 0 and tostring(total) or "∞",
        blooms,
        plantOn,
        collectOn,
        reclaimOn,
        phase
    )
end

----------------------------------------------------------------
-- Hooks
----------------------------------------------------------------
local function hookRemotes()
    resolveRemotes()
    if ProgressRemote and not HOOKED_PROGRESS then
        local ok = pcall(function()
            ProgressRemote.OnClientEvent:Connect(function(cur, maxN)
                local c = tonumber(cur)
                if c then PROGRESS_CUR = c end
                local m = tonumber(maxN)
                if m and m > 0 then PROGRESS_MAX = m end
            end)
        end)
        if ok then
            HOOKED_PROGRESS = true
        end
    end
end

----------------------------------------------------------------
-- Loop
----------------------------------------------------------------
local function worker(token)
    publishStatus("running")
    hookRemotes()
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if not anyEnabled() then
            break
        end

        resolveRemotes()
        refreshObservers()
        local didWork = false
        local collectBusy = false

        if AUTO_FALL_COLLECT_ENABLED == true then
            local n, msg = tryCollectEvent()
            n = tonumber(n) or 0
            if n > 0 then
                if msg then publishStatus(msg) end
                didWork = true
                collectBusy = n >= COLLECT_BATCH
            elseif msg == "no craving trait yet" then
                -- skip
            elseif type(msg) == "string" and msg:find("backpack", 1, true) then
                if LAST_STATUS ~= msg then
                    publishStatus(msg)
                end
            else
                if not didWork then publishStatus(msg) end
            end
        end

        if AUTO_FALL_PLANT_ENABLED == true then
            local ok, msg = tryPlantOne()
            if ok then
                if msg then publishStatus(msg) end
                didWork = true
            elseif msg and msg ~= "garden full" and not tostring(msg):find("garden full", 1, true) then
                if not didWork then publishStatus(msg) end
            end
        end

        if AUTO_FALL_RECLAIM_ENABLED == true then
            local ok, msg = tryReclaimOne()
            if ok then
                if msg then publishStatus(msg) end
                didWork = true
            elseif msg and msg ~= "no leftover plant" and msg ~= "no craving trait yet" then
                if not didWork then publishStatus(msg) end
            end
        end

        if AUTO_FALL_SUBMIT_ENABLED == true then
            local ok, msg = trySubmit()
            if msg then publishStatus(msg) end
            if ok then didWork = true end
        end

        if AUTO_FALL_CLAIM_ENERGY == true then
            local ok, msg = tryClaimEnergy()
            if ok then
                if msg then publishStatus(msg) end
                didWork = true
            elseif msg and not didWork and msg ~= "energy not claimable" and msg ~= "claim cooldown" then
                publishStatus(msg)
            end
        end

        if not didWork then
            if AUTO_FALL_SUBMIT_ENABLED == true then
                if LAST_STATUS == "running" or LAST_STATUS == "" then
                    publishStatus("waiting")
                end
            elseif LAST_STATUS == "running" or LAST_STATUS == "" then
                publishStatus("idle")
            end
        end

        if collectBusy then
            task.wait(COLLECT_FAST_WAIT)
        else
            task.wait(clampDelay(AUTO_FALL_DELAY_SEC))
        end
    end

    pcall(unequipTools)
    RUNNING = false
    if LAST_STATUS == "running" then
        publishStatus("stopped")
    end
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
    G.AUTO_FALL_SUBMIT_ENABLED = (AUTO_FALL_SUBMIT_ENABLED == true)
    G.AUTO_FALL_DELAY_SEC = clampDelay(AUTO_FALL_DELAY_SEC)
    G.AUTO_FALL_CLAIM_ENERGY = (AUTO_FALL_CLAIM_ENERGY == true)
    G.AUTO_FALL_PLANT_ENABLED = (AUTO_FALL_PLANT_ENABLED == true)
    G.AUTO_FALL_RECLAIM_ENABLED = (AUTO_FALL_RECLAIM_ENABLED == true)
    G.AUTO_FALL_COLLECT_ENABLED = (AUTO_FALL_COLLECT_ENABLED == true)
    G.AUTO_FALL_PLANT_TOTAL = math.max(0, math.floor(tonumber(AUTO_FALL_PLANT_TOTAL) or 10))
    G.AUTO_FALL_PLANT_SORT = (tostring(AUTO_FALL_PLANT_SORT or ""):lower() == "good") and "good" or "bad"
    _G.AUTO_FALL_SUBMIT_ENABLED = G.AUTO_FALL_SUBMIT_ENABLED
    _G.AUTO_FALL_DELAY_SEC = G.AUTO_FALL_DELAY_SEC
    _G.AUTO_FALL_CLAIM_ENERGY = G.AUTO_FALL_CLAIM_ENERGY
    _G.AUTO_FALL_PLANT_ENABLED = G.AUTO_FALL_PLANT_ENABLED
    _G.AUTO_FALL_RECLAIM_ENABLED = G.AUTO_FALL_RECLAIM_ENABLED
    _G.AUTO_FALL_COLLECT_ENABLED = G.AUTO_FALL_COLLECT_ENABLED
    _G.AUTO_FALL_PLANT_TOTAL = G.AUTO_FALL_PLANT_TOTAL
    _G.AUTO_FALL_PLANT_SORT = G.AUTO_FALL_PLANT_SORT
end

function M.Start()
    M.SyncFromGlobals()
    hookRemotes()
    if RUNNING then return end
    if not anyEnabled() then return end
    RUNNING = true
    STOP_TOKEN = STOP_TOKEN + 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN = STOP_TOKEN + 1
    pcall(unequipTools)
    publishStatus("stopped")
end

