local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_halloween_event
    if type(st) == "table" then
        return st
    end
    local STATE = rawget(_G, "STATE") or G.STATE
    st = STATE and STATE.main and STATE.main.misc and STATE.main.misc.auto_halloween_event
    if type(st) ~= "table" then
        st = STATE and STATE.misc and STATE.misc.auto_halloween_event
    end
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function asSet(src)
    local map = {}
    if type(src) ~= "table" then
        return map
    end
    if src[1] ~= nil then
        for _, k in ipairs(src) do
            if k ~= nil and k ~= "" then
                map[tostring(k)] = true
            end
        end
    else
        for k, v in pairs(src) do
            if v == true or v == 1 then
                map[tostring(k)] = true
            end
        end
    end
    return map
end

local function flagOn(globalName, stKey, defaultOn)
    local st = getState()
    if G[globalName] == true or _G[globalName] == true or st[stKey] == true then
        return true
    end
    if defaultOn == true and G[globalName] ~= false and _G[globalName] ~= false and st[stKey] ~= false then
        if G[globalName] == nil and _G[globalName] == nil and st[stKey] == nil then
            return true
        end
    end
    return false
end

