    _G.AUTO_HALLOWEEN_SWAP_NORMAL = AUTO_HALLOWEEN_SWAP_NORMAL
    _G.AUTO_HALLOWEEN_OPEN_PACK = AUTO_HALLOWEEN_OPEN_PACK
