local function getData()
    if type(DataService) ~= "table" or type(DataService.GetData) ~= "function" then
        return nil
    end
    local ok, data = pcall(function()
        return DataService:GetData()
    end)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end

local function candyCorn()
    local data = getData()
    if not data then
        return 0
    end
    local sc = data.SpecialCurrency
    if type(sc) == "table" then
        return tonumber(sc.CandyCorn or sc.candyCorn) or 0
    end
    return tonumber(data.CandyCorn) or 0
end

local function eventIndex()
    if type(EventRotationUtils) ~= "table" then
        return 1
    end
    local ok, ev = pcall(function()
        return EventRotationUtils:GetCurrentEvent()
    end)
    if not ok or type(ev) ~= "table" then
        return 1
    end
    return tonumber(ev.EventIndex or ev.Index) or 1
end

local function isHalloweenEvent()
    if type(EventRotationUtils) ~= "table" then
        return true
    end
    local ok, ev = pcall(function()
        return EventRotationUtils:GetCurrentEvent()
    end)
    if not ok or not ev then
        return false
    end
    local set = ev.EventSet or ev.EventID or ev.Id
    set = tostring(set or "")
    return set:find("Halloween2026", 1, true) ~= nil
end

local function isHalloweenGarden()
    local slot = LP and LP:GetAttribute("SelectedSlot")
    if slot == SLOT_KEY then
        return true
    end
    local data = getData()
    local ss = data and data.SaveSlots
    if type(ss) == "table" and tostring(ss.SelectedSlot) == SLOT_KEY then
        return true
    end
    return false
end

local function isEventSlotKey(key)
    local k = tostring(key or ""):upper()
    if k == "" or k == SLOT_KEY then
        return true
    end
    return k:find("HALLOWEEN", 1, true) ~= nil
        or k:find("BEE", 1, true) ~= nil
        or k:find("EASTER", 1, true) ~= nil
end

local function bindChangeSlots()
    if ChangeSlotsRE then
        return ChangeSlotsRE
    end
    pcall(function()
        local ss = ge() and ge():FindFirstChild("SaveSlotService")
        ChangeSlotsRE = ss and ss:FindFirstChild("RequestChangeSlots")
    end)
    return ChangeSlotsRE
end

local function currentSlotKey()
    local slot = LP and LP:GetAttribute("SelectedSlot")
    if slot ~= nil and tostring(slot) ~= "" then
        return tostring(slot)
    end
    local data = getData()
    local ss = data and data.SaveSlots
    if type(ss) == "table" and ss.SelectedSlot ~= nil then
        return tostring(ss.SelectedSlot)
    end
    return ""
end

local function trimStr(s)
    return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

local function slotDisplayName(key, rec)
    if type(rec) ~= "table" then
        rec = nil
        local data = getData()
        local all = data and data.SaveSlots and data.SaveSlots.AllSlots
        if type(all) == "table" then
            rec = all[key]
        end
    end
    local shown = ""
    pcall(function()
        local ctrl = require(ReplicatedStorage.Modules.SaveSlotControllers.SaveSlotController)
        if type(ctrl) == "table" and type(ctrl.GetSlotDisplayName) == "function" then
            shown = trimStr(ctrl:GetSlotDisplayName(key))
        end
    end)
    if shown ~= "" then
        return shown
    end
    if type(rec) == "table" then
        local n = trimStr(rec.DisplayName or rec.SlotName or rec.Name)
        if n ~= "" then
            return n
        end
    end
    return "Save Slot"
end

local function isNormalGardenSlot(key, rec)
    if isEventSlotKey(key) then
        return false
    end
    if type(rec) == "table" then
        if rec.IsHalloweenSlot or rec.IsBeeSlot or rec.IsEasterSlot then
            return false
        end
    end
    return true
end

local function listNormalSlots()
    local out = {}
    local data = getData()
    local ss = data and data.SaveSlots
    local all = ss and ss.AllSlots
    local seen = {}
    if type(all) == "table" then
        local keys = {}
        for k, rec in pairs(all) do
            if isNormalGardenSlot(k, rec) then
                keys[#keys + 1] = tostring(k)
            end
        end
        table.sort(keys)
        for i = 1, #keys do
            local k = keys[i]
            seen[k] = true
            out[#out + 1] = { key = k, name = slotDisplayName(k, all[k]) }
        end
    end
    if #out == 0 then
        out[1] = { key = "DEFAULT", name = "Save Slot" }
    end
    return out
end

function M.GetNormalSlotItems()
    return listNormalSlots()
end

local function normalSlotKey()
    local want = tostring(AUTO_HALLOWEEN_NORMAL_SLOT or "DEFAULT")
    if want == "" or isEventSlotKey(want) then
        want = "DEFAULT"
    end
    local data = getData()
    local ss = data and data.SaveSlots
    local all = ss and ss.AllSlots
    if type(all) == "table" then
        if all[want] ~= nil and isNormalGardenSlot(want, all[want]) then
            return want
        end
        if all.DEFAULT ~= nil then
            return "DEFAULT"
        end
        for k, slot in pairs(all) do
            if isNormalGardenSlot(k, slot) then
                return tostring(k)
            end
        end
    end
    return want ~= "" and want or "DEFAULT"
end

local function sharkWaitingBite()
    local txt = tostring(G.__SHARK_STATUS_TEXT or _G.__SHARK_STATUS_TEXT or "")
    return txt:lower():find("waiting bite", 1, true) ~= nil
end

local function getHrp()
    local char = LP and LP.Character
    return char and char:FindFirstChild("HumanoidRootPart")
end

local function distTo(pos)
    local hrp = getHrp()
    if not hrp or not pos then
        return 1e9
    end
    local d = hrp.Position - pos
    return math.sqrt(d.X * d.X + d.Z * d.Z)
end

local GARDEN_ACT_RANGE = 80

local function nearOwnGarden()
    local pos = gardenCenterPos()
    if not pos then
        return false
    end
    return distTo(pos) <= GARDEN_ACT_RANGE
end

local function gardenWorkAllowed()
    return true
end

local function goNear(pos, range)
    if sharkWaitingBite() then
        return false
    end
    local hrp = getHrp()
    if not hrp or not pos then
        return false
    end
    range = range or 14
    if distTo(pos) <= range then
        return true
    end
    hrp.CFrame = CFrame.new(pos.X, hrp.Position.Y, pos.Z)
    task.wait(0.2)
    return distTo(pos) <= range + 6
end

local function unequipTools()
    local char = LP and LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end
end

local function invalidateFarmCache()
    cachedFarm = nil
    cachedFarmAt = 0
    hwPlantSlots = nil
    hwPlantSlotSig = nil
end

pcall(function()
    if LP then
        LP:GetAttributeChangedSignal("SelectedSlot"):Connect(function()
            invalidateFarmCache()
        end)
    end
end)

local function getOwnFarm()
    local now = os.clock()
    if cachedFarm and cachedFarm.Parent and (now - cachedFarmAt) <= 1.2 then
        return cachedFarm
    end
    cachedFarmAt = now
    cachedFarm = nil
    if type(GetFarmAsync) == "function" then
        local ok, farm = pcall(GetFarmAsync, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end
    local farms = workspace:FindFirstChild("Farm") or workspace:FindFirstChild("Farms")
    if not farms then
        return nil
    end
    local username = LP and LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local ok, owner = pcall(function()
            return farm.Important.Data.Owner.Value
        end)
        if ok and owner == username then
            cachedFarm = farm
            return farm
        end
    end
    return nil
end

local function getPlantsFolder(farm)
    farm = farm or getOwnFarm()
    if not farm then
        return nil
    end
    local important = farm:FindFirstChild("Important")
    return important and important:FindFirstChild("Plants_Physical")
end

local function gardenCenterPos()
    local farm = getOwnFarm()
    if not farm then
        return nil
    end
    local ok, pivot = pcall(function()
        return farm:GetPivot().Position
    end)
    if ok then
        return pivot
    end
    return nil
end

local function hasPlantTrait(name, trait)
    if type(PlantTraitsData) ~= "table" or type(PlantTraitsData.HasTrait) ~= "function" then
        return false
    end
    local ok, has = pcall(function()
        return PlantTraitsData.HasTrait(name, trait)
    end)
    return ok and has == true
end

local function hasHalloweenTrait(name)
    name = tostring(name or "")
    if name == "" then
        return false
    end
    if hasPlantTrait(name, "HalloweenSlot") then
        return true
    end
    for i = 1, #HW_PLANTS do
        if HW_PLANTS[i]:lower() == name:lower() then
            return true
        end
    end
    return name:lower():find("halloween", 1, true) ~= nil
end

local function hasSpookyTrait(name)
    name = tostring(name or "")
    if name == "" then
        return false
    end
    if hasPlantTrait(name, "Spooky") then
        return true
    end
    return name:lower():gsub("^halloween%s+", "") == "ghost bush"
end

local function cleanName(s)
    local n = tostring(s or "")
    n = n:gsub("%b[]", " "):gsub("%b()", " ")
    n = n:gsub("[%d%.]+%s*[kK][gG]", " ")
    n = n:gsub("%s+[Ss]eed%s*$", "")
    return n:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
end

local function toolItemName(tool)
    if not tool then
        return ""
    end
    return cleanName(
        tool:GetAttribute("ItemName")
            or tool:GetAttribute("ITEM_NAME")
            or tool:GetAttribute("f")
            or tool:GetAttribute("PlantName")
            or tool.Name
    )
end

local function toolItemType(tool)
    if not tool then
        return ""
    end
    return tostring(
        tool:GetAttribute("ItemType")
            or tool:GetAttribute("ITEM_TYPE")
            or tool:GetAttribute("b")
            or ""
    ):lower()
end

local function toolWeight(tool)
    if not tool then
        return 0
    end
    local w = tool:GetAttribute("Weight") or tool:GetAttribute("KG") or tool:GetAttribute("WeightKg")
    w = tonumber(w)
    if w then
        return w
    end
    local child = tool:FindFirstChild("Weight")
    if child then
        w = tonumber(child.Value)
        if w then
            return w
        end
    end
    local nm = tostring(tool.Name or "")
    local kg = nm:match("([%d%.]+)%s*[kK][gG]")
    return tonumber(kg) or 0
end

local function toolHasMutation(tool, mut)
    if not mut or mut == "" then
        return true
    end
    local want = tostring(mut):lower()
    local attrs = {}
    pcall(function()
        attrs = tool:GetAttributes()
    end)
    for k, v in pairs(attrs) do
        if tostring(v) == true or v == true then
            if tostring(k):lower() == want then
                return true
            end
        end
        if tostring(v):lower() == want then
            return true
        end
    end
    return tostring(tool.Name or ""):lower():find(want, 1, true) ~= nil
end

local function isFavorited(tool)
    if not tool then
        return false
    end
    if tool:GetAttribute("Favorited") == true or tool:GetAttribute("Favorite") == true then
        return true
    end
    if tool:GetAttribute("f") == true or tool:GetAttribute("d") == true then
        return true
    end
    return false
end

local function isSeedTool(tool)
    if not tool or not tool:IsA("Tool") then
        return false
    end
    if tool:HasTag("FoodTool") then
        return false
    end
    local nm = tostring(tool.Name or ""):lower()
    if not nm:find("seed", 1, true) or nm:find("seed pack", 1, true) then
        return false
    end
    local it = toolItemType(tool)
    if it == "j" or it == "holdable" or it == "fruit" or it == "u" or it == "food" then
        return false
    end
    if it ~= "" and it ~= "seed" and it ~= "n" then
        return false
    end
    return true
end

local function isGenericFruit(tool)
    if not tool or not tool:IsA("Tool") then
        return false
    end
    local it = toolItemType(tool)
    if it == "seed" or it == "n" or it == "pet" or it == "a" then
        return false
    end
    if it == "u" or it == "food" then
        return false
    end
    if isSeedTool(tool) then
        return false
    end
    return true
end

local function hasEventMutation(tool)
    if not tool then
        return false
    end
    local attrs = {}
    pcall(function()
        attrs = tool:GetAttributes()
    end)
    for k, v in pairs(attrs) do
        local kn = tostring(k)
        if EVENT_MUTS[kn] == true then
            if v == true or tostring(v) == "true" then
                return true
            end
        end
        if EVENT_MUTS[tostring(v)] == true then
            return true
        end
    end
    local nm = tostring(tool.Name or "")
    local bracket = nm:match("%[(.-)%]")
    if type(bracket) == "string" and bracket ~= "" then
        for part in string.gmatch(bracket, "[^,]+") do
            local p = tostring(part):match("^%s*(.-)%s*$")
            if EVENT_MUTS[p] == true then
                return true
            end
        end
    end
    return false
end

local function isPlantHwFruit(tool)
    if not isGenericFruit(tool) then
        return false
    end
    local name = toolItemName(tool)
    if hasHalloweenTrait(name) or hasSpookyTrait(name) then
        return true
    end
    local base = name:gsub("^[Hh]alloween%s+", "")
    if PACK_MULTI[base] == true or PACK_ONE[base] == true then
        return true
    end
    return false
end

local function isHoldableFruit(tool)
    if not isGenericFruit(tool) then
        return false
    end
    if AUTO_HALLOWEEN_SWAP_NORMAL == true and not isHalloweenGarden() then
        return hasEventMutation(tool)
    end
    return isPlantHwFruit(tool)
end

local function forEachTool(fn)
    local function scan(container)
        if not container then
            return
        end
        for _, t in ipairs(container:GetChildren()) do
            if t:IsA("Tool") then
                fn(t)
            end
        end
    end
    scan(LP and LP:FindFirstChild("Backpack"))
    scan(LP and LP.Character)
end

local function findSeedTool(plantName)
    local wantExact = cleanName(plantName):lower()
    local wantBase = wantExact:gsub("^halloween%s+", "")
    local onHw = isHalloweenGarden()
    local found
    forEachTool(function(tool)
        if found then
            return
        end
        if not isSeedTool(tool) then
            return
        end
        local got = cleanName(toolItemName(tool)):lower()
        if onHw then
            if got == wantExact then
                found = tool
            end
            return
        end
        if got:find("halloween", 1, true) then
            return
        end
        local gotBase = got:gsub("^halloween%s+", "")
        if gotBase == wantBase then
            found = tool
        end
    end)
    return found
end

local function findGearTool(name)
    local want = cleanName(name):lower()
    local found
    forEachTool(function(tool)
        if found then
            return
        end
        if cleanName(toolItemName(tool)):lower() == want then
            found = tool
        end
    end)
    return found
end

local function equipTool(tool)
    local char = LP and LP.Character
    if not char or not tool then
        return false
    end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if tool.Parent == char then
        return true
    end
    unequipTools()
    if hum then
        pcall(function()
            hum:EquipTool(tool)
        end)
    else
        tool.Parent = char
    end
    task.wait(0.15)
    return tool.Parent == char
end

local function uuidOf(tool)
    if not tool then
        return ""
    end
    return tostring(
        tool:GetAttribute("UUID")
            or tool:GetAttribute("Uid")
            or tool:GetAttribute("PET_UUID")
            or tool:GetAttribute("ITEM_UUID")
            or ""
    )
end

local function worldPos(inst)
    if not inst then
        return nil
    end
    if inst:IsA("BasePart") then
        return inst.Position
    end
    if inst:IsA("Model") then
        local ok, pivot = pcall(function()
            return inst:GetPivot().Position
        end)
        if ok then
            return pivot
        end
        if inst.PrimaryPart then
            return inst.PrimaryPart.Position
        end
    end
    local part = inst:FindFirstChildWhichIsA("BasePart", true)
    return part and part.Position or nil
end

local function ageBelowMax(inst)
    if not inst then
        return false
    end
    local grow = inst:FindFirstChild("Grow")
    local age = grow and grow:FindFirstChild("Age")
    local maxAge = inst:GetAttribute("MaxAge")
    if not age or maxAge == nil then
        return false
    end
    return age.Value < maxAge
end

local function isGrowing(plant)
    if ageBelowMax(plant) then
        return true
    end
    local ok, tagged = pcall(function()
        return plant:HasTag("Harvestable")
    end)
    if ok and tagged and ageBelowMax(plant) then
        return true
    end
    for _, ch in ipairs(plant:GetChildren()) do
        local fruitOk, fruitTag = pcall(function()
            return ch:HasTag("Harvestable")
        end)
        if fruitOk and fruitTag and ageBelowMax(ch) then
            return true
        end
        if ch:IsA("Model") then
            for _, ch2 in ipairs(ch:GetChildren()) do
                local ok2, tag2 = pcall(function()
                    return ch2:HasTag("Harvestable")
                end)
                if ok2 and tag2 and ageBelowMax(ch2) then
                    return true
                end
            end
        end
    end
    return false
end

local function nearestCanPlant(farm, pos)
    if not farm or not pos then
        return pos
    end
    local important = farm:FindFirstChild("Important")
    local locs = important and important:FindFirstChild("Plant_Locations")
    if not locs then
        return pos
    end
    local bestPad, bestLocal
    local bestD = 1e9
    for _, pad in ipairs(locs:GetDescendants()) do
        if pad:IsA("BasePart") and (pad.Name == "Can_Plant" or pad.Name == "CanPlant") then
            local lp = pad.CFrame:PointToObjectSpace(pos)
            local hx = pad.Size.X * 0.5
            local hz = pad.Size.Z * 0.5
            local cx = math.clamp(lp.X, -hx + 0.2, hx - 0.2)
            local cz = math.clamp(lp.Z, -hz + 0.2, hz - 0.2)
            local dx = lp.X - cx
            local dz = lp.Z - cz
            local d = math.sqrt(dx * dx + dz * dz)
            if d < bestD then
                bestD = d
                bestPad = pad
                bestLocal = Vector3.new(cx, 0, cz)
            end
        end
    end
    if bestPad then
        return (bestPad.CFrame * CFrame.new(bestLocal)).Position
    end
    return pos
end

local function toolUses(tool)
    if not tool then
        return 0
    end
    local n = tool:GetAttribute("e") or tool:GetAttribute("Uses")
    n = tonumber(n)
    if n then
        return n
    end
    return 1
end

local function selectedWaterCans()
    local map = AUTO_HALLOWEEN_WATER_CANS
    if type(map) ~= "table" or next(map) == nil then
        return { "Watering Can" }
    end
    local names = {}
    for i = 1, #HW_WATER_CANS do
        local key = HW_WATER_CANS[i].key
        if map[key] == true then
            names[#names + 1] = key
        end
    end
    if #names == 0 then
        names[1] = "Watering Can"
    end
    return names
end

local function findWateringCan()
    local names = selectedWaterCans()
    for i = 1, #names do
        local tool = findGearTool(names[i])
        if tool and toolUses(tool) >= 1 then
            return tool, names[i]
        end
    end
    return nil, nil
end

local function returnToGarden()
    local pos = gardenCenterPos()
    if not pos then
        return false
    end
    return goNear(pos, 18)
end

local function findNpcModel(kind)
    local names = {
        steven = { "SinisterSteven" },
        cat = { "HalloweenHungryModel" },
        brew = { "WitchesBrewCauldron", "WitchesBrew", "WitchesBrewPlatform", "WitchRigged" },
    }
    local list = names[kind]
    if type(list) ~= "table" then
        return nil
    end
    local roots = {
        workspace:FindFirstChild("Interaction"),
        workspace,
    }
    for r = 1, #roots do
        local root = roots[r]
        if root then
            for i = 1, #list do
                local inst
                pcall(function()
                    inst = root:FindFirstChild(list[i], true)
                end)
                if inst then
                    if inst:IsA("Model") then
                        return inst
                    end
                    return inst:FindFirstAncestorOfClass("Model") or inst
                end
            end
        end
    end
    return nil
end

local function npcPart(model)
    if not model then
        return nil
    end
    return model:FindFirstChild("HumanoidRootPart")
        or model:FindFirstChild("RootPart")
        or model.PrimaryPart
        or model:FindFirstChildWhichIsA("BasePart", true)
end

local function brewTarget()
    local model = findNpcModel("brew")
    local prompt = model and model:FindFirstChild("SubmitItem", true)
    local part = prompt and prompt.Parent
    if not (part and part:IsA("BasePart")) then
        part = npcPart(model)
    end
    return model, part, prompt
end

-- Sell/ToT: server cek jarak player ke NPC (CFrame NPC di client diabaikan).
-- Cat: submit from garden is accepted. Brew: must be <10 studs at SubmitItem while holding fruit.
local function withNpcRange(kind, action, stay)
    local model, part, prompt
    if kind == "brew" then
        model, part, prompt = brewTarget()
    else
        model = findNpcModel(kind)
        part = npcPart(model)
    end
    local pos = part and part.Position
    local near = kind == "brew" and 8 or 16
    local go = kind == "brew" and 6 or 14
    if pos and distTo(pos) <= near then
        action(prompt)
        return true, "near"
    end
    if kind == "cat" or not pos then
        action(prompt)
        return true, "fired"
    end
    if not goNear(pos, go) then
        return false, sharkWaitingBite() and "shark wait bite" or "need near npc"
    end
    action(prompt)
    task.wait(0.3)
    if stay ~= true then
        returnToGarden()
    end
    return true, "tp-npc"
end

local function getCanPlantParts(farm)
    farm = farm or getOwnFarm()
    if not farm then
        return {}
    end
    local out = {}
    local root = farm:FindFirstChild("Important") or farm
    for _, d in ipairs(root:GetDescendants()) do
        if d:IsA("BasePart") and d.Name == "Can_Plant" then
            out[#out + 1] = d
        end
    end
    return out
end

local function middlePlantPlots(farm)
    local parts = getCanPlantParts(farm)
    if #parts == 0 then
        return {}
    end
    local center = gardenCenterPos()
    if not center then
        local hrp = getHrp()
        center = hrp and hrp.Position
    end
    if not center then
        return { parts[1] }
    end
    local ranked = {}
    for i = 1, #parts do
        local p = parts[i]
        local dx = p.Position.X - center.X
        local dz = p.Position.Z - center.Z
        ranked[i] = { part = p, d = dx * dx + dz * dz, large = math.max(p.Size.X, p.Size.Z) >= 10 }
    end
    table.sort(ranked, function(a, b)
        return a.d < b.d
    end)
    local out = {}
    if ranked[1] and ranked[1].large then
        for i = 1, #ranked do
            if ranked[i].large then
                out[#out + 1] = ranked[i].part
                if #out >= 2 then
                    break
                end
            end
        end
        return out
    end
    for i = 1, math.min(#ranked, 24) do
        out[i] = ranked[i].part
    end
    return out
end

local function gridSlotsOnPlot(part)
    local out = {}
    if not part then
        return out
    end
    local cf = part.CFrame
    local hx = part.Size.X * 0.5 * 0.78
    local hz = part.Size.Z * 0.5 * 0.78
    local yOff = part.Size.Y * 0.5 + 0.05
    local nx = math.max(0, math.floor(hx / PLANT_SPACING))
    local nz = math.max(0, math.floor(hz / PLANT_SPACING))
    local scored = {}
    for dx = -nx, nx do
        for dz = -nz, nz do
            local lx = dx * PLANT_SPACING
            local lz = dz * PLANT_SPACING
            if math.abs(lx) <= hx + 0.01 and math.abs(lz) <= hz + 0.01 then
                scored[#scored + 1] = { lx = lx, lz = lz, d2 = lx * lx + lz * lz }
            end
        end
    end
    table.sort(scored, function(a, b)
        return a.d2 < b.d2
    end)
    for i = 1, #scored do
        local s = scored[i]
        out[i] = (cf * CFrame.new(s.lx, yOff, s.lz)).Position
    end
    return out
end

local function buildPlantSlots(farm)
    local plots = middlePlantPlots(farm)
    local lists = {}
    for i = 1, #plots do
        lists[i] = gridSlotsOnPlot(plots[i])
    end
    local slots = {}
    local maxN = 0
    for i = 1, #lists do
        if #lists[i] > maxN then
            maxN = #lists[i]
        end
    end
    for i = 1, maxN do
        for p = 1, #lists do
            if lists[p][i] then
                slots[#slots + 1] = lists[p][i]
            end
        end
    end
    return slots
end

local function countGardenPlant(plantName)
    local want = cleanName(plantName):lower()
    local folder = getPlantsFolder()
    if not folder or want == "" then
        return 0
    end
    local n = 0
    for _, plant in ipairs(folder:GetChildren()) do
        local nm = cleanName(
            plant:GetAttribute("ItemName") or plant:GetAttribute("PlantName") or plant.Name
        ):lower()
        if nm == want then
            n += 1
        end
    end
    return n
end

local function countSeedQty(plantName)
    local want = cleanName(plantName):lower()
    if want == "" then
        return 0
    end
    local n = 0
    forEachTool(function(tool)
        if isSeedTool(tool) and cleanName(toolItemName(tool)):lower() == want then
            local q = tonumber(tool:GetAttribute("Quantity") or tool:GetAttribute("Qty") or 1) or 1
            if q < 1 then
                q = 1
            end
            n += q
        end
    end)
    return n
end

local function packBaseName(name)
    local n = cleanName(name)
    n = n:gsub("^[Hh]alloween%s+", "")
    return n
end

local function hasPackPlant(name)
    local n = packBaseName(name)
    return PACK_MULTI[n] == true or PACK_ONE[n] == true
end

local function countPackSeedQty(plantName)
    local want = packBaseName(plantName):lower()
    if want == "" then
        return 0
    end
    local n = 0
    forEachTool(function(tool)
        if not isSeedTool(tool) then
            return
        end
        local raw = cleanName(toolItemName(tool))
        if raw:lower():find("halloween", 1, true) then
            return
        end
        if packBaseName(raw):lower() == want then
            local q = tonumber(tool:GetAttribute("Quantity") or tool:GetAttribute("Qty") or 1) or 1
            if q < 1 then
                q = 1
            end
            n += q
        end
    end)
    return n
end

local function packMultiInBag()
    for n in pairs(PACK_MULTI) do
        if countPackSeedQty(n) > 0 then
            return true
        end
    end
    return false
end

local function anySeedSelected()
    if type(AUTO_HALLOWEEN_SEEDS) ~= "table" then
        return false
    end
    for _, v in pairs(AUTO_HALLOWEEN_SEEDS) do
        if v == true then
            return true
        end
    end
    return false
end

local function isSeedSelected(plantName)
    local n = cleanName(plantName)
    local base = packBaseName(n)
    if AUTO_HALLOWEEN_SEEDS[n] == true or AUTO_HALLOWEEN_SEEDS[base] == true then
        return true
    end
    return AUTO_HALLOWEEN_SEEDS["Halloween " .. base] == true
end

local function selectedPackSeedNames()
    local names = {}
    local filter = anySeedSelected()
    local function add(n)
        if countPackSeedQty(n) > 0 and (not filter or isSeedSelected(n)) then
            names[#names + 1] = n
        end
    end
    for n in pairs(PACK_MULTI) do
        add(n)
    end
    for n in pairs(PACK_ONE) do
        add(n)
    end
    return names
end

local function findHwPackTool()
    local found, key
    forEachTool(function(tool)
        if found or not tool then
            return
        end
        local n = toolItemName(tool)
        if HW_PACKS[n] == true then
            found, key = tool, n
            return
        end
        local low = tostring(n):lower()
        if low:find("haunted seed pack", 1, true)
            or low:find("spooky chest", 1, true) then
            found, key = tool, n
        end
    end)
    return found, key
end

local function countOwnedSeed(plantName)
    return countGardenPlant(plantName) + countSeedQty(plantName)
end

local function pickPlantSlot(farm, plantsFolder)
    farm = farm or getOwnFarm()
    if not farm then
        return nil, "no own farm"
    end
    local plots = middlePlantPlots(farm)
    if #plots == 0 then
        return nil, "no Can_Plant"
    end
    local sig = tostring(#plots)
    for i = 1, #plots do
        sig = sig .. "|" .. tostring(plots[i]:GetFullName())
    end
    if hwPlantSlots == nil or hwPlantSlotSig ~= sig then
        hwPlantSlots = buildPlantSlots(farm)
        hwPlantSlotSig = sig
        plantSlotCursor = 1
    end
    local slots = hwPlantSlots
    if type(slots) ~= "table" or #slots == 0 then
        return nil, "no empty slot"
    end
    local occupied = {}
    if plantsFolder then
        for _, p in ipairs(plantsFolder:GetChildren()) do
            local wp = worldPos(p)
            if wp then
                occupied[#occupied + 1] = wp
            end
        end
    end
    local min2 = PLANT_SPACING * PLANT_SPACING
    local n = #slots
    local start = plantSlotCursor
    if start < 1 or start > n then
        start = 1
    end
    for step = 0, n - 1 do
        local idx = ((start - 1 + step) % n) + 1
        local pos = slots[idx]
        if pos then
            local free = true
            for i = 1, #occupied do
                local o = occupied[i]
                local dx, dz = pos.X - o.X, pos.Z - o.Z
                if dx * dx + dz * dz < min2 then
                    free = false
                    break
                end
            end
            if free then
                plantSlotCursor = (idx % n) + 1
                return pos
            end
        end
    end
    return nil, "no empty slot"
end

local function selectedSeedNames()
    local names = {}
    for i = 1, #HW_PLANTS do
        local n = HW_PLANTS[i]
        if AUTO_HALLOWEEN_SEEDS[n] == true then
            names[#names + 1] = n
        end
    end
    return names
end

local function buildShopCatalog()
    if shopCatalog then
        return shopCatalog
    end
    local items = {}
    local function addShop(tbl, shopName)
        if type(tbl) ~= "table" then
            return
        end
        for name, info in pairs(tbl) do
            if type(info) == "table" and info.DisplayInShop ~= false then
                items[#items + 1] = {
                    name = tostring(name),
                    price = tonumber(info.Price) or 0,
                    shop = shopName,
                    itemType = tostring(info.ItemType or ""),
                    minIndex = tonumber(info.MinEventIndex) or 0,
                    layout = tonumber(info.LayoutOrder) or 999,
                }
            end
        end
    end
    if type(ShopData) == "table" then
        addShop(ShopData.SeedShop, "Scary Seeds")
        addShop(ShopData.PetShop, "Frightening Fauna")
        addShop(ShopData.CosmeticShop, "Demonic Decor")
        addShop(ShopData.GearShop, "Scary Seeds")
    end
    if #items == 0 then
        for i = 1, #HW_PLANTS do
            items[#items + 1] = {
                name = HW_PLANTS[i],
                price = 10,
                shop = "Scary Seeds",
                itemType = "Seed",
                minIndex = 0,
                layout = i,
            }
        end
    end
    local typeOrder = {
        Seed = 1,
        Gear = 2,
        ["Seed Pack"] = 3,
        Egg = 4,
        Pet = 5,
        Crate = 6,
        Cosmetic = 7,
    }
    table.sort(items, function(a, b)
        local ta = typeOrder[a.itemType] or 90
        local tb = typeOrder[b.itemType] or 90
        if ta ~= tb then
            return ta < tb
        end
        if a.price ~= b.price then
            return a.price < b.price
        end
        return a.layout < b.layout
    end)
    shopCatalog = items
    return items
end

function M.GetShopItems()
    local out = {}
    for _, it in ipairs(buildShopCatalog()) do
        local kind = it.itemType
        if kind == "" then
            kind = "?"
        end
        local price = tonumber(it.price) or 0
        out[#out + 1] = {
            key = it.name,
            name = ("[%s] %s · %s CC"):format(kind, it.name, tostring(price)),
        }
    end
    return out
end

function M.GetSeedItems()
    local out = {}
    local seen = {}
    for i = 1, #HW_PLANTS do
        local n = HW_PLANTS[i]
        seen[n] = true
        out[#out + 1] = { key = n, name = n .. " · Ghoul / Scary Seeds" }
    end
    local extras = {}
    for n in pairs(PACK_MULTI) do
        extras[#extras + 1] = n
    end
    for n in pairs(PACK_ONE) do
        extras[#extras + 1] = n
    end
    table.sort(extras)
    for i = 1, #extras do
        local n = extras[i]
        if not seen[n] then
            seen[n] = true
            local src = CHEST_SEEDS[n] and "Normal / Spooky Chest" or "Normal / Haunted Pack"
            out[#out + 1] = { key = n, name = n .. " · " .. src }
        end
    end
    return out
end

function M.GetWaterItems()
    local usesBy = {}
    forEachTool(function(tool)
        local n = cleanName(toolItemName(tool))
        local u = toolUses(tool)
        if u > 0 then
            usesBy[n] = (usesBy[n] or 0) + u
        end
    end)
    local out = {}
    for i = 1, #HW_WATER_CANS do
        local it = HW_WATER_CANS[i]
        local uses = usesBy[it.key]
        local label = it.name
        if uses then
            label = ("%s · %dx"):format(it.name, uses)
        end
        out[#out + 1] = { key = it.key, name = label }
    end
    return out
end

local function stockCountOf(rec)
    if type(rec) == "table" then
        return tonumber(rec.Stock) or 0
    end
    return tonumber(rec) or 0
end

local function shopStock(shopName, itemName)
    local data = getData()
    local stockRoot = data and data.EventShopStock
    if type(stockRoot) ~= "table" then
        return 0
    end
    local function fromShop(shop)
        if type(shop) ~= "table" then
            return nil
        end
        local stocks = shop.Stocks
        if type(stocks) == "table" and stocks[itemName] ~= nil then
            return stockCountOf(stocks[itemName])
        end
        if shop[itemName] ~= nil then
            return stockCountOf(shop[itemName])
        end
        return nil
    end
    local n = fromShop(stockRoot[shopName])
    if n ~= nil then
        return n
    end
    for _, shop in pairs(stockRoot) do
        if type(shop) == "table" then
            local got = fromShop(shop)
            if got ~= nil then
                return got
            end
        end
    end
    return 0
end

local function isCollectableInst(inst)
    if not inst or not inst.Parent then
        return false
    end
    if inst:GetAttribute("Collected") == true then
        return false
    end
    if CollectionService:HasTag(inst, "Harvestable") or inst:HasTag("Harvestable") then
        return true
    end
    local prompt = inst:FindFirstChildWhichIsA("ProximityPrompt", true)
    if not prompt or prompt.Enabled ~= true then
        return false
    end
    return prompt:HasTag("CollectPrompt") or CollectionService:HasTag(prompt, "CollectPrompt")
end

local function collectModelFrom(inst)
    local prompt = inst:FindFirstChildWhichIsA("ProximityPrompt", true)
    if prompt and prompt.Parent and prompt.Parent.Parent then
        return prompt.Parent.Parent
    end
    return inst
end

local function hungryProgress()
    if type(HungryController) == "table" and type(HungryController.GetProgress) == "function" then
        local ok, prog = pcall(function()
            return HungryController:GetProgress()
        end)
        if ok and type(prog) == "table" then
            return prog
        end
    end
    local data = getData()
    local hd = data and data.HalloweenHungryData
    local level = tonumber(hd and hd.CurrentLevel) or 1
    local sets = HungryConfig and HungryConfig.SETS
    local set = type(sets) == "table" and sets[level] or {}
    return {
        Level = level,
        NumSets = type(sets) == "table" and #sets or 15,
        Set = set,
        Fed = 0,
        Needed = type(set) == "table" and #set or 3,
        Remaining = set,
        RemainingSlots = {},
        Submitted = (hd and hd.Submitted) or {},
    }
end

local function fruitMatchesReq(tool, req)
    if not tool or type(req) ~= "table" then
        return false
    end
    if not isGenericFruit(tool) then
        return false
    end
    local want = cleanName(req.PLANT_NAME):lower()
    local have = toolItemName(tool):lower()
    if have ~= want and not have:find(want, 1, true) then
        return false
    end
    local minW = tonumber(req.WEIGHT) or 0
    if toolWeight(tool) + 1e-4 < minW then
        return false
    end
    if req.MUTATION then
        return toolHasMutation(tool, req.MUTATION)
    end
    if req.VARIANT and tostring(req.VARIANT) ~= "" then
        local v = tostring(tool:GetAttribute("Variant") or tool:GetAttribute("d") or "")
        if v:lower() ~= tostring(req.VARIANT):lower() then
            return false
        end
    end
    return true
end

local function remainingReqs(prog)
    local out = {}
    if type(prog.RemainingSlots) == "table" and #prog.RemainingSlots > 0 then
        for i = 1, #prog.RemainingSlots do
            out[#out + 1] = prog.RemainingSlots[i]
        end
        return out
    end
    if type(prog.Remaining) == "table" then
        for i = 1, #prog.Remaining do
            out[#out + 1] = { Slot = i, Req = prog.Remaining[i] }
        end
    end
    return out
end

local function formatCatReq(req)
    if type(req) ~= "table" then
        return "?"
    end
    local n = cleanName(req.PLANT_NAME):gsub("^Halloween%s+", "")
    local w = tonumber(req.WEIGHT) or 0
    local s = n
    if w > 0 then
        s = s .. (" ≥%.2fkg"):format(w)
    end
    if req.MUTATION and tostring(req.MUTATION) ~= "" then
        s = s .. " " .. tostring(req.MUTATION)
    end
    return s
end

local function bagHasCatReq(req)
    local found = false
    forEachTool(function(tool)
        if found then
            return
        end
        if fruitMatchesReq(tool, req) then
            found = true
        end
    end)
    return found
end

local function catNeedLine(prog)
    if AUTO_HALLOWEEN_HUNGRY_ENABLED == false then
        return "cat off"
    end
    prog = prog or hungryProgress()
    local slots = remainingReqs(prog)
    local fed = tonumber(prog.Fed) or 0
    local need = tonumber(prog.Needed) or 3
    if #slots <= 0 or fed >= need then
        return "cat set complete"
    end
    local parts = {}
    for i = 1, #slots do
        local req = slots[i] and slots[i].Req
        local label = formatCatReq(req)
        if bagHasCatReq(req) then
            parts[#parts + 1] = label .. " have"
        else
            parts[#parts + 1] = label .. " missing"
        end
    end
    return "cat need: " .. table.concat(parts, " · ")
end

local function reserveCatFruits()
    reservedFav = {}
    local prog = hungryProgress()
    local slots = remainingReqs(prog)
    local used = {}
    local picks = {}
    for i = 1, #slots do
        local slot = slots[i]
        local req = slot and slot.Req
        local best, bestW
        forEachTool(function(tool)
            if used[tool] then
                return
            end
            if fruitMatchesReq(tool, req) then
                local w = toolWeight(tool)
                if not best or w < bestW then
                    best, bestW = tool, w
                end
            end
        end)
        if best then
            used[best] = true
            reservedFav[best] = true
            picks[#picks + 1] = { tool = best, slot = slot.Slot, req = req }
        end
    end
    return picks, prog
end

local function trySwapGarden(force)
    if isHalloweenGarden() then
        return true
    end
    if not force and os.clock() - LAST_SLOT_AT < 8 then
        return false, "need Halloween garden"
    end
    LAST_SLOT_AT = os.clock()
    if not bindChangeSlots() then
        return false, "need Halloween garden"
    end
    pcall(function()
        ChangeSlotsRE:FireServer(SLOT_KEY)
    end)
    invalidateFarmCache()
    task.wait(1.6)
    invalidateFarmCache()
    if isHalloweenGarden() then
        returnToGarden()
        return true
    end
    return false, "need Halloween garden"
end

local function trySwapNormalGarden(force)
    if AUTO_HALLOWEEN_SWAP_NORMAL ~= true then
        return false, "garden normal off"
    end
    local key = normalSlotKey()
    if currentSlotKey() == key then
        return true
    end
    if candyCorn() < AUTO_HALLOWEEN_MIN_CC then
        return false, "need min CC"
    end
    if not force and os.clock() - LAST_SLOT_AT < 8 then
        return false, "slot cooldown"
    end
    LAST_SLOT_AT = os.clock()
    if not bindChangeSlots() then
        return false, "no ChangeSlots"
    end
    pcall(function()
        ChangeSlotsRE:FireServer(key)
    end)
    invalidateFarmCache()
    task.wait(1.6)
    invalidateFarmCache()
    if currentSlotKey() == key or not isHalloweenGarden() then
        returnToGarden()
        return true, "swapped " .. tostring(key)
    end
    return false, "swap normal fail"
end

local function tryOpenHwPack()
    if AUTO_HALLOWEEN_OPEN_PACK ~= true then
        return false, "open pack off"
    end
    if os.clock() - LAST_PACK_AT < 0.8 then
        return false, "pack cooldown"
    end
    local tool, key = findHwPackTool()
    if not tool or not key then
        return false, "no haunted pack"
    end
    LAST_PACK_AT = os.clock()
    local opener = rawget(_G, "AutoOpen") or rawget(G, "AutoOpen")
    if type(opener) == "table" and type(opener.OpenPackByKeys) == "function" then
        local wanted = { [key] = true }
        for n in pairs(HW_PACKS) do
            wanted[n] = true
        end
        local ok, why = opener.OpenPackByKeys(wanted)
        if ok then
            return true, "opened " .. tostring(key)
        end
        return false, tostring(why or "open pack fail")
    end
    return false, "no AutoOpen"
end

local function tryCollect()
    if AUTO_HALLOWEEN_COLLECT_ENABLED ~= true then
        return false, "collect off"
    end
    if not gardenWorkAllowed() then
        return false, "away from plot"
    end
    local folder = getPlantsFolder()
    if not folder then
        return false, "no own farm"
    end
    if not CollectCropsRE then
        pcall(function()
            local crops = ge() and ge():FindFirstChild("Crops")
            CollectCropsRE = crops and crops:FindFirstChild("Collect")
        end)
    end
    if not CollectCropsRE then
        return false, "no Collect remote"
    end
    local function addRipe(batch, seen, inst)
        if not isCollectableInst(inst) then
            return
        end
        local model = collectModelFrom(inst)
        if model and not seen[model] then
            seen[model] = true
            batch[#batch + 1] = model
        end
    end
    local function listRipe()
        local batch = {}
        local seen = {}
        for _, plant in ipairs(folder:GetChildren()) do
            local pname = cleanName(plant:GetAttribute("ItemName") or plant:GetAttribute("PlantName") or plant.Name)
            local wanted = isHalloweenGarden() and hasHalloweenTrait(pname) or hasPackPlant(pname)
            if wanted then
                local fruitsFolder = plant:FindFirstChild("Fruits")
                local fruits = fruitsFolder and fruitsFolder:GetChildren() or {}
                if #fruits == 0 then
                    addRipe(batch, seen, plant)
                else
                    for i = 1, #fruits do
                        addRipe(batch, seen, fruits[i])
                    end
                end
                for _, d in ipairs(plant:GetDescendants()) do
                    if d:IsA("Model") and d ~= plant then
                        addRipe(batch, seen, d)
                    end
                end
            end
        end
        return batch
    end
    local before = #listRipe()
    if before <= 0 then
        return false, "no ripe"
    end
    local function collectNear()
        local n = 0
        for _ = 1, COLLECT_BURSTS do
            if sharkWaitingBite() then
                break
            end
            local ripe = listRipe()
            if #ripe == 0 then
                break
            end
            local target, tpos, bestD
            for i = 1, #ripe do
                local p = worldPos(ripe[i])
                if p then
                    local d = distTo(p)
                    if not bestD or d < bestD then
                        bestD = d
                        target = ripe[i]
                        tpos = p
                    end
                end
            end
            if not tpos then
                break
            end
            if bestD > 16 then
                if not goNear(tpos, 12) then
                    break
                end
            end
            local slice = {}
            for i = 1, #ripe do
                local p = worldPos(ripe[i])
                if p and distTo(p) <= 22 then
                    slice[#slice + 1] = ripe[i]
                    if #slice >= COLLECT_BATCH then
                        break
                    end
                end
            end
            if #slice == 0 and target then
                slice[1] = target
            end
            if #slice == 0 then
                break
            end
            pcall(function()
                CollectCropsRE:FireServer(slice)
            end)
            n += #slice
            task.wait(0.18)
        end
        return n
    end
    local fired = collectNear()
    local left = #listRipe()
    local got = math.max(0, before - left)
    if got <= 0 and (tonumber(fired) or 0) <= 0 then
        return false, "no ripe"
    end
    return true, ("collect %d left %d"):format(got, left)
end

local function tryFavAndFeed()
    if AUTO_HALLOWEEN_HUNGRY_ENABLED ~= true then
        return false, "hungry off"
    end
    local picks, prog = reserveCatFruits()
    if type(prog) == "table" and tonumber(prog.Needed) and (tonumber(prog.Fed) or 0) >= tonumber(prog.Needed) then
        return false, "cat full"
    end
    if #picks == 0 then
        return false, "no cat fruit"
    end
    if os.clock() - LAST_CAT_AT < 1.2 then
        return false, "cat cooldown"
    end
    local pick = picks[1]
    local feedTool = pick.tool
    if not feedTool or not feedTool.Parent then
        return false, "no cat fruit"
    end
    if not equipTool(feedTool) then
        return false, "equip fruit fail"
    end
    LAST_CAT_AT = os.clock()
    local fedBefore = tonumber(prog.Fed) or 0
    local result
    local function doSubmit()
        local payload = { Mode = "Slot", Slot = pick.slot }
        if type(HungryController) == "table" and type(HungryController.Submit) == "function" then
            local ok, ret = pcall(function()
                return HungryController:Submit(5, payload)
            end)
            if ok then
                result = ret
            end
            if type(result) ~= "table" or result.Success ~= true then
                ok, ret = pcall(function()
                    return HungryController:Submit(5, nil)
                end)
                if ok then
                    result = ret
                end
            end
        end
        if not HungrySubmit then
            pcall(function()
                local ev = ge()
                local eventsFolder = ev and ev:FindFirstChild("Events")
                local he = eventsFolder and eventsFolder:FindFirstChild("Halloween2026Event")
                local hh = (he and he:FindFirstChild("HalloweenHungry"))
                    or (ev and ev:FindFirstChild("HalloweenHungry"))
                HungrySubmit = hh and hh:FindFirstChild("Submit")
            end)
        end
        if (type(result) ~= "table" or result.Success ~= true) and HungrySubmit then
            pcall(function()
                HungrySubmit:FireServer(payload)
            end)
            task.wait(0.4)
        end
    end
    local rangeOk, how = withNpcRange("cat", doSubmit)
    unequipTools()
    if not rangeOk then
        return false, how
    end
    if type(result) == "table" and result.Success ~= true then
        return false, tostring(result.Reason or "cat reject")
    end
    local now = hungryProgress()
    local fedNow = tonumber(now.Fed) or (fedBefore + 1)
    return true, ("feed cat %d/%d · %s"):format(fedNow, now.Needed or prog.Needed or 3, how)
end

local function trySell(stay)
    if AUTO_HALLOWEEN_SWAP_NORMAL == true and not isHalloweenGarden() then
        return false, "halloween sell skip · normal plot"
    end
    if AUTO_HALLOWEEN_SELL_ENABLED ~= true then
        return false, "sell off"
    end
    if os.clock() - LAST_SELL_AT < 2 then
        return false, "sell cooldown"
    end
    if AUTO_HALLOWEEN_HUNGRY_ENABLED ~= false then
        reserveCatFruits()
    end
    local extras = 0
    forEachTool(function(tool)
        if isHoldableFruit(tool) and not reservedFav[tool] and not isFavorited(tool) then
            extras += 1
        end
    end)
    if extras <= 0 then
        return false, "no extras"
    end
    if not SellInvRE then
        pcall(function()
            local ev = ge()
            local eventsFolder = ev and ev:FindFirstChild("Events")
            local he = (eventsFolder and eventsFolder:FindFirstChild("Halloween2026Event"))
                or (ev and ev:FindFirstChild("HalloweenEvent"))
                or (eventsFolder and eventsFolder:FindFirstChild("HalloweenEvent"))
            SellInvRE = he and he:FindFirstChild("HalloweenSellInventoryRE")
        end)
    end
    if not SellInvRE then
        return false, "no sell remote"
    end
    LAST_SELL_AT = os.clock()
    local before = extras
    local function fireSell()
        pcall(function()
            SellInvRE:FireServer()
        end)
    end
    fireSell()
    task.wait(0.45)
    extras = 0
    forEachTool(function(tool)
        if isHoldableFruit(tool) and not reservedFav[tool] and not isFavorited(tool) then
            extras += 1
        end
    end)
    if extras < before then
        return true, "sold extras · garden"
    end
    local rangeOk, how = withNpcRange("steven", fireSell, stay)
    if not rangeOk then
        return false, how
    end
    extras = 0
    forEachTool(function(tool)
        if isHoldableFruit(tool) and not reservedFav[tool] and not isFavorited(tool) then
            extras += 1
        end
    end)
    if extras < before then
        return true, ("sold extras · %s"):format(how)
    end
    return false, ("sell fail · %s"):format(how)
end

local function tryShop()
    if AUTO_HALLOWEEN_SHOP_ENABLED ~= true then
        return false, "shop off"
    end
    if os.clock() - LAST_SHOP_AT < 1.5 then
        return false, "shop cooldown"
    end
    if not BuyEventShopStock then
        pcall(function()
            BuyEventShopStock = ge() and ge():FindFirstChild("BuyEventShopStock")
        end)
    end
    if not BuyEventShopStock then
        return false, "no shop remote"
    end
    local cc = candyCorn()
    local idx = eventIndex()
    local lastWhy = "shop skip"
    for _, it in ipairs(buildShopCatalog()) do
        if AUTO_HALLOWEEN_SHOP[it.name] then
            if (it.minIndex or 0) > idx then
                lastWhy = "shop locked"
            elseif cc < (it.price or 0) then
                lastWhy = ("need %d CC for %s"):format(it.price, it.name)
            else
                local isSeed = tostring(it.itemType or ""):lower() == "seed"
                local cap = AUTO_HALLOWEEN_SEED_BUY_MAX
                local wantBuy = 80
                if isSeed and cap > 0 then
                    local have = countOwnedSeed(it.name)
                    if have >= cap then
                        lastWhy = ("seed cap %s %d/%d"):format(it.name, have, cap)
                        wantBuy = 0
                    else
                        wantBuy = cap - have
                    end
                end
                if wantBuy > 0 then
                    local stock = shopStock(it.shop, it.name)
                    if stock <= 0 then
                        lastWhy = ("oos %s"):format(it.name)
                    else
                        LAST_SHOP_AT = os.clock()
                        local fires
                        if isSeed then
                            fires = math.min(stock, wantBuy)
                        else
                            fires = math.min(80, math.max(1, stock) * 10)
                        end
                        for _ = 1, fires do
                            task.spawn(function()
                                pcall(function()
                                    BuyEventShopStock:FireServer(it.name, it.shop)
                                end)
                            end)
                        end
                        task.wait(0.35)
                        return true, ("buy %s x%d"):format(it.name, fires)
                    end
                end
            end
        end
    end
    return false, lastWhy
end

local function tryPlant()
    if AUTO_HALLOWEEN_PLANT_ENABLED ~= true then
        return false, "plant off"
    end
    if not gardenWorkAllowed() then
        return false, "away from plot"
    end
    if os.clock() - LAST_PLANT_AT < PLANT_COOLDOWN then
        return false, "plant cooldown"
    end
    local names
    if isHalloweenGarden() then
        names = selectedSeedNames()
        if #names == 0 then
            return false, "no seed selected"
        end
    elseif AUTO_HALLOWEEN_SWAP_NORMAL == true then
        names = selectedPackSeedNames()
        if #names == 0 then
            return false, "no pack seed"
        end
    else
        return false, "need Halloween garden"
    end
    local farm = getOwnFarm()
    if not farm then
        return false, "no own farm"
    end
    local plantsFolder = getPlantsFolder(farm)
    local total = AUTO_HALLOWEEN_PLANT_TOTAL
    if not PlantRE then
        pcall(function()
            PlantRE = ge() and ge():FindFirstChild("Plant_RE")
        end)
    end
    if not PlantRE then
        return false, "no Plant_RE"
    end
    local nNames = #names
    local start = plantTypeCursor
    if start < 1 or start > nNames then
        start = 1
    end
    for step = 0, nNames - 1 do
        local i = ((start + step - 1) % nNames) + 1
        local plantName = names[i]
        local have = countGardenPlant(plantName)
        if total > 0 and have >= total then
            -- enough
        else
            local tool = findSeedTool(plantName)
            if tool then
                plantTypeCursor = i
                local placed = false
                for _ = 1, 5 do
                    local pos, err = pickPlantSlot(farm, plantsFolder)
                    if not pos then
                        return false, err or "no empty slot"
                    end
                    if not goNear(pos, 14) then
                        return false, sharkWaitingBite() and "shark wait bite" or "far from plot"
                    end
                    if not equipTool(tool) then
                        tool = findSeedTool(plantName)
                        if not tool or not equipTool(tool) then
                            unequipTools()
                            return false, "equip seed failed"
                        end
                    end
                    LAST_PLANT_AT = os.clock()
                    local seedName = cleanName(toolItemName(tool))
                    if packBaseName(seedName):lower() ~= packBaseName(plantName):lower() then
                        unequipTools()
                        return false, "seed mismatch"
                    end
                    if isHalloweenGarden() then
                        if AUTO_HALLOWEEN_SEEDS[plantName] ~= true and AUTO_HALLOWEEN_SEEDS[seedName] ~= true then
                            unequipTools()
                            return false, "seed not selected"
                        end
                    elseif not hasPackPlant(plantName) then
                        unequipTools()
                        return false, "not pack seed"
                    end
                    local fireOk = pcall(function()
                        PlantRE:FireServer(pos, seedName)
                    end)
                    task.wait(0.35)
                    unequipTools()
                    if fireOk and countGardenPlant(plantName) > have then
                        placed = true
                        break
                    end
                    tool = findSeedTool(plantName)
                    if not tool then
                        break
                    end
                end
                if placed then
                    return true, ("planted %s"):format(plantName)
                end
            end
        end
    end
    return false, "plant skip"
end

local function trySprinkler()
    if AUTO_HALLOWEEN_SPRINKLER_ENABLED ~= true then
        return false, "sprinkler off"
    end
    if not gardenWorkAllowed() then
        return false, "away from plot"
    end
    if os.clock() - LAST_SPRINKLER_AT < 8 then
        return false, "sprinkler cooldown"
    end
    local farm = getOwnFarm()
    local objects = farm and farm:FindFirstChild("Important")
    objects = objects and objects:FindFirstChild("Objects_Physical")
    if objects then
        for _, obj in ipairs(objects:GetChildren()) do
            local nm = tostring(obj.Name or ""):lower()
            local item = tostring(
                obj:GetAttribute("ItemName")
                    or obj:GetAttribute("f")
                    or obj:GetAttribute("OBJECT_TYPE")
                    or ""
            ):lower()
            if (nm:find("haunted sprinkler", 1, true) or item:find("haunted sprinkler", 1, true))
                or ((nm:find("sprinkler", 1, true) or item:find("sprinkler", 1, true))
                    and (nm:find("haunted", 1, true) or item:find("haunted", 1, true))) then
                return false, "haunted sprinkler already placed"
            end
        end
    end
    local tool = findGearTool("Haunted Sprinkler")
    if not tool then
        return false, "no sprinkler"
    end
    if not SprinklerService then
        pcall(function()
            SprinklerService = ge() and ge():FindFirstChild("SprinklerService")
        end)
    end
    if not SprinklerService then
        return false, "no sprinkler remote"
    end
    local folder = getPlantsFolder()
    local pos
    if folder then
        for _, plant in ipairs(folder:GetChildren()) do
            local pname = cleanName(plant:GetAttribute("ItemName") or plant.Name)
            if hasHalloweenTrait(pname) or hasPackPlant(pname) then
                pos = worldPos(plant)
                if pos then
                    break
                end
            end
        end
    end
    if not pos then
        pos = gardenCenterPos()
    end
    if not pos then
        return false, "no plant pos"
    end
    if not equipTool(tool) then
        return false, "equip sprinkler fail"
    end
    LAST_SPRINKLER_AT = os.clock()
    pcall(function()
        SprinklerService:FireServer("Create", CFrame.new(pos))
    end)
    task.wait(0.3)
    unequipTools()
    return true, "placed haunted sprinkler"
end

local function tryWater()
    if AUTO_HALLOWEEN_WATER_ENABLED ~= true then
        return false, "water off"
    end
    if not gardenWorkAllowed() then
        return false, "away from plot"
    end
    if os.clock() - LAST_WATER_AT < 2 then
        return false, "water cooldown"
    end
    if sharkWaitingBite() then
        return false, "shark wait bite"
    end
    local tool, toolName = findWateringCan()
    if not tool then
        return false, "no watering can"
    end
    if not WaterRE then
        pcall(function()
            local ev = ge()
            WaterRE = ev and ev:FindFirstChild("Water_RE")
            SuperWaterRE = ev and ev:FindFirstChild("TrySuperWateringCan")
        end)
    end
    if not WaterRE and not SuperWaterRE then
        return false, "no water remote"
    end
    local farm = getOwnFarm()
    local folder = getPlantsFolder(farm)
    if not folder then
        return false, "no plants"
    end
    local growing = {}
    for _, plant in ipairs(folder:GetChildren()) do
        local pname = cleanName(plant:GetAttribute("ItemName") or plant.Name)
        if (hasHalloweenTrait(pname) or hasPackPlant(pname)) and isGrowing(plant) then
            local last = lastWaterPlant[plant]
            if not last or (os.clock() - last) >= 8 then
                table.insert(growing, plant)
            end
        end
    end
    if #growing == 0 then
        return false, "no growing plants"
    end
    if not equipTool(tool) then
        return false, "equip watering can fail"
    end
    local n = 0
    local start = waterCursor
    if start < 1 or start > #growing then
        start = 1
    end
    local maxN = math.min(#growing, 6)
    local useSuper = tostring(toolName or ""):lower():find("super", 1, true) ~= nil
    for i = 0, maxN - 1 do
        local idx = ((start + i - 1) % #growing) + 1
        local plant = growing[idx]
        local pos = worldPos(plant)
        waterCursor = idx + 1
        if pos then
            pos = nearestCanPlant(farm, pos)
            if not goNear(pos, 12) then
                unequipTools()
                LAST_WATER_AT = os.clock()
                if n > 0 then
                    return true, ("watered %d growing"):format(n)
                end
                return false, sharkWaitingBite() and "shark wait bite" or "far from plant"
            end
            pcall(function()
                if useSuper and SuperWaterRE then
                    SuperWaterRE:FireServer(pos)
                elseif WaterRE then
                    WaterRE:FireServer(pos)
                elseif SuperWaterRE then
                    SuperWaterRE:FireServer(pos)
                end
            end)
            lastWaterPlant[plant] = os.clock()
            n += 1
            task.wait(0.2)
        end
    end
    LAST_WATER_AT = os.clock()
    unequipTools()
    for inst in pairs(lastWaterPlant) do
        if not inst.Parent then
            lastWaterPlant[inst] = nil
        end
    end
    if n <= 0 then
        return false, "water skip"
    end
    return true, ("watered %d growing"):format(n)
end

local function countExtrasFruit()
    local n = 0
    forEachTool(function(tool)
        if isHoldableFruit(tool) and not reservedFav[tool] and not isFavorited(tool) then
            n += 1
        end
    end)
    return n
end

local function countHalloweenFruit()
    local n = 0
    forEachTool(function(tool)
        if isHoldableFruit(tool) then
            n += 1
        end
    end)
    return n
end

local function dumpMode()
    local cc = candyCorn()
    local n = countHalloweenFruit()
    local maxBag = AUTO_HALLOWEEN_MAX_BACKPACK
    local minCc = AUTO_HALLOWEEN_MIN_CC
    if cc < DUMP_CC then
        return "sell", ("sell only · CC %d<%d"):format(cc, DUMP_CC)
    end
    if maxBag > 0 and n < maxBag then
        return "wait", ("wait fruit %d/%d"):format(n, maxBag)
    end
    if minCc > 0 and cc < minCc then
        return "sell", ("sell only · CC %d/%d"):format(cc, minCc)
    end
    return "full", ""
end

local function totStopCc()
    return math.max(0, math.floor(tonumber(AUTO_HALLOWEEN_TOT_STOP_VALUE) or 0))
end

local function parseCostText(s)
    local t = tostring(s or ""):gsub(",", ""):gsub("%s+", "")
    return tonumber((t:match("%d+"))) or 0
end

local function totDoorCost()
    local model = workspace:FindFirstChild("Interaction")
    model = model and model:FindFirstChild("TrickOrTreatingModel")
    local costPart = model and (model:FindFirstChild("CandyCornCost") or (TotConfig and model:FindFirstChild(TotConfig.COST_PART_NAME)))
    if costPart then
        for _, d in ipairs(costPart:GetDescendants()) do
            if d:IsA("TextLabel") then
                local n = parseCostText(d.Text)
                if n > 0 then
                    return n
                end
            end
        end
    end
    local knocks = 0
    local data = getData()
    local tot = data and data.TrickOrTreatingData
    if type(tot) == "table" then
        knocks = tonumber(tot.Knocks) or 0
    end
    local base = (TotConfig and tonumber(TotConfig.BASE_PRICE)) or 10
    local growth = (TotConfig and tonumber(TotConfig.PRICE_GROWTH)) or 2
    local roundTo = (TotConfig and tonumber(TotConfig.PRICE_ROUND_TO)) or 5
    local raw = base * (growth ^ knocks)
    if roundTo > 0 then
        raw = math.floor((raw / roundTo) + 0.5) * roundTo
    end
    return math.max(0, math.floor(raw))
end

local function bindTotRemotes()
    pcall(function()
        local ev = ge()
        local eventsFolder = ev and ev:FindFirstChild("Events")
        local he = (eventsFolder and eventsFolder:FindFirstChild("Halloween2026Event"))
            or (ev and ev:FindFirstChild("HalloweenEvent"))
            or (eventsFolder and eventsFolder:FindFirstChild("HalloweenEvent"))
        if not ToTRF then
            ToTRF = he and he:FindFirstChild("HalloweenTrickOrTreatRF")
        end
        if not ToTKnockRF then
            local totFolder = he and he:FindFirstChild("TrickOrTreating")
            ToTKnockRF = totFolder and totFolder:FindFirstChild("Knock")
        end
    end)
end

local function totDoorPart()
    local interaction = workspace:FindFirstChild("Interaction")
    local model = interaction and interaction:FindFirstChild("TrickOrTreatingModel")
    if not model then
        return nil, nil
    end
    local part = model:FindFirstChild("Door")
    if not (part and part:IsA("BasePart")) then
        local door = model:FindFirstChild("DoorModel") or model:FindFirstChild("Door")
        part = door and (door:FindFirstChildWhichIsA("BasePart", true) or door)
    end
    if not (part and part:IsA("BasePart")) then
        part = model:FindFirstChildWhichIsA("BasePart", true)
    end
    return model, part
end

local function invokeKnock()
    if not ToTKnockRF then
        return nil
    end
    local ok, ret = pcall(function()
        return ToTKnockRF:InvokeServer()
    end)
    if ok then
        return ret
    end
    return nil
end

local function knockReason(ret)
    if type(ret) ~= "table" then
        return tostring(ret or "empty")
    end
    if ret.Success == true then
        local outcome = tostring(ret.Outcome or "ok")
        local reward = ret.Reward
        local name = ""
        if type(reward) == "table" then
            name = tostring(reward.Value or reward.Name or reward.Item or "")
        end
        if name ~= "" then
            return ("%s · %s"):format(outcome, name)
        end
        return outcome
    end
    return tostring(ret.Reason or "fail")
end

local function tryTotDoor()
    bindTotRemotes()
    local _, part = totDoorPart()
    if not ToTKnockRF then
        return false, "no door knock"
    end
    if not part then
        return false, "no door"
    end
    local maxDist = (TotConfig and tonumber(TotConfig.KNOCK_MAX_DISTANCE)) or 25
    if distTo(part.Position) > (maxDist - 2) then
        LAST_TOT_DOOR_MSG = "ToT knock near"
        if not goNear(part.Position, math.max(8, maxDist - 6)) then
            return false, sharkWaitingBite() and "ToT shark wait bite" or "ToT need near door"
        end
        task.wait(0.2)
    end
    LAST_TOT_DOOR_MSG = "ToT knock door"
    local ret = invokeKnock()
    if type(ret) == "table" and ret.Success == true then
        return true, ("ToT door · %s"):format(knockReason(ret))
    end
    if type(ret) == "table" and tostring(ret.Reason) == "TooFar" then
        goNear(part.Position, 8)
        task.wait(0.2)
        ret = invokeKnock()
        if type(ret) == "table" and ret.Success == true then
            return true, ("ToT door · %s"):format(knockReason(ret))
        end
    end
    return false, ("ToT door %s"):format(knockReason(ret))
end

local function tryTot(stay)
    if AUTO_HALLOWEEN_TOT_ENABLED ~= true then
        LAST_TOT_MSG = "ToT sell off"
        return false, LAST_TOT_MSG
    end
    if os.clock() - LAST_TOT_AT < 8 then
        LAST_TOT_MSG = "ToT sell cooldown"
        return false, LAST_TOT_MSG
    end
    if countExtrasFruit() <= 0 then
        LAST_TOT_MSG = "ToT sell no fruit"
        return false, LAST_TOT_MSG
    end
    bindTotRemotes()
    if not ToTRF then
        LAST_TOT_MSG = "no ToT sell remote"
        return false, LAST_TOT_MSG
    end
    LAST_TOT_AT = os.clock()
    LAST_TOT_MSG = "ToT going to Scream-ven"
    local totResult
    local rangeOk, how = withNpcRange("steven", function()
        LAST_TOT_MSG = "ToT sell invoke"
        local ok, a = pcall(function()
            return ToTRF:InvokeServer()
        end)
        if ok then
            totResult = a
        end
    end, stay)
    if not rangeOk then
        LAST_TOT_MSG = ("ToT sell %s"):format(how)
        return false, LAST_TOT_MSG
    end
    if totResult == nil then
        LAST_TOT_MSG = ("ToT sell empty · %s"):format(how)
        return false, LAST_TOT_MSG
    end
    LAST_TOT_MSG = ("ToT sell %s · %s"):format(tostring(totResult), how)
    return true, LAST_TOT_MSG
end

local function tryTotDoorRun()
    if AUTO_HALLOWEEN_TOT_DOOR_ENABLED ~= true then
        LAST_TOT_DOOR_MSG = "ToT door off"
        return false, LAST_TOT_DOOR_MSG
    end
    local cd = (TotConfig and tonumber(TotConfig.KNOCK_COOLDOWN)) or 1.5
    if os.clock() - LAST_TOT_DOOR_AT < math.max(1.5, cd) then
        LAST_TOT_DOOR_MSG = "ToT door cooldown"
        return false, LAST_TOT_DOOR_MSG
    end
    local cost = totDoorCost()
    local stop = totStopCc()
    if stop > 0 and cost >= stop then
        LAST_TOT_DOOR_MSG = ("ToT door stop · cost %d ≥ %d"):format(cost, stop)
        return false, LAST_TOT_DOOR_MSG
    end
    local cc = candyCorn()
    if cost > 0 and cc < cost then
        LAST_TOT_DOOR_MSG = ("ToT door need CC %d/%d"):format(cc, cost)
        return false, LAST_TOT_DOOR_MSG
    end
    LAST_TOT_DOOR_AT = os.clock()
    local ok, msg = tryTotDoor()
    LAST_TOT_DOOR_MSG = msg
    return ok, LAST_TOT_DOOR_MSG
end

local function tryBrew()
    if AUTO_HALLOWEEN_BREW_ENABLED ~= true then
        LAST_BREW_MSG = "Brew off"
        return false, LAST_BREW_MSG
    end
    if os.clock() - LAST_BREW_AT < 4 then
        LAST_BREW_MSG = "Brew cooldown"
        return false, LAST_BREW_MSG
    end
    if not BrewRE then
        pcall(function()
            local events = ge() and ge():FindFirstChild("Events")
            local hw = events and events:FindFirstChild("HalloweenEvent")
            local brew = hw and hw:FindFirstChild("WitchesBrew")
            BrewRE = brew and brew:FindFirstChild("SubmitItemToCauldron")
        end)
    end
    if not BrewRE then
        LAST_BREW_MSG = "no brew remote"
        return false, LAST_BREW_MSG
    end
    local tool
    forEachTool(function(t)
        if tool then
            return
        end
        if isGenericFruit(t) and not reservedFav[t] and not isFavorited(t) then
            tool = t
        end
    end)
    if not tool then
        LAST_BREW_MSG = "Brew no fruit"
        return false, LAST_BREW_MSG
    end
    LAST_BREW_AT = os.clock()
    LAST_BREW_MSG = "Brew going to cauldron"
    local _, part, prompt = brewTarget()
    local pos = part and part.Position
    if not pos then
        LAST_BREW_MSG = "Brew no cauldron"
        return false, LAST_BREW_MSG
    end
    if distTo(pos) > 8 then
        if not goNear(pos, 6) then
            LAST_BREW_MSG = sharkWaitingBite() and "Brew shark wait bite" or "Brew need near cauldron"
            return false, LAST_BREW_MSG
        end
        task.wait(0.65)
    end
    if not equipTool(tool) then
        LAST_BREW_MSG = "Brew equip fail"
        return false, LAST_BREW_MSG
    end
    task.wait(0.4)
    local char = LP and LP.Character
    if tool.Parent ~= char then
        unequipTools()
        LAST_BREW_MSG = "Brew not holding"
        return false, LAST_BREW_MSG
    end
    local ok, ret = pcall(function()
        return BrewRE:InvokeServer("All")
    end)
    local done = ok and ret == true
    if not done then
        ok, ret = pcall(function()
            return BrewRE:InvokeServer()
        end)
        done = ok and ret == true
    end
    if not done and prompt and prompt:IsA("ProximityPrompt") then
        pcall(function()
            prompt.Enabled = true
            fireproximityprompt(prompt)
        end)
        task.wait(0.35)
        done = tool.Parent ~= char
    end
    task.wait(0.35)
    local gone = not tool.Parent or tool.Parent ~= char
    unequipTools()
    if done or gone then
        LAST_BREW_MSG = "Brew ok · All"
        return true, LAST_BREW_MSG
    end
    LAST_BREW_MSG = "Brew reject · All"
    return false, LAST_BREW_MSG
end

local function brewPercent()
    if LAST_BREW_PCT ~= nil and (os.clock() - LAST_BREW_PCT_AT) < 4 then
        return LAST_BREW_PCT
    end
    if not CauldronVisualRF then
        pcall(function()
            local events = ge() and ge():FindFirstChild("Events")
            local hw = events and events:FindFirstChild("HalloweenEvent")
            local brew = hw and hw:FindFirstChild("WitchesBrew")
            CauldronVisualRF = brew and brew:FindFirstChild("GetCauldronVisualsData")
        end)
    end
    if CauldronVisualRF then
        pcall(function()
            local data = CauldronVisualRF:InvokeServer()
            if type(data) == "table" and type(data.Percentage) == "number" then
                local p = data.Percentage
                LAST_BREW_PCT = math.floor(((p > 1) and p or (p * 100)) + 0.5)
                LAST_BREW_PCT_AT = os.clock()
            end
        end)
    end
    return LAST_BREW_PCT
end

local function statusLine()
    local cc = candyCorn()
    local prog = hungryProgress()
    local fed = tonumber(prog.Fed) or 0
    local need = tonumber(prog.Needed) or 3
    local lvl = tonumber(prog.Level) or 1
    local maxS = tonumber(prog.NumSets) or 15
    local garden
    if isHalloweenGarden() then
        garden = "Ghoul"
    elseif AUTO_HALLOWEEN_SWAP_NORMAL == true then
        garden = "Normal · " .. slotDisplayName(normalSlotKey())
    else
        garden = "need Halloween garden"
    end
    local totLbl = LAST_TOT_MSG
    local pct = brewPercent()
    local brewLbl
    if AUTO_HALLOWEEN_TOT_ENABLED ~= true then
        totLbl = "ToT sell off"
    end
    local doorLbl = LAST_TOT_DOOR_MSG
    if AUTO_HALLOWEEN_TOT_DOOR_ENABLED ~= true then
        doorLbl = "ToT door off"
    end
    totLbl = totLbl .. " · " .. doorLbl
    if AUTO_HALLOWEEN_BREW_ENABLED ~= true then
        brewLbl = (pct ~= nil) and ("Brew off %d%%"):format(pct) or "Brew off"
    elseif pct ~= nil then
        brewLbl = ("Brew %d%%"):format(pct)
    else
        brewLbl = LAST_BREW_MSG
    end
    return ("CC %d · fruit %d/%d · cat %d/%d set %d/%d · %s · %s · %s\n%s\n%s"):format(
        cc,
        countHalloweenFruit(),
        AUTO_HALLOWEEN_MAX_BACKPACK,
        fed,
        need,
        lvl,
        maxS,
        totLbl,
        brewLbl,
        garden,
        catNeedLine(prog),
        LAST_STATUS
    )
end

function M.GetStatusText()
    return statusLine()
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if AUTO_HALLOWEEN_ENABLED ~= true then
            break
        end
        if not isHalloweenEvent() then
            publishStatus("not Halloween event")
            task.wait(clampDelay(AUTO_HALLOWEEN_DELAY_SEC))
        else
            local did = false
            local ok, msg = tryShop()
            if ok then
                publishStatus(msg)
                did = true
            end
            ok, msg = tryOpenHwPack()
            if ok then
                publishStatus(msg)
                did = true
            end
            if AUTO_HALLOWEEN_SWAP_NORMAL == true then
                if candyCorn() >= AUTO_HALLOWEEN_MIN_CC then
                    ok, msg = trySwapNormalGarden()
                    if ok and type(msg) == "string" and msg ~= "" then
                        publishStatus(msg)
                        did = true
                    end
                elseif not isHalloweenGarden() then
                    ok, msg = trySwapGarden()
                    if ok then
                        publishStatus("swapped Halloween · CC below min")
                        did = true
                    elseif not did then
                        publishStatus(msg or "need Halloween garden")
                    end
                end
            elseif not isHalloweenGarden() then
                ok, msg = trySwapGarden()
                if not ok and not did then
                    publishStatus(msg or "need Halloween garden")
                end
            end
            local onHw = isHalloweenGarden()
            local onPlot = onHw or AUTO_HALLOWEEN_SWAP_NORMAL == true
            local skipHwSell = AUTO_HALLOWEEN_SWAP_NORMAL == true and not onHw
            if onPlot then
                ok, msg = tryTotDoorRun()
                if ok then
                    publishStatus(msg)
                    did = true
                elseif AUTO_HALLOWEEN_TOT_DOOR_ENABLED == true and msg and not tostring(msg):find("cooldown", 1, true) then
                    publishStatus(msg)
                end
                ok, msg = tryCollect()
                if ok then
                    publishStatus(msg)
                    did = true
                end
                local mode, dumpWait = dumpMode()
                if skipHwSell then
                    if mode == "wait" then
                        publishStatus(dumpWait)
                    else
                        for _ = 1, 3 do
                            ok, msg = tryFavAndFeed()
                            if not ok then
                                break
                            end
                            publishStatus(msg)
                            did = true
                            task.wait(0.35)
                        end
                        ok, msg = tryBrew()
                        publishStatus(msg)
                        if ok then
                            did = true
                        end
                        ok, msg = tryTot(true)
                        publishStatus(msg)
                        if ok then
                            did = true
                        end
                    end
                elseif mode == "wait" then
                    publishStatus(dumpWait)
                elseif mode == "sell" then
                    publishStatus(dumpWait)
                    ok, msg = trySell(true)
                    if ok then
                        publishStatus(msg)
                        did = true
                    end
                    returnToGarden()
                else
                    for _ = 1, 3 do
                        ok, msg = tryFavAndFeed()
                        if not ok then
                            break
                        end
                        publishStatus(msg)
                        did = true
                        task.wait(0.35)
                    end
                    ok, msg = tryBrew()
                    publishStatus(msg)
                    if ok then
                        did = true
                    end
                    ok, msg = tryTot(true)
                    publishStatus(msg)
                    if ok then
                        did = true
                    end
                    ok, msg = trySell(true)
                    if ok then
                        publishStatus(msg)
                        did = true
                    end
                    returnToGarden()
                end
            end
            if onPlot then
                ok, msg = tryPlant()
                if ok then
                    publishStatus(msg)
                    did = true
                end
                ok, msg = trySprinkler()
                if ok then
                    publishStatus(msg)
                    did = true
                end
                ok, msg = tryWater()
                if ok then
                    publishStatus(msg)
                    did = true
                end
                ok, msg = tryCollect()
                if ok then
                    publishStatus(msg)
                    did = true
                end
                if not did and (LAST_STATUS == "running" or LAST_STATUS == "idle" or LAST_STATUS == "") then
                    local cc = candyCorn()
                    if cc <= 0 then
                        publishStatus("need seed/fruit")
                    else
                        publishStatus("idle")
                    end
                end
            end
            task.wait(clampDelay(AUTO_HALLOWEEN_DELAY_SEC))
        end
    end
    RUNNING = false
    if LAST_STATUS == "running" then
        publishStatus("stopped")
    end
end

function M.SyncFromState()
    syncGlobalsFromState()
    if AUTO_HALLOWEEN_ENABLED == true then
        M.Start()
    else
        M.Stop()
    end
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
end

function M.Start()
    M.SyncFromGlobals()
    if RUNNING then
        return
    end
    if AUTO_HALLOWEEN_ENABLED ~= true then
        return
    end
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    publishStatus("stopped")
end

