local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_FAIRY_STATUS = LAST_STATUS
    _G.__AUTO_FAIRY_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_fairy_event
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function flagOn(globalName, stKey)
    local st = getState()
    if G[globalName] == true or _G[globalName] == true or st[stKey] == true then
        return true
    end
    return false
end

local function syncGlobalsFromState()
    local st = getState()
    AUTO_FAIRY_CATCH_ENABLED = flagOn("AUTO_FAIRY_CATCH_ENABLED", "catch_enabled")
    AUTO_FAIRY_JAR_ENABLED = flagOn("AUTO_FAIRY_JAR_ENABLED", "jar_enabled")
    AUTO_FAIRY_FOUNTAIN_ENABLED = flagOn("AUTO_FAIRY_FOUNTAIN_ENABLED", "fountain_enabled")
    AUTO_FAIRY_CLAIM_ENABLED = flagOn("AUTO_FAIRY_CLAIM_ENABLED", "claim_enabled")
    AUTO_FAIRY_RESTART_ENABLED = flagOn("AUTO_FAIRY_RESTART_ENABLED", "restart_enabled")
    AUTO_FAIRY_UPGRADE_ENABLED = flagOn("AUTO_FAIRY_UPGRADE_ENABLED", "upgrade_enabled")
    AUTO_FAIRY_PLANT_ENABLED = flagOn("AUTO_FAIRY_PLANT_ENABLED", "plant_enabled")
    local plantTotalSrc = G.AUTO_FAIRY_PLANT_TOTAL
    if plantTotalSrc == nil then plantTotalSrc = _G.AUTO_FAIRY_PLANT_TOTAL end
    if plantTotalSrc == nil then plantTotalSrc = AUTO_FAIRY_PLANT_TOTAL end
    if plantTotalSrc == nil then plantTotalSrc = st.plant_total end
    AUTO_FAIRY_PLANT_TOTAL = math.max(0, math.floor(tonumber(plantTotalSrc) or 1))

    local prefer = G.AUTO_FAIRY_WISH_REWARDS
    if type(prefer) ~= "table" then prefer = _G.AUTO_FAIRY_WISH_REWARDS end
    if type(prefer) ~= "table" then prefer = st.wish_rewards end
    if type(prefer) == "table" then
        local set = {}
        if prefer[1] ~= nil then
            for _, k in ipairs(prefer) do
                if k ~= nil and k ~= "" then
                    set[tostring(k)] = true
                end
            end
        else
            for k, v in pairs(prefer) do
                if v == true or v == 1 then
                    set[tostring(k)] = true
                end
            end
        end
        AUTO_FAIRY_WISH_REWARDS = set
    end

    local upSel = G.AUTO_FAIRY_UPGRADES
    if type(upSel) ~= "table" then upSel = _G.AUTO_FAIRY_UPGRADES end
    if type(upSel) ~= "table" then upSel = st.upgrades end
    if type(upSel) == "table" then
        local set = {}
        if upSel[1] ~= nil then
            for _, k in ipairs(upSel) do
                if k ~= nil and k ~= "" then
                    set[tostring(k)] = true
                end
            end
        else
            for k, v in pairs(upSel) do
                if v == true or v == 1 then
                    set[tostring(k)] = true
                end
            end
        end
        AUTO_FAIRY_UPGRADES = set
    end

    local delaySrc = G.AUTO_FAIRY_DELAY_SEC
    if delaySrc == nil then delaySrc = _G.AUTO_FAIRY_DELAY_SEC end
    if delaySrc == nil then delaySrc = AUTO_FAIRY_DELAY_SEC end
    if delaySrc == nil then delaySrc = st.delaySec end
    AUTO_FAIRY_DELAY_SEC = clampDelay(delaySrc)

    G.AUTO_FAIRY_CATCH_ENABLED = AUTO_FAIRY_CATCH_ENABLED
    G.AUTO_FAIRY_JAR_ENABLED = AUTO_FAIRY_JAR_ENABLED
    G.AUTO_FAIRY_FOUNTAIN_ENABLED = AUTO_FAIRY_FOUNTAIN_ENABLED
    G.AUTO_FAIRY_CLAIM_ENABLED = AUTO_FAIRY_CLAIM_ENABLED
    G.AUTO_FAIRY_RESTART_ENABLED = AUTO_FAIRY_RESTART_ENABLED
    G.AUTO_FAIRY_UPGRADE_ENABLED = AUTO_FAIRY_UPGRADE_ENABLED
    G.AUTO_FAIRY_PLANT_ENABLED = AUTO_FAIRY_PLANT_ENABLED
    G.AUTO_FAIRY_PLANT_TOTAL = AUTO_FAIRY_PLANT_TOTAL
    G.AUTO_FAIRY_WISH_REWARDS = AUTO_FAIRY_WISH_REWARDS
    G.AUTO_FAIRY_UPGRADES = AUTO_FAIRY_UPGRADES
    G.AUTO_FAIRY_DELAY_SEC = AUTO_FAIRY_DELAY_SEC
    _G.AUTO_FAIRY_CATCH_ENABLED = AUTO_FAIRY_CATCH_ENABLED
    _G.AUTO_FAIRY_JAR_ENABLED = AUTO_FAIRY_JAR_ENABLED
    _G.AUTO_FAIRY_FOUNTAIN_ENABLED = AUTO_FAIRY_FOUNTAIN_ENABLED
    _G.AUTO_FAIRY_CLAIM_ENABLED = AUTO_FAIRY_CLAIM_ENABLED
    _G.AUTO_FAIRY_RESTART_ENABLED = AUTO_FAIRY_RESTART_ENABLED
    _G.AUTO_FAIRY_UPGRADE_ENABLED = AUTO_FAIRY_UPGRADE_ENABLED
    _G.AUTO_FAIRY_PLANT_ENABLED = AUTO_FAIRY_PLANT_ENABLED
    _G.AUTO_FAIRY_PLANT_TOTAL = AUTO_FAIRY_PLANT_TOTAL
    _G.AUTO_FAIRY_WISH_REWARDS = AUTO_FAIRY_WISH_REWARDS
    _G.AUTO_FAIRY_UPGRADES = AUTO_FAIRY_UPGRADES
    _G.AUTO_FAIRY_DELAY_SEC = AUTO_FAIRY_DELAY_SEC
end

local function anyEnabled()
    return AUTO_FAIRY_CATCH_ENABLED == true
        or AUTO_FAIRY_JAR_ENABLED == true
        or AUTO_FAIRY_FOUNTAIN_ENABLED == true
        or AUTO_FAIRY_CLAIM_ENABLED == true
        or AUTO_FAIRY_RESTART_ENABLED == true
        or AUTO_FAIRY_UPGRADE_ENABLED == true
        or AUTO_FAIRY_PLANT_ENABLED == true
end

local function isFairyLive()
    local ok, ev = pcall(function()
        if EventRotationUtils and type(EventRotationUtils.GetCurrentEvent) == "function" then
            return EventRotationUtils:GetCurrentEvent()
        end
        return nil
    end)
    if ok and type(ev) == "table" then
        local set = tostring(ev.EventSet or ev.EventID or "")
        if set:find("Fairy", 1, true) then
            return true
        end
    end
    local model = workspace:FindFirstChild("Interaction")
    model = model and model:FindFirstChild("FairyEventModel")
    return model ~= nil
end

local function resolveRemotes()
    if not FolderRemote or not FolderRemote.Parent then
        local ge = ReplicatedStorage:FindFirstChild("GameEvents")
        local events = ge and ge:FindFirstChild("Events")
        FolderRemote = events and events:FindFirstChild("FairyEvent")
    end
    local folder = FolderRemote
    if not folder then
        return false
    end
    CollectLooseRemote = folder:FindFirstChild("CollectLooseFairy") or CollectLooseRemote
    SubmitJarRemote = folder:FindFirstChild("FairySubmitJar") or SubmitJarRemote
    SubmitAllJarRemote = folder:FindFirstChild("FairySubmitAllJar") or SubmitAllJarRemote
    SubmitFountainHeldRemote = folder:FindFirstChild("SubmitFairyFountainHeldPlant") or SubmitFountainHeldRemote
    SubmitFountainAllRemote = folder:FindFirstChild("SubmitFairyFountainAllPlants") or SubmitFountainAllRemote
    ClaimRewardRemote = folder:FindFirstChild("ClaimFairyReward") or ClaimRewardRemote
    SelectAllRewardRemote = folder:FindFirstChild("FairySelectAllRewardPoints") or SelectAllRewardRemote
    OpenFairyUIRemote = folder:FindFirstChild("OpenFairyUI") or OpenFairyUIRemote
    MakeWishRemote = folder:FindFirstChild("MakeFairyWish") or MakeWishRemote
    RestartTrackRemote = folder:FindFirstChild("RestartFairyTrack") or RestartTrackRemote
    UpgradeRemote = folder:FindFirstChild("Upgrade") or UpgradeRemote
    SubmitHeldGenericRemote = folder:FindFirstChild("SubmitHeldPlant") or SubmitHeldGenericRemote
    SubmitAllGenericRemote = folder:FindFirstChild("SubmitAllPlants") or SubmitAllGenericRemote
    return true
end

local hookedOpenUI = false
local function closeFairyGuis()
    pcall(function()
        local pg = LP:FindFirstChild("PlayerGui")
        local folder = pg and pg:FindFirstChild("Events")
        folder = folder and folder:FindFirstChild("FairyEvent")
        if not folder then
            return
        end
        for _, name in ipairs({
            "FairyQuests_UI",
            "ChooseFairyRewards_UI",
            "FairyWishRewards_UI",
            "FairyEventUpgrade_UI",
            "FairyOdds_UI",
            "ChooseFairyRewardsUI",
        }) do
            local gui = folder:FindFirstChild(name)
            if gui then
                if GuiController and type(GuiController.Close) == "function" then
                    pcall(GuiController.Close, GuiController, gui)
                end
                pcall(function()
                    gui.Enabled = false
                end)
            end
        end
    end)
end

local function hookCloseOpenFairyUI()
    if hookedOpenUI or not OpenFairyUIRemote then
        return
    end
    if not OpenFairyUIRemote:IsA("RemoteEvent") then
        return
    end
    hookedOpenUI = true
    OpenFairyUIRemote.OnClientEvent:Connect(function()
        if AUTO_FAIRY_CLAIM_ENABLED == true
            or AUTO_FAIRY_FOUNTAIN_ENABLED == true
            or AUTO_FAIRY_JAR_ENABLED == true
        then
            task.delay(0.22, closeFairyGuis)
            task.delay(0.55, closeFairyGuis)
        end
    end)
end

local function fireRE(remote, ...)
    if not remote then
        return false
    end
    local args = table.pack(...)
    local ok = pcall(function()
        if args.n > 0 then
            remote:FireServer(table.unpack(args, 1, args.n))
        else
            remote:FireServer()
        end
    end)
    return ok
end

local function getHrp()
    local char = LP.Character
    return char and char:FindFirstChild("HumanoidRootPart")
end

local function distTo(pos)
    local hrp = getHrp()
    if not hrp or not pos then
        return math.huge
    end
    return (hrp.Position - Vector3.new(pos.X, hrp.Position.Y, pos.Z)).Magnitude
end

local function dist3(pos)
    local hrp = getHrp()
    if not hrp or not pos then
        return math.huge
    end
    return (hrp.Position - pos).Magnitude
end

local function markFountainStay()
    NEED_GARDEN_RETURN = true
    if FOUNTAIN_STAY_UNTIL <= 0 then
        FOUNTAIN_STAY_UNTIL = os.clock() + GARDEN_RETURN_SEC
    end
end

local function fountainStayLeft()
    if FOUNTAIN_STAY_UNTIL <= 0 then
        return 0
    end
    return math.max(0, FOUNTAIN_STAY_UNTIL - os.clock())
end

local function goNear(pos, range, kind)
    local hrp = getHrp()
    if not hrp or not pos then
        return false
    end
    range = range or FOUNTAIN_RANGE
    if kind == "fountain" then
        markFountainStay()
    end
    if distTo(pos) <= range then
        return true
    end
    DID_TP = true
    if kind == "fountain" then
        NEED_GARDEN_RETURN = true
    end
    hrp.CFrame = CFrame.new(pos.X, hrp.Position.Y, pos.Z)
    task.wait(0.4)
    return distTo(pos) <= range + 5
end

local function goPlantPos(pos)
    if not pos then
        return false
    end
    if fountainStayLeft() > 0 then
        return false
    end
    local hrp = getHrp()
    if not hrp then
        return false
    end
    if distTo(pos) <= 14 then
        return true
    end
    DID_TP = false
    hrp.CFrame = CFrame.new(pos.X, hrp.Position.Y, pos.Z)
    task.wait(0.2)
    return distTo(pos) <= 18
end

local function getOwnFarm()
    local now = os.clock()
    if cachedFarm and cachedFarm.Parent and (now - cachedFarmAt) <= 8 then
        return cachedFarm
    end
    cachedFarm = nil
    cachedFarmAt = now
    if type(GetFarmAsync) == "function" then
        local ok, farm = pcall(GetFarmAsync, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end
    local farms = workspace:FindFirstChild("Farm") or workspace:FindFirstChild("Farms")
    if not farms then
        return nil
    end
    local username = LP and LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local ok, owner = pcall(function()
            return farm.Important.Data.Owner.Value
        end)
        if ok and owner == username then
            cachedFarm = farm
            return farm
        end
    end
    return nil
end

local function gardenCenterPos()
    local farm = getOwnFarm()
    if not farm then
        return nil
    end
    local important = farm:FindFirstChild("Important")
    local plantLocs = important and important:FindFirstChild("Plant_Locations")
    if plantLocs then
        local sum = Vector3.zero
        local n = 0
        for _, part in ipairs(plantLocs:GetDescendants()) do
            if part:IsA("BasePart") then
                sum = sum + part.Position
                n = n + 1
                if n >= 50 then
                    break
                end
            end
        end
        if n > 0 then
            return sum / n
        end
    end
    for _, name in ipairs({ "Center_Point", "CenterPoint", "FarmCenter" }) do
        local obj = farm:FindFirstChild(name, true)
        if obj then
            if obj:IsA("BasePart") then
                return obj.Position
            end
            if obj:IsA("Model") then
                return obj:GetPivot().Position
            end
        end
    end
    if farm:IsA("Model") then
        local ok, pivot = pcall(function()
            return farm:GetPivot()
        end)
        if ok and typeof(pivot) == "CFrame" then
            return pivot.Position
        end
    end
    return nil
end

local function returnToGarden()
    if fountainStayLeft() > 0 then
        return false
    end
    if not NEED_GARDEN_RETURN and not DID_TP then
        return false
    end
    local pos = gardenCenterPos()
    local hrp = getHrp()
    DID_TP = false
    NEED_GARDEN_RETURN = false
    FOUNTAIN_STAY_UNTIL = 0
    if not pos or not hrp then
        return false
    end
    if distTo(pos) <= 18 then
        return true
    end
    hrp.CFrame = CFrame.new(pos.X, hrp.Position.Y, pos.Z)
    return true
end

local function fountainPos()
    local tagged = CollectionService:GetTagged("FairyFountain")
    local inst = tagged and tagged[1]
    if not inst then
        local root = workspace:FindFirstChild("Interaction")
        local model = root and root:FindFirstChild("FairyEventModel")
        inst = model and model:FindFirstChild("WishFountain")
    end
    if inst and inst:IsA("Model") then
        return inst:GetPivot().Position
    end
    if inst and inst:IsA("BasePart") then
        return inst.Position
    end
    return nil
end

local function spawnPos()
    local tagged = CollectionService:GetTagged("FairySpawnPoint")
    local inst = tagged and tagged[1]
    if inst then
        return inst:GetPivot().Position
    end
    return fountainPos()
end

local function isHoldableFruitTool(tool)
    if not tool or not tool:IsA("Tool") then
        return false
    end
    if tool:GetAttribute("Favorited") == true then
        return false
    end
    if tool:HasTag("FoodTool") then
        return false
    end
    local n = tostring(tool.Name or ""):lower()
    if n:find("shard", 1, true) or n:find("radar", 1, true) or n:find("egg", 1, true) or n:find("seed", 1, true) then
        return false
    end
    if n:find("food", 1, true) or n:find("corndog", 1, true) or n:find("smoothie", 1, true) or n:find("wreath", 1, true) then
        return false
    end
    local it = tostring(tool:GetAttribute("ItemType") or tool:GetAttribute("ITEM_TYPE") or "")
    local itl = it:lower()
    if it == "A" or itl == "petshard" or itl == "pet" or it == "l" then
        return false
    end
    if it == "u" or itl == "food" then
        return false
    end
    if it ~= "" and itl ~= "holdable" and it ~= "j" and itl ~= "fruit" then
        return false
    end
    return true
end

local function isGlimmeringTool(tool)
    if not isHoldableFruitTool(tool) then
        return false
    end
    local n = tostring(tool.Name or ""):lower()
    local it = tostring(tool:GetAttribute("ItemType") or tool:GetAttribute("ITEM_TYPE") or "")
    local itl = it:lower()
    if tool:GetAttribute("Glimmering") == true then
        return true
    end
    if n:find("glimmering", 1, true) then
        return true
    end
    return false
end

local function fruitPlantName(tool)
    if not tool then
        return ""
    end
    local item = tool:FindFirstChild("Item_String")
    local raw = (item and (item.Value or item.Name)) or tool:GetAttribute("ItemName") or tool.Name
    local n = tostring(raw or "")
    n = n:gsub("%s*%[.-%]", "")
    n = n:gsub("%s*%d+%.?%d*%s*[kK][gG].*", "")
    n = n:gsub("%s*x%d+%s*$", "")
    return (n:match("^%s*(.-)%s*$") or "")
end

local function findGlimmeringTool()
    local char = LP.Character
    if char then
        local held = char:FindFirstChildOfClass("Tool")
        if isGlimmeringTool(held) then
            return held
        end
    end
    local bp = LP:FindFirstChild("Backpack")
    if not bp then
        return nil
    end
    for _, t in ipairs(bp:GetChildren()) do
        if isGlimmeringTool(t) then
            return t
        end
    end
    return nil
end

local function countGlimmeringTools()
    local n = 0
    local function scan(p)
        if not p then
            return
        end
        for _, t in ipairs(p:GetChildren()) do
            if isGlimmeringTool(t) then
                n = n + 1
            end
        end
    end
    scan(LP:FindFirstChild("Backpack"))
    scan(LP.Character)
    return n
end

local function equipTool(tool)
    if not tool then
        return false
    end
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then
        return false
    end
    if tool.Parent == char then
        return true
    end
    pcall(function()
        hum:EquipTool(tool)
    end)
    return tool.Parent == char
end

local function unequipTools()
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end
end

local function getLooseTargets()
    local list = {}
    pcall(function()
        if FairyVisuals and type(FairyVisuals.GetAllFairies) == "function" then
            local got = FairyVisuals:GetAllFairies()
            if type(got) == "table" then
                for _, e in ipairs(got) do
                    if type(e) == "table" and e.Id ~= nil and e.Position ~= nil then
                        list[#list + 1] = { Id = tostring(e.Id), Position = e.Position }
                    end
                end
            end
        end
    end)
    local prompts = {}
    pcall(function()
        prompts = CollectionService:GetTagged("FairyPrompt")
    end)
    if type(prompts) == "table" and #prompts > 0 then
        local matched = {}
        for _, pp in ipairs(prompts) do
            if pp and pp.Parent and pp.Enabled ~= false and pp:GetAttribute("Collecting") ~= true then
                local pos = pp.Parent:GetPivot().Position
                local best, bestD = nil, nil
                for _, e in ipairs(list) do
                    local d = (e.Position - pos).Magnitude
                    if not bestD or d < bestD then
                        best, bestD = e, d
                    end
                end
                if best and bestD and bestD <= 18 then
                    matched[#matched + 1] = { Id = best.Id, Position = pos, Prompt = pp }
                elseif not best then
                    matched[#matched + 1] = { Id = nil, Position = pos, Prompt = pp }
                end
            end
        end
        if #matched > 0 then
            return matched
        end
    end
    return list
end

local function stillHasFairy(id)
    if not id then
        return false
    end
    id = tostring(id)
    for _, e in ipairs(getLooseTargets()) do
        if tostring(e.Id) == id then
            return true
        end
    end
    return false
end

local function fireCatchPrompt(prompt)
    if not prompt then
        return false
    end
    local ok = false
    pcall(function()
        if fireproximityprompt then
            fireproximityprompt(prompt)
            ok = true
        end
    end)
    if not ok then
        pcall(function()
            prompt:InputHoldBegin()
            task.wait(0.05)
            prompt:InputHoldEnd()
            ok = true
        end)
    end
    return ok
end

local function fireCatchIds(id)
    if not CollectLooseRemote or id == nil or id == "" then
        return false
    end
    local s = tostring(id)
    fireRE(CollectLooseRemote, s)
    if s:sub(1, 1) == "{" and s:sub(-1) == "}" then
        fireRE(CollectLooseRemote, s:sub(2, -2))
    else
        fireRE(CollectLooseRemote, "{" .. s .. "}")
    end
    return true
end

local function getData()
    if not DataService or type(DataService.GetData) ~= "function" then
        return nil
    end
    local ok, data = pcall(function()
        return DataService:GetData()
    end)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end

local function getFairyData(data)
    data = data or getData()
    return type(data) == "table" and type(data.FairyEvent) == "table" and data.FairyEvent or nil
end

local function getFairyPoints(data)
    data = data or getData()
    local sc = type(data) == "table" and data.SpecialCurrency
    return tonumber(sc and sc.FairyPoints) or 0
end

local function numFrom(t, ...)
    if type(t) ~= "table" then
        return nil
    end
    for i = 1, select("#", ...) do
        local v = t[select(i, ...)]
        if v ~= nil then
            return tonumber(v)
        end
    end
    return nil
end

local function fountainTargetForWish(wish)
    wish = math.floor(tonumber(wish) or 1)
    if wish < 1 then
        wish = 1
    end
    local tiers = FairyMilestones and FairyMilestones.TierToFountainProgress
    if type(tiers) == "table" then
        local t = tonumber(tiers[wish]) or tonumber(tiers[tostring(wish)])
        if t and t > 0 then
            return t
        end
    end
    local fallback = { 100, 200, 300, 500, 800 }
    return fallback[wish] or fallback[#fallback]
end

local function fountainInfo(fe)
    fe = fe or getFairyData()
    local q = type(fe) == "table" and fe.FairyQuests or nil
    local wish = numFrom(fe, "WishLevel") or numFrom(q, "WishLevel") or 0
    local actual = numFrom(fe, "FairyFountainProgressActual", "FairyFountainProgressVisual")
        or numFrom(q, "FairyFountainProgressActual", "FairyFountainProgressVisual")
        or 0
    local target = numFrom(fe, "FairyFountainProgressTarget")
        or numFrom(q, "FairyFountainProgressTarget")
        or fountainTargetForWish(wish)
    if not target or target <= 0 then
        target = fountainTargetForWish(wish)
    end
    local questDay = numFrom(q, "Day") or numFrom(fe, "QuestDay") or 0
    local trackDone = (q and q.TrackCompleted == true) or (fe and fe.TrackCompleted == true)
    return actual, target, wish, questDay, trackDone
end

local function countLooseFairies()
    return #getLooseTargets()
end

local function findJarTool()
    local function scan(parent)
        if not parent then
            return nil
        end
        for _, t in ipairs(parent:GetChildren()) do
            if t:IsA("Tool") then
                local n = tostring(t.Name or ""):lower()
                local item = tostring(t:GetAttribute("ItemName") or ""):lower()
                if n:find("jar", 1, true) and n:find("fairy", 1, true) then
                    return t
                end
                if item == "fairy jar" or (item:find("jar", 1, true) and item:find("fairy", 1, true)) then
                    return t
                end
                local itemType = tostring(t:GetAttribute("ItemType") or t:GetAttribute("ITEM_TYPE") or "")
                if itemType == "Fairy Jar" or itemType == "J" then
                    return t
                end
            end
        end
        return nil
    end
    return scan(LP.Character) or scan(LP:FindFirstChild("Backpack"))
end

local function tryCatch()
    if fountainStayLeft() > 0 then
        return false, "stay fountain"
    end
    if os.clock() - LAST_CATCH_AT < CATCH_COOLDOWN then
        return false, "catch cooldown"
    end
    if not CollectLooseRemote then
        return false, "no CollectLooseFairy"
    end
    local targets = getLooseTargets()
    if #targets == 0 then
        return false, "no loose fairy"
    end
    local best, bestD = targets[1], math.huge
    for _, e in ipairs(targets) do
        local d = dist3(e.Position)
        if d < bestD then
            best, bestD = e, d
        end
    end
    goNear(best.Position, CATCH_RANGE, "catch")
    if dist3(best.Position) > CATCH_RANGE + 2 then
        goNear(best.Position, CATCH_RANGE, "catch")
    end
    if dist3(best.Position) > CATCH_RANGE + 4 then
        return false, "far from fairy"
    end
    LAST_CATCH_AT = os.clock()
    local hadJar = findJarTool() ~= nil
    fireCatchPrompt(best.Prompt)
    fireCatchIds(best.Id)
    for _ = 1, 8 do
        task.wait(0.25)
        if findJarTool() and not hadJar then
            return true, "caught fairy"
        end
        if best.Id and not stillHasFairy(best.Id) then
            return true, "caught fairy"
        end
    end
    return false, "catch failed"
end

local function tryJar()
    if fountainStayLeft() > 0 then
        return false, "stay fountain"
    end
    local jar = findJarTool()
    if not jar then
        return false, "no jar"
    end
    local pos = fountainPos()
    if pos and distTo(pos) > FOUNTAIN_RANGE then
        goNear(pos, FOUNTAIN_RANGE, "fountain")
        task.wait(0.15)
    end
    equipTool(jar)
    task.wait(0.1)
    local fe = getFairyData()
    local before = tonumber(fe and fe.SubmittedFairyJars) or 0
    local fired = false
    if SubmitAllJarRemote then
        fired = fireRE(SubmitAllJarRemote) or fired
    end
    if SubmitJarRemote then
        fired = fireRE(SubmitJarRemote) or fired
    end
    if not fired then
        return false, "no jar remote"
    end
    task.wait(0.3)
    unequipTools()
    fe = getFairyData()
    local after = tonumber(fe and fe.SubmittedFairyJars) or 0
    if after > before or findJarTool() == nil then
        return true, "submitted jar"
    end
    return false, "jar submit fail"
end

local function getPendingRewards()
    local fe = getFairyData()
    local q = type(fe) == "table" and fe.FairyQuests or nil
    local pending = q and q.PendingRewards
    return type(pending) == "table" and pending or {}
end

local function getCompletionSource()
    local fe = getFairyData()
    local q = type(fe) == "table" and fe.FairyQuests or nil
    return q and q.CompletionSource or nil
end

local function getIncompleteQuests()
    local out = {}
    local fe = getFairyData()
    local q = type(fe) == "table" and fe.FairyQuests or nil
    local containers = q and q.Containers
    if type(containers) ~= "table" or type(QuestsController) ~= "table" then
        return out
    end
    local getC = QuestsController.GetContainerFromId
    if type(getC) ~= "function" then
        return out
    end
    for _, id in pairs(containers) do
        local ok, cont = pcall(getC, QuestsController, tostring(id))
        local quests = ok and type(cont) == "table" and cont.Quests
        if type(quests) == "table" then
            for _, quest in pairs(quests) do
                if type(quest) == "table" and quest.Completed ~= true then
                    local args = quest.Arguments
                    local plant = type(args) == "table" and args[1]
                    local mut = type(args) == "table" and args[2]
                    local prog = tonumber(quest.Progress) or 0
                    local tgt = tonumber(quest.Target) or 1
                    if type(plant) == "string" and plant ~= "" and prog < tgt then
                        out[#out + 1] = {
                            plant = plant,
                            mut = type(mut) == "string" and mut or nil,
                        }
                    end
                end
            end
        end
    end
    return out
end

local function toolMatchesQuest(tool, quest)
    if not tool or type(quest) ~= "table" then
        return false
    end
    local want = tostring(quest.plant or ""):lower()
    if want == "" then
        return false
    end
    local have = fruitPlantName(tool):lower():gsub("^[g]limmering%s+", "")
    if have ~= want then
        return false
    end
    local mut = tostring(quest.mut or ""):lower()
    if mut == "glimmering" then
        return isGlimmeringTool(tool)
    end
    return isHoldableFruitTool(tool)
end

local function findQuestFruitTool(quests)
    local function scan(parent)
        if not parent then
            return nil
        end
        for _, t in ipairs(parent:GetChildren()) do
            if t:IsA("Tool") then
                for i = 1, #quests do
                    if toolMatchesQuest(t, quests[i]) then
                        return t, quests[i]
                    end
                end
            end
        end
        return nil
    end
    local char = LP.Character
    if char then
        local held = char:FindFirstChildOfClass("Tool")
        if held then
            for i = 1, #quests do
                if toolMatchesQuest(held, quests[i]) then
                    return held, quests[i]
                end
            end
        end
        local t = scan(char)
        if t then
            return t
        end
    end
    return scan(LP:FindFirstChild("Backpack"))
end

local function getPlantsFolder(farm)
    farm = farm or getOwnFarm()
    if not farm then
        return nil
    end
    local important = farm:FindFirstChild("Important")
    local plants = important and important:FindFirstChild("Plants_Physical")
    if plants then
        return plants
    end
    return farm:FindFirstChild("Plants_Physical", true)
end

local function cleanGardenPlantName(plant)
    if not plant then
        return ""
    end
    local n = plant:GetAttribute("ItemName")
        or plant:GetAttribute("PlantName")
        or plant:GetAttribute("SeedName")
        or plant.Name
    n = tostring(n or "")
    n = n:gsub("%s*%[.-%]$", ""):gsub("%s*%(%d+%)$", "")
    return n:gsub("^%s+", ""):gsub("%s+$", "")
end

local function countGardenPlant(plantName)
    local want = tostring(plantName or ""):lower()
    if want == "" then
        return 0
    end
    local folder = getPlantsFolder()
    if not folder then
        return 0
    end
    local n = 0
    for _, plant in ipairs(folder:GetChildren()) do
        if cleanGardenPlantName(plant):lower() == want then
            n = n + 1
        end
    end
    return n
end

local function gardenHasPlant(plantName)
    return countGardenPlant(plantName) > 0
end

-- Seed detect = Auto Event Fall Market (isSeedTool / seedNameOf / EquipTool)
local function cleanSeedName(s)
    local n = tostring(s or "")
    n = n:gsub("%s*%[.-%]$", "")
    n = n:gsub("%s*%(%d+%)$", "")
    n = n:gsub("%s+[Ss]eed%s*$", "")
    n = n:gsub("^%s+", ""):gsub("%s+$", "")
    return n
end

local function isSeedTool(tool)
    if not tool or not tool:IsA("Tool") then
        return false
    end
    if tool:HasTag("FoodTool") then
        return false
    end
    local nm = tostring(tool.Name or ""):lower()
    if nm:find("food", 1, true) or nm:find("corndog", 1, true) or nm:find("smoothie", 1, true) or nm:find("wreath", 1, true) then
        return false
    end
    if not nm:find("seed", 1, true) or nm:find("seed pack", 1, true) then
        return false
    end
    local it = tostring(tool:GetAttribute("ItemType") or tool:GetAttribute("ITEM_TYPE") or ""):lower()
    if it == "j" or it == "holdable" or it == "fruit" or it == "u" or it == "food" or it == "w" or it == "a" then
        return false
    end
    if it ~= "" and it ~= "seed" and it ~= "n" then
        return false
    end
    return true
end

local function seedNameOf(tool)
    if not tool then
        return ""
    end
    return cleanSeedName(tool:GetAttribute("ItemName") or tool.Name)
end

local function findSeedTool(plantName)
    local want = cleanSeedName(plantName):lower()
    if want == "" then
        return nil, nil
    end
    local function scan(container)
        if not container then
            return nil, nil
        end
        for _, tool in ipairs(container:GetChildren()) do
            if isSeedTool(tool) then
                local sn = seedNameOf(tool)
                if sn:lower() == want then
                    return tool, sn
                end
            end
        end
        return nil, nil
    end
    local bag = LP and LP:FindFirstChild("Backpack")
    local t, n = scan(bag)
    if t then
        return t, n
    end
    return scan(LP.Character)
end

local function equipSeedTool(tool)
    if not isSeedTool(tool) then
        return false
    end
    local char = LP.Character
    local bag = LP and LP:FindFirstChild("Backpack")
    if not char or not tool then
        return false
    end
    if tool.Parent ~= bag and tool.Parent ~= char then
        return false
    end
    unequipTools()
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:EquipTool(tool)
        end)
    else
        tool.Parent = char
    end
    task.wait(0.15)
    if not isSeedTool(tool) or tool.Parent ~= char then
        unequipTools()
        return false
    end
    return true
end

local function plantWorldPos(plant)
    if not plant then
        return nil
    end
    if plant:IsA("BasePart") then
        return plant.Position
    end
    if plant:IsA("Model") then
        local ok, pivot = pcall(function()
            return plant:GetPivot().Position
        end)
        if ok and pivot then
            return pivot
        end
        if plant.PrimaryPart then
            return plant.PrimaryPart.Position
        end
    end
    local part = plant:FindFirstChildWhichIsA("BasePart", true)
    return part and part.Position or nil
end

local function getCanPlantParts(farm)
    farm = farm or getOwnFarm()
    if not farm then
        return {}
    end
    local out = {}
    local root = farm:FindFirstChild("Important") or farm
    for _, d in ipairs(root:GetDescendants()) do
        if d:IsA("BasePart") and d.Name == "Can_Plant" then
            out[#out + 1] = d
        end
    end
    return out
end

local function plantQuota()
    local n = tonumber(G.AUTO_FAIRY_PLANT_TOTAL)
    if n == nil then
        n = tonumber(_G.AUTO_FAIRY_PLANT_TOTAL)
    end
    if n == nil then
        n = tonumber(AUTO_FAIRY_PLANT_TOTAL)
    end
    n = math.max(0, math.floor(n or 1))
    AUTO_FAIRY_PLANT_TOTAL = n
    return n
end

local function middlePlantPlots(farm)
    local parts = getCanPlantParts(farm)
    if #parts == 0 then
        return {}
    end
    local center = gardenCenterPos()
    if not center then
        local hrp = getHrp()
        center = hrp and hrp.Position
    end
    if not center then
        return { parts[1] }
    end
    local ranked = {}
    for i = 1, #parts do
        local p = parts[i]
        local dx = p.Position.X - center.X
        local dz = p.Position.Z - center.Z
        ranked[i] = {
            part = p,
            d = dx * dx + dz * dz,
            large = math.max(p.Size.X, p.Size.Z) >= 10,
        }
    end
    table.sort(ranked, function(a, b)
        return a.d < b.d
    end)
    local out = {}
    if ranked[1] and ranked[1].large then
        for i = 1, #ranked do
            if ranked[i].large then
                out[#out + 1] = ranked[i].part
                if #out >= 2 then
                    break
                end
            end
        end
        return out
    end
    local n = math.min(#ranked, 24)
    for i = 1, n do
        out[i] = ranked[i].part
    end
    return out
end

local function gridSlotsOnPlot(part)
    local out = {}
    if not part then
        return out
    end
    local cf = part.CFrame
    local hx = part.Size.X * 0.5 * 0.78
    local hz = part.Size.Z * 0.5 * 0.78
    local yOff = part.Size.Y * 0.5 + 0.05
    local spacing = PLANT_SPACING
    local nx = math.max(0, math.floor(hx / spacing))
    local nz = math.max(0, math.floor(hz / spacing))
    local scored = {}
    for dx = -nx, nx do
        for dz = -nz, nz do
            local lx = dx * spacing
            local lz = dz * spacing
            if math.abs(lx) <= hx + 0.01 and math.abs(lz) <= hz + 0.01 then
                scored[#scored + 1] = { lx = lx, lz = lz, d2 = lx * lx + lz * lz }
            end
        end
    end
    table.sort(scored, function(a, b)
        if a.d2 ~= b.d2 then
            return a.d2 < b.d2
        end
        if a.lz ~= b.lz then
            return a.lz < b.lz
        end
        return a.lx < b.lx
    end)
    for i = 1, #scored do
        local s = scored[i]
        out[i] = (cf * CFrame.new(s.lx, yOff, s.lz)).Position
    end
    return out
end

local function buildFairyPlantSlots(farm)
    local plots = middlePlantPlots(farm)
    local lists = {}
    for i = 1, #plots do
        lists[i] = gridSlotsOnPlot(plots[i])
    end
    local slots = {}
    local maxN = 0
    for i = 1, #lists do
        if #lists[i] > maxN then
            maxN = #lists[i]
        end
    end
    for i = 1, maxN do
        for p = 1, #lists do
            if lists[p][i] then
                slots[#slots + 1] = lists[p][i]
            end
        end
    end
    return slots
end

local function pickPlantSlot(farm, plantsFolder)
    farm = farm or getOwnFarm()
    if not farm then
        return nil, "no own farm"
    end
    local plots = middlePlantPlots(farm)
    if #plots == 0 then
        return nil, "no Can_Plant"
    end
    local sig = tostring(#plots)
    for i = 1, #plots do
        local p = plots[i]
        sig = sig .. "|" .. tostring(p:GetFullName()) .. ":" .. tostring(p.Size)
    end
    if fairyPlantSlots == nil or fairyPlantSlotSig ~= sig then
        fairyPlantSlots = buildFairyPlantSlots(farm)
        fairyPlantSlotSig = sig
        plantSlotCursor = 1
    end
    local slots = fairyPlantSlots
    if type(slots) ~= "table" or #slots == 0 then
        return nil, "no empty slot"
    end
    local occupied = {}
    if plantsFolder then
        for _, p in ipairs(plantsFolder:GetChildren()) do
            local wp = plantWorldPos(p)
            if wp then
                occupied[#occupied + 1] = wp
            end
        end
    end
    local min2 = PLANT_SPACING * PLANT_SPACING
    local n = #slots
    local start = plantSlotCursor
    if start < 1 or start > n then
        start = 1
    end
    for step = 0, n - 1 do
        local idx = ((start - 1 + step) % n) + 1
        local pos = slots[idx]
        if pos then
            local free = true
            for i = 1, #occupied do
                local o = occupied[i]
                local dx, dz = pos.X - o.X, pos.Z - o.Z
                if dx * dx + dz * dz < min2 then
                    free = false
                    break
                end
            end
            if free then
                plantSlotCursor = (idx % n) + 1
                return pos
            end
        end
    end
    return nil, "no empty slot"
end

local function tryPlantQuest()
    if fountainStayLeft() > 0 then
        return false, "stay fountain"
    end
    if os.clock() - LAST_PLANT_AT < PLANT_COOLDOWN then
        return false, "plant cooldown"
    end
    local quests = getIncompleteQuests()
    local names = {}
    local seen = {}
    for i = 1, #quests do
        local plantName = quests[i].plant
        if type(plantName) == "string" and plantName ~= "" and not seen[plantName] then
            seen[plantName] = true
            names[#names + 1] = plantName
        end
    end
    if #names == 0 then
        return false, "no quest plant"
    end
    local farm = getOwnFarm()
    if not farm then
        return false, "no own farm"
    end
    local plantsFolder = getPlantsFolder(farm)
    local total = plantQuota()
    local nNames = #names
    local start = plantTypeCursor
    if start < 1 or start > nNames then
        start = 1
    end
    local lastSlotErr = nil
    for step = 0, nNames - 1 do
        local i = ((start + step - 1) % nNames) + 1
        local plantName = names[i]
        local have = countGardenPlant(plantName)
        if total > 0 and have >= total then
            -- enough of this type
        else
            local tool, seedName = findSeedTool(plantName)
            if tool and isSeedTool(tool) then
                plantTypeCursor = i
                if not (PlantRE and PlantRE.Parent) then
                    pcall(function()
                        PlantRE = ReplicatedStorage.GameEvents:FindFirstChild("Plant_RE")
                    end)
                end
                if not PlantRE then
                    return false, "no Plant_RE"
                end
                local placed = false
                local lastFireOk = false
                for _ = 1, 5 do
                    local pos, posErr = pickPlantSlot(farm, plantsFolder)
                    if not pos then
                        lastSlotErr = posErr or "no empty slot"
                        break
                    end
                    if not goPlantPos(pos) then
                        lastSlotErr = "far from plot"
                        break
                    end
                    if not equipSeedTool(tool) then
                        tool, seedName = findSeedTool(plantName)
                        if not tool or not equipSeedTool(tool) then
                            unequipTools()
                            return false, "equip seed failed"
                        end
                    end
                    LAST_PLANT_AT = os.clock()
                    lastFireOk = pcall(function()
                        PlantRE:FireServer(pos, seedName)
                    end)
                    task.wait(0.35)
                    unequipTools()
                    if lastFireOk and countGardenPlant(plantName) > have then
                        placed = true
                        break
                    end
                    tool, seedName = findSeedTool(plantName)
                    if not tool then
                        break
                    end
                end
                if placed then
                    return true, ("planted %s · %d/%s"):format(
                        tostring(seedName),
                        have + 1,
                        total > 0 and tostring(total) or "∞"
                    )
                end
                if lastSlotErr and not lastFireOk then
                    -- try next type
                elseif lastFireOk then
                    lastSlotErr = "plant not placed"
                end
            end
        end
    end
    if lastSlotErr then
        return false, lastSlotErr
    end
    return false, "quest plant skip"
end

local function goFountainRange()
    local pos = fountainPos()
    if not pos then
        return false, "no fountain"
    end
    if distTo(pos) > FOUNTAIN_RANGE then
        goNear(pos, FOUNTAIN_RANGE, "fountain")
        task.wait(0.2)
    end
    if distTo(pos) > FOUNTAIN_RANGE + 8 then
        return false, "far from fountain"
    end
    return true
end

local function submitMoved(beforeActual, beforeFp)
    local afterActual = select(1, fountainInfo())
    local afterFp = getFairyPoints()
    if afterActual > beforeActual then
        return true, "power"
    end
    if afterFp > beforeFp then
        return true, "fp"
    end
    return false, nil
end

local function submitHeldAtFountain(tool, label)
    local near, err = goFountainRange()
    if not near then
        return false, err
    end
    local before = select(1, fountainInfo())
    local fpBefore = getFairyPoints()
    equipTool(tool)
    task.wait(0.2)
    if SubmitFountainHeldRemote then
        fireRE(SubmitFountainHeldRemote)
    end
    if SubmitHeldGenericRemote then
        fireRE(SubmitHeldGenericRemote)
    end
    task.wait(0.35)
    local ok, kind = submitMoved(before, fpBefore)
    if ok then
        markFountainStay()
        FOUNTAIN_RETRY_AT = 0
        unequipTools()
        return true, label or ("fountain " .. kind)
    end
    unequipTools()
    FOUNTAIN_RETRY_AT = math.max(FOUNTAIN_STAY_UNTIL, os.clock()) + GARDEN_RETURN_SEC
    return false, "submit no change"
end

local function submitAllAtFountain()
    local near, err = goFountainRange()
    if not near then
        return false, err
    end
    local before = select(1, fountainInfo())
    local fpBefore = getFairyPoints()
    if SubmitFountainAllRemote then
        fireRE(SubmitFountainAllRemote)
    end
    if SubmitAllGenericRemote then
        fireRE(SubmitAllGenericRemote)
    end
    task.wait(0.45)
    local ok, kind = submitMoved(before, fpBefore)
    if ok then
        markFountainStay()
        FOUNTAIN_RETRY_AT = 0
        return true, "fountain all" .. (kind == "fp" and " fp" or "")
    end
    local tool = findGlimmeringTool()
    if not tool then
        return false, "no glimmering fruit"
    end
    return submitHeldAtFountain(tool, "fountain held")
end

local function tryFountain()
    if fountainStayLeft() <= 0 and os.clock() < FOUNTAIN_RETRY_AT then
        return false, "submit no change"
    end
    local actual, target, wish = fountainInfo()
    local full = target > 0 and actual >= target
    local fp = getFairyPoints()
    local needRestartFp = AUTO_FAIRY_RESTART_ENABLED == true
        and wish >= MAX_WISH
        and fp < RESTART_FP_COST
    local questsOpen = getCompletionSource() == nil
    local quests = questsOpen and getIncompleteQuests() or {}
    if #quests > 0 then
        local qTool = findQuestFruitTool(quests)
        if qTool then
            return submitHeldAtFountain(qTool, "fountain quest")
        end
        if not findGlimmeringTool() then
            return false, "no glimmering fruit"
        end
        return submitAllAtFountain()
    end
    if full and not needRestartFp then
        return false, "fountain full"
    end
    if not findGlimmeringTool() then
        return false, "no glimmering fruit"
    end
    return submitAllAtFountain()
end

local function preferSet()
    local src = AUTO_FAIRY_WISH_REWARDS
    return type(src) == "table" and src or {}
end

local function preferCount(set)
    local n = 0
    for _, v in pairs(set) do
        if v == true then
            n = n + 1
        end
    end
    return n
end

local function rewardKey(reward)
    if type(reward) ~= "table" then
        return ""
    end
    return tostring(reward.Value or reward.Name or "")
end

local function chanceFor(reward, wish)
    if type(reward) ~= "table" then
        return 999
    end
    local listed = tonumber(reward.Chance or reward.chance)
    if listed then
        return listed
    end
    local pools = FairyMilestones and FairyMilestones.Rewards
    if type(pools) ~= "table" then
        return 999
    end
    local key = rewardKey(reward)
    local idx = math.floor(tonumber(wish) or 1)
    if idx < 1 then
        idx = 1
    end
    if idx > #pools then
        idx = #pools
    end
    local best = nil
    for _, ti in ipairs({ idx, idx + 1, idx - 1 }) do
        local tier = pools[ti]
        if type(tier) == "table" then
            for _, row in ipairs(tier) do
                local r = type(row) == "table" and row.Reward
                if type(r) == "table" and tostring(r.Value) == key then
                    local c = tonumber(row.Chance) or 999
                    if not best or c < best then
                        best = c
                    end
                end
            end
        end
    end
    return best or 999
end

local function pickPendingReward(pending, wish)
    local set = preferSet()
    if preferCount(set) > 0 then
        for _, key in ipairs(WISH_REWARD_KEYS) do
            if set[key] == true then
                for _, reward in ipairs(pending) do
                    if type(reward) == "table"
                        and rewardKey(reward) == key
                        and (reward.UUID or reward.uuid)
                    then
                        return reward, key
                    end
                end
            end
        end
    end
    local best, bestC, bestName = nil, nil, nil
    for _, reward in ipairs(pending) do
        if type(reward) == "table" and (reward.UUID or reward.uuid) then
            local c = chanceFor(reward, wish)
            if not bestC or c < bestC then
                best = reward
                bestC = c
                bestName = rewardKey(reward)
            end
        end
    end
    if best then
        return best, bestName
    end
    return nil, nil
end

local function disableFountainPrompts()
    pcall(function()
        local tagged = CollectionService:GetTagged("FairyFountain")
        local extra = workspace:FindFirstChild("Interaction")
        extra = extra and extra:FindFirstChild("FairyEventModel")
        extra = extra and extra:FindFirstChild("WishFountain")
        local roots = {}
        if type(tagged) == "table" then
            for _, inst in ipairs(tagged) do
                roots[#roots + 1] = inst
            end
        end
        if extra then
            roots[#roots + 1] = extra
        end
        for _, root in ipairs(roots) do
            if root then
                if root:IsA("ProximityPrompt") then
                    root.Enabled = false
                end
                for _, d in ipairs(root:GetDescendants()) do
                    if d:IsA("ProximityPrompt") then
                        d.Enabled = false
                    end
                end
            end
        end
    end)
end

local function tryClaim()
    local actual, target, wish = fountainInfo()
    local pending = getPendingRewards()
    local src = getCompletionSource()
    local unclaimed = (#pending > 0) or (src ~= nil)
    if wish >= MAX_WISH and not unclaimed then
        return false, "wish max"
    end
    local ready = unclaimed or (actual >= target)
    if not ready then
        return false, "fountain not full"
    end
    if os.clock() - LAST_CLAIM_AT < CLAIM_COOLDOWN and #pending == 0 then
        return false, "claim cooldown"
    end
    disableFountainPrompts()
    closeFairyGuis()
    LAST_CLAIM_AT = os.clock()
    LAST_CLAIM_WISH = wish
    if #pending == 0 then
        if MakeWishRemote then
            fireRE(MakeWishRemote)
        end
        for _ = 1, 12 do
            task.wait(0.25)
            pending = getPendingRewards()
            if #pending > 0 then
                break
            end
        end
    end
    closeFairyGuis()
    if #pending == 0 then
        return false, "waiting wish roll"
    end
    local picked, name = pickPendingReward(pending, wish)
    if picked then
        local uuid = picked.UUID or picked.uuid
        if ClaimRewardRemote and fireRE(ClaimRewardRemote, uuid) then
            closeFairyGuis()
            return true, "claimed " .. tostring(name)
        end
    end
    local set = preferSet()
    if set.FairyPoints == true and SelectAllRewardRemote then
        fireRE(SelectAllRewardRemote)
        closeFairyGuis()
        return true, "claimed FP"
    end
    local first = pending[1]
    local uuid = type(first) == "table" and (first.UUID or first.uuid)
    if uuid and ClaimRewardRemote and fireRE(ClaimRewardRemote, uuid) then
        closeFairyGuis()
        return true, "claimed " .. tostring(first.Value or "wish")
    end
    closeFairyGuis()
    return false, "no matching wish"
end

local function selectedUpgradeNames()
    local names = {}
    local sel = AUTO_FAIRY_UPGRADES
    if preferCount(sel) > 0 then
        for k, v in pairs(sel) do
            if v == true then
                names[#names + 1] = tostring(k)
            end
        end
        return names
    end
    for _, k in ipairs(FAIRY_UPGRADE_KEYS) do
        names[#names + 1] = k
    end
    if type(FairyUpgradesData) == "table" then
        for k, v in pairs(FairyUpgradesData) do
            if type(k) == "string" and type(v) == "table" and type(v.Upgrades) == "table" then
                local seen = false
                for _, n in ipairs(names) do
                    if n == k then
                        seen = true
                        break
                    end
                end
                if not seen then
                    names[#names + 1] = k
                end
            end
        end
    end
    return names
end

local function upgradesAllMaxed()
    if type(FairyUpgradesData) ~= "table" then
        return false
    end
    local fe = getFairyData()
    local levels = type(fe) == "table" and type(fe.Upgrades) == "table" and fe.Upgrades or {}
    local names = selectedUpgradeNames()
    if #names == 0 then
        return true
    end
    for _, name in ipairs(names) do
        local def = FairyUpgradesData[name]
        if type(def) == "table" and type(def.Upgrades) == "table" then
            local lvl = tonumber(levels[name]) or 0
            if def.Upgrades[lvl + 1] then
                return false
            end
        end
    end
    return true
end

local function tryRestart()
    local _, _, wish = fountainInfo()
    if wish < MAX_WISH then
        return false, "wish not max"
    end
    if getCompletionSource() ~= nil then
        return false, "wish unclaimed"
    end
    if #getPendingRewards() > 0 then
        return false, "wish unclaimed"
    end
    local fp = getFairyPoints()
    if fp < RESTART_FP_COST then
        return false, "need " .. tostring(RESTART_FP_COST) .. " FP"
    end
    if os.clock() - LAST_RESTART_AT < RESTART_COOLDOWN then
        return false, "restart cooldown"
    end
    if not RestartTrackRemote then
        return false, "no RestartFairyTrack"
    end
    LAST_RESTART_AT = os.clock()
    closeFairyGuis()
    if fireRE(RestartTrackRemote) then
        closeFairyGuis()
        return true, "restarted track"
    end
    return false, "restart failed"
end

local function tryUpgrade()
    if AUTO_FAIRY_RESTART_ENABLED == true then
        local _, _, wish = fountainInfo()
        if wish >= MAX_WISH then
            return false, "restart first"
        end
    end
    if os.clock() - LAST_UPGRADE_AT < UPGRADE_COOLDOWN then
        return false, "upgrade cooldown"
    end
    if not UpgradeRemote then
        return false, "no Upgrade"
    end
    if type(FairyUpgradesData) ~= "table" then
        return false, "no upgrade data"
    end
    local fe = getFairyData()
    local levels = type(fe) == "table" and type(fe.Upgrades) == "table" and fe.Upgrades or {}
    local budget = getFairyPoints()
    if budget <= 0 then
        return false, "need FP"
    end
    local names = selectedUpgradeNames()
    local bestName, bestPrice = nil, nil
    for _, name in ipairs(names) do
        local def = FairyUpgradesData[name]
        if type(def) == "table" and type(def.Upgrades) == "table" then
            local lvl = tonumber(levels[name]) or 0
            local nxt = def.Upgrades[lvl + 1]
            local price = nxt and tonumber(nxt.Price)
            if price and price <= budget then
                if not bestPrice or price < bestPrice then
                    bestName = name
                    bestPrice = price
                end
            end
        end
    end
    if not bestName then
        return false, "upgrade max/fp"
    end
    LAST_UPGRADE_AT = os.clock()
    closeFairyGuis()
    if fireRE(UpgradeRemote, bestName) then
        closeFairyGuis()
        return true, "upgraded " .. bestName
    end
    return false, "upgrade failed"
end

local function formatDuration(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    local d = math.floor(sec / 86400)
    local h = math.floor((sec % 86400) / 3600)
    local m = math.floor((sec % 3600) / 60)
    local s = sec % 60
    if d > 0 then
        return string.format("%dd %dh", d, h)
    end
    if h > 0 then
        return string.format("%dh %dm", h, m)
    end
    if m > 0 then
        return string.format("%dm %ds", m, s)
    end
    return string.format("%ds", s)
end

local function eventRemainText()
    local ok, rem = pcall(function()
        if EventRotationUtils and type(EventRotationUtils.GetTimeTillEventEnd) == "function" then
            return EventRotationUtils:GetTimeTillEventEnd()
        end
        return nil
    end)
    if ok and type(rem) == "number" and rem > 0 then
        return "event " .. formatDuration(rem)
    end
    if ON_EVENT then
        return "event live"
    end
    return "event —"
end

local function waveRemainText()
    local now = workspace:GetServerTimeNow()
    local leaveAt = LP:GetAttribute("FairyWaveEnd")
    local arriveAt = LP:GetAttribute("FairyNextWaveStart")
    if type(leaveAt) == "number" and now < leaveAt then
        local t = leaveAt - now
        if t < 1 then
            return "fairies leaving"
        end
        return "leave " .. formatDuration(t)
    end
    if type(arriveAt) == "number" then
        local t = math.max(arriveAt - now, 0)
        if t < 1 then
            return "fairies arriving"
        end
        return "arrive " .. formatDuration(t)
    end
    return "wave —"
end

function M.GetStatusText()
    syncGlobalsFromState()
    ON_EVENT = isFairyLive()
    local data = getData()
    local fe = getFairyData(data)
    local fp = getFairyPoints(data)
    local actual, target, wish = fountainInfo(fe)
    local jars = tonumber(fe and fe.SubmittedFairyJars) or 0
    local loose = countLooseFairies()
    local glimmer = countGlimmeringTools()
    local catchOn = AUTO_FAIRY_CATCH_ENABLED == true and "ON" or "OFF"
    local jarOn = AUTO_FAIRY_JAR_ENABLED == true and "ON" or "OFF"
    local ftnOn = AUTO_FAIRY_FOUNTAIN_ENABLED == true and "ON" or "OFF"
    local claimOn = AUTO_FAIRY_CLAIM_ENABLED == true and "ON" or "OFF"
    local restartOn = AUTO_FAIRY_RESTART_ENABLED == true and "ON" or "OFF"
    local upgradeOn = AUTO_FAIRY_UPGRADE_ENABLED == true and "ON" or "OFF"
    local plantOn = AUTO_FAIRY_PLANT_ENABLED == true and "ON" or "OFF"
    local phase = LAST_STATUS ~= "" and LAST_STATUS or "idle"
    if type(phase) == "string" and phase:find("stay fountain", 1, true) then
        phase = "idle"
    end
    if not ON_EVENT then
        phase = "not on event"
    elseif RUNNING and (phase == "idle" or phase == "stopped") then
        phase = "running"
    end
    return string.format(
        "Wish %d/%d · fountain %d/%d · FP %d · jars %d · loose %d · glimmer %d\n%s\nCatch %s · Jar %s · Fountain %s · Claim %s · Restart %s · Upgrade %s · Plant %s\n%s",
        wish,
        MAX_WISH,
        actual,
        target,
        fp,
        jars,
        loose,
        glimmer,
        waveRemainText(),
        catchOn,
        jarOn,
        ftnOn,
        claimOn,
        restartOn,
        upgradeOn,
        plantOn,
        phase
    )
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if not anyEnabled() then
            break
        end
        ON_EVENT = isFairyLive()
        if not ON_EVENT then
            publishStatus("not on event")
            task.wait(clampDelay(AUTO_FAIRY_DELAY_SEC))
        else
            resolveRemotes()
            hookCloseOpenFairyUI()
            disableFountainPrompts()
            closeFairyGuis()
            local didWork = false

            if AUTO_FAIRY_CLAIM_ENABLED == true then
                local ok, msg = tryClaim()
                if ok then
                    publishStatus(msg)
                    didWork = true
                    task.wait(FIRE_WAIT)
                elseif msg and not didWork
                    and msg ~= "fountain not full"
                    and msg ~= "claim cooldown"
                    and msg ~= "wish max"
                then
                    publishStatus(msg)
                end
            end

            if AUTO_FAIRY_CATCH_ENABLED == true then
                local ok, msg = tryCatch()
                if ok then
                    publishStatus(msg)
                    didWork = true
                    task.wait(FIRE_WAIT)
                elseif msg and not didWork
                    and msg ~= "catch cooldown"
                    and msg ~= "stay fountain"
                    and msg ~= "no loose fairy"
                    and msg ~= "catch failed"
                    and msg ~= "far from fairy"
                then
                    publishStatus(msg)
                end
            end

            if AUTO_FAIRY_JAR_ENABLED == true then
                local ok, msg = tryJar()
                if ok then
                    publishStatus(msg)
                    didWork = true
                    task.wait(FIRE_WAIT)
                elseif msg and not didWork
                    and msg ~= "no jar"
                    and msg ~= "jar submit fail"
                    and msg ~= "no jar remote"
                    and msg ~= "stay fountain"
                then
                    publishStatus(msg)
                end
            end

            local _, _, wishNow = fountainInfo()
            local fpNow = getFairyPoints()
            local saveFp = AUTO_FAIRY_RESTART_ENABLED == true
                and wishNow >= MAX_WISH
                and fpNow < RESTART_FP_COST

            if AUTO_FAIRY_FOUNTAIN_ENABLED == true then
                local ok, msg = tryFountain()
                if ok then
                    publishStatus(msg)
                    didWork = true
                    task.wait(FIRE_WAIT)
                elseif msg and not didWork
                    and msg ~= "fountain full"
                    and msg ~= "waiting quest fruit"
                    and msg ~= "no glimmering fruit"
                    and msg ~= "submit no change"
                then
                    publishStatus(msg)
                end
            end

            if AUTO_FAIRY_PLANT_ENABLED == true and fountainStayLeft() <= 0 then
                local ok, msg = tryPlantQuest()
                if ok then
                    publishStatus(msg)
                    didWork = true
                    task.wait(FIRE_WAIT)
                elseif msg and not didWork
                    and msg ~= "plant cooldown"
                    and msg ~= "stay fountain"
                    and msg ~= "no quest plant"
                    and msg ~= "quest plant skip"
                then
                    publishStatus(msg)
                end
            end

            if AUTO_FAIRY_RESTART_ENABLED == true then
                local ok, msg = tryRestart()
                if ok then
                    publishStatus(msg)
                    didWork = true
                    task.wait(FIRE_WAIT)
                elseif msg and not didWork
                    and msg ~= "wish not max"
                    and msg ~= "restart cooldown"
                    and msg ~= "wish unclaimed"
                    and msg ~= "need " .. tostring(RESTART_FP_COST) .. " FP"
                then
                    publishStatus(msg)
                end
            end

            if AUTO_FAIRY_UPGRADE_ENABLED == true then
                local ok, msg = tryUpgrade()
                if ok then
                    publishStatus(msg)
                    didWork = true
                    task.wait(FIRE_WAIT)
                elseif msg and not didWork
                    and msg ~= "upgrade cooldown"
                    and msg ~= "upgrade max/fp"
                    and msg ~= "need FP"
                    and msg ~= "restart first"
                then
                    publishStatus(msg)
                end
            end

            if fountainStayLeft() <= 0 then
                if NEED_GARDEN_RETURN then
                    returnToGarden()
                elseif DID_TP and countLooseFairies() == 0 then
                    returnToGarden()
                end
            end
            if not didWork then
                if saveFp then
                    publishStatus(("need %d FP (%d)"):format(RESTART_FP_COST, fpNow))
                elseif LAST_STATUS == "running" or LAST_STATUS == "" or LAST_STATUS == "waiting" then
                    publishStatus("idle")
                end
            end
            task.wait(clampDelay(AUTO_FAIRY_DELAY_SEC))
        end
    end
    RUNNING = false
    if LAST_STATUS == "running" then
        publishStatus("stopped")
    end
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
end

function M.Start()
    M.SyncFromGlobals()
    if RUNNING then return end
    if not anyEnabled() then return end
    RUNNING = true
    STOP_TOKEN = STOP_TOKEN + 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN = STOP_TOKEN + 1
    publishStatus("stopped")
end

