        if map[1] ~= nil then
            for _, k in ipairs(map) do
                if k ~= nil and k ~= "" then
                    set[tostring(k)] = true
                end
            end
        else
            for k, v in pairs(map) do
                if v == true or v == 1 then
                    set[tostring(k)] = true
                end
            end
        end
    end
    AUTO_FAIRY_WISH_REWARDS = set
    G.AUTO_FAIRY_WISH_REWARDS = set
    _G.AUTO_FAIRY_WISH_REWARDS = set
