            -- auto_wise_owl.lua
-- Harvest Moon OWL (Wise Owl) — Auto Submit / Submit All
-- NEW event (separate from auto_harvest_moon.lua)
--
-- Config : GameConfigController "HarvestMoonOwlConfig"
-- Remotes: ReplicatedStorage.GameEvents.HarvestMoonOwl.*
--   SubmitHarvestMoonOwl / SubmitAllHarvestMoonOwl / PreviewHarvestMoonOwl

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local EQUIP_WAIT = 0.2
local FIRE_WAIT  = 0.3
local MIN_DELAY  = 0.05
local MAX_DELAY  = 300
local DEFAULT_DELAY = 1.0

local RUNNING    = false
local STOP_TOKEN = 0
local LAST_STATUS = "idle"
local LAST_FIRE_AT = 0

local GameConfigController = nil
local DataService = nil
local PlantTraitsData = nil
local CFG_CACHE = nil

local FolderRemote = nil
local SubmitRemote = nil
local SubmitAllRemote = nil
local PreviewRemote = nil

pcall(function()
    ReplicatedStorage:WaitForChild("Modules", 8)
end)

pcall(function()
    GameConfigController = require(ReplicatedStorage.Modules.GameConfigController)
end)
pcall(function()
    DataService = require(ReplicatedStorage.Modules.DataService)
end)
pcall(function()
    PlantTraitsData = require(ReplicatedStorage.Modules.PlantTraitsData)
end)

----------------------------------------------------------------
-- Globals / state
----------------------------------------------------------------
AUTO_WISE_OWL_SUBMIT_ENABLED = (AUTO_WISE_OWL_SUBMIT_ENABLED == true)
AUTO_WISE_OWL_SUBMIT_ALL = (AUTO_WISE_OWL_SUBMIT_ALL ~= false) -- default ON
AUTO_WISE_OWL_DELAY_SEC = tonumber(AUTO_WISE_OWL_DELAY_SEC) or DEFAULT_DELAY
AUTO_WISE_OWL_PLANT_ENABLED = (AUTO_WISE_OWL_PLANT_ENABLED == true)
AUTO_WISE_OWL_PLANT_TOTAL = math.max(0, math.floor(tonumber(AUTO_WISE_OWL_PLANT_TOTAL) or 10)) -- default 10; 0 = ∞ per trait

local PLANT_RUNNING = false
local PLANT_STOP_TOKEN = 0
local PLANT_DONE = 0
local PLANT_TRAIT_KEY = ""
local LAST_PLANT_STATUS = "idle"

local PlantRE = nil
local GetFarmAsync = nil
pcall(function()
    PlantRE = ReplicatedStorage.GameEvents:WaitForChild("Plant_RE", 5)
end)
pcall(function()
    GetFarmAsync = require(ReplicatedStorage.Modules.GetFarmAsync)
end)

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_WISE_OWL_STATUS = LAST_STATUS
    _G.__AUTO_WISE_OWL_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_wise_owl
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function syncGlobalsFromState()
    local st = getState()

    if G.AUTO_WISE_OWL_SUBMIT_ENABLED == true
        or _G.AUTO_WISE_OWL_SUBMIT_ENABLED == true
        or AUTO_WISE_OWL_SUBMIT_ENABLED == true
        or st.submit_enabled == true then
        AUTO_WISE_OWL_SUBMIT_ENABLED = true
    else
        AUTO_WISE_OWL_SUBMIT_ENABLED = false
    end

    local submitAll = G.AUTO_WISE_OWL_SUBMIT_ALL
    if submitAll == nil then submitAll = _G.AUTO_WISE_OWL_SUBMIT_ALL end
    if submitAll == nil then submitAll = AUTO_WISE_OWL_SUBMIT_ALL end
    if submitAll == nil then submitAll = st.submit_all end
    AUTO_WISE_OWL_SUBMIT_ALL = (submitAll ~= false)

    local delaySrc = G.AUTO_WISE_OWL_DELAY_SEC
    if delaySrc == nil then delaySrc = _G.AUTO_WISE_OWL_DELAY_SEC end
    if delaySrc == nil then delaySrc = AUTO_WISE_OWL_DELAY_SEC end
    if delaySrc == nil then delaySrc = st.delaySec end
    AUTO_WISE_OWL_DELAY_SEC = clampDelay(delaySrc)

    if G.AUTO_WISE_OWL_PLANT_ENABLED == true
        or _G.AUTO_WISE_OWL_PLANT_ENABLED == true
        or AUTO_WISE_OWL_PLANT_ENABLED == true
        or st.plant_enabled == true then
        AUTO_WISE_OWL_PLANT_ENABLED = true
    else
        AUTO_WISE_OWL_PLANT_ENABLED = false
    end

    local plantTotal = G.AUTO_WISE_OWL_PLANT_TOTAL
    if plantTotal == nil then plantTotal = _G.AUTO_WISE_OWL_PLANT_TOTAL end
    if plantTotal == nil then plantTotal = AUTO_WISE_OWL_PLANT_TOTAL end
    if plantTotal == nil then plantTotal = st.plant_total end
    AUTO_WISE_OWL_PLANT_TOTAL = math.max(0, math.floor(tonumber(plantTotal) or 10))

    G.AUTO_WISE_OWL_SUBMIT_ENABLED = AUTO_WISE_OWL_SUBMIT_ENABLED
    G.AUTO_WISE_OWL_SUBMIT_ALL = AUTO_WISE_OWL_SUBMIT_ALL
    G.AUTO_WISE_OWL_DELAY_SEC = AUTO_WISE_OWL_DELAY_SEC
    G.AUTO_WISE_OWL_PLANT_ENABLED = AUTO_WISE_OWL_PLANT_ENABLED
    G.AUTO_WISE_OWL_PLANT_TOTAL = AUTO_WISE_OWL_PLANT_TOTAL
    _G.AUTO_WISE_OWL_SUBMIT_ENABLED = AUTO_WISE_OWL_SUBMIT_ENABLED
    _G.AUTO_WISE_OWL_SUBMIT_ALL = AUTO_WISE_OWL_SUBMIT_ALL
    _G.AUTO_WISE_OWL_DELAY_SEC = AUTO_WISE_OWL_DELAY_SEC
    _G.AUTO_WISE_OWL_PLANT_ENABLED = AUTO_WISE_OWL_PLANT_ENABLED
    _G.AUTO_WISE_OWL_PLANT_TOTAL = AUTO_WISE_OWL_PLANT_TOTAL
end

----------------------------------------------------------------
-- Config / remotes
----------------------------------------------------------------
local function getConfig()
    if CFG_CACHE then return CFG_CACHE end
    local cfg = nil
    if GameConfigController then
        pcall(function()
            cfg = GameConfigController:GetConfig("HarvestMoonOwlConfig")
        end)
    end
    if type(cfg) ~= "table" then
        cfg = {}
    end

    cfg.SUBMIT_REMOTE = cfg.SUBMIT_REMOTE or "SubmitHarvestMoonOwl"
    cfg.SUBMIT_ALL_REMOTE = cfg.SUBMIT_ALL_REMOTE or "SubmitAllHarvestMoonOwl"
    cfg.PREVIEW_REMOTE = cfg.PREVIEW_REMOTE or "PreviewHarvestMoonOwl"
    cfg.WORKSPACE_TRAIT_ATTR = cfg.WORKSPACE_TRAIT_ATTR or "HarvestMoonOwl_Trait"
    cfg.WORKSPACE_MUTATION_ATTR = cfg.WORKSPACE_MUTATION_ATTR
        or cfg.MUTATION_ATTR
        or "HarvestMoonOwl_Mutation"
    cfg.FOLDER = cfg.FOLDER or "HarvestMoonOwl"
    cfg.SUBMIT_DEBOUNCE = tonumber(cfg.SUBMIT_DEBOUNCE) or 0.25
    cfg.TRAIT_INTERVAL = tonumber(cfg.TRAIT_INTERVAL) or 3600
    cfg.POINTS_REQUIRED = tonumber(cfg.POINTS_REQUIRED) or 0

    CFG_CACHE = cfg
    return cfg
end

local function resolveRemotes()
    local cfg = getConfig()
    local ge = ReplicatedStorage:FindFirstChild("GameEvents")
    if not ge then return end

    if not FolderRemote or FolderRemote.Parent ~= ge then
        FolderRemote = ge:FindFirstChild(tostring(cfg.FOLDER or "HarvestMoonOwl"))
        if not FolderRemote then
            pcall(function()
                FolderRemote = ge:WaitForChild(tostring(cfg.FOLDER or "HarvestMoonOwl"), 2)
            end)
        end
    end

    local function findIn(parent, name)
        if not parent or not name then return nil end
        local r = parent:FindFirstChild(name)
        if r then return r end
        return ge:FindFirstChild(name)
    end

    SubmitRemote = SubmitRemote or findIn(FolderRemote, tostring(cfg.SUBMIT_REMOTE))
    SubmitAllRemote = SubmitAllRemote or findIn(FolderRemote, tostring(cfg.SUBMIT_ALL_REMOTE))
    PreviewRemote = PreviewRemote or findIn(FolderRemote, tostring(cfg.PREVIEW_REMOTE))
end

----------------------------------------------------------------
-- Owl data / craving
----------------------------------------------------------------
local function getOwlData()
    if not DataService then return nil end
    local ok, data = pcall(function()
        return DataService:GetData()
    end)
    if not ok or type(data) ~= "table" then return nil end
    local owl = data.HarvestMoonOwlData
    return type(owl) == "table" and owl or nil
end

local function isOnCooldown()
    local owl = getOwlData()
    if owl == nil then return false end
    local ends = tonumber(owl.CooldownEndsAt) or 0
    if ends <= 0 then return false end
    return workspace:GetServerTimeNow() < ends
end

local function cooldownRemain()
    local owl = getOwlData()
    if owl == nil then return 0 end
    local ends = tonumber(owl.CooldownEndsAt) or 0
    if ends <= 0 then return 0 end
    return math.max(0, ends - workspace:GetServerTimeNow())
end

local function cravingRemain()
    local cfg = getConfig()
    local interval = tonumber(cfg.TRAIT_INTERVAL) or 3600
    if interval <= 0 then return 0 end
    local now = workspace:GetServerTimeNow()
    if now <= 0 then return 0 end
    return math.max(0, interval - (now % interval))
end

local function getCravingTrait()
    local cfg = getConfig()
    local key = tostring(cfg.WORKSPACE_TRAIT_ATTR or "HarvestMoonOwl_Trait")
    local v = workspace:GetAttribute(key)
    if v == nil or tostring(v) == "" then
        local owl = getOwlData()
        if owl then
            v = owl.Trait or owl.CurrentTrait or owl.CravingTrait
        end
    end
    return tostring(v or "")
end

local function getCravingMutation()
    local cfg = getConfig()
    local key = tostring(cfg.WORKSPACE_MUTATION_ATTR or "HarvestMoonOwl_Mutation")
    local v = workspace:GetAttribute(key)
    if v == nil or tostring(v) == "" then
        local owl = getOwlData()
        if owl then
            v = owl.Mutation or owl.CurrentMutation
        end
    end
    local s = tostring(v or "")
    if s == "" or s == "None" or s == "nil" then
        return ""
    end
    return s
end

local function getProgress()
    local cfg = getConfig()
    local owl = getOwlData()
    local n = 0
    local maxN = tonumber(cfg.POINTS_REQUIRED) or 0
    if type(owl) == "table" then
        n = tonumber(owl.Points or owl.Progress or owl.Submitted or owl.N) or 0
        if maxN <= 0 then
            maxN = tonumber(owl.MaxPoints or owl.Max or owl.Goal or owl.Target) or 0
        end
    end
    return n, maxN
end

local function fmtCountdown(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    local m = math.floor(sec / 60)
    local s = sec % 60
    return string.format("%d:%02d", m, s)
end

----------------------------------------------------------------
-- Tools / trait match
----------------------------------------------------------------
local function getBackpack()
    return LP:FindFirstChild("Backpack")
end

local function isFavoriteTool(tool)
    if not tool then return false end
    if tool:GetAttribute("d") == true then return true end
    if tool:GetAttribute("Favorited") == true then return true end
    if tool:GetAttribute("Favorite") == true then return true end
    if tool:GetAttribute("IsFavorite") == true then return true end
    if tool:GetAttribute("Fav") == true then return true end
    if tool:GetAttribute("fav") == true then return true end
    return false
end

local function isFruitTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    if CollectionService:HasTag(tool, "FruitTool") then return true end
    local t = tool:GetAttribute("ITEMTYPE") or tool:GetAttribute("ItemType")
    return t == "Holdable"
end

local function toolPlantName(tool)
    if not tool then return "" end
    local n = tool:GetAttribute("ItemName")
        or tool:GetAttribute("FruitName")
        or tool:GetAttribute("PlantName")
        or tool:GetAttribute("HoldableName")
    if n and tostring(n) ~= "" then return tostring(n) end
    local raw = tostring(tool.Name or "")
    return raw:gsub("%s*%[.-%]$", ""):gsub("%s*%(%d+%)$", "")
end

local function toolHasMutation(tool, mutName)
    if not tool then return false end
    mutName = tostring(mutName or "")
    if mutName == "" then return true end
    if tool:GetAttribute(mutName) == true then return true end
    local var = tool:GetAttribute("Variant") or tool:GetAttribute("Mutation")
    if var and tostring(var):lower() == mutName:lower() then return true end
    return false
end

local function plantTraitsFor(name)
    name = tostring(name or "")
    if name == "" or not PlantTraitsData then return nil end

    local ok, res = pcall(function()
        if type(PlantTraitsData.GetTraits) == "function" then
            return PlantTraitsData:GetTraits(name) or PlantTraitsData.GetTraits(name)
        end
        if type(PlantTraitsData.Get) == "function" then
            return PlantTraitsData:Get(name) or PlantTraitsData.Get(name)
        end
        if type(PlantTraitsData[name]) == "table" then
            return PlantTraitsData[name]
        end
        return nil
    end)
    if ok then return res end
    return nil
end

local function hasTraitName(plantName, trait)
    plantName = tostring(plantName or "")
    trait = tostring(trait or "")
    if plantName == "" or trait == "" then return false end
    if PlantTraitsData and type(PlantTraitsData.HasTrait) == "function" then
        local ok, res = pcall(function()
            return PlantTraitsData.HasTrait(plantName, trait)
        end)
        if ok and res == true then return true end
        ok, res = pcall(function()
            return PlantTraitsData:HasTrait(plantName, trait)
        end)
        if ok and res == true then return true end
    end
    -- lookup set: PlantTraitsData[trait][plantName]
    if PlantTraitsData and type(PlantTraitsData[trait]) == "table" then
        if PlantTraitsData[trait][plantName] == true then return true end
        local want = plantName:lower()
        for k, v in pairs(PlantTraitsData[trait]) do
            if v == true and tostring(k):lower() == want then
                return true
            end
        end
    end
    local traits = plantTraitsFor(plantName)
    if type(traits) == "table" then
        for _, t in ipairs(traits) do
            if tostring(t):lower() == trait:lower() then
                return true
            end
        end
        for k, v in pairs(traits) do
            if type(k) == "string" and k:lower() == trait:lower() and v then
                return true
            end
            if type(v) == "string" and v:lower() == trait:lower() then
                return true
            end
        end
    end
    return false
end

local function toolHasTrait(tool, trait)
    trait = tostring(trait or "")
    if trait == "" then return true end
    if not tool then return false end

    if tool:GetAttribute(trait) == true then return true end
    local tAttr = tool:GetAttribute("Trait") or tool:GetAttribute("Traits")
    if type(tAttr) == "string" and tAttr:lower() == trait:lower() then return true end
    if type(tAttr) == "table" then
        for _, v in pairs(tAttr) do
            if tostring(v):lower() == trait:lower() then return true end
        end
    end

    return hasTraitName(toolPlantName(tool), trait)
end

local function unequipTools()
    local char = LP.Character
    local bag = getBackpack()
    if not char or not bag then return end
    for _, inst in ipairs(char:GetChildren()) do
        if inst:IsA("Tool") then
            inst.Parent = bag
        end
    end
end

local function equipTool(tool)
    local char = LP.Character
    local bag = getBackpack()
    if not char or not tool then return false end
    if tool.Parent ~= bag and tool.Parent ~= char then return false end

    unequipTools()
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum:EquipTool(tool) end)
    else
        tool.Parent = char
    end
    task.wait(EQUIP_WAIT)
    return tool.Parent == char
end

local function findMatchingTool(trait, mutation)
    local function scan(container)
        if not container then return nil end
        for _, tool in ipairs(container:GetChildren()) do
            if isFruitTool(tool) and not isFavoriteTool(tool) then
                if toolHasTrait(tool, trait) and toolHasMutation(tool, mutation) then
                    return tool
                end
            end
        end
        return nil
    end
    return scan(getBackpack()) or scan(LP.Character)
end

local function debounceOk()
    local cfg = getConfig()
    local gap = tonumber(cfg.SUBMIT_DEBOUNCE) or 0.25
    return (os.clock() - LAST_FIRE_AT) >= gap
end

local function markFired()
    LAST_FIRE_AT = os.clock()
end

----------------------------------------------------------------
-- Actions
----------------------------------------------------------------
local function previewCount()
    resolveRemotes()
    if not PreviewRemote then return 0 end
    local ok, n = pcall(function()
        return PreviewRemote:InvokeServer()
    end)
    if not ok then return 0 end
    return tonumber(n) or 0
end

local function fireSubmitHeld()
    resolveRemotes()
    if not SubmitRemote then return false, "no Submit remote" end
    local ok = pcall(function()
        SubmitRemote:FireServer()
    end)
    if ok then markFired() end
    return ok, ok and "submitted held" or "submit fire failed"
end

local function fireSubmitAll()
    resolveRemotes()
    if not SubmitAllRemote then return false, "no SubmitAll remote" end
    local ok = pcall(function()
        SubmitAllRemote:FireServer()
    end)
    if ok then markFired() end
    return ok, ok and "submitted all" or "submitAll fire failed"
end

local function trySubmit()
    if isOnCooldown() then
        return false, ("on cooldown %s"):format(fmtCountdown(cooldownRemain()))
    end
    if not debounceOk() then
        return false, "debounce"
    end

    local trait = getCravingTrait()
    local mut = getCravingMutation()
    if trait == "" then
        return false, "no craving trait yet"
    end

    if AUTO_WISE_OWL_SUBMIT_ALL ~= false then
        local n = previewCount()
        if n > 0 then
            publishStatus(("submit all x%d [%s]"):format(n, trait))
            return fireSubmitAll()
        end
    end

    local tool = findMatchingTool(trait, mut)
    if not tool then
        local need = trait
        if mut ~= "" then need = mut .. " " .. trait end
        return false, ("need %s plant"):format(need)
    end

    publishStatus(("submit held %s [%s]"):format(toolPlantName(tool), trait))
    if not equipTool(tool) then
        return false, "equip failed"
    end
    task.wait(FIRE_WAIT)
    local ok, msg = fireSubmitHeld()
    unequipTools()
    return ok, msg
end

----------------------------------------------------------------
-- Auto Plant (seed matching craving trait — Random on Can_Plant)
----------------------------------------------------------------
local function cleanSeedName(s)
    local n = tostring(s or "")
    n = n:gsub("%s*%[.-%]$", "")
    n = n:gsub("%s*%(%d+%)$", "")
    n = n:gsub("%s+[Ss]eed%s*$", "")
    n = n:gsub("^%s+", ""):gsub("%s+$", "")
    return n
end

local function isSeedTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    local it = tostring(tool:GetAttribute("ItemType") or tool:GetAttribute("ITEM_TYPE") or ""):lower()
    if it == "seed" then return true end
    local nm = tostring(tool.Name or ""):lower()
    return nm:find("seed", 1, true) ~= nil and not nm:find("seed pack", 1, true)
end

local function seedNameOf(tool)
    if not tool then return "" end
    return cleanSeedName(tool:GetAttribute("ItemName") or tool.Name)
end

local function findTraitSeedTool(trait)
    trait = tostring(trait or "")
    if trait == "" then return nil, nil end

    local function scan(container)
        if not container then return nil, nil end
        for _, tool in ipairs(container:GetChildren()) do
            if isSeedTool(tool) then
                local sn = seedNameOf(tool)
                if sn ~= "" and hasTraitName(sn, trait) then
                    return tool, sn
                end
            end
        end
        return nil, nil
    end

    local char = LP.Character
    local t, n = scan(char)
    if t then return t, n end
    return scan(getBackpack())
end

local function resolvePlantRemote()
    if PlantRE and PlantRE.Parent then return true end
    local ok, rem = pcall(function()
        return ReplicatedStorage.GameEvents:FindFirstChild("Plant_RE")
    end)
    if ok and rem then
        PlantRE = rem
        return true
    end
    return false
end

local cachedFarm, cachedFarmAt = nil, 0
local FARM_CACHE_SEC = 5
local RANDOM_PART_MARGIN = 0.92
local RANDOM_MAX_TRY = 40
local RANDOM_MIN_DIST = 1.0

local function getOwnFarm()
    local now = os.clock()
    if cachedFarm and cachedFarm.Parent and (now - cachedFarmAt) <= FARM_CACHE_SEC then
        return cachedFarm
    end
    cachedFarm = nil
    cachedFarmAt = now

    if type(GetFarmAsync) == "function" then
        local ok, farm = pcall(GetFarmAsync, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end

    local farms = workspace:FindFirstChild("Farm") or workspace:FindFirstChild("Farms")
    if farms then
        for _, farm in ipairs(farms:GetChildren()) do
            local owner = farm:GetAttribute("Owner")
                or farm:GetAttribute("OwnerName")
                or farm:GetAttribute("Player")
            if owner == LP.Name or tostring(owner) == tostring(LP.UserId) then
                cachedFarm = farm
                return farm
            end
            local important = farm:FindFirstChild("Important")
            local data = important and important:FindFirstChild("Data")
            local ownerVal = data and data:FindFirstChild("Owner")
            if ownerVal and (ownerVal.Value == LP.Name or tostring(ownerVal.Value) == tostring(LP.UserId)) then
                cachedFarm = farm
                return farm
            end
        end
    end
    return nil
end

local function getPlantsFolder(farm)
    farm = farm or getOwnFarm()
    if not farm then return nil end
    local important = farm:FindFirstChild("Important")
    local plants = important and important:FindFirstChild("Plants_Physical")
    if plants then return plants end
    return farm:FindFirstChild("Plants_Physical", true)
end

local function getCanPlantParts(farm)
    farm = farm or getOwnFarm()
    if not farm then return {} end
    local out = {}
    local important = farm:FindFirstChild("Important")
    local root = important or farm
    for _, desc in ipairs(root:GetDescendants()) do
        if desc:IsA("BasePart") and desc.Name == "Can_Plant" then
            out[#out + 1] = desc
        end
    end
    return out
end

local function plantGroundXZ(plant)
    if not plant then return nil end
    if plant:IsA("BasePart") then
        return plant.Position.X, plant.Position.Z
    end
    if plant:IsA("Model") then
        local ok, pivot = pcall(function() return plant:GetPivot().Position end)
        if ok and pivot then return pivot.X, pivot.Z end
        if plant.PrimaryPart then
            return plant.PrimaryPart.Position.X, plant.PrimaryPart.Position.Z
        end
    end
    local part = plant:FindFirstChildWhichIsA("BasePart", true)
    if part then return part.Position.X, part.Position.Z end
    return nil
end

local function isBlockedSpot(pos, plantsFolder, minDist)
    if not pos then return true end
    minDist = tonumber(minDist) or RANDOM_MIN_DIST
    if not plantsFolder then return false end
    local min2 = minDist * minDist
    local px, pz = pos.X, pos.Z
    for _, plant in ipairs(plantsFolder:GetChildren()) do
        local gx, gz = plantGroundXZ(plant)
        if gx and gz then
            local dx = gx - px
            local dz = gz - pz
            if (dx * dx + dz * dz) < min2 then
                return true
            end
        end
    end
    return false
end

local function randomPointOnPart(part)
    if not part then return nil end
    local size = part.Size
    local margin = RANDOM_PART_MARGIN
    local rx = (math.random() - 0.5) * size.X * margin
    local rz = (math.random() - 0.5) * size.Z * margin
    return (part.CFrame * CFrame.new(rx, size.Y * 0.5 + 0.05, rz)).Position
end

local function pickRandomPlantPos(farm, plantsFolder)
    local canPlants = getCanPlantParts(farm)
    if #canPlants == 0 then
        return nil, "no Can_Plant"
    end
    for _ = 1, RANDOM_MAX_TRY do
        local part = canPlants[math.random(1, #canPlants)]
        local pos = randomPointOnPart(part)
        if pos and not isBlockedSpot(pos, plantsFolder, RANDOM_MIN_DIST) then
            return pos, nil
        end
    end
    return nil, "no empty slot"
end

local function cleanGardenPlantName(plant)
    if not plant then return "" end
    local n = plant:GetAttribute("ItemName")
        or plant:GetAttribute("PlantName")
        or plant:GetAttribute("SeedName")
        or plant.Name
    n = tostring(n or "")
    n = n:gsub("%s*%[.-%]$", ""):gsub("%s*%(%d+%)$", "")
    return n:gsub("^%s+", ""):gsub("%s+$", "")
end

-- Count plants in own garden that match craving trait
local function countGardenTraitPlants(trait)
    trait = tostring(trait or "")
    if trait == "" then return 0 end
    local folder = getPlantsFolder()
    if not folder then return 0 end
    local n = 0
    for _, plant in ipairs(folder:GetChildren()) do
        local pname = cleanGardenPlantName(plant)
        if pname ~= "" and hasTraitName(pname, trait) then
            n += 1
        end
    end
    return n
end

local function ensurePlantTraitCounter(trait)
    trait = tostring(trait or "")
    if trait ~= PLANT_TRAIT_KEY then
        PLANT_TRAIT_KEY = trait
        PLANT_DONE = 0
        G.__AUTO_WISE_OWL_PLANT_DONE = 0
        _G.__AUTO_WISE_OWL_PLANT_DONE = 0
    end
end

local function tryPlantOne()
    local trait = getCravingTrait()
    if trait == "" then
        return false, "no craving trait yet"
    end
    ensurePlantTraitCounter(trait)

    local total = AUTO_WISE_OWL_PLANT_TOTAL
    local gardenN = countGardenTraitPlants(trait)

    -- Sudah cukup plant trait di garden → jangan tanam lagi
    if total > 0 and gardenN >= total then
        return false, ("garden full %d/%d [%s]"):format(gardenN, total, trait)
    end

    local tool, seedName = findTraitSeedTool(trait)
    if not tool or not seedName then
        return false, ("no %s seed"):format(trait)
    end

    local farm = getOwnFarm()
    if not farm then
        return false, "no own farm"
    end
    local plantsFolder = getPlantsFolder(farm)
    local pos, posErr = pickRandomPlantPos(farm, plantsFolder)
    if not pos then
        return false, posErr or "no empty slot"
    end

    if not equipTool(tool) then
        return false, "equip seed failed"
    end

    if not resolvePlantRemote() then
        return false, "no Plant_RE"
    end

    local ok = pcall(function()
        PlantRE:FireServer(pos, seedName)
    end)
    if not ok then
        return false, "plant fire failed"
    end

    PLANT_DONE += 1
    G.__AUTO_WISE_OWL_PLANT_DONE = PLANT_DONE
    _G.__AUTO_WISE_OWL_PLANT_DONE = PLANT_DONE

    task.wait(0.15)
    local gardenAfter = countGardenTraitPlants(trait)
    LAST_PLANT_STATUS = ("planted %s · garden %d/%s · session %d [%s]"):format(
        seedName,
        gardenAfter,
        total > 0 and tostring(total) or "∞",
        PLANT_DONE,
        trait
    )
    return true, LAST_PLANT_STATUS
end

----------------------------------------------------------------
-- Status / public API
----------------------------------------------------------------
function M.GetStatusText()
    syncGlobalsFromState()
    resolveRemotes()

    local trait = getCravingTrait()
    local mut = getCravingMutation()
    local n, maxN = getProgress()
    local cd = cooldownRemain()
    local rotate = cravingRemain()
    local preview = 0
    pcall(function() preview = previewCount() end)

    local submitOn = AUTO_WISE_OWL_SUBMIT_ENABLED == true and "ON" or "OFF"
    local allOn = AUTO_WISE_OWL_SUBMIT_ALL ~= false and "ON" or "OFF"
    local plantOn = AUTO_WISE_OWL_PLANT_ENABLED == true and "ON" or "OFF"
    local plantTotal = AUTO_WISE_OWL_PLANT_TOTAL

    ensurePlantTraitCounter(trait)
    local gardenN = 0
    if trait ~= "" then
        gardenN = countGardenTraitPlants(trait)
    end

    local craving = trait ~= "" and trait or "?"
    if mut ~= "" then
        craving = mut .. " " .. craving
    end

    local lines = {}
    if cd > 0 then
        lines[#lines + 1] = ("Cooldown: %s"):format(fmtCountdown(cd))
    else
        lines[#lines + 1] = ("Craves: %s · match x%d"):format(craving, preview)
    end
    if maxN > 0 then
        lines[#lines + 1] = ("Progress: %d / %d"):format(n, maxN)
    elseif n > 0 then
        lines[#lines + 1] = ("Progress: %d"):format(n)
    else
        lines[#lines + 1] = "Progress: —"
    end
    lines[#lines + 1] = ("Craving rotate: %s"):format(fmtCountdown(rotate))
    lines[#lines + 1] = ("Plant %s · garden %d / %s · session %d"):format(
        plantOn,
        gardenN,
        plantTotal > 0 and tostring(plantTotal) or "∞",
        PLANT_DONE
    )
    lines[#lines + 1] = ("Submit %s · Prefer All %s"):format(submitOn, allOn)
    local last = LAST_STATUS
    if AUTO_WISE_OWL_PLANT_ENABLED == true and LAST_PLANT_STATUS ~= "" and LAST_PLANT_STATUS ~= "idle" then
        last = LAST_PLANT_STATUS
    end
    lines[#lines + 1] = (last ~= "" and last or "idle")

    return table.concat(lines, "\n")
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if AUTO_WISE_OWL_SUBMIT_ENABLED ~= true then
            break
        end

        resolveRemotes()
        local ok, msg = trySubmit()
        if msg then publishStatus(msg) end

        task.wait(clampDelay(AUTO_WISE_OWL_DELAY_SEC))
    end

    unequipTools()
    RUNNING = false
    if LAST_STATUS == "running" then
        publishStatus("stopped")
    end
end

local function plantWorker(token)
    LAST_PLANT_STATUS = "plant running"
    while PLANT_RUNNING and token == PLANT_STOP_TOKEN do
        syncGlobalsFromState()
        if AUTO_WISE_OWL_PLANT_ENABLED ~= true then
            break
        end

        local ok, msg = tryPlantOne()
        if msg then
            LAST_PLANT_STATUS = tostring(msg)
            -- soft publish so status line updates even if submit idle
            if not RUNNING then
                publishStatus(msg)
            end
        end

        -- stop/wait when garden already has enough / no slot
        if not ok and type(msg) == "string" and (
            msg:find("^garden full ")
            or msg:find("^plant done ")
            or msg == "no empty slot"
            or msg == "no Can_Plant"
        ) then
            task.wait(1)
        else
            task.wait(clampDelay(AUTO_WISE_OWL_DELAY_SEC))
        end
    end

    PLANT_RUNNING = false
    if LAST_PLANT_STATUS == "plant running" then
        LAST_PLANT_STATUS = "plant stopped"
    end
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
    G.AUTO_WISE_OWL_SUBMIT_ENABLED = (AUTO_WISE_OWL_SUBMIT_ENABLED == true)
    G.AUTO_WISE_OWL_SUBMIT_ALL = (AUTO_WISE_OWL_SUBMIT_ALL ~= false)
    G.AUTO_WISE_OWL_DELAY_SEC = clampDelay(AUTO_WISE_OWL_DELAY_SEC)
    G.AUTO_WISE_OWL_PLANT_ENABLED = (AUTO_WISE_OWL_PLANT_ENABLED == true)
    G.AUTO_WISE_OWL_PLANT_TOTAL = math.max(0, math.floor(tonumber(AUTO_WISE_OWL_PLANT_TOTAL) or 10))
    _G.AUTO_WISE_OWL_SUBMIT_ENABLED = G.AUTO_WISE_OWL_SUBMIT_ENABLED
    _G.AUTO_WISE_OWL_SUBMIT_ALL = G.AUTO_WISE_OWL_SUBMIT_ALL
    _G.AUTO_WISE_OWL_DELAY_SEC = G.AUTO_WISE_OWL_DELAY_SEC
    _G.AUTO_WISE_OWL_PLANT_ENABLED = G.AUTO_WISE_OWL_PLANT_ENABLED
    _G.AUTO_WISE_OWL_PLANT_TOTAL = G.AUTO_WISE_OWL_PLANT_TOTAL
end

function M.Start()
    M.SyncFromGlobals()
    if RUNNING then return end
    if AUTO_WISE_OWL_SUBMIT_ENABLED ~= true then return end
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    publishStatus("stopped")
end

function M.StartPlant()
    M.SyncFromGlobals()
    if PLANT_RUNNING then return end
    if AUTO_WISE_OWL_PLANT_ENABLED ~= true then return end
    local trait = getCravingTrait()
    ensurePlantTraitCounter(trait)
    PLANT_RUNNING = true
    PLANT_STOP_TOKEN += 1
    local token = PLANT_STOP_TOKEN
    task.spawn(plantWorker, token)
end

function M.StopPlant()
    PLANT_RUNNING = false
    PLANT_STOP_TOKEN += 1
    LAST_PLANT_STATUS = "plant stopped"
end

function M.SetEnabled(on)
    AUTO_WISE_OWL_SUBMIT_ENABLED = (on == true)
    G.AUTO_WISE_OWL_SUBMIT_ENABLED = AUTO_WISE_OWL_SUBMIT_ENABLED
    _G.AUTO_WISE_OWL_SUBMIT_ENABLED = AUTO_WISE_OWL_SUBMIT_ENABLED
    if AUTO_WISE_OWL_SUBMIT_ENABLED then
        M.Start()
    else
        M.Stop()
    end
end

function M.SetSubmitEnabled(on)
    M.SetEnabled(on)
end

function M.SetSubmitAll(on)
    AUTO_WISE_OWL_SUBMIT_ALL = (on ~= false)
    G.AUTO_WISE_OWL_SUBMIT_ALL = AUTO_WISE_OWL_SUBMIT_ALL
    _G.AUTO_WISE_OWL_SUBMIT_ALL = AUTO_WISE_OWL_SUBMIT_ALL
end

function M.SetDelay(sec)
    AUTO_WISE_OWL_DELAY_SEC = clampDelay(sec)
    G.AUTO_WISE_OWL_DELAY_SEC = AUTO_WISE_OWL_DELAY_SEC
    _G.AUTO_WISE_OWL_DELAY_SEC = AUTO_WISE_OWL_DELAY_SEC
end

function M.SetPlantEnabled(on)
    AUTO_WISE_OWL_PLANT_ENABLED = (on == true)
    G.AUTO_WISE_OWL_PLANT_ENABLED = AUTO_WISE_OWL_PLANT_ENABLED
    _G.AUTO_WISE_OWL_PLANT_ENABLED = AUTO_WISE_OWL_PLANT_ENABLED
    if AUTO_WISE_OWL_PLANT_ENABLED then
        M.StartPlant()
    else
        M.StopPlant()
    end
end

function M.SetPlantTotal(n)
    AUTO_WISE_OWL_PLANT_TOTAL = math.max(0, math.floor(tonumber(n) or 10))
    G.AUTO_WISE_OWL_PLANT_TOTAL = AUTO_WISE_OWL_PLANT_TOTAL
    _G.AUTO_WISE_OWL_PLANT_TOTAL = AUTO_WISE_OWL_PLANT_TOTAL
end

function M.SyncFromState()
    M.SyncFromGlobals()
    if AUTO_WISE_OWL_SUBMIT_ENABLED == true then
        M.Start()
    else
        M.Stop()
    end
    if AUTO_WISE_OWL_PLANT_ENABLED == true then
        M.StartPlant()
    else
        M.StopPlant()
    end
end

G.AutoWiseOwl = M
_G.AutoWiseOwl = M

return M

        end,
        required = false,
    },
    {
        key = "AutoMoonCrafting",
        name = "Auto Moon Crafting",
        factory = function()
            -- auto_moon_crafting.lua
-- Moon Crafting — Auto SetRecipe / Submit / Craft / Claim
--
-- Config : ReplicatedStorage.Data.MoonCrafting.MoonCraftingConfig
-- Remotes: GameEvents.MoonCrafting.Remote
--   SetRecipe / InputItem / Craft / Claim / Cancel
-- Skip Robux (AuthoriseSkip) tidak di-auto. Favorite items selalu di-skip.

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local MIN_DELAY = 0.3
local MAX_DELAY = 300
local DEFAULT_DELAY = 1
local SUBMIT_GAP = 0.12

local RUNNING = false
local STOP_TOKEN = 0
local LAST_STATUS = "idle"

local DataService = nil
local InventoryService = nil
local InventoryServiceEnums = nil
local MoonCraftingClient = nil
local MoonCraftingConfigAccessor = nil
local MoonCraftingItemIdentity = nil
local MoonCraftingStationHandler = nil
local StaticConfig = nil
local Remote = nil

pcall(function()
    ReplicatedStorage:WaitForChild("Modules", 8)
end)
pcall(function()
    DataService = require(ReplicatedStorage.Modules.DataService)
end)
pcall(function()
    InventoryService = require(ReplicatedStorage.Modules.InventoryService)
end)
pcall(function()
    InventoryServiceEnums = require(ReplicatedStorage.Data.EnumRegistry.InventoryServiceEnums)
end)
pcall(function()
    MoonCraftingClient = require(ReplicatedStorage.Modules.MoonCrafting.MoonCraftingClient)
end)
pcall(function()
    MoonCraftingConfigAccessor = require(ReplicatedStorage.Modules.MoonCrafting.MoonCraftingConfigAccessor)
end)
pcall(function()
    MoonCraftingItemIdentity = require(ReplicatedStorage.Modules.MoonCrafting.MoonCraftingItemIdentity)
end)
pcall(function()
    MoonCraftingStationHandler = require(ReplicatedStorage.Modules.MoonCrafting.MoonCraftingStationHandler)
end)
pcall(function()
    StaticConfig = require(ReplicatedStorage.Data.MoonCrafting.MoonCraftingConfig)
end)

----------------------------------------------------------------
-- Globals / state
----------------------------------------------------------------
AUTO_MOON_CRAFTING_ENABLED = (AUTO_MOON_CRAFTING_ENABLED == true)
AUTO_MOON_CRAFTING_DELAY_SEC = tonumber(AUTO_MOON_CRAFTING_DELAY_SEC) or DEFAULT_DELAY
AUTO_MOON_CRAFTING_RECIPES = type(AUTO_MOON_CRAFTING_RECIPES) == "table" and AUTO_MOON_CRAFTING_RECIPES or {}

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_MOON_CRAFTING_STATUS = LAST_STATUS
    _G.__AUTO_MOON_CRAFTING_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_moon_crafting
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function mapHasAny(map)
    if type(map) ~= "table" then return false end
    for _, v in pairs(map) do
        if v == true then return true end
    end
    return false
end

local function toBoolMap(src)
    local out = {}
    if type(src) ~= "table" then return out end
    if #src > 0 then
        for _, k in ipairs(src) do
            if k ~= nil and tostring(k) ~= "" then
                out[tostring(k)] = true
            end
        end
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function syncGlobalsFromState()
    local st = getState()

    AUTO_MOON_CRAFTING_ENABLED = (
        G.AUTO_MOON_CRAFTING_ENABLED == true
        or _G.AUTO_MOON_CRAFTING_ENABLED == true
        or AUTO_MOON_CRAFTING_ENABLED == true
        or st.enabled == true
    )

    local delaySrc = G.AUTO_MOON_CRAFTING_DELAY_SEC
    if delaySrc == nil then delaySrc = _G.AUTO_MOON_CRAFTING_DELAY_SEC end
    if delaySrc == nil then delaySrc = AUTO_MOON_CRAFTING_DELAY_SEC end
    if delaySrc == nil then delaySrc = st.delaySec end
    AUTO_MOON_CRAFTING_DELAY_SEC = clampDelay(delaySrc)

    local recipes = G.AUTO_MOON_CRAFTING_RECIPES or _G.AUTO_MOON_CRAFTING_RECIPES
        or AUTO_MOON_CRAFTING_RECIPES or st.recipes
    AUTO_MOON_CRAFTING_RECIPES = toBoolMap(recipes)

    G.AUTO_MOON_CRAFTING_ENABLED = AUTO_MOON_CRAFTING_ENABLED
    G.AUTO_MOON_CRAFTING_DELAY_SEC = AUTO_MOON_CRAFTING_DELAY_SEC
    G.AUTO_MOON_CRAFTING_RECIPES = AUTO_MOON_CRAFTING_RECIPES
    _G.AUTO_MOON_CRAFTING_ENABLED = AUTO_MOON_CRAFTING_ENABLED
    _G.AUTO_MOON_CRAFTING_DELAY_SEC = AUTO_MOON_CRAFTING_DELAY_SEC
    _G.AUTO_MOON_CRAFTING_RECIPES = AUTO_MOON_CRAFTING_RECIPES
end

local function anyEnabled()
    return AUTO_MOON_CRAFTING_ENABLED == true
end

----------------------------------------------------------------
-- Remotes / game helpers
----------------------------------------------------------------
local function resolveRemote()
    if Remote and Remote.Parent then return Remote end
    local ok, rem = pcall(function()
        return ReplicatedStorage:WaitForChild("GameEvents", 5)
            :WaitForChild("MoonCrafting", 5)
            :WaitForChild("Remote", 5)
    end)
    if ok then Remote = rem end
    return Remote
end

local function fireAction(action, ...)
    local rem = resolveRemote()
    if not rem then return false, "no remote" end
    local args = table.pack(...)
    local ok, err = pcall(function()
        rem:FireServer(action, table.unpack(args, 1, args.n))
    end)
    if not ok then return false, tostring(err) end
    return true
end

local function clientCall(method, ...)
    if type(MoonCraftingClient) == "table" and type(MoonCraftingClient[method]) == "function" then
        local ok, a, b = pcall(MoonCraftingClient[method], MoonCraftingClient, ...)
        if ok then return true, a, b end
    end
    return false
end

local function getProfile()
    if DataService and type(DataService.GetData) == "function" then
        local ok, data = pcall(function() return DataService:GetData() end)
        if ok and type(data) == "table" then return data end
    end
    return nil
end

local function getMoonData()
    local ok, data = clientCall("GetMoonData")
    if ok and type(data) == "table" then return data end
    local profile = getProfile()
    return profile and profile.MoonCraftingData or nil
end

local function getSummonsContributed()
    local ok, n = clientCall("GetSummonsContributed")
    if ok and tonumber(n) then return tonumber(n) or 0 end
    local profile = getProfile()
    local hm = profile and profile.HarvestMoonData
    return tonumber(hm and hm.SummonsContributed) or 0
end

local function getMoonCoins(profile)
    profile = profile or getProfile()
    if type(profile) ~= "table" then return 0 end
    local sc = profile.SpecialCurrency
    if type(sc) == "table" then
        local n = tonumber(sc.MoonCoins) or tonumber(sc.MoonCoin)
        if n then return n end
    end
    local n = tonumber(profile.MoonCoins) or tonumber(profile.MoonCoin)
    if n then return n end
    local cd = profile.CurrencyData or profile.Currencies
    if type(cd) == "table" then
        n = tonumber(cd.MoonCoins) or tonumber(cd.MoonCoin) or tonumber(cd["Moon Coins"])
        if n then return n end
    end
    return 0
end

local function fmtTime(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    local m = math.floor(sec / 60)
    local s = sec % 60
    if m >= 60 then
        local h = math.floor(m / 60)
        m = m % 60
        return string.format("%dh%02dm", h, m)
    end
    return string.format("%dm%02ds", m, s)
end

----------------------------------------------------------------
-- Recipes
----------------------------------------------------------------
local function getAllRecipes()
    if MoonCraftingConfigAccessor and type(MoonCraftingConfigAccessor.GetRecipes) == "function" then
        local ok, list = pcall(function()
            return MoonCraftingConfigAccessor:GetRecipes()
        end)
        if ok and type(list) == "table" and #list > 0 then
            return list
        end
    end
    local cfg = StaticConfig
    if type(cfg) ~= "table" or type(cfg.Recipes) ~= "table" then
        return {}
    end
    local list = {}
    for _, r in ipairs(cfg.Recipes) do
        if type(r) == "table" and r.Id then
            list[#list + 1] = r
        end
    end
    table.sort(list, function(a, b)
        return (tonumber(a.LayoutOrder) or 0) < (tonumber(b.LayoutOrder) or 0)
    end)
    return list
end

local function getRecipeById(id)
    id = tostring(id or "")
    if id == "" then return nil end
    if MoonCraftingConfigAccessor and type(MoonCraftingConfigAccessor.GetRecipe) == "function" then
        local ok, rec = pcall(function()
            return MoonCraftingConfigAccessor:GetRecipe(id)
        end)
        if ok and type(rec) == "table" then return rec end
    end
    for _, r in ipairs(getAllRecipes()) do
        if tostring(r.Id) == id then return r end
    end
    return nil
end

local function isRecipeUnlocked(recipe)
    if type(recipe) ~= "table" then return false end
    local need = tonumber(recipe.RequiredSummonContributions) or 0
    if need <= 0 then return true end
    if MoonCraftingConfigAccessor and type(MoonCraftingConfigAccessor.IsRecipeUnlocked) == "function" then
        local ok, unlocked = pcall(function()
            return MoonCraftingConfigAccessor:IsRecipeUnlocked(recipe, getSummonsContributed())
        end)
        if ok then return unlocked == true end
    end
    return getSummonsContributed() >= need
end

local function recipeCost(recipe)
    local cost = recipe and recipe.Cost
    if type(cost) ~= "table" then return 0, "MoonCoins" end
    return tonumber(cost.Amount) or 0, tostring(cost.CurrencyType or "MoonCoins")
end

local function getSelectedRecipe()
    local ok, recipe, rid = clientCall("GetSelectedRecipe")
    if ok and type(recipe) == "table" then
        return recipe, rid or recipe.Id
    end
    local md = getMoonData()
    local id = md and md.RecipeId
    if id then
        return getRecipeById(id), id
    end
    return nil, nil
end

local function getSubmittedSlots()
    local ok, slots = clientCall("GetSubmittedSlots")
    if ok and type(slots) == "table" then return slots end
    local out = {}
    local md = getMoonData()
    if type(md) == "table" and type(md.InputItems) == "table" then
        for i in pairs(md.InputItems) do
            out[tostring(i)] = true
        end
    end
    return out
end

local function getCraftingSlot(index)
    index = tonumber(index) or 1
    local ok, slot = clientCall("GetCraftingSlot", index)
    if ok then return slot end
    local md = getMoonData()
    return md and md.CraftingItems and md.CraftingItems[index] or nil
end

local function isReadyToCraft(recipe)
    recipe = recipe or select(1, getSelectedRecipe())
    if type(recipe) ~= "table" or type(recipe.Inputs) ~= "table" then
        return false
    end
    local submitted = getSubmittedSlots()
    local n = 0
    for _ in pairs(submitted) do n += 1 end
    return n >= #recipe.Inputs
end

local function craftRemainSec(slot)
    if type(slot) ~= "table" then return 0 end
    if slot.IsDone == true then return 0 end
    local endAt = tonumber(slot.EndTime) or tonumber(slot.EndsAt) or tonumber(slot.FinishTime)
    if endAt then
        local now = workspace:GetServerTimeNow()
        if typeof(now) ~= "number" then
            now = os.time()
        end
        -- EndTime sometimes absolute unix, sometimes relative leftover
        if endAt > 1e9 then
            return math.max(0, endAt - now)
        end
        return math.max(0, endAt)
    end
    local remain = tonumber(slot.TimeRemaining) or tonumber(slot.Remaining)
    return math.max(0, remain or 0)
end

----------------------------------------------------------------
-- Inventory submit
----------------------------------------------------------------
local function favKey()
    return (InventoryServiceEnums and InventoryServiceEnums.Favorite) or "d"
end

local function isFavItemData(itemData)
    if type(itemData) ~= "table" then return false end
    if itemData.IsFavorite == true then return true end
    local fk = favKey()
    if itemData[fk] == true then return true end
    if itemData.Favorite == true then return true end
    return false
end

local function inventoryNameFor(itemType, itemData)
    if MoonCraftingItemIdentity and type(MoonCraftingItemIdentity.FromInventoryData) == "function" then
        local ok, name = pcall(MoonCraftingItemIdentity.FromInventoryData, itemType, itemData)
        if ok and name ~= nil then return tostring(name) end
    end
    if type(itemData) ~= "table" then return nil end
    return tostring(
        itemData.ItemName
            or itemData.EggName
            or itemData.CrateType
            or itemData.SprayType
            or itemData.Type
            or itemData.ShardType
            or ""
    )
end

local function findInventoryMatches(itemType, itemName, acceptAll)
    local matches = {}
    if not InventoryService or type(InventoryService.Find) ~= "function" then
        return matches
    end
    local ok, found = pcall(function()
        return InventoryService:Find(itemType, function(itemData)
            if acceptAll == true then return true end
            return inventoryNameFor(itemType, itemData) == itemName
        end)
    end)
    if not ok or type(found) ~= "table" then
        return matches
    end
    for uuid, entry in pairs(found) do
        if type(entry) == "table" then
            local data = entry.ItemData or entry
            if not isFavItemData(data) then
                matches[#matches + 1] = {
                    UUID = tostring(uuid),
                    ItemType = entry.ItemType or itemType,
                    ItemData = data,
                    Quantity = tonumber(data.Quantity) or tonumber(data.Uses) or 1,
                }
            end
        end
    end
    return matches
end

local function countAvailable(itemType, itemName, acceptAll)
    local total = 0
    for _, m in ipairs(findInventoryMatches(itemType, itemName, acceptAll)) do
        total += math.max(1, tonumber(m.Quantity) or 1)
    end
    return total
end

local function recipeHasMaterials(recipe)
    if type(recipe) ~= "table" or type(recipe.Inputs) ~= "table" then
        return false
    end
    local need = {}
    for _, inp in ipairs(recipe.Inputs) do
        local itemType = tostring(inp.ItemType or "")
        local itemName = tostring(inp.ItemData and inp.ItemData.ItemName or "")
        local acceptAll = inp.ItemData and (inp.ItemData.AcceptAllTypes == true or inp.ItemData.AcceptAllTypes == true)
        local key = itemType .. "\0" .. itemName .. "\0" .. tostring(acceptAll)
        local entry = need[key]
        if not entry then
            entry = {
                ItemType = itemType,
                ItemName = itemName,
                AcceptAll = acceptAll,
                Qty = 0,
            }
            need[key] = entry
        end
        entry.Qty += tonumber(inp.ItemData and inp.ItemData.Quantity) or 1
    end
    for _, entry in pairs(need) do
        if countAvailable(entry.ItemType, entry.ItemName, entry.AcceptAll) < entry.Qty then
            return false
        end
    end
    return true
end

local function setRecipe(recipeId)
    recipeId = tostring(recipeId or "")
    if recipeId == "" then return false, "no recipe" end
    local ok = select(1, clientCall("SetRecipe", recipeId))
    if ok then return true end
    return fireAction("SetRecipe", recipeId)
end

local function inputItem(slotIndex, itemType, uuid)
    local payload = {
        ItemType = itemType,
        ItemData = { UUID = uuid },
    }
    local ok = select(1, clientCall("InputItem", slotIndex, payload))
    if ok then return true end
    return fireAction("InputItem", slotIndex, payload)
end

local function startCraft()
    local ok = select(1, clientCall("Craft"))
    if ok then return true end
    return fireAction("Craft")
end

local function claimCraft(slot)
    slot = tonumber(slot) or 1
    local ok = select(1, clientCall("Claim", slot))
    if ok then return true end
    return fireAction("Claim", slot)
end

local function countSubmitted(recipe)
    local submitted = getSubmittedSlots()
    local need = (type(recipe) == "table" and type(recipe.Inputs) == "table") and #recipe.Inputs or 0
    local n = 0
    for i = 1, need do
        if submitted[tostring(i)] then
            n += 1
        end
    end
    return n, need, submitted
end

local function missingInputNames(recipe, submitted)
    submitted = submitted or getSubmittedSlots()
    local names = {}
    for i, inp in ipairs((recipe and recipe.Inputs) or {}) do
        if not submitted[tostring(i)] then
            names[#names + 1] = tostring(inp.ItemData and inp.ItemData.ItemName or inp.ItemType or "?")
        end
    end
    return names
end

local function callMoonSubmitAll()
    local handler = MoonCraftingStationHandler
    if type(handler) ~= "table" then
        return false
    end
    local fn = handler.SubmitAllRequiredItems or handler.SubmitAllRequiredItems
    if type(fn) ~= "function" then
        return false
    end
    return pcall(fn, handler)
end

local function submitMissingInputs(recipe)
    if type(recipe) ~= "table" or type(recipe.Inputs) ~= "table" then
        return false, "no recipe"
    end

    local before = select(1, countSubmitted(recipe))
    if before >= #recipe.Inputs then
        return true, "full"
    end

    -- Game [F] Submit All. Don't treat pcall success as "all slots filled".
    callMoonSubmitAll()
    task.wait(0.15 + 0.12 * math.max(1, #recipe.Inputs))

    local after, need, submitted = countSubmitted(recipe)
    if after >= need then
        return true, "submitted"
    end

    local usedQty = {}
    for i, inp in ipairs(recipe.Inputs) do
        if not submitted[tostring(i)] then
            local itemType = inp.ItemType
            local itemName = inp.ItemData and inp.ItemData.ItemName
            local acceptAll = inp.ItemData and (inp.ItemData.AcceptAllTypes == true or inp.ItemData.AcceptAllTypes == true)
            local needQty = tonumber(inp.ItemData and inp.ItemData.Quantity) or 1
            local matches = findInventoryMatches(itemType, itemName, acceptAll)
            for _, m in ipairs(matches) do
                local used = usedQty[m.UUID] or 0
                if (m.Quantity - used) >= needQty then
                    usedQty[m.UUID] = used + needQty
                    if select(1, inputItem(i, m.ItemType, m.UUID)) then
                        task.wait(SUBMIT_GAP)
                    end
                    break
                end
            end
        end
    end

    task.wait(0.2)
    after, need, submitted = countSubmitted(recipe)
    if after >= need then
        return true, "submitted"
    end

    local miss = missingInputNames(recipe, submitted)
    local msg = #miss > 0 and ("need " .. table.concat(miss, ", ")) or "need items"
    return false, msg
end

local function pickNextRecipe()
    if not mapHasAny(AUTO_MOON_CRAFTING_RECIPES) then
        return nil, "select recipe"
    end
    local coins = getMoonCoins()
    local locked = 0
    local noCoins = 0
    local noMats = 0

    for _, recipe in ipairs(getAllRecipes()) do
        local id = tostring(recipe.Id or "")
        if AUTO_MOON_CRAFTING_RECIPES[id] == true then
            if not isRecipeUnlocked(recipe) then
                locked += 1
            else
                local cost = select(1, recipeCost(recipe))
                if coins < cost then
                    noCoins += 1
                elseif not recipeHasMaterials(recipe) then
                    noMats += 1
                else
                    return recipe, id
                end
            end
        end
    end

    if locked > 0 and noCoins == 0 and noMats == 0 then
        return nil, "locked"
    end
    if noCoins > 0 and noMats == 0 then
        return nil, "no coins"
    end
    if noMats > 0 then
        return nil, "need items"
    end
    return nil, "no recipe"
end

----------------------------------------------------------------
-- Actions / worker
----------------------------------------------------------------
local function tryClaim()
    local slot = getCraftingSlot(1)
    if not slot then return false, nil end
    if slot.IsDone ~= true then
        return false, "crafting " .. fmtTime(craftRemainSec(slot))
    end
    publishStatus("claiming")
    local ok, err = claimCraft(1)
    if not ok then return false, err or "claim fail" end
    task.wait(0.35)
    return true, "claimed"
end

local function tryCraftOrSubmit()
    local recipe, rid = getSelectedRecipe()
    local slot = getCraftingSlot(1)
    if slot then
        if slot.IsDone == true then
            return tryClaim()
        end
        return false, "crafting " .. fmtTime(craftRemainSec(slot))
    end

    if not recipe then
        local nextRecipe, reason = pickNextRecipe()
        if not nextRecipe then
            return false, reason
        end
        publishStatus("select " .. tostring(nextRecipe.DisplayName or nextRecipe.Id))
        local ok, err = setRecipe(nextRecipe.Id)
        if not ok then return false, err or "set fail" end
        task.wait(0.35)
        recipe, rid = getSelectedRecipe()
        if not recipe then
            return false, "set pending"
        end
    else
        -- If current selected not in user list, cancel and re-pick
        local id = tostring(rid or recipe.Id or "")
        if mapHasAny(AUTO_MOON_CRAFTING_RECIPES) and AUTO_MOON_CRAFTING_RECIPES[id] ~= true then
            publishStatus("cancel")
            clientCall("Cancel")
            fireAction("Cancel")
            task.wait(0.3)
            return true, "cancelled"
        end
    end

    if isReadyToCraft(recipe) then
        local cost = select(1, recipeCost(recipe))
        if getMoonCoins() < cost then
            return false, "no coins"
        end
        publishStatus("craft " .. tostring(recipe.DisplayName or recipe.Id))
        local ok, err = startCraft()
        if not ok then return false, err or "craft fail" end
        task.wait(0.4)
        return true, "crafting"
    end

    publishStatus("submit")
    local did, msg = submitMissingInputs(recipe)
    if did then
        task.wait(0.2)
        if isReadyToCraft(recipe) then
            local cost = select(1, recipeCost(recipe))
            if getMoonCoins() < cost then
                return true, "no coins"
            end
            publishStatus("craft " .. tostring(recipe.DisplayName or recipe.Id))
            local ok = select(1, startCraft())
            if ok then
                task.wait(0.4)
                return true, "crafting"
            end
        end
        return true, msg or "submitted"
    end
    return false, msg or "need items"
end

function M.GetStatusText()
    syncGlobalsFromState()
    local coins = getMoonCoins()
    local recipe = select(1, getSelectedRecipe())
    local slot = getCraftingSlot(1)
    local flags = AUTO_MOON_CRAFTING_ENABLED == true and "ON" or "OFF"

    local phase = "Idle"
    if slot then
        if slot.IsDone == true then
            phase = "Ready"
        else
            phase = "Crafting " .. fmtTime(craftRemainSec(slot))
        end
    elseif recipe then
        local sub = getSubmittedSlots()
        local n = 0
        for _ in pairs(sub) do n += 1 end
        local need = type(recipe.Inputs) == "table" and #recipe.Inputs or 0
        phase = ("Submit %d/%d"):format(n, need)
    end

    local recipeLine = "—"
    if recipe then
        recipeLine = tostring(recipe.DisplayName or recipe.Id)
    elseif mapHasAny(AUTO_MOON_CRAFTING_RECIPES) then
        local names = {}
        for _, r in ipairs(getAllRecipes()) do
            if AUTO_MOON_CRAFTING_RECIPES[tostring(r.Id)] == true then
                names[#names + 1] = tostring(r.DisplayName or r.Id)
            end
        end
        if #names > 0 then
            recipeLine = table.concat(names, ", ")
            if #recipeLine > 42 then
                recipeLine = recipeLine:sub(1, 39) .. "..."
            end
        end
    end

    return table.concat({
        string.format("%s · %s coins", phase, tostring(coins)),
        recipeLine,
        "Craft " .. flags,
        LAST_STATUS ~= "" and LAST_STATUS or "idle",
    }, "\n")
end

function M.ListRecipeItems()
    local items = {}
    for _, r in ipairs(getAllRecipes()) do
        local cost, cur = recipeCost(r)
        local unlock = tonumber(r.RequiredSummonContributions) or 0
        local right = cost > 0 and (tostring(cost) .. " " .. tostring(cur)) or nil
        if unlock > 0 then
            right = (right and (right .. " · ") or "") .. ("x" .. tostring(unlock))
        end
        items[#items + 1] = {
            key = tostring(r.Id),
            name = tostring(r.DisplayName or r.Id),
            right = right,
        }
    end
    return items
end

function M.SetRecipes(map)
    AUTO_MOON_CRAFTING_RECIPES = toBoolMap(map)
    G.AUTO_MOON_CRAFTING_RECIPES = AUTO_MOON_CRAFTING_RECIPES
    _G.AUTO_MOON_CRAFTING_RECIPES = AUTO_MOON_CRAFTING_RECIPES
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if not anyEnabled() then
            break
        end

        resolveRemote()
        local didWork = false
        local slot = getCraftingSlot(1)

        if slot and slot.IsDone == true then
            local ok, msg = tryClaim()
            if msg then publishStatus(msg) end
            if ok then didWork = true end
        elseif slot then
            publishStatus("crafting " .. fmtTime(craftRemainSec(slot)))
        else
            local ok, msg = tryCraftOrSubmit()
            if msg then publishStatus(msg) end
            if ok then didWork = true end
        end

        if not didWork and LAST_STATUS == "running" then
            publishStatus("idle")
        end

        local waitSec = clampDelay(AUTO_MOON_CRAFTING_DELAY_SEC)
        slot = getCraftingSlot(1)
        if slot and slot.IsDone ~= true then
            local remain = craftRemainSec(slot)
            if remain > 0 then
                waitSec = math.max(waitSec, math.min(5, 1))
            end
        end
        task.wait(waitSec)
    end

    RUNNING = false
    publishStatus("stopped")
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
end

function M.SyncFromState()
    syncGlobalsFromState()
    if anyEnabled() then M.Start() else M.Stop() end
end

function M.Start()
    M.SyncFromGlobals()
    if RUNNING then return end
    if not anyEnabled() then return end
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    publishStatus("stopped")
end

function M.SetEnabled(on)
    AUTO_MOON_CRAFTING_ENABLED = (on == true)
    G.AUTO_MOON_CRAFTING_ENABLED = AUTO_MOON_CRAFTING_ENABLED
    _G.AUTO_MOON_CRAFTING_ENABLED = AUTO_MOON_CRAFTING_ENABLED
    if anyEnabled() then M.Start() else M.Stop() end
end

function M.SetDelay(sec)
    AUTO_MOON_CRAFTING_DELAY_SEC = clampDelay(sec)
    G.AUTO_MOON_CRAFTING_DELAY_SEC = AUTO_MOON_CRAFTING_DELAY_SEC
    _G.AUTO_MOON_CRAFTING_DELAY_SEC = AUTO_MOON_CRAFTING_DELAY_SEC
end

syncGlobalsFromState()
publishStatus("idle")

G.AutoMoonCrafting = M
_G.AutoMoonCrafting = M

return M

