AUTO_PET_ESP_ENABLED = (AUTO_PET_ESP_ENABLED == true)

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_PET_ESP_STATUS = LAST_STATUS
    _G.__AUTO_PET_ESP_STATUS = LAST_STATUS
end

function M.GetStatus()
