local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.pet_esp
    return type(st) == "table" and st or {}
end

local function syncGlobalsFromState()
    local st = getState()
    AUTO_PET_ESP_ENABLED = (
        G.AUTO_PET_ESP_ENABLED == true
        or _G.AUTO_PET_ESP_ENABLED == true
        or AUTO_PET_ESP_ENABLED == true
        or st.enabled == true
    )
    G.AUTO_PET_ESP_ENABLED = AUTO_PET_ESP_ENABLED
    _G.AUTO_PET_ESP_ENABLED = AUTO_PET_ESP_ENABLED
end

local function fmtKg(n)
    n = tonumber(n) or 0
    -- 1 decimal biar muat di slot kecil
    return string.format("%.1f", n)
end

local function calcWeight(baseWeight, level, petType)
    baseWeight = tonumber(baseWeight) or 0
    level = tonumber(level) or 0
    if PetUtilities and type(PetUtilities.CalculateWeight) == "function" then
        local ok, w = pcall(function()
            return PetUtilities:CalculateWeight(baseWeight, level, petType)
        end)
        if ok and tonumber(w) then
            return tonumber(w)
        end
    end
    if petType == "Chubby Chipmunk" then
        return baseWeight
    end
    return baseWeight * (1 + (SCALE_PER_LVL or 0) * level)
end

local function normUUID(uuid)
    if uuid == nil then return nil end
    local s = tostring(uuid):gsub("^BackpackInspection_", "")
    local core = s:match("{?([0-9a-fA-F%-]+)}?") or s
    if core == "" or #core < 8 then return nil end
    return core, "{" .. core .. "}"
end

local function isPetTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    if tool:GetAttribute("PET_UUID") then return true end
    local itemType = tool:GetAttribute("ItemType")
        or (InventoryServiceEnums and tool:GetAttribute(InventoryServiceEnums.ITEM_TYPE))
        or tool:GetAttribute("b")
    if itemType == "Pet" then return true end
    if ItemTypeEnums and itemType == ItemTypeEnums.Pet then return true end -- "l"
    if itemType == "l" then return true end
    -- Jangan pakai pola KG saja (buah juga punya [x KG])
    local n = tostring(tool.Name or "")
    if n:find("%[Age%s*%d+%]") then
        return true
    end
    return false
end

local function toolUUID(tool)
    if not tool then return nil end
    return tool:GetAttribute("PET_UUID")
        or (InventoryServiceEnums and tool:GetAttribute(InventoryServiceEnums.ITEM_UUID))
        or tool:GetAttribute("c")
        or tool:GetAttribute("UUID")
end

-- Hanya pet: wajib ada [Age N]. Buah cuma [KG] → diabaikan.
local function parsePetToolName(text)
    text = tostring(text or "")
    if text == "" then return nil end
    local age = tonumber(text:match("%[Age%s*(%d+)%]"))
        or tonumber(text:match("%[age%s*(%d+)%]"))
    if not age then
        return nil
    end
    local kg = tonumber(text:match("%[([%d%.]+)%s*KG%]"))
        or tonumber(text:match("%[([%d%.]+)%s*kg%]"))
    local petType = text:match("^(.-)%s*%[") or text
    petType = petType:gsub("%s+$", "")
    return {
        petType = petType,
        age = age,
        nowKg = kg,
        raw = text,
    }
end

local function statsFromRec(rec, parsed)
    local petType = parsed and parsed.petType or "?"
    local age = parsed and parsed.age or 0
    local now = parsed and parsed.nowKg or nil
    local age1 = nil

    if type(rec) == "table" then
        local PD = rec.PetData or rec.Data or {}
        petType = tostring(rec.PetType or rec.Type or PD.PetType or petType)
        local base = tonumber(PD.BaseWeight) or tonumber(rec.BaseWeight) or 0
        age = tonumber(PD.Level) or tonumber(PD.Age) or tonumber(rec.Level) or tonumber(rec.Age) or age or 0
        age1 = calcWeight(base, 1, petType)
        now = calcWeight(base, age, petType)
    elseif now and age and age > 0 then
        local denom = 1 + (SCALE_PER_LVL or 0) * age
        if denom > 0 then
            local base = now / denom
            age1 = base * (1 + (SCALE_PER_LVL or 0) * 1)
        end
    end

    if not age1 and now then
        age1 = now
    end
    if not now then
        return nil
    end

    return {
        petType = petType,
        age1 = age1 or now,
        now = now,
        age = math.floor(tonumber(age) or 0),
    }
end

-- 1 baris: Base1 · Age now
local function buildPillText(stats)
    return string.format(
        "<font color=\"#86EFAC\">%s</font><font color=\"#94A3B8\"> · </font><font color=\"#FBBF24\">A%d</font>",
        fmtKg(stats.age1),
        stats.age
    )
end

local function getPetBag()
    local now = os.clock()
    if petBagCache and (now - petBagCacheAt) < 2 then
        return petBagCache
    end
    petBagCacheAt = now
    petBagCache = nil
    if DataService and type(DataService.GetData) == "function" then
        local ok, data = pcall(function() return DataService:GetData() end)
        local inv = ok and data and data.PetsData and data.PetsData.PetInventory
        petBagCache = inv and (inv.Data or inv) or nil
    end
    return petBagCache
end

local function getPetRec(uuid)
    local core, br = normUUID(uuid)
    if not core then return nil end
    local keys = { br, core, tostring(uuid) }

    if PetsService and type(PetsService.GetPlayerPetData) == "function" then
        for _, key in ipairs(keys) do
            local ok, rec = pcall(function()
                return PetsService:GetPlayerPetData(key)
            end)
            if ok and type(rec) == "table" then return rec end
        end
    end

    local bag = getPetBag()
    if type(bag) == "table" then
        for _, key in ipairs(keys) do
            if type(bag[key]) == "table" then
                return bag[key]
            end
        end
        for k, v in pairs(bag) do
            if select(1, normUUID(k)) == core and type(v) == "table" then
                return v
            end
        end
    end
    return nil
end

local function clearAllPills()
    for slot, pill in pairs(tracked) do
        -- restore kalau versi lama sempat hide ToolName
        if slot and slot:GetAttribute("PetEsp_HidTN") == true then
            local tn = slot:FindFirstChild("ToolName")
            if tn and tn:IsA("TextLabel") then
                local prev = slot:GetAttribute("PetEsp_PrevTN")
                tn.Visible = (prev ~= false)
            end
            slot:SetAttribute("PetEsp_HidTN", nil)
            slot:SetAttribute("PetEsp_PrevTN", nil)
        end
        if pill and pill.Parent then
            pcall(function() pill:Destroy() end)
        end
        tracked[slot] = nil
    end
    table.clear(tracked)

    local gui = PlayerGui:FindFirstChild("BackpackGui")
    if not gui then return end
    local inv = gui:FindFirstChild("Backpack") or gui
    local grid = inv:FindFirstChild("UIGridFrame", true)
    local hotbar = inv:FindFirstChild("Hotbar", true)
    local function wipe(container)
        if not container then return end
        for _, child in ipairs(container:GetChildren()) do
            if child:GetAttribute("PetEsp_HidTN") == true then
                local tn = child:FindFirstChild("ToolName")
                if tn and tn:IsA("TextLabel") then
                    local prev = child:GetAttribute("PetEsp_PrevTN")
                    tn.Visible = (prev ~= false)
                end
                child:SetAttribute("PetEsp_HidTN", nil)
                child:SetAttribute("PetEsp_PrevTN", nil)
            end
            local pill = child:FindFirstChild(PILL_NAME)
            if pill then pcall(function() pill:Destroy() end) end
        end
    end
    wipe(grid)
    wipe(hotbar)
end

local function ensurePill(slot)
    local pill = slot:FindFirstChild(PILL_NAME)
    if pill and pill:IsA("Frame") then
        pill.Size = UDim2.new(1, -4, 0, 14)
        pill.Position = UDim2.new(0.5, 0, 1, -2)
        pill.ClipsDescendants = true
        local label = pill:FindFirstChild("Text")
        if label and label:IsA("TextLabel") then
            label.TextWrapped = false
            label.TextScaled = true
            local c = label:FindFirstChild("SizeLimit")
            if c and c:IsA("UITextSizeConstraint") then
                c.MinTextSize = 7
                c.MaxTextSize = 11
            end
        end
        tracked[slot] = pill
        return pill
    end
    if pill then
        pcall(function() pill:Destroy() end)
    end

    pill = Instance.new("Frame")
    pill.Name = PILL_NAME
    pill.AnchorPoint = Vector2.new(0.5, 1)
    pill.Position = UDim2.new(0.5, 0, 1, -2)
    pill.Size = UDim2.new(1, -4, 0, 14)
    pill.BackgroundColor3 = Color3.fromRGB(8, 10, 14)
    pill.BackgroundTransparency = 0.12
    pill.BorderSizePixel = 0
    pill.ZIndex = 30
    pill.ClipsDescendants = true
    pill.Parent = slot

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 4)
    corner.Parent = pill

    local stroke = Instance.new("UIStroke")
    stroke.Thickness = 1
    stroke.Color = Color3.fromRGB(250, 204, 21)
    stroke.Transparency = 0.55
    stroke.Parent = pill

    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, 2)
    pad.PaddingRight = UDim.new(0, 2)
    pad.Parent = pill

    local label = Instance.new("TextLabel")
    label.Name = "Text"
    label.BackgroundTransparency = 1
    label.Size = UDim2.fromScale(1, 1)
    label.Font = Enum.Font.GothamBold
    label.TextColor3 = Color3.fromRGB(255, 255, 255)
    label.TextStrokeTransparency = 0.7
    label.RichText = true
    label.TextWrapped = false
    label.TextScaled = true
    label.TextXAlignment = Enum.TextXAlignment.Center
    label.TextYAlignment = Enum.TextYAlignment.Center
    label.ZIndex = 31
    label.Text = ""
    label.Parent = pill

    local constraint = Instance.new("UITextSizeConstraint")
    constraint.Name = "SizeLimit"
    constraint.MinTextSize = 7
    constraint.MaxTextSize = 11
    constraint.Parent = label

    tracked[slot] = pill
    return pill
end

local function setPillVisible(slot, visible, text)
    if not visible then
        local pill = slot:FindFirstChild(PILL_NAME)
        if pill then
            pill.Visible = false
        end
        return
    end
    local pill = ensurePill(slot)
    pill.Visible = true
    local label = pill:FindFirstChild("Text")
    if label and label:IsA("TextLabel") and text and label.Text ~= text then
        label.Text = text
    end
end

local function collectPetTools()
    local byName = {}
    local byUUID = {}
    local function scan(container)
        if not container then return end
        for _, child in ipairs(container:GetChildren()) do
            if isPetTool(child) then
                byName[child.Name] = child
                local core = select(1, normUUID(toolUUID(child)))
                if core then
                    byUUID[core] = child
                end
            end
        end
    end
    scan(LP:FindFirstChild("Backpack"))
    scan(LP.Character)
    return byName, byUUID
end

local function isInventorySlot(slot)
    if not slot then return false end
    if not (slot:IsA("TextButton") or slot:IsA("ImageButton") or slot:IsA("Frame")) then
        return false
    end
    if slot.Name == PILL_NAME or slot.Name == "FakeSlot" then return false end
    return slot:FindFirstChild("ToolName") ~= nil and slot:FindFirstChild("Icon") ~= nil
end

local function resolveToolForSlot(slot, byName, byUUID)
    local attr = slot:GetAttribute("UUID")
    if attr then
        local core = select(1, normUUID(attr))
        if core and byUUID[core] then
            return byUUID[core]
        end
    end
    local toolName = slot:FindFirstChild("ToolName")
    if toolName and toolName:IsA("TextLabel") then
        local name = toolName.Text
        if name ~= "" and byName[name] then
            return byName[name]
        end
    end
    return nil
end

local function iterSlots(gui)
    local out = {}
    local backpack = gui:FindFirstChild("Backpack") or gui
    local function addFrom(container)
        if not container then return end
        for _, child in ipairs(container:GetChildren()) do
            if isInventorySlot(child) then
                out[#out + 1] = child
            end
        end
    end
    -- Hanya Hotbar + UIGridFrame (bukan GetDescendants seluruh GUI)
    local inv = backpack:FindFirstChild("Inventory")
    local hotbar = backpack:FindFirstChild("Hotbar")
    local grid = inv and inv:FindFirstChild("ScrollingFrame")
    grid = grid and grid:FindFirstChild("UIGridFrame")
    addFrom(hotbar)
    addFrom(grid)
    -- fallback kalau struktur beda
    if #out == 0 then
        local g = backpack:FindFirstChild("UIGridFrame", true)
        local h = backpack:FindFirstChild("Hotbar", true)
        addFrom(g)
        addFrom(h)
    end
    return out
end

local function inventoryOpen(gui)
    local backpack = gui:FindFirstChild("Backpack") or gui
    local inv = backpack:FindFirstChild("Inventory")
    return inv and inv.Visible == true
end

local function rebuildESP()
    local gui = PlayerGui:FindFirstChild("BackpackGui")
    if not gui then
        publishStatus("no backpack")
        return 0
    end

    -- Saat inventory tutup: jangan kerja berat (hindari lag ganti kategori/hotbar)
    if not inventoryOpen(gui) then
        -- tetap update hotbar tipis
    end

    local byName, byUUID = collectPetTools()
    local seen = {}
    local count = 0
    local slots = iterSlots(gui)

    for _, d in ipairs(slots) do
        local toolNameLbl = d:FindFirstChild("ToolName")
        local nameText = toolNameLbl and toolNameLbl.Text or ""
        local tool = resolveToolForSlot(d, byName, byUUID)
        local parsed = parsePetToolName(nameText)
        if not parsed and tool then
            parsed = parsePetToolName(tool.Name)
        end

        -- Pet only: harus tool pet ATAU teks punya [Age]
        local isPet = (tool ~= nil) or (parsed ~= nil)
        if isPet and tool and not isPetTool(tool) then
            isPet = false
        end
        -- Kalau cuma parsed dari teks tanpa tool, parsed sudah wajib Age
        if not tool and not parsed then
            isPet = false
        end

        if isPet and (tool or parsed) then
            local rec = tool and getPetRec(toolUUID(tool)) or nil
            if not rec then
                rec = getPetRec(d:GetAttribute("UUID"))
            end
            local stats = statsFromRec(rec, parsed)
            if stats then
                setPillVisible(d, true, buildPillText(stats))
                seen[d] = true
                count += 1
            else
                setPillVisible(d, false)
            end
        elseif d:FindFirstChild(PILL_NAME) then
            setPillVisible(d, false)
        end
    end

    for slot, pill in pairs(tracked) do
        if not seen[slot] then
            if pill and pill.Parent then
                pill.Visible = false
            end
            if not slot.Parent then
                if pill then pcall(function() pill:Destroy() end) end
                tracked[slot] = nil
            end
        end
    end

    publishStatus(("%d pets"):format(count))
    return count
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if AUTO_PET_ESP_ENABLED ~= true then
            break
        end
        local ok, err = pcall(rebuildESP)
        if not ok then
            publishStatus("err")
            warn("[PetESP]", err)
        end
        local gui = PlayerGui:FindFirstChild("BackpackGui")
        -- Lebih jarang refresh kalau inventory tutup
        if gui and inventoryOpen(gui) then
            task.wait(REFRESH_SEC)
        else
            task.wait(2.5)
        end
    end
    clearAllPills()
    RUNNING = false
    if AUTO_PET_ESP_ENABLED ~= true then
        publishStatus("off")
    else
        publishStatus("stopped")
    end
end

function M.GetStatusText()
    syncGlobalsFromState()
    local on = AUTO_PET_ESP_ENABLED == true and "ON" or "OFF"
    return string.format("Backpack Pet ESP %s\n%s", on, LAST_STATUS ~= "" and LAST_STATUS or "idle")
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
end

function M.SyncFromState()
    syncGlobalsFromState()
    if AUTO_PET_ESP_ENABLED == true then
        M.Start()
    else
        M.Stop()
    end
end

function M.Start()
    syncGlobalsFromState()
    if AUTO_PET_ESP_ENABLED ~= true then
        return
    end
    if RUNNING then
        pcall(rebuildESP)
        return
    end
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    clearAllPills()
    publishStatus("off")
end

function M.Refresh()
    if AUTO_PET_ESP_ENABLED == true then
        pcall(rebuildESP)
    end
end

function M.SetEnabled(on)
    AUTO_PET_ESP_ENABLED = (on == true)
    G.AUTO_PET_ESP_ENABLED = AUTO_PET_ESP_ENABLED
    _G.AUTO_PET_ESP_ENABLED = AUTO_PET_ESP_ENABLED
    if AUTO_PET_ESP_ENABLED then
        M.Start()
    else
        M.Stop()
    end
end

