local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local MIN_DELAY = 0.05
local MAX_DELAY = 300
local DEFAULT_DELAY = 1.0
local DEFAULT_TOTAL = 1
local FARM_CACHE_SEC = 5
local EQUIP_WAIT = 0.2
local BATCH_SIZE = 24
local SCAN_YIELD_EVERY = 200
local FIRE_YIELD_EVERY = 8

local RUNNING = false
local STOP_TOKEN = 0
local LAST_STATUS = "idle"
local DONE_COUNT = 0
local SESSION_HIT_TOTAL = false -- true setelah total tercapai; cegah SyncFromState restart loop

local ReclaimerRE = nil
local InventoryServiceEnums = nil
local StringUtils = nil
local SaveSlotController = nil
local GetFarmAsync = nil

local BLOCKLIST = {
    ["Christmas Tree"] = true,
}

