----------------------------------------------------------------
-- Globals
----------------------------------------------------------------
AUTO_RECLAIMER_ENABLED = (AUTO_RECLAIMER_ENABLED == true)
AUTO_RECLAIMER_SKIP_FAV = (AUTO_RECLAIMER_SKIP_FAV ~= false) -- default ON
AUTO_RECLAIMER_DELAY_SEC = tonumber(AUTO_RECLAIMER_DELAY_SEC) or DEFAULT_DELAY
AUTO_RECLAIMER_TOTAL = math.max(0, math.floor(tonumber(AUTO_RECLAIMER_TOTAL) or DEFAULT_TOTAL))
AUTO_RECLAIMER_PLANTS_SELECTED = AUTO_RECLAIMER_PLANTS_SELECTED or {}

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_RECLAIMER_STATUS = LAST_STATUS
    _G.__AUTO_RECLAIMER_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_reclaimer
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function cleanSelectedMap(src)
    local out = {}
    if type(src) ~= "table" then return out end
    local hasFlags = false
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
            hasFlags = true
        end
    end
    if hasFlags then
        return out
    end
    if #src > 0 then
        for _, k in ipairs(src) do
            if type(k) == "string" or type(k) == "number" then
                local s = tostring(k)
                if s ~= "" then
                    out[s] = true
                end
            end
        end
    end
    return out
end

local function selectedCount(map)
    local n = 0
    if type(map) ~= "table" then return 0 end
    for _, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            n += 1
        end
    end
    return n
end

local function syncGlobalsFromState()
    local st = getState()

    if G.AUTO_RECLAIMER_ENABLED == true
        or _G.AUTO_RECLAIMER_ENABLED == true
        or AUTO_RECLAIMER_ENABLED == true
        or st.enabled == true then
        AUTO_RECLAIMER_ENABLED = true
    else
        AUTO_RECLAIMER_ENABLED = false
    end

    local skipFav = G.AUTO_RECLAIMER_SKIP_FAV
    if skipFav == nil then skipFav = _G.AUTO_RECLAIMER_SKIP_FAV end
    if skipFav == nil then skipFav = AUTO_RECLAIMER_SKIP_FAV end
    if skipFav == nil then skipFav = st.skip_fav end
    AUTO_RECLAIMER_SKIP_FAV = (skipFav ~= false)

    local delaySrc = G.AUTO_RECLAIMER_DELAY_SEC
    if delaySrc == nil then delaySrc = _G.AUTO_RECLAIMER_DELAY_SEC end
    if delaySrc == nil then delaySrc = AUTO_RECLAIMER_DELAY_SEC end
    if delaySrc == nil then delaySrc = st.delaySec end
    AUTO_RECLAIMER_DELAY_SEC = clampDelay(delaySrc)

    local totalSrc = G.AUTO_RECLAIMER_TOTAL
    if totalSrc == nil then totalSrc = _G.AUTO_RECLAIMER_TOTAL end
    if totalSrc == nil then totalSrc = AUTO_RECLAIMER_TOTAL end
    if totalSrc == nil then totalSrc = st.total end
    AUTO_RECLAIMER_TOTAL = math.max(0, math.floor(tonumber(totalSrc) or DEFAULT_TOTAL))

    local plants = G.AUTO_RECLAIMER_PLANTS_SELECTED
    if type(plants) ~= "table" then plants = _G.AUTO_RECLAIMER_PLANTS_SELECTED end
    if type(plants) ~= "table" then plants = AUTO_RECLAIMER_PLANTS_SELECTED end
    if type(plants) ~= "table" then plants = st.plants end
    AUTO_RECLAIMER_PLANTS_SELECTED = cleanSelectedMap(plants)

    G.AUTO_RECLAIMER_ENABLED = AUTO_RECLAIMER_ENABLED
    G.AUTO_RECLAIMER_SKIP_FAV = AUTO_RECLAIMER_SKIP_FAV
    G.AUTO_RECLAIMER_DELAY_SEC = AUTO_RECLAIMER_DELAY_SEC
    G.AUTO_RECLAIMER_TOTAL = AUTO_RECLAIMER_TOTAL
    G.AUTO_RECLAIMER_PLANTS_SELECTED = AUTO_RECLAIMER_PLANTS_SELECTED
    _G.AUTO_RECLAIMER_ENABLED = AUTO_RECLAIMER_ENABLED
    _G.AUTO_RECLAIMER_SKIP_FAV = AUTO_RECLAIMER_SKIP_FAV
    _G.AUTO_RECLAIMER_DELAY_SEC = AUTO_RECLAIMER_DELAY_SEC
    _G.AUTO_RECLAIMER_TOTAL = AUTO_RECLAIMER_TOTAL
    _G.AUTO_RECLAIMER_PLANTS_SELECTED = AUTO_RECLAIMER_PLANTS_SELECTED
end

----------------------------------------------------------------
-- Farm / tool
----------------------------------------------------------------
local cachedFarm, cachedFarmAt = nil, 0

local function getOwnFarm()
    local now = os.clock()
    if cachedFarm and cachedFarm.Parent and (now - cachedFarmAt) <= FARM_CACHE_SEC then
        return cachedFarm
    end
    cachedFarm = nil
    cachedFarmAt = now

    if type(GetFarmAsync) == "function" then
        local ok, farm = pcall(GetFarmAsync, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end

    local farms = workspace:FindFirstChild("Farm")
    if not farms then return nil end
    local username = LP and LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local ok, owner = pcall(function()
            return farm.Important.Data.Owner.Value
        end)
        if ok and owner == username then
            cachedFarm = farm
            return farm
        end
    end
    return nil
end

local function getPlantsFolder()
    local farm = getOwnFarm()
    if not farm then return nil end
    local plants = farm:FindFirstChild("Plants_Physical", true)
    return plants
end

local function usesAttrKey()
    if type(InventoryServiceEnums) == "table" and InventoryServiceEnums.Uses ~= nil then
        return InventoryServiceEnums.Uses
    end
    return "Uses"
end

local function findReclaimerTool()
    local function scan(container)
        if not container then return nil end
        for _, tool in ipairs(container:GetChildren()) do
            if tool:IsA("Tool") then
                local n = tostring(tool.Name or "")
                if n:lower():find("reclaimer", 1, true) then
                    return tool
                end
            end
        end
        return nil
    end
    local char = LP.Character
    return scan(char) or scan(LP:FindFirstChild("Backpack"))
end

local function getReclaimerUses()
    local tool = findReclaimerTool()
    if not tool then return 0, nil end
    local uses = tonumber(tool:GetAttribute(usesAttrKey())) or 1
    return uses, tool
end

local function ensureReclaimerEquipped()
    local tool = findReclaimerTool()
    if not tool then return false end
    local char = LP.Character
    if not char then return false end
    if tool.Parent == char then return true end
    local bag = LP:FindFirstChild("Backpack")
    if tool.Parent ~= bag then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum:EquipTool(tool) end)
    else
        tool.Parent = char
    end
    task.wait(EQUIP_WAIT)
    return tool.Parent == char
end

----------------------------------------------------------------
-- Plant eligibility
----------------------------------------------------------------
local function cleanPlantName(plant)
    local raw = tostring(plant and plant.Name or "")
    return raw:gsub("%s*%[.-%]$", ""):gsub("%s*%(%d+%)$", "")
end

local function plantFilterNames(plant)
    local names = {}
    local function add(v)
        v = tostring(v or ""):gsub("%s*%[.-%]$", ""):gsub("%s*%(%d+%)$", "")
        v = v:gsub("^%s+", ""):gsub("%s+$", "")
        if v ~= "" then
            names[#names + 1] = v
        end
    end
    add(plant and plant.Name)
    if plant then
        add(plant:GetAttribute("ItemName"))
        add(plant:GetAttribute("PlantName"))
        add(plant:GetAttribute("SeedName"))
    end
    return names
end

local function plantAllowedByFilter(name)
    local sel = AUTO_RECLAIMER_PLANTS_SELECTED
    if selectedCount(sel) <= 0 then
        return true
    end
    name = tostring(name or "")
    if name == "" then return false end
    if sel[name] == true then return true end
    local low = name:lower()
    for k, v in pairs(sel) do
        if (v == true or v == 1 or v == "true") and tostring(k):lower() == low then
            return true
        end
    end
    return false
end

local function plantPassesSelectedFilter(plant, fallbackName)
    if selectedCount(AUTO_RECLAIMER_PLANTS_SELECTED) <= 0 then
        return true
    end
    if fallbackName and plantAllowedByFilter(fallbackName) then
        return true
    end
    for _, n in ipairs(plantFilterNames(plant)) do
        if plantAllowedByFilter(n) then
            return true
        end
    end
    return false
end

-- Lightweight unique plant names from own garden (for UI dropdown)
local _gardenListCache, _gardenListAt = nil, 0
local GARDEN_LIST_CACHE_SEC = 2.5

local function listGardenPlantItemsLive()
    local now = os.clock()
    if _gardenListCache and (now - _gardenListAt) <= GARDEN_LIST_CACHE_SEC then
        return _gardenListCache
    end

    local folder = getPlantsFolder()
    local counts = {}

    if folder then
        -- one shallow GetChildren; count per plant type
        for _, plant in ipairs(folder:GetChildren()) do
            local name = cleanPlantName(plant)
            if name ~= "" and not BLOCKLIST[name] then
                counts[name] = (counts[name] or 0) + 1
            end
        end
    end

    local list = {}
    for name, n in pairs(counts) do
        list[#list + 1] = {
            key = name,
            name = string.format("%s x%d", name, n),
            right = tostring(n),
        }
    end

    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)

    _gardenListCache = list
    _gardenListAt = now
    return list
end

local function listGardenPlantItems()
    syncGlobalsFromState()
    local live = listGardenPlantItemsLive()
    local seen = {}
    local list = {}

    for _, item in ipairs(live) do
        local key = tostring(item.key)
        seen[key] = true
        list[#list + 1] = {
            key = key,
            name = item.name,
            right = item.right,
        }
    end

    -- keep selected plants visible even when gone / x0 (so user can unselect)
    for k, v in pairs(AUTO_RECLAIMER_PLANTS_SELECTED or {}) do
        if v == true or v == 1 or v == "true" then
            local key = tostring(k)
            if key ~= "" and not seen[key] then
                seen[key] = true
                list[#list + 1] = {
                    key = key,
                    name = string.format("%s x0", key),
                    right = "0",
                }
            end
        end
    end

    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    return list
end

function M.ListGardenPlantItems()
    return listGardenPlantItems()
end

local function isEasterBlocked()
    if not SaveSlotController then return false end
    local ok, blocked = pcall(function()
        return SaveSlotController:IsCurrentSlotSpecial("EASTER_2026")
    end)
    return ok and blocked == true
end

local function hasFavoritedFruit(plant)
    local fruits = plant:FindFirstChild("Fruits")
    if not fruits then return false end
    for _, child in ipairs(fruits:GetChildren()) do
        if child:GetAttribute("Favorited") == true then
            return true
        end
    end
    return false
end

local function isFullyGrown(plant)
    local maxAge = plant:GetAttribute("MaxAge")
    local grow = plant:FindFirstChild("Grow")
    local age = grow and grow:FindFirstChild("Age")
    if maxAge == nil or not age or not age:IsA("NumberValue") then
        return false
    end
    return age.Value >= maxAge
end

local function filterSignature()
    local sel = AUTO_RECLAIMER_PLANTS_SELECTED or {}
    local keys = {}
    for k, v in pairs(sel) do
        if v == true or v == 1 or v == "true" then
            keys[#keys + 1] = tostring(k):lower()
        end
    end
    table.sort(keys)
    return table.concat(keys, "\0") .. "\0skip:" .. tostring(AUTO_RECLAIMER_SKIP_FAV ~= false)
end

local LAST_FILTER_SIG = ""

local function isEligible(plant, plantsFolder)
    if not plant or not plant.Parent then return false, "gone" end
    local rawName = plant.Name
    if BLOCKLIST[rawName] then
        return false, "blocklist"
    end
    if plant:HasTag("Harvestable") then
        return false, "harvestable"
    end
    if not plant:FindFirstChild("Grow") then
        return false, "no grow"
    end
    if AUTO_RECLAIMER_SKIP_FAV ~= false then
        if plant:GetAttribute("Favorited") == true then
            return false, "favorited"
        end
        if hasFavoritedFruit(plant) then
            return false, "fav fruit"
        end
    end
    if not isFullyGrown(plant) then
        return false, "not grown"
    end
    local name = cleanPlantName(plant)
    if BLOCKLIST[name] then
        return false, "blocklist"
    end
    if not plantPassesSelectedFilter(plant, name) then
        return false, "filter"
    end
    return true, name
end

local _eligCacheN, _eligCacheAt = 0, 0
local ELIG_QUEUE = {}
local ELIG_QUEUE_AT = 0

local function invalidateEligibleQueue()
    ELIG_QUEUE = {}
    ELIG_QUEUE_AT = 0
    LAST_FILTER_SIG = ""
    _eligCacheN = 0
    _eligCacheAt = 0
end

local function rebuildEligibleQueue()
    local folder = getPlantsFolder()
    local out = {}
    if not folder then
        ELIG_QUEUE = out
        ELIG_QUEUE_AT = os.clock()
        _eligCacheN = 0
        _eligCacheAt = ELIG_QUEUE_AT
        return out
    end
    local children = folder:GetChildren()
    for i, plant in ipairs(children) do
        local ok, nameOrReason = isEligible(plant, folder)
        if ok then
            out[#out + 1] = { plant = plant, name = nameOrReason }
        end
        if i % SCAN_YIELD_EVERY == 0 then
            task.wait()
        end
    end
    ELIG_QUEUE = out
    ELIG_QUEUE_AT = os.clock()
    LAST_FILTER_SIG = filterSignature()
    _eligCacheN = #out
    _eligCacheAt = ELIG_QUEUE_AT
    return out
end

local function listEligible(force)
    local sig = filterSignature()
    if force == true or #ELIG_QUEUE == 0 or sig ~= LAST_FILTER_SIG or (os.clock() - ELIG_QUEUE_AT) > 8 then
        return rebuildEligibleQueue()
    end
    local compact = {}
    for _, rec in ipairs(ELIG_QUEUE) do
        local plant = rec and rec.plant
        if plant and plant.Parent and plantPassesSelectedFilter(plant, rec.name) then
            compact[#compact + 1] = rec
        end
    end
    ELIG_QUEUE = compact
    _eligCacheN = #compact
    return compact
end

local function eligibleCountCached()
    local now = os.clock()
    if (now - _eligCacheAt) <= 1.0 then
        return _eligCacheN
    end
    if #ELIG_QUEUE > 0 and (now - ELIG_QUEUE_AT) <= 8 then
        local n = 0
        for _, rec in ipairs(ELIG_QUEUE) do
            if rec.plant and rec.plant.Parent then
                n += 1
            end
        end
        _eligCacheN = n
        _eligCacheAt = now
        return n
    end
    local n = #listEligible(true)
    _eligCacheN = n
    _eligCacheAt = now
    return n
end

----------------------------------------------------------------
-- Actions
----------------------------------------------------------------
local function resolveRemote()
    if ReclaimerRE and ReclaimerRE.Parent then return true end
    local ge = ReplicatedStorage:FindFirstChild("GameEvents")
    if not ge then return false end
    ReclaimerRE = ge:FindFirstChild("ReclaimerService_RE")
    return ReclaimerRE ~= nil
end

local function fireReclaim(plant)
    if not resolveRemote() then return false, "no remote" end
    local ok = pcall(function()
        ReclaimerRE:FireServer("TryReclaim", plant)
    end)
    return ok, ok and "ok" or "fire failed"
end

local function dropPlantsFromQueue(plantSet)
    if type(plantSet) ~= "table" then return end
    local compact = {}
    for _, rec in ipairs(ELIG_QUEUE) do
        local plant = rec and rec.plant
        if plant and plant.Parent and not plantSet[plant] then
            compact[#compact + 1] = rec
        end
    end
    ELIG_QUEUE = compact
    _eligCacheN = #compact
end

local function tryBatch()
    if isEasterBlocked() then
        return false, "easter slot blocked"
    end

    local uses, tool = getReclaimerUses()
    if not tool then
        return false, "no Reclaimer tool"
    end
    if uses <= 0 then
        return false, "Reclaimer uses 0"
    end

    local total = math.max(0, math.floor(tonumber(AUTO_RECLAIMER_TOTAL) or 0))
    if total > 0 and DONE_COUNT >= total then
        SESSION_HIT_TOTAL = true
        return false, ("done %d/%d"):format(DONE_COUNT, total)
    end

    local remainTotal = (total > 0) and math.max(0, total - DONE_COUNT) or BATCH_SIZE
    local remainUses = math.max(0, math.floor(tonumber(uses) or 0))
    local want = math.min(BATCH_SIZE, remainTotal)
    if remainUses > 0 then
        want = math.min(want, remainUses)
    end
    if want <= 0 then
        return false, ("done %d/%s"):format(DONE_COUNT, total > 0 and tostring(total) or "∞")
    end

    local list = listEligible(false)
    if #list <= 0 then
        list = listEligible(true)
    end
    if #list <= 0 then
        return false, "no eligible plant"
    end

    ensureReclaimerEquipped()
    if not resolveRemote() then
        return false, "no remote"
    end

    local targets = {}
    for i = 1, math.min(want, #list) do
        local rec = list[i]
        if rec and rec.plant and rec.plant.Parent and plantPassesSelectedFilter(rec.plant, rec.name) then
            targets[#targets + 1] = rec
        end
    end
    if #targets <= 0 then
        ELIG_QUEUE = {}
        ELIG_QUEUE_AT = 0
        return false, "no eligible plant"
    end

    local fired = 0
    local lastName = "?"
    local firedSet = {}
    for i, rec in ipairs(targets) do
        if total > 0 and DONE_COUNT >= total then
            break
        end
        local plant = rec.plant
        if plant and plant.Parent then
            lastName = rec.name or lastName
            local ok = pcall(function()
                ReclaimerRE:FireServer("TryReclaim", plant)
            end)
            if ok then
                fired += 1
                DONE_COUNT += 1
                firedSet[plant] = true
                if fired % FIRE_YIELD_EVERY == 0 then
                    task.wait()
                end
            end
        end
    end

    dropPlantsFromQueue(firedSet)

    if fired <= 0 then
        ELIG_QUEUE = {}
        ELIG_QUEUE_AT = 0
        return false, "no eligible plant"
    end

    G.__AUTO_RECLAIMER_DONE = DONE_COUNT
    _G.__AUTO_RECLAIMER_DONE = DONE_COUNT
    _eligCacheAt = 0
    _gardenListAt = 0

    if total > 0 and DONE_COUNT >= total then
        SESSION_HIT_TOTAL = true
    end

    return true, ("reclaimed x%d · last %s · %d/%s"):format(
        fired,
        lastName,
        DONE_COUNT,
        total > 0 and tostring(total) or "∞"
    )
end

----------------------------------------------------------------
-- Status / public API
----------------------------------------------------------------
function M.GetStatusText()
    syncGlobalsFromState()
    local uses = select(1, getReclaimerUses())
    local eligible = eligibleCountCached()
    local total = AUTO_RECLAIMER_TOTAL
    local on = AUTO_RECLAIMER_ENABLED == true and "ON" or "OFF"
    local skip = AUTO_RECLAIMER_SKIP_FAV ~= false and "ON" or "OFF"
    local filterN = selectedCount(AUTO_RECLAIMER_PLANTS_SELECTED)

    local lines = {}
    lines[#lines + 1] = ("Done: %d / %s · eligible %d · uses %d"):format(
        DONE_COUNT,
        total > 0 and tostring(total) or "∞",
        eligible,
        uses
    )
    lines[#lines + 1] = ("Enable %s · SkipFav %s · filter %s"):format(
        on,
        skip,
        filterN > 0 and tostring(filterN) or "ALL"
    )
    lines[#lines + 1] = (LAST_STATUS ~= "" and LAST_STATUS or "idle")
    return table.concat(lines, "\n")
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if AUTO_RECLAIMER_ENABLED ~= true then
            break
        end

        local total = math.max(0, math.floor(tonumber(AUTO_RECLAIMER_TOTAL) or 0))
        if total > 0 and DONE_COUNT >= total then
            SESSION_HIT_TOTAL = true
            publishStatus(("done %d/%d"):format(DONE_COUNT, total))
            break
        end

        local ok, msg = tryBatch()
        if msg then publishStatus(msg) end

        -- stop segera kalau total sudah kena (meski verify pending)
        total = math.max(0, math.floor(tonumber(AUTO_RECLAIMER_TOTAL) or 0))
        if total > 0 and DONE_COUNT >= total then
            SESSION_HIT_TOTAL = true
            publishStatus(("done %d/%d"):format(DONE_COUNT, total))
            break
        end

        if not ok then
            if msg == "no eligible plant"
                or msg == "no Reclaimer tool"
                or msg == "Reclaimer uses 0"
                or msg == "easter slot blocked"
                or (type(msg) == "string" and msg:find("^done "))
            then
                if msg == "Reclaimer uses 0"
                    or msg == "no Reclaimer tool"
                    or msg == "easter slot blocked"
                    or (type(msg) == "string" and msg:find("^done "))
                then
                    break
                end
            end
        end

        task.wait(clampDelay(AUTO_RECLAIMER_DELAY_SEC))
    end

    RUNNING = false
    if LAST_STATUS == "running" then
        publishStatus("stopped")
    end
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
end

function M.Start()
    M.SyncFromGlobals()
    if RUNNING then return end
    if AUTO_RECLAIMER_ENABLED ~= true then return end
    -- Jangan restart + reset counter kalau sesi ini sudah hit total
    if SESSION_HIT_TOTAL then
        local total = math.max(0, math.floor(tonumber(AUTO_RECLAIMER_TOTAL) or 0))
        publishStatus(("done %d/%s (waiting disable)"):format(
            DONE_COUNT,
            total > 0 and tostring(total) or "∞"
        ))
        return
    end
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    publishStatus("stopped")
end

function M.SetEnabled(on)
    AUTO_RECLAIMER_ENABLED = (on == true)
    G.AUTO_RECLAIMER_ENABLED = AUTO_RECLAIMER_ENABLED
    _G.AUTO_RECLAIMER_ENABLED = AUTO_RECLAIMER_ENABLED
    if AUTO_RECLAIMER_ENABLED then
        -- Enable ON = sesi baru: reset counter
        SESSION_HIT_TOTAL = false
        DONE_COUNT = 0
        G.__AUTO_RECLAIMER_DONE = 0
        _G.__AUTO_RECLAIMER_DONE = 0
        M.Start()
    else
        SESSION_HIT_TOTAL = false
        M.Stop()
    end
end

function M.SetDelay(sec)
    AUTO_RECLAIMER_DELAY_SEC = clampDelay(sec)
    G.AUTO_RECLAIMER_DELAY_SEC = AUTO_RECLAIMER_DELAY_SEC
    _G.AUTO_RECLAIMER_DELAY_SEC = AUTO_RECLAIMER_DELAY_SEC
end

function M.SetTotal(n)
    AUTO_RECLAIMER_TOTAL = math.max(0, math.floor(tonumber(n) or DEFAULT_TOTAL))
    G.AUTO_RECLAIMER_TOTAL = AUTO_RECLAIMER_TOTAL
    _G.AUTO_RECLAIMER_TOTAL = AUTO_RECLAIMER_TOTAL
    if AUTO_RECLAIMER_TOTAL > 0 and DONE_COUNT >= AUTO_RECLAIMER_TOTAL then
        SESSION_HIT_TOTAL = true
    elseif AUTO_RECLAIMER_TOTAL == 0 then
        -- 0 = ∞ → boleh lanjut lagi kalau enable masih ON
        SESSION_HIT_TOTAL = false
    else
        -- total dinaikkan di atas DONE → boleh lanjut
        SESSION_HIT_TOTAL = false
    end
end

function M.SetSkipFav(on)
    AUTO_RECLAIMER_SKIP_FAV = (on ~= false)
    G.AUTO_RECLAIMER_SKIP_FAV = AUTO_RECLAIMER_SKIP_FAV
    _G.AUTO_RECLAIMER_SKIP_FAV = AUTO_RECLAIMER_SKIP_FAV
    invalidateEligibleQueue()
end

function M.SetPlants(map)
    AUTO_RECLAIMER_PLANTS_SELECTED = cleanSelectedMap(map)
    G.AUTO_RECLAIMER_PLANTS_SELECTED = AUTO_RECLAIMER_PLANTS_SELECTED
    _G.AUTO_RECLAIMER_PLANTS_SELECTED = AUTO_RECLAIMER_PLANTS_SELECTED
    invalidateEligibleQueue()
end

function M.SyncFromState()
    M.SyncFromGlobals()
    if AUTO_RECLAIMER_ENABLED == true then
        M.Start()
    else
        M.Stop()
    end
end

G.AutoReclaimer = M
_G.AutoReclaimer = M

return M

