local G  = (getgenv and getgenv()) or _G
local M  = {}

local MIN_DELAY = 0.05
local MAX_DELAY = 300
local DEFAULT_DELAY = 1.0
local DEFAULT_TOTAL = 0 -- 0 = unlimited
local FARM_CACHE_SEC = 5
local EQUIP_WAIT = 0.15
local FIRE_WAIT = 0.05
local VERIFY_WAIT = 0.35
local VERIFY_RETRY = 8
local VERIFY_STEP = 0.12
-- Game min plant distance ~1; keep tight so Near/Position pack close
local MIN_PLANT_DIST = 1.0
local POSITION_SPACING = 1.0
local NEAR_SPACING = 1.0
local PLANT_GRID = 4.0 -- legacy coarse grid (unused by random)
