local RANDOM_MAX_TRY = 40
local RANDOM_PART_MARGIN = 0.92
local POSITION_MAX_SCAN = 400
local NEAR_MAX_SCAN = 120
local MAX_SAVED_POSITIONS = 40

local MODES = { near = true, position = true, random = true }

local RUNNING = false
local STOP_TOKEN = 0
local LAST_STATUS = "idle"
local DONE_COUNT = 0

local posSlotCursor = 1
local posAnchorCursor = 1
local nearSlotCursor = 1
local nearAnchorCursor = 1

local PlantRE = nil
local GetFarmAsync = nil
local DataService = nil

pcall(function()
