-- Globals
----------------------------------------------------------------
AUTO_PLANT_ENABLED = (AUTO_PLANT_ENABLED == true)
AUTO_PLANT_DELAY_SEC = tonumber(AUTO_PLANT_DELAY_SEC) or DEFAULT_DELAY
AUTO_PLANT_TOTAL = math.max(0, math.floor(tonumber(AUTO_PLANT_TOTAL) or DEFAULT_TOTAL))
AUTO_PLANT_MODE = tostring(AUTO_PLANT_MODE or "near"):lower()
if AUTO_PLANT_MODE == "posisi" or AUTO_PLANT_MODE == "pos" or AUTO_PLANT_MODE == "manual" then
    AUTO_PLANT_MODE = "position"
end
if not MODES[AUTO_PLANT_MODE] then AUTO_PLANT_MODE = "near" end
AUTO_PLANT_SEEDS_SELECTED = AUTO_PLANT_SEEDS_SELECTED or {}
AUTO_PLANT_GARDEN_SELECTED = AUTO_PLANT_GARDEN_SELECTED or {}
AUTO_PLANT_POSITIONS = type(AUTO_PLANT_POSITIONS) == "table" and AUTO_PLANT_POSITIONS or {}
AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED or {}

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_PLANT_STATUS = LAST_STATUS
    _G.__AUTO_PLANT_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_plant
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function cleanSelectedMap(src)
    local out = {}
    if type(src) ~= "table" then return out end
    if #src > 0 then
        for _, k in ipairs(src) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function selectedCount(map)
    local n = 0
    if type(map) ~= "table" then return 0 end
    for _, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            n += 1
        end
    end
    return n
end

local function normalizeMode(v)
    local m = tostring(v or "near"):lower()
    if m == "posisi" or m == "pos" or m == "manual" then
        m = "position"
    end
    if not MODES[m] then m = "near" end
    return m
end

local function round1(n)
    return math.floor((tonumber(n) or 0) * 10 + 0.5) / 10
end

local function makePosKey(pos)
    return string.format("%.1f,%.1f,%.1f", round1(pos.X), round1(pos.Y), round1(pos.Z))
end

local function cleanSeedName(s)
    local n = tostring(s or "")
    n = n:gsub("%s*%[.-%]$", "")
    n = n:gsub("%s*%(%d+%)$", "")
    n = n:gsub("%s+[Ss]eed%s*$", "")
    n = n:gsub("^%s+", ""):gsub("%s+$", "")
    return n
end

local function cleanPlantName(plantOrName)
    local raw = typeof(plantOrName) == "Instance"
        and tostring(plantOrName.Name or "")
        or tostring(plantOrName or "")
    return raw:gsub("%s*%[.-%]$", ""):gsub("%s*%(%d+%)$", "")
end

local function gardenPlantAllowed(name)
    local sel = AUTO_PLANT_GARDEN_SELECTED
    if selectedCount(sel) <= 0 then
        return false -- near mode: must pick garden plant
    end
    if sel[name] == true then return true end
    local low = tostring(name or ""):lower()
    for k, v in pairs(sel) do
        if (v == true or v == 1) and tostring(k):lower() == low then
            return true
        end
    end
    return false
end

local function syncGlobalsFromState()
    local st = getState()

    if G.AUTO_PLANT_ENABLED == true
        or _G.AUTO_PLANT_ENABLED == true
        or AUTO_PLANT_ENABLED == true
        or st.enabled == true then
        AUTO_PLANT_ENABLED = true
    else
        AUTO_PLANT_ENABLED = false
    end

    local delaySrc = G.AUTO_PLANT_DELAY_SEC
    if delaySrc == nil then delaySrc = _G.AUTO_PLANT_DELAY_SEC end
    if delaySrc == nil then delaySrc = AUTO_PLANT_DELAY_SEC end
    if delaySrc == nil then delaySrc = st.delaySec end
    AUTO_PLANT_DELAY_SEC = clampDelay(delaySrc)

    local totalSrc = G.AUTO_PLANT_TOTAL
    if totalSrc == nil then totalSrc = _G.AUTO_PLANT_TOTAL end
    if totalSrc == nil then totalSrc = AUTO_PLANT_TOTAL end
    if totalSrc == nil then totalSrc = st.total end
    AUTO_PLANT_TOTAL = math.max(0, math.floor(tonumber(totalSrc) or DEFAULT_TOTAL))

    local modeSrc = G.AUTO_PLANT_MODE
    if modeSrc == nil then modeSrc = _G.AUTO_PLANT_MODE end
    if modeSrc == nil then modeSrc = AUTO_PLANT_MODE end
    if modeSrc == nil then modeSrc = st.mode end
    AUTO_PLANT_MODE = normalizeMode(modeSrc)

    local seeds = G.AUTO_PLANT_SEEDS_SELECTED
    if type(seeds) ~= "table" then seeds = _G.AUTO_PLANT_SEEDS_SELECTED end
    if type(seeds) ~= "table" then seeds = AUTO_PLANT_SEEDS_SELECTED end
    if type(seeds) ~= "table" then seeds = st.seeds end
    AUTO_PLANT_SEEDS_SELECTED = cleanSelectedMap(seeds)

    local garden = G.AUTO_PLANT_GARDEN_SELECTED
    if type(garden) ~= "table" then garden = _G.AUTO_PLANT_GARDEN_SELECTED end
    if type(garden) ~= "table" then garden = AUTO_PLANT_GARDEN_SELECTED end
    if type(garden) ~= "table" then garden = st.garden_plants end
    AUTO_PLANT_GARDEN_SELECTED = cleanSelectedMap(garden)

    local positions = G.AUTO_PLANT_POSITIONS
    if type(positions) ~= "table" then positions = _G.AUTO_PLANT_POSITIONS end
    if type(positions) ~= "table" then positions = AUTO_PLANT_POSITIONS end
    if type(positions) ~= "table" then positions = st.positions end
    AUTO_PLANT_POSITIONS = type(positions) == "table" and positions or {}

    local posSel = G.AUTO_PLANT_POSITION_SELECTED
    if type(posSel) ~= "table" then posSel = _G.AUTO_PLANT_POSITION_SELECTED end
    if type(posSel) ~= "table" then posSel = AUTO_PLANT_POSITION_SELECTED end
    if type(posSel) ~= "table" then posSel = st.position_selected end
    AUTO_PLANT_POSITION_SELECTED = cleanSelectedMap(posSel)

    G.AUTO_PLANT_ENABLED = AUTO_PLANT_ENABLED
    G.AUTO_PLANT_DELAY_SEC = AUTO_PLANT_DELAY_SEC
    G.AUTO_PLANT_TOTAL = AUTO_PLANT_TOTAL
    G.AUTO_PLANT_MODE = AUTO_PLANT_MODE
    G.AUTO_PLANT_SEEDS_SELECTED = AUTO_PLANT_SEEDS_SELECTED
    G.AUTO_PLANT_GARDEN_SELECTED = AUTO_PLANT_GARDEN_SELECTED
    G.AUTO_PLANT_POSITIONS = AUTO_PLANT_POSITIONS
    G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED

    _G.AUTO_PLANT_ENABLED = AUTO_PLANT_ENABLED
    _G.AUTO_PLANT_DELAY_SEC = AUTO_PLANT_DELAY_SEC
    _G.AUTO_PLANT_TOTAL = AUTO_PLANT_TOTAL
    _G.AUTO_PLANT_MODE = AUTO_PLANT_MODE
    _G.AUTO_PLANT_SEEDS_SELECTED = AUTO_PLANT_SEEDS_SELECTED
    _G.AUTO_PLANT_GARDEN_SELECTED = AUTO_PLANT_GARDEN_SELECTED
    _G.AUTO_PLANT_POSITIONS = AUTO_PLANT_POSITIONS
    _G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED
end

----------------------------------------------------------------
-- Farm / surfaces
----------------------------------------------------------------
local cachedFarm, cachedFarmAt = nil, 0

local function getOwnFarm()
    local now = os.clock()
    if cachedFarm and cachedFarm.Parent and (now - cachedFarmAt) <= FARM_CACHE_SEC then
        return cachedFarm
    end
    cachedFarm = nil
    cachedFarmAt = now

    if type(GetFarmAsync) == "function" then
        local ok, farm = pcall(GetFarmAsync, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end

    local farms = workspace:FindFirstChild("Farm")
    if not farms then return nil end
    local username = LP and LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local ok, owner = pcall(function()
            return farm.Important.Data.Owner.Value
        end)
        if ok and owner == username then
            cachedFarm = farm
            return farm
        end
    end
    return nil
end

local function getPlantsFolder(farm)
    farm = farm or getOwnFarm()
    if not farm then return nil end
    return farm:FindFirstChild("Plants_Physical", true)
end

local function getFarmCF(farm)
    if not farm then return nil end
    if farm:IsA("Model") then
        local ok, pivot = pcall(function() return farm:GetPivot() end)
        if ok and pivot then return pivot end
    end
    local preferred = {
        "Center_Point", "CenterPoint", "Spawn_Point", "SpawnPoint",
        "FarmSpawn", "Base", "Baseplate", "Ground",
    }
    for _, name in ipairs(preferred) do
        local obj = farm:FindFirstChild(name, true)
        if obj and obj:IsA("BasePart") then
            return obj.CFrame
        end
    end
    local sum = Vector3.zero
    local count = 0
    for _, obj in ipairs(farm:GetDescendants()) do
        if obj:IsA("BasePart") then
            sum += obj.Position
            count += 1
            if count >= 40 then break end
        end
    end
    if count > 0 then
        return CFrame.new(sum / count)
    end
    return nil
end

local function getCanPlantParts(farm)
    local out = {}
    if not farm then return out end
    local important = farm:FindFirstChild("Important")
    local plantLocs = important and important:FindFirstChild("Plant_Locations")
    if plantLocs then
        for _, part in ipairs(plantLocs:GetChildren()) do
            if part:IsA("BasePart") and part.Name == "Can_Plant" then
                out[#out + 1] = part
            end
        end
    end
    if #out > 0 then return out end
    for _, desc in ipairs(farm:GetDescendants()) do
        if desc:IsA("BasePart") and desc.Name == "Can_Plant" then
            out[#out + 1] = desc
        end
    end
    return out
end

local function plantGroundXZ(plant)
    if not plant then return nil end
    if plant:IsA("BasePart") then
        return plant.Position.X, plant.Position.Z
    end
    if plant:IsA("Model") then
        local ok, pivot = pcall(function() return plant:GetPivot().Position end)
        if ok and pivot then
            return pivot.X, pivot.Z
        end
        if plant.PrimaryPart then
            return plant.PrimaryPart.Position.X, plant.PrimaryPart.Position.Z
        end
    end
    local part = plant:FindFirstChildWhichIsA("BasePart", true)
    if part then
        return part.Position.X, part.Position.Z
    end
    return nil
end

local function isBlockedSpot(pos, plantsFolder, minDist)
    if not pos then return true end
    minDist = tonumber(minDist) or MIN_PLANT_DIST
    if not plantsFolder then return false end
    local min2 = minDist * minDist
    local px, pz = pos.X, pos.Z
    for _, plant in ipairs(plantsFolder:GetChildren()) do
        local gx, gz = plantGroundXZ(plant)
        if gx and gz then
            local dx = gx - px
            local dz = gz - pz
            if (dx * dx + dz * dz) < min2 then
                return true
            end
        end
    end
    return false
end

local function getGridOffsets()
    local r = PLANT_GRID
    local out = { Vector3.new(0, 0, 0) }
    for _, v in ipairs({
        Vector3.new(r, 0, 0), Vector3.new(-r, 0, 0),
        Vector3.new(0, 0, r), Vector3.new(0, 0, -r),
        Vector3.new(r, 0, r), Vector3.new(-r, 0, r),
        Vector3.new(r, 0, -r), Vector3.new(-r, 0, -r),
        Vector3.new(r * 2, 0, 0), Vector3.new(-r * 2, 0, 0),
        Vector3.new(0, 0, r * 2), Vector3.new(0, 0, -r * 2),
    }) do
        out[#out + 1] = v
    end
    return out
end

local function snapToPart(part, worldPos)
    if not part or not worldPos then return worldPos end
    local localPos = part.CFrame:PointToObjectSpace(worldPos)
    local half = part.Size * 0.45
    local x = math.clamp(localPos.X, -half.X, half.X)
    local z = math.clamp(localPos.Z, -half.Z, half.Z)
    local y = part.Size.Y * 0.5 + 0.05
    return part.CFrame:PointToWorldSpace(Vector3.new(x, y, z))
end

-- Random point anywhere on Can_Plant surface (fills whole plot, not fixed 15-slot grid)
local function randomPointOnPart(part)
    if not part then return nil end
    local size = part.Size
    local margin = RANDOM_PART_MARGIN
    local rx = (math.random() - 0.5) * size.X * margin
    local rz = (math.random() - 0.5) * size.Z * margin
    return (part.CFrame * CFrame.new(rx, size.Y * 0.5 + 0.05, rz)).Position
end

local function pickRandomOnCanPlant(farm, plantsFolder)
    local canPlants = getCanPlantParts(farm)
    if #canPlants == 0 then
        return nil, "no Can_Plant"
    end
    for _ = 1, RANDOM_MAX_TRY do
        local part = canPlants[math.random(1, #canPlants)]
        local pos = randomPointOnPart(part)
        if pos and not isBlockedSpot(pos, plantsFolder, RANDOM_MIN_PLANT_DIST) then
            return pos, nil
        end
    end
    return nil, "no empty slot"
end

local function buildCandidates(farm)
    local canPlants = getCanPlantParts(farm)
    local plantsFolder = getPlantsFolder(farm)
    local offsets = getGridOffsets()
    local list = {}
    for _, part in ipairs(canPlants) do
        local base = part.Position + Vector3.new(0, part.Size.Y * 0.5 + 0.05, 0)
        for _, off in ipairs(offsets) do
            local pos = snapToPart(part, base + off)
            if not isBlockedSpot(pos, plantsFolder, MIN_PLANT_DIST) then
                list[#list + 1] = { pos = pos, part = part }
            end
        end
    end
    return list, plantsFolder
end

----------------------------------------------------------------
-- Seeds (stack = InventoryData / player data; backpack = equip only)
----------------------------------------------------------------
local function seedAllowed(name)
    local sel = AUTO_PLANT_SEEDS_SELECTED
    if selectedCount(sel) <= 0 then
        return true
    end
    if sel[name] == true then return true end
    local want = cleanSeedName(name):lower()
    if want ~= "" and sel[want] == true then return true end
    for k, v in pairs(sel) do
        if v == true or v == 1 then
            local key = cleanSeedName(k):lower()
            if key == want or tostring(k):lower() == want then
                return true
            end
        end
    end
    return false
end

local function getInventoryData()
    if not DataService then return nil end
    if type(DataService.InventoryData) == "table" then
        return DataService.InventoryData
    end
    if type(DataService.GetData) == "function" then
        local ok, profile = pcall(function()
            return DataService:GetData()
        end)
        if ok and type(profile) == "table" and type(profile.InventoryData) == "table" then
            return profile.InventoryData
        end
    end
    if type(DataService.Data) == "table" and type(DataService.Data.InventoryData) == "table" then
        return DataService.Data.InventoryData
    end
    return nil
end

local function normUUID(v)
    if v == nil then return nil end
    local s = tostring(v)
    s = s:gsub("[%[%]%s]", "")
    if s == "" then return nil end
    return s
end

local function isSeedPackName(raw)
    local low = tostring(raw or ""):lower()
    if low == "" then return false end
    if low:find("seed pack", 1, true) then return true end
    if low:find("seedpack", 1, true) then return true end
    return false
end

-- Aggregate seed stacks from player InventoryData only (not backpack tools)
local function scanSeedInventory()
    local counts = {}
    local uuidByName = {}
    local inv = getInventoryData()
    if type(inv) ~= "table" then
        return counts, uuidByName
    end

    for rawUUID, rec in pairs(inv) do
        if type(rec) == "table" then
            local itype = tostring(rec.ItemType or ""):lower()
            if itype == "seed" then
                local data = type(rec.ItemData) == "table" and rec.ItemData or {}
                local rawName = data.ItemName or data.SeedName or data.Name or ""
                if not isSeedPackName(rawName) then
                    local name = cleanSeedName(rawName)
                    if name ~= "" and not isSeedPackName(name) then
                        local qty = math.max(0, math.floor(tonumber(data.Quantity) or 0))
                        if qty > 0 then
                            counts[name] = (counts[name] or 0) + qty
                            if not uuidByName[name] then
                                uuidByName[name] = normUUID(rawUUID)
                                    or normUUID(data.UUID)
                                    or normUUID(data.uuid)
                            end
                        end
                    end
                end
            end
        end
    end

    return counts, uuidByName
end

local function toolMatchesSeed(tool, seedName, wantUUID)
    if not tool or not tool:IsA("Tool") then return false end
    if wantUUID then
        local attr = tool:GetAttribute("c")
            or tool:GetAttribute("C")
            or tool:GetAttribute("UUID")
            or tool:GetAttribute("uuid")
        if normUUID(attr) == wantUUID then
            return true
        end
    end
    local itemType = tool:GetAttribute("ItemType") or tool:GetAttribute("ITEM_TYPE")
    local looksSeed = (tostring(itemType or ""):lower() == "seed")
        or tostring(tool.Name or ""):lower():find("seed", 1, true)
    if itemType ~= nil and not looksSeed then
        return false
    end
    local name = cleanSeedName(tool:GetAttribute("ItemName") or tool.Name)
    return name:lower() == tostring(seedName or ""):lower()
end

-- Backpack / character only — for EquipTool, never for stack counts
local function findSeedToolForEquip(seedName, wantUUID)
    local function scan(container)
        if not container then return nil end
        for _, tool in ipairs(container:GetChildren()) do
            if toolMatchesSeed(tool, seedName, wantUUID) then
                return tool
            end
        end
        return nil
    end
    local char = LP.Character
    return scan(char) or scan(LP:FindFirstChild("Backpack"))
end

local function listSeedItems()
    syncGlobalsFromState()
    local counts = select(1, scanSeedInventory())
    local seen = {}
    local list = {}

    for name, n in pairs(counts) do
        local key = tostring(name)
        seen[key] = true
        list[#list + 1] = {
            key = key,
            name = string.format("%s x%d", key, n),
            right = tostring(n),
        }
    end

    -- keep selected seeds visible even when qty = 0 (so user can unselect)
    for k, v in pairs(AUTO_PLANT_SEEDS_SELECTED or {}) do
        if v == true or v == 1 or v == "true" then
            local key = tostring(k)
            if key ~= "" and not seen[key] then
                seen[key] = true
                list[#list + 1] = {
                    key = key,
                    name = string.format("%s x0", key),
                    right = "0",
                }
            end
        end
    end

    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    return list
end

function M.ListSeedItems()
    return listSeedItems()
end

local _gardenListCache, _gardenListAt = nil, 0
local GARDEN_LIST_CACHE_SEC = 2.5

local function listGardenPlantItemsLive()
    local now = os.clock()
    if _gardenListCache and (now - _gardenListAt) <= GARDEN_LIST_CACHE_SEC then
        return _gardenListCache
    end

    local folder = getPlantsFolder()
    local counts = {}
    if folder then
        for _, plant in ipairs(folder:GetChildren()) do
            local name = cleanPlantName(plant)
            if name ~= "" then
                counts[name] = (counts[name] or 0) + 1
            end
        end
    end

    local list = {}
    for name, n in pairs(counts) do
        list[#list + 1] = {
            key = name,
            name = string.format("%s x%d", name, n),
            right = tostring(n),
        }
    end
    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    _gardenListCache = list
    _gardenListAt = now
    return list
end

local function listGardenPlantItems()
    syncGlobalsFromState()
    local live = listGardenPlantItemsLive()
    local seen = {}
    local list = {}

    for _, item in ipairs(live) do
        local key = tostring(item.key)
        seen[key] = true
        list[#list + 1] = {
            key = key,
            name = item.name,
            right = item.right,
        }
    end

    for k, v in pairs(AUTO_PLANT_GARDEN_SELECTED or {}) do
        if v == true or v == 1 or v == "true" then
            local key = tostring(k)
            if key ~= "" and not seen[key] then
                seen[key] = true
                list[#list + 1] = {
                    key = key,
                    name = string.format("%s x0", key),
                    right = "0",
                }
            end
        end
    end

    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    return list
end

function M.ListGardenPlantItems()
    return listGardenPlantItems()
end

local function pickSeed()
    local counts, uuidByName = scanSeedInventory()
    local names = {}
    for name, n in pairs(counts) do
        if n > 0 and seedAllowed(name) then
            names[#names + 1] = name
        end
    end
    if #names == 0 then
        return nil, nil, "no seed"
    end
    table.sort(names)
    local name = names[((DONE_COUNT % #names) + 1)]
    local tool = findSeedToolForEquip(name, uuidByName[name])
    return name, tool, nil
end

local function equipSeed(tool)
    if not tool then return false end
    local char = LP.Character
    if not char then return false end
    if tool.Parent == char then return true end
    local bag = LP:FindFirstChild("Backpack")
    if tool.Parent ~= bag then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum:EquipTool(tool) end)
    else
        tool.Parent = char
    end
    task.wait(EQUIP_WAIT)
    return tool.Parent == char
end

----------------------------------------------------------------
-- Positions (position mode)
----------------------------------------------------------------
local function cfToTable(cf)
    local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
    return { x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 }
end

local function tableToCF(t)
    if type(t) ~= "table" or #t < 12 then return nil end
    return CFrame.new(table.unpack(t))
end

function M.BuildPositionItems()
    syncGlobalsFromState()
    local items = {}
    for i, p in ipairs(AUTO_PLANT_POSITIONS) do
        if type(p) == "table" then
            local key = tostring(p.key or i)
            local label = string.format(
                "#%d  X %.1f | Y %.1f | Z %.1f",
                i,
                round1(p.rx or 0),
                round1(p.ry or 0),
                round1(p.rz or 0)
            )
            items[#items + 1] = { key = key, name = label }
        end
    end
    return items
end

function M.SaveCurrentPosition()
    syncGlobalsFromState()
    local farm = getOwnFarm()
    if not farm then return false, "no farm" end
    local farmCF = getFarmCF(farm)
    if not farmCF then return false, "no farm cf" end
    local char = LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return false, "no hrp" end

    local relCF = farmCF:ToObjectSpace(hrp.CFrame)
    local relPos = relCF.Position
    local key = makePosKey(relPos)

    for _, p in ipairs(AUTO_PLANT_POSITIONS) do
        if p and p.key == key then
            return true, "exists"
        end
    end

    while #AUTO_PLANT_POSITIONS >= MAX_SAVED_POSITIONS do
        local old = table.remove(AUTO_PLANT_POSITIONS, 1)
        if old and old.key then
            AUTO_PLANT_POSITION_SELECTED[old.key] = nil
        end
    end

    table.insert(AUTO_PLANT_POSITIONS, {
        key = key,
        rx = round1(relPos.X),
        ry = round1(relPos.Y),
        rz = round1(relPos.Z),
        rel = cfToTable(relCF),
    })

    AUTO_PLANT_POSITION_SELECTED[key] = true
    G.AUTO_PLANT_POSITIONS = AUTO_PLANT_POSITIONS
    G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED
    _G.AUTO_PLANT_POSITIONS = AUTO_PLANT_POSITIONS
    _G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED
    return true, key
end

function M.DeletePosition(key)
    key = tostring(key or "")
    for i = #AUTO_PLANT_POSITIONS, 1, -1 do
        local p = AUTO_PLANT_POSITIONS[i]
        if p and tostring(p.key) == key then
            table.remove(AUTO_PLANT_POSITIONS, i)
        end
    end
    AUTO_PLANT_POSITION_SELECTED[key] = nil
    G.AUTO_PLANT_POSITIONS = AUTO_PLANT_POSITIONS
    G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED
    _G.AUTO_PLANT_POSITIONS = AUTO_PLANT_POSITIONS
    _G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED
end

local function resolveSavedWorldPos(farm, entry)
    local farmCF = getFarmCF(farm)
    if not farmCF or type(entry) ~= "table" then return nil end
    local rel = tableToCF(entry.rel)
    if rel then
        return farmCF:ToWorldSpace(rel).Position
    end
    local rx = tonumber(entry.rx) or 0
    local ry = tonumber(entry.ry) or 0
    local rz = tonumber(entry.rz) or 0
    return farmCF:ToWorldSpace(CFrame.new(rx, ry, rz)).Position
end

local function getSelectedSavedEntries()
    local sel = AUTO_PLANT_POSITION_SELECTED
    if selectedCount(sel) <= 0 then
        return {}
    end
    local out = {}
    for _, p in ipairs(AUTO_PLANT_POSITIONS) do
        if type(p) == "table" and sel[tostring(p.key)] == true then
            out[#out + 1] = p
        end
    end
    return out
end

----------------------------------------------------------------
-- Pick plant position by mode
-- near     = spiral tight around selected garden plant(s)
-- position = spiral around saved Location List (many plants / 1 pos)
-- random   = empty slot on Can_Plant
----------------------------------------------------------------
local function offsetForSlot(slot, spacing)
    spacing = tonumber(spacing) or POSITION_SPACING
    if slot <= 1 then
        return Vector3.zero
    end
    local remaining = slot - 1
    local ring = 1
    while remaining > 8 * ring do
        remaining -= 8 * ring
        ring += 1
    end
    local idx = remaining - 1
    local r = ring
    local side = 2 * r
    if idx < side then
        return Vector3.new((-r + idx) * spacing, 0, -r * spacing)
    elseif idx < 2 * side then
        local i = idx - side
        return Vector3.new(r * spacing, 0, (-r + i) * spacing)
    elseif idx < 3 * side then
        local i = idx - 2 * side
        return Vector3.new((r - i) * spacing, 0, r * spacing)
    end
    local i = idx - 3 * side
    return Vector3.new(-r * spacing, 0, (r - i) * spacing)
end

local function getPlantWorldPos(plant)
    if not plant then return nil end
    if plant:IsA("BasePart") then return plant.Position end
    if plant:IsA("Model") then
        local ok, pivot = pcall(function() return plant:GetPivot().Position end)
        if ok and pivot then return pivot end
        if plant.PrimaryPart then return plant.PrimaryPart.Position end
    end
    local part = plant:FindFirstChildWhichIsA("BasePart", true)
    return part and part.Position or nil
end

local function snapToNearestCanPlant(farm, pos)
    if not pos then return nil end
    local canParts = getCanPlantParts(farm)
    if #canParts == 0 then return pos end
    local nearest, nd = nil, math.huge
    for _, part in ipairs(canParts) do
        local d = (part.Position - pos).Magnitude
        if d < nd then
            nd = d
            nearest = part
        end
    end
    if nearest then
        return snapToPart(nearest, pos)
    end
    return pos
end

local function collectSelectedGardenAnchors(plantsFolder)
    if not plantsFolder then return {} end
    if selectedCount(AUTO_PLANT_GARDEN_SELECTED) <= 0 then
        return {}
    end

    local out = {}
    for _, plant in ipairs(plantsFolder:GetChildren()) do
        local name = cleanPlantName(plant)
        if gardenPlantAllowed(name) then
            local p = getPlantWorldPos(plant)
            if p then
                out[#out + 1] = { plant = plant, name = name, pos = p }
            end
        end
    end
    return out
end

-- Spiral around anchors; startSlot=1 includes center, 2 skips center (for Near)
local function pickSpiralAround(farm, plantsFolder, anchors, state, spacing, maxScan, startSlot)
    if type(anchors) ~= "table" or #anchors == 0 then
        return nil, "no anchor"
    end
    spacing = tonumber(spacing) or POSITION_SPACING
    maxScan = math.max(1, math.floor(tonumber(maxScan) or POSITION_MAX_SCAN))
    startSlot = math.max(1, math.floor(tonumber(startSlot) or 1))

    if state.anchorCursor > #anchors or state.anchorCursor < 1 then
        state.anchorCursor = 1
    end
    if state.slotCursor > maxScan or state.slotCursor < startSlot then
        state.slotCursor = startSlot
    end

    for _ = 1, #anchors do
        local aIdx = state.anchorCursor
        local anchor = anchors[aIdx]
        local base = anchor and anchor.pos
        if not base then
            state.anchorCursor += 1
            if state.anchorCursor > #anchors then state.anchorCursor = 1 end
            state.slotCursor = startSlot
        else
            for slot = state.slotCursor, maxScan do
                local offset = offsetForSlot(slot, spacing)
                local pos = snapToNearestCanPlant(farm, base + offset)
                if pos and not isBlockedSpot(pos, plantsFolder, spacing) then
                    state.slotCursor = slot + 1
                    return pos, nil
                end
            end
            -- this anchor full → next anchor
            state.anchorCursor += 1
            if state.anchorCursor > #anchors then state.anchorCursor = 1 end
            state.slotCursor = startSlot
        end
    end
    return nil, "spiral full"
end

local _posPickState = { slotCursor = 1, anchorCursor = 1 }
local _nearPickState = { slotCursor = 2, anchorCursor = 1 }

local function resetPickCursors()
    posSlotCursor = 1
    posAnchorCursor = 1
    nearSlotCursor = 2
    nearAnchorCursor = 1
    _posPickState.slotCursor = 1
    _posPickState.anchorCursor = 1
    _nearPickState.slotCursor = 2
    _nearPickState.anchorCursor = 1
end

-- Mode near: tight spiral beside selected garden plant
local function pickNearPlant(farm, plantsFolder)
    if selectedCount(AUTO_PLANT_GARDEN_SELECTED) <= 0 then
        return nil, "select garden plant"
    end
    if not plantsFolder then
        return nil, "no plant in garden"
    end

    local plants = collectSelectedGardenAnchors(plantsFolder)
    if #plants == 0 then
        return nil, "selected plant gone"
    end

    local char = LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then
        table.sort(plants, function(a, b)
            return (a.pos - hrp.Position).Magnitude < (b.pos - hrp.Position).Magnitude
        end)
    end

    _nearPickState.slotCursor = nearSlotCursor
    _nearPickState.anchorCursor = nearAnchorCursor
    -- startSlot=2 → first ring around plant (not on top of it)
    local pos, err = pickSpiralAround(
        farm, plantsFolder, plants, _nearPickState, NEAR_SPACING, NEAR_MAX_SCAN, 2
    )
    nearSlotCursor = _nearPickState.slotCursor
    nearAnchorCursor = _nearPickState.anchorCursor
    if not pos then
        return nil, err == "spiral full" and "near plant full" or (err or "near plant full")
    end
    return pos, nil
end

local function pickRandom(candidates)
    if #candidates == 0 then return nil end
    return candidates[math.random(1, #candidates)].pos
end

-- Mode position: spiral around saved Location List (many plants per 1 pos)
local function pickPosition(farm, plantsFolder)
    local entries = getSelectedSavedEntries()
    if #entries == 0 then
        if type(AUTO_PLANT_POSITIONS) ~= "table" or #AUTO_PLANT_POSITIONS == 0 then
            return nil, "save position first"
        end
        return nil, "select position"
    end

    local anchors = {}
    for _, entry in ipairs(entries) do
        local pos = resolveSavedWorldPos(farm, entry)
        if pos then
            anchors[#anchors + 1] = { pos = pos, tag = tostring(entry.key or "?") }
        end
    end
    if #anchors == 0 then
        return nil, "no saved position"
    end

    _posPickState.slotCursor = posSlotCursor
    _posPickState.anchorCursor = posAnchorCursor
    local pos, err = pickSpiralAround(
        farm, plantsFolder, anchors, _posPickState, POSITION_SPACING, POSITION_MAX_SCAN, 1
    )
    posSlotCursor = _posPickState.slotCursor
    posAnchorCursor = _posPickState.anchorCursor
    if not pos then
        return nil, err == "spiral full" and "position full" or (err or "position full")
    end
    return pos, nil
end

local function pickPlantPos()
    local farm = getOwnFarm()
    if not farm then
        return nil, "no own farm"
    end

    local mode = AUTO_PLANT_MODE
    local plantsFolder = getPlantsFolder(farm)

    if mode == "position" then
        return pickPosition(farm, plantsFolder)
    end

    if mode == "near" then
        return pickNearPlant(farm, plantsFolder)
    end

    -- random: sample whole Can_Plant surface (not fixed ~15 grid slots)
    return pickRandomOnCanPlant(farm, plantsFolder)
end

----------------------------------------------------------------
-- Fire plant
----------------------------------------------------------------
local function resolveRemote()
    if PlantRE and PlantRE.Parent then return true end
    local ok, rem = pcall(function()
        return ReplicatedStorage.GameEvents:FindFirstChild("Plant_RE")
    end)
    if ok and rem then
        PlantRE = rem
        return true
    end
    return false
end

local function firePlant(pos, seedName)
    if not resolveRemote() then return false, "no Plant_RE" end
    local ok = pcall(function()
        PlantRE:FireServer(pos, seedName)
    end)
    if not ok then
        return false, "fire failed"
    end
    return true
end

local function getSeedQty(seedName)
    local counts = select(1, scanSeedInventory())
    return tonumber(counts[seedName]) or 0
end

local function getToolQty(tool)
    if not tool then return nil end
    local q = tool:GetAttribute("Quantity")
        or tool:GetAttribute("Count")
        or tool:GetAttribute("Uses")
        or tool:GetAttribute("Stack")
    if q ~= nil then
        return math.max(0, math.floor(tonumber(q) or 0))
    end
    return nil
end

local function countPlantsNearPos(plantsFolder, pos, radius)
    if not plantsFolder or not pos then return 0 end
    radius = tonumber(radius) or MIN_PLANT_DIST
    local r2 = radius * radius
    local n = 0
    for _, plant in ipairs(plantsFolder:GetChildren()) do
        local gx, gz = plantGroundXZ(plant)
        if gx and gz then
            local dx = gx - pos.X
            local dz = gz - pos.Z
            if (dx * dx + dz * dz) <= r2 then
                n += 1
            end
        end
    end
    return n
end

local function countAllPlants(plantsFolder)
    if not plantsFolder then return 0 end
    return #plantsFolder:GetChildren()
end

local function tryOne()
    if AUTO_PLANT_TOTAL > 0 and DONE_COUNT >= AUTO_PLANT_TOTAL then
        return false, ("done %d/%d"):format(DONE_COUNT, AUTO_PLANT_TOTAL)
    end

    local seedName, tool, seedErr = pickSeed()
    if not seedName then
        return false, seedErr or "no seed"
    end

    local pos, posErr = pickPlantPos()
    if not pos then
        return false, posErr or "no position"
    end

    if tool then
        if not equipSeed(tool) then
            return false, "equip failed"
        end
    else
        return false, "seed not in backpack"
    end

    local farm = getOwnFarm()
    local plantsFolder = getPlantsFolder(farm)
    local qtyBefore = getSeedQty(seedName)
    local toolQtyBefore = getToolQty(tool)
    local nearBefore = countPlantsNearPos(plantsFolder, pos, math.max(MIN_PLANT_DIST, 1.25))
    local totalBefore = countAllPlants(plantsFolder)

    local ok, err = firePlant(pos, seedName)
    if not ok then
        return false, err
    end

    task.wait(VERIFY_WAIT)

    local verified = false
    for _ = 1, VERIFY_RETRY do
        local qtyAfter = getSeedQty(seedName)
        local toolQtyAfter = getToolQty(tool)
        local nearAfter = countPlantsNearPos(plantsFolder, pos, math.max(MIN_PLANT_DIST, 1.25))
        local totalAfter = countAllPlants(plantsFolder)

        if qtyAfter < qtyBefore then
            verified = true
            break
        end
        if toolQtyBefore ~= nil and toolQtyAfter ~= nil and toolQtyAfter < toolQtyBefore then
            verified = true
            break
        end
        if nearAfter > nearBefore then
            verified = true
            break
        end
        if totalAfter > totalBefore then
            verified = true
            break
        end
        -- tool destroyed / swapped after consume
        if tool and tool.Parent == nil then
            verified = true
            break
        end
        task.wait(VERIFY_STEP)
    end

    if not verified then
        return false, ("plant fail %s"):format(seedName)
    end

    DONE_COUNT += 1
    G.__AUTO_PLANT_DONE = DONE_COUNT
    _G.__AUTO_PLANT_DONE = DONE_COUNT
    task.wait(FIRE_WAIT)
    return true, ("planted %s · %d/%s"):format(
        seedName,
        DONE_COUNT,
        AUTO_PLANT_TOTAL > 0 and tostring(AUTO_PLANT_TOTAL) or "∞"
    )
end

----------------------------------------------------------------
-- Status / loop / API
----------------------------------------------------------------
function M.GetStatusText()
    syncGlobalsFromState()
    local seedN = selectedCount(AUTO_PLANT_SEEDS_SELECTED)
    local gardenN = selectedCount(AUTO_PLANT_GARDEN_SELECTED)
    local posN = selectedCount(AUTO_PLANT_POSITION_SELECTED)
    local owned = 0
    for name, n in pairs(select(1, scanSeedInventory())) do
        if seedAllowed(name) then
            owned += n
        end
    end
    local total = AUTO_PLANT_TOTAL
    local on = AUTO_PLANT_ENABLED == true and "ON" or "OFF"
    local modeTag = AUTO_PLANT_MODE
    if modeTag == "near" then
        modeTag = ("Near · garden %s"):format(gardenN > 0 and tostring(gardenN) or "NONE")
    elseif modeTag == "position" then
        modeTag = ("Position · pos %s"):format(posN > 0 and tostring(posN) or "NONE")
    else
        modeTag = "Random"
    end

    local lines = {}
    lines[#lines + 1] = ("Done: %d / %s · qty %d · %s"):format(
        DONE_COUNT,
        total > 0 and tostring(total) or "∞",
        owned,
        modeTag
    )
    lines[#lines + 1] = ("Enable %s · seed %s"):format(
        on,
        seedN > 0 and tostring(seedN) or "ALL"
    )
    lines[#lines + 1] = (LAST_STATUS ~= "" and LAST_STATUS or "idle")
    return table.concat(lines, "\n")
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if AUTO_PLANT_ENABLED ~= true then
            break
        end

        local total = AUTO_PLANT_TOTAL
        if total > 0 and DONE_COUNT >= total then
            publishStatus(("done %d/%d"):format(DONE_COUNT, total))
            break
        end

        local ok, msg = tryOne()
        if msg then publishStatus(msg) end
        if not ok then
            if msg == "no seed"
                or msg == "seed not in backpack"
                or msg == "equip failed"
                or msg == "no own farm"
                or msg == "no empty slot"
                or msg == "no Can_Plant"
                or msg == "select garden plant"
                or msg == "selected plant gone"
                or msg == "no plant in garden"
                or msg == "near plant full"
                or msg == "position full"
                or msg == "posisi full"
                or msg == "no saved position"
                or msg == "save position first"
                or msg == "save position dulu"
                or msg == "select position"
                or msg == "saved positions full"
                or msg == "no Plant_RE"
                or (type(msg) == "string" and msg:find("^done "))
            then
                if msg == "no seed"
                    or msg == "seed not in backpack"
                    or msg == "no Plant_RE"
                    or msg == "select garden plant"
                    or msg == "select position"
                    or msg == "save position first"
                    or msg == "save position dulu"
                    or msg == "near plant full"
                    or msg == "position full"
                    or msg == "posisi full"
                    or msg == "no empty slot"
                    or msg == "no Can_Plant"
                    or (type(msg) == "string" and msg:find("^done "))
                then
                    break
                end
            end
        end

        task.wait(clampDelay(AUTO_PLANT_DELAY_SEC))
    end

    RUNNING = false
    if LAST_STATUS == "running" then
        publishStatus("stopped")
    end
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
end

function M.Start()
    M.SyncFromGlobals()
    if RUNNING then return end
    if AUTO_PLANT_ENABLED ~= true then return end
    DONE_COUNT = 0
    G.__AUTO_PLANT_DONE = 0
    _G.__AUTO_PLANT_DONE = 0
    resetPickCursors()
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    publishStatus("stopped")
end

function M.SetEnabled(on)
    AUTO_PLANT_ENABLED = (on == true)
    G.AUTO_PLANT_ENABLED = AUTO_PLANT_ENABLED
    _G.AUTO_PLANT_ENABLED = AUTO_PLANT_ENABLED
    if AUTO_PLANT_ENABLED then
        M.Start()
    else
        M.Stop()
    end
end

function M.SetDelay(sec)
    AUTO_PLANT_DELAY_SEC = clampDelay(sec)
    G.AUTO_PLANT_DELAY_SEC = AUTO_PLANT_DELAY_SEC
    _G.AUTO_PLANT_DELAY_SEC = AUTO_PLANT_DELAY_SEC
end

function M.SetTotal(n)
    AUTO_PLANT_TOTAL = math.max(0, math.floor(tonumber(n) or DEFAULT_TOTAL))
    G.AUTO_PLANT_TOTAL = AUTO_PLANT_TOTAL
    _G.AUTO_PLANT_TOTAL = AUTO_PLANT_TOTAL
end

function M.SetMode(mode)
    AUTO_PLANT_MODE = normalizeMode(mode)
    G.AUTO_PLANT_MODE = AUTO_PLANT_MODE
    _G.AUTO_PLANT_MODE = AUTO_PLANT_MODE
end

function M.SetSeeds(map)
    AUTO_PLANT_SEEDS_SELECTED = cleanSelectedMap(map)
    G.AUTO_PLANT_SEEDS_SELECTED = AUTO_PLANT_SEEDS_SELECTED
    _G.AUTO_PLANT_SEEDS_SELECTED = AUTO_PLANT_SEEDS_SELECTED
end

function M.SetGardenPlants(map)
    AUTO_PLANT_GARDEN_SELECTED = cleanSelectedMap(map)
    G.AUTO_PLANT_GARDEN_SELECTED = AUTO_PLANT_GARDEN_SELECTED
    _G.AUTO_PLANT_GARDEN_SELECTED = AUTO_PLANT_GARDEN_SELECTED
end

function M.SetPositions(list)
    AUTO_PLANT_POSITIONS = type(list) == "table" and list or {}
    G.AUTO_PLANT_POSITIONS = AUTO_PLANT_POSITIONS
    _G.AUTO_PLANT_POSITIONS = AUTO_PLANT_POSITIONS
end

function M.SetPositionSelected(map)
    AUTO_PLANT_POSITION_SELECTED = cleanSelectedMap(map)
    G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED
    _G.AUTO_PLANT_POSITION_SELECTED = AUTO_PLANT_POSITION_SELECTED
end

function M.SyncFromState()
    M.SyncFromGlobals()
    if AUTO_PLANT_ENABLED == true then
        M.Start()
    else
        M.Stop()
    end
end

G.AutoPlant = M
_G.AutoPlant = M

return M

