        factory = function()
            -- auto_shovel.lua
-- Auto Shovel plants on own garden via GameEvents.Remove_Item
-- Dump: Shovel [Destroy Plants] → Remove_Item:FireServer(plantModel)
-- Rules: own farm, has Grow, not favorited plant/fruit, not cant-shovel list

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local MIN_DELAY = 0.05
local MAX_DELAY = 300
local DEFAULT_DELAY = 1.0
local DEFAULT_TOTAL = 0 -- 0 = unlimited
local FARM_CACHE_SEC = 5
local EQUIP_WAIT = 0.2
local SHOVEL_NAME = "Shovel [Destroy Plants]"

-- Dump u3 + sprinkler name check
local CANT_SHOVEL = {
    ["Carrot"] = true,
    ["Candy Carrot"] = true,
    ["Christmas Tree"] = true,
}

local RUNNING = false
local STOP_TOKEN = 0
local LAST_STATUS = "idle"
local DONE_COUNT = 0

local RemoveItemRE = nil
local IsInReadOnlySlotRF = nil
local GetFarm = nil
local GetFarmAsync = nil
local StringUtils = nil

pcall(function()
    ReplicatedStorage:WaitForChild("Modules", 30)
end)
pcall(function()
    ReplicatedStorage:WaitForChild("GameEvents", 15)
end)

pcall(function()
    RemoveItemRE = ReplicatedStorage.GameEvents:WaitForChild("Remove_Item", 5)
end)
pcall(function()
    IsInReadOnlySlotRF = ReplicatedStorage.GameEvents.SaveSlotService:WaitForChild("IsInReadOnlySlot", 5)
end)
pcall(function()
    GetFarm = require(ReplicatedStorage.Modules.GetFarm)
end)
pcall(function()
    GetFarmAsync = require(ReplicatedStorage.Modules.GetFarmAsync)
end)
pcall(function()
    StringUtils = require(ReplicatedStorage.Modules.StringUtils)
end)

----------------------------------------------------------------
-- Globals
----------------------------------------------------------------
AUTO_SHOVEL_ENABLED = (AUTO_SHOVEL_ENABLED == true)
AUTO_SHOVEL_DELAY_SEC = tonumber(AUTO_SHOVEL_DELAY_SEC) or DEFAULT_DELAY
AUTO_SHOVEL_TOTAL = math.max(0, math.floor(tonumber(AUTO_SHOVEL_TOTAL) or DEFAULT_TOTAL))
AUTO_SHOVEL_PLANTS_SELECTED = AUTO_SHOVEL_PLANTS_SELECTED or {}

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_SHOVEL_STATUS = LAST_STATUS
    _G.__AUTO_SHOVEL_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_shovel
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function cleanSelectedMap(src)
    local out = {}
    if type(src) ~= "table" then return out end
    if #src > 0 then
        for _, k in ipairs(src) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function selectedCount(map)
    local n = 0
    if type(map) ~= "table" then return 0 end
    for _, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            n += 1
        end
    end
    return n
end

local function syncGlobalsFromState()
    local st = getState()

    if G.AUTO_SHOVEL_ENABLED == true
        or _G.AUTO_SHOVEL_ENABLED == true
        or AUTO_SHOVEL_ENABLED == true
        or st.enabled == true then
        AUTO_SHOVEL_ENABLED = true
    else
        AUTO_SHOVEL_ENABLED = false
    end

    local delaySrc = G.AUTO_SHOVEL_DELAY_SEC
    if delaySrc == nil then delaySrc = _G.AUTO_SHOVEL_DELAY_SEC end
    if delaySrc == nil then delaySrc = AUTO_SHOVEL_DELAY_SEC end
    if delaySrc == nil then delaySrc = st.delaySec end
    AUTO_SHOVEL_DELAY_SEC = clampDelay(delaySrc)

    local totalSrc = G.AUTO_SHOVEL_TOTAL
    if totalSrc == nil then totalSrc = _G.AUTO_SHOVEL_TOTAL end
    if totalSrc == nil then totalSrc = AUTO_SHOVEL_TOTAL end
    if totalSrc == nil then totalSrc = st.total end
    AUTO_SHOVEL_TOTAL = math.max(0, math.floor(tonumber(totalSrc) or DEFAULT_TOTAL))

    local plants = G.AUTO_SHOVEL_PLANTS_SELECTED
    if type(plants) ~= "table" then plants = _G.AUTO_SHOVEL_PLANTS_SELECTED end
    if type(plants) ~= "table" then plants = AUTO_SHOVEL_PLANTS_SELECTED end
    if type(plants) ~= "table" then plants = st.plants end
    AUTO_SHOVEL_PLANTS_SELECTED = cleanSelectedMap(plants)

    G.AUTO_SHOVEL_ENABLED = AUTO_SHOVEL_ENABLED
    G.AUTO_SHOVEL_DELAY_SEC = AUTO_SHOVEL_DELAY_SEC
    G.AUTO_SHOVEL_TOTAL = AUTO_SHOVEL_TOTAL
    G.AUTO_SHOVEL_PLANTS_SELECTED = AUTO_SHOVEL_PLANTS_SELECTED
    _G.AUTO_SHOVEL_ENABLED = AUTO_SHOVEL_ENABLED
    _G.AUTO_SHOVEL_DELAY_SEC = AUTO_SHOVEL_DELAY_SEC
    _G.AUTO_SHOVEL_TOTAL = AUTO_SHOVEL_TOTAL
    _G.AUTO_SHOVEL_PLANTS_SELECTED = AUTO_SHOVEL_PLANTS_SELECTED
end

----------------------------------------------------------------
-- Farm / shovel tool
----------------------------------------------------------------
local cachedFarm, cachedFarmAt = nil, 0

local function getOwnFarm()
    local now = os.clock()
    if cachedFarm and cachedFarm.Parent and (now - cachedFarmAt) <= FARM_CACHE_SEC then
        return cachedFarm
    end
    cachedFarm = nil
    cachedFarmAt = now

    if type(GetFarm) == "function" then
        local ok, farm = pcall(GetFarm, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end
    if type(GetFarmAsync) == "function" then
        local ok, farm = pcall(GetFarmAsync, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end

    local farms = workspace:FindFirstChild("Farm")
    if not farms then return nil end
    local username = LP and LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local ok, owner = pcall(function()
            return farm.Important.Data.Owner.Value
        end)
        if ok and owner == username then
            cachedFarm = farm
            return farm
        end
    end
    return nil
end

local function getPlantsFolder()
    local farm = getOwnFarm()
    if not farm then return nil end
    return farm:FindFirstChild("Plants_Physical", true)
end

local function findShovelTool()
    local function scan(container)
        if not container then return nil end
        for _, tool in ipairs(container:GetChildren()) do
            if tool:IsA("Tool") then
                local n = tostring(tool.Name or "")
                if n == SHOVEL_NAME or n:lower():find("shovel", 1, true) then
                    return tool
                end
            end
        end
        return nil
    end
    local char = LP.Character
    return scan(char) or scan(LP:FindFirstChild("Backpack"))
end

local function ensureShovelEquipped()
    local tool = findShovelTool()
    if not tool then return false end
    local char = LP.Character
    if not char then return false end
    if tool.Parent == char then return true end
    local bag = LP:FindFirstChild("Backpack")
    if tool.Parent ~= bag then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum:EquipTool(tool) end)
    else
        tool.Parent = char
    end
    task.wait(EQUIP_WAIT)
    return tool.Parent == char
end

local function unequipShovelIfHeld()
    local char = LP.Character
    if not char then
        return
    end
    local tool = findShovelTool()
    if not tool or tool.Parent ~= char then
        return
    end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    else
        local bag = LP:FindFirstChild("Backpack")
        if bag then
            pcall(function()
                tool.Parent = bag
            end)
        end
    end
end

local function isReadOnlySlot()
    if not IsInReadOnlySlotRF then return false end
    local ok, blocked = pcall(function()
        return IsInReadOnlySlotRF:InvokeServer()
    end)
    return ok and blocked == true
end

----------------------------------------------------------------
-- Plant rules (from dump)
----------------------------------------------------------------
local function cleanPlantName(plant)
    local raw = tostring(plant and plant.Name or "")
    if StringUtils and type(StringUtils.StipFlavourText) == "function" then
        local ok, cleaned = pcall(function()
            return StringUtils:StipFlavourText(raw)
        end)
        if ok and type(cleaned) == "string" and cleaned ~= "" then
            return cleaned
        end
    end
    return raw:gsub("%s*%[.-%]$", ""):gsub("%s*%(%d+%)$", "")
end

local function cantShovel(name)
    local n = tostring(name or "")
    local low = n:lower()
    if CANT_SHOVEL[n] then return true end
    for k in pairs(CANT_SHOVEL) do
        if low == tostring(k):lower() then return true end
    end
    if low:find("sprinkler", 1, true) then return true end
    return false
end

local function hasFavoritedFruit(plant)
    local fruits = plant:FindFirstChild("Fruits")
    if not fruits then return false end
    for _, child in ipairs(fruits:GetChildren()) do
        if child:GetAttribute("Favorited") == true then
            return true
        end
    end
    return false
end

local function plantAllowedByFilter(name)
    local sel = AUTO_SHOVEL_PLANTS_SELECTED
    if selectedCount(sel) <= 0 then
        return true
    end
    if sel[name] == true then return true end
    local low = name:lower()
    for k, v in pairs(sel) do
        if (v == true or v == 1) and tostring(k):lower() == low then
            return true
        end
    end
    return false
end

local function isEligible(plant, plantsFolder)
    if not plant or not plant.Parent then return false, "gone" end
    if plantsFolder and not plant:IsDescendantOf(plantsFolder) then
        return false, "not own"
    end
    if not plant:FindFirstChild("Grow") then
        return false, "no grow"
    end
    local name = cleanPlantName(plant)
    if cantShovel(name) or cantShovel(plant.Name) then
        return false, "cant shovel"
    end
    if plant:GetAttribute("Favorited") == true then
        return false, "favorited"
    end
    if hasFavoritedFruit(plant) then
        return false, "fav fruit"
    end
    if not plantAllowedByFilter(name) then
        return false, "filter"
    end
    return true, name
end

local _gardenListCache, _gardenListAt = nil, 0
local GARDEN_LIST_CACHE_SEC = 2.5

local function listGardenPlantItemsLive()
    local now = os.clock()
    if _gardenListCache and (now - _gardenListAt) <= GARDEN_LIST_CACHE_SEC then
        return _gardenListCache
    end

    local folder = getPlantsFolder()
    local counts = {}
    if folder then
        for _, plant in ipairs(folder:GetChildren()) do
            local name = cleanPlantName(plant)
            if name ~= "" and not cantShovel(name) then
                counts[name] = (counts[name] or 0) + 1
            end
        end
    end

    local list = {}
    for name, n in pairs(counts) do
        list[#list + 1] = {
            key = name,
            name = string.format("%s x%d", name, n),
            right = tostring(n),
        }
    end
    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    _gardenListCache = list
    _gardenListAt = now
    return list
end

local function listGardenPlantItems()
    syncGlobalsFromState()
    local live = listGardenPlantItemsLive()
    local seen = {}
    local list = {}

    for _, item in ipairs(live) do
        local key = tostring(item.key)
        seen[key] = true
        list[#list + 1] = {
            key = key,
            name = item.name,
            right = item.right,
        }
    end

    -- keep selected plants visible even when gone / x0 (so user can unselect)
    for k, v in pairs(AUTO_SHOVEL_PLANTS_SELECTED or {}) do
        if v == true or v == 1 or v == "true" then
            local key = tostring(k)
            if key ~= "" and not seen[key] then
                seen[key] = true
                list[#list + 1] = {
                    key = key,
                    name = string.format("%s x0", key),
                    right = "0",
                }
            end
        end
    end

    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    return list
end

function M.ListGardenPlantItems()
    return listGardenPlantItems()
end

local function listEligible()
    local folder = getPlantsFolder()
    if not folder then return {} end
    local out = {}
    for _, plant in ipairs(folder:GetChildren()) do
        local ok, nameOrReason = isEligible(plant, folder)
        if ok then
            out[#out + 1] = { plant = plant, name = nameOrReason }
        end
    end
    return out
end

local _eligCacheN, _eligCacheAt = 0, 0
local function eligibleCountCached()
    local now = os.clock()
    if (now - _eligCacheAt) <= 1.0 then
        return _eligCacheN
    end
    _eligCacheN = #listEligible()
    _eligCacheAt = now
    return _eligCacheN
end

----------------------------------------------------------------
-- Fire shovel
----------------------------------------------------------------
local function resolveRemote()
    if RemoveItemRE and RemoveItemRE.Parent then return true end
    local ok, rem = pcall(function()
        return ReplicatedStorage.GameEvents:FindFirstChild("Remove_Item")
    end)
    if ok and rem then
        RemoveItemRE = rem
        return true
    end
    return false
end

local function fireRemove(plant)
    if not resolveRemote() then return false, "no Remove_Item" end
    local ok = pcall(function()
        RemoveItemRE:FireServer(plant)
    end)
    if not ok then
        return false, "fire failed"
    end
    return true
end

local VERIFY_WAIT = 0.4
local VERIFY_RETRY = 6
local VERIFY_STEP = 0.1

local function plantStillExists(plant, plantsFolder)
    if not plant then return false end
    if not plant.Parent then return false end
    if plantsFolder and not plant:IsDescendantOf(plantsFolder) then
        return false
    end
    return true
end

local function tryOne()
    if AUTO_SHOVEL_TOTAL > 0 and DONE_COUNT >= AUTO_SHOVEL_TOTAL then
        return false, ("done %d/%d"):format(DONE_COUNT, AUTO_SHOVEL_TOTAL)
    end

    if isReadOnlySlot() then
        return false, "read-only slot"
    end

    local plantsFolder = getPlantsFolder()
    local list = listEligible()
    if #list == 0 then
        unequipShovelIfHeld()
        return false, "no eligible plant"
    end

    if not findShovelTool() then
        return false, "no shovel"
    end
    if not ensureShovelEquipped() then
        return false, "equip failed"
    end

    local target = list[1]
    local plant = target.plant
    local name = target.name
    local eligBefore = #list

    local ok, err = fireRemove(plant)
    if not ok then
        return false, err
    end

    -- verify plant benar-benar hilang (jangan +1 cuma karena FireServer ok)
    task.wait(VERIFY_WAIT)
    local gone = false
    for _ = 1, VERIFY_RETRY do
        if not plantStillExists(plant, plantsFolder) then
            gone = true
            break
        end
        task.wait(VERIFY_STEP)
    end

    if not gone then
        return false, ("shovel fail %s"):format(name)
    end

    DONE_COUNT += 1
    G.__AUTO_SHOVEL_DONE = DONE_COUNT
    _G.__AUTO_SHOVEL_DONE = DONE_COUNT
    _eligCacheAt = 0
    _gardenListAt = 0

    return true, ("shoveled %s · %d/%s · left ~%d"):format(
        name,
        DONE_COUNT,
        AUTO_SHOVEL_TOTAL > 0 and tostring(AUTO_SHOVEL_TOTAL) or "∞",
        math.max(0, eligBefore - 1)
    )
end

