-- Status / loop / API
----------------------------------------------------------------
function M.GetStatusText()
    syncGlobalsFromState()
    local eligible = eligibleCountCached()
    local total = AUTO_SHOVEL_TOTAL
    local on = AUTO_SHOVEL_ENABLED == true and "ON" or "OFF"
    local filterN = selectedCount(AUTO_SHOVEL_PLANTS_SELECTED)
    local hasShovel = findShovelTool() ~= nil

    local lines = {}
    lines[#lines + 1] = ("Done: %d / %s · eligible %d · shovel %s"):format(
        DONE_COUNT,
        total > 0 and tostring(total) or "∞",
        eligible,
        hasShovel and "OK" or "NO"
    )
    lines[#lines + 1] = ("Enable %s · filter %s"):format(
        on,
        filterN > 0 and tostring(filterN) or "ALL"
    )
    lines[#lines + 1] = (LAST_STATUS ~= "" and LAST_STATUS or "idle")
    return table.concat(lines, "\n")
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if AUTO_SHOVEL_ENABLED ~= true then
            break
        end

        local total = AUTO_SHOVEL_TOTAL
        if total > 0 and DONE_COUNT >= total then
            publishStatus(("done %d/%d"):format(DONE_COUNT, total))
            break
        end

        local ok, msg = tryOne()
        if msg then publishStatus(msg) end
        if not ok then
            if msg == "no shovel"
                or msg == "equip failed"
                or msg == "read-only slot"
                or msg == "no Remove_Item"
                or msg == "no eligible plant"
                or (type(msg) == "string" and msg:find("^done "))
            then
                break
            end
        end

        task.wait(clampDelay(AUTO_SHOVEL_DELAY_SEC))
    end

    RUNNING = false
    unequipShovelIfHeld()
    if LAST_STATUS == "running" then
        publishStatus("stopped")
    end
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
end

function M.Start()
    M.SyncFromGlobals()
    if RUNNING then return end
    if AUTO_SHOVEL_ENABLED ~= true then return end
    DONE_COUNT = 0
    G.__AUTO_SHOVEL_DONE = 0
    _G.__AUTO_SHOVEL_DONE = 0
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    unequipShovelIfHeld()
    publishStatus("stopped")
end

function M.SetEnabled(on)
    AUTO_SHOVEL_ENABLED = (on == true)
    G.AUTO_SHOVEL_ENABLED = AUTO_SHOVEL_ENABLED
    _G.AUTO_SHOVEL_ENABLED = AUTO_SHOVEL_ENABLED
    if AUTO_SHOVEL_ENABLED then
        M.Start()
    else
        M.Stop()
    end
end

function M.SetDelay(sec)
    AUTO_SHOVEL_DELAY_SEC = clampDelay(sec)
    G.AUTO_SHOVEL_DELAY_SEC = AUTO_SHOVEL_DELAY_SEC
    _G.AUTO_SHOVEL_DELAY_SEC = AUTO_SHOVEL_DELAY_SEC
end

function M.SetTotal(n)
    AUTO_SHOVEL_TOTAL = math.max(0, math.floor(tonumber(n) or DEFAULT_TOTAL))
    G.AUTO_SHOVEL_TOTAL = AUTO_SHOVEL_TOTAL
    _G.AUTO_SHOVEL_TOTAL = AUTO_SHOVEL_TOTAL
end

function M.SetPlants(map)
    AUTO_SHOVEL_PLANTS_SELECTED = cleanSelectedMap(map)
    G.AUTO_SHOVEL_PLANTS_SELECTED = AUTO_SHOVEL_PLANTS_SELECTED
    _G.AUTO_SHOVEL_PLANTS_SELECTED = AUTO_SHOVEL_PLANTS_SELECTED
end

function M.SyncFromState()
    M.SyncFromGlobals()
    if AUTO_SHOVEL_ENABLED == true then
        M.Start()
    else
        M.Stop()
    end
end

G.AutoShovel = M
_G.AutoShovel = M

