local IDLE_WAIT = 0.25
local FARM_CACHE_SEC = 5
local EQUIP_WAIT = 0.12
local READONLY_CACHE_SEC = 8
local VERIFY_RETRY = 16
local VERIFY_STEP = 0.03
local INFLIGHT_SEC = 1.0
local FAIL_SKIP_SEC = 6
-- Tes live: gap <0.5s → fruit genap not removed. 0.55s after gone = 6/6.
local POST_SUCCESS_WAIT = 0.52
local SHOVEL_NAME = "Shovel [Destroy Plants]"

