AUTO_SHOVEL_FRUIT_ENABLED = (AUTO_SHOVEL_FRUIT_ENABLED == true)
AUTO_SHOVEL_FRUIT_DELAY_SEC = tonumber(AUTO_SHOVEL_FRUIT_DELAY_SEC) or DEFAULT_DELAY
AUTO_SHOVEL_FRUIT_SELECTED = AUTO_SHOVEL_FRUIT_SELECTED or {}
AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED = AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED or {}
AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED = AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED or {}
AUTO_SHOVEL_FRUIT_KG = tonumber(AUTO_SHOVEL_FRUIT_KG) or 0
AUTO_SHOVEL_FRUIT_KG_MODE = tostring(AUTO_SHOVEL_FRUIT_KG_MODE or "above")

local inflight = {}
local skipUntil = {}

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_SHOVEL_FRUIT_STATUS = LAST_STATUS
    _G.__AUTO_SHOVEL_FRUIT_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_shovel_fruit
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v)
    if n == nil then n = DEFAULT_DELAY end
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function cleanSelectedMap(src)
    local out = {}
    if type(src) ~= "table" then return out end
    if #src > 0 then
        for _, k in ipairs(src) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function selectedCount(map)
    local n = 0
    if type(map) ~= "table" then return 0 end
    for _, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            n += 1
        end
    end
    return n
end

local function _canonKey(s)
    s = tostring(s or "")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")
    s = s:gsub("^[Ff]ruit[_%s%-]+", "")
    s = s:gsub("^[Ss]eed[_%s%-]+", "")
    s = s:gsub("^[Pp]lant[_%s%-]+", "")
    s = s:gsub("[_%s%-]+[Ss]eed$", "")
    s = s:gsub("%s+[Ss]eed$", "")
    s = s:lower()
    s = s:gsub("[^%w]+", "")
    return s
end

local function hasAnySelected(map)
    return selectedCount(map) > 0
end

local function pickMap(...)
    for i = 1, select("#", ...) do
        local v = select(i, ...)
        if type(v) == "table" then
            return v
        end
    end
    return {}
end

local function syncGlobalsFromState()
    local st = getState()

    if G.AUTO_SHOVEL_FRUIT_ENABLED == true
        or _G.AUTO_SHOVEL_FRUIT_ENABLED == true
        or AUTO_SHOVEL_FRUIT_ENABLED == true
        or st.enabled == true then
        AUTO_SHOVEL_FRUIT_ENABLED = true
    else
        AUTO_SHOVEL_FRUIT_ENABLED = false
    end

    local delaySrc = G.AUTO_SHOVEL_FRUIT_DELAY_SEC
    if delaySrc == nil then delaySrc = _G.AUTO_SHOVEL_FRUIT_DELAY_SEC end
    if delaySrc == nil then delaySrc = AUTO_SHOVEL_FRUIT_DELAY_SEC end
    if delaySrc == nil then delaySrc = st.delaySec end
    AUTO_SHOVEL_FRUIT_DELAY_SEC = clampDelay(delaySrc)

    AUTO_SHOVEL_FRUIT_SELECTED = cleanSelectedMap(pickMap(
        G.AUTO_SHOVEL_FRUIT_SELECTED,
        _G.AUTO_SHOVEL_FRUIT_SELECTED,
        AUTO_SHOVEL_FRUIT_SELECTED,
        st.fruits
    ))
    AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED = cleanSelectedMap(pickMap(
        G.AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED,
        _G.AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED,
        AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED,
        st.variants
    ))
    AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED = cleanSelectedMap(pickMap(
        G.AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED,
        _G.AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED,
        AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED,
        st.mutations
    ))

    local kgSrc = G.AUTO_SHOVEL_FRUIT_KG
    if kgSrc == nil then kgSrc = _G.AUTO_SHOVEL_FRUIT_KG end
    if kgSrc == nil then kgSrc = AUTO_SHOVEL_FRUIT_KG end
    if kgSrc == nil then kgSrc = st.kg end
    AUTO_SHOVEL_FRUIT_KG = tonumber(kgSrc) or 0

    local modeSrc = G.AUTO_SHOVEL_FRUIT_KG_MODE
    if modeSrc == nil then modeSrc = _G.AUTO_SHOVEL_FRUIT_KG_MODE end
    if modeSrc == nil then modeSrc = AUTO_SHOVEL_FRUIT_KG_MODE end
    if modeSrc == nil then modeSrc = st.kgMode end
    modeSrc = tostring(modeSrc or "above")
    if modeSrc ~= "below" then modeSrc = "above" end
    AUTO_SHOVEL_FRUIT_KG_MODE = modeSrc

    G.AUTO_SHOVEL_FRUIT_ENABLED = AUTO_SHOVEL_FRUIT_ENABLED
    G.AUTO_SHOVEL_FRUIT_DELAY_SEC = AUTO_SHOVEL_FRUIT_DELAY_SEC
    G.AUTO_SHOVEL_FRUIT_SELECTED = AUTO_SHOVEL_FRUIT_SELECTED
    G.AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED = AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED
    G.AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED = AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED
    G.AUTO_SHOVEL_FRUIT_KG = AUTO_SHOVEL_FRUIT_KG
    G.AUTO_SHOVEL_FRUIT_KG_MODE = AUTO_SHOVEL_FRUIT_KG_MODE
    G.AUTO_SHOVEL_FRUIT_RULES = type(st.rules) == "table" and st.rules or (G.AUTO_SHOVEL_FRUIT_RULES or {})
    G.AUTO_SHOVEL_FRUIT_RULE_MODE = tostring(st.ruleMode or G.AUTO_SHOVEL_FRUIT_RULE_MODE or "keep")
    st.rules = G.AUTO_SHOVEL_FRUIT_RULES
    st.ruleMode = G.AUTO_SHOVEL_FRUIT_RULE_MODE
    _G.AUTO_SHOVEL_FRUIT_ENABLED = AUTO_SHOVEL_FRUIT_ENABLED
    _G.AUTO_SHOVEL_FRUIT_DELAY_SEC = AUTO_SHOVEL_FRUIT_DELAY_SEC
    _G.AUTO_SHOVEL_FRUIT_SELECTED = AUTO_SHOVEL_FRUIT_SELECTED
    _G.AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED = AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED
    _G.AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED = AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED
    _G.AUTO_SHOVEL_FRUIT_KG = AUTO_SHOVEL_FRUIT_KG
    _G.AUTO_SHOVEL_FRUIT_KG_MODE = AUTO_SHOVEL_FRUIT_KG_MODE
    _G.AUTO_SHOVEL_FRUIT_RULES = G.AUTO_SHOVEL_FRUIT_RULES
    _G.AUTO_SHOVEL_FRUIT_RULE_MODE = G.AUTO_SHOVEL_FRUIT_RULE_MODE
