local cachedFarm, cachedFarmAt = nil, 0

local function getOwnFarm()
    local now = os.clock()
    if cachedFarm and cachedFarm.Parent and (now - cachedFarmAt) <= FARM_CACHE_SEC then
        return cachedFarm
    end
    cachedFarm = nil
    cachedFarmAt = now

    if type(GetFarm) == "function" then
        local ok, farm = pcall(GetFarm, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end
    if type(GetFarmAsync) == "function" then
        local ok, farm = pcall(GetFarmAsync, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end

    local farms = workspace:FindFirstChild("Farm")
    if not farms then return nil end
    local username = LP and LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local ok, owner = pcall(function()
            return farm.Important.Data.Owner.Value
        end)
        if ok and owner == username then
            cachedFarm = farm
            return farm
        end
    end
    return nil
end

local function getPlantsFolder()
    local farm = getOwnFarm()
    if not farm then return nil end
    return farm:FindFirstChild("Plants_Physical", true)
end

local function findShovelTool()
    local function scan(container)
        if not container then return nil end
        for _, tool in ipairs(container:GetChildren()) do
            if tool:IsA("Tool") then
                local n = tostring(tool.Name or "")
                if n == SHOVEL_NAME or n:lower():find("shovel", 1, true) then
                    return tool
                end
            end
        end
        return nil
    end
    local char = LP.Character
    return scan(char) or scan(LP:FindFirstChild("Backpack"))
end

local function ensureShovelEquipped()
    local tool = findShovelTool()
    if not tool then return false end
    local char = LP.Character
    if not char then return false end
    if tool.Parent == char then return true end
    local bag = LP:FindFirstChild("Backpack")
    if tool.Parent ~= bag then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum:EquipTool(tool) end)
    else
        tool.Parent = char
    end
    local t0 = os.clock()
    while tool.Parent ~= char and (os.clock() - t0) < EQUIP_WAIT do
        task.wait(0.03)
    end
    return tool.Parent == char
end

local function unequipShovelIfHeld()
    local char = LP.Character
    if not char then
        return
    end
    local tool = findShovelTool()
    if not tool or tool.Parent ~= char then
        return
    end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    else
        local bag = LP:FindFirstChild("Backpack")
        if bag then
            pcall(function()
                tool.Parent = bag
            end)
        end
    end
end

local readonlyCached, readonlyAt = false, 0

local function isReadOnlySlot()
    local now = os.clock()
    if (now - readonlyAt) <= READONLY_CACHE_SEC then
        return readonlyCached
    end
    readonlyAt = now
    if not IsInReadOnlySlotRF then
        readonlyCached = false
        return false
    end
    local ok, blocked = pcall(function()
        return IsInReadOnlySlotRF:InvokeServer()
    end)
    readonlyCached = ok and blocked == true
    return readonlyCached
end

local function getValue(inst, name)
    local v = inst and inst:FindFirstChild(name)
    if v and (
        v:IsA("StringValue")
        or v:IsA("NumberValue")
        or v:IsA("IntValue")
        or v:IsA("BoolValue")
    ) then
        return v.Value
    end
    return nil
end

local function getFruitName(fruit)
    return getValue(fruit, "Item_String")
        or fruit:GetAttribute("ItemName")
        or fruit:GetAttribute("FruitName")
        or fruit:GetAttribute("SeedName")
        or fruit.Name
end

local function getFruitVariant(fruit)
    return tostring(
        getValue(fruit, "Variant")
        or fruit:GetAttribute("Variant")
        or "Normal"
    )
end

local function getFruitWeight(fruit)
    return tonumber(
        getValue(fruit, "Weight")
        or fruit:GetAttribute("Weight")
        or 0
    ) or 0
end

local function matchSet(selectedMap, value)
    if not hasAnySelected(selectedMap) then
        return true
    end
    local needle = _canonKey(value)
    for k, v in pairs(selectedMap) do
        if (v == true or v == 1) and _canonKey(k) == needle then
            return true
        end
    end
    return false
end

local function matchMutation(selectedMap, fruit)
    if not hasAnySelected(selectedMap) then
        return true
    end
    for selectedName, on in pairs(selectedMap) do
        if (on == true or on == 1) and fruit:GetAttribute(selectedName) == true then
            return true
        end
    end
    return false
end

local function matchKg(weight, kg, mode)
    kg = tonumber(kg) or 0
    weight = tonumber(weight) or 0
    if kg <= 0 then
        return true
    end
    if tostring(mode) == "below" then
        return weight <= kg
    end
    return weight >= kg
end

local function pruneInflight()
    local now = os.clock()
    for fruit, at in pairs(inflight) do
        local t = tonumber(at) or 0
        if not fruit or not fruit.Parent or (now - t) >= INFLIGHT_SEC then
            inflight[fruit] = nil
        end
    end
    for fruit, untilAt in pairs(skipUntil) do
        if not fruit or not fruit.Parent or now >= (tonumber(untilAt) or 0) then
            skipUntil[fruit] = nil
        end
    end
end

local function isRipeFruit(f)
    if not f then
        return false
    end
    local tagged = false
    pcall(function()
        tagged = CollectionService:HasTag(f, "Harvestable") == true
    end)
    if tagged then
        return true
    end
    local prompt = f:FindFirstChildWhichIsA("ProximityPrompt", true)
    if prompt and prompt.Enabled == true then
        return true
    end
    local maxAge = tonumber(f:GetAttribute("MaxAge"))
    local grow = f:FindFirstChild("Grow")
    local ageVal = grow and grow:FindFirstChild("Age")
    if maxAge ~= nil and ageVal and (ageVal:IsA("NumberValue") or ageVal:IsA("IntValue")) then
        return (tonumber(ageVal.Value) or 0) >= maxAge
    end
    local done = tonumber(f:GetAttribute("DoneGrowTime"))
    if done and done > 0 then
        local now = os.time()
        pcall(function()
            now = workspace:GetServerTimeNow()
        end)
        return now >= done
    end
    return false
end

local function fruitAllowed(fruit)
    if not fruit or not fruit:IsA("Model") then
        return false
    end
    if fruit:GetAttribute("Favorited") == true then
        return false
    end
    if inflight[fruit] then
        return false
    end
    local skipAt = skipUntil[fruit]
    if skipAt and os.clock() < skipAt then
        return false
    end
    local name = getFruitName(fruit)
    local variant = getFruitVariant(fruit)
    local weight = getFruitWeight(fruit)
    local st = getState()
    local CR = G.CollectRules or rawget(_G, "CollectRules")
    if type(CR) == "table" and type(CR.Has) == "function" and type(CR.Allow) == "function" and CR.Has(st.rules) then
        local fruitMuts = {}
        if type(CR.FruitMuts) == "function" then
            fruitMuts = CR.FruitMuts(fruit)
        else
            local attrs = fruit:GetAttributes()
            if type(attrs) == "table" then
                for k, v in pairs(attrs) do
                    if v == true then
                        fruitMuts[tostring(k)] = true
                    end
                end
            end
        end
        return CR.Allow(st.ruleMode, st.rules, name, variant, weight, fruitMuts) == true
    end
    if not matchSet(AUTO_SHOVEL_FRUIT_SELECTED, name) then
        return false
    end
    if not matchSet(AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED, variant) then
        return false
    end
    if not matchMutation(AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED, fruit) then
        return false
    end
    if not matchKg(weight, AUTO_SHOVEL_FRUIT_KG, AUTO_SHOVEL_FRUIT_KG_MODE) then
        return false
    end
    return true
end

local function collectOne()
    pruneInflight()
    local folder = getPlantsFolder()
    if not folder then
        LAST_ELIGIBLE = 0
        return nil
    end

    local seen = 0
    local firstUnripe = nil
    local firstRipe = nil
    for _, plant in ipairs(folder:GetChildren()) do
        if plant:GetAttribute("Favorited") ~= true then
            local fruits = plant:FindFirstChild("Fruits")
            if fruits then
                for _, fruit in ipairs(fruits:GetChildren()) do
                    if fruitAllowed(fruit) then
                        seen += 1
                        if isRipeFruit(fruit) then
                            if not firstRipe then
                                firstRipe = fruit
                            end
                        elseif not firstUnripe then
                            firstUnripe = fruit
                        end
                    end
                end
            end
        end
    end
    LAST_ELIGIBLE = seen
    return firstUnripe or firstRipe
end

local function resolveRemote()
    if RemoveItemRE and RemoveItemRE.Parent then return true end
    local ok, rem = pcall(function()
        return ReplicatedStorage.GameEvents:FindFirstChild("Remove_Item")
    end)
    if ok and rem then
        RemoveItemRE = rem
        return true
    end
    return false
end

local function fireOne()
    if not resolveRemote() then
        return 0, "no Remove_Item"
    end
    if isReadOnlySlot() then
        return 0, "read-only slot"
    end
    local fruit = collectOne()
    if not fruit then
        unequipShovelIfHeld()
        return 0, "no eligible fruit"
    end
    if not findShovelTool() then
        return 0, "no shovel"
    end
    if not ensureShovelEquipped() then
        return 0, "equip failed"
    end

    inflight[fruit] = os.clock()
    local t0 = os.clock()
    local ok = pcall(function()
        RemoveItemRE:FireServer(fruit)
    end)
    if not ok then
        inflight[fruit] = nil
        skipUntil[fruit] = os.clock() + FAIL_SKIP_SEC
        return 0, "fire failed"
    end

    local waitSec = math.max(POST_SUCCESS_WAIT, clampDelay(AUTO_SHOVEL_FRUIT_DELAY_SEC))
    local gone = false
    while (os.clock() - t0) < waitSec do
        if not fruit.Parent then
            gone = true
        end
        task.wait(VERIFY_STEP)
    end
    if not fruit.Parent then
        gone = true
    end
    inflight[fruit] = nil
    if gone then
        DONE_COUNT += 1
        G.__AUTO_SHOVEL_FRUIT_DONE = DONE_COUNT
        _G.__AUTO_SHOVEL_FRUIT_DONE = DONE_COUNT
        return 1, ("removed · left ~%d · ~%.2fs/ea"):format(
            math.max(0, LAST_ELIGIBLE - 1),
            waitSec
        )
    end
    skipUntil[fruit] = os.clock() + FAIL_SKIP_SEC
    return 0, "skipped"
end

function M.ShovelFruit(fruit)
    if not fruit or not fruit.Parent then
        return "none"
    end
    if not resolveRemote() then
        return "no Remove_Item"
    end
    if isReadOnlySlot() then
        return "read-only slot"
    end
    if not findShovelTool() then
        return "no shovel"
    end
    if not ensureShovelEquipped() then
        return "equip failed"
    end
    inflight[fruit] = os.clock()
    local t0 = os.clock()
    local ok = pcall(function()
        RemoveItemRE:FireServer(fruit)
    end)
    if not ok then
        inflight[fruit] = nil
        return "fire failed"
    end
    local waitSec = math.max(POST_SUCCESS_WAIT, clampDelay(AUTO_SHOVEL_FRUIT_DELAY_SEC))
    local gone = false
    while (os.clock() - t0) < waitSec do
        if not fruit.Parent then
            gone = true
        end
        task.wait(VERIFY_STEP)
    end
    if not fruit.Parent then
        gone = true
    end
    inflight[fruit] = nil
    unequipShovelIfHeld()
    if gone then
        return "removed"
    end
    return "skipped"
end

function M.GetStatusText()
    syncGlobalsFromState()
    local on = AUTO_SHOVEL_FRUIT_ENABLED == true and "ON" or "OFF"
    local hasShovel = findShovelTool() ~= nil
    local lines = {}
    lines[#lines + 1] = ("Done: %d · eligible %d · shovel %s"):format(
        DONE_COUNT,
        LAST_ELIGIBLE,
        hasShovel and "OK" or "NO"
    )
    lines[#lines + 1] = ("Enable %s · fruit %s · var %s · mut %s"):format(
        on,
        selectedCount(AUTO_SHOVEL_FRUIT_SELECTED) > 0 and tostring(selectedCount(AUTO_SHOVEL_FRUIT_SELECTED)) or "ALL",
        selectedCount(AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED) > 0 and tostring(selectedCount(AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED)) or "ALL",
        selectedCount(AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED) > 0 and tostring(selectedCount(AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED)) or "ALL"
    )
    lines[#lines + 1] = (LAST_STATUS ~= "" and LAST_STATUS or "idle")
    return table.concat(lines, "\n")
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if AUTO_SHOVEL_FRUIT_ENABLED ~= true then
            break
        end

        local n, msg = fireOne()
        if msg then publishStatus(msg) end

        if msg == "no shovel"
            or msg == "equip failed"
            or msg == "no Remove_Item"
            or msg == "read-only slot"
            or msg == "no eligible fruit"
        then
            task.wait(IDLE_WAIT)
        elseif n <= 0 then
            -- skip fruit, coba berikutnya
        else
            -- cooldown sudah di fireOne (POST_SUCCESS_WAIT)
        end
    end

    RUNNING = false
    unequipShovelIfHeld()
    if LAST_STATUS == "running" then
        publishStatus("stopped")
    end
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
end

function M.Start()
    M.SyncFromGlobals()
    if RUNNING then return end
    if AUTO_SHOVEL_FRUIT_ENABLED ~= true then return end
    DONE_COUNT = 0
    G.__AUTO_SHOVEL_FRUIT_DONE = 0
    _G.__AUTO_SHOVEL_FRUIT_DONE = 0
    table.clear(inflight)
    table.clear(skipUntil)
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    unequipShovelIfHeld()
    publishStatus("stopped")
end

function M.SetEnabled(on)
    AUTO_SHOVEL_FRUIT_ENABLED = (on == true)
    G.AUTO_SHOVEL_FRUIT_ENABLED = AUTO_SHOVEL_FRUIT_ENABLED
    _G.AUTO_SHOVEL_FRUIT_ENABLED = AUTO_SHOVEL_FRUIT_ENABLED
    if AUTO_SHOVEL_FRUIT_ENABLED then
        M.Start()
    else
        M.Stop()
    end
end

function M.SetDelay(sec)
    AUTO_SHOVEL_FRUIT_DELAY_SEC = clampDelay(sec)
    G.AUTO_SHOVEL_FRUIT_DELAY_SEC = AUTO_SHOVEL_FRUIT_DELAY_SEC
    _G.AUTO_SHOVEL_FRUIT_DELAY_SEC = AUTO_SHOVEL_FRUIT_DELAY_SEC
end

function M.SetFruits(map)
    AUTO_SHOVEL_FRUIT_SELECTED = cleanSelectedMap(map)
    G.AUTO_SHOVEL_FRUIT_SELECTED = AUTO_SHOVEL_FRUIT_SELECTED
    _G.AUTO_SHOVEL_FRUIT_SELECTED = AUTO_SHOVEL_FRUIT_SELECTED
end

function M.SetVariants(map)
    AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED = cleanSelectedMap(map)
    G.AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED = AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED
    _G.AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED = AUTO_SHOVEL_FRUIT_VARIANTS_SELECTED
end

function M.SetMutations(map)
    AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED = cleanSelectedMap(map)
    G.AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED = AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED
    _G.AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED = AUTO_SHOVEL_FRUIT_MUTATIONS_SELECTED
end

function M.SetKgFilter(kg, mode)
    AUTO_SHOVEL_FRUIT_KG = tonumber(kg) or 0
    mode = tostring(mode or "above")
    if mode ~= "below" then mode = "above" end
    AUTO_SHOVEL_FRUIT_KG_MODE = mode
    G.AUTO_SHOVEL_FRUIT_KG = AUTO_SHOVEL_FRUIT_KG
    G.AUTO_SHOVEL_FRUIT_KG_MODE = AUTO_SHOVEL_FRUIT_KG_MODE
    _G.AUTO_SHOVEL_FRUIT_KG = AUTO_SHOVEL_FRUIT_KG
    _G.AUTO_SHOVEL_FRUIT_KG_MODE = AUTO_SHOVEL_FRUIT_KG_MODE
end

function M.SetRules(a, b)
    local rules = a
    if type(a) == "table" and b ~= nil then
        rules = b
    end
    local CR = G.CollectRules or rawget(_G, "CollectRules")
    local st = getState()
    if type(st) ~= "table" then
        return
    end
    if type(st.rules) == "table" and st.rules == rules then
        if type(CR) == "table" and type(CR.PackInPlace) == "function" then
            CR.PackInPlace(st.rules)
        end
        G.AUTO_SHOVEL_FRUIT_RULES = st.rules
        _G.AUTO_SHOVEL_FRUIT_RULES = st.rules
        return
    end
    if type(CR) == "table" and type(CR.Pack) == "function" then
        rules = CR.Pack(rules)
    elseif type(rules) ~= "table" then
        rules = {}
    end
    G.AUTO_SHOVEL_FRUIT_RULES = rules
    _G.AUTO_SHOVEL_FRUIT_RULES = rules
    if type(st.rules) == "table" and type(CR) == "table" and type(CR.PackInPlace) == "function" then
        local live = st.rules
        for i = 1, #live do
            live[i] = nil
        end
        for i = 1, #rules do
            live[i] = rules[i]
        end
        G.AUTO_SHOVEL_FRUIT_RULES = live
        _G.AUTO_SHOVEL_FRUIT_RULES = live
    else
        st.rules = rules
    end
end

M.setRules = M.SetRules

function M.SetRuleMode(a, b)
    local mode = a
    if type(a) == "table" and b ~= nil then
        mode = b
    end
    local CR = G.CollectRules or rawget(_G, "CollectRules")
    if type(CR) == "table" and type(CR.NormAction) == "function" then
        mode = CR.NormAction(mode)
    else
        mode = tostring(mode or "keep")
    end
    G.AUTO_SHOVEL_FRUIT_RULE_MODE = mode
    _G.AUTO_SHOVEL_FRUIT_RULE_MODE = mode
    local st = getState()
    if type(st) == "table" then
        st.ruleMode = mode
    end
end

M.setRuleMode = M.SetRuleMode

function M.SyncFromState()
    M.SyncFromGlobals()
    if AUTO_SHOVEL_FRUIT_ENABLED == true then
        M.Start()
    else
        M.Stop()
    end
end

G.AutoShovelFruit = M
_G.AutoShovelFruit = M

return M

