            -- Gauto_trowel.lua
-- Auto move plants on own garden via GameEvents.TrowelRemote
-- Dump Trowel_Client:
--   InvokeServer("Pickup", trowelTool, plantModel)
--   InvokeServer("Place",  trowelTool, plantModel, cframe)
--   InvokeServer("Cancel", trowelTool, plantModel)
-- Place = exact 1 saved point (stack all plants on that CFrame)

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local MIN_DELAY = 0
local MAX_DELAY = 300
local DEFAULT_DELAY = 1.0
local DEFAULT_TOTAL = 0 -- 0 = unlimited
local FARM_CACHE_SEC = 5
local EQUIP_WAIT = 0.08
local PICKUP_WAIT = 0.08
local PLACE_WAIT = 0.12
local ON_POINT_RADIUS = 3.5 -- already on the saved point (pivot XZ; ignore fruit offset)

local RUNNING = false
local STOP_TOKEN = 0
local LAST_STATUS = "idle"
local DONE_COUNT = 0
local DONE_PLANTS = setmetatable({}, { __mode = "k" })

local TrowelRemote = nil
local GetFarm = nil
local GetFarmAsync = nil
local StringUtils = nil

pcall(function()
    GetFarm = require(ReplicatedStorage.Modules.GetFarm)
end)
pcall(function()
    GetFarmAsync = require(ReplicatedStorage.Modules.GetFarmAsync)
end)
pcall(function()
    StringUtils = require(ReplicatedStorage.Modules.StringUtils)
end)

----------------------------------------------------------------
-- Globals
----------------------------------------------------------------
AUTO_TROWEL_ENABLED = (AUTO_TROWEL_ENABLED == true)
    or (G.AUTO_TROWEL_ENABLED == true)
    or (_G.AUTO_TROWEL_ENABLED == true)
    or (type(G.MAIN) == "table"
        and type(G.MAIN.misc) == "table"
        and type(G.MAIN.misc.auto_trowel) == "table"
        and G.MAIN.misc.auto_trowel.enabled == true)
AUTO_TROWEL_DELAY_SEC = tonumber(AUTO_TROWEL_DELAY_SEC) or DEFAULT_DELAY
AUTO_TROWEL_TOTAL = math.max(0, math.floor(tonumber(AUTO_TROWEL_TOTAL) or DEFAULT_TOTAL))
AUTO_TROWEL_PLANTS_SELECTED = AUTO_TROWEL_PLANTS_SELECTED or {}
AUTO_TROWEL_POSITION = type(AUTO_TROWEL_POSITION) == "table" and AUTO_TROWEL_POSITION or nil

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_TROWEL_STATUS = LAST_STATUS
    _G.__AUTO_TROWEL_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_trowel
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function cleanSelectedMap(src)
    local out = {}
    if type(src) ~= "table" then return out end
    if #src > 0 then
        for _, k in ipairs(src) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function selectedCount(map)
    local n = 0
    if type(map) ~= "table" then return 0 end
    for _, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            n += 1
        end
    end
    return n
end

local function round1(n)
    return math.floor((tonumber(n) or 0) * 10 + 0.5) / 10
end

local function copyPos(src)
    if type(src) ~= "table" then return nil end
    local rx = tonumber(src.rx)
    local ry = tonumber(src.ry)
    local rz = tonumber(src.rz)
    if rx == nil or ry == nil or rz == nil then
        rx = tonumber(src.x)
        ry = tonumber(src.y)
        rz = tonumber(src.z)
    end
    if rx == nil and type(src.rel) == "table" then
        rx = tonumber(src.rel[1])
        ry = tonumber(src.rel[2])
        rz = tonumber(src.rel[3])
    end
    if rx == nil or ry == nil or rz == nil then return nil end
    local out = { rx = round1(rx), ry = round1(ry), rz = round1(rz) }
    if type(src.rel) == "table" and #src.rel >= 12 then
        out.rel = src.rel
    end
    return out
end

local function persistPositionToMain(pos)
    AUTO_TROWEL_POSITION = copyPos(pos)
    G.AUTO_TROWEL_POSITION = AUTO_TROWEL_POSITION
    _G.AUTO_TROWEL_POSITION = AUTO_TROWEL_POSITION
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.auto_trowel = MAIN.misc.auto_trowel or {}
        MAIN.misc.auto_trowel.position = AUTO_TROWEL_POSITION
    end
end

local function publishPosition(pos)
    persistPositionToMain(pos)
end

local function syncGlobalsFromState()
    local st = getState()

    if G.AUTO_TROWEL_ENABLED == true
        or _G.AUTO_TROWEL_ENABLED == true
        or AUTO_TROWEL_ENABLED == true
        or (st.enabled == true)
    then
        AUTO_TROWEL_ENABLED = true
    else
        AUTO_TROWEL_ENABLED = false
    end

    local delaySrc = G.AUTO_TROWEL_DELAY_SEC
    if delaySrc == nil then delaySrc = _G.AUTO_TROWEL_DELAY_SEC end
    if delaySrc == nil then delaySrc = AUTO_TROWEL_DELAY_SEC end
    if delaySrc == nil then delaySrc = st.delaySec end
    AUTO_TROWEL_DELAY_SEC = clampDelay(delaySrc)

    local totalSrc = G.AUTO_TROWEL_TOTAL
    if totalSrc == nil then totalSrc = _G.AUTO_TROWEL_TOTAL end
    if totalSrc == nil then totalSrc = AUTO_TROWEL_TOTAL end
    if totalSrc == nil then totalSrc = st.total end
    AUTO_TROWEL_TOTAL = math.max(0, math.floor(tonumber(totalSrc) or DEFAULT_TOTAL))

    local plants = G.AUTO_TROWEL_PLANTS_SELECTED
    if type(plants) ~= "table" then plants = _G.AUTO_TROWEL_PLANTS_SELECTED end
    if type(plants) ~= "table" then plants = AUTO_TROWEL_PLANTS_SELECTED end
    if type(plants) ~= "table" then plants = st.plants end
    AUTO_TROWEL_PLANTS_SELECTED = cleanSelectedMap(plants)

    local pos = copyPos(G.AUTO_TROWEL_POSITION)
        or copyPos(_G.AUTO_TROWEL_POSITION)
        or copyPos(AUTO_TROWEL_POSITION)
        or copyPos(st.position)
    AUTO_TROWEL_POSITION = pos

    G.AUTO_TROWEL_ENABLED = AUTO_TROWEL_ENABLED
    G.AUTO_TROWEL_DELAY_SEC = AUTO_TROWEL_DELAY_SEC
    G.AUTO_TROWEL_TOTAL = AUTO_TROWEL_TOTAL
    G.AUTO_TROWEL_PLANTS_SELECTED = AUTO_TROWEL_PLANTS_SELECTED
    G.AUTO_TROWEL_POSITION = AUTO_TROWEL_POSITION
    _G.AUTO_TROWEL_ENABLED = AUTO_TROWEL_ENABLED
    _G.AUTO_TROWEL_DELAY_SEC = AUTO_TROWEL_DELAY_SEC
    _G.AUTO_TROWEL_TOTAL = AUTO_TROWEL_TOTAL
    _G.AUTO_TROWEL_PLANTS_SELECTED = AUTO_TROWEL_PLANTS_SELECTED
    _G.AUTO_TROWEL_POSITION = AUTO_TROWEL_POSITION
end

----------------------------------------------------------------
-- Farm / trowel tool
----------------------------------------------------------------
local cachedFarm, cachedFarmAt = nil, 0

local function getOwnFarm()
    local now = os.clock()
    if cachedFarm and cachedFarm.Parent and (now - cachedFarmAt) <= FARM_CACHE_SEC then
        return cachedFarm
    end
    cachedFarm = nil
    cachedFarmAt = now

    if type(GetFarmAsync) == "function" then
        local ok, farm = pcall(GetFarmAsync, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end
    if type(GetFarm) == "function" then
        local ok, farm = pcall(GetFarm, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end

    local farms = workspace:FindFirstChild("Farm")
    if not farms then return nil end
    local username = LP and LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local ok, owner = pcall(function()
            return farm.Important.Data.Owner.Value
        end)
        if ok and owner == username then
            cachedFarm = farm
            return farm
        end
    end
    return nil
end

local function getFarmCF(farm)
    if not farm then return nil end
    if farm:IsA("Model") then
        local ok, pivot = pcall(function() return farm:GetPivot() end)
        if ok and pivot then return pivot end
    end
    local preferred = {
        "Center_Point", "CenterPoint", "Spawn_Point", "SpawnPoint",
        "FarmSpawn", "Base", "Baseplate", "Ground",
    }
    for _, name in ipairs(preferred) do
        local obj = farm:FindFirstChild(name, true)
        if obj and obj:IsA("BasePart") then
            return obj.CFrame
        end
    end
    local pp = farm.PrimaryPart or farm:FindFirstChildWhichIsA("BasePart", true)
    if pp then return pp.CFrame end
    return nil
end

local function cfToTable(cf)
    local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
    return { x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 }
end

local function tableToCF(t)
    if type(t) ~= "table" or #t < 12 then return nil end
    return CFrame.new(table.unpack(t))
end

local function getPlantsFolder(farm)
    farm = farm or getOwnFarm()
    if not farm then return nil end
    local important = farm:FindFirstChild("Important")
    if important then
        local folder = important:FindFirstChild("Plants_Physical")
        if folder then return folder end
    end
    return farm:FindFirstChild("Plants_Physical", true)
end

local function getCanPlantParts(farm)
    local out = {}
    farm = farm or getOwnFarm()
    if not farm then return out end
    local important = farm:FindFirstChild("Important")
    local plantLocs = important and important:FindFirstChild("Plant_Locations")
    if plantLocs then
        for _, part in ipairs(plantLocs:GetChildren()) do
            if part:IsA("BasePart") and part.Name == "Can_Plant" then
                out[#out + 1] = part
            end
        end
    end
    if #out > 0 then return out end
    for _, desc in ipairs(farm:GetDescendants()) do
        if desc:IsA("BasePart") and desc.Name == "Can_Plant" then
            out[#out + 1] = desc
        end
    end
    return out
end

local function isTrowelTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    return tostring(tool.Name or ""):lower():find("trowel", 1, true) ~= nil
end

local function scanTrowel(container)
    if not container then return nil end
    for _, tool in ipairs(container:GetChildren()) do
        if isTrowelTool(tool) then
            return tool
        end
    end
    return nil
end

local function findTrowelTool()
    local char = LP.Character
    local held = char and char:FindFirstChildOfClass("Tool")
    if isTrowelTool(held) then return held end
    return scanTrowel(char) or scanTrowel(LP:FindFirstChild("Backpack"))
end

local function getEquippedTrowel()
    local char = LP.Character
    if not char then return nil end
    local held = char:FindFirstChildOfClass("Tool")
    if isTrowelTool(held) then return held end
    return nil
end

local function unequipTrowel()
    if not getEquippedTrowel() then
        return
    end
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end
    local bag = LP:FindFirstChild("Backpack")
    if not (char and bag) then
        return
    end
    for _, inst in ipairs(char:GetChildren()) do
        if isTrowelTool(inst) then
            pcall(function()
                inst.Parent = bag
            end)
        end
    end
end

local function unequipOtherTools(keep)
    local char = LP.Character
    local bag = LP:FindFirstChild("Backpack")
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum:UnequipTools() end)
    end
    if not bag then return end
    for _, inst in ipairs(char:GetChildren()) do
        if inst:IsA("Tool") and inst ~= keep then
            pcall(function()
                inst.Parent = bag
            end)
        end
    end
end

local function ensureTrowelEquipped()
    local equipped = getEquippedTrowel()
    if equipped then return equipped end

    local tool = findTrowelTool()
    if not tool then return nil end

    local char = LP.Character
    if not char then return nil end
    local bag = LP:FindFirstChild("Backpack")
    if tool.Parent ~= char and tool.Parent ~= bag then
        return nil
    end

    if tool.Parent == char then
        unequipOtherTools(tool)
        task.wait(0.05)
        equipped = getEquippedTrowel()
        if equipped then return equipped end
        if bag then
            pcall(function()
                tool.Parent = bag
            end)
            task.wait(0.05)
        end
    end

    unequipOtherTools(tool)
    task.wait(0.08)

    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum:EquipTool(tool) end)
        task.wait(EQUIP_WAIT)
    end

    equipped = getEquippedTrowel()
    if equipped then return equipped end

    pcall(function()
        tool.Parent = char
    end)
    task.wait(EQUIP_WAIT)

    return getEquippedTrowel() or (tool.Parent == char and tool) or nil
end

local function resolveRemote()
    if TrowelRemote and TrowelRemote.Parent then return true end
    local ge = ReplicatedStorage:FindFirstChild("GameEvents")
    if not ge then return false end
    TrowelRemote = ge:FindFirstChild("TrowelRemote")
    return TrowelRemote ~= nil
end

----------------------------------------------------------------
-- Names / eligibility
----------------------------------------------------------------
local function cleanPlantName(plant)
    local raw = tostring(plant and plant.Name or "")
    if StringUtils and type(StringUtils.StipFlavourText) == "function" then
        local ok, cleaned = pcall(function()
            return StringUtils:StipFlavourText(raw)
        end)
        if ok and type(cleaned) == "string" and cleaned ~= "" then
            return cleaned
        end
    end
    return raw:gsub("%s*%[.-%]$", ""):gsub("%s*%(%d+%)$", "")
end

local function plantAllowedByFilter(name)
    local sel = AUTO_TROWEL_PLANTS_SELECTED
    if selectedCount(sel) <= 0 then
        return true
    end
    if sel[name] == true then return true end
    local low = tostring(name or ""):lower()
    for k, v in pairs(sel) do
        if (v == true or v == 1) and tostring(k):lower() == low then
            return true
        end
    end
    return false
end

local function isGrowablePlant(plant)
    if not plant then return false end
    if plant:FindFirstChild("Grow") then return true end
    local tagged = false
    pcall(function()
        tagged = CollectionService:HasTag(plant, "Growable") == true
    end)
    if tagged then return true end
    pcall(function()
        tagged = plant:HasTag("Growable") == true
    end)
    return tagged
end

local function plantGroundPos(plant)
    if not plant then return nil end
    -- Pivot = posisi trowel Place. Jangan pakai descendant (buah/optimizer
    -- sisa part) — itu offset dari batang jadi kira belum pindah.
    if plant:IsA("Model") then
        local ok, pivot = pcall(function() return plant:GetPivot() end)
        if ok and pivot then return pivot.Position end
        if plant.PrimaryPart then return plant.PrimaryPart.Position end
    end
    if plant:IsA("BasePart") then
        return plant.Position
    end
    local part = plant:FindFirstChildWhichIsA("BasePart", false)
    if part then return part.Position end
    return nil
end

local function plantPivot(plant)
    if not plant then return nil end
    if plant:IsA("Model") then
        local ok, cf = pcall(function() return plant:GetPivot() end)
        if ok then return cf end
    end
    if plant:IsA("BasePart") then
        return plant.CFrame
    end
    return nil
end

local function horizDist(a, b)
    if not a or not b then return 1e9 end
    local dx = a.X - b.X
    local dz = a.Z - b.Z
    return math.sqrt(dx * dx + dz * dz)
end

local function snapToCanPlant(worldPos, parts)
    if not worldPos or type(parts) ~= "table" or #parts == 0 then
        return worldPos
    end
    local best, bestD = nil, 1e12
    for _, part in ipairs(parts) do
        if part and part.Parent then
            local localPos = part.CFrame:PointToObjectSpace(worldPos)
            local half = part.Size * 0.45
            local x = math.clamp(localPos.X, -half.X, half.X)
            local z = math.clamp(localPos.Z, -half.Z, half.Z)
            local y = part.Size.Y * 0.5 + 0.05
            local snapped = part.CFrame:PointToWorldSpace(Vector3.new(x, y, z))
            local d = horizDist(worldPos, snapped)
            if d < bestD then
                bestD = d
                best = snapped
            end
        end
    end
    return best or worldPos
end

----------------------------------------------------------------
-- Saved 1-point position
----------------------------------------------------------------
local function resolveSavedWorldPos(farm)
    local pos = copyPos(AUTO_TROWEL_POSITION)
    if not pos then return nil end
    local farmCF = getFarmCF(farm)
    if farmCF then
        local relCF = tableToCF(pos.rel)
        if relCF then
            return farmCF:ToWorldSpace(relCF).Position
        end
        return farmCF:ToWorldSpace(CFrame.new(pos.rx, pos.ry, pos.rz)).Position
    end
    return Vector3.new(pos.rx, pos.ry, pos.rz)
end

-- Same as Auto Plant: save character CFrame relative to farm (no Can_Plant raycast).
function M.SaveCurrentPosition()
    local farm = getOwnFarm()
    if not farm then
        publishStatus("save fail: no farm")
        return false, "no farm"
    end
    local farmCF = getFarmCF(farm)
    if not farmCF then
        publishStatus("save fail: no farm cf")
        return false, "no farm cf"
    end
    local char = LP.Character
    local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso"))
    if not hrp then
        publishStatus("save fail: no hrp")
        return false, "no hrp"
    end

    local relCF = farmCF:ToObjectSpace(hrp.CFrame)
    local relPos = relCF.Position
    local world = hrp.Position

    publishPosition({
        rx = round1(relPos.X),
        ry = round1(relPos.Y),
        rz = round1(relPos.Z),
        rel = cfToTable(relCF),
    })
    publishStatus(("saved %.0f, %.0f"):format(world.X, world.Z))
    if AUTO_TROWEL_ENABLED == true or G.AUTO_TROWEL_ENABLED == true then
        AUTO_TROWEL_ENABLED = true
        G.AUTO_TROWEL_ENABLED = true
        _G.AUTO_TROWEL_ENABLED = true
        STOP_TOKEN += 1
        RUNNING = false
        M.Start()
    end
    return true
end

function M.SaveStandingPosition()
    return M.SaveCurrentPosition()
end

function M.ClearPosition()
    persistPositionToMain(nil)
    AUTO_TROWEL_POSITION = nil
    G.AUTO_TROWEL_POSITION = nil
    _G.AUTO_TROWEL_POSITION = nil
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) == "table" and type(MAIN.misc) == "table" and type(MAIN.misc.auto_trowel) == "table" then
        MAIN.misc.auto_trowel.position = nil
    end
    return true
end

local function pickPlacePos(farm)
    local anchor = resolveSavedWorldPos(farm)
    if not anchor then return nil end
    local parts = getCanPlantParts(farm)
    if #parts > 0 then
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Include
        params.FilterDescendantsInstances = parts
        local hit = workspace:Raycast(
            Vector3.new(anchor.X, anchor.Y + 40, anchor.Z),
            Vector3.new(0, -160, 0),
            params
        )
        if hit and hit.Position then
            return Vector3.new(anchor.X, hit.Position.Y, anchor.Z)
        end
        local snapped = snapToCanPlant(anchor, parts)
        if snapped then
            return Vector3.new(anchor.X, snapped.Y, anchor.Z)
        end
    end
    return anchor
end

----------------------------------------------------------------
-- Garden list
----------------------------------------------------------------
local function isEligible(plant, plantsFolder, targetPos)
    if not plant or not plant.Parent then return false, "gone" end
    if plantsFolder and not plant:IsDescendantOf(plantsFolder) then
        return false, "not own"
    end
    if plant.Parent and plant.Parent.Name == "Fruits" then
        return false, "fruit"
    end
    if not isGrowablePlant(plant) then
        return false, "not growable"
    end
    local name = cleanPlantName(plant)
    if name == "" then return false, "no name" end
    if not plantAllowedByFilter(name) then
        return false, "filter"
    end
    if DONE_PLANTS[plant] then
        return false, "already moved"
    end
    if targetPos then
        local p = plantGroundPos(plant)
        if p and horizDist(p, targetPos) <= ON_POINT_RADIUS then
            return false, "already there"
        end
    end
    return true, name
end

local _gardenListCache, _gardenListAt = nil, 0
local GARDEN_LIST_CACHE_SEC = 2.5

local function listGardenPlantItemsLive()
    local now = os.clock()
    if _gardenListCache and (now - _gardenListAt) <= GARDEN_LIST_CACHE_SEC then
        return _gardenListCache
    end

    local folder = getPlantsFolder()
    local counts = {}
    if folder then
        for _, plant in ipairs(folder:GetChildren()) do
            if isGrowablePlant(plant) and (not plant.Parent or plant.Parent.Name ~= "Fruits") then
                local name = cleanPlantName(plant)
                if name ~= "" then
                    counts[name] = (counts[name] or 0) + 1
                end
            end
        end
    end

    local list = {}
    for name, n in pairs(counts) do
        list[#list + 1] = {
            key = name,
            name = string.format("%s x%d", name, n),
            right = tostring(n),
        }
    end
    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    _gardenListCache = list
    _gardenListAt = now
    return list
end

function M.ListGardenPlantItems()
    syncGlobalsFromState()
    local live = listGardenPlantItemsLive()
    local seen = {}
    local list = {}
    for _, item in ipairs(live) do
        local key = tostring(item.key)
        seen[key] = true
        list[#list + 1] = {
            key = key,
            name = item.name,
            right = item.right,
        }
    end
    for k, v in pairs(AUTO_TROWEL_PLANTS_SELECTED or {}) do
        if v == true or v == 1 or v == "true" then
            local key = tostring(k)
            if key ~= "" and not seen[key] then
                seen[key] = true
                list[#list + 1] = {
                    key = key,
                    name = string.format("%s x0", key),
                    right = "0",
                }
            end
        end
    end
    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    return list
end

local function listEligible()
    local farm = getOwnFarm()
    local folder = getPlantsFolder(farm)
    if not folder then return {} end
    local targetPos = resolveSavedWorldPos(farm)
    local out = {}
    for _, plant in ipairs(folder:GetChildren()) do
        local ok, nameOrReason = isEligible(plant, folder, targetPos)
        if ok then
            local pos = plantGroundPos(plant)
            local dist = (targetPos and pos) and horizDist(pos, targetPos) or 0
            out[#out + 1] = { plant = plant, name = nameOrReason, dist = dist }
        end
    end
    table.sort(out, function(a, b)
        return (a.dist or 0) > (b.dist or 0)
    end)
    return out
end

local _eligCacheN, _eligCacheAt = 0, 0
local function eligibleCountCached()
    local now = os.clock()
    if (now - _eligCacheAt) <= 1.0 then
        return _eligCacheN
    end
    _eligCacheN = #listEligible()
    _eligCacheAt = now
    return _eligCacheN
end

----------------------------------------------------------------
-- Actions
----------------------------------------------------------------
local function invokeTrowel(action, tool, plant, placeCF)
    if not resolveRemote() then return false, "no TrowelRemote" end
    if not tool or not plant then return false, "missing args" end
    local ok, err = pcall(function()
        if placeCF then
            TrowelRemote:InvokeServer(action, tool, plant, placeCF)
        else
            TrowelRemote:InvokeServer(action, tool, plant)
        end
    end)
    if not ok then
        return false, tostring(err or "invoke failed")
    end
    return true
end

local function wantRun()
    return AUTO_TROWEL_ENABLED == true
end

local function tryOne()
    if AUTO_TROWEL_TOTAL > 0 and DONE_COUNT >= AUTO_TROWEL_TOTAL then
        return false, ("done %d/%d"):format(DONE_COUNT, AUTO_TROWEL_TOTAL)
    end

    local farm = getOwnFarm()
    if not farm then return false, "no farm" end
    if not resolveSavedWorldPos(farm) then
        return false, "no saved position"
    end

    local list = listEligible()
    if #list == 0 then
        unequipTrowel()
        return false, "no eligible plant"
    end

    if not findTrowelTool() then return false, "no trowel" end
    local tool = ensureTrowelEquipped()
    if not tool then return false, "equip failed" end
    if not isTrowelTool(tool) or tool.Parent ~= LP.Character then
        return false, "equip failed"
    end

    local target = list[1]
    local plant = target.plant
    local name = target.name
    local orig = plantPivot(plant)
    if not orig then return false, "no pivot" end

    local placePos = pickPlacePos(farm)
    if not placePos then
        return false, "no saved position"
    end

    local rot = orig - orig.Position
    local placeCF = CFrame.new(placePos.X, orig.Position.Y, placePos.Z) * rot

    publishStatus(("pickup %s"):format(name))
    local okPick = invokeTrowel("Pickup", tool, plant)
    if not okPick then
        return false, "pickup failed"
    end
    task.wait(PICKUP_WAIT)

    if not plant.Parent then
        return false, "plant gone"
    end

    publishStatus(("place %s"):format(name))
    local okPlace = invokeTrowel("Place", tool, plant, placeCF)
    if not okPlace then
        pcall(function()
            invokeTrowel("Cancel", tool, plant)
        end)
        return false, "place failed"
    end

    task.wait(PLACE_WAIT)
    DONE_PLANTS[plant] = true
    _eligCacheAt = 0
    DONE_COUNT += 1
    G.__AUTO_TROWEL_DONE = DONE_COUNT
    _G.__AUTO_TROWEL_DONE = DONE_COUNT
    return true, ("moved %s (%d)"):format(name, DONE_COUNT)
end

----------------------------------------------------------------
-- Status / loop / API
----------------------------------------------------------------
function M.GetStatusText()
    syncGlobalsFromState()
    local farm = getOwnFarm()
    local world = resolveSavedWorldPos(farm)
    local eligible = eligibleCountCached()
    local total = AUTO_TROWEL_TOTAL
    local on = (AUTO_TROWEL_ENABLED == true and "ON") or "OFF"
    local filterN = selectedCount(AUTO_TROWEL_PLANTS_SELECTED)
    local trowelTxt = "NO"
    if getEquippedTrowel() then
        trowelTxt = "EQ"
    elseif findTrowelTool() then
        trowelTxt = "BAG"
    end
    local posTxt = "NONE"
    if world then
        posTxt = string.format("%.0f, %.0f", world.X, world.Z)
    elseif AUTO_TROWEL_POSITION then
        posTxt = string.format("%.0f, %.0f", AUTO_TROWEL_POSITION.rx, AUTO_TROWEL_POSITION.rz)
    end

    local lines = {}
    lines[#lines + 1] = ("Done: %d / %s · eligible %d · trowel %s"):format(
        DONE_COUNT,
        total > 0 and tostring(total) or "all",
        eligible,
        trowelTxt
    )
    lines[#lines + 1] = ("Enable %s · %s · filter %s · pos %s"):format(
        on,
        RUNNING and "moving" or "idle",
        filterN > 0 and tostring(filterN) or "ALL",
        posTxt
    )
    lines[#lines + 1] = (LAST_STATUS ~= "" and LAST_STATUS or "idle")
    return table.concat(lines, "\n")
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if not wantRun() then
            break
        end

        local callOk, ok, msg = pcall(tryOne)
        if not callOk then
            publishStatus("err: " .. tostring(ok):sub(1, 80))
            task.wait(0.25)
        else
            if type(msg) == "string" and msg ~= "" then
                publishStatus(msg)
            end
            if ok ~= true then
                unequipTrowel()
                if msg == "no eligible plant" then
                    publishStatus("wait plants")
                end
            end
            local d = clampDelay(AUTO_TROWEL_DELAY_SEC)
            if d > 0 then
                task.wait(d)
            else
                task.wait()
            end
        end
    end

    RUNNING = false
    unequipTrowel()
    if LAST_STATUS == "running" then
        publishStatus("stopped")
    end
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
end

function M.Start()
    M.SyncFromGlobals()
    if RUNNING then return end
    if not wantRun() then return end
    DONE_COUNT = 0
    DONE_PLANTS = setmetatable({}, { __mode = "k" })
    G.__AUTO_TROWEL_DONE = 0
    _G.__AUTO_TROWEL_DONE = 0
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    unequipTrowel()
    publishStatus("stopped")
end

function M.SetEnabled(on)
    AUTO_TROWEL_ENABLED = (on == true)
    G.AUTO_TROWEL_ENABLED = AUTO_TROWEL_ENABLED
    _G.AUTO_TROWEL_ENABLED = AUTO_TROWEL_ENABLED
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.auto_trowel = MAIN.misc.auto_trowel or {}
        MAIN.misc.auto_trowel.enabled = AUTO_TROWEL_ENABLED
    end
    if AUTO_TROWEL_ENABLED then
        M.Start()
    else
        M.Stop()
    end
end

function M.SetDelay(sec)
    AUTO_TROWEL_DELAY_SEC = clampDelay(sec)
    G.AUTO_TROWEL_DELAY_SEC = AUTO_TROWEL_DELAY_SEC
    _G.AUTO_TROWEL_DELAY_SEC = AUTO_TROWEL_DELAY_SEC
end

function M.SetTotal(n)
    AUTO_TROWEL_TOTAL = math.max(0, math.floor(tonumber(n) or DEFAULT_TOTAL))
    G.AUTO_TROWEL_TOTAL = AUTO_TROWEL_TOTAL
    _G.AUTO_TROWEL_TOTAL = AUTO_TROWEL_TOTAL
end

function M.SetPlants(map)
    AUTO_TROWEL_PLANTS_SELECTED = cleanSelectedMap(map)
    G.AUTO_TROWEL_PLANTS_SELECTED = AUTO_TROWEL_PLANTS_SELECTED
    _G.AUTO_TROWEL_PLANTS_SELECTED = AUTO_TROWEL_PLANTS_SELECTED
end

function M.SyncFromState()
    M.SyncFromGlobals()
    if wantRun() then
        M.Start()
    else
        M.Stop()
    end
end

G.AutoTrowel = M
_G.AutoTrowel = M

return M

        end,
        required = false,
    },
    {
        key = "AutoWatering",
        name = "Auto Watering",
        factory = function()
            -- Gauto_watering.lua
-- Water own garden plants via GameEvents.Water_RE / TrySuperWateringCan
-- No age / growing check — water selected plants (empty = all)

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local MIN_DELAY = 0
local MAX_DELAY = 300
local DEFAULT_DELAY = 8
local FARM_CACHE_SEC = 5

local KNOWN_CANS = {
    { key = "Watering Can", name = "Watering Can" },
    { key = "Sugar Watering Can", name = "Sugar Watering Can" },
    { key = "Super Watering Can", name = "Super Watering Can" },
}

local RUNNING = false
local STOP_TOKEN = 0
local LAST_STATUS = "idle"
local plantCursor = 1
local WaterRE, SuperWaterRE
local GetFarm, GetFarmAsync, StringUtils
local cachedFarm, cachedFarmAt = nil, 0

pcall(function()
    GetFarm = require(ReplicatedStorage.Modules.GetFarm)
end)
pcall(function()
    GetFarmAsync = require(ReplicatedStorage.Modules.GetFarmAsync)
end)
pcall(function()
    StringUtils = require(ReplicatedStorage.Modules.StringUtils)
end)

AUTO_WATERING_ENABLED = (AUTO_WATERING_ENABLED == true)
    or (G.AUTO_WATERING_ENABLED == true)
    or (_G.AUTO_WATERING_ENABLED == true)
    or (type(G.MAIN) == "table"
        and type(G.MAIN.misc) == "table"
        and type(G.MAIN.misc.auto_watering) == "table"
        and G.MAIN.misc.auto_watering.enabled == true)
AUTO_WATERING_DELAY_SEC = tonumber(AUTO_WATERING_DELAY_SEC) or DEFAULT_DELAY
AUTO_WATERING_PLANTS_SELECTED = AUTO_WATERING_PLANTS_SELECTED or {}
AUTO_WATERING_CANS_SELECTED = AUTO_WATERING_CANS_SELECTED or {}

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_WATERING_STATUS = LAST_STATUS
    _G.__AUTO_WATERING_STATUS = LAST_STATUS
end

function M.GetStatus()
    return LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_watering
    return type(st) == "table" and st or {}
end

local function clampDelay(v)
    local n = tonumber(v) or DEFAULT_DELAY
    if n < MIN_DELAY then n = MIN_DELAY end
    if n > MAX_DELAY then n = MAX_DELAY end
    return n
end

local function cleanSelectedMap(src)
    local out = {}
    if type(src) ~= "table" then return out end
    if #src > 0 then
        for _, k in ipairs(src) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function selectedCount(map)
    local n = 0
    if type(map) ~= "table" then return 0 end
    for _, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            n += 1
        end
    end
    return n
end

local function syncGlobalsFromState()
    local st = getState()
    if G.AUTO_WATERING_ENABLED == true
        or _G.AUTO_WATERING_ENABLED == true
        or AUTO_WATERING_ENABLED == true
        or (st.enabled == true)
    then
        AUTO_WATERING_ENABLED = true
    else
        AUTO_WATERING_ENABLED = false
    end

    local delaySrc = G.AUTO_WATERING_DELAY_SEC
    if delaySrc == nil then delaySrc = _G.AUTO_WATERING_DELAY_SEC end
    if delaySrc == nil then delaySrc = AUTO_WATERING_DELAY_SEC end
    if delaySrc == nil then delaySrc = st.delaySec end
    AUTO_WATERING_DELAY_SEC = clampDelay(delaySrc)

    local plants = G.AUTO_WATERING_PLANTS_SELECTED
    if type(plants) ~= "table" then plants = _G.AUTO_WATERING_PLANTS_SELECTED end
    if type(plants) ~= "table" then plants = AUTO_WATERING_PLANTS_SELECTED end
    if type(plants) ~= "table" then plants = st.plants end
    AUTO_WATERING_PLANTS_SELECTED = cleanSelectedMap(plants)

    local cans = G.AUTO_WATERING_CANS_SELECTED
    if type(cans) ~= "table" then cans = _G.AUTO_WATERING_CANS_SELECTED end
    if type(cans) ~= "table" then cans = AUTO_WATERING_CANS_SELECTED end
    if type(cans) ~= "table" then cans = st.cans end
    AUTO_WATERING_CANS_SELECTED = cleanSelectedMap(cans)

    G.AUTO_WATERING_ENABLED = AUTO_WATERING_ENABLED
    G.AUTO_WATERING_DELAY_SEC = AUTO_WATERING_DELAY_SEC
    G.AUTO_WATERING_PLANTS_SELECTED = AUTO_WATERING_PLANTS_SELECTED
    G.AUTO_WATERING_CANS_SELECTED = AUTO_WATERING_CANS_SELECTED
    _G.AUTO_WATERING_ENABLED = AUTO_WATERING_ENABLED
    _G.AUTO_WATERING_DELAY_SEC = AUTO_WATERING_DELAY_SEC
    _G.AUTO_WATERING_PLANTS_SELECTED = AUTO_WATERING_PLANTS_SELECTED
    _G.AUTO_WATERING_CANS_SELECTED = AUTO_WATERING_CANS_SELECTED
end

local function getOwnFarm()
    local now = os.clock()
    if cachedFarm and cachedFarm.Parent and (now - cachedFarmAt) <= FARM_CACHE_SEC then
        return cachedFarm
    end
    cachedFarm = nil
    cachedFarmAt = now
    if type(GetFarmAsync) == "function" then
        local ok, farm = pcall(GetFarmAsync, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end
    if type(GetFarm) == "function" then
        local ok, farm = pcall(GetFarm, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end
    local farms = workspace:FindFirstChild("Farm")
    if not farms then return nil end
    local username = LP and LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local ok, owner = pcall(function()
            return farm.Important.Data.Owner.Value
        end)
        if ok and owner == username then
            cachedFarm = farm
            return farm
        end
    end
    return nil
end

local function getPlantsFolder(farm)
    farm = farm or getOwnFarm()
    if not farm then return nil end
    local important = farm:FindFirstChild("Important")
    if important then
        local folder = important:FindFirstChild("Plants_Physical")
        if folder then return folder end
    end
    return farm:FindFirstChild("Plants_Physical", true)
end

local function cleanName(s)
    local n = tostring(s or "")
    n = n:gsub("%b[]", " "):gsub("%b()", " ")
    n = n:gsub("[%d%.]+%s*[kK][gG]", " ")
    n = n:gsub("%s+[Ss]eed%s*$", "")
    return n:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
end

local function cleanPlantName(plant)
    local raw = tostring(plant and (plant:GetAttribute("ItemName") or plant.Name) or "")
    if StringUtils and type(StringUtils.StipFlavourText) == "function" then
        local ok, cleaned = pcall(function()
            return StringUtils:StipFlavourText(raw)
        end)
        if ok and type(cleaned) == "string" and cleaned ~= "" then
            return cleaned
        end
    end
    return cleanName(raw)
end

local function isGrowablePlant(plant)
    if not plant then return false end
    if plant:FindFirstChild("Grow") then return true end
    local tagged = false
    pcall(function()
        tagged = CollectionService:HasTag(plant, "Growable") == true
    end)
    if tagged then return true end
    pcall(function()
        tagged = plant:HasTag("Growable") == true
    end)
    return tagged
end

local function plantAllowed(name)
    local sel = AUTO_WATERING_PLANTS_SELECTED
    if selectedCount(sel) <= 0 then
        return true
    end
    if sel[name] == true then return true end
    local low = tostring(name or ""):lower()
    for k, v in pairs(sel) do
        if (v == true or v == 1) and tostring(k):lower() == low then
            return true
        end
    end
    return false
end

local function worldPos(inst)
    if not inst then return nil end
    if inst:IsA("BasePart") then
        return inst.Position
    end
    if inst:IsA("Model") then
        local ok, pivot = pcall(function()
            return inst:GetPivot().Position
        end)
        if ok then return pivot end
        if inst.PrimaryPart then
            return inst.PrimaryPart.Position
        end
    end
    local part = inst:FindFirstChildWhichIsA("BasePart", true)
    return part and part.Position or nil
end

local function waterHitPos(farm, plant)
    local pos = worldPos(plant)
    if not pos then return nil end
    local important = farm and farm:FindFirstChild("Important")
    local locs = important and important:FindFirstChild("Plant_Locations")
    if not locs then
        return pos
    end
    local bestPad, bestLocal
    local bestD = 1e9
    for _, pad in ipairs(locs:GetDescendants()) do
        if pad:IsA("BasePart") and (pad.Name == "Can_Plant" or pad.Name == "CanPlant") then
            local lp = pad.CFrame:PointToObjectSpace(pos)
            local hx = pad.Size.X * 0.5
            local hz = pad.Size.Z * 0.5
            local cx = math.clamp(lp.X, -hx + 0.2, hx - 0.2)
            local cz = math.clamp(lp.Z, -hz + 0.2, hz - 0.2)
            local dx = lp.X - cx
            local dz = lp.Z - cz
            local d = math.sqrt(dx * dx + dz * dz)
            if d < bestD then
                bestD = d
                bestPad = pad
                bestLocal = Vector3.new(cx, 0, cz)
            end
        end
    end
    if bestPad then
        return (bestPad.CFrame * CFrame.new(bestLocal)).Position
    end
    return pos
end

local function getHrp()
    local char = LP and LP.Character
    return char and char:FindFirstChild("HumanoidRootPart")
end

local function distTo(pos)
    local hrp = getHrp()
    if not hrp or not pos then return 1e9 end
    local d = hrp.Position - pos
    return math.sqrt(d.X * d.X + d.Z * d.Z)
end

local function goNear(pos, range)
    local hrp = getHrp()
    if not hrp or not pos then return false end
    range = range or 12
    if distTo(pos) <= range then return true end
    hrp.CFrame = CFrame.new(pos.X, hrp.Position.Y, pos.Z)
    task.wait(0.15)
    return distTo(pos) <= range + 6
end

local function unequipTools()
    local char = LP and LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end
end

local function toolItemName(tool)
    if not tool then return "" end
    return cleanName(
        tool:GetAttribute("ItemName")
            or tool:GetAttribute("ITEM_NAME")
            or tool.Name
    )
end

local function toolUses(tool)
    if not tool then return 0 end
    local n = tool:GetAttribute("e") or tool:GetAttribute("Uses")
    n = tonumber(n)
    if n then return n end
    return 1
end

local function looksWateringCan(tool)
    if not tool or not tool:IsA("Tool") then return false end
    local n = toolItemName(tool):lower()
    return n:find("watering", 1, true) ~= nil or n:find("water can", 1, true) ~= nil
end

local function forEachTool(fn)
    local function scan(container)
        if not container then return end
        for _, t in ipairs(container:GetChildren()) do
            if t:IsA("Tool") then
                fn(t)
            end
        end
    end
    scan(LP and LP:FindFirstChild("Backpack"))
    scan(LP and LP.Character)
end

local function canAllowed(name)
    local sel = AUTO_WATERING_CANS_SELECTED
    if selectedCount(sel) <= 0 then
        return true
    end
    if sel[name] == true then return true end
    local low = tostring(name or ""):lower()
    for k, v in pairs(sel) do
        if (v == true or v == 1) and tostring(k):lower() == low then
            return true
        end
    end
    return false
end

local function findWateringCan()
    local found
    forEachTool(function(tool)
        if found then return end
        if looksWateringCan(tool) and toolUses(tool) >= 1 then
            local n = toolItemName(tool)
            if canAllowed(n) then
                found = tool
            end
        end
    end)
    return found
end

local function equipTool(tool)
    local char = LP and LP.Character
    if not char or not tool then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if tool.Parent == char then return true end
    unequipTools()
    if hum then
        pcall(function()
            hum:EquipTool(tool)
        end)
    else
        tool.Parent = char
    end
    task.wait(0.12)
    return tool.Parent == char
end

local function resolveRemote()
    if WaterRE and WaterRE.Parent then return true end
    local ge = ReplicatedStorage:FindFirstChild("GameEvents")
    if not ge then return false end
    WaterRE = ge:FindFirstChild("Water_RE")
    SuperWaterRE = ge:FindFirstChild("TrySuperWateringCan")
    return WaterRE ~= nil or SuperWaterRE ~= nil
end

local function listTargetPlants()
    local farm = getOwnFarm()
    local folder = getPlantsFolder(farm)
    local out = {}
    if not folder then return out, farm end
    for _, plant in ipairs(folder:GetChildren()) do
        if isGrowablePlant(plant) and (not plant.Parent or plant.Parent.Name ~= "Fruits") then
            local name = cleanPlantName(plant)
            if name ~= "" and plantAllowed(name) then
                out[#out + 1] = plant
            end
        end
    end
    return out, farm
end

function M.ListGardenPlantItems()
    syncGlobalsFromState()
    local folder = getPlantsFolder()
    local counts = {}
    if folder then
        for _, plant in ipairs(folder:GetChildren()) do
            if isGrowablePlant(plant) and (not plant.Parent or plant.Parent.Name ~= "Fruits") then
                local name = cleanPlantName(plant)
                if name ~= "" then
                    counts[name] = (counts[name] or 0) + 1
                end
            end
        end
    end
    local list = {}
    local seen = {}
    for name, n in pairs(counts) do
        seen[name] = true
        list[#list + 1] = {
            key = name,
            name = string.format("%s x%d", name, n),
            right = tostring(n),
        }
    end
    for k, v in pairs(AUTO_WATERING_PLANTS_SELECTED or {}) do
        if (v == true or v == 1) and not seen[tostring(k)] then
            local key = tostring(k)
            list[#list + 1] = { key = key, name = key .. " x0", right = "0" }
        end
    end
    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    return list
end

function M.ListWateringItems()
    syncGlobalsFromState()
    local usesBy = {}
    forEachTool(function(tool)
        if looksWateringCan(tool) then
            local n = toolItemName(tool)
            usesBy[n] = (usesBy[n] or 0) + math.max(0, toolUses(tool))
        end
    end)
    local seen = {}
    local list = {}
    local function add(key)
        if seen[key] then return end
        seen[key] = true
        local uses = usesBy[key]
        list[#list + 1] = {
            key = key,
            name = uses and string.format("%s · %dx", key, uses) or key,
            right = uses and tostring(uses) or nil,
        }
    end
    for i = 1, #KNOWN_CANS do
        add(KNOWN_CANS[i].key)
    end
    for name in pairs(usesBy) do
        add(name)
    end
    for k, v in pairs(AUTO_WATERING_CANS_SELECTED or {}) do
        if v == true or v == 1 then
            add(tostring(k))
        end
    end
    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    return list
end

local function wantRun()
    return AUTO_WATERING_ENABLED == true
end

local function tryOne()
    if not resolveRemote() then
        return false, "no Water_RE"
    end
    local plants, farm = listTargetPlants()
    if #plants == 0 then
        unequipTools()
        return false, "no plants"
    end
    local tool = findWateringCan()
    if not tool then
        unequipTools()
        return false, "no watering can"
    end
    if plantCursor < 1 or plantCursor > #plants then
        plantCursor = 1
    end
    local plant = plants[plantCursor]
    plantCursor = plantCursor + 1
    local name = cleanPlantName(plant)
    local pos = waterHitPos(farm, plant)
    if not pos then
        return false, "no plant pos"
    end
    if not goNear(pos, 12) then
        return false, "far from plant"
    end
    if not equipTool(tool) then
        tool = findWateringCan()
        if not tool or not equipTool(tool) then
            return false, "equip can failed"
        end
    end
    if tool.Parent ~= (LP and LP.Character) then
        unequipTools()
        return false, "can not equipped"
    end
    local useSuper = toolItemName(tool):lower():find("super", 1, true) ~= nil
    local fireOk = pcall(function()
        if useSuper and SuperWaterRE then
            SuperWaterRE:FireServer(pos)
        elseif WaterRE then
            WaterRE:FireServer(pos)
        elseif SuperWaterRE then
            SuperWaterRE:FireServer(pos)
        end
    end)
    if not fireOk then
        unequipTools()
        return false, "water failed"
    end
    task.wait(0.55)
    unequipTools()
    return true, ("watered %s"):format(name)
end

function M.GetStatusText()
    syncGlobalsFromState()
    local plants = select(1, listTargetPlants())
    local can = findWateringCan()
    local on = AUTO_WATERING_ENABLED == true and "ON" or "OFF"
    local filterN = selectedCount(AUTO_WATERING_PLANTS_SELECTED)
    local canN = selectedCount(AUTO_WATERING_CANS_SELECTED)
    local lines = {}
    lines[#lines + 1] = ("plants %d · can %s"):format(#plants, can and "YES" or "NO")
    lines[#lines + 1] = ("Enable %s · %s · plant %s · can %s"):format(
        on,
        RUNNING and "watering" or "idle",
        filterN > 0 and tostring(filterN) or "ALL",
        canN > 0 and tostring(canN) or "ANY"
    )
    lines[#lines + 1] = (LAST_STATUS ~= "" and LAST_STATUS or "idle")
    return table.concat(lines, "\n")
end

local function worker(token)
    publishStatus("running")
    while RUNNING and token == STOP_TOKEN do
        syncGlobalsFromState()
        if not wantRun() then
            break
        end
        local callOk, ok, msg = pcall(tryOne)
        if not callOk then
            publishStatus("err: " .. tostring(ok):sub(1, 80))
            unequipTools()
            task.wait(0.25)
        else
            if type(msg) == "string" and msg ~= "" then
                publishStatus(msg)
            end
            if ok ~= true then
                unequipTools()
                if msg == "no plants" then
                    publishStatus("wait plants")
                end
            end
            local d = clampDelay(AUTO_WATERING_DELAY_SEC)
            if d > 0 then
                task.wait(d)
            else
                task.wait()
            end
        end
    end
    RUNNING = false
    unequipTools()
    if LAST_STATUS == "running" then
        publishStatus("stopped")
    end
end

function M.SyncFromGlobals()
    syncGlobalsFromState()
end

function M.Start()
    M.SyncFromGlobals()
    if RUNNING then return end
    if not wantRun() then return end
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    unequipTools()
    publishStatus("stopped")
end

function M.SetEnabled(on)
    AUTO_WATERING_ENABLED = (on == true)
    G.AUTO_WATERING_ENABLED = AUTO_WATERING_ENABLED
    _G.AUTO_WATERING_ENABLED = AUTO_WATERING_ENABLED
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.auto_watering = MAIN.misc.auto_watering or {}
        MAIN.misc.auto_watering.enabled = AUTO_WATERING_ENABLED
    end
    if AUTO_WATERING_ENABLED then
        M.Start()
    else
        M.Stop()
    end
end

function M.SetDelay(sec)
    AUTO_WATERING_DELAY_SEC = clampDelay(sec)
    G.AUTO_WATERING_DELAY_SEC = AUTO_WATERING_DELAY_SEC
    _G.AUTO_WATERING_DELAY_SEC = AUTO_WATERING_DELAY_SEC
end

function M.SetPlants(map)
    AUTO_WATERING_PLANTS_SELECTED = cleanSelectedMap(map)
    G.AUTO_WATERING_PLANTS_SELECTED = AUTO_WATERING_PLANTS_SELECTED
    _G.AUTO_WATERING_PLANTS_SELECTED = AUTO_WATERING_PLANTS_SELECTED
end

function M.SetCans(map)
    AUTO_WATERING_CANS_SELECTED = cleanSelectedMap(map)
    G.AUTO_WATERING_CANS_SELECTED = AUTO_WATERING_CANS_SELECTED
    _G.AUTO_WATERING_CANS_SELECTED = AUTO_WATERING_CANS_SELECTED
end

function M.SyncFromState()
    M.SyncFromGlobals()
    if wantRun() then
        M.Start()
    else
        M.Stop()
    end
end

G.AutoWatering = M
_G.AutoWatering = M

return M

