    {
        key = "AutoShovelSprinkler",
        name = "Auto Shovel Sprinkler",
        factory = function()
            -- Gauto_shovel_sprinkler.lua
-- Session one-shot: place selected sprinklers up to max per type, then
-- shovel ALL garden sprinklers via DeleteObject (PlaceableObject), then stop.

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local DEFAULT_MAX = 1
local PLACE_WAIT = 0.45
local SHOVEL_WAIT = 0.45
local EQUIP_WAIT = 0.18
local SHOVEL_NAME = "Shovel [Destroy Plants]"

local RUNNING = false
local STOP_TOKEN = 0
local SHOVEL_ALL_RUNNING = false
local SHOVEL_ALL_TOKEN = 0
local LAST_STATUS = "idle"
local PHASE = "idle"
local plantCursor = 1
local GetFarm, GetFarmAsync, StringUtils
local SprinklerService, DeleteObjectRE
local cachedFarm, cachedFarmAt = nil, 0

pcall(function()
    GetFarm = require(ReplicatedStorage.Modules.GetFarm)
end)
pcall(function()
    GetFarmAsync = require(ReplicatedStorage.Modules.GetFarmAsync)
end)
pcall(function()
    StringUtils = require(ReplicatedStorage.Modules.StringUtils)
end)

AUTO_SHOVEL_SPRINKLER_ENABLED = (AUTO_SHOVEL_SPRINKLER_ENABLED == true)
    or (G.AUTO_SHOVEL_SPRINKLER_ENABLED == true)
AUTO_SHOVEL_SPRINKLER_MAX = math.max(0, math.floor(tonumber(AUTO_SHOVEL_SPRINKLER_MAX) or DEFAULT_MAX))
AUTO_SHOVEL_SPRINKLER_TYPES = AUTO_SHOVEL_SPRINKLER_TYPES or {}
AUTO_SHOVEL_SPRINKLER_PLANTS = AUTO_SHOVEL_SPRINKLER_PLANTS or {}

local function publishStatus(msg)
    LAST_STATUS = tostring(msg or "")
    G.__AUTO_SHOVEL_SPRINKLER_STATUS = LAST_STATUS
    _G.__AUTO_SHOVEL_SPRINKLER_STATUS = LAST_STATUS
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.auto_shovel_sprinkler
    return type(st) == "table" and st or {}
end

local function cleanSelectedMap(src)
    local out = {}
    if type(src) ~= "table" then return out end
    if #src > 0 then
        for _, k in ipairs(src) do
            out[tostring(k)] = true
        end
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function selectedCount(map)
    local n = 0
    if type(map) ~= "table" then return 0 end
    for _, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            n += 1
        end
    end
    return n
end

local function syncGlobalsFromState()
    local st = getState()
    if G.AUTO_SHOVEL_SPRINKLER_ENABLED == true
        or _G.AUTO_SHOVEL_SPRINKLER_ENABLED == true
        or AUTO_SHOVEL_SPRINKLER_ENABLED == true
        or st.enabled == true
    then
        AUTO_SHOVEL_SPRINKLER_ENABLED = true
    else
        AUTO_SHOVEL_SPRINKLER_ENABLED = false
    end
    local maxSrc = G.AUTO_SHOVEL_SPRINKLER_MAX
        or _G.AUTO_SHOVEL_SPRINKLER_MAX
        or AUTO_SHOVEL_SPRINKLER_MAX
        or st.maxPerType
    AUTO_SHOVEL_SPRINKLER_MAX = math.max(0, math.floor(tonumber(maxSrc) or DEFAULT_MAX))
    local types = G.AUTO_SHOVEL_SPRINKLER_TYPES or _G.AUTO_SHOVEL_SPRINKLER_TYPES or AUTO_SHOVEL_SPRINKLER_TYPES or st.types
    AUTO_SHOVEL_SPRINKLER_TYPES = cleanSelectedMap(types)
    local plants = G.AUTO_SHOVEL_SPRINKLER_PLANTS or _G.AUTO_SHOVEL_SPRINKLER_PLANTS or AUTO_SHOVEL_SPRINKLER_PLANTS or st.plants
    AUTO_SHOVEL_SPRINKLER_PLANTS = cleanSelectedMap(plants)
    G.AUTO_SHOVEL_SPRINKLER_ENABLED = AUTO_SHOVEL_SPRINKLER_ENABLED
    G.AUTO_SHOVEL_SPRINKLER_MAX = AUTO_SHOVEL_SPRINKLER_MAX
    G.AUTO_SHOVEL_SPRINKLER_TYPES = AUTO_SHOVEL_SPRINKLER_TYPES
    G.AUTO_SHOVEL_SPRINKLER_PLANTS = AUTO_SHOVEL_SPRINKLER_PLANTS
    _G.AUTO_SHOVEL_SPRINKLER_ENABLED = AUTO_SHOVEL_SPRINKLER_ENABLED
    _G.AUTO_SHOVEL_SPRINKLER_MAX = AUTO_SHOVEL_SPRINKLER_MAX
    _G.AUTO_SHOVEL_SPRINKLER_TYPES = AUTO_SHOVEL_SPRINKLER_TYPES
    _G.AUTO_SHOVEL_SPRINKLER_PLANTS = AUTO_SHOVEL_SPRINKLER_PLANTS
end

local SESSION_DONE = false

local function sessionDone()
    return SESSION_DONE == true
end

local function setSessionDone(on)
    SESSION_DONE = (on == true)
    G.__AUTO_SHOVEL_SPRINKLER_SESSION_DONE = SESSION_DONE
    _G.__AUTO_SHOVEL_SPRINKLER_SESSION_DONE = SESSION_DONE
end

local function getOwnFarm()
    local now = os.clock()
    if cachedFarm and cachedFarm.Parent and (now - cachedFarmAt) <= 5 then
        return cachedFarm
    end
    cachedFarmAt = now
    cachedFarm = nil
    if type(GetFarmAsync) == "function" then
        local ok, farm = pcall(GetFarmAsync, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end
    if type(GetFarm) == "function" then
        local ok, farm = pcall(GetFarm, LP)
        if ok and farm then
            cachedFarm = farm
            return farm
        end
    end
    local farms = workspace:FindFirstChild("Farm")
    if not farms then return nil end
    local username = LP and LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local ok, owner = pcall(function()
            return farm.Important.Data.Owner.Value
        end)
        if ok and owner == username then
            cachedFarm = farm
            return farm
        end
    end
    return nil
end

local function getPlantsFolder(farm)
    farm = farm or getOwnFarm()
    if not farm then return nil end
    local important = farm:FindFirstChild("Important")
    return (important and important:FindFirstChild("Plants_Physical"))
        or farm:FindFirstChild("Plants_Physical", true)
end

local function getObjectsFolder(farm)
    farm = farm or getOwnFarm()
    if not farm then return nil end
    local important = farm:FindFirstChild("Important")
    return (important and important:FindFirstChild("Objects_Physical"))
        or farm:FindFirstChild("Objects_Physical", true)
end

local function cleanName(s)
    local n = tostring(s or "")
    n = n:gsub("%b[]", " "):gsub("%b()", " ")
    n = n:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    return n
end

local function sprinklerKind(obj)
    if not obj then return "" end
    local raw = obj:GetAttribute("ItemName") or obj:GetAttribute("ITEM_NAME") or obj:GetAttribute("f") or obj.Name
    local n = cleanName(raw)
    local kind = n:match("^(.-[Ss]prinkler)")
    return kind or n
end

local function looksSprinkler(obj)
    if not obj then return false end
    local n = tostring(obj.Name or ""):lower()
    local item = tostring(
        obj:GetAttribute("ItemName")
            or obj:GetAttribute("ITEM_NAME")
            or obj:GetAttribute("f")
            or obj:GetAttribute("ItemType")
            or obj:GetAttribute("OBJECT_TYPE")
            or ""
    ):lower()
    return n:find("sprinkler", 1, true) ~= nil or item:find("sprinkler", 1, true) ~= nil
end

local function typeAllowed(kind)
    local sel = AUTO_SHOVEL_SPRINKLER_TYPES
    if selectedCount(sel) <= 0 then
        return true
    end
    if sel[kind] == true then return true end
    local low = tostring(kind or ""):lower()
    for k, v in pairs(sel) do
        if (v == true or v == 1) and tostring(k):lower() == low then
            return true
        end
    end
    return false
end

local function plantAllowed(name)
    local sel = AUTO_SHOVEL_SPRINKLER_PLANTS
    if selectedCount(sel) <= 0 then
        return true
    end
    if sel[name] == true then return true end
    local low = tostring(name or ""):lower()
    for k, v in pairs(sel) do
        if (v == true or v == 1) and tostring(k):lower() == low then
            return true
        end
    end
    return false
end

local function cleanPlantName(plant)
    local raw = tostring(plant and (plant:GetAttribute("ItemName") or plant.Name) or "")
    if StringUtils and type(StringUtils.StipFlavourText) == "function" then
        local ok, cleaned = pcall(function()
            return StringUtils:StipFlavourText(raw)
        end)
        if ok and type(cleaned) == "string" and cleaned ~= "" then
            return cleaned
        end
    end
    return cleanName(raw)
end

local function isGrowablePlant(plant)
    if not plant then return false end
    if plant:FindFirstChild("Grow") then return true end
    local tagged = false
    pcall(function()
        tagged = CollectionService:HasTag(plant, "Growable") == true
    end)
    if tagged then return true end
    pcall(function()
        tagged = plant:HasTag("Growable") == true
    end)
    return tagged
end

local function worldPos(inst)
    if not inst then return nil end
    if inst:IsA("BasePart") then return inst.Position end
    if inst:IsA("Model") then
        local ok, pivot = pcall(function()
            return inst:GetPivot().Position
        end)
        if ok then return pivot end
        if inst.PrimaryPart then return inst.PrimaryPart.Position end
    end
    local part = inst:FindFirstChildWhichIsA("BasePart", true)
    return part and part.Position or nil
end

local function listPlantPos()
    local farm = getOwnFarm()
    local folder = getPlantsFolder(farm)
    local out = {}
    if folder then
        for _, plant in ipairs(folder:GetChildren()) do
            if isGrowablePlant(plant) and (not plant.Parent or plant.Parent.Name ~= "Fruits") then
                local name = cleanPlantName(plant)
                if name ~= "" and plantAllowed(name) then
                    local pos = worldPos(plant)
                    if pos then
                        out[#out + 1] = { plant = plant, name = name, pos = pos }
                    end
                end
            end
        end
    end
    return out, farm
end

local function listGardenSprinklers(selectedOnly)
    local farm = getOwnFarm()
    local folder = getObjectsFolder(farm)
    local out = {}
    local function consider(obj)
        if not looksSprinkler(obj) then return end
        if obj:IsA("BasePart") then
            local m = obj:FindFirstAncestorOfClass("Model")
            if m and m ~= farm and looksSprinkler(m) then
                obj = m
            end
        end
        local kind = sprinklerKind(obj)
        if selectedOnly and not typeAllowed(kind) then return end
        for i = 1, #out do
            if out[i].obj == obj then return end
        end
        out[#out + 1] = { obj = obj, kind = kind }
    end
    if folder then
        for _, ch in ipairs(folder:GetChildren()) do
            consider(ch)
        end
    elseif farm then
        for _, d in ipairs(farm:GetDescendants()) do
            if d:IsA("Model") or d:IsA("BasePart") then
                consider(d)
            end
        end
    end
    return out
end

local function countGardenKind(kind)
    local n = 0
    local want = tostring(kind or ""):lower()
    for _, rec in ipairs(listGardenSprinklers(false)) do
        if tostring(rec.kind or ""):lower() == want then
            n += 1
        end
    end
    return n
end

local function forEachTool(fn)
    local function scan(container)
        if not container then return end
        for _, t in ipairs(container:GetChildren()) do
            if t:IsA("Tool") then
                fn(t)
            end
        end
    end
    scan(LP and LP:FindFirstChild("Backpack"))
    scan(LP and LP.Character)
end

local function findSprinklerTool(kind)
    local want = tostring(kind or ""):lower()
    local found
    forEachTool(function(tool)
        if found then return end
        if not looksSprinkler(tool) then return end
        local k = sprinklerKind(tool):lower()
        if want == "" or k == want or k:find(want, 1, true) or want:find(k, 1, true) then
            found = tool
        end
    end)
    return found
end

local function findShovelTool()
    local found
    forEachTool(function(tool)
        if found then return end
        local n = tostring(tool.Name or "")
        if n == SHOVEL_NAME or n:lower():find("shovel", 1, true) then
            found = tool
        end
    end)
    return found
end

local function unequipTools()
    local char = LP and LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            hum:UnequipTools()
        end)
    end
end

local function equipTool(tool)
    local char = LP and LP.Character
    if not char or not tool then return false end
    if tool.Parent == char then return true end
    local hum = char:FindFirstChildOfClass("Humanoid")
    unequipTools()
    if hum then
        pcall(function()
            hum:EquipTool(tool)
        end)
    else
        tool.Parent = char
    end
    task.wait(EQUIP_WAIT)
    return tool.Parent == char
end

local function getHrp()
    local char = LP and LP.Character
    return char and char:FindFirstChild("HumanoidRootPart")
end

local function goNear(pos, range)
    local hrp = getHrp()
    if not hrp or not pos then return false end
    range = range or 14
    local d = hrp.Position - pos
    if math.sqrt(d.X * d.X + d.Z * d.Z) <= range then
        return true
    end
    hrp.CFrame = CFrame.new(pos.X, hrp.Position.Y, pos.Z)
    task.wait(0.15)
    d = hrp.Position - pos
    return math.sqrt(d.X * d.X + d.Z * d.Z) <= range + 6
end

local function resolveRemotes()
    local ge = ReplicatedStorage:FindFirstChild("GameEvents")
    if not ge then return false end
    if not (SprinklerService and SprinklerService.Parent) then
        SprinklerService = ge:FindFirstChild("SprinklerService")
    end
    if not (DeleteObjectRE and DeleteObjectRE.Parent) then
        DeleteObjectRE = ge:FindFirstChild("DeleteObject")
    end
    return SprinklerService ~= nil, DeleteObjectRE ~= nil
end

local function pickPlacePos()
    local plants = select(1, listPlantPos())
    if #plants == 0 then
        local farm = getOwnFarm()
        local folder = getPlantsFolder(farm)
        if folder then
            local p = worldPos(folder:FindFirstChildWhichIsA("Model", true) or folder)
            if p then return p, farm end
        end
        return nil, farm
    end
    if plantCursor < 1 or plantCursor > #plants then
        plantCursor = 1
    end
    local rec = plants[plantCursor]
    plantCursor += 1
    return rec.pos, getOwnFarm(), rec.name
end

local function kindsToPlace()
    local kinds = {}
    local seen = {}
    local function add(kind)
        kind = cleanName(kind)
        if kind == "" then return end
        local low = kind:lower()
        if seen[low] then return end
        if not typeAllowed(kind) then return end
        seen[low] = true
        kinds[#kinds + 1] = kind
    end
    if selectedCount(AUTO_SHOVEL_SPRINKLER_TYPES) > 0 then
        for k, v in pairs(AUTO_SHOVEL_SPRINKLER_TYPES) do
            if v == true or v == 1 then
                add(tostring(k))
            end
        end
    else
        forEachTool(function(tool)
            if looksSprinkler(tool) then
                add(sprinklerKind(tool))
            end
        end)
    end
    table.sort(kinds)
    return kinds
end

local function sprinklerUses(src)
    if type(src) == "number" then
        return math.max(0, math.floor(src))
    end
    if type(src) == "string" then
        local n = tonumber(src:match("(%d+)"))
        return math.max(0, math.floor(n or 0))
    end
    if typeof(src) == "Instance" then
        local n = tonumber(src:GetAttribute("Uses") or src:GetAttribute("Quantity"))
        if n then
            return math.max(0, math.floor(n))
        end
        local ok, val = pcall(function()
            local v = src:FindFirstChild("Uses") or src:FindFirstChild("Quantity")
            return v and tonumber(v.Value)
        end)
        if ok and val then
            return math.max(0, math.floor(val))
        end
        return 1
    end
    return 0
end

function M.ListSprinklerItems()
    syncGlobalsFromState()
    local totals = {}
    local PetListView = G.PetListView or _G.PetListView
    if PetListView and type(PetListView.buildInventoryItemsByType) == "function" then
        local ok, items = pcall(function()
            return PetListView.buildInventoryItemsByType("Sprinkler", { onlyBackpack = true })
        end)
        if ok and type(items) == "table" then
            for _, it in ipairs(items) do
                local name = tostring(it.itemName or "")
                if name ~= "" then
                    totals[name] = (totals[name] or 0) + sprinklerUses(it.amount or it.amountText)
                end
            end
        end
    end
    if next(totals) == nil then
        forEachTool(function(tool)
            if looksSprinkler(tool) then
                local k = sprinklerKind(tool)
                totals[k] = (totals[k] or 0) + sprinklerUses(tool)
            end
        end)
    end
    local list = {}
    local seen = {}
    local function add(key, uses)
        key = tostring(key or "")
        if key == "" or seen[key] then return end
        seen[key] = true
        list[#list + 1] = {
            key = key,
            name = string.format("%s | Uses %d | Sprinkler", key, math.max(0, math.floor(tonumber(uses) or 0))),
        }
    end
    for name, n in pairs(totals) do
        add(name, n)
    end
    for k, v in pairs(AUTO_SHOVEL_SPRINKLER_TYPES or {}) do
        if v == true or v == 1 then
            add(tostring(k), totals[tostring(k)] or 0)
        end
    end
    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    return list
end

function M.ListGardenPlantItems()
    syncGlobalsFromState()
    local folder = getPlantsFolder()
    local counts = {}
    if folder then
        for _, plant in ipairs(folder:GetChildren()) do
            if isGrowablePlant(plant) and (not plant.Parent or plant.Parent.Name ~= "Fruits") then
                local name = cleanPlantName(plant)
                if name ~= "" then
                    counts[name] = (counts[name] or 0) + 1
                end
            end
        end
    end
    local list, seen = {}, {}
    for name, n in pairs(counts) do
        seen[name] = true
        list[#list + 1] = { key = name, name = string.format("%s x%d", name, n), right = tostring(n) }
    end
    for k, v in pairs(AUTO_SHOVEL_SPRINKLER_PLANTS or {}) do
        if (v == true or v == 1) and not seen[tostring(k)] then
            list[#list + 1] = { key = tostring(k), name = tostring(k) .. " x0", right = "0" }
        end
    end
    table.sort(list, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    return list
end

function M.GetStatus()
    return LAST_STATUS
end

function M.GetStatusText()
    syncGlobalsFromState()
    local on = AUTO_SHOVEL_SPRINKLER_ENABLED == true and "ON" or "OFF"
    local done = sessionDone() and "DONE" or (RUNNING and PHASE or "idle")
    local gN = #listGardenSprinklers(false)
    local tN = selectedCount(AUTO_SHOVEL_SPRINKLER_TYPES)
    local pN = selectedCount(AUTO_SHOVEL_SPRINKLER_PLANTS)
    local lines = {}
    lines[#lines + 1] = ("garden sprinkler %d · max/type %d"):format(gN, AUTO_SHOVEL_SPRINKLER_MAX)
    lines[#lines + 1] = ("Enable %s · %s · type %s · plant %s"):format(
        on,
        done,
        tN > 0 and tostring(tN) or "ANY",
        pN > 0 and tostring(pN) or "ALL"
    )
    lines[#lines + 1] = (LAST_STATUS ~= "" and LAST_STATUS or "idle")
    if SHOVEL_ALL_RUNNING then
        lines[#lines + 1] = "shovel all ON"
    end
    return table.concat(lines, "\n")
end

local function tryPlaceOneKind(kind, cap)
    if cap <= 0 then
        return false, "cap 0"
    end
    local have = countGardenKind(kind)
    if have >= cap then
        return false, ("cap %s %d/%d"):format(kind, have, cap)
    end
    local tool = findSprinklerTool(kind)
    if not tool then
        return false, ("no tool %s"):format(kind)
    end
    local hasCreate = select(1, resolveRemotes())
    if not hasCreate then
        return false, "no SprinklerService"
    end
    local pos = pickPlacePos()
    if not pos then
        return false, "no plant pos"
    end
    if not goNear(pos, 14) then
        return false, "far from plant"
    end
    if not equipTool(tool) then
        return false, "equip sprinkler fail"
    end
    local ok = pcall(function()
        SprinklerService:FireServer("Create", CFrame.new(pos))
    end)
    task.wait(PLACE_WAIT)
    unequipTools()
    if not ok then
        return false, "place failed"
    end
    return true, ("placed %s (%d/%d)"):format(kind, math.min(have + 1, cap), cap)
end

local function tryShovelOne()
    local list = listGardenSprinklers(false)
    if #list == 0 then
        return false, "no sprinkler"
    end
    local hasDelete = select(2, resolveRemotes())
    if not hasDelete then
        return false, "no DeleteObject"
    end
    local rec = list[1]
    local obj = rec.obj
    local pos = worldPos(obj)
    if pos then
        goNear(pos, 14)
    end
    local shovel = findShovelTool()
    if not shovel then
        return false, "no shovel"
    end
    if not equipTool(shovel) then
        return false, "equip shovel fail"
    end
    local ok = pcall(function()
        DeleteObjectRE:FireServer(obj)
    end)
    task.wait(SHOVEL_WAIT)
    if not ok then
        return false, "shovel failed"
    end
    if obj.Parent then
        task.wait(0.45)
    end
    if obj.Parent then
        return false, "still there"
    end
    return true, ("shoveled %s"):format(rec.kind)
end

local function gardenReady()
    cachedFarm = nil
    cachedFarmAt = 0
    local farm = getOwnFarm()
    if not farm then
        return false
    end
    local folder = getPlantsFolder(farm)
    if not folder then
        return false
    end
    local char = LP and LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then
        return false
    end
    return true
end

local function waitOwnFarm(token, timeoutSec)
    local deadline = os.clock() + (timeoutSec or 60)
    while os.clock() < deadline do
        if not RUNNING or token ~= STOP_TOKEN or AUTO_SHOVEL_SPRINKLER_ENABLED ~= true then
            return nil
        end
        if gardenReady() then
            return getOwnFarm()
        end
        publishStatus("wait garden")
        task.wait(0.45)
    end
    return gardenReady() and getOwnFarm() or nil
end

local function isTransientPlaceFail(msg)
    msg = tostring(msg or "")
    return msg == "no plant pos"
        or msg == "far from plant"
        or msg == "equip sprinkler fail"
        or msg == "place failed"
        or msg == "no SprinklerService"
        or msg == "shark wait bite"
end

local function worker(token)
    PHASE = "place"
    publishStatus("session start · wait garden")
    local farm = waitOwnFarm(token, 60)
    if not RUNNING or token ~= STOP_TOKEN or AUTO_SHOVEL_SPRINKLER_ENABLED ~= true then
        return
    end
    if not farm then
        RUNNING = false
        publishStatus("wait garden timeout · retry")
        task.delay(2.5, function()
            if AUTO_SHOVEL_SPRINKLER_ENABLED == true and not sessionDone() and not RUNNING then
                M.Start()
            end
        end)
        return
    end
    publishStatus("session start · place")
    local cap = AUTO_SHOVEL_SPRINKLER_MAX
    local kinds = kindsToPlace()
    if cap > 0 and #kinds > 0 then
        for _, kind in ipairs(kinds) do
            if not RUNNING or token ~= STOP_TOKEN or AUTO_SHOVEL_SPRINKLER_ENABLED ~= true then
                break
            end
            local guard = 0
            while RUNNING and token == STOP_TOKEN and guard < 40 do
                guard += 1
                syncGlobalsFromState()
                cap = AUTO_SHOVEL_SPRINKLER_MAX
                local have = countGardenKind(kind)
                if have >= cap then
                    publishStatus(("place done %s %d/%d"):format(kind, have, cap))
                    break
                end
                local callOk, ok, msg = pcall(tryPlaceOneKind, kind, cap)
                if not callOk then
                    publishStatus("err: " .. tostring(ok):sub(1, 80))
                    task.wait(0.4)
                elseif type(msg) == "string" then
                    publishStatus(msg)
                end
                if ok ~= true then
                    if type(msg) == "string" and msg:find("no tool", 1, true) then
                        if guard < 8 then
                            publishStatus("wait tool " .. tostring(kind))
                            task.wait(0.5)
                        else
                            break
                        end
                    elseif type(msg) == "string" and msg:sub(1, 4) == "cap " then
                        break
                    elseif isTransientPlaceFail(msg) then
                        task.wait(0.45)
                    else
                        task.wait(0.35)
                    end
                else
                    task.wait(0.2)
                end
            end
        end
    else
        publishStatus("skip place")
    end

    if RUNNING and token == STOP_TOKEN and AUTO_SHOVEL_SPRINKLER_ENABLED == true then
        PHASE = "shovel"
        publishStatus("shovel all")
        local guard = 0
        while RUNNING and token == STOP_TOKEN and guard < 80 do
            guard += 1
            syncGlobalsFromState()
            local callOk, ok, msg = pcall(tryShovelOne)
            if not callOk then
                publishStatus("err: " .. tostring(ok):sub(1, 80))
                break
            end
            if type(msg) == "string" then
                publishStatus(msg)
            end
            if ok ~= true then
                break
            end
            task.wait(0.15)
        end
        unequipTools()
    end

    PHASE = "done"
    setSessionDone(true)
    publishStatus("done this session")
    RUNNING = false
    unequipTools()
end

function M.Start()
    syncGlobalsFromState()
    if RUNNING then return end
    if AUTO_SHOVEL_SPRINKLER_ENABLED ~= true then return end
    if sessionDone() then
        publishStatus("done this session")
        return
    end
    RUNNING = true
    STOP_TOKEN += 1
    local token = STOP_TOKEN
    task.spawn(worker, token)
end

function M.Stop()
    RUNNING = false
    STOP_TOKEN += 1
    PHASE = "idle"
    unequipTools()
    if LAST_STATUS ~= "done this session" then
        publishStatus("stopped")
    end
end

function M.SetEnabled(on)
    AUTO_SHOVEL_SPRINKLER_ENABLED = (on == true)
    G.AUTO_SHOVEL_SPRINKLER_ENABLED = AUTO_SHOVEL_SPRINKLER_ENABLED
    _G.AUTO_SHOVEL_SPRINKLER_ENABLED = AUTO_SHOVEL_SPRINKLER_ENABLED
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.auto_shovel_sprinkler = MAIN.misc.auto_shovel_sprinkler or {}
        MAIN.misc.auto_shovel_sprinkler.enabled = AUTO_SHOVEL_SPRINKLER_ENABLED
    end
    if AUTO_SHOVEL_SPRINKLER_ENABLED then
        setSessionDone(false)
        M.Start()
    else
        M.Stop()
    end
end

function M.SetMaxPerType(n)
    AUTO_SHOVEL_SPRINKLER_MAX = math.max(0, math.floor(tonumber(n) or DEFAULT_MAX))
    G.AUTO_SHOVEL_SPRINKLER_MAX = AUTO_SHOVEL_SPRINKLER_MAX
    _G.AUTO_SHOVEL_SPRINKLER_MAX = AUTO_SHOVEL_SPRINKLER_MAX
end

function M.SetTypes(map)
    AUTO_SHOVEL_SPRINKLER_TYPES = cleanSelectedMap(map)
    G.AUTO_SHOVEL_SPRINKLER_TYPES = AUTO_SHOVEL_SPRINKLER_TYPES
    _G.AUTO_SHOVEL_SPRINKLER_TYPES = AUTO_SHOVEL_SPRINKLER_TYPES
end

function M.SetPlants(map)
    AUTO_SHOVEL_SPRINKLER_PLANTS = cleanSelectedMap(map)
    G.AUTO_SHOVEL_SPRINKLER_PLANTS = AUTO_SHOVEL_SPRINKLER_PLANTS
    _G.AUTO_SHOVEL_SPRINKLER_PLANTS = AUTO_SHOVEL_SPRINKLER_PLANTS
end

function M.IsShovelAllRunning()
    return SHOVEL_ALL_RUNNING == true
end

function M.StopShovelAll()
    SHOVEL_ALL_RUNNING = false
    SHOVEL_ALL_TOKEN += 1
    if not RUNNING then
        unequipTools()
        publishStatus("shovel all stopped")
    end
end

function M.ShovelAll(onDone)
    if SHOVEL_ALL_RUNNING then
        return
    end
    SHOVEL_ALL_RUNNING = true
    SHOVEL_ALL_TOKEN += 1
    local token = SHOVEL_ALL_TOKEN
    task.spawn(function()
        publishStatus("shovel all now")
        local guard = 0
        while SHOVEL_ALL_RUNNING and token == SHOVEL_ALL_TOKEN and guard < 80 do
            guard += 1
            local callOk, ok, msg = pcall(tryShovelOne)
            if not callOk then
                publishStatus("err: " .. tostring(ok):sub(1, 80))
                break
            end
            if type(msg) == "string" then
                publishStatus(msg)
            end
            if ok ~= true then
                break
            end
            task.wait(0.15)
        end
        if token == SHOVEL_ALL_TOKEN then
            SHOVEL_ALL_RUNNING = false
            if not RUNNING then
                unequipTools()
            end
            publishStatus("shovel all done")
            if type(onDone) == "function" then
                pcall(onDone)
            end
        end
    end)
end

function M.SyncFromState()
    syncGlobalsFromState()
    if AUTO_SHOVEL_SPRINKLER_ENABLED == true then
        task.defer(function()
            task.wait(1.2)
            if AUTO_SHOVEL_SPRINKLER_ENABLED == true and not sessionDone() then
                M.Start()
            end
        end)
    else
        M.Stop()
    end
end

G.AutoShovelSprinkler = M
_G.AutoShovelSprinkler = M

return M

