}

local COSMETIC_HIDE = {
    Cosmetic_Physical = true,
}

local savedGfx = nil

local PART_CLASS = {
    Part = true,
    MeshPart = true,
    UnionOperation = true,
    WedgePart = true,
    CornerWedgePart = true,
    TrussPart = true,
    Seat = true,
    VehicleSeat = true,
}

local FX_CLASSNAME = {
    ParticleEmitter = true,
    Trail = true,
    Beam = true,
    Fire = true,
    Smoke = true,
    Sparkles = true,
    PointLight = true,
    SpotLight = true,
    SurfaceLight = true,
    Highlight = true,
}

local SKIP_CLASS = {
    ProximityPrompt = true,
    ClickDetector = true,
    Humanoid = true,
    Animator = true,
    AnimationController = true,
    Weld = true,
    WeldConstraint = true,
    Motor6D = true,
    Attachment = true,
    NumberValue = true,
    StringValue = true,
    IntValue = true,
    BoolValue = true,
    ObjectValue = true,
    CFrameValue = true,
    Vector3Value = true,
    Color3Value = true,
    Folder = true,
    Model = true,
    Configuration = true,
    Camera = true,
    Accoutrement = true,
    Accessory = true,
}

local function optTbl()
    local MAIN = rawget(G, "MAIN") or rawget(_G, "MAIN")
    return MAIN and MAIN.misc and MAIN.misc.optimizer
end

local function isGardenEnabled()
    if gardenOn == true or G.REDUCE_GARDEN_FX_ENABLED == true then
        return true
    end
    local o = optTbl()
    return o and o.reduce_garden_fx == true
end

local function isParticleEnabled()
    if particleOn == true or G.REDUCE_PARTICLES_ENABLED == true then
        return true
    end
    local o = optTbl()
    return o and o.reduce_particles == true
end

local function persistFlag(key, on)
    local MAIN = rawget(G, "MAIN") or rawget(_G, "MAIN")
    if type(MAIN) ~= "table" then
        return
    end
    MAIN.misc = MAIN.misc or {}
    MAIN.misc.optimizer = MAIN.misc.optimizer or {}
    MAIN.misc.optimizer[key] = on
end

local function isProtected(inst)
    if not inst then
        return true
    end
    local c = inst.ClassName
    if SKIP_CLASS[c] then
        return true
    end
    if inst:IsA("ValueBase") then
        return true
    end
    local n = inst.Name
    if n == "Item_String" or n == "Weight" or n == "Variant" then
        return true
    end
    if n == "Fruits" or n == "Fruit_Spawn" or n == "Plants_Physical" or n == "Important" or n == "Data" then
        return true
    end
    return false
end

local function isUnderPlantsPhysical(inst)
    local p = inst
    while p and p ~= game do
        if p.Name == "Plants_Physical" then
            return true
        end
        p = p.Parent
    end
    return false
end

local function isFxClass(inst)
    return inst ~= nil and FX_CLASSNAME[inst.ClassName] == true
end

local function remember(bag, inst, key, value)
    local rec = bag[inst]
    if type(rec) ~= "table" then
        rec = {}
        bag[inst] = rec
    end
    if rec[key] == nil then
        rec[key] = value
    end
end

local function disableFx(bag, inst, mark)
    local c = inst.ClassName
    if c == "ParticleEmitter" then
        remember(bag, inst, "Enabled", inst.Enabled)
        remember(bag, inst, "Rate", inst.Rate)
        inst.Rate = 0
        inst.Enabled = false
    elseif FX_CLASSNAME[c] then
        remember(bag, inst, "Enabled", inst.Enabled)
        inst.Enabled = false
    else
        return
    end
    pcall(function()
        inst:SetAttribute(mark, true)
    end)
end

local function isUnderFruits(inst)
    local p = inst
    for _ = 1, 16 do
        if not p or p == game then
            return false
        end
        if p.Name == "Fruits" then
            return true
        end
        if p.Name == "Plants_Physical" then
            return false
        end
        p = p.Parent
    end
    return false
end

-- Spawn points are Parts. Destroying them zeros fruit-slot count and breaks ClientPlantGrowth.
local function isUnderFruitSpawn(inst)
    local p = inst
    for _ = 1, 16 do
        if not p or p == game then
            return false
        end
        if p.Name == "Fruit_Spawn" then
            return true
        end
        if p.Name == "Plants_Physical" then
            return false
        end
        p = p.Parent
    end
    return false
end

local function partHoldsPrompt(inst)
    if not inst then
        return false
    end
    for _, ch in ipairs(inst:GetChildren()) do
        if ch.ClassName == "ProximityPrompt" then
            return true
        end
        if ch.ClassName == "Attachment" and ch:FindFirstChildWhichIsA("ProximityPrompt") then
            return true
        end
    end
    return false
end

local function hideGardenPart(inst)
    remember(savedGarden, inst, "LTM", inst.LocalTransparencyModifier)
    remember(savedGarden, inst, "CastShadow", inst.CastShadow)
    inst.LocalTransparencyModifier = 1
    inst.CastShadow = false
end

-- knownUnder=true when walking Plants_Physical (skip parent-chain walk)
-- Keep fruit parts + ProximityPrompt (auto collect). Destroy other meshes/FX.
local function stripGardenOne(inst, knownUnder)
    if not inst or not inst.Parent then
        return
    end
    local c = inst.ClassName
    if SKIP_CLASS[c] then
        return
    end
    local n = inst.Name
    if n == "Item_String" or n == "Weight" or n == "Variant" then
        return
    end
    if knownUnder ~= true and not isUnderPlantsPhysical(inst) then
        return
    end

    local keepForCollect = isUnderFruits(inst) or isUnderFruitSpawn(inst) or partHoldsPrompt(inst)

    if PART_CLASS[c] then
        if keepForCollect then
            hideGardenPart(inst)
        else
            pcall(function()
                inst:Destroy()
            end)
        end
        return
    end

    if FX_CLASSNAME[c]
        or c == "Decal"
        or c == "Texture"
        or c == "BillboardGui"
        or c == "SurfaceGui"
        or c == "SpecialMesh"
        or c == "BlockMesh"
        or c == "CylinderMesh"
        or c == "FileMesh"
    then
        pcall(function()
            inst:Destroy()
        end)
    end
end

local function stripParticleOne(inst)
    if not inst or not inst.Parent then
        return
    end
    if isProtected(inst) then
        return
    end
    if inst:IsDescendantOf(Players) then
        return
    end
    if LP and LP:FindFirstChild("PlayerGui") and inst:IsDescendantOf(LP.PlayerGui) then
        return
    end
    if isFxClass(inst) then
        disableFx(savedParticle, inst, ATTR_PARTICLE)
    end
end

local function restoreFxEnabled(inst, rec)
    if rec.Enabled ~= nil then
        inst.Enabled = rec.Enabled == true
    end
    if rec.Rate ~= nil and inst:IsA("ParticleEmitter") then
        inst.Rate = rec.Rate
    end
end

local function restoreGardenOne(inst, rec)
    if not inst or not inst.Parent or type(rec) ~= "table" then
        return
    end

    if isFxClass(inst) then
        if not isParticleEnabled() then
            restoreFxEnabled(inst, rec)
        end
    elseif rec.Enabled ~= nil and (inst:IsA("BillboardGui") or inst:IsA("SurfaceGui")) then
        inst.Enabled = rec.Enabled == true
    end

    if rec.Transparency ~= nil and (inst:IsA("Decal") or inst:IsA("Texture")) then
        inst.Transparency = rec.Transparency
    end

    if inst:IsA("BasePart") then
        if rec.LTM ~= nil then
            inst.LocalTransparencyModifier = rec.LTM
        end
        if rec.CastShadow ~= nil then
            inst.CastShadow = rec.CastShadow
        end
        if rec.Material ~= nil then
            pcall(function()
                inst.Material = rec.Material
            end)
        end
        if rec.Reflectance ~= nil then
            inst.Reflectance = rec.Reflectance
        end
    end

    pcall(function()
        inst:SetAttribute(ATTR_GARDEN, nil)
    end)
end

local function restoreParticleOne(inst, rec)
    if not inst or not inst.Parent or type(rec) ~= "table" then
        return
    end
    if isFxClass(inst) and isGardenEnabled() and isUnderPlantsPhysical(inst) then
        pcall(function()
            inst:SetAttribute(ATTR_PARTICLE, nil)
        end)
        return
    end
    restoreFxEnabled(inst, rec)
    if rec.LightingEnabled ~= nil then
        pcall(function()
            inst.Enabled = rec.LightingEnabled
        end)
    end
    if rec.Transparency ~= nil and (inst.ClassName == "Decal" or inst.ClassName == "Texture") then
        inst.Transparency = rec.Transparency
    end
    if rec.Enabled ~= nil and (inst.ClassName == "BillboardGui" or inst.ClassName == "SurfaceGui") then
        inst.Enabled = rec.Enabled == true
    end
    if PART_CLASS[inst.ClassName] then
        if rec.LTM ~= nil then
            inst.LocalTransparencyModifier = rec.LTM
        end
        if rec.CastShadow ~= nil then
            inst.CastShadow = rec.CastShadow
        end
        if rec.Material ~= nil then
            pcall(function()
                inst.Material = rec.Material
            end)
        end
        if rec.MaterialVariant ~= nil then
            pcall(function()
                inst.MaterialVariant = rec.MaterialVariant
            end)
        end
        if rec.Reflectance ~= nil then
            inst.Reflectance = rec.Reflectance
        end
        if rec.RenderFidelity ~= nil then
            pcall(function()
                inst.RenderFidelity = rec.RenderFidelity
            end)
        end
    end
    pcall(function()
        inst:SetAttribute(ATTR_PARTICLE, nil)
    end)
end

local function readSetting(name, fallback)
    local v = fallback
    pcall(function()
        local SettingsService = require(game:GetService("ReplicatedStorage").Modules.Settings.SettingsService)
        local got = SettingsService:GetSetting(name)
        if got ~= nil then
            v = got
        end
    end)
    return v
end

local function applyCropVfx(hide)
    if not LP then
        return
    end
    if hide then
        if cropVfxPrev == nil then
            cropVfxPrev = LP:GetAttribute("CropMutationVFX")
        end
        LP:SetAttribute("CropMutationVFX", false)
        return
    end
    if isGardenEnabled() or isParticleEnabled() then
        return
    end
    local restore = cropVfxPrev
    cropVfxPrev = nil
    if restore == nil then
        restore = readSetting("CropMutationVFX", true)
    end
    LP:SetAttribute("CropMutationVFX", restore)
end

local function applyPetVfx(hide)
    if not LP then
        return
    end
    if hide then
        if petVfxPrev == nil then
            petVfxPrev = LP:GetAttribute("PetMutationVFX")
        end
        LP:SetAttribute("PetMutationVFX", false)
        return
    end
    if isParticleEnabled() then
        return
    end
    local restore = petVfxPrev
    petVfxPrev = nil
    if restore == nil then
        restore = readSetting("PetMutationVFX", true)
    end
    LP:SetAttribute("PetMutationVFX", restore)
end

local function getOwnPlantsPhysical()
    local farms = workspace:FindFirstChild("Farm")
    if not farms or not LP then
        return nil
    end
    local uname = LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local important = farm:FindFirstChild("Important")
        local data = important and important:FindFirstChild("Data")
        local owner = data and data:FindFirstChild("Owner")
        local ok, val = pcall(function()
            return owner and owner.Value
        end)
        if ok and val == uname then
            return important and important:FindFirstChild("Plants_Physical"), farm
        end
    end
    return nil
end

local function eachOtherPlantsPhysical(fn)
    local farms = workspace:FindFirstChild("Farm")
    if not farms or not LP then
        return
    end
    local uname = LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local important = farm:FindFirstChild("Important")
        local data = important and important:FindFirstChild("Data")
        local owner = data and data:FindFirstChild("Owner")
        local ok, val = pcall(function()
            return owner and owner.Value
        end)
        if not (ok and val == uname) then
            local plants = important and important:FindFirstChild("Plants_Physical")
            if plants then
                fn(plants)
            end
        end
    end
end

local function stripTree(root, fn, chunk, knownUnder)
    if not root then
        return
    end
    chunk = chunk or CHUNK_GARDEN
    local n = 0
    fn(root, knownUnder)
    local list = root:GetDescendants()
    for i = 1, #list do
        fn(list[i], knownUnder)
        n = n + 1
        if n == chunk then
            n = 0
            task.wait()
            if knownUnder == true and not isGardenEnabled() then
                return
            end
        end
    end
end

local function restripGardenFx(root)
    if not root then
        return
    end
    local list = root:GetDescendants()
    for i = 1, #list do
        local d = list[i]
        local c = d.ClassName
        if FX_CLASSNAME[c]
            or c == "Decal"
            or c == "Texture"
            or c == "BillboardGui"
            or c == "SurfaceGui"
        then
            pcall(function()
                d:Destroy()
            end)
        elseif PART_CLASS[c] then
            if isUnderFruits(d) or isUnderFruitSpawn(d) or partHoldsPrompt(d) then
                hideGardenPart(d)
            else
                pcall(function()
                    d:Destroy()
                end)
            end
        end
    end
end

local function stripGardenAll()
    local own = getOwnPlantsPhysical()
    if own then
        stripTree(own, stripGardenOne, CHUNK_GARDEN, true)
    end

    task.spawn(function()
        eachOtherPlantsPhysical(function(plants)
            if not isGardenEnabled() then
                return
            end
            stripTree(plants, stripGardenOne, CHUNK_OTHER, true)
        end)
    end)
end

local function isUnderNamed(inst, nameSet)
    local p = inst
    while p and p ~= workspace and p ~= game do
        if nameSet[p.Name] then
            return true
        end
        p = p.Parent
    end
    return false
end

local function hideVisual(inst)
    if not inst or not inst.Parent then
        return
    end
    if SKIP_CLASS[inst.ClassName] then
        return
    end
    local n = inst.Name
    if n == "Item_String" or n == "Weight" or n == "Variant" then
        return
    end
    if inst.ClassName == "ProximityPrompt" then
        return
    end
    if savedParticle[inst] then
        local rec = savedParticle[inst]
        if rec and rec.LTM ~= nil and PART_CLASS[inst.ClassName] then
            if inst.LocalTransparencyModifier < 1 then
                inst.LocalTransparencyModifier = 1
                inst.CastShadow = false
            end
            return
        end
        if rec and rec.Enabled ~= nil and FX_CLASSNAME[inst.ClassName] then
            if inst.Enabled then
                inst.Enabled = false
            end
            return
        end
    end

    local c = inst.ClassName
    if FX_CLASSNAME[c] then
        disableFx(savedParticle, inst, ATTR_PARTICLE)
        if c == "ParticleEmitter" then
            pcall(function()
                inst:Clear()
            end)
        end
        return
    end
    if c == "Decal" or c == "Texture" then
        remember(savedParticle, inst, "Transparency", inst.Transparency)
        inst.Transparency = 1
        return
    end
    if c == "BillboardGui" or c == "SurfaceGui" then
        remember(savedParticle, inst, "Enabled", inst.Enabled)
        inst.Enabled = false
        return
    end
    if PART_CLASS[c] then
        remember(savedParticle, inst, "LTM", inst.LocalTransparencyModifier)
        remember(savedParticle, inst, "CastShadow", inst.CastShadow)
        inst.LocalTransparencyModifier = 1
        inst.CastShadow = false
    end
end

local function applyGfx(on)
    if on then
        if savedGfx then
            return
        end
        savedGfx = {}
        pcall(function()
            local rs = settings().Rendering
            savedGfx.QualityLevel = rs.QualityLevel
            rs.QualityLevel = Enum.QualityLevel.Level01
        end)
        pcall(function()
            savedGfx.MeshLod = settings().Rendering.MeshPartDetailLevel
            settings().Rendering.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Level04
        end)
        pcall(function()
            savedGfx.GlobalShadows = Lighting.GlobalShadows
            Lighting.GlobalShadows = false
            savedGfx.FogEnd = Lighting.FogEnd
            savedGfx.FogStart = Lighting.FogStart
            Lighting.FogEnd = 250
            Lighting.FogStart = 0
            savedGfx.Brightness = Lighting.Brightness
            Lighting.Brightness = 1
        end)
        pcall(function()
            local at = Lighting:FindFirstChildWhichIsA("Atmosphere")
            if at then
                savedGfx.AtDensity = at.Density
                savedGfx.AtHaze = at.Haze
                at.Density = 0
                at.Haze = 0
            end
        end)
        pcall(function()
            savedGfx.TerrainDeco = workspace.Terrain.Decoration
            workspace.Terrain.Decoration = false
        end)
        return
    end

    local g = savedGfx
    savedGfx = nil
    if type(g) ~= "table" then
        return
    end
    pcall(function()
        if g.QualityLevel ~= nil then
            settings().Rendering.QualityLevel = g.QualityLevel
        end
    end)
    pcall(function()
        if g.MeshLod ~= nil then
            settings().Rendering.MeshPartDetailLevel = g.MeshLod
        end
    end)
    pcall(function()
        if g.GlobalShadows ~= nil then
            Lighting.GlobalShadows = g.GlobalShadows
        end
        if g.FogEnd ~= nil then
            Lighting.FogEnd = g.FogEnd
        end
        if g.FogStart ~= nil then
            Lighting.FogStart = g.FogStart
        end
        if g.Brightness ~= nil then
            Lighting.Brightness = g.Brightness
        end
    end)
    pcall(function()
        local at = Lighting:FindFirstChildWhichIsA("Atmosphere")
        if at then
            if g.AtDensity ~= nil then
                at.Density = g.AtDensity
            end
            if g.AtHaze ~= nil then
                at.Haze = g.AtHaze
            end
        end
    end)
    pcall(function()
        if g.TerrainDeco ~= nil then
            workspace.Terrain.Decoration = g.TerrainDeco
        end
    end)
end

local function hideOtherCharacters()
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP and plr.Character then
            stripTree(plr.Character, hideVisual, CHUNK_OTHER, false)
        end
    end
end

local function hideOtherFarmsAndCosmetics()
    local farms = workspace:FindFirstChild("Farm")
    if not farms or not LP then
        return
    end
    local uname = LP.Name
    for _, farm in ipairs(farms:GetChildren()) do
        local important = farm:FindFirstChild("Important")
        if important then
            local data = important:FindFirstChild("Data")
            local owner = data and data:FindFirstChild("Owner")
            local ok, val = pcall(function()
                return owner and owner.Value
            end)
            local mine = ok and val == uname
            local cosmetic = important:FindFirstChild("Cosmetic_Physical")
            if cosmetic then
                stripTree(cosmetic, hideVisual, CHUNK_OTHER, false)
            end
            if not mine then
                local plants = important:FindFirstChild("Plants_Physical")
                if plants then
                    stripTree(plants, hideVisual, CHUNK_OTHER, false)
                end
            end
        end
    end
end

local function lowLand(inst)
    if not inst or not inst.Parent then
        return
    end
    if SKIP_CLASS[inst.ClassName] then
        return
    end
    local n = inst.Name
    if n == "Item_String" or n == "Weight" or n == "Variant" then
        return
    end

    local c = inst.ClassName
    if FX_CLASSNAME[c] then
        disableFx(savedParticle, inst, ATTR_PARTICLE)
        if c == "ParticleEmitter" then
            pcall(function()
                inst:Clear()
            end)
        end
        return
    end
    if c == "Decal" or c == "Texture" then
        remember(savedParticle, inst, "Transparency", inst.Transparency)
        inst.Transparency = 1
        return
    end
    if PART_CLASS[c] then
        remember(savedParticle, inst, "Material", inst.Material)
        remember(savedParticle, inst, "MaterialVariant", inst.MaterialVariant)
        remember(savedParticle, inst, "Reflectance", inst.Reflectance)
        remember(savedParticle, inst, "CastShadow", inst.CastShadow)
        if inst.LocalTransparencyModifier ~= 0 then
            inst.LocalTransparencyModifier = 0
        end
        inst.CastShadow = false
        inst.Reflectance = 0
        pcall(function()
            inst.Material = Enum.Material.SmoothPlastic
            inst.MaterialVariant = ""
        end)
        pcall(function()
            remember(savedParticle, inst, "RenderFidelity", inst.RenderFidelity)
            inst.RenderFidelity = Enum.RenderFidelity.Performance
        end)
    end
end

local function hideFarmLand()
    local farms = workspace:FindFirstChild("Farm")
    if not farms then
        return
    end
    for _, farm in ipairs(farms:GetChildren()) do
        local list = farm:GetDescendants()
        local n = 0
        for i = 1, #list do
            local inst = list[i]
            if not isUnderPlantsPhysical(inst) then
                lowLand(inst)
            end
            n = n + 1
            if n == CHUNK_OTHER then
                n = 0
                task.wait()
                if not isParticleEnabled() then
                    return
                end
            end
        end
    end
end

local function lowMapFolders()
    for name in pairs(MAP_LOW) do
        local folder = workspace:FindFirstChild(name)
        if folder then
            stripTree(folder, lowLand, CHUNK_GARDEN, false)
        end
    end
end

local function hideMapFolders()
    for name in pairs(MAP_HIDE) do
        local folder = workspace:FindFirstChild(name)
        if folder then
            stripTree(folder, hideVisual, CHUNK_GARDEN, false)
        end
    end
    -- NPCs must stay visible (previously hidden in older lite mode)
    local npcs = workspace:FindFirstChild("NPCS")
    if npcs then
        for _, d in ipairs(npcs:GetDescendants()) do
            if PART_CLASS[d.ClassName] then
                d.LocalTransparencyModifier = 0
            elseif d.ClassName == "BillboardGui" or d.ClassName == "SurfaceGui" then
                d.Enabled = true
            elseif d.ClassName == "Decal" or d.ClassName == "Texture" then
                if d.Transparency >= 1 then
                    d.Transparency = 0
                end
            end
        end
    end
end

local function stripLighting()
    for _, d in ipairs(Lighting:GetDescendants()) do
        if not KEEP_LIGHTING_NAME[d.Name] and not d:IsA("Sky") and not d:IsA("Folder") then
            local ok, en = pcall(function()
                return d.Enabled
            end)
            if ok and type(en) == "boolean" then
                remember(savedParticle, d, "LightingEnabled", en)
                pcall(function()
                    d.Enabled = false
                end)
            end
        end
    end
end

local function stripParticleAll()
    applyGfx(true)
    stripLighting()
    hideMapFolders()
    lowMapFolders()
    hideFarmLand()
    hideOtherFarmsAndCosmetics()
    hideOtherCharacters()

    local n = 0
    for _, d in ipairs(workspace:GetDescendants()) do
        if not isParticleEnabled() then
            return
        end
        if isFxClass(d) then
            stripParticleOne(d)
        end
        n = n + 1
        if n % 400 == 0 then
            task.wait()
        end
    end

    for _, tag in ipairs(FX_TAGS) do
        local list = {}
        pcall(function()
            list = CollectionService:GetTagged(tag)
        end)
        for _, inst in ipairs(list) do
            if not isParticleEnabled() then
                return
            end
            stripParticleOne(inst)
        end
    end
end

local function restoreBag(bag, fn)
    for inst, rec in pairs(bag) do
        pcall(fn, inst, rec)
    end
    table.clear(bag)
end

local function hookListeners()
    if started then
        return
    end
    started = true

    local pendingGarden = {}
    local gardenFlushOn = false
    local function flushGardenPending()
        if not isGardenEnabled() then
            gardenFlushOn = false
            table.clear(pendingGarden)
            return
        end
        -- Jangan pairs()+wait: DescendantAdded isi key baru → "invalid key to 'next'".
        -- Jangan matikan gardenFlushOn di awal: flush kedua bisa jalan barengan.
        local n = 0
        while true do
            local inst = next(pendingGarden)
            if inst == nil then
                break
            end
            pendingGarden[inst] = nil
            if typeof(inst) == "Instance" and inst.Parent then
                pcall(stripGardenOne, inst, false)
            end
            n = n + 1
            if n % 60 == 0 then
                task.wait()
                if not isGardenEnabled() then
                    table.clear(pendingGarden)
                    gardenFlushOn = false
                    return
                end
            end
        end
        gardenFlushOn = false
        if next(pendingGarden) ~= nil then
            gardenFlushOn = true
            task.delay(0.4, flushGardenPending)
        end
    end

    local function onFarmDescendant(inst)
        if not inst then
            return
        end
        local c = inst.ClassName
        if isGardenEnabled() then
            if FX_CLASSNAME[c] or c == "Decal" or c == "Texture" then
                pcall(function()
                    inst:Destroy()
                end)
            else
                pendingGarden[inst] = true
                if not gardenFlushOn then
                    gardenFlushOn = true
                    task.delay(0.4, flushGardenPending)
                end
            end
        end
        if isParticleEnabled() then
            if FX_CLASSNAME[c] then
                task.defer(function()
                    if isParticleEnabled() then
                        stripParticleOne(inst)
                    end
                end)
            elseif not isUnderPlantsPhysical(inst) then
                task.defer(function()
                    if isParticleEnabled() then
                        lowLand(inst)
                    end
                end)
            end
        end
    end

    local farms = workspace:FindFirstChild("Farm")
    if farms then
        conns[#conns + 1] = farms.DescendantAdded:Connect(onFarmDescendant)
    else
        conns[#conns + 1] = workspace.ChildAdded:Connect(function(child)
            if child.Name ~= "Farm" then
                return
            end
            conns[#conns + 1] = child.DescendantAdded:Connect(onFarmDescendant)
            if isGardenEnabled() then
                task.defer(stripGardenAll)
            end
        end)
    end

    conns[#conns + 1] = workspace.DescendantAdded:Connect(function(inst)
        if not isParticleEnabled() then
            return
        end
        if isFxClass(inst) then
            task.defer(function()
                if isParticleEnabled() then
                    stripParticleOne(inst)
                end
            end)
            return
        end
        if isUnderPlantsPhysical(inst) then
            return
        end
        if isUnderNamed(inst, MAP_LOW) then
            task.defer(function()
                if isParticleEnabled() then
                    lowLand(inst)
                end
            end)
            return
        end
        if isUnderNamed(inst, MAP_HIDE) or isUnderNamed(inst, COSMETIC_HIDE) then
            task.defer(function()
                if isParticleEnabled() then
                    hideVisual(inst)
                end
            end)
        end
    end)

    conns[#conns + 1] = Players.PlayerAdded:Connect(function(plr)
        if plr == LP then
            return
        end
        plr.CharacterAdded:Connect(function(char)
            if isParticleEnabled() then
                task.defer(function()
                    if isParticleEnabled() then
                        stripTree(char, hideVisual, CHUNK_OTHER, false)
                    end
                end)
            end
        end)
    end)

    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP then
            conns[#conns + 1] = plr.CharacterAdded:Connect(function(char)
                if isParticleEnabled() then
                    task.defer(function()
                        if isParticleEnabled() then
                            stripTree(char, hideVisual, CHUNK_OTHER, false)
                        end
                    end)
                end
            end)
        end
    end

    conns[#conns + 1] = Lighting.DescendantAdded:Connect(function(inst)
        if not isParticleEnabled() then
            return
        end
        task.defer(function()
            if isParticleEnabled() then
                stripLighting()
            end
        end)
    end)

    for _, tag in ipairs(FX_TAGS) do
        local ok, sig = pcall(function()
            return CollectionService:GetInstanceAddedSignal(tag)
        end)
        if ok and sig then
            conns[#conns + 1] = sig:Connect(function(inst)
                task.defer(function()
                    if isGardenEnabled() then
                        stripGardenOne(inst, false)
                    end
                    if isParticleEnabled() then
                        stripParticleOne(inst)
                    end
                end)
            end)
        end
    end

    local okPlant, plantSig = pcall(function()
        return CollectionService:GetInstanceAddedSignal("PlantGenerated")
    end)
    if okPlant and plantSig then
        conns[#conns + 1] = plantSig:Connect(function(inst)
            if not isGardenEnabled() then
                return
            end
            task.defer(function()
                if isGardenEnabled() then
                    stripTree(inst, stripGardenOne, CHUNK_GARDEN, true)
                end
            end)
        end)
    end

    task.spawn(function()
        local my = stopToken
        while my == stopToken do
            task.wait(RESCAN_SEC)
            if isGardenEnabled() then
                local own = getOwnPlantsPhysical()
                if own then
                    pcall(restripGardenFx, own)
                end
            end
            if isParticleEnabled() then
                pcall(stripLighting)
                pcall(hideMapFolders)
                pcall(lowMapFolders)
                pcall(hideFarmLand)
            end
        end
    end)
end

function M.IsEnabled()
    return isGardenEnabled()
end

function M.IsParticlesEnabled()
    return isParticleEnabled()
end

function M.SetEnabled(on)
    on = (on == true)
    gardenOn = on
    G.REDUCE_GARDEN_FX_ENABLED = on
    _G.REDUCE_GARDEN_FX_ENABLED = on
    persistFlag("reduce_garden_fx", on)
    hookListeners()

    if on then
        applyCropVfx(true)
        task.spawn(function()
            pcall(stripGardenAll)
        end)
        return
    end

    restoreBag(savedGarden, restoreGardenOne)
    applyCropVfx(false)
end

function M.SetParticlesEnabled(on)
    on = (on == true)
    particleOn = on
    G.REDUCE_PARTICLES_ENABLED = on
    _G.REDUCE_PARTICLES_ENABLED = on
    persistFlag("reduce_particles", on)
    hookListeners()

    if on then
        applyCropVfx(true)
        applyPetVfx(true)
        task.spawn(function()
            pcall(stripParticleAll)
        end)
        return
    end

    restoreBag(savedParticle, restoreParticleOne)
    applyGfx(false)
    applyPetVfx(false)
    applyCropVfx(false)
end

function M.SyncFromState()
    local og, op = false, false
    local o = optTbl()
    if o then
        og = o.reduce_garden_fx == true
        op = o.reduce_particles == true
    end
    if G.REDUCE_GARDEN_FX_ENABLED == true then
        og = true
    end
    if G.REDUCE_PARTICLES_ENABLED == true then
        op = true
    end
    M.SetEnabled(og)
    M.SetParticlesEnabled(op)
end

G.GardenOptimizer = M
_G.GardenOptimizer = M

task.defer(function()
    pcall(M.SyncFromState)
end)

return M

