local function log(...)
    if M.DEBUG then
        print("[NilCooldownFixer]", ...)
    end
end

local function warnlog(...)
    if M.DEBUG then
        warn("[NilCooldownFixer]", ...)
    end
end

local function normUUID(u)
    if u == nil then return nil end
    local s = tostring(u)
    local core = s:match("{?([0-9a-fA-F%-]+)}?") or s
    if core == "" then return nil end
    return "{" .. core .. "}", core
end

-- NCF hanya sentuh pet PnP selected. Toggle OFF / list kosong = tidak equip/unequip.
local function getPnPSelectedMap()
    local env = (getgenv and getgenv()) or _G
    local st = (type(env.STATE) == "table" and env.STATE) or _G.STATE
    local ss = type(st) == "table" and st.swap_skill
    if type(ss) ~= "table" or ss.enabled ~= true then
        return nil
    end
    local selected = ss.selected
    if type(selected) ~= "table" then
        return nil
    end
    local map = {}
    local any = false
    for k, v in pairs(selected) do
        if v == true then
            local full, core = normUUID(k)
            if full and tostring(k) == full then
                map[full] = true
                if core then
                    map[core] = true
                end
                any = true
            end
        end
    end
    if not any then
        return nil
    end
    return map
end

local function isPnPSelected(uuid)
    local map = getPnPSelectedMap()
    if not map then
        return false
    end
    local full, core = normUUID(uuid)
    if full and map[full] == true then
        return true
    end
    if core and map[core] == true then
        return true
    end
    return false
end

local function lower(s)
    return string.lower(tostring(s or ""))
end

-- Time=inf / nan / huge = UI CD kosong (game kirim event tapi angka tidak usable)
local function isFiniteCdTime(n)
    return type(n) == "number"
        and n == n
        and n ~= math.huge
        and n ~= -math.huge
        and n > -1e12
        and n < 1e12
end

local function hasFiniteSkillTime(cd)
    if type(cd) ~= "table" then
        return false
    end
    if isFiniteCdTime(cd.minTime) then
        return true
    end
    if type(cd.numbers) == "table" then
        for _, n in ipairs(cd.numbers) do
            if isFiniteCdTime(n) then
                return true
            end
        end
    end
    return false
end

local function isCurrentlyEquipped(uuid)
    local full, core = normUUID(uuid)
    if not full then return false end

    local ok, data = pcall(function()
        return DataService:GetData()
    end)

    if not ok or type(data) ~= "table" then
        return false
    end

    local equipped =
        data.PetsData
        and data.PetsData.EquippedPets
        or {}

    for _, eqUuid in pairs(equipped) do
        local eFull, eCore = normUUID(eqUuid)

        if eFull == full or eCore == core then
            return true
        end
    end

    return false
end
