local function getToolPetType(uuid)
    return nil
end

local function getDatastoreRecord(uuid)
    local full = select(1, normUUID(uuid))
    if not full then return nil end

    local function fromBag(bag)
        if type(bag) ~= "table" then return nil end
        for id, rec in pairs(bag) do
            if select(1, normUUID(id)) == full then
                return rec
            end
        end
        return nil
    end

    if DataService then
        local ok, data = pcall(function()
            return DataService:GetData()
        end)
        if ok and type(data) == "table" then
            local rec = fromBag(data.PetsData and data.PetsData.PetInventory and data.PetsData.PetInventory.Data)
            if rec then return rec end
        end
    end

    if not ActivePetsService or type(ActivePetsService.GetPlayerDatastorePetData) ~= "function" then
        return nil
    end

    local ok, data = pcall(function()
        return ActivePetsService:GetPlayerDatastorePetData(LP.Name)
    end)

    if not ok or type(data) ~= "table" then
        return nil
    end

    return fromBag(data.PetInventory and data.PetInventory.Data)
end

local function getPetType(uuid, st)
    if type(st) == "table" then
        local tries = {
            st.PetType,
            st.petType,
            st.Type,
            st.Name,
            st.PetName,

            st.PetData and st.PetData.PetType,
            st.PetData and st.PetData.Type,
            st.PetData and st.PetData.Name,

            st.Data and st.Data.PetType,
            st.Data and st.Data.Type,
            st.Data and st.Data.Name,
        }

        for _, v in ipairs(tries) do
            if type(v) == "string" and v ~= "" then
                return v
            end
        end
    end

    local rec = getDatastoreRecord(uuid)
    if type(rec) == "table" then
        local pd = rec.PetData or rec.Data or rec

        return
            rec.PetType
            or rec.petType
            or rec.Type
            or rec.Name
            or pd.PetType
            or pd.Type
            or pd.Name
            or getToolPetType(uuid)
            or "UNKNOWN"
    end

    return getToolPetType(uuid) or "UNKNOWN"
end

local function isFavoritePet(uuid, st)
    if type(st) == "table" then
        local pd = st.PetData or st.Data or st

        if st.Favorite == true or st.Favorited == true then return true end
        if st.IsFavorite == true or st.IsFavorited == true then return true end
        if pd.Favorite == true or pd.Favorited == true then return true end
        if pd.IsFavorite == true or pd.IsFavorited == true then return true end
    end

    local rec = getDatastoreRecord(uuid)
    if type(rec) ~= "table" then
        return false
    end

    local pd = rec.PetData or rec.Data or rec

    return rec.Favorite == true
        or rec.Favorited == true
        or rec.IsFavorite == true
        or rec.IsFavorited == true
        or pd.Favorite == true
        or pd.Favorited == true
        or pd.IsFavorite == true
        or pd.IsFavorited == true
end

--------------------------------------------------
-- PET COOLDOWN UPDATED CACHE
--------------------------------------------------
local CD_CACHE = {}
local CD_LAST_UPDATE = {}
local CD_CONN = nil
local PREEMPT_LAST = {}
local CD_MAX_SEEN = {} -- [uuidFull][passiveName] = total CD skill (estimasi)

local SKILL_PET_KNOWN = {}

local function registryHasCooldown(passiveName)
    local info = PassiveRegistry[tostring(passiveName or "")]
    local states = type(info) == "table" and info.States
    return type(states) == "table" and type(states.Cooldown) == "table"
end

local function isMutationCooldown(passiveName)
    passiveName = tostring(passiveName or "")
    return passiveName:find("Pet Mutation", 1, true) ~= nil
end

local function isPetSkillCooldown(passiveName)
    passiveName = tostring(passiveName or "")
    if passiveName == "" then return false end
    if isMutationCooldown(passiveName) then return false end
    return registryHasCooldown(passiveName)
end

local EXPECT_SKILL_CACHE = {}
local LAST_INVOKE_AT = {}
local LAST_INVOKE_DATA = {}

local function petTypeExpectsSkillCd(petType)
    local pt = tostring(petType or "")
    if pt == "" or pt == "UNKNOWN" then
        return false
    end
    if EXPECT_SKILL_CACHE[pt] ~= nil then
        return EXPECT_SKILL_CACHE[pt]
    end
    local info = type(PetList) == "table" and PetList[pt]
    local expect = false
    if type(info) == "table" and type(info.Passives) == "table" then
        for _, pname in ipairs(info.Passives) do
            if isPetSkillCooldown(pname) then
                expect = true
                break
            end
        end
    end
    EXPECT_SKILL_CACHE[pt] = expect
    return expect
end

local function invokeCooldown(uuid)
    if not (GetPetCooldownRF and type(GetPetCooldownRF.InvokeServer) == "function") then
        return LAST_INVOKE_DATA[select(1, normUUID(uuid) or "")]
    end
    local full = select(1, normUUID(uuid))
    if not full then return nil end
    local now = os.clock()
    if (now - (tonumber(LAST_INVOKE_AT[full]) or 0)) < 2 then
        return LAST_INVOKE_DATA[full]
    end
    LAST_INVOKE_AT[full] = now
    local ok, cds = pcall(function()
        return GetPetCooldownRF:InvokeServer(uuid)
    end)
    if ok and type(cds) == "table" then
        LAST_INVOKE_DATA[full] = cds
        return cds
    end
    return LAST_INVOKE_DATA[full]
end

local function getRegistryMaxCd(passiveName)
    local info = PassiveRegistry[tostring(passiveName or "")]
    if type(info) ~= "table" then return nil end

    local cdState = info.States and info.States.Cooldown
    if type(cdState) ~= "table" then return nil end

    return tonumber(cdState.Duration)
        or tonumber(cdState.Time)
        or tonumber(cdState.Max)
        or tonumber(cdState.Cooldown)
        or tonumber(cdState.Length)
end

local function trackCdMaxSeen(full, data)
    if not full or type(data) ~= "table" then return end

    CD_MAX_SEEN[full] = CD_MAX_SEEN[full] or {}
    local map = CD_MAX_SEEN[full]

    for _, item in pairs(data) do
        if type(item) == "table" then
            local passive = tostring(item.Passive or "")
            local t = tonumber(item.Time)

            if isPetSkillCooldown(passive) and t ~= nil and t > 0 then
                local regMax = getRegistryMaxCd(passive)
                local prev = tonumber(map[passive]) or 0
                map[passive] = math.max(prev, t, regMax or 0)
            end
        end
    end
end

local function resetCdMaxSeen(uuid)
    local full = select(1, normUUID(uuid))
    if full then
        CD_MAX_SEEN[full] = nil
    end
end

local function inspectSkillCooldown(data)
    local minTime = nil
    local ready = false
    local hasSkill = false
    local texts = {}
    local numbers = {}
    local passives = {}
    local skillCount = 0

    if type(data) ~= "table" then
        return nil, false, false, texts, numbers, passives, skillCount
    end

    for _, item in pairs(data) do
        if type(item) == "table" then
            local passive = tostring(item.Passive or item.Skill or "")
            local t = tonumber(item.Time)
            if not isFiniteCdTime(t) then
                t = nil
            end

            if isPetSkillCooldown(passive) then
                hasSkill = true
                passives[passive] = true
                skillCount += 1

                if t ~= nil then
                    table.insert(numbers, t)

                    if t <= 0 then
                        ready = true
                        table.insert(texts, "READY")
                    else
                        table.insert(texts, tostring(t) .. "s")
                        minTime = minTime and math.min(minTime, t) or t
                    end
                end
            end
        end
    end

    return minTime, hasSkill, ready, texts, numbers, passives, skillCount
end

local function readCooldownFromEvent(uuid)
    local full, core = normUUID(uuid)
    if not full then
        return {
            ok = false,
            ready = false,
            reason = "BAD_UUID",
            hasSkillCooldown = false,
            texts = {},
            numbers = {},
            minTime = nil,
            raw = nil,
            skillCount = 0,
        }
    end

    local data = CD_CACHE[full] or CD_CACHE[core] or CD_CACHE[tostring(uuid)]

    if type(data) ~= "table" then
        return {
            ok = false,
            ready = false,
            reason = "NO_EVENT_CACHE",
            hasSkillCooldown = SKILL_PET_KNOWN[full] == true,
            texts = {},
            numbers = {},
            minTime = nil,
            raw = nil,
            skillCount = 0,
        }
    end

    local minTime, hasSkill, ready, texts, numbers, passives, skillCount =
        inspectSkillCooldown(data)

    trackCdMaxSeen(full, data)

    if hasSkill then
        SKILL_PET_KNOWN[full] = true
        SKILL_PET_KNOWN[core] = true
    end

if not hasSkill then
    return {
        ok = true,
        ready = false,
        reason = "NO_PET_SKILL_COOLDOWN",
        hasSkillCooldown = SKILL_PET_KNOWN[full] == true,
        texts = texts,
        numbers = {},
        minTime = nil,
        passives = passives,
        raw = data,
        skillCount = skillCount,
    }
end

    return {
        ok = true,
        ready = ready == true,
        reason = ready and "READY" or "COOLDOWN_RUNNING",
        hasSkillCooldown = true,
        texts = texts,
        numbers = numbers,
        minTime = minTime,
        passives = passives,
        raw = data,
        skillCount = skillCount,
    }
end

local function countSkillCooldowns(cd)
    if type(cd) ~= "table" then return 0 end
    if type(cd.skillCount) == "number" and cd.skillCount > 0 then
        return cd.skillCount
    end
    if type(cd.passives) == "table" then
        local n = 0
        for _ in pairs(cd.passives) do n += 1 end
        return n
    end
    if type(cd.numbers) == "table" then
        return #cd.numbers
    end
    return 0
end

local function shouldSkipUnfavReequip(fav)
    if fav == true then return false end
    return M.SKIP_REEQUIP_UNFAV == true or M.SKIP_REEQUIP_UNFAV_DUAL == true
end

local function shouldPreemptiveDualSkill(cd, fav, uuid)
    if M.DUAL_SKILL_PREEMPTIVE ~= true then
        return false, nil
    end

    -- hanya pet UNFAV
    if fav == true then
        return false, nil
    end

    if cd.hasSkillCooldown ~= true then
        return false, nil
    end

    local skillCount = countSkillCooldowns(cd)
    local minNeeded = tonumber(M.MIN_SKILL_COUNT) or 2
    if skillCount < minNeeded then
        return false, nil
    end

    if cd.ready == true then
        return true, "UNFAV_DUAL_SKILL_READY_X" .. tostring(skillCount)
    end

    local full = select(1, normUUID(uuid))
    local raw = cd.raw
    if not full or type(raw) ~= "table" then
        return false, nil
    end

    local ratio = tonumber(M.PREEMPTIVE_RATIO) or 0.5
    if ratio < 0.05 then ratio = 0.05 end
    if ratio > 0.95 then ratio = 0.95 end

    local maxMap = CD_MAX_SEEN[full] or {}
    local bestPassive, bestRemain, bestMax, bestThreshold = nil, nil, nil, nil

    for _, item in pairs(raw) do
        if type(item) == "table" then
            local passive = tostring(item.Passive or "")
            local remain = tonumber(item.Time)

            if isPetSkillCooldown(passive) and remain ~= nil and remain > 0 then
                local maxCd = tonumber(maxMap[passive]) or getRegistryMaxCd(passive)
                if maxCd and maxCd > 0 then
                    local threshold = maxCd * ratio
                    if remain <= threshold then
                        if not bestRemain or remain < bestRemain then
                            bestPassive = passive
                            bestRemain = remain
                            bestMax = maxCd
                            bestThreshold = threshold
                        end
                    end
                end
            end
        end
    end

    if bestPassive then
        return true, string.format(
            "UNFAV_DUAL_SKILL_%d%%_%s_%.1fs<=%.1fs/%.1fs",
            math.floor(ratio * 100 + 0.5),
            bestPassive,
            bestRemain,
            bestThreshold,
            bestMax
        )
    end

    return false, nil
end

local function canPreemptiveReequip(uuid)
    local full = normUUID(uuid)
    if not full then return false end

    local cooldown = tonumber(M.PREEMPTIVE_REEQUIP_COOLDOWN) or 4
    local last = PREEMPT_LAST[full] or 0
    return (os.clock() - last) >= cooldown
end

local function markPreemptiveReequip(uuid)
    local full = normUUID(uuid)
    if full then
        PREEMPT_LAST[full] = os.clock()
        resetCdMaxSeen(full)
    end
end

--------------------------------------------------
-- EQUIP / UNEQUIP
--------------------------------------------------
function M.Unequip(uuid)
    local full = normUUID(uuid)
    if not full then return false end

    local ok, err = pcall(function()
        PetsServiceRE:FireServer("UnequipPet", full)
    end)

    if not ok then
        warnlog("UNEQUIP FAIL:", full, err)
        return false
    end

    log("UNEQUIP OK:", full)
    return true
end

function M.Equip(uuid)
    local full = normUUID(uuid)
    if not full then return false end

    local ok, err = pcall(function()
        PetsServiceRE:FireServer("EquipPet", full)
    end)

    if not ok then
        warnlog("EQUIP FAIL:", full, err)
        return false
    end

    log("EQUIP OK:", full)
    return true
end

function M.ReEquip(uuid)
    local full = normUUID(uuid)
    if not full then return false end
    if not isPnPSelected(full) then
        return false
    end

    warnlog("RE-EQUIP START:", full)

    M.Unequip(full)
    task.wait(M.UNEQUIP_DELAY)
    M.Equip(full)
    task.wait(M.EQUIP_DELAY)

    warnlog("RE-EQUIP DONE:", full)
    return true
end

local function isCooldownBroken(cd)
    if type(cd) ~= "table" then
        return true
    end

    if cd.hasSkillCooldown ~= true then
        return false
    end

    if type(cd.numbers) ~= "table" then
        return true
    end

    if #cd.numbers <= 0 then
        return true
    end

    for _, n in ipairs(cd.numbers) do
        if isFiniteCdTime(n) then
            return false
        end
    end

    return true
end

--------------------------------------------------
-- BROKEN COUNTER
--------------------------------------------------
local BROKEN_COUNT = {}
local MISSING_FIX_AT = {}
local MISSING_FIX_N = {}
M.BROKEN_LIMIT = 3

local function addBroken(uuid)
    local full = normUUID(uuid)
    if not full then
        return 0
    end

    BROKEN_COUNT[full] = (BROKEN_COUNT[full] or 0) + 1
    return BROKEN_COUNT[full]
end

local function resetBroken(uuid)
    local full = normUUID(uuid)
    if not full then
        return
    end

    BROKEN_COUNT[full] = 0
end

local function tryFixPet(uuid, st, options)
    options = options or {}
    if not isPnPSelected(uuid) then
        return false
    end
    local doReequip = options.reequip ~= false

    if not isCurrentlyEquipped(uuid) then
        return false
    end

    local petType = getPetType(uuid, st)
    local fav = isFavoritePet(uuid, st)
    local full, core = normUUID(uuid)
    local hadEvent = type(CD_CACHE[full]) == "table" or type(CD_CACHE[core]) == "table"
    local cd = readCooldownFromEvent(uuid)
    local expectSkill = petTypeExpectsSkillCd(petType)
    local missingUi = false

    if (not hadEvent)
    or cd.reason == "NO_EVENT_CACHE"
    or cd.hasSkillCooldown ~= true
    or not hasFiniteSkillTime(cd)
    then
        local live = invokeCooldown(uuid)
        if type(live) == "table" then
            local minTime, hasSkill, ready = inspectSkillCooldown(live)
            if hasSkill and ready then
                CD_CACHE[full] = live
                if core then CD_CACHE[core] = live end
                return false
            end
            if hasSkill and isFiniteCdTime(minTime) and minTime > 0 then
                missingUi = true
            elseif hasSkill and not isFiniteCdTime(minTime) then
                missingUi = true
            elseif expectSkill and not hasSkill then
                missingUi = true
            end
        elseif expectSkill then
            missingUi = true
        end
    end

    if cd.hasSkillCooldown == true and not hasFiniteSkillTime(cd) then
        missingUi = true
    end

    if cd.hasSkillCooldown ~= true and not missingUi then
        return false
    end

    local skillCount = countSkillCooldowns(cd)
    if (not missingUi) and shouldSkipUnfavReequip(fav) then
        log(
            "SKIP UNFAV (no re-equip):",
            petType,
            uuid,
            "skills=" .. tostring(skillCount),
            "ready=" .. tostring(cd.ready),
            "minTime=" .. tostring(cd.minTime)
        )
        return false
    end

    local shouldFix = false
    local fixReason = nil
    local brokenCount = 0
    local brokenCD = (not missingUi) and isCooldownBroken(cd)

    if missingUi or brokenCD then
        brokenCount = addBroken(uuid)
    else
        resetBroken(uuid)
    end

    local preemptive, preemptReason = shouldPreemptiveDualSkill(cd, fav, uuid)
    if preemptive then
        shouldFix = true
        fixReason = preemptReason
    elseif missingUi and brokenCount >= (tonumber(M.MISSING_CONFIRM) or 2) then
        shouldFix = true
        fixReason = "MISSING_SKILL_CD"
    elseif fav and brokenCD and brokenCount >= M.BROKEN_LIMIT then
        shouldFix = true
        fixReason = "FAV_BROKEN_SKILL_CD_X" .. tostring(brokenCount)
    end

    if missingUi and shouldFix then
        local n = tonumber(MISSING_FIX_N[full]) or 0
        local last = tonumber(MISSING_FIX_AT[full]) or 0
        if n >= (tonumber(M.MISSING_REQUIP_MAX) or 4) then
            return false
        end
        if (os.clock() - last) < (tonumber(M.MISSING_REQUIP_SEC) or 8) then
            return false
        end
        MISSING_FIX_AT[full] = os.clock()
        MISSING_FIX_N[full] = n + 1
    end

    if not shouldFix then
        log(
            "OK:",
            petType,
            uuid,
            "fav=" .. tostring(fav),
            "ready=" .. tostring(cd.ready),
            "broken=" .. tostring(brokenCD),
            "skills=" .. tostring(countSkillCooldowns(cd)),
            "minTime=" .. tostring(cd.minTime)
        )
        return false
    end

    if preemptive and not canPreemptiveReequip(uuid) then
        warnlog("SKIP PREEMPTIVE COOLDOWN:", petType, uuid, fixReason)
        return false
    end

    warnlog(
        "FIX CHECK:",
        petType,
        uuid,
        "fav=" .. tostring(fav),
        "reason=" .. tostring(fixReason),
        "skills=" .. tostring(countSkillCooldowns(cd)),
        "cdReason=" .. tostring(cd.reason),
        "minTime=" .. tostring(cd.minTime)
    )

    if not doReequip then
        return true
    end

    if isCurrentlyEquipped(uuid) then
        M.ReEquip(uuid)
        resetBroken(uuid)
        if preemptive then
            markPreemptiveReequip(uuid)
        end
        return true
    end

    warnlog("SKIP FIX - NOT EQUIPPED:", petType, uuid)
    resetBroken(uuid)
    return false
end

function M.CheckPreemptive(uuid)
    if M.DUAL_SKILL_PREEMPTIVE ~= true then
        return false
    end

    local full = normUUID(uuid)
    if not full then return false end

    local myPets = getMyActivePets()
    local st = myPets[full] or myPets[select(2, normUUID(uuid))] or myPets[tostring(uuid)]
    if type(st) ~= "table" then
        for rawUuid, petSt in pairs(myPets) do
            local rawFull = select(1, normUUID(rawUuid))
            if rawFull == full then
                st = petSt
                uuid = rawUuid
                break
            end
        end
    end

    return tryFixPet(uuid, st, { reequip = true })
end

local function startCooldownListener()
    if CD_CONN then
        return
    end

    if not PetCooldownsUpdated then
        local ge = ReplicatedStorage:FindFirstChild("GameEvents")
        PetCooldownsUpdated = ge and (ge:FindFirstChild("PetCooldownsUpdated") or ge:WaitForChild("PetCooldownsUpdated", 3))
    end
    if not PetCooldownsUpdated then
        return
    end

    CD_CONN = PetCooldownsUpdated.OnClientEvent:Connect(function(uuid, data)
        local full, core = normUUID(uuid)
        if not full then return end

        local _, hasSkill = inspectSkillCooldown(data)
        if not hasSkill then
            local prev = CD_CACHE[full] or CD_CACHE[core]
            if type(prev) == "table" then
                local _, prevHas = inspectSkillCooldown(prev)
                if prevHas then
                    return
                end
            end
        end

        CD_CACHE[full] = data
        CD_CACHE[core] = data
        CD_LAST_UPDATE[full] = os.clock()
        CD_LAST_UPDATE[core] = os.clock()
        trackCdMaxSeen(full, data)
        if hasSkill then
            MISSING_FIX_N[full] = nil
            MISSING_FIX_AT[full] = nil
            if core then
                MISSING_FIX_N[core] = nil
                MISSING_FIX_AT[core] = nil
            end
        end
        if M.DEBUG then
            local minTime, hasSkill, ready, _, _, _, skillCount = inspectSkillCooldown(data)
            print(
                "[NilCooldownFixer-CD]",
                full,
                "skills=" .. tostring(skillCount),
                "hasSkill=" .. tostring(hasSkill),
                "ready=" .. tostring(ready),
                "minTime=" .. tostring(minTime)
            )
        end

        if running and M.DUAL_SKILL_PREEMPTIVE == true then
            pcall(function()
                M.CheckPreemptive(full)
            end)
        end
    end)

    warnlog("PetCooldownsUpdated listener connected")
end

local function stopCooldownListener()
    if CD_CONN then
        CD_CONN:Disconnect()
        CD_CONN = nil
    end
end

--------------------------------------------------
-- SCAN ONCE
--------------------------------------------------
function M.ScanOnce(options)
    options = options or {}
    if not getPnPSelectedMap() then
        return true
    end
    local myPets = getMyActivePets()

    for rawUuid, st in pairs(myPets) do
        if isPnPSelected(rawUuid) then
            tryFixPet(rawUuid, st, options)
        end
    end

    return true
end
--------------------------------------------------
-- START / STOP
--------------------------------------------------

function M.Start(interval)
    if running then
        return false, "already running"
    end

    running = true
    interval =  M.SCAN_INTERVAL

    startCooldownListener()

    task.spawn(function()
        while running do
            local ok, err = pcall(function()
                M.ScanOnce({
                    reequip = true,
                })
            end)

            if not ok then
                warn("[NilCooldownFixer] SCAN ERROR:", err)
            end

            task.wait(interval)
        end
    end)

    warnlog("STARTED interval=", interval)
    return true
end

function M.Stop(force)
    if force ~= true then
        warnlog("STOP skipped (keep running)")
        return false
    end
    running = false
    stopCooldownListener()
    warnlog("STOPPED")
    return true
end

function M.IsRunning()
    return running == true
end

function M.GetCooldown(uuid)
    return readCooldownFromEvent(uuid)
end

function M.ClearCache()
    table.clear(CD_CACHE)
    table.clear(CD_LAST_UPDATE)
    table.clear(CD_MAX_SEEN)
    warnlog("CACHE CLEARED")
end

