        required = false,
    },
}

local STATE_URL = "https://golaspay.net/getsc_verify/mainuigh9rvgdKF1ARNbULXgzOa64OBso4PLw9I1793489665__yt0TtcgTKE714"

----------------------------------------------------------------
-- HTTP / METHOD HELPERS
----------------------------------------------------------------
debuglog("BOOT_START", "retry=", BOOT_RETRY, "stateRetry=", STATE_RETRY)

local function httpRequest(url)
    local req =
        (syn and syn.request) or
        (http and http.request) or
        http_request or
        (fluxus and fluxus.request) or
        request

    if req then
        debuglog("HTTP_REQUEST", url)
        local res = req({
            Url = url,
            Method = "GET",
        })
        if not res then
            error("no response")
        end
        return res.Body or res.body or ""
    end

    debuglog("HTTP_GET_FALLBACK", url)
    return game:HttpGet(url)
end

local function callMethod(mod, names, ...)
    if type(mod) ~= "table" then
        return false, "module not table"
    end

    for _, name in ipairs(names) do
        local fn = mod[name]
        if type(fn) == "function" then
            local ok, res = pcall(fn, mod, ...)
            if ok then
                return true, res
            end

            ok, res = pcall(fn, ...)
            if ok then
                return true, res
            end

            return false, res
        end
    end

    return false, "method not found"
end

local function moduleIsRunning(mod)
    if type(mod) ~= "table" then
        return false
    end
    if type(mod.IsRunning) == "function" then
        local ok, v = pcall(mod.IsRunning, mod)
        if ok then return v == true end
        ok, v = pcall(mod.IsRunning)
        if ok then return v == true end
    end
    return mod.running == true
end

local function moduleStart(mod, ...)
    if type(mod) ~= "table" then
        return false
    end
    if moduleIsRunning(mod) then
        return true
    end
    local ok = callMethod(mod, { "Start", "start" }, ...)
    return ok == true
end

local function moduleStop(mod, reason)
    if type(mod) ~= "table" then
        return false
    end
    local ok = callMethod(mod, { "Stop", "stop" }, reason)
    return ok == true
end

local function hasAnyTrue(map)
    if type(map) ~= "table" then
        return false
    end
    for _, v in pairs(map) do
        if v == true then
            return true
        end
    end
    return false
end

local function pickEnvState()
    local env = (getgenv and getgenv()) or _G
    local s = rawget(_G, "STATE") or rawget(env, "STATE")
    if type(s) == "table" then
        return s
    end
    return nil
end

local function wireStateModule(mod, state)
    local env = (getgenv and getgenv()) or _G

    if type(state) == "table" then
        G.STATE = state
        _G.STATE = state
        env.STATE = state
    end

    if type(mod) == "table" then
        G.State = mod
        _G.State = mod
        env.State = mod

        if type(_G.autoSave) ~= "function" then
            local saveFn = mod.save or mod.Save
            if type(saveFn) == "function" then
                _G.autoSave = function()
                    return saveFn(mod)
                end
                G.autoSave = _G.autoSave
                env.autoSave = _G.autoSave
            end
        end
    end
end

----------------------------------------------------------------
-- LOAD STATE EARLY
----------------------------------------------------------------
local StateModule
local STATE

local function loadStateOnce()
    debuglog("STATE_BEGIN")
    local okBody, bodyOrErr = pcall(httpRequest, STATE_URL)
    if not okBody or type(bodyOrErr) ~= "string" or bodyOrErr == "" then
        return false, "state http failed: " .. tostring(bodyOrErr)
    end

    local okLS, chunkOrErr = pcall(loadstring, bodyOrErr)
    if not okLS or type(chunkOrErr) ~= "function" then
        return false, "state loadstring failed: " .. tostring(chunkOrErr)
    end

    local okRun, modOrErr = pcall(chunkOrErr)
    if not okRun or type(modOrErr) ~= "table" then
        return false, "state run failed / bukan table: " .. tostring(modOrErr)
    end

    local mod = modOrErr
    local state

    -- state.lua sekarang auto-load di akhir; tetap panggil load() + fallback ke env
    local loadFn = mod.load or mod.Load
    if type(loadFn) == "function" then
        local okLoad, result = pcall(function()
            return loadFn(mod)
        end)
        if okLoad and type(result) == "table" then
            state = result
        else
            state = pickEnvState()
            if type(state) ~= "table" then
                return false, "State.load gagal: " .. tostring(result)
            end
            warnlog("State.load error, pakai STATE dari auto-load:", tostring(result))
        end
    else
        state = mod.STATE or mod.state or pickEnvState() or mod
    end

    if type(state) ~= "table" then
        return false, "state result bukan table"
    end

    debuglog("STATE_OK")
    return true, mod, state
end

LOADER.SetProgress(0.05, "Loading state early...")

for attempt = 1, STATE_RETRY do
    LOADER.SetInfo(("Loading state.lua early (%d/%d)..."):format(attempt, STATE_RETRY))

    local ok, modOrErr, state = loadStateOnce()
    if ok then
        StateModule = modOrErr
        STATE = state
        wireStateModule(StateModule, STATE)
        break
    end

    debuglog("STATE_FAIL", "attempt", attempt, tostring(modOrErr))
    warnlog("State load gagal:", tostring(modOrErr))
    task.wait(STATE_RETRY_DELAY)
end

if type(STATE) ~= "table" then
    STATE = pickEnvState()
end

if type(STATE) ~= "table" then
    STATE = {
        autoKgOn = false,
        onlyGBXP = false,
        skipFavorited = true,
        skipMutated = false,
        onlyAboveTarget = false,
        autoHatchOn = false,
        autoBuySeeds = false,
        rejoin = {},
        webhook = {},
    }
    warnlog("State fallback dipakai karena state.lua gagal load")
end

wireStateModule(StateModule, STATE)
debuglog("STATE_ASSIGNED_EARLY", type(STATE))

