local function waitGameData()
    local RS = game:GetService("ReplicatedStorage")

    LOADER.SetProgress(0.10, "Waiting game data...")
    LOADER.SetInfo("Menunggu ReplicatedStorage...")

    local mods = waitChild(RS, "Modules", GAME_DATA_WAIT)
    waitChild(RS, "Data", GAME_DATA_WAIT)
    local ge = waitChild(RS, "GameEvents", GAME_DATA_WAIT)

    if not mods then
        warnlog("ReplicatedStorage.Modules belum siap. Module akan di-retry.")
    else
        if not waitChild(mods, "DataService", 15) then
            warnlog("Modules.DataService belum siap.")
        end
        waitChild(mods, "PetServices", 15)
    end

    if not ge then
        warnlog("ReplicatedStorage.GameEvents belum siap. Module akan di-retry.")
    else
        waitChild(ge, "GetPetCooldown", 10)
        waitChild(ge, "PetsService", 10)
        waitChild(ge, "PetCooldownsUpdated", 10)
    end

    if LP then
        waitChild(LP, "Backpack", 8)
    end
end

waitGameData()

----------------------------------------------------------------
-- LOAD MODULE WITH RETRY
----------------------------------------------------------------
local HARD_REQUIRED = {
    MainUI = true,
    AutoKgTabs = true,
    MiscTabs = true,
    PetListView = true,
}

local FailedModules = {}

local function runWithTimeout(fn, timeoutSec, timeoutMsg)
    local box = { done = false }

    task.spawn(function()
        box.ok, box.res = pcall(fn)
        box.done = true
    end)

    local t0 = os.clock()
    while not box.done do
        if os.clock() - t0 > timeoutSec then
            return false, timeoutMsg or "timeout"
        end
        RunService.Heartbeat:Wait()
    end

    if not box.ok then
        return false, box.res
    end

    return true, box.res
end

local function runFactory(def)
    local okRun, res = runWithTimeout(
        def.factory,
        FACTORY_TIMEOUT,
        "factory timeout (WaitForChild/require hung)"
    )
    if not okRun then
        return false, "factory error: " .. tostring(res)
    end
    if type(res) ~= "table" then
        return false, "factory result bukan table: " .. tostring(typeof and typeof(res) or type(res))
    end
    return true, res
end

local function runUrl(def)
    local okBody, bodyOrErr = pcall(httpRequest, def.url)
    if not okBody or type(bodyOrErr) ~= "string" or bodyOrErr == "" then
        return false, "http failed: " .. tostring(bodyOrErr)
    end

    local okLS, chunkOrErr = pcall(loadstring, bodyOrErr)
    if not okLS or type(chunkOrErr) ~= "function" then
        return false, "loadstring failed: " .. tostring(chunkOrErr)
    end

    local okRun, res = runWithTimeout(chunkOrErr, FACTORY_TIMEOUT, "runtime timeout (WaitForChild/require hung)")
    if not okRun then
        return false, "chunk run failed: " .. tostring(res)
    end
    if type(res) ~= "table" then
        return false, "url result bukan table: " .. tostring(typeof and typeof(res) or type(res))
    end

    return true, res
end

local function loadOneModule(def)
    local lastErr = "unknown"
    debuglog("MODULE_BEGIN", def and def.key, def and def.name)

    for attempt = 1, BOOT_RETRY do
        LOADER.SetInfo(("Loading %s (%d/%d)..."):format(tostring(def.name), attempt, BOOT_RETRY))

        local ok, resultOrErr

        if type(def.factory) == "function" then
            ok, resultOrErr = runFactory(def)
        elseif type(def.url) == "string" and def.url ~= "" then
            ok, resultOrErr = runUrl(def)
        else
            ok = false
            resultOrErr = "module tidak punya factory/url"
        end

        if ok and type(resultOrErr) == "table" then
            debuglog("MODULE_OK", def.key, def.name, "attempt", attempt)
            return true, resultOrErr
        end

        lastErr = tostring(resultOrErr)
        debuglog("MODULE_FAIL", def.key, def.name, "attempt", attempt, "err", lastErr)
        warnlog(("Load gagal %s attempt %d/%d: %s"):format(
            tostring(def.name),
            attempt,
            BOOT_RETRY,
            lastErr
        ))

        if attempt < BOOT_RETRY then
            task.wait(RETRY_DELAY)
        end
    end

    debuglog("MODULE_DEAD", def and def.key, def and def.name, lastErr)
    return false, lastErr
end

local Loaded = {}

