local function loadModuleSet(label, filterFn, progressStart, progressSpan)
    local list = {}
    for _, def in ipairs(MODULE_DEFS) do
        if filterFn(def) then
            list[#list + 1] = def
        end
    end

    for i, def in ipairs(list) do
        local p = progressStart + (progressSpan * (i - 1) / math.max(#list, 1))
        LOADER.SetProgress(p, label .. ": " .. tostring(def.name) .. "...")
        debuglog("MODULE_QUEUE", label, i .. "/" .. #list, def.key, def.name)

        local ok, modOrErr = loadOneModule(def)
        if ok then
            Loaded[def.key] = modOrErr
        else
            FailedModules[#FailedModules + 1] = def
            if HARD_REQUIRED[def.key] then
                failBoot(("required module failed: %s | %s"):format(tostring(def.name), tostring(modOrErr)))
            else
                warnlog(("Skip module %s (akan di-retry): %s"):format(tostring(def.name), tostring(modOrErr)))
            end
        end
    end
end

