            env.AutoCraftLoop = AC
            _G.AutoCraftLoop  = AC

            if type(AC.SyncFromGlobals) == "function" then
                pcall(AC.SyncFromGlobals)
            elseif type(AC.SetEnabled) == "function" then
                pcall(function() AC.SetEnabled(env.AUTO_CRAFT_ENABLED == true) end)
            end
        end
    end

    -- AutoFeed
    do
        local Feed = rawget(_G, "AutoFeed") or rawget(env, "AutoFeed")
            or rawget(_G, "AutoKGFeed") or rawget(env, "AutoKGFeed")
            or FeedMod

        if type(Feed) == "table" then
            env.AutoFeed = Feed
            _G.AutoFeed  = Feed
            if type(Feed.ApplyConfig) == "function" then
                pcall(Feed.ApplyConfig, Feed)
            elseif type(Feed.SetEnabled) == "function" then
                local on = type(env.AUTO_FEED) == "table" and (env.AUTO_FEED.enabled == true)
                pcall(function() Feed:SetEnabled(on) end)
            end
        end
    end

    -- CollectFruit
