            if type(CF.SetEnabled) == "function" then
                pcall(function() CF.SetEnabled(AUTO_COLLECT_FRUIT_ENABLED == true) end)
            elseif (AUTO_COLLECT_FRUIT_ENABLED == true) and type(CF.Start) == "function" then
                pcall(CF.Start)
