-- Auto Start KG on rejoin.
task.defer(function()
    task.wait(0.25)
    if _G.__AUTOKG_AUTOSTART_DONE then return end
    _G.__AUTOKG_AUTOSTART_DONE = true

    if AUTO_START_KG_ON_REJOIN ~= true then return end
    moduleStart(AutoKGLoop, tostring(_G.GBXP_STAGE_MODE or "AUTO"))
end)

-- SwapSkill auto-start: retry beberapa kali karena state/UI kadang telat sync.
-- Enable OFF anywhere (STATE vs G.swap_skill) wins — never boot PnP from a stale true.
task.defer(function()
    local function pnpWantOn()
        local env = (getgenv and getgenv()) or _G
        local st = STATE and STATE.swap_skill
        local gs = rawget(env, "swap_skill") or rawget(_G, "swap_skill")
        if type(st) == "table" and st.enabled ~= true then
            return false
        end
        if type(gs) == "table" and gs ~= st and gs.enabled ~= true then
            return false
        end
        local ss = (type(st) == "table" and st) or (type(gs) == "table" and gs) or nil
        return ss and ss.enabled == true and hasAnyTrue(ss.selected)
    end

    for i = 1, 8 do
        local okOn = pnpWantOn()
        debuglog("SWAP_BOOT_TRY", i, "enabled=", okOn)

        if okOn then
            debuglog("AUTOSTART_SWAPSKILL")
            pcall(function()
                callMethod(SwapSkill, { "SetDebug", "setDebug" }, true)
            end)
            pcall(function()
                callMethod(SwapSkill, { "SyncFromState", "syncFromState" }, STATE)
            end)
            moduleStart(SwapSkill)
            return
        end

        task.wait(0.6)
    end

    moduleStop(SwapSkill, "boot")
end)

