-- RETRY MODULE YANG GAGAL (game belum siap saat boot)
----------------------------------------------------------------
local function applyEnvAlias(key, mod)
    if type(mod) ~= "table" then
        return
    end
    local env = (getgenv and getgenv()) or _G
    local map = {
        PetListView = { "PetListView" },
        CraftListView = { "CraftListView" },
        WorldShardCleaner = { "WorldShardCleaner" },
        Boost = { "AutoBoost", "BoostModule", "auto_hatchBoost" },
        Gift = { "GiftModule", "Gift" },
        AutoAccept = { "AutoAccept" },
        baku_combo = { "BakuCombo" },
        autokg_loop = { "AutoKGLoop", "autokg_loop" },
        mutation_machine_api = { "MutationMachineApi" },
        mutation_machine_loop = { "MutationMachineLoop" },
        mutation_machine_remap = { "MutationMachineRemap" },
        autobuy = { "AutoBuyModule" },
        antiafk = { "AntiAFK", "antiafk" },
        PSReconnect = { "PSReconnect" },
        Feed = { "AutoFeed", "FeedModule" },
        auto_buy_dev = { "AutoBuyDevModule" },
        AutoSellFruit = { "AutoSellFruit" },
        AutoFavoritePet = { "AutoFavoritePet" },
        AutoSellPet = { "AutoSellPet" },
        auto_craft_loop = { "AutoCraftLoop" },
        swap_skill_module = { "SwapSkill", "SwapSkillModule" },
        collect_rules = { "CollectRules" },
        Collectfruit = { "AutoCollectFruit", "CollectFruitModule", "Collectfruit" },
        UpdateNewServer = { "UpdateNewServer" },
        Webhook = { "Webhook" },
        AutoSprinkler = { "AutoSprinkler" },
        AutoCook = { "AutoCook" },
        AutoOpen = { "AutoOpen" },
        AutoBeanstalk = { "AutoBeanstalk" },
        AutoFallMarket = { "AutoFallMarket" },
        AutoHalloweenEvent = { "AutoHalloweenEvent" },
        AutoFairyEvent = { "AutoFairyEvent" },
        AutoWiseOwl = { "AutoWiseOwl" },
        AutoMoonCrafting = { "AutoMoonCrafting" },
        AutoPetEsp = { "AutoPetEsp", "PetEsp" },
        AutoReclaimer = { "AutoReclaimer" },
        AutoPlant = { "AutoPlant" },
        AutoShovel = { "AutoShovel" },
        AutoShovelFruit = { "AutoShovelFruit" },
        AutoTrowel = { "AutoTrowel" },
        AutoWatering = { "AutoWatering" },
        AutoShovelSprinkler = { "AutoShovelSprinkler" },
        GardenOptimizer = { "GardenOptimizer" },
        NilCooldownFixer = { "NilCooldownFixer" },
    }
    local names = map[key]
    if not names then
        return
    end
    for _, name in ipairs(names) do
        env[name] = mod
        _G[name] = mod
    end
    if key == "autokg_loop" and mod.running == nil then
        mod.running = false
    end
    if key == "mutation_machine_remap" and type(mod.Start) == "function" then
        pcall(function()
            mod.Start()
        end)
    end
    local syncKeys = {
        AutoCook = true,
        AutoOpen = true,
        AutoSellPet = true,
        AutoBeanstalk = true,
        AutoFallMarket = true,
        AutoHalloweenEvent = true,
        AutoFairyEvent = true,
        AutoWiseOwl = true,
        AutoMoonCrafting = true,
        AutoPetEsp = true,
        AutoReclaimer = true,
        AutoPlant = true,
        AutoShovel = true,
        AutoShovelFruit = true,
        AutoTrowel = true,
        AutoWatering = true,
        AutoShovelSprinkler = true,
        GardenOptimizer = true,
        AutoFavoritePet = true,
        AutoSellFruit = true,
        AutoSprinkler = true,
        autobuy = true,
    }
    if syncKeys[key] then
        if type(mod.SyncFromState) == "function" then
            pcall(mod.SyncFromState)
        elseif type(mod.SyncFromGlobals) == "function" then
            pcall(mod.SyncFromGlobals)
        end
    end
end

