if #FailedModules > 0 then
    task.spawn(function()
        for attempt = 1, MODULE_RETRY_MAX do
            local pending = {}
            for _, def in ipairs(FailedModules) do
                if type(Loaded[def.key]) ~= "table" then
                    pending[#pending + 1] = def
                end
            end
            if #pending == 0 then
                return
            end
            warnlog(("Retry %d/%d untuk %d module (game lebih siap)..."):format(
                attempt,
                MODULE_RETRY_MAX,
                #pending
            ))
            task.wait(MODULE_RETRY_DELAY)
            for _, def in ipairs(pending) do
                if type(Loaded[def.key]) == "table" then
                    continue
                end
                warnlog(("Module %s retrying %d/%d..."):format(tostring(def.name), attempt, MODULE_RETRY_MAX))
                local ok, modOrErr = loadOneModule(def)
                if ok and type(modOrErr) == "table" then
                    Loaded[def.key] = modOrErr
                    applyEnvAlias(def.key, modOrErr)
                    refreshLocalsFromLoaded()
                    warnlog(("Module %s retry OK"):format(tostring(def.name)))
                else
                    warnlog(("Module %s retry fail (%d/%d): %s"):format(
                        tostring(def.name),
                        attempt,
                        MODULE_RETRY_MAX,
                        tostring(modOrErr)
                    ))
                end
            end
        end
    end)
end

